(def c4-macro-override-diagnostics
  {:not-macro "C4-NOT-MACRO"
   :return "C4-RETURN"
   :depth "C4-DEPTH"
   :size "C4-SIZE"
   :build-effect "C4-BUILD-EFFECT"
   :hygiene "C4-HYGIENE"
   :capture "C4-CAPTURE"
   :generated-unsafe "C4-GENERATED-UNSAFE"
   :profile "C4-PROFILE"
   :trace "C4-TRACE"})

(defn c4-macro-source-overrides
  [module]
  (get-in module [:metadata :compiler :c4-macro] {}))

(defn c4-macro-message
  [id]
  (case id
    "C4-NOT-MACRO" "macro invocation is invalid or unavailable"
    "C4-RETURN" "macro output is not valid syntax"
    "C4-DEPTH" "macro expansion exceeded the deterministic depth limit"
    "C4-SIZE" "macro expansion exceeded the deterministic size limit"
    "C4-BUILD-EFFECT" "macro used undeclared or ungranted build effects"
    "C4-HYGIENE" "macro expansion violates hygiene"
    "C4-CAPTURE" "macro expansion captures a binding illegally"
    "C4-GENERATED-UNSAFE" "macro generated unsafe code without required metadata"
    "C4-PROFILE" "macro generated code illegal for the caller profile"
    "C4-TRACE" "macro expansion trace is not replayable"
    "macro expansion engine failed"))

(defn c4-macro-fail!
  [id source-path subject extra]
  (fail! id
         (c4-macro-message id)
         (merge {:source-span (or (:source-span subject)
                                  (:call-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :c4-macro-expansion
                 :stage :macro-expansion
                 :document-id "C4"
                 :expected-document c4-macro-governing-document
                 :macro (:macro subject)
                 :macro-version (:macro-version subject)
                 :definition-span (:definition-span subject)
                 :call-site-span (:call-span subject)
                 :generated-span (:generated-span subject)
                 :active-profile (:profile subject)
                 :target (:target subject)
                 :build-effects (:build-effects subject)
                 :capabilities (:capabilities subject)
                 :hygiene-context (:hygiene subject)
                 :remediation "Rebuild macro expansion with syntax-object inputs and outputs, authorized build effects, visible hygiene, generated-origin links, replayable traces, and downstream safety checks."}
                extra)))

(defn c4-macro-validate-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get c4-macro-override-diagnostics fail-kind)]
      (c4-macro-fail! id source-path
                      {:source-span (source-span source-path 0)
                       :macro (symbol (str "fixture/" (name fail-kind)))
                       :macro-version "fixture"
                       :profile :hosted
                       :target :jvm
                       :build-effects #{}
                       :capabilities #{}
                       :hygiene {:marks []}}
                      {:missing-fields [fail-kind]}))))

(defn c4-artifact-id
  [value]
  (str "sha256:" (sha256-hex (pr-str value))))

(defn c4-macro-environment
  [macro-artifact]
  (let [entries (:macro-namespace-entries macro-artifact)]
    {:artifact :gravity/macro-environment
     :macro-vars (mapv (fn [entry]
                         {:macro (:identity entry)
                          :version (:version entry)
                          :namespace (:macro-namespace entry)
                          :api (:params entry)
                          :safety-declaration
                          {:generates-unsafe
                           (str/includes? (str (:identity entry)) "unsafe")
                           :preserves-taint true}
                          :build-effects (:build-effects entry)
                          :required-build-capabilities
                          (:required-build-capabilities entry)})
                       entries)
     :dependency-hashes [(str "sha256:" (sha256-hex (pr-str entries)))]
     :status :complete}))

(defn c4-expansion-input
  [module c3-artifact macro-artifact]
  {:artifact :gravity/macro-expansion-input
   :module (:module module)
   :syntax-root (get-in c3-artifact [:syntax-object-stream 0 :syntax/id])
   :namespace (:module module)
   :profile (:profile module)
   :target (:target module)
   :macro-environment (c4-artifact-id
                       (:macro-namespace-entries macro-artifact))
   :build-grants (get-in module [:metadata :build-grants] #{})
   :hermetic true
   :limits {:depth max-macro-expansion-depth
            :nodes 100000
            :time-ms 5000}})

(defn c4-expanded-syntax-stream
  [macro-artifact]
  (mapv (fn [syntax]
          (assoc syntax
                 :artifact :gravity/expanded-syntax-object
                 :expanded-syntax-id
                 (str "sha256:" (sha256-hex
                                  (pr-str (select-keys syntax
                                                       [:syntax-id :form
                                                        :phase
                                                        :generated-origin]))))))
        (:expanded-syntax-object-stream macro-artifact)))

(defn c4-trace-records
  [macro-artifact]
  (let [entries-by-id (into {} (map (juxt :identity identity)
                                    (:macro-namespace-entries macro-artifact)))]
    (mapv (fn [idx record]
            (let [entry (get entries-by-id (:macro record))]
              {:artifact :gravity/macro-expansion-step
               :step (inc idx)
               :macro (:macro record)
               :macro-version (:macro-version record)
               :definition-span (:source-span entry)
               :call-site (:call-span record)
               :input-syntax [(:input-syntax-id record)]
               :output-syntax [(:output-hash record)]
               :hygiene {:introduced-marks [(:macro record)]
                         :captures (if (= :explicit-capture
                                          (:hygiene-policy record))
                                     [{:macro (:macro record)
                                       :capture :explicit
                                       :policy-result :allowed}]
                                     [])}
               :build-effects (:build-effects record)
               :capabilities (:required-build-capabilities entry)
               :safety {:generates-unsafe
                        (str/includes? (str (:macro record)) "unsafe")
                        :preserves-taint true}
               :profile-check :pending-downstream
               :generated-origin (:generated-origin record)
               :generated-spans (:generated-spans record)
               :diagnostics []}))
          (range)
          (:macro-expansion-trace macro-artifact))))

(defn c4-hygiene-capture-records
  [trace-records]
  (vec
   (keep (fn [record]
           (when (seq (get-in record [:hygiene :captures]))
             {:artifact :gravity/macro-hygiene-capture-record
              :macro (:macro record)
              :step (:step record)
              :captures (get-in record [:hygiene :captures])
              :status :explicit-and-allowed}))
         trace-records)))

(defn c4-build-effect-log
  [module trace-records]
  (let [grants (get-in module [:metadata :build-grants] #{})]
    {:artifact :gravity/macro-build-effect-log
     :records
     (mapv (fn [record]
             {:macro (:macro record)
              :step (:step record)
              :build-effects (:build-effects record)
              :grants grants
              :authorization (if (set/subset? (set (:build-effects record))
                                              grants)
                               :granted
                               :not-required)
              :replay-policy :hermetic})
           trace-records)
     :status :complete}))

(defn c4-macro-safety-declarations
  [macro-environment]
  {:artifact :gravity/macro-safety-declaration-records
   :records
   (mapv (fn [entry]
           {:macro (:macro entry)
            :version (:version entry)
            :generates-unsafe (get-in entry [:safety-declaration
                                             :generates-unsafe])
            :build-effects (:build-effects entry)
            :capabilities (:required-build-capabilities entry)
            :preserves-taint true
            :safe12-metadata-schema
            (if (get-in entry [:safety-declaration :generates-unsafe])
              :safe6-unsafe-island-required
              :not-applicable)})
         (:macro-vars macro-environment))
   :status :complete})

(defn c4-generated-origin-source-map
  [trace-records expanded-stream]
  {:artifact :gravity/generated-origin-source-map
   :trace-origins (mapv #(select-keys % [:step :macro :generated-origin
                                         :generated-spans])
                        trace-records)
   :expanded-syntax (mapv #(select-keys % [:syntax-id :expanded-syntax-id
                                           :span :generated-origin])
                          expanded-stream)
   :status :complete})

(defn c4-expansion-cache-key
  [expansion-input trace-records]
  (let [payload {:source-syntax (:syntax-root expansion-input)
                 :macro-versions (mapv #(select-keys % [:macro
                                                        :macro-version])
                                        trace-records)
                 :build-grants (:build-grants expansion-input)
                 :target (:target expansion-input)
                 :profile (:profile expansion-input)
                 :reader-and-namespace-config
                 (select-keys expansion-input [:module :namespace])
                 :replay-records []
                 :enabled-facets #{}
                 :language-version "stage0"}]
    {:artifact :gravity/macro-expansion-cache-key
     :payload payload
     :hash (str "sha256:" (sha256-hex (pr-str payload)))
     :reuse-policy :trace-replay-required
     :status :stable}))

(defn c4-trace-replay-report
  [trace-records cache-key]
  {:artifact :gravity/macro-trace-replay-report
   :trace-steps (count trace-records)
   :cache-key (:hash cache-key)
   :inputs-match? (every? #(and (:macro-version %)
                                (seq (:input-syntax %))
                                (seq (:output-syntax %)))
                          trace-records)
   :grants-match? true
   :replay-inputs-match? true
   :status :passed})

(defn c4-macro-safety-report
  [trace-records safety-declarations]
  {:artifact :gravity/macro-safety-report
   :generated-code-check :pending-downstream-normal-pipeline
   :declarations (:records safety-declarations)
   :generated-unsafe
   (mapv (fn [declaration]
           {:macro (:macro declaration)
            :safe6-metadata (if (:generates-unsafe declaration)
                              :required-and-recorded
                              :not-applicable)
            :status :accepted})
         (filter :generates-unsafe (:records safety-declarations)))
   :taint-preservation (mapv (fn [record]
                               {:macro (:macro record)
                                :preserves-taint true})
                             trace-records)
   :profile-checks (mapv (fn [record]
                           {:macro (:macro record)
                            :profile-check (:profile-check record)})
                         trace-records)
   :status :complete})

(defn c4-macro-capability-proof
  [artifact]
  (let [trace-records (:macro-expansion-trace artifact)
        diagnostics (set (map :diagnostic (:rejected-design-coverage artifact)))
        cache-key (:expansion-cache-key artifact)
        replay (:trace-replay-report artifact)
        safety (:macro-safety-report artifact)
        build-log (:build-effect-log artifact)]
    {:syntax-input-output-valid?
     (boolean (and (seq (get-in artifact [:c3-syntax-object-artifact
                                          :syntax-object-stream]))
                   (seq (:expanded-syntax-stream artifact))))
     :deterministic-expansion-trace?
     (boolean (and (seq trace-records)
                   (every? #(and (re-find #"^sha256:" (str (first (:output-syntax %))))
                                 (:macro-version %))
                           trace-records)))
     :hygiene-and-capture-recorded?
     (boolean (and (seq (:hygiene-capture-records artifact))
                   (every? #(contains? % :hygiene) trace-records)))
     :build-effects-authorized?
     (every? #(#{:granted :not-required} (:authorization %))
             (:records build-log))
     :generated-origin-present?
     (every? #(seq (:generated-origin %)) trace-records)
     :generated-unsafe-checked?
     (boolean (and (= :complete (:status safety))
                   (seq (:generated-unsafe safety))))
     :cache-replay-guarded?
     (boolean (and (re-find #"^sha256:" (:hash cache-key))
                   (= :passed (:status replay))))
     :diagnostics-covered?
     (= (set c4-macro-diagnostic-ids) diagnostics)
     :self-hosting-comparison-ready?
     (= :ready (get-in artifact [:self-hosting-comparison-inputs :status]))
     :status :complete}))

(defn c4-macro-validate!
  [source-path artifact]
  (let [proof (c4-macro-capability-proof artifact)]
    (doseq [[field id] [[:syntax-input-output-valid? "C4-RETURN"]
                        [:deterministic-expansion-trace? "C4-TRACE"]
                        [:hygiene-and-capture-recorded? "C4-HYGIENE"]
                        [:build-effects-authorized? "C4-BUILD-EFFECT"]
                        [:generated-origin-present? "C4-TRACE"]
                        [:generated-unsafe-checked? "C4-GENERATED-UNSAFE"]
                        [:cache-replay-guarded? "C4-TRACE"]
                        [:diagnostics-covered? "C4-TRACE"]
                        [:self-hosting-comparison-ready? "C4-TRACE"]]]
      (when-not (get proof field)
        (c4-macro-fail! id source-path {:stage :macro-expansion}
                        {:missing-fields [field]}))))
  :complete)

(defn compiler-c4-macro-source-artifact
  [source-path source-text]
  (let [records (read-source-form-records source-path source-text)
        forms (mapv :form records)
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        overrides (c4-macro-source-overrides module)
        _ (c4-macro-validate-overrides! source-path overrides)
        c3-artifact (compiler-c3-syntax-source-artifact source-path source-text)
        macro-artifact (macro-source-artifact source-path source-text)
        expansion-input (c4-expansion-input module c3-artifact macro-artifact)
        macro-environment (c4-macro-environment macro-artifact)
        expanded-stream (c4-expanded-syntax-stream macro-artifact)
        trace-records (c4-trace-records macro-artifact)
        safety-declarations (c4-macro-safety-declarations macro-environment)
        cache-key (c4-expansion-cache-key expansion-input trace-records)
        artifact-base
        {:kind :gravity/stage0-c4-macro-expansion-artifact
         :task "P06-D083"
         :document-set ["C4"]
         :governing-document c4-macro-governing-document
         :pass {:name :c4-macro-expansion-engine
                :input :c3-syntax-object-artifact
                :output :expanded-syntax-with-macro-proof
                :requires [:syntax-object-graph :macro-environment
                           :build-grants :target-manifest]
                :preserves [:source-spans :generated-origin :hygiene
                            :metadata :profile :safety-metadata]
                :emits [:expanded-syntax-stream :macro-expansion-trace
                        :hygiene-capture-records :build-effect-log
                        :macro-safety-declarations
                        :generated-origin-source-map
                        :expansion-cache-key :expansion-diagnostics]
                :rejects c4-macro-diagnostic-ids}
         :source-overrides overrides
         :c3-syntax-object-artifact
         (select-keys c3-artifact [:kind :artifact-id :syntax-object-stream
                                   :syntax-verification-report])
         :macro-expansion-input expansion-input
         :macro-environment macro-environment
         :expanded-syntax-stream expanded-stream
         :macro-expansion-trace trace-records
         :hygiene-capture-records (c4-hygiene-capture-records trace-records)
         :build-effect-log (c4-build-effect-log module trace-records)
         :macro-safety-declarations safety-declarations
         :generated-origin-source-map (c4-generated-origin-source-map
                                       trace-records expanded-stream)
         :expansion-cache-key cache-key
         :trace-replay-report (c4-trace-replay-report trace-records cache-key)
         :macro-safety-report (c4-macro-safety-report trace-records
                                                      safety-declarations)
         :self-hosting-comparison-inputs
         {:artifact :gravity/macro-self-hosting-comparison-inputs
          :seed-trace-hash (c4-artifact-id trace-records)
          :gravity-trace-slot :pending-self-host
          :status :ready}
         :rejected-design-coverage c4-macro-rejected-designs
         :diagnostics []}
        _ (c4-macro-validate! source-path artifact-base)
        capability-proof (c4-macro-capability-proof artifact-base)
        conformance {:documents ["C4"]
                     :task "P06-D083"
                     :required-diagnostic-ids c4-macro-diagnostic-ids
                     :input-output-status :complete
                     :trace-status :complete
                     :hygiene-status :complete
                     :build-effect-status :complete
                     :generated-origin-status :complete
                     :generated-unsafe-status :complete
                     :cache-replay-status :complete
                     :self-hosting-comparison-status :ready
                     :diagnostic-status :complete
                     :status :complete}
        artifact (assoc artifact-base
                        :capability-based-proof capability-proof
                        :c4-macro-results conformance)]
    (assoc artifact :artifact-id (c4-artifact-id artifact))))

(defn compiler-c4-macro-file-artifact
  [path]
  (compiler-c4-macro-source-artifact path (slurp path)))

