(defn record-checker!
  [checker key value]
  (swap! checker update key conj value)
  value)

(defn typed-context
  [module]
  (atom {:profile (:profile module)
         :target (:target module)
         :safety (:safety module)
         :declared-effects (:effects module)
         :declared-capabilities (:capabilities module)
         :build-grants (or (get-in module [:metadata :build-grants]) #{})
         :replay-records (or (get-in module [:metadata :replay-records]) #{})
         :replay-policy (or (get-in module [:metadata :replay-policy]) #{})
         :declared-inputs (or (get-in module [:metadata :declared-inputs]) #{})
         :target-manifests (or (get-in module [:metadata :target-manifests]) #{})
         :hermetic? (true? (get-in module [:metadata :hermetic]))
         :cache-policy (or (get-in module [:metadata :cache-policy]) :default)
         :language-facets (or (get-in module [:metadata :language-facets]) #{})
         :provider-policy (or (get-in module [:metadata :provider-policy]) {})
         :provider-grants (or (get-in module [:metadata :provider-grants]) #{})
         :handler-grants (or (get-in module [:metadata :handler-grants]) #{})
         :handler-covered-effects #{}
         :handler-covered-capabilities #{}
         :variable-types {}
         :linear-resources {}
         :moved-values {}
         :task-scope-id nil
         :in-task-scope? false}))

(defn child-context
  [ctx]
  (atom (update @ctx :linear-resources
                (fn [resources]
                  (into {} (map (fn [[k v]] [k (assoc v :consumed? (:consumed? v false))])
                                resources))))))

(defn literal-type
  [value]
  (cond
    (nil? value) "Nil"
    (true? value) "Boolean"
    (false? value) "Boolean"
    (integer? value) "Integer"
    (ratio? value) "ExactRatio"
    (float? value) "F64"
    (string? value) "String"
    (char? value) "Character"
    (symbol? value) "Symbol"
    (keyword? value) "Keyword"
    (seq? value) "List"
    (vector? value) "Vector"
    (map? value) "Map"
    (set? value) "Set"
    :else "Dynamic"))

(defn collect-fact-effects
  [facts]
  (set (mapcat :effects facts)))

(defn collect-fact-capabilities
  [facts]
  (set (mapcat :capabilities facts)))

(defn common-type
  [facts]
  (let [types (stable-vec (keep :type facts))]
    (cond
      (empty? types) "Nil"
      (= 1 (count types)) (first types)
      :else (str "Union[" (str/join "," types) "]"))))

(defn linear-type?
  [type-name]
  (and (string? type-name) (str/starts-with? type-name "Linear[")))

(defn linear-resource-type
  [type-name]
  (subs type-name (count "Linear[") (dec (count type-name))))

(defn typed-fact
  [checker node type-name effects capabilities extra]
  (let [fact (merge {:node-id (:node-id node)
                     :source-kind (:kind node)
                     :source-span (:source-span node)
                     :type type-name
                     :effects (stable-set effects)
                     :capabilities (stable-set capabilities)
                     :memory []
                     :concurrency []
                     :profile-context (:profile node)
                     :namespace-context (:namespace node)}
                    extra)]
    (record-checker! checker :type-facts
                     {:node-id (:node-id fact)
                      :type (:type fact)
                      :source-kind (:source-kind fact)
                      :source-span (:source-span fact)})
    (when-let [category (type-category (:type fact))]
      (when-not (= :unknown category)
        (record-checker! checker :type-category-coverage
                         {:node-id (:node-id fact)
                          :type (:type fact)
                          :category category})))
    (when (or (seq (:effects fact)) (seq (:capabilities fact)))
      (record-checker! checker :effect-facts
                       {:node-id (:node-id fact)
                        :effects (:effects fact)
                        :capabilities (:capabilities fact)
                        :source-kind (:source-kind fact)}))
    fact))

(declare check-typed-node)

(defn effect-registry-entry
  [effect]
  (get effect-registry effect))

(defn build-effect?
  [effect]
  (= :build (:kind (effect-registry-entry effect))))

(defn replay-sensitive-effect?
  [effect]
  (true? (:replay-record (effect-registry-entry effect))))

(defn active-profile-needs-replay?
  [ctx]
  (contains? #{:distributed :ai} (:profile @ctx)))

(defn handled-effect?
  [ctx effect]
  (contains? (:handler-covered-effects @ctx) effect))

(defn handled-capability?
  [ctx capability]
  (contains? (:handler-covered-capabilities @ctx) capability))

(defn check-effect-registry!
  [node effect]
  (when-not (effect-registry-entry effect)
    (typed-diagnostic! "L6-EFFECT-UNKNOWN"
                       "effect kind is unknown or lacks governance registration"
                       node
                       "Register the effect with profile legality, capability requirements, ordering, and artifact representation."
                       {:effect effect})))

(defn check-build-effects!
  [checker ctx node effects opts]
  (doseq [effect effects
          :when (build-effect? effect)]
    (when-not (contains? (:build-grants @ctx) effect)
      (typed-diagnostic! (or (:build-grant-diagnostic opts)
                             "L6-BUILD-EFFECT")
                         "build-time effect is not granted by build policy"
                         node
                         "Grant the build effect in metadata or move the operation behind an approved build provider."
                         {:effect effect
                          :granted-build-effects (:build-grants @ctx)}))
    (record-checker! checker :build-effect-log
                     {:node-id (:node-id node)
                      :effect effect
                      :phase :build
                      :grant :metadata-build-grant
                      :status :granted})))

(defn check-replay-effects!
  [checker ctx node effects]
  (doseq [effect effects
          :when (and (replay-sensitive-effect? effect)
                     (active-profile-needs-replay? ctx))]
    (when-not (contains? (:replay-records @ctx) effect)
      (typed-diagnostic! "L6-REPLAY-EFFECT"
                         "replay-sensitive effect lacks a replay record"
                         node
                         "Record replay evidence for this nondeterministic effect or use a replay-aware handler."
                         {:effect effect
                          :profile (:profile @ctx)}))
    (record-checker! checker :replay-effect-log
                     {:node-id (:node-id node)
                      :effect effect
                      :profile (:profile @ctx)
                      :replay-record :metadata-replay-record
                      :mode :recorded})))

(defn check-effects-and-capabilities!
  ([checker ctx node effects capabilities]
   (check-effects-and-capabilities! checker ctx node effects capabilities {}))
  ([checker ctx node effects capabilities opts]
  (doseq [effect effects]
    (check-effect-registry! node effect)
    (when (contains? (get profile-denied-effects (:profile @ctx) #{}) effect)
      (typed-diagnostic! "L6-EFFECT-PROFILE"
                         "active profile rejects an inferred effect"
                         node
                         "Move the operation behind a profile-supported provider or remove the effect."
                         {:effect effect
                          :active-profile (:profile @ctx)}))
    (when (and (not (handled-effect? ctx effect))
               (not (contains? typed-internal-effects effect))
               (not (contains? (:declared-effects @ctx) effect)))
      (typed-diagnostic! "L6-EFFECT-UNDECLARED"
                         "inferred effect exceeds namespace declaration"
                         node
                         "Declare the effect in the namespace, function, package, and runtime policy or remove the operation."
                          {:effect effect
                           :declared-effects (:declared-effects @ctx)})))
  (check-build-effects! checker ctx node effects opts)
  (check-replay-effects! checker ctx node effects)
	  (doseq [capability capabilities]
	    (when (and (not (handled-capability? ctx capability))
	               (not (contains? (:declared-capabilities @ctx) capability)))
	      (typed-diagnostic! (or (:capability-diagnostic opts)
	                             "L15-CAPABILITY-MISSING")
                         "effect requires a capability that is not granted"
                         node
                         "Declare an explicit capability grant or use a handler with a structured fixture/replay capability."
                         {:requested-capability capability
                          :selected-or-missing-provider (provider-name capability)
                          :grant-id nil
                          :scope nil
                          :phase :runtime
	                          :active-profile (:profile @ctx)
	                          :target (:target @ctx)}))
	    (when (and (not (handled-capability? ctx capability))
	               (contains? (:declared-capabilities @ctx) capability)
	               (nil? (provider-name capability)))
	      (typed-diagnostic! "L15-PROVIDER-MISSING"
	                         "no provider implements the requested capability"
	                         node
	                         "Install or declare a provider that implements this capability for the active profile and target."
	                         {:requested-capability capability
	                          :selected-or-missing-provider nil
	                          :grant-id nil
	                          :scope nil
	                          :phase :runtime
	                          :active-profile (:profile @ctx)
	                          :target (:target @ctx)}))
	    (when-let [provider (provider-name capability)]
	      (when-not (contains? (get-in provider-specs [capability :profiles] #{})
	                           (:profile @ctx))
	        (when (true? (get-in @ctx [:provider-policy :strict-profile?]))
	          (typed-diagnostic! "L15-PROFILE"
	                             "selected provider is unsupported by the active profile or target"
	                             node
	                             "Select a provider whose declaration covers the active profile and target or reject the operation."
	                             {:requested-capability capability
	                              :selected-or-missing-provider provider
	                              :provider-profiles (get-in provider-specs [capability :profiles])
	                              :grant-id nil
	                              :scope nil
	                              :phase :runtime
	                              :active-profile (:profile @ctx)
	                              :target (:target @ctx)}))))
	    (when-not (handled-capability? ctx capability)
	      (record-checker! checker :provider-selection-records
	                       {:capability capability
	                        :provider (provider-name capability)
	                        :version (provider-version capability)
	                        :phase :runtime
	                        :selection :profile-default
	                        :selection-deterministic? true
	                        :scope :namespace
	                        :scope-kind (provider-scope-kind capability)
	                        :trust-level (provider-trust-level capability)
	                        :artifact-schema (provider-artifact-schema capability)
	                        :contracts (provider-contracts capability)
	                        :conformance-suite (provider-conformance-suite capability)
	                        :active-profile (:profile @ctx)
	                        :target (:target @ctx)})
	      (record-checker! checker :capability-records
	                       {:node-id (:node-id node)
	                        :capability capability
	                        :provider (provider-name capability)
	                        :provider-version (provider-version capability)
	                        :scope-kind (provider-scope-kind capability)
	                        :trust-level (provider-trust-level capability)
	                        :phase :runtime
	                        :status :granted})))))

(defn parse-typed-params
  [params]
  (loop [items (seq params)
         parsed []]
    (cond
      (nil? items) parsed

      (= '& (first items))
      (let [rest-name (second items)]
        (when-not (symbol? rest-name)
          (fail! "L5-ANNOTATION-REQUIRED"
                 "rest parameter requires a symbolic name"
                 {:params params
                  :remediation "Use a symbol after & in parameter vectors."}))
        (recur (nnext items)
               (conj parsed {:name rest-name :type "Dynamic" :rest? true})))

      (symbol? (first items))
      (let [name (first items)
            maybe-marker (second items)
            maybe-type (nth items 2 nil)]
        (if (= ':- maybe-marker)
          (recur (nnext (next items))
                 (conj parsed {:name name :type (type-form-name maybe-type) :declared? true}))
          (recur (next items)
                 (conj parsed {:name name :type "Dynamic"}))))

      :else
      (fail! "L5-ANNOTATION-REQUIRED"
             "function parameter requires a symbol and optional :- type annotation"
             {:params params
              :remediation "Use parameters such as [value] or [value :- String]."}))))

(defn consume-linear-resource!
  [checker ctx node args]
  (when (or (empty? args) (not= :symbol (:source-kind (first args))))
    (typed-diagnostic! "L10-LINEAR-RESOURCE"
                       "resource close requires a linear resource symbol"
                       node
                       "Close the named linear resource exactly once."))
  (let [name (:name (first args))
        state (get-in @ctx [:linear-resources name])]
    (when (or (nil? state) (:consumed? state))
      (typed-diagnostic! "L10-LINEAR-RESOURCE"
                         "linear resource is unavailable or already consumed"
                         node
                         "Close each linear resource exactly once."
                         {:resource name}))
    (swap! ctx assoc-in [:linear-resources name] (assoc state :consumed? true))
    (record-checker! checker :linear-resource-table
                     {:name name
                      :resource-type (:resource-type state)
                      :opened-at (:node-id state)
                      :closed-at (:node-id node)
                      :status :consumed})))

(defn check-typed-assert!
  [node args]
  (when-not (and (= 2 (count args))
                 (= "Keyword" (:type (first args))))
    (typed-diagnostic! "L5-ANNOTATION-REQUIRED"
                       "typed/assert requires a type keyword and value"
                       node
                       "Use (typed/assert :Type value)."))
  (let [expected (get type-keywords (:value (first args)))
        actual (:type (second args))]
    (when-not expected
      (typed-diagnostic! "L5-ANNOTATION-REQUIRED"
                         "typed/assert uses an unknown type keyword"
                         node
                         "Use a registered type keyword."))
    (when (not= expected actual)
      (typed-diagnostic! "L5-TYPE-MISMATCH"
                         "expression type does not match declared assertion"
                         node
                         "Change the expression type or the declared assertion."
                         {:expected-type expected
                          :actual-type actual}))))

(defn type-token-name
  [fact]
  (cond
    (= "Keyword" (:type fact)) (get type-keywords (:value fact))
    (= "QuotedData" (:type fact)) (type-form-name (:value fact))
    (string? (:value fact)) (:value fact)
    :else nil))

(def primitive-compatible-types
  #{"Nil" "Unit" "Boolean" "I8" "I16" "I32" "I64" "U8" "U16" "U32" "U64"
    "Int" "Integer" "BigInt" "F32" "F64" "Exact" "ExactRatio" "Symbol"
    "Keyword" "String" "Text" "List" "Vector" "Map" "Set" "Tuple" "Dynamic"})

(defn compatible-value-type?
  [expected actual]
  (or (not (contains? primitive-compatible-types expected))
      (= expected actual)
      (and (#{"I8" "I16" "I32" "I64" "U8" "U16" "U32" "U64" "Int" "BigInt"} expected)
           (= "Integer" actual))
      (and (= "F32" expected) (= "F64" actual))
      (and (= "Exact" expected) (#{"Integer" "ExactRatio"} actual))
      (and (= "Text" expected) (= "String" actual))
      (and (= "Tuple" expected) (= "Vector" actual))
      (and (= "Unit" expected) (= "Nil" actual))))

(defn check-typed-value!
  [node args]
  (when-not (and (= 2 (count args)) (= "Keyword" (:type (first args))))
    (typed-diagnostic! "L5-ANNOTATION-REQUIRED"
                       "typed/value requires a type keyword and value"
                       node
                       "Use (typed/value :Type value)."))
  (let [expected (type-token-name (first args))
        value-fact (second args)
        actual (if (= "QuotedData" (:type value-fact))
                 (literal-type (:value value-fact))
                 (:type value-fact))]
    (when-not expected
      (typed-diagnostic! "L5-ANNOTATION-REQUIRED"
                         "typed/value uses an unknown type keyword"
                         node
                         "Use a registered L5 type keyword."))
    (when-not (compatible-value-type? expected actual)
      (typed-diagnostic! "L5-TYPE-MISMATCH"
                         "typed/value expression does not satisfy the declared type"
                         node
                         "Change the fixture value or the declared type."
                         {:expected-type expected
                          :actual-type actual}))
    expected))

(defn check-typed-return!
  [node args]
  (when-not (= 2 (count args))
    (typed-diagnostic! "L5-ANNOTATION-REQUIRED"
                       "typed/return requires a return type and value"
                       node
                       "Use (typed/return (quote Type) value)."))
  (let [expected (type-token-name (first args))
        actual (:type (second args))]
    (when-not expected
      (typed-diagnostic! "L5-ANNOTATION-REQUIRED"
                         "typed/return uses an unknown return type"
                         node
                         "Use a registered return type."))
    (when-not (compatible-value-type? expected actual)
      (typed-diagnostic! "L5-TYPE-MISMATCH"
                         "function return expression does not match its declared type"
                         node
                         "Change the function body or declared return type."
                         {:expected-type expected
                          :actual-type actual}))
    expected))

(defn asserted-return-type
  [operator args spec]
  (cond
    (and (= 'typed/assert operator) (= 2 (count args)))
    (get type-keywords (:value (first args)) (:return-type spec))

    (and (= 'typed/value operator) (= 2 (count args)))
    (or (type-token-name (first args)) (:return-type spec))

    (and (= 'typed/return operator) (= 2 (count args)))
    (or (type-token-name (first args)) (:return-type spec))

    (and (= 'dynamic/cast operator) (= 2 (count args)))
    (or (type-token-name (first args)) (:return-type spec))

    (and (= 'record/new operator) (keyword? (:value (first args))))
    (str "Record[" (name (:value (first args))) "]")

    (and (= 'union/ok operator) (keyword? (:value (first args))))
    (str "Union[" (name (:value (first args))) ".Ok]")

    (and (= 'protocol/value operator) (keyword? (:value (first args))))
    (str "Protocol[" (name (:value (first args))) "]")

    (and (= 'generic/id operator) (seq args))
    (:type (first args))

    (and (= 'schema/derive operator) (keyword? (:value (first args))))
    (str "Schema[" (name (:value (first args))) "]")

    (and (= 'schema/validate operator) (keyword? (:value (first args))))
    (str "Validated[" (name (:value (first args))) "]")

    :else
    (:return-type spec)))

