                    :message "fixture manifest is malformed"}
   'safe16/outcome {:id "SAFE16-OUTCOME"
                    :rule :SAFE16
                    :operation :expected-outcome
                    :missing-fact :matching-outcome
                    :fixture-id :safe1/outcome
                    :document-id :SAFE1
                    :expected-outcome :reject
                    :actual-outcome :accept
                    :missing-artifact nil
                    :message "expected and actual outcome mismatch"}
   'safe16/diagnostic {:id "SAFE16-DIAGNOSTIC"
                       :rule :SAFE16
                       :operation :diagnostic-match
                       :missing-fact :diagnostic-id-or-span
                       :fixture-id :safe10/scope
                       :document-id :SAFE10
                       :expected-outcome :reject
                       :actual-outcome :reject
                       :missing-artifact :diagnostic-id
                       :message "diagnostic id or source span does not match"}
   'safe16/artifact {:id "SAFE16-ARTIFACT"
                     :rule :SAFE16
                     :operation :artifact-inspection
                     :missing-fact :required-artifact
                     :fixture-id :safe15/certificate
                     :document-id :SAFE15
                     :expected-outcome :accept
                     :actual-outcome :accept
                     :missing-artifact :certificate-record
                     :message "required artifact inspection is missing or invalid"}
   'safe16/profile {:id "SAFE16-PROFILE"
                    :rule :SAFE16
                    :operation :profile-matrix
                    :missing-fact :profile-specific-outcome
                    :fixture-id :safe8/actor-profile
                    :document-id :SAFE8
                    :expected-outcome :reject
                    :actual-outcome :accept
                    :missing-artifact :profile-matrix-row
                    :message "profile matrix result does not match expected behavior"}
   'safe16/certificate {:id "SAFE16-CERTIFICATE"
                        :rule :SAFE16
                        :operation :certificate-inspection
                        :missing-fact :proof-or-certificate-inspection
                        :fixture-id :safe15/check-erasure
                        :document-id :SAFE15
                        :expected-outcome :certificate-backed-proof
                        :actual-outcome :accept
                        :missing-artifact :proof-record
                        :message "proof or certificate inspection is missing"}
   'safe16/backend {:id "SAFE16-BACKEND"
                    :rule :SAFE16
                    :operation :backend-preservation
                    :missing-fact :backend-preservation-report
                    :fixture-id :safe9/backend
                    :document-id :SAFE9
                    :expected-outcome :retain-check
                    :actual-outcome :erased-check
                    :missing-artifact :backend-preservation-report
                    :message "backend preservation result does not match"}
   'safe16/report {:id "SAFE16-REPORT"
                   :rule :SAFE16
                   :operation :conformance-report
                   :missing-fact :machine-readable-report
                   :fixture-id :phase02/conformance
                   :document-id :SAFE16
                   :expected-outcome :report-valid
                   :actual-outcome :report-invalid
                   :missing-artifact :conformance-report
                   :message "conformance report output is invalid"}})

(def profile-direct-diagnostics
  {'p2/effect {:id "P2-EFFECT"
               :rule :P2
               :operation :core/runtime-effect
               :effect :io/write
               :message "core profile rejects runtime effects"}
   'p2/capability {:id "P2-CAPABILITY"
                   :rule :P2
                   :operation :core/capability
                   :requested-capability :io/stdout
                   :message "core profile rejects requested authority"}
   'p2/runtime {:id "P2-RUNTIME"
                :rule :P2
                :operation :core/runtime
                :missing-fact :no-runtime-provider
                :message "core profile rejects hidden runtime assumptions"}
   'p2/memory {:id "P2-MEMORY"
               :rule :P2
               :operation :core/memory
               :memory-regime :managed-runtime
               :message "core profile rejects concrete memory regime dependency"}
   'p2/unsafe {:id "P2-UNSAFE"
               :rule :P2
               :operation :core/unsafe
               :safety-outcome :unsafe-island
               :message "core profile forbids unsafe behavior"}
   'p2/nondeterminism {:id "P2-NONDETERMINISM"
                       :rule :P2
                       :operation :core/nondeterminism
                       :effect :time/read
                       :message "core profile rejects nondeterminism"}
   'p2/macro {:id "P2-MACRO"
              :rule :P2
              :operation :core/macro-output
              :message "macro expansion leaves the core subset"}
