(defn registered-effect-capability
  [effect]
  (:capability (effect-registry-entry effect)))

(defn check-effect-handle-node
  [checker ctx node]
  (let [arg-nodes (:arguments node)]
    (when-not (>= (count arg-nodes) 3)
      (typed-diagnostic! "L6-HANDLER-TYPE"
                         "effect/handle requires an effect label, handler identity, and body"
                         node
                         "Use (effect/handle :effect :handler body)."))
    (let [label-fact (check-typed-node checker ctx (first arg-nodes))
          handler-fact (check-typed-node checker ctx (second arg-nodes))
          effect-label (:value label-fact)
          handler-id (:value handler-fact)
          handler-capability :test/fixture]
      (when-not (keyword? effect-label)
        (typed-diagnostic! "L6-HANDLER-TYPE"
                           "handler effect label must be a keyword"
                           node
                           "Use a registered effect keyword as the first effect/handle argument."))
      (check-effect-registry! node effect-label)
      (when-not (keyword? handler-id)
        (typed-diagnostic! "L6-HANDLER-TYPE"
                           "handler identity must be a keyword"
                           node
                           "Use a stable handler identity keyword."))
      (when (contains? #{:kernel :firmware :hardware} (:profile @ctx))
        (typed-diagnostic! "L6-HANDLER-PROFILE"
                           "active profile rejects this handler form"
                           node
                           "Use a profile-supported handler or lower to explicit effect operations."
                           {:effect effect-label
                            :profile (:profile @ctx)
                            :handler handler-id}))
      (when-not (contains? (:handler-grants @ctx) handler-capability)
        (typed-diagnostic! "L6-HANDLER-CAPABILITY"
                           "handler lacks fixture or interpretation capability"
                           node
                           "Grant the handler capability in metadata or remove the handler."
                           {:effect effect-label
                            :handler handler-id
                            :requested-capability handler-capability}))
      (let [covered-capability (registered-effect-capability effect-label)
            child (child-context ctx)]
        (swap! child assoc
               :handler-covered-effects #{effect-label}
               :handler-covered-capabilities (cond-> #{}
                                                covered-capability (conj covered-capability)))
        (let [body-facts (mapv #(check-typed-node checker child %) (drop 2 arg-nodes))
              body-effects (collect-fact-effects body-facts)
              body-capabilities (collect-fact-capabilities body-facts)]
          (when-not (contains? body-effects effect-label)
            (typed-diagnostic! "L6-HANDLER-COVERAGE"
                               "handler claims an effect label that no handled occurrence produces"
                               node
                               "Handle a body that actually performs the label, or remove the handler claim."
                               {:effect effect-label
                                :handler handler-id}))
          (check-effects-and-capabilities! checker ctx node #{} #{handler-capability})
          (let [escaping-effects (disj body-effects effect-label)
                escaping-capabilities (cond-> body-capabilities
                                        covered-capability (disj covered-capability))
                handled-record {:node-id (:node-id node)
                                :effect-label effect-label
                                :request-type "EffectRequest"
                                :response-type "EffectResponse"
                                :resume-mode :abort
                                :replay-mode :fixture
                                :handler-identity handler-id
                                :handler-residual-effects #{}
                                :required-handler-capabilities #{handler-capability}
                                :original-label-preserved true
                                :handled-node-ids (mapv :node-id
                                                        (filter #(contains? (:effects %) effect-label)
                                                                body-facts))}]
            (record-checker! checker :handled-effect-table handled-record)
            (record-checker! checker :handler-capability-and-profile-report
                             {:node-id (:node-id node)
                              :handler handler-id
                              :effect-label effect-label
                              :active-profile (:profile @ctx)
                              :required-capabilities #{handler-capability}
                              :status :accepted})
            (record-checker! checker :continuation-and-replay-safety-report
                             {:node-id (:node-id node)
                              :handler handler-id
                              :resume-mode :abort
                              :continuation-safety :proven-affine
                              :replay-safety :fixture-recorded})
            (typed-fact checker node (if (seq body-facts) (:type (last body-facts)) "Nil")
                        escaping-effects
                        (conj escaping-capabilities handler-capability)
                        {:children (vec (concat [label-fact handler-fact] body-facts))
                         :callee 'effect/handle
                         :handled-effects [handled-record]})))))))

(def dispatch-operator-modes
  {'dispatch/direct :direct
   'dispatch/dictionary :dictionary
   'dispatch/vtable :vtable
   'dispatch/dynamic :hosted-dynamic
   'dispatch/multimethod :multimethod
   'dispatch/host-normalized :host-interface
   'dispatch/tool :artifact-boundary})

(defn dispatch-arg-value
  [args index]
  (:value (nth args index nil)))

(defn record-dispatch-call!
  [checker node operator args effects capabilities]
  (when-let [mode (get dispatch-operator-modes operator)]
    (let [record {:node-id (:node-id node)
                  :call operator
                  :protocol (dispatch-arg-value args 0)
                  :receiver (dispatch-arg-value args 1)
                  :method (dispatch-arg-value args 2)
                  :dispatch-mode mode
                  :effects effects
                  :capabilities capabilities
                  :profile (:profile node)
                  :implementation (str (name (or (dispatch-arg-value args 1) :unknown))
                                       "/"
                                       (name (or (dispatch-arg-value args 2) :unknown)))
                  :fallback-artifact (when (contains? #{:hosted-dynamic :multimethod
                                                        :artifact-boundary}
                                                      mode)
                                       :recorded)}]
      (record-checker! checker :dispatch-mode-records record)
      (when (= :host-interface mode)
        (record-checker! checker :host-interop-dispatch-records
                         (assoc record
                                :nullability :normalized
                                :exceptions :mapped
                                :host-type-identity (:receiver record)))))))

(defn record-error-call!
  [checker node operator args effects capabilities]
  (case operator
    option/some
    (record-checker! checker :error-type-declarations
                     {:node-id (:node-id node)
                      :family :option
                      :constructor :Some
                      :type "Option[T]"})
    option/none
    (record-checker! checker :error-type-declarations
                     {:node-id (:node-id node)
                      :family :option
                      :constructor :None
                      :type "Option[T]"})
    result/ok
    (record-checker! checker :error-type-declarations
                     {:node-id (:node-id node)
                      :family :result
                      :constructor :Ok
                      :type "Result[T,E]"})
    result/err
    (record-checker! checker :error-type-declarations
                     {:node-id (:node-id node)
                      :family :result
                      :constructor :Err
                      :type "Result[T,E]"})
    panic
    (record-checker! checker :panic-lowering-records
                     {:node-id (:node-id node)
                      :profile (:profile node)
                      :lowering :hosted-panic-record
                      :effects effects
                      :provenance :source-span-preserved})
    safety/check
    (record-checker! checker :safety-check-failure-records
                     {:node-id (:node-id node)
                      :check (dispatch-arg-value args 0)
                      :failure-behavior :typed-record
                      :effects effects})
    host/error-normalized
    (record-checker! checker :host-error-normalization-records
                     {:node-id (:node-id node)
                      :host-error (dispatch-arg-value args 0)
                      :nullability :normalized
                      :exceptions :mapped
                      :type-contract :gravity-error})
    ffi/error-mapped
    (record-checker! checker :ffi-error-mapping-artifacts
                     {:node-id (:node-id node)
                      :convention (dispatch-arg-value args 0)
                      :errno :mapped
                      :nullability :mapped
                      :ownership-on-failure :preserved
                      :cleanup :recorded
                      :capabilities capabilities})
    workflow/failure-recorded
    (record-checker! checker :workflow-failure-records
                     {:node-id (:node-id node)
                      :step-id (dispatch-arg-value args 0)
                      :retry-policy :recorded
                      :compensation-policy :recorded
                      :replay-id :stage0-replay
                      :effects effects})
    ai/error-recorded
    (record-checker! checker :ai-tool-error-records
                     {:node-id (:node-id node)
                      :provider (dispatch-arg-value args 0)
                      :policy :recorded
                      :schema :recorded
                      :budget :recorded
                      :audit :recorded
                      :capabilities capabilities})
    nil))

(def memory-regime->family
  {:gc-backed :gc
   :ownership-backed :ownership
   :borrowing :borrow
   :region-memory :region
   :arena-memory :arena
   :stack-allocation :stack
   :static-allocation :static
   :raw-memory :raw
   :mmio :mmio
   :device-memory :gpu-device
   :host-managed :host-managed
   :initialization :initialization
   :bounds-checked :bounds-check})

(defn symbol-arg-name
  [args index]
  (let [arg (nth args index nil)]
    (when (= :symbol (:source-kind arg))
      (:name arg))))

(defn record-allocation!
  [checker ctx node operator spec effects capabilities]
  (when (seq (set/intersection #{:memory/allocate :memory/free} effects))
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :effects effects
                  :capabilities capabilities
                  :profile (:profile @ctx)
                  :allocation-kind (:allocation-kind spec)
                  :regime (:memory-regime spec)
                  :visibility :effect-recorded}]
      (record-checker! checker :allocation-effect-records record)
      (when (contains? capabilities :memory/allocator)
        (record-checker! checker :allocator-runtime-manifests
                         {:node-id (:node-id node)
                          :allocator-provider (provider-name :memory/allocator)
                          :provider-version (provider-version :memory/allocator)
                          :profile (:profile @ctx)
                          :target (:target @ctx)
                          :regime (:memory-regime spec)
                          :allocation-kind (:allocation-kind spec)
                          :runtime-assumption (:runtime-assumption spec)
                          :status :declared}))
      record)))

(defn record-memory-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [regime (:memory-regime spec)]
    (record-checker! checker :memory-facts
                     {:node-id (:node-id node)
                      :operator operator
                      :regime regime
                      :family (memory-regime->family regime)
                      :type return-type
                      :effects effects
                      :capabilities capabilities
                      :profile (:profile @ctx)
                      :target (:target @ctx)
                      :safety-outcome (cond
                                        (contains? #{'unsafe/raw-read 'unsafe/mmio-read} operator)
                                        :unsafe-island

                                        (= 'bounds/check operator)
                                        :runtime-checked

                                        :else
                                        :proven-safe)
                      :memory-space (:memory-space spec)}))
  (record-allocation! checker ctx node operator spec effects capabilities)
  (case operator
    buffer/new
    (record-checker! checker :ownership-borrow-facts
                     {:node-id (:node-id node)
                      :fact :owner-created
                      :owner (:node-id node)
                      :type return-type
                      :status :owned})

    ownership/move
    (let [name (symbol-arg-name args 0)]
      (when name
        (swap! ctx assoc-in [:moved-values name]
               {:moved-at (:node-id node)
                :source-span (:source-span node)}))
      (record-checker! checker :ownership-borrow-facts
                       {:node-id (:node-id node)
                        :fact :ownership-move
                        :name name
                        :source-node (:node-id (first args))
                        :status :moved}))

    borrow/read
    (record-checker! checker :ownership-borrow-facts
                     {:node-id (:node-id node)
                      :fact :borrow
                      :mode :immutable
                      :owner-node (:node-id (first args))
                      :lifetime :lexical
                      :status :valid})

    borrow/write
    (record-checker! checker :ownership-borrow-facts
                     {:node-id (:node-id node)
                      :fact :borrow
                      :mode :mutable
                      :owner-node (:node-id (first args))
                      :lifetime :lexical
                      :excludes-other-borrows true
                      :status :valid})

    region/alloc
    (record-checker! checker :lifetime-region-facts
                     {:node-id (:node-id node)
                      :region (dispatch-arg-value args 0)
                      :allocation :region/alloc
                      :escape :rejected-unless-copied-or-moved
                      :lifetime :region-bound})

    arena/alloc
    (record-checker! checker :lifetime-region-facts
                     {:node-id (:node-id node)
                      :arena (dispatch-arg-value args 0)
                      :allocation :arena/alloc
                      :release :bulk
                      :thread-behavior :provider-declared
                      :alignment :provider-declared})

    memory/init
    (record-checker! checker :initialization-facts
                     {:node-id (:node-id node)
                      :state :init
                      :from :constructor
                      :status :proven-initialized})

    unsafe/raw-read
    (record-checker! checker :unsafe-raw-memory-audit-records
                     {:node-id (:node-id node)
                      :effect :memory/raw
                      :capabilities capabilities
                      :safety-outcome :unsafe-island
                      :preconditions [:alignment-checked :bounds-wrapper]
                      :postconditions [:no-safe-alias-created]
                      :safe-boundary :memory.safe/raw-read
                      :evidence [:stage0-fixture]
                      :owner "stage0-bootstrap"
                      :review "L10-RAW-STAGE0"})

    unsafe/mmio-read
    (do
      (record-checker! checker :unsafe-raw-memory-audit-records
                       {:node-id (:node-id node)
                        :effect :memory/mmio
                        :capabilities capabilities
                        :safety-outcome :unsafe-island
                        :preconditions [:aligned-u32 :volatile-region]
                        :postconditions [:u32-value :no-safe-alias-created]
                        :safe-boundary :mmio.safe/read-u32
                        :evidence [:stage0-fixture]
                        :owner "stage0-bootstrap"
                        :review "L10-MMIO-STAGE0"})
      (record-checker! checker :mmio-capability-records
                       {:node-id (:node-id node)
                        :capability :hardware/mmio
                        :profile (:profile @ctx)
                        :memory-space :mmio
                        :volatile-ordering :preserved
                        :alignment :u32
                        :status :audited}))

    bounds/check
    (record-checker! checker :runtime-check-records
                     {:node-id (:node-id node)
                      :kind :bounds
                      :status :runtime-checked
                      :proof :absent
                      :residual-check :retained})

    nil))

(def l11-family->conformance
  {:structured-task-scope :task-scope
   :structured-task :structured-task
   :async-await :async-await
   :atomic :atomic
   :lock :lock
   :channel :channel
   :actor :actor
   :ownership-transfer :ownership-transfer
   :immutable-sharing :immutable-sharing
   :durable-workflow :workflow-replay
   :hardware-state :hardware-state
   :gpu-kernel :gpu-kernel})

(defn record-concurrency-call!
  [checker ctx node operator args effects capabilities spec]
  (when-let [family (:concurrency-family spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :family family
                  :conformance-family (l11-family->conformance family)
                  :effects effects
                  :capabilities capabilities
                  :profile (:profile @ctx)
                  :target (:target @ctx)}]
      (record-checker! checker :concurrency-facts record)
      (when (seq effects)
        (record-checker! checker :concurrency-effect-records
                         (assoc record :effect-order :source-order)))
      (when (contains? capabilities :scheduler/task)
        (record-checker! checker :scheduler-runtime-manifests
                         {:node-id (:node-id node)
                          :operator operator
                          :scheduler-provider (provider-name :scheduler/task)
                          :provider-version (provider-version :scheduler/task)
                          :profile (:profile @ctx)
                          :target (:target @ctx)
                          :runtime-assumption :structured-scheduler
                          :status :declared}))
      (case operator
        task/scope
        (record-checker! checker :task-scope-graphs
                         {:scope-node (:node-id node)
                          :task-nodes (mapv :node-id args)
                          :scope-exit :join-or-cancel
                          :structured? true})

        task/spawn
        (record-checker! checker :task-scope-graphs
                         {:scope-node (:task-scope-id @ctx)
                          :task-node (:node-id node)
                          :task-body (mapv :node-id args)
                          :structured? (boolean (:in-task-scope? @ctx))})

        task/transfer
        (record-checker! checker :concurrency-ownership-transfer-records
                         {:node-id (:node-id node)
                          :source-node (:node-id (first args))
                          :transfer :move-into-concurrency-boundary
                          :parent-status :consumed
                          :status :explicit})

        atomic/cell
        (record-checker! checker :atomic-ordering-records
                         {:node-id (:node-id node)
                          :operation :atomic-cell
                          :ordering (:atomic-order spec)
                          :status :declared})

        atomic/load-ordered
        (do
          (record-checker! checker :atomic-ordering-records
                           {:node-id (:node-id node)
                            :operation :atomic-load
                            :ordering (:atomic-order spec)
                            :status :declared})
          (record-checker! checker :synchronization-facts
                           {:node-id (:node-id node)
                            :primitive :atomic
                            :race-safety :proven-safe
                            :ordering (:atomic-order spec)}))

        lock/with
        (record-checker! checker :synchronization-facts
                         {:node-id (:node-id node)
                          :primitive :lock
                          :race-safety :runtime-checked
                          :scope :lexical})

        channel/send
        (record-checker! checker :actor-channel-schemas
                         {:node-id (:node-id node)
                          :kind :channel
                          :message-schema :stage0-message
                          :ownership-transfer :move-or-copy
                          :status :typed})

        actor/send
        (record-checker! checker :actor-channel-schemas
                         {:node-id (:node-id node)
                          :kind :actor
                          :message-schema :stage0-message
                          :state-ownership :actor-owned
                          :status :typed})

        shared/immutable
        (record-checker! checker :race-analysis-reports
                         {:node-id (:node-id node)
                          :subject :immutable-sharing
                          :result :proven-safe
                          :reason :immutable-value})

        workflow/parallel
        (record-checker! checker :workflow-replay-records
                         {:node-id (:node-id node)
                          :workflow-step (dispatch-arg-value args 0)
                          :branches (mapv :value args)
                          :replay-id :stage0-concurrency-replay
                          :ordering :recorded
                          :status :recorded})

        hardware/state
        (record-checker! checker :synchronization-facts
                         {:node-id (:node-id node)
                          :primitive :hardware-state
                          :clock (dispatch-arg-value args 0)
                          :domain-ir-anchor :hardware-state-machine
                          :status :represented})

        gpu/kernel
        (do
          (record-checker! checker :synchronization-facts
                           {:node-id (:node-id node)
                            :primitive :gpu-barrier
                            :barrier :declared
                            :memory-space :gpu/shared
                            :race-safety :proven-safe})
          (record-checker! checker :race-analysis-reports
                           {:node-id (:node-id node)
                            :subject :gpu-kernel
                            :result :proven-safe
                            :barrier :declared}))

        nil)
      record)))

(def l12-nondeterministic-build-effects
  #{:build/time :build/random :build/network :build/model-call :build/tool-call})

(def l12-stable-constant-types
  #{"Nil" "Boolean" "Integer" "BigInt" "F64" "ExactRatio" "String"
    "Keyword" "Symbol" "Vector" "Map" "Set" "QuotedData"})

(defn l12-build-effects
  [effects]
  (set (filter build-effect? effects)))

(defn l12-digest
  [value]
  (str "sha256:" (sha256-hex (pr-str value))))

(defn l12-build-provider
  [effect]
  (symbol "gravity.build" (name effect)))

(defn l12-stable-constant-representation?
  [type-name]
  (or (contains? l12-stable-constant-types type-name)
      (and (string? type-name)
           (or (str/starts-with? type-name "Comptime[")
               (str/starts-with? type-name "ArtifactRef[")
               (str/starts-with? type-name "Schema[")
               (= type-name "GeneratedFormArtifact")))))

(defn check-compile-time-policy!
  [ctx node args effects spec]
  (let [build-effects (l12-build-effects effects)
        first-input (:value (first args))]
    (when (and (:pure-compile-time? spec) (seq build-effects))
      (typed-diagnostic! "L12-PURE-EFFECT"
                         "pure compile-time evaluation attempts a build effect"
                         node
                         "Move effectful compile-time work to an authorized build provider."
                         {:requested-effects build-effects
                          :phase :compile-time
                          :profile (:profile @ctx)
                          :target (:target @ctx)}))
    (when (and (:hermetic? @ctx)
               (:declared-input-required? spec)
               (not (contains? (:declared-inputs @ctx) first-input)))
      (typed-diagnostic! "L12-HERMETIC-INPUT"
                         "hermetic compile-time evaluation observes an undeclared input"
                         node
                         "Declare the input in namespace metadata with a content digest or remove the ambient read."
                         {:input first-input
                          :declared-inputs (:declared-inputs @ctx)
                          :phase :compile-time
                          :profile (:profile @ctx)
                          :target (:target @ctx)}))
    (when (and (:hermetic? @ctx)
               (:target-manifest-required? spec)
               (not (contains? (:target-manifests @ctx) first-input)))
      (typed-diagnostic! "L12-HERMETIC-INPUT"
                         "hermetic target probing must use a declared target manifest"
                         node
                         "Declare the target manifest used by compile-time specialization."
                         {:target-probe first-input
                          :target-manifests (:target-manifests @ctx)
                          :phase :compile-time
                          :profile (:profile @ctx)
                          :target (:target @ctx)}))
    (when (and (:requires-replay-policy? spec)
               (seq (set/intersection l12-nondeterministic-build-effects
                                      build-effects))
               (not (set/subset? (set/intersection l12-nondeterministic-build-effects
                                                   build-effects)
                                 (:replay-policy @ctx))))
      (typed-diagnostic! "L12-NONDETERMINISM"
                         "compile-time nondeterminism lacks replay policy"
                         node
                         "Record deterministic seeds, pinned provider responses, or replay records for nondeterministic build effects."
                         {:requested-effects build-effects
                          :replay-policy (:replay-policy @ctx)
                          :phase :compile-time
                          :profile (:profile @ctx)
                          :target (:target @ctx)}))
    (when (and (:requires-strict-cache-policy? spec)
               (not= :strict (:cache-policy @ctx)))
      (typed-diagnostic! "L12-CACHE-UNSAFE"
                         "compile-time cache reuse policy is not strict enough for this result"
                         node
                         "Use a strict cache policy keyed by source, grants, target manifests, replay records, and compiler version."
                         {:cache-policy (:cache-policy @ctx)
                          :phase :compile-time
                          :profile (:profile @ctx)
                          :target (:target @ctx)}))))

(defn record-compile-time-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:compile-time-kind spec)]
    (let [build-effects (l12-build-effects effects)
          granted-build-effects (set/intersection build-effects (:build-grants @ctx))
          input-digest (l12-digest (mapv #(select-keys % [:type :value :node-id])
                                         args))
          output-digest (l12-digest {:operator operator
                                     :kind kind
                                     :return-type return-type
                                     :effects effects})
          event {:node-id (:node-id node)
                 :operator operator
                 :compile-time-kind kind
                 :phase :compile-time
                 :profile (:profile @ctx)
                 :target (:target @ctx)
                 :source-span (:source-span node)
                 :effects effects
                 :capabilities capabilities
                 :build-effects build-effects
                 :build-grants granted-build-effects
                 :hermetic? (:hermetic? @ctx)
                 :input-digest input-digest
                 :output-digest output-digest
                 :result-type return-type}]
      (record-checker! checker :compile-time-evaluation-trace event)
      (when (= :pure-constant kind)
        (record-checker! checker :constant-value-table
                         {:node-id (:node-id node)
                          :constant-id (str "stage0-const-" (:node-id node))
                          :type return-type
                          :stable-representation :stage0-edn
                          :value-digest output-digest
                          :target (:target @ctx)
                          :profile (:profile @ctx)
                          :source-span (:source-span node)}))
      (when (:generated-form? spec)
        (record-checker! checker :generated-form-provenance-records
                         {:node-id (:node-id node)
                          :generator operator
                          :phase :compile-time
                          :package (:namespace node)
                          :profile (:profile @ctx)
                          :target (:target @ctx)
                          :input-digest input-digest
                          :output-digest output-digest
                          :build-effects build-effects
                          :generated-origin-chain [{:generator operator
                                                    :phase :compile-time
                                                    :source-span (:source-span node)
                                                    :input-digest input-digest
                                                    :output-digest output-digest}]
                          :syntax-validation :passed
                          :typecheck :passed
                          :effect-check :passed
                          :capability-check :passed
                          :safety-check :passed}))
      (doseq [effect build-effects]
        (record-checker! checker :compile-time-capability-proof-records
                         {:node-id (:node-id node)
                          :effect effect
                          :grant :metadata-build-grant
                          :provider (l12-build-provider effect)
                          :scope (cond
                                   (= :build/read-file effect) (:declared-inputs @ctx)
                                   (= :build/target-probe effect) (:target-manifests @ctx)
                                   :else :namespace)
                          :status (if (contains? granted-build-effects effect)
                                    :authorized
                                    :missing)
                          :phase :compile-time
                          :profile (:profile @ctx)
                          :target (:target @ctx)}))
      (when (or (:hermetic? @ctx) (seq build-effects))
        (record-checker! checker :hermetic-replay-records
                         {:node-id (:node-id node)
                          :operator operator
                          :hermetic? (:hermetic? @ctx)
                          :declared-inputs (:declared-inputs @ctx)
                          :target-manifests (:target-manifests @ctx)
                          :build-grants granted-build-effects
                          :replay-policy (:replay-policy @ctx)
                          :compiler-version :stage0-clojure
                          :input-digest input-digest
                          :output-digest output-digest
                          :status :recorded}))
      (record-checker! checker :cache-key-records
                       {:node-id (:node-id node)
                        :operator operator
                        :cache-key (l12-digest {:operator operator
                                                :source (:source-span node)
                                                :profile (:profile @ctx)
                                                :target (:target @ctx)
                                                :grants (:build-grants @ctx)
                                                :declared-inputs (:declared-inputs @ctx)
                                                :target-manifests (:target-manifests @ctx)
                                                :replay-policy (:replay-policy @ctx)
                                                :compiler-version :stage0-clojure})
                        :reuse-decision (if (= :strict (:cache-policy @ctx))
                                          :reuse-allowed
                                          :rebuild-required)
                        :policy (:cache-policy @ctx)
                        :legal-under-current-policy? (= :strict (:cache-policy @ctx))})
      event)))

(defn record-compile-time-binding!
  [checker ctx node value-fact]
  (when-not (l12-stable-constant-representation? (:type value-fact))
    (typed-diagnostic! "L12-CONST-REPRESENTATION"
                       "compile-time constant lacks a stable target representation"
                       node
                       "Use a stable Gravity value, generated form, or artifact reference for defconst."
                       {:constant (:name node)
                        :type (:type value-fact)
                        :phase :compile-time
                        :profile (:profile @ctx)
                        :target (:target @ctx)}))
  (record-checker! checker :constant-value-table
                   {:node-id (:node-id node)
                    :constant-id (str (:namespace node) "/" (:name node))
                    :name (:name node)
                    :type (:type value-fact)
                    :stable-representation :stage0-edn
                    :value-digest (l12-digest (select-keys value-fact
                                                           [:type :value :node-id]))
                    :source-span (:source-span node)
                    :profile (:profile @ctx)
                    :target (:target @ctx)
                    :binding :defconst})
  (record-checker! checker :compile-time-evaluation-trace
                   {:node-id (:node-id node)
                    :operator 'defconst
                    :compile-time-kind :defconst
                    :phase :compile-time
                    :profile (:profile @ctx)
                    :target (:target @ctx)
                    :source-span (:source-span node)
                    :result-type (:type value-fact)
                    :constant (:name node)
                    :value-node-id (:node-id value-fact)
                    :hermetic? (:hermetic? @ctx)})
  (record-checker! checker :cache-key-records
                   {:node-id (:node-id node)
                    :operator 'defconst
                    :cache-key (l12-digest {:name (:name node)
                                            :value (:node-id value-fact)
                                            :profile (:profile @ctx)
                                            :target (:target @ctx)
                                            :compiler-version :stage0-clojure})
                    :reuse-decision (if (= :strict (:cache-policy @ctx))
                                      :reuse-allowed
                                      :rebuild-required)
                    :policy (:cache-policy @ctx)
                    :legal-under-current-policy? (= :strict (:cache-policy @ctx))}))

(defn record-standard-library-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:standard-library-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :standard-library-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)}]
      (case kind
        :namespace-contract
        (record-checker! checker :standard-library-namespace-contracts
                         (merge record
                                {:namespace (dispatch-arg-value args 0)
                                 :supported-profiles (or (dispatch-arg-value args 1) #{})
                                 :stability (or (dispatch-arg-value args 2) :experimental)
                                 :allocation (or (dispatch-arg-value args 3) :declared)
                                 :since (or (dispatch-arg-value args 4) "stage0")
                                 :contract-source :namespace-metadata}))

        :api-contract
        (record-checker! checker :standard-library-api-contracts
                         (merge record
                                {:symbol (dispatch-arg-value args 0)
                                 :classification (or (dispatch-arg-value args 1) :pure)
                                 :supported-profiles (or (dispatch-arg-value args 2) #{})
                                 :declared-effects (or (dispatch-arg-value args 3) #{})
                                 :declared-capabilities (or (dispatch-arg-value args 4) #{})
                                 :allocation (or (dispatch-arg-value args 5) :none)
                                 :panic (or (dispatch-arg-value args 6) :none)
                                 :blocking (or (dispatch-arg-value args 7) :nonblocking)
                                 :nondeterminism (or (dispatch-arg-value args 8) :deterministic)
                                 :stability :stable}))

        :profile-availability
        (record-checker! checker :standard-library-profile-availability-reports
                         (merge record
                                {:namespace (dispatch-arg-value args 0)
                                 :available-profiles (or (dispatch-arg-value args 1) #{})
                                 :unavailable-profiles (or (dispatch-arg-value args 2) #{})
                                 :generated-from :actual-stage0-contracts}))

        :example
        (record-checker! checker :standard-library-documentation-examples
                         (merge record
                                {:namespace (dispatch-arg-value args 0)
                                 :profile (or (dispatch-arg-value args 1) (:profile @ctx))
                                 :example-id (or (dispatch-arg-value args 2) :stage0-example)
                                 :compile-status :passed
                                 :negative? (true? (dispatch-arg-value args 3))}))

        :unsafe-wrapper
        (record-checker! checker :standard-library-unsafe-wrapper-audits
                         (merge record
                                {:wrapper (dispatch-arg-value args 0)
                                 :unsafe-namespace (or (dispatch-arg-value args 1)
                                                       'gravity.memory.unsafe)
                                 :invariant (or (dispatch-arg-value args 2)
                                                :bounds-and-alignment-checked)
                                 :proof [:stage0-test :runtime-check]
                                 :profile-gates (or (dispatch-arg-value args 3)
                                                    #{:native})
                                 :audit-status :proved
                                 :safe-surface true}))

        :compatibility
        (record-checker! checker :standard-library-compatibility-records
                         (merge record
                                {:namespace (dispatch-arg-value args 0)
                                 :event (or (dispatch-arg-value args 1) :minor-addition)
                                 :from-version (or (dispatch-arg-value args 2) "0.1.0")
                                 :to-version (or (dispatch-arg-value args 3) "0.1.1")
                                 :migration-recorded? true
                                 :profile-support-change (or (dispatch-arg-value args 4) :none)}))

        :numeric-mode
        (record-checker! checker :standard-library-numeric-mode-records
                         (merge record
                                {:symbol (dispatch-arg-value args 0)
                                 :width (or (dispatch-arg-value args 1) :i64)
                                 :overflow (or (dispatch-arg-value args 2) :checked)
                                 :rounding (or (dispatch-arg-value args 3) :exact)
                                 :floating-mode (or (dispatch-arg-value args 4) :deterministic)
                                 :rewrite-proof :required-for-optimization}))

        :resource-api
        (record-checker! checker :standard-library-resource-records
                         (merge record
                                {:symbol (dispatch-arg-value args 0)
                                 :resource (or (dispatch-arg-value args 1) :file)
                                 :lifetime :linear
                                 :release :required
                                 :failure-mode :result
                                 :blocking (or (dispatch-arg-value args 2) :may-block)}))

        nil)
      record)))

(defn record-facet-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:facet-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :facet-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :manifest
        (record-checker! checker :facet-manifests
                         (merge record
                                {:facet-id (dispatch-arg-value args 0)
                                 :version (or (dispatch-arg-value args 1) "0.1.0")
                                 :surface (or (dispatch-arg-value args 2) #{})
                                 :profiles (or (dispatch-arg-value args 3) #{})
                                 :requires-facets (or (dispatch-arg-value args 4) #{})
                                 :build-effects (or (dispatch-arg-value args 5) #{})
                                 :capabilities-declared (or (dispatch-arg-value args 6) #{})
                                 :lowers-to (or (dispatch-arg-value args 7) #{:gravity.core})
                                 :artifacts (or (dispatch-arg-value args 8) #{})
                                 :stability (or (dispatch-arg-value args 9) :experimental)
                                 :schema-version "stage0-facet-manifest-v1"}))

        :activation
        (record-checker! checker :facet-activation-records
                         (merge record
                                {:active-facets (or (dispatch-arg-value args 0) #{})
                                 :scope :namespace
                                 :activation-source :namespace-metadata
                                 :lexical? true}))

        :generated-code
        (record-checker! checker :facet-generated-gravity-records
                         (merge record
                                {:facet-id (dispatch-arg-value args 0)
                                 :generated-form (dispatch-arg-value args 1)
                                 :validation :passed-normal-gravity-checks
                                 :typecheck :passed
                                 :effect-check :passed
                                 :capability-check :passed
                                 :source-map :preserved
                                 :output-digest (l12-digest {:operator operator
                                                             :args (mapv :value args)})}))

        :domain-ir
        (record-checker! checker :facet-domain-ir-records
                         (merge record
                                {:facet-id (dispatch-arg-value args 0)
                                 :ir-kind (dispatch-arg-value args 1)
                                 :artifact-schema-version (or (dispatch-arg-value args 2)
                                                              "0.1.0")
                                 :source-map :preserved
                                 :generated-origin-map :preserved
                                 :type-annotations :preserved
                                 :effect-annotations :preserved
                                 :profile-assumptions #{(:profile @ctx)}
                                 :target-assumptions #{(:target @ctx)}
                                 :validation-results :passed
                                 :proof-obligations [:stage0-domain-check]}))

        :composition
        (record-checker! checker :facet-composition-records
                         (merge record
                                {:from-facet (dispatch-arg-value args 0)
                                 :to-facet (dispatch-arg-value args 1)
                                 :boundary (dispatch-arg-value args 2)
                                 :effects-visible true
                                 :capabilities-visible true
                                 :artifacts-linked true}))

        :privacy-boundary
        (record-checker! checker :facet-privacy-boundary-records
                         (merge record
                                {:facet-id (dispatch-arg-value args 0)
                                 :private-value (dispatch-arg-value args 1)
                                 :public-output-schema (dispatch-arg-value args 2)
                                 :disclosure-policy (dispatch-arg-value args 3)
                                 :witness-provenance :preserved
                                 :reveal-reason :declared
                                 :boundary-preserved? true}))

        :compatibility
        (record-checker! checker :facet-compatibility-records
                         (merge record
                                {:facet-id (dispatch-arg-value args 0)
                                 :from-version (or (dispatch-arg-value args 1) "0.1.0")
                                 :to-version (or (dispatch-arg-value args 2) "0.1.1")
                                 :event (or (dispatch-arg-value args 3) :migration)
                                 :migration-diagnostic :recorded
                                 :automatic-rewrite (contains? #{:deprecated :minor-addition}
                                                               (dispatch-arg-value args 3))}))

        nil)
      record)))

(defn record-provider-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:provider-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :provider-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :declaration
        (record-checker! checker :provider-declaration-records
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :version (or (dispatch-arg-value args 1) "fixture-1")
                                 :category (or (dispatch-arg-value args 2) :provider)
                                 :implements (or (dispatch-arg-value args 3) #{})
                                 :profiles (or (dispatch-arg-value args 4) #{(:profile @ctx)})
                                 :targets (or (dispatch-arg-value args 5) #{(:target @ctx)})
                                 :runtime-effects (or (dispatch-arg-value args 6) #{})
                                 :build-effects (or (dispatch-arg-value args 7) #{})
                                 :contracts (or (dispatch-arg-value args 8)
                                                #{'gravity.contracts/Provider})
                                 :failures (or (dispatch-arg-value args 9) #{})
                                 :trust-level (or (dispatch-arg-value args 10) :trusted-core)
                                 :artifact-schema (or (dispatch-arg-value args 11)
                                                      :gravity.provider/generic-v1)
                                 :conformance-suite (or (dispatch-arg-value args 12)
                                                        :gravity.conformance/provider)
                                 :declaration-complete? true}))

        :grant
        (record-checker! checker :grant-records
                         (merge record
                                {:grant-id (dispatch-arg-value args 0)
                                 :principal (dispatch-arg-value args 1)
                                 :capability (dispatch-arg-value args 2)
                                 :provider (dispatch-arg-value args 3)
                                 :scope (dispatch-arg-value args 4)
                                 :phase (or (dispatch-arg-value args 5) :runtime)
                                 :lifetime (or (dispatch-arg-value args 6) :process)
                                 :audit-policy (or (dispatch-arg-value args 7) :required)
                                 :status :granted}))

        :capability-value
        (record-checker! checker :capability-value-records
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :provider (dispatch-arg-value args 1)
                                 :scope (dispatch-arg-value args 2)
                                 :phase (or (dispatch-arg-value args 3) :runtime)
                                 :lifetime (or (dispatch-arg-value args 4) :process)
                                 :thread-safety (or (dispatch-arg-value args 5) :thread-confined)
                                 :explicit-api-value? true}))

        :selection
        (record-checker! checker :provider-selection-records
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :provider (dispatch-arg-value args 1)
                                 :version (or (dispatch-arg-value args 2) "fixture-1")
                                 :selection (or (dispatch-arg-value args 3) :profile-default)
                                 :selection-deterministic? true
                                 :scope (or (dispatch-arg-value args 4) :namespace)
                                 :phase (or (dispatch-arg-value args 5) :runtime)
                                 :trust-level (or (dispatch-arg-value args 6) :trusted-core)
                                 :artifact-schema (or (dispatch-arg-value args 7)
                                                      :gravity.provider/generic-v1)
                                 :conformance-suite (or (dispatch-arg-value args 8)
                                                        :gravity.conformance/provider)
                                 :active-profile (:profile @ctx)
                                 :target (:target @ctx)}))

        :scope-audit
        (record-checker! checker :capability-scope-audit-logs
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :category (or (dispatch-arg-value args 1)
                                               (provider-scope-kind (dispatch-arg-value args 0)))
                                 :requested-scope (dispatch-arg-value args 2)
                                 :grant-scope (dispatch-arg-value args 3)
                                 :within-grant? (true? (dispatch-arg-value args 4))
                                 :status (if (true? (dispatch-arg-value args 4))
                                           :accepted
                                           :rejected)}))

        :compile-time-replay
        (record-checker! checker :compile-time-provider-replay-records
                         (merge record
                                {:provider (dispatch-arg-value args 0)
                                 :capability (dispatch-arg-value args 1)
                                 :input-digest (dispatch-arg-value args 2)
                                 :output-digest (or (dispatch-arg-value args 3)
                                                    (str "sha256:" (l12-digest {:operator operator
                                                                               :args (mapv :value args)})))
                                 :replayable? (not (false? (dispatch-arg-value args 4)))
                                 :secret-policy (or (dispatch-arg-value args 5) :redacted)
                                 :phase :build
                                 :audit :recorded}))

        :runtime-manifest
        (record-checker! checker :runtime-provider-manifests
                         (merge record
                                {:provider (dispatch-arg-value args 0)
                                 :version (or (dispatch-arg-value args 1) "fixture-1")
                                 :capabilities (or (dispatch-arg-value args 2) #{})
                                 :scopes (or (dispatch-arg-value args 3) {})
                                 :trust-level (or (dispatch-arg-value args 4) :trusted-core)
                                 :contracts-checked? true
                                 :profiles #{(:profile @ctx)}
                                 :targets #{(:target @ctx)}
                                 :safety-audit :enabled}))

        :conformance
        (record-checker! checker :provider-conformance-results
                         (merge record
                                {:provider (dispatch-arg-value args 0)
                                 :suite (dispatch-arg-value args 1)
                                 :status (or (dispatch-arg-value args 2) :passed)
                                 :covered-categories (or (dispatch-arg-value args 3) #{})
                                 :contract-evidence :recorded}))

        :attenuation
        (record-checker! checker :capability-attenuation-records
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :parent-scope (dispatch-arg-value args 1)
                                 :child-scope (dispatch-arg-value args 2)
                                 :authority-narrowed? true
                                 :type-metadata-preserved? true
                                 :audit-log :recorded}))

        :revocation
        (record-checker! checker :capability-revocation-records
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :profile (or (dispatch-arg-value args 1) (:profile @ctx))
                                 :revocation-mode (or (dispatch-arg-value args 2)
                                                      :static-lifetime)
                                 :status (or (dispatch-arg-value args 3) :supported)
                                 :lifetime-evidence :recorded}))

        :replacement
        (record-checker! checker :provider-replacement-records
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :original-provider (dispatch-arg-value args 1)
                                 :replacement-provider (dispatch-arg-value args 2)
                                 :contract-status (or (dispatch-arg-value args 3)
                                                      :contract-preserved)
                                 :safety-status (or (dispatch-arg-value args 4)
                                                    :safe)
                                 :safe-semantics-preserved? true}))

        nil)
      record)))

(defn record-alternative-macro-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:alternative-macro-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :alternative-macro-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :provider
        (record-checker! checker :alternative-macro-provider-declarations
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :version (or (dispatch-arg-value args 1) "fixture-1")
                                 :profiles (or (dispatch-arg-value args 2) #{(:profile @ctx)})
                                 :targets (or (dispatch-arg-value args 3) #{(:target @ctx)})
                                 :facets (or (dispatch-arg-value args 4) #{})
                                 :build-effects (or (dispatch-arg-value args 5) #{})
                                 :capabilities (or (dispatch-arg-value args 6) #{})
                                 :syntax-guarantees (or (dispatch-arg-value args 7)
                                                        #{:span :metadata
                                                          :hygiene})
                                 :hygiene-mode (or (dispatch-arg-value args 8)
                                                   :hygienic)
                                 :phase-model (or (dispatch-arg-value args 9)
                                                  :l4-compatible)
                                 :cache-policy (or (dispatch-arg-value args 10)
                                                   :deterministic)
                                 :trace-schema (or (dispatch-arg-value args 11)
                                                   :gravity.macro/trace-v1)
                                 :conformance-suite (or (dispatch-arg-value args 12)
                                                        :gravity.conformance/macro-l4)
                                 :known-deviations (or (dispatch-arg-value args 13)
                                                       #{})
                                 :declaration-complete? true}))

        :expansion-trace
        (record-checker! checker :alternative-macro-expansion-traces
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :provider-version (or (dispatch-arg-value args 1)
                                                       "fixture-1")
                                 :source-namespace (:namespace node)
                                 :macro-symbol (dispatch-arg-value args 2)
                                 :input-syntax-object-id (dispatch-arg-value args 3)
                                 :output-syntax-object-id (dispatch-arg-value args 4)
                                 :phase (or (dispatch-arg-value args 5)
                                            :macro-invocation)
                                 :active-facets (or (dispatch-arg-value args 6) #{})
                                 :reference-equivalent? true
                                 :source-span-preserved? true
                                 :generated-origin-preserved? true}))

        :syntax-object
        (record-checker! checker :alternative-macro-syntax-serializations
                         (merge record
                                {:syntax-object-id (dispatch-arg-value args 0)
                                 :form-kind (dispatch-arg-value args 1)
                                 :source-span-preserved? true
                                 :lexical-context-preserved? true
                                 :metadata-preserved? true
                                 :hygiene-marks-preserved? true
                                 :generated-origin-preserved? true
                                 :serializable? true}))

        :hygiene
        (record-checker! checker :alternative-macro-hygiene-records
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :macro-symbol (dispatch-arg-value args 1)
                                 :hygiene-mode (or (dispatch-arg-value args 2)
                                                   :hygienic)
                                 :identifier-comparison :l4-compatible
                                 :hidden-capture? false}))

        :explicit-capture
        (record-checker! checker :alternative-macro-explicit-capture-records
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :macro-symbol (dispatch-arg-value args 1)
                                 :captured-identifier (dispatch-arg-value args 2)
                                 :capture-marker :explicit
                                 :generated-origin :recorded
                                 :safe? true}))

        :build-effect-trace
        (record-checker! checker :alternative-macro-build-effect-traces
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :macro-symbol (dispatch-arg-value args 1)
                                 :build-effect (or (dispatch-arg-value args 2)
                                                   :build/read-file)
                                 :grant-id (or (dispatch-arg-value args 3)
                                               :grant/macro-build)
                                 :input-digest (or (dispatch-arg-value args 4)
                                                   "sha256:macro-input")
                                 :output-digest (or (dispatch-arg-value args 5)
                                                    (str "sha256:" (l12-digest {:operator operator
                                                                               :args (mapv :value args)})))
                                 :replay-policy (or (dispatch-arg-value args 6)
                                                    :replay-required)
                                 :secret-policy (or (dispatch-arg-value args 7)
                                                    :redacted)
                                 :phase :build}))

        :cache-decision
        (record-checker! checker :alternative-macro-cache-decisions
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :macro-symbol (dispatch-arg-value args 1)
                                 :cache-key-inputs (or (dispatch-arg-value args 2)
                                                       #{:source :provider
                                                         :profile :target
                                                         :facet :grant
                                                         :compiler-version})
                                 :decision (or (dispatch-arg-value args 3)
                                               :miss)
                                 :invalidates-on (or (dispatch-arg-value args 4)
                                                     #{:source :provider
                                                       :profile :target
                                                       :facet :grant
                                                       :compiler-version})
                                 :deterministic? true}))

        :equivalence
        (record-checker! checker :alternative-macro-equivalence-reports
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :macro-symbol (dispatch-arg-value args 1)
                                 :reference-engine :l4-reference
                                 :alternative-engine (dispatch-arg-value args 0)
                                 :comparison (or (dispatch-arg-value args 2)
                                                 :structural-alpha-equivalent)
                                 :l4-rule (or (dispatch-arg-value args 3)
                                              :expansion-result)
                                 :status :passed}))

        :facet-dispatch
        (record-checker! checker :alternative-macro-facet-dispatch-records
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :facet-id (dispatch-arg-value args 1)
                                 :activation-scope :namespace
                                 :ambiguity-check :performed
                                 :domain-ir-versioned? true
                                 :generated-gravity-origin-preserved? true
                                 :l14-boundary :preserved}))

        :generated-validation
        (record-checker! checker :alternative-macro-generated-validation-records
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :macro-symbol (dispatch-arg-value args 1)
                                 :syntax-check :passed
                                 :type-check :passed
                                 :effect-check :passed
                                 :capability-check :passed
                                 :memory-check :passed
                                 :profile-check :passed
                                 :safety-check :passed}))

        nil)
      record)))

(defn record-alternative-type-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:alternative-type-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :alternative-type-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :provider
        (record-checker! checker :alternative-type-provider-declarations
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :version (or (dispatch-arg-value args 1)
                                              "fixture-1")
                                 :kind :type-system
                                 :profiles (or (dispatch-arg-value args 2)
                                               #{(:profile @ctx)})
                                 :targets (or (dispatch-arg-value args 3)
                                              #{(:target @ctx)})
                                 :facets (or (dispatch-arg-value args 4) #{})
                                 :features (or (dispatch-arg-value args 5) #{})
                                 :build-effects (or (dispatch-arg-value args 6)
                                                    #{})
                                 :capability-requirements (or (dispatch-arg-value args 7)
                                                              #{})
                                 :fact-schema (or (dispatch-arg-value args 8)
                                                  :gravity.types/facts-v1)
                                 :proof-schema (or (dispatch-arg-value args 9)
                                                   :gravity.proof/refinement-v1)
                                 :conformance-suite (or (dispatch-arg-value args 10)
                                                        :gravity.conformance/types-l5)
                                 :soundness-claim (or (dispatch-arg-value args 11)
                                                      :reference-equivalent)
                                 :known-restrictions (or (dispatch-arg-value args 12)
                                                         #{})
                                 :deterministic-selection? true
                                 :typed-core-metadata-recorded? true
                                 :lockfile-recorded? true}))

        :typed-core-lowering
        (record-checker! checker :alternative-type-lowering-rules
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :typed-core-version (or (dispatch-arg-value args 1)
                                                         :typed-core-v1)
                                 :lowering-rules (or (dispatch-arg-value args 2)
                                                     #{:expression-types
                                                       :binding-types
                                                       :function-types})
                                 :preserved-fields (or (dispatch-arg-value args 3)
                                                       #{:effects
                                                         :capabilities
                                                         :panic
                                                         :allocation
                                                         :resource
                                                         :ownership
                                                         :casts
                                                         :proof-refs
                                                         :profile
                                                         :source-span})
                                 :accepted-downstream? true
                                 :source-span-map :preserved
                                 :macro-generated-map :preserved}))

        :fact-export
        (record-checker! checker :alternative-type-fact-export-schemas
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :fact-schema (or (dispatch-arg-value args 1)
                                                  :gravity.types/facts-v1)
                                 :fact-families (or (dispatch-arg-value args 2)
                                                   #{:ownership :region
                                                     :linear
                                                     :initialization
                                                     :nullability :taint
                                                     :schema :domain
                                                     :capability-value})
                                 :consumable-by #{:optimizer
                                                  :safety-checker
                                                  :backend-lowerer
                                                  :documentation-tool
                                                  :package-auditor
                                                  :language-server}
                                 :serialized? true}))

        :proof-artifact
        (record-checker! checker :alternative-type-proof-artifacts
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :proof-id (dispatch-arg-value args 1)
                                 :proof-schema (or (dispatch-arg-value args 2)
                                                   :gravity.proof/refinement-v1)
                                 :status (or (dispatch-arg-value args 3)
                                             :profile-safe)
                                 :serialized? true
                                 :safe-optimization-evidence? true}))

        :runtime-check
        (record-checker! checker :alternative-type-runtime-check-records
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :boundary-id (dispatch-arg-value args 1)
                                 :source-type (or (dispatch-arg-value args 2)
                                                  "Dynamic")
                                 :target-type (or (dispatch-arg-value args 3)
                                                  "User")
                                 :status (or (dispatch-arg-value args 4)
                                             :runtime-checked)
                                 :failure-type (or (dispatch-arg-value args 5)
                                                   "DecodeError")
                                 :blame (or (dispatch-arg-value args 6)
                                            :caller)
                                 :source-span-recorded? true}))

        :diagnostic-map
        (record-checker! checker :alternative-type-diagnostic-mapping-records
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :diagnostic-id (dispatch-arg-value args 1)
                                 :generated-syntax-id (dispatch-arg-value args 2)
                                 :source-path (dispatch-arg-value args 3)
                                 :type-fact-id (or (dispatch-arg-value args 4)
                                                   :fact/type-1)
                                 :macro-expansion-provenance :preserved
                                 :generated-origin-chain :preserved
                                 :source-span-map :preserved}))

        :compatibility-report
        (record-checker! checker :alternative-type-compatibility-reports
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :reference-suite (or (dispatch-arg-value args 1)
                                                      :l5-reference)
                                 :soundness-claim (or (dispatch-arg-value args 2)
                                                      :reference-equivalent)
                                 :status (or (dispatch-arg-value args 3)
                                             :passed)
                                 :positive-fixtures :passed
                                 :negative-fixtures :passed}))

        :profile-soundness
        (record-checker! checker :alternative-type-profile-soundness-evidence
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :profile (or (dispatch-arg-value args 1)
                                              (:profile @ctx))
                                 :evidence-id (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :passed)
                                 :safe-profile-claim? true}))

        :effect-capability-preservation
        (record-checker! checker :alternative-type-effect-capability-records
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :function-effects (or (dispatch-arg-value args 1)
                                                       #{})
                                 :capability-requirements (or (dispatch-arg-value args 2)
                                                              #{})
                                 :panic-behavior (or (dispatch-arg-value args 3)
                                                     #{})
                                 :allocation-behavior (or (dispatch-arg-value args 4)
                                                          #{})
                                 :resource-behavior (or (dispatch-arg-value args 5)
                                                        #{})
                                 :effects-erased? false
                                 :capabilities-erased? false
                                 :l15-capability-facts-exported? true}))

        :ownership-facts
        (record-checker! checker :alternative-type-ownership-facts
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :fact-families (or (dispatch-arg-value args 1)
                                                   #{:borrow :region
                                                     :linear
                                                     :initialization})
                                 :memory-safety-consumer :l10
                                 :resource-release-consumer :l10
                                 :concurrency-transfer-consumer :l11
                                 :backend-layout-consumer :mir
                                 :complete? true}))

        :gradual-boundary
        (record-checker! checker :alternative-type-gradual-boundaries
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :source-type (or (dispatch-arg-value args 1)
                                                  "Dynamic")
                                 :target-type (or (dispatch-arg-value args 2)
                                                  "User")
                                 :runtime-check (or (dispatch-arg-value args 3)
                                                    :checked-cast)
                                 :blame (or (dispatch-arg-value args 4)
                                            :caller)
                                 :failure-type (or (dispatch-arg-value args 5)
                                                   "DecodeError")
                                 :explicit? true
                                 :legal-for-profile? true}))

        :domain-facts
        (record-checker! checker :alternative-type-domain-facts
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :facet-id (dispatch-arg-value args 1)
                                 :fact-families (or (dispatch-arg-value args 2)
                                                   #{:schema :nullability
                                                     :taint})
                                 :crosses-facet-boundary? true
                                 :serialized-in-typed-artifact? true}))

        :optimization-proof
        (record-checker! checker :alternative-type-optimization-proofs
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :optimization (dispatch-arg-value args 1)
                                 :proof-id (dispatch-arg-value args 2)
                                 :erased-check (or (dispatch-arg-value args 3)
                                                   :runtime-check)
                                 :proof-reference-retained? true
                                 :valid-for-profile? true
                                 :valid-for-target? true
                                 :serialized? true
                                 :stable-under-transform? true
                                 :invalidates-on #{:source :provider
                                                   :profile :target
                                                   :macro :facet
                                                   :grant}}))

        nil)
      record)))

(defn record-alternative-memory-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:alternative-memory-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :alternative-memory-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :provider
        (record-checker! checker :alternative-memory-provider-declarations
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :version (or (dispatch-arg-value args 1)
                                              "fixture-1")
                                 :kind :memory-system
                                 :profiles (or (dispatch-arg-value args 2)
                                               #{(:profile @ctx)})
                                 :targets (or (dispatch-arg-value args 3)
                                              #{(:target @ctx)})
                                 :allocation-families (or (dispatch-arg-value args 4)
                                                          #{:alloc/arena})
                                 :allocation-policy (or (dispatch-arg-value args 5)
                                                        {:hidden false
                                                         :bounded true})
                                 :contracts (or (dispatch-arg-value args 6)
                                                #{'gravity.contracts/MemorySafety})
                                 :proof-artifacts (or (dispatch-arg-value args 7)
                                                      #{})
                                 :conformance-suite (or (dispatch-arg-value args 8)
                                                        :gravity.conformance/memory)
                                 :deterministic-selection? true
                                 :capability-scope :memory
                                 :safe-code-guarantee :no-undefined-behavior}))

        :allocation-strategy
        (record-checker! checker :alternative-memory-allocation-strategies
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :family (or (dispatch-arg-value args 1)
                                             :alloc/arena)
                                 :hidden? (true? (dispatch-arg-value args 2))
                                 :bounded? (not (false? (dispatch-arg-value args 3)))
                                 :can-fail? (true? (dispatch-arg-value args 4))
                                 :may-block? (true? (dispatch-arg-value args 5))
                                 :profile-policy (or (dispatch-arg-value args 6)
                                                     :explicit-allocation)
                                 :allocation-effect-recorded? true
                                 :provider-recorded? true}))

        :lifetime-facts
        (record-checker! checker :alternative-memory-lifetime-facts
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :region (dispatch-arg-value args 1)
                                 :fact-families (or (dispatch-arg-value args 2)
                                                   #{:lifetime :aliasing
                                                     :ownership :region
                                                     :escape
                                                     :initialization})
                                 :escape (or (dispatch-arg-value args 3)
                                             :no-escape)
                                 :aliasing :unique-or-shared-immutable
                                 :borrow-valid-until :scope-end
                                 :serialized? true}))

        :unsafe-boundary-audit
        (record-checker! checker :alternative-memory-unsafe-boundary-audits
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :safe-wrapper (dispatch-arg-value args 1)
                                 :unsafe-op (dispatch-arg-value args 2)
                                 :invariant (dispatch-arg-value args 3)
                                 :evidence (or (dispatch-arg-value args 4)
                                               #{:alignment-check
                                                 :bounds-check
                                                 :capability-scope})
                                 :unsafe-visible? true
                                 :safe-api-boundary? true
                                 :audit-status :passed}))

        :layout-metadata
        (record-checker! checker :alternative-memory-layout-metadata
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :type-id (dispatch-arg-value args 1)
                                 :alignment (or (dispatch-arg-value args 2)
                                                :align-8)
                                 :size (or (dispatch-arg-value args 3) 0)
                                 :endianness (or (dispatch-arg-value args 4)
                                                 :little-endian)
                                 :layout-facts-serialized? true
                                 :backend-consumable? true}))

        :runtime-check
        (record-checker! checker :alternative-memory-runtime-checks
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :check-kind (or (dispatch-arg-value args 1)
                                                 :bounds)
                                 :status (or (dispatch-arg-value args 2)
                                             :runtime-checked)
                                 :residual-check (or (dispatch-arg-value args 3)
                                                     :retained)
                                 :source-span-recorded? true
                                 :capability-scope :memory}))

        :release-evidence
        (record-checker! checker :alternative-memory-release-evidence
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :resource (dispatch-arg-value args 1)
                                 :release-mode (or (dispatch-arg-value args 2)
                                                   :exactly-once)
                                 :leak-status (or (dispatch-arg-value args 3)
                                                  :no-leak)
                                 :double-release-status :rejected
                                 :release-proof :recorded}))

        :device-map
        (record-checker! checker :alternative-memory-device-maps
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :address-space (or (dispatch-arg-value args 1)
                                                    :device/global)
                                 :synchronization (or (dispatch-arg-value args 2)
                                                      :host-device-sync)
                                 :mmio-map (or (dispatch-arg-value args 3)
                                               :device/register-map)
                                 :width :u32
                                 :alignment :u32
                                 :volatile-semantics :preserved
                                 :ordering :declared
                                 :capability-scope :hardware/mmio}))

        :ffi-allocator
        (record-checker! checker :alternative-memory-ffi-allocator-records
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :foreign-library (dispatch-arg-value args 1)
                                 :allocator (dispatch-arg-value args 2)
                                 :release (dispatch-arg-value args 3)
                                 :compatibility (or (dispatch-arg-value args 4)
                                                    :compatible)
                                 :ownership-transfer :recorded
                                 :nullability :recorded
                                 :lifetime :recorded
                                 :thread-affinity :recorded}))

        :conformance-report
        (record-checker! checker :alternative-memory-conformance-reports
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :suite (or (dispatch-arg-value args 1)
                                            :gravity.conformance/memory)
                                 :status (or (dispatch-arg-value args 2)
                                             :passed)
                                 :covered-tests (or (dispatch-arg-value args 3)
                                                    #{:leak :double-release
                                                      :bounds :uninit
                                                      :alias
                                                      :device-sync
                                                      :mmio-width})
                                 :positive-fixtures :passed
                                 :negative-fixtures :passed}))

        :safety-classification
        (record-checker! checker :alternative-memory-safety-classifications
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :operation (dispatch-arg-value args 1)
                                 :outcomes (or (dispatch-arg-value args 2)
                                               #{:proven-safe
                                                 :runtime-checked
                                                 :rejected
                                                 :unsafe-island})
                                 :evidence-id (dispatch-arg-value args 3)
                                 :safe-code-guarantee :no-undefined-behavior}))

        nil)
      record)))

(defn record-interop-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:interop-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :interop-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :foreign-declaration
        (record-checker! checker :interop-foreign-binding-declarations
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :boundary-family (dispatch-arg-value args 1)
                                 :foreign-language (dispatch-arg-value args 2)
                                 :abi-or-protocol (dispatch-arg-value args 3)
                                 :link-name (dispatch-arg-value args 4)
                                 :type-mapping (dispatch-arg-value args 5)
                                 :declared-effects (or (dispatch-arg-value args 6)
                                                       #{})
                                 :declared-capabilities (or (dispatch-arg-value args 7)
                                                            #{})
                                 :ownership (or (dispatch-arg-value args 8)
                                                {})
                                 :safety (or (dispatch-arg-value args 9)
                                             :unsafe)
                                 :profiles (or (dispatch-arg-value args 10)
                                               #{(:profile @ctx)})
                                 :targets (or (dispatch-arg-value args 11)
                                              #{(:target @ctx)})
                                 :version (or (dispatch-arg-value args 12)
                                              "fixture-1")
                                 :threading :declared
                                 :memory-behavior :declared
                                 :error-behavior :declared
                                 :complete? true}))

        :boundary-metadata
        (record-checker! checker :interop-boundary-metadata
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :metadata-kind (dispatch-arg-value args 1)
                                 :version (or (dispatch-arg-value args 2)
                                              "fixture-1")
                                 :provider-id (dispatch-arg-value args 3)
                                 :reproducible? true
                                 :versioned? true}))

        :generated-binding
        (record-checker! checker :interop-generated-binding-provenance
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :source-kind (dispatch-arg-value args 1)
                                 :source-digest (or (dispatch-arg-value args 2)
                                                    "sha256:schema")
                                 :schema-version (or (dispatch-arg-value args 3)
                                                     "fixture-1")
                                 :generated-types (or (dispatch-arg-value args 4)
                                                      #{})
                                 :generated-codecs :recorded
                                 :field-nullability :recorded
                                 :diagnostic-provenance :preserved
                                 :conformance-evidence :recorded}))

        :safe-wrapper-audit
        (record-checker! checker :interop-safe-wrapper-audits
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :safe-wrapper (dispatch-arg-value args 1)
                                 :foreign-call (dispatch-arg-value args 2)
                                 :requires (or (dispatch-arg-value args 3)
                                               #{})
                                 :ensures (or (dispatch-arg-value args 4)
                                             #{})
                                 :evidence (or (dispatch-arg-value args 5)
                                               #{})
                                 :unsafe-call-visible? true
                                 :audit-status :passed}))

        :type-mapping
        (record-checker! checker :interop-type-mapping-records
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :source-type (dispatch-arg-value args 1)
                                 :foreign-type (dispatch-arg-value args 2)
                                 :direction (or (dispatch-arg-value args 3)
                                                :bidirectional)
                                 :conversion (or (dispatch-arg-value args 4)
                                                 :checked)
                                 :failure-behavior (or (dispatch-arg-value args 5)
                                                       :result)
                                 :round-trip-test :passed}))

        :ownership-map
        (record-checker! checker :interop-ownership-lifetime-maps
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :ownership (or (dispatch-arg-value args 1)
                                                {})
                                 :allocator (dispatch-arg-value args 2)
                                 :release (dispatch-arg-value args 3)
                                 :nullability :recorded
                                 :initialization :recorded
                                 :lifetime :recorded
                                 :thread-affinity :recorded}))

        :error-map
        (record-checker! checker :interop-error-translation-maps
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :foreign-errors (or (dispatch-arg-value args 1)
                                                     #{})
                                 :gravity-errors (or (dispatch-arg-value args 2)
                                                     #{})
                                 :untranslated? false
                                 :translation-test :passed}))

        :capability-effect
        (record-checker! checker :interop-capability-effect-records
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :declared-effects (or (dispatch-arg-value args 1)
                                                       #{:ffi/call})
                                 :declared-capabilities (or (dispatch-arg-value args 2)
                                                            #{:ffi/call})
                                 :provider-id (dispatch-arg-value args 3)
                                 :effect-enforced? true
                                 :capability-enforced? true}))

        :migration-shim
        (record-checker! checker :interop-migration-shim-records
                         (merge record
                                {:shim-id (dispatch-arg-value args 0)
                                 :incumbent-source (dispatch-arg-value args 1)
                                 :target-namespace (dispatch-arg-value args 2)
                                 :preserved (or (dispatch-arg-value args 3)
                                                #{})
                                 :rejected (or (dispatch-arg-value args 4)
                                               #{})
                                 :generated-files (or (dispatch-arg-value args 5)
                                                      #{})
                                 :owner (or (dispatch-arg-value args 6)
                                            "interop-working-group")
                                 :stability :temporary}))

        :parity-report
        (record-checker! checker :interop-parity-test-reports
                         (merge record
                                {:shim-id (dispatch-arg-value args 0)
                                 :suite (or (dispatch-arg-value args 1)
                                            :interop/parity)
                                 :status (or (dispatch-arg-value args 2)
                                             :passed)
                                 :golden-tests :passed
                                 :round-trip-tests :passed
                                 :error-translation-tests :passed
                                 :ownership-tests :passed}))

        :compatibility-record
        (record-checker! checker :interop-compatibility-records
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :version (or (dispatch-arg-value args 1)
                                              "fixture-1")
                                 :policy (or (dispatch-arg-value args 2)
                                             :semver)
                                 :deprecation (or (dispatch-arg-value args 3)
                                                  :none)
                                 :lockfile-entry :recorded}))

        :schema-drift-check
        (record-checker! checker :interop-schema-drift-records
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :source-digest (dispatch-arg-value args 1)
                                 :generated-digest (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :passed)
                                 :compatibility-check :performed}))

        :profile-rejection
        (record-checker! checker :interop-profile-rejection-records
                         (merge record
                                {:boundary-id (dispatch-arg-value args 0)
                                 :unsupported-profile (dispatch-arg-value args 1)
                                 :replacement (or (dispatch-arg-value args 2)
                                                  :portable-artifact)
                                 :rejection-diagnostic "L19-PROFILE"
                                 :status :rejected}))

        nil)
      record)))

(def safe1-legal-outcomes
  #{:proven-safe :runtime-checked :rejected :unsafe-island})

(def safe1-required-families
  [:proven-safe :runtime-checked :rejected :unsafe-island
   :runtime-check-record :unsafe-island-audit :generated-provenance
   :optimization-proof :dependency-mode])

(defn safe1-diagnostic!
  [id message node remediation data]
  (typed-diagnostic! id message node remediation
                     (merge {:safe-rule :SAFE1
                             :active-profile (:profile node)
                             :source-span (:source-span node)}
                            data)))

(defn check-safe1-outcome!
  [node operation outcome evidence]
  (when-not (contains? safe1-legal-outcomes outcome)
    (safe1-diagnostic! "SAFE1-NO-OUTCOME"
                       "dangerous operation lacks a legal safety outcome"
                       node
                       "Classify the operation as :proven-safe, :runtime-checked, :rejected, or :unsafe-island."
                       {:operation operation
                        :safety-outcome outcome
                        :missing-fact :legal-safety-outcome}))
  (when (and (= :proven-safe outcome) (nil? evidence))
    (safe1-diagnostic! "SAFE1-PROOF-MISSING"
                       "claimed static safety proof is absent"
                       node
                       "Attach a proof reference, retain a runtime check, reject the operation, or isolate it as an unsafe island."
                       {:operation operation
                        :safety-outcome outcome
                        :missing-fact :proof-reference})))

(defn safe1-conformance-fixture
  [checker-state]
  (let [classifications (:safe1-safety-classification-records checker-state)
        outcomes (set (map :outcome classifications))
        covered (cond-> #{}
                  (contains? outcomes :proven-safe) (conj :proven-safe)
                  (contains? outcomes :runtime-checked) (conj :runtime-checked)
                  (contains? outcomes :rejected) (conj :rejected)
                  (contains? outcomes :unsafe-island) (conj :unsafe-island)
                  (seq (:safe1-runtime-check-records checker-state))
                  (conj :runtime-check-record)
                  (seq (:safe1-unsafe-island-audit-records checker-state))
                  (conj :unsafe-island-audit)
                  (seq (:safe1-generated-code-safety-provenance checker-state))
                  (conj :generated-provenance)
                  (seq (:safe1-optimization-check-erasure-justifications checker-state))
                  (conj :optimization-proof)
                  (seq (:safe1-dependency-safety-mode-records checker-state))
                  (conj :dependency-mode))
        missing (vec (remove covered safe1-required-families))]
    {:required-families safe1-required-families
     :covered-families (vec (sort-by name covered))
     :legal-outcomes (vec (sort-by name safe1-legal-outcomes))
     :observed-outcomes (vec (sort-by name outcomes))
     :missing-families missing
     :status (if (empty? missing) :complete :incomplete)}))

(defn record-safe1-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:safe1-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :safe1-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :safety-mode (:safety @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :classification
        (let [operation (dispatch-arg-value args 0)
              outcome (dispatch-arg-value args 1)
              condition (dispatch-arg-value args 2)
              evidence (dispatch-arg-value args 3)
              failure (dispatch-arg-value args 4)]
          (check-safe1-outcome! node operation outcome evidence)
          (record-checker! checker :safe1-safety-classification-records
                           (merge record
                                  {:operation operation
                                   :outcome outcome
                                   :condition condition
                                   :proof-reference (when (= :proven-safe outcome)
                                                      evidence)
                                   :runtime-check (when (= :runtime-checked outcome)
                                                    condition)
                                   :rejection-diagnostic (when (= :rejected outcome)
                                                           failure)
                                   :unsafe-audit (when (= :unsafe-island outcome)
                                                   evidence)
                                   :failure-behavior failure
                                   :exactly-one-outcome? true})))

        :runtime-check
        (let [operation (dispatch-arg-value args 0)
              condition (dispatch-arg-value args 1)
              failure (dispatch-arg-value args 2)]
          (when (nil? condition)
            (safe1-diagnostic! "SAFE1-CHECK-MISSING"
                               "runtime checking is required but no emitted check is recorded"
                               node
                               "Emit a runtime check with condition, source span, failure behavior, and artifact record."
                               {:operation operation
                                :safety-outcome :runtime-checked
                                :missing-fact :runtime-check}))
          (record-checker! checker :safe1-runtime-check-records
                           (merge record
                                  {:operation operation
                                   :outcome :runtime-checked
                                   :condition condition
                                   :failure-behavior (or failure
                                                         :panic/safety-check)
                                   :defined-failure? true
                                   :type-context :recorded
                                   :effect-context effects
                                   :capability-context capabilities
                                   :artifact-recorded? true})))

        :unsafe-island
        (let [operation (dispatch-arg-value args 0)
              owner (dispatch-arg-value args 1)
              reason (dispatch-arg-value args 2)
              invariant (dispatch-arg-value args 3)
              safe-boundary (dispatch-arg-value args 4)
              evidence (dispatch-arg-value args 5)]
          (when (or (nil? owner) (nil? reason) (nil? invariant)
                    (nil? safe-boundary))
            (safe1-diagnostic! "SAFE1-UNSAFE-METADATA"
                               "unsafe island lacks required audit metadata"
                               node
                               "Record owner, reason, invariant, review policy, source span, effects, capabilities, and safe wrapper boundary."
                               {:operation operation
                                :safety-outcome :unsafe-island
                                :missing-fact :unsafe-audit-metadata}))
          (when (= :safe (:safety @ctx))
            (safe1-diagnostic! "SAFE1-UNSAFE-POLICY"
                               "unsafe island violates active safety mode or package policy"
                               node
                               "Move unsafe code to an allowed mode or provide package policy permitting the audited island."
                               {:operation operation
                                :safety-outcome :unsafe-island
                                :missing-fact :unsafe-policy-approval}))
          (record-checker! checker :safe1-unsafe-island-audit-records
                           (merge record
                                  {:operation operation
                                   :outcome :unsafe-island
                                   :owner owner
                                   :reason reason
                                   :invariant invariant
                                   :safe-boundary safe-boundary
                                   :evidence (or evidence #{})
                                   :review-policy :recorded
                                   :audit-status :passed})))

        :generated-provenance
        (record-checker! checker :safe1-generated-code-safety-provenance
                         (merge record
                                {:generator (dispatch-arg-value args 0)
                                 :source-form (dispatch-arg-value args 1)
                                 :generated-form (dispatch-arg-value args 2)
                                 :origin-status (or (dispatch-arg-value args 3)
                                                    :preserved)
                                 :diagnostic-source :generator-and-generated-form}))

        :optimization-erasure
        (let [operation (dispatch-arg-value args 0)
              erased-check (dispatch-arg-value args 1)
              outcome (dispatch-arg-value args 2)
              proof (dispatch-arg-value args 3)]
          (when (nil? proof)
            (safe1-diagnostic! "SAFE1-OPTIMIZATION-PROOF"
                               "optimization removes a safety check without replacement proof"
                               node
                               "Retain the check or attach a proof record for the erased check."
                               {:operation operation
                                :erased-check erased-check
                                :missing-fact :optimization-proof}))
          (record-checker! checker :safe1-optimization-check-erasure-justifications
                           (merge record
                                  {:operation operation
                                   :erased-check erased-check
                                   :outcome (or outcome :proven-safe)
                                   :proof proof
                                   :proof-preserved? (boolean proof)})))

        :dependency-mode
        (let [dependency (dispatch-arg-value args 0)
              caller-safety (dispatch-arg-value args 1)
              dependency-safety (dispatch-arg-value args 2)
              status (or (dispatch-arg-value args 3) :accepted)]
          (when (= :rejected status)
            (safe1-diagnostic! "SAFE1-DEPENDENCY-MODE"
                               "dependency safety mode is weaker than the caller's safe claim"
                               node
                               "Use a certified safe facade, a reviewed unsafe wrapper, or reject the dependency."
                               {:dependency dependency
                                :caller-safety caller-safety
                                :dependency-safety dependency-safety
                                :missing-fact :dependency-safety-certificate}))
          (record-checker! checker :safe1-dependency-safety-mode-records
                           (merge record
                                  {:dependency dependency
                                   :caller-safety caller-safety
                                   :dependency-safety dependency-safety
                                   :status status
                                   :certificate :recorded})))

        :conformance
        (record-checker! checker :safe1-conformance-records
                         (merge record
                                {:declared-outcomes (or (dispatch-arg-value args 0)
                                                       safe1-legal-outcomes)
                                 :status (or (dispatch-arg-value args 1)
                                             :complete)
                                 :positive-fixtures :passed
                                 :negative-fixtures :passed}))

        nil)
      record)))

(def safe-memory-required-families
  [:safe2-memory-operation :safe2-runtime-check :safe2-allocation-release
   :safe2-escape-analysis :safe2-optimization-proof
   :safe2-backend-preservation :safe2-unsafe-audit
   :safe3-ownership-graph :safe3-borrow-graph :safe3-lifetime-map
   :safe3-transfer :safe3-runtime-borrow-check
   :safe4-region-lifetime :safe4-arena-generation
   :safe4-reset-invalidation :safe4-provider :safe4-cleanup
   :safe5-linear-flow :safe5-terminal-operation
   :safe5-exceptional-cleanup :safe5-structured-lowering
   :safe5-generated-flow])

(defn safe-memory-conformance-fixture
  [checker-state]
  (let [covered (cond-> #{}
                  (seq (:safe-memory-operation-records checker-state))
                  (conj :safe2-memory-operation)
                  (seq (:safe-memory-runtime-check-records checker-state))
                  (conj :safe2-runtime-check)
                  (seq (:safe-memory-allocation-release-maps checker-state))
                  (conj :safe2-allocation-release)
                  (seq (:safe-memory-escape-analysis-records checker-state))
                  (conj :safe2-escape-analysis)
                  (seq (:safe-memory-proof-records checker-state))
                  (conj :safe2-optimization-proof)
                  (seq (:safe-memory-backend-preservation-records checker-state))
                  (conj :safe2-backend-preservation)
                  (seq (:safe-memory-unsafe-audit-records checker-state))
                  (conj :safe2-unsafe-audit)
                  (seq (:safe-memory-ownership-graphs checker-state))
                  (conj :safe3-ownership-graph)
                  (seq (:safe-memory-borrow-graphs checker-state))
                  (conj :safe3-borrow-graph)
                  (seq (:safe-memory-lifetime-interval-maps checker-state))
                  (conj :safe3-lifetime-map)
                  (seq (:safe-memory-transfer-records checker-state))
                  (conj :safe3-transfer)
                  (seq (:safe-memory-runtime-borrow-check-records checker-state))
                  (conj :safe3-runtime-borrow-check)
                  (seq (:safe-memory-region-lifetime-maps checker-state))
                  (conj :safe4-region-lifetime)
                  (seq (:safe-memory-arena-generation-graphs checker-state))
                  (conj :safe4-arena-generation)
                  (seq (:safe-memory-reset-invalidation-records checker-state))
                  (conj :safe4-reset-invalidation)
                  (seq (:safe-memory-provider-records checker-state))
                  (conj :safe4-provider)
                  (seq (:safe-memory-cleanup-records checker-state))
                  (conj :safe4-cleanup)
                  (seq (:safe-memory-linear-flow-graphs checker-state))
                  (conj :safe5-linear-flow)
                  (seq (:safe-memory-terminal-operation-records checker-state))
                  (conj :safe5-terminal-operation)
                  (seq (:safe-memory-exceptional-cleanup-records checker-state))
                  (conj :safe5-exceptional-cleanup)
                  (seq (:safe-memory-structured-resource-lowerings checker-state))
                  (conj :safe5-structured-lowering)
                  (seq (:safe-memory-generated-linear-flow-records checker-state))
                  (conj :safe5-generated-flow))
        missing (vec (remove covered safe-memory-required-families))]
    {:required-families safe-memory-required-families
     :covered-families (vec (sort-by name covered))
     :documents [:SAFE2 :SAFE3 :SAFE4 :SAFE5]
     :missing-families missing
     :status (if (empty? missing) :complete :incomplete)}))

(defn record-safe-memory-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:safe-memory-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :safe-memory-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :safety-mode (:safety @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :memory-operation
        (record-checker! checker :safe-memory-operation-records
                         (merge record
                                {:operation (dispatch-arg-value args 0)
                                 :subject (dispatch-arg-value args 1)
                                 :safety-outcome (dispatch-arg-value args 2)
                                 :required-facts (or (dispatch-arg-value args 3) #{})
                                 :memory-regime (dispatch-arg-value args 4)
                                 :provider-id (dispatch-arg-value args 5)
                                 :source-facts-preserved? true}))

        :runtime-check
        (record-checker! checker :safe-memory-runtime-check-records
                         (merge record
                                {:check-kind (dispatch-arg-value args 0)
                                 :subject (dispatch-arg-value args 1)
                                 :failure-behavior (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :runtime-checked)
                                 :defined-failure? true
                                 :artifact-recorded? true}))

        :allocation-release
        (record-checker! checker :safe-memory-allocation-release-maps
                         (merge record
                                {:allocation-id (dispatch-arg-value args 0)
                                 :release-id (dispatch-arg-value args 1)
                                 :provider-id (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :matched)
                                 :allocator-identity-preserved? true}))

        :escape-analysis
        (record-checker! checker :safe-memory-escape-analysis-records
                         (merge record
                                {:value-id (dispatch-arg-value args 0)
                                 :scope (dispatch-arg-value args 1)
                                 :escape-path (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :no-escape)
                                 :profile-aware? true}))

        :optimization-proof
        (record-checker! checker :safe-memory-proof-records
                         (merge record
                                {:erased-check (dispatch-arg-value args 0)
                                 :proof-id (dispatch-arg-value args 1)
                                 :status (or (dispatch-arg-value args 2)
                                             :preserved)
                                 :proof-preserved? (boolean (dispatch-arg-value args 1))}))

        :backend-preservation
        (record-checker! checker :safe-memory-backend-preservation-records
                         (merge record
                                {:subject (dispatch-arg-value args 0)
                                 :preserved-facts (or (dispatch-arg-value args 1)
                                                      #{})
                                 :status (or (dispatch-arg-value args 2)
                                             :preserved)
                                 :target-consumable? true}))

        :unsafe-audit
        (record-checker! checker :safe-memory-unsafe-audit-records
                         (merge record
                                {:operation (dispatch-arg-value args 0)
                                 :safe-boundary (dispatch-arg-value args 1)
                                 :owner (dispatch-arg-value args 2)
                                 :invariant (dispatch-arg-value args 3)
                                 :outcome :unsafe-island
                                 :review-policy :recorded
                                 :audit-status :passed}))

        :ownership-graph
        (record-checker! checker :safe-memory-ownership-graphs
                         (merge record
                                {:value-id (dispatch-arg-value args 0)
                                 :owner-id (dispatch-arg-value args 1)
                                 :ownership-kind (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :valid)
                                 :move-consume-visible? true}))

        :borrow-graph
        (record-checker! checker :safe-memory-borrow-graphs
                         (merge record
                                {:owner-id (dispatch-arg-value args 0)
                                 :borrow-id (dispatch-arg-value args 1)
                                 :mode (dispatch-arg-value args 2)
                                 :lifetime (dispatch-arg-value args 3)
                                 :status (or (dispatch-arg-value args 4)
                                             :valid)
                                 :exclusive-when-mutable? (= :mutable
                                                             (dispatch-arg-value args 2))}))

        :lifetime-map
        (record-checker! checker :safe-memory-lifetime-interval-maps
                         (merge record
                                {:reference-id (dispatch-arg-value args 0)
                                 :lifetime-id (dispatch-arg-value args 1)
                                 :relation (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :valid)}))

        :transfer-record
        (record-checker! checker :safe-memory-transfer-records
                         (merge record
                                {:value-id (dispatch-arg-value args 0)
                                 :from-owner (dispatch-arg-value args 1)
                                 :to-owner (dispatch-arg-value args 2)
                                 :mode (or (dispatch-arg-value args 3)
                                           :moved)
                                 :source-consumed? true
                                 :destination-cleanup-contract? true}))

        :runtime-borrow-check
        (record-checker! checker :safe-memory-runtime-borrow-check-records
                         (merge record
                                {:borrow-id (dispatch-arg-value args 0)
                                 :condition (dispatch-arg-value args 1)
                                 :failure-behavior (dispatch-arg-value args 2)
                                 :status :runtime-checked
                                 :artifact-recorded? true}))

        :region-lifetime
        (record-checker! checker :safe-memory-region-lifetime-maps
                         (merge record
                                {:region-id (dispatch-arg-value args 0)
                                 :allocation-id (dispatch-arg-value args 1)
                                 :lifetime (dispatch-arg-value args 2)
                                 :escape-status (or (dispatch-arg-value args 3)
                                                    :no-escape)}))

        :arena-generation
        (record-checker! checker :safe-memory-arena-generation-graphs
                         (merge record
                                {:arena-id (dispatch-arg-value args 0)
                                 :generation (dispatch-arg-value args 1)
                                 :state (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :valid)}))

        :reset-invalidation
        (record-checker! checker :safe-memory-reset-invalidation-records
                         (merge record
                                {:arena-id (dispatch-arg-value args 0)
                                 :from-generation (dispatch-arg-value args 1)
                                 :to-generation (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :invalidated)}))

        :provider
        (record-checker! checker :safe-memory-provider-records
                         (merge record
                                {:provider-id (dispatch-arg-value args 0)
                                 :profiles (or (dispatch-arg-value args 1)
                                               #{(:profile @ctx)})
                                 :reset-policy (dispatch-arg-value args 2)
                                 :thread-policy (dispatch-arg-value args 3)
                                 :allocation-alignment-failure-threading-declared? true}))

        :cleanup-record
        (record-checker! checker :safe-memory-cleanup-records
                         (merge record
                                {:scope-id (dispatch-arg-value args 0)
                                 :cleanup-kind (dispatch-arg-value args 1)
                                 :mode (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :valid)
                                 :runs-at-most-once? true}))

        :linear-flow
        (record-checker! checker :safe-memory-linear-flow-graphs
                         (merge record
                                {:resource-id (dispatch-arg-value args 0)
                                 :start-state (dispatch-arg-value args 1)
                                 :terminal-state (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :exactly-once)}))

        :terminal-operation
        (record-checker! checker :safe-memory-terminal-operation-records
                         (merge record
                                {:resource-id (dispatch-arg-value args 0)
                                 :operation (dispatch-arg-value args 1)
                                 :terminal-state (dispatch-arg-value args 2)
                                 :control-flow-path (or (dispatch-arg-value args 3)
                                                        :normal)
                                 :provider-compatible? true}))

        :exceptional-cleanup
        (record-checker! checker :safe-memory-exceptional-cleanup-records
                         (merge record
                                {:resource-id (dispatch-arg-value args 0)
                                 :control-flow-path (dispatch-arg-value args 1)
                                 :cleanup-operation (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :covered)}))

        :structured-lowering
        (record-checker! checker :safe-memory-structured-resource-lowerings
                         (merge record
                                {:form (dispatch-arg-value args 0)
                                 :resource-id (dispatch-arg-value args 1)
                                 :lowering (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :preserved)
                                 :normal-error-panic-cancel-covered? true}))

        :generated-flow
        (record-checker! checker :safe-memory-generated-linear-flow-records
                         (merge record
                                {:generator (dispatch-arg-value args 0)
                                 :resource-id (dispatch-arg-value args 1)
                                 :duplication-status (dispatch-arg-value args 2)
                                 :origin-status (or (dispatch-arg-value args 3)
                                                    :preserved)
                                 :generated-origin-preserved? true}))

        :conformance
        (record-checker! checker :safe-memory-conformance-records
                         (merge record
                                {:documents (or (dispatch-arg-value args 0)
                                                #{:SAFE2 :SAFE3 :SAFE4 :SAFE5})
                                 :status (or (dispatch-arg-value args 1)
                                             :complete)
                                 :positive-fixtures :passed
                                 :negative-fixtures :passed}))

        nil)
      record)))

(def safe6-required-families
  [:unsafe-island :safe-wrapper :operation-inventory :review-status
   :invariant-proof :generated-provenance :policy-decision
   :dependency-summary :release-audit])

(defn safe6-conformance-fixture
  [checker-state]
  (let [covered (cond-> #{}
                  (seq (:safe6-unsafe-island-records checker-state))
                  (conj :unsafe-island)
                  (seq (:safe6-safe-wrapper-records checker-state))
                  (conj :safe-wrapper)
                  (seq (:safe6-operation-inventories checker-state))
                  (conj :operation-inventory)
                  (seq (:safe6-review-status-records checker-state))
                  (conj :review-status)
                  (seq (:safe6-invariant-proof-links checker-state))
                  (conj :invariant-proof)
                  (seq (:safe6-generated-unsafe-provenance checker-state))
                  (conj :generated-provenance)
                  (seq (:safe6-policy-decision-records checker-state))
                  (conj :policy-decision)
                  (seq (:safe6-dependency-unsafe-summaries checker-state))
                  (conj :dependency-summary)
                  (seq (:safe6-release-audit-reports checker-state))
                  (conj :release-audit))
        missing (vec (remove covered safe6-required-families))]
    {:required-families safe6-required-families
     :covered-families (vec (sort-by name covered))
     :document :SAFE6
     :missing-families missing
     :status (if (empty? missing) :complete :incomplete)}))

(defn record-safe6-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:safe6-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :safe6-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :safety-mode (:safety @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :unsafe-island
        (record-checker! checker :safe6-unsafe-island-records
                         (merge record
                                {:island-id (dispatch-arg-value args 0)
                                 :operation (dispatch-arg-value args 1)
                                 :reason (dispatch-arg-value args 2)
                                 :owner (dispatch-arg-value args 3)
                                 :invariants (or (dispatch-arg-value args 4) #{})
                                 :preconditions (or (dispatch-arg-value args 5) #{})
                                 :postconditions (or (dispatch-arg-value args 6) #{})
                                 :safe-boundary (dispatch-arg-value args 7)
                                 :review-policy (dispatch-arg-value args 8)
                                 :review-state :approved
                                 :audit-status :passed}))

        :safe-wrapper
        (record-checker! checker :safe6-safe-wrapper-records
                         (merge record
                                {:wrapper (dispatch-arg-value args 0)
                                 :unsafe-islands (or (dispatch-arg-value args 1) #{})
                                 :invariant (dispatch-arg-value args 2)
                                 :hides-raw-capabilities? true
                                 :failure-behavior (dispatch-arg-value args 3)
                                 :preconditions-enforced? true
                                 :cleanup-connected? true}))

        :operation-inventory
        (record-checker! checker :safe6-operation-inventories
                         (merge record
                                {:package (dispatch-arg-value args 0)
                                 :operation-families (or (dispatch-arg-value args 1)
                                                        #{})
                                 :island-count (or (dispatch-arg-value args 2)
                                                   0)
                                 :safe-wrappers (or (dispatch-arg-value args 3)
                                                    #{})}))

        :review-status
        (record-checker! checker :safe6-review-status-records
                         (merge record
                                {:island-id (dispatch-arg-value args 0)
                                 :policy (dispatch-arg-value args 1)
                                 :reviewer (dispatch-arg-value args 2)
                                 :state (or (dispatch-arg-value args 3)
                                            :approved)
                                 :expiration (dispatch-arg-value args 4)
                                 :source-version-bound? true}))

        :invariant-proof
        (record-checker! checker :safe6-invariant-proof-links
                         (merge record
                                {:island-id (dispatch-arg-value args 0)
                                 :invariant (dispatch-arg-value args 1)
                                 :evidence (or (dispatch-arg-value args 2)
                                               #{})
                                 :proof-status (or (dispatch-arg-value args 3)
                                                   :recorded)}))

        :generated-provenance
        (record-checker! checker :safe6-generated-unsafe-provenance
                         (merge record
                                {:generator (dispatch-arg-value args 0)
                                 :source-form (dispatch-arg-value args 1)
                                 :generated-form (dispatch-arg-value args 2)
                                 :unsafe-island (dispatch-arg-value args 3)
                                 :origin-status :preserved
                                 :diagnostic-source :generator-and-generated-form}))

        :policy-decision
        (record-checker! checker :safe6-policy-decision-records
                         (merge record
                                {:policy (dispatch-arg-value args 0)
                                 :package (dispatch-arg-value args 1)
                                 :decision (dispatch-arg-value args 2)
                                 :reason (dispatch-arg-value args 3)
                                 :profile (:profile @ctx)
                                 :target (:target @ctx)}))

        :dependency-summary
        (record-checker! checker :safe6-dependency-unsafe-summaries
                         (merge record
                                {:dependency (dispatch-arg-value args 0)
                                 :unsafe-island-count (or (dispatch-arg-value args 1)
                                                          0)
                                 :operation-families (or (dispatch-arg-value args 2)
                                                        #{})
                                 :review-states (or (dispatch-arg-value args 3)
                                                    #{})
                                 :safe-wrappers (or (dispatch-arg-value args 4)
                                                    #{})
                                 :policy-status (or (dispatch-arg-value args 5)
                                                    :accepted)}))

        :release-audit
        (record-checker! checker :safe6-release-audit-reports
                         (merge record
                                {:package (dispatch-arg-value args 0)
                                 :unsafe-island-count (or (dispatch-arg-value args 1)
                                                          0)
                                 :review-status (dispatch-arg-value args 2)
                                 :certificate-status (dispatch-arg-value args 3)
                                 :artifact-stable? true}))

        :conformance
        (record-checker! checker :safe6-conformance-records
                         (merge record
                                {:document :SAFE6
                                 :status (or (dispatch-arg-value args 0)
                                             :complete)
                                 :positive-fixtures :passed
                                 :negative-fixtures :passed}))

        nil)
      record)))

