        :safe11-validator-contract
        (record-checker! checker :safe11-validator-contracts
                         (merge record
                                {:validator (dispatch-arg-value args 0)
                                 :accepts (or (dispatch-arg-value args 1) #{})
                                 :clears (or (dispatch-arg-value args 2) #{})
                                 :retains (or (dispatch-arg-value args 3) #{})
                                 :residual (or (dispatch-arg-value args 4) #{})
                                 :failure-type (dispatch-arg-value args 5)}))

        :safe11-residual-constraint
        (record-checker! checker :safe11-residual-constraint-records
                         (merge record
                                {:value-id (dispatch-arg-value args 0)
                                 :residual (or (dispatch-arg-value args 1) #{})
                                 :sink (dispatch-arg-value args 2)
                                 :status (or (dispatch-arg-value args 3)
                                             :accepted)}))

        :safe11-sink-authorization
        (record-checker! checker :safe11-sink-authorization-records
                         (merge record
                                {:sink (dispatch-arg-value args 0)
                                 :accepted-state (dispatch-arg-value args 1)
                                 :required-handling (or (dispatch-arg-value args 2)
                                                        #{})
                                 :capability (dispatch-arg-value args 3)
                                 :status (or (dispatch-arg-value args 4)
                                             :authorized)}))

        :safe11-parameterization
        (record-checker! checker :safe11-parameterization-records
                         (merge record
                                {:api (dispatch-arg-value args 0)
                                 :syntax-source (dispatch-arg-value args 1)
                                 :parameters (or (dispatch-arg-value args 2) #{})
                                 :status (or (dispatch-arg-value args 3)
                                             :parameterized)}))

        :safe11-deserialization
        (record-checker! checker :safe11-deserialization-records
                         (merge record
                                {:input (dispatch-arg-value args 0)
                                 :schema (dispatch-arg-value args 1)
                                 :validation (dispatch-arg-value args 2)
                                 :residual-taint (or (dispatch-arg-value args 3)
                                                     #{})}))

        :safe11-secret-redaction
        (record-checker! checker :safe11-secret-redaction-records
                         (merge record
                                {:secret-id (dispatch-arg-value args 0)
                                 :sink (dispatch-arg-value args 1)
                                 :redaction (dispatch-arg-value args 2)
                                 :artifact-policy (dispatch-arg-value args 3)
                                 :secret-value-emitted? false}))

        :safe11-prompt-tool-policy
        (record-checker! checker :safe11-prompt-tool-policy-records
                         (merge record
                                {:prompt-id (dispatch-arg-value args 0)
                                 :tool (dispatch-arg-value args 1)
                                 :categories (or (dispatch-arg-value args 2) #{})
                                 :policy (dispatch-arg-value args 3)
                                 :capability (dispatch-arg-value args 4)
                                 :policy-mediated? true}))

        :safe11-generated-taint
        (record-checker! checker :safe11-generated-taint-propagation
                         (merge record
                                {:generator (dispatch-arg-value args 0)
                                 :source-categories (or (dispatch-arg-value args 1)
                                                        #{})
                                 :source-form (dispatch-arg-value args 2)
                                 :generated-form (dispatch-arg-value args 3)
                                 :status (or (dispatch-arg-value args 4)
                                             :preserved)}))

        :safe11-unsafe-clear-audit
        (record-checker! checker :safe11-unsafe-clear-audits
                         (merge record
                                {:value-id (dispatch-arg-value args 0)
                                 :categories (or (dispatch-arg-value args 1)
                                                 #{})
                                 :unsafe-island (dispatch-arg-value args 2)
                                 :owner (dispatch-arg-value args 3)
                                 :review (dispatch-arg-value args 4)
                                 :audit-status :passed}))

        :safe11-conformance
        (record-checker! checker :safe11-conformance-records
                         (merge record
                                {:document :SAFE11
                                 :status (or (dispatch-arg-value args 0)
                                             :complete)
                                 :positive-fixtures :passed
                                 :negative-fixtures :passed}))

        nil)
      record)))

(defn record-safe-capability-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:safe-capability-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :safe-capability-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :safety-mode (:safety @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :safe10-capability-requirement
        (record-checker! checker :safe10-capability-requirement-records
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :family (dispatch-arg-value args 1)
                                 :effect (dispatch-arg-value args 2)
                                 :phase (dispatch-arg-value args 3)
                                 :visibility (dispatch-arg-value args 4)
                                 :provider-id (dispatch-arg-value args 5)
                                 :grant-id (dispatch-arg-value args 6)
                                 :scope (dispatch-arg-value args 7)
                                 :visible-in-artifact? true}))

        :safe10-grant-intersection
        (record-checker! checker :safe10-grant-intersection-records
                         (merge record
                                {:grant-id (dispatch-arg-value args 0)
                                 :capability (dispatch-arg-value args 1)
                                 :source (dispatch-arg-value args 2)
                                 :package-manifest (dispatch-arg-value args 3)
                                 :workspace-policy (dispatch-arg-value args 4)
                                 :profile-policy (dispatch-arg-value args 5)
                                 :deployment-policy (dispatch-arg-value args 6)
                                 :runtime-provider-scope (dispatch-arg-value args 7)
                                 :effective-grant (dispatch-arg-value args 8)
                                 :decision (or (dispatch-arg-value args 9)
                                               :allowed)
                                 :expands-parent-authority? false}))

        :safe10-provider-selection
        (record-checker! checker :safe10-provider-selection-records
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :provider-id (dispatch-arg-value args 1)
                                 :provider-version (dispatch-arg-value args 2)
                                 :selection-source (dispatch-arg-value args 3)
                                 :scope (dispatch-arg-value args 4)
                                 :phase (dispatch-arg-value args 5)
                                 :trust-level (dispatch-arg-value args 6)
                                 :artifact-schema (dispatch-arg-value args 7)
                                 :conformance-suite (dispatch-arg-value args 8)
                                 :policy-bypassed? false}))

        :safe10-scope-check
        (record-checker! checker :safe10-scope-check-records
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :category (dispatch-arg-value args 1)
                                 :requested-scope (dispatch-arg-value args 2)
                                 :grant-scope (dispatch-arg-value args 3)
                                 :allowed? (boolean (dispatch-arg-value args 4))
                                 :failure-behavior (dispatch-arg-value args 5)}))

        :safe10-attenuation
        (record-checker! checker :safe10-attenuation-records
                         (merge record
                                {:parent-capability (dispatch-arg-value args 0)
                                 :derived-capability (dispatch-arg-value args 1)
                                 :parent-scope (dispatch-arg-value args 2)
                                 :derived-scope (dispatch-arg-value args 3)
                                 :lifetime (dispatch-arg-value args 4)
                                 :narrowed? (boolean (dispatch-arg-value args 5))
                                 :expands-authority? false}))

        :safe10-revocation
        (record-checker! checker :safe10-revocation-records
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :provider-id (dispatch-arg-value args 1)
                                 :revoker (dispatch-arg-value args 2)
                                 :failure-type (dispatch-arg-value args 3)
                                 :thread-safety (dispatch-arg-value args 4)
                                 :synchronous? (boolean (dispatch-arg-value args 5))
                                 :supported? (boolean (dispatch-arg-value args 6))}))

        :safe10-secret-redaction
        (record-checker! checker :safe10-secret-redaction-records
                         (merge record
                                {:secret-name (dispatch-arg-value args 0)
                                 :redaction-policy (dispatch-arg-value args 1)
                                 :artifact-policy (dispatch-arg-value args 2)
                                 :export-policy (dispatch-arg-value args 3)
                                 :secret-value-emitted? false}))

        :safe10-runtime-check
        (record-checker! checker :safe10-runtime-check-records
                         (merge record
                                {:capability (dispatch-arg-value args 0)
                                 :provider-id (dispatch-arg-value args 1)
                                 :scope (dispatch-arg-value args 2)
                                 :failure-behavior (dispatch-arg-value args 3)
                                 :audit-record (dispatch-arg-value args 4)
                                 :status (or (dispatch-arg-value args 5)
                                             :runtime-checked)}))

        :safe10-usage-summary
        (record-checker! checker :safe10-usage-summaries
                         (merge record
                                {:package-id (dispatch-arg-value args 0)
                                 :runtime-capabilities (or (dispatch-arg-value args 1)
                                                           #{})
                                 :build-capabilities (or (dispatch-arg-value args 2)
                                                         #{})
                                 :capability-families (or (dispatch-arg-value args 3)
                                                          #{})
                                 :policy-layers (or (dispatch-arg-value args 4)
                                                    #{})
                                 :deployment-id (dispatch-arg-value args 5)
                                 :secret-values-redacted? true}))

        :safe10-conformance
        (record-checker! checker :safe10-conformance-records
                         (merge record
                                {:document :SAFE10
                                 :status (or (dispatch-arg-value args 0)
                                             :complete)
                                 :positive-fixtures :passed
                                 :negative-fixtures :passed}))

        :safe14-package-manifest
        (record-checker! checker :safe14-package-safety-manifests
                         (merge record
                                {:package-id (dispatch-arg-value args 0)
                                 :package-version (dispatch-arg-value args 1)
                                 :profiles (or (dispatch-arg-value args 2) #{})
                                 :runtime-capabilities (or (dispatch-arg-value args 3) #{})
                                 :build-effects (or (dispatch-arg-value args 4) #{})
                                 :denied-effects (or (dispatch-arg-value args 5) #{})
                                 :unsafe-summary (dispatch-arg-value args 6)
                                 :native-deps (or (dispatch-arg-value args 7) [])
                                 :compiler-plugins (or (dispatch-arg-value args 8) [])
                                 :generated-artifacts (or (dispatch-arg-value args 9) [])
                                 :reproducible? (boolean (dispatch-arg-value args 10))
                                 :metadata-complete? true}))

        :safe14-lockfile
        (record-checker! checker :safe14-lockfile-records
                         (merge record
                                {:package-id (dispatch-arg-value args 0)
                                 :package-version (dispatch-arg-value args 1)
                                 :package-digest (dispatch-arg-value args 2)
                                 :provider-versions (dispatch-arg-value args 3)
                                 :build-grants (or (dispatch-arg-value args 4) #{})
                                 :native-digests (or (dispatch-arg-value args 5) {})
                                 :generated-artifact-digests (or (dispatch-arg-value args 6) {})
                                 :replay-records (or (dispatch-arg-value args 7) #{})
                                 :pinned? (boolean (dispatch-arg-value args 8))}))

        :safe14-build-effect-summary
        (record-checker! checker :safe14-build-effect-summaries
                         (merge record
                                {:package-id (dispatch-arg-value args 0)
                                 :build-effects (or (dispatch-arg-value args 1) #{})
                                 :grants (or (dispatch-arg-value args 2) #{})
                                 :providers (or (dispatch-arg-value args 3) #{})
                                 :replayable? (boolean (dispatch-arg-value args 4))
                                 :denied-effects (or (dispatch-arg-value args 5) #{})}))

        :safe14-runtime-capability-summary
        (record-checker! checker :safe14-runtime-capability-summaries
                         (merge record
                                {:package-id (dispatch-arg-value args 0)
                                 :dependency-path (or (dispatch-arg-value args 1) [])
                                 :requested-capabilities (or (dispatch-arg-value args 2) #{})
                                 :approved-capabilities (or (dispatch-arg-value args 3) #{})
                                 :denied-capabilities (or (dispatch-arg-value args 4) #{})
                                 :root-approval (dispatch-arg-value args 5)}))

        :safe14-unsafe-summary
        (record-checker! checker :safe14-unsafe-summaries
                         (merge record
                                {:package-id (dispatch-arg-value args 0)
                                 :unsafe-island-count (or (dispatch-arg-value args 1)
                                                          0)
                                 :operation-families (or (dispatch-arg-value args 2) #{})
                                 :profiles (or (dispatch-arg-value args 3) #{})
                                 :safe-wrappers (or (dispatch-arg-value args 4) #{})
                                 :review-status (dispatch-arg-value args 5)
                                 :certificate (dispatch-arg-value args 6)
                                 :unsafe-dependencies (or (dispatch-arg-value args 7)
                                                          #{})}))

        :safe14-native-dependency
        (record-checker! checker :safe14-native-dependency-records
                         (merge record
                                {:package-id (dispatch-arg-value args 0)
                                 :library (dispatch-arg-value args 1)
                                 :version (dispatch-arg-value args 2)
                                 :source (dispatch-arg-value args 3)
                                 :digest (dispatch-arg-value args 4)
                                 :abi (dispatch-arg-value args 5)
                                 :targets (or (dispatch-arg-value args 6) #{})
                                 :link-mode (dispatch-arg-value args 7)
                                 :license (dispatch-arg-value args 8)
                                 :safety-wrapper-package (dispatch-arg-value args 9)
                                 :required-capabilities (or (dispatch-arg-value args 10)
                                                            #{})
                                 :advisories (or (dispatch-arg-value args 11)
                                                 #{})
                                 :metadata-complete? true}))

        :safe14-generated-provenance
        (record-checker! checker :safe14-generated-artifact-provenance
                         (merge record
                                {:artifact-id (dispatch-arg-value args 0)
                                 :generator-id (dispatch-arg-value args 1)
                                 :source-digests (or (dispatch-arg-value args 2)
                                                     #{})
                                 :build-effects (or (dispatch-arg-value args 3)
                                                    #{})
                                 :provider-grants (or (dispatch-arg-value args 4)
                                                      #{})
                                 :output-digest (dispatch-arg-value args 5)
                                 :reproducible? (boolean (dispatch-arg-value args 6))
                                 :safety-checks (or (dispatch-arg-value args 7)
                                                    #{})}))

        :safe14-signature-attestation
        (record-checker! checker :safe14-signature-attestation-records
                         (merge record
                                {:package-id (dispatch-arg-value args 0)
                                 :package-digest (dispatch-arg-value args 1)
                                 :signature (dispatch-arg-value args 2)
                                 :attestation (dispatch-arg-value args 3)
                                 :verified? (boolean (dispatch-arg-value args 4))}))

        :safe14-authority-diff
        (record-checker! checker :safe14-authority-diff-records
                         (merge record
                                {:package-id (dispatch-arg-value args 0)
                                 :from-version (dispatch-arg-value args 1)
                                 :to-version (dispatch-arg-value args 2)
                                 :added-runtime-capabilities (or (dispatch-arg-value args 3)
                                                                 #{})
                                 :added-build-effects (or (dispatch-arg-value args 4)
                                                          #{})
                                 :added-unsafe-families (or (dispatch-arg-value args 5)
                                                           #{})
                                 :approval (dispatch-arg-value args 6)
                                 :status (or (dispatch-arg-value args 7)
                                             :no-unapproved-expansion)}))

        :safe14-conformance
        (record-checker! checker :safe14-conformance-records
                         (merge record
                                {:document :SAFE14
                                 :status (or (dispatch-arg-value args 0)
                                             :complete)
                                 :positive-fixtures :passed
                                 :negative-fixtures :passed}))

        nil)
      record)))

(defn record-safety-conformance-call!
  [checker ctx node operator args effects capabilities return-type spec]
  (when-let [kind (:safety-conformance-kind spec)]
    (let [record {:node-id (:node-id node)
                  :operator operator
                  :safety-conformance-kind kind
                  :profile (:profile @ctx)
                  :target (:target @ctx)
                  :safety-mode (:safety @ctx)
                  :effects effects
                  :capabilities capabilities
                  :return-type return-type
                  :source-span (:source-span node)
                  :generated-origin-chain (:generated-origin node)}]
      (case kind
        :safe12-macro-safety-declaration
        (record-checker! checker :safe12-macro-safety-declarations
                         (merge record
                                {:macro-symbol (dispatch-arg-value args 0)
                                 :generates-unsafe? (boolean (dispatch-arg-value args 1))
                                 :build-effects (or (dispatch-arg-value args 2) #{})
                                 :capabilities-declared (or (dispatch-arg-value args 3) #{})
