                                 :trust-level (dispatch-arg-value args 3)
                                 :policy-status (dispatch-arg-value args 4)}))

        :safe15-unsafe-wrapper-audit
        (record-checker! checker :safe15-unsafe-wrapper-audit-views
                         (merge record
                                {:wrapper-id (dispatch-arg-value args 0)
                                 :unsafe-island (dispatch-arg-value args 1)
                                 :certificate-id (dispatch-arg-value args 2)
                                 :invariant (dispatch-arg-value args 3)
                                 :status :invariant-proven}))

        :safe15-backend-preservation
        (record-checker! checker :safe15-backend-preservation-records
                         (merge record
                                {:proof-id (dispatch-arg-value args 0)
                                 :backend (dispatch-arg-value args 1)
                                 :preserved-assumptions (or (dispatch-arg-value args 2) #{})
                                 :invalidated-assumptions (or (dispatch-arg-value args 3) #{})
                                 :status (or (dispatch-arg-value args 4)
                                             :preserved)}))

        :safe15-conformance
        (record-checker! checker :safe15-conformance-records
                         (merge record
                                {:document :SAFE15
                                 :status (or (dispatch-arg-value args 0)
                                             :complete)
                                 :positive-fixtures :passed
                                 :negative-fixtures :passed}))

        :safe16-fixture-manifest
        (record-checker! checker :safe16-fixture-manifests
                         (merge record
                                {:fixture-id (dispatch-arg-value args 0)
                                 :document-id (dispatch-arg-value args 1)
                                 :profile (dispatch-arg-value args 2)
                                 :target (dispatch-arg-value args 3)
                                 :source (dispatch-arg-value args 4)
                                 :expected (dispatch-arg-value args 5)}))

        :safe16-expected-outcome
        (record-checker! checker :safe16-expected-outcome-manifests
                         (merge record
                                {:fixture-id (dispatch-arg-value args 0)
                                 :document-id (dispatch-arg-value args 1)
                                 :expected-verdict (dispatch-arg-value args 2)
                                 :operation-outcome (dispatch-arg-value args 3)
                                 :diagnostic-id (dispatch-arg-value args 4)
                                 :artifact-inspections (or (dispatch-arg-value args 5) #{})}))

        :safe16-diagnostic-match
        (record-checker! checker :safe16-diagnostic-match-records
                         (merge record
                                {:fixture-id (dispatch-arg-value args 0)
                                 :expected-diagnostic (dispatch-arg-value args 1)
