(defn check-match-node
  [checker ctx node]
  (let [value-fact (check-typed-node checker ctx (:value node))
        clauses (:clauses node)
        patterns (mapv :pattern clauses)
        seen-default? (atom false)
        branch-facts
        (mapv (fn [clause]
                (let [pattern (:pattern clause)
                      branch-index (:branch-index clause)
                      bindings (vec (pattern-bindings pattern))
                      family (pattern-family pattern)]
                  (when @seen-default?
                    (let [diagnostic {:match-node (:node-id node)
                                      :branch-index branch-index
                                      :pattern pattern
                                      :diagnostic "L7-UNREACHABLE"}]
                      (record-checker! checker :unreachable-branch-diagnostics diagnostic)
                      (typed-diagnostic! "L7-UNREACHABLE"
                                         "match branch can never be selected"
                                         node
                                         "Move the default branch after reachable branches or remove the unreachable branch."
                                         diagnostic)))
                  (when (wildcard-pattern? pattern)
                    (reset! seen-default? true))
                  (when-let [binding (duplicate-binding pattern)]
                    (typed-diagnostic! "L7-DUP-BINDING"
                                       "pattern binds the same name more than once"
                                       node
                                       "Use distinct names or a future equality-pattern form."
                                       {:binding binding
                                        :pattern pattern}))
                  (when (literal-pattern-incompatible? (:type value-fact) pattern)
                    (typed-diagnostic! "L7-PATTERN-TYPE"
                                       "pattern is incompatible with the scrutinee type"
                                       node
                                       "Use a pattern whose type can match the scrutinee."
                                       {:scrutinee-type (:type value-fact)
                                        :pattern pattern
                                        :pattern-type (literal-pattern-type pattern)}))
                  (when (and (= :map (pattern-kind pattern))
                             (untrusted-type? (:type value-fact)))
                    (typed-diagnostic! "L7-UNVALIDATED-SHAPE"
                                       "untrusted data is matched as a closed shape without validation"
                                       node
                                       "Validate external data through a schema boundary before matching required keys."
                                       {:scrutinee-type (:type value-fact)
                                        :pattern pattern}))
                  (when (= "MoveLinear" (constructor-name pattern))
                    (typed-diagnostic! "L7-LINEAR-MOVE"
                                       "pattern moves a linear value without ownership proof"
                                       node
                                       "Borrow the value or provide ownership evidence before moving it in a pattern."
                                       {:pattern pattern}))
                  (let [branch-ctx (child-context ctx)
                        binding-type (narrowed-type (:type value-fact) pattern)]
                    (doseq [binding bindings]
                      (swap! branch-ctx assoc-in [:variable-types binding] binding-type)
                      (record-checker! checker :branch-type-narrowing-table
                                       {:match-node (:node-id node)
                                        :branch-index branch-index
                                        :binding binding
                                        :narrowed-type binding-type
                                        :pattern-family family})
                      (record-checker! checker :pattern-ownership-facts
                                       {:match-node (:node-id node)
                                        :branch-index branch-index
                                        :binding binding
                                        :mode (if (= :linear family)
                                                :borrow-or-bind-linear
                                                :borrow-or-bind)}))
                    (when (and (= :map (pattern-kind pattern))
                               (validated-type? (:type value-fact)))
                      (record-checker! checker :pattern-schema-validation-links
                                       {:match-node (:node-id node)
                                        :branch-index branch-index
                                        :schema (:type value-fact)
                                        :validation-boundary :validated}))
                    (let [guard-fact (when-let [guard (:guard clause)]
                                       (let [guard-ctx (permissive-pattern-context branch-ctx)
                                             fact (check-typed-node checker guard-ctx guard)]
                                         (when (guard-effects-illegal? ctx fact)
                                           (typed-diagnostic! "L7-GUARD-EFFECT"
                                                              "guard effect is not legal for the active context"
                                                              node
                                                              "Declare the guard effect and capability, use a pure guard, or move the effect outside the pattern."
                                                              {:guard-effects (:effects fact)
                                                               :guard-capabilities (:capabilities fact)
                                                               :declared-effects (:declared-effects @ctx)
                                                               :declared-capabilities (:declared-capabilities @ctx)}))
                                         fact))
                          body-fact (check-typed-node checker branch-ctx (:body clause))
                          branch-effects (set/union (:effects body-fact)
                                                    (or (:effects guard-fact) #{}))
                          branch-capabilities (set/union (:capabilities body-fact)
                                                         (or (:capabilities guard-fact) #{}))]
                      (record-checker! checker :branch-effect-summary
                                       {:match-node (:node-id node)
                                        :branch-index branch-index
                                        :guard-effects (or (:effects guard-fact) #{})
                                        :branch-effects branch-effects
                                        :branch-capabilities branch-capabilities})
                      (assoc body-fact
                             :effects branch-effects
                             :capabilities branch-capabilities
                             :guard-fact guard-fact
                             :pattern pattern
                             :branch-index branch-index)))))
              clauses)
        has-default? (boolean (some wildcard-pattern? patterns))
        constructors (constructor-coverage patterns)]
    (when (and (closed-result-match? patterns)
               (not has-default?)
               (not (exhaustive-result-match? patterns)))
      (typed-diagnostic! "L7-NONEXHAUSTIVE"
                         "closed match lacks a required constructor case"
                         node
                         "Cover all closed constructors or add an explicit default where policy allows it."
                         {:constructors constructors
                          :required #{"Ok" "Err"}}))
    (when (and (= :formal (:profile @ctx))
               (not has-default?)
               (not (exhaustive-result-match? patterns)))
      (typed-diagnostic! "L7-NONEXHAUSTIVE"
                         "formal profile requires total pattern matching"
                         node
                         "Cover every closed case or provide an explicit partiality proof."
                         {:profile (:profile @ctx)}))
    (record-checker! checker :match-decision-trees
                     {:match-node (:node-id node)
                      :scrutinee-type (:type value-fact)
                      :pattern-families (vec (set (map pattern-family patterns)))
                      :branches (mapv (fn [clause]
                                        {:branch-index (:branch-index clause)
                                         :pattern (:pattern clause)
                                         :pattern-kind (pattern-kind (:pattern clause))
                                         :pattern-family (pattern-family (:pattern clause))
                                         :guarded? (boolean (:guard clause))
                                         :source-span (:source-span node)})
                                      clauses)})
    (record-checker! checker :exhaustiveness-report
                     {:match-node (:node-id node)
                      :profile (:profile @ctx)
                      :constructors constructors
                      :has-default has-default?
                      :closed-result-match? (boolean (closed-result-match? patterns))
                      :exhaustive? (or has-default?
                                       (not (closed-result-match? patterns))
                                       (exhaustive-result-match? patterns))})
    (typed-fact checker node (common-type branch-facts)
                (set/union (:effects value-fact) (collect-fact-effects branch-facts))
                (set/union (:capabilities value-fact) (collect-fact-capabilities branch-facts))
                {:children (vec (cons value-fact branch-facts))
                 :clauses clauses})))

(defn check-typed-node
  [checker ctx node]
  (case (:kind node)
    :literal
    (typed-fact checker node (literal-type (:value node)) #{} #{}
                {:value (:value node)})

    :symbol
    (do
      (when-let [move (get-in @ctx [:moved-values (:name node)])]
        (typed-diagnostic! "L10-USE-AFTER-MOVE"
                           "owned value is used after transfer"
                           node
                           "Do not use a moved value unless ownership is returned explicitly."
                           {:name (:name node)
                            :moved-at (:moved-at move)}))
      (typed-fact checker node
                  (get-in @ctx [:variable-types (:name node)] "Dynamic")
                  #{} #{}
                  {:name (:name node)}))

    :quote
    (typed-fact checker node "QuotedData" #{} #{}
                {:value (:value node)})

    :if
    (let [children (mapv #(check-typed-node checker ctx %) (:children node))]
      (typed-fact checker node (common-type (rest children))
                  (collect-fact-effects children)
                  (collect-fact-capabilities children)
                  {:children children}))

    :do
    (let [children (mapv #(check-typed-node checker ctx %) (:children node))]
      (typed-fact checker node (if (seq children) (:type (last children)) "Nil")
                  (collect-fact-effects children)
                  (collect-fact-capabilities children)
                  {:children children}))

    :let
    (let [child (child-context ctx)
          bound-linear (atom [])
          binding-facts (mapv (fn [{:keys [name initializer]}]
                                (let [fact (check-typed-node checker child initializer)]
                                  (swap! child assoc-in [:variable-types name] (:type fact))
                                  (when (linear-type? (:type fact))
                                    (swap! child assoc-in [:linear-resources name]
                                           {:name name
                                            :resource-type (linear-resource-type (:type fact))
                                            :node-id (:node-id fact)
                                            :consumed? false})
                                    (swap! bound-linear conj name))
                                  fact))
                              (:bindings node))
          body-facts (mapv #(check-typed-node checker child %) (:children node))]
      (doseq [name @bound-linear]
        (let [state (get-in @child [:linear-resources name])]
          (when-not (:consumed? state)
            (typed-diagnostic! "L10-LINEAR-RESOURCE"
                               "linear resource was not consumed exactly once"
                               node
                               "Consume, transfer, or explicitly forget the linear resource under a privileged policy."
                               {:resource name
                                :resource-type (:resource-type state)}))))
      (typed-fact checker node (if (seq body-facts) (:type (last body-facts)) "Nil")
                  (collect-fact-effects (concat binding-facts body-facts))
                  (collect-fact-capabilities (concat binding-facts body-facts))
                  {:children (vec (concat binding-facts body-facts))}))

    :fn
    (let [child (child-context ctx)
          params (parse-typed-params (:params node))]
      (doseq [{:keys [name type]} params]
        (swap! child assoc-in [:variable-types name] type))
      (let [body (mapv #(check-typed-node checker child %) (:children node))
            latent-effects (collect-fact-effects body)
            capabilities (collect-fact-capabilities body)
            return-type (if (seq body) (:type (last body)) "Nil")
            signature {:node-id (:node-id node)
                       :params (mapv #(select-keys % [:name :type :rest? :declared?]) params)
                       :return-type return-type
                       :latent-effects latent-effects
                       :capabilities capabilities}]
        (record-checker! checker :function-signature-table signature)
        (typed-fact checker node (str "Fn[" (count params) "]->" return-type)
                    #{} #{}
                    {:latent-effects latent-effects
                     :children body})))

    :loop
    (let [child (child-context ctx)
          binding-facts (mapv (fn [{:keys [name initializer]}]
                                (let [fact (check-typed-node checker child initializer)]
                                  (swap! child assoc-in [:variable-types name] (:type fact))
                                  fact))
                              (:bindings node))
          body (mapv #(check-typed-node checker child %) (:children node))]
      (typed-fact checker node (if (seq body) (:type (last body)) "Nil")
                  (collect-fact-effects (concat binding-facts body))
                  (collect-fact-capabilities (concat binding-facts body))
                  {:children (vec (concat binding-facts body))}))

    :recur
    (let [args (mapv #(check-typed-node checker ctx %) (:arguments node))]
      (typed-fact checker node "Never"
                  (conj (collect-fact-effects args) :control/recur)
                  (collect-fact-capabilities args)
                  {:children args}))

    :def
    (let [value-fact (check-typed-node checker ctx (:value node))]
      (swap! ctx assoc-in [:variable-types (:name node)] (:type value-fact))
      (when (:compile-time-binding? node)
        (record-compile-time-binding! checker ctx node value-fact))
      (typed-fact checker node (:type value-fact)
                  (:effects value-fact)
                  (:capabilities value-fact)
                  {:name (:name node)
                   :children [value-fact]}))

    :var
    (typed-fact checker node (str "Var[" (:name node) "]") #{} #{}
                {:name (:name node)})

    :set!
    (let [value-fact (check-typed-node checker ctx (:value node))]
      (typed-fact checker node "Nil"
                  (conj (:effects value-fact) :state/write)
                  (:capabilities value-fact)
                  {:target (:target node)
                   :children [value-fact]}))

    :try
    (let [body (check-typed-node checker ctx (:body node))]
      (typed-fact checker node (:type body)
                  (:effects body)
                  (:capabilities body)
                  {:children [body]
                   :handlers (:handlers node)}))

    :throw
    (let [value-fact (check-typed-node checker ctx (:value node))]
      (record-checker! checker :thrown-error-effect-records
                       {:node-id (:node-id node)
                        :error-type (:type value-fact)
                        :effect :error/throw
                        :profile (:profile @ctx)
                        :source-span (:source-span node)})
      (typed-fact checker node "Never"
                  (conj (:effects value-fact) :error/throw)
                  (:capabilities value-fact)
                  {:children [value-fact]}))

    :match
    (check-match-node checker ctx node)

    :call
    (check-call-node checker ctx node)

    (typed-diagnostic! "L5-ANNOTATION-REQUIRED"
                       "typed core checker has no rule for this core form"
                       node
                       "Add a typed core rule before using this form.")))

(defn type-environment
  [typed-roots]
  (->> typed-roots
       (keep (fn [fact]
               (when-let [name (:name fact)]
                 {:name name
                  :type (:type fact)
                  :node-id (:node-id fact)})))
       vec))

(defn distinct-records
  [records]
  (distinct-by-pr-str records))

(defn covered-type-categories
  [coverage]
  (->> coverage
       (map :category)
       set
       (sort-by name)
       vec))

(defn type-conformance-fixture
  [coverage]
  (let [covered (covered-type-categories coverage)
        covered-set (set covered)
        missing (vec (remove covered-set l5-required-type-categories))]
    {:required-categories l5-required-type-categories
     :covered-categories covered
     :missing-categories missing
     :status (if (empty? missing) :complete :incomplete)}))

(defn mir-type-preservation-records
  [type-facts]
  (mapv (fn [fact]
          {:core-node-id (:node-id fact)
           :mir-value-id (str "stage0-mir-value-" (:node-id fact))
           :type (:type fact)
           :source-kind (:source-kind fact)
           :source-span (:source-span fact)
           :preserved? true})
        type-facts))

(def l6-required-effect-families
  [:pure :io :filesystem :network :database :memory-allocation :raw-memory
   :mmio :interrupt :resource :time :random :async :generator
   :resumable-error :ffi :reflection :dynamic :compiler :build :secrets
   :shell :workflow :ai :unsafe-island :handler])

(defn effect-families
  [effect]
  (let [entry (effect-registry-entry effect)]
    (cond-> [(:family entry)]
      (= :unsafe-island (:kind entry)) (conj :unsafe-island))))

(defn covered-effect-families
  [effect-facts build-log handled-table]
  (let [effect-families (->> effect-facts
                             (mapcat :effects)
                             (mapcat effect-families))
        build-families (map (fn [_] :build) build-log)
        handled-families (map (fn [_] :handler) handled-table)
        pure-family (when (empty? (mapcat :effects effect-facts)) [:pure])]
    (->> (concat effect-families build-families handled-families pure-family [:pure])
         (remove nil?)
         set
         (sort-by name)
         vec)))

(defn effect-conformance-fixture
  [effect-facts build-log handled-table]
  (let [covered (covered-effect-families effect-facts build-log handled-table)
        covered-set (set covered)
        missing (vec (remove covered-set l6-required-effect-families))]
    {:required-families l6-required-effect-families
     :covered-families covered
     :missing-families missing
     :status (if (empty? missing) :complete :incomplete)}))

(defn effect-registry-snapshot
  []
  (->> effect-registry
       (map (fn [[effect entry]]
              (merge {:effect effect}
                     (select-keys entry [:family :kind :requires-capability
                                         :requires-build-grant :capability
                                         :nondeterministic :replay-record
                                         :profiles]))))
       (sort-by (comp str :effect))
       vec))

(defn mir-effect-annotation-records
  [effect-facts]
  (mapcat (fn [fact]
            (map (fn [effect]
                   {:core-node-id (:node-id fact)
                    :mir-effect-id (str "stage0-mir-effect-" (:node-id fact) "-" (name effect))
                    :effect effect
                    :source-kind (:source-kind fact)
                    :source-span (:source-span fact)
                    :preserved? true})
                 (:effects fact)))
          effect-facts))

(defn typed-source-artifact
  [source-path source-text]
  (let [core-artifact (core-source-artifact source-path source-text)
        module (:module core-artifact)
        checker (new-typed-checker)
        ctx (typed-context module)
        typed-roots (mapv #(check-typed-node checker ctx %)
                          (:expanded-core-ast core-artifact))
        checked @checker
        type-coverage (distinct-records (:type-category-coverage checked))
        type-facts (:type-facts checked)
        effect-facts (:effect-facts checked)
        build-log (distinct-records (:build-effect-log checked))
        handled-table (distinct-records (:handled-effect-table checked))
        mir-records (mir-type-preservation-records type-facts)
        module-effects (set/union (collect-fact-effects typed-roots)
                                  (set (mapcat :effects effect-facts)))
        module-capabilities (set/union (collect-fact-capabilities typed-roots)
                                       (set (mapcat :capabilities effect-facts)))
        handled-labels (set (map :effect-label handled-table))
        escaping-effects (set/difference module-effects handled-labels)
        mir-effect-records (vec (mir-effect-annotation-records effect-facts))
        source-forms (mapv :form (rest (:expanded-syntax-object-stream core-artifact)))
        protocol-table (protocol-table-from-forms source-forms)
        method-signatures (method-signature-records protocol-table)
        implementation-table (implementation-table-from-forms source-forms protocol-table)
        dispatch-records (distinct-records (:dispatch-mode-records checked))
        multimethods (multimethod-tables-from-forms source-forms)
        host-dispatch-records (distinct-records (:host-interop-dispatch-records checked))
        interface-artifacts (interface-lowering-artifacts implementation-table dispatch-records)]
    {:kind :gravity/stage0-typed-core-artifact
     :pass {:name :type-effect-capability-check
            :input :core-ast
            :output :typed-effected-core
            :requires [:reader :namespace-analyzer :macro-expansion :core-lowering]
            :preserves [:source-spans :generated-origin :profile :types :effects :capabilities]
