(defn distributed-ai-profile-source-artifact
  [source-path source-text]
  (try
    (let [manifest-artifact (profile-manifest-source-artifact source-path source-text)
          manifest (:profile-manifest manifest-artifact)
          profile (:profile manifest)
          document (distributed-ai-profile-documents-by-profile profile)
          _ (when-not document
              (fail! "P1-PROFILE-UNSUPPORTED"
                     "distributed/AI profile validation covers :distributed and :ai profiles"
                     {:source-span {:source source-path}
                      :profile profile
                      :supported distributed-ai-profile-order
                      :remediation "Use profile-validation for constrained profiles or profile-set for P2-P5."}))
          profile-validation (get-in manifest [:metadata :profile-validation] {})
          required-artifacts (require-distributed-ai-artifacts!
                              source-path profile document profile-validation)
          matrix {:profile profile
                  :document document
                  :effects {:source (:source-effects manifest)
                            :inferred (:inferred-effects manifest)
                            :effective (:effective-effects manifest)
                            :permission-table (:effect-permission-table
                                               manifest-artifact)}
                  :capabilities {:source (:source-capabilities manifest)
                                 :required (:required-capabilities manifest)
                                 :effective (:effective-capabilities manifest)
                                 :permission-table (:capability-permission-table
                                                    manifest-artifact)}
                  :memory (:memory-regime manifest)
                  :runtime (:runtime-assumptions manifest)}
          report (distributed-ai-profile-report profile document
                                                manifest-artifact matrix
                                                profile-validation
                                                required-artifacts)
          conformance (distributed-ai-profile-conformance-fixture
                       profile document matrix required-artifacts)]
      {:kind :gravity/stage0-distributed-ai-profile-artifact
       :document-set ["P9" "P10"]
       :pass {:name :distributed-ai-profile-validation
              :input :profile-manifest
              :output :cross-profile-boundary-graph
              :requires [:reader :namespace-analyzer :macro-expansion
                         :core-lowering :type-effect-capability-check
                         :profile-manifest-validation]
              :preserves [:source-spans :generated-origin :profile :target
                          :effects :capabilities :profile-validation-evidence
                          :replay-policy :human-review-policy]
              :emits [:profile-manifest :effect-capability-matrix
                      :profile-validation-report
                      :cross-profile-boundary-graph
                      :distributed-ai-conformance-fixture]
              :rejects distributed-ai-diagnostic-ids}
       :profile-manifest-artifact-hash (str "sha256:"
                                            (sha256-hex
                                             (pr-str manifest-artifact)))
       :profile-manifest manifest
       :profile-contract (:profile-contract manifest-artifact)
       :effect-capability-matrix matrix
       :profile-validation-report report
       :cross-profile-boundary-graph
       (:cross-profile-boundary-graph report)
       :distributed-ai-conformance-fixture conformance
       :diagnostics []})
    (catch clojure.lang.ExceptionInfo ex
      (throw-distributed-ai-diagnostic! ex))))

(def p13-diagnostic-ids
  ["P13-DIRECT" "P13-FACADE" "P13-ARTIFACT" "P13-EVIDENCE"
   "P13-RUNTIME" "P13-MEMORY" "P13-EFFECT" "P13-CAPABILITY"
   "P13-GENERATED" "P13-MATRIX"])

(def p13-artifact-boundary-kinds
  #{:schema :schema-file :proof-object :proof-artifact :hdl :hdl-module
    :firmware-image :kernel-module :workflow-graph :agent-manifest
    :native-object :generated-header :verified-lookup-table})

(def p13-default-facade-evidence
  #{:typed-api :safety-proof})

(defn p13-required-facade-evidence
  [consumer-profile producer-profile]
  (cond
    (and (contains? #{:firmware :kernel} consumer-profile)
         (= :native producer-profile))
    #{:typed-api :safety-proof :no-gc :no-hidden-allocation :no-throw}

    (and (= :distributed consumer-profile)
         (contains? #{:hosted :native} producer-profile))
    #{:schema :durable-step :capability-proof}

    (= :ai consumer-profile)
    #{:tool-schema :capability-proof :human-review-policy}

    (and (= :gpu consumer-profile)
         (= :native producer-profile))
    #{:transfer-boundary :capability-proof :device-memory-proof}

    (= :formal consumer-profile)
    #{:proof-certificate :safety-proof}

    :else
    p13-default-facade-evidence))

(defn p13-source-context
  [source-path source-text]
  (let [records (read-source-form-records source-path source-text)
        forms (mapv :form records)
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        dependencies (vec (concat (:requires module) (:imports module)))]
    {:records records
     :forms forms
     :module module
     :dependencies dependencies
     :metadata (:metadata module)}))

(defn p13-fail!
  [id source-path module dependency extra]
  (fail! id
         (case id
           "P13-DIRECT" "illegal direct cross-profile source import"
           "P13-FACADE" "cross-profile facade metadata is missing or invalid"
           "P13-ARTIFACT" "artifact-only edge is being imported as source"
           "P13-EVIDENCE" "cross-profile edge is missing required evidence"
           "P13-RUNTIME" "producer runtime assumptions are unsupported"
           "P13-MEMORY" "producer memory assumptions are incompatible"
           "P13-EFFECT" "producer effects exceed consumer profile policy"
           "P13-CAPABILITY" "producer capabilities exceed consumer grants"
           "P13-GENERATED" "macro-generated cross-profile edge is illegal"
           "P13-MATRIX" "package-declared edge contradicts the profile matrix"
           "profile compatibility diagnostic")
         (merge {:source-span {:source source-path}
                 :document-id "P13"
                 :consumer-namespace (:module module)
                 :consumer-profile (:profile module)
                 :producer-namespace (:module dependency)
                 :producer-profile (:profile dependency)
                 :edge-kind (or (:edge dependency) :direct)
                 :boundary (:boundary dependency)
                 :generated-origin-chain (when (:generated? dependency)
                                           [:macro-generated-edge])
                 :suggested-boundary
                 (or (:suggested-boundary extra)
                     :profile-safe-facade-or-artifact-boundary)
                 :remediation
                 "Declare a legal direct edge, complete facade evidence, or an artifact-only boundary before lowering."}
                extra)))

(defn p13-unsupported-runtime
  [consumer-profile runtime]
  (let [providers (set (:providers runtime))
        consumer-providers (get-in (profile-contract consumer-profile)
                                   [:runtime :providers])]
    (when (:required runtime)
      (seq (set/difference providers consumer-providers)))))

(defn p13-memory-compatible?
  [consumer-profile memory]
  (let [consumer-hidden (get-in (profile-contract consumer-profile)
                                [:memory :hidden-allocation])
        producer-hidden (:hidden-allocation memory)]
    (or (nil? producer-hidden)
        (not= :forbidden consumer-hidden)
        (= :forbidden producer-hidden))))

(defn p13-effect-denials
  [consumer-profile effects]
  (seq (set/difference (set effects)
                       (profile-allowed-effects consumer-profile))))

(defn p13-capability-denials
  [consumer-profile capabilities]
  (seq (set/difference (set capabilities)
                       (profile-capabilities consumer-profile))))

(defn p13-facade-record
  [module dependency]
  (let [consumer (:profile module)
        producer (:profile dependency)]
    {:consumer {:namespace (:module module)
                :profile consumer}
     :producer {:namespace (:module dependency)
                :profile producer}
     :edge :facade-required
     :boundary (:boundary dependency)
     :facade (:facade dependency)
     :evidence (:evidence dependency)
     :effects (:producer-effects dependency)
     :capabilities (:producer-capabilities dependency)
     :memory (:memory dependency)
     :runtime (:runtime dependency)
     :provider (:provider dependency)
     :status :accepted}))

(defn p13-direct-record
  [module dependency]
  {:consumer {:namespace (:module module)
              :profile (:profile module)}
   :producer {:namespace (:module dependency)
              :profile (:profile dependency)}
   :edge :direct
   :boundary (:boundary dependency)
   :facade nil
   :evidence #{}
   :status :accepted})

(defn p13-validate-facade!
  [source-path module dependency]
  (let [consumer (:profile module)
        producer (:profile dependency)
        evidence (set (:evidence dependency))
        required-evidence (p13-required-facade-evidence consumer producer)
        missing-evidence (set/difference required-evidence evidence)
        unsupported-runtime (p13-unsupported-runtime consumer
                                                     (:runtime dependency))
        effect-denials (p13-effect-denials consumer
                                           (:producer-effects dependency))
        capability-denials (p13-capability-denials
                            consumer
                            (:producer-capabilities dependency))]
    (when-not (and (:facade dependency)
                   (= :facade (:boundary dependency)))
      (p13-fail! "P13-FACADE" source-path module dependency
                 {:missing-fact :facade
                  :suggested-boundary :facade-required}))
    (when (seq missing-evidence)
      (p13-fail! "P13-EVIDENCE" source-path module dependency
                 {:missing-evidence missing-evidence
                  :required-evidence required-evidence
                  :suggested-boundary :facade-required}))
    (when (seq unsupported-runtime)
      (p13-fail! "P13-RUNTIME" source-path module dependency
                 {:unsupported-runtime-providers unsupported-runtime
                  :runtime (:runtime dependency)
                  :suggested-boundary :runtime-isolating-facade}))
    (when-not (p13-memory-compatible? consumer (:memory dependency))
      (p13-fail! "P13-MEMORY" source-path module dependency
                 {:memory (:memory dependency)
                  :consumer-memory (get-in (profile-contract consumer)
                                           [:memory])
                  :suggested-boundary :memory-safe-facade}))
    (when (seq effect-denials)
      (p13-fail! "P13-EFFECT" source-path module dependency
                 {:denied-effects effect-denials
                  :suggested-boundary :effect-narrowing-facade}))
    (when (seq capability-denials)
      (p13-fail! "P13-CAPABILITY" source-path module dependency
                 {:denied-capabilities capability-denials
                  :suggested-boundary :capability-narrowing-facade}))
    (p13-facade-record module dependency)))

(defn p13-validate-dependency!
  [source-path module dependency]
  (let [consumer (:profile module)
        producer (:profile dependency)
        edge (or (:edge dependency)
                 (cond
                   (profile-direct-import-allowed? consumer producer) :direct
                   (contains? p13-artifact-boundary-kinds
                              (:boundary dependency)) :artifact-only
                   (:boundary dependency) :facade-required
                   :else :direct))]
    (when producer
      (cond
        (and (= :direct edge)
             (not (profile-direct-import-allowed? consumer producer))
             (:boundary dependency))
        (p13-fail! "P13-MATRIX" source-path module dependency
                   {:declared-edge edge
                    :standard-direct-imports (get profile-direct-imports
                                                  consumer)
                    :suggested-boundary :facade-required})

        (and (:generated? dependency)
             (not (profile-direct-import-allowed? consumer producer))
             (nil? (:boundary dependency)))
        (p13-fail! "P13-GENERATED" source-path module dependency
                   {:declared-edge edge
                    :missing-fact :generated-profile-boundary
                    :suggested-boundary :generated-facade-or-artifact})

        (profile-direct-import-allowed? consumer producer)
        (p13-direct-record module dependency)

        (nil? (:boundary dependency))
        (p13-fail! "P13-DIRECT" source-path module dependency
                   {:declared-edge edge
                    :standard-direct-imports (get profile-direct-imports
                                                  consumer)
                    :suggested-boundary :facade-required})

        (= :artifact-only edge)
        (p13-fail! "P13-ARTIFACT" source-path module dependency
                   {:declared-edge edge
                    :artifact (:artifact dependency)
                    :artifact-schema (:artifact-schema dependency)
                    :suggested-boundary :artifact-manifest})

        :else
        (p13-validate-facade! source-path module dependency)))))

(defn p13-artifact-record
  [source-path module artifact]
  (let [consumer (:profile module)
        producer (:producer-profile artifact)
        effect-denials (p13-effect-denials consumer (:effects artifact))
        capability-denials (p13-capability-denials consumer
                                                   (:capabilities artifact))]
    (when-not (contains? p13-artifact-boundary-kinds
                         (:artifact-kind artifact))
      (p13-fail! "P13-ARTIFACT" source-path module
                 {:module (:producer-namespace artifact)
                  :profile producer
                  :edge :artifact-only
                  :boundary (:artifact-kind artifact)}
                 {:artifact (:artifact artifact)
                  :artifact-kind (:artifact-kind artifact)
                  :suggested-boundary :declared-artifact-boundary}))
    (when (empty? (:evidence artifact))
      (p13-fail! "P13-EVIDENCE" source-path module
                 {:module (:producer-namespace artifact)
                  :profile producer
                  :edge :artifact-only
                  :boundary (:artifact-kind artifact)}
                 {:missing-evidence #{:schema :provenance}
                  :suggested-boundary :declared-artifact-boundary}))
    (when (seq effect-denials)
      (p13-fail! "P13-EFFECT" source-path module
                 {:module (:producer-namespace artifact)
                  :profile producer
                  :edge :artifact-only
                  :boundary (:artifact-kind artifact)}
                 {:denied-effects effect-denials
                  :suggested-boundary :effect-free-artifact}))
    (when (seq capability-denials)
      (p13-fail! "P13-CAPABILITY" source-path module
                 {:module (:producer-namespace artifact)
                  :profile producer
                  :edge :artifact-only
                  :boundary (:artifact-kind artifact)}
                 {:denied-capabilities capability-denials
                  :suggested-boundary :capability-free-artifact}))
    {:consumer {:namespace (:module module)
                :profile consumer}
     :producer {:namespace (:producer-namespace artifact)
                :profile producer}
     :edge :artifact-only
     :artifact (:artifact artifact)
     :artifact-kind (:artifact-kind artifact)
     :artifact-schema (:artifact-schema artifact)
     :evidence (:evidence artifact)
     :status :accepted}))

(defn p13-artifact-boundaries
  [module]
  (vec (get-in module [:metadata :profile-compatibility
                       :artifact-boundaries] [])))

(defn p13-standard-library-facades
  [module]
  (vec (get-in module [:metadata :profile-compatibility
                       :standard-library-facades] [])))

(defn p13-capability-proof
  [dependency-records artifact-records]
  {:dependency-edges (count dependency-records)
   :artifact-edges (count artifact-records)
   :effect-authority-preserved?
   (every? #(empty? (:effects %)) dependency-records)
   :capability-authority-preserved?
   (every? #(empty? (:capabilities %)) dependency-records)
   :artifact-authority-preserved?
   (every? #(and (empty? (:effects %))
                 (empty? (:capabilities %)))
           artifact-records)
   :status :complete})

(defn p13-conformance-results
  [dependency-records artifact-records standard-library-facades]
  (let [edge-kinds (set (concat (map :edge dependency-records)
                                (map :edge artifact-records)))
        required #{:direct :facade-required :artifact-only}
        missing (set/difference required edge-kinds)]
    {:document "P13"
     :required-edge-kinds required
     :covered-edge-kinds edge-kinds
     :missing-edge-kinds missing
     :diagnostic-ids p13-diagnostic-ids
     :dependency-graph-status :complete
     :standard-library-facades standard-library-facades
     :standard-library-facade-status (if (seq standard-library-facades)
                                       :complete
                                       :not-present)
     :status (if (empty? missing) :complete :incomplete)}))

(defn p13-compatibility-matrix
  []
  (mapv (fn [profile]
          {:consumer profile
           :direct-imports (get profile-direct-imports profile)
           :facade-required :matrix-specific
           :artifact-only :richer-profile-artifacts})
        standard-profile-order))

(defn profile-compatibility-source-artifact
  [source-path source-text]
  (let [{:keys [module dependencies]} (p13-source-context source-path source-text)
        dependency-records (vec (keep #(p13-validate-dependency!
                                        source-path module %)
                                      dependencies))
        artifact-records (mapv #(p13-artifact-record source-path module %)
                               (p13-artifact-boundaries module))
        standard-library-facades (p13-standard-library-facades module)
        manifest-artifact (profile-manifest-source-artifact source-path
                                                            source-text)
        conformance (p13-conformance-results dependency-records
                                             artifact-records
                                             standard-library-facades)
        graph {:consumer {:namespace (:module module)
                          :profile (:profile module)}
               :edges (vec (concat dependency-records artifact-records))
               :status :complete}]
    {:kind :gravity/stage0-profile-compatibility-artifact
     :document "P13"
     :pass {:name :profile-compatibility-validation
            :input :profile-manifest
            :output :cross-profile-dependency-graph
            :requires [:reader :namespace-analyzer :macro-expansion
                       :core-lowering :type-effect-capability-check
                       :profile-manifest-validation]
            :preserves [:source-spans :generated-origin :profile :target
                        :effects :capabilities :facade-evidence
                        :artifact-boundaries]
            :emits [:profile-compatibility-matrix
                    :cross-profile-dependency-graph :facade-manifest
                    :artifact-boundary-manifest :evidence-records
                    :compatibility-conformance-results]
            :rejects p13-diagnostic-ids}
     :profile-manifest-artifact-hash (str "sha256:"
                                          (sha256-hex
                                           (pr-str manifest-artifact)))
     :profile-manifest (:profile-manifest manifest-artifact)
     :profile-compatibility-matrix (p13-compatibility-matrix)
     :cross-profile-dependency-graph graph
     :facade-manifest (filterv #(= :facade-required (:edge %))
                               dependency-records)
     :artifact-boundary-manifest artifact-records
     :evidence-records (mapv #(select-keys % [:producer :edge :evidence
                                              :facade :artifact :status])
                             (concat dependency-records artifact-records))
     :capability-based-proof (p13-capability-proof dependency-records
                                                   artifact-records)
     :compatibility-conformance-results conformance
     :diagnostics []}))

