(def perf1-required-claim-fields
  [:claim-id :profile :target :target-features :input-shape :layout
   :safety-mode :benchmark])

(defn perf-present?
  [value]
  (and (some? value)
       (not (and (coll? value) (empty? value)))))

(defn perf1-normalize-claim
  [claim]
  (let [claim-id (or (:claim-id claim) (:claim claim))
        input-shape (or (:input-shape claim) (:input-domain claim))]
    (assoc claim
           :claim-id claim-id
           :input-shape input-shape)))

(defn perf1-missing-claim-fields
  [claim]
  (vec (remove #(perf-present? (get claim %))
               perf1-required-claim-fields)))

(defn perf1-fail!
  [id source-path manifest claim extra]
  (fail! id
         (case id
           "PERF1-CLAIM" "performance claim is incomplete"
           "PERF1-EVIDENCE" "performance claim is missing required evidence"
           "PERF1-SAFETY" "optimization loses required safety evidence"
           "PERF1-PROFILE" "optimization introduces profile-illegal behavior"
           "PERF1-EFFECT" "optimization hides or expands effects"
           "PERF1-CAPABILITY" "optimization hides or expands capability authority"
           "PERF1-NUMERIC" "optimization changes numeric mode without evidence"
           "PERF1-TARGET" "performance claim lacks target feature or fingerprint evidence"
           "PERF1-VARIANT" "generated variant lacks guard predicate evidence"
           "performance claim is invalid")
         (merge {:source-span {:source source-path}
                 :profile (:profile manifest)
                 :target (:target manifest)
                 :claim-id (:claim-id claim)
                 :target-request (:target claim)
                 :diagnostic-family :performance-claim-validation}
                extra)))

(defn perf1-target-fingerprint
  [claim]
  (or (get-in claim [:benchmark :target-fingerprint])
      (get-in claim [:benchmark :environment-fingerprint])))

(defn perf1-validate-claim!
  [source-path manifest performance claim]
  (let [missing-fields (perf1-missing-claim-fields claim)
        target-features (set (:target-features claim))
        target-fingerprint (perf1-target-fingerprint claim)
        semantic-proof (set (:semantic-proof claim))
        safety-proof (set (:safety-proof claim))
        artifacts (set (:artifacts claim))
        lost-safety-facts (set (:lost-safety-facts performance))
        expanded-effects (set (:expanded-effects performance))
        expanded-capabilities (set (:expanded-capabilities performance))
        numeric-change (:numeric-mode-change performance)
        variants (vec (:generated-variants performance))]
    (when (seq missing-fields)
      (perf1-fail! "PERF1-CLAIM" source-path manifest claim
                   {:missing-fields missing-fields
                    :remediation "Record profile, target, feature, input, layout, safety, and benchmark fields in the performance claim."}))
    (when-not (= (:profile manifest) (:profile claim))
      (perf1-fail! "PERF1-PROFILE" source-path manifest claim
                   {:active-profile (:profile manifest)
                    :requested-profile (:profile claim)
                    :remediation "The performance claim profile must match the already validated source profile."}))
    (when (or (empty? target-features)
              (not (perf-present? target-fingerprint)))
      (perf1-fail! "PERF1-TARGET" source-path manifest claim
                   {:target-features target-features
                    :target-fingerprint target-fingerprint
                    :remediation "Record target features and benchmark target fingerprint evidence."}))
    (when (or (empty? semantic-proof)
              (empty? safety-proof)
              (not (contains? artifacts :optimized-mir))
              (not (contains? artifacts :proof-index))
              (not (contains? artifacts :benchmark-report)))
      (perf1-fail! "PERF1-EVIDENCE" source-path manifest claim
                   {:missing-evidence
                    (cond-> #{}
                      (empty? semantic-proof) (conj :semantic-proof)
                      (empty? safety-proof) (conj :safety-proof)
                      (not (contains? artifacts :optimized-mir))
                      (conj :optimized-mir)
                      (not (contains? artifacts :proof-index))
                      (conj :proof-index)
                      (not (contains? artifacts :benchmark-report))
                      (conj :benchmark-report))
                    :remediation "Attach semantic proof, safety proof, optimized MIR, proof index, and benchmark report evidence."}))
    (when (seq lost-safety-facts)
      (perf1-fail! "PERF1-SAFETY" source-path manifest claim
                   {:lost-safety-facts lost-safety-facts
                    :remediation "Preserve, regenerate, or retain runtime checks for every safety fact."}))
    (when (seq expanded-effects)
      (perf1-fail! "PERF1-EFFECT" source-path manifest claim
                   {:expanded-effects expanded-effects
                    :declared-effects (:source-effects manifest)
                    :remediation "Optimization must not hide or expand effects outside the validated manifest."}))
    (when (seq expanded-capabilities)
      (perf1-fail! "PERF1-CAPABILITY" source-path manifest claim
                   {:expanded-capabilities expanded-capabilities
                    :declared-capabilities (:source-capabilities manifest)
                    :remediation "Optimization must not hide or expand authority outside the validated manifest."}))
    (when (and (:source-mode numeric-change)
               (:optimized-mode numeric-change)
               (not= (:source-mode numeric-change)
                     (:optimized-mode numeric-change))
               (not (perf-present? (:certificate numeric-change))))
      (perf1-fail! "PERF1-NUMERIC" source-path manifest claim
                   {:source-numeric-mode (:source-mode numeric-change)
                    :optimized-numeric-mode (:optimized-mode numeric-change)
                    :certificate-id (:certificate numeric-change)
                    :remediation "Attach an explicit math or numeric certificate for mode changes."}))
    (when-let [bad-variant (first (filter #(not (perf-present?
                                                 (:guard-predicate %)))
                                          variants))]
      (perf1-fail! "PERF1-VARIANT" source-path manifest claim
                   {:generated-variant (:variant-id bad-variant)
                    :missing-fact :guard-predicate
                    :remediation "Generated fast paths and variants require guard predicates and compatibility evidence."}))
    :complete))

(defn performance-capability-proof
  [manifest claim performance]
  {:profile-legality-preserved? (= (:profile manifest) (:profile claim))
   :effect-authority-preserved? (empty? (:expanded-effects performance))
   :capability-authority-preserved?
   (empty? (:expanded-capabilities performance))
   :safety-evidence-preserved? (empty? (:lost-safety-facts performance))
   :target-fingerprint-recorded? (perf-present? (perf1-target-fingerprint
                                                 claim))
   :benchmark-not-used-for-safety-elision? true
   :status :complete})

(defn performance-source-artifact
  [source-path source-text]
  (let [manifest-artifact (profile-manifest-source-artifact source-path
                                                            source-text)
        manifest (:profile-manifest manifest-artifact)
        performance (get-in manifest [:metadata :performance] {})
        claim (perf1-normalize-claim (:claim performance))
        _ (perf1-validate-claim! source-path manifest performance claim)
        target-fingerprint (perf1-target-fingerprint claim)
        optimization-decisions (vec (:optimization-decisions performance))
        generated-variants (vec (:generated-variants performance))
        proof-index {:semantic-proof (:semantic-proof claim)
                     :safety-proof (:safety-proof claim)
                     :proof-artifacts (:artifacts claim)}
        conformance {:document "PERF1"
                     :task "P04-T01"
                     :required-diagnostic-ids perf1-diagnostic-ids
                     :claim-schema-status :complete
                     :target-fingerprint-status :complete
                     :proof-index-status :complete
                     :status :complete}]
    {:kind :gravity/stage0-performance-claim-artifact
     :document "PERF1"
     :pass {:name :performance-claim-validation
            :input :profile-manifest
            :output :optimization-manifest
            :requires [:reader :namespace-analyzer :macro-expansion
                       :core-lowering :type-effect-capability-check
                       :profile-manifest-validation]
            :preserves [:source-spans :profile :target :effects
                        :capabilities :safety-mode :profile-legality
                        :proof-index]
            :emits [:performance-contract-manifest
                    :optimization-decision-log
                    :target-feature-report
                    :layout-input-shape-record
                    :benchmark-report
                    :proof-index
                    :generated-variant-manifest
                    :performance-conformance-results]
            :rejects perf1-diagnostic-ids}
     :profile-manifest-artifact-hash (str "sha256:"
                                          (sha256-hex
                                           (pr-str manifest-artifact)))
     :profile-manifest manifest
     :performance-contract-manifest
     {:claim-id (:claim-id claim)
      :profile (:profile claim)
      :source-profile (:profile manifest)
      :stage0-source-target (:target manifest)
      :target-request (:target claim)
      :target-features (:target-features claim)
      :safety-mode (:safety-mode claim)
      :objective (:objective claim)
      :status :complete}
     :optimization-decision-log optimization-decisions
     :target-feature-report {:target (:target claim)
                             :features (:target-features claim)
                             :fingerprint target-fingerprint
                             :status :complete}
     :layout-input-shape-record {:input-shape (:input-shape claim)
                                 :layout (:layout claim)
                                 :status :complete}
     :benchmark-report (:benchmark claim)
     :proof-index proof-index
     :generated-variant-manifest generated-variants
     :capability-based-proof (performance-capability-proof manifest claim
                                                           performance)
     :performance-conformance-results conformance
     :diagnostics []}))

(def perf2-required-claim-fields
  [:claim-id :profile :target :abstraction :equivalent-form
   :expected-erased-costs :erased-costs :residual-costs
   :semantic-proof :safety-proof :proof-ids :artifacts
   :source-operation :before-ir :after-ir])

(def perf2-required-nonempty-claim-fields
  #{:claim-id :profile :target :abstraction :equivalent-form
    :expected-erased-costs :semantic-proof :safety-proof :proof-ids
    :artifacts :source-operation :before-ir :after-ir})

(def perf2-required-artifacts
  #{:before-mir :after-mir})

(def perf2-abstraction-families
  #{:protocol-dispatch :interface-call :generic-function :record-field-access
    :newtype-wrapper :wrapper-value :iterator-pipeline
    :collection-view :pattern-match :macro :facet-generated-form
    :higher-order-function :error-result-wrapper :resource-wrapper
    :numeric-mode-wrapper :standard-library-wrapper})

(def perf2-cost-diagnostic
  {:allocation "PERF2-ALLOCATION"
   :hidden-allocation "PERF2-ALLOCATION"
   :boxing "PERF2-BOXING"
   :unboxing "PERF2-BOXING"
   :representation-conversion "PERF2-BOXING"
   :dynamic-dispatch "PERF2-DISPATCH"
   :vtable-lookup "PERF2-DISPATCH"
   :reflection "PERF2-REFLECTION"
   :host-reflection "PERF2-REFLECTION"
   :runtime-bounds-check "PERF2-CHECK"
   :runtime-type-check "PERF2-CHECK"
   :runtime-check "PERF2-CHECK"})

(defn perf2-normalize-claim
  [claim]
  (assoc claim
         :claim-id (or (:claim-id claim) (:claim claim))
         :expected-erased-costs
         (or (:expected-erased-costs claim) (:erased-costs claim) #{})
         :residual-costs (or (:residual-costs claim) #{})))

(defn perf2-missing-claim-fields
  [claim]
  (vec (remove #(if (contains? perf2-required-nonempty-claim-fields %)
                  (perf-present? (get claim %))
                  (contains? claim %))
               perf2-required-claim-fields)))

(defn perf2-fail!
  [id source-path manifest performance-claim claim extra]
  (fail! id
         (case id
           "PERF2-CLAIM" "zero-cost abstraction claim is incomplete"
           "PERF2-RESIDUAL" "residual work contradicts zero-cost claim"
           "PERF2-ALLOCATION" "zero-cost claim hides allocation"
           "PERF2-BOXING" "zero-cost claim hides boxing or representation conversion"
           "PERF2-DISPATCH" "zero-cost claim leaves dynamic dispatch unerased"
           "PERF2-REFLECTION" "zero-cost claim hides host reflection"
           "PERF2-CHECK" "zero-cost claim leaves runtime checks unaccounted"
           "PERF2-PROFILE" "zero-cost erasure relies on profile-illegal behavior"
           "PERF2-EVIDENCE" "zero-cost claim is missing IR or proof evidence"
           "zero-cost abstraction claim is invalid")
         (merge {:source-span {:source source-path}
                 :profile (:profile manifest)
                 :target (:target manifest)
                 :target-request (:target performance-claim)
                 :claim-id (:claim-id claim)
                 :abstraction (:abstraction claim)
                 :equivalent-form (:equivalent-form claim)
                 :expected-erased-costs (:expected-erased-costs claim)
                 :residual-costs (:residual-costs claim)
                 :ir-artifacts (:artifacts claim)
                 :diagnostic-family :zero-cost-abstraction-validation}
                extra)))

(defn perf2-ir-artifact-id
  [claim key]
  (or (get-in claim [key :artifact-id])
      (get-in claim [key :id])))

(defn perf2-costs-in-ir
  [claim ir-key]
  (set (concat (get-in claim [ir-key :costs])
               (mapcat :costs (get-in claim [ir-key :operations])))))

(defn perf2-hidden-costs
  [claim]
  (set/union (set (:residual-costs claim))
             (perf2-costs-in-ir claim :after-ir)
             (set (get-in claim [:allocation-audit :hidden-allocations]))
             (set (get-in claim [:boxing-audit :hidden-boxing]))
             (set (get-in claim [:dispatch-specialization-report
                                  :residual-dispatch]))
             (set (get-in claim [:reflection-audit :hidden-reflection]))
             (set (get-in claim [:runtime-check-report
                                  :unaccounted-checks]))))

(defn perf2-missing-evidence
  [claim]
  (let [artifacts (set (:artifacts claim))]
    (cond-> #{}
      (empty? (:semantic-proof claim)) (conj :semantic-proof)
      (empty? (:safety-proof claim)) (conj :safety-proof)
      (empty? (:proof-ids claim)) (conj :proof-ids)
      (not (perf-present? (perf2-ir-artifact-id claim :before-ir)))
      (conj :before-ir)
      (not (perf-present? (perf2-ir-artifact-id claim :after-ir)))
      (conj :after-ir)
      (not (set/subset? perf2-required-artifacts artifacts))
      (conj :before-after-mir-artifacts))))

(defn perf2-validate-claim!
  [source-path manifest performance-claim claim]
  (let [missing-fields (perf2-missing-claim-fields claim)
        artifacts (set (:artifacts claim))
        expected-erased-costs (set (:expected-erased-costs claim))
        erased-costs (set (:erased-costs claim))
        residual-costs (set (:residual-costs claim))
        unerased-expected-costs (set/difference expected-erased-costs
                                                erased-costs)
        hidden-costs (set/union (perf2-hidden-costs claim)
                                unerased-expected-costs)
        profile-illegal (set (:profile-illegal-behavior claim))
        missing-evidence (perf2-missing-evidence claim)]
    (when (seq missing-fields)
      (perf2-fail! "PERF2-CLAIM" source-path manifest performance-claim claim
                   {:missing-fields missing-fields
                    :remediation "Record abstraction kind, equivalent form, erased/residual costs, before/after IR, proof ids, and proof artifacts."}))
    (when (or (not= (:profile manifest) (:profile claim))
              (not= (:profile performance-claim) (:profile claim))
              (not= (:target performance-claim) (:target claim))
              (not (contains? perf2-abstraction-families
                              (:abstraction claim)))
              (seq profile-illegal))
      (perf2-fail! "PERF2-PROFILE" source-path manifest performance-claim claim
                   {:active-profile (:profile manifest)
                    :performance-profile (:profile performance-claim)
                    :target-request (:target performance-claim)
                    :profile-illegal-behavior profile-illegal
                    :remediation "Zero-cost erasure must use a legal abstraction family under the already validated profile and target request."}))
    (when (or (seq missing-evidence)
              (not (contains? artifacts :dispatch-report))
              (nil? (:allocation-audit claim))
              (nil? (:boxing-audit claim))
              (nil? (:runtime-check-report claim)))
      (perf2-fail! "PERF2-EVIDENCE" source-path manifest performance-claim claim
                   {:missing-evidence
                    (cond-> missing-evidence
                      (not (contains? artifacts :dispatch-report))
                      (conj :dispatch-report)
                      (nil? (:allocation-audit claim))
                      (conj :allocation-audit)
                      (nil? (:boxing-audit claim))
                      (conj :boxing-audit)
                      (nil? (:runtime-check-report claim))
                      (conj :runtime-check-report))
                    :remediation "Attach before/after MIR, dispatch report, allocation and boxing audits, runtime-check report, and proof artifacts."}))
    (when-let [[cost id] (first (keep (fn [cost]
                                        (when-let [id (perf2-cost-diagnostic
                                                       cost)]
                                          [cost id]))
                                      hidden-costs))]
      (perf2-fail! id source-path manifest performance-claim claim
                   {:residual-cost cost
                    :remediation "Report the residual cost instead of accepting the zero-cost claim, or prove that the equivalent lower-level form has the same cost."}))
    (when (seq (set/union residual-costs unerased-expected-costs))
      (perf2-fail! "PERF2-RESIDUAL" source-path manifest performance-claim claim
                   {:residual-costs (set/union residual-costs
                                               unerased-expected-costs)
                    :remediation "A zero-cost claim must have an empty residual-cost set; non-erased work belongs in a performance report."}))
    :complete))

(defn zero-cost-capability-proof
  [manifest performance-claim claims]
  {:profile-legality-preserved? (every? #(= (:profile manifest)
                                            (:profile %))
                                        claims)
   :target-request-preserved? (every? #(= (:target performance-claim)
                                          (:target %))
                                      claims)
   :effect-authority-preserved?
   (every? #(= (set (get-in % [:effect-proof :source-effects]))
               (set (get-in % [:effect-proof :optimized-effects])))
           claims)
   :capability-authority-preserved?
   (every? #(= (set (get-in % [:capability-proof
                               :source-capabilities]))
               (set (get-in % [:capability-proof
                               :optimized-capabilities])))
           claims)
   :safety-evidence-preserved? (every? #(seq (:safety-proof %)) claims)
   :before-after-ir-recorded?
   (every? #(and (perf-present? (perf2-ir-artifact-id % :before-ir))
                 (perf-present? (perf2-ir-artifact-id % :after-ir)))
           claims)
   :residual-costs-empty? (every? #(empty? (:residual-costs %)) claims)
   :status :complete})

(defn zero-cost-source-artifact
  [source-path source-text]
  (let [performance-artifact (performance-source-artifact source-path
                                                          source-text)
        manifest (:profile-manifest performance-artifact)
        performance (get-in manifest [:metadata :performance] {})
        performance-claim (perf1-normalize-claim (:claim performance))
        suite (:zero-cost performance)
        claims (mapv perf2-normalize-claim (:claims suite))]
    (when (empty? claims)
      (perf2-fail! "PERF2-CLAIM" source-path manifest performance-claim
                   {:claim-id (:suite-id suite)
                    :profile (:profile manifest)
                    :target (:target performance-claim)
                    :abstraction nil
                    :equivalent-form nil
                    :expected-erased-costs #{}
                    :erased-costs #{}
                    :residual-costs #{}
                    :artifacts #{}}
                   {:missing-fields [:claims]
                    :remediation "Provide at least one zero-cost abstraction erasure claim."}))
    (doseq [claim claims]
      (perf2-validate-claim! source-path manifest performance-claim claim))
    (let [capability-proof (zero-cost-capability-proof manifest
                                                       performance-claim
                                                       claims)
          conformance {:document "PERF2"
                       :task "P04-T02"
                       :required-diagnostic-ids perf2-diagnostic-ids
                       :abstraction-families-covered
                       (set (map :abstraction claims))
                       :before-after-ir-status :complete
                       :residual-cost-reporting-status :complete
                       :allocation-boxing-audit-status :complete
                       :dispatch-specialization-status :complete
                       :runtime-check-proof-status :complete
                       :status :complete}]
      {:kind :gravity/stage0-zero-cost-abstraction-artifact
       :document "PERF2"
       :pass {:name :zero-cost-abstraction-validation
              :input :optimization-manifest
              :output :abstraction-erasure-report
              :requires [:performance-claim-validation
                         :typed-core-facts
                         :effect-capability-facts
                         :dispatch-artifacts
                         :compile-time-provenance
                         :safe15-proof-records
                         :before-after-mir]
              :preserves [:source-spans :profile :target :effects
                          :capabilities :safety-mode :profile-legality
                          :proof-index :dispatch-diagnostics]
              :emits [:abstraction-erasure-report
                      :before-after-ir-records
                      :residual-cost-list
                      :allocation-boxing-audit
                      :dispatch-specialization-report
                      :runtime-check-erasure-report
                      :zero-cost-conformance-results]
              :rejects perf2-diagnostic-ids}
       :performance-artifact-hash (str "sha256:"
                                       (sha256-hex
                                        (pr-str performance-artifact)))
       :performance-contract-manifest
       (:performance-contract-manifest performance-artifact)
       :abstraction-erasure-report
       {:suite-id (:suite-id suite)
        :claim-count (count claims)
        :claims (mapv #(select-keys %
                                    [:claim-id :abstraction :equivalent-form
                                     :expected-erased-costs :erased-costs
                                     :residual-costs :semantic-proof
                                     :safety-proof :proof-ids :status])
                      claims)
        :status :complete}
       :before-after-ir-records
       (mapv #(select-keys % [:claim-id :source-operation
                              :before-ir :after-ir])
             claims)
       :residual-cost-list
       (mapv #(select-keys % [:claim-id :residual-costs])
             claims)
       :allocation-boxing-audit
       (mapv #(select-keys % [:claim-id :allocation-audit
                              :boxing-audit])
             claims)
       :dispatch-specialization-report
       (mapv #(select-keys % [:claim-id
                              :dispatch-specialization-report])
             claims)
       :runtime-check-erasure-report
       (mapv #(select-keys % [:claim-id :runtime-check-report])
             claims)
       :capability-based-proof capability-proof
       :zero-cost-conformance-results conformance
       :diagnostics []})))

(def perf3-required-record-fields
  [:record-id :optimization :source-function :profile :target :behavior-facts
   :key :guard :effects :capabilities :semantic-proof :safety-proof
   :artifacts :source-map :cache-key-inputs :invalidation-inputs
   :variant-id :variant-selection])

(def perf3-required-nonempty-record-fields
  #{:record-id :optimization :source-function :profile :target :behavior-facts
    :key :semantic-proof :safety-proof :artifacts
    :cache-key-inputs :invalidation-inputs :variant-id})

(def perf3-required-artifacts
  #{:specialized-mir :guard-table :source-map})

(defn perf3-normalize-record
  [record]
  (assoc record
         :record-id (or (:record-id record) (:id record))
         :source-function (or (:source-function record) (:source record))
         :variant-id (or (:variant-id record)
                         (get-in record [:variant-selection :variant-id]))))

(defn perf3-missing-record-fields
  [record]
  (vec (remove #(if (contains? perf3-required-nonempty-record-fields %)
                  (perf-present? (get record %))
                  (contains? record %))
               perf3-required-record-fields)))

(defn perf3-fail!
  [id source-path manifest performance-claim record extra]
  (fail! id
         (case id
           "PERF3-KEY" "specialization key omits behavior-affecting facts"
           "PERF3-GUARD" "specialized variant lacks a valid guard predicate"
           "PERF3-EFFECT" "partial evaluation uses undeclared build effects"
           "PERF3-HERMETIC" "partial evaluation is not hermetic or replayable"
           "PERF3-SOURCE-MAP" "specialized artifact lacks source map"
           "PERF3-CACHE" "specialization cache omits invalidation inputs"
           "PERF3-PROFILE" "specialized variant is illegal in the active profile"
           "PERF3-PROOF" "specialization erased checks without specialized proof"
           "PERF3-VARIANT" "variant selection is ambiguous or unsafe"
           "specialization record is invalid")
         (merge {:source-span {:source source-path}
                 :profile (:profile manifest)
                 :target (:target manifest)
                 :target-request (:target performance-claim)
                 :source-function (:source-function record)
                 :specialization-key (:key record)
                 :guard (:guard record)
                 :build-effects (get-in record [:partial-evaluation
                                                :build-effects])
                 :variant-id (:variant-id record)
                 :proof-id (:proof-id record)
                 :diagnostic-family :specialization-validation}
                extra)))

(defn perf3-missing-key-inputs
  [record]
  (let [key-map (:key record)]
    (vec (remove #(contains? key-map %)
                 (:behavior-facts record)))))

(defn perf3-required-cache-inputs
  [record]
  (set/union (set (:invalidation-inputs record))
             (set (:behavior-facts record))
             #{:source :macro-expansion :profile :target}))

(defn perf3-validate-record!
  [source-path manifest performance-claim record]
  (let [missing-fields (perf3-missing-record-fields record)
        missing-key-inputs (perf3-missing-key-inputs record)
        partial (:partial-evaluation record)
        build-effects (set (:build-effects partial))
        grants (set (:grants partial))
        ungranted-effects (set/difference build-effects grants)
        cache-key-inputs (set (:cache-key-inputs record))
        missing-cache-inputs (set/difference
                              (perf3-required-cache-inputs record)
                              cache-key-inputs)
        variant (:variant-selection record)
        artifacts (set (:artifacts record))
        erased-checks (set (:erased-checks record))
        profile-illegal (set (:profile-illegal-behavior record))]
    (when (or (seq missing-fields)
              (seq missing-key-inputs)
              (not (set/subset? perf3-required-artifacts artifacts)))
      (perf3-fail! "PERF3-KEY" source-path manifest performance-claim record
                   {:missing-fields missing-fields
                    :missing-key-inputs missing-key-inputs
                    :missing-artifacts (set/difference
                                        perf3-required-artifacts
                                        artifacts)
                    :remediation "Record every behavior-affecting fact in the specialization key and attach specialized MIR, guard table, and source map artifacts."}))
    (when (or (not (perf-present? (:guard record)))
              (= :too-late (:guard-stage record))
              (= :hot-path (:guard-stage record)))
      (perf3-fail! "PERF3-GUARD" source-path manifest performance-claim record
                   {:guard-stage (:guard-stage record)
                    :remediation "Emit a guard predicate before the specialized variant can be selected."}))
    (when (seq ungranted-effects)
      (perf3-fail! "PERF3-EFFECT" source-path manifest performance-claim record
                   {:ungranted-build-effects ungranted-effects
                    :grants grants
                    :remediation "Declare and grant every L12 build effect used by partial evaluation."}))
    (when (and partial
               (or (false? (:hermetic partial))
                   (not (perf-present? (:replay-record partial)))))
      (perf3-fail! "PERF3-HERMETIC" source-path manifest performance-claim record
                   {:hermetic (:hermetic partial)
                    :replay-record (:replay-record partial)
                    :remediation "Partial evaluation must be hermetic and replayable."}))
    (when-not (perf-present? (:source-map record))
      (perf3-fail! "PERF3-SOURCE-MAP" source-path manifest performance-claim
                   record
                   {:missing-artifact :source-map
                    :remediation "Link the specialized artifact back to the generic source and generated-origin chain."}))
    (when (seq missing-cache-inputs)
      (perf3-fail! "PERF3-CACHE" source-path manifest performance-claim record
                   {:cache-key-inputs cache-key-inputs
                    :invalidation-inputs (:invalidation-inputs record)
                    :missing-cache-inputs missing-cache-inputs
                    :remediation "Include every invalidation and behavior fact in the specialization cache key."}))
    (when (or (not= (:profile manifest) (:profile record))
              (not= (:profile performance-claim) (:profile record))
              (not= (:target performance-claim) (:target record))
              (not= (:profile record) (:profile variant))
              (not= (:target record) (:target variant))
              (seq profile-illegal))
      (perf3-fail! "PERF3-PROFILE" source-path manifest performance-claim
                   record
                   {:active-profile (:profile manifest)
                    :performance-profile (:profile performance-claim)
                    :variant-profile (:profile variant)
                    :variant-target (:target variant)
                    :profile-illegal-behavior profile-illegal
                    :remediation "Specialized variants must remain legal for the active profile and target request."}))
    (when (and (seq erased-checks)
               (not (perf-present? (:proof-id record))))
      (perf3-fail! "PERF3-PROOF" source-path manifest performance-claim record
                   {:erased-checks erased-checks
                    :remediation "Attach the specialized SAFE15 proof id for every erased check."}))
    (when (or (not (perf-present? (:strategy variant)))
              (not (perf-present? (:guard-binding variant)))
              (:ambiguous? variant)
              (:unsafe? variant))
      (perf3-fail! "PERF3-VARIANT" source-path manifest performance-claim
                   record
                   {:variant-selection variant
                    :remediation "Variant selection must be unambiguous, guarded, and safe for the performance claim."}))
    :complete))

(defn specialization-capability-proof
  [manifest performance-claim records]
  {:profile-legality-preserved? (every? #(= (:profile manifest)
                                            (:profile %))
                                        records)
   :target-request-preserved? (every? #(= (:target performance-claim)
                                          (:target %))
                                      records)
   :effect-authority-preserved?
   (every? #(set/subset? (set (:effects %))
                         (set (:source-effects manifest)))
           records)
   :capability-authority-preserved?
   (every? #(set/subset? (set (:capabilities %))
                         (set (:source-capabilities manifest)))
           records)
   :build-effects-granted?
   (every? (fn [record]
             (let [partial (:partial-evaluation record)]
               (set/subset? (set (:build-effects partial))
                            (set (:grants partial)))))
           records)
   :cache-invalidation-recorded?
   (every? #(empty? (set/difference
                    (perf3-required-cache-inputs %)
                    (set (:cache-key-inputs %))))
           records)
   :specialized-proof-preserved?
   (every? #(or (empty? (:erased-checks %))
                (perf-present? (:proof-id %)))
           records)
   :variant-selection-safe? (every? #(not (or (:ambiguous?
                                               (:variant-selection %))
                                             (:unsafe?
                                              (:variant-selection %))))
                                    records)
   :status :complete})

(defn specialization-source-artifact
  [source-path source-text]
  (let [performance-artifact (performance-source-artifact source-path
                                                          source-text)
        manifest (:profile-manifest performance-artifact)
        performance (get-in manifest [:metadata :performance] {})
        performance-claim (perf1-normalize-claim (:claim performance))
        suite (:specialization performance)
        records (mapv perf3-normalize-record (:records suite))]
    (when (empty? records)
      (perf3-fail! "PERF3-KEY" source-path manifest performance-claim
                   {:record-id (:suite-id suite)
                    :source-function nil
                    :profile (:profile manifest)
                    :target (:target performance-claim)
                    :behavior-facts []
                    :key {}
                    :guard nil
                    :artifacts #{}}
                   {:missing-fields [:records]
                    :remediation "Provide at least one specialization record."}))
    (doseq [record records]
      (perf3-validate-record! source-path manifest performance-claim record))
    (let [capability-proof (specialization-capability-proof
                            manifest performance-claim records)
          conformance {:document "PERF3"
                       :task "P04-T03"
                       :required-diagnostic-ids perf3-diagnostic-ids
                       :specialization-modes-covered
                       (set (mapcat :specialization-modes records))
                       :guard-predicate-status :complete
                       :partial-evaluation-status :complete
                       :source-map-status :complete
                       :cache-invalidation-status :complete
                       :variant-selection-status :complete
                       :proof-backed-erasure-status :complete
                       :status :complete}]
      {:kind :gravity/stage0-specialization-artifact
       :document "PERF3"
       :pass {:name :specialization-validation
              :input :optimization-manifest
              :output :specialization-report
              :requires [:performance-claim-validation
                         :typed-compile-time-values
                         :effect-capability-facts
                         :profile-manifest-validation
                         :safe15-proof-records
                         :compile-time-evaluation-log]
              :preserves [:source-spans :profile :target :effects
                          :capabilities :safety-mode :profile-legality
                          :proof-index :generated-origin-chain]
              :emits [:specialization-key-report
                      :guard-predicate-set
                      :specialized-artifact-manifest
                      :generic-to-specialized-source-map
                      :compile-time-evaluation-log
                      :variant-manifest
                      :cache-invalidation-record
                      :specialization-conformance-results]
              :rejects perf3-diagnostic-ids}
       :performance-artifact-hash (str "sha256:"
                                       (sha256-hex
                                        (pr-str performance-artifact)))
       :performance-contract-manifest
       (:performance-contract-manifest performance-artifact)
       :specialization-key-report
       (mapv #(select-keys % [:record-id :source-function
                              :specialization-modes :behavior-facts
                              :key])
             records)
       :guard-predicate-set
       (mapv #(select-keys % [:record-id :guard :guard-stage])
             records)
       :specialized-artifact-manifest
       (mapv #(select-keys % [:record-id :variant-id :profile :target
                              :artifacts :proof-id :erased-checks])
             records)
       :generic-to-specialized-source-map
       (mapv #(select-keys % [:record-id :source-map
                              :generated-origin-chain])
             records)
       :compile-time-evaluation-log
       (mapv #(select-keys % [:record-id :partial-evaluation])
             records)
       :variant-manifest
       (mapv #(select-keys % [:record-id :variant-selection])
             records)
       :cache-invalidation-record
       (mapv #(select-keys % [:record-id :cache-key-inputs
                              :invalidation-inputs])
             records)
       :capability-based-proof capability-proof
       :specialization-conformance-results conformance
       :diagnostics []})))

(def perf4-required-record-fields
  [:record-id :type :profile :target :layout :transformation :fields
   :alignment :abi :proofs :artifacts])

(def perf4-required-artifacts
  #{:layout-manifest :alignment-proof :alias-ownership-report
    :address-identity-report :abi-compatibility-record :cache-shape-report
    :device-transfer-layout-record :debug-source-map})

(defn perf4-normalize-record
  [record]
  (assoc record
         :record-id (or (:record-id record) (:id record))))

(defn perf4-missing-record-fields
  [record]
  (vec (remove #(perf-present? (get record %))
               perf4-required-record-fields)))

(defn perf4-fail!
  [id source-path manifest performance-claim record extra]
  (fail! id
         (case id
           "PERF4-LAYOUT" "layout manifest is missing or ambiguous"
           "PERF4-ABI" "layout transformation crosses a fixed boundary without compatible representation"
           "PERF4-ADDRESS" "layout transformation violates observable address identity"
           "PERF4-ALIAS" "layout transformation lacks alias or ownership proof"
           "PERF4-ALIGN" "layout alignment is unsupported or unsafe"
           "PERF4-PACKED" "packed layout lacks access-safety facts"
           "PERF4-CACHE" "cache claim lacks target and benchmark evidence"
           "PERF4-DEVICE" "host and device layouts are incompatible"
           "PERF4-PROOF" "layout-driven check erasure lacks proof"
           "layout optimization record is invalid")
         (merge {:source-span {:source source-path}
                 :profile (:profile manifest)
                 :target (:target manifest)
                 :target-request (:target performance-claim)
                 :layout-type (:type record)
                 :field (:field record)
                 :boundary (:boundary record)
                 :layout-transform (:transformation record)
                 :missing-proof nil
                 :diagnostic-family :layout-optimization-validation}
                extra)))

(defn perf4-validate-record!
  [source-path manifest performance-claim record]
  (let [missing-fields (perf4-missing-record-fields record)
        artifacts (set (:artifacts record))
        missing-artifacts (set/difference perf4-required-artifacts artifacts)
        boundary (:boundary record)
        address (:address-identity record)
        alias-proof (:alias-proof record)
        ownership-proof (:ownership-proof record)
        alignment-proof (:alignment-proof record)
        packing (:packing-record record)
        cache (:cache-shape record)
        device (:device-transfer record)
        erased-checks (set (:erased-checks record))]
    (when (or (seq missing-fields)
              (seq missing-artifacts)
              (not= (:profile manifest) (:profile record))
              (not= (:profile performance-claim) (:profile record))
              (not= (:target performance-claim) (:target record)))
      (perf4-fail! "PERF4-LAYOUT" source-path manifest performance-claim
                   record
                   {:missing-fields missing-fields
                    :missing-artifacts missing-artifacts
                    :remediation "Emit a complete layout manifest with profile, target, fields, alignment, ABI, proofs, and required layout artifacts."}))
    (when (and (or (:public? boundary)
                   (:persistence? boundary)
                   (:ffi? boundary)
                   (:changes-public-boundary? record))
               (not (perf-present? (:adapter boundary))))
      (perf4-fail! "PERF4-ABI" source-path manifest performance-claim record
                   {:boundary boundary
                    :missing-proof :boundary-adapter
                    :remediation "Public ABI, FFI, persistence, and package boundaries require compatible representation or generated adapters."}))
    (when (and (:observable? address)
               (not (or (contains? (set (:proofs record))
                                   :no-observable-address-identity)
                        (perf-present? (:unsafe-audit address)))))
      (perf4-fail! "PERF4-ADDRESS" source-path manifest performance-claim
                   record
                   {:missing-proof :address-identity
                    :remediation "Do not change observable address identity without proof or unsafe audit."}))
    (when (or (not (perf-present? alias-proof))
              (not (perf-present? ownership-proof)))
      (perf4-fail! "PERF4-ALIAS" source-path manifest performance-claim record
                   {:missing-proof
                    (cond-> #{}
                      (not (perf-present? alias-proof)) (conj :alias-proof)
                      (not (perf-present? ownership-proof))
                      (conj :ownership-proof))
                    :remediation "Attach alias and ownership proofs before layout transformation."}))
    (when (or (false? (:target-supported? alignment-proof))
              (false? (:access-safe? alignment-proof)))
      (perf4-fail! "PERF4-ALIGN" source-path manifest performance-claim record
                   {:missing-proof :target-alignment-support
                    :alignment (:alignment record)
                    :remediation "Record target support and safe access behavior for optimized alignment."}))
    (when (and (:packed? packing)
               (empty? (:access-safety-facts packing)))
      (perf4-fail! "PERF4-PACKED" source-path manifest performance-claim record
                   {:missing-proof :access-safety-facts
                    :remediation "Packed layouts require explicit access-safety facts."}))
    (when (or (not (perf-present? (:target-fingerprint cache)))
              (not (perf-present? (:benchmark cache))))
      (perf4-fail! "PERF4-CACHE" source-path manifest performance-claim record
                   {:missing-proof :cache-target-benchmark
                    :remediation "Cache-shape claims must name target fingerprint and benchmark evidence."}))
    (when (and (not= (:host-layout device) (:device-layout device))
               (not (perf-present? (:adapter device))))
      (perf4-fail! "PERF4-DEVICE" source-path manifest performance-claim
                   record
                   {:missing-proof :device-transfer-adapter
                    :remediation "Host/device layout mismatch requires an explicit transfer adapter or compatible layout record."}))
    (when (and (seq erased-checks)
               (not (perf-present? (:proof-id record))))
      (perf4-fail! "PERF4-PROOF" source-path manifest performance-claim record
                   {:erased-checks erased-checks
                    :missing-proof :layout-proof-id
                    :remediation "Attach a layout proof id for checks erased by layout facts."}))
    :complete))

(defn layout-capability-proof
  [manifest performance-claim records]
  {:profile-legality-preserved? (every? #(= (:profile manifest)
                                            (:profile %))
                                        records)
   :target-request-preserved? (every? #(= (:target performance-claim)
                                          (:target %))
                                      records)
   :alias-and-ownership-proven?
   (every? #(and (perf-present? (:alias-proof %))
                 (perf-present? (:ownership-proof %)))
           records)
   :address-identity-safe?
   (every? #(not (get-in % [:address-identity :observable?])) records)
   :alignment-supported? (every? #(true? (get-in % [:alignment-proof
                                                    :target-supported?]))
                                 records)
   :cache-evidence-recorded?
   (every? #(and (perf-present? (get-in % [:cache-shape
                                           :target-fingerprint]))
                 (perf-present? (get-in % [:cache-shape :benchmark])))
           records)
   :device-transfer-compatible?
   (every? #(or (= (get-in % [:device-transfer :host-layout])
                  (get-in % [:device-transfer :device-layout]))
                (perf-present? (get-in % [:device-transfer :adapter])))
           records)
   :layout-proof-preserved?
   (every? #(or (empty? (:erased-checks %))
                (perf-present? (:proof-id %)))
           records)
   :status :complete})

(defn layout-source-artifact
  [source-path source-text]
  (let [performance-artifact (performance-source-artifact source-path
                                                          source-text)
        manifest (:profile-manifest performance-artifact)
        performance (get-in manifest [:metadata :performance] {})
        performance-claim (perf1-normalize-claim (:claim performance))
        suite (:layout performance)
        records (mapv perf4-normalize-record (:records suite))]
    (when (empty? records)
      (perf4-fail! "PERF4-LAYOUT" source-path manifest performance-claim
                   {:record-id (:suite-id suite)}
                   {:missing-fields [:records]
                    :remediation "Provide at least one layout optimization record."}))
    (doseq [record records]
      (perf4-validate-record! source-path manifest performance-claim record))
    (let [capability-proof (layout-capability-proof manifest performance-claim
                                                    records)
          conformance {:document "PERF4"
                       :task "P04-T04"
                       :required-diagnostic-ids perf4-diagnostic-ids
                       :layout-transformations-covered
                       (set (map :transformation records))
                       :layout-manifest-status :complete
                       :abi-boundary-status :complete
                       :address-identity-status :complete
                       :alias-ownership-status :complete
                       :alignment-packing-status :complete
                       :cache-shape-status :complete
                       :device-transfer-status :complete
                       :proof-backed-erasure-status :complete
                       :status :complete}]
      {:kind :gravity/stage0-layout-optimization-artifact
       :document "PERF4"
       :pass {:name :layout-optimization-validation
              :input :optimization-manifest
              :output :layout-optimization-report
              :requires [:performance-claim-validation
                         :typed-field-facts
                         :memory-safety-facts
                         :ffi-abi-boundaries
                         :profile-manifest-validation
                         :safe15-proof-records]
              :preserves [:source-spans :profile :target :effects
                          :capabilities :safety-mode :profile-legality
                          :proof-index :debug-source-map]
              :emits [:layout-manifest
                      :alignment-proof
                      :padding-packing-record
                      :alias-ownership-report
                      :address-identity-report
                      :abi-compatibility-record
                      :cache-shape-report
                      :device-transfer-layout-record
                      :layout-conformance-results]
              :rejects perf4-diagnostic-ids}
       :performance-artifact-hash (str "sha256:"
                                       (sha256-hex
                                        (pr-str performance-artifact)))
       :performance-contract-manifest
       (:performance-contract-manifest performance-artifact)
       :layout-manifest (mapv #(select-keys % [:record-id :type :profile
                                               :target :layout :fields
                                               :alignment :padding :abi
                                               :transformation])
                              records)
       :alignment-proof (mapv #(select-keys % [:record-id :alignment-proof])
                              records)
       :padding-packing-record
       (mapv #(select-keys % [:record-id :packing-record]) records)
       :alias-ownership-report
       (mapv #(select-keys % [:record-id :alias-proof :ownership-proof])
             records)
       :address-identity-report
       (mapv #(select-keys % [:record-id :address-identity])
             records)
       :abi-compatibility-record
       (mapv #(select-keys % [:record-id :boundary :abi]) records)
       :cache-shape-report
       (mapv #(select-keys % [:record-id :cache-shape]) records)
       :device-transfer-layout-record
       (mapv #(select-keys % [:record-id :device-transfer]) records)
       :debug-source-map
       (mapv #(select-keys % [:record-id :debug-source-map]) records)
       :capability-based-proof capability-proof
       :layout-conformance-results conformance
       :diagnostics []})))

(def perf5-required-benchmark-fields
  [:benchmark-id :profile :target :workload :metric :warmup :units
   :samples :statistics :environment-fingerprint :acceptance :gates
   :baseline :sample-summary :regression-report :baseline-registry])

(def perf6-required-identity-fields
  [:source-hash :typed-artifact-hash :mir-hash :compiler-version :profile
   :target :provider-versions :workload])

(def perf6-required-decision-preserves
  #{:types :effects :capabilities :profile :safety :taint :numeric
    :unsafe-audit})

(def perf7-required-candidate-space-fields
  [:candidate-space-id :objective :variants :constraints :benchmark])

(defn perf5-normalize-benchmark
  [record]
  (assoc record
         :benchmark-id (or (:benchmark-id record) (:id record))
         :samples (or (:samples record) (get-in record [:sample-summary
                                                        :count]))))

(defn perf5-missing-benchmark-fields
  [record]
  (vec (remove #(perf-present? (get record %))
               perf5-required-benchmark-fields)))

(defn perf5-fail!
  [id source-path manifest performance-claim record extra]
  (fail! id
         (case id
           "PERF5-MANIFEST" "benchmark manifest is incomplete"
           "PERF5-FINGERPRINT" "benchmark environment fingerprint is missing or incomplete"
           "PERF5-SAFETY-GATE" "benchmark result bypasses the safety gate"
           "PERF5-CORRECTNESS-GATE" "benchmark result bypasses the correctness gate"
           "PERF5-REGRESSION" "benchmark report contains an unaccepted regression"
           "PERF5-NOISE" "benchmark sample set is too noisy or undersampled"
           "PERF5-BASELINE" "benchmark baseline update lacks review or history"
           "PERF5-DRIFT" "benchmark environment drift is unaccounted"
           "benchmark governance record is invalid")
         (merge {:source-span {:source source-path}
                 :profile (:profile manifest)
                 :target (:target manifest)
                 :target-request (:target performance-claim)
                 :benchmark-id (:benchmark-id record)
                 :metric (:metric record)
                 :baseline (:baseline record)
                 :environment-fingerprint (:environment-fingerprint record)
                 :sample-summary (:sample-summary record)
                 :threshold (get-in record [:acceptance
                                            :max-regression-percent])
                 :gate-state (:gates record)
                 :diagnostic-family :benchmark-governance-validation}
                extra)))

(defn perf5-valid-fingerprint?
  [fingerprint]
  (every? #(perf-present? (get fingerprint %))
          [:source-hash :compiler :runtime :target :profile
           :provider-versions]))

(defn perf5-validate-benchmark!
  [source-path manifest performance-claim record]
  (let [missing-fields (perf5-missing-benchmark-fields record)
        fingerprint (:environment-fingerprint record)
        gates (:gates record)
        min-samples (or (get-in record [:acceptance :min-samples]) 30)
        sample-count (or (:samples record)
                         (get-in record [:sample-summary :count])
                         0)
        regression (:regression-report record)
        regression-percent (or (:percent regression) 0)
        threshold (or (get-in record [:acceptance
                                      :max-regression-percent])
                      (:threshold regression)
                      0)
        baseline (:baseline record)
        baseline-update (:baseline-update record)
        drift (:environment-drift record)]
    (when (or (seq missing-fields)
              (not= (:profile manifest) (:profile record))
              (not= (:profile performance-claim) (:profile record))
              (not= (:target performance-claim) (:target record)))
      (perf5-fail! "PERF5-MANIFEST" source-path manifest performance-claim
                   record
                   {:missing-fields missing-fields
                    :remediation "Record workload, profile, target, metric, warmup, sample count, statistics, environment, gates, baselines, and machine-readable report fields."}))
    (when-not (perf5-valid-fingerprint? fingerprint)
      (perf5-fail! "PERF5-FINGERPRINT" source-path manifest
                   performance-claim record
                   {:missing-fields
                    (vec (remove #(perf-present? (get fingerprint %))
                                 [:source-hash :compiler :runtime :target
                                  :profile :provider-versions]))
                    :remediation "Tie benchmark evidence to source, compiler, runtime, profile, target, and provider versions."}))
    (when-not (true? (:safety gates))
      (perf5-fail! "PERF5-SAFETY-GATE" source-path manifest
                   performance-claim record
                   {:remediation "Performance evidence cannot accept a win until the safety gate passes."}))
    (when-not (true? (:correctness gates))
      (perf5-fail! "PERF5-CORRECTNESS-GATE" source-path manifest
                   performance-claim record
                   {:remediation "Performance evidence cannot accept a win until the correctness gate passes."}))
    (when (or (< sample-count min-samples)
              (false? (get-in record [:sample-summary
                                      :variance-stable?]))
              (= :unstable (get-in record [:sample-summary
                                           :noise-classification])))
      (perf5-fail! "PERF5-NOISE" source-path manifest performance-claim
                   record
                   {:samples sample-count
                    :required-samples min-samples
                    :remediation "Classify noisy measurements instead of treating them as release-quality evidence."}))
    (when (and (> regression-percent threshold)
               (not (contains? #{:accepted-regression
                                 :intentional-drift
                                 :no-regression}
                               (:classification regression))))
      (perf5-fail! "PERF5-REGRESSION" source-path manifest
                   performance-claim record
                   {:regression-percent regression-percent
                    :threshold threshold
                    :classification (:classification regression)
                    :remediation "Classify regressions and require an accepted baseline or explicit review before release."}))
    (when (or (false? (:reviewed? baseline))
              (empty? (:history baseline))
              (and (:requested? baseline-update)
                   (not (true? (:reviewed? baseline-update)))))
      (perf5-fail! "PERF5-BASELINE" source-path manifest performance-claim
                   record
                   {:baseline baseline
                    :baseline-update baseline-update
                    :remediation "Baseline updates require review, history, and a machine-readable registry entry."}))
    (when (or (= :incompatible (:classification drift))
              (false? (:compatible? drift)))
      (perf5-fail! "PERF5-DRIFT" source-path manifest performance-claim
                   record
                   {:environment-drift drift
                    :remediation "Account for environment drift before comparing benchmark results against a baseline."}))
    :complete))

(defn perf6-normalize-record
  [record]
  (assoc record
         :profile-data-id (or (:profile-data-id record) (:id record))))

(defn perf6-missing-identity-fields
  [record]
  (let [identity (:identity record)]
    (vec (remove #(perf-present? (get identity %))
                 perf6-required-identity-fields))))

(defn perf6-fail!
  [id source-path manifest performance-claim record extra]
  (fail! id
         (case id
           "PERF6-DATA-MISSING" "required PGO profile data is missing"
           "PERF6-STALE" "PGO profile data is stale for release use"
           "PERF6-IDENTITY" "PGO profile identity does not match the compiled artifact"
           "PERF6-PRIVACY" "PGO profile data violates privacy or taint policy"
           "PERF6-DECISION" "PGO optimization decision lacks an audit log"
           "PERF6-SAFETY" "PGO decision loses semantic or safety facts"
           "PERF6-REPRO" "PGO decision is not reproducible from recorded inputs"
           "PERF6-WORKLOAD" "PGO workload does not match the declared workload"
           "PGO record is invalid")
         (merge {:source-span {:source source-path}
                 :profile (:profile manifest)
                 :target (:target manifest)
                 :target-request (:target performance-claim)
                 :profile-data-id (:profile-data-id record)
                 :policy (:policy record)
                 :source-hash (get-in record [:identity :source-hash])
                 :mir-hash (get-in record [:identity :mir-hash])
                 :workload (:workload record)
                 :diagnostic-family :pgo-validation}
                extra)))

(defn perf6-validate-record!
  [source-path manifest performance-claim record]
  (let [missing-identity (perf6-missing-identity-fields record)
        identity (:identity record)
        status (:status record)
        privacy (:privacy record)
        decisions (vec (:decisions record))
        bad-decision (first (filter #(or (not (perf-present?
                                               (:pass-id %)))
                                          (not (perf-present?
                                               (:decision-log %)))
                                          (not (= (:profile-data-id record)
                                                  (:profile-data-id %))))
                                    decisions))
        unsafe-decision (first
                         (filter #(seq (set/difference
                                        perf6-required-decision-preserves
                                        (set (:preserves %))))
                                 decisions))
        staleness (:staleness record)]
    (when (or (seq missing-identity)
              (not= (:profile manifest) (:profile identity))
              (not= (:profile performance-claim) (:profile identity))
              (not= (:target performance-claim) (:target identity)))
      (perf6-fail! "PERF6-IDENTITY" source-path manifest performance-claim
                   record
                   {:missing-fields missing-identity
                    :remediation "Key PGO data by source hash, typed artifact hash, MIR hash, compiler version, profile, target, provider versions, and workload."}))
    (when (or (= :required-missing status)
              (false? (:profile-data-present? record))
              (not (perf-present? (:profile-data-id record))))
      (perf6-fail! "PERF6-DATA-MISSING" source-path manifest
                   performance-claim record
                   {:missing-field :profile-data
                    :remediation "Required PGO data must be present, or the optimization must be rejected instead of silently using defaults."}))
    (when (or (= :stale status)
              (= :stale (:status staleness))
              (and (:release-use? record)
                   (not (true? (:fresh-for-release? staleness)))))
      (perf6-fail! "PERF6-STALE" source-path manifest performance-claim
                   record
                   {:stale-field staleness
                    :remediation "Stale PGO data cannot drive release builds without an explicit stale/rejected status."}))
    (when (or (not (true? (:redacted? privacy)))
              (true? (:raw-identifiers? privacy))
              (false? (:taint-free? privacy)))
      (perf6-fail! "PERF6-PRIVACY" source-path manifest performance-claim
                   record
                   {:privacy privacy
                    :remediation "Aggregate or redact profile data before it enters the optimization decision record."}))
    (when (or (empty? decisions) bad-decision)
      (perf6-fail! "PERF6-DECISION" source-path manifest performance-claim
                   record
                   {:pass-id (:pass-id bad-decision)
                    :missing-field :decision-log
                    :remediation "Every PGO-driven optimization must emit a decision log tied to the profile data identity."}))
    (when (or unsafe-decision
              (seq (:lost-safety-facts record)))
      (perf6-fail! "PERF6-SAFETY" source-path manifest performance-claim
                   record
                   {:pass-id (:pass-id unsafe-decision)
                    :lost-safety-facts (:lost-safety-facts record)
                    :missing-fact (when unsafe-decision
                                    (set/difference
                                     perf6-required-decision-preserves
                                     (set (:preserves unsafe-decision))))
                    :remediation "PGO may change optimization choices, but it must not erase type, effect, capability, profile, safety, taint, numeric, or unsafe-audit facts."}))
    (when-not (true? (get-in record [:reproducibility :replayable?]))
      (perf6-fail! "PERF6-REPRO" source-path manifest performance-claim
                   record
                   {:reproducibility (:reproducibility record)
                    :remediation "Record inputs sufficient to replay the PGO decision with the same compiler and profile data."}))
    (when (and (perf-present? (:expected-workload record))
               (not= (:expected-workload record)
                     (get-in record [:identity :workload])))
      (perf6-fail! "PERF6-WORKLOAD" source-path manifest performance-claim
                   record
                   {:expected-workload (:expected-workload record)
                    :actual-workload (get-in record [:identity :workload])
                    :remediation "PGO data must be matched to the workload declared for the optimization decision."}))
    :complete))

(defn perf7-normalize-record
  [record]
  (assoc record
         :candidate-space-id (or (get-in record [:candidate-space
                                                 :candidate-space-id])
                                 (:candidate-space-id record))))

(defn perf7-missing-candidate-space-fields
  [record]
  (let [space (:candidate-space record)]
    (vec (remove #(perf-present? (get space %))
                 perf7-required-candidate-space-fields))))

(defn perf7-fail!
  [id source-path manifest performance-claim record extra]
  (fail! id
         (case id
           "PERF7-CANDIDATE-SPACE" "autotuning candidate space is missing or undeclared"
           "PERF7-CANDIDATE-REJECTED" "invalid autotuning candidate reached benchmarking or selection"
           "PERF7-GUARD" "autotuned variant guard table is incomplete or ambiguous"
           "PERF7-SELECTION" "autotuning selection lacks objective, benchmark, target, or reason"
           "PERF7-CERTIFICATE" "selected variant lacks required certificates"
           "PERF7-DISPATCH" "multiversion dispatch overhead is not accounted"
           "PERF7-REPRO" "autotuning selection is not reproducible"
           "PERF7-FALLBACK" "autotuned multiversion dispatch lacks a safe fallback"
           "autotuning record is invalid")
         (merge {:source-span {:source source-path}
                 :profile (:profile manifest)
                 :target (:target manifest)
                 :target-request (:target performance-claim)
                 :candidate-space-id (:candidate-space-id record)
                 :candidate-id (get-in record [:selected :candidate-id])
                 :variant-id (get-in record [:selected :variant-id])
                 :objective (get-in record [:candidate-space :objective])
                 :guard (get-in record [:selected :guard-predicate])
                 :fallback-status (get-in record [:guard-table :fallback])
                 :diagnostic-family :autotuning-multiversioning-validation}
                extra)))

(defn perf7-variant-guard-valid?
  [guard]
  (and (perf-present? (:variant-id guard))
       (perf-present? (:predicate guard))))

(defn perf7-validate-record!
  [source-path manifest performance-claim record]
  (let [space (:candidate-space record)
        missing-space (perf7-missing-candidate-space-fields record)
        candidates (vec (:candidates record))
        selected (:selected record)
        selected-id (:candidate-id selected)
        candidate-ids (set (map :candidate-id candidates))
        invalid-benchmarked (first
                             (filter #(and (:benchmarked? %)
                                           (not= :accepted
                                                 (:evidence-status %)))
                                     candidates))
        guard-table (:guard-table record)
        guards (vec (:guards guard-table))
        invalid-guard (first (remove perf7-variant-guard-valid? guards))]
    (when (or (seq missing-space)
              (empty? candidates)
              (not= (:profile manifest)
                    (get-in space [:constraints :profile]))
              (not= (:profile performance-claim)
                    (get-in space [:constraints :profile]))
              (not= (:target performance-claim)
                    (get-in space [:constraints :target])))
      (perf7-fail! "PERF7-CANDIDATE-SPACE" source-path manifest
                   performance-claim record
                   {:missing-fields missing-space
                    :remediation "Declare the candidate space, objective, variants, constraints, target, profile, and benchmark before tuning."}))
    (when (or invalid-benchmarked
              (and selected-id
                   (not (contains? candidate-ids selected-id))))
      (perf7-fail! "PERF7-CANDIDATE-REJECTED" source-path manifest
                   performance-claim record
                   {:candidate-id (or (:candidate-id invalid-benchmarked)
                                      selected-id)
                    :selected-status (:evidence-status invalid-benchmarked)
                    :remediation "Reject invalid candidates before benchmarking and never select a candidate outside the declared space."}))
    (when (or (empty? guards)
              (true? (:overlap? guard-table))
              invalid-guard)
      (perf7-fail! "PERF7-GUARD" source-path manifest performance-claim
                   record
                   {:guard invalid-guard
                    :remediation "Emit explicit, non-overlapping dispatch guards before a multiversioned artifact is accepted."}))
    (when (or (not (perf-present? selected-id))
              (not (perf-present? (:objective selected)))
              (not (perf-present? (:benchmark-comparison selected)))
              (not (perf-present? (:target-fingerprint selected)))
              (not (perf-present? (:reason selected))))
      (perf7-fail! "PERF7-SELECTION" source-path manifest
                   performance-claim record
                   {:missing-fields
                    (vec (remove #(perf-present? (get selected %))
                                 [:candidate-id :objective
                                  :benchmark-comparison
                                  :target-fingerprint :reason]))
                    :remediation "Selection records must name the chosen variant, objective, benchmark comparison, target fingerprint, and reason."}))
    (when (empty? (:certificates selected))
      (perf7-fail! "PERF7-CERTIFICATE" source-path manifest
                   performance-claim record
                   {:missing-certificate :selected-variant
                    :remediation "Selected variants require safety, compatibility, and semantic certificates."}))
    (when-not (true? (get-in record [:dispatch-overhead :accounted?]))
      (perf7-fail! "PERF7-DISPATCH" source-path manifest performance-claim
                   record
                   {:dispatch-overhead (:dispatch-overhead record)
                    :remediation "Account for multiversion dispatch overhead or prove static erasure."}))
    (when-not (true? (get-in record [:reproducibility :reproducible?]))
      (perf7-fail! "PERF7-REPRO" source-path manifest performance-claim
                   record
                   {:reproducibility (:reproducibility record)
                    :remediation "Record candidate-space hash, benchmark inputs, compiler version, target fingerprint, and selected variant evidence."}))
    (when-not (and (perf-present? (:fallback guard-table))
                   (contains? candidate-ids (:fallback guard-table)))
      (perf7-fail! "PERF7-FALLBACK" source-path manifest performance-claim
                   record
                   {:fallback-status (:fallback guard-table)
                    :remediation "Multiversioned dispatch must include a safe fallback variant from the declared candidate set."}))
    :complete))

(defn performance-governance-capability-proof
  [manifest performance-claim benchmarks pgo-records autotuning-records]
  {:profile-legality-preserved?
   (and (every? #(= (:profile manifest) (:profile %)) benchmarks)
        (every? #(= (:profile manifest) (get-in % [:identity :profile]))
                pgo-records)
        (every? #(= (:profile manifest)
                    (get-in % [:candidate-space :constraints :profile]))
                autotuning-records))
   :target-request-preserved?
   (and (every? #(= (:target performance-claim) (:target %)) benchmarks)
        (every? #(= (:target performance-claim)
                    (get-in % [:identity :target]))
                pgo-records)
        (every? #(= (:target performance-claim)
                    (get-in % [:candidate-space :constraints :target]))
                autotuning-records))
   :benchmark-safety-gates-passed?
   (every? #(true? (get-in % [:gates :safety])) benchmarks)
   :benchmark-correctness-gates-passed?
   (every? #(true? (get-in % [:gates :correctness])) benchmarks)
   :pgo-identity-recorded?
   (every? #(empty? (perf6-missing-identity-fields %)) pgo-records)
   :pgo-privacy-preserved?
   (every? #(and (true? (get-in % [:privacy :redacted?]))
                 (not (true? (get-in % [:privacy
                                         :raw-identifiers?])))
                 (true? (get-in % [:privacy :taint-free?])))
           pgo-records)
   :pgo-decisions-preserve-capabilities?
   (every? (fn [record]
             (every? #(empty? (set/difference
                               perf6-required-decision-preserves
                               (set (:preserves %))))
                     (:decisions record)))
           pgo-records)
   :autotuning-invalid-candidates-excluded?
   (every? (fn [record]
             (every? #(or (= :accepted (:evidence-status %))
                          (not (:benchmarked? %)))
                     (:candidates record)))
           autotuning-records)
   :variant-guards-recorded?
   (every? #(and (seq (get-in % [:guard-table :guards]))
                 (not (true? (get-in % [:guard-table
                                         :overlap?]))))
           autotuning-records)
   :fallback-recorded?
   (every? #(perf-present? (get-in % [:guard-table :fallback]))
           autotuning-records)
   :status :complete})

(defn performance-governance-source-artifact
  [source-path source-text]
  (let [performance-artifact (performance-source-artifact source-path
                                                          source-text)
        manifest (:profile-manifest performance-artifact)
        performance (get-in manifest [:metadata :performance] {})
        performance-claim (perf1-normalize-claim (:claim performance))
        suite (:governance performance)
        benchmarks (mapv perf5-normalize-benchmark (:benchmarks suite))
        pgo-records (mapv perf6-normalize-record (:pgo-records suite))
        autotuning-records (mapv perf7-normalize-record
                                 (:autotuning-records suite))]
    (when (empty? benchmarks)
      (perf5-fail! "PERF5-MANIFEST" source-path manifest performance-claim
                   {:benchmark-id (:suite-id suite)}
                   {:missing-fields [:benchmarks]
                    :remediation "Provide at least one governed benchmark manifest."}))
    (when (empty? pgo-records)
      (perf6-fail! "PERF6-DATA-MISSING" source-path manifest
                   performance-claim {:profile-data-id (:suite-id suite)}
                   {:missing-field :pgo-records
                    :remediation "Provide at least one PGO profile data record or explicitly reject PGO use."}))
    (when (empty? autotuning-records)
      (perf7-fail! "PERF7-CANDIDATE-SPACE" source-path manifest
                   performance-claim
                   {:candidate-space-id (:suite-id suite)}
                   {:missing-fields [:autotuning-records]
                    :remediation "Provide at least one autotuning candidate-space record."}))
    (doseq [record benchmarks]
      (perf5-validate-benchmark! source-path manifest performance-claim
                                 record))
    (doseq [record pgo-records]
      (perf6-validate-record! source-path manifest performance-claim record))
    (doseq [record autotuning-records]
      (perf7-validate-record! source-path manifest performance-claim
                              record))
    (let [capability-proof
          (performance-governance-capability-proof
           manifest performance-claim benchmarks pgo-records
           autotuning-records)
          conformance {:documents ["PERF5" "PERF6" "PERF7"]
                       :task "P04-T05"
                       :required-diagnostic-ids perf5-7-diagnostic-ids
                       :benchmark-governance-status :complete
                       :pgo-governance-status :complete
                       :autotuning-governance-status :complete
                       :status :complete}]
      {:kind :gravity/stage0-performance-governance-artifact
       :document-set ["PERF5" "PERF6" "PERF7"]
       :pass {:name :performance-governance-validation
              :input :optimization-manifest
              :output :performance-governance-report
              :requires [:performance-claim-validation
                         :benchmark-manifest
                         :safety-and-correctness-gates
                         :profile-guided-optimization-data
                         :autotuning-candidate-space
                         :variant-guard-table]
              :preserves [:source-spans :profile :target :effects
                          :capabilities :safety-mode :profile-legality
                          :proof-index :benchmark-provenance
                          :pgo-identity :variant-guards]
              :emits [:benchmark-manifest
                      :environment-fingerprint
                      :correctness-safety-gate-record
                      :benchmark-sample-summary
                      :regression-report
                      :baseline-registry
                      :pgo-profile-data-schema
                      :pgo-decision-log
                      :pgo-staleness-report
                      :pgo-privacy-report
                      :autotuning-candidate-space-manifest
                      :autotuning-variant-guard-table
                      :autotuning-selection-certificate
                      :dispatch-overhead-report
                      :performance-governance-conformance-results]
              :rejects perf5-7-diagnostic-ids}
       :performance-artifact-hash (str "sha256:"
                                       (sha256-hex
                                        (pr-str performance-artifact)))
       :performance-contract-manifest
       (:performance-contract-manifest performance-artifact)
       :benchmark-manifest
       (mapv #(select-keys % [:benchmark-id :profile :target :workload
                              :metric :warmup :units :samples
                              :statistics :acceptance
                              :machine-readable-report])
             benchmarks)
       :environment-fingerprint
       (mapv #(select-keys % [:benchmark-id :environment-fingerprint])
             benchmarks)
       :correctness-safety-gate-record
       (mapv #(select-keys % [:benchmark-id :gates]) benchmarks)
       :benchmark-sample-summary
       (mapv #(select-keys % [:benchmark-id :sample-summary])
             benchmarks)
       :regression-report
       (mapv #(select-keys % [:benchmark-id :regression-report])
             benchmarks)
       :baseline-registry
       (mapv #(select-keys % [:benchmark-id :baseline
                              :baseline-registry
                              :baseline-update])
             benchmarks)
       :pgo-profile-data-schema
       (mapv #(select-keys % [:profile-data-id :identity :status
                              :policy :workload])
             pgo-records)
       :pgo-hot-cold-map
       (mapv #(select-keys % [:profile-data-id :hot-cold-map])
             pgo-records)
       :pgo-decision-log
       (mapv #(select-keys % [:profile-data-id :decisions])
             pgo-records)
       :pgo-staleness-report
       (mapv #(select-keys % [:profile-data-id :staleness])
             pgo-records)
       :pgo-privacy-report
       (mapv #(select-keys % [:profile-data-id :privacy])
             pgo-records)
       :pgo-reproducibility-record
       (mapv #(select-keys % [:profile-data-id :reproducibility])
             pgo-records)
       :autotuning-candidate-space-manifest
       (mapv #(select-keys % [:candidate-space-id :candidate-space])
             autotuning-records)
       :autotuning-candidate-rejection-report
       (mapv #(select-keys % [:candidate-space-id :candidates])
             autotuning-records)
       :autotuning-variant-guard-table
       (mapv #(select-keys % [:candidate-space-id :guard-table])
             autotuning-records)
       :autotuning-selection-certificate
       (mapv #(select-keys % [:candidate-space-id :selected
                              :compatibility :source-map])
             autotuning-records)
       :dispatch-overhead-report
       (mapv #(select-keys % [:candidate-space-id :dispatch-overhead])
             autotuning-records)
       :autotuning-reproducibility-record
       (mapv #(select-keys % [:candidate-space-id :reproducibility])
             autotuning-records)
       :capability-based-proof capability-proof
       :performance-governance-conformance-results conformance
       :diagnostics []})))

(def perf8-required-record-fields
  [:record-id :optimization :loop :profile :target :requires :vector-width
   :numeric-mode :intrinsics :proofs :lane-plan :alignment-report
   :tail-handling :intrinsic-map :cache-transformation])

(def perf8-required-proofs
  #{:lane-independence :no-overlap :bounds-safe
    :aligned-or-safe-unaligned})

(def perf8-valid-tail-handling
  #{:scalar-epilogue :masked-vector :padded-input
    :multiple-of-width-proof})

(def perf9-required-contract-fields
  [:contract-id :profile :target :budget :workload :allocation :blocking
   :bounds :preemption :forbidden-runtime :evidence :failure-mode])

(def perf10-required-record-fields
  [:record-id :optimization :check-class :operation :profile :target
   :source-span :ir-node :dominating-proof :proof-dominates-use
   :invalidated-by :residual-checks :certificate :pass-id :source-map])

(def perf10-policy-check-classes
  #{:capability :effect :unsafe-audit :workflow-replay :ai-human-review})

(defn perf8-normalize-record
  [record]
  (assoc record
         :record-id (or (:record-id record) (:id record))))

(defn perf8-missing-record-fields
  [record]
  (vec (remove #(perf-present? (get record %))
               perf8-required-record-fields)))

(defn perf8-fail!
  [id source-path manifest performance-claim record extra]
  (fail! id
         (case id
           "PERF8-LANE" "SIMD vectorization lacks lane-independence proof"
           "PERF8-ALIAS" "SIMD vectorization has illegal aliasing"
           "PERF8-BOUNDS" "SIMD vectorization lacks bounds proof"
           "PERF8-ALIGN" "SIMD vectorization lacks supported alignment or safe unaligned access"
           "PERF8-TAIL" "SIMD vectorization has invalid tail handling"
           "PERF8-NUMERIC" "SIMD vectorization violates numeric mode"
           "PERF8-MATH" "vector elementary function lacks math certificate"
           "PERF8-VOLATILE" "cache or vector transformation reorders volatile, MMIO, atomic, or synchronized access"
           "PERF8-INTRINSIC" "target intrinsic lacks feature guard or fallback"
           "PERF8-CACHE" "cache transformation lacks semantic or benchmark evidence"
           "SIMD/cache record is invalid")
         (merge {:source-span {:source source-path}
                 :profile (:profile manifest)
                 :target (:target manifest)
                 :target-request (:target performance-claim)
                 :loop-id (:loop record)
                 :vector-width (:vector-width record)
                 :operation (:operation record)
                 :missing-proof nil
                 :intrinsic (:intrinsics record)
                 :target-feature nil
                 :diagnostic-family :simd-cache-validation}
                extra)))

(defn perf8-intrinsic-invalid?
  [entry]
  (or (not (perf-present? (:source-operation entry)))
      (not (perf-present? (:target-intrinsic entry)))
      (not (perf-present? (:required-feature entry)))
      (not (perf-present? (:guard entry)))
      (not (perf-present? (:fallback entry)))))

(defn perf8-validate-record!
  [source-path manifest performance-claim record]
  (let [missing-fields (perf8-missing-record-fields record)
        proofs (set (:proofs record))
        missing-proofs (set/difference perf8-required-proofs proofs)
        alias (:alias-proof record)
        bounds (:bounds-proof record)
        alignment (:alignment-report record)
        cache (:cache-transformation record)
        invalid-intrinsic (first (filter perf8-intrinsic-invalid?
                                         (:intrinsic-map record)))]
    (when (or (seq missing-fields)
              (not= (:profile manifest) (:profile record))
              (not= (:profile performance-claim) (:profile record))
              (not= (:target performance-claim) (:target record))
              (contains? missing-proofs :lane-independence)
              (true? (get-in record [:lane-independence-report
                                     :loop-carried-dependency?]))
              (true? (get-in record [:lane-independence-report
                                     :hidden-side-effects?])))
      (perf8-fail! "PERF8-LANE" source-path manifest performance-claim
                   record
                   {:missing-fields missing-fields
                    :missing-proof
                    (cond-> #{}
                      (contains? missing-proofs :lane-independence)
                      (conj :lane-independence))
                    :remediation "Prove lane independence and reject loop-carried dependencies or hidden side effects before vectorization."}))
    (when (or (contains? missing-proofs :no-overlap)
              (false? (:legal? alias)))
      (perf8-fail! "PERF8-ALIAS" source-path manifest performance-claim
                   record
                   {:missing-proof :alias-proof
                    :remediation "Attach no-overlap alias evidence or keep the scalar form."}))
    (when (or (contains? missing-proofs :bounds-safe)
              (false? (:valid? bounds)))
      (perf8-fail! "PERF8-BOUNDS" source-path manifest performance-claim
                   record
                   {:missing-proof :vector-bounds-proof
                    :remediation "Prove every lane access is in range or emit a profile-legal runtime check."}))
    (when (or (false? (:target-supported? alignment))
              (and (false? (:aligned? alignment))
                   (not (true? (:safe-unaligned? alignment)))))
      (perf8-fail! "PERF8-ALIGN" source-path manifest performance-claim
                   record
                   {:missing-proof :alignment-or-safe-unaligned
                    :alignment (:alignment alignment)
                    :remediation "Record target-supported alignment or safe unaligned access support."}))
    (when-not (contains? perf8-valid-tail-handling (:tail-handling record))
      (perf8-fail! "PERF8-TAIL" source-path manifest performance-claim
                   record
                   {:tail-handling (:tail-handling record)
                    :remediation "Use scalar epilogue, mask, padding, or a multiple-of-width proof for vector tails."}))
    (when (or (false? (:numeric-mode-preserved? record))
              (and (= :strict-f32 (:numeric-mode record))
                   (true? (:reassociation? record))))
      (perf8-fail! "PERF8-NUMERIC" source-path manifest performance-claim
                   record
                   {:numeric-mode (:numeric-mode record)
                    :remediation "Strict numeric modes cannot reassociate or change elementary operations without explicit mode evidence."}))
    (when (and (seq (:elementary-functions record))
               (not (:exact-equivalence? record))
               (empty? (:math-certificates record)))
      (perf8-fail! "PERF8-MATH" source-path manifest performance-claim
                   record
                   {:missing-proof :math-certificate
                    :remediation "Vector elementary functions need accuracy or equivalence certificates."}))
    (when (or (true? (:volatile-reordered? record))
              (seq (:reordered-ordered-operations record)))
      (perf8-fail! "PERF8-VOLATILE" source-path manifest performance-claim
                   record
                   {:operation (:reordered-ordered-operations record)
                    :remediation "Do not reorder volatile, MMIO, atomic, synchronized, or capability-bearing operations for locality."}))
    (when invalid-intrinsic
      (perf8-fail! "PERF8-INTRINSIC" source-path manifest
                   performance-claim record
                   {:intrinsic (:target-intrinsic invalid-intrinsic)
                    :target-feature (:required-feature invalid-intrinsic)
                    :remediation "Target intrinsics require feature guards and fallback behavior."}))
    (when (or (not (perf-present? (:benchmark cache)))
              (not (true? (:effect-order-preserved? cache)))
              (not (true? (:synchronization-preserved? cache))))
      (perf8-fail! "PERF8-CACHE" source-path manifest performance-claim
                   record
                   {:missing-proof :cache-transformation-evidence
                    :remediation "Cache transformations must preserve semantics and attach benchmark or target evidence."}))
    :complete))

(defn perf9-normalize-contract
  [contract]
  (assoc contract
         :contract-id (or (:contract-id contract) (:id contract))))

(defn perf9-missing-contract-fields
  [contract]
  (vec (remove #(perf-present? (get contract %))
               perf9-required-contract-fields)))

(defn perf9-fail!
  [id source-path manifest performance-claim contract extra]
  (fail! id
         (case id
           "PERF9-BUDGET" "realtime latency budget is missing or exceeded"
           "PERF9-LOOP" "realtime path has unbounded loop behavior"
           "PERF9-RECURSION" "realtime path has unbounded recursion"
           "PERF9-ALLOC" "realtime path has forbidden or unbounded allocation"
           "PERF9-GC" "deterministic path uses managed runtime pauses"
           "PERF9-BLOCKING" "deterministic path has unbounded blocking"
           "PERF9-LOCK" "deterministic path has unbounded lock behavior"
           "PERF9-PREEMPTION" "realtime path lacks interrupt or preemption assumptions"
           "PERF9-EVIDENCE" "realtime contract lacks worst-case or bounded empirical evidence"
           "PERF9-OPTIMIZATION" "optimization introduces unpredictable latency"
           "realtime latency contract is invalid")
         (merge {:source-span {:source source-path}
                 :profile (:profile contract)
                 :target (:target contract)
                 :target-request (:target performance-claim)
                 :path-id (:contract-id contract)
                 :budget (:budget contract)
                 :operation (:operation contract)
                 :proof-id (:proof-id contract)
                 :failure-mode (:failure-mode contract)
                 :diagnostic-family :realtime-latency-validation}
                extra)))

(defn perf9-validate-contract!
  [source-path manifest performance-claim contract]
  (let [missing-fields (perf9-missing-contract-fields contract)
        budget (:budget contract)
        evidence-summary (:evidence-summary contract)
        bounds (:bounds contract)
        preemption (:preemption contract)
        locks (:locks contract)
        evidence (set (:evidence contract))]
    (when (or (seq missing-fields)
              (not= (:profile manifest) (:profile contract))
              (not= (:profile performance-claim) (:profile contract))
              (not= (:target performance-claim) (:target contract))
              (not (perf-present? (:max-us budget)))
              (> (or (:worst-case-us evidence-summary) 0)
                 (or (:max-us budget) 0))
              (> (or (:jitter-us evidence-summary) 0)
                 (or (:jitter-us budget) Long/MAX_VALUE)))
      (perf9-fail! "PERF9-BUDGET" source-path manifest performance-claim
                   contract
                   {:missing-fields missing-fields
                    :remediation "Declare max latency, jitter, profile, target, workload, and evidence that stays within budget."}))
    (when (or (false? (:loops-bounded? bounds))
              (not (perf-present? (:iterations bounds))))
      (perf9-fail! "PERF9-LOOP" source-path manifest performance-claim
                   contract
                   {:missing-proof :bounded-loop-proof
                    :remediation "Realtime loops need static bounds, bounded model evidence, timeout, or rejection."}))
    (when (and (:recursion? bounds)
               (not (perf-present? (:recursion-depth bounds))))
      (perf9-fail! "PERF9-RECURSION" source-path manifest
                   performance-claim contract
                   {:missing-proof :recursion-bound-proof
                    :remediation "Recursive realtime paths require maximum depth evidence."}))
    (when (contains? #{:unbounded-heap :unbounded-region :unknown}
                     (:allocation contract))
      (perf9-fail! "PERF9-ALLOC" source-path manifest performance-claim
                   contract
                   {:operation :allocation
                    :remediation "Use no allocation, stack/static allocation, or bounded regions, arenas, or pools."}))
    (when (or (:managed-runtime-pauses? contract)
              (contains? (set (:runtime-services contract)) :gc))
      (perf9-fail! "PERF9-GC" source-path manifest performance-claim
                   contract
                   {:operation :gc
                    :remediation "Managed runtime pauses must be outside the deterministic path or proven isolated."}))
    (when (or (true? (:blocking contract))
              (some #(not (perf-present? (:max-wait-us %)))
                    (:blocking-operations contract)))
      (perf9-fail! "PERF9-BLOCKING" source-path manifest
                   performance-claim contract
                   {:operation (:blocking-operations contract)
                    :remediation "Blocking operations in deterministic paths need bounded wait evidence or isolation."}))
    (when (or (not (perf-present? (:max-hold-us locks)))
              (not (perf-present? (:priority-inversion-policy locks))))
      (perf9-fail! "PERF9-LOCK" source-path manifest performance-claim
                   contract
                   {:operation :lock
                    :remediation "Realtime locks require maximum hold time and priority inversion policy."}))
    (when (or (not (perf-present? (:interrupt-policy preemption)))
              (not (perf-present? (:preemption-bound-us preemption))))
      (perf9-fail! "PERF9-PREEMPTION" source-path manifest
                   performance-claim contract
                   {:missing-proof :interrupt-preemption-assumptions
                    :remediation "Record interrupt and preemption assumptions for deterministic paths."}))
    (when (or (not (seq (set/intersection evidence
                                         #{:worst-case-path
                                           :bounded-empirical-latency})))
              (not (perf-present? (:target-fingerprint evidence-summary)))
              (not (perf-present? (:workload-fingerprint evidence-summary))))
      (perf9-fail! "PERF9-EVIDENCE" source-path manifest performance-claim
                   contract
                   {:missing-proof :worst-case-or-empirical-evidence
                    :remediation "Emit static worst-case path analysis or bounded empirical evidence tied to target and workload fingerprints."}))
    (when (true? (get-in contract [:optimization-effects
                                   :unpredictable-latency?]))
      (perf9-fail! "PERF9-OPTIMIZATION" source-path manifest
                   performance-claim contract
                   {:operation (:optimization-effects contract)
                    :remediation "Reject optimizations that introduce unbounded tail latency in deterministic paths."}))
    :complete))

(defn perf10-normalize-record
  [record]
  (assoc record
         :record-id (or (:record-id record) (:id record))))

(defn perf10-missing-record-fields
  [record]
  (vec (remove #(contains? record %)
               perf10-required-record-fields)))

(defn perf10-fail!
  [id source-path manifest performance-claim record extra]
  (fail! id
         (case id
           "PERF10-PROOF-MISSING" "check elision lacks a proof"
           "PERF10-DOMINANCE" "check-elision proof does not dominate the operation"
           "PERF10-INVALIDATED" "check-elision proof was invalidated"
           "PERF10-RESIDUAL" "required residual checks are missing"
           "PERF10-POLICY" "policy check was removed for performance"
           "PERF10-BACKEND" "backend cannot preserve check-elision assumptions"
           "PERF10-CERTIFICATE" "check-elision certificate is invalid"
           "PERF10-SOURCEMAP" "check-elision source mapping was lost"
           "check-elision record is invalid")
         (merge {:source-span {:source source-path}
                 :profile (:profile manifest)
                 :target (:target manifest)
                 :target-request (:target performance-claim)
                 :check-class (:check-class record)
                 :ir-node (:ir-node record)
                 :proof-id (:dominating-proof record)
                 :pass-id (:pass-id record)
                 :invalidating-pass (first (:invalidated-by record))
                 :diagnostic-family :check-elision-validation}
                extra)))

(defn perf10-validate-record!
  [source-path manifest performance-claim record]
  (let [missing-fields (perf10-missing-record-fields record)
        certificate (:certificate record)
        source-map (:source-map record)]
    (when (or (seq missing-fields)
              (not (perf-present? (:dominating-proof record))))
      (perf10-fail! "PERF10-PROOF-MISSING" source-path manifest
                    performance-claim record
                    {:missing-fields missing-fields
                     :remediation "Every erased check needs a named proof fact and complete elision record."}))
    (when-not (true? (:proof-dominates-use record))
      (perf10-fail! "PERF10-DOMINANCE" source-path manifest
                    performance-claim record
                    {:remediation "The proof must dominate the checked operation in the relevant IR."}))
    (when (and (seq (:invalidated-by record))
               (not (contains? #{:regenerated-proof :kept-check
                                 :rejected-no-checks}
                               (:invalidation-outcome record))))
      (perf10-fail! "PERF10-INVALIDATED" source-path manifest
                    performance-claim record
                    {:invalidated-by (:invalidated-by record)
                     :remediation "Invalidated proofs must be regenerated, keep the check, or reject no-checks compilation."}))
    (when (and (:residual-required? record)
               (empty? (:residual-checks record)))
      (perf10-fail! "PERF10-RESIDUAL" source-path manifest
                    performance-claim record
                    {:missing-proof :residual-check-report
                     :remediation "Emit narrower residual checks when proof covers only part of the condition."}))
    (when (and (contains? perf10-policy-check-classes
                          (:check-class record))
               (= :performance (:elision-reason record))
               (not (perf-present? (:equivalent-policy-artifact record))))
      (perf10-fail! "PERF10-POLICY" source-path manifest
                    performance-claim record
                    {:missing-proof :equivalent-policy-artifact
                     :remediation "Policy, unsafe-audit, replay, and human-review gates need equivalent policy artifacts, not speed-only removal."}))
    (when-not (true? (get-in record [:backend-preservation :preserves?]))
      (perf10-fail! "PERF10-BACKEND" source-path manifest
                    performance-claim record
                    {:backend-preservation (:backend-preservation record)
                     :remediation "Backend lowering must preserve proof assumptions or keep the check."}))
    (when-not (and (perf-present? (:certificate-id certificate))
                   (true? (:valid? certificate)))
      (perf10-fail! "PERF10-CERTIFICATE" source-path manifest
                    performance-claim record
                    {:certificate-id (:certificate-id certificate)
                     :remediation "Check-elision certificates must be valid and tied to the erased check."}))
    (when (or (not (perf-present? (:source-span source-map)))
              (not (perf-present? (:generated-origin source-map))))
      (perf10-fail! "PERF10-SOURCEMAP" source-path manifest
                    performance-claim record
                    {:missing-proof :source-map
                     :remediation "Preserve source span and generated-origin mapping for erased checks."}))
    :complete))

(defn realtime-governance-capability-proof
  [manifest performance-claim vector-records latency-contracts
   check-records]
  {:profile-legality-preserved?
   (and (every? #(= (:profile manifest) (:profile %)) vector-records)
        (every? #(= (:profile manifest) (:profile %)) latency-contracts)
        (every? #(= (:profile manifest) (:profile %)) check-records))
   :target-request-preserved?
   (and (every? #(= (:target performance-claim) (:target %))
                vector-records)
        (every? #(= (:target performance-claim) (:target %))
                latency-contracts)
        (every? #(= (:target performance-claim) (:target %))
                check-records))
   :vector-safety-proofs-preserved?
   (every? #(set/subset? perf8-required-proofs (set (:proofs %)))
           vector-records)
   :intrinsic-guards-recorded?
   (every? #(every? (complement perf8-intrinsic-invalid?)
                   (:intrinsic-map %))
           vector-records)
   :latency-bounds-proven?
   (every? #(and (true? (get-in % [:bounds :loops-bounded?]))
                 (perf-present? (get-in % [:bounds :iterations]))
                 (perf-present? (get-in % [:evidence-summary
                                            :target-fingerprint]))
                 (perf-present? (get-in % [:evidence-summary
                                            :workload-fingerprint])))
           latency-contracts)
   :runtime-services-isolated?
   (every? #(and (not (:managed-runtime-pauses? %))
                 (empty? (:runtime-services %)))
           latency-contracts)
   :check-elision-proof-backed?
   (every? #(and (perf-present? (:dominating-proof %))
                 (true? (:proof-dominates-use %))
                 (true? (get-in % [:certificate :valid?])))
           check-records)
   :policy-checks-preserved?
   (every? #(or (not (contains? perf10-policy-check-classes
                                (:check-class %)))
                (perf-present? (:equivalent-policy-artifact %)))
           check-records)
   :backend-preservation-recorded?
   (every? #(true? (get-in % [:backend-preservation :preserves?]))
           check-records)
   :status :complete})

(defn realtime-governance-source-artifact
  [source-path source-text]
  (let [performance-artifact (performance-source-artifact source-path
                                                          source-text)
        manifest (:profile-manifest performance-artifact)
        performance (get-in manifest [:metadata :performance] {})
        performance-claim (perf1-normalize-claim (:claim performance))
        suite (:realtime performance)
        vector-records (mapv perf8-normalize-record
                             (:vectorization-records suite))
        latency-contracts (mapv perf9-normalize-contract
                                (:latency-contracts suite))
        check-records (mapv perf10-normalize-record
                            (:check-elision-records suite))]
    (when (empty? vector-records)
      (perf8-fail! "PERF8-LANE" source-path manifest performance-claim
                   {:record-id (:suite-id suite)}
                   {:missing-fields [:vectorization-records]
                    :remediation "Provide at least one SIMD/cache vectorization record."}))
    (when (empty? latency-contracts)
      (perf9-fail! "PERF9-EVIDENCE" source-path manifest performance-claim
                   {:contract-id (:suite-id suite)}
                   {:missing-fields [:latency-contracts]
                    :remediation "Provide at least one realtime latency contract."}))
    (when (empty? check-records)
      (perf10-fail! "PERF10-PROOF-MISSING" source-path manifest
                    performance-claim {:record-id (:suite-id suite)}
                    {:missing-fields [:check-elision-records]
                     :remediation "Provide at least one proof-backed check-elision record."}))
    (doseq [record vector-records]
      (perf8-validate-record! source-path manifest performance-claim record))
    (doseq [contract latency-contracts]
      (perf9-validate-contract! source-path manifest performance-claim
                                contract))
    (doseq [record check-records]
      (perf10-validate-record! source-path manifest performance-claim
                               record))
    (let [capability-proof
          (realtime-governance-capability-proof
           manifest performance-claim vector-records latency-contracts
           check-records)
          conformance {:documents ["PERF8" "PERF9" "PERF10"]
                       :task "P04-T06"
                       :required-diagnostic-ids perf8-10-diagnostic-ids
                       :simd-cache-status :complete
                       :realtime-latency-status :complete
                       :check-elision-status :complete
                       :status :complete}]
      {:kind :gravity/stage0-realtime-governance-artifact
       :document-set ["PERF8" "PERF9" "PERF10"]
       :pass {:name :realtime-governance-validation
              :input :optimization-manifest
              :output :realtime-governance-report
              :requires [:performance-claim-validation
                         :simd-cache-legality
                         :latency-contract-validation
                         :check-elision-certificate-validation]
              :preserves [:source-spans :profile :target :effects
                          :capabilities :safety-mode :profile-legality
                          :proof-index :diagnostics :generated-origin-chain]
              :emits [:vector-legality-proof
                      :lane-independence-report
                      :alias-bounds-proof
                      :alignment-report
                      :lane-plan
                      :intrinsic-map
                      :cache-transformation-log
                      :tiling-prefetch-plan
                      :math-certificate-references
                      :latency-contract-manifest
                      :bounded-loop-proof
                      :recursion-bound-proof
                      :allocation-report
                      :blocking-lock-report
                      :interrupt-preemption-report
                      :worst-case-path-analysis
                      :bounded-empirical-latency-report
                      :check-elision-certificate
                      :dominating-proof-fact-list
                      :residual-check-report
                      :invalidated-proof-regeneration-log
                      :pass-decision-record
                      :backend-preservation-record
                      :realtime-governance-conformance-results]
              :rejects perf8-10-diagnostic-ids}
       :performance-artifact-hash (str "sha256:"
                                       (sha256-hex
                                        (pr-str performance-artifact)))
       :performance-contract-manifest
       (:performance-contract-manifest performance-artifact)
       :vector-legality-proof
       (mapv #(select-keys % [:record-id :loop :requires :proofs
                              :numeric-mode :vector-width])
             vector-records)
       :lane-independence-report
       (mapv #(select-keys % [:record-id :lane-independence-report
                              :lane-plan])
             vector-records)
       :alias-bounds-proof
       (mapv #(select-keys % [:record-id :alias-proof :bounds-proof])
             vector-records)
       :alignment-report
       (mapv #(select-keys % [:record-id :alignment-report])
             vector-records)
       :lane-plan
       (mapv #(select-keys % [:record-id :lane-plan :tail-handling])
             vector-records)
       :intrinsic-map
       (mapv #(select-keys % [:record-id :intrinsic-map])
             vector-records)
       :cache-transformation-log
       (mapv #(select-keys % [:record-id :cache-transformation])
             vector-records)
       :tiling-prefetch-plan
       (mapv #(select-keys % [:record-id :tiling-prefetch-plan])
             vector-records)
       :math-certificate-references
       (mapv #(select-keys % [:record-id :math-certificates])
             vector-records)
       :latency-contract-manifest
       (mapv #(select-keys % [:contract-id :profile :target :budget
                              :workload :allocation :blocking
                              :failure-mode])
             latency-contracts)
       :bounded-loop-proof
       (mapv #(select-keys % [:contract-id :bounds]) latency-contracts)
       :recursion-bound-proof
       (mapv #(select-keys % [:contract-id :bounds]) latency-contracts)
       :allocation-report
       (mapv #(select-keys % [:contract-id :allocation])
             latency-contracts)
       :blocking-lock-report
       (mapv #(select-keys % [:contract-id :blocking :blocking-operations
                              :locks])
             latency-contracts)
       :interrupt-preemption-report
       (mapv #(select-keys % [:contract-id :preemption])
             latency-contracts)
       :worst-case-path-analysis
       (mapv #(select-keys % [:contract-id :worst-case-path-analysis
                              :evidence-summary])
             latency-contracts)
       :bounded-empirical-latency-report
       (mapv #(select-keys % [:contract-id :bounded-empirical-latency
                              :evidence-summary])
             latency-contracts)
       :check-elision-certificate
       (mapv #(select-keys % [:record-id :check-class :operation
                              :certificate])
             check-records)
       :dominating-proof-fact-list
       (mapv #(select-keys % [:record-id :dominating-proof
                              :proof-dominates-use])
             check-records)
       :residual-check-report
       (mapv #(select-keys % [:record-id :residual-checks
                              :residual-required?])
             check-records)
       :invalidated-proof-regeneration-log
       (mapv #(select-keys % [:record-id :invalidated-by
                              :invalidation-outcome])
             check-records)
       :pass-decision-record
       (mapv #(select-keys % [:record-id :pass-id :elision-reason
                              :equivalent-policy-artifact])
             check-records)
       :backend-preservation-record
       (mapv #(select-keys % [:record-id :backend-preservation])
             check-records)
       :capability-based-proof capability-proof
       :realtime-governance-conformance-results conformance
       :diagnostics []})))

(def numeric-required-families
  #{:fixed-integer :bigint :ratio :real :float :complex
    :interval :symbolic :quantity})

(def numeric-allocation-sensitive-families
  #{:bigint :ratio})

(def numeric-constrained-profiles
  #{:firmware :kernel :hardware})

(def numeric-conversion-modes
  #{:widening-exact :checked-narrowing :saturating :wrapping
    :explicitly-rounded :approximate-with-error-record :proof-backed
    :unsafe-reinterpretation})

(def numeric-standard-modes
  #{:exact :checked :wrapping :saturating :symbolic :exact-real
    :interval :correctly-rounded :faithful :certified-approx
    :relaxed :fast-approx :hardware-native :libm :eml-normalized})

(def numeric-floating-or-approx-modes
  #{:correctly-rounded :faithful :certified-approx :relaxed
    :fast-approx :hardware-native :libm})

(def numeric-result-quality-fields
  [:absolute-error-max :relative-error-max :ulp-max
   :correct-rounding-target :faithful-rounding-target
   :interval-width :symbolic-exactness])

(def numeric-supported-rounding-policies
  #{:nearest-even :nearest-ties-to-even :nearest-ties-away
    :toward-zero :toward-positive-infinity :toward-negative-infinity
    :stochastic})

(def numeric-supported-floating-formats
  #{:binary16 :bfloat16 :binary32 :binary64 :binary128
    :decimal32 :decimal64 :decimal128})

(def numeric-supported-denormal-policies
  #{:preserve :flush-inputs-to-zero :flush-results-to-zero
    :flush-all :target-native-explicit})

(def numeric-default-kind-lattice
  (mapv (fn [family] {:family family :explicit? true})
        [:fixed-integer :bigint :ratio :real :float :complex
         :interval :symbolic :quantity]))

(def numeric-default-profile-support-matrix
  [{:profile :core :target :portable :family :fixed-integer
