  [{:claim-id :symbolic/sin-square-plus-cos-square
    :claimed-equal? true
    :lhs '(+ (* (sin x) (sin x)) (* (cos x) (cos x)))
    :rhs 1
    :domain {'x {:real [-3.1415927 3.1415927]}}
    :proof :proof/trig-identity-interval
    :source-span "math/numeric.gravity:30:1"}])

(defn numeric-mode-suite
  [manifest]
  (let [source-suite (get-in manifest [:metadata :math :numeric] {})]
    (assoc source-suite
           :numeric-kind-lattice
           (or (:numeric-kind-lattice source-suite)
               numeric-default-kind-lattice)
           :profile-support-matrix
           (vec (concat numeric-default-profile-support-matrix
                        (:profile-support-matrix source-suite)))
           :conversion-rules
           (if (contains? source-suite :conversion-rules)
             (vec (:conversion-rules source-suite))
             numeric-default-conversion-rules)
           :mode-records
           (if (contains? source-suite :mode-records)
             (vec (:mode-records source-suite))
             numeric-default-mode-records)
           :floating-manifests
           (if (contains? source-suite :floating-manifests)
             (vec (:floating-manifests source-suite))
             numeric-default-floating-manifests)
           :provider-eligibility
           (if (contains? source-suite :provider-eligibility)
             (vec (:provider-eligibility source-suite))
             numeric-default-provider-eligibility)
           :efir-numeric-annotations
           (if (contains? source-suite :efir-numeric-annotations)
             (vec (:efir-numeric-annotations source-suite))
             numeric-default-efir-annotations)
           :symbolic-equality-claims
           (if (contains? source-suite :symbolic-equality-claims)
             (vec (:symbolic-equality-claims source-suite))
             numeric-default-symbolic-equality-claims))))

(defn numeric-fail!
  [id source-path manifest record extra]
  (fail! id
         (case id
           "MATH1-FAMILY" "numeric family is unavailable or not explicit"
           "MATH1-CONVERSION" "numeric conversion rule is missing or illegal"
           "MATH1-NARROW" "implicit narrowing conversion is rejected"
           "MATH1-PRECISION" "numeric conversion loses precision without evidence"
           "MATH1-ROUNDING" "numeric conversion is missing rounding policy"
           "MATH1-BRANCH" "complex or elementary conversion lacks branch policy"
           "MATH1-ALLOCATION" "allocation-heavy numeric family lacks bounded provider support"
           "MATH1-EQUALITY" "symbolic equality was claimed without proof"
           "MATH1-PROFILE" "numeric family or mode is not supported by the active profile"
           "MATH7-MISSING" "numeric mode or precision contract is missing"
           "MATH7-SCOPE" "numeric mode inheritance is ambiguous or conflicting"
           "MATH7-DOWNGRADE" "numeric mode weakening lacks authorization"
           "MATH7-TARGET-DEFAULT" "target-default numeric behavior is not a portable contract"
           "MATH7-PRECISION" "precision contract is incomplete or impossible"
           "MATH7-PROVIDER" "selected numeric provider is not mode eligible"
           "MATH7-ROUNDING" "numeric mode record lacks rounding policy"
           "MATH7-EXCEPTIONAL" "numeric mode record lacks exceptional-value policy"
           "MATH7-RESIDUAL" "residual runtime checks are not allowed by the numeric mode"
           "MATH8-MANIFEST" "floating manifest is missing or incomplete"
           "MATH8-FORMAT" "floating format is unavailable or mismatched"
           "MATH8-ROUNDING" "floating rounding policy is missing or unsupported"
           "MATH8-NAN" "NaN behavior is unspecified"
           "MATH8-INF" "infinity behavior is unspecified"
           "MATH8-ZERO" "signed-zero behavior is unspecified or mismatched"
           "MATH8-DENORMAL" "denormal behavior is unspecified"
           "MATH8-FMA" "FMA contraction is illegal under the active manifest"
           "MATH8-REASSOC" "floating reassociation is illegal under the active manifest"
           "MATH8-STATUS" "observable floating status behavior is not preserved"
           "MATH8-BACKEND" "backend lowering cannot satisfy the floating manifest"
           "numeric mode record is invalid")
         (merge {:source-span (or (:source-span record)
                                  {:source source-path})
                 :profile (or (:profile record) (:profile manifest))
                 :target (or (:target record) (:target manifest))
                 :numeric-family (or (:family record)
                                     (:source-family record)
                                     (:target-family record))
                 :numeric-mode (or (:math/mode record)
                                   (:numeric-mode record)
                                   (:mode record))
                 :conversion-mode (:conversion-mode record)
                 :rounding-policy (or (:rounding record)
                                      (:rounding-policy record))
                 :provider (:provider record)
                 :operation (or (:operation record) (:record-id record))
                 :manifest-id (or (:manifest-id record)
                                  (:operation record))
                 :diagnostic-family :numeric-mode-validation}
                extra)))

(defn numeric-family-set
  [suite]
  (set (map :family (:numeric-kind-lattice suite))))

(defn numeric-support-row?
  [row profile target family]
  (and (= profile (:profile row))
       (= family (:family row))
       (true? (:available? row))
       (or (= target (:target row))
           (= :portable (:target row)))))

(defn numeric-family-supported?
  [suite profile target family]
  (boolean
   (some #(numeric-support-row? % profile target family)
         (:profile-support-matrix suite))))

(defn numeric-floating-conversion?
  [rule]
  (or (= :float (:source-family rule))
      (= :float (:target-family rule))
      (= :floating (:kind rule))
      (contains? numeric-floating-or-approx-modes (:numeric-mode rule))))

(defn numeric-complex-or-elementary-conversion?
  [rule]
  (or (= :complex (:source-family rule))
      (= :complex (:target-family rule))
      (= :elementary (:kind rule))
      (:elementary-operation rule)))

(defn numeric-precision-contract-meaningful?
  [precision]
  (boolean
   (some #(perf-present? (get precision %))
         numeric-result-quality-fields)))

(defn numeric-mode-value
  [record]
  (or (:math/mode record) (:mode record) (:numeric-mode record)))

(defn numeric-floating-mode-record?
  [record]
  (or (contains? numeric-floating-or-approx-modes (numeric-mode-value record))
      (= :float (:family record))
      (perf-present? (:floating-manifest record))))

(defn numeric-mode-record-complete?
  [record]
  (and (perf-present? (numeric-mode-value record))
       (perf-present? (:scope record))
       (perf-present? (:precision record))))

(defn numeric-required-floating-manifest-fields
  []
  [:operation :format :rounding :numeric-mode :precision :exceptions
   :nan :infinity :signed-zero :denormals :status-flags :fma
   :reassociation :reciprocal-substitution :determinism])

(defn numeric-missing-floating-fields
  [manifest]
  (vec (remove #(contains? manifest %)
               (numeric-required-floating-manifest-fields))))

(defn numeric-strict-floating-mode?
  [mode]
  (contains? #{:strict :correctly-rounded :faithful
               :certified-approx :exact} mode))

(defn numeric-validate-math1!
  [source-path manifest suite]
  (let [families (numeric-family-set suite)
        conversions (:conversion-rules suite)
        symbolic-claims (:symbolic-equality-claims suite)]
    (when-not (set/subset? numeric-required-families families)
      (numeric-fail! "MATH1-FAMILY" source-path manifest {}
                     {:missing-families
                      (set/difference numeric-required-families families)
                      :remediation "Emit every numeric family in the numeric kind lattice."}))
    (doseq [row (:profile-support-matrix suite)]
      (when (and (numeric-constrained-profiles (:profile row))
                 (numeric-allocation-sensitive-families (:family row))
                 (true? (:available? row))
                 (= :unbounded (:allocation row))
                 (not (perf-present? (:provider-bounds row))))
        (numeric-fail! "MATH1-ALLOCATION" source-path manifest row
                       {:remediation "Constrained profiles need bounded provider evidence or must reject BigInt and Ratio."})))
    (when (empty? conversions)
      (numeric-fail! "MATH1-CONVERSION" source-path manifest {}
                     {:missing-fields [:conversion-rules]
                      :remediation "Provide explicit conversion rules for the numeric tower."}))
    (doseq [rule conversions]
      (when (or (:implicit? rule)
                (= :implicit-narrowing (:class rule))
                (= :implicit (:conversion-mode rule)))
        (numeric-fail! "MATH1-NARROW" source-path manifest rule
                       {:remediation "Use checked, rounded, saturating, wrapping, proof-backed, or unsafe conversion syntax."}))
      (when (or (not (perf-present? (:source-family rule)))
                (not (perf-present? (:target-family rule)))
                (not (contains? numeric-conversion-modes
                                (:conversion-mode rule))))
        (numeric-fail! "MATH1-CONVERSION" source-path manifest rule
                       {:missing-fields
                        (cond-> []
                          (not (perf-present? (:source-family rule)))
                          (conj :source-family)
                          (not (perf-present? (:target-family rule)))
                          (conj :target-family)
                          (not (contains? numeric-conversion-modes
                                          (:conversion-mode rule)))
                          (conj :conversion-mode))
                        :remediation "Classify conversions with one of the MATH1 conversion classes."}))
      (when (and (:precision-loss? rule)
                 (not (or (perf-present? (:error-record rule))
                          (perf-present? (:proof rule)))))
        (numeric-fail! "MATH1-PRECISION" source-path manifest rule
                       {:remediation "Precision loss needs an error record or proof-backed conversion."}))
      (when (and (numeric-floating-conversion? rule)
                 (not (perf-present? (:rounding rule))))
        (numeric-fail! "MATH1-ROUNDING" source-path manifest rule
                       {:remediation "Float and approximate conversions must declare rounding policy."}))
      (when (and (numeric-complex-or-elementary-conversion? rule)
                 (not (perf-present? (:branch-policy rule))))
        (numeric-fail! "MATH1-BRANCH" source-path manifest rule
                       {:remediation "Complex and elementary conversions must declare branch and domain policy."}))
      (when (or (not (numeric-family-supported? suite (:profile rule)
                                                (:target rule)
                                                (:source-family rule)))
                (not (numeric-family-supported? suite (:profile rule)
                                                (:target rule)
                                                (:target-family rule))))
        (numeric-fail! "MATH1-PROFILE" source-path manifest rule
                       {:remediation "The active profile and target must support both numeric families used by the conversion."})))
    (doseq [claim symbolic-claims]
      (when (and (:claimed-equal? claim)
                 (not (perf-present? (:proof claim))))
        (numeric-fail! "MATH1-EQUALITY" source-path manifest claim
                       {:remediation "Symbolic or elementary equality requires a proof, interval argument, rewrite certificate, or approximation certificate."})))
    :complete))

(defn numeric-validate-math7!
  [source-path manifest suite]
  (let [records (:mode-records suite)
        grouped (group-by :scope records)]
    (when (empty? records)
      (numeric-fail! "MATH7-MISSING" source-path manifest {}
                     {:missing-fields [:mode-records]
                      :remediation "Emit at least one resolved numeric mode record with a precision contract."}))
    (doseq [[scope scoped] grouped]
      (when (and (perf-present? scope)
                 (> (count (set (map numeric-mode-value scoped))) 1)
                 (not (every? :mode-change scoped)))
        (numeric-fail! "MATH7-SCOPE" source-path manifest (first scoped)
                       {:scope scope
                        :remediation "Conflicting inherited numeric modes require an explicit mode-change trace."})))
    (doseq [record records]
      (let [mode (numeric-mode-value record)
            precision (:precision record)]
        (when (or (not (numeric-mode-record-complete? record))
                  (and mode
                       (not= :target-default mode)
                       (not (contains? numeric-standard-modes mode))))
          (numeric-fail! "MATH7-MISSING" source-path manifest record
                         {:missing-fields
                          (cond-> []
                            (not (perf-present? mode)) (conj :math/mode)
                            (not (perf-present? (:scope record)))
                            (conj :scope)
                            (not (perf-present? precision))
                            (conj :precision))
                          :remediation "Numeric mode records need mode, scope, domain, precision, rounding, exceptional policy, and certificate facts."}))
        (when (and (= :weakening (get-in record [:mode-change :kind]))
                   (not (true? (get-in record [:mode-change :approved?]))))
          (numeric-fail! "MATH7-DOWNGRADE" source-path manifest record
                         {:inherited-mode (get-in record [:mode-change
                                                          :from])
                          :local-override (get-in record [:mode-change :to])
                          :remediation "Mode weakening needs explicit source or package policy authorization and an artifacted downgrade record."}))
        (when (or (= :target-default mode)
                  (= :target-native (:rounding record))
                  (= :target-native (:rounding-policy record)))
          (numeric-fail! "MATH7-TARGET-DEFAULT" source-path manifest record
                         {:remediation "Replace target-default behavior with an explicit hardware-native, libm, or target-contract mode record."}))
        (when (and (numeric-floating-mode-record? record)
                   (not (numeric-precision-contract-meaningful? precision)))
          (numeric-fail! "MATH7-PRECISION" source-path manifest record
                         {:precision precision
                          :remediation "Approximate or floating modes need an absolute, relative, ulp, interval, faithful, or correct-rounding quality field."}))
        (when (and (numeric-floating-mode-record? record)
                   (not (perf-present? (:rounding record))))
          (numeric-fail! "MATH7-ROUNDING" source-path manifest record
                         {:remediation "Floating and approximate mode records must declare rounding policy."}))
        (when (and (numeric-floating-mode-record? record)
                   (not (perf-present? (:float-exceptions record))))
          (numeric-fail! "MATH7-EXCEPTIONAL" source-path manifest record
                         {:remediation "Floating and approximate mode records must declare NaN, infinity, signed-zero, and denormal behavior."}))
        (when (and (seq (:residual-checks record))
                   (false? (:residual-allowed? record)))
          (numeric-fail! "MATH7-RESIDUAL" source-path manifest record
                         {:remediation "Residual checks must be allowed by the active mode or rejected."}))))
    (doseq [provider (:provider-eligibility suite)]
      (when (and (:selected? provider)
                 (not (true? (:eligible? provider))))
        (numeric-fail! "MATH7-PROVIDER" source-path manifest provider
                       {:remediation "Provider selection must satisfy profile, target, numeric mode, precision, branch, certificate, allocation, effects, and capabilities."})))
    :complete))

(defn numeric-validate-math8!
  [source-path manifest suite]
  (let [floating-manifests (:floating-manifests suite)]
    (when (empty? floating-manifests)
      (numeric-fail! "MATH8-MANIFEST" source-path manifest {}
                     {:missing-fields [:floating-manifests]
                      :remediation "Emit at least one floating manifest for floating operations."}))
    (doseq [floating floating-manifests]
      (let [missing-fields (numeric-missing-floating-fields floating)
            mode (:numeric-mode floating)
            backend (:backend-lowering floating)]
        (when (seq missing-fields)
          (numeric-fail! "MATH8-MANIFEST" source-path manifest floating
                         {:missing-fields missing-fields
                          :remediation "Floating manifests must expose format, rounding, exceptional values, status, determinism, and transform policy."}))
        (when-not (contains? numeric-supported-floating-formats
                             (:format floating))
          (numeric-fail! "MATH8-FORMAT" source-path manifest floating
                         {:format (:format floating)
                          :remediation "Declare a supported binary, decimal, bfloat, or accelerator format with target availability."}))
        (when-not (contains? numeric-supported-rounding-policies
                             (:rounding floating))
          (numeric-fail! "MATH8-ROUNDING" source-path manifest floating
                         {:remediation "Use a supported floating rounding policy and map it to the target."}))
        (when-not (and (perf-present? (get-in floating [:nan :quiet]))
                       (perf-present? (get-in floating [:nan
                                                        :signaling])))
          (numeric-fail! "MATH8-NAN" source-path manifest floating
                         {:remediation "NaN behavior must distinguish quiet, signaling, and payload policy where observable."}))
        (when-not (perf-present? (:infinity floating))
          (numeric-fail! "MATH8-INF" source-path manifest floating
                         {:remediation "Infinity behavior must be explicit."}))
        (when-not (contains? #{:preserve :collapse-explicit
                               :not-observable}
                             (:signed-zero floating))
          (numeric-fail! "MATH8-ZERO" source-path manifest floating
                         {:remediation "Signed-zero behavior must be preserved or explicitly made unobservable by mode."}))
        (when (or (not (contains? numeric-supported-denormal-policies
                                  (:denormals floating)))
                  (and (= :target-native-explicit (:denormals floating))
                       (not (perf-present? (:target-contract floating)))))
          (numeric-fail! "MATH8-DENORMAL" source-path manifest floating
                         {:remediation "Denormal and flush behavior must be explicit and tied to a target contract when target-native."}))
        (when (and (numeric-strict-floating-mode? mode)
                   (contains? #{:allowed :contract :contract-fma}
                              (:fma floating))
                   (not (or (perf-present? (:proof floating))
                            (perf-present? (:certificate floating)))))
          (numeric-fail! "MATH8-FMA" source-path manifest floating
                         {:remediation "Strict modes forbid FMA contraction unless proof or certificate preserves the manifest."}))
        (when (and (numeric-strict-floating-mode? mode)
                   (= :allowed (:reassociation floating))
                   (not (or (perf-present? (:proof floating))
                            (perf-present? (:certificate floating)))))
          (numeric-fail! "MATH8-REASSOC" source-path manifest floating
                         {:remediation "Strict modes forbid reassociation unless proof or certificate preserves the manifest."}))
        (when (and (= :observable-through-declared-api
                      (:status-flags floating))
                   (false? (get-in backend [:status-preserved?])))
          (numeric-fail! "MATH8-STATUS" source-path manifest floating
                         {:remediation "Lowering and optimization must preserve observable floating status behavior."}))
        (when (or (false? (:preserves-manifest? backend))
                  (and (false? (:eligible? backend))
                       (not (perf-present? (:fallback backend)))))
          (numeric-fail! "MATH8-BACKEND" source-path manifest floating
                         {:remediation "Backend lowering must preserve the manifest, select a legal fallback, or reject compilation."}))))
    :complete))

(defn numeric-mode-capability-proof
  [suite]
  {:numeric-families-explicit?
   (set/subset? numeric-required-families (numeric-family-set suite))
   :conversion-classes-explicit?
   (every? #(contains? numeric-conversion-modes (:conversion-mode %))
           (:conversion-rules suite))
   :implicit-narrowing-rejected? true
   :symbolic-equality-proof-backed?
   (every? #(or (not (:claimed-equal? %))
                (perf-present? (:proof %)))
           (:symbolic-equality-claims suite))
   :mode-contracts-explicit?
   (every? numeric-mode-record-complete? (:mode-records suite))
   :provider-selection-mode-checked?
   (every? #(or (not (:selected? %)) (true? (:eligible? %)))
           (:provider-eligibility suite))
   :floating-manifests-complete?
   (every? #(empty? (numeric-missing-floating-fields %))
           (:floating-manifests suite))
   :target-defaults-rejected? true
   :capability-authority-preserved? true
   :status :complete})

(defn numeric-mode-source-artifact
  [source-path source-text]
  (let [manifest-artifact (profile-manifest-source-artifact source-path
                                                            source-text)
        manifest (:profile-manifest manifest-artifact)
        suite (numeric-mode-suite manifest)
        _ (numeric-validate-math1! source-path manifest suite)
        _ (numeric-validate-math7! source-path manifest suite)
        _ (numeric-validate-math8! source-path manifest suite)
        capability-proof (numeric-mode-capability-proof suite)
        conformance {:documents ["MATH1" "MATH7" "MATH8"]
                     :task "P05-T01"
                     :required-diagnostic-ids math1-7-8-diagnostic-ids
                     :numeric-tower-status :complete
                     :numeric-mode-status :complete
                     :floating-manifest-status :complete
                     :status :complete}]
    {:kind :gravity/stage0-numeric-mode-artifact
     :document-set ["MATH1" "MATH7" "MATH8"]
     :pass {:name :numeric-mode-validation
            :input :profile-manifest
            :output :numeric-mode-table
            :requires [:reader :namespace-analyzer :macro-expansion
                       :core-lowering :type-effect-capability-check
                       :profile-manifest-validation]
            :preserves [:source-spans :profile :target :effects
                        :capabilities :safety-mode :profile-legality
                        :numeric-mode :precision-contract
                        :floating-manifest]
            :emits [:numeric-kind-lattice
                    :conversion-rule-table
                    :profile-support-matrix
                    :numeric-mode-environment
                    :precision-contract-table
                    :mode-inheritance-trace
                    :provider-mode-eligibility-report
                    :floating-manifest
                    :target-format-map
                    :rounding-exception-policy-table
                    :efir-numeric-annotations
                    :symbolic-equality-proof-table
                    :numeric-conformance-results]
            :rejects math1-7-8-diagnostic-ids}
     :profile-manifest-artifact-hash (str "sha256:"
                                          (sha256-hex
                                           (pr-str manifest-artifact)))
     :profile-manifest manifest
     :numeric-kind-lattice (:numeric-kind-lattice suite)
     :conversion-rule-table (:conversion-rules suite)
     :profile-support-matrix (:profile-support-matrix suite)
     :numeric-mode-environment (:mode-records suite)
     :precision-contract-table
     (mapv #(select-keys % [:record-id :scope :domain :precision
                            :rounding :float-exceptions])
           (:mode-records suite))
     :mode-inheritance-trace
     (mapv #(select-keys % [:record-id :scope :inherited-mode
                            :local-override :mode-change])
           (:mode-records suite))
     :provider-mode-eligibility-report (:provider-eligibility suite)
     :floating-manifest (:floating-manifests suite)
     :target-format-map numeric-default-target-format-map
     :rounding-exception-policy-table
     (mapv #(select-keys % [:operation :rounding :exceptions :nan
                            :infinity :signed-zero :denormals
                            :status-flags])
           (:floating-manifests suite))
     :efir-numeric-annotations (:efir-numeric-annotations suite)
     :symbolic-equality-proof-table (:symbolic-equality-claims suite)
     :capability-based-proof capability-proof
     :numeric-conformance-results conformance
     :diagnostics []}))

(def efir-supported-elementary-ops
  #{:sin :cos :exp :log :sqrt :pow :tanh :sigmoid})

(def efir-node-ops
  #{:const :var :arith :call :let :piecewise :constraint :eml})

(def efir-default-declarations
  [{:function-id :math/sigmoid
    :source-span "math/efir.gravity:8:1"
    :domain {'x {:real [-8.0 8.0]}}
    :codomain {:real [0.0 1.0]}
    :branch-policy :real-only
    :exceptional-values {:nan :propagate
                         :inf :saturate-by-mode}
    :semantic-form '(/ 1 (+ 1 (exp (- x))))
    :numeric-modes #{:exact :faithful :certified-approx}
    :provider-requirements #{:domain :codomain :branch-policy
                             :numeric-mode :precision :certificate}
    :efir-anchor :efir/sigmoid
    :status :complete}])

