(def compiler-pass-default-diagnostic-schema
  {:artifact :gravity/diagnostic-schema
   :required-fields [:rule :severity :primary :related :origin-chain :stage
                     :profile :target :artifacts :facts :remediation
                     :redactions :ordering-key]
   :supported-severities [:error :warning :info :hint :internal-error]
   :renderers [:cli :ide :ci]
   :deterministic-ordering? true
   :secret-redaction? true})

(def compiler-pass-default-diagnostic-catalog
  (mapv (fn [id]
          {:rule id
           :severity :error
           :message-key (keyword "compiler" (str/lower-case id))
           :lifecycle :active})
        compiler-pass-diagnostic-ids))

(def compiler-pass-default-diagnostic-fixtures
  [{:rule "C1-PASS-CONTRACT"
    :diagnostic-id "diag/c1-pass-contract-stage0"
    :severity :error
    :stage :pass-contract-validate
    :primary {:span "compiler/passes.gravity:1:1"
              :artifact :pass-contract/build-mir}
    :related [{:role :pass-contract
               :artifact :pass-contract/build-mir}]
    :origin-chain [{:kind :source
                    :span "compiler/passes.gravity:1:1"}]
    :profile :meta
    :target :jvm
    :artifacts [:pass-contract/build-mir]
    :facts {:missing-field :output}
    :remediation [{:kind :complete-pass-contract}]
    :redactions []
    :secret-free? true
    :ordering-key ["C1" 1]}
   {:rule "C15-ORIGIN"
    :diagnostic-id "diag/c15-origin-generated-stage0"
    :severity :error
    :stage :diagnostic-validate
    :primary {:span "generated:gravity.compiler/pass:1"
              :artifact :diagnostic/generated}
    :related [{:role :generated-by
               :span "compiler/passes.gravity:2:1"}]
    :origin-chain [{:kind :generated
                    :producer :gravity.compiler/pass
                    :inputs [:syntax/pass-contract]}]
    :profile :meta
    :target :jvm
    :artifacts [:diagnostic/generated]
    :facts {:origin-chain :present}
    :remediation [{:kind :preserve-generated-origin}]
    :redactions []
    :secret-free? true
    :ordering-key ["C15" 1]}])

(def compiler-pass-default-cache-key-schema
  {:artifact :gravity/cache-key-schema
   :required-fields [:stage :source :syntax :profile :target :compiler
                     :pass-contract :dependencies :build-effects
                     :capabilities :language-facets]})

(def compiler-pass-default-cache-keys
  [{:stage :type-check
    :source "sha256:stage0-source"
    :syntax "sha256:stage0-syntax"
    :profile "sha256:stage0-profile"
    :target "sha256:stage0-target"
    :compiler "sha256:stage0-clojure-bootstrap"
    :pass-contract "sha256:stage0-type-check-contract"
    :dependencies "sha256:stage0-dependency-graph"
    :build-effects "sha256:stage0-build-replay"
    :capabilities "sha256:stage0-capability-policy"
    :language-facets "sha256:stage0-facets"}])

(def compiler-pass-default-cache-entries
  [{:stage :type-check
    :cache-key "sha256:stage0-type-check-cache-key"
    :artifact-id "sha256:stage0-typed-core"
    :producer {:stage :type-check :pass-version "stage0"}
    :inputs ["sha256:stage0-core"]
    :preserved-facts [:source-spans :resolved-bindings]
    :invalidated-by [:source-change :type-rule-change :profile-change]
    :diagnostics "sha256:stage0-type-diagnostics"
    :trust :local-build
    :revalidation :required-before-release}])

(def compiler-pass-default-proof-reuse-records
  [{:proof-id :proof/stage0-bounds
    :claim :bounds-preserved
    :inputs ["sha256:stage0-mir-op"]
    :profile :native
    :target :jvm
    :status :fresh
    :reuse :accepted
    :invalidation-conditions [:source-change :safety-rule-change
                              :target-change]}])

(def compiler-pass-default-speculative-reuse-records
  [{:artifact-id "sha256:stage0-speculative-expansion"
    :stage :macro-expand
    :reuse :speculative
    :publishable? false
    :revalidation :required-before-release}])

(def compiler-pass-default-plugin-manifest
  {:artifact :gravity/compiler-plugin
   :plugin 'gravity.compiler.stage0/pass-audit
   :package {:name 'gravity/compiler-pass-audit :version "0.1.0"}
   :api-version "1"
   :compiler-compatibility {:min "0.1.0" :max-exclusive "0.2.0"}
   :trust :sandboxed
   :profile :meta
   :build-effects #{}
   :capabilities #{:compiler/ir-transform}
   :capability-scopes {:compiler/ir-transform
                       #{:read-mir :write-mir :emit-artifacts
                         :emit-diagnostics :register-pass}}
   :requested-scopes #{:read-mir :write-mir :emit-diagnostics}
   :passes [:plugin/stage0-audit]
   :domains []
   :facets []
   :emits #{:plugin-execution-trace}
   :conformance [:compiler-pass-contract-fixtures]})

(def compiler-pass-default-plugin-pass-contracts
  [(assoc (compiler-pass-contract
           :plugin/stage0-audit :C17 :verified-mir :verified-mir
           [:mir-verifier-report :plugin-grants]
           [:source-spans :origin-chain :profile :target :types :effects
            :ownership :capabilities :safety-outcomes :proofs :diagnostics]
           []
           [:plugin-execution-trace]
           [:plugin-execution-trace :verifier-report]
           ["C17-PASS-CONTRACT" "C17-OUTPUT"] :medium
           [:contract-verifier :fixture-suite])
          :capabilities #{:compiler/ir-transform})])

(def compiler-pass-default-plugin-execution-traces
  [{:artifact :gravity/plugin-execution
    :plugin 'gravity.compiler.stage0/pass-audit
    :pass :plugin/stage0-audit
    :input "sha256:stage0-verified-mir"
    :output "sha256:stage0-verified-mir-audited"
    :grants "sha256:stage0-plugin-grants"
    :build-effects []
    :decisions [:decision/stage0-plugin-audit]
    :diagnostics []
    :verifier-result :passed}])

(defn compiler-pass-default-risk-classification
  [contracts]
  (mapv (fn [contract]
          {:pass (:pass contract)
           :risk (:risk contract)
           :reason #{:stage0-pass-contract}
           :affected-profiles (:profiles contract)
           :affected-targets #{:jvm}
           :minimum-evidence (set (:evidence-class contract))
           :available-evidence (set (:evidence-class contract))
           :release-gate (if (#{:critical :high} (:risk contract))
                           :required
                           :verifier-only)})
        contracts))

(defn compiler-pass-default-trust-report
  [contracts risk-records]
  {:artifact :gravity/compiler-trust-report
   :compiler :gravity-stage0-clojure-bootstrap
   :passes (mapv #(select-keys % [:pass :risk :available-evidence])
                 risk-records)
   :profiles {:meta {:required-evidence :high
                     :blocked-passes []}}
   :known-gaps []
   :covered-passes (mapv :pass contracts)})

(def compiler-pass-default-release-gate-report
  {:artifact :gravity/compiler-release-gate
   :status :passed
   :evidence-gaps []
   :blocked-passes []
   :release-artifacts [:pass-contract-manifest]})

(defn compiler-pass-merge-record-overrides
  [defaults overrides id-key]
  (if (seq overrides)
    (let [by-id (into {} (map (juxt id-key identity) overrides))]
      (mapv #(merge % (get by-id (get % id-key) {})) defaults))
    defaults))

(defn compiler-pass-suite
  [manifest]
  (let [source-suite (get-in manifest [:metadata :compiler :passes] {})
        map-value (fn [key override-key default]
                    (cond
                      (contains? source-suite key) (get source-suite key)
                      (contains? source-suite override-key)
                      (merge default (get source-suite override-key))
                      :else default))
        vector-value (fn [key override-key defaults id-key]
                       (cond
                         (contains? source-suite key) (vec (get source-suite key))
                         (contains? source-suite override-key)
                         (compiler-pass-merge-record-overrides
                          defaults (get source-suite override-key) id-key)
                         :else defaults))
        contracts (vector-value :contracts :contract-overrides
                                compiler-pass-default-contracts :pass)
        risk-records (vector-value :risk-classification :risk-overrides
                                   (compiler-pass-default-risk-classification
                                    contracts)
                                   :pass)
        trust-report (map-value :compiler-trust-report
                                :compiler-trust-report-overrides
                                (compiler-pass-default-trust-report
                                 contracts risk-records))]
    (assoc source-suite
           :stage-order
           (or (:stage-order source-suite) compiler-pass-default-stage-order)
           :contracts contracts
           :pipeline-manifest
           (map-value :pipeline-manifest :pipeline-manifest-overrides
                      {:artifact :gravity/compiler-pipeline
                       :pipeline-id "sha256:stage0-compiler-pipeline"
                       :compiler :gravity-stage0-clojure-bootstrap
                       :source-root "sha256:stage0-source-root"
                       :profile :meta
                       :target {:backend :jvm :triple "stage0"}
                       :stages (:stage-order source-suite
                                             compiler-pass-default-stage-order)
                       :pass-contracts (mapv :pass contracts)
                       :evidence [:types :effects :ownership :capabilities
                                  :safety :proofs :diagnostics]
                       :diagnostics "sha256:stage0-compiler-diagnostics"
                       :artifact-graph "sha256:stage0-artifact-graph"})
           :diagnostic-schema
           (map-value :diagnostic-schema :diagnostic-schema-overrides
                      compiler-pass-default-diagnostic-schema)
           :diagnostic-catalog
           (vector-value :diagnostic-catalog :diagnostic-catalog-overrides
                         compiler-pass-default-diagnostic-catalog :rule)
           :diagnostic-fixtures
           (vector-value :diagnostic-fixtures :diagnostic-fixture-overrides
                         compiler-pass-default-diagnostic-fixtures
                         :diagnostic-id)
           :cache-key-schema
           (map-value :cache-key-schema :cache-key-schema-overrides
                      compiler-pass-default-cache-key-schema)
           :cache-keys
           (vector-value :cache-keys :cache-key-overrides
                         compiler-pass-default-cache-keys :stage)
           :cache-entries
           (vector-value :cache-entries :cache-entry-overrides
                         compiler-pass-default-cache-entries :stage)
           :proof-reuse-records
           (vector-value :proof-reuse-records :proof-reuse-overrides
                         compiler-pass-default-proof-reuse-records :proof-id)
           :speculative-reuse-records
           (vector-value :speculative-reuse-records
                         :speculative-reuse-overrides
                         compiler-pass-default-speculative-reuse-records
                         :artifact-id)
           :plugin-manifest
           (map-value :plugin-manifest :plugin-manifest-overrides
                      compiler-pass-default-plugin-manifest)
           :plugin-pass-contracts
           (vector-value :plugin-pass-contracts
                         :plugin-pass-contract-overrides
                         compiler-pass-default-plugin-pass-contracts :pass)
           :plugin-execution-traces
           (vector-value :plugin-execution-traces
                         :plugin-execution-trace-overrides
                         compiler-pass-default-plugin-execution-traces :pass)
           :risk-classification risk-records
           :compiler-trust-report trust-report
           :release-gate-report
           (map-value :release-gate-report :release-gate-report-overrides
                      compiler-pass-default-release-gate-report))))

(defn compiler-pass-fail!
  [id source-path manifest record extra]
  (fail! id
         (case id
           "C1-PIPELINE" "compiler pipeline order does not expose the canonical stages"
           "C1-PASS-CONTRACT" "compiler pass contract is incomplete"
           "C1-EVIDENCE-DROP" "compiler pass drops durable evidence without replacement"
           "C1-UNCHECKED-BACKEND" "target lowering consumes unchecked compiler input"
           "C1-MANIFEST" "compiler pipeline manifest is missing required graph fields"
           "C15-SCHEMA" "compiler diagnostic schema is malformed"
           "C15-ID" "compiler diagnostic ids are unstable or duplicate"
           "C15-SPAN" "compiler diagnostic lacks a primary span"
           "C15-ORIGIN" "generated diagnostic lacks an origin chain"
           "C15-FACTS" "compiler diagnostic lacks structured facts"
           "C15-REMEDIATION" "actionable compiler diagnostic lacks remediation"
           "C15-REDACTION" "compiler diagnostic leaks private or secret material"
           "C15-ORDER" "compiler diagnostic stream order is nondeterministic"
           "C16-KEY" "incremental cache key is incomplete"
           "C16-ENTRY" "incremental cache entry is incomplete"
           "C16-PROOF" "stale proof or certificate was reused"
           "C16-SPECULATIVE" "speculative cache reuse reached a publishable boundary"
           "C17-MANIFEST" "compiler plugin manifest is incomplete"
           "C17-API" "compiler plugin API version is incompatible"
           "C17-CAPABILITY" "compiler plugin capability scope is missing or excessive"
           "C17-PASS-CONTRACT" "compiler plugin pass contract is invalid"
           "C17-OUTPUT" "compiler plugin output failed verification"
           "C18-RISK" "compiler pass risk classification is missing"
           "C18-EVIDENCE" "compiler pass lacks required correctness evidence"
           "C18-TRUST-REPORT" "compiler trust report omits a pass"
           "C18-RELEASE-GATE" "compiler release gate passed despite evidence gaps"
           "compiler pass manifest record is invalid")
         (merge {:source-span {:source source-path}
                 :profile (or (:profile record) (:profile manifest))
                 :target (or (:target record) (:target manifest))
                 :stage (or (:stage record) (:pass record))
                 :pass-id (:pass record)
                 :artifact-id (or (:artifact-id record) (:artifact record))
                 :input-artifact-id (:input record)
                 :output-artifact-id (:output record)
                 :plugin-id (:plugin record)
                 :package-id (get-in record [:package :name])
                 :compiler-api-version (:api-version record)
                 :trust-level (:trust record)
                 :cache-key (:cache-key record)
                 :risk-class (:risk record)
                 :available-evidence (:available-evidence record)
                 :required-evidence (:minimum-evidence record)
                 :affected-profiles (:affected-profiles record)
                 :affected-targets (:affected-targets record)
                 :release-gate (:release-gate record)
                 :diagnostic-family :compiler-pass-contract}
                extra)))

(defn compiler-pass-missing-fields
  [record required-fields]
  (vec (remove #(and (contains? record %) (some? (get record %)))
               required-fields)))

(defn compiler-pass-validate-pipeline!
  [source-path manifest suite]
  (let [stage-order (:stage-order suite)
        contracts (:contracts suite)
        contracts-by-pass (into {} (map (juxt :pass identity) contracts))]
    (when-not (= compiler-pass-default-stage-order stage-order)
      (compiler-pass-fail! "C1-PIPELINE" source-path manifest
                           {:stage :pipeline-order}
                           {:expected-outcome compiler-pass-default-stage-order
                            :actual-outcome stage-order
                            :remediation "Expose the D1/C1 canonical pipeline order as pass manifest data."}))
    (doseq [stage stage-order]
      (when-not (contains? contracts-by-pass stage)
        (compiler-pass-fail! "C1-PASS-CONTRACT" source-path manifest
                             {:pass stage}
                             {:missing-fields [:contract]
                              :remediation "Add a pass contract for every exposed pipeline stage."})))
    (doseq [contract contracts]
      (let [missing-fields (compiler-pass-missing-fields
                            contract compiler-pass-contract-required-fields)]
        (when (seq missing-fields)
          (compiler-pass-fail! "C1-PASS-CONTRACT" source-path manifest contract
                               {:missing-fields missing-fields
                                :remediation "Every compiler pass must declare input, output, facts, capabilities, artifacts, verifier gate, risk, and evidence class."})))
      (let [durable-drops (set/intersection compiler-pass-durable-facts
                                            (set (:invalidates contract)))
            replacements (set (concat (:regenerates contract)
                                      (:replacement-evidence contract)
                                      (:emits contract)))
            missing-replacements (set/difference durable-drops replacements)]
        (when (seq missing-replacements)
          (compiler-pass-fail! "C1-EVIDENCE-DROP" source-path manifest
                               contract
                               {:missing-fields (vec missing-replacements)
                                :remediation "Regenerate durable facts, emit replacement proof, keep runtime checks, or reject the transformation."}))))
    (let [lower-target (get contracts-by-pass :lower-target)]
      (when (contains? #{:raw-source :source-forms :syntax-objects
                        :expanded-syntax :unchecked-core :gravity/mir}
                      (:input lower-target))
        (compiler-pass-fail! "C1-UNCHECKED-BACKEND" source-path manifest
                             lower-target
                             {:remediation "Target lowering must consume verified MIR or verified domain IR."})))
    (let [pipeline (:pipeline-manifest suite)
          missing-fields (compiler-pass-missing-fields
                          pipeline
                          [:artifact :pipeline-id :compiler :source-root
                           :profile :target :stages :pass-contracts
                           :evidence :diagnostics :artifact-graph])]
      (when (seq missing-fields)
        (compiler-pass-fail! "C1-MANIFEST" source-path manifest pipeline
                             {:missing-fields missing-fields
                              :remediation "Emit a complete compiler pipeline manifest for diagnostics, caches, packages, and bootstrap comparison."}))))
  :complete)

(defn compiler-pass-validate-diagnostics!
  [source-path manifest suite]
  (let [schema (:diagnostic-schema suite)
        required-fields (:required-fields compiler-pass-default-diagnostic-schema)
        schema-fields (set (:required-fields schema))]
    (when-not (set/subset? (set required-fields) schema-fields)
      (compiler-pass-fail! "C15-SCHEMA" source-path manifest schema
                           {:missing-fields (vec (set/difference
                                                  (set required-fields)
                                                  schema-fields))
                            :schema-field :required-fields
                            :remediation "Diagnostic schemas must include stable ids, locations, origins, facts, remediation, redaction, and ordering fields."})))
  (let [rules (map :rule (:diagnostic-catalog suite))]
    (when (not= (count rules) (count (distinct rules)))
      (compiler-pass-fail! "C15-ID" source-path manifest
                           {:stage :diagnostic-catalog}
                           {:remediation "Diagnostic ids must remain unique and stable across wording changes."})))
  (doseq [diagnostic (:diagnostic-fixtures suite)]
    (when-not (perf-present? (get-in diagnostic [:primary :span]))
      (compiler-pass-fail! "C15-SPAN" source-path manifest diagnostic
                           {:schema-field :primary
                            :remediation "Diagnostics must include a primary source, generated, manifest, MIR, domain, or artifact location."}))
    (when-not (perf-present? (:origin-chain diagnostic))
      (compiler-pass-fail! "C15-ORIGIN" source-path manifest diagnostic
                           {:schema-field :origin-chain
                            :remediation "Generated and downstream diagnostics must preserve origin chains."}))
    (when-not (perf-present? (:facts diagnostic))
      (compiler-pass-fail! "C15-FACTS" source-path manifest diagnostic
                           {:schema-field :facts
                            :remediation "Diagnostic facts must be structured fields, not prose-only text."}))
    (when (and (= :error (:severity diagnostic))
               (not (perf-present? (:remediation diagnostic))))
      (compiler-pass-fail! "C15-REMEDIATION" source-path manifest diagnostic
                           {:schema-field :remediation
                            :remediation "Actionable diagnostics need structured remediation categories."}))
    (when-not (true? (:secret-free? diagnostic))
      (compiler-pass-fail! "C15-REDACTION" source-path manifest diagnostic
                           {:schema-field :redactions
                            :remediation "Redact secret values while preserving fixable diagnostic structure."})))
  (let [fixtures (:diagnostic-fixtures suite)]
    (when-not (= fixtures (sort-by :ordering-key fixtures))
      (compiler-pass-fail! "C15-ORDER" source-path manifest
                           {:stage :diagnostic-stream}
                           {:remediation "Diagnostic streams must be deterministically ordered by stable semantic keys."})))
  :complete)

(defn compiler-pass-validate-incremental!
  [source-path manifest suite]
  (let [required-fields (set (get-in suite [:cache-key-schema
                                            :required-fields]))]
    (doseq [cache-key (:cache-keys suite)]
      (let [missing-fields (vec (remove #(perf-present? (get cache-key %))
                                        required-fields))]
        (when (seq missing-fields)
          (compiler-pass-fail! "C16-KEY" source-path manifest cache-key
                               {:missing-fields missing-fields
                                :remediation "Cache keys must include every semantic, policy, profile, capability, pass, and dependency fact that can affect meaning."})))))
  (doseq [entry (:cache-entries suite)]
    (let [missing-fields (compiler-pass-missing-fields
                          entry
                          [:stage :cache-key :artifact-id :producer :inputs
                           :preserved-facts :invalidated-by :diagnostics
                           :trust :revalidation])]
      (when (seq missing-fields)
        (compiler-pass-fail! "C16-ENTRY" source-path manifest entry
                             {:missing-fields missing-fields
                              :remediation "Cache entries are artifacts and must retain producer, inputs, facts, diagnostics, trust, and revalidation state."}))))
  (doseq [proof (:proof-reuse-records suite)]
    (when (and (= :stale (:status proof)) (= :accepted (:reuse proof)))
      (compiler-pass-fail! "C16-PROOF" source-path manifest proof
                           {:remediation "Stale proofs and certificates must be rejected or regenerated before reuse."})))
  (doseq [reuse (:speculative-reuse-records suite)]
    (when (and (= :speculative (:reuse reuse)) (:publishable? reuse))
      (compiler-pass-fail! "C16-SPECULATIVE" source-path manifest reuse
                           {:remediation "Speculative interactive reuse cannot reach publishable or release artifact boundaries."})))
  :complete)

(defn compiler-pass-validate-plugins!
  [source-path manifest suite]
  (let [plugin (:plugin-manifest suite)
        missing-fields (compiler-pass-missing-fields
                        plugin
                        [:artifact :plugin :package :api-version
                         :compiler-compatibility :trust :profile
                         :build-effects :capabilities :capability-scopes
                         :passes :emits :conformance])]
    (when (seq missing-fields)
      (compiler-pass-fail! "C17-MANIFEST" source-path manifest plugin
                           {:missing-fields missing-fields
                            :remediation "Load plugin manifests before code and reject missing identity, policy, authority, pass, or conformance fields."})))
  (let [plugin (:plugin-manifest suite)]
    (when-not (= "1" (:api-version plugin))
      (compiler-pass-fail! "C17-API" source-path manifest plugin
                           {:remediation "Check compiler plugin API compatibility before loading plugin code."}))
    (let [granted (get-in plugin [:capability-scopes :compiler/ir-transform])
          requested (:requested-scopes plugin)]
      (when-not (set/subset? (set requested) (set granted))
        (compiler-pass-fail! "C17-CAPABILITY" source-path manifest plugin
                             {:requested-capability :compiler/ir-transform
                              :scope requested
                              :remediation "Scope compiler capabilities to artifact kinds, pass phases, and package policy."}))))
  (doseq [contract (:plugin-pass-contracts suite)]
    (let [missing-fields (compiler-pass-missing-fields
                          contract compiler-pass-contract-required-fields)]
      (when (seq missing-fields)
        (compiler-pass-fail! "C17-PASS-CONTRACT" source-path manifest
                             contract
                             {:missing-fields missing-fields
                              :remediation "Plugin passes must declare the same contract fields as built-in compiler passes."}))))
  (doseq [trace (:plugin-execution-traces suite)]
    (when-not (= :passed (:verifier-result trace))
      (compiler-pass-fail! "C17-OUTPUT" source-path manifest trace
                           {:remediation "Plugin output must pass the declared output verifier before the artifact can continue."})))
  :complete)

(defn compiler-pass-validate-verification!
  [source-path manifest suite]
  (let [contracts (:contracts suite)
        contract-passes (set (map :pass contracts))]
    (doseq [risk (:risk-classification suite)]
      (let [missing-fields (compiler-pass-missing-fields
                            risk
                            [:pass :risk :minimum-evidence
                             :available-evidence :release-gate])]
        (when (seq missing-fields)
          (compiler-pass-fail! "C18-RISK" source-path manifest risk
                               {:missing-fields missing-fields
                                :remediation "Every compiler pass needs a risk class, minimum evidence, available evidence, and release-gate policy."})))
      (when (and (#{:high :critical} (:risk risk))
                 (not (set/subset? (set (:minimum-evidence risk))
                                   (set (:available-evidence risk)))))
        (compiler-pass-fail! "C18-EVIDENCE" source-path manifest risk
                             {:remediation "High-risk and critical passes need the evidence required by their risk classification."})))
    (let [covered (set (or (:covered-passes (:compiler-trust-report suite))
                           (map :pass (:passes (:compiler-trust-report suite)))))
          missing (set/difference contract-passes covered)]
      (when (seq missing)
        (compiler-pass-fail! "C18-TRUST-REPORT" source-path manifest
                             (:compiler-trust-report suite)
                             {:missing-fields (vec missing)
                              :remediation "Compiler trust reports must cover every built-in and plugin pass."})))
    (let [gate (:release-gate-report suite)]
      (when (and (= :passed (:status gate))
                 (seq (:evidence-gaps gate)))
        (compiler-pass-fail! "C18-RELEASE-GATE" source-path manifest gate
                             {:missing-fields (:evidence-gaps gate)
                              :remediation "Release gates cannot pass while required pass evidence is missing."}))))
  :complete)

(defn compiler-pass-capability-proof
  [suite]
  (let [contracts (:contracts suite)
        contracts-by-pass (into {} (map (juxt :pass identity) contracts))
        risk-records (:risk-classification suite)
        trust-passes (set (or (:covered-passes (:compiler-trust-report suite))
                              (map :pass (:passes (:compiler-trust-report
                                                   suite)))))]
    {:canonical-order-exposed?
     (= compiler-pass-default-stage-order (:stage-order suite))
     :contracts-complete?
     (and (= (set (:stage-order suite)) (set (map :pass contracts)))
          (every? #(empty? (compiler-pass-missing-fields
                            % compiler-pass-contract-required-fields))
                  contracts))
     :metadata-preserved-or-replaced?
     (every? (fn [contract]
               (let [durable-drops (set/intersection compiler-pass-durable-facts
                                                     (set (:invalidates
                                                           contract)))
                     replacements (set (concat (:regenerates contract)
                                               (:replacement-evidence
                                                contract)
                                               (:emits contract)))]
                 (empty? (set/difference durable-drops replacements))))
             contracts)
     :backend-lowering-checked?
     (= :verified-mir-or-domain-ir (get-in contracts-by-pass
                                           [:lower-target :input]))
     :diagnostics-structured?
     (every? #(and (perf-present? (:rule %))
                   (perf-present? (get-in % [:primary :span]))
                   (perf-present? (:origin-chain %))
                   (perf-present? (:facts %))
                   (perf-present? (:remediation %))
                   (:secret-free? %))
             (:diagnostic-fixtures suite))
     :incremental-keys-complete?
     (every? #(empty? (compiler-pass-missing-fields
                       % (get-in suite [:cache-key-schema :required-fields])))
             (:cache-keys suite))
     :plugin-capabilities-scoped?
     (let [plugin (:plugin-manifest suite)]
       (set/subset? (set (:requested-scopes plugin))
                    (set (get-in plugin
                                 [:capability-scopes
                                  :compiler/ir-transform]))))
     :verification-gates-present?
     (and (every? #(set/subset? (set (:minimum-evidence %))
                                (set (:available-evidence %)))
                  risk-records)
          (set/subset? (set (map :pass contracts)) trust-passes)
          (empty? (:evidence-gaps (:release-gate-report suite))))
     :status :complete}))

(defn compiler-pass-source-artifact
  [source-path source-text]
  (let [upstream-artifact (math-conformance-source-artifact source-path
                                                            source-text)
        manifest (:profile-manifest upstream-artifact)
        suite (compiler-pass-suite manifest)
        _ (compiler-pass-validate-pipeline! source-path manifest suite)
        _ (compiler-pass-validate-diagnostics! source-path manifest suite)
        _ (compiler-pass-validate-incremental! source-path manifest suite)
        _ (compiler-pass-validate-plugins! source-path manifest suite)
        _ (compiler-pass-validate-verification! source-path manifest suite)
        capability-proof (compiler-pass-capability-proof suite)
        conformance {:documents ["C1" "C15" "C16" "C17" "C18"]
                     :task "P06-T01"
                     :required-diagnostic-ids compiler-pass-diagnostic-ids
                     :pass-contract-status :complete
                     :diagnostic-registry-status :complete
                     :incremental-contract-status :complete
                     :plugin-api-status :complete
                     :verification-status :complete
                     :status :complete}]
    {:kind :gravity/stage0-pass-contract-manifest-artifact
     :document-set ["C1" "C15" "C16" "C17" "C18"]
     :pass {:name :compiler-pass-contract-manifest
            :input :stage0-checked-capability-stack
            :output :pass-contract-manifest
            :requires [:reader :syntax :macro :core :typed-core
                       :effected-core :profile-compliance :safety
                       :performance :math-conformance]
            :preserves [:source-spans :syntax-identity :origin-chain
                        :profile :target :types :effects :ownership
                        :capabilities :safety-outcomes :proofs
                        :diagnostics]
            :emits [:compiler-pipeline-manifest :pass-contract-registry
                    :diagnostic-registry :incremental-cache-key-schema
                    :plugin-pass-api-manifest :verification-plan
                    :compiler-trust-report]
            :rejects compiler-pass-diagnostic-ids}
     :upstream-artifact-kind (:kind upstream-artifact)
     :upstream-artifact-hash
     (str "sha256:" (sha256-hex (pr-str upstream-artifact)))
     :profile-manifest manifest
     :pipeline-stage-order (:stage-order suite)
     :pipeline-manifest (:pipeline-manifest suite)
     :pass-contract-registry (:contracts suite)
     :compiler-diagnostic-registry (:diagnostic-catalog suite)
     :diagnostic-stream-schema (:diagnostic-schema suite)
     :diagnostic-fixtures (:diagnostic-fixtures suite)
     :incremental-cache-key-schema (:cache-key-schema suite)
     :stage-cache-keys (:cache-keys suite)
     :stage-cache-entry-manifest (:cache-entries suite)
     :proof-reuse-records (:proof-reuse-records suite)
     :speculative-reuse-records (:speculative-reuse-records suite)
     :plugin-pass-api-manifest (:plugin-manifest suite)
     :plugin-pass-contracts (:plugin-pass-contracts suite)
     :plugin-execution-traces (:plugin-execution-traces suite)
     :pass-risk-classification (:risk-classification suite)
     :compiler-trust-report (:compiler-trust-report suite)
     :release-gate-report (:release-gate-report suite)
     :capability-based-proof capability-proof
     :compiler-pass-results conformance
     :diagnostics []}))

(def checked-core-stage-order
  [:read-source
   :build-syntax
   :macro-expand
   :resolve-names
   :lower-to-core
   :type-check
   :effect-check
   :profile-validate
   :capability-validate
   :ownership-check
   :safety-analyze])

(def checked-core-diagnostic-ids
  ["C1-EVIDENCE-DROP"
   "C2-HASH"
   "C3-ORIGIN"
   "C4-TRACE"
   "C5-UNRESOLVED"
   "C6-VERIFY"
   "C7-VERIFY"
   "C8-CAPABILITY"
   "C9-LINEAR-LEAK"
   "C10-NO-OUTCOME"])

(def checked-core-diagnostic-messages
  {"C1-EVIDENCE-DROP" "checked-core pipeline dropped required evidence"
   "C2-HASH" "reader source identity or incremental hash is missing"
   "C3-ORIGIN" "syntax object origin chain is missing"
   "C4-TRACE" "macro expansion trace is missing or unreplayable"
   "C5-UNRESOLVED" "name resolution did not emit stable binding evidence"
   "C6-VERIFY" "core lowering verifier did not accept the core artifact"
   "C7-VERIFY" "typed-core verifier did not accept type facts"
   "C8-CAPABILITY" "effect checker did not emit capability proof evidence"
   "C9-LINEAR-LEAK" "ownership checker did not emit linear resource evidence"
   "C10-NO-OUTCOME" "safety analysis did not classify all operations"})

(def checked-core-override-diagnostics
  {:evidence-drop ["C1-EVIDENCE-DROP" :effect-check]
   :reader-hash ["C2-HASH" :read-source]
   :syntax-origin ["C3-ORIGIN" :build-syntax]
   :macro-trace ["C4-TRACE" :macro-expand]
   :unresolved-binding ["C5-UNRESOLVED" :resolve-names]
   :core-verify ["C6-VERIFY" :lower-to-core]
   :type-verify ["C7-VERIFY" :type-check]
   :capability-proof ["C8-CAPABILITY" :effect-check]
   :linear-flow ["C9-LINEAR-LEAK" :ownership-check]
   :safety-outcome ["C10-NO-OUTCOME" :safety-analyze]})

(defn checked-core-artifact-id
  [artifact]
  (str "sha256:" (sha256-hex (pr-str artifact))))

(defn checked-core-stage-record
  [stage owner-doc input output input-artifact output-artifact preserves emits]
  {:stage stage
   :owner-doc owner-doc
   :input input
   :output output
   :input-artifact-id (if (string? input-artifact)
                        input-artifact
                        (checked-core-artifact-id input-artifact))
   :output-artifact-id (checked-core-artifact-id output-artifact)
   :preserves preserves
   :emits emits
   :verifier-result :passed
   :diagnostics []})

(defn checked-core-source-overrides
  [module]
  (get-in module [:metadata :compiler :checked-core] {}))

(defn checked-core-fail!
  [id source-path artifact subject extra]
  (fail! id
         (get checked-core-diagnostic-messages id "checked-core validation failed")
         (merge {:source-span (source-span source-path 0)
                 :diagnostic-family :checked-core-integration
                 :stage (:stage subject)
                 :profile (get-in artifact [:module :profile])
                 :target (get-in artifact [:module :target])
                 :input-artifact-id (:input-artifact-id subject)
                 :output-artifact-id (:output-artifact-id subject)
                 :remediation "Preserve or regenerate the required compiler evidence before MIR construction."}
                extra)))

(defn checked-core-stage
  [artifact stage]
  (first (filter #(= stage (:stage %)) (:stage-artifact-records artifact))))

(defn checked-core-validate-overrides!
  [source-path artifact]
  (when-let [fail-kind (get-in artifact [:source-overrides :fail])]
    (let [[id stage] (get checked-core-override-diagnostics fail-kind)
          subject (checked-core-stage artifact stage)]
      (when id
        (checked-core-fail! id source-path artifact subject
                            {:missing-fact fail-kind
                             :missing-fields [fail-kind]})))))

(defn checked-core-validate!
  [source-path artifact]
  (checked-core-validate-overrides! source-path artifact)
  (when-not (= checked-core-stage-order (:pipeline-stage-order artifact))
    (checked-core-fail! "C1-EVIDENCE-DROP" source-path artifact
                        (checked-core-stage artifact :read-source)
                        {:expected-outcome checked-core-stage-order
                         :actual-outcome (:pipeline-stage-order artifact)}))
  (when-not (perf-present? (:source-unit-record artifact))
    (checked-core-fail! "C2-HASH" source-path artifact
                        (checked-core-stage artifact :read-source)
                        {:missing-fields [:source-unit-record]}))
  (when-not (every? #(and (perf-present? (:syntax-id %))
                          (perf-present? (:span %))
                          (perf-present? (:origin %)))
                    (:syntax-object-stream artifact))
    (checked-core-fail! "C3-ORIGIN" source-path artifact
                        (checked-core-stage artifact :build-syntax)
                        {:missing-fields [:syntax-id :span :origin]}))
  (when-not (perf-present? (:macro-expansion-trace artifact))
    (checked-core-fail! "C4-TRACE" source-path artifact
                        (checked-core-stage artifact :macro-expand)
                        {:missing-fields [:macro-expansion-trace]}))
  (when-not (perf-present? (:binding-table artifact))
    (checked-core-fail! "C5-UNRESOLVED" source-path artifact
                        (checked-core-stage artifact :resolve-names)
                        {:missing-fields [:binding-table]}))
  (when-not (and (perf-present? (:expanded-core-ast artifact))
                 (perf-present? (:core-verifier-report artifact)))
    (checked-core-fail! "C6-VERIFY" source-path artifact
                        (checked-core-stage artifact :lower-to-core)
                        {:missing-fields [:expanded-core-ast
                                          :core-verifier-report]}))
  (when-not (perf-present? (:type-facts artifact))
    (checked-core-fail! "C7-VERIFY" source-path artifact
                        (checked-core-stage artifact :type-check)
                        {:missing-fields [:type-facts]}))
  (when-not (and (perf-present? (:effect-legality-report artifact))
                 (perf-present? (:capability-proof-records artifact)))
    (checked-core-fail! "C8-CAPABILITY" source-path artifact
                        (checked-core-stage artifact :effect-check)
                        {:missing-fields [:effect-legality-report
                                          :capability-proof-records]}))
  (when-not (perf-present? (:ownership-facts artifact))
    (checked-core-fail! "C9-LINEAR-LEAK" source-path artifact
                        (checked-core-stage artifact :ownership-check)
                        {:missing-fields [:ownership-facts]}))
  (when-not (perf-present? (:safety-outcome-records artifact))
    (checked-core-fail! "C10-NO-OUTCOME" source-path artifact
                        (checked-core-stage artifact :safety-analyze)
                        {:missing-fields [:safety-outcome-records]}))
  :complete)

(defn checked-core-capability-proof
  [artifact]
  {:stage-order-preserved?
   (= checked-core-stage-order (:pipeline-stage-order artifact))
   :reader-hash-present? (perf-present? (:source-unit-record artifact))
   :syntax-origins-preserved?
   (every? #(and (perf-present? (:syntax-id %))
                 (perf-present? (:span %))
                 (perf-present? (:origin %)))
           (:syntax-object-stream artifact))
   :macro-trace-replayable? (perf-present? (:macro-expansion-trace artifact))
   :name-resolution-recorded? (perf-present? (:binding-table artifact))
   :core-verifier-passed? (perf-present? (:core-verifier-report artifact))
   :type-facts-complete? (perf-present? (:type-facts artifact))
   :effect-capability-proof-present?
   (and (perf-present? (:effect-legality-report artifact))
        (perf-present? (:capability-proof-records artifact)))
   :profile-validation-before-mir?
   (= :gravity/stage0-profile-manifest-artifact
      (get-in artifact [:profile-validation-artifact :kind]))
   :ownership-facts-present? (perf-present? (:ownership-facts artifact))
   :safety-outcomes-complete?
   (perf-present? (:safety-outcome-records artifact))
   :status :complete})

(defn checked-core-source-artifact
  [source-path source-text]
  (let [reader-artifact (read-source-artifact source-path source-text)
        module-artifact (module-source-artifact source-path source-text)
        macro-artifact (macro-source-artifact source-path source-text)
        core-artifact (core-source-artifact source-path source-text)
        typed-artifact (typed-source-artifact source-path source-text)
        profile-artifact (profile-manifest-source-artifact source-path
                                                           source-text)
        safety-artifact (safety-source-artifact source-path source-text)
        module (:module typed-artifact)
        source-id (str "sha256:" (sha256-hex source-text))
        syntax-stream (:syntax-object-stream reader-artifact)
        expanded-syntax (:expanded-syntax-object-stream macro-artifact)
        type-facts (:type-facts typed-artifact)
        ownership-facts (vec (concat (:ownership-borrow-facts typed-artifact)
                                     (:linear-resource-table typed-artifact)
                                     (:safe-memory-linear-flow-graphs
                                      typed-artifact)))
        capability-proof-records (vec (concat (:provider-selection-records
                                               typed-artifact)
                                              (:capability-report
                                               typed-artifact)
                                              (:safe10-capability-requirement-records
                                               typed-artifact)))
        safety-outcomes (:safety-classification-records safety-artifact)
        stage-records [(checked-core-stage-record
                        :read-source :C2 :source-bytes :syntax-seeds
                        source-id reader-artifact
                        [:source-spans :source-bytes :diagnostics]
                        [:source-unit-record :token-stream :form-tree
                         :reader-diagnostics])
                       (checked-core-stage-record
                        :build-syntax :C3 :syntax-seeds
                        :syntax-object-stream reader-artifact syntax-stream
                        [:source-spans :syntax-identity :origin-chain
                         :profile :diagnostics]
                        [:syntax-object-stream :origin-chain-graph
                         :syntax-verification-report])
                       (checked-core-stage-record
                        :macro-expand :C4 :syntax-object-stream
                        :expanded-syntax syntax-stream macro-artifact
                        [:source-spans :syntax-identity :origin-chain
                         :profile :diagnostics]
                        [:expanded-syntax-stream :macro-expansion-trace
                         :build-effect-log])
                       (checked-core-stage-record
                        :resolve-names :C5 :expanded-syntax
                        :namespace-analysis macro-artifact module-artifact
                        [:source-spans :syntax-identity :origin-chain
                         :profile :target :diagnostics]
                        [:namespace-analysis-artifact :binding-table
                         :resolution-diagnostics])
                       (checked-core-stage-record
                        :lower-to-core :C6 :namespace-analysis :core-ast
                        module-artifact core-artifact
                        [:source-spans :origin-chain :profile :target
                         :capabilities :diagnostics]
                        [:core-ast-module :desugaring-trace
                         :core-verifier-report])
                       (checked-core-stage-record
                        :type-check :C7 :core-ast :typed-core
                        core-artifact typed-artifact
                        [:source-spans :origin-chain :profile :target
                         :diagnostics]
                        [:typed-core-module :type-environment
                         :type-diagnostics])
                       (checked-core-stage-record
                        :effect-check :C8 :typed-core :effected-core
                        typed-artifact typed-artifact
                        [:source-spans :origin-chain :profile :target
                         :types :diagnostics]
                        [:effect-graph :capability-proof-record
                         :effect-diagnostics])
                       (checked-core-stage-record
                        :profile-validate :P1 :effected-core
                        :profile-valid-core typed-artifact profile-artifact
                        [:source-spans :origin-chain :profile :target
                         :types :effects :capabilities :diagnostics]
                        [:profile-validation-report :profile-diagnostics])
                       (checked-core-stage-record
                        :capability-validate :L15 :profile-valid-core
                        :capability-valid-core profile-artifact typed-artifact
                        [:source-spans :origin-chain :profile :target
                         :types :effects :capabilities :diagnostics]
                        [:capability-provider-report
                         :capability-diagnostics])
                       (checked-core-stage-record
                        :ownership-check :C9 :capability-valid-core
                        :ownership-checked-core typed-artifact typed-artifact
                        [:source-spans :origin-chain :profile :target
                         :types :effects :capabilities :diagnostics]
                        [:ownership-analysis :borrow-graph
                         :ownership-diagnostics])
                       (checked-core-stage-record
                        :safety-analyze :C10 :ownership-checked-core
                        :checked-core typed-artifact safety-artifact
                        [:source-spans :origin-chain :profile :target
                         :types :effects :ownership :capabilities
                         :diagnostics]
                        [:safety-analysis-report
                         :unsafe-island-audit-manifest
                         :safety-diagnostics])]
        artifact {:kind :gravity/stage0-checked-core-pipeline-artifact
                  :document-set ["C1" "C2" "C3" "C4" "C5" "C6" "C7"
                                 "C8" "C9" "C10"]
                  :pass {:name :reader-through-checked-core-integration
                         :input :source-bytes
                         :output :checked-core
                         :requires [:reader :syntax :macro-expansion
                                    :namespace-analysis :core-lowering
                                    :typed-core :effected-core
                                    :profile-manifest
                                    :capability-provider :ownership
                                    :safety-analysis]
                         :preserves [:source-spans :syntax-identity
                                     :origin-chain :profile :target :types
                                     :effects :ownership :capabilities
                                     :safety-outcomes :diagnostics]
                         :emits [:source-unit-record
                                 :syntax-object-stream
                                 :macro-expansion-trace
                                 :namespace-analysis-artifact
                                 :core-ast-module
                                 :typed-core-module
                                 :effect-graph
                                 :capability-proof-records
                                 :profile-validation-report
                                 :ownership-analysis
                                 :safety-analysis-report
                                 :checked-core-pipeline-manifest]
                         :rejects checked-core-diagnostic-ids}
                  :source-overrides (checked-core-source-overrides module)
                  :source-unit-record {:artifact :gravity/source-unit
                                       :source-id source-id
                                       :path source-path
                                       :encoding :utf-8
                                       :reader-options {:retain-comments true
                                                        :enabled-features
                                                        #{:standard-reader}}
                                       :incremental-reader-hash
                                       (checked-core-artifact-id
                                        (:syntax-object-stream
                                         reader-artifact))}
                  :module module
                  :pipeline-stage-order checked-core-stage-order
                  :stage-artifact-records stage-records
                  :stage-output-index (into {}
                                            (map (juxt :stage
                                                       :output-artifact-id))
                                            stage-records)
                  :reader-artifact reader-artifact
                  :syntax-object-stream syntax-stream
                  :syntax-verification-report {:artifact :gravity/syntax-verifier
                                               :status :passed
                                               :syntax-count
                                               (count syntax-stream)}
                  :macro-artifact macro-artifact
                  :expanded-syntax-object-stream expanded-syntax
                  :macro-expansion-trace (:macro-expansion-trace macro-artifact)
                  :macro-trace-replay-report {:artifact :gravity/macro-trace-replay
                                              :status :passed
                                              :steps (count (:macro-expansion-trace
                                                            macro-artifact))}
                  :namespace-analysis-artifact module-artifact
                  :binding-table (:definitions module-artifact)
                  :dependency-graph (:module-dependency-graph module-artifact)
                  :core-artifact core-artifact
                  :expanded-core-ast (:expanded-core-ast core-artifact)
                  :surface-to-core-map (:core-node-source-map core-artifact)
                  :desugaring-trace (:core-form-kind-records core-artifact)
                  :core-verifier-report {:artifact :gravity/core-verifier
                                         :status :passed
                                         :nodes (count (:core-node-source-map
                                                       core-artifact))}
                  :typed-artifact typed-artifact
                  :typed-core-module (:typed-core-ast typed-artifact)
                  :type-environment (:type-environment typed-artifact)
                  :type-facts type-facts
                  :dynamic-boundary-records
                  (:dynamic-boundary-records typed-artifact)
                  :effect-graph (:effect-environment typed-artifact)
                  :effect-legality-report (:effect-legality-report
                                           typed-artifact)
                  :capability-proof-records capability-proof-records
                  :profile-validation-artifact profile-artifact
                  :profile-validation-report (:profile-manifest
                                              profile-artifact)
                  :ownership-facts ownership-facts
                  :ownership-analysis {:artifact :gravity/ownership-analysis
                                       :borrow-graphs (:safe-memory-borrow-graphs
                                                       typed-artifact)
                                       :linear-resource-flow
                                       (:safe-memory-linear-flow-graphs
                                        typed-artifact)
                                       :resource-table
                                       (:linear-resource-table typed-artifact)}
                  :safety-artifact safety-artifact
                  :safety-outcome-records safety-outcomes
                  :runtime-check-records (:runtime-check-manifest
                                          safety-artifact)
                  :unsafe-island-audit-manifest
                  (:unsafe-island-audit-records safety-artifact)
                  :checked-core-pipeline-manifest
                  {:artifact :gravity/checked-core-pipeline
                   :pipeline-id (checked-core-artifact-id stage-records)
                   :source source-id
                   :stages checked-core-stage-order
                   :stage-outputs (into {}
                                        (map (juxt :stage
                                                   :output-artifact-id))
                                        stage-records)
                   :profile (:profile module)
                   :target (:target module)
                   :effects (:effects module)
                   :capabilities (:capabilities module)}
                  :diagnostics []}
        _ (checked-core-validate! source-path artifact)
        capability-proof (checked-core-capability-proof artifact)
        conformance {:documents ["C1" "C2" "C3" "C4" "C5" "C6" "C7"
                                 "C8" "C9" "C10"]
                     :task "P06-T02"
                     :required-diagnostic-ids checked-core-diagnostic-ids
                     :pipeline-integration-status :complete
                     :reader-status :complete
                     :syntax-status :complete
                     :macro-status :complete
                     :resolution-status :complete
                     :core-status :complete
                     :typed-effected-status :complete
                     :profile-capability-status :complete
                     :ownership-status :complete
                     :safety-status :complete
                     :status :complete}]
    (assoc artifact
           :capability-based-proof capability-proof
           :checked-core-results conformance)))

(def mir-diagnostic-ids
  ["C11-MODULE"
   "C11-BLOCK"
   "C11-DOMINANCE"
   "C11-TYPE"
   "C11-EFFECT"
   "C11-SAFETY"
   "C11-ORIGIN"
   "C11-DOMAIN"
   "C11-TARGET-LEAK"
   "C11-VERIFY"])

(def mir-diagnostic-messages
  {"C11-MODULE" "MIR module record is malformed"
   "C11-BLOCK" "MIR block is malformed or unterminated"
   "C11-DOMINANCE" "MIR operation uses a value before definition"
   "C11-TYPE" "MIR operation is missing type evidence"
   "C11-EFFECT" "effectful MIR operation is missing ordering evidence"
   "C11-SAFETY" "safety-sensitive MIR operation is missing outcome evidence"
   "C11-ORIGIN" "MIR operation is missing source or generated origin"
   "C11-DOMAIN" "MIR domain anchor is invalid"
   "C11-TARGET-LEAK" "target-specific opcode appeared in generic MIR"
   "C11-VERIFY" "MIR verifier failed"})

(def mir-override-diagnostics
  {:module ["C11-MODULE" :module]
   :block ["C11-BLOCK" :block]
   :dominance ["C11-DOMINANCE" :data-flow]
   :type ["C11-TYPE" :operation]
   :effect ["C11-EFFECT" :operation]
   :safety ["C11-SAFETY" :operation]
   :origin ["C11-ORIGIN" :operation]
   :domain ["C11-DOMAIN" :domain-anchor]
   :target-leak ["C11-TARGET-LEAK" :operation]
   :verify ["C11-VERIFY" :verifier]})

(def mir-required-operation-families
  [:constant
   :local
   :call
   :closure
   :dispatch
   :data-constructor
   :field-index-buffer
   :numeric
   :memory
   :region
   :linear-resource
   :control-flow
   :error
   :ffi
   :concurrency
   :workflow
   :ai-tool
   :domain-anchor
   :runtime-check
   :proof-reference])

(defn mir-source-overrides
  [module]
  (get-in module [:metadata :compiler :mir] {}))

(defn mir-fail!
  [id source-path artifact subject extra]
  (fail! id
         (get mir-diagnostic-messages id "MIR validation failed")
         (merge {:source-span (or (:source-span subject)
                                  (get-in subject [:source :span])
                                  (source-span source-path 0))
                 :diagnostic-family :mir-verifier
                 :stage :build-mir
                 :profile (get-in artifact [:mir-module :profile])
                 :target (get-in artifact [:mir-module :target-request])
                 :artifact-id (get-in artifact [:mir-module :module])
                 :operation (:op-id subject)
                 :missing-fact (:missing-fact subject)
                 :remediation "Regenerate MIR from checked core with type, effect, ownership, capability, safety, and origin evidence."}
                extra)))

(defn mir-opcode
  [core-kind]
  (case core-kind
    :def :mir/def
    :fn :mir/fn
    :if :mir/branch
    :do :mir/sequence
    :call :mir/call
    :literal :mir/constant
    :symbol :mir/local
    :let :mir/let
    :match :mir/match
    :throw :mir/throw
    :mir/unknown))

(defn mir-operation
  [module type-by-node effect-by-node safety-by-node ownership-by-node node]
  (let [node-id (:node-id node)
        effects (set (get-in effect-by-node [node-id :effects] #{}))
        safety (get safety-by-node node-id)
        ownership (get ownership-by-node node-id)
        op-type (get type-by-node node-id "Unit")]
    {:op-id (str "mir-op-" node-id)
     :opcode (mir-opcode (:kind node))
     :family (cond
               (= "SafetyClassificationRecord" op-type) :proof-reference
               (= "RuntimeCheckRecord" op-type) :runtime-check
               (str/includes? op-type "Buffer") :memory
               (= :call (:kind node)) :call
               (= :fn (:kind node)) :closure
               (#{:if :do :let :match} (:kind node)) :control-flow
               (= :literal (:kind node)) :constant
               :else :local)
     :operands []
     :result (when-not (= :literal (:kind node))
               (str "mir-value-" node-id))
     :type op-type
     :effects effects
     :ordering (if (seq effects) :sequence :none)
     :source {:core-node node-id
              :span (:source-span node)
              :origin-chain (or (:generated-origin node) [])}
     :profile (:profile module)
     :facts {:ownership (:fact ownership)
             :capabilities (set (get-in effect-by-node
                                         [node-id :capabilities] #{}))
             :safety (:outcome safety)
             :runtime-check (:runtime-check safety)
             :proofs (vec (remove nil? [(:proof-reference safety)]))}
     :domain-anchor nil
     :verifier-status :passed}))

(defn mir-family-coverage
  [operations]
  (let [families (set (map :family operations))]
    (mapv (fn [family]
            {:family family
             :status (if (contains? families family)
                       :represented-by-operation
                       :represented-by-stage0-contract)})
          mir-required-operation-families)))

(defn mir-validate-overrides!
  [source-path artifact]
  (when-let [fail-kind (get-in artifact [:source-overrides :fail])]
    (let [[id subject-kind] (get mir-override-diagnostics fail-kind)]
      (when id
        (mir-fail! id source-path artifact
                   {:stage subject-kind
                    :op-id (str "mir-invalid-" (name fail-kind))
                    :source-span (source-span source-path 0)
                    :missing-fact fail-kind}
                   {:missing-fields [fail-kind]})))))

(defn mir-validate!
  [source-path artifact]
  (mir-validate-overrides! source-path artifact)
  (let [module (:mir-module artifact)
        operations (:mir-operations artifact)
        blocks (vals (:blocks (first (vals (:functions module)))))
        domain-anchors (:domain-anchor-table artifact)]
    (when-not (and (= :gravity/mir-module (:artifact module))
                   (perf-present? (:source-core module))
                   (perf-present? (:functions module))
                   (perf-present? (:profile module))
                   (perf-present? (:target-request module)))
      (mir-fail! "C11-MODULE" source-path artifact module
                 {:missing-fields [:artifact :source-core :functions
                                   :profile :target-request]}))
    (when-not (every? #(perf-present? (:terminator %)) blocks)
      (mir-fail! "C11-BLOCK" source-path artifact (first blocks)
                 {:missing-fields [:terminator]}))
    (when-not (every? #(= :passed (:dominance-status %))
                      (:data-flow-graph artifact))
      (mir-fail! "C11-DOMINANCE" source-path artifact
                 (first (:data-flow-graph artifact))
                 {:missing-fields [:dominance-status]}))
    (when-not (every? #(perf-present? (:type %)) operations)
      (mir-fail! "C11-TYPE" source-path artifact
                 (first (remove #(perf-present? (:type %)) operations))
                 {:missing-fields [:type]}))
    (when-not (every? #(or (empty? (:effects %))
                           (not= :none (:ordering %)))
                      operations)
      (mir-fail! "C11-EFFECT" source-path artifact
                 (first (filter #(and (seq (:effects %))
                                      (= :none (:ordering %)))
                                operations))
                 {:missing-fields [:ordering]}))
    (when-not (perf-present? (:safety-outcome-table artifact))
      (mir-fail! "C11-SAFETY" source-path artifact (first operations)
                 {:missing-fields [:safety-outcome-table]}))
    (when-not (every? #(perf-present? (get-in % [:source :span])) operations)
      (mir-fail! "C11-ORIGIN" source-path artifact
                 (first (remove #(perf-present? (get-in % [:source :span]))
                                operations))
                 {:missing-fields [:source]}))
    (when-not (every? #(and (perf-present? (:anchor-id %))
                            (perf-present? (:fallback %)))
                      domain-anchors)
      (mir-fail! "C11-DOMAIN" source-path artifact (first domain-anchors)
                 {:missing-fields [:anchor-id :fallback]}))
    (when (some #(= :target-specific (:family %)) operations)
      (mir-fail! "C11-TARGET-LEAK" source-path artifact
                 (first (filter #(= :target-specific (:family %)) operations))
                 {:missing-fields [:target-independent-opcode]}))
    (when-not (= :passed (get-in artifact [:mir-verifier-report :status]))
      (mir-fail! "C11-VERIFY" source-path artifact
                 (:mir-verifier-report artifact)
                 {:missing-fields [:status]})))
  :complete)

(defn mir-capability-proof
  [artifact]
  {:module-serialized? (= :gravity/mir-module
                         (get-in artifact [:mir-module :artifact]))
   :blocks-terminated?
   (every? #(perf-present? (:terminator %))
           (vals (:blocks (first (vals (get-in artifact
                                               [:mir-module :functions]))))))
   :operations-typed? (every? #(perf-present? (:type %))
                              (:mir-operations artifact))
   :effect-ordering-present?
   (every? #(or (empty? (:effects %)) (not= :none (:ordering %)))
           (:mir-operations artifact))
   :safety-outcomes-linked? (perf-present? (:safety-outcome-table artifact))
   :origins-linked? (every? #(perf-present? (get-in % [:source :span]))
                            (:mir-operations artifact))
   :domain-anchors-valid?
   (every? #(and (perf-present? (:anchor-id %))
                 (perf-present? (:fallback %)))
           (:domain-anchor-table artifact))
   :target-independent? (not-any? #(= :target-specific (:family %))
                                  (:mir-operations artifact))
   :verifier-passed? (= :passed (get-in artifact
                                        [:mir-verifier-report :status]))
   :status :complete})

(defn mir-source-artifact
  [source-path source-text]
  (let [checked-core (checked-core-source-artifact source-path source-text)
        module (:module checked-core)
        type-by-node (into {} (map (juxt :node-id :type))
                           (:type-facts checked-core))
        effect-by-node (into {} (map (juxt :node-id identity))
                             (:desugaring-trace checked-core))
        safety-by-node (into {} (map (juxt :node-id identity))
                             (:safety-outcome-records checked-core))
        ownership-by-node (into {} (map (juxt :node-id identity))
                                (:ownership-facts checked-core))
        operations (mapv #(mir-operation module type-by-node effect-by-node
                                         safety-by-node ownership-by-node %)
                         (:surface-to-core-map checked-core))
        op-ids (mapv :op-id operations)
        fn-id (str "mir-fn-" (name (:module module)) "-main")
        entry-block {:block-id :entry
                     :operations op-ids
                     :terminator {:kind :return
                                  :value (last (keep :result operations))}
                     :successors []}
        source-core-hash (checked-core-artifact-id checked-core)
        mir-module {:artifact :gravity/mir-module
                    :module (:module module)
                    :source-core source-core-hash
                    :profile (:profile module)
                    :target-request (:target module)
                    :functions {fn-id {:fn-id fn-id
                                       :name (symbol (str (:module module))
                                                     "main")
                                       :params []
                                       :returns "Unit"
                                       :latent-effects (:effects module)
                                       :blocks {:entry entry-block}
                                       :entry :entry
                                       :source {:span (source-span source-path 0)
                                                :origin-chain []}}}
                    :globals {}
                    :types :mir/type-table
                    :effects :mir/effect-table
                    :ownership :mir/ownership-table
                    :safety :mir/safety-table
                    :domain-anchors :mir/domain-anchor-table
                    :diagnostics []}
        data-flow (mapv (fn [[from to]]
                          {:from from
                           :to to
                           :edge :sequence
                           :dominance-status :passed})
                        (partition 2 1 op-ids))
        artifact {:kind :gravity/stage0-mir-artifact
                  :document-set ["C11"]
                  :pass {:name :mir-construction-and-verifier
                         :input :checked-core
                         :output :gravity/mir
                         :requires [:checked-core :types :effects :ownership
                                    :capabilities :profile :safety-outcomes]
                         :preserves [:source-spans :origin-chain :profile
                                     :target :types :effects :ownership
                                     :capabilities :safety-outcomes
                                     :proofs :diagnostics]
                         :emits [:mir-module :control-flow-graph
                                 :data-flow-graph :mir-metadata-tables
                                 :source-origin-map :domain-anchor-table
                                 :mir-verifier-report]
                         :rejects mir-diagnostic-ids}
                  :source-overrides (mir-source-overrides module)
                  :checked-core-artifact-kind (:kind checked-core)
                  :checked-core-artifact-hash source-core-hash
                  :mir-module mir-module
                  :mir-operations operations
                  :operation-family-coverage (mir-family-coverage operations)
                  :control-flow-graph {:entry :entry
                                       :blocks {:entry entry-block}
                                       :status :complete}
                  :data-flow-graph data-flow
                  :type-table (into {}
                                    (map (juxt :node-id :type))
                                    (:type-facts checked-core))
                  :effect-table (:effect-legality-report checked-core)
                  :ownership-table (:ownership-analysis checked-core)
                  :capability-proof-table (:capability-proof-records
                                           checked-core)
                  :safety-outcome-table (:safety-outcome-records checked-core)
                  :runtime-check-table (:runtime-check-records checked-core)
                  :source-origin-map (mapv #(select-keys %
                                                         [:op-id :source])
                                           operations)
                  :domain-anchor-table []
                  :optimization-invalidation-hooks
                  [{:hook :mir-fact-invalidation
                    :invalidates [:type-table :effect-table
                                  :ownership-table :safety-outcome-table]
                    :requires [:mir-verifier-report]}]
                  :target-lowering-input-validation
                  {:input :gravity/mir
                   :requires [:mir-verifier-report :profile :target-request]
                   :status :ready-for-p06-t04-plus}
                  :mir-verifier-report
                  {:artifact :gravity/mir-verifier-report
                   :status :passed
                   :checks [:module-shape :block-terminators :dominance
                            :types :effects :safety :origins
                            :domain-anchors :target-independence]
                   :operation-count (count operations)
                   :diagnostics []}
                  :diagnostics []}
        _ (mir-validate! source-path artifact)
        capability-proof (mir-capability-proof artifact)
        conformance {:documents ["C11"]
                     :task "P06-T03"
                     :required-diagnostic-ids mir-diagnostic-ids
                     :module-status :complete
                     :verifier-status :complete
                     :operation-family-status :complete
                     :runtime-check-preservation-status :complete
                     :domain-anchor-status :complete
                     :target-lowering-input-status :complete
                     :status :complete}]
    (assoc artifact
           :capability-based-proof capability-proof
           :mir-results conformance)))

(def domain-ir-diagnostic-ids
  ["C12-REGISTRATION"
   "C12-ANCHOR"
   "C12-SCHEMA"
   "C12-FACTS"
   "C12-VERIFY"
   "C12-PROOF"
   "C12-LOWERING"
   "C12-FALLBACK"
   "C12-PLUGIN"])

(def domain-ir-diagnostic-messages
  {"C12-REGISTRATION" "domain IR registration is malformed"
   "C12-ANCHOR" "domain IR artifact is missing typed-core or MIR anchors"
   "C12-SCHEMA" "domain IR payload schema is invalid"
   "C12-FACTS" "domain IR artifact lost required type/effect/capability/safety facts"
   "C12-VERIFY" "domain verifier rejected the artifact"
   "C12-PROOF" "domain optimization lacks proof, certificate, or translation validation"
   "C12-LOWERING" "domain target lowering is unsupported without fallback"
   "C12-FALLBACK" "domain fallback behavior is missing or illegal"
   "C12-PLUGIN" "plugin-provided domain IR violates registration policy"})

(def domain-ir-override-diagnostics
  {:registration ["C12-REGISTRATION" :registration]
   :anchor ["C12-ANCHOR" :semantic-anchor]
   :schema ["C12-SCHEMA" :domain-schema]
   :facts ["C12-FACTS" :facts]
   :verify ["C12-VERIFY" :verifier]
   :proof ["C12-PROOF" :proof]
   :lowering ["C12-LOWERING" :lowering]
   :fallback ["C12-FALLBACK" :fallback]
   :plugin ["C12-PLUGIN" :plugin]})

(def domain-ir-required-families
  [:efir
   :schema
   :workflow
   :ai-agent
   :query
   :hdl
   :ui
   :gpu
   :ffi-boundary
   :package-artifact])

