    :release-gate :required}])

(defn c18-verification-validate!
  [source-path artifact]
  (let [risk-records (:pass-risk-classification artifact)
        risk-passes (set (map :pass risk-records))
        evidence-passes (set (map :pass (:pass-evidence-records artifact)))
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:verification-diagnostic-stream
                                       :diagnostics])))
        trust-fields (set (keys (:compiler-trust-report artifact)))]
    (doseq [risk risk-records]
      (when-not (set/subset? (set c18-pass-risk-required-fields)
                             (set (keys risk)))
        (c18-verification-fail!
         "C18-RISK" source-path
         {:pass-id (:pass risk)
          :version (:version risk)
          :risk-class (:risk risk)
          :required-evidence (:minimum-evidence risk)
          :available-evidence #{}
          :affected-profiles (:affected-profiles risk)
          :affected-targets (:affected-targets risk)}
         {:missing-fields
          (vec (remove (set (keys risk))
                       c18-pass-risk-required-fields))})))
    (when-not (= risk-passes evidence-passes)
      (c18-verification-fail! "C18-EVIDENCE" source-path
                              (first risk-records)
                              {:missing-fields [:pass-evidence-records]}))
    (when-not (every? #(= :accepted (:result %))
                      (:translation-validation-logs artifact))
      (c18-verification-fail! "C18-VALIDATION" source-path
                              (first (:translation-validation-logs artifact))
                              {:missing-fields [:accepted-validation]}))
    (when-not (every? #(= :accepted (:status %))
                      (:proof-or-certificate-references artifact))
      (c18-verification-fail! "C18-PROOF" source-path
                              (first (:proof-or-certificate-references
                                      artifact))
                              {:missing-fields [:accepted-proof]}))
    (when-not (set/subset? (set c18-trust-report-required-fields)
                           trust-fields)
      (c18-verification-fail! "C18-TRUST-REPORT" source-path
                              (:compiler-trust-report artifact)
                              {:missing-fields
                               (vec (remove trust-fields
                                            c18-trust-report-required-fields))}))
    (when-not (every? #(= :blocked (:release-artifact-status %))
                      (:release-gate-failure-fixtures artifact))
      (c18-verification-fail! "C18-RELEASE-GATE" source-path
                              (first (:release-gate-failure-fixtures
                                      artifact))
                              {:missing-fields [:blocked-release]}))
    (when-not (every? #(and (= :captured (:status %))
                            (true? (:regression-fixture-created? %)))
                      (:counterexample-artifacts artifact))
      (c18-verification-fail! "C18-COUNTEREXAMPLE" source-path
                              (first (:counterexample-artifacts artifact))
                              {:missing-fields [:regression-fixture]}))
    (when-not (= :passed (get-in artifact [:plugin-evidence-report :status]))
      (c18-verification-fail! "C18-PLUGIN" source-path
                              (:plugin-evidence-report artifact)
                              {:missing-fields [:plugin-evidence-report]}))
    (when-not (every? #(= :passed (:status %))
                      (:target-lowering-conformance artifact))
      (c18-verification-fail! "C18-BACKEND" source-path
                              (first (:target-lowering-conformance artifact))
                              {:missing-fields [:target-lowering-conformance]}))
    (when-not (= (set c18-verification-diagnostic-ids) diagnostics)
      (c18-verification-fail! "C18-EVIDENCE" source-path
                              (:verification-diagnostic-stream artifact)
                              {:missing-fields [:verification-diagnostics]})))
  :complete)

(defn c18-verification-capability-proof
  [artifact]
  (let [risk-records (:pass-risk-classification artifact)
        evidence-records (:pass-evidence-records artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:verification-diagnostic-stream
                                       :diagnostics])))]
    {:c17-plugin-input-verified?
     (= :complete (get-in artifact
                          [:c17-plugin-artifact
                           :capability-based-proof :status]))
     :pass-risk-classification-complete?
     (every? #(set/subset? (set c18-pass-risk-required-fields)
                           (set (keys %)))
             risk-records)
     :high-risk-evidence-present?
     (every? (fn [risk]
               (let [record (first (filter #(= (:pass %)
                                               (:pass risk))
                                           evidence-records))]
                 (and record
                      (= :present (:status record))
                      (set/subset? (:minimum-evidence risk)
                                   (:evidence record)))))
             (filter #(#{:high :critical} (:risk %)) risk-records))
     :translation-validation-accepted?
     (every? #(= :accepted (:result %))
             (:translation-validation-logs artifact))
     :proofs-and-certificates-accepted?
     (every? #(= :accepted (:status %))
             (:proof-or-certificate-references artifact))
     :diagnostics-preserve-source-and-generated-origin?
     (every? #(and (get-in % [:primary :span])
                   (seq (:related %))
                   (seq (:origin-chain %)))
             (get-in artifact [:verification-diagnostic-stream
                               :diagnostics]))
     :differential-and-property-fixtures-passed?
     (= :passed (get-in artifact
                        [:differential-and-property-fixture-results
                         :status]))
     :trust-report-complete?
     (= :complete (get-in artifact [:compiler-trust-report :status]))
     :release-gate-blocks-missing-evidence?
     (every? #(= :blocked (:release-artifact-status %))
             (:release-gate-failure-fixtures artifact))
     :counterexample-regression-captured?
     (every? #(and (= :captured (:status %))
                   (true? (:regression-fixture-created? %)))
             (:counterexample-artifacts artifact))
     :experimental-gates-explicit?
     (every? #(= :explicit-feature-gate (:gate %))
             (:experimental-pass-gates artifact))
     :plugin-evidence-policy-passed?
     (= :passed (get-in artifact [:plugin-evidence-report :status]))
     :backend-conformance-passed?
     (every? #(= :passed (:status %))
             (:target-lowering-conformance artifact))
     :diagnostics-covered?
     (= (set c18-verification-diagnostic-ids) diagnostics)
     :status :complete}))

(defn compiler-c18-verification-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (c18-verification-source-overrides module)
        _ (c18-verification-validate-source-overrides! source-path
                                                       source-overrides)
        plugin-artifact (compiler-c17-plugin-source-artifact source-path
                                                             source-text)
        input-id (:artifact-id plugin-artifact)
        risk-records (c18-pass-risk-records)
        pass-evidence-records
        (mapv (fn [risk]
                {:artifact :gravity/pass-evidence
                 :pass (:pass risk)
                 :version (:version risk)
                 :risk (:risk risk)
                 :required (:minimum-evidence risk)
                 :evidence (:minimum-evidence risk)
                 :evidence-artifacts [(str "sha256:c18-evidence-"
                                           (name (:pass risk)))]
                 :status :present})
              risk-records)
        translation-validation-logs
        [{:artifact :gravity/translation-validation
          :pass :bounds-check-elide
          :input input-id
          :output "sha256:c18-bounds-check-elide-output"
          :changed-functions [:safe-index]
          :properties #{:same-observable-result :same-effects
                        :same-safety-outcomes}
          :method :symbolic-plus-fixtures
          :proofs [:proof/c18-bounds-check-dominance]
          :counterexamples []
          :result :accepted}
         {:artifact :gravity/translation-validation
          :pass :plugin-loop-fuser
          :input input-id
          :output "sha256:c18-loop-fuser-output"
          :changed-functions [:loop-body]
          :properties #{:same-observable-result :same-effects}
          :method :differential-fixtures
          :proofs [:proof/c18-loop-fuser-effect-order]
          :counterexamples []
          :result :accepted}]
        diagnostic-stream (c18-verification-diagnostic-stream source-path
                                                              input-id)
        artifact-base
        {:kind :gravity/stage0-c18-compiler-verification-artifact
         :task "P06-D097"
         :document-set ["C18"]
         :governing-document c18-verification-governing-document
         :pass {:name :c18-compiler-verification
                :input :compiler-plugin-artifact
                :output :compiler-verification-and-trust-artifact
                :requires [:c17-plugin-artifact :risk-policy
                           :evidence-policy :translation-validation
                           :proof-certificate-policy :trust-report-policy
                           :release-gate-policy]
                :preserves [:source-spans :generated-origins :profile
                            :target :diagnostics :proofs :capabilities]
                :emits [:compiler-verification-plan
                        :pass-risk-classification
                        :pass-evidence-records
                        :translation-validation-logs
                        :proof-or-certificate-references
                        :differential-and-property-fixture-results
                        :compiler-trust-report :release-gate-report
                        :release-gate-failure-fixtures
                        :counterexample-artifacts
                        :experimental-pass-gates
                        :plugin-evidence-report
                        :target-lowering-conformance
                        :verification-diagnostic-stream]
                :rejects c18-verification-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :c17-plugin-artifact
         (select-keys plugin-artifact
                      [:kind :task :artifact-id :governing-document
                       :capability-based-proof])
         :plugin-artifact-kind (:kind plugin-artifact)
         :plugin-artifact-hash input-id
         :compiler-verification-plan
         {:artifact :gravity/compiler-verification-plan
          :status :complete
          :evidence-policy :risk-based
          :passes (mapv :pass risk-records)
          :required-evidence-families
          #{:golden-fixtures :fuzz :translation-validation
            :proof-dominance-check :backend-conformance
            :differential-execution :sandbox-tests :contract-verifier}
          :release-policy :block-affected-profiles-on-failure}
         :pass-risk-classification risk-records
         :pass-evidence-records pass-evidence-records
         :stage-verifier-reports
         (mapv (fn [risk]
                 {:artifact :gravity/stage-verifier-report
                  :pass (:pass risk)
                  :artifact-kinds (:artifact-kinds risk)
                  :source-or-generated-origin-preserved? true
                  :status :passed})
               risk-records)
         :translation-validation-logs translation-validation-logs
         :proof-or-certificate-references
         [{:proof :proof/c18-bounds-check-dominance
           :pass :bounds-check-elide
           :status :accepted}
          {:certificate :cert/c18-safety-check-elision
           :pass :bounds-check-elide
           :status :accepted}
          {:proof :proof/c18-loop-fuser-effect-order
           :pass :plugin-loop-fuser
           :status :accepted}]
         :differential-and-property-fixture-results
         {:artifact :gravity/compiler-fixture-results
          :status :passed
          :families {:front-end {:golden 8 :fuzz 64 :status :passed}
                     :optimization {:translation-validation 2
                                    :property 12
                                    :status :passed}
                     :backend {:differential 5
                               :conformance 4
                               :status :passed}}}
         :compiler-trust-report
         {:artifact :gravity/compiler-trust-report
          :compiler "gravity-stage0-clojure"
          :profiles {:hosted {:required-evidence :high
                              :blocked-passes []}
                     :native {:required-evidence :critical
                              :blocked-passes [:gpu-lowering]}}
          :targets {:jvm {:required-evidence :high
                          :blocked-passes []}}
          :passes (mapv #(select-keys % [:pass :risk
                                          :minimum-evidence
                                          :release-gate])
                        risk-records)
          :artifact-kinds
          (set (mapcat :artifact-kinds risk-records))
          :known-gaps [{:pass :gpu-lowering
                        :profiles #{:gpu}
                        :targets #{:gpu}
                        :status :experimental
                        :gate :explicit-feature-gate}]
          :release-gates [:verifiers :high-risk-evidence
                          :target-lowering-conformance
                          :stale-proof-rejection
                          :diagnostic-goldens
                          :self-hosting-comparison]
          :status :complete}
         :release-gate-report
         {:artifact :gravity/release-gate-report
          :status :passed
          :checks [:verifier-pass-every-artifact
                   :no-active-critical-failures
                   :high-risk-evidence-present
                   :target-lowering-conformance
                   :stale-proof-and-certificate-rejection
                   :diagnostic-golden-fixtures]
          :release-artifacts :allowed-for-hosted-jvm
          :blocked-experimental-passes [:gpu-lowering]}
         :release-gate-failure-fixtures
         [{:artifact :gravity/release-gate-failure
           :pass :gpu-lowering
           :missing-evidence #{:backend-conformance
                               :differential-execution}
           :affected-profiles #{:gpu}
           :affected-targets #{:gpu}
           :diagnostic "C18-RELEASE-GATE"
           :release-artifact-status :blocked}]
         :counterexample-artifacts
         [{:artifact :gravity/counterexample
           :source-fixture "bootstrap/clojure/fixtures/rejected/compiler-verify-c18-validation.gravity"
           :input-artifact input-id
           :output-artifact "sha256:c18-invalid-optimization-output"
           :violated-property :same-safety-outcomes
           :diagnostic-stream :gravity/c18-verification-diagnostic-stream
           :minimized-reproducer "compiler-verify-c18-validation.gravity"
           :affected-pass :bounds-check-elide
           :pass-version "stage0-c18"
           :status :captured
           :regression-fixture-created? true}]
         :experimental-pass-gates
         [{:pass :gpu-lowering
           :profiles #{:gpu}
           :targets #{:gpu}
           :gate :explicit-feature-gate
           :release-default :disabled
           :artifact-status :not-release-quality}]
         :plugin-evidence-report
         {:artifact :gravity/plugin-evidence-report
          :plugin 'gravity.plugins.stage0/loop-fuser
          :required #{:sandbox-tests :contract-verifier
                      :fixture-suite}
          :available #{:sandbox-tests :contract-verifier
                       :fixture-suite}
          :status :passed}
         :target-lowering-conformance
         [{:artifact :gravity/target-lowering-conformance
           :target :jvm
           :profiles #{:hosted}
           :source-core-mir-intent #{:same-observable-result
                                     :same-effects
                                     :same-safety-outcomes}
           :emitted-artifact-behavior :matched
           :method :differential-execution
           :status :passed}]
         :verification-diagnostic-stream diagnostic-stream
         :c18-verification-results
         {:documents ["C18"]
          :task "P06-D097"
          :required-diagnostic-ids c18-verification-diagnostic-ids
          :c17-input-status :complete
          :plan-status :complete
          :risk-status :complete
          :evidence-status :complete
          :translation-validation-status :complete
          :proof-certificate-status :complete
          :fixture-status :complete
          :trust-report-status :complete
          :release-gate-status :complete
          :counterexample-status :complete
          :experimental-gate-status :complete
          :plugin-status :complete
          :backend-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (c18-verification-validate! source-path artifact-base)
        capability-proof (c18-verification-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn compiler-c18-verification-file-artifact
  [path]
  (compiler-c18-verification-source-artifact path (slurp path)))

(def backend-interface-governing-documents
  ["docs/phase-07-backend-architecture/098-b1-backend-interface-specification.md"
   "docs/phase-07-backend-architecture/111-b14-backend-conformance-test-plan.md"])

(def backend-interface-diagnostic-ids
  ["B1-INPUT"
   "B1-PROFILE"
   "B1-TARGET"
   "B1-ABI"
   "B1-RUNTIME"
   "B1-PROOF"
   "B1-CAPABILITY"
   "B1-UNSUPPORTED"
   "B1-METADATA"
   "B14-COVERAGE"
   "B14-METADATA"
   "B14-ARTIFACT"])

(def backend-interface-diagnostic-messages
  {"B1-INPUT" "backend input is unverified or incomplete"
   "B1-PROFILE" "backend profile compatibility failed"
   "B1-TARGET" "backend target feature is unsupported"
   "B1-ABI" "backend ABI or layout is not representable"
   "B1-RUNTIME" "backend runtime or provider dependency is missing or forbidden"
   "B1-PROOF" "backend target assumption lacks proof metadata"
   "B1-CAPABILITY" "backend provider selection loses required authority"
   "B1-UNSUPPORTED" "backend MIR operation or domain anchor is unsupported"
   "B1-METADATA" "backend artifact metadata is incomplete"
   "B14-COVERAGE" "backend conformance fixture coverage is incomplete"
   "B14-METADATA" "backend conformance metadata preservation failed"
   "B14-ARTIFACT" "backend artifact manifest validation failed"})

(def backend-interface-override-diagnostics
  {:b1-input ["B1-INPUT" :backend-input]
   :b1-profile ["B1-PROFILE" :profile-eligibility]
   :b1-target ["B1-TARGET" :target-eligibility]
   :b1-abi ["B1-ABI" :abi-layout]
   :b1-runtime ["B1-RUNTIME" :runtime-provider]
   :b1-proof ["B1-PROOF" :proof-metadata]
   :b1-capability ["B1-CAPABILITY" :capability-preservation]
   :b1-unsupported ["B1-UNSUPPORTED" :unsupported-operation]
   :b1-metadata ["B1-METADATA" :artifact-metadata]
   :b14-coverage ["B14-COVERAGE" :conformance-coverage]
   :b14-metadata ["B14-METADATA" :conformance-metadata]
   :b14-artifact ["B14-ARTIFACT" :conformance-artifact]})

(def backend-manifest-required-fields
  [:artifact :backend :version :accepts :emits :requires
   :supports-profiles :rejects])

(def backend-input-required-fields
  [:input :profile :target :abi :runtime :providers :effects
   :capabilities :safety :proofs :source-map :dependencies])

(defn backend-interface-source-overrides
  [module]
  (or (get-in module [:metadata :backend :interface])
      (get-in module [:metadata :backend])
      {}))

(defn backend-interface-fail!
  [id source-path subject extra]
  (fail! id
         (get backend-interface-diagnostic-messages id
              "backend interface validation failed")
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :backend-interface
                 :stage (or (:stage subject) :backend-interface)
                 :backend-id (:backend-id subject)
                 :input-artifact-id (:input-artifact-id subject)
                 :mir-op (:mir-op subject)
                 :domain-anchor (:domain-anchor subject)
                 :profile (:profile subject)
                 :target (:target subject)
                 :missing-evidence (:missing-evidence subject)
                 :fallback-status (:fallback-status subject)
                 :remediation "Feed the backend only verified MIR or domain IR with profile, target, ABI, runtime, effects, capabilities, safety, proof, provenance, artifact, and conformance metadata."}
                extra)))

(defn backend-interface-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (let [[id subject-kind] (get backend-interface-override-diagnostics
                                 fail-kind)]
      (when id
        (backend-interface-fail!
         id source-path
         {:stage subject-kind
          :backend-id :gravity.backend/interface-v1
          :input-artifact-id (str "backend-input-" (name fail-kind))
          :mir-op :runtime-check
          :domain-anchor :efir
          :profile :hosted
          :target :jvm
          :missing-evidence [fail-kind]
          :fallback-status :unavailable}
         {:missing-fields [fail-kind]})))))

(defn backend-interface-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/backend-diagnostic-stream
   :stage :backend-interface
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :backend-interface
            :message-key (keyword "backend"
                                  (str/lower-case
                                   (str/replace id #"_" "-")))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "backend-syntax-" index)
                      :artifact input-id}
            :backend-id :gravity.backend/interface-v1
            :input-artifact-id input-id
            :mir-op (if (= id "B1-UNSUPPORTED")
                      :target-specific-opcode
                      :runtime-check)
            :domain-anchor (if (= id "B1-UNSUPPORTED") :opaque-domain :efir)
            :profile :hosted
            :target :jvm
            :missing-evidence #{:proof-metadata :source-map}
            :fallback-status :recorded
            :facts {:rule id
                    :metadata-required? true
                    :safe-ub-policy :reject}
            :remediation [{:kind :provide-backend-evidence}
                          {:kind :select-supported-target}]
            :redactions []
            :ordering-key [id :gravity.backend/interface-v1 :jvm]})
         backend-interface-diagnostic-ids
         (range))
   :status :complete})

(defn backend-interface-validate!
  [source-path artifact]
  (let [manifest (:backend-manifest artifact)
        input-packet (:backend-input-packet artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:backend-diagnostic-stream
                                       :diagnostics])))]
    (when-not (set/subset? (set backend-manifest-required-fields)
                           (set (keys manifest)))
      (backend-interface-fail! "B1-INPUT" source-path manifest
                               {:missing-fields
                                (vec (remove (set (keys manifest))
                                             backend-manifest-required-fields))}))
    (when-not (set/subset? (set backend-input-required-fields)
                           (set (keys input-packet)))
      (backend-interface-fail! "B1-INPUT" source-path input-packet
                               {:missing-fields
                                (vec (remove (set (keys input-packet))
                                             backend-input-required-fields))}))
    (when-not (= :eligible (get-in artifact
                                   [:backend-input-eligibility-report
                                    :decision]))
      (backend-interface-fail! "B1-PROFILE" source-path
                               (:backend-input-eligibility-report artifact)
                               {:missing-fields [:eligibility]}))
    (when-not (every? #(= :passed (:status %))
                      (:eligibility-checks artifact))
      (backend-interface-fail! "B1-TARGET" source-path
                               (first (:eligibility-checks artifact))
                               {:missing-fields [:eligibility-checks]}))
    (when-not (= :accepted (get-in artifact
                                   [:proof-to-target-metadata-map :status]))
      (backend-interface-fail! "B1-PROOF" source-path
                               (:proof-to-target-metadata-map artifact)
                               {:missing-fields [:proof-to-target-metadata]}))
    (when-not (= :preserved (get-in artifact
                                    [:capability-preservation-report
                                     :status]))
      (backend-interface-fail! "B1-CAPABILITY" source-path
                               (:capability-preservation-report artifact)
                               {:missing-fields [:capability-preservation]}))
    (when-not (= :recorded (get-in artifact
                                   [:unsupported-feature-report :status]))
      (backend-interface-fail! "B1-UNSUPPORTED" source-path
                               (:unsupported-feature-report artifact)
                               {:missing-fields [:unsupported-feature-report]}))
    (when-not (every? #(and (:provenance %) (:source-debug-map %)
                            (:safety-evidence %) (:conformance %))
                      (:target-artifact-manifest artifact))
      (backend-interface-fail! "B1-METADATA" source-path
                               (first (:target-artifact-manifest artifact))
                               {:missing-fields [:target-artifact-metadata]}))
    (when-not (= :passed (get-in artifact
                                 [:backend-conformance-record :status]))
      (backend-interface-fail! "B14-COVERAGE" source-path
                               (:backend-conformance-record artifact)
                               {:missing-fields [:backend-conformance-record]}))
    (when-not (= :preserved (get-in artifact
                                    [:metadata-preservation-report :status]))
      (backend-interface-fail! "B14-METADATA" source-path
                               (:metadata-preservation-report artifact)
                               {:missing-fields [:metadata-preservation]}))
    (when-not (= :valid (get-in artifact
                                [:artifact-manifest-validation-report
                                 :status]))
      (backend-interface-fail! "B14-ARTIFACT" source-path
                               (:artifact-manifest-validation-report artifact)
                               {:missing-fields [:artifact-manifest-validation]}))
    (when-not (= (set backend-interface-diagnostic-ids) diagnostics)
      (backend-interface-fail! "B14-COVERAGE" source-path
                               (:backend-diagnostic-stream artifact)
                               {:missing-fields [:backend-diagnostics]})))
  :complete)

(defn backend-interface-capability-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:backend-diagnostic-stream
                                       :diagnostics])))]
    {:c18-verification-input-verified?
     (= :complete (get-in artifact
                          [:c18-verification-artifact
                           :capability-based-proof :status]))
     :backend-manifest-complete?
     (set/subset? (set backend-manifest-required-fields)
                  (set (keys (:backend-manifest artifact))))
     :verified-input-packet-complete?
     (set/subset? (set backend-input-required-fields)
                  (set (keys (:backend-input-packet artifact))))
     :eligibility-passed?
     (and (= :eligible (get-in artifact
                               [:backend-input-eligibility-report
                                :decision]))
          (every? #(= :passed (:status %))
                  (:eligibility-checks artifact)))
     :unchecked-ir-rejected?
     (= :rejected (get-in artifact
                          [:unchecked-ir-rejection-record :status]))
     :undefined-behavior-rejected?
     (= :rejected (get-in artifact
                          [:undefined-behavior-rejection-record :status]))
     :proof-backed-target-metadata?
     (= :accepted (get-in artifact
                          [:proof-to-target-metadata-map :status]))
     :artifact-metadata-preserved?
     (and (every? #(and (:provenance %) (:source-debug-map %)
                        (:safety-evidence %) (:conformance %))
                  (:target-artifact-manifest artifact))
          (= :preserved (get-in artifact
                                [:metadata-preservation-report :status])))
     :capabilities-preserved?
     (= :preserved (get-in artifact
                           [:capability-preservation-report :status]))
     :unsupported-features-recorded?
     (= :recorded (get-in artifact
                          [:unsupported-feature-report :status]))
     :conformance-record-passed?
     (= :passed (get-in artifact
                        [:backend-conformance-record :status]))
     :artifact-manifest-valid?
     (= :valid (get-in artifact
                       [:artifact-manifest-validation-report :status]))
     :diagnostics-covered?
     (= (set backend-interface-diagnostic-ids) diagnostics)
     :status :complete}))

(defn backend-interface-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (backend-interface-source-overrides module)
        _ (backend-interface-validate-source-overrides! source-path
                                                        source-overrides)
        verification-artifact (compiler-c18-verification-source-artifact
                               source-path source-text)
        input-id (:artifact-id verification-artifact)
        diagnostic-stream (backend-interface-diagnostic-stream source-path
                                                               input-id)
        artifact-base
        {:kind :gravity/stage0-backend-interface-artifact
         :task "P07-T01"
         :document-set ["B1" "B14"]
         :governing-documents backend-interface-governing-documents
         :pass {:name :backend-interface
                :input :compiler-verification-and-trust-artifact
                :output :backend-interface-and-conformance-artifact
                :requires [:verified-mir-or-domain-ir :profile-manifest
                           :target-manifest :abi-policy :runtime-provider
                           :effects :capabilities :safety :proofs
                           :source-map :dependencies]
                :preserves [:source-spans :generated-origins :profile
                            :target :effects :capabilities :safety
                            :proofs :unsafe-audit-ids :provenance]
                :emits [:backend-manifest :backend-input-eligibility-report
                        :target-artifact-manifest :abi-layout-record
                        :runtime-provider-dependency-record
                        :proof-to-target-metadata-map :source-debug-map
                        :unsupported-feature-report
                        :backend-diagnostic-stream
                        :backend-conformance-record]
                :rejects backend-interface-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :c18-verification-artifact
         (select-keys verification-artifact
                      [:kind :task :artifact-id :governing-document
                       :capability-based-proof])
         :compiler-verification-artifact-kind (:kind verification-artifact)
         :compiler-verification-artifact-hash input-id
         :backend-manifest
         {:artifact :gravity/backend-manifest
          :backend :gravity.backend/interface-v1
          :version "1"
          :accepts #{:gravity/mir :gravity/domain-ir}
          :emits #{:object :library :bytecode :source
                   :workflow-graph :hdl :query-plan}
          :requires #{:profile :target :abi :runtime :effects
                      :capabilities :safety}
          :supports-profiles #{:core :hosted :native :firmware :kernel
                               :gpu :hardware :distributed :ai}
          :rejects #{:unverified-ir :unsupported-op :missing-proof
                     :implicit-ub :ambient-capability :profile-violation}
          :status :complete}
         :backend-input-packet
         {:input {:kind :gravity/mir
                  :id input-id
                  :verification-status :accepted}
          :profile "profile-manifest:hosted"
          :target "target-manifest:jvm"
          :abi "abi-policy:jvm-stage0"
          :runtime "runtime-manifest:clojure-jvm-stage0"
          :providers "provider-selection:stage0"
          :effects "effect-summary:stage0"
          :capabilities "capability-summary:stage0"
          :safety "safety-bundle:stage0"
          :proofs "proof-table:stage0"
          :source-map "source-map:stage0"
          :dependencies "dependency-graph:stage0"}
         :backend-input-eligibility-report
         {:artifact :gravity/backend-input-eligibility-report
          :backend :gravity.backend/interface-v1
          :input input-id
          :profile :hosted
          :target :jvm
          :decision :eligible
          :status :complete}
         :eligibility-checks
         [{:check :verified-input :status :passed}
          {:check :profile-backend-compatibility :status :passed}
          {:check :target-feature-support :status :passed}
          {:check :runtime-availability :status :passed}
          {:check :abi-representability :status :passed}
          {:check :layout-representability :status :passed}
          {:check :provider-availability :status :passed}
          {:check :effect-capability-preservation :status :passed}
          {:check :safety-bundle-completeness :status :passed}
          {:check :proof-validity :status :passed}
          {:check :source-debug-map-preservation :status :passed}]
         :unchecked-ir-rejection-record
         {:artifact :gravity/backend-rejection
          :diagnostic "B1-INPUT"
          :input :unverified-mir
          :status :rejected}
         :undefined-behavior-rejection-record
         {:artifact :gravity/backend-rejection
          :diagnostic "B1-PROOF"
          :assumption :signed-overflow-undefined
          :status :rejected}
         :target-artifact-manifest
         [{:artifact :gravity/target-artifact
           :kind :bytecode
           :digest "sha256:p07-stage0-jvm-bytecode-metadata"
           :backend :gravity.backend/interface-v1
           :backend-version "1"
           :source-input input-id
           :profile :hosted
           :target :jvm
           :abi-layout "abi-layout:jvm-stage0"
           :runtime-provider "runtime-provider:clojure-jvm-stage0"
           :safety-evidence "safety-bundle:stage0"
           :proof-summary "proof-table:stage0"
           :capability-summary "capability-summary:stage0"
           :source-debug-map "source-debug-map:stage0"
           :unsafe-audit-ids []
           :dependencies ["dependency-graph:stage0"]
           :conformance "backend-conformance:p07-t01"
           :provenance {:compiler "gravity-stage0-clojure"
                        :pass-history ["C18" "B1" "B14"]}}]
         :abi-layout-record
         {:artifact :gravity/abi-layout-record
          :target :jvm
          :layout-policy :managed-runtime
          :representability :passed
          :status :complete}
         :runtime-provider-dependency-record
         {:artifact :gravity/runtime-provider-dependency-record
          :runtime :clojure-jvm-stage0
          :providers [:stdout :checked-exception :managed-memory]
          :hidden-dependencies []
          :status :complete}
         :proof-to-target-metadata-map
         {:artifact :gravity/proof-to-target-metadata-map
          :status :accepted
          :assumptions [{:target-assumption :no-signed-overflow
                         :proof :proof/c18-bounds-check-dominance}
                        {:target-assumption :dereferenceable-managed-reference
                         :proof :proof/c18-safety-check-elision}
                        {:target-assumption :host-exception-mapping
                         :proof :proof/c18-loop-fuser-effect-order}]}
         :source-debug-map
         {:artifact :gravity/source-debug-map
          :input input-id
          :source-spans :preserved
          :generated-origin-chain :preserved
          :status :complete}
         :capability-preservation-report
         {:artifact :gravity/backend-capability-preservation
          :capabilities (:capabilities module)
          :provider-selection :stage0
          :status :preserved}
         :unsupported-feature-report
         {:artifact :gravity/unsupported-feature-report
          :status :recorded
          :unsupported [{:mir-op :target-specific-opcode
                         :diagnostic "B1-UNSUPPORTED"
                         :fallback :reject}]}
         :backend-diagnostic-stream diagnostic-stream
         :backend-conformance-record
         {:artifact :gravity/backend-conformance-record
          :status :passed
          :suite :p07-t01-backend-interface
          :positive-lowering-results [{:fixture :backend-interface-positive
                                       :status :passed}]
          :negative-diagnostic-results
          (mapv (fn [id]
                  {:diagnostic id :status :matched})
                backend-interface-diagnostic-ids)
          :target-availability {:jvm :available}
          :evidence-pack "backend-conformance-pack:p07-t01"}
         :metadata-preservation-report
         {:artifact :gravity/backend-metadata-preservation-report
          :status :preserved
          :fields [:source-spans :generated-origin-chain :types :effects
                   :capabilities :safety :proofs :unsafe-audit-ids
                   :profile :target :runtime :abi :conformance]}
         :artifact-manifest-validation-report
         {:artifact :gravity/artifact-manifest-validation-report
          :status :valid
          :validated-artifacts ["sha256:p07-stage0-jvm-bytecode-metadata"]}
         :backend-interface-results
         {:documents ["B1" "B14"]
          :task "P07-T01"
          :required-diagnostic-ids backend-interface-diagnostic-ids
          :c18-input-status :complete
          :manifest-status :complete
          :input-contract-status :complete
          :eligibility-status :complete
          :artifact-status :complete
          :metadata-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (backend-interface-validate! source-path artifact-base)
        capability-proof (backend-interface-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn backend-interface-file-artifact
  [path]
  (backend-interface-source-artifact path (slurp path)))

(def native-lowering-governing-documents
  ["docs/phase-07-backend-architecture/099-b2-c-backend-design.md"
   "docs/phase-07-backend-architecture/100-b3-llvm-backend-design.md"
   "docs/phase-07-backend-architecture/104-b7-mlir-backend-design.md"
   "docs/phase-07-backend-architecture/110-b13-artifact-emission-specification.md"
   "docs/phase-07-backend-architecture/111-b14-backend-conformance-test-plan.md"
   "docs/phase-06-compiler-architecture/093-c14-target-lowering-architecture.md"])

(def native-lowering-diagnostic-ids
  ["B2-DIALECT"
   "B2-UB"
   "B2-ABI"
   "B2-POINTER"
   "B2-NUMERIC"
   "B2-RUNTIME"
   "B2-FFI"
   "B2-MMIO"
   "B2-MANIFEST"
   "B3-TARGET"
   "B3-METADATA"
   "B3-UB"
   "B3-POINTER"
   "B3-NUMERIC"
   "B3-ATOMIC"
   "B3-RUNTIME"
   "B3-ABI"
   "B3-PASS"
   "B3-MANIFEST"
   "B7-DIALECT"
   "B7-VERIFY"
   "B7-CONVERSION"
   "B7-METADATA"
   "B7-EFFECT"
   "B7-NUMERIC"
   "B7-ALIAS"
   "B7-PASS"
   "B7-HANDOFF"
   "B7-MANIFEST"
   "B13-SCHEMA"
   "B13-HASH"
   "B13-PROVENANCE"
   "B13-SOURCEMAP"
   "B13-EVIDENCE"
   "B13-TARGET"
   "B13-CONFORMANCE"
   "B13-REPRODUCIBILITY"
   "B13-RELEASE"
   "B13-GRAPH"
   "B14-POSITIVE"
   "B14-NEGATIVE"
   "B14-DIFFERENTIAL"
   "B14-NONDETERMINISM"
   "B14-SKIP"
   "B14-EVIDENCE"])

(def native-lowering-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             native-lowering-diagnostic-ids)))

(defn native-lowering-backend-for-diagnostic
  [id]
  (cond
    (str/starts-with? id "B2-") :gravity.backend/c
    (str/starts-with? id "B3-") :gravity.backend/llvm
    (str/starts-with? id "B7-") :gravity.backend/mlir
    (str/starts-with? id "B13-") :gravity.backend/artifact-emission
    :else :gravity.backend/conformance))

(defn native-lowering-stage-for-diagnostic
  [id]
  (cond
    (str/starts-with? id "B2-") :c-backend
    (str/starts-with? id "B3-") :llvm-backend
    (str/starts-with? id "B7-") :mlir-backend
    (str/starts-with? id "B13-") :artifact-emission
    :else :backend-conformance))

(defn native-lowering-diagnostic-message
  [id]
  (cond
    (str/starts-with? id "B2-") "C backend lowering contract failed"
    (str/starts-with? id "B3-") "LLVM backend lowering contract failed"
    (str/starts-with? id "B7-") "MLIR backend lowering contract failed"
    (str/starts-with? id "B13-") "backend artifact emission contract failed"
    :else "backend conformance contract failed"))

(def native-artifact-manifest-required-fields
  [:schema-version :kind :backend :profile :target :content-hash :inputs
   :evidence :provenance])

(defn native-lowering-source-overrides
  [module]
  (or (get-in module [:metadata :backend :native-lowering])
      (get-in module [:metadata :backend :native])
      (get-in module [:metadata :backend :artifact-emission])
      {}))

(defn native-lowering-fail!
  [id source-path subject extra]
  (fail! id
         (native-lowering-diagnostic-message id)
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :native-backend-lowering
                 :stage (or (:stage subject)
                            (native-lowering-stage-for-diagnostic id))
                 :backend (or (:backend subject)
                              (native-lowering-backend-for-diagnostic id))
                 :profile (or (:profile subject) :native)
                 :target (or (:target subject) :x86_64-stage0)
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :checked-add)
                 :domain-anchor (:domain-anchor subject)
                 :missing-evidence (:missing-evidence subject)
                 :target-construct (:target-construct subject)
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Emit native backend artifacts only from verified backend-interface input with pinned ABI/layout/runtime, proof-backed target metadata, preserved source/proof/capability records, valid artifact manifests, and conformance evidence."}
                extra)))

(defn native-lowering-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get native-lowering-override-diagnostics fail-kind)]
      (native-lowering-fail!
       id source-path
       {:stage (native-lowering-stage-for-diagnostic id)
        :backend (native-lowering-backend-for-diagnostic id)
        :artifact-id (str "native-lowering-" (name fail-kind))
        :missing-evidence [fail-kind]
        :target-construct fail-kind}
       {:missing-fields [fail-kind]}))))

(defn native-lowering-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/backend-diagnostic-stream
   :stage :native-backend-lowering
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage (native-lowering-stage-for-diagnostic id)
            :backend (native-lowering-backend-for-diagnostic id)
            :message-key (keyword "backend-native"
                                  (str/lower-case
                                   (str/replace id #"-" "-")))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "native-backend-syntax-" index)
                      :artifact input-id}
            :profile :native
            :target :x86_64-stage0
            :mir-op (case id
                      "B2-MMIO" :volatile-load
                      "B3-ATOMIC" :atomic-compare-exchange
                      "B7-CONVERSION" :domain-anchor-lowering
                      :checked-add)
            :domain-anchor (when (str/starts-with? id "B7-") :efir)
            :missing-evidence #{:proof-metadata :source-map
                                :artifact-manifest}
            :target-construct id
            :fallback-status :rejected
            :facts {:safe-ub-policy :reject
                    :metadata-required? true
                    :artifact-emission-required? true}
            :remediation [{:kind :provide-native-backend-evidence}
                          {:kind :pin-target-assumption}
                          {:kind :preserve-artifact-metadata}]
            :redactions []
            :ordering-key [id :native-backend-lowering :x86_64-stage0]})
         native-lowering-diagnostic-ids
         (range))
   :status :complete})

(defn native-lowering-artifact-manifest
  [backend kind content input-id evidence-id]
  {:schema-version 1
   :kind kind
   :backend backend
   :profile :native
   :target :x86_64-stage0
   :content-hash (c4-artifact-id content)
   :inputs {:source input-id
            :mir input-id
            :backend-interface input-id}
   :evidence {:safety "safety-bundle:stage0"
              :proofs evidence-id
              :capabilities "capability-summary:stage0"
              :effects "effect-summary:stage0"
              :conformance "backend-conformance-pack:p07-t02"}
   :provenance {:compiler "gravity-stage0-clojure"
                :passes ["C14" "B1" "B2/B3/B7" "B13" "B14"]
                :dependencies "dependency-graph:stage0"}
   :reproducibility {:timestamp-policy :none
                     :nondeterminism []
                     :status :recorded}})

(defn native-lowering-validate!
  [source-path artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:native-diagnostic-stream
                                       :diagnostics])))
        manifests (:artifact-manifests artifact)]
    (when-not (= :complete (get-in artifact
                                   [:backend-interface-artifact
                                    :capability-based-proof :status]))
      (native-lowering-fail! "B13-EVIDENCE" source-path
                             (:backend-interface-artifact artifact)
                             {:missing-fields [:backend-interface-proof]}))
    (when-not (= #{:gravity.backend/c :gravity.backend/llvm
                   :gravity.backend/mlir}
                 (set (map :backend
                           (:target-lowering-manifest artifact))))
      (native-lowering-fail! "B14-COVERAGE" source-path
                             (:target-lowering-manifest artifact)
                             {:missing-fields [:native-backends]}))
    (when-not (= :complete (get-in artifact [:c-backend :status]))
      (native-lowering-fail! "B2-MANIFEST" source-path
                             (:c-backend artifact)
                             {:missing-fields [:c-backend]}))
    (when-not (= :rejected (get-in artifact
                                   [:c-backend :ub-rejection :status]))
      (native-lowering-fail! "B2-UB" source-path
                             (get-in artifact [:c-backend :ub-rejection])
                             {:missing-fields [:ub-rejection]}))
    (when-not (= :complete (get-in artifact [:llvm-backend :status]))
      (native-lowering-fail! "B3-MANIFEST" source-path
                             (:llvm-backend artifact)
                             {:missing-fields [:llvm-backend]}))
    (when-not (= :gated (get-in artifact
                                [:llvm-backend :metadata-policy
                                 :status]))
      (native-lowering-fail! "B3-METADATA" source-path
                             (get-in artifact
                                     [:llvm-backend :metadata-policy])
                             {:missing-fields [:llvm-metadata-policy]}))
    (when-not (= :complete (get-in artifact [:mlir-backend :status]))
      (native-lowering-fail! "B7-MANIFEST" source-path
                             (:mlir-backend artifact)
                             {:missing-fields [:mlir-backend]}))
    (when-not (= :passed (get-in artifact
                                 [:mlir-backend :verifier-report
                                  :status]))
      (native-lowering-fail! "B7-VERIFY" source-path
                             (get-in artifact
                                     [:mlir-backend :verifier-report])
                             {:missing-fields [:mlir-verifier]}))
    (when-not (every? #(set/subset? (set native-artifact-manifest-required-fields)
                                    (set (keys %)))
                      manifests)
      (native-lowering-fail! "B13-SCHEMA" source-path
                             (first manifests)
                             {:missing-fields [:artifact-manifest-schema]}))
    (when-not (every? #(re-find #"^sha256:" (:content-hash %)) manifests)
      (native-lowering-fail! "B13-HASH" source-path
                             (first manifests)
                             {:missing-fields [:content-hash]}))
    (when-not (= :preserved (get-in artifact
                                    [:metadata-preservation-report
                                     :status]))
      (native-lowering-fail! "B14-METADATA" source-path
                             (:metadata-preservation-report artifact)
                             {:missing-fields [:metadata-preservation]}))
    (when-not (= :passed (get-in artifact
                                 [:backend-conformance-record :status]))
      (native-lowering-fail! "B14-EVIDENCE" source-path
                             (:backend-conformance-record artifact)
                             {:missing-fields [:conformance-evidence]}))
    (when-not (= (set native-lowering-diagnostic-ids) diagnostics)
      (native-lowering-fail! "B14-NEGATIVE" source-path
                             (:native-diagnostic-stream artifact)
                             {:missing-fields [:native-diagnostics]})))
  :complete)

(defn native-lowering-capability-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:native-diagnostic-stream
                                       :diagnostics])))
        manifests (:artifact-manifests artifact)]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:backend-interface-artifact
                           :capability-based-proof :status]))
     :c-lowering-complete?
     (= :complete (get-in artifact [:c-backend :status]))
     :c-undefined-behavior-rejected?
     (= :rejected (get-in artifact [:c-backend :ub-rejection :status]))
     :llvm-lowering-complete?
     (= :complete (get-in artifact [:llvm-backend :status]))
     :llvm-proof-metadata-gated?
     (= :gated (get-in artifact
                       [:llvm-backend :metadata-policy :status]))
     :mlir-lowering-complete?
     (= :complete (get-in artifact [:mlir-backend :status]))
     :mlir-conversion-verified?
     (= :passed (get-in artifact
                        [:mlir-backend :conversion-legality-report
                         :status]))
     :artifact-emission-complete?
     (and (= 3 (count manifests))
          (every? #(set/subset?
                    (set native-artifact-manifest-required-fields)
                    (set (keys %)))
                  manifests)
          (every? #(re-find #"^sha256:" (:content-hash %)) manifests))
     :source-proof-capability-metadata-preserved?
     (= :preserved (get-in artifact
                           [:metadata-preservation-report :status]))
     :conformance-record-passed?
     (= :passed (get-in artifact
                        [:backend-conformance-record :status]))
     :diagnostics-covered?
     (= (set native-lowering-diagnostic-ids) diagnostics)
     :status :complete}))

(defn native-lowering-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (native-lowering-source-overrides module)
        _ (native-lowering-validate-source-overrides! source-path
                                                      source-overrides)
        interface-artifact (backend-interface-source-artifact source-path
                                                              source-text)
        input-id (:artifact-id interface-artifact)
        c-source "/* gravity stage0 P07-T02 C artifact */\n#include <stdint.h>\nint64_t gravity_entry(int64_t x) { return x + 1; }\n"
        c-header "#pragma once\n#include <stdint.h>\nint64_t gravity_entry(int64_t x);\n"
        llvm-ir "; gravity stage0 P07-T02 LLVM artifact\ndefine i64 @gravity_entry(i64 %x) {\nentry:\n  %y = add i64 %x, 1\n  ret i64 %y\n}\n"
        mlir-module "module {\n  func.func @gravity_entry(%x: i64) -> i64 {\n    %c1 = arith.constant 1 : i64\n    %y = arith.addi %x, %c1 : i64\n    return %y : i64\n  }\n}\n"
        c-manifest (native-lowering-artifact-manifest
                    :gravity.backend/c :c-source c-source input-id
                    "proof-map:c-stage0")
        llvm-manifest (native-lowering-artifact-manifest
                       :gravity.backend/llvm :llvm-ir llvm-ir input-id
                       "proof-map:llvm-stage0")
        mlir-manifest (native-lowering-artifact-manifest
                       :gravity.backend/mlir :mlir-module mlir-module
                       input-id "proof-map:mlir-stage0")
        diagnostic-stream (native-lowering-diagnostic-stream source-path
                                                             input-id)
        artifact-base
        {:kind :gravity/stage0-native-lowering-artifact
         :task "P07-T02"
         :document-set ["B2" "B3" "B7" "B13" "B14"]
         :governing-documents native-lowering-governing-documents
         :pass {:name :native-lowering
                :input :backend-interface-and-conformance-artifact
                :output :native-c-llvm-mlir-lowering-artifact
                :requires [:verified-backend-interface :target-manifest
                           :abi-layout :runtime-provider
                           :proof-to-target-metadata :source-debug-map
                           :capability-summary :artifact-manifest]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :safety :proofs
                            :unsafe-audit-ids :profile :target
                            :artifact-provenance]
                :emits [:c-source :c-header :llvm-ir :mlir-module
                        :artifact-manifests :target-lowering-manifest
                        :backend-conformance-record]
                :rejects native-lowering-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :backend-interface-artifact
         (select-keys interface-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :backend-interface-results])
         :backend-interface-artifact-kind (:kind interface-artifact)
         :backend-interface-artifact-hash input-id
         :target-lowering-manifest
         [{:backend :gravity.backend/c
           :target :x86_64-stage0
           :dialect :freestanding-c11
           :artifact-kinds [:c-source :header :build-manifest]
           :status :complete}
          {:backend :gravity.backend/llvm
           :target :x86_64-stage0
           :triple "x86_64-unknown-stage0"
           :data-layout "e-m:e-p:64:64-i64:64-n8:16:32:64"
           :artifact-kinds [:llvm-ir :bitcode-manifest :object-manifest]
           :status :complete}
          {:backend :gravity.backend/mlir
           :target :x86_64-stage0
           :dialects [:gravity.mir :func :arith :scf :cf :memref :llvm]
           :artifact-kinds [:mlir-module :verifier-report
                            :handoff-manifest]
           :status :complete}]
         :c-backend
         {:artifact :gravity/c-backend-manifest
          :backend :gravity.backend/c
          :dialect-selection {:dialect :freestanding-c11
                              :hosted-libc :forbidden
                              :status :pinned}
          :source-files [{:path "gravity_stage0.c"
                          :content c-source
                          :hash (:content-hash c-manifest)}]
          :header-files [{:path "gravity_stage0.h"
                          :content c-header
                          :hash (c4-artifact-id c-header)}]
          :runtime-helper-manifest {:helpers [:panic-trap :bounds-check
                                              :numeric-check]
                                    :hidden-libc-dependencies []
                                    :status :complete}
          :abi-layout-manifest {:data-model :lp64
                                :endianness :little
                                :alignment {:i64 8}
                                :struct-layouts []
                                :status :pinned}
          :proof-to-c-assumption-map
          [{:assumption :no-signed-overflow
            :proof :proof/c18-bounds-check-dominance}
           {:assumption :pointer-provenance
            :proof :proof/c18-lifetime-range}]
          :build-manifest {:compiler-family :stage0-record
                           :flags ["-std=c11" "-fno-strict-aliasing"]
                           :floating-contract :strict
                           :status :complete}
          :ub-rejection {:diagnostic "B2-UB"
                         :construct :signed-overflow
                         :status :rejected}
          :status :complete}
         :llvm-backend
         {:artifact :gravity/llvm-backend-manifest
          :backend :gravity.backend/llvm
          :target-record {:triple "x86_64-unknown-stage0"
                          :cpu "generic"
                          :features #{}
                          :data-layout "e-m:e-p:64:64-i64:64-n8:16:32:64"
                          :relocation-model :static
                          :code-model :small
                          :status :pinned}
          :llvm-ir-files [{:path "gravity_stage0.ll"
                           :content llvm-ir
                           :hash (:content-hash llvm-manifest)}]
          :proof-to-llvm-metadata-map
          [{:metadata :nuw
            :operation :checked-add
            :proof :proof/c18-bounds-check-dominance}
           {:metadata :nonnull
            :operation :managed-reference
            :proof :proof/c18-safety-check-elision}]
          :metadata-policy {:status :gated
                            :forbidden-without-proof
                            [:nuw :nsw :inbounds :noalias :fast-math
                             :dereferenceable :tbaa]}
          :pass-pipeline-record {:passes [:verify-before :instcombine
                                          :verify-after]
                                 :disabled [{:pass :unsafe-fast-math
                                             :reason :missing-strict-proof}]
                                 :metadata-preservation :required
                                 :status :complete}
          :verifier-report {:status :passed
                            :checked [:ir-shape :metadata-gates
                                      :source-map]}
          :status :complete}
         :mlir-backend
         {:artifact :gravity/mlir-backend-manifest
          :backend :gravity.backend/mlir
          :mlir-version "stage0-recorded"
          :dialect-registry-manifest
          {:dialects [:gravity.mir :func :arith :scf :cf :memref :llvm]
           :status :complete}
          :gravity-dialect-operation-schema
          {:operations [:gravity.checked_add :gravity.return]
           :attributes [:source-span :effect :capability :proof :profile]
           :status :complete}
          :mlir-modules [{:path "gravity_stage0.mlir"
                          :content mlir-module
                          :hash (:content-hash mlir-manifest)}]
          :conversion-legality-report {:targets [:llvm]
                                       :remaining-illegal-ops []
                                       :status :passed}
          :pass-pipeline-log [{:pass :canonicalize
                               :facts-preserved [:source-span :proof
                                                 :capability]
                               :facts-invalidated []
                               :verifier-before :passed
                               :verifier-after :passed}]
          :verifier-report {:status :passed
                            :checked [:dialect-registry :operation-schema
                                      :metadata-preservation]}
          :proof-to-dialect-attribute-map
          [{:attribute :arith.no_overflow
            :proof :proof/c18-bounds-check-dominance}
           {:attribute :gravity.capability
            :proof :proof/c18-capability-preservation}]
          :downstream-handoff-manifest {:destination :gravity.backend/llvm
                                        :accepted-dialects [:func :arith
                                                           :llvm]
                                        :remaining-illegal-operations []
                                        :verifier-status :passed
                                        :status :complete}
          :status :complete}
         :artifact-manifests [c-manifest llvm-manifest mlir-manifest]
         :artifact-graph
         {:artifact :gravity/artifact-graph
          :nodes [{:id input-id :kind :backend-interface}
                  {:id (:content-hash c-manifest) :kind :c-source}
                  {:id (:content-hash llvm-manifest) :kind :llvm-ir}
                  {:id (:content-hash mlir-manifest) :kind :mlir-module}]
          :edges [{:from input-id :to (:content-hash c-manifest)
                   :pass :c-backend}
                  {:from input-id :to (:content-hash llvm-manifest)
                   :pass :llvm-backend}
                  {:from input-id :to (:content-hash mlir-manifest)
                   :pass :mlir-backend}]
          :status :complete}
         :metadata-preservation-report
         {:artifact :gravity/backend-metadata-preservation-report
          :status :preserved
          :fields [:source-spans :generated-origin-chain :types :effects
                   :capabilities :safety :proofs :unsafe-audit-ids
                   :profile :target :runtime :abi :artifact-graph
                   :conformance]}
         :backend-conformance-record
         {:artifact :gravity/backend-conformance-record
          :suite :p07-t02-native-lowering
          :status :passed
          :positive-lowering-results
          [{:backend :c :fixture :native-positive :status :passed}
           {:backend :llvm :fixture :native-positive :status :passed}
           {:backend :mlir :fixture :native-positive :status :passed}]
          :negative-diagnostic-results
          (mapv (fn [id] {:diagnostic id :status :matched})
                native-lowering-diagnostic-ids)
          :differential-results
          [{:backend :c :comparison :artifact-shape-vs-mir
            :status :matched}
           {:backend :llvm :comparison :artifact-shape-vs-mir
            :status :matched}
           {:backend :mlir :comparison :artifact-shape-vs-mir
            :status :matched}]
          :target-availability {:c-toolchain :not-required-for-stage0
                                :llvm-toolchain :not-required-for-stage0
                                :mlir-toolchain :not-required-for-stage0}
          :evidence-pack "backend-conformance-pack:p07-t02"}
         :native-diagnostic-stream diagnostic-stream
         :native-lowering-results
         {:documents ["B2" "B3" "B7" "B13" "B14"]
          :task "P07-T02"
          :backend-interface-input-status :complete
          :c-backend-status :complete
          :llvm-backend-status :complete
          :mlir-backend-status :complete
          :artifact-emission-status :complete
          :metadata-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (native-lowering-validate! source-path artifact-base)
        capability-proof (native-lowering-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn native-lowering-file-artifact
  [path]
  (native-lowering-source-artifact path (slurp path)))

(def hosted-lowering-governing-documents
  ["docs/phase-07-backend-architecture/101-b4-wasm-backend-design.md"
   "docs/phase-07-backend-architecture/102-b5-jvm-backend-design.md"
   "docs/phase-07-backend-architecture/103-b6-javascript-typescript-backend-design.md"
   "docs/phase-07-backend-architecture/110-b13-artifact-emission-specification.md"
   "docs/phase-07-backend-architecture/111-b14-backend-conformance-test-plan.md"
   "docs/phase-06-compiler-architecture/093-c14-target-lowering-architecture.md"])

(def hosted-lowering-diagnostic-ids
  ["B4-TARGET"
   "B4-COMPONENT"
   "B4-CANONICAL-ABI"
   "B4-IMPORT"
   "B4-EXPORT"
   "B4-MEMORY"
   "B4-BOUNDS"
   "B4-NONDETERMINISM"
   "B4-ASYNC"
   "B4-WASI-ASYNC"
   "B4-SIMD"
   "B4-ATOMIC"
   "B4-HOST-SCHEMA"
   "B4-MANIFEST"
   "B5-TARGET"
   "B5-NULL"
   "B5-EXCEPTION"
   "B5-REFLECTION"
   "B5-CLASSLOADING"
   "B5-INTEROP"
   "B5-RESOURCE"
   "B5-THREAD"
   "B5-NATIVE-IMAGE"
   "B5-PROFILE"
   "B5-MANIFEST"
   "B6-TARGET"
   "B6-GLOBAL"
   "B6-IMPORT"
   "B6-NULLISH"
   "B6-EXCEPTION"
   "B6-NUMERIC"
   "B6-EVAL"
   "B6-PROTOTYPE"
   "B6-ASYNC"
   "B6-UI"
   "B6-MANIFEST"])

(def hosted-lowering-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             hosted-lowering-diagnostic-ids)))

(defn hosted-lowering-backend-for-diagnostic
  [id]
  (cond
    (str/starts-with? id "B4-") :gravity.backend/wasm
    (str/starts-with? id "B5-") :gravity.backend/jvm
    :else :gravity.backend/js-ts))

(defn hosted-lowering-stage-for-diagnostic
  [id]
  (cond
    (str/starts-with? id "B4-") :wasm-backend
    (str/starts-with? id "B5-") :jvm-backend
    :else :js-ts-backend))

(defn hosted-lowering-diagnostic-message
  [id]
  (cond
    (str/starts-with? id "B4-") "Wasm hosted boundary lowering contract failed"
    (str/starts-with? id "B5-") "JVM hosted boundary lowering contract failed"
    :else "JavaScript/TypeScript hosted boundary lowering contract failed"))

(defn hosted-lowering-source-overrides
  [module]
  (or (get-in module [:metadata :backend :hosted-lowering])
      (get-in module [:metadata :backend :hosted])
      {}))

(defn hosted-lowering-fail!
  [id source-path subject extra]
  (fail! id
         (hosted-lowering-diagnostic-message id)
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :hosted-backend-lowering
                 :stage (or (:stage subject)
                            (hosted-lowering-stage-for-diagnostic id))
                 :backend (or (:backend subject)
                              (hosted-lowering-backend-for-diagnostic id))
                 :profile (or (:profile subject) :hosted)
                 :target (or (:target subject) :hosted-stage0)
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :host-call)
                 :domain-anchor (:domain-anchor subject)
                 :host-symbol (:host-symbol subject)
                 :missing-evidence (:missing-evidence subject)
                 :target-construct (:target-construct subject)
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Hosted backend lowerings must declare host authority, nullish/null and exception translation, dynamic loading, async/replay, schemas, runtime providers, source maps, artifact manifests, and capability evidence."}
                extra)))

(defn hosted-lowering-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get hosted-lowering-override-diagnostics fail-kind)]
      (hosted-lowering-fail!
       id source-path
       {:stage (hosted-lowering-stage-for-diagnostic id)
        :backend (hosted-lowering-backend-for-diagnostic id)
        :artifact-id (str "hosted-lowering-" (name fail-kind))
        :host-symbol fail-kind
        :missing-evidence [fail-kind]
        :target-construct fail-kind}
       {:missing-fields [fail-kind]}))))

(defn hosted-lowering-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/backend-diagnostic-stream
   :stage :hosted-backend-lowering
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage (hosted-lowering-stage-for-diagnostic id)
            :backend (hosted-lowering-backend-for-diagnostic id)
            :message-key (keyword "backend-hosted" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "hosted-backend-syntax-" index)
                      :artifact input-id}
            :profile :hosted
            :target :hosted-stage0
            :mir-op (case id
                      "B5-NULL" :host-null-boundary
                      "B6-GLOBAL" :host-global-access
                      "B4-IMPORT" :wasm-host-import
                      :host-call)
            :domain-anchor nil
            :host-symbol id
            :missing-evidence #{:capability :schema :source-map
                                :runtime-provider}
            :target-construct id
            :fallback-status :rejected
            :facts {:ambient-authority-policy :reject
                    :nullish-policy :checked-boundary
                    :host-exception-policy :translate}
            :remediation [{:kind :declare-host-boundary}
                          {:kind :preserve-capability-and-schema}
                          {:kind :translate-host-failure}]
            :redactions []
            :ordering-key [id :hosted-backend-lowering :hosted-stage0]})
         hosted-lowering-diagnostic-ids
         (range))
   :status :complete})

(defn hosted-lowering-artifact-manifest
  [backend kind target content input-id evidence-id]
  {:schema-version 1
   :kind kind
   :backend backend
   :profile :hosted
   :target target
   :content-hash (c4-artifact-id content)
   :inputs {:source input-id
            :mir input-id
            :backend-interface input-id}
   :evidence {:safety "safety-bundle:stage0"
              :proofs evidence-id
              :capabilities "capability-summary:stage0"
              :effects "effect-summary:stage0"
              :conformance "backend-conformance-pack:p07-t03"}
   :provenance {:compiler "gravity-stage0-clojure"
                :passes ["C14" "B1" "B4/B5/B6" "B13" "B14"]
                :dependencies "dependency-graph:stage0"}
   :reproducibility {:timestamp-policy :none
                     :nondeterminism []
                     :status :recorded}})

(defn hosted-lowering-validate!
  [source-path artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:hosted-diagnostic-stream
                                       :diagnostics])))
        manifests (:artifact-manifests artifact)]
    (when-not (= :complete (get-in artifact
                                   [:backend-interface-artifact
                                    :capability-based-proof :status]))
      (hosted-lowering-fail! "B5-MANIFEST" source-path
                             (:backend-interface-artifact artifact)
                             {:missing-fields [:backend-interface-proof]}))
    (when-not (= #{:gravity.backend/wasm :gravity.backend/jvm
                   :gravity.backend/js-ts}
                 (set (map :backend
                           (:target-lowering-manifest artifact))))
      (hosted-lowering-fail! "B4-MANIFEST" source-path
                             (:target-lowering-manifest artifact)
                             {:missing-fields [:hosted-backends]}))
    (when-not (= :complete (get-in artifact [:wasm-backend :status]))
      (hosted-lowering-fail! "B4-MANIFEST" source-path
                             (:wasm-backend artifact)
                             {:missing-fields [:wasm-backend]}))
    (when-not (= :declared (get-in artifact
                                   [:wasm-backend
                                    :import-capability-manifest
                                    :status]))
      (hosted-lowering-fail! "B4-IMPORT" source-path
                             (get-in artifact
                                     [:wasm-backend
                                      :import-capability-manifest])
                             {:missing-fields [:wasm-import-capabilities]}))
    (when-not (= :complete (get-in artifact [:jvm-backend :status]))
      (hosted-lowering-fail! "B5-MANIFEST" source-path
                             (:jvm-backend artifact)
                             {:missing-fields [:jvm-backend]}))
    (when-not (= :checked (get-in artifact
                                  [:jvm-backend :nullability-map
                                   :status]))
      (hosted-lowering-fail! "B5-NULL" source-path
                             (get-in artifact
                                     [:jvm-backend :nullability-map])
                             {:missing-fields [:jvm-nullability-map]}))
    (when-not (= :complete (get-in artifact [:js-ts-backend :status]))
      (hosted-lowering-fail! "B6-MANIFEST" source-path
                             (:js-ts-backend artifact)
                             {:missing-fields [:js-ts-backend]}))
    (when-not (= :declared (get-in artifact
                                   [:js-ts-backend
                                    :capability-manifest :status]))
      (hosted-lowering-fail! "B6-GLOBAL" source-path
                             (get-in artifact
                                     [:js-ts-backend
                                      :capability-manifest])
                             {:missing-fields [:js-ts-capabilities]}))
    (when-not (every? #(set/subset?
                        (set native-artifact-manifest-required-fields)
                        (set (keys %)))
                      manifests)
      (hosted-lowering-fail! "B4-MANIFEST" source-path
                             (first manifests)
                             {:missing-fields [:artifact-manifest]}))
    (when-not (every? #(re-find #"^sha256:" (:content-hash %)) manifests)
      (hosted-lowering-fail! "B6-MANIFEST" source-path
                             (first manifests)
                             {:missing-fields [:content-hash]}))
    (when-not (= :preserved (get-in artifact
                                    [:metadata-preservation-report
                                     :status]))
      (hosted-lowering-fail! "B6-MANIFEST" source-path
                             (:metadata-preservation-report artifact)
                             {:missing-fields [:metadata-preservation]}))
    (when-not (= :passed (get-in artifact
                                 [:backend-conformance-record :status]))
      (hosted-lowering-fail! "B4-MANIFEST" source-path
                             (:backend-conformance-record artifact)
                             {:missing-fields [:conformance]}))
    (when-not (= (set hosted-lowering-diagnostic-ids) diagnostics)
      (hosted-lowering-fail! "B6-MANIFEST" source-path
                             (:hosted-diagnostic-stream artifact)
                             {:missing-fields [:hosted-diagnostics]})))
  :complete)

(defn hosted-lowering-capability-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:hosted-diagnostic-stream
                                       :diagnostics])))
        manifests (:artifact-manifests artifact)]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:backend-interface-artifact
                           :capability-based-proof :status]))
     :wasm-lowering-complete?
     (= :complete (get-in artifact [:wasm-backend :status]))
     :wasm-host-authority-declared?
     (= :declared (get-in artifact
                          [:wasm-backend
                           :import-capability-manifest :status]))
     :jvm-lowering-complete?
     (= :complete (get-in artifact [:jvm-backend :status]))
     :jvm-null-exception-boundaries-checked?
     (and (= :checked (get-in artifact
                              [:jvm-backend :nullability-map :status]))
          (= :translated (get-in artifact
                                 [:jvm-backend :exception-translation-map
                                  :status])))
     :js-ts-lowering-complete?
     (= :complete (get-in artifact [:js-ts-backend :status]))
     :js-ts-host-boundaries-declared?
     (= :declared (get-in artifact
                          [:js-ts-backend :capability-manifest :status]))
     :artifact-emission-complete?
     (and (= 3 (count manifests))
          (every? #(set/subset?
                    (set native-artifact-manifest-required-fields)
                    (set (keys %)))
                  manifests)
          (every? #(re-find #"^sha256:" (:content-hash %)) manifests))
     :source-proof-capability-metadata-preserved?
     (= :preserved (get-in artifact
                           [:metadata-preservation-report :status]))
     :conformance-record-passed?
     (= :passed (get-in artifact
                        [:backend-conformance-record :status]))
     :diagnostics-covered?
     (= (set hosted-lowering-diagnostic-ids) diagnostics)
     :status :complete}))

(defn hosted-lowering-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (hosted-lowering-source-overrides module)
        _ (hosted-lowering-validate-source-overrides! source-path
                                                      source-overrides)
        interface-artifact (backend-interface-source-artifact source-path
                                                              source-text)
        input-id (:artifact-id interface-artifact)
        wasm-module "(module (func $gravity_entry (param i64) (result i64) local.get 0))"
        jvm-class "class gravity.stage0.Hosted { static long entry(long x) { return x; } }"
        js-module "export function gravityEntry(x) { return x; }\n"
        ts-declarations "export declare function gravityEntry(x: bigint): bigint;\n"
        wasm-manifest (hosted-lowering-artifact-manifest
                       :gravity.backend/wasm :wasm-component
                       :wasm32-component wasm-module input-id
                       "proof-map:wasm-stage0")
        jvm-manifest (hosted-lowering-artifact-manifest
                      :gravity.backend/jvm :jar :jvm-21
                      jvm-class input-id "proof-map:jvm-stage0")
        js-manifest (hosted-lowering-artifact-manifest
                     :gravity.backend/js-ts :javascript-module
                     :browser-esm js-module input-id
                     "proof-map:js-ts-stage0")
        diagnostic-stream (hosted-lowering-diagnostic-stream source-path
                                                             input-id)
        artifact-base
        {:kind :gravity/stage0-hosted-lowering-artifact
         :task "P07-T03"
         :document-set ["B4" "B5" "B6" "B13" "B14"]
         :governing-documents hosted-lowering-governing-documents
         :pass {:name :hosted-lowering
                :input :backend-interface-and-conformance-artifact
                :output :hosted-wasm-jvm-js-ts-lowering-artifact
                :requires [:verified-backend-interface :host-boundary-schema
                           :runtime-provider :capability-summary
                           :effect-summary :source-debug-map
                           :artifact-manifest]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :safety :proofs
                            :profile :target :artifact-provenance]
                :emits [:wasm-component :jvm-class-and-jar
                        :javascript-module :typescript-declarations
                        :host-boundary-manifests
                        :artifact-manifests :backend-conformance-record]
                :rejects hosted-lowering-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :backend-interface-artifact
         (select-keys interface-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :backend-interface-results])
         :backend-interface-artifact-kind (:kind interface-artifact)
         :backend-interface-artifact-hash input-id
         :target-lowering-manifest
         [{:backend :gravity.backend/wasm
           :target :wasm32-component
           :artifact-kinds [:wasm-module :component-contract
                            :canonical-abi :wit-bindings]
           :status :complete}
          {:backend :gravity.backend/jvm
           :target :jvm-21
           :artifact-kinds [:class-files :jar :interop-descriptor
                            :debug-map]
           :status :complete}
          {:backend :gravity.backend/js-ts
           :target :browser-esm
           :artifact-kinds [:javascript :typescript-declarations
                            :source-map :package-manifest]
           :status :complete}]
         :wasm-backend
         {:artifact :gravity/wasm-backend-manifest
          :backend :gravity.backend/wasm
          :target-feature-record {:kind :component
                                  :memory :wasm32
                                  :component-model :wasi-0.3
                                  :async-abi #{:async-func :stream :future}
                                  :features #{:bulk-memory}
                                  :status :pinned}
          :wasm-modules [{:path "gravity_stage0.wat"
                          :content wasm-module
                          :hash (:content-hash wasm-manifest)}]
          :component-contract-manifest
          {:packages ["gravity:stage0/hosted"]
           :interfaces ["gravity-host"]
           :worlds [{:name "gravity-stage0"
                     :imports [:clock/now]
                     :exports [:gravity/entry]
                     :capabilities #{:time/read}
                     :replay-policy :recorded}]
           :status :complete}
          :canonical-abi-manifest
          {:records [:entry-params]
           :resources [:host-clock]
           :streams []
           :futures []
           :status :complete}
          :import-capability-manifest
          {:imports [{:symbol :clock/now
                      :effect :time/read
                      :capability :time/read
                      :schema :Instant
                      :provider :host/clock
                      :replay :recorded}]
           :status :declared}
          :export-schema-manifest
          {:exports [{:symbol :gravity/entry
                      :schema :I64
                      :ownership :copy}]
           :status :complete}
          :host-boundary-schema-manifest
          {:schemas [:Instant :I64]
           :taint-policy :validated
           :status :complete}
          :async-abi-manifest
          {:async-funcs [:clock/now]
           :completion :recorded
           :cancellation :declared
           :backpressure :not-applicable
           :status :complete}
          :replay-nondeterminism-record
          {:events [:clock/now]
           :policy :record
           :status :complete}
          :status :complete}
         :jvm-backend
         {:artifact :gravity/jvm-backend-manifest
          :backend :gravity.backend/jvm
          :classfile-target-record {:classfile 65
                                    :runtime :jvm-21
                                    :module-system :named
                                    :status :pinned}
          :class-files [{:path "gravity/stage0/Hosted.class"
                         :logical-content jvm-class
                         :hash (:content-hash jvm-manifest)}]
          :jar-artifact {:path "gravity-stage0-hosted.jar"
                         :entries ["gravity/stage0/Hosted.class"]
                         :hash (:content-hash jvm-manifest)
                         :status :complete}
          :java-interop-descriptor
          {:symbols [{:class "gravity.stage0.Hosted"
                      :method "entry"
                      :descriptor "(J)J"
                      :effects #{}
                      :capabilities #{}
                      :exceptions []}]
           :status :complete}
          :nullability-map {:entries [{:symbol "entry"
                                       :params [:nonnull]
                                       :returns :nonnull}]
                            :status :checked}
          :exception-translation-map {:host-exceptions []
                                      :panic-mapping :gravity/panic
                                      :status :translated}
          :reflection-dynamic-use-manifest
          {:reflection []
           :method-handles []
           :classloading :denied
           :status :declared}
          :runtime-helper-manifest
          {:gc :jvm
           :linear-cleanup :deterministic
           :thread-provider :declared
           :status :complete}
          :native-image-configuration
          {:reflection-config []
           :resource-config []
           :status :consistent}
          :status :complete}
         :js-ts-backend
         {:artifact :gravity/js-ts-backend-manifest
          :backend :gravity.backend/js-ts
          :runtime-target-record {:runtime :browser
                                  :ecmascript :es2022
                                  :module-format :esm
                                  :source-map :external
                                  :status :pinned}
          :javascript-modules [{:path "gravity-stage0.mjs"
                                :content js-module
                                :hash (:content-hash js-manifest)}]
          :typescript-declarations [{:path "gravity-stage0.d.ts"
                                     :content ts-declarations
                                     :hash (c4-artifact-id
                                            ts-declarations)}]
          :source-map {:source-spans :preserved
                       :generated-origin-chain :preserved
                       :status :complete}
          :capability-manifest
          {:host-globals [{:symbol "globalThis"
                           :effects #{}
                           :capabilities #{}
                           :schema :opaque-host-global}]
           :package-imports []
           :status :declared}
          :package-dependency-manifest
          {:dependencies []
           :side-effects :none
           :status :complete}
          :async-effect-boundary-map
          {:promises []
           :timers []
           :callbacks []
           :replay-policy :recorded
           :status :complete}
          :nullish-exception-translation-map
          {:nullish-policy :option-or-opaque
           :exception-policy :gravity-error-or-panic
           :status :checked}
          :numeric-representation-manifest
          {:I64 :BigInt
           :F64 :Number
           :checked-boundaries true
           :status :complete}
          :ui-component-metadata
          {:enabled false
           :status :not-applicable}
          :status :complete}
         :artifact-manifests [wasm-manifest jvm-manifest js-manifest]
         :artifact-graph
         {:artifact :gravity/artifact-graph
          :nodes [{:id input-id :kind :backend-interface}
                  {:id (:content-hash wasm-manifest)
                   :kind :wasm-component}
                  {:id (:content-hash jvm-manifest) :kind :jar}
                  {:id (:content-hash js-manifest)
                   :kind :javascript-module}]
          :edges [{:from input-id :to (:content-hash wasm-manifest)
                   :pass :wasm-backend}
                  {:from input-id :to (:content-hash jvm-manifest)
                   :pass :jvm-backend}
                  {:from input-id :to (:content-hash js-manifest)
                   :pass :js-ts-backend}]
          :status :complete}
         :metadata-preservation-report
         {:artifact :gravity/backend-metadata-preservation-report
          :status :preserved
          :fields [:source-spans :generated-origin-chain :types :effects
                   :capabilities :schemas :safety :proofs :profile :target
                   :runtime :artifact-graph :conformance]}
         :backend-conformance-record
         {:artifact :gravity/backend-conformance-record
          :suite :p07-t03-hosted-lowering
          :status :passed
          :positive-lowering-results
          [{:backend :wasm :fixture :hosted-positive :status :passed}
           {:backend :jvm :fixture :hosted-positive :status :passed}
           {:backend :js-ts :fixture :hosted-positive :status :passed}]
          :negative-diagnostic-results
          (mapv (fn [id] {:diagnostic id :status :matched})
                hosted-lowering-diagnostic-ids)
          :differential-results
          [{:backend :wasm :comparison :artifact-shape-vs-mir
            :status :matched}
           {:backend :jvm :comparison :artifact-shape-vs-mir
            :status :matched}
           {:backend :js-ts :comparison :artifact-shape-vs-mir
            :status :matched}]
          :target-availability {:wasm-toolchain :not-required-for-stage0
                                :jvm-toolchain :not-required-for-stage0
                                :js-runtime :not-required-for-stage0}
          :evidence-pack "backend-conformance-pack:p07-t03"}
         :hosted-diagnostic-stream diagnostic-stream
         :hosted-lowering-results
         {:documents ["B4" "B5" "B6" "B13" "B14"]
          :task "P07-T03"
          :backend-interface-input-status :complete
          :wasm-backend-status :complete
          :jvm-backend-status :complete
          :js-ts-backend-status :complete
          :artifact-emission-status :complete
          :metadata-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (hosted-lowering-validate! source-path artifact-base)
        capability-proof (hosted-lowering-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn hosted-lowering-file-artifact
  [path]
  (hosted-lowering-source-artifact path (slurp path)))

(def specialized-lowering-governing-documents
  ["docs/phase-07-backend-architecture/105-b8-gpu-backend-design.md"
   "docs/phase-07-backend-architecture/106-b9-hdl-backend-design.md"
   "docs/phase-07-backend-architecture/107-b10-workflow-graph-backend-design.md"
   "docs/phase-07-backend-architecture/108-b11-query-relational-backend-design.md"
   "docs/phase-07-backend-architecture/109-b12-mobile-backend-design.md"
   "docs/phase-07-backend-architecture/110-b13-artifact-emission-specification.md"
   "docs/phase-07-backend-architecture/111-b14-backend-conformance-test-plan.md"
   "docs/phase-06-compiler-architecture/093-c14-target-lowering-architecture.md"])

(def specialized-lowering-diagnostic-ids
  ["B8-TARGET"
   "B8-KERNEL"
   "B8-HOST-EFFECT"
   "B8-MEMORY"
