(defn b4-document-validate!
  [source-path artifact]
  (let [hosted (:hosted-lowering-artifact artifact)
        manifest (:wasm-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b4-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-hosted-lowering-artifact (:kind hosted))
      (b4-document-fail! "B4-MANIFEST" source-path hosted
                         {:missing-fields [:hosted-lowering-artifact]}))
    (when-not (= :complete (get-in hosted
                                   [:capability-based-proof :status]))
      (b4-document-fail! "B4-MANIFEST" source-path hosted
                         {:missing-fields [:hosted-lowering-proof]}))
    (when-not (= :pinned (get-in manifest
                                 [:target-feature-record :status]))
      (b4-document-fail! "B4-TARGET" source-path manifest
                         {:missing-fields [:target-feature-record]}))
    (when-not (= :complete (get-in manifest
                                   [:component-contract-manifest :status]))
      (b4-document-fail! "B4-COMPONENT" source-path manifest
                         {:missing-fields [:component-contract]}))
    (when-not (= :complete (get-in manifest
                                   [:canonical-abi-manifest :status]))
      (b4-document-fail! "B4-CANONICAL-ABI" source-path manifest
                         {:missing-fields [:canonical-abi]}))
    (when-not (= :declared (get-in manifest
                                   [:import-capability-manifest :status]))
      (b4-document-fail! "B4-IMPORT" source-path manifest
                         {:missing-fields [:import-capabilities]}))
    (when-not (= :complete (get-in manifest
                                   [:export-schema-manifest :status]))
      (b4-document-fail! "B4-EXPORT" source-path manifest
                         {:missing-fields [:export-schemas]}))
    (when-not (= :complete (get-in manifest
                                   [:linear-memory-and-table-plan :status]))
      (b4-document-fail! "B4-MEMORY" source-path manifest
                         {:missing-fields [:linear-memory-plan]}))
    (when-not (= [:safe2-bounds :safe2-lifetime]
                 (get-in manifest
                         [:linear-memory-and-table-plan
                          :bounds-and-lifetime-proofs]))
      (b4-document-fail! "B4-BOUNDS" source-path manifest
                         {:missing-fields [:bounds-proof]}))
    (when-not (= :complete (get-in manifest
                                   [:replay-and-nondeterminism-record
                                    :status]))
      (b4-document-fail! "B4-NONDETERMINISM" source-path manifest
                         {:missing-fields [:replay-record]}))
    (when-not (= :complete (get-in manifest
                                   [:wasi-component-async-abi-manifest
                                    :status]))
      (b4-document-fail! "B4-WASI-ASYNC" source-path manifest
                         {:missing-fields [:wasi-async-abi]}))
    (when-not (= :complete (get-in manifest
                                   [:simd-feature-record :status]))
      (b4-document-fail! "B4-SIMD" source-path manifest
                         {:missing-fields [:simd-feature-record]}))
    (when-not (= :complete (get-in manifest
                                   [:atomic-feature-record :status]))
      (b4-document-fail! "B4-ATOMIC" source-path manifest
                         {:missing-fields [:atomic-feature-record]}))
    (when-not (= :complete (get-in manifest
                                   [:host-boundary-schema-manifest :status]))
      (b4-document-fail! "B4-HOST-SCHEMA" source-path manifest
                         {:missing-fields [:host-boundary-schema]}))
    (when-not (b4-document-wat-structurally-valid? b4-document-wat)
      (b4-document-fail! "B4-MANIFEST" source-path manifest
                         {:missing-fields [:wat-structural-validation]}))
    (when-not (every? #(contains? manifest %)
                      [:target-feature-record
                       :linear-memory-and-table-plan
                       :wasm-modules
                       :component-model-artifact
                       :component-contract-manifest
                       :canonical-abi-manifest
                       :import-capability-manifest
                       :export-schema-manifest
                       :host-boundary-schema-manifest
                       :wasi-component-async-abi-manifest
                       :component-composition-plan
                       :host-binding-stubs
                       :runtime-helper-manifest
                       :source-map-and-generated-origin-map
                       :replay-and-nondeterminism-record])
      (b4-document-fail! "B4-MANIFEST" source-path manifest
                         {:missing-fields [:wasm-artifact-manifest]}))
    (when-not (= (set b4-document-diagnostic-ids) diagnostics)
      (b4-document-fail! "B4-MANIFEST" source-path
                         (:b4-diagnostic-stream artifact)
                         {:missing-fields [:b4-diagnostics]})))
  :complete)

(defn b4-document-capability-proof
  [artifact]
  (let [manifest (:wasm-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b4-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:hosted-lowering-artifact
                           :capability-based-proof :status]))
     :target-feature-record-pinned?
     (= :pinned (get-in manifest [:target-feature-record :status]))
     :component-contract-covered?
     (= :complete (get-in manifest
                          [:component-contract-manifest :status]))
     :canonical-abi-covered?
     (= :complete (get-in manifest
                          [:canonical-abi-manifest :status]))
     :imports-capability-declared?
     (= :declared (get-in manifest
                          [:import-capability-manifest :status]))
     :exports-schema-declared?
     (= :complete (get-in manifest
                          [:export-schema-manifest :status]))
     :linear-memory-pointer-policy-covered?
     (= :complete (get-in manifest
                          [:linear-memory-and-table-plan :status]))
     :bounds-proof-covered?
     (= [:safe2-bounds :safe2-lifetime]
        (get-in manifest
                [:linear-memory-and-table-plan
                 :bounds-and-lifetime-proofs]))
     :replay-nondeterminism-covered?
     (= :complete (get-in manifest
                          [:replay-and-nondeterminism-record :status]))
     :async-and-wasi-async-covered?
     (= :complete (get-in manifest
                          [:wasi-component-async-abi-manifest :status]))
     :simd-feature-covered?
     (= :complete (get-in manifest [:simd-feature-record :status]))
     :atomic-feature-covered?
     (= :complete (get-in manifest [:atomic-feature-record :status]))
     :host-boundary-schema-covered?
     (= :complete (get-in manifest
                          [:host-boundary-schema-manifest :status]))
     :manifest-complete?
     (every? #(contains? manifest %)
             [:target-feature-record
              :linear-memory-and-table-plan
              :wasm-modules
              :component-model-artifact
              :component-contract-manifest
              :canonical-abi-manifest
              :import-capability-manifest
              :export-schema-manifest
              :host-boundary-schema-manifest
              :wasi-component-async-abi-manifest
              :component-composition-plan
              :host-binding-stubs
              :runtime-helper-manifest
              :source-map-and-generated-origin-map
              :replay-and-nondeterminism-record])
     :wat-structurally-valid?
     (b4-document-wat-structurally-valid? b4-document-wat)
     :diagnostics-covered?
     (= (set b4-document-diagnostic-ids) diagnostics)
     :external-wasm-toolchain-validation?
     :not-available-in-current-environment
     :status :complete}))

(defn b4-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b4-document-source-overrides module)
        _ (b4-document-validate-source-overrides! source-path
                                                  source-overrides)
        hosted-artifact (hosted-lowering-source-artifact source-path
                                                         source-text)
        input-id (:artifact-id hosted-artifact)
        manifest (b4-document-wasm-manifest input-id)
        diagnostic-stream (b4-document-diagnostic-stream source-path
                                                         input-id)
        artifact-base
        {:kind :gravity/stage0-b4-wasm-backend-document-artifact
         :task "P07-D101"
         :document-set ["B4"]
         :governing-document b4-document-governing-document
         :pass {:name :b4-wasm-backend-document-coverage
                :input :hosted-lowering-artifact
                :output :b4-wasm-backend-document-artifact
                :requires [:verified-mir-or-domain-ir :b1-backend-interface
                           :c14-target-lowering :wasm-target-features
                           :component-contracts :canonical-abi
                           :import-capabilities :export-schemas
                           :host-boundary-schemas :async-abi
                           :replay-record :linear-memory-plan]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :schemas :safety
                            :proofs :profile :target
                            :artifact-provenance]
                :emits [:wasm-backend-manifest :target-feature-record
                        :linear-memory-and-table-plan :wasm-modules
                        :component-model-artifact
                        :component-contract-manifest
                        :canonical-abi-manifest
                        :import-capability-manifest
                        :export-schema-manifest
                        :host-boundary-schema-manifest
                        :wasi-component-async-abi-manifest
                        :component-composition-plan
                        :replay-and-nondeterminism-record
                        :b4-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b4-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :hosted-lowering-artifact
         (select-keys hosted-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :hosted-lowering-results])
         :hosted-lowering-artifact-kind (:kind hosted-artifact)
         :hosted-lowering-artifact-hash input-id
         :wasm-backend-manifest manifest
         :target-feature-record (:target-feature-record manifest)
         :linear-memory-and-table-plan
         (:linear-memory-and-table-plan manifest)
         :wasm-modules (:wasm-modules manifest)
         :component-model-artifact (:component-model-artifact manifest)
         :component-contract-manifest
         (:component-contract-manifest manifest)
         :canonical-abi-manifest (:canonical-abi-manifest manifest)
         :import-capability-manifest
         (:import-capability-manifest manifest)
         :export-schema-manifest (:export-schema-manifest manifest)
         :host-boundary-schema-manifest
         (:host-boundary-schema-manifest manifest)
         :wasi-component-async-abi-manifest
         (:wasi-component-async-abi-manifest manifest)
         :component-composition-plan
         (:component-composition-plan manifest)
         :replay-and-nondeterminism-record
         (:replay-and-nondeterminism-record manifest)
         :rejected-design-coverage
         [{:design :ambient-host-import
           :diagnostic "B4-IMPORT" :status :rejected}
          {:design :raw-linear-memory-offset-export
           :diagnostic "B4-MEMORY" :status :rejected}
          {:design :sandbox-as-capability-check-substitute
           :diagnostic "B4-IMPORT" :status :rejected}
          {:design :unrecorded-nondeterministic-host-call
           :diagnostic "B4-NONDETERMINISM" :status :rejected}
          {:design :runtime-feature-probing-for-eligible-profile
           :diagnostic "B4-TARGET" :status :rejected}
          {:design :authority-amplifying-composition
           :diagnostic "B4-COMPONENT" :status :rejected}
          {:design :opaque-host-promise-for-wasi-async
           :diagnostic "B4-WASI-ASYNC" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b4-wasm-backend-conformance-criteria-record
          :core-module-and-component-model :emitted
          :wit-contracts :emitted
          :canonical-abi-validation :complete
          :wasi-async-fixtures [:async-func :stream :future]
          :import-capability-manifests [:browser :wasi :custom]
          :composition-capability-preservation :complete
          :export-schema-validation :complete
          :host-boundary-schema-validation :complete
          :pointer-handle-lifetime-tests :recorded
          :memory-growth-bounds-check-behavior :recorded
          :rejected-ambient-imports-and-pointer-escape :covered
          :invalid-contract-diagnostics :covered
          :replay-records :covered
          :async-replay-cancellation-ordering-backpressure :covered
          :simd-and-atomics-feature-records :covered
          :metadata-preservation :preserved
          :differential-execution :mir-reference-recorded
          :status :passed}
         :b4-diagnostic-stream diagnostic-stream
         :b4-document-results
         {:documents ["B4"]
          :task "P07-D101"
          :required-diagnostic-ids b4-document-diagnostic-ids
          :hosted-lowering-input-status :complete
          :target-feature-status :complete
          :component-contract-status :complete
          :canonical-abi-status :complete
          :import-status :complete
          :export-status :complete
          :linear-memory-status :complete
          :bounds-status :complete
          :replay-status :complete
          :async-status :complete
          :wasi-async-status :complete
          :simd-status :complete
          :atomic-status :complete
          :host-schema-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b4-document-validate! source-path artifact-base)
        capability-proof (b4-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b4-document-file-artifact
  [path]
  (b4-document-source-artifact path (slurp path)))

(def b5-document-governing-document
  "docs/phase-07-backend-architecture/102-b5-jvm-backend-design.md")

(def b5-document-diagnostic-ids
  ["B5-TARGET"
   "B5-NULL"
   "B5-EXCEPTION"
   "B5-REFLECTION"
   "B5-CLASSLOADING"
   "B5-INTEROP"
   "B5-RESOURCE"
   "B5-THREAD"
   "B5-NATIVE-IMAGE"
   "B5-PROFILE"
   "B5-MANIFEST"])

(def b5-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             b5-document-diagnostic-ids)))

(defn b5-document-source-overrides
  [module]
  (or (get-in module [:metadata :backend :b5-document])
      (get-in module [:metadata :backend :hosted-lowering])
      (get-in module [:metadata :backend :hosted])
      {}))

(defn b5-document-missing-fact
  [id]
  (case id
    "B5-TARGET" :classfile-jvm-module-packaging-target
    "B5-NULL" :nullability-wrapper-or-opaque-check
    "B5-EXCEPTION" :host-exception-translation
    "B5-REFLECTION" :reflection-dynamic-policy-capability
    "B5-CLASSLOADING" :classloader-policy
    "B5-INTEROP" :java-boundary-descriptor
    "B5-RESOURCE" :deterministic-linear-resource-cleanup
    "B5-THREAD" :thread-monitor-scheduler-effect-record
    "B5-NATIVE-IMAGE" :native-image-configuration
    "B5-PROFILE" :hosted-profile-boundary
    "B5-MANIFEST" :complete-jvm-artifact-manifest
    :b5-document-evidence))

(defn b5-document-jvm-symbol
  [id]
  (case id
    "B5-TARGET" "gravity.stage0.Hosted"
    "B5-NULL" "gravity.stage0.Hosted.nullable"
    "B5-EXCEPTION" "gravity.stage0.Hosted.translateException"
    "B5-REFLECTION" "java.lang.reflect.Method"
    "B5-CLASSLOADING" "java.lang.ClassLoader#defineClass"
    "B5-INTEROP" "gravity.stage0.Hosted.entry"
    "B5-RESOURCE" "gravity.stage0.Hosted.Resource"
    "B5-THREAD" "java.lang.Thread"
    "B5-NATIVE-IMAGE" "native-image-config"
    "B5-PROFILE" "gravity.lower-profile.export"
    "B5-MANIFEST" "gravity/jvm-backend-manifest"
    "gravity.stage0.Hosted"))

(defn b5-document-selected-adapter
  [id]
  (case id
    "B5-NULL" :option-wrapper
    "B5-EXCEPTION" :gravity-error-or-panic-adapter
    "B5-REFLECTION" :declared-reflection-manifest-or-reject
    "B5-CLASSLOADING" :direct-call-or-reject
    "B5-RESOURCE" :auto-closeable-safe5-cleanup
    "B5-THREAD" :runtime-scheduler-provider
    "B5-NATIVE-IMAGE" :generated-native-image-config
    "B5-PROFILE" :profile-boundary-rejection
    :jvm-backend-record))

(defn b5-document-fail!
  [id source-path subject extra]
  (fail! id
         "B5 JVM backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b5-jvm-backend-document
                 :stage (or (:stage subject)
                            :b5-jvm-backend-document-coverage)
                 :backend :gravity.backend/jvm
                 :profile (or (:profile subject) :hosted)
                 :classfile-target (or (:classfile-target subject) 65)
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :host-call)
                 :domain-anchor (:domain-anchor subject)
                 :jvm-symbol (or (:jvm-symbol subject)
                                 (b5-document-jvm-symbol id))
                 :missing-type-effect-capability-cleanup-fact
                 (or (:missing-type-effect-capability-cleanup-fact subject)
                     (b5-document-missing-fact id))
                 :selected-adapter-or-rejection
                 (or (:selected-adapter-or-rejection subject)
                     (b5-document-selected-adapter id))
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Emit JVM artifacts only from verified hosted backend input with pinned classfile/JVM/module/package policy, nullability and exception maps, explicit reflection/classloading/thread/native-image capabilities, deterministic resource cleanup, profile boundary checks, source maps, and complete JVM manifests."}
                extra)))

(defn b5-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b5-document-override-diagnostics fail-kind)]
      (b5-document-fail!
       id source-path
       {:stage :b5-jvm-backend-document-coverage
        :artifact-id (str "b5-document-" (name fail-kind))
        :missing-type-effect-capability-cleanup-fact fail-kind
        :jvm-symbol (name fail-kind)}
       {:missing-fields [fail-kind]}))))

(def b5-document-java-source
  (str "package gravity.stage0;\n\n"
       "import java.util.Optional;\n"
       "import java.util.concurrent.Callable;\n\n"
       "public final class Hosted {\n"
       "  private Hosted() {}\n\n"
       "  public static long entry(long x) {\n"
       "    return x;\n"
       "  }\n\n"
       "  public static Optional<String> nullable(String value) {\n"
       "    return Optional.ofNullable(value);\n"
       "  }\n\n"
       "  public static String translateException(Callable<String> thunk) {\n"
       "    try {\n"
       "      return thunk.call();\n"
       "    } catch (Exception ex) {\n"
       "      throw new GravityPanic(ex);\n"
       "    }\n"
       "  }\n\n"
       "  public static Resource openResource() {\n"
       "    return new Resource();\n"
       "  }\n\n"
       "  public static final class GravityPanic extends RuntimeException {\n"
       "    public GravityPanic(Throwable cause) {\n"
       "      super(cause);\n"
       "    }\n"
       "  }\n\n"
       "  public static final class Resource implements AutoCloseable {\n"
       "    private boolean closed;\n\n"
       "    @Override\n"
       "    public void close() {\n"
       "      closed = true;\n"
       "    }\n\n"
       "    public boolean isClosed() {\n"
       "      return closed;\n"
       "    }\n"
       "  }\n"
       "}\n"))

(def b5-document-module-info
  (str "module gravity.stage {\n"
       "  exports gravity.stage0;\n"
       "}\n"))

(defn b5-document-java-structurally-valid?
  [source]
  (and (str/includes? source "package gravity.stage0;")
       (str/includes? source "public final class Hosted")
       (str/includes? source "Optional<String>")
       (str/includes? source "GravityPanic")
       (str/includes? source "implements AutoCloseable")
       (str/includes? source "Callable<String>")))

(defn b5-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b5-jvm-backend-diagnostic-stream
   :stage :b5-jvm-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b5-jvm-backend-document-coverage
            :backend :gravity.backend/jvm
            :message-key (keyword "backend-jvm" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b5-document-syntax-" index)
                      :artifact input-id}
            :mir-op (case id
                      "B5-NULL" :host-null-boundary
                      "B5-EXCEPTION" :host-exception-boundary
                      "B5-RESOURCE" :linear-resource-cleanup
                      "B5-THREAD" :host-thread-call
                      :host-call)
            :domain-anchor (when (= id "B5-INTEROP") :java-interop)
            :jvm-symbol (b5-document-jvm-symbol id)
            :classfile-target 65
            :profile :hosted
            :missing-type-effect-capability-cleanup-fact
            (b5-document-missing-fact id)
            :selected-adapter-or-rejection (b5-document-selected-adapter id)
            :fallback-status :rejected
            :facts {:java-null-policy :option-result-checked-or-opaque
                    :host-exception-policy :translate
                    :hidden-dynamic-behavior :rejected}
            :remediation [{:kind :pin-jvm-target-record}
                          {:kind :attach-java-interop-descriptor}
                          {:kind :translate-null-exception-resource-boundary}]
            :redactions []
            :ordering-key [id :b5-jvm-backend-document-coverage
                           :jvm-21]})
         b5-document-diagnostic-ids
         (range))
   :status :complete})

(defn b5-document-jvm-manifest
  [input-id]
  (let [source-hash (c4-artifact-id b5-document-java-source)
        module-hash (c4-artifact-id b5-document-module-info)]
    {:artifact :gravity/jvm-backend-manifest
     :backend :gravity.backend/jvm
     :target {:classfile 65
              :runtime :jvm-21
              :module-system :named
              :status :pinned}
     :emits #{:class-files :jar :interop-descriptors :debug-map}
     :requires #{:hosted-profile :exception-map :nullability-map
                 :runtime-provider-manifest}
     :rejects #{:unchecked-null-flow :undeclared-reflection
                :untranslated-host-exception :hidden-classloading}
     :classfile-and-jvm-target-record
     {:classfile 65
      :jvm-version-range [:jvm-21 :jvm-25]
      :module-system :named
      :classloader-policy :single-declared-loader
      :packaging-mode :modular-jar
      :reflection-policy :declared-denied-by-default
      :native-image-constraints :generated-from-dynamic-use
      :status :pinned}
     :class-and-module-model
     {:package "gravity.stage0"
      :module "gravity.stage"
      :generated-classes ["gravity.stage0.Hosted"
                          "gravity.stage0.Hosted$GravityPanic"
                          "gravity.stage0.Hosted$Resource"]
      :symbol-to-method {"gravity/entry" "gravity.stage0.Hosted.entry(J)J"
                         "gravity/nullable" "gravity.stage0.Hosted.nullable(Ljava/lang/String;)Ljava/util/Optional;"}
      :static-initializer :none
      :field-layout []
      :interface-protocol-mapping []
      :closure-representation :static-method-or-runtime-handle
      :generic-signature-strategy :bridge-when-required
      :annotations-emitted []
      :visibility-and-access-flags :public-final
      :classloader-assumptions :single-declared-loader
      :incremental-name-stability :stable
      :status :complete}
     :java-source-files [{:path "gravity/stage0/Hosted.java"
                          :content b5-document-java-source
                          :hash source-hash}]
     :module-descriptors [{:path "module-info.java"
                           :content b5-document-module-info
                           :hash module-hash}]
     :class-files [{:path "gravity/stage0/Hosted.class"
                    :logical-source "gravity/stage0/Hosted.java"
                    :classfile 65
                    :status :requires-proof-command}]
     :jar-or-module-artifact
     {:path "gravity-stage0-jvm.jar"
      :module "gravity.stage"
      :entries ["module-info.class"
                "gravity/stage0/Hosted.class"
                "gravity/stage0/Hosted$GravityPanic.class"
                "gravity/stage0/Hosted$Resource.class"]
      :status :requires-proof-command}
     :value-representation-record
     {:representations [{:gravity-type :I64
                         :jvm-descriptor "J"
                         :nullability :non-null-primitive
                         :boxing :specialized
                         :equality :primitive
                         :mutability :immutable
                         :ownership-rooting :stack}
                        {:gravity-type :String?
                         :jvm-descriptor "Ljava/util/Optional;"
                         :nullability :option-wrapper
                         :boxing :boxed
                         :equality :object-equals
                         :mutability :immutable
                         :ownership-rooting :gc-root}]
      :bridge-methods :when-required
      :status :complete}
     :java-interop-descriptor
     {:descriptors [{:id :gravity.stage0/entry
                     :class "gravity.stage0.Hosted"
                     :method "entry"
                     :jvm-descriptor "(J)J"
                     :generic-signature nil
                     :gravity-type [:fn [:I64] :I64]
                     :nullability {:params [:non-null-primitive]
                                   :return :non-null-primitive}
                     :exception-mapping :none
                     :thread-affinity :none
                     :reflection-required? false
                     :effects #{}
                     :capabilities #{}
                     :taint-policy :not-applicable}
                    {:id :gravity.stage0/translate-exception
                     :class "gravity.stage0.Hosted"
                     :method "translateException"
                     :jvm-descriptor "(Ljava/util/concurrent/Callable;)Ljava/lang/String;"
                     :gravity-type [:fn [:host-callable] :String]
                     :nullability {:params [:nonnull] :return :nonnull}
                     :exception-mapping :gravity-panic
                     :thread-affinity :caller
                     :reflection-required? false
                     :effects #{:error/throw}
                     :capabilities #{}
                     :taint-policy :validated}]
      :status :complete}
     :nullability-and-exception-translation-map
     {:nullability {:java-null-flow :option-result-checked-or-opaque
                    :safe-gravity-null-entry :rejected
                    :wrappers [:Option :Result :opaque-foreign]}
      :exceptions {:java-checked :gravity-error
                   :java-unchecked :gravity-panic
                   :fatal-jvm :runtime-record-when-catchable
                   :catch-all-preserves-source-and-host-identity true}
      :status :complete}
     :reflection-and-dynamic-use-manifest
     {:reflection []
      :dynamic-proxies []
      :method-handles []
      :invokedynamic []
      :service-loaders []
      :serialization-frameworks []
      :native-image-reflection-metadata []
      :policy :declared-denied-by-default
      :status :declared}
     :classloading-policy-record
     {:dynamic-loading :denied
      :hidden-classloading []
      :accepted-loaders [:single-declared-loader]
      :status :complete}
     :native-image-configuration
     {:reflection-config []
      :resource-config []
      :jni-config []
      :proxy-config []
      :dynamic-use-correspondence :exact
      :status :consistent}
     :runtime-helper-manifest
     {:gc-assumptions :jvm-gc
      :scheduler :runtime-provider-declared
      :threads :declared-effect-only
      :monitors :declared-effect-only
      :atomics :varhandle-record-required
      :executor-integration :manifested
      :classloader-lifecycle-hooks :none
      :shutdown-behavior :declared
      :deterministic-cleanup-helpers [:safe5-auto-close]
      :logging-tracing-hooks :declared
      :status :complete}
     :resource-cleanup-record
     {:linear-resources [:resource/file :resource/socket
                        :resource/lock :resource/transaction
                        :resource/native-handle]
      :cleanup-path :safe5-deterministic
      :gc-finalization-only :rejected
      :status :complete}
     :thread-monitor-executor-atomic-effect-record
     {:threads {:creation :requires-effect-and-capability}
      :monitors {:synchronized :requires-effect}
      :executors {:integration :runtime-provider}
      :atomics {:varhandle :requires-ordering-record}
      :blocking {:policy :declared}
      :status :complete}
     :profile-boundary-record
     {:hosted-behavior-exported-to-lower-profiles :rejected
      :lower-profile-contracts [:core :native :firmware :kernel :hardware]
      :status :complete}
     :source-debug-map
     {:source input-id
      :generated-origin-chain [:mir :c14-target-lowering
                               :b1-interface :b5-jvm-backend]
      :generated-files ["module-info.java" "gravity/stage0/Hosted.java"]
      :status :preserved}
     :bootstrap-self-hosting-record
     {:applies? true
      :stage :stage0-hosted-jvm-bootstrap-support
      :replacement-policy :retire-when-gravity-can-compile-subset
      :status :recorded}
     :javac-compilation-record
     {:declared-command "javac --release 21 -d /tmp/gravity-p07-b5-classes /tmp/gravity-p07-b5-src/module-info.java /tmp/gravity-p07-b5-src/gravity/stage0/Hosted.java"
      :proof-artifact "docs/artifacts/phase-07/reports/p07-d102-b5-jvm-backend-report.md"
      :status :requires-proof-command}
     :jar-creation-record
     {:declared-command "jar --create --file /tmp/gravity-p07-b5.jar -C /tmp/gravity-p07-b5-classes ."
      :proof-artifact "docs/artifacts/phase-07/reports/p07-d102-b5-jvm-backend-report.md"
      :status :requires-proof-command}
     :input-artifact input-id
     :status :complete}))

(defn b5-document-validate!
  [source-path artifact]
  (let [hosted (:hosted-lowering-artifact artifact)
        manifest (:jvm-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b5-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-hosted-lowering-artifact (:kind hosted))
      (b5-document-fail! "B5-MANIFEST" source-path hosted
                         {:missing-fields [:hosted-lowering-artifact]}))
    (when-not (= :complete (get-in hosted
                                   [:capability-based-proof :status]))
      (b5-document-fail! "B5-MANIFEST" source-path hosted
                         {:missing-fields [:hosted-lowering-proof]}))
    (when-not (= :pinned (get-in manifest
                                 [:classfile-and-jvm-target-record
                                  :status]))
      (b5-document-fail! "B5-TARGET" source-path manifest
                         {:missing-fields [:target-record]}))
    (when-not (= :complete (get-in manifest
                                   [:class-and-module-model :status]))
      (b5-document-fail! "B5-MANIFEST" source-path manifest
                         {:missing-fields [:class-module-model]}))
    (when-not (= :complete (get-in manifest
                                   [:value-representation-record :status]))
      (b5-document-fail! "B5-INTEROP" source-path manifest
                         {:missing-fields [:value-representation]}))
    (when-not (= :complete (get-in manifest
                                   [:java-interop-descriptor :status]))
      (b5-document-fail! "B5-INTEROP" source-path manifest
                         {:missing-fields [:interop-descriptor]}))
    (when-not (= :complete
                 (get-in manifest
                         [:nullability-and-exception-translation-map
                          :status]))
      (b5-document-fail! "B5-NULL" source-path manifest
                         {:missing-fields [:null-exception-map]}))
    (when-not (= :declared (get-in manifest
                                   [:reflection-and-dynamic-use-manifest
                                    :status]))
      (b5-document-fail! "B5-REFLECTION" source-path manifest
                         {:missing-fields [:reflection-manifest]}))
    (when-not (= :complete (get-in manifest
                                   [:classloading-policy-record :status]))
      (b5-document-fail! "B5-CLASSLOADING" source-path manifest
                         {:missing-fields [:classloading-policy]}))
    (when-not (= :complete (get-in manifest
                                   [:resource-cleanup-record :status]))
      (b5-document-fail! "B5-RESOURCE" source-path manifest
                         {:missing-fields [:resource-cleanup]}))
    (when-not (= :complete
                 (get-in manifest
                         [:thread-monitor-executor-atomic-effect-record
                          :status]))
      (b5-document-fail! "B5-THREAD" source-path manifest
                         {:missing-fields [:thread-effect-record]}))
    (when-not (= :consistent (get-in manifest
                                     [:native-image-configuration :status]))
      (b5-document-fail! "B5-NATIVE-IMAGE" source-path manifest
                         {:missing-fields [:native-image-config]}))
    (when-not (= :complete (get-in manifest
                                   [:profile-boundary-record :status]))
      (b5-document-fail! "B5-PROFILE" source-path manifest
                         {:missing-fields [:profile-boundary]}))
    (when-not (b5-document-java-structurally-valid?
               b5-document-java-source)
      (b5-document-fail! "B5-MANIFEST" source-path manifest
                         {:missing-fields [:java-source-structure]}))
    (when-not (every? #(contains? manifest %)
                      [:classfile-and-jvm-target-record
                       :class-and-module-model
                       :java-source-files
                       :module-descriptors
                       :class-files
                       :jar-or-module-artifact
                       :java-interop-descriptor
                       :nullability-and-exception-translation-map
                       :reflection-and-dynamic-use-manifest
                       :native-image-configuration
                       :runtime-helper-manifest
                       :source-debug-map])
      (b5-document-fail! "B5-MANIFEST" source-path manifest
                         {:missing-fields [:jvm-artifact-manifest]}))
    (when-not (= (set b5-document-diagnostic-ids) diagnostics)
      (b5-document-fail! "B5-MANIFEST" source-path
                         (:b5-diagnostic-stream artifact)
                         {:missing-fields [:b5-diagnostics]})))
  :complete)

(defn b5-document-capability-proof
  [artifact]
  (let [manifest (:jvm-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b5-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:hosted-lowering-artifact
                           :capability-based-proof :status]))
     :classfile-jvm-target-pinned?
     (= :pinned (get-in manifest
                        [:classfile-and-jvm-target-record :status]))
     :class-module-model-covered?
     (= :complete (get-in manifest [:class-and-module-model :status]))
     :value-representation-covered?
     (= :complete (get-in manifest
                          [:value-representation-record :status]))
     :interop-descriptor-covered?
     (= :complete (get-in manifest [:java-interop-descriptor :status]))
     :nullability-and-exception-covered?
     (= :complete
        (get-in manifest
                [:nullability-and-exception-translation-map :status]))
     :reflection-dynamic-use-declared?
     (= :declared
        (get-in manifest
                [:reflection-and-dynamic-use-manifest :status]))
     :classloading-policy-covered?
     (= :complete (get-in manifest
                          [:classloading-policy-record :status]))
     :resource-cleanup-deterministic?
     (= :complete (get-in manifest
                          [:resource-cleanup-record :status]))
     :thread-monitor-executor-atomic-covered?
     (= :complete
        (get-in manifest
                [:thread-monitor-executor-atomic-effect-record :status]))
     :native-image-config-consistent?
     (= :consistent (get-in manifest
                            [:native-image-configuration :status]))
     :profile-boundary-rejection-covered?
     (= :complete (get-in manifest
                          [:profile-boundary-record :status]))
     :source-debug-map-preserved?
     (= :preserved (get-in manifest [:source-debug-map :status]))
     :java-source-structurally-valid?
     (b5-document-java-structurally-valid? b5-document-java-source)
     :manifest-complete?
     (every? #(contains? manifest %)
             [:classfile-and-jvm-target-record
              :class-and-module-model
              :java-source-files
              :module-descriptors
              :class-files
              :jar-or-module-artifact
              :java-interop-descriptor
              :nullability-and-exception-translation-map
              :reflection-and-dynamic-use-manifest
              :native-image-configuration
              :runtime-helper-manifest
              :source-debug-map])
     :diagnostics-covered?
     (= (set b5-document-diagnostic-ids) diagnostics)
     :requires-external-javac-proof?
     (= :requires-proof-command
        (get-in manifest [:javac-compilation-record :status]))
     :requires-external-jar-proof?
     (= :requires-proof-command
        (get-in manifest [:jar-creation-record :status]))
     :status :complete}))

(defn b5-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b5-document-source-overrides module)
        _ (b5-document-validate-source-overrides! source-path
                                                  source-overrides)
        hosted-artifact (hosted-lowering-source-artifact source-path
                                                         source-text)
        input-id (:artifact-id hosted-artifact)
        manifest (b5-document-jvm-manifest input-id)
        diagnostic-stream (b5-document-diagnostic-stream source-path
                                                         input-id)
        artifact-base
        {:kind :gravity/stage0-b5-jvm-backend-document-artifact
         :task "P07-D102"
         :document-set ["B5"]
         :governing-document b5-document-governing-document
         :pass {:name :b5-jvm-backend-document-coverage
                :input :hosted-lowering-artifact
                :output :b5-jvm-backend-document-artifact
                :requires [:verified-mir-or-domain-ir :b1-backend-interface
                           :c14-target-lowering :hosted-profile
                           :classfile-jvm-target-record
                           :exception-map :nullability-map
                           :runtime-provider-manifest
                           :interop-descriptor :source-debug-map]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :safety :proofs
                            :profile :target :artifact-provenance]
                :emits [:jvm-backend-manifest :java-source-files
                        :module-descriptors :classfile-target-record
                        :jar-or-module-artifact
                        :java-interop-descriptor
                        :nullability-and-exception-translation-map
                        :reflection-and-dynamic-use-manifest
                        :native-image-configuration
                        :runtime-helper-manifest
                        :source-debug-map :b5-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b5-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :hosted-lowering-artifact
         (select-keys hosted-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :hosted-lowering-results])
         :hosted-lowering-artifact-kind (:kind hosted-artifact)
         :hosted-lowering-artifact-hash input-id
         :jvm-backend-manifest manifest
         :classfile-and-jvm-target-record
         (:classfile-and-jvm-target-record manifest)
         :class-and-module-model (:class-and-module-model manifest)
         :java-source-files (:java-source-files manifest)
         :module-descriptors (:module-descriptors manifest)
         :class-files (:class-files manifest)
         :jar-or-module-artifact (:jar-or-module-artifact manifest)
         :java-interop-descriptor (:java-interop-descriptor manifest)
         :nullability-and-exception-translation-map
         (:nullability-and-exception-translation-map manifest)
         :reflection-and-dynamic-use-manifest
         (:reflection-and-dynamic-use-manifest manifest)
         :native-image-configuration (:native-image-configuration manifest)
         :runtime-helper-manifest (:runtime-helper-manifest manifest)
         :source-debug-map (:source-debug-map manifest)
         :rejected-design-coverage
         [{:design :java-null-as-safe-type-inhabitant
           :diagnostic "B5-NULL" :status :rejected}
          {:design :host-exception-leaks-through-safe-api
           :diagnostic "B5-EXCEPTION" :status :rejected}
          {:design :hidden-reflection-classloading
           :diagnostic "B5-REFLECTION" :status :rejected}
          {:design :gc-finalization-as-deterministic-cleanup
           :diagnostic "B5-RESOURCE" :status :rejected}
          {:design :jvm-only-semantics-through-lower-profile
           :diagnostic "B5-PROFILE" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b5-jvm-backend-conformance-criteria-record
          :classfile-jar-module-source-map :emitted
          :hosted-pure-code-and-interop-lowering :complete
          :nullability-wrapper-acceptance :complete
          :unchecked-null-rejection :covered
          :exception-translation-fixtures :covered
          :reflection-dynamic-loading-policy :covered
          :native-image-configuration :generated
          :linear-resource-cleanup-despite-gc :covered
          :thread-monitor-executor-atomic-effects :recorded
          :profile-boundary-rejection :covered
          :differential-execution :mir-reference-recorded
          :status :passed}
         :b5-diagnostic-stream diagnostic-stream
         :b5-document-results
         {:documents ["B5"]
          :task "P07-D102"
          :required-diagnostic-ids b5-document-diagnostic-ids
          :hosted-lowering-input-status :complete
          :target-status :complete
          :class-module-status :complete
          :value-representation-status :complete
          :interop-status :complete
          :nullability-status :complete
          :exception-status :complete
          :reflection-status :complete
          :classloading-status :complete
          :resource-status :complete
          :thread-status :complete
          :native-image-status :complete
          :profile-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b5-document-validate! source-path artifact-base)
        capability-proof (b5-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b5-document-file-artifact
  [path]
  (b5-document-source-artifact path (slurp path)))

(def b6-document-governing-document
  "docs/phase-07-backend-architecture/103-b6-javascript-typescript-backend-design.md")

(def b6-document-diagnostic-ids
  ["B6-TARGET"
   "B6-GLOBAL"
   "B6-IMPORT"
   "B6-NULLISH"
   "B6-EXCEPTION"
   "B6-NUMERIC"
   "B6-EVAL"
   "B6-PROTOTYPE"
   "B6-ASYNC"
   "B6-UI"
   "B6-MANIFEST"])

(def b6-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             b6-document-diagnostic-ids)))

(defn b6-document-source-overrides
  [module]
  (or (get-in module [:metadata :backend :b6-document])
      (get-in module [:metadata :backend :hosted-lowering])
      (get-in module [:metadata :backend :hosted])
      {}))

(defn b6-document-missing-fact
  [id]
  (case id
    "B6-TARGET" :runtime-ecmascript-module-bundler-source-map-target
    "B6-GLOBAL" :host-global-effect-capability-schema
    "B6-IMPORT" :typed-package-import-integrity-and-side-effect-policy
    "B6-NULLISH" :option-result-checked-nullish-adapter
    "B6-EXCEPTION" :exception-promise-callback-translation
    "B6-NUMERIC" :numeric-representation-boundary-validation
    "B6-EVAL" :dynamic-code-loading-policy
    "B6-PROTOTYPE" :prototype-object-layout-policy
    "B6-ASYNC" :async-effect-cancellation-event-loop-record
    "B6-UI" :ui-component-schema-source-map-capability-record
    "B6-MANIFEST" :complete-js-ts-artifact-manifest
    :b6-document-evidence))

(defn b6-document-host-symbol
  [id]
  (case id
    "B6-TARGET" "gravity-stage0.mjs"
    "B6-GLOBAL" "globalThis"
    "B6-IMPORT" "@gravity/stage0"
    "B6-NULLISH" "optionFromNullish"
    "B6-EXCEPTION" "translatePromise"
    "B6-NUMERIC" "checkedNumber"
    "B6-EVAL" "eval"
    "B6-PROTOTYPE" "Object.prototype"
    "B6-ASYNC" "Promise"
    "B6-UI" "GravityStage0Component"
    "B6-MANIFEST" "gravity/js-ts-backend-manifest"
    "gravity-stage0.mjs"))

(defn b6-document-selected-adapter
  [id]
  (case id
    "B6-TARGET" :browser-esm-target-record-or-reject
    "B6-GLOBAL" :host-global-capability-manifest-entry
    "B6-IMPORT" :typed-schema-wrapped-package-import
    "B6-NULLISH" :option-result-opaque-wrapper
    "B6-EXCEPTION" :gravity-error-panic-effect-adapter
    "B6-NUMERIC" :bigint-number-typed-array-checked-helper
    "B6-EVAL" :dynamic-code-rejection
    "B6-PROTOTYPE" :frozen-record-layout
    "B6-ASYNC" :async-effect-boundary-record
    "B6-UI" :component-schema-source-map-capability-record
    :js-ts-backend-record))

(defn b6-document-fail!
  [id source-path subject extra]
  (fail! id
         "B6 JavaScript/TypeScript backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b6-js-ts-backend-document
                 :stage (or (:stage subject)
                            :b6-js-ts-backend-document-coverage)
                 :backend :gravity.backend/js-ts
                 :profile (or (:profile subject) :hosted)
                 :runtime (or (:runtime subject) :browser)
                 :module-format (or (:module-format subject) :esm)
                 :ecmascript (or (:ecmascript subject) :es2022)
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :host-call)
                 :domain-anchor (:domain-anchor subject)
                 :host-symbol (or (:host-symbol subject)
                                  (b6-document-host-symbol id))
                 :package-id (or (:package-id subject)
                                 (when (= id "B6-IMPORT")
                                   "@gravity/stage0"))
                 :missing-effect-capability-schema-fact
                 (or (:missing-effect-capability-schema-fact subject)
                     (b6-document-missing-fact id))
                 :selected-adapter-or-rejection
                 (or (:selected-adapter-or-rejection subject)
                     (b6-document-selected-adapter id))
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Emit JS/TS artifacts only from verified hosted backend input with pinned runtime, ECMAScript, module, package, source-map, host-global, package-import, nullish, exception, async, numeric, UI, and manifest evidence."}
                extra)))

(defn b6-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b6-document-override-diagnostics fail-kind)]
      (b6-document-fail!
       id source-path
       {:stage :b6-js-ts-backend-document-coverage
        :artifact-id (str "b6-document-" (name fail-kind))
        :missing-effect-capability-schema-fact fail-kind
        :host-symbol (name fail-kind)}
       {:missing-fields [fail-kind]}))))

(def b6-document-js-source
  (str "export class GravityPanic extends Error {\n"
       "  constructor(message, cause) {\n"
       "    super(message);\n"
       "    this.name = \"GravityPanic\";\n"
       "    this.cause = cause;\n"
       "  }\n"
       "}\n\n"
       "export function gravityEntry(x) {\n"
       "  if (typeof x !== \"bigint\") {\n"
       "    throw new GravityPanic(\"expected Gravity I64 BigInt boundary\");\n"
       "  }\n"
       "  return x;\n"
       "}\n\n"
       "export function optionFromNullish(value) {\n"
       "  if (value === null || value === undefined) {\n"
       "    return Object.freeze({ tag: \"none\" });\n"
       "  }\n"
       "  return Object.freeze({ tag: \"some\", value });\n"
       "}\n\n"
       "export async function translatePromise(thunk) {\n"
       "  try {\n"
       "    return Object.freeze({ tag: \"ok\", value: await thunk() });\n"
       "  } catch (error) {\n"
       "    return Object.freeze({ tag: \"error\", error: normalizeHostError(error) });\n"
       "  }\n"
       "}\n\n"
       "export function checkedNumber(value) {\n"
       "  if (typeof value !== \"number\" || !Number.isFinite(value)) {\n"
       "    throw new GravityPanic(\"invalid Gravity F64 Number boundary\");\n"
       "  }\n"
       "  return value;\n"
       "}\n\n"
       "export function packI32(values) {\n"
       "  return Int32Array.from(values);\n"
       "}\n\n"
       "function normalizeHostError(error) {\n"
       "  if (error instanceof Error) {\n"
       "    return { name: error.name, message: error.message };\n"
       "  }\n"
       "  return { name: \"HostError\", message: String(error) };\n"
       "}\n\n"
       "export const numericPolicy = Object.freeze({\n"
       "  exactInteger: \"BigInt\",\n"
       "  float: \"Number\",\n"
       "  packed: \"Int32Array\",\n"
       "  jsonBoundary: \"schema-checked\"\n"
       "});\n\n"
       "export const capabilityManifest = Object.freeze({\n"
       "  globals: [{ symbol: \"globalThis\", effects: [], capabilities: [], schema: \"opaque-host-global\" }],\n"
       "  imports: []\n"
       "});\n\n"
       "export const componentMetadata = Object.freeze({\n"
       "  enabled: false,\n"
       "  sourceMap: \"gravity-stage0.mjs.map\",\n"
       "  capabilities: []\n"
       "});\n\n"
       "export default Object.freeze({\n"
       "  gravityEntry,\n"
       "  optionFromNullish,\n"
       "  translatePromise,\n"
       "  checkedNumber,\n"
       "  packI32,\n"
       "  numericPolicy,\n"
       "  capabilityManifest,\n"
       "  componentMetadata\n"
       "});\n"
       "//# sourceMappingURL=gravity-stage0.mjs.map\n"))

(def b6-document-ts-declarations
  (str "export type GravityOption<T> =\n"
       "  | Readonly<{ tag: \"none\" }>\n"
       "  | Readonly<{ tag: \"some\"; value: T }>;\n\n"
       "export type GravityResult<T, E> =\n"
       "  | Readonly<{ tag: \"ok\"; value: T }>\n"
       "  | Readonly<{ tag: \"error\"; error: E }>;\n\n"
       "export interface GravityHostError {\n"
       "  readonly name: string;\n"
       "  readonly message: string;\n"
       "}\n\n"
       "export declare class GravityPanic extends Error {\n"
       "  constructor(message: string, cause?: unknown);\n"
       "}\n\n"
       "export declare function gravityEntry(x: bigint): bigint;\n"
       "export declare function optionFromNullish<T>(value: T | null | undefined): GravityOption<T>;\n"
       "export declare function translatePromise<T>(thunk: () => Promise<T> | T): Promise<GravityResult<T, GravityHostError>>;\n"
       "export declare function checkedNumber(value: number): number;\n"
       "export declare function packI32(values: Iterable<number>): Int32Array;\n"
       "export declare const numericPolicy: Readonly<{ exactInteger: \"BigInt\"; float: \"Number\"; packed: \"Int32Array\"; jsonBoundary: \"schema-checked\" }>;\n"
       "export declare const capabilityManifest: Readonly<{ globals: readonly Readonly<{ symbol: \"globalThis\"; effects: readonly []; capabilities: readonly []; schema: \"opaque-host-global\" }>[]; imports: readonly [] }>;\n"
       "export declare const componentMetadata: Readonly<{ enabled: false; sourceMap: \"gravity-stage0.mjs.map\"; capabilities: readonly [] }>;\n"))

(def b6-document-source-map
  (str "{\"version\":3,"
       "\"file\":\"gravity-stage0.mjs\","
       "\"sources\":[\"bootstrap/clojure/fixtures/accepted/backend-hosted-lowering.gravity\"],"
       "\"sourcesContent\":[],"
       "\"names\":[\"GravityPanic\",\"gravityEntry\",\"optionFromNullish\",\"translatePromise\",\"checkedNumber\",\"packI32\"],"
       "\"mappings\":\"\","
       "\"x_gravity_generated_origin\":[\"mir\",\"c14-target-lowering\",\"b1-interface\",\"b6-js-ts-backend\"]}\n"))

(def b6-document-package-json
  (str "{\"name\":\"@gravity/stage0-js-ts\","
       "\"version\":\"0.0.0-stage0\","
       "\"type\":\"module\","
       "\"sideEffects\":false,"
       "\"exports\":{\".\":{\"types\":\"./gravity-stage0.d.ts\","
       "\"import\":\"./gravity-stage0.mjs\"}},"
       "\"files\":[\"gravity-stage0.mjs\","
       "\"gravity-stage0.d.ts\","
       "\"gravity-stage0.mjs.map\"]}\n"))

(defn b6-document-js-structurally-valid?
  [source]
  (and (str/includes? source "export function gravityEntry")
       (str/includes? source "export async function translatePromise")
       (str/includes? source "typeof x !== \"bigint\"")
       (str/includes? source "Int32Array.from")
       (str/includes? source "Object.freeze")
       (str/includes? source "sourceMappingURL=gravity-stage0.mjs.map")
       (not (str/includes? source "eval("))
       (not (str/includes? source "new Function"))))

(defn b6-document-ts-structurally-valid?
  [source]
  (and (str/includes? source "export declare function gravityEntry")
       (str/includes? source "bigint")
       (str/includes? source "GravityOption")
       (str/includes? source "Promise<GravityResult")
       (str/includes? source "Int32Array")
       (str/includes? source "Readonly")))

(defn b6-document-source-map-structurally-valid?
  [source]
  (and (str/includes? source "\"version\":3")
       (str/includes? source "\"file\":\"gravity-stage0.mjs\"")
       (str/includes? source "\"sources\"")
       (str/includes? source "\"x_gravity_generated_origin\"")))

(defn b6-document-package-structurally-valid?
  [source]
  (and (str/includes? source "\"type\":\"module\"")
       (str/includes? source "\"sideEffects\":false")
       (str/includes? source "\"types\":\"./gravity-stage0.d.ts\"")
       (str/includes? source "\"import\":\"./gravity-stage0.mjs\"")))

(defn b6-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b6-js-ts-backend-diagnostic-stream
   :stage :b6-js-ts-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b6-js-ts-backend-document-coverage
            :backend :gravity.backend/js-ts
            :message-key (keyword "backend-js-ts" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b6-document-syntax-" index)
                      :artifact input-id}
            :mir-op (case id
                      "B6-GLOBAL" :host-global-access
                      "B6-IMPORT" :package-import
                      "B6-NULLISH" :host-nullish-boundary
                      "B6-EXCEPTION" :host-exception-boundary
                      "B6-NUMERIC" :numeric-lowering
                      "B6-ASYNC" :async-host-boundary
                      :host-call)
            :domain-anchor (when (= id "B6-UI") :ui-component)
            :runtime :browser
            :module-format :esm
            :ecmascript :es2022
            :host-symbol (b6-document-host-symbol id)
            :package-id (when (= id "B6-IMPORT") "@gravity/stage0")
            :missing-effect-capability-schema-fact
            (b6-document-missing-fact id)
            :selected-adapter-or-rejection (b6-document-selected-adapter id)
            :fallback-status :rejected
            :facts {:ambient-global-policy :reject-without-capability
                    :nullish-policy :option-result-checked-or-opaque
                    :exception-policy :translate
                    :dynamic-code-policy :denied
                    :numeric-policy :manifested}
            :remediation [{:kind :pin-js-runtime-target}
                          {:kind :declare-host-global-or-import}
                          {:kind :emit-type-declaration-source-map-and-boundary-map}]
            :redactions []
            :ordering-key [id :b6-js-ts-backend-document-coverage
                           :browser-esm]})
         b6-document-diagnostic-ids
         (range))
   :status :complete})

