               :signedness :unsigned :clock-domain :clk
               :protocol :clock}
              {:name :rst :direction :input :width 1
               :signedness :unsigned :clock-domain :clk
               :reset-domain :rst :protocol :reset}
              {:name :input_valid :direction :input :width 1
               :signedness :unsigned :clock-domain :clk
               :protocol :ready-valid}
              {:name :input_data :direction :input :width 32
               :signedness :unsigned :clock-domain :clk
