(defn b12-document-validate!
  [source-path artifact]
  (let [specialized (:specialized-lowering-artifact artifact)
        manifest (:mobile-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b12-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-specialized-lowering-artifact
                 (:kind specialized))
      (b12-document-fail! "B12-MANIFEST" source-path specialized
                          {:missing-fields [:specialized-lowering-artifact]}))
    (when-not (= :complete (get-in specialized
                                   [:capability-based-proof :status]))
      (b12-document-fail! "B12-MANIFEST" source-path specialized
                          {:missing-fields [:specialized-lowering-proof]}))
    (when-not (= :ios (get-in manifest [:target :platform]))
      (b12-document-fail! "B12-TARGET" source-path manifest
                          {:missing-fields [:target-platform]}))
    (when-not (= :complete (get-in manifest
                                   [:mobile-ir-handoff-record :status]))
      (b12-document-fail! "B12-MANIFEST" source-path manifest
                          {:missing-fields [:mobile-ir-handoff-record]}))
    (when-not (= :complete (get-in manifest
                                   [:platform-target-record :status]))
      (b12-document-fail! "B12-TARGET" source-path manifest
                          {:missing-fields [:platform-target-record]}))
    (when-not (= :complete (get-in manifest
                                   [:application-bundle-artifact :status]))
      (b12-document-fail! "B12-RESOURCE" source-path manifest
                          {:missing-fields [:application-bundle-artifact]}))
    (when-not (b12-document-bundle-structurally-valid?
               b12-document-app-bundle)
      (b12-document-fail! "B12-RESOURCE" source-path manifest
                          {:missing-fields [:application-bundle-structure]}))
    (when-not (seq (:platform-binding-descriptors manifest))
      (b12-document-fail! "B12-MANIFEST" source-path manifest
                          {:missing-fields [:platform-binding-descriptors]}))
    (when-not (= :complete (get-in manifest [:permission-manifest :status]))
      (b12-document-fail! "B12-PERMISSION" source-path manifest
                          {:missing-fields [:permission-manifest]}))
    (when-not (b12-document-permission-structurally-valid?
               b12-document-permission-manifest-fixture)
      (b12-document-fail! "B12-PERMISSION" source-path manifest
                          {:missing-fields [:permission-policy]}))
    (when-not (= :complete (get-in manifest
                                   [:resource-asset-manifest :status]))
      (b12-document-fail! "B12-RESOURCE" source-path manifest
                          {:missing-fields [:resource-asset-manifest]}))
    (when-not (= :complete (get-in manifest
                                   [:lifecycle-threading-map :status]))
      (b12-document-fail! "B12-LIFECYCLE" source-path manifest
                          {:missing-fields [:lifecycle-threading-map]}))
    (when-not (= :main (get-in manifest
                               [:lifecycle-threading-map :ui-thread]))
      (b12-document-fail! "B12-THREAD" source-path manifest
                          {:missing-fields [:main-thread-policy]}))
    (when-not (= :complete (get-in manifest [:ui-bridge-metadata :status]))
      (b12-document-fail! "B12-TARGET" source-path manifest
                          {:missing-fields [:ui-bridge-metadata]}))
    (when-not (= :complete (get-in manifest
                                   [:null-error-callback-adapter-record
                                    :status]))
      (b12-document-fail! "B12-NULL" source-path manifest
                          {:missing-fields [:null-error-callback-adapters]}))
    (when-not (= :mapped-to-gravity-errors
                 (get-in manifest
                         [:null-error-callback-adapter-record
                          :exceptions]))
      (b12-document-fail! "B12-ERROR" source-path manifest
                          {:missing-fields [:platform-error-mapping]}))
    (when-not (= :complete (get-in manifest
                                   [:local-storage-sync-schema-bundle
                                    :status]))
      (b12-document-fail! "B12-STORAGE" source-path manifest
                          {:missing-fields [:local-storage-sync-schema]}))
    (when-not (= :complete (get-in manifest
                                   [:background-task-policy :status]))
      (b12-document-fail! "B12-BACKGROUND" source-path manifest
                          {:missing-fields [:background-task-policy]}))
    (when-not (= :rejected (get-in manifest
                                   [:background-task-policy
                                    :hidden-background-execution]))
      (b12-document-fail! "B12-BACKGROUND" source-path manifest
                          {:missing-fields [:hidden-background-rejection]}))
    (when-not (= :complete (get-in manifest [:store-audit-metadata :status]))
      (b12-document-fail! "B12-MANIFEST" source-path manifest
                          {:missing-fields [:store-audit-metadata]}))
    (when-not (= :preserved (get-in manifest [:source-debug-map :status]))
      (b12-document-fail! "B12-MANIFEST" source-path manifest
                          {:missing-fields [:source-debug-map]}))
    (when-not (= :complete (get-in manifest
                                   [:device-simulator-conformance-report
                                    :status]))
      (b12-document-fail! "B12-MANIFEST" source-path manifest
                          {:missing-fields [:device-simulator-conformance]}))
    (when-not (every? #(contains? manifest %)
                      [:mobile-ir-handoff-record
                       :platform-target-record
                       :application-bundle-artifact
                       :platform-binding-descriptors
                       :permission-manifest
                       :resource-asset-manifest
                       :lifecycle-threading-map
                       :ui-bridge-metadata
                       :null-error-callback-adapter-record
                       :local-storage-sync-schema-bundle
                       :background-task-policy
                       :store-audit-metadata
                       :source-debug-map
                       :device-simulator-conformance-report
                       :external-mobile-validation-record])
      (b12-document-fail! "B12-MANIFEST" source-path manifest
                          {:missing-fields [:mobile-artifact-manifest]}))
    (when-not (= (set b12-document-diagnostic-ids) diagnostics)
      (b12-document-fail! "B12-MANIFEST" source-path
                          (:b12-diagnostic-stream artifact)
                          {:missing-fields [:b12-diagnostics]})))
  :complete)

(defn b12-document-capability-proof
  [artifact]
  (let [manifest (:mobile-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b12-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:specialized-lowering-artifact
                           :capability-based-proof :status]))
     :mobile-ir-handoff-covered?
     (= :complete (get-in manifest
                          [:mobile-ir-handoff-record :status]))
     :platform-target-covered?
     (= :complete (get-in manifest
                          [:platform-target-record :status]))
     :application-bundle-emitted?
     (and (= :complete (get-in manifest
                               [:application-bundle-artifact :status]))
          (b12-document-bundle-structurally-valid?
           b12-document-app-bundle))
     :platform-bindings-covered?
     (every? #(= :complete (:status %))
             (:platform-binding-descriptors manifest))
     :permission-manifest-covered?
     (and (= :complete (get-in manifest [:permission-manifest :status]))
          (b12-document-permission-structurally-valid?
           b12-document-permission-manifest-fixture))
     :resource-asset-manifest-covered?
     (= :complete (get-in manifest
                          [:resource-asset-manifest :status]))
     :lifecycle-and-threading-covered?
     (and (= :complete (get-in manifest
                               [:lifecycle-threading-map :status]))
          (= :main (get-in manifest
                           [:lifecycle-threading-map :ui-thread])))
     :ui-bridge-covered?
     (= :complete (get-in manifest [:ui-bridge-metadata :status]))
     :null-and-error-adapters-covered?
     (and (= :complete (get-in manifest
                               [:null-error-callback-adapter-record
                                :status]))
          (= :mapped-to-gravity-errors
             (get-in manifest
                     [:null-error-callback-adapter-record
                      :exceptions])))
     :storage-sync-covered?
     (= :complete (get-in manifest
                          [:local-storage-sync-schema-bundle :status]))
     :background-work-rejected?
     (= :rejected (get-in manifest
                          [:background-task-policy
                           :hidden-background-execution]))
     :store-audit-covered?
     (= :complete (get-in manifest [:store-audit-metadata :status]))
     :source-debug-map-preserved?
     (= :preserved (get-in manifest [:source-debug-map :status]))
     :device-simulator-record-covered?
     (= :complete (get-in manifest
                          [:device-simulator-conformance-report
                           :status]))
     :manifest-complete?
     (every? #(contains? manifest %)
             [:mobile-ir-handoff-record
              :platform-target-record
              :application-bundle-artifact
              :platform-binding-descriptors
              :permission-manifest
              :resource-asset-manifest
              :lifecycle-threading-map
              :ui-bridge-metadata
              :null-error-callback-adapter-record
              :local-storage-sync-schema-bundle
              :background-task-policy
              :store-audit-metadata
              :source-debug-map
              :device-simulator-conformance-report
              :external-mobile-validation-record])
     :diagnostics-covered?
     (= (set b12-document-diagnostic-ids) diagnostics)
     :external-mobile-validation?
     (get-in manifest [:external-mobile-validation-record :status])
     :status :complete}))

(defn b12-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b12-document-source-overrides module)
        _ (b12-document-validate-source-overrides! source-path
                                                   source-overrides)
        specialized-artifact (specialized-lowering-source-artifact source-path
                                                                   source-text)
        input-id (:artifact-id specialized-artifact)
        manifest (b12-document-mobile-manifest source-path input-id)
        diagnostic-stream (b12-document-diagnostic-stream source-path
                                                          input-id)
        artifact-base
        {:kind :gravity/stage0-b12-mobile-backend-document-artifact
         :task "P07-D109"
         :document-set ["B12"]
         :governing-document b12-document-governing-document
         :pass {:name :b12-mobile-backend-document-coverage
                :input :specialized-lowering-artifact
                :output :b12-mobile-backend-document-artifact
                :requires [:verified-mir-or-ui-domain-ir
                           :b1-backend-interface :c11-mir
                           :c12-domain-ir :c14-target-lowering
                           :platform-target :permission-manifest
                           :lifecycle-threading-map :capability-manifest
                           :platform-adapter-map :storage-sync-schema
                           :store-audit-metadata]
                :preserves [:source-spans :generated-origins :schemas
                            :effects :capabilities :taint-facts
                            :lifecycle :threading :permissions
                            :resources :store-policy :safety :proofs
                            :profile :target :artifact-provenance]
                :emits [:mobile-backend-manifest
                        :platform-target-record
                        :application-bundle-artifact
                        :platform-binding-descriptors
                        :permission-manifest
                        :resource-asset-manifest
                        :lifecycle-threading-map
                        :ui-bridge-metadata
                        :local-storage-sync-schema-bundle
                        :store-audit-metadata
                        :source-debug-map
                        :device-simulator-conformance-report
                        :b12-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b12-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :specialized-lowering-artifact
         (select-keys specialized-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :mobile-backend :specialized-lowering-results])
         :specialized-lowering-artifact-kind (:kind specialized-artifact)
         :specialized-lowering-artifact-hash input-id
         :mobile-backend-manifest manifest
         :platform-target-record (:platform-target-record manifest)
         :application-bundle-artifact
         (:application-bundle-artifact manifest)
         :platform-binding-descriptors
         (:platform-binding-descriptors manifest)
         :permission-manifest (:permission-manifest manifest)
         :resource-asset-manifest (:resource-asset-manifest manifest)
         :lifecycle-threading-map (:lifecycle-threading-map manifest)
         :ui-bridge-metadata (:ui-bridge-metadata manifest)
         :null-error-callback-adapter-record
         (:null-error-callback-adapter-record manifest)
         :local-storage-sync-schema-bundle
         (:local-storage-sync-schema-bundle manifest)
         :background-task-policy (:background-task-policy manifest)
         :store-audit-metadata (:store-audit-metadata manifest)
         :source-debug-map (:source-debug-map manifest)
         :device-simulator-conformance-report
         (:device-simulator-conformance-report manifest)
         :rejected-design-coverage
         [{:design :platform-api-without-permission-or-capability
           :diagnostic "B12-PERMISSION" :status :rejected}
          {:design :hidden-background-network-or-sync-work
           :diagnostic "B12-BACKGROUND" :status :rejected}
          {:design :unchecked-platform-null-error-callback-or-lifecycle
           :diagnostic "B12-NULL" :status :rejected}
          {:design :ui-update-without-main-thread-or-actor
           :diagnostic "B12-THREAD" :status :rejected}
          {:design :local-storage-sync-without-schema-migration
           :diagnostic "B12-STORAGE" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b12-mobile-backend-conformance-criteria-record
          :ios-and-android-style-platform-target-manifests :complete
          :app-bundle-resource-permission-binding-emission :complete
          :platform-api-capability-acceptance-and-rejection :covered
          :lifecycle-and-threading-diagnostics :complete
          :null-error-callback-adapter-fixtures :complete
          :camera-network-storage-notification-background-permission-tests
          :covered
          :local-schema-migration-offline-sync-artifacts :complete
          :source-provenance-effect-capability-metadata-preservation :complete
          :simulator-device-smoke-records :recorded
          :status :passed}
         :b12-diagnostic-stream diagnostic-stream
         :b12-document-results
         {:documents ["B12"]
          :task "P07-D109"
          :required-diagnostic-ids b12-document-diagnostic-ids
          :specialized-lowering-input-status :complete
          :mobile-ir-status :complete
          :target-status :complete
          :bundle-status :complete
          :binding-status :complete
          :permission-status :complete
          :resource-status :complete
          :lifecycle-status :complete
          :thread-status :complete
          :ui-bridge-status :complete
          :null-error-status :complete
          :background-status :complete
          :storage-sync-status :complete
          :store-audit-status :complete
          :simulator-record-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b12-document-validate! source-path artifact-base)
        capability-proof (b12-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b12-document-file-artifact
  [path]
  (b12-document-source-artifact path (slurp path)))

(def b13-document-governing-document
  "docs/phase-07-backend-architecture/110-b13-artifact-emission-specification.md")

(def b13-document-diagnostic-ids
  artifact-emission-diagnostic-ids)

(def b13-document-override-diagnostics
  artifact-emission-override-diagnostics)

(defn b13-document-source-overrides
  [module]
  (artifact-emission-source-overrides module))

(defn b13-document-missing-policy
  [id]
  (case id
    "B13-SCHEMA" :common-artifact-manifest-schema
    "B13-HASH" :content-addressed-artifact-hash
    "B13-PROVENANCE" :source-compiler-generator-pass-dependency-provenance
    "B13-SOURCEMAP" :source-debug-generated-origin-map
    "B13-EVIDENCE" :safety-proof-certificate-effect-capability-evidence
    "B13-TARGET" :target-runtime-provider-abi-layout-record
    "B13-CONFORMANCE" :conformance-evidence-reference
    "B13-REPRODUCIBILITY" :reproducibility-nondeterminism-environment-record
    "B13-RELEASE" :release-grade-evidence-gate
    :artifact-graph))

(defn b13-document-fail!
  [id source-path subject extra]
  (fail! id
         "B13 artifact emission specification document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b13-artifact-emission-document
                 :stage :b13-artifact-emission-document-coverage
                 :backend (or (:backend subject)
                              :gravity.backend/artifact-emission)
                 :profile (or (:profile subject) :hosted)
                 :target (or (:target subject) :multi-target-stage0)
                 :artifact-id (:artifact-id subject)
                 :artifact-kind (or (:artifact-kind subject)
                                    (:kind subject))
                 :missing-policy (b13-document-missing-policy id)
                 :missing-evidence (:missing-evidence subject)
                 :stale-field (:stale-field subject)
                 :release-grade? (:release-grade? subject)
                 :fallback-status :rejected
                 :remediation "B13 requires common artifact manifests, content hashes, provenance, source/debug maps, safety/proof/effect/capability evidence, target/runtime/ABI records, reproducibility, conformance evidence, release gates, and a backend-neutral artifact graph before downstream packaging, tooling, or conformance consumption."}
                extra)))

(defn b13-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b13-document-override-diagnostics fail-kind)]
      (b13-document-fail!
       id source-path
       {:artifact-id (str "b13-document-" (name fail-kind))
        :artifact-kind :gravity/artifact-manifest
        :missing-evidence [fail-kind]
        :stale-field fail-kind
        :release-grade? (= id "B13-RELEASE")}
       {:missing-fields [fail-kind]}))))

(defn b13-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b13-artifact-emission-diagnostic-stream
   :stage :b13-artifact-emission-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b13-artifact-emission-document-coverage
            :backend :gravity.backend/artifact-emission
            :message-key (keyword "backend-artifact" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b13-document-syntax-" index)
                      :artifact input-id}
            :profile :hosted
            :target :multi-target-stage0
            :artifact-kind (case id
                             "B13-GRAPH" :gravity/artifact-graph
                             "B13-SOURCEMAP" :gravity/source-debug-map
                             "B13-RELEASE" :gravity/release-gate
                             :gravity/artifact-manifest)
            :missing-policy (b13-document-missing-policy id)
            :source-generated-origin-chain
            [:reader :macro-expansion :core :checked-core :mir
             :domain-ir :optimization :lowering :backend-emission]
            :missing-evidence #{:schema :content-hash :source-map
                                :compiler-provenance
                                :dependency-provenance :safety
                                :proofs :effects :capabilities
                                :runtime-provider :abi-layout
                                :reproducibility :conformance}
            :stale-field id
            :release-grade? (= id "B13-RELEASE")
            :fallback-status :rejected
            :facts {:common-manifest-required true
                    :content-addressing-required true
                    :source-debug-map-required true
                    :release-evidence-required true
                    :downstream-consumption-blocked-on-failure true}
            :remediation [{:kind :rebuild-common-artifact-manifest}
                          {:kind :preserve-generated-origin-chain}
                          {:kind :attach-evidence-provenance-and-hashes}
                          {:kind :block-release-grade-output}]
            :redactions []
            :ordering-key [id :b13-artifact-emission-document-coverage
                           :multi-target-stage0]})
         b13-document-diagnostic-ids
         (range))
   :status :complete})

(defn b13-document-artifact-index
  [artifact-emission-artifact]
  (let [manifests (:artifact-manifests artifact-emission-artifact)]
    {:artifact :gravity/b13-common-artifact-manifest-index
     :schema-version 1
     :input-artifact (:artifact-id artifact-emission-artifact)
     :manifest-count (count manifests)
     :content-hash-count (count (:content-hash-records
                                 artifact-emission-artifact))
     :artifact-kinds (set (map :kind manifests))
     :backends (set (map :backend manifests))
     :profiles (set (map :profile manifests))
     :targets (set (map :target manifests))
     :content-hashes (mapv :content-hash manifests)
     :all-manifests-schema-valid?
     (every? #(set/subset?
               (set native-artifact-manifest-required-fields)
               (set (keys %)))
             manifests)
     :all-content-addressed?
     (every? #(re-find #"^sha256:" (:content-hash %)) manifests)
     :common-fields native-artifact-manifest-required-fields
     :status :complete}))

(defn b13-document-downstream-consumption-record
  [artifact-emission-artifact]
  {:artifact :gravity/b13-downstream-consumption-record
   :input-artifact (:artifact-id artifact-emission-artifact)
   :consumers
   [{:consumer :package-system
     :required-inputs [:artifact-manifests :artifact-graph
                       :content-hash-records :release-gate-record]
     :status :complete}
    {:consumer :tooling
     :required-inputs [:source-debug-map-record
                       :compiler-provenance-record
                       :dependency-provenance-record
                       :diagnostic-stream]
     :status :complete}
    {:consumer :conformance
     :required-inputs [:safety-proof-certificate-bundle
                       :effect-capability-summary
                       :target-runtime-abi-layout-summary
                       :conformance-evidence-reference
                       :reproducibility-record]
     :status :complete}]
   :release-consumption :blocked-until-release-grade-evidence
   :status :complete})

(defn b13-document-validate!
  [source-path artifact]
  (let [artifact-emission (:artifact-emission-artifact artifact)
        index (:common-artifact-manifest-index artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b13-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-artifact-emission-artifact
                 (:kind artifact-emission))
      (b13-document-fail! "B13-SCHEMA" source-path artifact-emission
                          {:missing-fields [:artifact-emission-artifact]}))
    (when-not (= :complete (get-in artifact-emission
                                   [:capability-based-proof :status]))
      (b13-document-fail! "B13-EVIDENCE" source-path artifact-emission
                          {:missing-fields [:artifact-emission-proof]}))
    (when-not (= 12 (:manifest-count index))
      (b13-document-fail! "B13-SCHEMA" source-path index
                          {:missing-fields [:common-manifest-count]}))
    (when-not (:all-manifests-schema-valid? index)
      (b13-document-fail! "B13-SCHEMA" source-path index
                          {:missing-fields [:common-manifest-schema]}))
    (when-not (:all-content-addressed? index)
      (b13-document-fail! "B13-HASH" source-path index
                          {:missing-fields [:content-hashes]}))
    (when-not (= 12 (:content-hash-count index))
      (b13-document-fail! "B13-HASH" source-path index
                          {:missing-fields [:content-hash-records]}))
    (when-not (= :complete (get-in artifact
                                   [:artifact-graph :status]))
      (b13-document-fail! "B13-GRAPH" source-path (:artifact-graph artifact)
                          {:missing-fields [:artifact-graph]}))
    (when-not (= :preserved (get-in artifact
                                    [:source-debug-map-record :status]))
      (b13-document-fail! "B13-SOURCEMAP" source-path
                          (:source-debug-map-record artifact)
                          {:missing-fields [:source-debug-map]}))
    (when-not (= :complete (get-in artifact
                                   [:compiler-provenance-record :status]))
      (b13-document-fail! "B13-PROVENANCE" source-path
                          (:compiler-provenance-record artifact)
                          {:missing-fields [:compiler-provenance]}))
    (when-not (= :complete (get-in artifact
                                   [:dependency-provenance-record :status]))
      (b13-document-fail! "B13-PROVENANCE" source-path
                          (:dependency-provenance-record artifact)
                          {:missing-fields [:dependency-provenance]}))
    (when-not (= :complete (get-in artifact
                                   [:safety-proof-certificate-bundle
                                    :status]))
      (b13-document-fail! "B13-EVIDENCE" source-path
                          (:safety-proof-certificate-bundle artifact)
                          {:missing-fields [:safety-proof-certificate-bundle]}))
    (when-not (= :complete (get-in artifact
                                   [:effect-capability-summary :status]))
      (b13-document-fail! "B13-EVIDENCE" source-path
                          (:effect-capability-summary artifact)
                          {:missing-fields [:effect-capability-summary]}))
    (when-not (= :complete (get-in artifact
                                   [:runtime-provider-summary :status]))
      (b13-document-fail! "B13-TARGET" source-path
                          (:runtime-provider-summary artifact)
                          {:missing-fields [:runtime-provider-summary]}))
    (when-not (= :complete (get-in artifact
                                   [:target-runtime-abi-layout-summary
                                    :status]))
      (b13-document-fail! "B13-TARGET" source-path
                          (:target-runtime-abi-layout-summary artifact)
                          {:missing-fields [:target-runtime-abi-layout]}))
    (when-not (= :complete (get-in artifact
                                   [:conformance-evidence-reference
                                    :status]))
      (b13-document-fail! "B13-CONFORMANCE" source-path
                          (:conformance-evidence-reference artifact)
                          {:missing-fields [:conformance-evidence-reference]}))
    (when-not (= :recorded (get-in artifact
                                   [:reproducibility-record :status]))
      (b13-document-fail! "B13-REPRODUCIBILITY" source-path
                          (:reproducibility-record artifact)
                          {:missing-fields [:reproducibility-record]}))
    (when-not (= :blocked-development-only
                 (get-in artifact [:release-gate-record
                                   :release-grade-artifact-status]))
      (b13-document-fail! "B13-RELEASE" source-path
                          (:release-gate-record artifact)
                          {:missing-fields [:release-gate-record]}))
    (when-not (= :complete (get-in artifact
                                   [:downstream-consumption-record
                                    :status]))
      (b13-document-fail! "B13-GRAPH" source-path
                          (:downstream-consumption-record artifact)
                          {:missing-fields [:downstream-consumption-record]}))
    (when-not (= :passed (get-in artifact
                                 [:conformance-criteria-record :status]))
      (b13-document-fail! "B13-CONFORMANCE" source-path
                          (:conformance-criteria-record artifact)
                          {:missing-fields [:conformance-criteria-record]}))
    (when-not (= (set b13-document-diagnostic-ids) diagnostics)
      (b13-document-fail! "B13-SCHEMA" source-path
                          (:b13-diagnostic-stream artifact)
                          {:missing-fields [:b13-diagnostics]})))
  :complete)

(defn b13-document-capability-proof
  [artifact]
  (let [index (:common-artifact-manifest-index artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b13-diagnostic-stream
                                       :diagnostics])))]
    {:artifact-emission-input-verified?
     (= :complete (get-in artifact
                          [:artifact-emission-artifact
                           :capability-based-proof :status]))
     :common-manifest-schema-covered?
     (and (= 12 (:manifest-count index))
          (:all-manifests-schema-valid? index))
     :content-hashes-covered?
     (and (= 12 (:content-hash-count index))
          (:all-content-addressed? index))
     :provenance-covered?
     (and (= :complete (get-in artifact
                               [:compiler-provenance-record :status]))
          (= :complete (get-in artifact
                               [:dependency-provenance-record :status])))
     :source-debug-map-preserved?
     (= :preserved (get-in artifact [:source-debug-map-record :status]))
     :evidence-bundle-covered?
     (= :complete (get-in artifact
                          [:safety-proof-certificate-bundle :status]))
     :effect-capability-summary-covered?
     (= :complete (get-in artifact
                          [:effect-capability-summary :status]))
     :runtime-provider-summary-covered?
     (= :complete (get-in artifact
                          [:runtime-provider-summary :status]))
     :target-runtime-abi-covered?
     (= :complete (get-in artifact
                          [:target-runtime-abi-layout-summary :status]))
     :conformance-reference-covered?
     (= :complete (get-in artifact
                          [:conformance-evidence-reference :status]))
     :reproducibility-covered?
     (= :recorded (get-in artifact [:reproducibility-record :status]))
     :release-gate-covered?
     (= :blocked-development-only
        (get-in artifact [:release-gate-record
                          :release-grade-artifact-status]))
     :artifact-graph-covered?
     (= :complete (get-in artifact [:artifact-graph :status]))
     :downstream-consumption-covered?
     (= :complete (get-in artifact
                          [:downstream-consumption-record :status]))
     :diagnostics-covered?
     (= (set b13-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn b13-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b13-document-source-overrides module)
        _ (b13-document-validate-source-overrides! source-path
                                                   source-overrides)
        artifact-emission-artifact (artifact-emission-source-artifact
                                    source-path source-text)
        input-id (:artifact-id artifact-emission-artifact)
        manifest-index (b13-document-artifact-index
                        artifact-emission-artifact)
        downstream-consumption (b13-document-downstream-consumption-record
                                artifact-emission-artifact)
        diagnostic-stream (b13-document-diagnostic-stream source-path
                                                          input-id)
        artifact-base
        {:kind :gravity/stage0-b13-artifact-emission-document-artifact
         :task "P07-D110"
         :document-set ["B13"]
         :governing-document b13-document-governing-document
         :pass {:name :b13-artifact-emission-document-coverage
                :input :artifact-emission-artifact
                :output :b13-artifact-emission-document-artifact
                :requires [:common-manifest-schema :content-hashes
                           :artifact-graph :source-debug-map
                           :compiler-provenance :dependency-provenance
                           :safety-proof-certificate-bundle
                           :effect-capability-summary
                           :runtime-provider-summary
                           :target-runtime-abi-layout-summary
                           :conformance-evidence-reference
                           :reproducibility-record :release-gate-record
                           :downstream-consumption-record]
                :preserves [:source-spans :generated-origin-chain
                            :profile :target :runtime :backend
                            :effects :capabilities :safety :proofs
                            :unsafe-audit-ids :diagnostics
                            :artifact-provenance]
                :emits [:common-artifact-manifest-index
                        :content-hash-records :artifact-graph
                        :source-debug-map-record
                        :compiler-provenance-record
                        :dependency-provenance-record
                        :safety-proof-certificate-bundle
                        :effect-capability-summary
                        :runtime-provider-summary
                        :target-runtime-abi-layout-summary
                        :conformance-evidence-reference
                        :reproducibility-record :release-gate-record
                        :downstream-consumption-record
                        :b13-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b13-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :artifact-emission-artifact
         (select-keys artifact-emission-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :artifact-emission-results])
         :artifact-emission-artifact-kind (:kind artifact-emission-artifact)
         :artifact-emission-artifact-hash input-id
         :common-artifact-manifest-index manifest-index
         :artifact-manifests (:artifact-manifests artifact-emission-artifact)
         :content-hash-records
         (:content-hash-records artifact-emission-artifact)
         :artifact-graph (:artifact-graph artifact-emission-artifact)
         :source-debug-map-record
         (:source-debug-map-record artifact-emission-artifact)
         :compiler-provenance-record
         (:compiler-provenance-record artifact-emission-artifact)
         :dependency-provenance-record
         (:dependency-provenance-record artifact-emission-artifact)
         :safety-proof-certificate-bundle
         (:safety-proof-certificate-bundle artifact-emission-artifact)
         :effect-capability-summary
         (:effect-capability-summary artifact-emission-artifact)
         :runtime-provider-summary
         (:runtime-provider-summary artifact-emission-artifact)
         :target-runtime-abi-layout-summary
         (:target-runtime-abi-layout-summary artifact-emission-artifact)
         :conformance-evidence-reference
         (:conformance-evidence-reference artifact-emission-artifact)
         :reproducibility-record
         (:reproducibility-record artifact-emission-artifact)
         :release-gate-record (:release-gate-record artifact-emission-artifact)
         :downstream-consumption-record downstream-consumption
         :rejected-design-coverage
         [{:design :bytes-without-typed-common-manifest
           :diagnostic "B13-SCHEMA" :status :rejected}
          {:design :release-artifact-without-content-provenance-safety-conformance
           :diagnostic "B13-RELEASE" :status :rejected}
          {:design :source-map-stopping-before-macro-mir-backend
           :diagnostic "B13-SOURCEMAP" :status :rejected}
          {:design :generated-artifact-without-generator-input-digests
           :diagnostic "B13-PROVENANCE" :status :rejected}
          {:design :backend-specific-manifest-replacing-common-artifact-graph
           :diagnostic "B13-GRAPH" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b13-artifact-emission-conformance-criteria-record
          :common-manifest-schema-validation :passed
          :artifact-graph-from-source-through-backend-emission :complete
          :hash-mismatch-rejection :covered
          :source-debug-generated-origin-preservation :complete
          :evidence-checks :complete
          :runtime-provider-target-abi-checks :complete
          :reproducibility-nondeterminism-diagnostics :covered
          :release-grade-evidence-gate :blocked-development-only
          :downstream-package-tooling-conformance-consumption :complete
          :status :passed}
         :b13-diagnostic-stream diagnostic-stream
         :b13-document-results
         {:documents ["B13"]
          :task "P07-D110"
          :required-diagnostic-ids b13-document-diagnostic-ids
          :artifact-emission-input-status :complete
          :manifest-schema-status :complete
          :content-hash-status :complete
          :artifact-graph-status :complete
          :source-map-status :complete
          :provenance-status :complete
          :evidence-status :complete
          :effect-capability-status :complete
          :runtime-provider-status :complete
          :target-runtime-abi-status :complete
          :conformance-status :complete
          :reproducibility-status :complete
          :release-gate-status :complete
          :downstream-consumption-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b13-document-validate! source-path artifact-base)
        capability-proof (b13-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b13-document-file-artifact
  [path]
  (b13-document-source-artifact path (slurp path)))

(def b14-document-governing-document
  "docs/phase-07-backend-architecture/111-b14-backend-conformance-test-plan.md")

(def b14-document-diagnostic-ids
  backend-test-matrix-diagnostic-ids)

(def b14-document-override-diagnostics
  backend-test-matrix-override-diagnostics)

(defn b14-document-source-overrides
  [module]
  (backend-test-matrix-source-overrides module))

(defn b14-document-missing-policy
  [id]
  (case id
    "B14-COVERAGE" :fixture-family-and-backend-coverage
    "B14-TARGET" :target-availability-and-skip-record
    "B14-POSITIVE" :positive-lowering-or-execution-result
    "B14-NEGATIVE" :exact-negative-diagnostic-result
    "B14-DIFFERENTIAL" :differential-execution-or-semantic-comparison
    "B14-METADATA" :source-proof-safety-effect-capability-audit-metadata
    "B14-ARTIFACT" :backend-and-common-artifact-manifest-validation
    "B14-NONDETERMINISM" :recorded-or-replayed-nondeterminism
    "B14-SKIP" :explicit-supported-skip-policy
    :conformance-evidence-pack))

(defn b14-document-fail!
  [id source-path subject extra]
  (fail! id
         "B14 backend conformance test plan document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b14-backend-conformance-document
                 :stage :b14-backend-conformance-document-coverage
                 :backend (or (:backend subject)
                              :gravity.backend/conformance)
                 :profile (or (:profile subject) :hosted)
                 :target (or (:target subject) :multi-target-stage0)
                 :fixture-id (:fixture-id subject)
                 :expected-diagnostic (:expected-diagnostic subject)
                 :actual-diagnostic (:actual-diagnostic subject)
                 :missing-metadata (:missing-metadata subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (b14-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "B14 requires a backend conformance suite manifest, fixture matrix, target availability records, positive and negative checks, exact diagnostic ids, differential or semantic comparisons, metadata preservation, artifact manifest validation, nondeterminism replay records, risk coverage, and conformance evidence packs consumable by artifact emission and release review."}
                extra)))

(defn b14-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b14-document-override-diagnostics fail-kind)]
      (b14-document-fail!
       id source-path
       {:backend :gravity.backend/conformance
        :target :multi-target-stage0
        :fixture-id (str "b14-document-" (name fail-kind))
        :expected-diagnostic id
        :actual-diagnostic :missing
        :missing-metadata [fail-kind]
        :artifact-id (str "b14-document-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn b14-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b14-backend-conformance-diagnostic-stream
   :stage :b14-backend-conformance-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b14-backend-conformance-document-coverage
            :backend :gravity.backend/conformance
            :message-key (keyword "backend-conformance"
                                  (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b14-document-syntax-" index)
                      :artifact input-id}
            :profile :hosted
            :target :multi-target-stage0
            :fixture-id (str "p07-d111-" (str/lower-case id))
            :expected-diagnostic id
            :actual-diagnostic :missing
            :missing-policy (b14-document-missing-policy id)
            :missing-metadata #{:coverage :target-availability
                                :positive-result :negative-result
                                :differential-result :metadata
                                :artifact-manifest :nondeterminism
                                :skip-record :evidence-pack}
            :source-generated-origin-chain
            [:mir :domain-ir :target-lowering :backend-emission
             :artifact-emission :backend-conformance]
            :facts {:exact-diagnostic-required true
                    :metadata-preservation-required true
                    :artifact-validation-required true
                    :replay-required-for-nondeterminism true
                    :availability-record-required-for-skips true}
            :remediation [{:kind :add-required-fixture-family}
                          {:kind :record-target-availability}
                          {:kind :assert-exact-negative-diagnostic}
                          {:kind :record-or-replay-nondeterminism}
                          {:kind :attach-conformance-evidence-pack}]
            :redactions []
            :ordering-key [id :b14-backend-conformance-document-coverage
                           :multi-target-stage0]})
         b14-document-diagnostic-ids
         (range))
   :status :complete})

(defn b14-document-fixture-coverage-record
  [backend-test-artifact]
  (let [families (set (map :family (:fixture-matrix backend-test-artifact)))]
    {:artifact :gravity/b14-fixture-coverage-record
     :input-artifact (:artifact-id backend-test-artifact)
     :targets (get-in backend-test-artifact
                      [:backend-conformance-suite-manifest :targets])
     :fixture-family-count (count families)
     :fixture-families families
     :canonical-mir-families
     #{:pure-values :arithmetic :records :structs :tuples
       :tagged-unions :closures :calls :pattern-matching :loops
       :runtime-checks :allocation :regions :linear-resources
       :ownership-aliasing :ffi-host-interop
       :atomics-synchronization :source-maps}
     :domain-families
     #{:efir-domain :gpu-kernels :hardware-circuits
       :workflow-graphs :relational-queries
       :mobile-ui-boundaries :artifact-manifests
       :provenance-graphs}
     :negative-diagnostic-count
     (count (:negative-diagnostic-results backend-test-artifact))
     :positive-result-count
     (count (:positive-lowering-results backend-test-artifact))
     :semantic-comparison-count
     (count (get-in backend-test-artifact
                    [:differential-semantic-comparison-results
                     :comparisons]))
     :status :complete}))

(defn b14-document-release-review-consumption-record
  [backend-test-artifact]
  {:artifact :gravity/b14-release-review-consumption-record
   :input-artifact (:artifact-id backend-test-artifact)
   :consumers
   [{:consumer :artifact-emission
     :required-inputs [:conformance-evidence-pack
                       :artifact-manifest-validation-report
                       :metadata-preservation-report]
     :status :complete}
    {:consumer :release-review
     :required-inputs [:backend-risk-coverage-report
                       :target-availability-matrix
                       :nondeterminism-replay-record
                       :negative-diagnostic-results]
     :status :complete}]
   :release-ready? false
   :status :complete})

(defn b14-document-validate!
  [source-path artifact]
  (let [backend-test (:backend-test-matrix-artifact artifact)
        coverage (:fixture-coverage-record artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b14-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-backend-test-matrix-artifact
                 (:kind backend-test))
      (b14-document-fail! "B14-COVERAGE" source-path backend-test
                          {:missing-fields [:backend-test-matrix-artifact]}))
    (when-not (= :complete (get-in backend-test
                                   [:capability-based-proof :status]))
      (b14-document-fail! "B14-EVIDENCE" source-path backend-test
                          {:missing-fields [:backend-test-matrix-proof]}))
    (when-not (= (set backend-test-matrix-targets) (:targets coverage))
      (b14-document-fail! "B14-COVERAGE" source-path coverage
                          {:missing-fields [:targets]}))
    (when-not (= (set backend-test-matrix-fixture-families)
                 (:fixture-families coverage))
      (b14-document-fail! "B14-COVERAGE" source-path coverage
                          {:missing-fields [:fixture-families]}))
    (when-not (= :complete (get-in artifact
                                   [:target-availability-matrix :status]))
      (b14-document-fail! "B14-TARGET" source-path
                          (:target-availability-matrix artifact)
                          {:missing-fields [:target-availability]}))
    (when-not (= (count backend-test-matrix-targets)
                 (count (:positive-lowering-results artifact)))
      (b14-document-fail! "B14-POSITIVE" source-path
                          (first (:positive-lowering-results artifact))
                          {:missing-fields [:positive-lowering-results]}))
    (when-not (every? #(= :passed (:status %))
                      (:positive-lowering-results artifact))
      (b14-document-fail! "B14-POSITIVE" source-path
                          (first (:positive-lowering-results artifact))
                          {:missing-fields [:positive-status]}))
    (when-not (= (set b14-document-diagnostic-ids)
                 (set (map :diagnostic
                           (:negative-diagnostic-results artifact))))
      (b14-document-fail! "B14-NEGATIVE" source-path
                          (first (:negative-diagnostic-results artifact))
                          {:missing-fields [:negative-diagnostic-results]}))
    (when-not (= :passed (get-in artifact
                                 [:differential-semantic-comparison-results
                                  :status]))
      (b14-document-fail! "B14-DIFFERENTIAL" source-path
                          (:differential-semantic-comparison-results artifact)
                          {:missing-fields [:differential-results]}))
    (when-not (= :preserved (get-in artifact
                                    [:metadata-preservation-report :status]))
      (b14-document-fail! "B14-METADATA" source-path
                          (:metadata-preservation-report artifact)
                          {:missing-fields [:metadata-preservation]}))
    (when-not (= :valid (get-in artifact
                                [:artifact-manifest-validation-report
                                 :status]))
      (b14-document-fail! "B14-ARTIFACT" source-path
                          (:artifact-manifest-validation-report artifact)
                          {:missing-fields [:artifact-manifest-validation]}))
    (when-not (= :recorded (get-in artifact
                                   [:nondeterminism-replay-record :status]))
      (b14-document-fail! "B14-NONDETERMINISM" source-path
                          (:nondeterminism-replay-record artifact)
                          {:missing-fields [:nondeterminism-replay]}))
    (when-not (empty? (get-in artifact
                              [:target-availability-matrix
                               :unsupported-skips]))
      (b14-document-fail! "B14-SKIP" source-path
                          (:target-availability-matrix artifact)
                          {:missing-fields [:unsupported-skips]}))
    (when-not (= :complete (get-in artifact
                                   [:conformance-evidence-pack :status]))
      (b14-document-fail! "B14-EVIDENCE" source-path
                          (:conformance-evidence-pack artifact)
                          {:missing-fields [:conformance-evidence-pack]}))
    (when-not (= :complete (get-in artifact
                                   [:release-review-consumption-record
                                    :status]))
      (b14-document-fail! "B14-EVIDENCE" source-path
                          (:release-review-consumption-record artifact)
                          {:missing-fields [:release-review-consumption]}))
    (when-not (= :passed (get-in artifact
                                 [:conformance-criteria-record :status]))
      (b14-document-fail! "B14-COVERAGE" source-path
                          (:conformance-criteria-record artifact)
                          {:missing-fields [:conformance-criteria-record]}))
    (when-not (= (set b14-document-diagnostic-ids) diagnostics)
      (b14-document-fail! "B14-NEGATIVE" source-path
                          (:b14-diagnostic-stream artifact)
                          {:missing-fields [:b14-diagnostics]})))
  :complete)

(defn b14-document-capability-proof
  [artifact]
  (let [coverage (:fixture-coverage-record artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b14-diagnostic-stream
                                       :diagnostics])))]
    {:backend-test-matrix-input-verified?
     (= :complete (get-in artifact
                          [:backend-test-matrix-artifact
                           :capability-based-proof :status]))
     :phase-7-backends-covered?
     (= (set backend-test-matrix-targets) (:targets coverage))
     :shared-fixture-matrix-covered?
     (= (set backend-test-matrix-fixture-families)
        (:fixture-families coverage))
     :backend-specific-positive-negative-covered?
     (and (= (count backend-test-matrix-targets)
             (count (:positive-lowering-results artifact)))
          (= (set b14-document-diagnostic-ids)
             (set (map :diagnostic
                       (:negative-diagnostic-results artifact)))))
     :exact-diagnostic-assertions-covered?
     (every? #(= :matched (:status %))
             (:negative-diagnostic-results artifact))
     :differential-or-semantic-comparison-covered?
     (= :passed (get-in artifact
                        [:differential-semantic-comparison-results
                         :status]))
     :metadata-preservation-covered?
     (= :preserved (get-in artifact
                           [:metadata-preservation-report :status]))
     :artifact-manifest-validation-covered?
     (= :valid (get-in artifact
                       [:artifact-manifest-validation-report :status]))
     :nondeterminism-replay-covered?
     (= :recorded (get-in artifact
                          [:nondeterminism-replay-record :status]))
     :target-availability-and-skips-covered?
     (and (= :complete (get-in artifact
                               [:target-availability-matrix :status]))
          (empty? (get-in artifact
                          [:target-availability-matrix
                           :unsupported-skips])))
     :evidence-pack-consumable?
     (= :complete (get-in artifact
                          [:conformance-evidence-pack :status]))
     :release-review-consumption-covered?
     (= :complete (get-in artifact
                          [:release-review-consumption-record :status]))
     :diagnostics-covered?
     (= (set b14-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn b14-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b14-document-source-overrides module)
