(defn no-runtime-manifest
  [module input-id]
  {:artifact :gravity/no-runtime-manifest
   :input-artifact input-id
   :runtime :none
   :profile (or (:profile module) :firmware)
   :target {:backend :c :platform :bare-metal}
   :startup :reset-handler
   :memory {:static :stage0-static-map
            :stack :stage0-stack-bound
            :heap :none}
   :generated-support #{:bounds-checks :numeric-checks :panic-trap-stub
                        :resource-cleanup :startup-glue
                        :static-dispatch-table :mmio-accessor}
   :linked #{}
   :delegated #{}
   :external #{:target/mmio}
   :forbidden #{:gc :scheduler :dynamic-eval :reflection :host-io
                :classloading :managed-exceptions :hidden-allocator
                :dynamic-loader :repl :host-exceptions
                :runtime-dispatch}
   :hidden-runtime-services []
   :startup-reset-record
   {:artifact :gravity/no-runtime-startup-reset-record
    :reset-vector :reset-handler
    :entry-symbol "gravity_reset"
    :initialization-order [:copy-data :zero-bss :init-stack
                           :init-static-mmio :call-main]
    :interrupt-table [{:interrupt :timer :handler :timer_tick
                       :capability :interrupt/register}
                      {:interrupt :uart :handler :uart_rx
                       :capability :hardware/mmio}]
    :calling-convention :c-freestanding
    :handoff :user-main
    :status :complete}
   :memory-map
   {:artifact :gravity/no-runtime-memory-map
    :regions [{:name :flash :start "0x00000000" :size 65536
               :permissions #{:read :execute}}
              {:name :sram :start "0x20000000" :size 16384
               :permissions #{:read :write}}
              {:name :mmio :start "0x40000000" :size 4096
               :permissions #{:read :write} :capability :hardware/mmio}]
    :alignment 4
    :status :complete}
   :section-layout
   {:artifact :gravity/no-runtime-section-layout
    :sections [{:name ".text" :region :flash :alignment 4}
               {:name ".rodata" :region :flash :alignment 4}
               {:name ".data" :region :sram :alignment 4}
               {:name ".bss" :region :sram :alignment 4}
               {:name ".stack" :region :sram :alignment 8}]
    :status :complete}
   :stack-bound-report
   {:artifact :gravity/no-runtime-stack-bound-report
    :stack-bytes 2048
    :method :conservative-static-bound
    :recursion :rejected
    :status :bounded}
   :static-allocation-report
   {:artifact :gravity/no-runtime-static-allocation-report
    :static-objects [{:symbol "gravity_uart_state" :bytes 16
                      :region :sram}
                     {:symbol "gravity_counter" :bytes 8
                      :region :sram}]
    :heap :none
    :status :complete}
   :failure-policy
   {:artifact :gravity/no-runtime-failure-policy
    :panic :trap
    :trap-symbol "gravity_trap"
    :result-errors :explicit-result
    :reset-policy :explicit-reset-record
    :hardware-signal :explicit-interrupt-record
    :status :complete}
   :forbidden-service-report
   {:artifact :gravity/no-runtime-forbidden-service-report
    :forbidden-services #{:gc :scheduler :dynamic-eval :reflection
                          :host-io :classloading :managed-exceptions
                          :hidden-allocator :dynamic-loader :repl
                          :host-exceptions :runtime-dispatch}
    :observed-hidden-services []
    :runtime-dependencies-absent? true
    :status :passed}
   :proof-record
   {:artifact :gravity/no-runtime-proof-record
    :boundedness :proved-by-static-bound
    :initialization :proved-by-startup-order
    :check-elision :not-elided-without-proof
    :heap-allocation :rejected
    :dynamic-dispatch :lowered-or-rejected
    :boot-smoke-evidence :stage0-structural-simulation
    :status :complete}
   :status :complete})

(defn runtime-capability-enforcement-table
  [input-id]
  {:artifact :gravity/runtime-capability-enforcement-table
   :input-artifact input-id
   :checks-do-not-grant-authority? true
   :rows
   [{:effect :filesystem/read
     :capability :fs/read
     :family :managed
     :status :runtime-checked
     :hook :host-fs-read-cap}
    {:effect :memory/mmio
     :capability :hardware/mmio
     :family :no-runtime
     :status :statically-declared-target-authority
     :hook :mmio-accessor-generation}
    {:effect :ai/model-call
     :capability :model/call
     :family :ai
     :status :runtime-checked
     :hook :model-provider-cap}
    {:effect :ffi/call
     :capability :ffi/c
     :family :ffi
     :status :runtime-checked
     :hook :ffi-boundary-cap}
    {:effect :runtime/observability
     :capability :observability/write
     :family :observability
     :status :runtime-checked
     :hook :observability-sink-cap}]
   :denied-ambient-authority #{:filesystem/read :network/http
                               :database/write :shell/exec :secrets/read
                               :ai/model-call :tool/call :ffi/call
                               :memory/raw}
   :status :complete})

(defn runtime-package-permission-record
  [input-id]
  {:artifact :gravity/runtime-package-permission-record
   :input-artifact input-id
   :package :gravity/runtime-stage0
   :effects {:requests #{}
             :denies #{:shell/exec :secrets/read :filesystem/write
                       :network/http :database/write :ai/model-call}}
   :capabilities {:requests #{}
                  :denies #{:shell/exec :secret/read :fs/write
                            :http/client :db/write :model/call}
                  :deployment-grants #{}}
   :runtime-handles {}
   :deployment-grants-separate? true
   :dependency-grants-authority? false
   :ambient-authority-rejected? true
   :status :complete})

(defn runtime-backend-consumption-record
  [input-id]
  {:artifact :gravity/runtime-backend-consumption-record
   :input-artifact input-id
   :consumers
   [{:consumer :backend-artifact-emission
     :requires [:runtime-manifest :service-table
                :forbidden-service-report]
     :status :complete}
    {:consumer :package-manifest
     :requires [:capability-summary :runtime-handles
                :denied-authority]
     :status :complete}
    {:consumer :conformance-suite
     :requires [:accepted-no-runtime-fixture
                :rejected-runtime-diagnostics]
     :status :complete}
    {:consumer :self-hosting-check
     :requires [:runtime-family-selection-record
                :upstream-artifact-identity]
     :status :complete}]
   :status :complete})

(defn runtime-selection-validate!
  [source-path artifact]
  (let [artifact-emission (:artifact-emission-artifact artifact)
        families (set (map :family
                           (get-in artifact
                                   [:runtime-family-selection-record
                                    :families])))
        service-table (:runtime-service-table artifact)
        no-runtime (:no-runtime-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:runtime-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-artifact-emission-artifact
                 (:kind artifact-emission))
      (runtime-selection-fail! "R1-MANIFEST" source-path artifact-emission
                               {:missing-fields [:artifact-emission-artifact]}))
    (when-not (= :complete (get-in artifact-emission
                                   [:capability-based-proof :status]))
      (runtime-selection-fail! "R1-MANIFEST" source-path artifact-emission
                               {:missing-fields [:artifact-emission-proof]}))
    (when-not (every? families
                      [:no-runtime :minimal-native :managed :distributed
                       :ai :repl])
      (runtime-selection-fail! "R1-SELECTION" source-path
                               (:runtime-family-selection-record artifact)
                               {:missing-fields [:runtime-families]}))
    (when-not (= #{:linked :generated :delegated :external :forbidden}
                 (:classification-kinds service-table))
      (runtime-selection-fail! "R1-SERVICE" source-path service-table
                               {:missing-fields [:service-classifications]}))
    (when (seq (get-in no-runtime
                       [:forbidden-service-report
                        :observed-hidden-services]))
      (runtime-selection-fail! "R1-FORBIDDEN" source-path no-runtime
                               {:missing-fields [:hidden-services]}))
    (when-not (= :complete
                 (get-in artifact
                         [:runtime-capability-enforcement-table
                          :status]))
      (runtime-selection-fail! "R1-CAPABILITY" source-path
                               (:runtime-capability-enforcement-table
                                artifact)
                               {:missing-fields [:capability-table]}))
    (when-not (= :none (:runtime no-runtime))
      (runtime-selection-fail! "R2-MANIFEST" source-path no-runtime
                               {:missing-fields [:runtime-none]}))
    (when-not (= :complete (get-in no-runtime
                                   [:startup-reset-record :status]))
      (runtime-selection-fail! "R2-STARTUP" source-path no-runtime
                               {:missing-fields [:startup-reset-record]}))
    (when-not (= :none (get-in no-runtime [:memory :heap]))
      (runtime-selection-fail! "R2-MEMORY" source-path no-runtime
                               {:missing-fields [:heap-none]}))
    (when-not (= :bounded (get-in no-runtime
                                  [:stack-bound-report :status]))
      (runtime-selection-fail! "R2-MEMORY" source-path no-runtime
                               {:missing-fields [:stack-bound-report]}))
    (when-not (contains? (:forbidden no-runtime) :runtime-dispatch)
      (runtime-selection-fail! "R2-DISPATCH" source-path no-runtime
                               {:missing-fields [:runtime-dispatch]}))
    (when-not (= :complete (get-in no-runtime [:failure-policy :status]))
      (runtime-selection-fail! "R2-FAILURE" source-path no-runtime
                               {:missing-fields [:failure-policy]}))
    (when-not (some #(= :hardware/mmio (:capability %))
                    (get-in artifact
                            [:runtime-capability-enforcement-table
                             :rows]))
      (runtime-selection-fail! "R2-CAPABILITY" source-path no-runtime
                               {:missing-fields [:target-authority]}))
    (when-not (= :complete (get-in no-runtime [:proof-record :status]))
      (runtime-selection-fail! "R2-PROOF" source-path no-runtime
                               {:missing-fields [:proof-record]}))
    (when-not (= :complete (get-in artifact
                                   [:runtime-package-permission-record
                                    :status]))
      (runtime-selection-fail! "R1-CAPABILITY" source-path
                               (:runtime-package-permission-record
                                artifact)
                               {:missing-fields [:package-permission-record]}))
    (when-not (= :complete (get-in artifact
                                   [:runtime-backend-consumption-record
                                    :status]))
      (runtime-selection-fail! "R1-MANIFEST" source-path
                               (:runtime-backend-consumption-record
                                artifact)
                               {:missing-fields [:backend-consumption]}))
    (when-not (= (set runtime-selection-diagnostic-ids) diagnostics)
      (runtime-selection-fail! "R1-MANIFEST" source-path
                               (:runtime-diagnostic-stream artifact)
                               {:missing-fields [:runtime-diagnostics]})))
  :complete)

(defn runtime-selection-capability-proof
  [artifact]
  (let [families (set (map :family
                           (get-in artifact
                                   [:runtime-family-selection-record
                                    :families])))
        no-runtime (:no-runtime-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:runtime-diagnostic-stream
                                       :diagnostics])))]
    {:artifact-emission-input-verified?
     (= :complete (get-in artifact
                          [:artifact-emission-artifact
                           :capability-based-proof :status]))
     :runtime-selection-explicit?
     (every? families [:no-runtime :minimal-native :managed :distributed
                       :ai :repl])
     :service-classification-complete?
     (= #{:linked :generated :delegated :external :forbidden}
        (get-in artifact [:runtime-service-table
                          :classification-kinds]))
     :no-runtime-absence-proven?
     (and (= :none (:runtime no-runtime))
          (empty? (:hidden-runtime-services no-runtime))
          (true? (get-in no-runtime
                         [:forbidden-service-report
                          :runtime-dependencies-absent?])))
     :forbidden-services-rejected?
     (every? (:forbidden no-runtime)
             [:gc :scheduler :dynamic-eval :reflection :host-io
              :classloading :managed-exceptions :hidden-allocator
              :dynamic-loader :repl :host-exceptions
              :runtime-dispatch])
     :startup-memory-failure-explicit?
     (and (= :complete (get-in no-runtime
                               [:startup-reset-record :status]))
          (= :complete (get-in no-runtime
                               [:section-layout :status]))
          (= :bounded (get-in no-runtime
                              [:stack-bound-report :status]))
          (= :complete (get-in no-runtime
                               [:failure-policy :status])))
     :capability-policy-closed?
     (and (= :complete (get-in artifact
                               [:runtime-capability-enforcement-table
                                :status]))
          (true? (get-in artifact
                         [:runtime-package-permission-record
                          :ambient-authority-rejected?])))
     :no-runtime-proof-record-complete?
     (= :complete (get-in no-runtime [:proof-record :status]))
     :backend-package-consumption-covered?
     (= :complete (get-in artifact
                          [:runtime-backend-consumption-record
                           :status]))
     :diagnostics-covered?
     (= (set runtime-selection-diagnostic-ids) diagnostics)
     :status :complete}))

(defn runtime-selection-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (runtime-selection-source-overrides module)
        _ (runtime-selection-validate-source-overrides! source-path
                                                        source-overrides)
        artifact-emission-artifact
        (artifact-emission-file-artifact
         runtime-selection-upstream-artifact-path)
        input-id (:artifact-id artifact-emission-artifact)
        family-selection (runtime-family-selection-record module input-id)
        service-table (runtime-service-table input-id)
        no-runtime (no-runtime-manifest module input-id)
        capability-table (runtime-capability-enforcement-table input-id)
        package-permission (runtime-package-permission-record input-id)
        backend-consumption (runtime-backend-consumption-record input-id)
        diagnostic-stream (runtime-selection-diagnostic-stream source-path
                                                               input-id)
        artifact-base
        {:kind :gravity/stage0-runtime-selection-artifact
         :task "P08-T01"
         :document-set ["R1" "R2"]
         :governing-documents runtime-selection-governing-documents
         :pass {:name :runtime-selection
                :input :backend-artifact-provenance-graph
                :output :runtime-manifest
                :requires [:profile-manifest :target-lowering-manifest
                           :effect-capability-summary :package-policy
                           :artifact-emission-provenance]
                :preserves [:source-spans :generated-origin-chain
                            :types :effects :capabilities :safety
                            :proofs :profile :target :artifact-provenance]
                :emits [:runtime-family-selection-record
                        :runtime-service-table :no-runtime-manifest
                        :runtime-capability-enforcement-table
                        :runtime-package-permission-record
                        :runtime-backend-consumption-record
                        :runtime-diagnostic-stream
                        :conformance-criteria-record]
                :rejects runtime-selection-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :artifact-emission-artifact
         (select-keys artifact-emission-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :artifact-emission-results])
         :artifact-emission-artifact-kind (:kind artifact-emission-artifact)
         :artifact-emission-artifact-hash input-id
         :upstream-artifact-source runtime-selection-upstream-artifact-path
         :runtime-family-selection-record family-selection
         :runtime-service-table service-table
         :no-runtime-manifest no-runtime
         :runtime-capability-enforcement-table capability-table
         :runtime-package-permission-record package-permission
         :runtime-backend-consumption-record backend-consumption
         :rejected-design-coverage
         [{:design :universal-hidden-runtime
           :diagnostic "R1-FORBIDDEN" :status :rejected}
          {:design :backend-artifact-assumes-unmanifested-service
           :diagnostic "R1-SERVICE" :status :rejected}
          {:design :runtime-api-bypasses-effect-capability-checks
           :diagnostic "R1-CAPABILITY" :status :rejected}
          {:design :no-runtime-hidden-allocator-gc-scheduler-reflection
           :diagnostic "R2-HIDDEN-SERVICE" :status :rejected}
          {:design :no-runtime-implicit-startup-memory-or-failure-path
           :diagnostic "R2-STARTUP" :status :rejected}
          {:design :check-elision-without-proof-on-constrained-target
           :diagnostic "R2-PROOF" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/runtime-selection-conformance-criteria-record
          :runtime-family-selection :complete
          :service-classification :complete
          :no-runtime-manifest :complete
          :startup-memory-failure-records :complete
          :forbidden-service-rejection :covered
          :capability-policy :complete
          :backend-package-conformance-consumption :complete
          :status :passed}
         :runtime-diagnostic-stream diagnostic-stream
         :runtime-selection-results
         {:documents ["R1" "R2"]
          :task "P08-T01"
          :required-diagnostic-ids runtime-selection-diagnostic-ids
          :artifact-emission-input-status :complete
          :family-selection-status :complete
          :service-table-status :complete
          :no-runtime-manifest-status :complete
          :startup-status :complete
          :memory-status :complete
          :failure-status :complete
          :forbidden-service-status :complete
          :capability-status :complete
          :package-policy-status :complete
          :backend-consumption-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (runtime-selection-validate! source-path artifact-base)
        capability-proof (runtime-selection-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn runtime-selection-file-artifact
  [path]
  (runtime-selection-source-artifact path (slurp path)))

(def minimal-native-memory-governing-documents
  ["docs/phase-08-runtime-architecture/114-r3-minimal-native-runtime-design.md"
   "docs/phase-08-runtime-architecture/116-r5-memory-runtime-design.md"
   "docs/phase-01-core-language/020-l10-memory-model-specification.md"
   "docs/phase-02-safety/031-safe2-memory-safety-model.md"
   "docs/phase-02-safety/034-safe5-linear-resource-safety.md"
   "docs/phase-08-runtime-architecture/112-r1-runtime-architecture-overview.md"])

(def minimal-native-runtime-upstream-path
  "bootstrap/clojure/fixtures/accepted/runtime-selection-no-runtime.gravity")

(def minimal-native-memory-diagnostic-ids
  ["R3-SERVICE"
   "R3-ALLOCATOR"
   "R3-PANIC"
   "R3-ATOMICS"
   "R3-FFI"
   "R3-CAPABILITY"
   "R3-DEBUG"
   "R3-MANAGED"
   "R3-MANIFEST"
   "R5-PROVIDER"
   "R5-ALLOC"
   "R5-LIFETIME"
   "R5-LINEAR"
   "R5-RAW"
   "R5-DEVICE"
   "R5-BOUNDS"
   "R5-PROOF"
   "R5-DEBUG"
   "R5-MANIFEST"])

(def minimal-native-memory-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             minimal-native-memory-diagnostic-ids)))

(defn minimal-native-memory-source-overrides
  [module]
  (get-in module [:metadata :runtime :minimal-native] {}))

(defn minimal-native-memory-missing-policy
  [id]
  (case id
    "R3-SERVICE" :declared-linked-native-service
    "R3-ALLOCATOR" :allocator-provider-matches-memory-policy
    "R3-PANIC" :explicit-panic-trap-abort-unwind-policy
    "R3-ATOMICS" :target-memory-order-and-synchronization-provider
    "R3-FFI" :ffi-boundary-metadata-preservation
    "R3-CAPABILITY" :runtime-helper-effect-authority
    "R3-DEBUG" :debug-release-behavior-and-source-maps
    "R3-MANAGED" :hidden-managed-service-rejection
    "R3-MANIFEST" :complete-minimal-native-runtime-manifest
    "R5-PROVIDER" :selected-memory-provider-manifest
    "R5-ALLOC" :allocation-profile-and-region-policy
    "R5-LIFETIME" :region-arena-lifetime-and-escape-record
    "R5-LINEAR" :linear-resource-ledger
    "R5-RAW" :raw-memory-unsafe-wrapper-audit
    "R5-DEVICE" :device-memory-transfer-synchronization-lifetime-record
    "R5-BOUNDS" :bounds-initialization-runtime-check-map
    "R5-PROOF" :runtime-check-elision-proof-agreement
    "R5-DEBUG" :debug-allocation-trace-source-provenance
    :complete-memory-runtime-manifest))

(defn minimal-native-memory-fail!
  [id source-path subject extra]
  (fail! id
         "P08 minimal native and memory runtime validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :minimal-native-memory-runtime
                 :stage :minimal-native-memory-runtime
                 :profile (or (:profile subject) :native)
                 :target (or (:target subject)
                             {:backend :llvm :platform :linux})
                 :runtime-family (or (:runtime-family subject)
                                     (if (str/starts-with? id "R5")
                                       :memory
                                       :minimal-native))
                 :service-id (:service-id subject)
                 :provider (:provider subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :allocation-id (:allocation-id subject)
                 :resource-id (:resource-id subject)
                 :proof-id (:proof-id subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (minimal-native-memory-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-T02 requires declared minimal-native services, allocator, panic, atomics, FFI, runtime checks, debug/release records, capability policy, and memory provider, lifetime, linear resource, raw/device memory, bounds, debug, and proof-elision manifests."}
                extra)))

(defn minimal-native-memory-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get minimal-native-memory-override-diagnostics fail-kind)]
      (minimal-native-memory-fail!
       id source-path
       {:service-id fail-kind
        :provider fail-kind
        :effect fail-kind
        :capability fail-kind
        :allocation-id (str "alloc-" (name fail-kind))
        :resource-id (str "resource-" (name fail-kind))
        :proof-id (str "proof-" (name fail-kind))
        :artifact-id (str "minimal-native-memory-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn minimal-native-memory-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/minimal-native-memory-diagnostic-stream
   :stage :minimal-native-memory-runtime
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :minimal-native-memory-runtime
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-minimal-native-syntax-" index)
                      :artifact input-id}
            :profile :native
            :target {:backend :llvm :platform :linux}
            :runtime-family (if (str/starts-with? id "R5")
                              :memory
                              :minimal-native)
            :service-id (case id
                          "R3-SERVICE" :startup
                          "R3-PANIC" :panic
                          "R3-ATOMICS" :atomics
                          "R3-FFI" :ffi-helper
                          "R3-DEBUG" :debug-stack
                          "R3-MANAGED" :gc
                          "R5-PROVIDER" :region-arena
                          "R5-ALLOC" :allocation
                          "R5-LINEAR" :linear-resource
                          "R5-DEVICE" :device-memory
                          :runtime-service)
            :provider (case id
                        "R3-ALLOCATOR" :allocator/region-arena
                        "R5-PROVIDER" :memory/region-arena
                        "R5-DEVICE" :memory/device
                        :stage0-runtime-provider)
            :effect (case id
                      "R3-CAPABILITY" :filesystem/read
                      "R5-ALLOC" :memory/allocate
                      "R5-RAW" :memory/raw
                      "R5-DEVICE" :memory/device-transfer
                      nil)
            :capability (case id
                          "R3-CAPABILITY" :fs/read
                          "R5-RAW" :memory/raw
                          "R5-DEVICE" :gpu/device-memory
                          nil)
            :allocation-id (str "p08-" (str/lower-case id) "-allocation")
            :resource-id (str "p08-" (str/lower-case id) "-resource")
            :proof-id (str "p08-" (str/lower-case id) "-proof")
            :missing-policy (minimal-native-memory-missing-policy id)
            :source-generated-origin-chain
            [:profile-validation :safety-analysis :runtime-selection
             :minimal-native-memory-runtime]
            :facts {:runtime-helpers-effect-checked true
                    :memory-runtime-does-not-weaken-compiler-checks true
                    :debug-release-distinction-required true
                    :proof-elision-must-match-safe15 true}
            :remediation [{:kind :declare-runtime-service}
                          {:kind :attach-provider-manifest}
                          {:kind :preserve-memory-and-resource-facts}
                          {:kind :reject-or-prove-runtime-check-elision}]
            :redactions []
            :ordering-key [id :minimal-native-memory-runtime]})
         minimal-native-memory-diagnostic-ids
         (range))
   :status :complete})

(defn minimal-native-runtime-manifest
  [input-id]
  {:artifact :gravity/minimal-native-runtime
   :input-artifact input-id
   :family :minimal-native
   :profile :native
   :target {:backend :llvm :platform :linux}
   :services {:linked #{:startup :panic :atomics :runtime-checks
                        :resource-cleanup :ffi-trampoline}
              :generated #{:bounds-check-helper :numeric-check-helper
                           :stack-probe :panic-site-table}
              :delegated #{:allocator/provider}
              :external #{}
              :forbidden #{:gc :reflection :dynamic-eval
                           :managed-exceptions :host-exceptions
                           :classloading}}
   :linked-support-objects
   [{:object "gravity_startup.o" :service :startup :status :declared}
    {:object "gravity_panic.o" :service :panic :status :declared}
    {:object "gravity_checks.o" :service :runtime-checks :status :declared}
    {:object "gravity_atomics.o" :service :atomics :status :declared}
    {:object "gravity_resources.o" :service :resource-cleanup
     :status :declared}]
   :startup-record
   {:artifact :gravity/minimal-native-startup-record
    :entry-symbol "gravity_main"
    :initialization-order [:capture-argv :init-panic-table
                           :init-region-provider :call-main
                           :run-cleanup-handlers]
    :cleanup-order [:linear-resources :arena-reset :debug-flush]
    :status :complete}
   :allocator-provider-record
   {:artifact :gravity/native-allocator-provider-record
    :provider :allocator/region-arena
    :profiles #{:native}
    :effects #{:memory/allocate :memory/release}
    :capabilities #{:memory/arena}
    :allocation-regime :alloc/region
    :layout {:alignment 16 :max-object-align 64}
    :failure :result
    :deallocation :arena-reset-or-explicit-release
    :no-allocation-regions #{:signal-handler :panic-handler}
    :unsafe-implementation-boundary :runtime-internal-unsafe-island
    :debug {:allocation-trace true}
    :status :complete}
   :panic-failure-policy
   {:artifact :gravity/minimal-native-panic-policy
    :panic :abort-with-report
    :trap :target-trap
    :result-boundary :explicit-result
    :unwind :disabled-unless-abi-declared
    :abort-symbol "gravity_abort"
    :source-map-preserved? true
    :status :complete}
   :atomic-synchronization-provider-record
   {:artifact :gravity/native-atomic-synchronization-provider
    :supported-orders [:relaxed :acquire :release :acq-rel :seq-cst]
    :unsupported-orders []
    :target-memory-model :llvm-native
    :safe8-preservation :complete
    :locks {:provider :native-mutex :requires-capability? false}
    :scheduler-hooks :not-linked-without-effect
    :status :complete}
   :ffi-helper-manifest
   {:artifact :gravity/native-ffi-helper-manifest
    :helpers [:call-trampoline :ownership-adapter :error-adapter
              :callback-lifetime-token]
    :safe7-boundary-metadata-preserved? true
    :source-map-preserved? true
    :unsafe-island-audit "R3-FFI-STAGE0"
    :status :complete}
   :runtime-check-helper-manifest
   {:artifact :gravity/native-runtime-check-helper-manifest
    :checks [{:check :bounds :failure :panic :source-map true}
             {:check :numeric :failure :result-or-panic :source-map true}
             {:check :initialization :failure :panic :source-map true}
             {:check :borrow-state :failure :panic :source-map true}]
    :proof-elision :requires-safe15-proof
    :status :complete}
   :debug-release-behavior-record
   {:artifact :gravity/native-debug-release-behavior
    :debug {:stack-traces true
            :allocation-traces true
            :check-reports true
            :authority-effects #{}}
    :release {:stack-traces :source-map-only
              :allocation-traces false
              :check-reports :redacted
              :debug-only-services-linked? false}
    :status :complete}
   :capability-enforcement-table
   {:artifact :gravity/minimal-native-capability-table
    :runtime-helpers-grant-authority? false
    :helper-effects [{:helper :debug-stack :effects #{}
                      :capabilities #{}}
                     {:helper :allocator :effects #{:memory/allocate}
                      :capabilities #{:memory/arena}}
                     {:helper :ffi-trampoline :effects #{:ffi/call}
                      :capabilities #{:ffi/c}}]
    :status :complete}
   :managed-service-rejection-record
   {:artifact :gravity/minimal-native-managed-service-rejection
    :rejected #{:gc :reflection :dynamic-eval :managed-exceptions
                :host-exceptions :classloading}
    :status :complete}
   :status :complete})

(defn memory-runtime-manifest
  [input-id]
  {:artifact :gravity/memory-runtime-manifest
   :input-artifact input-id
   :family :memory
   :provider-families
   {:no-allocation {:profiles #{:firmware :hardware :formal}
                    :runtime-checks #{}
                    :status :declared}
    :stack {:profiles #{:native :firmware :kernel}
            :runtime-checks #{:bounds :initialization}
            :status :declared}
    :ownership {:profiles #{:native :kernel}
                :runtime-checks #{:use-after-move}
                :status :declared}
    :region {:profiles #{:native :firmware :kernel}
             :runtime-checks #{:region-escape :lifetime}
             :status :declared}
    :arena {:profiles #{:native :firmware}
            :runtime-checks #{:arena-reset :provider-match}
            :status :declared}
    :gc {:profiles #{:hosted}
         :runtime-checks #{:null :bounds}
         :status :profile-restricted}
    :reference-counting {:profiles #{:native :hosted}
                         :runtime-checks #{:release-state}
                         :status :declared}
    :raw {:profiles #{:kernel :native}
          :safe-default? false
          :requires #{:unsafe-island :safe-wrapper}
          :status :audited-only}
    :foreign {:profiles #{:native :hosted}
              :runtime-checks #{:lifetime :ownership-transfer}
              :status :declared}
    :pinned {:profiles #{:native :hosted :gpu}
             :runtime-checks #{:pinned-lifetime}
             :status :declared}
    :device {:profiles #{:gpu}
             :runtime-checks #{:transfer-state :synchronization
                               :address-space}
             :status :declared}}
   :provider-selection-record
   {:artifact :gravity/memory-provider-selection-record
    :selected [:region :arena :ownership :stack]
    :active-profile :native
    :rejected [{:provider :gc :reason :native-minimal-runtime}
               {:provider :raw :reason :safe-default-forbidden}]
    :status :complete}
   :allocation-deallocation-contract
   {:artifact :gravity/allocation-deallocation-contract
    :provider :memory/region-arena
    :allocation-effects #{:memory/allocate}
    :release-effects #{:memory/release}
    :alignment 16
    :failure :result
    :deallocation :explicit-release-or-region-exit
    :allocator-identity-check :runtime-checked
    :status :complete}
   :region-arena-manifest
   {:artifact :gravity/region-arena-manifest
    :regions [{:id :request-region :lifetime :lexical
               :escape :rejected}
              {:id :scratch-arena :lifetime :bounded-call
               :escape :rejected}]
    :arena-reset :requires-no-live-borrows
    :status :complete}
   :ownership-borrow-runtime-check-map
   {:artifact :gravity/ownership-borrow-runtime-check-map
    :checks [{:check :borrow-state :when :debug-or-dynamic-boundary}
             {:check :lifetime-generation :when :runtime-handle}
             {:check :allocator-identity :when :release}]
    :compiler-facts-preserved? true
    :status :complete}
   :linear-resource-ledger
   {:artifact :gravity/linear-resource-ledger
    :resources [{:resource-id :native-file-handle
                 :provider :resource/native-file
                 :terminal-states #{:closed}
                 :normal-path :closed
                 :error-path :closed
                 :panic-path :closed
                 :cancellation-path :not-applicable}]
    :duplicated-handles []
    :unconsumed-handles []
    :status :complete}
   :raw-memory-unsafe-audit-records
   [{:artifact :gravity/raw-memory-unsafe-audit
     :operation :runtime-internal-arena-pointer
     :unsafe-island "R5-RAW-STAGE0"
     :safe-wrapper :arena/alloc
     :invariants [:aligned :provider-owned :lifetime-bounded]
     :capabilities #{:memory/raw}
     :status :audited}]
   :device-memory-provider-manifest
   {:artifact :gravity/device-memory-provider-manifest
    :address-spaces #{:global :shared :local :constant}
    :transfer-records [:host-to-device :device-to-host]
    :synchronization [:barrier :stream-event]
    :lifetime :kernel-or-explicit-buffer
    :status :complete}
   :debug-allocation-trace-schema
   {:artifact :gravity/debug-allocation-trace-schema
    :fields [:source-span :allocation-site :provider :lifetime
             :resource-id :release-site]
    :hidden-authority-effects #{}
    :source-map-preserved? true
    :status :complete}
   :runtime-check-proof-agreement
   {:artifact :gravity/runtime-check-proof-agreement
    :retained-checks #{:bounds :initialization :borrow-state
                       :allocator-identity :region-escape}
    :elided-checks [{:check :static-stack-bound
                     :proof :safe15-static-stack-proof}]
    :unproved-elisions []
    :status :complete}
   :status :complete})

(defn minimal-native-memory-validate!
  [source-path artifact]
  (let [runtime-selection (:runtime-selection-artifact artifact)
        native (:minimal-native-runtime-manifest artifact)
        memory (:memory-runtime-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:minimal-native-memory-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-runtime-selection-artifact
                 (:kind runtime-selection))
      (minimal-native-memory-fail! "R3-MANIFEST" source-path
                                   runtime-selection
                                   {:missing-fields [:runtime-selection]}))
    (when-not (= :complete (get-in runtime-selection
                                   [:capability-based-proof :status]))
      (minimal-native-memory-fail! "R3-MANIFEST" source-path
                                   runtime-selection
                                   {:missing-fields [:runtime-selection-proof]}))
    (when-not (every? (get-in native [:services :linked])
                      [:startup :panic :atomics :runtime-checks])
      (minimal-native-memory-fail! "R3-SERVICE" source-path native
                                   {:missing-fields [:linked-services]}))
    (when-not (= :complete (get-in native
                                   [:allocator-provider-record :status]))
      (minimal-native-memory-fail! "R3-ALLOCATOR" source-path native
                                   {:missing-fields [:allocator-provider]}))
    (when-not (= :complete (get-in native
                                   [:panic-failure-policy :status]))
      (minimal-native-memory-fail! "R3-PANIC" source-path native
                                   {:missing-fields [:panic-policy]}))
    (when-not (= :complete
                 (get-in native
                         [:atomic-synchronization-provider-record :status]))
      (minimal-native-memory-fail! "R3-ATOMICS" source-path native
                                   {:missing-fields [:atomics]}))
    (when-not (true? (get-in native
                             [:ffi-helper-manifest
                              :safe7-boundary-metadata-preserved?]))
      (minimal-native-memory-fail! "R3-FFI" source-path native
                                   {:missing-fields [:ffi-metadata]}))
    (when (seq (get-in native
                       [:debug-release-behavior-record
                        :debug :authority-effects]))
      (minimal-native-memory-fail! "R3-CAPABILITY" source-path native
                                   {:missing-fields [:debug-authority]}))
    (when (true? (get-in native
                         [:debug-release-behavior-record
                          :release :debug-only-services-linked?]))
      (minimal-native-memory-fail! "R3-DEBUG" source-path native
                                   {:missing-fields [:release-debug-services]}))
    (when-not (every? (get-in native
                              [:managed-service-rejection-record
                               :rejected])
                      [:gc :reflection :dynamic-eval
                       :managed-exceptions])
      (minimal-native-memory-fail! "R3-MANAGED" source-path native
                                   {:missing-fields [:managed-rejections]}))
    (when-not (= :complete (:status native))
      (minimal-native-memory-fail! "R3-MANIFEST" source-path native
                                   {:missing-fields [:native-manifest]}))
    (when-not (= :complete (get-in memory
                                   [:provider-selection-record :status]))
      (minimal-native-memory-fail! "R5-PROVIDER" source-path memory
                                   {:missing-fields [:provider-selection]}))
    (when-not (= :complete (get-in memory
                                   [:allocation-deallocation-contract
                                    :status]))
      (minimal-native-memory-fail! "R5-ALLOC" source-path memory
                                   {:missing-fields [:allocation-contract]}))
    (when-not (= :complete (get-in memory
                                   [:region-arena-manifest :status]))
      (minimal-native-memory-fail! "R5-LIFETIME" source-path memory
                                   {:missing-fields [:region-arena]}))
    (when-not (= :complete (get-in memory
                                   [:linear-resource-ledger :status]))
      (minimal-native-memory-fail! "R5-LINEAR" source-path memory
                                   {:missing-fields [:linear-ledger]}))
    (when-not (every? #(= :audited (:status %))
                      (:raw-memory-unsafe-audit-records memory))
      (minimal-native-memory-fail! "R5-RAW" source-path memory
                                   {:missing-fields [:raw-memory-audit]}))
    (when-not (= :complete (get-in memory
                                   [:device-memory-provider-manifest
                                    :status]))
      (minimal-native-memory-fail! "R5-DEVICE" source-path memory
                                   {:missing-fields [:device-memory]}))
    (when-not (= :complete (get-in memory
                                   [:ownership-borrow-runtime-check-map
                                    :status]))
      (minimal-native-memory-fail! "R5-BOUNDS" source-path memory
                                   {:missing-fields [:runtime-check-map]}))
    (when (seq (get-in memory
                       [:runtime-check-proof-agreement
                        :unproved-elisions]))
      (minimal-native-memory-fail! "R5-PROOF" source-path memory
                                   {:missing-fields [:unproved-elisions]}))
    (when-not (true? (get-in memory
                             [:debug-allocation-trace-schema
                              :source-map-preserved?]))
      (minimal-native-memory-fail! "R5-DEBUG" source-path memory
                                   {:missing-fields [:debug-source-map]}))
    (when-not (= :complete (:status memory))
      (minimal-native-memory-fail! "R5-MANIFEST" source-path memory
                                   {:missing-fields [:memory-manifest]}))
    (when-not (= (set minimal-native-memory-diagnostic-ids) diagnostics)
      (minimal-native-memory-fail! "R3-MANIFEST" source-path
                                   (:minimal-native-memory-diagnostic-stream
                                    artifact)
                                   {:missing-fields [:diagnostics]})))
  :complete)

(defn minimal-native-memory-capability-proof
  [artifact]
  (let [native (:minimal-native-runtime-manifest artifact)
        memory (:memory-runtime-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:minimal-native-memory-diagnostic-stream
                                       :diagnostics])))]
    {:runtime-selection-input-verified?
     (= :complete (get-in artifact
                          [:runtime-selection-artifact
                           :capability-based-proof :status]))
     :minimal-native-services-declared?
     (every? (get-in native [:services :linked])
             [:startup :panic :atomics :runtime-checks])
     :allocator-provider-policy-complete?
     (= :complete (get-in native [:allocator-provider-record :status]))
     :panic-failure-policy-explicit?
     (= :complete (get-in native [:panic-failure-policy :status]))
     :atomics-safe8-preserved?
     (= :complete (get-in native
                          [:atomic-synchronization-provider-record
                           :status]))
     :ffi-safe7-metadata-preserved?
     (true? (get-in native
                    [:ffi-helper-manifest
                     :safe7-boundary-metadata-preserved?]))
     :debug-release-separated?
     (false? (get-in native
                     [:debug-release-behavior-record
                      :release :debug-only-services-linked?]))
     :hidden-managed-services-rejected?
     (every? (get-in native
                     [:managed-service-rejection-record :rejected])
             [:gc :reflection :dynamic-eval :managed-exceptions])
     :memory-providers-declared?
     (every? (set (keys (:provider-families memory)))
             [:no-allocation :stack :ownership :region :arena :gc
              :reference-counting :raw :foreign :pinned :device])
     :memory_runtime_preserves_compiler_checks?
     (true? (get-in memory
                    [:ownership-borrow-runtime-check-map
                     :compiler-facts-preserved?]))
     :linear-resource-ledger-complete?
     (= :complete (get-in memory [:linear-resource-ledger :status]))
     :raw-memory-audited-only?
     (= :audited-only (get-in memory
                              [:provider-families :raw :status]))
     :device-memory-recorded?
     (= :complete (get-in memory
                          [:device-memory-provider-manifest :status]))
     :proof-elision-agrees-with-safe15?
     (empty? (get-in memory
                     [:runtime-check-proof-agreement
                      :unproved-elisions]))
     :diagnostics-covered?
     (= (set minimal-native-memory-diagnostic-ids) diagnostics)
     :status :complete}))

(defn minimal-native-memory-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (minimal-native-memory-source-overrides module)
        _ (minimal-native-memory-validate-source-overrides! source-path
                                                            source-overrides)
        runtime-selection-artifact
        (runtime-selection-file-artifact minimal-native-runtime-upstream-path)
        input-id (:artifact-id runtime-selection-artifact)
        native-manifest (minimal-native-runtime-manifest input-id)
        memory-manifest (memory-runtime-manifest input-id)
        diagnostic-stream
        (minimal-native-memory-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-minimal-native-memory-runtime-artifact
         :task "P08-T02"
         :document-set ["R3" "R5"]
         :governing-documents minimal-native-memory-governing-documents
         :pass {:name :minimal-native-memory-runtime
                :input :runtime-selection-artifact
                :output :minimal-native-memory-runtime-artifact
                :requires [:runtime-family-selection-record
                           :runtime-service-table
                           :capability-enforcement-table
                           :safety-memory-facts
                           :ownership-resource-facts]
                :preserves [:source-spans :types :effects :capabilities
                            :safety :proofs :profile :target
                            :artifact-provenance]
                :emits [:minimal-native-runtime-manifest
                        :memory-runtime-manifest
                        :minimal-native-memory-diagnostic-stream
                        :conformance-criteria-record]
                :rejects minimal-native-memory-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :runtime-selection-artifact
         (select-keys runtime-selection-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :runtime-selection-results])
         :runtime-selection-artifact-kind (:kind runtime-selection-artifact)
         :runtime-selection-artifact-hash input-id
         :upstream-artifact-source minimal-native-runtime-upstream-path
         :minimal-native-runtime-manifest native-manifest
         :memory-runtime-manifest memory-manifest
         :rejected-design-coverage
         [{:design :native-helper-silent-io
           :diagnostic "R3-CAPABILITY" :status :rejected}
          {:design :allocator-use-in-no-allocation-region
           :diagnostic "R3-ALLOCATOR" :status :rejected}
          {:design :platform-default-panic-policy
           :diagnostic "R3-PANIC" :status :rejected}
          {:design :managed-gc-reflection-dynamic-loading-in-native
           :diagnostic "R3-MANAGED" :status :rejected}
          {:design :global-allocation-model-for-every-profile
           :diagnostic "R5-PROVIDER" :status :rejected}
          {:design :raw-memory-safe-default
           :diagnostic "R5-RAW" :status :rejected}
          {:design :region-arena-escape
           :diagnostic "R5-LIFETIME" :status :rejected}
          {:design :gc-finalization-as-linear-cleanup
           :diagnostic "R5-LINEAR" :status :rejected}
          {:design :runtime-check-elision-without-proof
           :diagnostic "R5-PROOF" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/minimal-native-memory-conformance-record
          :startup-panic-allocator-atomics-ffi-check-services :complete
          :allocator-policy-acceptance-and-rejection :covered
          :panic-trap-result-boundary-fixtures :complete
          :runtime-helper-capability-checks :complete
          :debug-release-difference :complete
          :ffi-metadata-preservation :complete
          :hidden-managed-service-rejection :covered
          :memory-provider-manifests :complete
          :lifetime-region-arena-fixtures :complete
          :linear-resource-ledger :complete
          :raw-device-memory-audit_and_transfer_records :complete
          :proof-backed-runtime-check-elision :complete
          :status :passed}
         :minimal-native-memory-diagnostic-stream diagnostic-stream
         :minimal-native-memory-results
         {:documents ["R3" "R5"]
          :task "P08-T02"
          :required-diagnostic-ids minimal-native-memory-diagnostic-ids
          :runtime-selection-input-status :complete
          :native-service-status :complete
          :allocator-status :complete
          :panic-status :complete
          :atomics-status :complete
          :ffi-status :complete
          :capability-status :complete
          :debug-release-status :complete
          :managed-rejection-status :complete
          :memory-provider-status :complete
          :allocation-status :complete
          :lifetime-status :complete
          :linear-resource-status :complete
          :raw-memory-status :complete
          :device-memory-status :complete
          :bounds-check-status :complete
          :proof-elision-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (minimal-native-memory-validate! source-path artifact-base)
        capability-proof
        (minimal-native-memory-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn minimal-native-memory-file-artifact
  [path]
  (minimal-native-memory-source-artifact path (slurp path)))

(def managed-runtime-governing-documents
  ["docs/phase-08-runtime-architecture/115-r4-managed-runtime-design.md"
   "docs/phase-08-runtime-architecture/112-r1-runtime-architecture-overview.md"
   "docs/phase-08-runtime-architecture/116-r5-memory-runtime-design.md"
   "docs/phase-08-runtime-architecture/120-r9-repl-and-interactive-runtime-design.md"
   "docs/phase-08-runtime-architecture/121-r10-ffi-runtime-design.md"
   "docs/phase-08-runtime-architecture/122-r11-runtime-capability-enforcement-design.md"
   "docs/phase-08-runtime-architecture/123-r12-runtime-observability-and-diagnostics-design.md"
   "docs/phase-03-profile-system/049-p4-hosted-profile-specification.md"
   "docs/phase-03-profile-system/058-p13-profile-compatibility-and-composition.md"
   "docs/phase-07-backend-architecture/101-b4-wasm-backend-specification.md"
   "docs/phase-07-backend-architecture/102-b5-jvm-backend-specification.md"
   "docs/phase-07-backend-architecture/103-b6-javascript-typescript-backend-specification.md"])

(def managed-runtime-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-minimal-native-memory.gravity")

(def managed-runtime-diagnostic-ids
  ["R4-HOST"
   "R4-NULL"
   "R4-EXCEPTION"
   "R4-REFLECTION"
   "R4-COLLECTION"
   "R4-RESOURCE"
   "R4-SOURCEMAP"
   "R4-PROFILE"
   "R4-MANIFEST"])

(def managed-runtime-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             managed-runtime-diagnostic-ids)))

(defn managed-runtime-source-overrides
  [module]
  (get-in module [:metadata :runtime :managed] {}))

(defn managed-runtime-missing-policy
  [id]
  (case id
    "R4-HOST" :declared-host-runtime-version-module-package-system
    "R4-NULL" :checked-null-undefined-translation
    "R4-EXCEPTION" :host-exception-rejected-promise-translation
    "R4-REFLECTION" :capability-gated-reflection-dynamic-use-policy
    "R4-COLLECTION" :gravity-compatible-collection-semantics
    "R4-RESOURCE" :deterministic-linear-resource-cleanup
    "R4-SOURCEMAP" :host-to-gravity-source-debug-map
    "R4-PROFILE" :hosted-behavior-profile-facade-boundary
    :complete-managed-runtime-manifest))

(defn managed-runtime-fail!
  [id source-path subject extra]
  (fail! id
         "P08 managed host runtime validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :managed-runtime
                 :stage :managed-runtime
                 :document-id "R4"
                 :profile (or (:profile subject) :hosted)
                 :target (or (:target subject) :jvm)
                 :runtime-family :managed
                 :host-runtime (:host-runtime subject)
                 :host-symbol (:host-symbol subject)
                 :host-package (:host-package subject)
                 :gravity-type (:gravity-type subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :adapter (:adapter subject)
                 :missing-policy (managed-runtime-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-T03 requires managed host runtime manifests that declare JVM, JS, and Wasm host targets, typed adapters, checked null and exception translation, capability-gated reflection, Gravity-compatible collection semantics, deterministic linear cleanup, source maps, diagnostics, and profile leakage rejection."}
                extra)))

(defn managed-runtime-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get managed-runtime-override-diagnostics fail-kind)]
      (managed-runtime-fail!
       id source-path
       {:host-runtime fail-kind
        :host-symbol (symbol "host" (name fail-kind))
        :host-package "stage0.host"
        :gravity-type 'HostValue
        :effect fail-kind
        :capability fail-kind
        :adapter fail-kind}
       {:missing-fields [fail-kind]}))))

(defn managed-runtime-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/managed-runtime-diagnostic-stream
   :stage :managed-runtime
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :managed-runtime
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-managed-runtime-syntax-" index)
                      :artifact input-id}
            :profile (if (= "R4-PROFILE" id) :firmware :hosted)
            :target (case id
                      "R4-HOST" :jvm
                      "R4-NULL" :javascript
                      "R4-EXCEPTION" :wasm-host
                      :managed-host)
            :runtime-family :managed
            :host-runtime (case id
                            "R4-HOST" :unsupported-host
                            "R4-NULL" :javascript
                            "R4-EXCEPTION" :jvm
                            "R4-REFLECTION" :jvm
                            "R4-COLLECTION" :host-collection
                            "R4-RESOURCE" :managed-gc
                            "R4-SOURCEMAP" :generated-host-code
                            "R4-PROFILE" :hosted-service
                            :managed)
            :host-symbol (case id
                           "R4-REFLECTION" 'java.lang.Class/forName
                           "R4-NULL" 'undefined
                           "R4-EXCEPTION" 'Promise.reject
                           nil)
            :host-package (case id
                            "R4-HOST" "undeclared.host"
                            "R4-COLLECTION" "host.collections"
                            "R4-RESOURCE" "host.resources"
                            nil)
            :gravity-type (case id
                            "R4-NULL" 'Option
                            "R4-EXCEPTION" 'Result
                            "R4-COLLECTION" 'PersistentVector
                            "R4-RESOURCE" 'LinearResource
                            'ManagedHostValue)
            :effect (case id
                      "R4-EXCEPTION" :host/error
                      "R4-REFLECTION" :host/reflect
                      "R4-RESOURCE" :resource/close
                      nil)
            :capability (case id
                          "R4-REFLECTION" :host/reflection
                          "R4-RESOURCE" :resource/cleanup
                          nil)
            :adapter (case id
                       "R4-NULL" :null-option-adapter
                       "R4-EXCEPTION" :exception-result-adapter
                       "R4-REFLECTION" :reflection-capability-adapter
                       "R4-COLLECTION" :persistent-collection-adapter
                       "R4-RESOURCE" :linear-resource-cleanup-adapter
                       :managed-host-adapter)
            :missing-policy (managed-runtime-missing-policy id)
            :source-generated-origin-chain
            [:profile-validation :runtime-selection :managed-runtime]
            :facts {:hosted-convenience-not-portable-core true
                    :host-null-exceptions-translated true
                    :runtime-checks-do-not-grant-authority true
                    :host-failures-map-to-gravity-source true}
            :remediation [{:kind :declare-host-runtime-contract}
                          {:kind :add-typed-host-adapter}
                          {:kind :gate-dynamic-host-use-with-capability}
                          {:kind :reject-hosted-profile-leakage}]
            :redactions []
            :ordering-key [id :managed-runtime]})
         managed-runtime-diagnostic-ids
         (range))
   :status :complete})

(defn managed-runtime-manifest
  [module input-id]
  {:artifact :gravity/managed-runtime
   :input-artifact input-id
   :family :managed
   :profile (or (:profile module) :hosted)
   :target (or (:target module) :jvm)
   :host {:kind :multi-host
          :version "stage0-declared-range"
          :supported #{:jvm :javascript :wasm-host}
          :module-system {:jvm :classpath-module
                          :javascript :esm
                          :wasm-host :component-model}
          :package-system {:jvm :maven-coordinate
                           :javascript :npm-package
                           :wasm-host :component-package}}
   :services {:delegated #{:gc :host-exceptions :collections
                           :event-loop :host-packages}
              :linked #{:gravity-adapters :capability-checks
                        :source-map-runtime :linear-cleanup}
              :generated #{:null-wrapper :exception-wrapper
                           :host-source-map :adapter-table}
              :forbidden #{:ambient-reflection :unchecked-null
                           :unchecked-exception :gc-only-linear-cleanup
                           :hosted-leakage}}
   :interop {:nulls :option-result-or-opaque
             :undefined :option
             :exceptions :gravity-error-panic-or-effect
             :rejected-promises :result-or-effect
             :foreign-values :opaque-typed-wrapper}
   :reflection :capability-gated
   :dynamic-loading :capability-gated
   :eval :capability-gated
   :collection-semantics :gravity-compatible
   :source-maps :host-to-gravity
   :status :complete})

(defn host-runtime-target-records
  [input-id]
  [{:artifact :gravity/host-runtime-target-record
    :input-artifact input-id
    :kind :jvm
    :version ">=17"
    :module-system :classpath-or-module-path
    :package-system :maven-coordinate
    :host-exception-model :throwable
    :host-null-model :nullable-reference
    :adapter :jvm-managed-adapter
    :status :complete}
   {:artifact :gravity/host-runtime-target-record
    :input-artifact input-id
    :kind :javascript
    :version "es2022+"
    :module-system :esm
    :package-system :npm-package
    :host-exception-model :throw-or-rejected-promise
    :host-null-model :null-or-undefined
    :adapter :js-managed-adapter
    :status :complete}
   {:artifact :gravity/host-runtime-target-record
    :input-artifact input-id
    :kind :wasm-host
    :version "component-model-stage0"
    :module-system :component-import-export
    :package-system :component-package
    :host-exception-model :host-trap-or-result
    :host-null-model :nullable-reference-or-option
    :adapter :wasm-host-managed-adapter
    :status :complete}])

(defn managed-collection-implementation-manifest
  [input-id]
  {:artifact :gravity/managed-collection-implementation-manifest
   :input-artifact input-id
   :implementations [{:gravity-type 'Vector
                      :host-representation :persistent-vector
                      :equality :gravity-value-equality
                      :hashing :gravity-stable-hash
                      :mutation :persistent
                      :identity :not-observable}
                     {:gravity-type 'Map
                      :host-representation :persistent-map
                      :equality :gravity-key-value-equality
                      :hashing :gravity-stable-hash
                      :mutation :persistent
                      :identity :not-observable}
                     {:gravity-type 'HostArray
                      :host-representation :opaque-foreign-value
                      :equality :adapter-defined
                      :hashing :adapter-defined
                      :mutation :capability-gated
                      :identity :opaque}]
   :semantics-tested #{:equality :hashing :serialization
                       :mutability :identity :taint}
   :divergences []
   :status :complete})

(defn dynamic-namespace-runtime-record
  [input-id]
  {:artifact :gravity/dynamic-variable-and-namespace-runtime-record
   :input-artifact input-id
   :dynamic-vars :manifest-declared
   :thread-local-values :host-adapter-declared
   :async-context :propagated-through-adapter
   :repl-state :r9-selected-only
   :namespace-loading :capability-gated
   :hot-reload :profile-gated
   :implicit-capabilities? false
   :status :complete})

(defn exception-null-translation-map
  [input-id]
  {:artifact :gravity/exception-null-translation-map
   :input-artifact input-id
   :nulls [{:host :jvm :source :nullable-reference
            :gravity :Option :unchecked? false}
           {:host :javascript :source :undefined
            :gravity :Option :unchecked? false}
           {:host :wasm-host :source :nullable-reference
            :gravity :Result :unchecked? false}
           {:host :foreign :source :opaque-host-value
            :gravity :OpaqueForeign :unchecked? false}]
   :exceptions [{:host :jvm :source :throwable
                 :gravity-channel :error/effect
                 :effect :host/error}
                {:host :javascript :source :rejected-promise
                 :gravity-channel :Result
                 :effect :host/error}
                {:host :wasm-host :source :trap
                 :gravity-channel :panic-or-result
                 :effect :host/error}]
   :unchecked-null-or-exception? false
   :status :complete})

(defn reflection-dynamic-use-policy
  [input-id]
  {:artifact :gravity/reflection-and-dynamic-use-policy
   :input-artifact input-id
   :reflection :capability-gated
   :class-loading :capability-gated
   :method-handles :capability-gated
   :dynamic-imports :capability-gated
   :eval :capability-gated
   :package-globals :capability-gated
   :required-effects #{:host/reflect :host/dynamic-load :host/eval}
   :required-capabilities #{:host/reflection :host/dynamic-load
                            :host/eval}
   :ambient-use-allowed? false
   :status :complete})

(defn host-interop-adapter-manifest
  [input-id]
  {:artifact :gravity/host-interop-adapter-manifest
   :input-artifact input-id
   :adapters [{:adapter :jvm-managed-adapter
               :host-runtime :jvm
               :types #{:nullable-reference :throwable :class}
               :effects #{:host/error}
               :capabilities #{}
               :taint :preserved
               :error-mapping :throwable-to-gravity-error
               :source-map :jvm-bytecode-to-gravity}
              {:adapter :js-managed-adapter
               :host-runtime :javascript
               :types #{:null :undefined :promise :object}
               :effects #{:host/error :async/await}
               :capabilities #{}
               :taint :preserved
               :error-mapping :throw-or-rejected-promise-to-result
               :source-map :source-map-v3-to-gravity}
              {:adapter :wasm-host-managed-adapter
               :host-runtime :wasm-host
               :types #{:component-import :component-export :trap}
               :effects #{:host/error}
               :capabilities #{}
               :taint :preserved
               :error-mapping :trap-or-result-to-gravity
               :source-map :wasm-debug-to-gravity}
              {:adapter :reflection-capability-adapter
               :host-runtime :jvm
               :types #{:class :method-handle}
               :effects #{:host/reflect}
               :capabilities #{:host/reflection}
               :taint :preserved
               :error-mapping :reflective-error-to-result
               :source-map :reflection-site-to-gravity}]
   :all-adapters-typed? true
   :status :complete})

(defn managed-resource-cleanup-manifest
  [input-id]
  {:artifact :gravity/managed-resource-cleanup-manifest
   :input-artifact input-id
   :resources [{:resource-id :managed-file
                :host-runtime :jvm
                :gravity-type 'LinearResource
                :cleanup :deterministic-close
                :fallback :debug-finalizer-warning
                :terminal-states #{:closed}
                :gc-only? false}
               {:resource-id :managed-transaction
                :host-runtime :javascript
                :gravity-type 'LinearResource
                :cleanup :deterministic-commit-or-rollback
                :fallback :debug-leak-diagnostic
                :terminal-states #{:committed :rolled-back}
                :gc-only? false}
               {:resource-id :wasm-host-handle
                :host-runtime :wasm-host
                :gravity-type 'LinearResource
                :cleanup :explicit-resource-drop
                :fallback :debug-leak-diagnostic
                :terminal-states #{:dropped}
                :gc-only? false}]
   :linear-resources-deterministic? true
   :gc-finalization-cleanup-policy? false
   :status :complete})

(defn managed-source-debug-map
  [source-path input-id]
  {:artifact :gravity/managed-source-debug-map
   :input-artifact input-id
   :entries [{:host-runtime :jvm
              :host-frame "gravity.runtime.Managed/main"
              :gravity-source source-path
              :source-span (source-span source-path 0)
              :generated-origin-chain [:managed-runtime :jvm-lowering]}
             {:host-runtime :javascript
              :host-frame "managedRuntime.main"
              :gravity-source source-path
              :source-span (source-span source-path 1)
              :generated-origin-chain [:managed-runtime :js-lowering]}
             {:host-runtime :wasm-host
              :host-frame "managed-runtime::main"
              :gravity-source source-path
              :source-span (source-span source-path 2)
              :generated-origin-chain [:managed-runtime :wasm-host-lowering]}]
   :host-failures-map-to-gravity? true
   :generated-origin-chain-preserved? true
   :status :complete})

(defn managed-runtime-validate!
  [source-path artifact]
  (let [upstream (:minimal-native-memory-artifact artifact)
        manifest (:managed-runtime-manifest artifact)
        targets (:host-runtime-target-records artifact)
        collections (:collection-implementation-manifest artifact)
        dynamic-state (:dynamic-variable-and-namespace-runtime-record artifact)
        translation (:exception-null-translation-map artifact)
        reflection (:reflection-and-dynamic-use-policy artifact)
        interop (:host-interop-adapter-manifest artifact)
        cleanup (:resource-cleanup-manifest artifact)
        source-map (:managed-source-debug-map artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:managed-runtime-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-minimal-native-memory-runtime-artifact
                 (:kind upstream))
      (managed-runtime-fail! "R4-MANIFEST" source-path upstream
                             {:missing-fields [:minimal-native-memory-artifact]}))
    (when-not (= :complete (get-in upstream
                                   [:capability-based-proof :status]))
      (managed-runtime-fail! "R4-MANIFEST" source-path upstream
                             {:missing-fields [:upstream-proof]}))
    (when-not (= :complete (:status manifest))
      (managed-runtime-fail! "R4-MANIFEST" source-path manifest
                             {:missing-fields [:managed-runtime-manifest]}))
    (when-not (every? (set (map :kind targets))
                      [:jvm :javascript :wasm-host])
      (managed-runtime-fail! "R4-HOST" source-path manifest
                             {:missing-fields [:host-runtime-targets]}))
    (when-not (every? #(= :complete (:status %)) targets)
      (managed-runtime-fail! "R4-HOST" source-path targets
                             {:missing-fields [:target-status]}))
    (when (true? (:unchecked-null-or-exception? translation))
      (managed-runtime-fail! "R4-NULL" source-path translation
                             {:missing-fields [:checked-null-translation]}))
    (when-not (every? :gravity-channel (:exceptions translation))
      (managed-runtime-fail! "R4-EXCEPTION" source-path translation
                             {:missing-fields [:exception-translation]}))
    (when-not (and (= :capability-gated (:reflection reflection))
                   (false? (:ambient-use-allowed? reflection)))
      (managed-runtime-fail! "R4-REFLECTION" source-path reflection
                             {:missing-fields [:capability-gated-reflection]}))
    (when-not (= :complete (:status collections))
      (managed-runtime-fail! "R4-COLLECTION" source-path collections
                             {:missing-fields [:collection-manifest]}))
    (when (seq (:divergences collections))
      (managed-runtime-fail! "R4-COLLECTION" source-path collections
                             {:missing-fields [:collection-semantics]}))
    (when-not (and (true? (:linear-resources-deterministic? cleanup))
                   (false? (:gc-finalization-cleanup-policy? cleanup)))
      (managed-runtime-fail! "R4-RESOURCE" source-path cleanup
                             {:missing-fields [:deterministic-cleanup]}))
    (when-not (and (true? (:host-failures-map-to-gravity? source-map))
                   (true? (:generated-origin-chain-preserved? source-map)))
      (managed-runtime-fail! "R4-SOURCEMAP" source-path source-map
                             {:missing-fields [:host-source-map]}))
    (when-not (false? (:implicit-capabilities? dynamic-state))
      (managed-runtime-fail! "R4-PROFILE" source-path dynamic-state
                             {:missing-fields [:hosted-profile-facade]}))
    (when-not (every? (fn [adapter]
                        (and (:types adapter)
                             (:effects adapter)
                             (:capabilities adapter)
                             (:taint adapter)
                             (:error-mapping adapter)
                             (:source-map adapter)))
                      (:adapters interop))
      (managed-runtime-fail! "R4-MANIFEST" source-path interop
                             {:missing-fields [:typed-adapter-fields]}))
    (when-not (= (set managed-runtime-diagnostic-ids) diagnostics)
      (managed-runtime-fail! "R4-MANIFEST" source-path
                             (:managed-runtime-diagnostic-stream artifact)
                             {:missing-fields [:diagnostics]})))
  :complete)

(defn managed-runtime-capability-proof
  [artifact]
  (let [manifest (:managed-runtime-manifest artifact)
        targets (:host-runtime-target-records artifact)
        collections (:collection-implementation-manifest artifact)
        dynamic-state (:dynamic-variable-and-namespace-runtime-record artifact)
        translation (:exception-null-translation-map artifact)
        reflection (:reflection-and-dynamic-use-policy artifact)
        interop (:host-interop-adapter-manifest artifact)
        cleanup (:resource-cleanup-manifest artifact)
        source-map (:managed-source-debug-map artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:managed-runtime-diagnostic-stream
                                       :diagnostics])))]
    {:minimal-native-memory-input-verified?
     (= :complete (get-in artifact
                          [:minimal-native-memory-artifact
                           :capability-based-proof :status]))
     :host-runtime-targets-declared?
     (every? (set (map :kind targets)) [:jvm :javascript :wasm-host])
     :manifest-declares-host-services?
     (and (= :managed (:family manifest))
          (contains? (get-in manifest [:services :delegated]) :gc)
          (contains? (get-in manifest [:services :forbidden])
                     :ambient-reflection))
     :null-and-exception-translation-checked?
     (and (false? (:unchecked-null-or-exception? translation))
          (every? :gravity-channel (:exceptions translation)))
     :reflection-and-dynamic-use-capability-gated?
     (and (= :capability-gated (:reflection reflection))
          (false? (:ambient-use-allowed? reflection)))
     :collection-semantics-gravity-compatible?
     (and (= :complete (:status collections))
          (empty? (:divergences collections)))
     :linear-resources-deterministic?
     (and (true? (:linear-resources-deterministic? cleanup))
          (false? (:gc-finalization-cleanup-policy? cleanup)))
     :hosted_state_does_not_grant_capabilities?
     (false? (:implicit-capabilities? dynamic-state))
     :host-adapters-typed-and-mapped?
     (and (true? (:all-adapters-typed? interop))
          (every? :source-map (:adapters interop)))
     :source-debug-map-complete?
     (and (true? (:host-failures-map-to-gravity? source-map))
          (true? (:generated-origin-chain-preserved? source-map)))
     :diagnostics-covered?
     (= (set managed-runtime-diagnostic-ids) diagnostics)
     :status :complete}))

(defn managed-runtime-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (managed-runtime-source-overrides module)
        _ (managed-runtime-validate-source-overrides! source-path
                                                      source-overrides)
        upstream-artifact
        (minimal-native-memory-file-artifact managed-runtime-upstream-artifact-path)
        input-id (:artifact-id upstream-artifact)
        manifest (managed-runtime-manifest module input-id)
        target-records (host-runtime-target-records input-id)
        collections (managed-collection-implementation-manifest input-id)
        dynamic-state (dynamic-namespace-runtime-record input-id)
        translation (exception-null-translation-map input-id)
        reflection (reflection-dynamic-use-policy input-id)
        interop (host-interop-adapter-manifest input-id)
        cleanup (managed-resource-cleanup-manifest input-id)
        source-map (managed-source-debug-map source-path input-id)
        diagnostic-stream (managed-runtime-diagnostic-stream source-path
                                                            input-id)
        artifact-base
        {:kind :gravity/stage0-managed-runtime-artifact
         :task "P08-T03"
         :document-set ["R4"]
         :governing-documents managed-runtime-governing-documents
         :pass {:name :managed-runtime
                :input :minimal-native-memory-runtime-artifact
                :output :managed-runtime-artifact
                :requires [:runtime-family-selection-record
                           :memory-runtime-manifest
                           :hosted-profile-manifest
                           :hosted-backend-artifacts
                           :capability-enforcement-table]
                :preserves [:source-spans :generated-origin :types
                            :effects :capabilities :taint :errors
                            :diagnostics :profile :target
                            :artifact-provenance]
                :emits [:managed-runtime-manifest
                        :host-runtime-target-records
                        :collection-implementation-manifest
                        :dynamic-variable-and-namespace-runtime-record
                        :exception-null-translation-map
                        :reflection-and-dynamic-use-policy
                        :host-interop-adapter-manifest
                        :resource-cleanup-manifest
                        :managed-source-debug-map
                        :managed-runtime-diagnostic-stream
                        :conformance-criteria-record]
                :rejects managed-runtime-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :minimal-native-memory-artifact
         (select-keys upstream-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :minimal-native-memory-results])
         :minimal-native-memory-artifact-kind (:kind upstream-artifact)
         :minimal-native-memory-artifact-hash input-id
         :upstream-artifact-source managed-runtime-upstream-artifact-path
         :managed-runtime-manifest manifest
         :host-runtime-target-records target-records
         :collection-implementation-manifest collections
         :dynamic-variable-and-namespace-runtime-record dynamic-state
         :exception-null-translation-map translation
         :reflection-and-dynamic-use-policy reflection
         :host-interop-adapter-manifest interop
         :resource-cleanup-manifest cleanup
         :managed-source-debug-map source-map
         :rejected-design-coverage
         [{:design :undeclared-host-runtime-behavior
           :diagnostic "R4-HOST" :status :rejected}
          {:design :unchecked-host-null-or-undefined
           :diagnostic "R4-NULL" :status :rejected}
          {:design :untranslated-host-exception-or-promise
           :diagnostic "R4-EXCEPTION" :status :rejected}
          {:design :ambient-reflection-dynamic-loading-eval
           :diagnostic "R4-REFLECTION" :status :rejected}
          {:design :host-collection-semantics-drift
           :diagnostic "R4-COLLECTION" :status :rejected}
          {:design :gc-finalization-as-linear-cleanup
           :diagnostic "R4-RESOURCE" :status :rejected}
          {:design :missing-host-source-map
           :diagnostic "R4-SOURCEMAP" :status :rejected}
          {:design :hosted-behavior-leaks-to-lower-profile
           :diagnostic "R4-PROFILE" :status :rejected}
          {:design :incomplete-managed-runtime-artifact
           :diagnostic "R4-MANIFEST" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/managed-runtime-conformance-record
          :jvm-js-wasm-host-manifests :complete
          :null-undefined-exception-translation-fixtures :complete
          :reflection-dynamic-loading-acceptance-rejection :complete
          :collection-semantics-tests :complete
          :deterministic-linear-resource-cleanup :complete
          :host-source-map-diagnostics :complete
          :profile-leakage-rejection :complete
          :status :passed}
         :managed-runtime-diagnostic-stream diagnostic-stream
         :managed-runtime-results
         {:documents ["R4"]
          :task "P08-T03"
          :required-diagnostic-ids managed-runtime-diagnostic-ids
          :minimal-native-memory-input-status :complete
          :host-target-status :complete
          :manifest-status :complete
          :null-translation-status :complete
          :exception-translation-status :complete
          :reflection-policy-status :complete
          :collection-semantics-status :complete
          :resource-cleanup-status :complete
          :source-map-status :complete
          :profile-boundary-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (managed-runtime-validate! source-path artifact-base)
        capability-proof (managed-runtime-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn managed-runtime-file-artifact
  [path]
  (managed-runtime-source-artifact path (slurp path)))

