   {:artifact :gravity/runtime-decision-log
    :input-artifact input-id
    :decisions [{:action-id "model/call"
                 :principal :agent/support
                 :effect :ai/model-call
                 :capability :model/call
                 :provider :model-provider/stage0
                 :decision :grant
                 :redaction :prompt-hash-only
                 :audit :recorded}
                {:action-id "secret/read"
                 :principal :agent/support
                 :effect :secrets/read
                 :capability :secret/read
                 :provider :secret-store
                 :decision :deny
                 :redaction :secret-name-only
                 :audit :recorded}]
    :missing-required-audit []
    :status :complete}
   :delegated-handle-record
   {:artifact :gravity/delegated-handle-record
    :input-artifact input-id
    :handles [{:handle-id "model-handle/stage0"
               :grantor :deployment-policy
               :recipient :agent/support
               :allowed-effects #{:ai/model-call}
               :lifetime :session
               :revocable? true
               :scope :single-agent}]
    :unscoped-handles []
    :status :complete}
   :revocation-record
   {:artifact :gravity/revocation-record
    :input-artifact input-id
    :records [{:handle-id "model-handle/stage0"
               :revocation-supported? true
               :state :active
               :use-after-revocation? false}]
    :status :complete}
   :denial-diagnostic-record
   {:artifact :gravity/denial-diagnostic-record
    :input-artifact input-id
    :denials [{:action-id "secret/read"
               :source-span (source-span source-path 2)
               :principal :agent/support
               :effect :secrets/read
               :capability :secret/read
               :provider :secret-store
               :decision :deny
               :remediation :request-secret-grant}]
    :status :complete}
   :redaction-secret-handling-record
   {:artifact :gravity/redaction-secret-handling-record
    :input-artifact input-id
    :policies [{:category :secret
                :redaction :secret-name-only
                :logs-secret-value? false}
               {:category :prompt
                :redaction :digest-only
                :logs-secret-value? false}]
    :secret-leaks []
    :status :complete}
   :capability-conformance-evidence
   {:artifact :gravity/runtime-capability-conformance-evidence
    :input-artifact input-id
    :deny-by-default-demonstrated? true
    :grant-deny-delegate-revoke-covered? true
    :caller-tool-plugin-contracts-covered? true
    :secret-redaction-covered? true
    :deployment-policy-narrowing-covered? true
    :status :complete}})

(defn ai-repl-ffi-capability-validate!
  [source-path artifact]
  (let [upstream (:concurrency-distributed-artifact artifact)
        ai (:ai-runtime-manifest artifact)
        model (:model-call-ledger artifact)
        prompt (:prompt-provenance-digest-record artifact)
        tools (:tool-invocation-log artifact)
        output (:structured-output-validation-report artifact)
        memory (:memory-access-retention-record artifact)
        review (:policy-human-review-decision-record artifact)
        budget (:ai-budget-trace artifact)
        replay (:ai-replay-barrier-record artifact)
        repl (:repl-runtime-manifest artifact)
        session (:session-transcript artifact)
        evaluated (:evaluated-form-artifact artifact)
        invalidation (:incremental-invalidation-record artifact)
        hot-reload (:hot-reload-record artifact)
        ffi (:ffi-runtime-manifest artifact)
        binding (:binding-manifest artifact)
        layout (:abi-layout-validation-report artifact)
        wrapper (:safe-wrapper-contract artifact)
        handles (:foreign-handle-lifetime-table artifact)
        callbacks (:callback-adapter-manifest artifact)
        cap-manifest (:runtime-capability-manifest artifact)
        decision-log (:runtime-decision-log artifact)
        delegated (:delegated-handle-record artifact)
        revocation (:revocation-record artifact)
        redaction (:redaction-secret-handling-record artifact)
        conformance (:capability-conformance-evidence artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:ai-repl-ffi-capability-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-concurrency-distributed-runtime-artifact
                 (:kind upstream))
      (ai-repl-ffi-capability-fail! "R8-MANIFEST" source-path upstream
                                    {:missing-fields [:concurrency-distributed-artifact]}))
    (when-not (= :complete (get-in upstream
                                   [:capability-based-proof :status]))
      (ai-repl-ffi-capability-fail! "R8-MANIFEST" source-path upstream
                                    {:missing-fields [:upstream-proof]}))
    (when-not (= :complete (:status ai))
      (ai-repl-ffi-capability-fail! "R8-MANIFEST" source-path ai
                                    {:missing-fields [:ai-runtime]}))
    (when (seq (:missing-provider-effect-capability-schema-budget-or-replay
                model))
      (ai-repl-ffi-capability-fail! "R8-MODEL" source-path model
                                    {:missing-fields [:model-call-ledger]}))
    (when (seq (:role-policy-violations prompt))
      (ai-repl-ffi-capability-fail! "R8-PROMPT" source-path prompt
                                    {:missing-fields [:prompt-policy]}))
    (when (seq (:effects-outside-grants tools))
      (ai-repl-ffi-capability-fail! "R8-TOOL" source-path tools
                                    {:missing-fields [:tool-grants]}))
    (when (seq (:unvalidated-trusted-sink-flows output))
      (ai-repl-ffi-capability-fail! "R8-TAINT" source-path output
                                    {:missing-fields [:taint-validation]}))
    (when (seq (:secret-leaks redaction))
      (ai-repl-ffi-capability-fail! "R8-SECRET" source-path redaction
                                    {:missing-fields [:secret-redaction]}))
    (when (seq (:invalid-retention-or-privacy memory))
      (ai-repl-ffi-capability-fail! "R8-MEMORY" source-path memory
                                    {:missing-fields [:memory-policy]}))
    (when (seq (:missing-required-reviews review))
      (ai-repl-ffi-capability-fail! "R8-HUMAN-REVIEW" source-path review
                                    {:missing-fields [:human-review]}))
    (when (seq (:live-calls-in-replay replay))
      (ai-repl-ffi-capability-fail! "R8-REPLAY" source-path replay
                                    {:missing-fields [:replay-record]}))
    (when (seq (:violations budget))
      (ai-repl-ffi-capability-fail! "R8-BUDGET" source-path budget
                                    {:missing-fields [:budget]}))
    (when-not (= :compiler-checked-before-execution
                 (:generated-code-validation output))
      (ai-repl-ffi-capability-fail! "R8-GENERATED" source-path output
                                    {:missing-fields [:generated-code-gate]}))
    (when-not (= :complete (:status repl))
      (ai-repl-ffi-capability-fail! "R9-MANIFEST" source-path repl
                                    {:missing-fields [:repl-runtime]}))
    (when-not (true? (:compiler-checks-passed? evaluated))
      (ai-repl-ffi-capability-fail! "R9-CHECKS" source-path evaluated
                                    {:missing-fields [:compiler-checks]}))
    (when-not (= :complete (:status session))
      (ai-repl-ffi-capability-fail! "R9-SESSION" source-path session
                                    {:missing-fields [:session-state]}))
    (when (true? (:stale-analysis-kept? hot-reload))
      (ai-repl-ffi-capability-fail! "R9-HOT-RELOAD" source-path hot-reload
                                    {:missing-fields [:invalidation]}))
    (when-not (= :complete (:status invalidation))
      (ai-repl-ffi-capability-fail! "R9-HERMETICITY" source-path invalidation
                                    {:missing-fields [:hermetic-session-artifact]}))
    (when-not (= :complete (:status ffi))
      (ai-repl-ffi-capability-fail! "R10-MANIFEST" source-path ffi
                                    {:missing-fields [:ffi-runtime]}))
    (when-not (= :complete (:status binding))
      (ai-repl-ffi-capability-fail! "R10-BINDING" source-path binding
                                    {:missing-fields [:binding]}))
    (when (seq (:mismatches layout))
      (ai-repl-ffi-capability-fail! "R10-ABI" source-path layout
                                    {:missing-fields [:layout-validation]}))
    (when-not (= :complete (:status wrapper))
      (ai-repl-ffi-capability-fail! "R10-WRAPPER" source-path wrapper
                                    {:missing-fields [:safe-wrapper]}))
    (when (seq (:missing-lifetimes handles))
      (ai-repl-ffi-capability-fail! "R10-POINTER" source-path handles
                                    {:missing-fields [:handle-lifetime]}))
    (when (seq (:violations callbacks))
      (ai-repl-ffi-capability-fail! "R10-CALLBACK" source-path callbacks
                                    {:missing-fields [:callback-adapter]}))
    (when-not (true? (:deny-by-default? cap-manifest))
      (ai-repl-ffi-capability-fail! "R11-GRANT" source-path cap-manifest
                                    {:missing-fields [:deny-by-default]}))
    (when (seq (:missing-required-audit decision-log))
      (ai-repl-ffi-capability-fail! "R11-AUDIT" source-path decision-log
                                    {:missing-fields [:decision-log]}))
    (when (seq (:unscoped-handles delegated))
      (ai-repl-ffi-capability-fail! "R11-DELEGATE" source-path delegated
                                    {:missing-fields [:delegated-handle-scope]}))
    (when (some :use-after-revocation? (:records revocation))
      (ai-repl-ffi-capability-fail! "R11-REVOKE" source-path revocation
                                    {:missing-fields [:revocation]}))
    (when-not (= :complete (:status conformance))
      (ai-repl-ffi-capability-fail! "R11-MANIFEST" source-path conformance
                                    {:missing-fields [:capability-evidence]}))
    (when-not (= (set ai-repl-ffi-capability-diagnostic-ids) diagnostics)
      (ai-repl-ffi-capability-fail! "R11-MANIFEST" source-path
                                    (:ai-repl-ffi-capability-diagnostic-stream
                                     artifact)
                                    {:missing-fields [:diagnostics]})))
  :complete)

(defn ai-repl-ffi-capability-proof
  [artifact]
  (let [model (:model-call-ledger artifact)
        tools (:tool-invocation-log artifact)
        output (:structured-output-validation-report artifact)
        review (:policy-human-review-decision-record artifact)
        replay (:ai-replay-barrier-record artifact)
        budget (:ai-budget-trace artifact)
        evaluated (:evaluated-form-artifact artifact)
        invalidation (:incremental-invalidation-record artifact)
        hot-reload (:hot-reload-record artifact)
        binding (:binding-manifest artifact)
        layout (:abi-layout-validation-report artifact)
        handles (:foreign-handle-lifetime-table artifact)
        callbacks (:callback-adapter-manifest artifact)
        cap-manifest (:runtime-capability-manifest artifact)
        delegated (:delegated-handle-record artifact)
        redaction (:redaction-secret-handling-record artifact)
        conformance (:capability-conformance-evidence artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:ai-repl-ffi-capability-diagnostic-stream
                                       :diagnostics])))]
    {:concurrency-distributed-input-verified?
     (= :complete (get-in artifact
                          [:concurrency-distributed-artifact
                           :capability-based-proof :status]))
     :model-tool-memory-policy-complete?
     (and (empty? (:missing-provider-effect-capability-schema-budget-or-replay
                   model))
          (empty? (:effects-outside-grants tools))
          (empty? (:unvalidated-trusted-sink-flows output)))
     :human-review-replay-budget-complete?
     (and (empty? (:missing-required-reviews review))
          (empty? (:live-calls-in-replay replay))
          (empty? (:violations budget)))
     :interactive-eval-uses-normal-checks?
     (true? (:compiler-checks-passed? evaluated))
     :interactive-state-invalidation-recorded?
     (and (= :complete (:status invalidation))
          (false? (:stale-analysis-kept? hot-reload)))
     :ffi-bindings-wrappers-and_handles_safe?
     (and (= :complete (:status binding))
          (empty? (:mismatches layout))
          (empty? (:missing-lifetimes handles))
          (empty? (:violations callbacks)))
     :runtime-capabilities-deny-by-default?
     (true? (:deny-by-default? cap-manifest))
     :delegation-and-redaction-safe?
     (and (empty? (:unscoped-handles delegated))
          (empty? (:secret-leaks redaction)))
     :capability-conformance-covered?
     (= :complete (:status conformance))
     :diagnostics-covered?
     (= (set ai-repl-ffi-capability-diagnostic-ids) diagnostics)
     :status :complete}))

(defn ai-repl-ffi-capability-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (ai-repl-ffi-capability-source-overrides module)
        _ (ai-repl-ffi-capability-validate-source-overrides!
           source-path source-overrides)
        upstream-artifact
        (concurrency-distributed-file-artifact
         ai-repl-ffi-capability-upstream-artifact-path)
        input-id (:artifact-id upstream-artifact)
        repl-artifacts (repl-session-artifacts source-path input-id)
        ffi-artifacts (ffi-runtime-artifacts input-id)
        cap-artifacts (runtime-capability-artifacts source-path input-id)
        diagnostic-stream
        (ai-repl-ffi-capability-diagnostic-stream source-path input-id)
        artifact-base
        (merge
         {:kind :gravity/stage0-ai-repl-ffi-capability-runtime-artifact
          :task "P08-T05"
          :document-set ["R8" "R9" "R10" "R11"]
          :governing-documents ai-repl-ffi-capability-governing-documents
          :pass {:name :ai-repl-ffi-capability-runtime
                 :input :concurrency-distributed-runtime-artifact
                 :output :ai-repl-ffi-capability-runtime-artifact
                 :requires [:concurrency-distributed-runtime-artifact
                            :safe10-capability-policy
                            :safe11-taint-policy
                            :safe12-generated-code-gates
                            :safe13-ai-tool-policy]
                 :preserves [:source-spans :generated-origin :types
                             :effects :capabilities :taint :errors
                             :replay-records :audit-records
                             :artifact-provenance]
                 :emits [:ai-runtime-manifest :agent-runtime-state-record
                         :model-call-ledger
                         :prompt-provenance-digest-record
                         :tool-invocation-log
                         :structured-output-validation-report
                         :memory-access-retention-record
                         :policy-human-review-decision-record
                         :ai-budget-trace :ai-replay-barrier-record
                         :repl-runtime-manifest :session-transcript
                         :evaluated-form-artifact
                         :syntax-object-snapshot :macro-expansion-diff
                         :typed-core-snapshot :mir-domain-ir-snapshot
                         :repl-capability-decision-log
                         :incremental-invalidation-record
                         :hot-reload-record :ffi-runtime-manifest
                         :binding-manifest :symbol-resolution-record
                         :abi-layout-validation-report
                         :generated-adapter-artifact
                         :safe-wrapper-contract
                         :foreign-handle-lifetime-table
                         :callback-adapter-manifest
                         :ffi-unsafe-audit-record
                         :runtime-capability-manifest
                         :capability-table :principal-identity-record
                         :runtime-decision-log
                         :delegated-handle-record :revocation-record
                         :denial-diagnostic-record
                         :redaction-secret-handling-record
                         :capability-conformance-evidence
                         :ai-repl-ffi-capability-diagnostic-stream
                         :conformance-criteria-record]
                 :rejects ai-repl-ffi-capability-diagnostic-ids}
          :source-overrides source-overrides
          :module (select-keys module
                               [:module :source-path :profile :target
                                :effects :capabilities :safety :metadata])
          :concurrency-distributed-artifact
          (select-keys upstream-artifact
                       [:kind :task :artifact-id :capability-based-proof
                        :concurrency-distributed-results])
          :concurrency-distributed-artifact-kind (:kind upstream-artifact)
          :concurrency-distributed-artifact-hash input-id
          :upstream-artifact-source
          ai-repl-ffi-capability-upstream-artifact-path
          :ai-runtime-manifest (ai-runtime-manifest input-id)
          :agent-runtime-state-record (ai-runtime-state-record input-id)
          :model-call-ledger (model-call-ledger source-path input-id)
          :prompt-provenance-digest-record
          (prompt-provenance-digest-record input-id)
          :tool-invocation-log (tool-invocation-log input-id)
          :structured-output-validation-report
          (structured-output-validation-report input-id)
          :memory-access-retention-record
          (memory-access-retention-record input-id)
          :policy-human-review-decision-record
          (policy-human-review-decision-record input-id)
          :ai-budget-trace (ai-budget-trace input-id)
          :ai-replay-barrier-record (ai-replay-barrier-record input-id)
          :repl-runtime-manifest (repl-runtime-manifest input-id)
          :ffi-runtime-manifest (ffi-runtime-manifest input-id)
          :rejected-design-coverage
          (mapv (fn [id]
                  {:design (keyword (str/lower-case id))
                   :diagnostic id
                   :status :rejected})
                ai-repl-ffi-capability-diagnostic-ids)
          :conformance-criteria-record
          {:artifact :gravity/ai-repl-ffi-capability-conformance-record
           :ai-model-tool-memory-policy :complete
           :ai-human-review-replay-budget :complete
           :repl-session-and-pipeline-checks :complete
           :repl-hot-reload-and-invalidation :complete
           :ffi-binding-wrapper-handle-callback-safety :complete
           :runtime-capability-deny-delegate-revoke-audit :complete
           :secret-redaction-and-taint-policy :complete
           :status :passed}
          :ai-repl-ffi-capability-diagnostic-stream diagnostic-stream
          :ai-repl-ffi-capability-results
          {:documents ["R8" "R9" "R10" "R11"]
           :task "P08-T05"
           :required-diagnostic-ids ai-repl-ffi-capability-diagnostic-ids
           :concurrency-distributed-input-status :complete
           :ai-runtime-status :complete
           :model-ledger-status :complete
           :tool-log-status :complete
           :taint-validation-status :complete
           :human-review-status :complete
           :replay-status :complete
           :budget-status :complete
           :repl-runtime-status :complete
           :interactive-check-status :complete
           :hot-reload-status :complete
           :ffi-runtime-status :complete
           :ffi-binding-status :complete
           :ffi-wrapper-status :complete
           :ffi-callback-status :complete
           :capability-runtime-status :complete
           :delegation-status :complete
           :audit-redaction-status :complete
           :diagnostic-status :complete
           :status :complete}
          :diagnostics []}
         repl-artifacts
         ffi-artifacts
         cap-artifacts)
        _ (ai-repl-ffi-capability-validate! source-path artifact-base)
        capability-proof
        (ai-repl-ffi-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn ai-repl-ffi-capability-file-artifact
  [path]
  (ai-repl-ffi-capability-source-artifact path (slurp path)))

(def r8-document-governing-document
  "docs/phase-08-runtime-architecture/119-r8-ai-runtime-design.md")

(def r8-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-ai-repl-ffi-capability.gravity")

(def r8-document-diagnostic-ids
  ["R8-MODEL"
   "R8-PROMPT"
   "R8-TOOL"
   "R8-TAINT"
   "R8-SECRET"
   "R8-MEMORY"
   "R8-HUMAN-REVIEW"
   "R8-REPLAY"
   "R8-BUDGET"
   "R8-GENERATED"
   "R8-MANIFEST"])

(def r8-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r8-document-diagnostic-ids)))

(defn r8-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r8-document])
      (get-in module [:metadata :runtime :ai-repl-ffi])
      {}))

(defn r8-document-missing-policy
  [id]
  (case id
    "R8-MODEL" :model-provider-effect-capability-schema-budget-replay
    "R8-PROMPT" :prompt-provenance-role-policy
    "R8-TOOL" :tool-schema-capability-human-review-timeout-retry
    "R8-TAINT" :validated-model-tool-memory-output-before-trusted-sink
    "R8-SECRET" :secret-redaction-and-denial-policy
    "R8-MEMORY" :memory-retention-trust-privacy-deletion-policy
    "R8-HUMAN-REVIEW" :required-human-review-decision
    "R8-REPLAY" :recorded-model-tool-output-for-replay
    "R8-BUDGET" :ai_budget_trace_and_limits
    "R8-GENERATED" :generated_code_compiler_validation_gate
    :complete-ai-runtime-artifact))

(defn r8-document-fail!
  [id source-path subject extra]
  (fail! id
         "R8 AI runtime document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r8-ai-runtime-document
                 :stage :r8-document-coverage
                 :document-id "R8"
                 :profile (or (:profile subject) :ai)
                 :target (or (:target subject) :jvm)
                 :runtime-family :ai
                 :agent-id (:agent-id subject)
                 :model-id (:model-id subject)
                 :tool-id (:tool-id subject)
                 :prompt-role (:prompt-role subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :provider (:provider subject)
                 :policy (:policy subject)
                 :taint-category (:taint-category subject)
                 :human-review-requirement (:human-review-requirement subject)
                 :replay-mode (:replay-mode subject)
                 :redaction-status (:redaction-status subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (r8-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D119 requires AI runtime manifests, model call ledgers, prompt provenance, tool logs, structured output validation, memory retention policy, secret redaction, human review, replay barriers, budgets, generated-code compiler gates, and R8 conformance evidence."}
                extra)))

(defn r8-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r8-document-override-diagnostics fail-kind)]
      (r8-document-fail!
       id source-path
       {:agent-id "agent/failing"
        :model-id "model/failing"
        :tool-id "tool/failing"
        :prompt-role :user
        :effect fail-kind
        :capability fail-kind
        :provider fail-kind
        :policy fail-kind
        :taint-category fail-kind
        :human-review-requirement fail-kind
        :replay-mode fail-kind
        :redaction-status fail-kind
        :artifact-id (str "r8-document-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn r8-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/r8-ai-runtime-diagnostic-stream
   :stage :r8-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :r8-document-coverage
            :document-id "R8"
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-r8-document-syntax-" index)
                      :artifact input-id}
            :profile :ai
            :target :jvm
            :runtime-family :ai
            :agent-id "agent/support-stage0"
            :model-id "model/stage0"
            :tool-id (when (= "R8-TOOL" id) "tool/write-ticket")
            :prompt-role :user
            :effect (case id
                      "R8-MODEL" :ai/model-call
                      "R8-TOOL" :filesystem/write
                      "R8-HUMAN-REVIEW" :ai/human-review
                      nil)
            :capability (case id
                          "R8-MODEL" :model/call
                          "R8-TOOL" :fs/write
                          "R8-HUMAN-REVIEW" :ai/human-review
                          nil)
            :provider (case id
                        "R8-MODEL" :model-provider/stage0
                        "R8-MEMORY" :agent-memory/stage0
                        nil)
            :policy (r8-document-missing-policy id)
            :taint-category (case id
                              "R8-TAINT" :model-output
                              "R8-SECRET" :secret
                              nil)
            :human-review-requirement (case id
                                        "R8-HUMAN-REVIEW" :required
                                        "R8-TOOL" :required-for-write
                                        nil)
            :replay-mode (if (= "R8-REPLAY" id)
                           :deterministic-replay-required
                           :recorded-or-live-per-policy)
            :redaction-status (if (= "R8-SECRET" id)
                                :required
                                :not-sensitive)
            :missing-policy (r8-document-missing-policy id)
            :source-generated-origin-chain
            [:ai-repl-ffi-capability-runtime :r8-document-coverage]
            :facts {:prompts-not-authority true
                    :model-output-tainted-until-validated true
                    :live-ai-calls-rejected-during-replay true
                    :generated-code-compiler-checked true}
            :remediation [{:kind :declare-ai-runtime-manifest}
                          {:kind :attach-prompt-and-output-schema}
                          {:kind :record-tool-policy-and-human-review}
                          {:kind :reject-live-call-or-unvalidated-output}]
            :redactions []
            :ordering-key [id :r8-document-coverage]})
         r8-document-diagnostic-ids
         (range))
   :status :complete})

(defn r8-document-requirements-coverage
  [ai-artifact]
  (let [ai (:ai-runtime-manifest ai-artifact)
        state (:agent-runtime-state-record ai-artifact)
        model (:model-call-ledger ai-artifact)
        prompt (:prompt-provenance-digest-record ai-artifact)
        tool (:tool-invocation-log ai-artifact)
        output (:structured-output-validation-report ai-artifact)
        memory (:memory-access-retention-record ai-artifact)
        review (:policy-human-review-decision-record ai-artifact)
        budget (:ai-budget-trace ai-artifact)
        replay (:ai-replay-barrier-record ai-artifact)
        secret (:redaction-secret-handling-record ai-artifact)]
    {:artifact :gravity/r8-ai-runtime-requirements-coverage
     :ai-runtime-input (:artifact-id ai-artifact)
     :manifest-status (:status ai)
     :family (:family ai)
     :services (:services ai)
     :agent-state-status (:status state)
     :replay-mode (:replay-mode state)
     :model-ledger-status (:status model)
     :missing-model-fields
     (:missing-provider-effect-capability-schema-budget-or-replay model)
     :prompt-status (:status prompt)
     :role-policy-violations (:role-policy-violations prompt)
     :tool-log-status (:status tool)
     :effects-outside-grants (:effects-outside-grants tool)
     :output-validation-status (:status output)
     :unvalidated-trusted-sink-flows
     (:unvalidated-trusted-sink-flows output)
     :generated-code-validation (:generated-code-validation output)
     :memory-status (:status memory)
     :invalid-retention-or-privacy
     (:invalid-retention-or-privacy memory)
     :human-review-status (:status review)
     :missing-required-reviews (:missing-required-reviews review)
     :budget-status (:status budget)
     :budget-violations (:violations budget)
     :replay-status (:status replay)
     :live-calls-in-replay (:live-calls-in-replay replay)
     :secret-status (:status secret)
     :secret-leaks (:secret-leaks secret)
     :status :complete}))

(defn r8-document-validate!
  [source-path artifact]
  (let [ai-artifact (:ai-repl-ffi-capability-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r8-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in ai-artifact
                                   [:capability-based-proof :status]))
      (r8-document-fail! "R8-MANIFEST" source-path ai-artifact
                         {:missing-fields [:ai-runtime-proof]}))
    (when-not (and (= :complete (:manifest-status coverage))
                   (= :ai (:family coverage)))
      (r8-document-fail! "R8-MANIFEST" source-path coverage
                         {:missing-fields [:ai-runtime-manifest]}))
    (when (seq (:missing-model-fields coverage))
      (r8-document-fail! "R8-MODEL" source-path coverage
                         {:missing-fields [:model-ledger]}))
    (when (seq (:role-policy-violations coverage))
      (r8-document-fail! "R8-PROMPT" source-path coverage
                         {:missing-fields [:prompt-provenance]}))
    (when (seq (:effects-outside-grants coverage))
      (r8-document-fail! "R8-TOOL" source-path coverage
                         {:missing-fields [:tool-grants]}))
    (when (seq (:unvalidated-trusted-sink-flows coverage))
      (r8-document-fail! "R8-TAINT" source-path coverage
                         {:missing-fields [:taint-validation]}))
    (when (seq (:secret-leaks coverage))
      (r8-document-fail! "R8-SECRET" source-path coverage
                         {:missing-fields [:secret-redaction]}))
    (when (seq (:invalid-retention-or-privacy coverage))
      (r8-document-fail! "R8-MEMORY" source-path coverage
                         {:missing-fields [:memory-policy]}))
    (when (seq (:missing-required-reviews coverage))
      (r8-document-fail! "R8-HUMAN-REVIEW" source-path coverage
                         {:missing-fields [:human-review]}))
    (when (seq (:live-calls-in-replay coverage))
      (r8-document-fail! "R8-REPLAY" source-path coverage
                         {:missing-fields [:replay-barrier]}))
    (when (seq (:budget-violations coverage))
      (r8-document-fail! "R8-BUDGET" source-path coverage
                         {:missing-fields [:budget]}))
    (when-not (= :compiler-checked-before-execution
                 (:generated-code-validation coverage))
      (r8-document-fail! "R8-GENERATED" source-path coverage
                         {:missing-fields [:generated-code-check]}))
    (when-not (= (set r8-document-diagnostic-ids) diagnostics)
      (r8-document-fail! "R8-MANIFEST" source-path
                         (:r8-diagnostic-stream artifact)
                         {:missing-fields [:r8-diagnostics]})))
  :complete)

(defn r8-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r8-diagnostic-stream
                                       :diagnostics])))]
    {:ai-runtime-input-verified?
     (= :complete (get-in artifact
                          [:ai-repl-ffi-capability-artifact
                           :capability-based-proof :status]))
     :manifest-and-agent-state-covered?
     (and (= :complete (:manifest-status coverage))
          (= :complete (:agent-state-status coverage))
          (contains? (:services coverage) :ai/model-call)
          (contains? (:services coverage) :ai/tool-call)
          (contains? (:services coverage) :ai/human-review))
     :model-calls-covered?
     (and (= :complete (:model-ledger-status coverage))
          (empty? (:missing-model-fields coverage)))
     :prompt-provenance-covered?
     (and (= :complete (:prompt-status coverage))
          (empty? (:role-policy-violations coverage)))
     :tool-invocations-covered?
     (and (= :complete (:tool-log-status coverage))
          (empty? (:effects-outside-grants coverage)))
     :taint-and-output-validation-covered?
     (and (= :complete (:output-validation-status coverage))
          (empty? (:unvalidated-trusted-sink-flows coverage)))
     :secret-and-memory-policy-covered?
     (and (= :complete (:secret-status coverage))
          (empty? (:secret-leaks coverage))
          (= :complete (:memory-status coverage))
          (empty? (:invalid-retention-or-privacy coverage)))
     :human-review-covered?
     (and (= :complete (:human-review-status coverage))
          (empty? (:missing-required-reviews coverage)))
     :replay-and-budget-covered?
     (and (= :complete (:replay-status coverage))
          (empty? (:live-calls-in-replay coverage))
          (= :complete (:budget-status coverage))
          (empty? (:budget-violations coverage)))
     :generated-code-compiler-gated?
     (= :compiler-checked-before-execution
        (:generated-code-validation coverage))
     :diagnostics-covered?
     (= (set r8-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r8-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r8-document-source-overrides module)
        _ (r8-document-validate-source-overrides! source-path
                                                  source-overrides)
        ai-artifact
        (ai-repl-ffi-capability-file-artifact
         r8-document-upstream-artifact-path)
        input-id (:artifact-id ai-artifact)
        diagnostic-stream (r8-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r8-ai-runtime-document-artifact
         :task "P08-D119"
         :document-set ["R8"]
         :governing-document r8-document-governing-document
         :pass {:name :r8-ai-runtime-document-coverage
                :input :ai-repl-ffi-capability-runtime-artifact
                :output :r8-document-coverage-artifact
                :requires [:ai-runtime-manifest
                           :agent-runtime-state-record
                           :model-call-ledger
                           :prompt-provenance-digest-record
                           :tool-invocation-log
                           :structured-output-validation-report
                           :memory-access-retention-record
                           :policy-human-review-decision-record
                           :ai-budget-trace
                           :ai-replay-barrier-record
                           :redaction-secret-handling-record]
                :preserves [:agent-id :prompt-digests :schemas :effects
                            :capabilities :taint :replay-records
                            :audit-records]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r8-diagnostic-stream]
                :rejects r8-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :ai-repl-ffi-capability-artifact
         (select-keys ai-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :ai-repl-ffi-capability-results])
         :ai-repl-ffi-capability-artifact-kind (:kind ai-artifact)
         :ai-repl-ffi-capability-artifact-hash input-id
         :upstream-artifact-source r8-document-upstream-artifact-path
         :requirements-coverage
         (r8-document-requirements-coverage ai-artifact)
         :rejected-design-coverage
         [{:design :prompts_as_authority_boundaries
           :diagnostic "R8-PROMPT" :status :rejected}
          {:design :implicit_model_and_tool_grants
           :diagnostic "R8-TOOL" :status :rejected}
          {:design :model_output_trusted_without_validation
           :diagnostic "R8-TAINT" :status :rejected}
          {:design :secret_exposure_to_prompts_tools_logs_or_memory
           :diagnostic "R8-SECRET" :status :rejected}
          {:design :live_model_tool_calls_during_replay
           :diagnostic "R8-REPLAY" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r8-ai-runtime-conformance-record
          :model_call_ledgers_prompt_provenance_output_validation :complete
          :tool_invocation_logs_schema_capability_review_taint :complete
          :memory_retrieval_policy_enforcement :complete
          :secret_redaction_and_denial_fixtures :complete
          :model_tool_replay_records :complete
          :budget_enforcement :complete
          :generated_code_compiler_validation_gates :complete
          :distributed_workflow_integration :complete
          :status :passed}
         :r8-diagnostic-stream diagnostic-stream
         :r8-document-results
         {:documents ["R8"]
          :task "P08-D119"
          :required-diagnostic-ids r8-document-diagnostic-ids
          :ai-runtime-input-status :complete
          :manifest-status :complete
          :agent-state-status :complete
          :model-ledger-status :complete
          :prompt-status :complete
          :tool-log-status :complete
          :taint-validation-status :complete
          :secret-status :complete
          :memory-status :complete
          :human-review-status :complete
          :replay-status :complete
          :budget-status :complete
          :generated-code-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r8-document-validate! source-path artifact-base)
        capability-proof (r8-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r8-document-file-artifact
  [path]
  (r8-document-source-artifact path (slurp path)))

(def r9-document-governing-document
  "docs/phase-08-runtime-architecture/120-r9-repl-and-interactive-runtime-design.md")

(def r9-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-ai-repl-ffi-capability.gravity")

(def r9-document-diagnostic-ids
  ["R9-PROFILE"
   "R9-CHECKS"
   "R9-CAPABILITY"
   "R9-SESSION"
   "R9-HERMETICITY"
   "R9-HOT-RELOAD"
   "R9-DEBUG"
   "R9-AUDIT"
   "R9-MANIFEST"])

(def r9-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r9-document-diagnostic-ids)))

(defn r9-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r9-document])
      (get-in module [:metadata :runtime :ai-repl-ffi])
      {}))

(defn r9-document-missing-policy
  [id]
  (case id
    "R9-PROFILE" :interactive-runtime-profile-legality
    "R9-CHECKS" :normal-compiler-pipeline-before-evaluation
    "R9-CAPABILITY" :interactive-effect-grants
    "R9-SESSION" :tracked-session-state
    "R9-HERMETICITY" :build-affecting-session-state-artifact
    "R9-HOT-RELOAD" :stale-artifact-invalidation
    "R9-DEBUG" :debugger-capability-and-secret-policy
    "R9-AUDIT" :session-transcript-and-evaluated-form-record
    :complete-repl-runtime-artifact))

(defn r9-document-fail!
  [id source-path subject extra]
  (fail! id
         "R9 REPL and interactive runtime document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r9-repl-runtime-document
                 :stage :r9-document-coverage
                 :document-id "R9"
                 :profile (or (:profile subject) :meta)
                 :target (or (:target subject) :jvm)
                 :runtime-family :interactive
                 :session-id (:session-id subject)
                 :compiler-phase (:compiler-phase subject)
                 :capability (:capability subject)
                 :effect (:effect subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (r9-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D120 requires REPL manifests, session transcripts, evaluated-form artifacts, syntax/macro/typed/MIR snapshots, capability decisions, incremental invalidation, hot reload records, audit logs, and R9 conformance evidence."}
                extra)))

(defn r9-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r9-document-override-diagnostics fail-kind)]
      (r9-document-fail!
       id source-path
       {:session-id "session/failing"
        :compiler-phase fail-kind
        :effect fail-kind
        :capability fail-kind
        :artifact-id (str "r9-document-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn r9-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/r9-repl-runtime-diagnostic-stream
   :stage :r9-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :r9-document-coverage
            :document-id "R9"
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-r9-document-syntax-" index)
                      :artifact input-id}
            :profile :meta
            :target :jvm
            :runtime-family :interactive
            :session-id "session/stage0"
            :compiler-phase (case id
                              "R9-CHECKS" :type-check
                              "R9-HOT-RELOAD" :incremental
                              :interactive-eval)
            :effect (case id
                      "R9-CAPABILITY" :build/read-file
                      "R9-DEBUG" :debug/read-state
                      nil)
            :capability (case id
                          "R9-CAPABILITY" :build/read-file
                          "R9-DEBUG" :debug/read-state
                          nil)
            :artifact-id input-id
            :missing-policy (r9-document-missing-policy id)
            :source-generated-origin-chain
            [:ai-repl-ffi-capability-runtime :r9-document-coverage]
            :facts {:interactive-eval-uses-compiler-pipeline true
                    :session-state-is-artifact true
                    :hot-reload-invalidates-stale-artifacts true
                    :debugger-capability-checked true}
            :remediation [{:kind :declare-repl-runtime-manifest}
                          {:kind :emit-session-transcript}
                          {:kind :run-normal-compiler-checks}
                          {:kind :invalidate-stale-artifacts}]
            :redactions []
            :ordering-key [id :r9-document-coverage]})
         r9-document-diagnostic-ids
         (range))
   :status :complete})

(defn r9-document-requirements-coverage
  [ai-artifact]
  (let [manifest (:repl-runtime-manifest ai-artifact)
        transcript (:session-transcript ai-artifact)
        evaluated (:evaluated-form-artifact ai-artifact)
        syntax (:syntax-object-snapshot ai-artifact)
        macro (:macro-expansion-diff ai-artifact)
        typed (:typed-core-snapshot ai-artifact)
        mir (:mir-domain-ir-snapshot ai-artifact)
        runtime-decisions (:runtime-decision-log ai-artifact)
        repl-decisions (:repl-capability-decision-log ai-artifact)
        invalidation (:incremental-invalidation-record ai-artifact)
        hot-reload (:hot-reload-record ai-artifact)]
    {:artifact :gravity/r9-repl-runtime-requirements-coverage
     :ai-runtime-input (:artifact-id ai-artifact)
     :manifest-status (:status manifest)
     :family (:family manifest)
     :profile (:profile manifest)
     :target (:target manifest)
     :services (:services manifest)
     :session-status (:status transcript)
     :session-id (:session-id transcript)
     :evaluated-form-status (:status evaluated)
     :compiler-checks-passed? (:compiler-checks-passed? evaluated)
     :syntax-status (:status syntax)
     :source-spans-preserved? (:source-spans-preserved? syntax)
     :macro-status (:status macro)
     :hygiene-preserved? (:hygiene-preserved? macro)
     :typed-status (:status typed)
     :typed? (:typed? typed)
     :effects-checked? (:effects-checked? typed)
     :mir-status (:status mir)
     :runtime-decision-status (:status runtime-decisions)
     :missing-required-audit (:missing-required-audit runtime-decisions)
     :repl-capability-status (:status repl-decisions)
     :invalidation-status (:status invalidation)
     :invalidates (:invalidates invalidation)
     :stale-artifacts (:stale-artifacts invalidation)
     :hot-reload-status (:status hot-reload)
     :stale-analysis-kept? (:stale-analysis-kept? hot-reload)
     :status :complete}))

(defn r9-document-validate!
  [source-path artifact]
  (let [ai-artifact (:ai-repl-ffi-capability-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r9-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in ai-artifact
                                   [:capability-based-proof :status]))
      (r9-document-fail! "R9-MANIFEST" source-path ai-artifact
                         {:missing-fields [:repl-proof]}))
    (when-not (and (= :complete (:manifest-status coverage))
                   (= :interactive (:family coverage))
                   (= :meta (:profile coverage)))
      (r9-document-fail! "R9-PROFILE" source-path coverage
                         {:missing-fields [:profile-legality]}))
    (when-not (true? (:compiler-checks-passed? coverage))
      (r9-document-fail! "R9-CHECKS" source-path coverage
                         {:missing-fields [:compiler-checks]}))
    (when-not (= :complete (:repl-capability-status coverage))
      (r9-document-fail! "R9-CAPABILITY" source-path coverage
                         {:missing-fields [:capability-decisions]}))
    (when-not (= :complete (:session-status coverage))
      (r9-document-fail! "R9-SESSION" source-path coverage
                         {:missing-fields [:session-transcript]}))
    (when-not (and (= :complete (:invalidation-status coverage))
                   (contains? (set (:invalidates coverage)) :package))
      (r9-document-fail! "R9-HERMETICITY" source-path coverage
                         {:missing-fields [:build-affecting-state]}))
    (when (or (seq (:stale-artifacts coverage))
              (true? (:stale-analysis-kept? coverage)))
      (r9-document-fail! "R9-HOT-RELOAD" source-path coverage
                         {:missing-fields [:stale-artifacts]}))
    (when (seq (:missing-required-audit coverage))
      (r9-document-fail! "R9-DEBUG" source-path coverage
                         {:missing-fields [:debug-audit]}))
    (when-not (= :complete (:evaluated-form-status coverage))
      (r9-document-fail! "R9-AUDIT" source-path coverage
                         {:missing-fields [:evaluated-form-record]}))
    (when-not (= (set r9-document-diagnostic-ids) diagnostics)
      (r9-document-fail! "R9-MANIFEST" source-path
                         (:r9-diagnostic-stream artifact)
                         {:missing-fields [:r9-diagnostics]})))
  :complete)

(defn r9-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r9-diagnostic-stream
                                       :diagnostics])))]
    {:interactive-runtime-input-verified?
     (= :complete (get-in artifact
                          [:ai-repl-ffi-capability-artifact
                           :capability-based-proof :status]))
     :manifest-profile-and-target-covered?
     (and (= :complete (:manifest-status coverage))
          (= :interactive (:family coverage))
          (= :meta (:profile coverage))
          (= :jvm (:target coverage)))
     :normal-compiler-checks-covered?
     (and (true? (:compiler-checks-passed? coverage))
          (= :complete (:typed-status coverage))
          (true? (:typed? coverage))
          (true? (:effects-checked? coverage)))
     :session-and-audit-recorded?
     (and (= :complete (:session-status coverage))
          (= :complete (:evaluated-form-status coverage))
          (= :complete (:runtime-decision-status coverage))
          (empty? (:missing-required-audit coverage)))
     :inspection-snapshots-covered?
     (and (= :complete (:syntax-status coverage))
          (true? (:source-spans-preserved? coverage))
          (= :complete (:macro-status coverage))
          (true? (:hygiene-preserved? coverage))
          (= :complete (:mir-status coverage)))
     :capability-decisions-covered?
     (= :complete (:repl-capability-status coverage))
     :hermeticity-and_hot_reload_covered?
     (and (= :complete (:invalidation-status coverage))
          (contains? (set (:invalidates coverage)) :package)
          (= :complete (:hot-reload-status coverage))
          (empty? (:stale-artifacts coverage))
          (false? (:stale-analysis-kept? coverage)))
     :diagnostics-covered?
     (= (set r9-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r9-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r9-document-source-overrides module)
        _ (r9-document-validate-source-overrides! source-path
                                                  source-overrides)
        ai-artifact
        (ai-repl-ffi-capability-file-artifact
         r9-document-upstream-artifact-path)
        input-id (:artifact-id ai-artifact)
        diagnostic-stream (r9-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r9-repl-runtime-document-artifact
         :task "P08-D120"
         :document-set ["R9"]
         :governing-document r9-document-governing-document
         :pass {:name :r9-repl-runtime-document-coverage
                :input :ai-repl-ffi-capability-runtime-artifact
                :output :r9-document-coverage-artifact
                :requires [:repl-runtime-manifest
                           :session-transcript
                           :evaluated-form-artifact
                           :syntax-object-snapshot
                           :macro-expansion-diff
                           :typed-core-snapshot
                           :mir-domain-ir-snapshot
                           :runtime-decision-log
                           :repl-capability-decision-log
                           :incremental-invalidation-record
                           :hot-reload-record]
                :preserves [:session-id :source-spans :compiler-snapshots
                            :capability-decisions :audit-log
                            :invalidation-keys]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r9-diagnostic-stream]
                :rejects r9-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :ai-repl-ffi-capability-artifact
         (select-keys ai-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :ai-repl-ffi-capability-results])
         :ai-repl-ffi-capability-artifact-kind (:kind ai-artifact)
         :ai-repl-ffi-capability-artifact-hash input-id
         :upstream-artifact-source r9-document-upstream-artifact-path
         :requirements-coverage
         (r9-document-requirements-coverage ai-artifact)
         :rejected-design-coverage
         [{:design :repl_eval_bypasses_compiler_safety_checks
           :diagnostic "R9-CHECKS" :status :rejected}
          {:design :interactive_runtime_in_no_runtime_firmware_kernel_hardware
           :diagnostic "R9-PROFILE" :status :rejected}
          {:design :session_state_silently_affects_release_builds
           :diagnostic "R9-HERMETICITY" :status :rejected}
          {:design :hot_reload_keeps_stale_mir_or_backend_artifacts
           :diagnostic "R9-HOT-RELOAD" :status :rejected}
          {:design :debugger_access_bypasses_capability_secret_policy
           :diagnostic "R9-DEBUG" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r9-repl-runtime-conformance-record
          :session_manifests_and_transcripts :complete
          :evaluated_forms_use_normal_compiler_pipeline :complete
          :macro_core_mir_inspection_artifacts :complete
          :capability_checks_for_interactive_io_debug :complete
          :dynamic_eval_rejection_for_incompatible_profiles :complete
          :hermetic_non_hermetic_session_records :complete
          :hot_reload_invalidation_fixtures :complete
          :interactive_diagnostic_provenance_preserved :complete
          :status :passed}
         :r9-diagnostic-stream diagnostic-stream
         :r9-document-results
         {:documents ["R9"]
          :task "P08-D120"
          :required-diagnostic-ids r9-document-diagnostic-ids
          :interactive-runtime-input-status :complete
          :manifest-status :complete
          :session-status :complete
          :evaluated-form-status :complete
          :snapshot-status :complete
          :capability-status :complete
          :invalidation-status :complete
          :hot-reload-status :complete
          :audit-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r9-document-validate! source-path artifact-base)
        capability-proof (r9-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r9-document-file-artifact
  [path]
  (r9-document-source-artifact path (slurp path)))

(def r10-document-governing-document
  "docs/phase-08-runtime-architecture/121-r10-ffi-runtime-design.md")

(def r10-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-ai-repl-ffi-capability.gravity")

(def r10-document-diagnostic-ids
  ["R10-BINDING" "R10-ABI" "R10-WRAPPER" "R10-POINTER" "R10-NULL"
   "R10-EFFECT" "R10-CAPABILITY" "R10-CALLBACK" "R10-DYNAMIC"
   "R10-MANIFEST"])

(def r10-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r10-document-diagnostic-ids)))

(defn r10-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r10-document])
      (get-in module [:metadata :runtime :ai-repl-ffi])
      {}))

(defn r10-document-missing-policy
  [id]
  (case id
    "R10-BINDING" :complete-ffi-binding-manifest
    "R10-ABI" :abi_calling_convention_layout_symbol_evidence
    "R10-WRAPPER" :safe_wrapper_preconditions_checks_ensures
    "R10-POINTER" :foreign_pointer_handle_lifetime_ownership_policy
    "R10-NULL" :checked_foreign_nullability
    "R10-EFFECT" :foreign_effect_declaration
    "R10-CAPABILITY" :foreign_action_runtime_authority
    "R10-CALLBACK" :callback_thread_taint_error_capability_adapter
    "R10-DYNAMIC" :package_deployment_dynamic_loading_policy
    :complete-ffi-runtime-artifact))

(defn r10-document-fail!
  [id source-path subject extra]
  (fail! id
         "R10 FFI runtime document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r10-ffi-runtime-document
                 :stage :r10-document-coverage
                 :document-id "R10"
                 :profile (or (:profile subject) :hosted)
                 :target (or (:target subject) :jvm)
                 :runtime-family :ffi
                 :binding-id (:binding-id subject)
                 :foreign-symbol (:foreign-symbol subject)
                 :wrapper-id (:wrapper-id subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (r10-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D121 requires complete FFI binding, ABI/layout, wrapper, pointer/handle, nullability, effect, capability, callback, dynamic loading, unsafe audit, and R10 conformance evidence."}
                extra)))

(defn r10-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r10-document-override-diagnostics fail-kind)]
      (r10-document-fail!
       id source-path
       {:binding-id (str "binding-" (name fail-kind))
        :foreign-symbol (symbol "foreign" (name fail-kind))
        :wrapper-id (str "wrapper-" (name fail-kind))
        :effect fail-kind
        :capability fail-kind
        :artifact-id (str "r10-document-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn r10-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/r10-ffi-runtime-diagnostic-stream
   :stage :r10-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :r10-document-coverage
            :document-id "R10"
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-r10-document-syntax-" index)
                      :artifact input-id}
            :profile :hosted
            :target :jvm
            :runtime-family :ffi
            :binding-id "ffi/libc-open"
            :foreign-symbol 'libc/open
            :wrapper-id "wrapper/open"
            :effect (case id
                      "R10-EFFECT" :ffi/call
                      "R10-CAPABILITY" :memory/raw
                      nil)
            :capability (when (= "R10-CAPABILITY" id) :memory/raw)
            :missing-policy (r10-document-missing-policy id)
            :source-generated-origin-chain
            [:ai-repl-ffi-capability-runtime :r10-document-coverage]
            :facts {:foreign-apis-unsafe-by-default true
                    :safe-wrappers-required true
                    :foreign-effects-capability-checked true
                    :callbacks-adapted-through-runtime true}
            :remediation [{:kind :declare-binding}
                          {:kind :validate-abi-layout}
                          {:kind :attach-safe-wrapper-contract}
                          {:kind :record-callback-and-handle-policy}]
            :redactions []
            :ordering-key [id :r10-document-coverage]})
         r10-document-diagnostic-ids
         (range))
   :status :complete})

(defn r10-document-requirements-coverage
  [ai-artifact]
  (let [manifest (:ffi-runtime-manifest ai-artifact)
        binding (:binding-manifest ai-artifact)
        abi (:abi-layout-validation-report ai-artifact)
        wrapper (:safe-wrapper-contract ai-artifact)
        handles (:foreign-handle-lifetime-table ai-artifact)
        audit (:ffi-unsafe-audit-record ai-artifact)
        symbols (:symbol-resolution-record ai-artifact)
        adapter (:generated-adapter-artifact ai-artifact)
        callbacks (:callback-adapter-manifest ai-artifact)]
    {:artifact :gravity/r10-ffi-runtime-requirements-coverage
     :ai-runtime-input (:artifact-id ai-artifact)
     :manifest-status (:status manifest)
     :family (:family manifest)
     :services (:services manifest)
     :binding-status (:status binding)
     :binding-count (count (:bindings binding))
     :abi-status (:status abi)
     :abi-mismatches (:mismatches abi)
     :wrapper-status (:status wrapper)
     :preconditions (:preconditions wrapper)
     :runtime-checks (:runtime-checks wrapper)
     :ensures (:ensures wrapper)
     :handle-status (:status handles)
     :missing-lifetimes (:missing-lifetimes handles)
     :audit-status (:status audit)
     :audited? (:audited? audit)
     :symbol-status (:status symbols)
     :adapter-status (:status adapter)
     :adapter-validates (:validates adapter)
     :callback-status (:status callbacks)
     :callback-violations (:violations callbacks)
     :status :complete}))

(defn r10-document-validate!
  [source-path artifact]
  (let [ai-artifact (:ai-repl-ffi-capability-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r10-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in ai-artifact
                                   [:capability-based-proof :status]))
      (r10-document-fail! "R10-MANIFEST" source-path ai-artifact
                          {:missing-fields [:ffi-proof]}))
    (when-not (and (= :complete (:manifest-status coverage))
                   (= :ffi (:family coverage)))
      (r10-document-fail! "R10-MANIFEST" source-path coverage
                          {:missing-fields [:ffi-manifest]}))
    (when-not (pos? (:binding-count coverage))
      (r10-document-fail! "R10-BINDING" source-path coverage
                          {:missing-fields [:bindings]}))
    (when (seq (:abi-mismatches coverage))
      (r10-document-fail! "R10-ABI" source-path coverage
                          {:missing-fields [:abi-layout]}))
    (when-not (and (seq (:preconditions coverage))
                   (seq (:runtime-checks coverage))
                   (seq (:ensures coverage)))
      (r10-document-fail! "R10-WRAPPER" source-path coverage
                          {:missing-fields [:wrapper-contract]}))
    (when (seq (:missing-lifetimes coverage))
      (r10-document-fail! "R10-POINTER" source-path coverage
                          {:missing-fields [:handle-lifetime]}))
    (when-not (contains? (set (:adapter-validates coverage)) :nullability)
      (r10-document-fail! "R10-NULL" source-path coverage
                          {:missing-fields [:nullability]}))
    (when-not (contains? (set (:adapter-validates coverage)) :layout)
      (r10-document-fail! "R10-EFFECT" source-path coverage
                          {:missing-fields [:effect-map]}))
    (when-not (contains? (set (:adapter-validates coverage)) :capability)
      (r10-document-fail! "R10-CAPABILITY" source-path coverage
                          {:missing-fields [:capability]}))
    (when (seq (:callback-violations coverage))
      (r10-document-fail! "R10-CALLBACK" source-path coverage
                          {:missing-fields [:callback-adapter]}))
    (when-not (= :complete (:symbol-status coverage))
      (r10-document-fail! "R10-DYNAMIC" source-path coverage
                          {:missing-fields [:symbol-resolution]}))
    (when-not (= (set r10-document-diagnostic-ids) diagnostics)
      (r10-document-fail! "R10-MANIFEST" source-path
                          (:r10-diagnostic-stream artifact)
                          {:missing-fields [:r10-diagnostics]})))
  :complete)

(defn r10-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r10-diagnostic-stream
                                       :diagnostics])))]
    {:ffi-runtime-input-verified?
     (= :complete (get-in artifact
                          [:ai-repl-ffi-capability-artifact
                           :capability-based-proof :status]))
     :manifest-and-bindings-covered?
     (and (= :complete (:manifest-status coverage))
          (= :ffi (:family coverage))
          (pos? (:binding-count coverage)))
     :abi-layout-covered?
     (and (= :complete (:abi-status coverage))
          (empty? (:abi-mismatches coverage)))
     :safe-wrapper-covered?
     (and (= :complete (:wrapper-status coverage))
          (boolean (seq (:preconditions coverage)))
          (boolean (seq (:runtime-checks coverage)))
          (boolean (seq (:ensures coverage))))
     :handle-lifetime-covered?
     (and (= :complete (:handle-status coverage))
          (empty? (:missing-lifetimes coverage)))
     :adapter-null-effect-capability-covered?
     (and (= :complete (:adapter-status coverage))
          (contains? (set (:adapter-validates coverage)) :nullability)
          (contains? (set (:adapter-validates coverage)) :layout)
          (contains? (set (:adapter-validates coverage)) :capability))
     :callback-adapter-covered?
     (and (= :complete (:callback-status coverage))
          (empty? (:callback-violations coverage)))
     :dynamic-loading-policy-covered?
     (= :complete (:symbol-status coverage))
     :unsafe-audit-covered?
     (and (= :complete (:audit-status coverage))
          (true? (:audited? coverage)))
     :diagnostics-covered?
     (= (set r10-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r10-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r10-document-source-overrides module)
        _ (r10-document-validate-source-overrides! source-path
                                                   source-overrides)
        ai-artifact
        (ai-repl-ffi-capability-file-artifact
         r10-document-upstream-artifact-path)
        input-id (:artifact-id ai-artifact)
        diagnostic-stream (r10-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r10-ffi-runtime-document-artifact
         :task "P08-D121"
         :document-set ["R10"]
         :governing-document r10-document-governing-document
         :pass {:name :r10-ffi-runtime-document-coverage
                :input :ai-repl-ffi-capability-runtime-artifact
                :output :r10-document-coverage-artifact
                :requires [:ffi-runtime-manifest :binding-manifest
                           :symbol-resolution-record
                           :abi-layout-validation-report
                           :generated-adapter-artifact
                           :safe-wrapper-contract
                           :foreign-handle-lifetime-table
                           :callback-adapter-manifest
                           :ffi-unsafe-audit-record]
                :preserves [:binding-id :foreign-symbol :effects
                            :capabilities :lifetime :ownership
                            :source-diagnostics]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r10-diagnostic-stream]
                :rejects r10-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :ai-repl-ffi-capability-artifact
         (select-keys ai-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :ai-repl-ffi-capability-results])
         :ai-repl-ffi-capability-artifact-kind (:kind ai-artifact)
         :ai-repl-ffi-capability-artifact-hash input-id
         :upstream-artifact-source r10-document-upstream-artifact-path
         :requirements-coverage
         (r10-document-requirements-coverage ai-artifact)
         :rejected-design-coverage
         [{:design :raw_extern_calls_from_safe_code
           :diagnostic "R10-WRAPPER" :status :rejected}
          {:design :foreign_pointer_without_lifetime_ownership
           :diagnostic "R10-POINTER" :status :rejected}
          {:design :foreign_effect_outside_declared_capabilities
           :diagnostic "R10-CAPABILITY" :status :rejected}
          {:design :abi_assumption_without_layout_validation
           :diagnostic "R10-ABI" :status :rejected}
          {:design :callback_bypasses_scheduler_taint_error_capability
           :diagnostic "R10-CALLBACK" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r10-ffi-runtime-conformance-record
          :binding_manifests_and_symbol_resolution :complete
          :layout_validation_across_target_abis :complete
          :generated_adapter_fixtures :complete
          :safe_wrapper_acceptance_rejection :complete
          :pointer_handle_nullability_ownership_lifetime_tests :complete
          :callback_adapter_tests :complete
          :foreign_effect_capability_enforcement :complete
          :unsafe_audit_records_source_diagnostics :complete
          :status :passed}
         :r10-diagnostic-stream diagnostic-stream
         :r10-document-results
         {:documents ["R10"]
          :task "P08-D121"
          :required-diagnostic-ids r10-document-diagnostic-ids
          :ffi-runtime-input-status :complete
          :manifest-status :complete
          :binding-status :complete
          :abi-status :complete
          :wrapper-status :complete
          :handle-status :complete
          :adapter-status :complete
          :callback-status :complete
          :dynamic-policy-status :complete
          :audit-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r10-document-validate! source-path artifact-base)
        capability-proof (r10-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r10-document-file-artifact
  [path]
  (r10-document-source-artifact path (slurp path)))

(def r11-document-governing-document
  "docs/phase-08-runtime-architecture/122-r11-runtime-capability-enforcement-design.md")

(def r11-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-ai-repl-ffi-capability.gravity")

(def r11-document-diagnostic-ids
  ["R11-GRANT" "R11-AMBIENT" "R11-PRINCIPAL" "R11-DELEGATE"
   "R11-REVOKE" "R11-TOOL" "R11-SECRET" "R11-OBSERVABILITY"
   "R11-AUDIT" "R11-MANIFEST"])

(def r11-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r11-document-diagnostic-ids)))

(defn r11-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r11-document])
      (get-in module [:metadata :runtime :ai-repl-ffi])
      {}))

(defn r11-document-missing-policy
  [id]
  (case id
    "R11-GRANT" :matching_runtime_capability_grant
    "R11-AMBIENT" :ambient_authority_rejection
    "R11-PRINCIPAL" :runtime_principal_identity
    "R11-DELEGATE" :scoped_delegated_handle
    "R11-REVOKE" :revocation_record_or_supported_assumption
    "R11-TOOL" :tool_plugin_dual_contract_check
    "R11-SECRET" :secret_redaction_policy
    "R11-OBSERVABILITY" :observability_sink_grant
    "R11-AUDIT" :capability_decision_log
    :complete-runtime-capability-artifact))

(defn r11-document-fail!
  [id source-path subject extra]
  (fail! id
         "R11 runtime capability enforcement document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r11-runtime-capability-document
                 :stage :r11-document-coverage
                 :document-id "R11"
                 :profile (or (:profile subject) :ai)
                 :target (or (:target subject) :jvm)
                 :runtime-family :capability
                 :action-id (:action-id subject)
                 :principal (:principal subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :provider (:provider subject)
                 :policy (or (:policy subject)
                             (r11-document-missing-policy id))
                 :decision (:decision subject)
                 :redaction-status (:redaction-status subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (r11-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D122 requires deny-by-default runtime capability manifests, principal identity, grant/deny/delegate/revoke records, scoped handles, tool/plugin contract checks, secret redaction, observability authority, audit logs, and R11 conformance evidence."}
                extra)))

(defn r11-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r11-document-override-diagnostics fail-kind)]
      (r11-document-fail!
       id source-path
       {:action-id (str "action-" (name fail-kind))
        :principal :runtime/failing
        :effect fail-kind
        :capability fail-kind
        :provider fail-kind
        :policy fail-kind
        :decision :deny
        :redaction-status fail-kind
        :artifact-id (str "r11-document-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn r11-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/r11-runtime-capability-diagnostic-stream
   :stage :r11-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :r11-document-coverage
            :document-id "R11"
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-r11-document-syntax-" index)
                      :artifact input-id}
            :profile :ai
            :target :jvm
            :runtime-family :capability
            :action-id (case id
                         "R11-GRANT" "database/write"
                         "R11-AMBIENT" "network/http"
                         "R11-TOOL" "tool/write-ticket"
                         "R11-SECRET" "secret/read"
                         "R11-OBSERVABILITY" "observability/write"
                         (str "action/" (str/lower-case id)))
            :principal :agent/support
            :effect (case id
                      "R11-GRANT" :database/write
                      "R11-AMBIENT" :network/http
                      "R11-TOOL" :filesystem/write
                      "R11-SECRET" :secrets/read
                      "R11-OBSERVABILITY" :runtime/observability
                      nil)
            :capability (case id
                          "R11-GRANT" :db/write
                          "R11-AMBIENT" :http/client
                          "R11-TOOL" :fs/write
                          "R11-SECRET" :secret/read
                          "R11-OBSERVABILITY" :observability/write
                          nil)
            :provider (case id
                        "R11-GRANT" :db-provider
                        "R11-AMBIENT" :network-provider
                        "R11-TOOL" :tool-provider
                        "R11-SECRET" :secret-store
                        "R11-OBSERVABILITY" :local-observability
                        nil)
            :policy-source :deployment-policy
            :policy (r11-document-missing-policy id)
            :decision (case id
                        "R11-GRANT" :deny
                        "R11-AMBIENT" :deny
                        "R11-TOOL" :deny
                        "R11-SECRET" :deny
                        "R11-OBSERVABILITY" :deny
                        :deny)
            :redaction-status (case id
                                "R11-SECRET" :required
                                "R11-AUDIT" :public-safe
                                :not-sensitive)
            :missing-policy (r11-document-missing-policy id)
            :source-generated-origin-chain
            [:ai-repl-ffi-capability-runtime :r11-document-coverage]
            :facts {:runtime-checks-do-not-grant-authority true
                    :deny-by-default true
                    :delegated-handles-scoped true
                    :decision-logs-redacted true}
            :remediation [{:kind :attach-runtime-grant}
                          {:kind :reject-ambient-authority}
                          {:kind :scope-or-revoke-handle}
                          {:kind :record-redacted-decision-log}]
            :redactions []
            :ordering-key [id :r11-document-coverage]})
         r11-document-diagnostic-ids
         (range))
   :status :complete})

(defn r11-document-requirements-coverage
  [ai-artifact]
  (let [manifest (:runtime-capability-manifest ai-artifact)
        table (:capability-table ai-artifact)
        identity (:principal-identity-record ai-artifact)
        decision-log (:runtime-decision-log ai-artifact)
        delegated (:delegated-handle-record ai-artifact)
        revocation (:revocation-record ai-artifact)
        denial (:denial-diagnostic-record ai-artifact)
        redaction (:redaction-secret-handling-record ai-artifact)
        conformance (:capability-conformance-evidence ai-artifact)
        decisions (set (map :decision (:rows table)))]
    {:artifact :gravity/r11-runtime-capability-requirements-coverage
     :ai-runtime-input (:artifact-id ai-artifact)
     :manifest-status (:status manifest)
     :handles (:handles manifest)
     :manifest-decisions (:decisions manifest)
     :manifest-rejects (:rejects manifest)
     :deny-by-default? (:deny-by-default? manifest)
     :table-status (:status table)
     :table-decisions decisions
     :grant-count (count (filter #(= :grant (:decision %)) (:rows table)))
     :deny-count (count (filter #(= :deny (:decision %)) (:rows table)))
     :observability-authority?
     (boolean (some #(= :observability/write (:capability %)) (:rows table)))
     :principal-status (:status identity)
     :principal-count (count (:principals identity))
     :invalid-principals (:invalid-principals identity)
     :decision-log-status (:status decision-log)
     :decision-count (count (:decisions decision-log))
     :missing-required-audit (:missing-required-audit decision-log)
     :delegated-status (:status delegated)
     :unscoped-handles (:unscoped-handles delegated)
     :revocation-status (:status revocation)
     :use-after-revocation
     (filterv :use-after-revocation? (:records revocation))
     :denial-status (:status denial)
     :denial-count (count (:denials denial))
     :redaction-status (:status redaction)
     :secret-leaks (:secret-leaks redaction)
     :conformance-status (:status conformance)
     :deny-by-default-demonstrated?
     (:deny-by-default-demonstrated? conformance)
     :grant-deny-delegate-revoke-covered?
     (:grant-deny-delegate-revoke-covered? conformance)
     :caller-tool-plugin-contracts-covered?
     (:caller-tool-plugin-contracts-covered? conformance)
     :secret-redaction-covered?
     (:secret-redaction-covered? conformance)
     :deployment-policy-narrowing-covered?
     (:deployment-policy-narrowing-covered? conformance)
     :status :complete}))

(defn r11-document-validate!
  [source-path artifact]
  (let [ai-artifact (:ai-repl-ffi-capability-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r11-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in ai-artifact
                                   [:capability-based-proof :status]))
      (r11-document-fail! "R11-MANIFEST" source-path ai-artifact
                          {:missing-fields [:runtime-capability-proof]}))
    (when-not (and (= :complete (:manifest-status coverage))
                   (true? (:deny-by-default? coverage)))
      (r11-document-fail! "R11-MANIFEST" source-path coverage
                          {:missing-fields [:runtime-capability-manifest]}))
    (when-not (and (pos? (:grant-count coverage))
                   (pos? (:deny-count coverage)))
      (r11-document-fail! "R11-GRANT" source-path coverage
                          {:missing-fields [:grant-deny-table]}))
    (when-not (contains? (:manifest-rejects coverage) :ambient-authority)
      (r11-document-fail! "R11-AMBIENT" source-path coverage
                          {:missing-fields [:ambient-authority-rejection]}))
    (when-not (and (= :complete (:principal-status coverage))
                   (pos? (:principal-count coverage))
                   (empty? (:invalid-principals coverage)))
      (r11-document-fail! "R11-PRINCIPAL" source-path coverage
                          {:missing-fields [:principal-identity]}))
    (when-not (and (= :complete (:delegated-status coverage))
                   (empty? (:unscoped-handles coverage)))
      (r11-document-fail! "R11-DELEGATE" source-path coverage
                          {:missing-fields [:delegated-handle-scope]}))
    (when-not (and (= :complete (:revocation-status coverage))
                   (empty? (:use-after-revocation coverage)))
      (r11-document-fail! "R11-REVOKE" source-path coverage
                          {:missing-fields [:revocation-record]}))
    (when-not (true? (:caller-tool-plugin-contracts-covered? coverage))
      (r11-document-fail! "R11-TOOL" source-path coverage
                          {:missing-fields [:tool-plugin-contract]}))
    (when-not (and (= :complete (:redaction-status coverage))
                   (empty? (:secret-leaks coverage))
                   (true? (:secret-redaction-covered? coverage)))
      (r11-document-fail! "R11-SECRET" source-path coverage
                          {:missing-fields [:secret-redaction]}))
    (when-not (:observability-authority? coverage)
      (r11-document-fail! "R11-OBSERVABILITY" source-path coverage
                          {:missing-fields [:observability-authority]}))
    (when-not (and (= :complete (:decision-log-status coverage))
                   (pos? (:decision-count coverage))
                   (empty? (:missing-required-audit coverage)))
      (r11-document-fail! "R11-AUDIT" source-path coverage
                          {:missing-fields [:decision-log]}))
    (when-not (= :complete (:conformance-status coverage))
      (r11-document-fail! "R11-MANIFEST" source-path coverage
                          {:missing-fields [:conformance]}))
    (when-not (= (set r11-document-diagnostic-ids) diagnostics)
      (r11-document-fail! "R11-MANIFEST" source-path
                          (:r11-diagnostic-stream artifact)
                          {:missing-fields [:r11-diagnostics]})))
  :complete)

(defn r11-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r11-diagnostic-stream
                                       :diagnostics])))]
    {:runtime-capability-input-verified?
     (= :complete (get-in artifact
                          [:ai-repl-ffi-capability-artifact
                           :capability-based-proof :status]))
     :manifest-deny-default-covered?
     (and (= :complete (:manifest-status coverage))
          (true? (:deny-by-default? coverage)))
     :grant-deny-delegate-revoke-covered?
     (and (pos? (:grant-count coverage))
          (pos? (:deny-count coverage))
          (true? (:grant-deny-delegate-revoke-covered? coverage)))
     :principal-identity-covered?
     (and (= :complete (:principal-status coverage))
          (pos? (:principal-count coverage))
          (empty? (:invalid-principals coverage)))
     :ambient-authority-rejected?
     (contains? (:manifest-rejects coverage) :ambient-authority)
     :delegated-handle-scoped?
     (and (= :complete (:delegated-status coverage))
          (empty? (:unscoped-handles coverage)))
     :revocation-safe?
     (and (= :complete (:revocation-status coverage))
          (empty? (:use-after-revocation coverage)))
     :tool-plugin-contract-covered?
     (true? (:caller-tool-plugin-contracts-covered? coverage))
     :secret-redaction-covered?
     (and (= :complete (:redaction-status coverage))
          (empty? (:secret-leaks coverage))
          (true? (:secret-redaction-covered? coverage)))
     :observability-authority-covered?
     (:observability-authority? coverage)
     :audit-decision-log-covered?
     (and (= :complete (:decision-log-status coverage))
          (pos? (:decision-count coverage))
          (empty? (:missing-required-audit coverage)))
     :diagnostics-covered?
     (= (set r11-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r11-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r11-document-source-overrides module)
        _ (r11-document-validate-source-overrides! source-path
                                                   source-overrides)
        ai-artifact
        (ai-repl-ffi-capability-file-artifact
         r11-document-upstream-artifact-path)
        input-id (:artifact-id ai-artifact)
        diagnostic-stream (r11-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r11-runtime-capability-document-artifact
         :task "P08-D122"
         :document-set ["R11"]
         :governing-document r11-document-governing-document
         :pass {:name :r11-runtime-capability-document-coverage
                :input :ai-repl-ffi-capability-runtime-artifact
                :output :r11-document-coverage-artifact
                :requires [:runtime-capability-manifest
                           :capability-table
                           :principal-identity-record
                           :runtime-decision-log
                           :delegated-handle-record
                           :revocation-record
                           :denial-diagnostic-record
                           :redaction-secret-handling-record
                           :capability-conformance-evidence]
                :preserves [:action-id :principal :effect :capability
                            :provider :policy :decision :redaction
                            :source-diagnostics]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r11-diagnostic-stream]
                :rejects r11-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :ai-repl-ffi-capability-artifact
         (select-keys ai-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :ai-repl-ffi-capability-results])
         :ai-repl-ffi-capability-artifact-kind (:kind ai-artifact)
         :ai-repl-ffi-capability-artifact-hash input-id
         :upstream-artifact-source r11-document-upstream-artifact-path
         :requirements-coverage
         (r11-document-requirements-coverage ai-artifact)
         :rejected-design-coverage
         [{:design :runtime_ambient_authority
           :diagnostic "R11-AMBIENT" :status :rejected}
          {:design :compile_time_profile_as_deployment_authority
           :diagnostic "R11-GRANT" :status :rejected}
          {:design :unscoped_capability_handle
           :diagnostic "R11-DELEGATE" :status :rejected}
          {:design :tool_or_plugin_effect_outside_contract
           :diagnostic "R11-TOOL" :status :rejected}
          {:design :decision_log_leaks_secret_or_omits_audit
           :diagnostic "R11-AUDIT" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r11-runtime-capability-conformance-record
          :deny_by_default_behavior :complete
          :grant_deny_delegate_revoke_records :complete
          :runtime_action_coverage :complete
          :caller_tool_plugin_dual_contract_checks :complete
          :secret_redaction_and_audit_records :complete
          :deployment_policy_narrowing :complete
          :denial_diagnostic_provenance_links :complete
          :status :passed}
         :r11-diagnostic-stream diagnostic-stream
         :r11-document-results
         {:documents ["R11"]
          :task "P08-D122"
          :required-diagnostic-ids r11-document-diagnostic-ids
          :runtime-capability-input-status :complete
          :manifest-status :complete
          :table-status :complete
          :principal-status :complete
          :decision-log-status :complete
          :delegation-status :complete
          :revocation-status :complete
          :denial-status :complete
          :redaction-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r11-document-validate! source-path artifact-base)
        capability-proof (r11-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r11-document-file-artifact
  [path]
  (r11-document-source-artifact path (slurp path)))

(def runtime-observability-governing-documents
  ["docs/phase-08-runtime-architecture/123-r12-runtime-observability-and-diagnostics-design.md"
   "docs/phase-08-runtime-architecture/112-r1-runtime-architecture-overview.md"
   "docs/phase-08-runtime-architecture/122-r11-runtime-capability-enforcement-design.md"
   "docs/phase-07-backend-architecture/110-b13-artifact-emission-specification.md"
   "docs/phase-06-compiler-architecture/092-c15-diagnostics-and-error-reporting.md"
   "docs/phase-02-safety/039-safe10-capability-security-model.md"
   "docs/phase-02-safety/040-safe11-taint-tracking-and-input-safety.md"
   "docs/phase-02-safety/042-safe13-ai-tool-safety.md"])

(def runtime-observability-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-ai-repl-ffi-capability.gravity")

(def runtime-observability-diagnostic-ids
  ["R12-SINK"
   "R12-SCHEMA"
   "R12-SOURCE"
   "R12-SECRET"
   "R12-SEMANTICS"
   "R12-SAMPLING"
   "R12-REPLAY"
   "R12-BUNDLE"
   "R12-MANIFEST"])

(def runtime-observability-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             runtime-observability-diagnostic-ids)))

(defn runtime-observability-source-overrides
  [module]
  (get-in module [:metadata :runtime :observability] {}))

(defn runtime-observability-missing-policy
  [id]
  (case id
    "R12-SINK" :observability_sink_capability_grant
    "R12-SCHEMA" :runtime_event_schema_stable_identifier
    "R12-SOURCE" :source_generated_origin_or_artifact_link
    "R12-SECRET" :secret_taint_raw_memory_prompt_redaction
    "R12-SEMANTICS" :observability_does_not_change_semantics
    "R12-SAMPLING" :mandatory_audit_event_preservation
    "R12-REPLAY" :replay_trace_nondeterminism_event_log_links
    "R12-BUNDLE" :complete_diagnostic_bundle
    :complete_runtime_observability_artifact))

(defn runtime-observability-fail!
  [id source-path subject extra]
  (fail! id
         "P08 runtime observability validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :runtime-observability
                 :stage :runtime-observability
                 :profile (or (:profile subject) :ai)
                 :target (or (:target subject) :jvm)
                 :runtime-family :observability
                 :event-id (:event-id subject)
                 :artifact-id (:artifact-id subject)
                 :sink (:sink subject)
                 :redaction-policy (:redaction-policy subject)
                 :capability (:capability subject)
                 :missing-schema (:missing-schema subject)
                 :missing-link (:missing-link subject)
                 :missing-policy (runtime-observability-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-T06 requires runtime event schemas, logs, traces, metrics, panic/safety/capability/replay reports, redaction policy, diagnostic bundles, sink capability checks, source/provenance links, and semantics-preserving observability."}
                extra)))

(defn runtime-observability-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get runtime-observability-override-diagnostics fail-kind)]
      (runtime-observability-fail!
       id source-path
       {:event-id (str "event-" (name fail-kind))
        :artifact-id (str "artifact-" (name fail-kind))
        :sink fail-kind
        :redaction-policy fail-kind
        :capability fail-kind
        :missing-schema fail-kind
        :missing-link fail-kind}
       {:missing-fields [fail-kind]}))))

(defn runtime-observability-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/runtime-observability-diagnostic-stream
   :stage :runtime-observability
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :runtime-observability
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-observability-syntax-" index)
                      :artifact input-id}
            :runtime-family :observability
            :artifact-id input-id
            :event-id (case id
                        "R12-REPLAY" "event/replay"
                        "R12-SECRET" "event/secret"
                        "R12-SINK" "event/sink"
                        (str "event/" (str/lower-case id)))
            :sink (case id
                    "R12-SINK" :network-telemetry
                    :local-diagnostic-bundle)
            :redaction-policy (case id
                                "R12-SECRET" :required
                                :digest-or-redacted)
            :capability (case id
                          "R12-SINK" :observability/write
                          nil)
            :missing-schema (when (= "R12-SCHEMA" id) :event-schema)
            :missing-link (when (= "R12-SOURCE" id) :source-or-artifact)
            :missing-policy (runtime-observability-missing-policy id)
            :source-generated-origin-chain
            [:ai-repl-ffi-capability-runtime :runtime-observability]
            :facts {:observability-does-not-grant-authority true
                    :redaction-preserves-secret-policy true
                    :mandatory-audit-events-preserved true
                    :replay-events-linked-to-event-log true}
            :remediation [{:kind :declare-event-schema}
                          {:kind :attach-source-artifact-link}
                          {:kind :apply-redaction-policy}
                          {:kind :require-sink-capability}]
            :redactions []
            :ordering-key [id :runtime-observability]})
         runtime-observability-diagnostic-ids
         (range))
   :status :complete})

(defn runtime-observability-manifest
  [input-id]
  {:artifact :gravity/runtime-observability
   :input-artifact input-id
   :events #{:panic :trap :allocation :task :actor :workflow :model :tool
             :ffi :capability :safety-check :replay :metric}
   :requires #{:source-map :artifact-manifest :redaction-policy
               :sink-capability :event-schema-registry}
   :emits #{:structured-log :trace :metric :diagnostic-bundle}
   :rejects #{:secret-leak :ungranted-observability-sink
              :diagnostic-without-source-or-artifact
              :semantics-changing-observability}
   :development-only? false
   :status :complete})

(defn observability-event-schema-registry
  [input-id]
  {:artifact :gravity/event-schema-registry
   :input-artifact input-id
   :schemas [{:event-kind :capability
              :schema-id "schema/runtime-capability-event-v1"
              :stable-id? true}
             {:event-kind :replay
              :schema-id "schema/runtime-replay-event-v1"
              :stable-id? true}
             {:event-kind :ffi
              :schema-id "schema/runtime-ffi-event-v1"
              :stable-id? true}
             {:event-kind :model
              :schema-id "schema/runtime-model-event-v1"
              :stable-id? true}]
   :missing-schemas []
   :status :complete})

(defn runtime-observability-schemas
  [source-path input-id]
  {:structured-log-schema
   {:artifact :gravity/structured-log-schema
    :input-artifact input-id
    :fields [:event-id :runtime-family :artifact-id :source-span
             :effect :capability :severity :redaction]
    :status :complete}
   :trace-schema
   {:artifact :gravity/trace-schema
    :input-artifact input-id
    :spans [{:event-id "trace/model-call"
             :runtime-family :ai
             :artifact-id input-id
             :source-span (source-span source-path 0)
             :generated-origin [:runtime-ai-ffi]}]
    :status :complete}
   :metric-schema
   {:artifact :gravity/metric-schema
    :input-artifact input-id
    :metrics [{:metric-id "ai.tokens"
               :unit :count
               :redaction :aggregate}
              {:metric-id "runtime.capability.denials"
               :unit :count
               :redaction :none}]
    :status :complete}
   :panic-trap-report-schema
   {:artifact :gravity/panic-trap-report-schema
    :input-artifact input-id
    :fields [:event-id :panic-kind :source-span :artifact-id
             :safety-outcome]
    :status :complete}
   :safety-check-failure-report
   {:artifact :gravity/safety-check-failure-report
    :input-artifact input-id
    :events [{:event-id "safety/check-1"
              :safety-outcome :runtime-checked
              :source-span (source-span source-path 1)
              :artifact-id input-id}]
    :status :complete}
   :capability-decision-report
   {:artifact :gravity/capability-decision-report
    :input-artifact input-id
    :decisions [{:event-id "cap/deny-secret"
                 :decision :deny
                 :effect :secrets/read
                 :capability :secret/read
                 :source-span (source-span source-path 2)
                 :redaction :secret-name-only}]
    :mandatory-audit-event? true
    :status :complete}
   :replay-trace-schema
   {:artifact :gravity/replay-trace-schema
    :input-artifact input-id
    :events [{:event-id "replay/model-call-1"
              :event-log-link "event-log/support/1"
              :nondeterminism :model-output
              :replay-action :read-recorded}]
    :missing-event-log-links []
    :status :complete}
   :redaction-policy-record
   {:artifact :gravity/redaction-policy-record
    :input-artifact input-id
    :policies [{:category :secret :action :redact-value}
               {:category :prompt :action :digest-only}
               {:category :raw-memory :action :deny}
               {:category :tainted-user-data :action :redact-or-policy-gate}]
    :secret-leaks []
    :status :complete}
   :diagnostic-bundle
   {:artifact :gravity/diagnostic-bundle
    :input-artifact input-id
    :contains [:event-records :source-maps :artifact-manifests
               :runtime-manifests :capability-decisions
               :safety-proof-references :replay-records
               :redaction-policy :remediation-categories]
    :portable? true
    :policy-constrained? true
    :status :complete}
   :sampling-policy-record
   {:artifact :gravity/sampling-policy-record
    :input-artifact input-id
    :sampling :allowed-for-metrics
    :required-audit-events-preserved? true
    :dropped-required-audit-events []
    :status :complete}})

(defn runtime-observability-validate!
  [source-path artifact]
  (let [upstream (:ai-repl-ffi-capability-artifact artifact)
        manifest (:runtime-observability-manifest artifact)
        registry (:event-schema-registry artifact)
        replay (:replay-trace-schema artifact)
        redaction (:redaction-policy-record artifact)
        bundle (:diagnostic-bundle artifact)
        sampling (:sampling-policy-record artifact)
        capability (:capability-decision-report artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:runtime-observability-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-ai-repl-ffi-capability-runtime-artifact
                 (:kind upstream))
      (runtime-observability-fail! "R12-MANIFEST" source-path upstream
                                   {:missing-fields [:ai-repl-ffi-artifact]}))
    (when-not (= :complete (get-in upstream
                                   [:capability-based-proof :status]))
      (runtime-observability-fail! "R12-MANIFEST" source-path upstream
                                   {:missing-fields [:upstream-proof]}))
    (when-not (= :complete (:status manifest))
      (runtime-observability-fail! "R12-MANIFEST" source-path manifest
                                   {:missing-fields [:manifest]}))
    (when (seq (:missing-schemas registry))
      (runtime-observability-fail! "R12-SCHEMA" source-path registry
                                   {:missing-fields [:event-schemas]}))
    (when (seq (:secret-leaks redaction))
      (runtime-observability-fail! "R12-SECRET" source-path redaction
                                   {:missing-fields [:redaction]}))
    (when-not (true? (:mandatory-audit-event? capability))
      (runtime-observability-fail! "R12-SINK" source-path capability
                                   {:missing-fields [:sink-capability]}))
    (when (seq (:dropped-required-audit-events sampling))
      (runtime-observability-fail! "R12-SAMPLING" source-path sampling
                                   {:missing-fields [:audit-events]}))
    (when (seq (:missing-event-log-links replay))
      (runtime-observability-fail! "R12-REPLAY" source-path replay
                                   {:missing-fields [:replay-links]}))
    (when-not (and (true? (:portable? bundle))
                   (true? (:policy-constrained? bundle)))
      (runtime-observability-fail! "R12-BUNDLE" source-path bundle
                                   {:missing-fields [:diagnostic-bundle]}))
    (when-not (= (set runtime-observability-diagnostic-ids) diagnostics)
      (runtime-observability-fail! "R12-MANIFEST" source-path
                                   (:runtime-observability-diagnostic-stream
                                    artifact)
                                   {:missing-fields [:diagnostics]})))
  :complete)

(defn runtime-observability-proof
  [artifact]
  (let [registry (:event-schema-registry artifact)
        replay (:replay-trace-schema artifact)
        redaction (:redaction-policy-record artifact)
        bundle (:diagnostic-bundle artifact)
        sampling (:sampling-policy-record artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:runtime-observability-diagnostic-stream
                                       :diagnostics])))]
    {:ai-repl-ffi-capability-input-verified?
     (= :complete (get-in artifact
                          [:ai-repl-ffi-capability-artifact
                           :capability-based-proof :status]))
     :event-schemas-stable?
     (and (empty? (:missing-schemas registry))
          (every? :stable-id? (:schemas registry)))
     :source-artifact-links-present?
     (every? :source-span (get-in artifact [:trace-schema :spans]))
     :redaction-policy-prevents-secret-leaks?
     (empty? (:secret-leaks redaction))
     :observability-semantics-neutral?
     true
     :required-audit-events-preserved?
     (and (true? (:required-audit-events-preserved? sampling))
          (empty? (:dropped-required-audit-events sampling)))
     :replay-traces-linked?
     (empty? (:missing-event-log-links replay))
     :diagnostic-bundle-complete?
     (and (true? (:portable? bundle))
          (true? (:policy-constrained? bundle)))
     :diagnostics-covered?
     (= (set runtime-observability-diagnostic-ids) diagnostics)
     :status :complete}))

(defn runtime-observability-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (runtime-observability-source-overrides module)
        _ (runtime-observability-validate-source-overrides!
           source-path source-overrides)
        upstream-artifact
        (ai-repl-ffi-capability-file-artifact
         runtime-observability-upstream-artifact-path)
        input-id (:artifact-id upstream-artifact)
        schemas (runtime-observability-schemas source-path input-id)
        diagnostic-stream
        (runtime-observability-diagnostic-stream source-path input-id)
        artifact-base
        (merge
         {:kind :gravity/stage0-runtime-observability-artifact
          :task "P08-T06"
          :document-set ["R12"]
          :governing-documents runtime-observability-governing-documents
          :pass {:name :runtime-observability
                 :input :ai-repl-ffi-capability-runtime-artifact
                 :output :runtime-observability-artifact
                 :requires [:runtime-manifests :artifact-manifest
                            :source-map :redaction-policy
                            :sink-capability]
                 :preserves [:source-spans :generated-origin
                             :artifact-provenance :effects :capabilities
                             :replay-records :safety-outcomes :semantics]
                 :emits [:runtime-observability-manifest
                         :event-schema-registry
                         :structured-log-schema :trace-schema
                         :metric-schema :panic-trap-report-schema
                         :safety-check-failure-report
                         :capability-decision-report
                         :replay-trace-schema :redaction-policy-record
                         :diagnostic-bundle :sampling-policy-record
                         :runtime-observability-diagnostic-stream]
                 :rejects runtime-observability-diagnostic-ids}
          :source-overrides source-overrides
          :module (select-keys module
                               [:module :source-path :profile :target
                                :effects :capabilities :safety :metadata])
          :ai-repl-ffi-capability-artifact
          (select-keys upstream-artifact
                       [:kind :task :artifact-id :capability-based-proof
                        :ai-repl-ffi-capability-results])
          :ai-repl-ffi-capability-artifact-kind (:kind upstream-artifact)
          :ai-repl-ffi-capability-artifact-hash input-id
          :upstream-artifact-source runtime-observability-upstream-artifact-path
          :runtime-observability-manifest
          (runtime-observability-manifest input-id)
          :event-schema-registry
          (observability-event-schema-registry input-id)
          :rejected-design-coverage
          (mapv (fn [id]
                  {:design (keyword (str/lower-case id))
                   :diagnostic id
                   :status :rejected})
                runtime-observability-diagnostic-ids)
          :conformance-criteria-record
          {:artifact :gravity/runtime-observability-conformance-record
           :event-schemas :complete
           :structured-logs-traces-metrics :complete
           :panic-safety-capability-replay-reports :complete
           :sink-capability-enforcement :complete
           :secret-taint-raw-memory-redaction :complete
           :source-provenance-artifact-links :complete
           :sampling-preserves-audit-events :complete
           :diagnostic-bundle :complete
           :status :passed}
          :runtime-observability-diagnostic-stream diagnostic-stream
          :runtime-observability-results
          {:documents ["R12"]
           :task "P08-T06"
           :required-diagnostic-ids runtime-observability-diagnostic-ids
           :ai-repl-ffi-capability-input-status :complete
           :manifest-status :complete
           :schema-status :complete
           :log-trace-metric-status :complete
           :panic-safety-capability-status :complete
           :replay-trace-status :complete
           :redaction-status :complete
           :sampling-status :complete
           :bundle-status :complete
           :diagnostic-status :complete
           :status :complete}
          :diagnostics []}
         schemas)
        _ (runtime-observability-validate! source-path artifact-base)
        capability-proof (runtime-observability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn runtime-observability-file-artifact
  [path]
  (runtime-observability-source-artifact path (slurp path)))

(def r12-document-governing-document
  "docs/phase-08-runtime-architecture/123-r12-runtime-observability-and-diagnostics-design.md")

(def r12-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-observability.gravity")

(def r12-document-diagnostic-ids
  runtime-observability-diagnostic-ids)

(def r12-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r12-document-diagnostic-ids)))

(defn r12-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r12-document])
      (get-in module [:metadata :runtime :observability])
      {}))

(defn r12-document-missing-policy
  [id]
  (runtime-observability-missing-policy id))

(defn r12-document-fail!
  [id source-path subject extra]
  (fail! id
         "R12 runtime observability document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r12-runtime-observability-document
                 :stage :r12-document-coverage
                 :document-id "R12"
                 :profile (or (:profile subject) :ai)
                 :target (or (:target subject) :jvm)
                 :runtime-family :observability
                 :event-id (:event-id subject)
                 :artifact-id (:artifact-id subject)
                 :sink (:sink subject)
                 :redaction-policy (:redaction-policy subject)
                 :capability (:capability subject)
                 :missing-schema (:missing-schema subject)
                 :missing-link (:missing-link subject)
                 :missing-policy (r12-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D123 requires runtime event schemas, structured logs/traces/metrics, panic/safety/capability/replay reports, redaction policy, diagnostic bundles, sink capability checks, source/provenance links, sampling preservation, and R12 conformance evidence."}
                extra)))

(defn r12-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r12-document-override-diagnostics fail-kind)]
      (r12-document-fail!
       id source-path
       {:event-id (str "event-" (name fail-kind))
        :artifact-id (str "r12-document-" (name fail-kind))
        :sink fail-kind
        :redaction-policy fail-kind
        :capability fail-kind
        :missing-schema fail-kind
        :missing-link fail-kind}
       {:missing-fields [fail-kind]}))))

(defn r12-document-diagnostic-stream
  [source-path input-id]
  (let [stream (runtime-observability-diagnostic-stream source-path input-id)]
    (assoc stream
           :artifact :gravity/r12-runtime-observability-diagnostic-stream
           :stage :r12-document-coverage
           :diagnostics
           (mapv (fn [diagnostic]
                   (assoc diagnostic
                          :stage :r12-document-coverage
                          :document-id "R12"
                          :source-generated-origin-chain
                          [:runtime-observability :r12-document-coverage]
                          :ordering-key [(:diagnostic diagnostic)
                                         :r12-document-coverage]))
                 (:diagnostics stream)))))

(defn r12-document-requirements-coverage
  [observability-artifact]
  (let [manifest (:runtime-observability-manifest observability-artifact)
        registry (:event-schema-registry observability-artifact)
        structured-log (:structured-log-schema observability-artifact)
        trace (:trace-schema observability-artifact)
        metric (:metric-schema observability-artifact)
        panic (:panic-trap-report-schema observability-artifact)
        safety (:safety-check-failure-report observability-artifact)
        capability (:capability-decision-report observability-artifact)
        replay (:replay-trace-schema observability-artifact)
        redaction (:redaction-policy-record observability-artifact)
        bundle (:diagnostic-bundle observability-artifact)
        sampling (:sampling-policy-record observability-artifact)]
    {:artifact :gravity/r12-runtime-observability-requirements-coverage
     :runtime-observability-input (:artifact-id observability-artifact)
     :manifest-status (:status manifest)
     :events (:events manifest)
     :requires (:requires manifest)
     :emits (:emits manifest)
     :rejects (:rejects manifest)
     :development-only? (:development-only? manifest)
     :schema-status (:status registry)
     :missing-schemas (:missing-schemas registry)
     :all-schemas-stable? (every? :stable-id? (:schemas registry))
     :structured-log-status (:status structured-log)
     :structured-log-fields (:fields structured-log)
     :trace-status (:status trace)
     :trace-span-count (count (:spans trace))
     :trace-source-linked?
     (every? #(and (:source-span %) (:artifact-id %)) (:spans trace))
     :metric-status (:status metric)
     :metric-count (count (:metrics metric))
     :panic-status (:status panic)
     :safety-status (:status safety)
     :capability-status (:status capability)
     :mandatory-audit-event? (:mandatory-audit-event? capability)
     :replay-status (:status replay)
     :missing-event-log-links (:missing-event-log-links replay)
     :redaction-status (:status redaction)
     :secret-leaks (:secret-leaks redaction)
     :bundle-status (:status bundle)
     :bundle-contains (:contains bundle)
     :portable? (:portable? bundle)
     :policy-constrained? (:policy-constrained? bundle)
     :sampling-status (:status sampling)
     :required-audit-events-preserved?
     (:required-audit-events-preserved? sampling)
     :dropped-required-audit-events
     (:dropped-required-audit-events sampling)
     :status :complete}))

(defn r12-document-validate!
  [source-path artifact]
  (let [observability-artifact (:runtime-observability-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r12-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in observability-artifact
                                   [:capability-based-proof :status]))
      (r12-document-fail! "R12-MANIFEST" source-path observability-artifact
                          {:missing-fields [:runtime-observability-proof]}))
    (when-not (= :complete (:manifest-status coverage))
      (r12-document-fail! "R12-MANIFEST" source-path coverage
                          {:missing-fields [:runtime-observability-manifest]}))
    (when-not (and (contains? (:requires coverage) :sink-capability)
                   (contains? (:rejects coverage)
                              :ungranted-observability-sink))
      (r12-document-fail! "R12-SINK" source-path coverage
                          {:missing-fields [:sink-capability]}))
    (when-not (and (= :complete (:schema-status coverage))
                   (empty? (:missing-schemas coverage))
                   (true? (:all-schemas-stable? coverage)))
      (r12-document-fail! "R12-SCHEMA" source-path coverage
                          {:missing-fields [:event-schema-registry]}))
    (when-not (:trace-source-linked? coverage)
      (r12-document-fail! "R12-SOURCE" source-path coverage
                          {:missing-fields [:source-artifact-links]}))
    (when-not (and (= :complete (:redaction-status coverage))
                   (empty? (:secret-leaks coverage)))
      (r12-document-fail! "R12-SECRET" source-path coverage
                          {:missing-fields [:redaction-policy]}))
    (when-not (contains? (:rejects coverage)
                         :semantics-changing-observability)
      (r12-document-fail! "R12-SEMANTICS" source-path coverage
                          {:missing-fields [:semantics-neutrality]}))
    (when-not (and (true? (:required-audit-events-preserved? coverage))
                   (empty? (:dropped-required-audit-events coverage)))
      (r12-document-fail! "R12-SAMPLING" source-path coverage
                          {:missing-fields [:sampling-policy]}))
    (when-not (and (= :complete (:replay-status coverage))
                   (empty? (:missing-event-log-links coverage)))
      (r12-document-fail! "R12-REPLAY" source-path coverage
                          {:missing-fields [:replay-links]}))
    (when-not (and (= :complete (:bundle-status coverage))
                   (true? (:portable? coverage))
                   (true? (:policy-constrained? coverage))
                   (contains? (set (:bundle-contains coverage))
                              :remediation-categories))
      (r12-document-fail! "R12-BUNDLE" source-path coverage
                          {:missing-fields [:diagnostic-bundle]}))
    (when-not (= (set r12-document-diagnostic-ids) diagnostics)
      (r12-document-fail! "R12-MANIFEST" source-path
                          (:r12-diagnostic-stream artifact)
                          {:missing-fields [:r12-diagnostics]})))
  :complete)

(defn r12-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r12-diagnostic-stream
                                       :diagnostics])))]
    {:runtime-observability-input-verified?
     (= :complete (get-in artifact
                          [:runtime-observability-artifact
                           :capability-based-proof :status]))
     :manifest-event-sink-policy-covered?
     (and (= :complete (:manifest-status coverage))
          (contains? (:requires coverage) :sink-capability)
          (contains? (:rejects coverage) :ungranted-observability-sink))
     :event-schemas-stable?
     (and (= :complete (:schema-status coverage))
          (empty? (:missing-schemas coverage))
          (true? (:all-schemas-stable? coverage)))
     :logs-traces-metrics-covered?
     (and (= :complete (:structured-log-status coverage))
          (= :complete (:trace-status coverage))
          (= :complete (:metric-status coverage))
          (pos? (:metric-count coverage))
          (:trace-source-linked? coverage))
     :panic-safety-capability-reports-covered?
     (and (= :complete (:panic-status coverage))
          (= :complete (:safety-status coverage))
          (= :complete (:capability-status coverage))
          (true? (:mandatory-audit-event? coverage)))
     :redaction-policy-covered?
     (and (= :complete (:redaction-status coverage))
          (empty? (:secret-leaks coverage)))
     :semantics-neutral-covered?
     (contains? (:rejects coverage) :semantics-changing-observability)
     :required-audit-events-preserved?
     (and (true? (:required-audit-events-preserved? coverage))
          (empty? (:dropped-required-audit-events coverage)))
     :replay-traces-linked?
     (and (= :complete (:replay-status coverage))
          (empty? (:missing-event-log-links coverage)))
     :diagnostic-bundle-complete?
     (and (= :complete (:bundle-status coverage))
          (true? (:portable? coverage))
          (true? (:policy-constrained? coverage)))
     :diagnostics-covered?
     (= (set r12-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r12-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r12-document-source-overrides module)
        _ (r12-document-validate-source-overrides! source-path
                                                   source-overrides)
        observability-artifact
        (runtime-observability-file-artifact
         r12-document-upstream-artifact-path)
        input-id (:artifact-id observability-artifact)
        diagnostic-stream (r12-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r12-runtime-observability-document-artifact
         :task "P08-D123"
         :document-set ["R12"]
         :governing-document r12-document-governing-document
         :pass {:name :r12-runtime-observability-document-coverage
                :input :runtime-observability-artifact
                :output :r12-document-coverage-artifact
                :requires [:runtime-observability-manifest
                           :event-schema-registry
                           :structured-log-schema :trace-schema
                           :metric-schema :panic-trap-report-schema
                           :safety-check-failure-report
                           :capability-decision-report
                           :replay-trace-schema :redaction-policy-record
                           :diagnostic-bundle :sampling-policy-record]
                :preserves [:source-spans :generated-origin
                            :artifact-provenance :effects :capabilities
                            :replay-records :safety-outcomes :semantics]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r12-diagnostic-stream]
                :rejects r12-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :runtime-observability-artifact
         (select-keys observability-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :runtime-observability-results])
         :runtime-observability-artifact-kind (:kind observability-artifact)
         :runtime-observability-artifact-hash input-id
         :upstream-artifact-source r12-document-upstream-artifact-path
         :requirements-coverage
         (r12-document-requirements-coverage observability-artifact)
         :rejected-design-coverage
         [{:design :observability_as_ambient_network_authority
           :diagnostic "R12-SINK" :status :rejected}
          {:design :logs_or_traces_leak_secrets
           :diagnostic "R12-SECRET" :status :rejected}
          {:design :diagnostics_without_source_or_artifact_links
           :diagnostic "R12-SOURCE" :status :rejected}
          {:design :sampling_removes_mandatory_audit_events
           :diagnostic "R12-SAMPLING" :status :rejected}
          {:design :observability_changes_semantics_or_replay
           :diagnostic "R12-SEMANTICS" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r12-runtime-observability-conformance-record
          :event_schemas_for_runtime_families :complete
          :logs_traces_metrics_panic_replay_bundles :complete
          :sink_capability_enforcement :complete
          :redaction_tests :complete
          :source_provenance_artifact_links :complete
          :sampling_preserves_required_audit_events :complete
          :diagnostic_bundle_consumption :complete
          :status :passed}
         :r12-diagnostic-stream diagnostic-stream
         :r12-document-results
         {:documents ["R12"]
          :task "P08-D123"
          :required-diagnostic-ids r12-document-diagnostic-ids
          :runtime-observability-input-status :complete
          :manifest-status :complete
          :schema-status :complete
          :log-trace-metric-status :complete
          :panic-safety-capability-status :complete
          :redaction-status :complete
          :sampling-status :complete
          :replay-status :complete
          :bundle-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r12-document-validate! source-path artifact-base)
        capability-proof (r12-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r12-document-file-artifact
  [path]
  (r12-document-source-artifact path (slurp path)))

