(def p11-ai-diagnostic-ids
  (vec
   (distinct
    (concat
     (mapcat
      (fn [document]
        (map (comp first val)
             (sort-by (comp name key) (p11-ai-contracts document))))
      p11-ai-documents)
     ["P11-MANIFEST" "P11-ACCEPTED" "P11-REJECTED"
      "P11-CONFORMANCE"]))))

(def p11-ai-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             p11-ai-diagnostic-ids)))

