(defn p11-ai-document-record
  [document]
  (let [summary (p11-ai-document-summaries document)]
    (merge
     {:document document
      :task-id (p11-task-id document)
      :governing-doc (p11-ai-governing-documents document)
      :agent-id "support-triage"
      :workflow-id "triage-ticket"
      :diagnostics (p11-contract-diagnostics document)
      :evidence (p11-contract-evidence document)
      :conformance
      {:accepted-fixture "bootstrap/clojure/fixtures/accepted/ai-agentic.gravity"
       :rejected-fixture (str "bootstrap/clojure/fixtures/rejected/"
                              (p11-ai-rejected-fixture-names document))
       :artifact-evidence :ai-agentic-artifact
       :validation-command "clojure -M:test"
       :status :complete}}
     summary)))

(defn p11-ai-document-records
  []
  (into {} (map (fn [document] [document (p11-ai-document-record document)])
                p11-ai-documents)))

(defn p11-accepted-ai-fixtures
  []
  (mapv (fn [document]
          {:document document
           :fixture "bootstrap/clojure/fixtures/accepted/ai-agentic.gravity"
           :artifact (get-in (p11-ai-document-summaries document)
                             [:owned-surface])
           :evidence [(p11-task-id document)
                      (p11-ai-governing-documents document)]
           :status :accepted})
        p11-ai-documents))

(defn p11-rejected-ai-fixtures
  []
  (mapv (fn [document]
          {:document document
           :fixture (str "bootstrap/clojure/fixtures/rejected/"
                         (p11-ai-rejected-fixture-names document))
           :artifact :stable-ai-agentic-diagnostic
           :diagnostic (p11-ai-rejected-diagnostics document)
           :evidence [(p11-task-id document)
                      (p11-ai-governing-documents document)]
           :status :rejected})
        p11-ai-documents))

(defn p11-ai-conformance-evidence
  []
  (mapv (fn [document]
          {:document document
           :accepted-behavior (get-in (p11-ai-document-summaries document)
                                      [:accepted-behavior])
           :rejected-behavior (p11-ai-rejected-diagnostics document)
           :artifacts (get-in (p11-ai-document-summaries document)
                              [:artifact-keys])
           :validation ["clojure -M:test"
                        "clojure -M:gravity ai-agentic bootstrap/clojure/fixtures/accepted/ai-agentic.gravity"]
           :status :complete})
        p11-ai-documents))

(defn p11-ai-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/phase11-ai-agentic-diagnostic-stream
   :stage :ai-agentic
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           (let [document (p11-ai-diagnostic-document id)]
             {:artifact :gravity/diagnostic
              :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
              :diagnostic id
              :rule id
              :severity :error
              :stage :ai-agentic
              :document-id document
              :task (when document (p11-task-id document))
              :primary {:span (source-span source-path index)
                        :syntax-id (str "p11-ai-syntax-" index)
                        :artifact input-id}
              :missing-fact (or (some (fn [[_ [diagnostic missing-fact]]]
                                         (when (= id diagnostic) missing-fact))
                                       (get p11-ai-contracts document))
                                :ai_agentic_manifest)
              :remediation [{:kind :declare-typed-ai-artifact}
                            {:kind :preserve-taint-and-authority}
                            {:kind :require-capability-and-policy}
                            {:kind :record-replay-eval-human-review}]
              :ordering-key [id :ai-agentic]}))
         p11-ai-diagnostic-ids
         (range))
   :status :complete})

(defn p11-present?
  [value]
  (if (coll? value)
    (seq value)
    (some? value)))

(defn p11-ai-validate!
  [source-path artifact]
  (let [documents (:document-contracts artifact)
        accepted (:accepted-ai-fixtures artifact)
        rejected (:rejected-ai-fixtures artifact)
        conformance (:ai-conformance-evidence artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:ai-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= (set p11-ai-documents) (set (:document-set artifact)))
      (p11-ai-fail! "P11-MANIFEST" source-path artifact
                    {:missing-fields [:document-set]}))
    (doseq [artifact-key p11-ai-artifact-keys]
      (when-not (p11-present? (get artifact artifact-key))
        (p11-ai-fail! "P11-MANIFEST" source-path artifact
                      {:missing-fields [artifact-key]}))
      (when-not (= :complete (:status (get artifact artifact-key)))
        (p11-ai-fail! "P11-MANIFEST" source-path (get artifact artifact-key)
                      {:missing-fields [:status]})))
    (when-not (every? #(contains? documents %) p11-ai-documents)
      (p11-ai-fail! "P11-MANIFEST" source-path documents
                    {:missing-fields [:document-contracts]}))
    (doseq [document p11-ai-documents
            :let [record (get documents document)
                  summary (p11-ai-document-summaries document)
                  contract (p11-ai-contracts document)]]
      (doseq [field [:document :task-id :governing-doc :agent-id
                     :workflow-id :diagnostics :evidence :owned-surface
                     :accepted-behavior :rejected-behavior :artifact-keys
                     :conformance]]
        (when-not (p11-present? (get record field))
          (p11-ai-fail! "P11-MANIFEST" source-path record
                        {:missing-fields [field]})))
      (when-not (= (:owned-surface summary) (:owned-surface record))
        (p11-ai-fail! "P11-MANIFEST" source-path record
                      {:missing-fields [:owned-surface]}))
      (doseq [[fact [diagnostic _]] contract]
        (when-not (and (contains? (set (:diagnostics record)) diagnostic)
                       (get-in record [:evidence fact]))
          (p11-ai-fail! diagnostic source-path record
                        {:missing-fields [fact]}))))
    (when-not (= (set p11-ai-documents) (set (map :document accepted)))
      (p11-ai-fail! "P11-ACCEPTED" source-path accepted
                    {:missing-fields [:accepted-ai-fixtures]}))
    (when-not (= (set p11-ai-documents) (set (map :document rejected)))
      (p11-ai-fail! "P11-REJECTED" source-path rejected
                    {:missing-fields [:rejected-ai-fixtures]}))
    (when-not (= (set p11-ai-documents) (set (map :document conformance)))
      (p11-ai-fail! "P11-CONFORMANCE" source-path conformance
                    {:missing-fields [:ai-conformance-evidence]}))
    (when-not (contains? (get-in artifact [:tool-schema :capabilities])
                         :ticket/write)
      (p11-ai-fail! "AI004" source-path (:tool-schema artifact)
                    {:missing-fields [:ticket-write-capability]}))
    (when-not (= :required-for-high-priority
                 (get-in artifact [:tool-schema :human-review]))
      (p11-ai-fail! "A4005" source-path (:tool-schema artifact)
                    {:missing-fields [:human-review]}))
    (when-not (seq (get-in artifact [:agent-manifest :eval-gates]))
      (p11-ai-fail! "A5005" source-path (:agent-manifest artifact)
                    {:missing-fields [:eval-gates]}))
    (when-not (= :recorded-effects
                 (get-in artifact [:workflow-graph :replay-mode]))
      (p11-ai-fail! "A6001" source-path (:workflow-graph artifact)
                    {:missing-fields [:replay-mode]}))
    (when-not (= :deny-by-default
                 (get-in artifact [:memory-policy :cross-tenant]))
      (p11-ai-fail! "A7004" source-path (:memory-policy artifact)
                    {:missing-fields [:tenant-partition]}))
    (when-not (= :untrusted-until-schema-validated
                 (get-in artifact [:policy-manifest :taint :ai-output]))
      (p11-ai-fail! "A8004" source-path (:policy-manifest artifact)
                    {:missing-fields [:taint-policy]}))
    (when-not (= :passed
                 (get-in artifact [:evaluation-report :release-gate]))
      (p11-ai-fail! "A9001" source-path (:evaluation-report artifact)
                    {:missing-fields [:eval-gate]}))
    (when-not (= :canonical-action-payload
                 (get-in artifact
                         [:human-review-manifest :payload-hash-rule]))
      (p11-ai-fail! "A10005" source-path (:human-review-manifest artifact)
                    {:missing-fields [:payload-hash-rule]}))
    (when-not (contains? (set (get-in artifact
                                      [:injection-defense
                                       :runtime-monitors]))
                         :denied-tool-escalation)
      (p11-ai-fail! "A11002" source-path (:injection-defense artifact)
                    {:missing-fields [:denied-tool-escalation]}))
    (when-not (set/subset? (set p11-ai-diagnostic-ids) diagnostics)
      (p11-ai-fail! "P11-MANIFEST" source-path (:ai-diagnostic-stream artifact)
                    {:missing-fields [:diagnostics]})))
  :complete)

(defn p11-task-statuses
  []
  (merge (zipmap ["P11-T01" "P11-T02" "P11-T03"
                  "P11-T04" "P11-T05" "P11-T06"]
                 (repeat :complete))
         (zipmap (map p11-task-id p11-ai-documents)
                 (repeat :complete))))

(defn p11-ai-proof
  [artifact]
  (let [documents (:document-contracts artifact)
        accepted-docs (set (map :document (:accepted-ai-fixtures artifact)))
        rejected-docs (set (map :document (:rejected-ai-fixtures artifact)))
        conformance-docs (set (map :document (:ai-conformance-evidence artifact)))
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:ai-diagnostic-stream
                                       :diagnostics])))]
    {:ai-programming-surface-covered?
     (= :complete (:status (:ai-program-manifest artifact)))
     :provider-and-prompt-covered?
     (and (= :redacted
             (:credential-redaction (:model-manifest artifact)))
          (= :system-trusted
             (get-in artifact [:prompt-artifact :authority :system])))
     :tool-agent-memory-policy-covered?
     (and (= :required-for-high-priority
             (:human-review (:tool-schema artifact)))
          (seq (:eval-gates (:agent-manifest artifact)))
          (= :deny-by-default
             (:cross-tenant (:memory-policy artifact)))
          (= :untrusted-until-schema-validated
             (get-in artifact [:policy-manifest :taint :ai-output])))
     :workflow-replay-covered?
     (= :recorded-effects
        (:replay-mode (:workflow-graph artifact)))
     :evaluation-and-human-review-covered?
     (and (= :passed (:release-gate (:evaluation-report artifact)))
          (= :canonical-action-payload
             (:payload-hash-rule (:human-review-manifest artifact))))
     :injection-defense-covered?
     (contains? (set (get-in artifact
                             [:injection-defense :runtime-monitors]))
                :denied-tool-escalation)
     :document-coverage-complete?
     (= (set p11-ai-documents) (set (keys documents)))
     :accepted-fixtures-covered?
     (= (set p11-ai-documents) accepted-docs)
     :rejected-fixtures-covered?
     (= (set p11-ai-documents) rejected-docs)
     :conformance-evidence-covered?
     (= (set p11-ai-documents) conformance-docs)
     :diagnostics-covered?
     (set/subset? (set p11-ai-diagnostic-ids) diagnostics)
     :task-statuses (p11-task-statuses)
     :status :complete}))

(defn ai-agentic-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (p11-ai-source-overrides module)
        _ (p11-ai-validate-source-overrides! source-path source-overrides)
        input-id (c4-artifact-id {:source-path source-path
                                  :module (:module module)
                                  :task "P11-T01-T06"
                                  :documents p11-ai-documents})
        diagnostic-stream (p11-ai-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-ai-agentic-artifact
         :phase "11"
         :task "P11-T01-T06"
         :document-set p11-ai-documents
         :governing-documents p11-ai-phase-governing-documents
         :pass {:name :phase11-ai-agentic
                :input :ordinary-gravity-source
                :output :ai-agentic-artifact
                :requires p11-ai-artifact-keys
                :preserves [:profile :target :schema :effect :capability
                            :taint :authority-partition :policy
                            :replay :evaluation :human-review
                            :source-spans :provenance]
                :emits [:document-contracts :accepted-ai-fixtures
                        :rejected-ai-fixtures :ai-conformance-evidence
                        :ai-diagnostic-stream]
                :rejects p11-ai-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :ai-program-manifest (p11-ai-program-manifest source-path input-id)
         :model-manifest (p11-model-manifest)
         :prompt-artifact (p11-prompt-artifact)
         :tool-schema (p11-tool-schema)
         :agent-manifest (p11-agent-manifest)
         :workflow-graph (p11-workflow-graph)
         :memory-policy (p11-memory-policy)
         :policy-manifest (p11-policy-manifest)
         :evaluation-report (p11-evaluation-report)
         :human-review-manifest (p11-human-review-manifest)
         :injection-defense (p11-injection-defense)
         :document-contracts (p11-ai-document-records)
         :accepted-ai-fixtures (p11-accepted-ai-fixtures)
         :rejected-ai-fixtures (p11-rejected-ai-fixtures)
         :ai-conformance-evidence (p11-ai-conformance-evidence)
         :ai-diagnostic-stream diagnostic-stream
         :ai-agentic-results
         {:documents p11-ai-documents
          :tasks (p11-task-statuses)
          :document-contracts 11
          :artifact-families (count p11-ai-artifact-keys)
          :accepted-fixtures 11
          :rejected-fixtures 11
          :conformance-records 11
          :diagnostic-count (count p11-ai-diagnostic-ids)
          :status :complete}
         :diagnostics []}
        _ (p11-ai-validate! source-path artifact-base)
        capability-proof (p11-ai-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn ai-agentic-file-artifact
  [path]
  (ai-agentic-source-artifact path (slurp path)))

