(def p12-package-diagnostic-ids
  (vec
   (distinct
    (concat
     (mapcat
      (fn [document]
        (map (comp first val)
             (sort-by (comp name key)
                      (p12-package-contracts document))))
      p12-package-documents)
     ["P12-MANIFEST" "P12-ACCEPTED" "P12-REJECTED"
      "P12-CONFORMANCE"]))))

