(defn p13-tooling-document-record
  [document]
  (let [summary (p13-tooling-document-summaries document)]
    (merge
     {:document document
      :task-id (p13-task-id document)
      :governing-doc (p13-tooling-phase-governing-documents document)
      :tool-id (get-in summary [:owned-surface])
      :diagnostics (p13-tooling-diagnostics-by-document document)
      :evidence (into {}
                      (map (fn [diagnostic]
                             [(keyword (str/lower-case diagnostic))
                              {:diagnostic diagnostic
                               :source :governing-document
                               :status :present}])
                           (p13-tooling-diagnostics-by-document document)))
      :conformance
      {:accepted-fixture "bootstrap/clojure/fixtures/accepted/tooling-experience.gravity"
       :rejected-fixture (str "bootstrap/clojure/fixtures/rejected/"
                              (p13-tooling-rejected-fixture-names document))
       :artifact-evidence :tooling-experience
       :validation-command "clojure -M:test"
       :status :complete}}
     summary)))

(defn p13-tooling-document-records
  []
  (into {} (map (fn [document]
                  [document (p13-tooling-document-record document)])
                p13-tooling-documents)))

(defn p13-accepted-tooling-fixtures
  []
  (mapv (fn [document]
          {:document document
           :fixture "bootstrap/clojure/fixtures/accepted/tooling-experience.gravity"
           :artifact (get-in (p13-tooling-document-summaries document)
                             [:owned-surface])
           :evidence [(p13-task-id document)
                      (p13-tooling-phase-governing-documents document)]
           :status :accepted})
        p13-tooling-documents))

(defn p13-rejected-tooling-fixtures
  []
  (mapv (fn [document]
          {:document document
           :fixture (str "bootstrap/clojure/fixtures/rejected/"
                         (p13-tooling-rejected-fixture-names document))
           :artifact :stable-tooling-diagnostic
           :diagnostic (p13-tooling-rejected-diagnostics document)
           :evidence [(p13-task-id document)
                      (p13-tooling-phase-governing-documents document)]
           :status :rejected})
        p13-tooling-documents))

(defn p13-tooling-conformance-evidence
  []
  (mapv (fn [document]
          {:document document
           :accepted-behavior (get-in (p13-tooling-document-summaries document)
                                      [:accepted-behavior])
           :rejected-behavior (p13-tooling-rejected-diagnostics document)
           :artifacts (get-in (p13-tooling-document-summaries document)
                              [:artifact-keys])
           :validation ["clojure -M:test"
                        "clojure -M:gravity tooling-experience bootstrap/clojure/fixtures/accepted/tooling-experience.gravity"]
           :status :complete})
        p13-tooling-documents))

(defn p13-tooling-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/phase13-tooling-diagnostic-stream
   :stage :tooling-experience
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           (let [document (p13-tooling-diagnostic-document id)]
             {:artifact :gravity/diagnostic
              :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
              :diagnostic id
              :rule id
              :severity :error
              :stage :tooling-experience
              :document-id document
              :task (when document (p13-task-id document))
              :primary {:span (source-span source-path index)
                        :syntax-id (str "p13-tooling-syntax-" index)
                        :artifact input-id}
              :missing-fact (keyword (str/lower-case id))
              :remediation [{:kind :surface-compiler-truth}
                            {:kind :preserve-source-artifact-lineage}
                            {:kind :enforce-authority-and-redaction}
                            {:kind :emit-structured-tooling-evidence}]
              :ordering-key [id :tooling-experience]}))
         p13-tooling-diagnostic-ids
         (range))
   :status :complete})

(defn p13-present?
  [value]
  (if (coll? value)
    (seq value)
    (some? value)))

(defn p13-tooling-validate!
  [source-path artifact]
  (let [documents (:document-contracts artifact)
        accepted (:accepted-tooling-fixtures artifact)
        rejected (:rejected-tooling-fixtures artifact)
        conformance (:tooling-conformance-evidence artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:tooling-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= (set p13-tooling-documents)
                 (set (:document-set artifact)))
      (p13-tooling-fail! "P13-MANIFEST" source-path artifact
                         {:missing-fields [:document-set]}))
    (doseq [artifact-key p13-tooling-artifact-keys]
      (when-not (p13-present? (get artifact artifact-key))
        (p13-tooling-fail! "P13-MANIFEST" source-path artifact
                           {:missing-fields [artifact-key]}))
      (when-not (= :complete (:status (get artifact artifact-key)))
        (p13-tooling-fail! "P13-MANIFEST" source-path
                           (get artifact artifact-key)
                           {:missing-fields [:status]})))
    (when-not (every? #(contains? documents %) p13-tooling-documents)
      (p13-tooling-fail! "P13-MANIFEST" source-path documents
                         {:missing-fields [:document-contracts]}))
    (doseq [document p13-tooling-documents
            :let [record (get documents document)
                  summary (p13-tooling-document-summaries document)]]
      (doseq [field [:document :task-id :governing-doc :tool-id
                     :diagnostics :evidence :owned-surface
                     :accepted-behavior :rejected-behavior :artifact-keys
                     :conformance]]
        (when-not (p13-present? (get record field))
          (p13-tooling-fail! "P13-MANIFEST" source-path record
                             {:missing-fields [field]})))
      (when-not (= (:owned-surface summary) (:owned-surface record))
        (p13-tooling-fail! "P13-MANIFEST" source-path record
                           {:missing-fields [:owned-surface]}))
      (doseq [diagnostic (p13-tooling-diagnostics-by-document document)]
        (when-not (and (contains? (set (:diagnostics record)) diagnostic)
                       (get-in record [:evidence
                                       (keyword (str/lower-case diagnostic))]))
          (p13-tooling-fail! diagnostic source-path record
                             {:missing-fields [(keyword (str/lower-case diagnostic))]}))))
    (when-not (= (set p13-tooling-documents) (set (map :document accepted)))
      (p13-tooling-fail! "P13-ACCEPTED" source-path accepted
                         {:missing-fields [:accepted-tooling-fixtures]}))
    (when-not (= (set p13-tooling-documents) (set (map :document rejected)))
      (p13-tooling-fail! "P13-REJECTED" source-path rejected
                         {:missing-fields [:rejected-tooling-fixtures]}))
    (when-not (= (set p13-tooling-documents) (set (map :document conformance)))
      (p13-tooling-fail! "P13-CONFORMANCE" source-path conformance
                         {:missing-fields [:tooling-conformance-evidence]}))
    (when-not (set/subset?
               #{:check :build :test :run :repl :fmt :lint :doc :package
                 :registry :audit :verify :inspect-ir :profile :ai :explain}
               (set (get-in artifact [:cli-command-set :commands])))
      (p13-tooling-fail! "T1006" source-path (:cli-command-set artifact)
                         {:missing-fields [:commands]}))
    (when-not (true? (get-in artifact [:cli-command-set :json-output]))
      (p13-tooling-fail! "T1002" source-path (:cli-command-set artifact)
                         {:missing-fields [:json-output]}))
    (when-not (contains? (set (get-in artifact
                                      [:cli-command-set
                                       :capability-prompts
                                       :shown-denials]))
                         :shell/exec)
      (p13-tooling-fail! "T1003" source-path (:cli-command-set artifact)
                         {:missing-fields [:capability-denial]}))
    (when-not (and (:profile (:repl-session-artifact artifact))
                   (:target (:repl-session-artifact artifact)))
      (p13-tooling-fail! "T2001" source-path (:repl-session-artifact artifact)
                         {:missing-fields [:profile :target]}))
    (when-not (seq (get-in artifact
                           [:repl-session-artifact :capability-grants]))
      (p13-tooling-fail! "T2002" source-path (:repl-session-artifact artifact)
                         {:missing-fields [:capability-grants]}))
    (when-not (true? (get-in artifact
                             [:repl-session-artifact
                              :transcript-redacted]))
      (p13-tooling-fail! "T2004" source-path (:repl-session-artifact artifact)
                         {:missing-fields [:transcript-redacted]}))
    (when-not (true? (get-in artifact
                             [:formatter-fixture :reader-round-trip]))
      (p13-tooling-fail! "T3002" source-path (:formatter-fixture artifact)
                         {:missing-fields [:reader-round-trip]}))
    (when-not (and (true? (get-in artifact
                                  [:formatter-fixture :comments-preserved]))
                   (true? (get-in artifact
                                  [:formatter-fixture :metadata-preserved])))
      (p13-tooling-fail! "T3005" source-path (:formatter-fixture artifact)
                         {:missing-fields [:comments-preserved
                                           :metadata-preserved]}))
    (when-not (set/subset?
               #{:types :effects :capabilities :profile :artifacts}
               (set (get-in artifact
                            [:linter-diagnostic-report :compiler-facts])))
      (p13-tooling-fail! "T4004" source-path
                         (:linter-diagnostic-report artifact)
                         {:missing-fields [:compiler-facts]}))
    (when-not (true? (get-in artifact
                             [:lsp-capability-matrix
                              :diagnostics-match-cli]))
      (p13-tooling-fail! "T5001" source-path (:lsp-capability-matrix artifact)
                         {:missing-fields [:diagnostics-match-cli]}))
    (when-not (true? (get-in artifact
                             [:lsp-capability-matrix :trace-redacted]))
      (p13-tooling-fail! "T5005" source-path (:lsp-capability-matrix artifact)
                         {:missing-fields [:trace-redacted]}))
    (when-not (= :passed (get-in artifact
                                 [:debugger-trace
                                  :source-map-validation :status]))
      (p13-tooling-fail! "T6001" source-path (:debugger-trace artifact)
                         {:missing-fields [:source-map-validation]}))
    (when-not (true? (get-in artifact [:documentation-artifact :redacted]))
      (p13-tooling-fail! "T7005" source-path
                         (:documentation-artifact artifact)
                         {:missing-fields [:redacted]}))
    (when-not (zero? (get-in artifact
                             [:documentation-artifact
                              :example-validation-report :failed]))
      (p13-tooling-fail! "T7003" source-path
                         (:documentation-artifact artifact)
                         {:missing-fields [:example-validation-report]}))
    (when-not (true? (get-in artifact
                             [:dev-server-session :bug-report-redacted]))
      (p13-tooling-fail! "T8004" source-path (:dev-server-session artifact)
                         {:missing-fields [:bug-report-redacted]}))
    (when-not (some #(= :restart (:decision %))
                    (get-in artifact
                            [:dev-server-session :hot-reload-decisions]))
      (p13-tooling-fail! "T8003" source-path (:dev-server-session artifact)
                         {:missing-fields [:hot-reload-decisions]}))
    (when-not (true? (get-in artifact
                             [:registry-ux-record :update-diff
                              :capability-diff-visible]))
      (p13-tooling-fail! "T9001" source-path (:registry-ux-record artifact)
                         {:missing-fields [:capability-diff-visible]}))
    (when-not (p13-present? (get-in artifact
                                    [:ir-inspector-bundle
                                     :source-span-maps]))
      (p13-tooling-fail! "T10002" source-path
                         (:ir-inspector-bundle artifact)
                         {:missing-fields [:source-span-maps]}))
    (when-not (p13-present? (get-in artifact
                                    [:profiler-report
                                     :check-elision-report :evidence]))
      (p13-tooling-fail! "T11003" source-path (:profiler-report artifact)
                         {:missing-fields [:check-elision-evidence]}))
    (when-not (p13-present? (get-in artifact
                                    [:safety-audit-report :proof-index]))
      (p13-tooling-fail! "T12005" source-path (:safety-audit-report artifact)
                         {:missing-fields [:proof-index]}))
    (when-not (and (true? (get-in artifact
                                  [:ai-tooling-record
                                   :patch-artifact :validated]))
                   (= :approved
                      (get-in artifact
                              [:ai-tooling-record
                               :human-review-record :decision]))
                   (every? #(= :passed %)
                           (vals (get-in artifact
                                         [:ai-tooling-record
                                          :validation-report]))))
      (p13-tooling-fail! "T13002" source-path (:ai-tooling-record artifact)
                         {:missing-fields [:checked-generated-source]}))
    (when-not (set/subset? (set p13-tooling-diagnostic-ids) diagnostics)
      (p13-tooling-fail! "P13-MANIFEST" source-path
                         (:tooling-diagnostic-stream artifact)
                         {:missing-fields [:diagnostics]})))
  :complete)

(defn p13-task-statuses
  []
  (merge (zipmap ["P13-T01" "P13-T02" "P13-T03"
                  "P13-T04" "P13-T05" "P13-T06"]
                 (repeat :complete))
         (zipmap (map p13-task-id p13-tooling-documents)
                 (repeat :complete))))

(defn p13-tooling-proof
  [artifact]
  (let [documents (:document-contracts artifact)
        accepted-docs (set (map :document (:accepted-tooling-fixtures artifact)))
        rejected-docs (set (map :document (:rejected-tooling-fixtures artifact)))
        conformance-docs (set (map :document
                                   (:tooling-conformance-evidence artifact)))
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:tooling-diagnostic-stream
                                       :diagnostics])))]
    {:cli-and-project-workflow-covered?
     (and (= :complete (:status (:cli-command-set artifact)))
          (true? (get-in artifact [:cli-command-set :json-output]))
          (contains? (set (get-in artifact
                                  [:cli-command-set
                                   :capability-prompts
                                   :shown-denials]))
                     :shell/exec))
     :repl-and-incremental-dev-covered?
     (and (= :complete (:status (:repl-session-artifact artifact)))
          (true? (get-in artifact
                         [:repl-session-artifact :transcript-redacted]))
          (= :complete (:status (:dev-server-session artifact))))
     :formatter-linter-docs-covered?
     (and (true? (get-in artifact
                         [:formatter-fixture :reader-round-trip]))
          (set/subset? #{:types :effects :capabilities :profile :artifacts}
                       (set (get-in artifact
                                    [:linter-diagnostic-report
                                     :compiler-facts])))
          (true? (get-in artifact [:documentation-artifact :structured-docs])))
     :lsp-and-debugger-covered?
     (and (true? (get-in artifact
                         [:lsp-capability-matrix
                          :diagnostics-match-cli]))
          (= :passed (get-in artifact
                             [:debugger-trace
                              :source-map-validation :status])))
     :dev-registry-and-inspectors-covered?
     (boolean
      (and (true? (get-in artifact
                          [:registry-ux-record :update-diff
                           :capability-diff-visible]))
           (p13-present? (get-in artifact
                                 [:ir-inspector-bundle
                                  :source-span-maps]))
           (p13-present? (get-in artifact
                                 [:profiler-report
                                  :check-elision-report :evidence]))
           (p13-present? (get-in artifact
                                 [:safety-audit-report :proof-index]))))
     :ai-assisted-tooling-covered?
     (and (true? (get-in artifact
                         [:ai-tooling-record
                          :patch-artifact :validated]))
          (= :approved
             (get-in artifact
                     [:ai-tooling-record
                      :human-review-record :decision]))
          (false? (get-in artifact
                          [:ai-tooling-record
                           :replay-trace
                           :hidden-tool-use-detected])))
     :document-coverage-complete?
     (= (set p13-tooling-documents) (set (keys documents)))
     :accepted-fixtures-covered?
     (= (set p13-tooling-documents) accepted-docs)
     :rejected-fixtures-covered?
     (= (set p13-tooling-documents) rejected-docs)
     :conformance-evidence-covered?
     (= (set p13-tooling-documents) conformance-docs)
     :diagnostics-covered?
     (set/subset? (set p13-tooling-diagnostic-ids) diagnostics)
     :task-statuses (p13-task-statuses)
     :status :complete}))

(defn tooling-experience-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (p13-tooling-source-overrides module)
        _ (p13-tooling-validate-source-overrides! source-path source-overrides)
        input-id (c4-artifact-id {:source-path source-path
                                  :module (:module module)
                                  :task "P13-T01-T06"
                                  :documents p13-tooling-documents})
        diagnostic-stream (p13-tooling-diagnostic-stream source-path input-id)
        tooling-artifacts (p13-tooling-artifact-values)
        artifact-base
        (merge
         {:kind :gravity/stage0-tooling-experience-artifact
          :phase "13"
          :task "P13-T01-T06"
          :document-set p13-tooling-documents
          :governing-documents p13-tooling-phase-governing-documents
          :pass {:name :phase13-tooling-experience
                 :input :ordinary-gravity-source
                 :output :tooling-experience
                 :requires p13-tooling-artifact-keys
                 :preserves [:compiler-truth :profile :target :effect
                             :capability :runtime :safety :artifact-lineage
                             :source-spans :redaction-policy
                             :human-review-policy]
                 :emits [:document-contracts :accepted-tooling-fixtures
                         :rejected-tooling-fixtures
                         :tooling-conformance-evidence
                         :tooling-diagnostic-stream]
                 :rejects p13-tooling-diagnostic-ids}
          :source-overrides source-overrides
          :module (select-keys module [:module :source-path :profile :target
                                       :effects :capabilities :safety
                                       :metadata])
          :document-contracts (p13-tooling-document-records)
          :accepted-tooling-fixtures (p13-accepted-tooling-fixtures)
          :rejected-tooling-fixtures (p13-rejected-tooling-fixtures)
          :tooling-conformance-evidence (p13-tooling-conformance-evidence)
          :tooling-diagnostic-stream diagnostic-stream
          :tooling-experience-results
          {:documents p13-tooling-documents
           :tasks (p13-task-statuses)
           :document-contracts 13
           :artifact-families (count p13-tooling-artifact-keys)
           :accepted-fixtures 13
           :rejected-fixtures 13
           :conformance-records 13
           :diagnostic-count (count p13-tooling-diagnostic-ids)
           :status :complete}
          :diagnostics []}
         tooling-artifacts)
        _ (p13-tooling-validate! source-path artifact-base)
        capability-proof (p13-tooling-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn tooling-experience-file-artifact
  [path]
  (tooling-experience-source-artifact path (slurp path)))

