    :diagnostic "STAGE1READER005"
    :rejected-behavior :odd-map-entries}])

(defn stage1-reader-fail!
  [id source-path value data]
  (fail! id
         (get stage1-reader-execution-diagnostic-messages
              id
              "stage1 reader execution failed")
         (merge {:source-span {:source source-path}
                 :stage :stage1-reader-execution
                 :diagnostic-family :stage1-reader-execution
                 :value value
                 :remediation "Keep the reader table in Gravity source, use supported stage1 reader syntax, and preserve source spans and diagnostics."}
                data)))

(defn stage1-reader-classpath-project-root
  []
  (when-let [resource (io/resource "gravity/bootstrap.clj")]
    (when (= "file" (.getProtocol resource))
      (loop [candidate (.getParentFile (.getCanonicalFile (io/file resource)))]
        (when candidate
          (if (.isFile (io/file candidate "deps.edn"))
            candidate
            (recur (.getParentFile candidate))))))))

(defn stage1-reader-owned-source-file
  [logical-path]
  (let [classpath-root (stage1-reader-classpath-project-root)
        candidates (if classpath-root
                     [(io/file classpath-root logical-path)]
                     [(io/file logical-path)])]
    (or (some #(when (.isFile %) (.getCanonicalFile %)) candidates)
        (stage1-reader-fail!
         "STAGE1READER006" logical-path nil
         {:missing-fields [:owned-reader-source]
          :facts {:logical-path logical-path
                  :resolution-bases
                  (if classpath-root
                    [:bootstrap-classpath-root]
                    [:process-working-directory-fallback])}}))))

(defn stage1-reader-table-form
  [source-path]
  (let [source-file (stage1-reader-owned-source-file source-path)
        forms (mapv :form (read-source-form-records source-path
                                                     (slurp source-file)))
        table-form (first (filter #(and (seq? %)
                                        (= 'def (first %))
                                        (= 'stage1-reader-table (second %)))
                                  forms))]
    (when-not (and table-form (= 3 (count table-form)) (map? (nth table-form 2)))
      (stage1-reader-fail! "STAGE1READER006" source-path table-form
                           {:missing-fields [:stage1-reader-table]}))
    (nth table-form 2)))

(defn stage1-reader-validate-table!
  [source-path table]
  (let [diagnostics (:diagnostics table)
        missing (remove #(contains? diagnostics %)
                        [:unexpected-close :unclosed-form :unclosed-string
                         :unsupported-dispatch :odd-map :missing-table])]
    (when-not (= :gravity-reader-table-v1 (:engine table))
      (stage1-reader-fail! "STAGE1READER006" source-path table
                           {:missing-fields [:engine]}))
    (doseq [field [:line-comment :string-delimiter :whitespace :delimiters
                   :dispatch :literal-kinds :diagnostics
                   :accepted-fixture :rejected-fixtures]]
      (when-not (contains? table field)
        (stage1-reader-fail! "STAGE1READER006" source-path table
                             {:missing-fields [field]})))
    (when (seq missing)
      (stage1-reader-fail! "STAGE1READER006" source-path diagnostics
                           {:missing-fields (vec missing)})))
  :complete)

(defn stage1-reader-location
  [source-text line-starts idx]
  (let [idx (min idx (count source-text))
        line-number (loop [line 0]
                      (if (and (< (inc line) (count line-starts))
                               (<= (line-starts (inc line)) idx))
                        (recur (inc line))
                        (inc line)))
        line-start (line-starts (dec line-number))
        line-prefix (subs source-text line-start idx)
        column (inc (.codePointCount line-prefix 0 (.length line-prefix)))]
    {:line line-number
     :column column
     :column-unit :unicode-scalar
     :char idx
     :byte (utf8-byte-count (subs source-text 0 idx))}))

(defn stage1-reader-span
  [source-path source-text line-starts start end]
  (let [start-location (stage1-reader-location source-text line-starts start)
        end-location (stage1-reader-location source-text line-starts end)]
    {:source source-path
     :start start-location
     :end end-location
     :byte-start (:byte start-location)
     :byte-end (:byte end-location)}))

(defn stage1-reader-table
  []
  (let [table (stage1-reader-table-form stage1-reader-source-path)]
    (stage1-reader-validate-table! stage1-reader-source-path table)
    table))

(defn stage1-reader-token-kind
  [token]
  (cond
    (= token "nil") :nil
    (= token "true") :boolean
    (= token "false") :boolean
    (str/starts-with? token ":") :keyword
    (re-matches #"[+-]?(?:0[xX][0-9A-Fa-f]+|0[bB][01]+|[0-9]+)" token)
    :integer
    (re-matches #"[+-]?[0-9]+/[0-9]+" token) :ratio
    (re-matches #"[+-]?(?:(?:(?:[0-9]+\.[0-9]*)|(?:[0-9]*\.[0-9]+))(?:[eE][+-]?[0-9]+)?|(?:[0-9]+[eE][+-]?[0-9]+))"
                token)
    :decimal
    (re-find #"^[+-]?[0-9]" token) :malformed-number
    :else :symbol))

(defn stage1-reader-malformed-numeric!
  [source-path raw span token-id cause]
  (stage1-reader-fail!
   "STAGE1READER007" source-path raw
   {:source-span span
    :token-id token-id
    :raw raw
    :cause-message cause
    :facts {:literal-kind :numeric
            :raw-spelling raw}}))

(defn stage1-reader-decode-atom
  [source-path kind raw span token-id]
  (try
    (case kind
      :nil nil
      :boolean (= "true" raw)
      :keyword (keyword (subs raw 1))
      :integer
      (let [negative? (str/starts-with? raw "-")
            positive? (str/starts-with? raw "+")
            unsigned (if (or negative? positive?) (subs raw 1) raw)
            [radix digits] (cond
                             (re-find #"^0[xX]" unsigned)
                             [16 (subs unsigned 2)]
                             (re-find #"^0[bB]" unsigned)
                             [2 (subs unsigned 2)]
                             :else [10 unsigned])
            value (bigint (java.math.BigInteger. digits radix))]
        (if negative? (- value) value))
      :ratio
      (let [[numerator-spelling denominator-spelling] (str/split raw #"/" 2)
            numerator (bigint numerator-spelling)
            denominator (bigint denominator-spelling)]
        (if (zero? denominator)
          {:artifact :gravity/deferred-ratio-literal
           :kind :ratio
           :raw raw
           :numerator-spelling numerator-spelling
           :denominator-spelling denominator-spelling
           :numerator numerator
           :denominator denominator
           :semantic-validation :deferred
           :reason :zero-denominator}
          (/ numerator denominator)))
      :decimal (Double/parseDouble raw)
      :malformed-number
      (stage1-reader-malformed-numeric!
       source-path raw span token-id
       "numeric lexeme does not match a declared Gravity numeric shape")
      :symbol (symbol raw)
      raw)
    (catch NumberFormatException ex
      (stage1-reader-malformed-numeric! source-path raw span token-id
                                        (.getMessage ex)))
    (catch ArithmeticException ex
      (stage1-reader-malformed-numeric! source-path raw span token-id
                                        (.getMessage ex)))))

(defn stage1-reader-decode-string
  [source-path raw span token-id]
  (try
    (binding [*read-eval* false]
      (read-string raw))
    (catch Exception ex
      (stage1-reader-fail! "STAGE1READER003" source-path raw
                           {:source-span span
                            :token-id token-id
                            :raw raw
                            :cause-message (.getMessage ex)}))))

(defn stage1-reader-decode-character
  [source-path raw span token-id]
  (try
    (let [value (binding [*read-eval* false]
                  (read-string raw))]
      (when-not (char? value)
        (throw (ex-info "reader character token did not decode to a character"
                        {:raw raw})))
      value)
    (catch Exception ex
      (stage1-reader-fail! "STAGE1READER003" source-path raw
                           {:source-span span
                            :token-id token-id
                            :raw raw
                            :cause-message (.getMessage ex)}))))

(defn stage1-reader-token-stream
  ([source-path source-text table]
   (stage1-reader-token-stream source-path source-text table
                               {:retain-comments false}))
  ([source-path source-text table reader-options]
  (let [line-starts (line-start-indices source-text)
        whitespace (set (:whitespace table))
        delimiters (:delimiters table)
        dispatch (:dispatch table)
        comment-marker (:line-comment table)
        string-delimiter (:string-delimiter table)
        retain-trivia? (true? (:retain-comments reader-options))
        source-length (count source-text)
        table-id (str "sha256:" (sha256-hex (pr-str table)))]
    (letfn [(char-string [idx]
              (str (.charAt source-text idx)))
            (ignored? [idx]
              (and (< idx source-length)
                   (contains? whitespace (char-string idx))))
            (comment? [idx]
              (and (< idx source-length)
                   (= comment-marker (char-string idx))))
            (skip-ignored [idx]
              (loop [idx idx]
                (cond
                  (>= idx source-length) idx
                  (ignored? idx) (recur (inc idx))
                  (comment? idx) (recur (loop [j idx]
                                          (if (and (< j source-length)
                                                   (not (line-terminator-char?
                                                         (.charAt source-text j))))
                                            (recur (inc j))
                                            j)))
                  :else idx)))
            (read-whitespace-token [idx token-index]
              (let [end (loop [end idx]
                          (if (and (< end source-length) (ignored? end))
                            (recur (inc end))
                            end))
                    raw (subs source-text idx end)]
                [{:index token-index
                  :kind :whitespace
                  :lexeme raw
                  :raw raw
                  :decoded nil
                  :trivia? true
                  :span (stage1-reader-span source-path source-text
                                            line-starts idx end)}
                 end]))
            (read-comment-token [idx token-index]
              (let [end (loop [end idx]
                          (if (and (< end source-length)
                                   (not (line-terminator-char?
                                         (.charAt source-text end))))
                            (recur (inc end))
                            end))
                    raw (subs source-text idx end)]
                [{:index token-index
                  :kind :comment
                  :lexeme raw
                  :raw raw
                  :decoded nil
                  :trivia? true
                  :span (stage1-reader-span source-path source-text
                                            line-starts idx end)}
                 end]))
            (read-string-token [idx token-index]
              (let [start idx]
                (loop [idx (inc idx)]
                  (cond
                    (>= idx source-length)
                    (stage1-reader-fail! "STAGE1READER003" source-path nil
                                         {:source-span
                                          (stage1-reader-span source-path
                                                              source-text
                                                              line-starts
                                                              start idx)
                                          :token-id
                                          (keyword (str "tok-" token-index))
                                          :raw (subs source-text start idx)})

                    (= string-delimiter (char-string idx))
                    (let [end (inc idx)
                          raw (subs source-text start end)
                          span (stage1-reader-span source-path source-text
                                                  line-starts start end)
                          decoded (stage1-reader-decode-string source-path
                                                               raw span
                                                               (keyword
                                                                (str "tok-"
                                                                     token-index)))]
                      [{:index token-index
                        :kind :string
                        :lexeme decoded
                        :raw raw
                        :decoded decoded
                        :span span}
                       end])

                    (= \\ (.charAt source-text idx))
                    (if (< (inc idx) source-length)
                      (recur (+ idx 2))
                      (stage1-reader-fail! "STAGE1READER003" source-path nil
                                           {:source-span
                                            (stage1-reader-span source-path
                                                                source-text
                                                                line-starts
                                                                start idx)
                                            :token-id
                                            (keyword (str "tok-" token-index))
                                            :raw (subs source-text start idx)}))
                    :else (recur (inc idx))))))
            (atom-end [idx]
              (loop [idx idx]
                (if (or (>= idx source-length)
                        (ignored? idx)
                        (comment? idx)
                        (= string-delimiter (char-string idx))
                        (contains? #{"'" "`" "~" "^" "@" "\\"}
                                   (char-string idx))
                        (contains? delimiters (char-string idx))
                        (contains? dispatch (char-string idx)))
                  idx
                  (recur (inc idx)))))
            (read-atom-token [idx token-index]
              (let [start idx
                    end (atom-end idx)
                    token (subs source-text start end)
                    kind (stage1-reader-token-kind token)
                    token-id (keyword (str "tok-" token-index))
                    span (stage1-reader-span source-path source-text
                                             line-starts start end)]
                [{:index token-index
                  :kind kind
                  :lexeme token
                  :raw token
                  :decoded (stage1-reader-decode-atom source-path kind token
                                                      span token-id)
                  :span span}
                 end]))
            (read-character-token [idx token-index]
              (let [word-start (inc idx)
                    end (cond
                          (>= word-start source-length) word-start
                          (or (ignored? word-start)
                              (comment? word-start)) word-start
                          (contains? delimiters (char-string word-start))
                          (inc word-start)
                          :else (atom-end word-start))
                    raw (subs source-text idx end)
                    span (stage1-reader-span source-path source-text
                                             line-starts idx end)
                    decoded (stage1-reader-decode-character source-path
                                                             raw span
                                                             (keyword
                                                              (str "tok-"
                                                                   token-index)))]
                [{:index token-index
                  :kind :character
                  :lexeme decoded
                  :raw raw
                  :decoded decoded
                  :span span}
                 end]))
            (read-abbreviation-token [idx token-index]
              (let [splice? (and (= "~" (char-string idx))
                                 (< (inc idx) source-length)
                                 (= "@" (char-string (inc idx))))
                    end (+ idx (if splice? 2 1))
                    raw (subs source-text idx end)
                    abbrev (case raw
                             "'" :quote
                             "`" :syntax-quote
                             "~" :unquote
                             "~@" :splice-unquote
                             "^" :metadata
                             "@" :deref)]
                [{:index token-index
                  :kind :abbreviation
                  :abbrev abbrev
                  :lexeme raw
                  :raw raw
                  :decoded abbrev
                  :span (stage1-reader-span source-path source-text
                                            line-starts idx end)}
                 end]))
            (read-dispatch-token [idx token-index]
              (let [dispatch-token (char-string idx)
                    next-token (when (< (inc idx) source-length)
                                 (char-string (inc idx)))
                    dispatch-entry (get-in dispatch [dispatch-token next-token])]
                (if (= :set-open (:kind dispatch-entry))
                  (let [end (+ idx 2)]
                    [{:index token-index
                      :kind (:kind dispatch-entry)
                      :lexeme (str dispatch-token next-token)
                      :raw (str dispatch-token next-token)
                      :decoded :set
                      :dispatch dispatch-token
                      :close-token (:closes dispatch-entry)
                      :span (stage1-reader-span source-path source-text
                                                line-starts idx end)}
                     end])
                  (let [end (atom-end (inc idx))
                        raw (subs source-text idx end)
                        tag (subs raw 1)]
                    (if (contains? #{"inst" "uuid"} tag)
                      [{:index token-index
                        :kind :tag
                        :tag (symbol tag)
                        :lexeme raw
                        :raw raw
                        :decoded (symbol tag)
                        :span (stage1-reader-span source-path source-text
                                                  line-starts idx end)}
                       end]
                      (stage1-reader-fail!
                       "STAGE1READER004" source-path dispatch-token
                       {:source-span
                        (stage1-reader-span source-path source-text
                                            line-starts idx
                                            (min source-length
                                                 (max (inc idx) end)))
                        :token-id (keyword (str "tok-" token-index))
                        :raw raw
                        :extension-tag (when (seq tag) (symbol tag))}))))))
            (read-delimiter-token [idx token-index delimiter]
              (let [token (char-string idx)]
                [{:index token-index
                  :kind (:kind delimiter)
                  :lexeme token
                  :raw token
                  :decoded token
                  :close-token (:closes delimiter)
                  :span (stage1-reader-span source-path source-text
                                            line-starts idx (inc idx))}
                 (inc idx)]))]
      (loop [idx 0
             token-index 0
             tokens []]
        (let [idx (if retain-trivia? idx (skip-ignored idx))]
          (if (>= idx source-length)
            {:kind :gravity/stage1-reader-token-stream
             :source-path source-path
             :source-id (str "sha256:" (sha256-hex source-text))
             :reader-table-id table-id
             :token-count (count tokens)
             :tokens tokens
             :status :complete}
            (let [token (char-string idx)
                  delimiter (get delimiters token)
                  [token-record next-idx]
                  (cond
                    (and retain-trivia? (ignored? idx))
                    (read-whitespace-token idx token-index)

                    (and retain-trivia? (comment? idx))
                    (read-comment-token idx token-index)

                    (= string-delimiter token)
                    (read-string-token idx token-index)

                    (= "\\" token)
                    (read-character-token idx token-index)

                    (contains? #{"'" "`" "~" "^" "@"} token)
                    (read-abbreviation-token idx token-index)

                    (contains? dispatch token)
                    (read-dispatch-token idx token-index)

                    delimiter
                    (read-delimiter-token idx token-index delimiter)

                    :else
                    (read-atom-token idx token-index))]
              (recur next-idx
                     (inc token-index)
                     (conj tokens token-record))))))))))

(declare stage1-reader-character-pipeline-fail!
         stage1-reader-token-classifier-pipeline-fail!
         stage1-reader-token-realizer-pipeline-fail!
         stage1-reader-token-automaton-pipeline-fail!
         stage1-reader-form-builder-pipeline-fail!
         stage1-reader-executor-pipeline-fail!
         stage1-reader-runtime-pipeline-fail!
         stage1-reader-compiled-pipeline-fail!
         stage1-reader-binary-pipeline-fail!
         stage1-reader-self-hosted-runtime-fail!
         stage1-reader-core-bootstrap-fail!
         stage1-reader-compiler-driver-fail!
         stage1-reader-runtime-entrypoint-fail!
         stage1-reader-runtime-image-fail!
         stage1-reader-verified-boot-chain-fail!
         stage1-reader-diverse-bootstrap-verification-fail!
         stage1-reader-release-attestation-seed-retirement-fail!
         stage1-reader-pipeline-fail!
         reader-canonical-hash
         ^:dynamic *stage1-reader-pipeline-trace*)

(defn stage1-reader-character-stream
  [source-path source-text]
  (let [line-starts (line-start-indices source-text)
        source-id (str "sha256:" (sha256-hex source-text))
        source-length (count source-text)
        characters
        (loop [char-offset 0
               scalar-index 0
               records []]
          (if (>= char-offset source-length)
            records
            (let [codepoint (.codePointAt source-text char-offset)
                  char-width (Character/charCount codepoint)
                  end-offset (+ char-offset char-width)
                  raw (subs source-text char-offset end-offset)]
              (recur end-offset
                     (inc scalar-index)
                     (conj records
                           {:index scalar-index
                            :char raw
                            :raw raw
                            :codepoint codepoint
                            :span (stage1-reader-span
                                   source-path source-text line-starts
                                   char-offset end-offset)})))))]
    {:kind :gravity/stage1-reader-character-stream
     :source-path source-path
     :source-id source-id
     :character-count (count characters)
     :utf16-unit-count source-length
     :characters characters
     :status :complete}))

(defn stage1-reader-token-stream-from-characters
  [source-path source-text table character-stream]
  (let [source-id (str "sha256:" (sha256-hex source-text))
        characters (:characters character-stream)]
    (when-not (= :gravity/stage1-reader-character-stream
                 (:kind character-stream))
      (stage1-reader-character-pipeline-fail! "STAGE1CHAR004" source-path
                                              character-stream
                                              {:missing-fields [:kind]}))
    (when-not (= source-path (:source-path character-stream))
      (stage1-reader-character-pipeline-fail! "STAGE1CHAR004" source-path
                                              character-stream
                                              {:missing-fields [:source-path]}))
    (when-not (= source-id (:source-id character-stream))
      (stage1-reader-character-pipeline-fail! "STAGE1CHAR004" source-path
                                              character-stream
                                              {:missing-fields [:source-id]}))
    (when-not (and (vector? characters)
                   (= (count characters)
                      (:character-count character-stream)))
      (stage1-reader-character-pipeline-fail! "STAGE1CHAR004" source-path
                                              character-stream
                                              {:missing-fields
                                               [:characters
                                                :character-count]}))
    (let [source-from-characters (apply str (map :char characters))]
      (when-not (= source-text source-from-characters)
        (stage1-reader-character-pipeline-fail! "STAGE1CHAR004" source-path
                                                character-stream
                                                {:missing-fields
                                                 [:source-character-parity]}))
      (stage1-reader-token-stream source-path source-from-characters table))))

(defn stage1-reader-table-from-token-classifier
  [source-path classifier]
  (let [diagnostics (:diagnostics classifier)
        missing (remove #(contains? diagnostics %)
                        [:unexpected-close :unclosed-form :unclosed-string
                         :unsupported-dispatch :odd-map
                         :invalid-classifier])]
    (when-not (= :gravity-reader-token-classifier-v1 (:engine classifier))
      (stage1-reader-token-classifier-pipeline-fail!
       "STAGE1CLASS004" source-path classifier
       {:missing-fields [:engine]}))
    (doseq [field [:derived-from :whitespace :line-comment :string-delimiter
                   :delimiters :dispatch :literal-kinds :diagnostics
                   :provenance]]
      (when-not (contains? classifier field)
        (stage1-reader-token-classifier-pipeline-fail!
         "STAGE1CLASS004" source-path classifier
         {:missing-fields [field]})))
    (when-not (= :stage1-reader-table (:derived-from classifier))
      (stage1-reader-token-classifier-pipeline-fail!
       "STAGE1CLASS004" source-path classifier
       {:missing-fields [:derived-from]}))
    (when (seq missing)
      (stage1-reader-token-classifier-pipeline-fail!
       "STAGE1CLASS004" source-path diagnostics
       {:missing-fields (vec missing)}))
    {:engine :gravity-reader-table-v1
     :line-comment (:line-comment classifier)
     :string-delimiter (:string-delimiter classifier)
     :whitespace (:whitespace classifier)
     :delimiters (:delimiters classifier)
     :dispatch (:dispatch classifier)
     :literal-kinds (:literal-kinds classifier)
     :diagnostics (assoc (select-keys diagnostics
                                      [:unexpected-close :unclosed-form
                                       :unclosed-string :unsupported-dispatch
                                       :odd-map])
                         :missing-table "STAGE1READER006")
     :accepted-fixture "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
     :rejected-fixtures {"bootstrap/clojure/fixtures/rejected/stage1-reader-unexpected-close.gravity"
                         "STAGE1READER001"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unclosed-list.gravity"
                         "STAGE1READER002"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unclosed-string.gravity"
                         "STAGE1READER003"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unsupported-dispatch.gravity"
                         "STAGE1READER004"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-odd-map.gravity"
                         "STAGE1READER005"}}))

(defn stage1-reader-token-stream-from-classifier
  [source-path source-text classifier character-stream]
  (let [source-id (str "sha256:" (sha256-hex source-text))
        characters (:characters character-stream)
        table (stage1-reader-table-from-token-classifier source-path
                                                         classifier)]
    (when-not (= :gravity/stage1-reader-character-stream
                 (:kind character-stream))
      (stage1-reader-token-classifier-pipeline-fail!
       "STAGE1CLASS004" source-path character-stream
       {:missing-fields [:kind]}))
    (when-not (= source-path (:source-path character-stream))
      (stage1-reader-token-classifier-pipeline-fail!
       "STAGE1CLASS004" source-path character-stream
       {:missing-fields [:source-path]}))
    (when-not (= source-id (:source-id character-stream))
      (stage1-reader-token-classifier-pipeline-fail!
       "STAGE1CLASS004" source-path character-stream
       {:missing-fields [:source-id]}))
    (when-not (and (vector? characters)
                   (= (count characters)
                      (:character-count character-stream)))
      (stage1-reader-token-classifier-pipeline-fail!
       "STAGE1CLASS004" source-path character-stream
       {:missing-fields [:characters :character-count]}))
    (let [source-from-characters (apply str (map :char characters))]
      (when-not (= source-text source-from-characters)
        (stage1-reader-token-classifier-pipeline-fail!
         "STAGE1CLASS004" source-path character-stream
         {:missing-fields [:source-character-parity]}))
      (stage1-reader-token-stream source-path source-from-characters table))))

(defn stage1-reader-table-from-token-realizer
  [source-path classifier realizer]
  (let [classifier-diagnostics (:diagnostics classifier)
        realizer-diagnostics (:diagnostics realizer)
        missing-classifier (remove #(contains? classifier-diagnostics %)
                                   [:unexpected-close :unclosed-form
                                    :unclosed-string :unsupported-dispatch
                                    :odd-map :invalid-classifier])
        missing-realizer (remove #(contains? realizer-diagnostics %)
                                 [:unexpected-close :unclosed-form
                                  :unclosed-string :unsupported-dispatch
                                  :odd-map :invalid-realizer])]
    (when-not (= :gravity-reader-token-classifier-v1 (:engine classifier))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path classifier
       {:missing-fields [:classifier-engine]}))
    (doseq [field [:derived-from :whitespace :line-comment :string-delimiter
                   :delimiters :dispatch :literal-kinds :diagnostics
                   :provenance]]
      (when-not (contains? classifier field)
        (stage1-reader-token-realizer-pipeline-fail!
         "STAGE1REAL004" source-path classifier
         {:missing-fields [field]})))
    (when-not (= :stage1-reader-table (:derived-from classifier))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path classifier
       {:missing-fields [:classifier-derived-from]}))
    (when (seq missing-classifier)
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path classifier-diagnostics
       {:missing-fields (vec missing-classifier)}))
    (when-not (= :gravity-reader-token-realizer-v1 (:engine realizer))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path realizer
       {:missing-fields [:engine]}))
    (doseq [field [:derived-from :classifier-engine :table-derived-from
                   :emits :token-record-fields :preserves :diagnostics
                   :provenance]]
      (when-not (contains? realizer field)
        (stage1-reader-token-realizer-pipeline-fail!
         "STAGE1REAL004" source-path realizer
         {:missing-fields [field]})))
    (when-not (= :stage1-reader-token-classifier (:derived-from realizer))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path realizer
       {:missing-fields [:derived-from]}))
    (when-not (= (:engine classifier) (:classifier-engine realizer))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path realizer
       {:missing-fields [:classifier-engine]}))
    (when-not (= :stage1-reader-table (:table-derived-from realizer))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path realizer
       {:missing-fields [:table-derived-from]}))
    (when-not (= :gravity/stage1-reader-token-stream (:emits realizer))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path realizer
       {:missing-fields [:emits]}))
    (when (seq missing-realizer)
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path realizer-diagnostics
       {:missing-fields (vec missing-realizer)}))
    {:engine :gravity-reader-table-v1
     :line-comment (:line-comment classifier)
     :string-delimiter (:string-delimiter classifier)
     :whitespace (:whitespace classifier)
     :delimiters (:delimiters classifier)
     :dispatch (:dispatch classifier)
     :literal-kinds (:literal-kinds classifier)
     :diagnostics (assoc (select-keys classifier-diagnostics
                                      [:unexpected-close :unclosed-form
                                       :unclosed-string :unsupported-dispatch
                                       :odd-map])
                         :missing-table "STAGE1READER006")
     :accepted-fixture "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
     :rejected-fixtures {"bootstrap/clojure/fixtures/rejected/stage1-reader-unexpected-close.gravity"
                         "STAGE1READER001"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unclosed-list.gravity"
                         "STAGE1READER002"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unclosed-string.gravity"
                         "STAGE1READER003"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unsupported-dispatch.gravity"
                         "STAGE1READER004"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-odd-map.gravity"
                         "STAGE1READER005"}}))

(defn stage1-reader-token-stream-from-realizer
  [source-path source-text classifier realizer character-stream]
  (let [source-id (str "sha256:" (sha256-hex source-text))
        characters (:characters character-stream)
        table (stage1-reader-table-from-token-realizer source-path
                                                       classifier
                                                       realizer)]
    (when-not (= :gravity/stage1-reader-character-stream
                 (:kind character-stream))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path character-stream
       {:missing-fields [:kind]}))
    (when-not (= source-path (:source-path character-stream))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path character-stream
       {:missing-fields [:source-path]}))
    (when-not (= source-id (:source-id character-stream))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path character-stream
       {:missing-fields [:source-id]}))
    (when-not (and (vector? characters)
                   (= (count characters)
                      (:character-count character-stream)))
      (stage1-reader-token-realizer-pipeline-fail!
       "STAGE1REAL004" source-path character-stream
       {:missing-fields [:characters :character-count]}))
    (let [source-from-characters (apply str (map :char characters))]
      (when-not (= source-text source-from-characters)
        (stage1-reader-token-realizer-pipeline-fail!
         "STAGE1REAL004" source-path character-stream
         {:missing-fields [:source-character-parity]}))
      (stage1-reader-token-stream source-path source-from-characters table))))

(defn stage1-reader-table-from-token-automaton
  [source-path classifier realizer automaton]
  (let [classifier-diagnostics (:diagnostics classifier)
        realizer-diagnostics (:diagnostics realizer)
        automaton-diagnostics (:diagnostics automaton)
        missing-classifier (remove #(contains? classifier-diagnostics %)
                                   [:unexpected-close :unclosed-form
                                    :unclosed-string :unsupported-dispatch
                                    :odd-map :invalid-classifier])
        missing-realizer (remove #(contains? realizer-diagnostics %)
                                 [:unexpected-close :unclosed-form
                                  :unclosed-string :unsupported-dispatch
                                  :odd-map :invalid-realizer])
        missing-automaton (remove #(contains? automaton-diagnostics %)
                                  [:unexpected-close :unclosed-form
                                   :unclosed-string :unsupported-dispatch
                                   :odd-map :invalid-automaton])
        required-states #{:scan :line-comment :string :atom :dispatch :done}
        required-operations #{:skip-whitespace :skip-line-comment
                              :read-string-token :read-dispatch-token
                              :read-delimiter-token :read-atom-token}]
    (when-not (= :gravity-reader-token-classifier-v1 (:engine classifier))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path classifier
       {:missing-fields [:classifier-engine]}))
    (doseq [field [:derived-from :whitespace :line-comment :string-delimiter
                   :delimiters :dispatch :literal-kinds :diagnostics
                   :provenance]]
      (when-not (contains? classifier field)
        (stage1-reader-token-automaton-pipeline-fail!
         "STAGE1AUTO004" source-path classifier
         {:missing-fields [field]})))
    (when-not (= :stage1-reader-table (:derived-from classifier))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path classifier
       {:missing-fields [:classifier-derived-from]}))
    (when (seq missing-classifier)
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path classifier-diagnostics
       {:missing-fields (vec missing-classifier)}))
    (when-not (= :gravity-reader-token-realizer-v1 (:engine realizer))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path realizer
       {:missing-fields [:realizer-engine]}))
    (doseq [field [:derived-from :classifier-engine :table-derived-from
                   :emits :token-record-fields :preserves :diagnostics
                   :provenance]]
      (when-not (contains? realizer field)
        (stage1-reader-token-automaton-pipeline-fail!
         "STAGE1AUTO004" source-path realizer
         {:missing-fields [field]})))
    (when-not (= :stage1-reader-token-classifier (:derived-from realizer))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path realizer
       {:missing-fields [:realizer-derived-from]}))
    (when-not (= (:engine classifier) (:classifier-engine realizer))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path realizer
       {:missing-fields [:realizer-classifier-engine]}))
    (when-not (= :stage1-reader-table (:table-derived-from realizer))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path realizer
       {:missing-fields [:table-derived-from]}))
    (when-not (= :gravity/stage1-reader-token-stream (:emits realizer))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path realizer
       {:missing-fields [:realizer-emits]}))
    (when (seq missing-realizer)
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path realizer-diagnostics
       {:missing-fields (vec missing-realizer)}))
    (when-not (= :gravity-reader-token-automaton-v1 (:engine automaton))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path automaton
       {:missing-fields [:engine]}))
    (doseq [field [:derived-from :classifier-engine :realizer-engine
                   :input :emits :states :operations :token-record-fields
                   :preserves :diagnostics :provenance]]
      (when-not (contains? automaton field)
        (stage1-reader-token-automaton-pipeline-fail!
         "STAGE1AUTO004" source-path automaton
         {:missing-fields [field]})))
    (when-not (= :stage1-reader-token-realizer (:derived-from automaton))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path automaton
       {:missing-fields [:derived-from]}))
    (when-not (= (:engine classifier) (:classifier-engine automaton))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path automaton
       {:missing-fields [:classifier-engine]}))
    (when-not (= (:engine realizer) (:realizer-engine automaton))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path automaton
       {:missing-fields [:realizer-engine]}))
    (when-not (= :gravity/stage1-reader-character-stream (:input automaton))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path automaton
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-token-stream (:emits automaton))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path automaton
       {:missing-fields [:emits]}))
    (when-not (set/subset? required-states (set (:states automaton)))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path automaton
       {:missing-fields [:states]}))
    (when-not (set/subset? required-operations (set (:operations automaton)))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path automaton
       {:missing-fields [:operations]}))
    (when (seq missing-automaton)
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path automaton-diagnostics
       {:missing-fields (vec missing-automaton)}))
    {:engine :gravity-reader-table-v1
     :line-comment (:line-comment classifier)
     :string-delimiter (:string-delimiter classifier)
     :whitespace (:whitespace classifier)
     :delimiters (:delimiters classifier)
     :dispatch (:dispatch classifier)
     :literal-kinds (:literal-kinds classifier)
     :diagnostics (assoc (select-keys classifier-diagnostics
                                      [:unexpected-close :unclosed-form
                                       :unclosed-string :unsupported-dispatch
                                       :odd-map])
                         :missing-table "STAGE1READER006")
     :accepted-fixture "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
     :rejected-fixtures {"bootstrap/clojure/fixtures/rejected/stage1-reader-unexpected-close.gravity"
                         "STAGE1READER001"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unclosed-list.gravity"
                         "STAGE1READER002"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unclosed-string.gravity"
                         "STAGE1READER003"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unsupported-dispatch.gravity"
                         "STAGE1READER004"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-odd-map.gravity"
                         "STAGE1READER005"}}))

(defn stage1-reader-token-stream-from-automaton
  [source-path source-text classifier realizer automaton character-stream]
  (let [source-id (str "sha256:" (sha256-hex source-text))
        characters (:characters character-stream)
        table (stage1-reader-table-from-token-automaton source-path classifier
                                                        realizer automaton)]
    (when-not (= :gravity/stage1-reader-character-stream
                 (:kind character-stream))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path character-stream
       {:missing-fields [:kind]}))
    (when-not (= source-path (:source-path character-stream))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path character-stream
       {:missing-fields [:source-path]}))
    (when-not (= source-id (:source-id character-stream))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path character-stream
       {:missing-fields [:source-id]}))
    (when-not (and (vector? characters)
                   (= (count characters)
                      (:character-count character-stream)))
      (stage1-reader-token-automaton-pipeline-fail!
       "STAGE1AUTO004" source-path character-stream
       {:missing-fields [:characters :character-count]}))
    (let [source-from-characters (apply str (map :char characters))]
      (when-not (= source-text source-from-characters)
        (stage1-reader-token-automaton-pipeline-fail!
         "STAGE1AUTO004" source-path character-stream
         {:missing-fields [:source-character-parity]}))
      (let [automaton-id (str "sha256:" (sha256-hex (pr-str automaton)))
            base-stream (stage1-reader-token-stream source-path
                                                    source-from-characters table)
            tokens
            (mapv (fn [token]
                    (let [[operation state]
                          (case (:kind token)
                            :string [:read-string-token :string]
                            :set-open [:read-dispatch-token :dispatch]
                            :tag [:read-dispatch-token :dispatch]
                            :list-open [:read-delimiter-token :scan]
                            :vector-open [:read-delimiter-token :scan]
                            :map-open [:read-delimiter-token :scan]
                            :close [:read-delimiter-token :scan]
                            [:read-atom-token :atom])]
                      (assoc token
                             :operation operation
                             :automaton-state state)))
                  (:tokens base-stream))]
        (assoc base-stream
               :token-automaton-id automaton-id
               :token-automaton-engine (:engine automaton)
               :executed-operations (vec (distinct (map :operation tokens)))
               :tokens tokens
               :token-count (count tokens))))))
(defn stage1-reader-table-driven-records
  [source-path source-text table]
  (let [line-starts (line-start-indices source-text)
        whitespace (set (:whitespace table))
        delimiters (:delimiters table)
        dispatch (:dispatch table)
        comment-marker (:line-comment table)
        string-delimiter (:string-delimiter table)
        source-length (count source-text)]
    (letfn [(char-string [idx]
              (str (.charAt source-text idx)))
            (ignored? [idx]
              (and (< idx source-length)
                   (contains? whitespace (char-string idx))))
            (comment? [idx]
              (and (< idx source-length)
                   (= comment-marker (char-string idx))))
            (skip-ignored [idx]
              (loop [idx idx]
                (cond
                  (>= idx source-length) idx
                  (ignored? idx) (recur (inc idx))
                  (comment? idx) (recur (loop [j idx]
                                          (if (and (< j source-length)
                                                   (not (line-terminator-char?
                                                         (.charAt source-text j))))
                                            (recur (inc j))
                                            j)))
                  :else idx)))
            (close-token? [idx close-token]
              (and (< idx source-length)
                   (= close-token (char-string idx))))
            (unexpected-close? [idx]
              (and (< idx source-length)
                   (= :close (get-in delimiters [(char-string idx) :kind]))))
            (read-string-literal [idx]
              (let [start idx
                    builder (StringBuilder.)]
                (loop [idx (inc idx)]
                  (cond
                    (>= idx source-length)
                    (stage1-reader-fail! "STAGE1READER003" source-path nil
                                         {:source-span
                                          (stage1-reader-span source-path
                                                              source-text
                                                              line-starts
                                                              start idx)})

                    (= string-delimiter (char-string idx))
                    [(.toString builder)
                     (inc idx)
                     (stage1-reader-span source-path source-text
                                         line-starts start (inc idx))]

                    (= \\ (.charAt source-text idx))
                    (if (< (inc idx) source-length)
                      (do
                        (.append builder (.charAt source-text (inc idx)))
                        (recur (+ idx 2)))
                      (stage1-reader-fail! "STAGE1READER003" source-path nil
                                           {:source-span
                                            (stage1-reader-span source-path
                                                                source-text
                                                                line-starts
                                                                start idx)}))

                    :else
                    (do
                      (.append builder (.charAt source-text idx))
                      (recur (inc idx)))))))
            (atom-end [idx]
              (loop [idx idx]
                (if (or (>= idx source-length)
                        (ignored? idx)
                        (comment? idx)
                        (contains? delimiters (char-string idx))
                        (contains? dispatch (char-string idx)))
                  idx
                  (recur (inc idx)))))
            (parse-atom [token]
              (cond
                (= token "nil") nil
                (= token "true") true
                (= token "false") false
                (str/starts-with? token ":") (keyword (subs token 1))
                (re-matches #"-?[0-9]+" token) (Long/parseLong token)
                :else (symbol token)))
            (read-atom [idx]
              (let [start idx
                    end (atom-end idx)
                    token (subs source-text start end)]
                [(parse-atom token)
                 end
                 (stage1-reader-span source-path source-text
                                     line-starts start end)]))
            (read-delimited [idx collection-kind close-token]
              (let [start idx]
                (loop [idx (inc idx)
                       values []]
                  (let [idx (skip-ignored idx)]
                    (cond
                      (>= idx source-length)
                      (stage1-reader-fail! "STAGE1READER002" source-path nil
                                           {:source-span
                                            (stage1-reader-span source-path
                                                                source-text
                                                                line-starts
                                                                start idx)
                                            :expected close-token})

                      (close-token? idx close-token)
                      (let [end (inc idx)
                            value (case collection-kind
                                    :list (apply list values)
                                    :vector (vec values)
                                    :set (set values)
                                    :map (do
                                           (when (odd? (count values))
                                             (stage1-reader-fail!
                                              "STAGE1READER005" source-path values
                                              {:source-span
                                               (stage1-reader-span
                                                source-path source-text
                                                line-starts start end)}))
                                           (apply hash-map values)))]
                        [value
                         end
                         (stage1-reader-span source-path source-text
                                             line-starts start end)])

                      :else
                      (let [[value next-idx _span] (read-form idx)]
                        (recur next-idx (conj values value))))))))
            (read-dispatch [idx]
              (let [dispatch-token (char-string idx)
                    next-token (when (< (inc idx) source-length)
                                 (char-string (inc idx)))
                    dispatch-entry (get-in dispatch [dispatch-token next-token])]
                (if (= :set-open (:kind dispatch-entry))
                  (let [[value next-idx span]
                        (read-delimited (inc idx) :set (:closes dispatch-entry))]
                    [value next-idx (assoc span :dispatch dispatch-token)])
                  (stage1-reader-fail! "STAGE1READER004" source-path dispatch-token
                                       {:source-span
                                        (stage1-reader-span source-path
                                                            source-text
                                                            line-starts
                                                            idx
                                                            (min source-length
                                                                 (+ idx 2)))}))))
            (read-form [idx]
              (let [idx (skip-ignored idx)]
                (when (>= idx source-length)
                  (stage1-reader-fail! "STAGE1READER002" source-path nil
                                       {:source-span
                                        (stage1-reader-span source-path
                                                            source-text
                                                            line-starts
                                                            idx idx)}))
                (let [token (char-string idx)
                      delimiter (get delimiters token)]
                  (cond
                    (unexpected-close? idx)
                    (stage1-reader-fail! "STAGE1READER001" source-path token
                                         {:source-span
                                          (stage1-reader-span source-path
                                                              source-text
                                                              line-starts
                                                              idx (inc idx))})

                    (= string-delimiter token)
                    (read-string-literal idx)

                    (= :list-open (:kind delimiter))
                    (read-delimited idx :list (:closes delimiter))

                    (= :vector-open (:kind delimiter))
                    (read-delimited idx :vector (:closes delimiter))

                    (= :map-open (:kind delimiter))
                    (read-delimited idx :map (:closes delimiter))

                    (contains? dispatch token)
                    (read-dispatch idx)

                    :else
                    (read-atom idx)))))]
      (loop [idx 0
             form-index 0
             records []]
        (let [idx (skip-ignored idx)]
          (if (>= idx source-length)
            records
            (let [[form next-idx span] (read-form idx)]
              (recur next-idx
                     (inc form-index)
                     (conj records
                           {:form form
                            :kind (form-kind form)
                            :span (assoc span :form-index form-index)})))))))))

(defn stage1-reader-execution-diagnostic-stream
  [source-path table-id]
  {:artifact :gravity/stage1-reader-execution-diagnostic-stream
   :stage :stage1-reader-execution
   :source-path source-path
   :reader-table-id table-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-execution
            :artifact :gravity/diagnostic
            :message (stage1-reader-execution-diagnostic-messages id)})
         stage1-reader-execution-diagnostic-ids)
   :status :complete})

(defn stage1-reader-execution-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:stage1-reader-diagnostic-stream
                                       :diagnostics])))]
    {:gravity-reader-table-used?
     (= :gravity.bootstrap.reader/stage1-reader-table
        (:reader-table-symbol artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :top-level-count-matches?
     (true? (get-in artifact [:stage0-comparison
                              :top-level-count-matches?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) (:stage1-reader-records artifact))
     :diagnostics-covered?
     (set/subset? (set (butlast stage1-reader-execution-diagnostic-ids))
                  diagnostics)
     :limitations
     {:clojure-host-interpreter? true
      :gravity-reader-algorithm-authored? false
      :clojure-seed-retired? false
      :next-required-capability
      :move-reader-algorithm-into-executable-gravity}
     :status :complete}))

(defn stage1-reader-execution-source-artifact
  [source-path source-text]
  (let [table (stage1-reader-table)
        table-id (str "sha256:" (sha256-hex (pr-str table)))
        stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        stage1-records (stage1-reader-table-driven-records source-path
                                                           source-text
                                                           table)
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        artifact-base
        {:kind :gravity/stage1-reader-execution-artifact
         :phase "15"
         :task "P15-S2"
         :stage :stage1-reader-execution
         :source-path source-path
         :reader-source-path stage1-reader-source-path
         :reader-table-symbol :gravity.bootstrap.reader/stage1-reader-table
         :reader-table-id table-id
         :reader-table table
         :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
         :stage1-reader-records stage1-records
         :stage0-comparison comparison
         :accepted-stage1-reader-fixtures
         [{:fixture "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
           :status :accepted
           :comparison comparison}]
         :rejected-stage1-reader-fixtures
         stage1-reader-execution-rejected-fixture-records
         :stage1-reader-diagnostic-stream
         (stage1-reader-execution-diagnostic-stream source-path table-id)
         :stage1-reader-execution-results
         {:accepted-fixtures 1
          :rejected-fixtures
          (count stage1-reader-execution-rejected-fixture-records)
          :diagnostic-count (count stage1-reader-execution-diagnostic-ids)
          :form-count (count stage1-records)
          :status :complete}
         :diagnostics []}
        capability-proof (stage1-reader-execution-proof artifact-base)]
    (when-not (:forms-equal? comparison)
      (stage1-reader-fail! "STAGE1READER006" source-path comparison
                           {:missing-fields [:stage0-form-parity]}))
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn stage1-reader-execution-file-artifact
  [path]
  (stage1-reader-execution-source-artifact path (slurp path)))

