            source-path
            (:release-attestation-seed-retirement-id
             release-attestation))
           :stage1-reader-release-attestation-seed-retirement-results
           {:accepted-fixtures 1
            :rejected-fixtures
            (count stage1-reader-release-attestation-seed-retirement-rejected-fixture-records)
            :diagnostic-count
            (+ (count stage1-reader-release-attestation-seed-retirement-diagnostic-ids)
               (dec (count stage1-reader-execution-diagnostic-ids)))
            :character-count (:character-count character-stream)
            :token-count (:token-count token-stream)
            :form-count (count stage1-records)
            :status :complete}
           :diagnostics []}]
      (when-not (:forms-equal? comparison)
        (stage1-reader-release-attestation-seed-retirement-fail!
         "STAGE1REL010" source-path comparison
         {:missing-fields [:stage0-form-parity]}))
      (when-not (= (:artifact release-attestation) (:kind artifact-base))
        (stage1-reader-release-attestation-seed-retirement-fail!
         "STAGE1REL010" source-path artifact-base
         {:missing-fields [:artifact]}))
      (when-not (= (:diagnostic-stream release-attestation)
