               ["STAGE1REL008" :seed-orchestration-fallbacks
                seed-orchestration-fallbacks]
               ["STAGE1REL008" :runner-fallbacks runner-fallbacks]
               ["STAGE1REL008" :os-boundaries os-boundaries]
