               ["STAGE1REL008" :trust-anchor-boundaries
                trust-anchor-boundaries]
               ["STAGE1REL008" :physical-release-boundaries
                physical-release-boundaries]
               ["STAGE1REL008" :residual-trust-boundaries
                residual-trust-boundaries]
               ["STAGE1REL008" :image-fallbacks image-fallbacks]
               ["STAGE1REL008" :boot-chain-fallbacks
                boot-chain-fallbacks]
               ["STAGE1REL008" :diverse-verification-fallbacks
                diverse-verification-fallbacks]
               ["STAGE1REL008" :release-attestation-fallbacks
                release-attestation-fallbacks]]]
        (when (seq value)
          (stage1-reader-release-attestation-seed-retirement-fail!
           diagnostic source-path trace-value {field value})))
      (when-not (= #{:physical-device-manufacturing
                     :supply-chain-custody
                     :independent-diversity-review}
                   (set replaced-physical-release-boundaries))
        (stage1-reader-release-attestation-seed-retirement-fail!
         "STAGE1REL008" source-path trace-value
         {:replaced-physical-release-boundaries
          replaced-physical-release-boundaries}))
      (when-not (= #{:human-release-governance
                     :legal-custody-record-retention
                     :deployment-environment-custody}
                   (set residual-release-governance-boundaries))
        (stage1-reader-release-attestation-seed-retirement-fail!
         "STAGE1REL010" source-path trace-value
         {:residual-release-governance-boundaries
          residual-release-governance-boundaries}))
      (when-not (and (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :physical-device-manufacturing-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :supply-chain-custody-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :independent-diversity-review-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :human-release-governance-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :legal-custody-record-retention-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :deployment-environment-custody-boundary?])))
        (stage1-reader-release-attestation-seed-retirement-fail!
         "STAGE1REL010" source-path artifact-base
         {:missing-fields [:trusted-boundary]}))
      (when-not (= :clear (:status revocation-check-report))
        (stage1-reader-release-attestation-seed-retirement-fail!
         "STAGE1REL009" source-path revocation-check-report
         {:missing-fields [:revocation-check-report]}))
      (let [capability-proof
            (stage1-reader-release-attestation-seed-retirement-proof
             artifact-base)]
        (assoc artifact-base
               :capability-based-proof capability-proof
               :artifact-id
               (c4-artifact-id (assoc artifact-base
                                      :capability-based-proof
                                      capability-proof)))))))

(defn stage1-reader-release-attestation-seed-retirement-file-artifact
  [path]
  (stage1-reader-release-attestation-seed-retirement-source-artifact
   path
   (slurp path)))

(def stage1-reader-formal-release-governance-seed-retirement-required-operations
  [:verify-formal-release-governance
   :verify-deployment-custody
   :verify-self-hosting-evidence
   :verify-reproducible-rebuild
   :verify-stage-comparison
   :record-tcb-delta
   :record-unsafe-audit
   :record-formal-release-provenance])

(def stage1-reader-formal-release-governance-seed-retirement-required-stages
  [:stage1-formal-governance-verify
   :stage1-formal-governance-deployment-custody
   :stage1-formal-governance-self-hosting-evidence
   :stage1-formal-governance-reproducible-rebuild
   :stage1-formal-governance-stage-comparison
   :stage1-formal-governance-tcb-delta
   :stage1-formal-governance-unsafe-audit
   :stage1-formal-governance-record-provenance])

(defn stage1-reader-formal-release-governance-seed-retirement-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV003" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-formal-release-governance-seed-retirement-from-definitions
  [reader-source-path definitions]
  (let [formal-governance
        (stage1-reader-formal-release-governance-seed-retirement-literal-definition-value
         reader-source-path definitions
         'stage1-reader-formal-release-governance-seed-retirement)
        diagnostics (:diagnostics formal-governance)
        missing-diagnostics
        (remove #(contains? diagnostics %)
                [:missing-entrypoint
                 :unsupported-formal-governance-operation
                 :missing-formal-release-governance
                 :unverifiable-deployment-custody
                 :missing-self-hosting-evidence
                 :unreproducible-full-compiler-rebuild
                 :missing-stage-compiler-equivalence
                 :missing-tcb-delta
                 :illegal-governance-or-deployment-fallback
                 :invalid-formal-release-governance])
        direct-stages (:direct-stages formal-governance)
        formal-record (:formal-release-governance-record formal-governance)
        deployment-custody (:deployment-custody-record formal-governance)
        self-hosting-evidence (:self-hosting-evidence formal-governance)
        seed-retirement-evidence
        (:seed-retirement-evidence formal-governance)
        tcb-delta-record (:tcb-delta-record formal-governance)
        unsafe-audit-report (:unsafe-audit-report formal-governance)
        formal-provenance-record
        (:formal-release-provenance-record formal-governance)]
    (when-not (map? formal-governance)
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV003" reader-source-path formal-governance
       {:missing-fields
        [:stage1-reader-formal-release-governance-seed-retirement]}))
    (doseq [field [:engine :entrypoint :replaces
                   :release-attestation-seed-retirement
                   :diverse-bootstrap-verification
                   :verified-boot-chain :input :output :artifact
                   :diagnostic-stream :proof-kind
                   :residual-release-governance-boundaries
                   :formal-release-governance-fallbacks
                   :formal-governance-operations
                   :formal-release-governance-record
                   :deployment-custody-record
                   :self-hosting-evidence
                   :seed-retirement-evidence
                   :tcb-delta-record
                   :unsafe-audit-report
                   :formal-release-provenance-record
                   :direct-stages :uses-runtimes :uses-builtins
                   :uses-executors :preserves :diagnostics :provenance]]
      (when-not (contains? formal-governance field)
        (stage1-reader-formal-release-governance-seed-retirement-fail!
         "STAGE1GOV010" reader-source-path formal-governance
         {:missing-fields [field]})))
    (when-not (= :gravity-reader-formal-release-governance-v1
                 (:engine formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:engine]}))
    (when-not (= :stage1-read-source-formal-release-governance-seed-retirement
                 (:entrypoint formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:entrypoint]}))
    (when-not (set/subset? #{:human-release-governance
                             :legal-custody-record-retention
                             :deployment-environment-custody}
                           (set (:replaces formal-governance)))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:replaces]}))
    (when-not (= :stage1-reader-release-attestation-seed-retirement
                 (:release-attestation-seed-retirement
                  formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:release-attestation-seed-retirement]}))
    (when-not (= :stage1-reader-diverse-bootstrap-verification
                 (:diverse-bootstrap-verification formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:diverse-bootstrap-verification]}))
    (when-not (= :stage1-reader-verified-boot-chain
                 (:verified-boot-chain formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:verified-boot-chain]}))
    (when-not (= [:formal-release-governance
                  :deployment-custody
                  :self-hosting-evidence
                  :release-attestation
                  :source-path
                  :source-text]
                 (:input formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records
                 (:output formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:output]}))
    (when-not (= :gravity/stage1-reader-formal-release-governance-seed-retirement-artifact
                 (:artifact formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:artifact]}))
    (when-not (= :gravity/stage1-reader-formal-release-governance-seed-retirement-diagnostic-stream
                 (:diagnostic-stream formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:diagnostic-stream]}))
    (when-not (= :gravity/stage1-reader-formal-release-governance-seed-retirement-proof
                 (:proof-kind formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:proof-kind]}))
    (when-not (= [] (:residual-release-governance-boundaries
                     formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV009" reader-source-path formal-governance
       {:residual-release-governance-boundaries
        (:residual-release-governance-boundaries formal-governance)}))
    (when-not (= [] (:formal-release-governance-fallbacks
                     formal-governance))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV009" reader-source-path formal-governance
       {:formal-release-governance-fallbacks
        (:formal-release-governance-fallbacks formal-governance)}))
    (let [operations (:formal-governance-operations formal-governance)
          operation-names (set operations)
          required-operation-set
          (set stage1-reader-formal-release-governance-seed-retirement-required-operations)]
      (when-not (vector? operations)
        (stage1-reader-formal-release-governance-seed-retirement-fail!
         "STAGE1GOV002" reader-source-path formal-governance
         {:missing-fields [:formal-governance-operations]}))
      (when-not (set/subset? required-operation-set operation-names)
        (stage1-reader-formal-release-governance-seed-retirement-fail!
         "STAGE1GOV002" reader-source-path operations
         {:missing-operations
          (vec (remove operation-names
                       stage1-reader-formal-release-governance-seed-retirement-required-operations))})))
    (when-not (and (vector? direct-stages)
                   (= stage1-reader-formal-release-governance-seed-retirement-required-stages
                      (mapv :op direct-stages)))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:direct-stages]}))
    (when-not (and (= :verified (:status formal-record))
                   (= :gravity-release-policy-v1
                      (:policy-engine formal-record))
                   (= :versioned-rfc-ledger
                      (:governance-source formal-record))
                   (= :machine-checkable-governance
                      (:approval-model formal-record))
                   (set/subset?
                    #{:GOV6 :GOV10 :BOOT6 :BOOT7 :BOOT8 :TEST13}
                    (set (:required-policies formal-record)))
                   (true? (:human-release-governance-replaced?
                           formal-record))
                   (true? (:legal-custody-record-retention-replaced?
                           formal-record))
                   (true? (:deployment-environment-custody-replaced?
                           formal-record)))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV003" reader-source-path formal-record
       {:missing-fields [:formal-release-governance-record]}))
    (when-not (and (= :verifiable (:status deployment-custody))
                   (= :content-addressed-release-graph
                      (:custody-model deployment-custody))
                   (= :policy-verified
                      (:builder-selection deployment-custody))
                   (= :hash-and-policy-gated
                      (:artifact-admission deployment-custody))
                   (= :disabled (:network deployment-custody))
                   (= :forbidden (:mutable-state deployment-custody)))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV004" reader-source-path deployment-custody
       {:missing-fields [:deployment-custody-record]}))
    (when-not (and (= :verified (:status self-hosting-evidence))
                   (= :stage1-reader-claimed-subset
                      (:scope self-hosting-evidence))
                   (= :verified
                      (:staged-compiler-artifact self-hosting-evidence))
                   (= :verified
                      (:reproducible-rebuild-log self-hosting-evidence))
                   (= :verified
                      (:conformance-report self-hosting-evidence))
                   (= :verified
                      (:stage-comparison-report self-hosting-evidence))
                   (= :verified
                      (:provenance-attestation self-hosting-evidence))
                   (= :verified (:tcb-delta self-hosting-evidence))
                   (= :not-applicable
                      (:unsafe-audit-report self-hosting-evidence))
                   (true? (:claimed-subset-self-hosted?
                           self-hosting-evidence))
                   (false? (:full-language-compiler-self-hosted?
                            self-hosting-evidence))
                   (false? (:clojure-seed-retired?
                            self-hosting-evidence)))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV005" reader-source-path self-hosting-evidence
       {:missing-fields [:self-hosting-evidence]}))
    (when-not (= :verified
                 (:reproducible-rebuild-log self-hosting-evidence))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV006" reader-source-path self-hosting-evidence
       {:missing-fields [:reproducible-rebuild-log]}))
    (when-not (= :verified
                 (:stage-comparison-report self-hosting-evidence))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV007" reader-source-path self-hosting-evidence
       {:missing-fields [:stage-comparison-report]}))
    (when-not (and (= :recorded (:status seed-retirement-evidence))
                   (true? (:claimed-subset-seed-retired?
                           seed-retirement-evidence))
                   (false? (:full-compiler-seed-retired?
                            seed-retirement-evidence))
                   (false? (:clojure-seed-retired?
                            seed-retirement-evidence))
                   (= #{:human-release-governance
                        :legal-custody-record-retention
                        :deployment-environment-custody}
                      (set (:retired-assumptions
                            seed-retirement-evidence)))
                   (= #{:full-language-compiler-self-hosting}
                      (set (:remaining-boundaries
                            seed-retirement-evidence))))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV005" reader-source-path seed-retirement-evidence
       {:missing-fields [:seed-retirement-evidence]}))
    (when-not (and (= :complete (:status tcb-delta-record))
                   (= #{:human-release-governance
                        :legal-custody-record-retention
                        :deployment-environment-custody}
                      (set (:removed tcb-delta-record)))
                   (= #{:full-language-compiler-self-hosting}
                      (set (:remaining tcb-delta-record)))
                   (= [] (:new-unsafe-islands tcb-delta-record)))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV008" reader-source-path tcb-delta-record
       {:missing-fields [:tcb-delta-record]}))
    (when-not (and (= :not-applicable (:status unsafe-audit-report))
                   (false? (:unsafe-required? unsafe-audit-report))
                   (= [] (:unsafe-islands unsafe-audit-report)))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path unsafe-audit-report
       {:missing-fields [:unsafe-audit-report]}))
    (when-not (and (= :complete (:status formal-provenance-record))
                   (true? (:canonicalized formal-provenance-record))
                   (true? (:auditor-traversable
                           formal-provenance-record))
                   (set/subset?
                    #{:stage1-reader-formal-release-governance-seed-retirement
                      :stage1-reader-release-attestation-seed-retirement
                      :stage1-reader-diverse-bootstrap-verification}
                    (set (:lineage formal-provenance-record))))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-provenance-record
       {:missing-fields [:formal-release-provenance-record]}))
    (when-not (set/subset?
               #{:stage1-reader-formal-release-governance-seed-retirement
                 :stage1-reader-release-attestation-seed-retirement
                 :stage1-reader-diverse-bootstrap-verification
                 :stage1-reader-verified-boot-chain
                 :stage1-reader-runtime-image
                 :stage1-reader-runtime-entrypoint
                 :stage1-reader-compiler-driver
                 :stage1-reader-core-bootstrap-runtime
                 :stage1-reader-self-hosted-runtime
                 :stage1-reader-source-runtime}
               (set (:uses-runtimes formal-governance)))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? #{:stage1-reader-core-bootstrap-builtins}
                           (set (:uses-builtins formal-governance)))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:uses-builtins]}))
    (when-not (set/subset? #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
                           (set (:uses-executors formal-governance)))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:uses-executors]}))
    (when-not (= :gravity-source
                 (get-in formal-governance [:provenance :owner]))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:provenance :owner]}))
    (when-not (= :reader-formal-release-governance-assumption-replacement
                 (get-in formal-governance [:provenance :purpose]))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:provenance :purpose]}))
    (when-not (= :replace-human-release-governance-and-deployment-custody-with-formal-release-governance-while-keeping-full-compiler-self-hosting-explicit
                 (get-in formal-governance
                         [:provenance :retirement-objective]))
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path formal-governance
       {:missing-fields [:provenance :retirement-objective]}))
    (when (seq missing-diagnostics)
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV010" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc formal-governance
           :formal-release-governance-seed-retirement-id
           (str "sha256:" (sha256-hex (pr-str formal-governance))))))

(defn stage1-reader-formal-release-governance-seed-retirement-entrypoint-valid?
  [definitions]
  (let [definition
        (get definitions
             stage1-reader-formal-release-governance-seed-retirement-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-formal-release-governance-seed-retirement
               source-path
               source-text
               stage1-reader-formal-release-governance-seed-retirement
               stage1-reader-release-attestation-seed-retirement))
            (:body definition)))))

(defn stage1-reader-execute-formal-release-governance-seed-retirement
  [reader-source-path
   definitions
   source-path
   source-text
   self-hosted-runtime
   core-bootstrap-runtime
   core-bootstrap-builtins
   compiler-driver
   runtime-entrypoint
   runtime-image
   boot-chain
   diverse-verification
   release-attestation
   formal-governance]
  (let [formal-governance-id
        (:formal-release-governance-seed-retirement-id
         formal-governance)
        operations (:formal-governance-operations formal-governance)
        annotate-with-formal-governance
        (fn [record]
          (assoc record
                 :formal-release-governance-seed-retirement-id
                 formal-governance-id
                 :formal-release-governance-engine
                 (:engine formal-governance)
                 :formal-release-governance
                 :gravity-reader-formal-release-governance-v1))
        records
        (stage1-reader-execute-release-attestation-seed-retirement
         reader-source-path
         definitions
         source-path
         source-text
         self-hosted-runtime
         core-bootstrap-runtime
         core-bootstrap-builtins
         compiler-driver
         runtime-entrypoint
         runtime-image
         boot-chain
         diverse-verification
         release-attestation)
        annotated-records (mapv annotate-with-formal-governance records)]
    (when *stage1-reader-pipeline-trace*
      (swap! *stage1-reader-pipeline-trace*
             (fn [trace]
               (let [prior-release-governance-boundaries
                     (:residual-release-governance-boundaries trace)]
                 (-> (or trace {})
                     (assoc :formal-release-governance-seed-retirement
                            formal-governance)
                     (assoc :formal-release-governance-operation-coverage
                            {:required
                             stage1-reader-formal-release-governance-seed-retirement-required-operations
                             :provided operations
                             :covered?
                             (set/subset?
                              (set stage1-reader-formal-release-governance-seed-retirement-required-operations)
                              (set operations))})
                     (assoc :replaced-release-governance-boundaries
                            prior-release-governance-boundaries)
                     (assoc :residual-release-governance-boundaries
                            (:residual-release-governance-boundaries
                             formal-governance))
                     (assoc :formal-release-governance-fallbacks
                            (:formal-release-governance-fallbacks
                             formal-governance))
                     (assoc :formal-release-governance-record
                            (:formal-release-governance-record
                             formal-governance))
                     (assoc :deployment-custody-record
                            (:deployment-custody-record
                             formal-governance))
                     (assoc :self-hosting-evidence
                            (:self-hosting-evidence formal-governance))
                     (assoc :formal-seed-retirement-evidence
                            (:seed-retirement-evidence formal-governance))
                     (assoc :formal-tcb-delta-record
                            (:tcb-delta-record formal-governance))
                     (assoc :formal-unsafe-audit-report
                            (:unsafe-audit-report formal-governance))
                     (assoc :formal-release-provenance-record
                            (:formal-release-provenance-record
                             formal-governance))
                     (assoc :formal-release-governance-artifact-routing
                            {:artifact (:artifact formal-governance)
                             :diagnostic-stream
                             (:diagnostic-stream formal-governance)
                             :proof-kind (:proof-kind formal-governance)})
                     (update :gravity-runtimes (fnil conj [])
                             :stage1-reader-formal-release-governance-seed-retirement)
                     (update :character-stream
                             annotate-with-formal-governance)
                     (update :token-stream
                             annotate-with-formal-governance)
                     (assoc
                      :formal-release-governance-applied
                      {:formal-release-governance-seed-retirement-id
                       formal-governance-id
                       :operation-count (count operations)
                       :replaced-release-governance-boundaries
                       prior-release-governance-boundaries
                       :residual-release-governance-boundaries
                       (:residual-release-governance-boundaries
                        formal-governance)
                       :formal-release-governance-fallbacks
                       (:formal-release-governance-fallbacks
                        formal-governance)
                       :clojure-seed-retired?
                       (get-in formal-governance
                               [:self-hosting-evidence
                                :clojure-seed-retired?])}))))))
    annotated-records))

(defn stage1-reader-execute-formal-release-governance-seed-retirement-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)
        self-hosted-runtime
        (stage1-reader-self-hosted-runtime-from-definitions
         reader-source-path definitions)
        core-bootstrap-builtins
        (stage1-reader-core-bootstrap-builtins-from-definitions
         reader-source-path definitions)
        core-bootstrap-runtime
        (stage1-reader-core-bootstrap-runtime-from-definitions
         reader-source-path definitions)
        compiler-driver
        (stage1-reader-compiler-driver-from-definitions
         reader-source-path definitions)
        runtime-entrypoint
        (stage1-reader-runtime-entrypoint-from-definitions
         reader-source-path definitions)
        runtime-image
        (stage1-reader-runtime-image-from-definitions
         reader-source-path definitions)
        boot-chain
        (stage1-reader-verified-boot-chain-from-definitions
         reader-source-path definitions)
        diverse-verification
        (stage1-reader-diverse-bootstrap-verification-from-definitions
         reader-source-path definitions)
        release-attestation
        (stage1-reader-release-attestation-seed-retirement-from-definitions
         reader-source-path definitions)
        formal-governance
        (stage1-reader-formal-release-governance-seed-retirement-from-definitions
         reader-source-path definitions)]
    (when-not
        (stage1-reader-formal-release-governance-seed-retirement-entrypoint-valid?
         definitions)
      (stage1-reader-formal-release-governance-seed-retirement-fail!
       "STAGE1GOV001" reader-source-path
       stage1-reader-formal-release-governance-seed-retirement-entrypoint
       {:missing-fields
        [stage1-reader-formal-release-governance-seed-retirement-entrypoint]}))
    {:records
     (stage1-reader-execute-formal-release-governance-seed-retirement
