(defn stage1-reader-formal-release-governance-seed-retirement-diagnostic-stream
  [source-path formal-governance-id]
  {:artifact
   :gravity/stage1-reader-formal-release-governance-seed-retirement-diagnostic-stream
   :stage :stage1-reader-formal-release-governance-seed-retirement
   :source-path source-path
   :formal-release-governance-seed-retirement-id formal-governance-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage
            :stage1-reader-formal-release-governance-seed-retirement
            :artifact :gravity/diagnostic
            :message
            (or (stage1-reader-formal-release-governance-seed-retirement-diagnostic-messages
                 id)
                (stage1-reader-execution-diagnostic-messages id))})
         (concat
          stage1-reader-formal-release-governance-seed-retirement-diagnostic-ids
          (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-formal-release-governance-seed-retirement-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:stage1-reader-formal-release-governance-seed-retirement-diagnostic-stream
                           :diagnostics])))
        formal-governance
        (:stage1-reader-formal-release-governance-seed-retirement
         artifact)
        release-attestation
        (:stage1-reader-release-attestation-seed-retirement artifact)
        diverse-verification
        (:stage1-reader-diverse-bootstrap-verification artifact)
        boot-chain (:stage1-reader-verified-boot-chain artifact)
        character-stream (:stage1-reader-character-stream artifact)
        token-stream (:stage1-reader-token-stream artifact)
        records (:stage1-reader-records artifact)
        operation-names
        (set (:formal-governance-operations formal-governance))
        direct-stages (mapv :op (:direct-stages formal-governance))
        gravity-runtimes (set (:gravity-runtimes artifact))
        gravity-executors (set (:gravity-executors artifact))
        formal-record
        (:formal-release-governance-record formal-governance)
        deployment-custody
        (:deployment-custody-record formal-governance)
        self-hosting-evidence
        (:self-hosting-evidence formal-governance)
        seed-retirement-evidence
        (:seed-retirement-evidence formal-governance)
        tcb-delta-record (:tcb-delta-record formal-governance)
        unsafe-audit-report (:unsafe-audit-report formal-governance)
        formal-provenance-record
        (:formal-release-provenance-record formal-governance)]
    {:gravity-reader-formal-release-governance-seed-retirement-verified?
     (= stage1-reader-formal-release-governance-seed-retirement-entrypoint
        (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :formal-release-governance-authored?
     (and (= :gravity-reader-formal-release-governance-v1
             (:engine formal-governance))
          (= :gravity-source
             (get-in formal-governance [:provenance :owner]))
          (= :reader-formal-release-governance-assumption-replacement
             (get-in formal-governance [:provenance :purpose])))
     :formal-governance-direct-stages-covered?
     (= stage1-reader-formal-release-governance-seed-retirement-required-stages
        direct-stages)
     :formal-governance-operations-covered?
     (set/subset?
      (set stage1-reader-formal-release-governance-seed-retirement-required-operations)
      operation-names)
     :formal-governance-links-release-attestation?
     (= :stage1-reader-release-attestation-seed-retirement
        (:release-attestation-seed-retirement formal-governance))
     :release-attestation-authored?
     (= :gravity-reader-release-attestation-seed-retirement-v1
        (:engine release-attestation))
     :diverse-bootstrap-verification-authored?
     (= :gravity-reader-diverse-bootstrap-verification-v1
        (:engine diverse-verification))
     :verified-boot-chain-authored?
     (= :gravity-reader-verified-boot-chain-v1 (:engine boot-chain))
     :artifact-routing-covered?
     (= :gravity/stage1-reader-formal-release-governance-seed-retirement-artifact
        (:artifact formal-governance)
        (:kind artifact))
     :diagnostic-stream-routing-covered?
     (= :gravity/stage1-reader-formal-release-governance-seed-retirement-diagnostic-stream
        (:diagnostic-stream formal-governance)
        (get-in artifact
                [:stage1-reader-formal-release-governance-seed-retirement-diagnostic-stream
                 :artifact]))
     :human-release-governance-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :human-release-governance-boundary?]))
     :legal-custody-record-retention-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :legal-custody-record-retention-boundary?]))
     :deployment-environment-custody-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :deployment-environment-custody-boundary?]))
     :residual-release-governance-boundaries-empty?
     (= [] (:residual-release-governance-boundaries artifact))
     :formal-release-governance-record-covered?
     (and (= :verified (:status formal-record))
          (= :gravity-release-policy-v1 (:policy-engine formal-record))
          (= :versioned-rfc-ledger (:governance-source formal-record))
          (= :machine-checkable-governance
             (:approval-model formal-record))
          (true? (:human-release-governance-replaced? formal-record))
          (true? (:legal-custody-record-retention-replaced?
                  formal-record))
          (true? (:deployment-environment-custody-replaced?
                  formal-record)))
     :deployment-custody-record-covered?
     (and (= :verifiable (:status deployment-custody))
          (= :content-addressed-release-graph
             (:custody-model deployment-custody))
          (= :policy-verified (:builder-selection deployment-custody))
          (= :hash-and-policy-gated
             (:artifact-admission deployment-custody))
          (= :disabled (:network deployment-custody))
          (= :forbidden (:mutable-state deployment-custody)))
     :self-hosting-evidence-covered?
     (and (= :verified (:status self-hosting-evidence))
          (= :stage1-reader-claimed-subset
             (:scope self-hosting-evidence))
          (= :verified
             (:staged-compiler-artifact self-hosting-evidence))
          (= :verified
             (:reproducible-rebuild-log self-hosting-evidence))
          (= :verified (:conformance-report self-hosting-evidence))
          (= :verified
             (:stage-comparison-report self-hosting-evidence))
          (= :verified
             (:provenance-attestation self-hosting-evidence))
          (= :verified (:tcb-delta self-hosting-evidence))
          (= :not-applicable
             (:unsafe-audit-report self-hosting-evidence))
          (true? (:claimed-subset-self-hosted? self-hosting-evidence))
          (false? (:full-language-compiler-self-hosted?
                   self-hosting-evidence))
          (false? (:clojure-seed-retired? self-hosting-evidence)))
     :full-language-compiler-self-hosting-not-claimed?
     (false? (:full-language-compiler-self-hosted?
              self-hosting-evidence))
     :seed-retirement-evidence-covered?
     (and (= :recorded (:status seed-retirement-evidence))
          (true? (:claimed-subset-seed-retired?
                  seed-retirement-evidence))
          (false? (:full-compiler-seed-retired?
                   seed-retirement-evidence))
          (false? (:clojure-seed-retired?
                   seed-retirement-evidence)))
     :tcb-delta-covered?
     (and (= :complete (:status tcb-delta-record))
          (= #{:human-release-governance
               :legal-custody-record-retention
               :deployment-environment-custody}
             (set (:removed tcb-delta-record)))
          (= #{:full-language-compiler-self-hosting}
             (set (:remaining tcb-delta-record)))
          (= [] (:new-unsafe-islands tcb-delta-record)))
     :unsafe-audit-covered?
     (and (= :not-applicable (:status unsafe-audit-report))
          (false? (:unsafe-required? unsafe-audit-report))
          (= [] (:unsafe-islands unsafe-audit-report)))
     :formal-release-provenance-covered?
     (and (= :complete (:status formal-provenance-record))
          (true? (:canonicalized formal-provenance-record))
          (true? (:auditor-traversable formal-provenance-record))
          (set/subset?
           #{:stage1-reader-formal-release-governance-seed-retirement
             :stage1-reader-release-attestation-seed-retirement
             :stage1-reader-diverse-bootstrap-verification
             :stage1-reader-verified-boot-chain}
           (set (:lineage formal-provenance-record))))
     :host-primitive-boundary-empty?
     (= [] (:host-primitives artifact))
     :host-fallbacks-empty?
     (= [] (get-in artifact [:stage1-reader-core-bootstrap-builtins
                             :host-fallbacks]))
     :seed-builtin-fallbacks-empty?
     (= [] (:seed-builtin-fallbacks artifact))
     :seed-orchestration-fallbacks-empty?
     (= [] (:seed-orchestration-fallbacks artifact))
     :runner-fallbacks-empty?
     (= [] (:runner-fallbacks artifact))
     :os-boundaries-empty?
     (= [] (:os-boundaries artifact))
     :image-fallbacks-empty?
     (= [] (:image-fallbacks artifact))
     :machine-boundaries-empty?
     (= [] (:machine-boundaries artifact))
     :boot-chain-fallbacks-empty?
     (= [] (:boot-chain-fallbacks artifact))
     :trust-anchor-boundaries-empty?
     (= [] (:trust-anchor-boundaries artifact))
     :physical-release-boundaries-empty?
     (= [] (:physical-release-boundaries artifact))
     :diverse-verification-fallbacks-empty?
     (= [] (:diverse-verification-fallbacks artifact))
     :release-attestation-fallbacks-empty?
     (= [] (:release-attestation-fallbacks artifact))
     :formal-release-governance-fallbacks-empty?
     (= [] (:formal-release-governance-fallbacks artifact))
     :replaced-release-governance-boundaries-recorded?
     (= #{:human-release-governance
          :legal-custody-record-retention
          :deployment-environment-custody}
        (set (:replaced-release-governance-boundaries artifact)))
     :gravity-runtimes-covered?
     (set/subset?
      #{:stage1-reader-formal-release-governance-seed-retirement
        :stage1-reader-release-attestation-seed-retirement
        :stage1-reader-diverse-bootstrap-verification
        :stage1-reader-verified-boot-chain
        :stage1-reader-runtime-image
        :stage1-reader-runtime-entrypoint
        :stage1-reader-compiler-driver
        :stage1-reader-core-bootstrap-runtime
        :stage1-reader-self-hosted-runtime
        :stage1-reader-source-runtime}
      gravity-runtimes)
     :gravity-executors-covered?
     (set/subset? #{:stage1-reader-token-automaton-executor
                    :stage1-reader-form-builder-executor}
                  gravity-executors)
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-formal-release-governance-v1
             (:formal-release-governance-engine character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream))))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-formal-release-governance-v1
             (:formal-release-governance-engine token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(and (= :gravity-reader-release-attestation-seed-retirement-v1
                           (:release-attestation-seed-retirement-engine %))
                        (= :gravity-reader-formal-release-governance-v1
                           (:formal-release-governance-engine %)))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset?
      (set (concat
            stage1-reader-formal-release-governance-seed-retirement-diagnostic-ids
            (butlast stage1-reader-execution-diagnostic-ids)))
      diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? false
      :clojure-binary-runner? false
      :clojure-character-stream-implementation? false
      :clojure-seed-builtins? false
      :clojure-seed-orchestration? false
      :clojure-driver-runner? false
      :host-command-invocation? false
      :host-file-read? false
      :os-process-boundary? false
      :os-filesystem-read-boundary? false
      :stdout-boundary? false
      :machine-boundary? false
      :kernel-process-scheduler-boundary? false
      :artifact-loader-boundary? false
      :hardware-reset-vector-boundary? false
      :firmware-root-of-trust-boundary? false
      :external-auditor-key-boundary? false
      :physical-device-manufacturing-boundary? false
      :supply-chain-custody-boundary? false
      :independent-diversity-review-boundary? false
      :human-release-governance-boundary? false
      :legal-custody-record-retention-boundary? false
      :deployment-environment-custody-boundary? false
      :claimed-subset-self-hosted? true
      :full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :next-required-capability
      :implement-full-language-compiler-self-hosting-before-retiring-clojure-seed}
     :status :complete}))

