            :clojure-seed-retired? false}
           :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
           :stage1-reader-formal-release-governance-seed-retirement
           formal-governance
           :stage1-reader-release-attestation-seed-retirement
           release-attestation
           :stage1-reader-diverse-bootstrap-verification
           diverse-verification
           :stage1-reader-verified-boot-chain boot-chain
           :stage1-reader-runtime-image runtime-image
           :stage1-reader-runtime-entrypoint runtime-entrypoint
           :stage1-reader-compiler-driver compiler-driver
           :stage1-reader-core-bootstrap-runtime
           core-bootstrap-runtime
           :stage1-reader-core-bootstrap-builtins
           core-bootstrap-builtins
           :stage1-reader-self-hosted-runtime self-hosted-runtime
           :stage1-reader-source-runtime source-runtime
           :stage1-reader-character-stream character-stream
           :stage1-reader-token-classifier token-classifier
           :stage1-reader-token-realizer token-realizer
           :stage1-reader-token-automaton token-automaton
           :stage1-reader-token-automaton-executor
           token-automaton-executor
           :stage1-reader-form-builder form-builder
           :stage1-reader-form-builder-executor form-builder-executor
           :stage1-reader-token-stream token-stream
           :stage1-reader-records stage1-records
           :stage1-reader-formal-release-governance-seed-retirement-trace
           (dissoc trace-value :character-stream :token-stream
                   :token-classifier :token-realizer :token-automaton
                   :token-automaton-executor :form-builder
                   :form-builder-executor :source-runtime
                   :self-hosted-reader-runtime
                   :core-bootstrap-runtime
                   :core-bootstrap-builtins
                   :compiler-driver
                   :runtime-entrypoint
                   :runtime-image
                   :verified-boot-chain
                   :diverse-bootstrap-verification
                   :release-attestation-seed-retirement
                   :formal-release-governance-seed-retirement)
           :stage0-comparison comparison
           :accepted-stage1-reader-formal-release-governance-seed-retirement-fixtures
           [{:fixture
             "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
             :status :accepted
             :comparison comparison
             :character-count (:character-count character-stream)
             :token-count (:token-count token-stream)
             :form-count (count stage1-records)
             :formal-release-governance-seed-retirement-id
             (:formal-release-governance-seed-retirement-id
              formal-governance)}]
           :rejected-stage1-reader-formal-release-governance-seed-retirement-fixtures
           stage1-reader-formal-release-governance-seed-retirement-rejected-fixture-records
           :stage1-reader-formal-release-governance-seed-retirement-diagnostic-stream
           (stage1-reader-formal-release-governance-seed-retirement-diagnostic-stream
            source-path
            (:formal-release-governance-seed-retirement-id
             formal-governance))
           :stage1-reader-formal-release-governance-seed-retirement-results
           {:accepted-fixtures 1
            :rejected-fixtures
            (count stage1-reader-formal-release-governance-seed-retirement-rejected-fixture-records)
            :diagnostic-count
            (+ (count stage1-reader-formal-release-governance-seed-retirement-diagnostic-ids)
               (dec (count stage1-reader-execution-diagnostic-ids)))
            :character-count (:character-count character-stream)
            :token-count (:token-count token-stream)
            :form-count (count stage1-records)
            :status :complete}
           :diagnostics []}]
      (when-not (:forms-equal? comparison)
        (stage1-reader-formal-release-governance-seed-retirement-fail!
         "STAGE1GOV007" source-path comparison
         {:missing-fields [:stage0-form-parity]}))
      (when-not (= (:artifact formal-governance) (:kind artifact-base))
        (stage1-reader-formal-release-governance-seed-retirement-fail!
         "STAGE1GOV010" source-path artifact-base
         {:missing-fields [:artifact]}))
      (when-not (= (:diagnostic-stream formal-governance)
                   (get-in artifact-base
                           [:stage1-reader-formal-release-governance-seed-retirement-diagnostic-stream
                            :artifact]))
        (stage1-reader-formal-release-governance-seed-retirement-fail!
         "STAGE1GOV010" source-path artifact-base
         {:missing-fields [:diagnostic-stream]}))
      (doseq [[diagnostic field value]
              [["STAGE1GOV009" :host-primitives host-primitives]
               ["STAGE1GOV009" :seed-builtin-fallbacks
                seed-builtin-fallbacks]
               ["STAGE1GOV009" :seed-orchestration-fallbacks
                seed-orchestration-fallbacks]
               ["STAGE1GOV009" :runner-fallbacks runner-fallbacks]
               ["STAGE1GOV009" :os-boundaries os-boundaries]
               ["STAGE1GOV009" :machine-boundaries machine-boundaries]
               ["STAGE1GOV009" :trust-anchor-boundaries
                trust-anchor-boundaries]
               ["STAGE1GOV009" :physical-release-boundaries
                physical-release-boundaries]
               ["STAGE1GOV009" :residual-trust-boundaries
                residual-trust-boundaries]
               ["STAGE1GOV009" :residual-release-governance-boundaries
                residual-release-governance-boundaries]
               ["STAGE1GOV009" :image-fallbacks image-fallbacks]
               ["STAGE1GOV009" :boot-chain-fallbacks
                boot-chain-fallbacks]
               ["STAGE1GOV009" :diverse-verification-fallbacks
                diverse-verification-fallbacks]
               ["STAGE1GOV009" :release-attestation-fallbacks
                release-attestation-fallbacks]
               ["STAGE1GOV009" :formal-release-governance-fallbacks
                formal-release-governance-fallbacks]]]
        (when (seq value)
          (stage1-reader-formal-release-governance-seed-retirement-fail!
           diagnostic source-path trace-value {field value})))
      (when-not (= #{:human-release-governance
                     :legal-custody-record-retention
                     :deployment-environment-custody}
                   (set replaced-release-governance-boundaries))
        (stage1-reader-formal-release-governance-seed-retirement-fail!
         "STAGE1GOV009" source-path trace-value
         {:replaced-release-governance-boundaries
          replaced-release-governance-boundaries}))
      (when-not (and (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :human-release-governance-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :legal-custody-record-retention-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :deployment-environment-custody-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-seed-retired?])))
        (stage1-reader-formal-release-governance-seed-retirement-fail!
         "STAGE1GOV010" source-path artifact-base
         {:missing-fields [:trusted-boundary]}))
      (when (and (true? (:clojure-seed-retired? self-hosting-evidence))
                 (not (true? (:full-language-compiler-self-hosted?
                              self-hosting-evidence))))
        (stage1-reader-formal-release-governance-seed-retirement-fail!
         "STAGE1GOV005" source-path self-hosting-evidence
         {:missing-fields [:full-language-compiler-self-hosted?]}))
      (let [capability-proof
            (stage1-reader-formal-release-governance-seed-retirement-proof
             artifact-base)]
        (assoc artifact-base
               :capability-based-proof capability-proof
               :artifact-id
               (c4-artifact-id (assoc artifact-base
                                      :capability-based-proof
                                      capability-proof)))))))

(defn stage1-reader-formal-release-governance-seed-retirement-file-artifact
  [path]
  (stage1-reader-formal-release-governance-seed-retirement-source-artifact
   path
   (slurp path)))

(defn p15-s23-whole-language-self-hosting-gate-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-whole-language-self-hosting-gate-diagnostic-messages
              id
              "P15-S23 whole-language self-hosting gate failed")
         (merge {:source-span {:source source-path}
                 :stage
                 :p15-s23-whole-language-self-hosting-gate
                 :diagnostic-family
                 :p15-s23-whole-language-self-hosting-gate
                 :value value
                 :remediation "Provide the complete BOOT1/BOOT3/BOOT6/BOOT7/BOOT8, C1/C2/C3/C6/C15, R1/R11, PKG7, TEST13, GOV6, and GOV10 evidence bundle before claiming full compiler self-hosting or retiring the Clojure seed."}
                data)))

(defn p15-s23-candidate-evidence-value
  [candidate key]
  (or (get candidate key)
      (get-in candidate [:evidence key])))

(defn p15-s23-evidence-present?
  [value]
  (cond
    (true? value) true
    (map? value) (contains? #{:accepted :clear :complete :passed
                              :present :reproducible :verified}
                            (:status value))
    (and (sequential? value) (seq value)) true
    :else false))

(defn p15-s23-diagnostic-record
  [source-path candidate requirement]
  (let [diagnostic (:diagnostic requirement)
        key (:key requirement)]
    {:artifact :gravity/diagnostic
     :diagnostic-id (str "diag-" (str/lower-case diagnostic))
     :diagnostic diagnostic
     :severity :error
     :stage :p15-s23-whole-language-self-hosting-gate
     :source-span {:source source-path}
     :candidate-id (:candidate-id candidate)
     :evidence-key key
     :governing-documents (:governing-documents requirement)
     :message (get p15-s23-whole-language-self-hosting-gate-diagnostic-messages
                   diagnostic)
     :facts {:required-evidence (:description requirement)
             :observed (p15-s23-candidate-evidence-value candidate key)}
     :remediation :supply_required_evidence_before_self_hosting_claim}))

(defn p15-s23-whole-language-self-hosting-gate-diagnostics
  [source-path candidate]
  (let [missing-evidence
        (mapv #(p15-s23-diagnostic-record source-path candidate %)
              (filter
               (fn [{:keys [key]}]
                 (not (p15-s23-evidence-present?
                       (p15-s23-candidate-evidence-value candidate key))))
               p15-s23-whole-language-self-hosting-required-evidence))
        seed-retired?
        (and (true? (:clojure-seed-retired? candidate))
             (false? (:clojure-seed-boundary? candidate)))
        seed-diagnostic
        (when-not seed-retired?
          [(p15-s23-diagnostic-record
            source-path
            candidate
            {:key :clojure-seed-retired
             :diagnostic "P15S23014"
             :governing-documents ["BOOT1" "BOOT3" "BOOT6" "TEST13"]
             :description :clojure_seed_boundary_is_absent})])
        required-missing?
        (seq (concat missing-evidence seed-diagnostic))
        overclaim?
        (and (or (true? (:full-language-compiler-self-hosted? candidate))
                 (true? (:clojure-seed-retired? candidate)))
             required-missing?)
        overclaim-diagnostic
        (when overclaim?
          [(assoc
            (p15-s23-diagnostic-record
             source-path
             candidate
             {:key :self-hosting-claim
              :diagnostic "P15S23016"
              :governing-documents ["BOOT1" "BOOT7" "BOOT8" "TEST13"]
              :description :full_self_hosting_claim_requires_complete_bundle})
            :facts
            {:full-language-compiler-self-hosted?
             (:full-language-compiler-self-hosted? candidate)
             :clojure-seed-retired? (:clojure-seed-retired? candidate)
             :missing-diagnostics
             (mapv :diagnostic (concat missing-evidence seed-diagnostic))})])]
    (vec (concat missing-evidence seed-diagnostic overclaim-diagnostic))))

(defn p15-s23-assert-whole-language-self-hosting-candidate!
  [source-path candidate]
  (let [diagnostics
        (p15-s23-whole-language-self-hosting-gate-diagnostics
         source-path candidate)]
    (when (seq diagnostics)
      (let [id (or (some #(when (= "P15S23016" (:diagnostic %))
                           (:diagnostic %))
                         diagnostics)
                   (:diagnostic (first diagnostics)))]
        (p15-s23-whole-language-self-hosting-gate-fail!
         id source-path candidate
         {:diagnostics diagnostics
          :missing-evidence (mapv :evidence-key diagnostics)})))
    candidate))

(defn p15-s23-whole-language-self-hosting-diagnostic-stream
  [source-path candidate diagnostics]
  {:artifact :gravity/p15-s23-whole-language-self-hosting-diagnostic-stream
   :stage :p15-s23-whole-language-self-hosting-gate
   :source-path source-path
   :candidate-id (:candidate-id candidate)
   :diagnostics diagnostics
   :summary {:errors (count diagnostics)
             :required-evidence
             (count p15-s23-whole-language-self-hosting-required-evidence)
             :status (if (seq diagnostics) :blocked :complete)}
   :status (if (seq diagnostics) :blocked :complete)})

