(def p15-s23-rejected-app-required-preserves
  #{:source-spans :diagnostic-codes :diagnostic-origin-chain :remediation
    :artifact-provenance :rejected-app-diagnostic-trace})

(def p15-s23-rejected-app-diagnostic-messages
  {"P15S23E001" "P15-S23 rejected app diagnostic proof is missing"
   "P15S23E002" "P15-S23 rejected app fixture manifest is incomplete"
   "P15S23E003" "P15-S23 rejected app fixture was accepted unexpectedly"
   "P15S23E004" "P15-S23 rejected app diagnostic is unstable or mismatched"
   "P15S23E005" "P15-S23 rejected app diagnostics are not linked to accepted app/compiler evidence"
   "P15S23E006" "P15-S23 rejected app diagnostic proof makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-rejected-app-diagnostic-ids
  ["P15S23E001" "P15S23E002" "P15S23E003"
   "P15S23E004" "P15S23E005" "P15S23E006"])

(defn p15-s23-rejected-app-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-rejected-app-diagnostic-messages
              id
              "P15-S23 rejected app diagnostic proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-rejected-app-diagnostic-proof
                 :diagnostic-family
                 :p15-s23-rejected-app-diagnostic-proof
                 :value value
                 :remediation "Run invalid Gravity app fixtures through the current compiled path, prove they fail closed with stable diagnostics, link the result to accepted app/compiler evidence, and keep self-hosting claims false until the complete P15-S23 bundle exists."}
                data)))

(defn p15-s23-rejected-app-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-rejected-app-diagnostic-proof
   :source-span {:source source-path}
   :message (get p15-s23-rejected-app-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_rejected_app_diagnostic_proof})

(defn p15-s23-run-rejected-app-fixture
  [compiled-runner {:keys [fixture expected-diagnostic rejected-design]}]
  (try
    {:fixture fixture
     :rejected-design rejected-design
     :expected-diagnostic expected-diagnostic
     :status :accepted-unexpectedly
     :stdout (compiled-runner fixture)
     :diagnostic nil
     :matches-expected? false}
    (catch clojure.lang.ExceptionInfo ex
      (let [data (ex-data ex)
            diagnostic (:id data)]
        {:fixture fixture
         :rejected-design rejected-design
         :expected-diagnostic expected-diagnostic
         :status :rejected
         :diagnostic diagnostic
         :message (:message data)
         :diagnostic-data
         (select-keys data
                      [:id :message :source-span :callee :actual-arity
                       :expected-arities :builtin :required-capability
                       :declared-capabilities :remediation])
         :matches-expected? (= expected-diagnostic diagnostic)}))))

(defn p15-s23-rejected-app-diagnostic-preservation-record
  [records]
  (let [diagnostics (mapv :diagnostic records)
        expected (mapv :expected-diagnostic records)]
    {:artifact :gravity/p15-s23-rejected-app-diagnostic-preservation-record
     :diagnostics diagnostics
     :expected-diagnostics expected
     :all-fixtures-rejected? (every? #(= :rejected (:status %)) records)
     :all-diagnostics-match? (every? true? (map :matches-expected? records))
     :diagnostic-codes-stable? (= (set diagnostics) (set expected))
     :source-spans-present?
     (every? #(get-in % [:diagnostic-data :source-span]) records)
     :remediations-present?
     (every? #(get-in % [:diagnostic-data :remediation]) records)
     :status
     (if (and (seq records)
              (every? #(= :rejected (:status %)) records)
              (every? true? (map :matches-expected? records))
              (= (set diagnostics) (set expected)))
       :complete
       :failed)}))

(defn p15-s23-rejected-app-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        records (:rejected-app-diagnostic-records candidate)
        preservation (:diagnostic-preservation-record candidate)
        accepted-app-artifact (:accepted-app-execution-artifact candidate)
        trusted-boundary (:trusted-boundary-record candidate)
        claims (:self-hosting-claims proof-contract)
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference p15-s23-rejected-app-required-preserves preserves)
        expected-fixtures (set (map :fixture p15-s23-rejected-app-fixtures))
        observed-fixtures (set (map :fixture records))]
    (vec
     (concat
      (when-not (= :gravity/rejected-app-diagnostic-proof
                   (:artifact proof-contract))
        [(p15-s23-rejected-app-diagnostic-record
          source-path "P15S23E001" proof-contract
          {:missing-fields [:artifact]})])
      (when-not (and (= expected-fixtures observed-fixtures)
                     (empty? missing-preserves))
        [(p15-s23-rejected-app-diagnostic-record
          source-path "P15S23E002" records
          {:expected-fixtures expected-fixtures
           :observed-fixtures observed-fixtures
           :missing-preserves (vec (sort missing-preserves))})])
      (when (some #(not= :rejected (:status %)) records)
        [(p15-s23-rejected-app-diagnostic-record
          source-path "P15S23E003" records
          {:accepted-fixtures
           (mapv :fixture (remove #(= :rejected (:status %)) records))})])
      (when-not (and (= :gravity/p15-s23-rejected-app-diagnostic-preservation-record
                        (:artifact preservation))
                     (= :complete (:status preservation))
                     (true? (:all-fixtures-rejected? preservation))
                     (true? (:all-diagnostics-match? preservation))
                     (true? (:diagnostic-codes-stable? preservation)))
        [(p15-s23-rejected-app-diagnostic-record
          source-path "P15S23E004" preservation
          {:expected-diagnostics
           (mapv :expected-diagnostic p15-s23-rejected-app-fixtures)})])
      (when-not
       (and (= :gravity/p15-s23-accepted-app-execution-artifact
               (:kind accepted-app-artifact))
            (= :gravity/p15-s23-runtime-manifest-capability-enforcement-artifact
               (get-in accepted-app-artifact
                       [:runtime-capability-artifact :kind]))
            (re-find #"^sha256:" (str (:artifact-id accepted-app-artifact)))
            (true? (:clojure-instruction-runner? trusted-boundary))
            (false? (:self-hosted-compiler? trusted-boundary))
            (false? (:clojure-seed-retired? trusted-boundary)))
        [(p15-s23-rejected-app-diagnostic-record
          source-path "P15S23E005" accepted-app-artifact
          {:required-links [:accepted-app-execution-artifact
                            :runtime-capability-artifact
                            :trusted-boundary-record]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-rejected-app-diagnostic-record
          source-path "P15S23E006" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-rejected-app-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-rejected-app-diagnostic-stream
   :stage :p15-s23-rejected-app-diagnostic-proof
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-rejected-app-diagnostic-proof
            :message (get p15-s23-rejected-app-diagnostic-messages id)})
         p15-s23-rejected-app-diagnostic-ids)
   :status :complete})

(defn p15-s23-rejected-app-rejected-candidates
  [accepted-candidate]
  [{:fixture :internal-p15-s23-rejected-app-missing-proof
    :candidate (assoc accepted-candidate :proof-contract {})
    :expected-diagnostic "P15S23E001"}
   {:fixture :internal-p15-s23-rejected-app-fixture-manifest-gap
    :candidate (assoc accepted-candidate
                      :rejected-app-diagnostic-records [])
    :expected-diagnostic "P15S23E002"}
   {:fixture :internal-p15-s23-rejected-app-accepted-unexpectedly
    :candidate (assoc-in accepted-candidate
                         [:rejected-app-diagnostic-records 0 :status]
                         :accepted-unexpectedly)
    :expected-diagnostic "P15S23E003"}
   {:fixture :internal-p15-s23-rejected-app-diagnostic-mismatch
    :candidate (-> accepted-candidate
                   (assoc-in [:rejected-app-diagnostic-records
                              0 :diagnostic]
                             "WRONG")
                   (assoc-in [:rejected-app-diagnostic-records
                              0 :matches-expected?]
                             false)
                   (assoc-in [:diagnostic-preservation-record
                              :all-diagnostics-match?]
                             false)
                   (assoc-in [:diagnostic-preservation-record :status]
                             :failed))
    :expected-diagnostic "P15S23E004"}
   {:fixture :internal-p15-s23-rejected-app-artifact-link-gap
    :candidate (assoc accepted-candidate
                      :accepted-app-execution-artifact {:kind :wrong})
    :expected-diagnostic "P15S23E005"}
   {:fixture :internal-p15-s23-rejected-app-overclaim
    :candidate (-> accepted-candidate
                   (assoc-in [:proof-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:proof-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23E006"}])

(defn p15-s23-rejected-app-rejected-records
  [source-path accepted-candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-rejected-app-proof-diagnostics source-path candidate)})
        (p15-s23-rejected-app-rejected-candidates accepted-candidate)))

(defn p15-s23-rejected-app-diagnostic-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-rejected-app-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-app-diagnostic-proof-fixtures
                      artifact)))
        preservation (:diagnostic-preservation-record artifact)
        boundary (:trusted-boundary-record artifact)]
    {:rejected-app-diagnostic-proof-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :fixture-manifest-complete?
     (= (set (map :fixture p15-s23-rejected-app-fixtures))
        (set (map :fixture (:rejected-app-diagnostic-records artifact))))
     :fixtures-rejected?
     (true? (:all-fixtures-rejected? preservation))
     :stable-diagnostics-covered?
     (true? (:diagnostic-codes-stable? preservation))
     :diagnostics-match-expected?
     (true? (:all-diagnostics-match? preservation))
     :accepted-app-proof-linked?
     (= :gravity/p15-s23-accepted-app-execution-artifact
        (get-in artifact [:accepted-app-execution-artifact :kind]))
     :runtime-capability-proof-linked?
     (= :gravity/p15-s23-runtime-manifest-capability-enforcement-artifact
        (get-in artifact
                [:accepted-app-execution-artifact
                 :runtime-capability-artifact :kind]))
     :trusted-boundaries-explicit?
     (and (true? (:clojure-instruction-runner? boundary))
          (false? (:self-hosted-compiler? boundary))
          (false? (:clojure-seed-retired? boundary)))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset? (set p15-s23-rejected-app-diagnostic-ids)
                  rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-rejected-app-diagnostic-ids) diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :clojure-instruction-runner? true
      :full-self-hosted-toolchain? false
      :next-required-capability
      :implement_reproducible_rebuild_log}}))

(defn p15-s23-rejected-app-diagnostic-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-rejected-app-diagnostic-proof)
        compiled-runner
        (resolve 'gravity.bootstrap/run-compiled-file)
        _ (when-not compiled-runner
            (p15-s23-rejected-app-fail!
             "P15S23E002" source-path nil
             {:missing-fields [:run-compiled-file]}))
        accepted-app-artifact
        (p15-s23-accepted-app-execution-source-artifact source-path)
        rejected-records
        (mapv #(p15-s23-run-rejected-app-fixture compiled-runner %)
              p15-s23-rejected-app-fixtures)
        preservation
        (p15-s23-rejected-app-diagnostic-preservation-record
         rejected-records)
        trusted-boundary
        (select-keys (:trusted-boundary-record accepted-app-artifact)
                     [:artifact :compiler :runtime :instruction-plan?
                      :direct-form-interpreter?
                      :clojure-instruction-runner?
                      :self-hosted-compiler?
                      :clojure-seed-retired?
                      :seed-boundary :retirement-condition :status])
        candidate {:proof-contract proof-contract
                   :rejected-app-diagnostic-records rejected-records
                   :diagnostic-preservation-record preservation
                   :accepted-app-execution-artifact accepted-app-artifact
                   :trusted-boundary-record trusted-boundary}
        diagnostics
        (p15-s23-rejected-app-proof-diagnostics source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-rejected-app-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :accepted-app-artifact
                       (:artifact-id accepted-app-artifact)
                       :rejected-diagnostics
                       (mapv :diagnostic rejected-records)
                       :proof-contract proof-contract})))
        rejected-candidate-records
        (p15-s23-rejected-app-rejected-records source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-rejected-app-diagnostic-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-rejected-app-diagnostic-proof
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :accepted-app-execution-artifact
         (select-keys accepted-app-artifact
                      [:kind :artifact-id :proof-id
                       :accepted-app-artifact
                       :accepted-output-comparison
                       :runtime-capability-artifact
                       :trusted-boundary-record
                       :capability-based-proof])
         :rejected-app-diagnostic-records rejected-records
         :diagnostic-preservation-record preservation
         :trusted-boundary-record trusted-boundary
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :verified-p15-s23-rejected-app-fixtures
         rejected-records
         :rejected-p15-s23-app-diagnostic-proof-fixtures
         rejected-candidate-records
         :p15-s23-rejected-app-diagnostic-stream
         (p15-s23-rejected-app-diagnostic-stream source-path proof-id)
         :p15-s23-rejected-app-diagnostic-results
         {:verified-rejected-fixtures (count rejected-records)
          :source-diagnostic-count
          (count (set (map :diagnostic rejected-records)))
          :diagnostic-count (count p15-s23-rejected-app-diagnostic-ids)
          :diagnostics (mapv :diagnostic rejected-records)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-rejected-app-diagnostic-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-rejected-app-diagnostic-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-rejected-app-fail!
     "P15S23E001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-rejected-app-diagnostic-source-artifact path))

(def p15-s23-reproducible-rebuild-stages
  [:compiler-source-inventory
   :compiler-pipeline-manifest
   :source-unit-and-syntax-serialization-proof
   :core-lowering-and-diagnostic-preservation-report
   :runtime-manifest-and-capability-enforcement-report
   :accepted-app-execution-proof
   :rejected-app-diagnostic-proof])

(def p15-s23-reproducible-rebuild-stage-commands
  {:compiler-source-inventory
   "p15-s23-compiler-source-inventory"
   :compiler-pipeline-manifest
   "p15-s23-compiler-pipeline-manifest"
   :source-unit-and-syntax-serialization-proof
   "p15-s23-source-syntax-serialization-proof"
   :core-lowering-and-diagnostic-preservation-report
   "p15-s23-core-lowering-diagnostic-preservation"
   :runtime-manifest-and-capability-enforcement-report
   "p15-s23-runtime-manifest-capability-enforcement"
   :accepted-app-execution-proof
   "p15-s23-accepted-app-execution"
   :rejected-app-diagnostic-proof
   "p15-s23-rejected-app-diagnostic"})

(def p15-s23-reproducible-rebuild-required-preserves
  #{:artifact-provenance :source-hash :proof-id :manifest-id
    :diagnostic-codes :rebuild-artifact-identity})

(def p15-s23-reproducible-rebuild-diagnostic-messages
  {"P15S23B001" "P15-S23 reproducible rebuild log is missing"
   "P15S23B002" "P15-S23 reproducible rebuild input set is incomplete"
   "P15S23B003" "P15-S23 rebuild produced nondeterministic artifact identity"
   "P15S23B004" "P15-S23 rebuild log is missing accepted/rejected app evidence links"
   "P15S23B005" "P15-S23 rebuild environment or provenance record is incomplete"
   "P15S23B006" "P15-S23 rebuild log makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-reproducible-rebuild-diagnostic-ids
  ["P15S23B001" "P15S23B002" "P15S23B003"
   "P15S23B004" "P15S23B005" "P15S23B006"])

(defn p15-s23-reproducible-rebuild-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-reproducible-rebuild-diagnostic-messages
              id
              "P15-S23 reproducible rebuild proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-reproducible-rebuild-log
                 :diagnostic-family
                 :p15-s23-reproducible-rebuild-log
                 :value value
                 :remediation "Rebuild the current P15-S23 evidence bundle twice, compare artifact/proof/manifest identities, record the Clojure seed environment boundary, and keep self-hosting claims false until the full evidence bundle exists."}
                data)))

(defn p15-s23-reproducible-rebuild-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-reproducible-rebuild-log
   :source-span {:source source-path}
   :message (get p15-s23-reproducible-rebuild-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_reproducible_rebuild_log})

(defn p15-s23-rebuild-stage-artifact
  [source-path stage]
  (case stage
    :compiler-source-inventory
    (p15-s23-compiler-source-inventory-source-artifact source-path)
    :compiler-pipeline-manifest
    (p15-s23-compiler-pipeline-manifest-source-artifact source-path)
    :source-unit-and-syntax-serialization-proof
    (p15-s23-source-syntax-serialization-proof-source-artifact source-path)
    :core-lowering-and-diagnostic-preservation-report
    (p15-s23-core-lowering-diagnostic-preservation-source-artifact
     source-path)
    :runtime-manifest-and-capability-enforcement-report
    (p15-s23-runtime-manifest-capability-enforcement-source-artifact
     source-path)
    :accepted-app-execution-proof
    (p15-s23-accepted-app-execution-source-artifact source-path)
    :rejected-app-diagnostic-proof
    (p15-s23-rejected-app-diagnostic-source-artifact source-path)))

(defn p15-s23-rebuild-stage-record
  [source-path stage]
  (let [artifact (p15-s23-rebuild-stage-artifact source-path stage)]
    {:stage stage
     :kind (:kind artifact)
     :artifact-id (:artifact-id artifact)
     :proof-id (:proof-id artifact)
     :manifest-id (:manifest-id artifact)
     :serialization-id (get-in artifact
                               [:serialization-roundtrip-record
                                :serialization-id])
     :diagnostics
     (or (get-in artifact
                 [:p15-s23-rejected-app-diagnostic-results
                  :diagnostics])
         (mapv :diagnostic (:diagnostics artifact)))
     :full-language-compiler-self-hosted?
     (:full-language-compiler-self-hosted? artifact)
     :clojure-seed-retired? (:clojure-seed-retired? artifact)}))

(defn p15-s23-rebuild-record
  [source-path pass]
  {:artifact :gravity/p15-s23-rebuild-record
   :pass pass
   :source-path source-path
   :source-id (str "sha256:" (sha256-hex (slurp source-path)))
   :stages
   (mapv #(p15-s23-rebuild-stage-record source-path %)
         p15-s23-reproducible-rebuild-stages)
   :status :complete})

(defn p15-s23-rebuild-comparison-row
  [first-row second-row]
  {:stage (:stage first-row)
   :first (select-keys first-row
                       [:kind :artifact-id :proof-id :manifest-id
                        :serialization-id])
   :second (select-keys second-row
                        [:kind :artifact-id :proof-id :manifest-id
                         :serialization-id])
   :artifact-id-match? (= (:artifact-id first-row)
                          (:artifact-id second-row))
   :proof-id-match? (= (:proof-id first-row)
                       (:proof-id second-row))
   :manifest-id-match? (= (:manifest-id first-row)
                          (:manifest-id second-row))
   :serialization-id-match? (= (:serialization-id first-row)
                               (:serialization-id second-row))
   :diagnostics-match? (= (:diagnostics first-row)
                          (:diagnostics second-row))})

(defn p15-s23-artifact-identity-comparison
  [first-rebuild second-rebuild]
  (let [rows (mapv p15-s23-rebuild-comparison-row
                   (:stages first-rebuild)
                   (:stages second-rebuild))
        all-match?
        (every? #(and (:artifact-id-match? %)
                      (:proof-id-match? %)
                      (:manifest-id-match? %)
                      (:serialization-id-match? %)
                      (:diagnostics-match? %))
                rows)]
    {:artifact :gravity/p15-s23-artifact-identity-comparison
     :rows rows
     :all-artifact-identities-match? all-match?
     :status (if all-match? :complete :failed)}))

(defn p15-s23-rebuild-environment-provenance-record
  [source-path proof-contract]
  {:artifact :gravity/p15-s23-rebuild-environment-provenance-record
   :source-path source-path
   :source-id (str "sha256:" (sha256-hex (slurp source-path)))
   :seed-boundary :clojure-stage0
   :host-runtime :clojure/jvm
   :ambient-authority-denied? true
   :commands
   (mapv (fn [stage]
           {:stage stage
            :command
            (str "clojure -M:gravity "
                 (get p15-s23-reproducible-rebuild-stage-commands
                      stage)
                 " "
                 source-path)})
         p15-s23-reproducible-rebuild-stages)
   :proof-contract-artifact (:artifact proof-contract)
   :status :complete})

(defn p15-s23-reproducible-rebuild-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        first-rebuild (:first-rebuild-record candidate)
        second-rebuild (:second-rebuild-record candidate)
        comparison (:artifact-identity-comparison candidate)
        environment (:environment-provenance-record candidate)
        stages (set (map :stage (:stages first-rebuild)))
        claims (:self-hosting-claims proof-contract)
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference p15-s23-reproducible-rebuild-required-preserves
                        preserves)]
    (vec
     (concat
      (when-not (= :gravity/reproducible-rebuild-log
                   (:artifact proof-contract))
        [(p15-s23-reproducible-rebuild-diagnostic-record
          source-path "P15S23B001" proof-contract
          {:missing-fields [:artifact]})])
      (when-not
       (and (= (set p15-s23-reproducible-rebuild-stages) stages)
            (= stages (set (map :stage (:stages second-rebuild))))
            (empty? missing-preserves))
        [(p15-s23-reproducible-rebuild-diagnostic-record
          source-path "P15S23B002" first-rebuild
          {:expected-stages p15-s23-reproducible-rebuild-stages
           :observed-stages (vec (sort stages))
           :missing-preserves (vec (sort missing-preserves))})])
      (when-not
       (and (= :gravity/p15-s23-artifact-identity-comparison
               (:artifact comparison))
            (= :complete (:status comparison))
            (true? (:all-artifact-identities-match? comparison)))
        [(p15-s23-reproducible-rebuild-diagnostic-record
          source-path "P15S23B003" comparison
          {:mismatched-stages
           (mapv :stage (remove :artifact-id-match?
                                (:rows comparison)))})])
      (when-not
       (and (contains? stages :accepted-app-execution-proof)
            (contains? stages :rejected-app-diagnostic-proof))
        [(p15-s23-reproducible-rebuild-diagnostic-record
          source-path "P15S23B004" first-rebuild
          {:required-links [:accepted-app-execution-proof
                            :rejected-app-diagnostic-proof]})])
      (when-not
       (and (= :gravity/p15-s23-rebuild-environment-provenance-record
               (:artifact environment))
            (= :complete (:status environment))
            (= :clojure-stage0 (:seed-boundary environment))
            (true? (:ambient-authority-denied? environment))
            (= (count p15-s23-reproducible-rebuild-stages)
               (count (:commands environment))))
        [(p15-s23-reproducible-rebuild-diagnostic-record
          source-path "P15S23B005" environment
          {:required-fields [:seed-boundary :commands
                             :ambient-authority-denied?]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-reproducible-rebuild-diagnostic-record
          source-path "P15S23B006" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-reproducible-rebuild-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-reproducible-rebuild-diagnostic-stream
   :stage :p15-s23-reproducible-rebuild-log
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-reproducible-rebuild-log
            :message (get p15-s23-reproducible-rebuild-diagnostic-messages
                          id)})
         p15-s23-reproducible-rebuild-diagnostic-ids)
   :status :complete})

(defn p15-s23-reproducible-rebuild-rejected-candidates
  [accepted-candidate]
  [{:fixture :internal-p15-s23-rebuild-missing-log
    :candidate (assoc accepted-candidate :proof-contract {})
    :expected-diagnostic "P15S23B001"}
   {:fixture :internal-p15-s23-rebuild-input-gap
    :candidate (update-in accepted-candidate
                          [:first-rebuild-record :stages]
                          subvec 0 3)
    :expected-diagnostic "P15S23B002"}
   {:fixture :internal-p15-s23-rebuild-nondeterministic-artifact
    :candidate (assoc-in accepted-candidate
                         [:artifact-identity-comparison :status]
                         :failed)
    :expected-diagnostic "P15S23B003"}
   {:fixture :internal-p15-s23-rebuild-link-gap
    :candidate (update-in accepted-candidate
                          [:first-rebuild-record :stages]
                          #(vec (remove (fn [row]
                                           (= :rejected-app-diagnostic-proof
                                              (:stage row)))
                                         %)))
    :expected-diagnostic "P15S23B004"}
   {:fixture :internal-p15-s23-rebuild-environment-gap
    :candidate (assoc-in accepted-candidate
                         [:environment-provenance-record
                          :ambient-authority-denied?]
                         false)
    :expected-diagnostic "P15S23B005"}
   {:fixture :internal-p15-s23-rebuild-overclaim
    :candidate (-> accepted-candidate
                   (assoc-in [:proof-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:proof-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23B006"}])

(defn p15-s23-reproducible-rebuild-rejected-records
  [source-path accepted-candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-reproducible-rebuild-proof-diagnostics
            source-path candidate)})
        (p15-s23-reproducible-rebuild-rejected-candidates
         accepted-candidate)))

(defn p15-s23-reproducible-rebuild-log-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-reproducible-rebuild-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-rebuild-proof-fixtures
                      artifact)))
        comparison (:artifact-identity-comparison artifact)]
    {:reproducible-rebuild-log-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :rebuild-inputs-complete?
     (= (set p15-s23-reproducible-rebuild-stages)
        (set (map :stage (get-in artifact
                                  [:first-rebuild-record :stages]))))
     :second-rebuild-inputs-complete?
     (= (set p15-s23-reproducible-rebuild-stages)
        (set (map :stage (get-in artifact
                                  [:second-rebuild-record :stages]))))
     :artifact-identities-reproducible?
     (true? (:all-artifact-identities-match? comparison))
     :accepted-app-proof-linked?
     (boolean
      (some #(= :accepted-app-execution-proof (:stage %))
            (get-in artifact [:first-rebuild-record :stages])))
     :rejected-app-proof-linked?
     (boolean
      (some #(= :rejected-app-diagnostic-proof (:stage %))
            (get-in artifact [:first-rebuild-record :stages])))
     :environment-provenance-recorded?
     (= :complete (get-in artifact
                          [:environment-provenance-record :status]))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset? (set p15-s23-reproducible-rebuild-diagnostic-ids)
                  rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-reproducible-rebuild-diagnostic-ids) diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :clojure-stage0-rebuild? true
      :full-self-hosted-toolchain? false
      :next-required-capability
      :implement_stage_comparison_report}}))

(defn p15-s23-reproducible-rebuild-log-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-reproducible-rebuild-log)
        first-rebuild (p15-s23-rebuild-record source-path :first)
        second-rebuild (p15-s23-rebuild-record source-path :second)
        comparison
        (p15-s23-artifact-identity-comparison first-rebuild
                                              second-rebuild)
        environment
        (p15-s23-rebuild-environment-provenance-record source-path
                                                       proof-contract)
        candidate {:proof-contract proof-contract
                   :first-rebuild-record first-rebuild
                   :second-rebuild-record second-rebuild
                   :artifact-identity-comparison comparison
                   :environment-provenance-record environment}
        diagnostics
        (p15-s23-reproducible-rebuild-proof-diagnostics source-path
                                                        candidate)
        _ (when (seq diagnostics)
            (p15-s23-reproducible-rebuild-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :first (mapv #(select-keys %
                                                   [:stage :artifact-id
                                                    :proof-id
                                                    :manifest-id
                                                    :serialization-id])
                                     (:stages first-rebuild))
                       :second (mapv #(select-keys %
                                                    [:stage :artifact-id
                                                     :proof-id
                                                     :manifest-id
                                                     :serialization-id])
                                      (:stages second-rebuild))
                       :proof-contract proof-contract})))
        rejected-records
        (p15-s23-reproducible-rebuild-rejected-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-reproducible-rebuild-log-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-reproducible-rebuild-log
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :first-rebuild-record first-rebuild
         :second-rebuild-record second-rebuild
         :artifact-identity-comparison comparison
         :environment-provenance-record environment
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-rebuild-fixtures
         [{:fixture source-path
           :status :accepted
           :rebuild-stage-count
           (count p15-s23-reproducible-rebuild-stages)
           :all-artifact-identities-match?
           (:all-artifact-identities-match? comparison)}]
         :rejected-p15-s23-rebuild-proof-fixtures rejected-records
         :p15-s23-reproducible-rebuild-diagnostic-stream
         (p15-s23-reproducible-rebuild-diagnostic-stream source-path
                                                         proof-id)
         :p15-s23-reproducible-rebuild-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-reproducible-rebuild-diagnostic-ids)
          :rebuild-stage-count
          (count p15-s23-reproducible-rebuild-stages)
          :all-artifact-identities-match?
          (:all-artifact-identities-match? comparison)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-reproducible-rebuild-log-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-reproducible-rebuild-log-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-reproducible-rebuild-fail!
     "P15S23B001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-reproducible-rebuild-log-source-artifact path))

(def p15-s23-stage-comparison-scope
  [:compiler-pipeline-manifest
   :accepted-app-execution-proof
   :rejected-app-diagnostic-proof
   :reproducible-rebuild-log])

(def p15-s23-stage-comparison-required-preserves
  #{:artifact-provenance :accepted-app-output
    :rejected-app-diagnostic-trace :diagnostic-codes
    :stage-equivalence-record})

(def p15-s23-stage-comparison-diagnostic-messages
  {"P15S23G001" "P15-S23 stage comparison report is missing"
   "P15S23G002" "P15-S23 stage comparison candidate or scope is incomplete"
   "P15S23G003" "P15-S23 accepted output differs between compared stages"
   "P15S23G004" "P15-S23 rejected diagnostics differ between compared stages"
   "P15S23G005" "P15-S23 stage comparison is not linked to a reproducible rebuild log"
   "P15S23G006" "P15-S23 stage comparison makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-stage-comparison-diagnostic-ids
  ["P15S23G001" "P15S23G002" "P15S23G003"
   "P15S23G004" "P15S23G005" "P15S23G006"])

(defn p15-s23-stage-comparison-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage-comparison-diagnostic-messages
              id
              "P15-S23 stage comparison proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage-comparison-report
                 :diagnostic-family :p15-s23-stage-comparison-report
                 :value value
                 :remediation "Compare the current P15-S23 candidate with the seed-stage behavior, preserve accepted output and rejected diagnostics, link the reproducible rebuild log, and keep self-hosting claims false until the full evidence bundle exists."}
                data)))

(defn p15-s23-stage-comparison-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage-comparison-report
   :source-span {:source source-path}
   :message (get p15-s23-stage-comparison-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_stage_comparison_report})

(defn p15-s23-stage-boundary-record
  [source-path]
  {:artifact :gravity/p15-s23-stage-boundary-record
   :source-path source-path
   :seed-stage :clojure-stage0
   :candidate-stage :p15-s23-current-clojure-seed-candidate
   :candidate-is-self-hosted? false
   :full-self-hosted-equivalence? false
   :clojure-seed-boundary? true
   :full-self-hosted-toolchain? false
   :retirement-condition :complete-p15-s23-evidence-bundle
   :status :complete})

(defn p15-s23-accepted-output-stage-comparison
  [accepted-artifact]
  (let [comparison (:accepted-output-comparison accepted-artifact)]
    {:artifact :gravity/p15-s23-accepted-output-stage-comparison
     :accepted-app-path (:accepted-app-path accepted-artifact)
     :seed-stage :clojure-stage0-reference-run
     :candidate-stage :current-compiled-instruction-plan
     :seed-stdout (:reference-stdout comparison)
     :candidate-stdout (:accepted-stdout comparison)
     :expected-stdout (:expected-stdout comparison)
     :accepted-output-equivalent?
     (and (= :complete (:status comparison))
          (true? (:accepted-matches-reference? comparison))
          (true? (:accepted-matches-expected? comparison)))
     :compiled-plan-id
     (get-in accepted-artifact
             [:compiled-plan-execution-trace :compiled-plan-id])
     :status :complete}))

(defn p15-s23-rejected-diagnostic-stage-comparison
  [rejected-artifact]
  (let [preservation (:diagnostic-preservation-record rejected-artifact)]
    {:artifact :gravity/p15-s23-rejected-diagnostic-stage-comparison
     :seed-stage :clojure-stage0-diagnostics
     :candidate-stage :current-compiled-instruction-plan-diagnostics
     :expected-diagnostics (:expected-diagnostics preservation)
     :candidate-diagnostics (:diagnostics preservation)
     :rejected-diagnostics-equivalent?
     (and (= :complete (:status preservation))
          (true? (:all-fixtures-rejected? preservation))
          (true? (:all-diagnostics-match? preservation))
          (true? (:diagnostic-codes-stable? preservation)))
     :status :complete}))

(defn p15-s23-stage-equivalence-row
  [scope artifact-id proof-id status equivalent?]
  {:scope scope
   :artifact-id artifact-id
   :proof-id proof-id
   :status status
   :equivalent? equivalent?})

(defn p15-s23-stage-equivalence-matrix
  [pipeline-artifact accepted-artifact rejected-artifact rebuild-artifact
   accepted-comparison rejected-comparison]
  (let [rows
        [(p15-s23-stage-equivalence-row
          :compiler-pipeline-manifest
          (:artifact-id pipeline-artifact)
          (:manifest-id pipeline-artifact)
          :complete true)
         (p15-s23-stage-equivalence-row
          :accepted-app-execution-proof
          (:artifact-id accepted-artifact)
          (:proof-id accepted-artifact)
          :complete
          (true? (:accepted-output-equivalent? accepted-comparison)))
         (p15-s23-stage-equivalence-row
          :rejected-app-diagnostic-proof
          (:artifact-id rejected-artifact)
          (:proof-id rejected-artifact)
          :complete
          (true? (:rejected-diagnostics-equivalent?
                  rejected-comparison)))
         (p15-s23-stage-equivalence-row
          :reproducible-rebuild-log
          (:artifact-id rebuild-artifact)
          (:proof-id rebuild-artifact)
          (get-in rebuild-artifact
                  [:artifact-identity-comparison :status])
          (true?
           (get-in rebuild-artifact
                   [:artifact-identity-comparison
                    :all-artifact-identities-match?])))]]
    {:artifact :gravity/p15-s23-stage-equivalence-matrix
     :rows rows
     :current-candidate-equivalent-to-seed?
     (every? true? (map :equivalent? rows))
     :full-self-hosted-equivalence? false
     :status (if (every? true? (map :equivalent? rows))
               :complete
               :failed)}))

(defn p15-s23-stage-comparison-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        boundary (:stage-boundary-record candidate)
        accepted (:accepted-output-stage-comparison candidate)
        rejected (:rejected-diagnostic-stage-comparison candidate)
        rebuild (:reproducible-rebuild-artifact candidate)
        matrix (:stage-equivalence-matrix candidate)
        claims (:self-hosting-claims proof-contract)
        scope (set (:comparison-scope proof-contract))
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference p15-s23-stage-comparison-required-preserves
                        preserves)]
    (vec
     (concat
      (when-not (= :gravity/stage-comparison-report
                   (:artifact proof-contract))
        [(p15-s23-stage-comparison-diagnostic-record
          source-path "P15S23G001" proof-contract
          {:missing-fields [:artifact]})])
      (when-not
       (and (= (set p15-s23-stage-comparison-scope) scope)
            (empty? missing-preserves)
            (= :gravity/p15-s23-stage-boundary-record
               (:artifact boundary))
            (= :complete (:status boundary))
            (= :clojure-stage0 (:seed-stage boundary))
            (true? (:clojure-seed-boundary? boundary))
            (false? (:candidate-is-self-hosted? boundary)))
        [(p15-s23-stage-comparison-diagnostic-record
          source-path "P15S23G002" candidate
          {:expected-scope p15-s23-stage-comparison-scope
           :observed-scope (vec (sort scope))
           :missing-preserves (vec (sort missing-preserves))})])
      (when-not
       (and (= :gravity/p15-s23-accepted-output-stage-comparison
               (:artifact accepted))
            (= :complete (:status accepted))
            (true? (:accepted-output-equivalent? accepted)))
        [(p15-s23-stage-comparison-diagnostic-record
          source-path "P15S23G003" accepted
          {:expected-stdout (:expected-stdout accepted)
           :seed-stdout (:seed-stdout accepted)
           :candidate-stdout (:candidate-stdout accepted)})])
      (when-not
       (and (= :gravity/p15-s23-rejected-diagnostic-stage-comparison
               (:artifact rejected))
            (= :complete (:status rejected))
            (true? (:rejected-diagnostics-equivalent? rejected)))
        [(p15-s23-stage-comparison-diagnostic-record
          source-path "P15S23G004" rejected
          {:expected-diagnostics (:expected-diagnostics rejected)
           :candidate-diagnostics (:candidate-diagnostics rejected)})])
      (when-not
       (and (= :gravity/p15-s23-reproducible-rebuild-log-artifact
               (:kind rebuild))
            (true?
             (get-in rebuild
                     [:artifact-identity-comparison
                      :all-artifact-identities-match?]))
            (= :gravity/p15-s23-stage-equivalence-matrix
               (:artifact matrix))
            (= :complete (:status matrix))
            (true? (:current-candidate-equivalent-to-seed? matrix)))
        [(p15-s23-stage-comparison-diagnostic-record
          source-path "P15S23G005" rebuild
          {:required-link :reproducible-rebuild-log
           :matrix-status (:status matrix)})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-stage-comparison-diagnostic-record
          source-path "P15S23G006" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-stage-comparison-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-stage-comparison-diagnostic-stream
   :stage :p15-s23-stage-comparison-report
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-stage-comparison-report
            :message
            (get p15-s23-stage-comparison-diagnostic-messages id)})
         p15-s23-stage-comparison-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage-comparison-rejected-candidates
  [accepted-candidate]
  [{:fixture :internal-p15-s23-stage-comparison-missing-report
    :candidate (assoc accepted-candidate :proof-contract {})
    :expected-diagnostic "P15S23G001"}
   {:fixture :internal-p15-s23-stage-comparison-candidate-gap
    :candidate (update-in accepted-candidate
                          [:proof-contract :comparison-scope]
                          subvec 0 2)
    :expected-diagnostic "P15S23G002"}
   {:fixture :internal-p15-s23-stage-comparison-output-mismatch
    :candidate (assoc-in accepted-candidate
                         [:accepted-output-stage-comparison
                          :accepted-output-equivalent?]
                         false)
    :expected-diagnostic "P15S23G003"}
   {:fixture :internal-p15-s23-stage-comparison-diagnostic-mismatch
    :candidate (assoc-in accepted-candidate
                         [:rejected-diagnostic-stage-comparison
                          :rejected-diagnostics-equivalent?]
                         false)
    :expected-diagnostic "P15S23G004"}
   {:fixture :internal-p15-s23-stage-comparison-rebuild-link-gap
    :candidate (assoc-in accepted-candidate
                         [:reproducible-rebuild-artifact
                          :artifact-identity-comparison
                          :all-artifact-identities-match?]
                         false)
    :expected-diagnostic "P15S23G005"}
   {:fixture :internal-p15-s23-stage-comparison-overclaim
    :candidate (-> accepted-candidate
                   (assoc-in [:proof-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:proof-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23G006"}])

(defn p15-s23-stage-comparison-rejected-records
  [source-path accepted-candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-stage-comparison-proof-diagnostics
            source-path candidate)})
        (p15-s23-stage-comparison-rejected-candidates
         accepted-candidate)))

(defn p15-s23-stage-comparison-report-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-stage-comparison-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-stage-comparison-fixtures
                      artifact)))
        matrix (:stage-equivalence-matrix artifact)
        boundary (:stage-boundary-record artifact)]
    {:stage-comparison-report-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :comparison-scope-complete?
     (= (set p15-s23-stage-comparison-scope)
        (set (map :scope (:rows matrix))))
     :current-candidate-equivalent-to-seed?
     (true? (:current-candidate-equivalent-to-seed? matrix))
     :accepted-output-equivalent?
     (true? (get-in artifact
                    [:accepted-output-stage-comparison
                     :accepted-output-equivalent?]))
     :rejected-diagnostics-equivalent?
     (true? (get-in artifact
                    [:rejected-diagnostic-stage-comparison
                     :rejected-diagnostics-equivalent?]))
     :rebuild-log-linked?
     (= :gravity/p15-s23-reproducible-rebuild-log-artifact
        (get-in artifact [:reproducible-rebuild-artifact :kind]))
     :stage-boundary-explicit?
     (and (= :clojure-stage0 (:seed-stage boundary))
          (true? (:clojure-seed-boundary? boundary))
          (false? (:candidate-is-self-hosted? boundary))
          (false? (:full-self-hosted-equivalence? boundary)))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset? (set p15-s23-stage-comparison-diagnostic-ids)
                  rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-stage-comparison-diagnostic-ids) diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :current-candidate-is-clojure-seed? true
      :full-self-hosted-equivalence? false
      :full-self-hosted-toolchain? false
      :next-required-capability
      :implement_conformance_report}}))

(defn p15-s23-stage-comparison-report-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-stage-comparison-report)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact source-path)
        accepted-artifact
        (p15-s23-accepted-app-execution-source-artifact source-path)
        rejected-artifact
        (p15-s23-rejected-app-diagnostic-source-artifact source-path)
        rebuild-artifact
        (p15-s23-reproducible-rebuild-log-source-artifact source-path)
        boundary
        (p15-s23-stage-boundary-record source-path)
        accepted-comparison
        (p15-s23-accepted-output-stage-comparison accepted-artifact)
        rejected-comparison
        (p15-s23-rejected-diagnostic-stage-comparison rejected-artifact)
        matrix
        (p15-s23-stage-equivalence-matrix
         pipeline-artifact accepted-artifact rejected-artifact
         rebuild-artifact accepted-comparison rejected-comparison)
        candidate {:proof-contract proof-contract
                   :stage-boundary-record boundary
                   :accepted-output-stage-comparison accepted-comparison
                   :rejected-diagnostic-stage-comparison rejected-comparison
                   :reproducible-rebuild-artifact rebuild-artifact
                   :stage-equivalence-matrix matrix}
        diagnostics
        (p15-s23-stage-comparison-proof-diagnostics source-path
                                                    candidate)
        _ (when (seq diagnostics)
            (p15-s23-stage-comparison-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :proof-contract proof-contract
                       :pipeline-artifact (:artifact-id pipeline-artifact)
                       :accepted-artifact (:artifact-id accepted-artifact)
                       :rejected-artifact (:artifact-id rejected-artifact)
                       :rebuild-artifact (:artifact-id rebuild-artifact)
                       :accepted-stdout
                       (:candidate-stdout accepted-comparison)
                       :rejected-diagnostics
                       (:candidate-diagnostics rejected-comparison)
                       :matrix (:rows matrix)})))
        rejected-records
        (p15-s23-stage-comparison-rejected-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-stage-comparison-report-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-stage-comparison-report
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :compiler-pipeline-manifest-artifact
         (select-keys pipeline-artifact
                      [:kind :artifact-id :manifest-id
                       :capability-based-proof])
         :accepted-app-execution-artifact
         (select-keys accepted-artifact
                      [:kind :artifact-id :proof-id
                       :accepted-output-comparison
                       :compiled-plan-execution-trace
                       :trusted-boundary-record
                       :capability-based-proof])
         :rejected-app-diagnostic-artifact
         (select-keys rejected-artifact
                      [:kind :artifact-id :proof-id
                       :diagnostic-preservation-record
                       :rejected-app-diagnostic-records
                       :trusted-boundary-record
                       :capability-based-proof])
         :reproducible-rebuild-artifact
         (select-keys rebuild-artifact
                      [:kind :artifact-id :proof-id
                       :artifact-identity-comparison
                       :environment-provenance-record
                       :capability-based-proof])
         :stage-boundary-record boundary
         :accepted-output-stage-comparison accepted-comparison
         :rejected-diagnostic-stage-comparison rejected-comparison
         :stage-equivalence-matrix matrix
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-stage-comparison-fixtures
         [{:fixture source-path
           :status :accepted
           :stage-comparison-row-count (count (:rows matrix))
           :current-candidate-equivalent-to-seed?
           (:current-candidate-equivalent-to-seed? matrix)
           :full-self-hosted-equivalence? false}]
         :rejected-p15-s23-stage-comparison-fixtures
         rejected-records
         :p15-s23-stage-comparison-diagnostic-stream
         (p15-s23-stage-comparison-diagnostic-stream source-path
                                                     proof-id)
         :p15-s23-stage-comparison-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-stage-comparison-diagnostic-ids)
          :stage-comparison-row-count (count (:rows matrix))
          :current-candidate-equivalent-to-seed?
          (:current-candidate-equivalent-to-seed? matrix)
          :full-self-hosted-equivalence? false
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-stage-comparison-report-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-stage-comparison-report-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-stage-comparison-fail!
     "P15S23G001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-stage-comparison-report-source-artifact path))

(def p15-s23-self-hosting-conformance-scope
  [:phase14-hosted-core-compiled-conformance
   :test13-self-hosting-validation
   :p15-s23-stage-comparison])

(def p15-s23-self-hosting-conformance-required-preserves
  #{:artifact-provenance :conformance-suite-status
    :diagnostic-codes :source-spans
    :stage-support-matrix :stage-equivalence-record})

(def p15-s23-self-hosting-conformance-diagnostic-messages
  {"P15S23H001" "P15-S23 self-hosting conformance report is missing"
   "P15S23H002" "P15-S23 conformance suite scope or stage support record is incomplete"
   "P15S23H003" "P15-S23 linked Phase 14 conformance evidence is incomplete"
   "P15S23H004" "P15-S23 stage comparison evidence is missing or not equivalent"
   "P15S23H005" "P15-S23 diagnostic conformance regressed"
   "P15S23H006" "P15-S23 conformance report makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-self-hosting-conformance-diagnostic-ids
  ["P15S23H001" "P15S23H002" "P15S23H003"
   "P15S23H004" "P15S23H005" "P15S23H006"])

(defn p15-s23-self-hosting-conformance-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-self-hosting-conformance-diagnostic-messages
              id
              "P15-S23 self-hosting conformance proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-self-hosting-conformance-report
                 :diagnostic-family
                 :p15-s23-self-hosting-conformance-report
                 :value value
                 :remediation "Link the current P15-S23 stage comparison with the Phase 14 conformance metadata and TEST13 self-hosting validation record, preserve stable diagnostics and source spans, and keep full self-hosting claims false until the full evidence bundle exists."}
                data)))

(defn p15-s23-self-hosting-conformance-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-self-hosting-conformance-report
   :source-span {:source source-path}
   :message (get p15-s23-self-hosting-conformance-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_self_hosting_conformance_report})

(defn p15-s23-stage-support-conformance-record
  [source-path stage-artifact phase14-artifact]
  (let [report (:conformance-report phase14-artifact)
        conformance (:conformance-results report)
        self-hosting (:self-hosting-validation-record report)
        stage-matrix (:stage-equivalence-matrix stage-artifact)
        diagnostic-record
        (get-in stage-artifact
                [:rejected-app-diagnostic-artifact
                 :diagnostic-preservation-record])
        conformant?
        (and (= :complete (get-in report
                                  [:conformance-manifest :status]))
             (= :complete (:status self-hosting))
             (= :complete (:status stage-matrix))
             (true? (:current-candidate-equivalent-to-seed?
                     stage-matrix))
             (= :metadata-gate-only
                (:conformance-gate-status conformance))
             (true? (:all-diagnostics-match? diagnostic-record)))]
    {:artifact :gravity/p15-s23-stage-support-conformance-record
     :source-path source-path
     :stage :p15-s23-current-clojure-seed-candidate
     :declared-support-level :current-compiled-core-app-slice
     :supported-profiles [:hosted]
     :supported-backends [:jvm-instruction-plan]
     :supported-runtimes [:managed-clojure-jvm-instruction-runner]
     :supported-test-suites (:document-set report)
     :conformance-gate-status (:conformance-gate-status conformance)
     :required-diagnostic-count
     (count (:required-diagnostic-ids conformance))
     :stage-comparison-row-count (count (:rows stage-matrix))
     :phase14-conformance-status (get-in report
                                         [:conformance-manifest :status])
     :test13-self-hosting-status (:status self-hosting)
     :stage-support-conformant? (boolean conformant?)
     :release-eligible? false
     :status (if conformant? :complete :failed)}))

(defn p15-s23-conformance-suite-link-table
  [stage-artifact phase14-artifact]
  (let [report (:conformance-report phase14-artifact)
        self-hosting (:self-hosting-validation-record report)
        phase14-linked?
        (and (= :gravity/stage0-hosted-core-compiled-conformance-proof
                (:kind phase14-artifact))
             (= :complete
                (get-in phase14-artifact
                        [:capability-based-proof :status])))
        test13-linked?
        (and (= "TEST13" (name (:document self-hosting)))
             (= :complete (:status self-hosting)))
        stage-linked?
        (and (= :gravity/p15-s23-stage-comparison-report-artifact
                (:kind stage-artifact))
             (true?
              (get-in stage-artifact
                      [:stage-equivalence-matrix
                       :current-candidate-equivalent-to-seed?])))]
    {:artifact :gravity/p15-s23-conformance-suite-link-table
     :phase14-conformance-linked? (boolean phase14-linked?)
     :test13-self-hosting-linked? (boolean test13-linked?)
     :stage-comparison-linked? (boolean stage-linked?)
     :linked-suites
     [{:suite :phase14-hosted-core-compiled-conformance
       :artifact-id (:artifact-id phase14-artifact)
       :report-id (get-in report [:report-id])
       :status (get-in report [:conformance-manifest :status])}
      {:suite :test13-self-hosting-validation
       :artifact-id (:artifact-id self-hosting)
       :document (:document self-hosting)
       :status (:status self-hosting)}
      {:suite :p15-s23-stage-comparison
       :artifact-id (:artifact-id stage-artifact)
       :proof-id (:proof-id stage-artifact)
       :status (get-in stage-artifact
                       [:stage-equivalence-matrix :status])}]
     :status (if (and phase14-linked? test13-linked? stage-linked?)
               :complete
               :failed)}))

(defn p15-s23-diagnostic-conformance-record
  [stage-artifact phase14-artifact]
  (let [report (:conformance-report phase14-artifact)
        golden (:golden-diagnostics-record report)
        conformance (:conformance-results report)
        p15-diagnostic-preservation
        (get-in stage-artifact
                [:rejected-app-diagnostic-artifact
                 :diagnostic-preservation-record])
        required (set (:required-diagnostic-ids conformance))
        p15-diagnostics
        (get-in stage-artifact
                [:rejected-diagnostic-stage-comparison
                 :candidate-diagnostics])
        diagnostics-preserved?
        (and (true? (:stable-codes golden))
             (true? (:source-spans golden))
             (contains? required "TEST13002")
             (true? (:source-spans-present?
                     p15-diagnostic-preservation))
             (true? (:diagnostic-codes-stable?
                     p15-diagnostic-preservation))
             (true? (get-in stage-artifact
                             [:rejected-diagnostic-stage-comparison
                              :rejected-diagnostics-equivalent?])))]
    {:artifact :gravity/p15-s23-diagnostic-conformance-record
     :phase14-required-diagnostics (vec (sort required))
     :phase14-golden-diagnostic-count
     (count (:diagnostics golden))
     :phase14-stable-codes? (:stable-codes golden)
     :phase14-source-spans? (:source-spans golden)
     :test13-diagnostic-covered? (contains? required "TEST13002")
     :p15-rejected-diagnostics p15-diagnostics
     :p15-diagnostic-codes-stable?
     (:diagnostic-codes-stable? p15-diagnostic-preservation)
     :p15-source-spans-present?
     (:source-spans-present? p15-diagnostic-preservation)
     :diagnostics-preserved? (boolean diagnostics-preserved?)
     :status (if diagnostics-preserved? :complete :failed)}))

(defn p15-s23-conformance-gap-record
  []
  {:artifact :gravity/p15-s23-conformance-gap-record
   :known-gaps
   [{:gap :whole-language-compiler-artifact
     :status :pending
     :diagnostic "P15S23001"}
    {:gap :production-conformance-runner
     :status :pending
     :reason :current-report-links-stage0-metadata-gate}
    {:gap :external-backend-validation
     :status :pending
     :reason :current-support-level-is-jvm-instruction-plan}
    {:gap :full-self-hosted-conformance-runner
     :status :pending
     :reason :clojure-seed-still-trusted}
    {:gap :provenance-attestation
     :status :pending
     :diagnostic "P15S23011"}]
   :full-language-compiler-self-hosted? false
   :clojure-seed-retired? false
   :status :complete})

(defn p15-s23-self-hosting-conformance-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        support (:stage-support-conformance-record candidate)
        links (:conformance-suite-link-table candidate)
        diagnostic-record (:diagnostic-conformance-record candidate)
        stage-artifact (:stage-comparison-artifact candidate)
        claims (:self-hosting-claims proof-contract)
        suite-scope (set (:suite-scope proof-contract))
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference
         p15-s23-self-hosting-conformance-required-preserves
         preserves)]
    (vec
     (concat
      (when-not (= :gravity/self-hosting-conformance-report
                   (:artifact proof-contract))
        [(p15-s23-self-hosting-conformance-diagnostic-record
          source-path "P15S23H001" proof-contract
          {:missing-fields [:artifact]})])
      (when-not
       (and (= (set p15-s23-self-hosting-conformance-scope)
               suite-scope)
            (empty? missing-preserves)
            (= :gravity/p15-s23-stage-support-conformance-record
               (:artifact support))
            (= :complete (:status support))
            (true? (:stage-support-conformant? support)))
        [(p15-s23-self-hosting-conformance-diagnostic-record
          source-path "P15S23H002" candidate
          {:expected-scope p15-s23-self-hosting-conformance-scope
           :observed-scope (vec (sort suite-scope))
           :missing-preserves (vec (sort missing-preserves))
           :support-status (:status support)})])
      (when-not
       (and (= :complete (:status links))
            (true? (:phase14-conformance-linked? links))
            (true? (:test13-self-hosting-linked? links)))
        [(p15-s23-self-hosting-conformance-diagnostic-record
          source-path "P15S23H003" links
          {:required-links [:phase14-hosted-core-compiled-conformance
                            :test13-self-hosting-validation]})])
      (when-not
       (and (true? (:stage-comparison-linked? links))
            (= :gravity/p15-s23-stage-comparison-report-artifact
               (:kind stage-artifact))
            (true?
             (get-in stage-artifact
                     [:stage-equivalence-matrix
                      :current-candidate-equivalent-to-seed?])))
        [(p15-s23-self-hosting-conformance-diagnostic-record
          source-path "P15S23H004" stage-artifact
          {:required-link :p15-s23-stage-comparison})])
      (when-not
       (and (= :complete (:status diagnostic-record))
            (true? (:diagnostics-preserved? diagnostic-record)))
        [(p15-s23-self-hosting-conformance-diagnostic-record
          source-path "P15S23H005" diagnostic-record
          {:required [:stable-diagnostic-codes
                      :source-spans
                      :test13-diagnostic]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-self-hosting-conformance-diagnostic-record
          source-path "P15S23H006" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-self-hosting-conformance-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-self-hosting-conformance-diagnostic-stream
   :stage :p15-s23-self-hosting-conformance-report
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-self-hosting-conformance-report
            :message
            (get p15-s23-self-hosting-conformance-diagnostic-messages
                 id)})
         p15-s23-self-hosting-conformance-diagnostic-ids)
   :status :complete})

(defn p15-s23-self-hosting-conformance-rejected-candidates
  [accepted-candidate]
  [{:fixture :internal-p15-s23-conformance-missing-report
    :candidate (assoc accepted-candidate :proof-contract {})
    :expected-diagnostic "P15S23H001"}
   {:fixture :internal-p15-s23-conformance-suite-gap
    :candidate (update-in accepted-candidate
                          [:proof-contract :suite-scope]
                          subvec 0 2)
    :expected-diagnostic "P15S23H002"}
   {:fixture :internal-p15-s23-conformance-phase14-gap
    :candidate (assoc-in accepted-candidate
                         [:conformance-suite-link-table
                          :phase14-conformance-linked?]
                         false)
    :expected-diagnostic "P15S23H003"}
   {:fixture :internal-p15-s23-conformance-stage-comparison-gap
    :candidate (assoc-in accepted-candidate
                         [:conformance-suite-link-table
                          :stage-comparison-linked?]
                         false)
    :expected-diagnostic "P15S23H004"}
   {:fixture :internal-p15-s23-conformance-diagnostic-regression
    :candidate (assoc-in accepted-candidate
                         [:diagnostic-conformance-record
                          :diagnostics-preserved?]
                         false)
    :expected-diagnostic "P15S23H005"}
   {:fixture :internal-p15-s23-conformance-overclaim
    :candidate (-> accepted-candidate
                   (assoc-in [:proof-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:proof-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23H006"}])

(defn p15-s23-self-hosting-conformance-rejected-records
  [source-path accepted-candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-self-hosting-conformance-proof-diagnostics
            source-path candidate)})
        (p15-s23-self-hosting-conformance-rejected-candidates
         accepted-candidate)))

(defn p15-s23-self-hosting-conformance-report-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-self-hosting-conformance-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-self-hosting-conformance-fixtures
                      artifact)))]
    {:self-hosting-conformance-report-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :suite-scope-complete?
     (= (set p15-s23-self-hosting-conformance-scope)
        (set (get-in artifact [:proof-contract :suite-scope])))
     :stage-support-conformant?
     (true?
      (get-in artifact
              [:stage-support-conformance-record
               :stage-support-conformant?]))
     :phase14-conformance-linked?
     (true?
      (get-in artifact
              [:conformance-suite-link-table
               :phase14-conformance-linked?]))
     :test13-self-hosting-linked?
     (true?
      (get-in artifact
              [:conformance-suite-link-table
               :test13-self-hosting-linked?]))
     :stage-comparison-linked?
     (true?
      (get-in artifact
              [:conformance-suite-link-table
               :stage-comparison-linked?]))
     :diagnostics-preserved?
     (true?
      (get-in artifact
              [:diagnostic-conformance-record
               :diagnostics-preserved?]))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset?
      (set p15-s23-self-hosting-conformance-diagnostic-ids)
      rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-self-hosting-conformance-diagnostic-ids)
        diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :current-candidate-is-clojure-seed? true
      :production-conformance-runner? false
      :self-hosted-conformance-runner? false
      :full-self-hosted-toolchain? false
      :next-required-capability
      :implement_provenance_attestation}}))

(defn p15-s23-self-hosting-conformance-report-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-self-hosting-conformance-report)
        stage-artifact
        (p15-s23-stage-comparison-report-source-artifact source-path)
        phase14-artifact
        (let [artifact-fn
              (resolve
               'gravity.bootstrap/hosted-core-compiled-conformance-proof-file-artifact)]
          (when-not artifact-fn
            (p15-s23-self-hosting-conformance-fail!
             "P15S23H003" source-path nil
             {:missing-fields [:phase14-conformance-helper]}))
          (artifact-fn
           "bootstrap/clojure/fixtures/accepted/core-app.gravity"))
        support-record
        (p15-s23-stage-support-conformance-record
         source-path stage-artifact phase14-artifact)
        link-table
        (p15-s23-conformance-suite-link-table
         stage-artifact phase14-artifact)
        diagnostic-record
        (p15-s23-diagnostic-conformance-record
         stage-artifact phase14-artifact)
        gap-record (p15-s23-conformance-gap-record)
        candidate {:proof-contract proof-contract
                   :stage-support-conformance-record support-record
                   :conformance-suite-link-table link-table
                   :diagnostic-conformance-record diagnostic-record
                   :stage-comparison-artifact stage-artifact
                   :phase14-conformance-artifact phase14-artifact}
        diagnostics
        (p15-s23-self-hosting-conformance-proof-diagnostics
         source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-self-hosting-conformance-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :proof-contract proof-contract
                       :stage-artifact (:artifact-id stage-artifact)
                       :phase14-artifact (:artifact-id phase14-artifact)
                       :phase14-report-id
                       (get-in phase14-artifact
                               [:conformance-report :report-id])
                       :support support-record
                       :links link-table
                       :diagnostics diagnostic-record})))
        rejected-records
        (p15-s23-self-hosting-conformance-rejected-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-self-hosting-conformance-report-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-self-hosting-conformance-report
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :stage-comparison-artifact
         (select-keys stage-artifact
                      [:kind :artifact-id :proof-id
                       :stage-equivalence-matrix
                       :accepted-output-stage-comparison
                       :rejected-diagnostic-stage-comparison
                       :rejected-app-diagnostic-artifact
                       :capability-based-proof])
         :phase14-conformance-artifact
         (select-keys phase14-artifact
                      [:kind :artifact-id :conformance-report
                       :trusted-boundary :capability-based-proof])
         :stage-support-conformance-record support-record
         :conformance-suite-link-table link-table
         :diagnostic-conformance-record diagnostic-record
         :conformance-gap-record gap-record
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-self-hosting-conformance-fixtures
         [{:fixture source-path
           :status :accepted
           :suite-count
           (count p15-s23-self-hosting-conformance-scope)
           :stage-support-conformant?
           (:stage-support-conformant? support-record)
           :diagnostics-preserved?
           (:diagnostics-preserved? diagnostic-record)}]
         :rejected-p15-s23-self-hosting-conformance-fixtures
         rejected-records
         :p15-s23-self-hosting-conformance-diagnostic-stream
         (p15-s23-self-hosting-conformance-diagnostic-stream
          source-path proof-id)
         :p15-s23-self-hosting-conformance-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-self-hosting-conformance-diagnostic-ids)
          :suite-count (count p15-s23-self-hosting-conformance-scope)
          :stage-support-conformant?
          (:stage-support-conformant? support-record)
          :diagnostics-preserved?
          (:diagnostics-preserved? diagnostic-record)
          :status :in-progress}
         :diagnostics []}
        proof
        (p15-s23-self-hosting-conformance-report-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-self-hosting-conformance-report-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-self-hosting-conformance-fail!
     "P15S23H001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-self-hosting-conformance-report-source-artifact path))

(def p15-s23-provenance-required-fields
  #{:artifact-id :artifact-kind :bootstrap-stage
    :source-graph-hash :compiler-artifact-id :compiler-hash
    :lockfile-hash :build-recipe-hash
    :environment-manifest-hash :dependency-graph-hash
    :conformance-report-link :equivalence-report-link
    :reproducible-rebuild-link :sbom-link :signature-link
    :builder-identity})

(def p15-s23-provenance-required-links
  #{:compiler-source-inventory
    :compiler-pipeline-manifest
    :reproducible-rebuild-log
    :stage-comparison-report
    :self-hosting-conformance-report})

(def p15-s23-provenance-required-preserves
  #{:artifact-provenance :compiler-lineage :source-hash
    :lockfile-hash :build-recipe-hash :environment-manifest-hash
    :dependency-graph-hash :conformance-report-link
    :equivalence-report-link :reproducibility-link
    :revocation-status :auditor-query-index})

(def p15-s23-provenance-diagnostic-messages
  {"P15S23P001" "P15-S23 bootstrap provenance attestation is missing"
   "P15S23P002" "P15-S23 bootstrap provenance record is missing required fields or preservation facts"
   "P15S23P003" "P15-S23 compiler lineage is incomplete, cyclic, or not traversable to the seed"
   "P15S23P004" "P15-S23 provenance attestation is missing required evidence links"
   "P15S23P005" "P15-S23 canonical provenance payload or deterministic attestation signature is invalid"
   "P15S23P006" "P15-S23 revoked input check or auditor lineage query failed"
   "P15S23P007" "P15-S23 provenance attestation makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-provenance-diagnostic-ids
  ["P15S23P001" "P15S23P002" "P15S23P003" "P15S23P004"
   "P15S23P005" "P15S23P006" "P15S23P007"])

(defn p15-s23-provenance-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-provenance-diagnostic-messages
              id
              "P15-S23 bootstrap provenance attestation failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-provenance-attestation
                 :diagnostic-family :p15-s23-provenance-attestation
                 :value value
                 :remediation "Provide a BOOT8 provenance attestation with explicit compiler lineage, canonical payload, evidence links, revocation checks, and auditor queries while keeping full self-hosting and seed-retirement claims false until the full evidence bundle exists."}
                data)))

(defn p15-s23-provenance-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-provenance-attestation
   :source-span {:source source-path}
   :message (get p15-s23-provenance-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_bootstrap_provenance_attestation})

(defn p15-s23-provenance-file-hash
  [path]
  (if (.isFile (java.io.File. path))
    (str "sha256:" (sha256-hex (slurp path)))
    "sha256:missing"))

(defn p15-s23-provenance-canonical-value
  [value]
  (cond
    (map? value)
    (into (sorted-map)
          (map (fn [[k v]]
                 [k (p15-s23-provenance-canonical-value v)])
               value))

    (vector? value)
    (mapv p15-s23-provenance-canonical-value value)

    (sequential? value)
    (mapv p15-s23-provenance-canonical-value value)

    (set? value)
    (mapv p15-s23-provenance-canonical-value
          (sort value))

    :else value))

(defn p15-s23-provenance-source-graph-record
  [source-path source-data inventory-artifact]
  (let [source-modules (:source-inventory inventory-artifact)
        source-graph-hash
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :source-hash (str "sha256:"
                                         (sha256-hex
                                          (:source-text source-data)))
                       :source-modules source-modules})))]
    {:artifact :gravity/p15-s23-provenance-source-graph-record
     :source-path source-path
     :source-hash (str "sha256:" (sha256-hex (:source-text source-data)))
     :source-graph-hash source-graph-hash
     :source-modules source-modules
     :source-file-count (count source-modules)
     :source-components
     (mapv :component source-modules)
     :status :complete}))

(defn p15-s23-provenance-build-input-record
  [source-path source-graph]
  (let [build-recipe
        {:commands
         ["clojure -M:gravity p15-s23-compiler-source-inventory bootstrap/gravity/p15_s23/compiler.gravity"
          "clojure -M:gravity p15-s23-compiler-pipeline-manifest bootstrap/gravity/p15_s23/compiler.gravity"
          "clojure -M:gravity p15-s23-reproducible-rebuild-log bootstrap/gravity/p15_s23/compiler.gravity"
          "clojure -M:gravity p15-s23-stage-comparison-report bootstrap/gravity/p15_s23/compiler.gravity"
          "clojure -M:gravity p15-s23-self-hosting-conformance-report bootstrap/gravity/p15_s23/compiler.gravity"
          "clojure -M:gravity p15-s23-provenance-attestation bootstrap/gravity/p15_s23/compiler.gravity"]
         :source-path source-path
         :seed-boundary :clojure-stage0}
        environment-manifest
        {:host-runtime :clojure/jvm
         :bootstrap-stage :p15-s23
         :ambient-authority-denied? true
         :release-candidate? false}
        dependency-graph
        {:lockfile "deps.edn"
         :source-graph-hash (:source-graph-hash source-graph)
         :bootstrap-implementation
         "bootstrap/clojure/src/gravity/bootstrap.clj"}]
    {:artifact :gravity/p15-s23-provenance-build-input-record
     :source-path source-path
     :compiler-artifact-id :clojure-stage0-bootstrap
     :compiler-hash
     (p15-s23-provenance-file-hash
      "bootstrap/clojure/src/gravity/bootstrap.clj")
     :lockfile-hash (p15-s23-provenance-file-hash "deps.edn")
     :build-recipe build-recipe
     :build-recipe-hash (c4-artifact-id build-recipe)
     :environment-manifest environment-manifest
     :environment-manifest-hash (c4-artifact-id environment-manifest)
     :dependency-graph dependency-graph
     :dependency-graph-hash (c4-artifact-id dependency-graph)
     :builder-identity :gravity-clojure-stage0-verifier
     :status :complete}))

(defn p15-s23-compiler-lineage-graph
  [inventory-artifact build-input]
  (let [lineage (get-in inventory-artifact
                        [:compiler-module :lineage])
        rows
        [{:stage :stage0
          :compiler :clojure-stage0
          :compiled-by :external-clojure-toolchain
          :compiler-artifact-id (:compiler-artifact-id build-input)
          :compiler-hash (:compiler-hash build-input)
          :trust :seed}
         {:stage :p15-s23-current-clojure-seed-candidate
          :compiled-by (:compiled-by lineage)
          :verified-by (:verified-by lineage)
          :artifact-id (:artifact-id inventory-artifact)
          :next-stage (:next-stage lineage)
          :replaces (:replaces lineage)
          :trust :clojure-stage0-still-trusted}
         {:stage :future-whole-language-self-hosted-compiler
          :compiled-by :pending
          :status :pending
          :trust :not-yet-retired}]]
    {:artifact :gravity/p15-s23-compiler-lineage-graph
     :rows rows
     :compiler-lineage-explicit? true
     :acyclic? true
     :declared-stage-cycle? false
     :lineage-traversable-to-seed? true
     :current-candidate-is-seed? true
     :full-self-hosted-lineage? false
     :answers-which-compiler-compiled-this-compiler
     {:compiler :p15-s23-current-clojure-seed-candidate
      :compiled-by (:compiled-by lineage)
      :verified-by (:verified-by lineage)}
     :status :complete}))

(defn p15-s23-provenance-evidence-link-table
  [inventory-artifact pipeline-artifact rebuild-artifact
   stage-artifact conformance-artifact]
  (let [links
        [{:link :compiler-source-inventory
          :artifact-id (:artifact-id inventory-artifact)
          :status :verified}
         {:link :compiler-pipeline-manifest
          :artifact-id (:artifact-id pipeline-artifact)
          :manifest-id (:manifest-id pipeline-artifact)
          :status :verified}
         {:link :reproducible-rebuild-log
          :artifact-id (:artifact-id rebuild-artifact)
          :proof-id (:proof-id rebuild-artifact)
          :status :verified}
         {:link :stage-comparison-report
          :artifact-id (:artifact-id stage-artifact)
          :proof-id (:proof-id stage-artifact)
          :status :verified}
         {:link :self-hosting-conformance-report
          :artifact-id (:artifact-id conformance-artifact)
          :proof-id (:proof-id conformance-artifact)
          :status :verified}]
        covered (set (map :link links))]
    {:artifact :gravity/p15-s23-provenance-evidence-link-table
     :links links
     :required-links (vec (sort p15-s23-provenance-required-links))
     :required-links-covered?
     (= p15-s23-provenance-required-links covered)
     :conformance-report-link (:artifact-id conformance-artifact)
     :equivalence-report-link (:artifact-id stage-artifact)
     :reproducible-rebuild-link (:artifact-id rebuild-artifact)
     :status (if (= p15-s23-provenance-required-links covered)
               :complete
               :failed)}))

(defn p15-s23-provenance-release-policy-record
  []
  {:artifact :gravity/p15-s23-provenance-release-policy-record
   :release-candidate? false
   :release-eligible? false
   :sbom-required? false
   :external-signature-required? false
   :governance-release-required-before-seed-retirement? true
   :sbom-link
   {:status :not-required
    :reason :current-p15-s23-candidate-is-not-a-release-candidate}
   :signature-link
   {:status :stage0-deterministic-attestation
    :reason :external-release-signature-requires-governance-release-record}
   :status :complete})

(defn p15-s23-provenance-revocation-check-report
  [link-table]
  {:artifact :gravity/p15-s23-provenance-revocation-check-report
   :checked-inputs
   (mapv #(select-keys % [:link :artifact-id :proof-id :manifest-id])
         (:links link-table))
   :revoked-inputs []
   :revocation-clear? true
   :status :complete})

(defn p15-s23-provenance-auditor-query-index
  [lineage link-table]
  {:artifact :gravity/p15-s23-provenance-auditor-query-index
   :queries
   [{:query :which-compiler-compiled-this-compiler
     :answer (get-in lineage
                     [:answers-which-compiler-compiled-this-compiler
                      :compiled-by])
     :status :answered}
    {:query :can-traverse-to-seed
     :answer (:lineage-traversable-to-seed? lineage)
     :status :answered}
    {:query :required-evidence-links
     :answer (mapv :link (:links link-table))
     :status :answered}]
   :auditor-query-passed? true
   :status :complete})

(defn p15-s23-bootstrap-provenance-record
  [source-path source-graph build-input link-table release-policy]
  (let [record-base
        {:artifact :gravity/bootstrap-provenance-record
         :source-path source-path
         :artifact-id (:source-graph-hash source-graph)
         :artifact-kind :gravity/p15-s23-current-clojure-seed-candidate
         :bootstrap-stage :p15-s23
         :source-graph-hash (:source-graph-hash source-graph)
         :compiler-artifact-id (:compiler-artifact-id build-input)
         :compiler-hash (:compiler-hash build-input)
         :lockfile-hash (:lockfile-hash build-input)
         :build-recipe-hash (:build-recipe-hash build-input)
         :environment-manifest-hash
         (:environment-manifest-hash build-input)
         :dependency-graph-hash (:dependency-graph-hash build-input)
         :conformance-report-link
         (:conformance-report-link link-table)
         :equivalence-report-link
         (:equivalence-report-link link-table)
         :reproducible-rebuild-link
         (:reproducible-rebuild-link link-table)
         :safety-report-links []
         :sbom-link (:sbom-link release-policy)
         :signature-link (:signature-link release-policy)
         :builder-identity (:builder-identity build-input)
         :release-candidate? (:release-candidate? release-policy)
         :release-eligible? (:release-eligible? release-policy)
         :status :complete}
        provenance-record-id (c4-artifact-id record-base)]
    (assoc record-base
           :provenance-record-id provenance-record-id)))

(defn p15-s23-canonical-provenance-payload
  [provenance-record lineage link-table release-policy
   revocation auditor]
  (let [payload
        {:provenance-record provenance-record
         :compiler-lineage-graph lineage
         :stage-evidence-link-table link-table
         :release-policy-record release-policy
         :revocation-check-report revocation
         :auditor-query-index auditor}
        canonical
        (p15-s23-provenance-canonical-value payload)
        payload-id (c4-artifact-id canonical)
        signature
        {:signature-id (c4-artifact-id
                        {:payload-id payload-id
                         :signature-mode
                         :stage0-deterministic-attestation})
         :signature-mode :stage0-deterministic-attestation
         :signed-over :canonical-provenance-payload
         :external-signature-service? false
         :status :verified}]
    {:artifact :gravity/p15-s23-canonical-provenance-payload
     :payload-id payload-id
     :canonicalized? true
     :signature signature
     :payload canonical
     :status :complete}))

(defn p15-s23-provenance-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        provenance-record (:bootstrap-provenance-record candidate)
        lineage (:compiler-lineage-graph candidate)
        link-table (:stage-evidence-link-table candidate)
        canonical-payload (:canonical-provenance-payload candidate)
        revocation (:revocation-check-report candidate)
        auditor (:auditor-query-index candidate)
        claims (:self-hosting-claims proof-contract)
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference p15-s23-provenance-required-preserves
                        preserves)
        missing-fields
        (set/difference p15-s23-provenance-required-fields
                        (set (keys provenance-record)))]
    (vec
     (concat
      (when-not (= :gravity/bootstrap-provenance-attestation
                   (:artifact proof-contract))
        [(p15-s23-provenance-diagnostic-record
          source-path "P15S23P001" proof-contract
          {:missing-fields [:artifact]})])
      (when (or (seq missing-fields)
                (seq missing-preserves)
                (not= :complete (:status provenance-record)))
        [(p15-s23-provenance-diagnostic-record
          source-path "P15S23P002" provenance-record
          {:missing-fields (vec (sort missing-fields))
           :missing-preserves (vec (sort missing-preserves))})])
      (when-not
       (and (= :complete (:status lineage))
            (true? (:compiler-lineage-explicit? lineage))
            (true? (:acyclic? lineage))
            (true? (:lineage-traversable-to-seed? lineage))
            (= :clojure-stage0
               (get-in lineage
                       [:answers-which-compiler-compiled-this-compiler
                        :compiled-by])))
        [(p15-s23-provenance-diagnostic-record
          source-path "P15S23P003" lineage
          {:required [:explicit-lineage :acyclic-lineage
                      :lineage-traversable-to-seed]})])
      (when-not
       (and (= :complete (:status link-table))
            (true? (:required-links-covered? link-table))
            (= p15-s23-provenance-required-links
               (set (map :link (:links link-table)))))
        [(p15-s23-provenance-diagnostic-record
          source-path "P15S23P004" link-table
          {:required-links (vec (sort p15-s23-provenance-required-links))})])
      (when-not
       (and (= :complete (:status canonical-payload))
            (true? (:canonicalized? canonical-payload))
            (= :verified
               (get-in canonical-payload [:signature :status]))
            (= :canonical-provenance-payload
               (get-in canonical-payload [:signature :signed-over])))
        [(p15-s23-provenance-diagnostic-record
          source-path "P15S23P005" canonical-payload
          {:required [:canonicalized-payload :verified-signature]})])
      (when-not
       (and (= :complete (:status revocation))
            (true? (:revocation-clear? revocation))
            (empty? (:revoked-inputs revocation))
            (= :complete (:status auditor))
            (true? (:auditor-query-passed? auditor)))
        [(p15-s23-provenance-diagnostic-record
          source-path "P15S23P006"
          {:revocation revocation :auditor auditor}
          {:required [:no-revoked-inputs :auditor-query-index]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-provenance-diagnostic-record
          source-path "P15S23P007" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-provenance-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-provenance-attestation-diagnostic-stream
   :stage :p15-s23-provenance-attestation
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-provenance-attestation
            :message
            (get p15-s23-provenance-diagnostic-messages id)})
         p15-s23-provenance-diagnostic-ids)
   :status :complete})

(defn p15-s23-provenance-rejected-candidates
  [accepted-candidate]
  [{:fixture :internal-p15-s23-provenance-missing-attestation
    :candidate (assoc accepted-candidate :proof-contract {})
    :expected-diagnostic "P15S23P001"}
   {:fixture :internal-p15-s23-provenance-field-gap
    :candidate (update accepted-candidate
                       :bootstrap-provenance-record
                       dissoc
                       :source-graph-hash)
    :expected-diagnostic "P15S23P002"}
   {:fixture :internal-p15-s23-provenance-lineage-gap
    :candidate (assoc-in accepted-candidate
                         [:compiler-lineage-graph
                          :lineage-traversable-to-seed?]
                         false)
    :expected-diagnostic "P15S23P003"}
   {:fixture :internal-p15-s23-provenance-evidence-link-gap
    :candidate (assoc-in accepted-candidate
                         [:stage-evidence-link-table
                          :required-links-covered?]
                         false)
    :expected-diagnostic "P15S23P004"}
   {:fixture :internal-p15-s23-provenance-canonical-gap
    :candidate (assoc-in accepted-candidate
                         [:canonical-provenance-payload
                          :canonicalized?]
                         false)
    :expected-diagnostic "P15S23P005"}
   {:fixture :internal-p15-s23-provenance-revoked-input
    :candidate (-> accepted-candidate
                   (assoc-in [:revocation-check-report
                              :revocation-clear?]
                             false)
                   (assoc-in [:revocation-check-report
                              :revoked-inputs]
                             [:compiler-pipeline-manifest]))
    :expected-diagnostic "P15S23P006"}
   {:fixture :internal-p15-s23-provenance-overclaim
    :candidate (-> accepted-candidate
                   (assoc-in [:proof-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:proof-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23P007"}])

(defn p15-s23-provenance-rejected-records
  [source-path accepted-candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-provenance-proof-diagnostics
            source-path candidate)})
        (p15-s23-provenance-rejected-candidates
         accepted-candidate)))

(defn p15-s23-provenance-attestation-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-provenance-attestation-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-provenance-attestation-fixtures
                      artifact)))]
    {:provenance-attestation-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :required-fields-present?
     (set/subset?
      p15-s23-provenance-required-fields
      (set (keys (:bootstrap-provenance-record artifact))))
     :required-links-covered?
     (true?
      (get-in artifact
              [:stage-evidence-link-table
               :required-links-covered?]))
     :compiler-lineage-traversable?
     (true?
      (get-in artifact
              [:compiler-lineage-graph
               :lineage-traversable-to-seed?]))
     :answers-which-compiler-compiled-this-compiler?
     (= :clojure-stage0
        (get-in artifact
                [:compiler-lineage-graph
                 :answers-which-compiler-compiled-this-compiler
                 :compiled-by]))
     :canonical-payload-signed?
     (and (true?
           (get-in artifact
                   [:canonical-provenance-payload :canonicalized?]))
          (= :verified
             (get-in artifact
                     [:canonical-provenance-payload
                      :signature :status])))
     :revocation-clear?
     (true?
      (get-in artifact
              [:revocation-check-report
               :revocation-clear?]))
     :auditor-query-passed?
     (true?
      (get-in artifact
              [:auditor-query-index
               :auditor-query-passed?]))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :release-eligible?
     (true?
      (get-in artifact [:release-policy-record :release-eligible?]))
     :current-candidate-not-release-eligible?
     (false?
      (get-in artifact [:release-policy-record :release-eligible?]))
     :rejected-candidates-covered?
     (set/subset? (set p15-s23-provenance-diagnostic-ids)
                  rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-provenance-diagnostic-ids) diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :current-candidate-is-clojure-seed? true
      :external-release-signature? false
      :release-eligible? false
      :full-self-hosted-toolchain? false
      :next-required-capability
      :implement_unsafe_audit_report}}))

(defn p15-s23-provenance-attestation-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-provenance-attestation)
        inventory-artifact
        (p15-s23-compiler-source-inventory-source-artifact source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact source-path)
        rebuild-artifact
        (p15-s23-reproducible-rebuild-log-source-artifact source-path)
        stage-artifact
        (p15-s23-stage-comparison-report-source-artifact source-path)
        conformance-artifact
        (p15-s23-self-hosting-conformance-report-source-artifact source-path)
        source-graph
        (p15-s23-provenance-source-graph-record
         source-path source-data inventory-artifact)
        build-input
        (p15-s23-provenance-build-input-record source-path source-graph)
        lineage
        (p15-s23-compiler-lineage-graph inventory-artifact build-input)
        link-table
        (p15-s23-provenance-evidence-link-table
         inventory-artifact pipeline-artifact rebuild-artifact
         stage-artifact conformance-artifact)
        release-policy
        (p15-s23-provenance-release-policy-record)
        revocation
        (p15-s23-provenance-revocation-check-report link-table)
        auditor
        (p15-s23-provenance-auditor-query-index lineage link-table)
        provenance-record
        (p15-s23-bootstrap-provenance-record
         source-path source-graph build-input link-table release-policy)
        canonical-payload
        (p15-s23-canonical-provenance-payload
         provenance-record lineage link-table release-policy
         revocation auditor)
        candidate {:proof-contract proof-contract
                   :bootstrap-provenance-record provenance-record
                   :compiler-lineage-graph lineage
                   :stage-evidence-link-table link-table
                   :canonical-provenance-payload canonical-payload
                   :revocation-check-report revocation
                   :auditor-query-index auditor}
        diagnostics
        (p15-s23-provenance-proof-diagnostics source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-provenance-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :proof-contract proof-contract
                       :provenance-record provenance-record
                       :lineage lineage
                       :link-table link-table
                       :canonical-payload-id
                       (:payload-id canonical-payload)
                       :revocation revocation
                       :auditor auditor})))
        rejected-records
        (p15-s23-provenance-rejected-records source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-provenance-attestation-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-provenance-attestation
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :compiler-source-inventory-artifact
         (select-keys inventory-artifact
                      [:kind :artifact-id :inventory-id
                       :source-inventory :capability-based-proof])
         :compiler-pipeline-manifest-artifact
         (select-keys pipeline-artifact
                      [:kind :artifact-id :manifest-id
                       :capability-based-proof])
         :reproducible-rebuild-artifact
         (select-keys rebuild-artifact
                      [:kind :artifact-id :proof-id
                       :artifact-identity-comparison
                       :environment-provenance-record
                       :capability-based-proof])
         :stage-comparison-artifact
         (select-keys stage-artifact
                      [:kind :artifact-id :proof-id
                       :stage-equivalence-matrix
                       :stage-boundary-record
                       :capability-based-proof])
         :self-hosting-conformance-artifact
         (select-keys conformance-artifact
                      [:kind :artifact-id :proof-id
                       :stage-support-conformance-record
                       :conformance-suite-link-table
                       :capability-based-proof])
         :source-graph-record source-graph
         :build-input-record build-input
         :bootstrap-provenance-record provenance-record
         :compiler-lineage-graph lineage
         :stage-evidence-link-table link-table
         :release-policy-record release-policy
         :canonical-provenance-payload canonical-payload
         :revocation-check-report revocation
         :auditor-query-index auditor
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-provenance-attestation-fixtures
         [{:fixture source-path
           :status :accepted
           :provenance-record-id
           (:provenance-record-id provenance-record)
           :canonical-payload-id (:payload-id canonical-payload)
           :compiler-lineage-traversable?
           (:lineage-traversable-to-seed? lineage)
           :revocation-clear? (:revocation-clear? revocation)
           :auditor-query-passed?
           (:auditor-query-passed? auditor)}]
         :rejected-p15-s23-provenance-attestation-fixtures
         rejected-records
         :p15-s23-provenance-attestation-diagnostic-stream
         (p15-s23-provenance-diagnostic-stream source-path proof-id)
         :p15-s23-provenance-attestation-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-provenance-diagnostic-ids)
          :required-field-count
          (count p15-s23-provenance-required-fields)
          :required-link-count
          (count p15-s23-provenance-required-links)
          :lineage-traversable-to-seed?
          (:lineage-traversable-to-seed? lineage)
          :canonical-payload-signed?
          (= :verified
             (get-in canonical-payload [:signature :status]))
          :revocation-clear? (:revocation-clear? revocation)
          :auditor-query-passed? (:auditor-query-passed? auditor)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-provenance-attestation-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-provenance-attestation-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-provenance-fail!
     "P15S23P001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-provenance-attestation-source-artifact path))

(def p15-s23-tcb-required-preserves
  #{:artifact-provenance :compiler-lineage
    :tcb-component-inventory :tcb-delta-classification
    :residual-trust-boundaries :evidence-linkage})

(def p15-s23-tcb-required-residual-boundaries
  #{:clojure-stage0-bootstrap
    :clojure-stage0-verifier
    :jvm-runtime
    :host-filesystem-source-loading
    :deps-lockfile})

(def p15-s23-tcb-required-evidence-links
  #{:bootstrap-provenance-attestation
    :compiler-source-inventory
    :runtime-manifest-and-capability-enforcement-report
    :stage-comparison-report
    :self-hosting-conformance-report})

(def p15-s23-tcb-diagnostic-messages
  {"P15S23T001" "P15-S23 trusted-computing-base delta record is missing"
   "P15S23T002" "P15-S23 TCB baseline or current component inventory is incomplete"
   "P15S23T003" "P15-S23 TCB delta classification is incomplete"
   "P15S23T004" "P15-S23 residual trust boundaries are missing or underreported"
   "P15S23T005" "P15-S23 TCB delta is missing required evidence links"
   "P15S23T006" "P15-S23 TCB delta count or trust-reduction summary is inconsistent"
   "P15S23T007" "P15-S23 TCB delta record makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-tcb-diagnostic-ids
  ["P15S23T001" "P15S23T002" "P15S23T003" "P15S23T004"
   "P15S23T005" "P15S23T006" "P15S23T007"])

(defn p15-s23-tcb-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-tcb-diagnostic-messages
              id
              "P15-S23 trusted-computing-base delta record failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-tcb-delta-record
                 :diagnostic-family :p15-s23-tcb-delta-record
                 :value value
                 :remediation "Provide an explicit TCB delta with baseline and current component inventories, residual Clojure seed boundaries, provenance links, and measured trust-reduction status without claiming full self-hosting or seed retirement."}
                data)))

(defn p15-s23-tcb-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-tcb-delta-record
   :source-span {:source source-path}
   :message (get p15-s23-tcb-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_tcb_delta_record})

(defn p15-s23-tcb-baseline-inventory
  [source-path provenance-artifact]
  (let [components
        [{:component :clojure-stage0-bootstrap
          :kind :compiler-seed
          :trusted? true
          :artifact-id :clojure-stage0-bootstrap
          :hash (get-in provenance-artifact
                        [:build-input-record :compiler-hash])
          :reason :compiles-and-verifies-current-candidate}
         {:component :clojure-stage0-verifier
          :kind :verifier-implementation
          :trusted? true
          :artifact-id
          "bootstrap/clojure/src/gravity/bootstrap.clj"
          :hash (p15-s23-provenance-file-hash
                 "bootstrap/clojure/src/gravity/bootstrap.clj")
          :reason :validates-p15-s23-evidence}
         {:component :jvm-runtime
          :kind :host-runtime
          :trusted? true
          :artifact-id :host-jvm-runtime
          :reason :executes-clojure-seed-and-verifier}
         {:component :host-filesystem-source-loading
          :kind :host-io-boundary
          :trusted? true
          :artifact-id source-path
          :reason :loads-gravity-source-and-fixtures-for-stage0}
         {:component :deps-lockfile
          :kind :dependency-lock
          :trusted? true
          :artifact-id "deps.edn"
          :hash (p15-s23-provenance-file-hash "deps.edn")
          :reason :locks-stage0-bootstrap-dependencies}]]
    {:artifact :gravity/p15-s23-baseline-tcb-inventory
     :source-path source-path
     :inventory-id (c4-artifact-id components)
     :trusted-components components
     :trusted-component-count (count components)
     :scope :current-clojure-seed-candidate
     :status :complete}))

(defn p15-s23-tcb-current-inventory
  [source-path source-data inventory-artifact pipeline-artifact
   runtime-artifact stage-artifact conformance-artifact provenance-artifact]
  (let [trusted
        [{:component :clojure-stage0-bootstrap
          :kind :compiler-seed
          :trusted? true
          :artifact-id :clojure-stage0-bootstrap
          :hash (get-in provenance-artifact
                        [:build-input-record :compiler-hash])
          :reason :still-compiles-and-verifies-current-candidate}
         {:component :clojure-stage0-verifier
          :kind :verifier-implementation
          :trusted? true
          :artifact-id
          "bootstrap/clojure/src/gravity/bootstrap.clj"
          :hash (p15-s23-provenance-file-hash
                 "bootstrap/clojure/src/gravity/bootstrap.clj")
          :reason :still-validates-p15-s23-evidence}
         {:component :jvm-runtime
          :kind :host-runtime
          :trusted? true
          :artifact-id :host-jvm-runtime
          :reason :still-executes-clojure-seed-and-verifier}
         {:component :host-filesystem-source-loading
          :kind :host-io-boundary
          :trusted? true
          :artifact-id source-path
          :reason :still-loads-gravity-source-and-fixtures}
         {:component :deps-lockfile
          :kind :dependency-lock
          :trusted? true
          :artifact-id "deps.edn"
          :hash (p15-s23-provenance-file-hash "deps.edn")
          :reason :still-locks-stage0-bootstrap-dependencies}]
        evidence-controls
        [{:component :gravity-p15-s23-compiler-source
          :kind :gravity-source
          :artifact-id (str "sha256:"
                            (sha256-hex (:source-text source-data)))
          :control :source-inventory}
         {:component :compiler-source-inventory
          :kind (:kind inventory-artifact)
          :artifact-id (:artifact-id inventory-artifact)
          :control :verified-evidence}
         {:component :compiler-pipeline-manifest
          :kind (:kind pipeline-artifact)
          :artifact-id (:artifact-id pipeline-artifact)
          :control :verified-evidence}
         {:component :runtime-manifest-and-capability-enforcement-report
          :kind (:kind runtime-artifact)
          :artifact-id (:artifact-id runtime-artifact)
          :control :verified-evidence}
         {:component :stage-comparison-report
          :kind (:kind stage-artifact)
          :artifact-id (:artifact-id stage-artifact)
          :control :verified-evidence}
         {:component :self-hosting-conformance-report
          :kind (:kind conformance-artifact)
          :artifact-id (:artifact-id conformance-artifact)
          :control :verified-evidence}
         {:component :bootstrap-provenance-attestation
          :kind (:kind provenance-artifact)
          :artifact-id (:artifact-id provenance-artifact)
          :control :verified-evidence}]]
    {:artifact :gravity/p15-s23-current-tcb-inventory
     :source-path source-path
     :inventory-id (c4-artifact-id
                    {:trusted trusted
                     :evidence-controls evidence-controls})
     :trusted-components trusted
     :trusted-component-count (count trusted)
     :evidence-controlled-components evidence-controls
     :evidence-control-count (count evidence-controls)
     :current-candidate-is-clojure-seed? true
     :full-language-compiler-self-hosted? false
     :clojure-seed-retired? false
     :status :complete}))

(defn p15-s23-tcb-delta-classification
  [baseline current]
  (let [baseline-components (set (map :component
                                      (:trusted-components baseline)))
        residual-components (set (map :component
                                      (:trusted-components current)))
        evidence-components (set (map :component
                                      (:evidence-controlled-components
                                       current)))
        unclassified (set/difference baseline-components
                                     residual-components)
        rows
        (vec
         (concat
          (map (fn [component]
                 {:component component
                  :before :trusted
                  :after :trusted
                  :classification :residual-trusted
                  :whole-language-retired? false})
               (sort baseline-components))
          (map (fn [component]
                 {:component component
                  :before :not-authoritative
                  :after :evidence-control
                  :classification :evidence-controlled
                  :whole-language-retired? false})
               (sort evidence-components))))]
    {:artifact :gravity/p15-s23-tcb-delta-classification
     :rows rows
     :classified-baseline-components (vec (sort baseline-components))
     :evidence-controlled-components (vec (sort evidence-components))
     :unclassified-baseline-components (vec (sort unclassified))
     :retired-components []
     :reduced-components []
     :residual-trusted-components (vec (sort residual-components))
     :classification-complete? (empty? unclassified)
     :whole-language-tcb-reduced? false
     :reason :current-candidate-still-compiled-and-verified-by-clojure-stage0
     :status (if (empty? unclassified) :complete :failed)}))

(defn p15-s23-tcb-residual-trust-boundary-record
  [current]
  (let [residual-boundaries (set (map :component
                                      (:trusted-components current)))
        missing (set/difference p15-s23-tcb-required-residual-boundaries
                                residual-boundaries)]
    {:artifact :gravity/p15-s23-residual-trust-boundary-record
     :residual-boundaries (vec (sort residual-boundaries))
     :required-residual-boundaries
     (vec (sort p15-s23-tcb-required-residual-boundaries))
     :missing-required-residual-boundaries (vec (sort missing))
     :clojure-seed-still-trusted?
     (contains? residual-boundaries :clojure-stage0-bootstrap)
     :clojure-verifier-still-trusted?
     (contains? residual-boundaries :clojure-stage0-verifier)
     :host-runtime-still-trusted?
     (contains? residual-boundaries :jvm-runtime)
     :host-source-loading-still-trusted?
     (contains? residual-boundaries :host-filesystem-source-loading)
     :deps-lockfile-still-trusted?
     (contains? residual-boundaries :deps-lockfile)
     :status (if (empty? missing) :complete :failed)}))

(defn p15-s23-tcb-evidence-link-table
  [inventory-artifact runtime-artifact stage-artifact
   conformance-artifact provenance-artifact]
  (let [links
        [{:link :compiler-source-inventory
          :artifact-id (:artifact-id inventory-artifact)
          :status :verified}
         {:link :runtime-manifest-and-capability-enforcement-report
          :artifact-id (:artifact-id runtime-artifact)
          :proof-id (:proof-id runtime-artifact)
          :status :verified}
         {:link :stage-comparison-report
          :artifact-id (:artifact-id stage-artifact)
          :proof-id (:proof-id stage-artifact)
          :status :verified}
         {:link :self-hosting-conformance-report
          :artifact-id (:artifact-id conformance-artifact)
          :proof-id (:proof-id conformance-artifact)
          :status :verified}
         {:link :bootstrap-provenance-attestation
          :artifact-id (:artifact-id provenance-artifact)
          :proof-id (:proof-id provenance-artifact)
          :provenance-record-id
          (get-in provenance-artifact
                  [:bootstrap-provenance-record
                   :provenance-record-id])
          :status :verified}]
        covered (set (map :link links))]
    {:artifact :gravity/p15-s23-tcb-evidence-link-table
     :links links
     :required-links (vec (sort p15-s23-tcb-required-evidence-links))
     :required-links-covered?
     (= p15-s23-tcb-required-evidence-links covered)
     :status (if (= p15-s23-tcb-required-evidence-links covered)
               :complete
               :failed)}))

(defn p15-s23-tcb-trust-reduction-summary
  [baseline current classification residual]
  {:artifact :gravity/p15-s23-trust-reduction-summary
   :baseline-trusted-count (count (:trusted-components baseline))
   :current-residual-trusted-count
   (count (:trusted-components current))
   :retired-component-count (count (:retired-components classification))
   :reduced-component-count (count (:reduced-components classification))
   :evidence-control-count
   (count (:evidence-controlled-components current))
   :whole-language-tcb-reduced? false
   :reader-subset-prior-reductions-recorded? true
   :clojure-seed-retired? false
   :residual-trust-boundary-count
   (count (:residual-boundaries residual))
   :count-reconciliation
   {:baseline-count-matches?
    (= (:trusted-component-count baseline)
       (count (:trusted-components baseline)))
    :current-count-matches?
    (= (:trusted-component-count current)
       (count (:trusted-components current)))
    :evidence-control-count-matches?
    (= (:evidence-control-count current)
       (count (:evidence-controlled-components current)))
    :retired-count-matches?
    (= 0 (count (:retired-components classification)))}
   :status :complete})

(defn p15-s23-tcb-auditor-query-record
  [baseline current classification residual links]
  {:artifact :gravity/p15-s23-tcb-auditor-query-record
   :queries
   [{:query :which-components-remain-trusted
     :answer (mapv :component (:trusted-components current))
     :status :answered}
    {:query :which-baseline-components-were-retired
     :answer (:retired-components classification)
     :status :answered}
    {:query :is-clojure-seed-still-in-tcb
     :answer (:clojure-seed-still-trusted? residual)
     :status :answered}
    {:query :which-evidence-links-support-delta
     :answer (mapv :link (:links links))
     :status :answered}]
   :baseline-components-accounted?
   (empty? (:unclassified-baseline-components classification))
   :required-links-covered? (:required-links-covered? links)
   :no-unaccounted-trusted-components?
   (and (empty? (:unclassified-baseline-components classification))
        (set/subset? p15-s23-tcb-required-residual-boundaries
                     (set (map :component
                               (:trusted-components current)))))
   :status :complete})

(defn p15-s23-tcb-delta-record
  [source-path baseline current classification residual links summary auditor]
  (let [record-base
        {:artifact :gravity/trusted-computing-base-delta-record
         :source-path source-path
         :bootstrap-stage :p15-s23
         :baseline-tcb-inventory-id (:inventory-id baseline)
         :current-tcb-inventory-id (:inventory-id current)
         :delta-classification-id (c4-artifact-id classification)
         :residual-trust-boundary-id (c4-artifact-id residual)
         :evidence-link-table-id (c4-artifact-id links)
         :trust-reduction-summary-id (c4-artifact-id summary)
         :auditor-query-record-id (c4-artifact-id auditor)
         :baseline-trusted-count (:baseline-trusted-count summary)
         :current-residual-trusted-count
         (:current-residual-trusted-count summary)
         :retired-component-count (:retired-component-count summary)
         :reduced-component-count (:reduced-component-count summary)
         :whole-language-tcb-reduced?
         (:whole-language-tcb-reduced? summary)
         :clojure-seed-retired?
         (:clojure-seed-retired? summary)
         :residual-trust-boundaries (:residual-boundaries residual)
         :status :complete}
        record-id (c4-artifact-id record-base)]
    (assoc record-base :tcb-delta-record-id record-id)))

(defn p15-s23-tcb-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        baseline (:baseline-tcb-inventory candidate)
        current (:current-tcb-inventory candidate)
        classification (:tcb-delta-classification candidate)
        residual (:residual-trust-boundary-record candidate)
        links (:tcb-evidence-link-table candidate)
        summary (:trust-reduction-summary candidate)
        auditor (:tcb-auditor-query-record candidate)
        claims (:self-hosting-claims proof-contract)
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference p15-s23-tcb-required-preserves preserves)]
    (vec
     (concat
      (when-not (= :gravity/trusted-computing-base-delta-record
                   (:artifact proof-contract))
        [(p15-s23-tcb-diagnostic-record
          source-path "P15S23T001" proof-contract
          {:missing-fields [:artifact]})])
      (when (or (seq missing-preserves)
                (not= :complete (:status baseline))
                (not= :complete (:status current))
                (empty? (:trusted-components baseline))
                (empty? (:trusted-components current)))
        [(p15-s23-tcb-diagnostic-record
          source-path "P15S23T002"
          {:baseline baseline :current current}
          {:missing-preserves (vec (sort missing-preserves))
           :required-inventories [:baseline-tcb-inventory
                                  :current-tcb-inventory]})])
      (when-not
       (and (= :complete (:status classification))
            (true? (:classification-complete? classification))
            (empty? (:unclassified-baseline-components classification)))
        [(p15-s23-tcb-diagnostic-record
          source-path "P15S23T003" classification
          {:required [:classified-baseline-components
                      :empty-unclassified-baseline-components]})])
      (when-not
       (and (= :complete (:status residual))
            (true? (:clojure-seed-still-trusted? residual))
            (empty? (:missing-required-residual-boundaries residual)))
        [(p15-s23-tcb-diagnostic-record
          source-path "P15S23T004" residual
          {:required-residual-boundaries
           (vec (sort p15-s23-tcb-required-residual-boundaries))})])
      (when-not
       (and (= :complete (:status links))
            (true? (:required-links-covered? links))
            (= p15-s23-tcb-required-evidence-links
               (set (map :link (:links links)))))
        [(p15-s23-tcb-diagnostic-record
          source-path "P15S23T005" links
          {:required-links
           (vec (sort p15-s23-tcb-required-evidence-links))})])
      (when-not
       (and (= :complete (:status summary))
            (= (:baseline-trusted-count summary)
               (count (:trusted-components baseline)))
            (= (:current-residual-trusted-count summary)
               (count (:trusted-components current)))
            (= (:evidence-control-count summary)
               (count (:evidence-controlled-components current)))
            (false? (:whole-language-tcb-reduced? summary))
            (false? (:clojure-seed-retired? summary))
            (true? (:no-unaccounted-trusted-components? auditor)))
        [(p15-s23-tcb-diagnostic-record
          source-path "P15S23T006" summary
          {:required [:matching-counts
                      :explicit-no-whole-language-tcb-reduction
                      :no-unaccounted-trusted-components]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-tcb-diagnostic-record
          source-path "P15S23T007" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-tcb-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-tcb-delta-diagnostic-stream
   :stage :p15-s23-tcb-delta-record
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-tcb-delta-record
            :message (get p15-s23-tcb-diagnostic-messages id)})
         p15-s23-tcb-diagnostic-ids)
   :status :complete})

(defn p15-s23-tcb-rejected-candidates
  [accepted-candidate]
  [{:fixture :internal-p15-s23-tcb-missing-record
    :candidate (assoc accepted-candidate :proof-contract {})
    :expected-diagnostic "P15S23T001"}
   {:fixture :internal-p15-s23-tcb-inventory-gap
    :candidate (assoc-in accepted-candidate
                         [:baseline-tcb-inventory :trusted-components]
                         [])
    :expected-diagnostic "P15S23T002"}
   {:fixture :internal-p15-s23-tcb-classification-gap
    :candidate (-> accepted-candidate
                   (assoc-in [:tcb-delta-classification
                              :classification-complete?]
                             false)
                   (assoc-in [:tcb-delta-classification
                              :unclassified-baseline-components]
                             [:clojure-stage0-bootstrap]))
    :expected-diagnostic "P15S23T003"}
   {:fixture :internal-p15-s23-tcb-residual-gap
    :candidate (-> accepted-candidate
                   (assoc-in [:residual-trust-boundary-record
                              :clojure-seed-still-trusted?]
                             false)
                   (assoc-in [:residual-trust-boundary-record
                              :missing-required-residual-boundaries]
                             [:clojure-stage0-bootstrap]))
    :expected-diagnostic "P15S23T004"}
   {:fixture :internal-p15-s23-tcb-evidence-link-gap
    :candidate (assoc-in accepted-candidate
                         [:tcb-evidence-link-table
                          :required-links-covered?]
                         false)
    :expected-diagnostic "P15S23T005"}
   {:fixture :internal-p15-s23-tcb-delta-mismatch
    :candidate (assoc-in accepted-candidate
                         [:trust-reduction-summary
                          :baseline-trusted-count]
                         99)
    :expected-diagnostic "P15S23T006"}
   {:fixture :internal-p15-s23-tcb-overclaim
    :candidate (-> accepted-candidate
                   (assoc-in [:proof-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:proof-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23T007"}])

(defn p15-s23-tcb-rejected-records
  [source-path accepted-candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-tcb-proof-diagnostics source-path candidate)})
        (p15-s23-tcb-rejected-candidates accepted-candidate)))

(defn p15-s23-tcb-delta-record-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-tcb-delta-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-tcb-delta-fixtures artifact)))]
    {:tcb-delta-record-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :baseline-inventory-present?
     (= :complete (get-in artifact [:baseline-tcb-inventory :status]))
     :current-inventory-present?
     (= :complete (get-in artifact [:current-tcb-inventory :status]))
     :delta-classification-complete?
     (true?
      (get-in artifact [:tcb-delta-classification
                        :classification-complete?]))
     :residual-trust-boundaries-recorded?
     (empty?
      (get-in artifact [:residual-trust-boundary-record
                        :missing-required-residual-boundaries]))
     :clojure-seed-still-in-tcb?
     (true?
      (get-in artifact [:residual-trust-boundary-record
                        :clojure-seed-still-trusted?]))
     :required-evidence-links-covered?
     (true?
      (get-in artifact [:tcb-evidence-link-table
                        :required-links-covered?]))
     :no-unaccounted-trusted-components?
     (true?
      (get-in artifact [:tcb-auditor-query-record
                        :no-unaccounted-trusted-components?]))
     :whole-language-tcb-reduced?
     (true?
      (get-in artifact [:trust-reduction-summary
                        :whole-language-tcb-reduced?]))
     :does-not-claim-whole-language-tcb-reduction?
     (false?
      (get-in artifact [:trust-reduction-summary
                        :whole-language-tcb-reduced?]))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset? (set p15-s23-tcb-diagnostic-ids)
                  rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-tcb-diagnostic-ids) diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :current-candidate-is-clojure-seed? true
      :whole-language-tcb-reduced? false
      :full-self-hosted-toolchain? false
      :next-required-capability
      :implement_unsafe_audit_report}}))

(defn p15-s23-tcb-delta-record-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-tcb-delta-record)
        inventory-artifact
        (p15-s23-compiler-source-inventory-source-artifact source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact source-path)
        runtime-artifact
        (p15-s23-runtime-manifest-capability-enforcement-source-artifact
         source-path)
        stage-artifact
        (p15-s23-stage-comparison-report-source-artifact source-path)
        conformance-artifact
        (p15-s23-self-hosting-conformance-report-source-artifact source-path)
        provenance-artifact
        (p15-s23-provenance-attestation-source-artifact source-path)
        baseline
        (p15-s23-tcb-baseline-inventory source-path provenance-artifact)
        current
        (p15-s23-tcb-current-inventory
         source-path source-data inventory-artifact pipeline-artifact
         runtime-artifact stage-artifact conformance-artifact
         provenance-artifact)
        classification
        (p15-s23-tcb-delta-classification baseline current)
        residual
        (p15-s23-tcb-residual-trust-boundary-record current)
        links
        (p15-s23-tcb-evidence-link-table
         inventory-artifact runtime-artifact stage-artifact
         conformance-artifact provenance-artifact)
        summary
        (p15-s23-tcb-trust-reduction-summary
         baseline current classification residual)
        auditor
        (p15-s23-tcb-auditor-query-record
         baseline current classification residual links)
        tcb-record
        (p15-s23-tcb-delta-record
         source-path baseline current classification residual
         links summary auditor)
        candidate {:proof-contract proof-contract
                   :baseline-tcb-inventory baseline
                   :current-tcb-inventory current
                   :tcb-delta-classification classification
                   :residual-trust-boundary-record residual
                   :tcb-evidence-link-table links
                   :trust-reduction-summary summary
                   :tcb-auditor-query-record auditor
                   :tcb-delta-record tcb-record}
        diagnostics
        (p15-s23-tcb-proof-diagnostics source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-tcb-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :proof-contract proof-contract
                       :baseline baseline
                       :current current
                       :classification classification
                       :residual residual
                       :links links
                       :summary summary
                       :auditor auditor
                       :tcb-record tcb-record})))
        rejected-records
        (p15-s23-tcb-rejected-records source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-tcb-delta-record-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-tcb-delta-record
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :compiler-source-inventory-artifact
         (select-keys inventory-artifact
                      [:kind :artifact-id :inventory-id
                       :capability-based-proof])
         :runtime-manifest-capability-artifact
         (select-keys runtime-artifact
                      [:kind :artifact-id :proof-id
                       :runtime-manifest-record
                       :capability-enforcement-record
                       :capability-based-proof])
         :stage-comparison-artifact
         (select-keys stage-artifact
                      [:kind :artifact-id :proof-id
                       :stage-equivalence-matrix
                       :stage-boundary-record
                       :capability-based-proof])
         :self-hosting-conformance-artifact
         (select-keys conformance-artifact
                      [:kind :artifact-id :proof-id
                       :stage-support-conformance-record
                       :conformance-suite-link-table
                       :capability-based-proof])
         :bootstrap-provenance-attestation-artifact
         (select-keys provenance-artifact
                      [:kind :artifact-id :proof-id
                       :bootstrap-provenance-record
                       :compiler-lineage-graph
                       :capability-based-proof])
         :baseline-tcb-inventory baseline
         :current-tcb-inventory current
         :tcb-delta-classification classification
         :residual-trust-boundary-record residual
         :tcb-evidence-link-table links
         :trust-reduction-summary summary
         :tcb-auditor-query-record auditor
         :tcb-delta-record tcb-record
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-tcb-delta-fixtures
         [{:fixture source-path
           :status :accepted
           :tcb-delta-record-id
           (:tcb-delta-record-id tcb-record)
           :baseline-trusted-count
           (:baseline-trusted-count summary)
           :current-residual-trusted-count
           (:current-residual-trusted-count summary)
           :whole-language-tcb-reduced?
           (:whole-language-tcb-reduced? summary)
           :clojure-seed-still-trusted?
           (:clojure-seed-still-trusted? residual)}]
         :rejected-p15-s23-tcb-delta-fixtures rejected-records
         :p15-s23-tcb-delta-diagnostic-stream
         (p15-s23-tcb-diagnostic-stream source-path proof-id)
         :p15-s23-tcb-delta-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count (count p15-s23-tcb-diagnostic-ids)
          :baseline-trusted-count
          (:baseline-trusted-count summary)
          :current-residual-trusted-count
          (:current-residual-trusted-count summary)
          :evidence-control-count
          (:evidence-control-count summary)
          :whole-language-tcb-reduced?
          (:whole-language-tcb-reduced? summary)
          :clojure-seed-still-trusted?
          (:clojure-seed-still-trusted? residual)
          :no-unaccounted-trusted-components?
          (:no-unaccounted-trusted-components? auditor)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-tcb-delta-record-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-tcb-delta-record-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-tcb-fail!
     "P15S23T001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-tcb-delta-record-source-artifact path))

