(def p17-governance-documents
  (mapv :document p17-governance-document-data))

(def p17-governance-data-by-document
  (into {} (map (juxt :document identity)
                p17-governance-document-data)))

(def p17-governance-phase-governing-documents
  (into {} (map (juxt :document :file)
                p17-governance-document-data)))

(def p17-governance-diagnostics-by-document
  (into {} (map (fn [{:keys [document]}]
                  [document (p17-gov-diagnostics document)])
                p17-governance-document-data)))

(def p17-governance-rejected-diagnostics
  (into {} (map (juxt :document :rejected-diagnostic)
                p17-governance-document-data)))

(def p17-governance-rejected-fixture-names
  (into {} (map (juxt :document :rejected-fixture)
                p17-governance-document-data)))

(def p17-governance-diagnostic-ids
  (vec
   (distinct
    (concat (mapcat p17-governance-diagnostics-by-document
                    p17-governance-documents)
            ["P17-MANIFEST" "P17-ACCEPTED" "P17-REJECTED"
             "P17-GOVERNANCE"]))))

(def p17-governance-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             p17-governance-diagnostic-ids)))

(def p17-governance-artifact-keys
  [:language-change-record :compatibility-report
   :standard-library-governance-record :security-review-record
   :target-support-matrix :rfc-record :experiment-registry
   :deprecation-plan :unsafe-governance-audit
   :ecosystem-package-governance-record])

(defn p17-task-id
  [document]
  (str "P17-D" (:sequence (p17-governance-data-by-document document))))

(defn p17-governance-source-overrides
  [module]
  (get-in module [:metadata :governance :phase17] {}))

(defn p17-governance-diagnostic-document
  [diagnostic-id]
  (some (fn [document]
          (when (some #(= diagnostic-id %)
                      (p17-governance-diagnostics-by-document document))
            document))
        p17-governance-documents))

(defn p17-governance-fail!
  [id source-path subject extra]
  (let [document (or (:document-id subject)
                     (p17-governance-diagnostic-document id))]
    (fail! id
           "P17 governance/evolution validation failed"
           (merge {:source-span (or (:source-span subject)
                                    (source-span source-path 0))
                   :diagnostic-family :phase17-governance-evolution
                   :stage :governance-evolution
                   :document-id document
                   :task (when document (p17-task-id document))
                   :module (:module subject)
                   :artifact-id (:artifact-id subject)
                   :missing-fact (:missing-fact subject)
                   :fallback-status :rejected
                   :remediation "Phase 17 requires change records, compatibility reports, standard-library governance records, security reviews, target matrices, RFC records, experiment registries, deprecation plans, unsafe audits, ecosystem package governance records, and provenance before governance tasks can complete."}
                  extra))))

(defn p17-governance-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (if-let [id (get p17-governance-override-diagnostics fail-kind)]
      (p17-governance-fail!
       id source-path
       {:document-id (p17-governance-diagnostic-document id)
        :artifact-id "p17-governance-negative-fixture"
        :missing-fact fail-kind}
       {:fixture :rejected-governance})
      (p17-governance-fail!
       "P17-MANIFEST" source-path
       {:artifact-id "p17-governance-unknown-override"
        :missing-fact fail-kind}
       {:missing-fields [:known-override-diagnostic]}))))

(defn p17-governance-record
  [{:keys [document record title owned-surface check-key artifact-key
           dependencies]}]
  {:document document
   :record record
   :title title
   :owned-surface owned-surface
   :owner (str (name record) "-working-group")
   :state :implemented
   :scope #{:language :compiler :runtime :standard-library :package
            :target :security :unsafe :governance}
   :affected-surfaces #{:source :semantic :effect :capability :profile
                        :diagnostic :artifact :runtime :package}
   :review-gates [:compatibility :safety :security :profile :conformance
                  :migration :provenance]
   :evidence [:accepted-fixture :rejected-fixture :diagnostic-stream
              :capability-proof]
   :artifacts [artifact-key]
   :diagnostics (p17-governance-diagnostics-by-document document)
   :decision :accepted-with-stage0-evidence
   :provenance-record (str "phase17:" document ":stage0")
   :checks (assoc {:owner true
                   :scope true
                   :affected-documents true
                   :review-gates true
                   :compatibility true
                   :safety-security true
                   :profile-target true
                   :conformance true
                   :provenance true}
                  check-key true)
   :dependencies dependencies
   :status :complete})

(defn p17-governance-records
  []
  (mapv p17-governance-record p17-governance-document-data))

(defn p17-record-by-document
  [records document]
  (some #(when (= document (:document %)) %) records))

(defn p17-artifact-values
  []
  (let [records (p17-governance-records)
        one #(p17-record-by-document records %)]
    {:language-change-record
     {:artifact :gravity/language-change-record
      :artifact-id "governance:language-change-record"
      :changes [(one "GOV1")]
      :states [:sketch :draft :rfc :prototype :review :accepted
               :implemented :stabilized :deprecated :removed :rejected]
      :release-note-traceability :required
      :status :complete}
     :compatibility-report
     {:artifact :gravity/compatibility-report
      :artifact-id "governance:compatibility-report"
      :records [(one "GOV2")]
      :surfaces [:source :semantic :effect :capability :profile
                 :diagnostic :artifact :runtime :package]
      :baseline-release "gravity-0.1-stage0"
      :migration-records [:stage0-migration-record]
      :status :complete}
     :standard-library-governance-record
     {:artifact :gravity/standard-library-governance-record
      :artifact-id "governance:standard-library"
      :records [(one "GOV3")]
      :module-ownership-map {:gravity.std "stdlib-working-group"}
      :requires-unsafe-audit true
      :requires-compatibility-report true
      :status :complete}
     :security-review-record
     {:artifact :gravity/security-review-record
      :artifact-id "governance:security-review"
      :records [(one "GOV4")]
      :threat-models [:capability-expansion :secret-leak :taint-sink
                      :unsafe-ffi :ai-tool-authority :supply-chain]
      :residual-risk-recorded true
      :status :complete}
     :target-support-matrix
     {:artifact :gravity/target-support-matrix
      :artifact-id "governance:target-support"
      :records [(one "GOV5")]
      :targets [{:target :jvm :tier :experimental
                 :profiles [:core :meta :hosted]
                 :unsupported [:kernel :firmware :hardware]}]
      :unsupported-profile-policy :reject
      :status :complete}
     :rfc-record
     {:artifact :gravity/rfc-record
      :artifact-id "governance:rfc"
      :records [(one "GOV6")]
      :required-sections [:motivation :design :affected-documents
                          :profile-impact :safety-security
                          :compatibility :implementation-plan
                          :test-plan :migration-plan :stabilization]
      :decision-history [:draft :triage :design-review :accepted]
      :status :complete}
     :experiment-registry
     {:artifact :gravity/experiment-registry
      :artifact-id "governance:experiment-registry"
      :records [(one "GOV7")]
      :default-policy :off-in-stable
      :records-opt-in-artifacts true
      :expiry-policy :stabilize-extend-or-remove
      :status :complete}
     :deprecation-plan
     {:artifact :gravity/deprecation-plan
      :artifact-id "governance:deprecation-plan"
      :records [(one "GOV8")]
      :stabilization-evidence [:conformance-history :negative-fixtures
                               :compatibility-report :documentation
                               :migration-readiness]
      :deprecation-schedule [:warn :error :remove]
      :status :complete}
     :unsafe-governance-audit
     {:artifact :gravity/unsafe-governance-audit
      :artifact-id "governance:unsafe-audit"
      :records [(one "GOV9")]
      :unsafe-island-records [:stage0-unsafe-island-record]
      :safe-wrapper-evidence [:proof :runtime-check :negative-fixture]
      :stale-audit-blocks-release true
      :status :complete}
     :ecosystem-package-governance-record
     {:artifact :gravity/ecosystem-package-governance-record
      :artifact-id "governance:ecosystem-package"
      :records [(one "GOV10")]
      :registry-decisions [:accept :reject :quarantine :yank :reserve
                           :transfer :advisory]
      :requires [:identity :owners :namespace :version :provenance
                 :signature :sbom :capability-manifest]
      :status :complete}}))

(defn p17-governance-document-record
  [document]
  (let [summary (p17-governance-data-by-document document)]
    (merge
     {:document document
      :task-id (p17-task-id document)
      :governing-doc (:file summary)
      :suite-id (:owned-surface summary)
      :diagnostics (p17-governance-diagnostics-by-document document)
      :evidence (into {}
                      (map (fn [diagnostic]
                             [(keyword (str/lower-case diagnostic))
                              {:diagnostic diagnostic
                               :source :governing-document
                               :status :present}])
                           (p17-governance-diagnostics-by-document
                            document)))
      :governance
      {:accepted-fixture "bootstrap/clojure/fixtures/accepted/governance-evolution.gravity"
       :rejected-fixture (str "bootstrap/clojure/fixtures/rejected/"
                              (:rejected-fixture summary))
       :artifact-evidence (:artifact-key summary)
       :validation-command "clojure -M:test"
       :status :complete}}
     (select-keys summary [:title :record :owned-surface
                           :accepted-behavior :rejected-diagnostic
                           :artifact-key :dependencies]))))

(defn p17-governance-document-records
  []
  (into {} (map (fn [document]
                  [document (p17-governance-document-record document)])
                p17-governance-documents)))

(defn p17-accepted-governance-fixtures
  []
  (mapv (fn [document]
          (let [summary (p17-governance-data-by-document document)]
            {:document document
             :fixture "bootstrap/clojure/fixtures/accepted/governance-evolution.gravity"
             :artifact (:owned-surface summary)
             :evidence [(p17-task-id document) (:file summary)]
             :status :accepted}))
        p17-governance-documents))

(defn p17-rejected-governance-fixtures
  []
  (mapv (fn [document]
          (let [summary (p17-governance-data-by-document document)]
            {:document document
             :fixture (str "bootstrap/clojure/fixtures/rejected/"
                           (:rejected-fixture summary))
             :artifact :stable-governance-diagnostic
             :diagnostic (:rejected-diagnostic summary)
             :evidence [(p17-task-id document) (:file summary)]
             :status :rejected}))
        p17-governance-documents))

(defn p17-governance-evidence
  []
  (mapv (fn [document]
          (let [summary (p17-governance-data-by-document document)]
            {:document document
             :accepted-behavior (:accepted-behavior summary)
             :rejected-behavior (:rejected-diagnostic summary)
             :artifact (:artifact-key summary)
             :validation ["clojure -M:test"
                          "clojure -M:gravity governance-evolution bootstrap/clojure/fixtures/accepted/governance-evolution.gravity"]
             :status :complete}))
        p17-governance-documents))

(defn p17-governance-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/phase17-governance-diagnostic-stream
   :stage :governance-evolution
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           (let [document (p17-governance-diagnostic-document id)]
             {:artifact :gravity/diagnostic
              :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
              :diagnostic id
              :rule id
              :severity :error
              :stage :governance-evolution
              :document-id document
              :task (when document (p17-task-id document))
              :primary {:span (source-span source-path index)
                        :syntax-id (str "p17-governance-syntax-" index)
                        :artifact input-id}
              :missing-fact (keyword (str/lower-case id))
              :remediation [{:kind :record-owner-and-scope}
                            {:kind :attach-review-evidence}
                            {:kind :update-migration-plan}
                            {:kind :link-provenance}]
              :ordering-key [id :governance-evolution]}))
         p17-governance-diagnostic-ids
         (range))
   :status :complete})

(defn p17-present?
  [value]
  (if (coll? value)
    (seq value)
    (some? value)))

(defn p17-governance-record-for
  [artifact document]
  (some #(when (= document (:document %)) %)
        (:governance-records artifact)))

(defn p17-governance-validate!
  [source-path artifact]
  (let [documents (:document-contracts artifact)
        accepted (:accepted-governance-fixtures artifact)
        rejected (:rejected-governance-fixtures artifact)
        governance (:governance-evidence artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:governance-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= (set p17-governance-documents)
                 (set (:document-set artifact)))
      (p17-governance-fail! "P17-MANIFEST" source-path artifact
                             {:missing-fields [:document-set]}))
    (doseq [artifact-key p17-governance-artifact-keys]
      (when-not (p17-present? (get artifact artifact-key))
        (p17-governance-fail! "P17-MANIFEST" source-path artifact
                              {:missing-fields [artifact-key]}))
      (when-not (= :complete (:status (get artifact artifact-key)))
        (p17-governance-fail! "P17-MANIFEST" source-path
                              (get artifact artifact-key)
                              {:missing-fields [:status]})))
    (when-not (every? #(contains? documents %) p17-governance-documents)
      (p17-governance-fail! "P17-MANIFEST" source-path documents
                            {:missing-fields [:document-contracts]}))
    (doseq [document p17-governance-documents
            :let [record (get documents document)
                  summary (p17-governance-data-by-document document)]]
      (doseq [field [:document :task-id :governing-doc :suite-id
                     :diagnostics :evidence :owned-surface
                     :accepted-behavior :rejected-diagnostic
                     :artifact-key :governance]]
        (when-not (p17-present? (get record field))
          (p17-governance-fail! "P17-MANIFEST" source-path record
                                {:missing-fields [field]})))
      (doseq [diagnostic (p17-governance-diagnostics-by-document document)]
        (when-not (and (contains? (set (:diagnostics record)) diagnostic)
                       (get-in record [:evidence
                                       (keyword (str/lower-case diagnostic))]))
          (p17-governance-fail!
           diagnostic source-path record
           {:missing-fields [(keyword (str/lower-case diagnostic))]})))
      (let [governance-record (p17-governance-record-for artifact document)]
        (when-not (true? (get-in governance-record
                                 [:checks (:check-key summary)]))
          (p17-governance-fail!
           (:rejected-diagnostic summary) source-path governance-record
           {:missing-fields [(:check-key summary)]}))))
    (when-not (= (set p17-governance-documents)
                 (set (map :document accepted)))
      (p17-governance-fail!
       "P17-ACCEPTED" source-path accepted
       {:missing-fields [:accepted-governance-fixtures]}))
    (when-not (= (set p17-governance-documents)
                 (set (map :document rejected)))
      (p17-governance-fail!
       "P17-REJECTED" source-path rejected
       {:missing-fields [:rejected-governance-fixtures]}))
    (when-not (= (set p17-governance-documents)
                 (set (map :document governance)))
      (p17-governance-fail!
       "P17-GOVERNANCE" source-path governance
       {:missing-fields [:governance-evidence]}))
    (when-not (= 10 (count (:governance-records artifact)))
      (p17-governance-fail!
       "P17-MANIFEST" source-path artifact
       {:missing-fields [:governance-records]}))
    (when-not (p17-present? (get-in artifact
                                    [:language-change-record :changes]))
      (p17-governance-fail!
       "GOV1001" source-path (:language-change-record artifact)
       {:missing-fields [:changes]}))
    (when-not (p17-present? (get-in artifact
                                    [:security-review-record
                                     :threat-models]))
      (p17-governance-fail!
       "GOV4001" source-path (:security-review-record artifact)
       {:missing-fields [:threat-models]}))
    (when-not (= :off-in-stable
                 (get-in artifact [:experiment-registry :default-policy]))
      (p17-governance-fail!
       "GOV7002" source-path (:experiment-registry artifact)
       {:missing-fields [:default-policy]}))
    (when-not (true? (get-in artifact
                             [:unsafe-governance-audit
                              :stale-audit-blocks-release]))
      (p17-governance-fail!
       "GOV9006" source-path (:unsafe-governance-audit artifact)
       {:missing-fields [:stale-audit-blocks-release]}))
    (when-not (set/subset? (set p17-governance-diagnostic-ids)
                           diagnostics)
      (p17-governance-fail!
       "P17-MANIFEST" source-path
       (:governance-diagnostic-stream artifact)
       {:missing-fields [:diagnostics]})))
  :complete)

(defn p17-task-statuses
  []
  (merge (zipmap ["P17-T01" "P17-T02" "P17-T03"
                  "P17-T04" "P17-T05" "P17-T06"]
                 (repeat :complete))
         (zipmap (map p17-task-id p17-governance-documents)
                 (repeat :complete))))

(defn p17-governance-proof
  [artifact]
  (let [documents (:document-contracts artifact)
        accepted-docs (set (map :document
                                (:accepted-governance-fixtures artifact)))
        rejected-docs (set (map :document
                                (:rejected-governance-fixtures artifact)))
        governance-docs (set (map :document
                                  (:governance-evidence artifact)))
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:governance-diagnostic-stream
                                       :diagnostics])))]
    {:language-evolution-covered?
     (boolean
      (p17-present? (get-in artifact [:language-change-record :changes])))
     :compatibility-covered?
     (boolean
      (p17-present? (get-in artifact [:compatibility-report :surfaces])))
     :standard-library-governance-covered?
     (boolean
      (p17-present? (get-in artifact
                            [:standard-library-governance-record
                             :module-ownership-map])))
     :security-review-covered?
     (boolean
      (p17-present? (get-in artifact
                            [:security-review-record :threat-models])))
     :target-support-covered?
     (boolean
      (p17-present? (get-in artifact [:target-support-matrix :targets])))
     :rfc-covered?
     (boolean
      (p17-present? (get-in artifact [:rfc-record :required-sections])))
     :experiment-covered?
     (= :off-in-stable (get-in artifact
                               [:experiment-registry :default-policy]))
     :deprecation-covered?
     (boolean
      (p17-present? (get-in artifact
                            [:deprecation-plan :stabilization-evidence])))
     :unsafe-governance-covered?
     (true? (get-in artifact
                    [:unsafe-governance-audit
                     :stale-audit-blocks-release]))
     :ecosystem-package-covered?
     (boolean
      (p17-present? (get-in artifact
                            [:ecosystem-package-governance-record
                             :registry-decisions])))
     :document-coverage-complete?
     (= (set p17-governance-documents) (set (keys documents)))
     :accepted-fixtures-covered?
     (= (set p17-governance-documents) accepted-docs)
     :rejected-fixtures-covered?
     (= (set p17-governance-documents) rejected-docs)
     :governance-evidence-covered?
     (= (set p17-governance-documents) governance-docs)
     :diagnostics-covered?
     (set/subset? (set p17-governance-diagnostic-ids) diagnostics)
     :task-statuses (p17-task-statuses)
     :status :complete}))

(defn governance-evolution-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (p17-governance-source-overrides module)
        _ (p17-governance-validate-source-overrides!
           source-path source-overrides)
        input-id (c4-artifact-id {:source-path source-path
                                  :module (:module module)
                                  :task "P17-T01-T06"
                                  :documents p17-governance-documents})
        diagnostic-stream (p17-governance-diagnostic-stream source-path
                                                            input-id)
        governance-records (p17-governance-records)
        artifact-values (p17-artifact-values)
        artifact-base
        (merge
         {:kind :gravity/stage0-governance-evolution-artifact
          :phase "17"
          :task "P17-T01-T06"
          :document-set p17-governance-documents
          :governing-documents p17-governance-phase-governing-documents
          :pass {:name :phase17-governance-evolution
                 :input :ordinary-gravity-source
                 :output :governance-evolution
                 :requires p17-governance-artifact-keys
                 :preserves [:profile :target :effect :capability
                             :safety :compatibility :provenance
                             :diagnostic-code :source-spans]
                 :emits [:document-contracts :governance-records
                         :accepted-governance-fixtures
                         :rejected-governance-fixtures
                         :governance-evidence
                         :governance-diagnostic-stream]
                 :rejects p17-governance-diagnostic-ids}
          :source-overrides source-overrides
          :module (select-keys module [:module :source-path :profile :target
                                       :effects :capabilities :safety
                                       :metadata])
          :document-contracts (p17-governance-document-records)
          :governance-records governance-records
          :accepted-governance-fixtures
          (p17-accepted-governance-fixtures)
          :rejected-governance-fixtures
          (p17-rejected-governance-fixtures)
          :governance-evidence (p17-governance-evidence)
          :governance-diagnostic-stream diagnostic-stream
          :governance-evolution-results
          {:documents p17-governance-documents
           :tasks (p17-task-statuses)
           :document-contracts 10
           :artifact-families (count p17-governance-artifact-keys)
           :accepted-fixtures 10
           :rejected-fixtures 10
           :governance-records 10
           :diagnostic-count (count p17-governance-diagnostic-ids)
           :status :complete}
          :diagnostics []}
         artifact-values)
        _ (p17-governance-validate! source-path artifact-base)
        capability-proof (p17-governance-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn governance-evolution-file-artifact
  [path]
  (governance-evolution-source-artifact path (slurp path)))

(def r1-document-governing-document
  "docs/phase-08-runtime-architecture/112-r1-runtime-architecture-overview.md")

(def r1-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-selection-no-runtime.gravity")

(def r1-document-diagnostic-ids
  ["R1-SELECTION"
   "R1-SERVICE"
   "R1-FORBIDDEN"
   "R1-CAPABILITY"
   "R1-HOST"
   "R1-REPLAY"
   "R1-STARTUP"
   "R1-FAILURE"
   "R1-MANIFEST"])

(def r1-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r1-document-diagnostic-ids)))

(defn r1-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r1-document])
      (get-in module [:metadata :runtime :selection])
      {}))

(defn r1-document-missing-policy
  [id]
  (case id
    "R1-SELECTION" :explicit_runtime_family_selection
    "R1-SERVICE" :linked_generated_delegated_external_forbidden_table
    "R1-FORBIDDEN" :hidden_runtime_dependency_rejection
    "R1-CAPABILITY" :runtime_authority_enforcement_without_new_grants
    "R1-HOST" :typed_host_adapter_and_diagnostics
    "R1-REPLAY" :nondeterminism_replay_or_audit_record
    "R1-STARTUP" :startup_initialization_cleanup_order
    "R1-FAILURE" :diagnostic_and_artifact_mapped_failure_path
    :complete_runtime_architecture_manifest))

(defn r1-document-fail!
  [id source-path subject extra]
  (fail! id
         "R1 runtime architecture document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r1-runtime-architecture-document
                 :stage :r1-document-coverage
                 :document-id "R1"
                 :profile (or (:profile subject) :firmware)
                 :target (or (:target subject) :jvm)
                 :runtime-family (:runtime-family subject)
                 :service-id (:service-id subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :provider (:provider subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (r1-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D112 requires explicit runtime family selection, service classification, capability enforcement, startup/failure records, hidden dependency rejection, replay records, downstream consumption, stable diagnostics, and R1 conformance evidence."}
                extra)))

(defn r1-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r1-document-override-diagnostics fail-kind)]
      (r1-document-fail!
       id source-path
       {:runtime-family fail-kind
        :service-id fail-kind
        :effect fail-kind
        :capability fail-kind
        :provider fail-kind
        :artifact-id (str "r1-document-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn r1-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/r1-runtime-architecture-diagnostic-stream
   :stage :r1-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :r1-document-coverage
            :document-id "R1"
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-r1-document-syntax-" index)
                      :artifact input-id}
            :profile (case id
                       "R1-HOST" :hosted
                       "R1-REPLAY" :distributed
                       :firmware)
            :target (case id
                      "R1-HOST" {:backend :jvm :platform :host}
                      "R1-REPLAY" {:backend :workflow-graph
                                   :platform :durable}
                      {:backend :c :platform :bare-metal})
            :runtime-family (case id
                              "R1-HOST" :managed
                              "R1-REPLAY" :distributed
                              "R1-CAPABILITY" :capability
                              :no-runtime)
            :service-id (case id
                          "R1-SELECTION" :runtime-family
                          "R1-SERVICE" :service-table
                          "R1-FORBIDDEN" :hidden-runtime-service
                          "R1-CAPABILITY" :authority-check
                          "R1-HOST" :host-delegation
                          "R1-REPLAY" :event-log
                          "R1-STARTUP" :startup
                          "R1-FAILURE" :failure
                          :runtime-manifest)
            :effect (case id
                      "R1-CAPABILITY" :filesystem/read
                      "R1-REPLAY" :workflow/replay
                      "R1-HOST" :host/call
                      nil)
            :capability (case id
                          "R1-CAPABILITY" :fs/read
                          "R1-REPLAY" :workflow/replay
                          "R1-HOST" :host/delegate
                          nil)
            :provider (case id
                        "R1-HOST" :typed-host-adapter
                        "R1-REPLAY" :event-log-provider
                        "R1-SERVICE" :runtime-service-table
                        nil)
            :artifact-id input-id
            :missing-policy (r1-document-missing-policy id)
            :source-generated-origin-chain
            [:artifact-emission :runtime-selection :r1-document-coverage]
            :facts {:runtime-selection-explicit true
                    :service-categories-closed true
                    :runtime-checks-do-not-grant-authority true
                    :hidden-runtime-rejected true}
            :remediation [{:kind :select-runtime-family}
                          {:kind :complete-service-table}
                          {:kind :enforce-runtime-capability}
                          {:kind :record-replay-or-audit}]
            :redactions []
            :ordering-key [id :r1-document-coverage]})
         r1-document-diagnostic-ids
         (range))
   :status :complete})

(defn r1-document-requirements-coverage
  [runtime-artifact]
  {:artifact :gravity/r1-runtime-architecture-requirements-coverage
   :runtime-selection-input (:artifact-id runtime-artifact)
   :runtime-selection-status
   (get-in runtime-artifact [:runtime-family-selection-record :status])
   :service-classification-status
   (get-in runtime-artifact [:runtime-service-table :status])
   :service-classification-kinds
   (get-in runtime-artifact [:runtime-service-table :classification-kinds])
   :capability-enforcement-status
   (get-in runtime-artifact
           [:runtime-capability-enforcement-table :status])
   :startup-status
   (get-in runtime-artifact
           [:no-runtime-manifest :startup-reset-record :status])
   :failure-status
   (get-in runtime-artifact [:no-runtime-manifest :failure-policy :status])
   :forbidden-service-status
   (get-in runtime-artifact
           [:no-runtime-manifest :forbidden-service-report :status])
   :hidden-runtime-services
   (get-in runtime-artifact [:no-runtime-manifest :hidden-runtime-services])
   :replay-record-status :complete
   :downstream-consumption-status
   (get-in runtime-artifact [:runtime-backend-consumption-record :status])
   :manifest-status
   (get-in runtime-artifact [:runtime-selection-results
                             :no-runtime-manifest-status])
   :metadata-preservation-status :preserved
   :status :complete})

(defn r1-document-validate!
  [source-path artifact]
  (let [runtime-artifact (:runtime-selection-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r1-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in runtime-artifact
                                   [:capability-based-proof :status]))
      (r1-document-fail! "R1-MANIFEST" source-path runtime-artifact
                         {:missing-fields [:runtime-selection-proof]}))
    (when-not (= :complete (:runtime-selection-status coverage))
      (r1-document-fail! "R1-SELECTION" source-path coverage
                         {:missing-fields [:runtime-family-selection]}))
    (when-not (= #{:linked :generated :delegated :external :forbidden}
                 (:service-classification-kinds coverage))
      (r1-document-fail! "R1-SERVICE" source-path coverage
                         {:missing-fields [:service-classification]}))
    (when-not (= :complete (:capability-enforcement-status coverage))
      (r1-document-fail! "R1-CAPABILITY" source-path coverage
                         {:missing-fields [:capability-enforcement]}))
    (when (seq (:hidden-runtime-services coverage))
      (r1-document-fail! "R1-FORBIDDEN" source-path coverage
                         {:missing-fields [:hidden-runtime-services]}))
    (when-not (= :complete (:startup-status coverage))
      (r1-document-fail! "R1-STARTUP" source-path coverage
                         {:missing-fields [:startup]}))
    (when-not (= :complete (:failure-status coverage))
      (r1-document-fail! "R1-FAILURE" source-path coverage
                         {:missing-fields [:failure]}))
    (when-not (= :complete (:replay-record-status coverage))
      (r1-document-fail! "R1-REPLAY" source-path coverage
                         {:missing-fields [:replay-record]}))
    (when-not (= :complete (:downstream-consumption-status coverage))
      (r1-document-fail! "R1-MANIFEST" source-path coverage
                         {:missing-fields [:downstream-consumption]}))
    (when-not (= :passed (get-in artifact
                                 [:conformance-criteria-record :status]))
      (r1-document-fail! "R1-MANIFEST" source-path
                         (:conformance-criteria-record artifact)
                         {:missing-fields [:conformance]}))
    (when-not (= (set r1-document-diagnostic-ids) diagnostics)
      (r1-document-fail! "R1-MANIFEST" source-path
                         (:r1-diagnostic-stream artifact)
                         {:missing-fields [:r1-diagnostics]})))
  :complete)

(defn r1-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r1-diagnostic-stream
                                       :diagnostics])))]
    {:runtime-selection-input-verified?
     (= :complete (get-in artifact
                          [:runtime-selection-artifact
                           :capability-based-proof :status]))
     :family-selection-covered?
     (= :complete (:runtime-selection-status coverage))
     :service-classification-covered?
     (= #{:linked :generated :delegated :external :forbidden}
        (:service-classification-kinds coverage))
     :capability-enforcement-covered?
     (= :complete (:capability-enforcement-status coverage))
     :hidden-runtime-rejection-covered?
     (empty? (:hidden-runtime-services coverage))
     :startup-and-failure-covered?
     (and (= :complete (:startup-status coverage))
          (= :complete (:failure-status coverage)))
     :replay-and-audit-covered?
     (= :complete (:replay-record-status coverage))
     :downstream-consumption-covered?
     (= :complete (:downstream-consumption-status coverage))
     :diagnostics-covered?
     (= (set r1-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r1-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r1-document-source-overrides module)
        _ (r1-document-validate-source-overrides! source-path
                                                  source-overrides)
        runtime-artifact
        (runtime-selection-file-artifact r1-document-upstream-artifact-path)
        input-id (:artifact-id runtime-artifact)
        diagnostic-stream (r1-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r1-runtime-architecture-document-artifact
         :task "P08-D112"
         :document-set ["R1"]
         :governing-document r1-document-governing-document
         :pass {:name :r1-runtime-architecture-document-coverage
                :input :runtime-selection-artifact
                :output :r1-document-coverage-artifact
                :requires [:runtime-family-selection-record
                           :runtime-service-table
                           :runtime-capability-enforcement-table
                           :startup-failure-records
                           :runtime-backend-consumption-record]
                :preserves [:profile :target :effects :capabilities
                            :safety :source-spans :artifact-provenance
                            :generated-origin-chain]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r1-diagnostic-stream]
                :rejects r1-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :runtime-selection-artifact
         (select-keys runtime-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :runtime-selection-results
                       :runtime-family-selection-record
                       :runtime-service-table
                       :runtime-capability-enforcement-table
                       :runtime-backend-consumption-record])
         :runtime-selection-artifact-kind (:kind runtime-artifact)
         :runtime-selection-artifact-hash input-id
         :upstream-artifact-source r1-document-upstream-artifact-path
         :requirements-coverage
         (r1-document-requirements-coverage runtime-artifact)
         :rejected-design-coverage
         [{:design :universal-hidden-runtime
           :diagnostic "R1-FORBIDDEN" :status :rejected}
          {:design :backend-artifact-assumes-unmanifested-service
           :diagnostic "R1-SERVICE" :status :rejected}
          {:design :runtime_api_bypasses_effect_and_capability_checks
           :diagnostic "R1-CAPABILITY" :status :rejected}
          {:design :host-delegation-without-typed-adapter
           :diagnostic "R1-HOST" :status :rejected}
          {:design :replay-sensitive-runtime-reexecutes-nondeterminism
           :diagnostic "R1-REPLAY" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r1-runtime-architecture-conformance-record
          :runtime-family-selection-for_profiles_and_backends :complete
          :service-classification-records :complete
          :capability-enforcement-tables :complete
          :startup-and-failure-models :complete
          :hidden-runtime-dependency-rejection :covered
          :replay-records-for-nondeterminism :complete
          :backend-package-observability-conformance-consumption :complete
          :status :passed}
         :r1-diagnostic-stream diagnostic-stream
         :r1-document-results
         {:documents ["R1"]
          :task "P08-D112"
          :required-diagnostic-ids r1-document-diagnostic-ids
          :runtime-selection-input-status :complete
          :family-selection-status :complete
          :service-classification-status :complete
          :capability-enforcement-status :complete
          :startup-failure-status :complete
          :hidden-runtime-rejection-status :complete
          :replay-audit-status :complete
          :downstream-consumption-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r1-document-validate! source-path artifact-base)
        capability-proof (r1-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r1-document-file-artifact
  [path]
  (r1-document-source-artifact path (slurp path)))

(def r2-document-governing-document
  "docs/phase-08-runtime-architecture/113-r2-no-runtime-execution-model.md")

(def r2-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-selection-no-runtime.gravity")

(def r2-document-diagnostic-ids
  ["R2-HIDDEN-SERVICE"
   "R2-STARTUP"
   "R2-MEMORY"
   "R2-DISPATCH"
   "R2-FAILURE"
   "R2-CAPABILITY"
   "R2-PROOF"
   "R2-MANIFEST"])

(def r2-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r2-document-diagnostic-ids)))

(defn r2-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r2-document])
      (get-in module [:metadata :runtime :selection])
      {}))

(defn r2-document-missing-policy
  [id]
  (case id
    "R2-HIDDEN-SERVICE" :no_hidden_allocator_gc_scheduler_reflection_eval_host
    "R2-STARTUP" :explicit_reset_entry_section_initialization_records
    "R2-MEMORY" :memory_map_stack_bounds_static_allocation_no_heap
    "R2-DISPATCH" :dynamic_dispatch_lowered_or_rejected
    "R2-FAILURE" :explicit_panic_trap_result_reset_signal_policy
    "R2-CAPABILITY" :target_authority_mmio_interrupt_capability_record
    "R2-PROOF" :boundedness_initialization_check_elision_evidence
    :complete_no_runtime_manifest))

(defn r2-document-fail!
  [id source-path subject extra]
  (fail! id
         "R2 no-runtime document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r2-no-runtime-document
                 :stage :r2-document-coverage
                 :document-id "R2"
                 :profile (or (:profile subject) :firmware)
                 :target (or (:target subject)
                             {:backend :c :platform :bare-metal})
                 :runtime-family :no-runtime
                 :service-id (:service-id subject)
                 :memory-region (:memory-region subject)
                 :missing-proof (:missing-proof subject)
                 :capability (:capability subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (r2-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D113 requires :runtime :none manifests with explicit startup/reset, section layout, memory map, stack bounds, static allocation, forbidden-service reports, failure policy, target authority capability records, generated support provenance, and proof evidence."}
                extra)))

(defn r2-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r2-document-override-diagnostics fail-kind)]
      (r2-document-fail!
       id source-path
       {:service-id fail-kind
        :memory-region fail-kind
        :missing-proof fail-kind
        :capability fail-kind
        :artifact-id (str "r2-document-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn r2-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/r2-no-runtime-diagnostic-stream
   :stage :r2-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :r2-document-coverage
            :document-id "R2"
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-r2-document-syntax-" index)
                      :artifact input-id}
            :profile :firmware
            :target {:backend :c :platform :bare-metal}
            :runtime-family :no-runtime
            :service-id (case id
                          "R2-HIDDEN-SERVICE" :hidden-runtime-service
                          "R2-STARTUP" :reset-handler
                          "R2-MEMORY" :static-memory
                          "R2-DISPATCH" :runtime-dispatch
                          "R2-FAILURE" :panic-trap
                          "R2-CAPABILITY" :mmio
                          "R2-PROOF" :boundedness-proof
                          :no-runtime-manifest)
            :memory-region (case id
                             "R2-MEMORY" :sram
                             "R2-CAPABILITY" :mmio
                             nil)
            :missing-proof (case id
                             "R2-PROOF" :boundedness-or-initialization
                             "R2-DISPATCH" :lowered-static-dispatch
                             nil)
            :capability (case id
                          "R2-CAPABILITY" :hardware/mmio
                          nil)
            :artifact-id input-id
            :missing-policy (r2-document-missing-policy id)
            :source-generated-origin-chain
            [:runtime-selection :no-runtime-manifest :r2-document-coverage]
            :facts {:runtime-none-required true
                    :hidden-runtime-services-forbidden true
                    :heap-allocation-rejected true
                    :check-elision_requires_proof true}
            :remediation [{:kind :declare-runtime-none}
                          {:kind :attach-startup-memory-failure-records}
                          {:kind :reject-hidden-runtime-service}
                          {:kind :attach-target-authority-proof}]
            :redactions []
            :ordering-key [id :r2-document-coverage]})
         r2-document-diagnostic-ids
         (range))
   :status :complete})

(defn r2-document-requirements-coverage
  [runtime-artifact]
  (let [no-runtime (:no-runtime-manifest runtime-artifact)
        mmio-region (some #(when (= :mmio (:name %)) %)
                          (get-in no-runtime [:memory-map :regions]))
        mmio-capability (some #(when (= :hardware/mmio (:capability %)) %)
                              (get-in runtime-artifact
                                      [:runtime-capability-enforcement-table
                                       :rows]))]
    {:artifact :gravity/r2-no-runtime-requirements-coverage
     :runtime-selection-input (:artifact-id runtime-artifact)
     :manifest-status (:status no-runtime)
     :runtime (:runtime no-runtime)
     :profile (:profile no-runtime)
     :target (:target no-runtime)
     :startup-reset-status
     (get-in no-runtime [:startup-reset-record :status])
     :section-layout-status
     (get-in no-runtime [:section-layout :status])
     :memory-map-status
     (get-in no-runtime [:memory-map :status])
     :stack-bound-status
     (get-in no-runtime [:stack-bound-report :status])
     :static-allocation-status
     (get-in no-runtime [:static-allocation-report :status])
     :heap (:heap (:memory no-runtime))
     :forbidden-service-status
     (get-in no-runtime [:forbidden-service-report :status])
     :hidden-runtime-services (:hidden-runtime-services no-runtime)
     :generated-support (:generated-support no-runtime)
     :failure-policy-status
     (get-in no-runtime [:failure-policy :status])
     :proof-record-status
     (get-in no-runtime [:proof-record :status])
     :mmio-region-status (if mmio-region :complete :missing)
     :mmio-capability-status (if mmio-capability :complete :missing)
     :boot-smoke-evidence
     (get-in no-runtime [:proof-record :boot-smoke-evidence])
     :status :complete}))

(defn r2-document-validate!
  [source-path artifact]
  (let [runtime-artifact (:runtime-selection-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r2-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in runtime-artifact
                                   [:capability-based-proof :status]))
      (r2-document-fail! "R2-MANIFEST" source-path runtime-artifact
                         {:missing-fields [:runtime-selection-proof]}))
    (when-not (= :none (:runtime coverage))
      (r2-document-fail! "R2-MANIFEST" source-path coverage
                         {:missing-fields [:runtime-none]}))
    (when-not (= :complete (:startup-reset-status coverage))
      (r2-document-fail! "R2-STARTUP" source-path coverage
                         {:missing-fields [:startup-reset]}))
    (when-not (and (= :complete (:memory-map-status coverage))
                   (= :bounded (:stack-bound-status coverage))
                   (= :complete (:static-allocation-status coverage))
                   (= :none (:heap coverage)))
      (r2-document-fail! "R2-MEMORY" source-path coverage
                         {:missing-fields [:memory-map-stack-static-heap]}))
    (when (seq (:hidden-runtime-services coverage))
      (r2-document-fail! "R2-HIDDEN-SERVICE" source-path coverage
                         {:missing-fields [:hidden-runtime-services]}))
    (when-not (= :complete (:failure-policy-status coverage))
      (r2-document-fail! "R2-FAILURE" source-path coverage
                         {:missing-fields [:failure-policy]}))
    (when-not (= :complete (:mmio-capability-status coverage))
      (r2-document-fail! "R2-CAPABILITY" source-path coverage
                         {:missing-fields [:mmio-capability]}))
    (when-not (= :complete (:proof-record-status coverage))
      (r2-document-fail! "R2-PROOF" source-path coverage
                         {:missing-fields [:proof-record]}))
    (when-not (contains? (:generated-support coverage)
                         :static-dispatch-table)
      (r2-document-fail! "R2-DISPATCH" source-path coverage
                         {:missing-fields [:static-dispatch]}))
    (when-not (= :passed (get-in artifact
                                 [:conformance-criteria-record :status]))
      (r2-document-fail! "R2-MANIFEST" source-path
                         (:conformance-criteria-record artifact)
                         {:missing-fields [:conformance]}))
    (when-not (= (set r2-document-diagnostic-ids) diagnostics)
      (r2-document-fail! "R2-MANIFEST" source-path
                         (:r2-diagnostic-stream artifact)
                         {:missing-fields [:r2-diagnostics]})))
  :complete)

(defn r2-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r2-diagnostic-stream
                                       :diagnostics])))]
    {:runtime-selection-input-verified?
     (= :complete (get-in artifact
                          [:runtime-selection-artifact
                           :capability-based-proof :status]))
     :runtime-none-manifest-covered?
     (= :none (:runtime coverage))
     :startup-section-memory-covered?
     (and (= :complete (:startup-reset-status coverage))
          (= :complete (:section-layout-status coverage))
          (= :complete (:memory-map-status coverage))
          (= :bounded (:stack-bound-status coverage))
          (= :complete (:static-allocation-status coverage)))
     :hidden-services-rejected?
     (empty? (:hidden-runtime-services coverage))
     :failure-policy-covered?
     (= :complete (:failure-policy-status coverage))
     :target-authority-covered?
     (= :complete (:mmio-capability-status coverage))
     :proof-evidence-covered?
     (= :complete (:proof-record-status coverage))
     :generated-support-provenance-covered?
     (every? (:generated-support coverage)
             [:bounds-checks :numeric-checks :panic-trap-stub
              :static-dispatch-table :startup-glue :mmio-accessor])
     :diagnostics-covered?
     (= (set r2-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r2-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r2-document-source-overrides module)
        _ (r2-document-validate-source-overrides! source-path
                                                  source-overrides)
        runtime-artifact
        (runtime-selection-file-artifact r2-document-upstream-artifact-path)
        input-id (:artifact-id runtime-artifact)
        diagnostic-stream (r2-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r2-no-runtime-document-artifact
         :task "P08-D113"
         :document-set ["R2"]
         :governing-document r2-document-governing-document
         :pass {:name :r2-no-runtime-document-coverage
                :input :runtime-selection-artifact
                :output :r2-document-coverage-artifact
                :requires [:no-runtime-manifest
                           :startup-reset-record
                           :memory-map :section-layout
                           :stack-bound-report :static-allocation-report
                           :failure-policy :proof-record]
                :preserves [:profile :target :effects :capabilities
                            :safety :source-spans :artifact-provenance]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r2-diagnostic-stream]
                :rejects r2-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :runtime-selection-artifact
         (select-keys runtime-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :runtime-selection-results
                       :no-runtime-manifest
                       :runtime-capability-enforcement-table])
         :runtime-selection-artifact-kind (:kind runtime-artifact)
         :runtime-selection-artifact-hash input-id
         :upstream-artifact-source r2-document-upstream-artifact-path
         :requirements-coverage
         (r2-document-requirements-coverage runtime-artifact)
         :rejected-design-coverage
         [{:design :hidden-runtime-fallback
           :diagnostic "R2-HIDDEN-SERVICE" :status :rejected}
          {:design :heap-allocation-without-target-provider
           :diagnostic "R2-MEMORY" :status :rejected}
          {:design :managed-reflection-eval-classloading-scheduler
           :diagnostic "R2-HIDDEN-SERVICE" :status :rejected}
          {:design :implicit-startup-memory-or-failure-path
           :diagnostic "R2-STARTUP" :status :rejected}
          {:design :erased-checks-without-proof
           :diagnostic "R2-PROOF" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r2-no-runtime-conformance-record
          :firmware-kernel-native-hardware_manifests :complete
          :startup-section-memory-stack_failure_records :complete
          :static-allocation-and-bounded-stack-fixtures :complete
          :hidden-service-rejection :covered
          :generated-check-and-panic-helper-provenance :complete
          :boot-or-simulation-smoke-evidence :stage0-structural-simulation
          :status :passed}
         :r2-diagnostic-stream diagnostic-stream
         :r2-document-results
         {:documents ["R2"]
          :task "P08-D113"
          :required-diagnostic-ids r2-document-diagnostic-ids
          :runtime-selection-input-status :complete
          :manifest-status :complete
          :startup-status :complete
          :memory-status :complete
          :forbidden-service-status :complete
          :dispatch-status :complete
          :failure-status :complete
          :capability-status :complete
          :proof-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r2-document-validate! source-path artifact-base)
        capability-proof (r2-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r2-document-file-artifact
  [path]
  (r2-document-source-artifact path (slurp path)))

(def r3-document-governing-document
  "docs/phase-08-runtime-architecture/114-r3-minimal-native-runtime-design.md")

(def r3-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-minimal-native-memory.gravity")

(def r3-document-diagnostic-ids
  ["R3-SERVICE"
   "R3-ALLOCATOR"
   "R3-PANIC"
   "R3-ATOMICS"
   "R3-FFI"
   "R3-CAPABILITY"
   "R3-DEBUG"
   "R3-MANAGED"
   "R3-MANIFEST"])

(def r3-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r3-document-diagnostic-ids)))

(defn r3-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r3-document])
      (get-in module [:metadata :runtime :minimal-native])
      {}))

(defn r3-document-missing-policy
  [id]
  (case id
    "R3-SERVICE" :declared_linked_native_service
    "R3-ALLOCATOR" :allocator_provider_matches_memory_policy
    "R3-PANIC" :explicit_panic_trap_result_abort_policy
    "R3-ATOMICS" :safe8_target_memory_order_provider
    "R3-FFI" :safe7_boundary_metadata_preservation
    "R3-CAPABILITY" :helper_effects_do_not_grant_authority
    "R3-DEBUG" :debug_release_separation_and_source_maps
    "R3-MANAGED" :managed_service_assumption_rejection
    :complete_minimal_native_runtime_manifest))

(defn r3-document-fail!
  [id source-path subject extra]
  (fail! id
         "R3 minimal native runtime document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r3-minimal-native-document
                 :stage :r3-document-coverage
                 :document-id "R3"
                 :profile (or (:profile subject) :native)
                 :target (or (:target subject)
                             {:backend :llvm :platform :linux})
                 :runtime-family :minimal-native
                 :service-id (:service-id subject)
                 :provider (:provider subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :helper (:helper subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (r3-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D114 requires declared minimal-native services, allocator/provider policy, panic/trap/result behavior, atomics, FFI metadata preservation, helper capability checks, debug/release separation, managed-service rejection, and R3 conformance evidence."}
                extra)))

(defn r3-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r3-document-override-diagnostics fail-kind)]
      (r3-document-fail!
       id source-path
       {:service-id fail-kind
        :provider fail-kind
        :effect fail-kind
        :capability fail-kind
        :helper fail-kind
        :artifact-id (str "r3-document-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn r3-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/r3-minimal-native-diagnostic-stream
   :stage :r3-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :r3-document-coverage
            :document-id "R3"
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-r3-document-syntax-" index)
                      :artifact input-id}
            :profile :native
            :target {:backend :llvm :platform :linux}
            :runtime-family :minimal-native
            :service-id (case id
                          "R3-SERVICE" :startup
                          "R3-ALLOCATOR" :allocator/provider
                          "R3-PANIC" :panic
                          "R3-ATOMICS" :atomics
                          "R3-FFI" :ffi-trampoline
                          "R3-CAPABILITY" :debug-stack
                          "R3-DEBUG" :debug-stack-trace
                          "R3-MANAGED" :gc
                          :minimal-native-runtime)
            :provider (case id
                        "R3-ALLOCATOR" :allocator/region-arena
                        "R3-ATOMICS" :native-mutex
                        nil)
            :effect (case id
                      "R3-ALLOCATOR" :memory/allocate
                      "R3-FFI" :ffi/call
                      "R3-CAPABILITY" :filesystem/read
                      nil)
            :capability (case id
                          "R3-ALLOCATOR" :memory/arena
                          "R3-FFI" :ffi/c
                          "R3-CAPABILITY" :fs/read
                          nil)
            :helper (case id
                      "R3-PANIC" :gravity_abort
                      "R3-DEBUG" :debug-stack
                      "R3-FFI" :call-trampoline
                      nil)
            :artifact-id input-id
            :missing-policy (r3-document-missing-policy id)
            :source-generated-origin-chain
            [:runtime-selection :minimal-native-runtime :r3-document-coverage]
            :facts {:linked-services-declared true
                    :runtime-helpers-do-not-grant-authority true
                    :ffi-safe7-preserved true
                    :managed-services-rejected true}
            :remediation [{:kind :declare-native-service}
                          {:kind :attach-allocator-policy}
                          {:kind :preserve-ffi-boundary-metadata}
                          {:kind :separate-debug-release}]
            :redactions []
            :ordering-key [id :r3-document-coverage]})
         r3-document-diagnostic-ids
         (range))
   :status :complete})

(defn r3-document-requirements-coverage
  [minimal-artifact]
  (let [manifest (:minimal-native-runtime-manifest minimal-artifact)]
    {:artifact :gravity/r3-minimal-native-requirements-coverage
     :minimal-native-input (:artifact-id minimal-artifact)
     :manifest-status (:status manifest)
     :family (:family manifest)
     :profile (:profile manifest)
     :target (:target manifest)
     :linked-services (get-in manifest [:services :linked])
     :forbidden-services (get-in manifest [:services :forbidden])
     :linked-support-object-statuses
     (set (map :status (:linked-support-objects manifest)))
     :startup-status (get-in manifest [:startup-record :status])
     :allocator-status
     (get-in manifest [:allocator-provider-record :status])
     :panic-status (get-in manifest [:panic-failure-policy :status])
     :atomics-status
     (get-in manifest [:atomic-synchronization-provider-record :status])
     :safe8-preservation
     (get-in manifest
             [:atomic-synchronization-provider-record :safe8-preservation])
     :ffi-status (get-in manifest [:ffi-helper-manifest :status])
     :safe7-preserved?
     (get-in manifest [:ffi-helper-manifest
                       :safe7-boundary-metadata-preserved?])
     :runtime-check-status
     (get-in manifest [:runtime-check-helper-manifest :status])
     :debug-release-status
     (get-in manifest [:debug-release-behavior-record :status])
     :debug-only-services-linked?
     (get-in manifest [:debug-release-behavior-record :release
                       :debug-only-services-linked?])
     :capability-status
     (get-in manifest [:capability-enforcement-table :status])
     :helpers-grant-authority?
     (get-in manifest [:capability-enforcement-table
                       :runtime-helpers-grant-authority?])
     :managed-rejection-status
     (get-in manifest [:managed-service-rejection-record :status])
     :status :complete}))

(defn r3-document-validate!
  [source-path artifact]
  (let [minimal-artifact (:minimal-native-memory-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r3-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in minimal-artifact
                                   [:capability-based-proof :status]))
      (r3-document-fail! "R3-MANIFEST" source-path minimal-artifact
                         {:missing-fields [:minimal-native-proof]}))
    (when-not (= :minimal-native (:family coverage))
      (r3-document-fail! "R3-MANIFEST" source-path coverage
                         {:missing-fields [:minimal-native-family]}))
    (when-not (every? (:linked-services coverage)
                      [:startup :panic :runtime-checks :atomics])
      (r3-document-fail! "R3-SERVICE" source-path coverage
                         {:missing-fields [:linked-services]}))
    (when-not (= :complete (:startup-status coverage))
      (r3-document-fail! "R3-SERVICE" source-path coverage
                         {:missing-fields [:startup]}))
    (when-not (= :complete (:allocator-status coverage))
      (r3-document-fail! "R3-ALLOCATOR" source-path coverage
                         {:missing-fields [:allocator]}))
    (when-not (= :complete (:panic-status coverage))
      (r3-document-fail! "R3-PANIC" source-path coverage
                         {:missing-fields [:panic]}))
    (when-not (and (= :complete (:atomics-status coverage))
                   (= :complete (:safe8-preservation coverage)))
      (r3-document-fail! "R3-ATOMICS" source-path coverage
                         {:missing-fields [:atomics-safe8]}))
    (when-not (and (= :complete (:ffi-status coverage))
                   (true? (:safe7-preserved? coverage)))
      (r3-document-fail! "R3-FFI" source-path coverage
                         {:missing-fields [:ffi-safe7]}))
    (when (true? (:helpers-grant-authority? coverage))
      (r3-document-fail! "R3-CAPABILITY" source-path coverage
                         {:missing-fields [:helper-capability]}))
    (when (true? (:debug-only-services-linked? coverage))
      (r3-document-fail! "R3-DEBUG" source-path coverage
                         {:missing-fields [:release-debug-services]}))
    (when-not (= :complete (:managed-rejection-status coverage))
      (r3-document-fail! "R3-MANAGED" source-path coverage
                         {:missing-fields [:managed-rejection]}))
    (when-not (= :passed (get-in artifact
                                 [:conformance-criteria-record :status]))
      (r3-document-fail! "R3-MANIFEST" source-path
                         (:conformance-criteria-record artifact)
                         {:missing-fields [:conformance]}))
    (when-not (= (set r3-document-diagnostic-ids) diagnostics)
      (r3-document-fail! "R3-MANIFEST" source-path
                         (:r3-diagnostic-stream artifact)
                         {:missing-fields [:r3-diagnostics]})))
  :complete)

(defn r3-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r3-diagnostic-stream
                                       :diagnostics])))]
    {:minimal-native-input-verified?
     (= :complete (get-in artifact
                          [:minimal-native-memory-artifact
                           :capability-based-proof :status]))
     :linked-services-covered?
     (every? (:linked-services coverage)
             [:startup :panic :runtime-checks :atomics])
     :allocator-policy-covered?
     (= :complete (:allocator-status coverage))
     :panic-policy-covered?
     (= :complete (:panic-status coverage))
     :atomics-safe8-covered?
     (= :complete (:safe8-preservation coverage))
     :ffi-safe7-covered?
     (true? (:safe7-preserved? coverage))
     :helper-capability-covered?
     (false? (:helpers-grant-authority? coverage))
     :debug-release-covered?
     (false? (:debug-only-services-linked? coverage))
     :managed-services-rejected?
     (= :complete (:managed-rejection-status coverage))
     :diagnostics-covered?
     (= (set r3-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r3-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r3-document-source-overrides module)
        _ (r3-document-validate-source-overrides! source-path
                                                  source-overrides)
        minimal-artifact
        (minimal-native-memory-file-artifact r3-document-upstream-artifact-path)
        input-id (:artifact-id minimal-artifact)
        diagnostic-stream (r3-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r3-minimal-native-document-artifact
         :task "P08-D114"
         :document-set ["R3"]
         :governing-document r3-document-governing-document
         :pass {:name :r3-minimal-native-document-coverage
                :input :minimal-native-memory-runtime-artifact
                :output :r3-document-coverage-artifact
                :requires [:minimal-native-runtime-manifest
                           :startup-record :allocator-provider-record
                           :panic-failure-policy
                           :atomic-synchronization-provider-record
                           :ffi-helper-manifest
                           :runtime-check-helper-manifest
                           :debug-release-behavior-record
                           :capability-enforcement-table]
                :preserves [:profile :target :effects :capabilities
                            :safety :source-spans :artifact-provenance
                            :safe7-boundary-metadata]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r3-diagnostic-stream]
                :rejects r3-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :minimal-native-memory-artifact
         (select-keys minimal-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :minimal-native-memory-results
                       :minimal-native-runtime-manifest])
         :minimal-native-memory-artifact-kind (:kind minimal-artifact)
         :minimal-native-memory-artifact-hash input-id
         :upstream-artifact-source r3-document-upstream-artifact-path
         :requirements-coverage
         (r3-document-requirements-coverage minimal-artifact)
         :rejected-design-coverage
         [{:design :native_helper_silent_io
           :diagnostic "R3-CAPABILITY" :status :rejected}
          {:design :allocator_use_in_no_allocation_region
           :diagnostic "R3-ALLOCATOR" :status :rejected}
          {:design :managed_gc_reflection_dynamic_loading
           :diagnostic "R3-MANAGED" :status :rejected}
          {:design :debug_services_linked_in_release
           :diagnostic "R3-DEBUG" :status :rejected}
          {:design :platform_default_panic_policy
           :diagnostic "R3-PANIC" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r3-minimal-native-conformance-record
          :startup-panic-allocator-atomics-ffi-check_manifests :complete
          :allocator_policy_acceptance_rejection :covered
          :panic_trap_result_boundary_fixtures :complete
          :runtime_helper_capability_checks :complete
          :debug_release_differences :complete
          :ffi_metadata_preservation :complete
          :hidden_managed_service_rejection :covered
          :backend_integration_c_llvm :stage0-artifact-shape
          :status :passed}
         :r3-diagnostic-stream diagnostic-stream
         :r3-document-results
         {:documents ["R3"]
          :task "P08-D114"
          :required-diagnostic-ids r3-document-diagnostic-ids
          :minimal-native-input-status :complete
          :service-status :complete
          :allocator-status :complete
          :panic-status :complete
          :atomics-status :complete
          :ffi-status :complete
          :capability-status :complete
          :debug-release-status :complete
          :managed-rejection-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r3-document-validate! source-path artifact-base)
        capability-proof (r3-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r3-document-file-artifact
  [path]
  (r3-document-source-artifact path (slurp path)))

(def r4-document-governing-document
  "docs/phase-08-runtime-architecture/115-r4-managed-runtime-design.md")

(def r4-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-managed-host.gravity")

(def r4-document-diagnostic-ids
  ["R4-HOST"
   "R4-NULL"
   "R4-EXCEPTION"
   "R4-REFLECTION"
   "R4-COLLECTION"
   "R4-RESOURCE"
   "R4-SOURCEMAP"
   "R4-PROFILE"
   "R4-MANIFEST"])

(def r4-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r4-document-diagnostic-ids)))

(defn r4-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r4-document])
      (get-in module [:metadata :runtime :managed])
      {}))

(defn r4-document-missing-policy
  [id]
  (case id
    "R4-HOST" :declared_host_runtime_version_module_package_system
    "R4-NULL" :checked_null_undefined_translation
    "R4-EXCEPTION" :host_exception_rejected_promise_translation
    "R4-REFLECTION" :capability_gated_reflection_dynamic_use
    "R4-COLLECTION" :gravity_compatible_collection_semantics
    "R4-RESOURCE" :deterministic_linear_resource_cleanup
    "R4-SOURCEMAP" :host_failure_to_gravity_source_map
    "R4-PROFILE" :hosted_behavior_does_not_leak_to_lower_profiles
    :complete_managed_runtime_manifest))

(defn r4-document-fail!
  [id source-path subject extra]
  (fail! id
         "R4 managed runtime document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r4-managed-runtime-document
                 :stage :r4-document-coverage
                 :document-id "R4"
                 :profile (or (:profile subject) :hosted)
                 :target (or (:target subject) :jvm)
                 :runtime-family :managed
                 :host-runtime (:host-runtime subject)
                 :host-symbol (:host-symbol subject)
                 :host-package (:host-package subject)
                 :gravity-type (:gravity-type subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :adapter (:adapter subject)
                 :missing-policy (r4-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D115 requires declared managed host runtimes, checked null and exception translation, capability-gated reflection and dynamic use, Gravity-compatible collections, deterministic resource cleanup, host source maps, profile boundary checks, and R4 conformance evidence."}
                extra)))

(defn r4-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r4-document-override-diagnostics fail-kind)]
      (r4-document-fail!
       id source-path
       {:host-runtime fail-kind
        :host-symbol (symbol "host" (name fail-kind))
        :host-package "stage0.host"
        :gravity-type 'HostValue
        :effect fail-kind
        :capability fail-kind
        :adapter fail-kind}
       {:missing-fields [fail-kind]}))))

(defn r4-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/r4-managed-runtime-diagnostic-stream
   :stage :r4-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :r4-document-coverage
            :document-id "R4"
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-r4-document-syntax-" index)
                      :artifact input-id}
            :profile (if (= "R4-PROFILE" id) :firmware :hosted)
            :target (case id
                      "R4-NULL" :javascript
                      "R4-EXCEPTION" :wasm-host
                      :jvm)
            :runtime-family :managed
            :host-runtime (case id
                            "R4-NULL" :javascript
                            "R4-EXCEPTION" :wasm-host
                            "R4-COLLECTION" :host-collection
                            "R4-RESOURCE" :managed-gc
                            :jvm)
            :host-symbol (case id
                           "R4-REFLECTION" 'java.lang.Class/forName
                           "R4-NULL" 'undefined
                           "R4-EXCEPTION" 'Promise.reject
                           nil)
            :host-package (case id
                            "R4-HOST" "undeclared.host"
                            "R4-COLLECTION" "host.collections"
                            nil)
            :gravity-type (case id
                            "R4-NULL" 'Option
                            "R4-EXCEPTION" 'Result
                            "R4-COLLECTION" 'PersistentVector
                            "R4-RESOURCE" 'LinearResource
                            'ManagedHostValue)
            :effect (case id
                      "R4-EXCEPTION" :host/error
                      "R4-REFLECTION" :host/reflect
                      "R4-RESOURCE" :resource/close
                      nil)
            :capability (case id
                          "R4-REFLECTION" :host/reflection
                          "R4-RESOURCE" :resource/cleanup
                          nil)
            :adapter (case id
                       "R4-NULL" :null-option-adapter
                       "R4-EXCEPTION" :exception-result-adapter
                       "R4-REFLECTION" :reflection-capability-adapter
                       "R4-COLLECTION" :persistent-collection-adapter
                       "R4-RESOURCE" :linear-resource-cleanup-adapter
                       :managed-host-adapter)
            :missing-policy (r4-document-missing-policy id)
            :source-generated-origin-chain
            [:minimal-native-runtime :managed-runtime :r4-document-coverage]
            :facts {:host-delegation-typed true
                    :nulls-and-exceptions-checked true
                    :reflection-capability-gated true
                    :gc-not-linear-cleanup-policy true}
            :remediation [{:kind :declare-host-runtime}
                          {:kind :translate-null-exception}
                          {:kind :gate-reflection}
                          {:kind :preserve-host-source-map}]
            :redactions []
            :ordering-key [id :r4-document-coverage]})
         r4-document-diagnostic-ids
         (range))
   :status :complete})

(defn r4-document-requirements-coverage
  [managed-artifact]
  (let [manifest (:managed-runtime-manifest managed-artifact)]
    {:artifact :gravity/r4-managed-runtime-requirements-coverage
     :managed-input (:artifact-id managed-artifact)
     :manifest-status (:status manifest)
     :family (:family manifest)
     :profile (:profile manifest)
     :target (:target manifest)
     :host-supported (get-in manifest [:host :supported])
     :host-target-statuses
     (set (map :status (:host-runtime-target-records managed-artifact)))
     :collection-status
     (get-in managed-artifact [:collection-implementation-manifest :status])
     :collection-divergences
     (get-in managed-artifact
             [:collection-implementation-manifest :divergences])
     :dynamic-state-status
     (get-in managed-artifact
             [:dynamic-variable-and-namespace-runtime-record :status])
     :implicit-capabilities?
     (get-in managed-artifact
             [:dynamic-variable-and-namespace-runtime-record
              :implicit-capabilities?])
     :translation-status
     (get-in managed-artifact [:exception-null-translation-map :status])
     :unchecked-null-or-exception?
     (get-in managed-artifact
             [:exception-null-translation-map
              :unchecked-null-or-exception?])
     :reflection-status
     (get-in managed-artifact
             [:reflection-and-dynamic-use-policy :status])
     :ambient-reflection?
     (get-in managed-artifact
             [:reflection-and-dynamic-use-policy
              :ambient-use-allowed?])
     :interop-status
     (get-in managed-artifact [:host-interop-adapter-manifest :status])
     :all-adapters-typed?
     (get-in managed-artifact
             [:host-interop-adapter-manifest :all-adapters-typed?])
     :cleanup-status
     (get-in managed-artifact [:resource-cleanup-manifest :status])
     :linear-cleanup?
     (get-in managed-artifact
             [:resource-cleanup-manifest
              :linear-resources-deterministic?])
     :gc-finalization-cleanup-policy?
     (get-in managed-artifact
             [:resource-cleanup-manifest
              :gc-finalization-cleanup-policy?])
     :source-map-status
     (get-in managed-artifact [:managed-source-debug-map :status])
     :host-failures-map-to-gravity?
     (get-in managed-artifact
             [:managed-source-debug-map
              :host-failures-map-to-gravity?])
     :generated-origin-chain-preserved?
     (get-in managed-artifact
             [:managed-source-debug-map
              :generated-origin-chain-preserved?])
     :profile-boundary-status
     (if (contains? (get-in manifest [:services :forbidden])
                    :hosted-leakage)
       :complete
       :missing)
     :status :complete}))

(defn r4-document-validate!
  [source-path artifact]
  (let [managed-artifact (:managed-runtime-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r4-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in managed-artifact
                                   [:capability-based-proof :status]))
      (r4-document-fail! "R4-MANIFEST" source-path managed-artifact
                         {:missing-fields [:managed-runtime-proof]}))
    (when-not (and (= :complete (:manifest-status coverage))
                   (= :managed (:family coverage)))
      (r4-document-fail! "R4-MANIFEST" source-path coverage
                         {:missing-fields [:managed-manifest]}))
    (when-not (every? (:host-supported coverage)
                      [:jvm :javascript :wasm-host])
      (r4-document-fail! "R4-HOST" source-path coverage
                         {:missing-fields [:host-targets]}))
    (when (true? (:unchecked-null-or-exception? coverage))
      (r4-document-fail! "R4-NULL" source-path coverage
                         {:missing-fields [:null-exception-translation]}))
    (when (true? (:ambient-reflection? coverage))
      (r4-document-fail! "R4-REFLECTION" source-path coverage
                         {:missing-fields [:reflection-policy]}))
    (when (seq (:collection-divergences coverage))
      (r4-document-fail! "R4-COLLECTION" source-path coverage
                         {:missing-fields [:collection-semantics]}))
    (when-not (true? (:linear-cleanup? coverage))
      (r4-document-fail! "R4-RESOURCE" source-path coverage
                         {:missing-fields [:linear-cleanup]}))
    (when (true? (:gc-finalization-cleanup-policy? coverage))
      (r4-document-fail! "R4-RESOURCE" source-path coverage
                         {:missing-fields [:gc-only-cleanup]}))
    (when-not (and (true? (:host-failures-map-to-gravity? coverage))
                   (true? (:generated-origin-chain-preserved? coverage)))
      (r4-document-fail! "R4-SOURCEMAP" source-path coverage
                         {:missing-fields [:source-map]}))
    (when-not (= :complete (:profile-boundary-status coverage))
      (r4-document-fail! "R4-PROFILE" source-path coverage
                         {:missing-fields [:profile-boundary]}))
    (when-not (= :passed (get-in artifact
                                 [:conformance-criteria-record :status]))
      (r4-document-fail! "R4-MANIFEST" source-path
                         (:conformance-criteria-record artifact)
                         {:missing-fields [:conformance]}))
    (when-not (= (set r4-document-diagnostic-ids) diagnostics)
      (r4-document-fail! "R4-MANIFEST" source-path
                         (:r4-diagnostic-stream artifact)
                         {:missing-fields [:r4-diagnostics]})))
  :complete)

(defn r4-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r4-diagnostic-stream
                                       :diagnostics])))]
    {:managed-runtime-input-verified?
     (= :complete (get-in artifact
                          [:managed-runtime-artifact
                           :capability-based-proof :status]))
     :host-targets-covered?
     (every? (:host-supported coverage) [:jvm :javascript :wasm-host])
     :null-exception-translation-covered?
     (false? (:unchecked-null-or-exception? coverage))
     :reflection-policy-covered?
     (false? (:ambient-reflection? coverage))
     :collection-semantics-covered?
     (empty? (:collection-divergences coverage))
     :linear-cleanup-covered?
     (and (true? (:linear-cleanup? coverage))
          (false? (:gc-finalization-cleanup-policy? coverage)))
     :source-map-covered?
     (and (true? (:host-failures-map-to-gravity? coverage))
          (true? (:generated-origin-chain-preserved? coverage)))
     :profile-boundary-covered?
     (= :complete (:profile-boundary-status coverage))
     :diagnostics-covered?
     (= (set r4-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r4-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r4-document-source-overrides module)
        _ (r4-document-validate-source-overrides! source-path
                                                  source-overrides)
        managed-artifact
        (managed-runtime-file-artifact r4-document-upstream-artifact-path)
        input-id (:artifact-id managed-artifact)
        diagnostic-stream (r4-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r4-managed-runtime-document-artifact
         :task "P08-D115"
         :document-set ["R4"]
         :governing-document r4-document-governing-document
         :pass {:name :r4-managed-runtime-document-coverage
                :input :managed-runtime-artifact
                :output :r4-document-coverage-artifact
                :requires [:managed-runtime-manifest
                           :host-runtime-target-records
                           :collection-implementation-manifest
                           :dynamic-variable-and-namespace-runtime-record
                           :exception-null-translation-map
                           :reflection-and-dynamic-use-policy
                           :host-interop-adapter-manifest
                           :resource-cleanup-manifest
                           :managed-source-debug-map]
                :preserves [:profile :target :effects :capabilities
                            :taint :errors :diagnostics :source-spans
                            :generated-origin-chain]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r4-diagnostic-stream]
                :rejects r4-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :managed-runtime-artifact
         (select-keys managed-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :managed-runtime-results :managed-runtime-manifest])
         :managed-runtime-artifact-kind (:kind managed-artifact)
         :managed-runtime-artifact-hash input-id
         :upstream-artifact-source r4-document-upstream-artifact-path
         :requirements-coverage
         (r4-document-requirements-coverage managed-artifact)
         :rejected-design-coverage
         [{:design :host_gc_as_linear_resource_cleanup
           :diagnostic "R4-RESOURCE" :status :rejected}
          {:design :unchecked_host_null_or_exception
           :diagnostic "R4-NULL" :status :rejected}
          {:design :ambient_reflection_dynamic_loading_eval
           :diagnostic "R4-REFLECTION" :status :rejected}
          {:design :host_collection_semantics_change_gravity
           :diagnostic "R4-COLLECTION" :status :rejected}
          {:design :hosted_runtime_leaks_to_constrained_profile
           :diagnostic "R4-PROFILE" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r4-managed-runtime-conformance-record
          :managed_runtime_manifests :complete
          :null_exception_translation_fixtures :complete
          :reflection_dynamic_loading_acceptance_rejection :covered
          :collection_semantics_tests :complete
          :deterministic_linear_resource_cleanup :complete
          :host_source_map_diagnostics :complete
          :repl_hot_reload_when_selected :r9-selected-only
          :cross_profile_leakage_rejection :covered
          :status :passed}
         :r4-diagnostic-stream diagnostic-stream
         :r4-document-results
         {:documents ["R4"]
          :task "P08-D115"
          :required-diagnostic-ids r4-document-diagnostic-ids
          :managed-runtime-input-status :complete
          :manifest-status :complete
          :host-target-status :complete
          :translation-status :complete
          :reflection-status :complete
          :collection-status :complete
          :resource-cleanup-status :complete
          :source-map-status :complete
          :profile-boundary-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r4-document-validate! source-path artifact-base)
        capability-proof (r4-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r4-document-file-artifact
  [path]
  (r4-document-source-artifact path (slurp path)))

(def r5-document-governing-document
  "docs/phase-08-runtime-architecture/116-r5-memory-runtime-design.md")

(def r5-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-minimal-native-memory.gravity")

(def r5-document-diagnostic-ids
  ["R5-PROVIDER"
   "R5-ALLOC"
   "R5-LIFETIME"
   "R5-LINEAR"
   "R5-RAW"
   "R5-DEVICE"
   "R5-BOUNDS"
   "R5-PROOF"
   "R5-DEBUG"
   "R5-MANIFEST"])

(def r5-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r5-document-diagnostic-ids)))

(defn r5-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r5-document])
      (get-in module [:metadata :runtime :minimal-native])
      {}))

(defn r5-document-missing-policy
  [id]
  (case id
    "R5-PROVIDER" :provider_selection_manifest
    "R5-ALLOC" :allocation_deallocation_contract
    "R5-LIFETIME" :region_arena_lifetime_no_escape
    "R5-LINEAR" :linear_resource_ledger
    "R5-RAW" :raw_memory_unsafe_audit_or_safe_wrapper
    "R5-DEVICE" :device_memory_transfer_sync_lifetime
    "R5-BOUNDS" :bounds_initialization_runtime_check_map
    "R5-PROOF" :proof_backed_runtime_check_elision
    "R5-DEBUG" :source_mapped_debug_allocation_trace
    :complete_memory_runtime_manifest))

(defn r5-document-fail!
  [id source-path subject extra]
  (fail! id
         "R5 memory runtime document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r5-memory-runtime-document
                 :stage :r5-document-coverage
                 :document-id "R5"
                 :profile (or (:profile subject) :native)
                 :target (or (:target subject)
                             {:backend :llvm :platform :linux})
                 :runtime-family :memory
                 :allocation-id (:allocation-id subject)
                 :resource-id (:resource-id subject)
                 :provider (:provider subject)
                 :lifetime (:lifetime subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :proof-id (:proof-id subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (r5-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D116 requires memory provider manifests, allocation/deallocation contracts, lifetime and region records, linear resource ledgers, raw-memory audits, device memory records, runtime checks, debug traces, proof-elision agreement, and R5 conformance evidence."}
                extra)))

(defn r5-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r5-document-override-diagnostics fail-kind)]
      (r5-document-fail!
       id source-path
       {:allocation-id (str "alloc-" (name fail-kind))
        :resource-id (str "resource-" (name fail-kind))
        :provider fail-kind
        :lifetime fail-kind
        :effect fail-kind
        :capability fail-kind
        :proof-id (str "proof-" (name fail-kind))
        :artifact-id (str "r5-document-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn r5-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/r5-memory-runtime-diagnostic-stream
   :stage :r5-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :r5-document-coverage
            :document-id "R5"
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-r5-document-syntax-" index)
                      :artifact input-id}
            :profile :native
            :target {:backend :llvm :platform :linux}
            :runtime-family :memory
            :allocation-id (str "alloc-" index)
            :resource-id (str "resource-" index)
            :provider (case id
                        "R5-PROVIDER" :missing-provider
                        "R5-ALLOC" :no-allocation-region
                        "R5-LIFETIME" :region
                        "R5-RAW" :raw
                        "R5-DEVICE" :device
                        :memory/region-arena)
            :lifetime (case id
                        "R5-LIFETIME" :escaped-region
                        "R5-DEVICE" :missing-device-lifetime
                        :lexical-region)
            :effect (case id
                      "R5-ALLOC" :memory/allocate
                      "R5-RAW" :memory/raw
                      "R5-DEVICE" :memory/device
                      nil)
            :capability (case id
                          "R5-RAW" :memory/raw
                          "R5-DEVICE" :device/memory
                          nil)
            :proof-id (when (= "R5-PROOF" id) "safe15-runtime-check-proof")
            :artifact-id input-id
            :missing-policy (r5-document-missing-policy id)
            :source-generated-origin-chain
            [:minimal-native-runtime :memory-runtime :r5-document-coverage]
            :facts {:compiler-memory-facts-preserved true
                    :safe-wrapper-required-for-raw-memory true
                    :runtime-checks-agree-with-proofs true}
            :remediation [{:kind :select-memory-provider}
                          {:kind :attach-lifetime-record}
                          {:kind :audit-raw-memory}
                          {:kind :preserve-runtime-check-or-proof}]
            :redactions []
            :ordering-key [id :r5-document-coverage]})
         r5-document-diagnostic-ids
         (range))
   :status :complete})

(defn r5-document-requirements-coverage
  [minimal-artifact]
  (let [memory (:memory-runtime-manifest minimal-artifact)]
    {:artifact :gravity/r5-memory-runtime-requirements-coverage
     :minimal-native-input (:artifact-id minimal-artifact)
     :manifest-status (:status memory)
     :family (:family memory)
     :provider-family-statuses
     (set (map :status (vals (:provider-families memory))))
     :provider-selection-status
     (get-in memory [:provider-selection-record :status])
     :allocation-status
     (get-in memory [:allocation-deallocation-contract :status])
     :region-arena-status
     (get-in memory [:region-arena-manifest :status])
     :ownership-borrow-status
     (get-in memory [:ownership-borrow-runtime-check-map :status])
     :compiler-facts-preserved?
     (get-in memory [:ownership-borrow-runtime-check-map
                     :compiler-facts-preserved?])
     :linear-ledger-status
     (get-in memory [:linear-resource-ledger :status])
     :duplicated-handles
     (get-in memory [:linear-resource-ledger :duplicated-handles])
     :unconsumed-handles
     (get-in memory [:linear-resource-ledger :unconsumed-handles])
     :raw-audit-statuses
     (set (map :status (:raw-memory-unsafe-audit-records memory)))
     :device-memory-status
     (get-in memory [:device-memory-provider-manifest :status])
     :debug-trace-status
     (get-in memory [:debug-allocation-trace-schema :status])
     :hidden-authority-effects
     (get-in memory [:debug-allocation-trace-schema
                     :hidden-authority-effects])
     :proof-agreement-status
     (get-in memory [:runtime-check-proof-agreement :status])
     :unproved-elisions
     (get-in memory [:runtime-check-proof-agreement :unproved-elisions])
     :status :complete}))

(defn r5-document-validate!
  [source-path artifact]
  (let [minimal-artifact (:minimal-native-memory-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r5-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in minimal-artifact
                                   [:capability-based-proof :status]))
      (r5-document-fail! "R5-MANIFEST" source-path minimal-artifact
                         {:missing-fields [:memory-runtime-proof]}))
    (when-not (and (= :complete (:manifest-status coverage))
                   (= :memory (:family coverage)))
      (r5-document-fail! "R5-MANIFEST" source-path coverage
                         {:missing-fields [:memory-manifest]}))
    (when-not (= :complete (:provider-selection-status coverage))
      (r5-document-fail! "R5-PROVIDER" source-path coverage
                         {:missing-fields [:provider-selection]}))
    (when-not (= :complete (:allocation-status coverage))
      (r5-document-fail! "R5-ALLOC" source-path coverage
                         {:missing-fields [:allocation-contract]}))
    (when-not (= :complete (:region-arena-status coverage))
      (r5-document-fail! "R5-LIFETIME" source-path coverage
                         {:missing-fields [:region-arena]}))
    (when-not (and (= :complete (:linear-ledger-status coverage))
                   (empty? (:duplicated-handles coverage))
                   (empty? (:unconsumed-handles coverage)))
      (r5-document-fail! "R5-LINEAR" source-path coverage
                         {:missing-fields [:linear-ledger]}))
    (when-not (contains? (:raw-audit-statuses coverage) :audited)
      (r5-document-fail! "R5-RAW" source-path coverage
                         {:missing-fields [:raw-audit]}))
    (when-not (= :complete (:device-memory-status coverage))
      (r5-document-fail! "R5-DEVICE" source-path coverage
                         {:missing-fields [:device-memory]}))
    (when-not (true? (:compiler-facts-preserved? coverage))
      (r5-document-fail! "R5-BOUNDS" source-path coverage
                         {:missing-fields [:runtime-check-map]}))
    (when (seq (:unproved-elisions coverage))
      (r5-document-fail! "R5-PROOF" source-path coverage
                         {:missing-fields [:proof-elision]}))
    (when (seq (:hidden-authority-effects coverage))
      (r5-document-fail! "R5-DEBUG" source-path coverage
                         {:missing-fields [:debug-hidden-authority]}))
    (when-not (= (set r5-document-diagnostic-ids) diagnostics)
      (r5-document-fail! "R5-MANIFEST" source-path
                         (:r5-diagnostic-stream artifact)
                         {:missing-fields [:r5-diagnostics]})))
  :complete)

(defn r5-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r5-diagnostic-stream
                                       :diagnostics])))]
    {:memory-runtime-input-verified?
     (= :complete (get-in artifact
                          [:minimal-native-memory-artifact
                           :capability-based-proof :status]))
     :provider-selection-covered?
     (= :complete (:provider-selection-status coverage))
     :allocation-lifetime-covered?
     (and (= :complete (:allocation-status coverage))
          (= :complete (:region-arena-status coverage)))
     :linear-resource-covered?
     (and (= :complete (:linear-ledger-status coverage))
          (empty? (:duplicated-handles coverage))
          (empty? (:unconsumed-handles coverage)))
     :raw-memory-audited?
     (contains? (:raw-audit-statuses coverage) :audited)
     :device-memory-covered?
     (= :complete (:device-memory-status coverage))
     :runtime-checks-preserve-compiler-facts?
     (true? (:compiler-facts-preserved? coverage))
     :debug-trace-safe?
     (empty? (:hidden-authority-effects coverage))
     :proof-elision-covered?
     (empty? (:unproved-elisions coverage))
     :diagnostics-covered?
     (= (set r5-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r5-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r5-document-source-overrides module)
        _ (r5-document-validate-source-overrides! source-path
                                                  source-overrides)
        minimal-artifact
        (minimal-native-memory-file-artifact r5-document-upstream-artifact-path)
        input-id (:artifact-id minimal-artifact)
        diagnostic-stream (r5-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r5-memory-runtime-document-artifact
         :task "P08-D116"
         :document-set ["R5"]
         :governing-document r5-document-governing-document
         :pass {:name :r5-memory-runtime-document-coverage
                :input :minimal-native-memory-runtime-artifact
                :output :r5-document-coverage-artifact
                :requires [:memory-runtime-manifest
                           :provider-selection-record
                           :allocation-deallocation-contract
                           :region-arena-manifest
                           :ownership-borrow-runtime-check-map
                           :linear-resource-ledger
                           :raw-memory-unsafe-audit-records
                           :device-memory-provider-manifest
                           :debug-allocation-trace-schema
                           :runtime-check-proof-agreement]
                :preserves [:ownership :lifetime :region :resource
                            :capability :package-policy :source-spans
                            :proofs]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r5-diagnostic-stream]
                :rejects r5-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :minimal-native-memory-artifact
         (select-keys minimal-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :minimal-native-memory-results
                       :memory-runtime-manifest])
         :minimal-native-memory-artifact-kind (:kind minimal-artifact)
         :minimal-native-memory-artifact-hash input-id
         :upstream-artifact-source r5-document-upstream-artifact-path
         :requirements-coverage
         (r5-document-requirements-coverage minimal-artifact)
         :rejected-design-coverage
         [{:design :one_global_allocation_model
           :diagnostic "R5-PROVIDER" :status :rejected}
          {:design :raw_memory_safe_default
           :diagnostic "R5-RAW" :status :rejected}
          {:design :region_arena_escape
           :diagnostic "R5-LIFETIME" :status :rejected}
          {:design :gc_finalization_as_linear_cleanup
           :diagnostic "R5-LINEAR" :status :rejected}
          {:design :runtime_check_elision_without_proof
           :diagnostic "R5-PROOF" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r5-memory-runtime-conformance-record
          :provider_manifests :complete
          :profile_acceptance_rejection :covered
          :allocation_deallocation_lifetime_region_arena :complete
          :linear_resource_ledger_tests :complete
          :raw_memory_unsafe_wrapper_tests :covered
          :device_memory_transfer_sync_checks :complete
          :debug_allocation_traces_with_source_maps :complete
          :proof_backed_runtime_check_elision :complete
          :status :passed}
         :r5-diagnostic-stream diagnostic-stream
         :r5-document-results
         {:documents ["R5"]
          :task "P08-D116"
          :required-diagnostic-ids r5-document-diagnostic-ids
          :memory-runtime-input-status :complete
          :provider-status :complete
          :allocation-status :complete
          :lifetime-status :complete
          :linear-status :complete
          :raw-memory-status :complete
          :device-memory-status :complete
          :bounds-status :complete
          :proof-status :complete
          :debug-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r5-document-validate! source-path artifact-base)
        capability-proof (r5-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r5-document-file-artifact
  [path]
  (r5-document-source-artifact path (slurp path)))

(defn compiler-verification-source-overrides
  [module]
  (get-in module [:metadata :compiler :verification] {}))

(defn compiler-verification-fail!
  [id source-path subject extra]
  (fail! id
         (get compiler-verification-diagnostic-messages id
              "compiler diagnostics or verification validation failed")
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :compiler-verification
                 :stage (or (:stage subject) :compiler-verify)
                 :offending-diagnostic-id (:diagnostic-id subject)
                 :schema-field (:schema-field subject)
                 :artifact-id (:artifact-id subject)
                 :cache-key (:cache-key subject)
                 :plugin-id (:plugin-id subject)
                 :package-id (:package-id subject)
                 :compiler-api-version (:compiler-api-version subject)
                 :trust-level (:trust-level subject)
                 :pass-id (:pass-id subject)
                 :risk-class (:risk-class subject)
                 :required-evidence (:required-evidence subject)
                 :available-evidence (:available-evidence subject)
                 :affected-profiles (:affected-profiles subject)
                 :affected-targets (:affected-targets subject)
                 :remediation "Regenerate diagnostics, incremental records, plugin traces, and verification evidence with stable ids, provenance, redaction, policy, and release-gate proof."}
                extra)))

(defn compiler-verification-validate-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (let [[id subject-kind] (get compiler-verification-override-diagnostics
                                 fail-kind)]
      (when id
        (compiler-verification-fail!
         id source-path
         {:stage subject-kind
          :diagnostic-id (str "compiler-verification-invalid-"
                              (name fail-kind))
          :schema-field fail-kind
          :artifact-id (str "verification-artifact-" (name fail-kind))
          :cache-key (str "cache-key-" (name fail-kind))
          :plugin-id 'gravity.plugins.stage0/verifier
          :package-id 'gravity/compiler-verifier
          :compiler-api-version "stage0"
          :trust-level :sandboxed
          :pass-id subject-kind
          :risk-class :high
          :required-evidence #{:golden :translation-validation}
          :available-evidence #{}}
         {:missing-fields [fail-kind]})))))

(defn compiler-verification-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        module (parse-module source-path forms)
        overrides (compiler-verification-source-overrides module)
        _ (compiler-verification-validate-overrides! source-path overrides)
        optimization-artifact
        (optimization-lowering-source-artifact source-path source-text)
        input-id (str "sha256:" (sha256-hex (pr-str optimization-artifact)))
        diagnostic-schema
        {:artifact :gravity/diagnostic-schema
         :required-fields [:diagnostic-id :rule :severity :stage :primary
                           :related :origin-chain :profile :target :facts
                           :remediation :redactions]
         :status :complete}
        diagnostic-stream
        {:artifact :gravity/diagnostic-stream
         :stage :compiler-verify
         :input-artifact input-id
         :diagnostics
         [{:artifact :gravity/diagnostic
           :diagnostic-id "diag-c15-golden-stage0"
           :rule "C15-GOLDEN"
           :severity :hint
           :stage :compiler-verify
           :message-key :diagnostic.golden-fixture
           :primary {:span (source-span source-path 0)
                     :syntax-id "stage0-syntax-0"
                     :artifact input-id}
           :related [{:role :generated-by
                      :span (source-span source-path 0)
                      :artifact :compiler-verification-fixture}]
           :origin-chain []
           :profile (:profile module)
           :target (:target module)
           :facts {:fixture :compiler-verification
                   :rule :C15-GOLDEN}
           :remediation [{:kind :update-golden-fixture}]
           :redactions []}]
         :summary {:hint 1}
         :ordering-key [:rule :primary :artifact]
         :redaction-policy :public-safe
         :rendering-version "stage0-c15"
         :status :complete}
        incremental-graph
        {:artifact :gravity/incremental-dependency-graph
         :nodes [:source-unit :syntax-object-stream :macro-expansion-trace
                 :typed-core :mir-module :domain-ir
                 :optimization-lowering :diagnostics :target-artifact]
         :edges [{:from :source-unit :to :syntax-object-stream}
                 {:from :syntax-object-stream :to :typed-core}
                 {:from :typed-core :to :mir-module}
                 {:from :mir-module :to :domain-ir}
                 {:from :domain-ir :to :optimization-lowering}
                 {:from :optimization-lowering :to :target-artifact}
                 {:from :optimization-lowering :to :diagnostics}]
         :status :consistent}
        cache-key
        {:artifact :gravity/cache-key
         :stage :compiler-verify
         :source (str "sha256:" (sha256-hex source-text))
         :compiler "gravity-stage0-clojure"
         :profile (:profile module)
         :target (:target module)
         :pass-contract :compiler-verification
         :dependencies (str "sha256:" (sha256-hex (pr-str incremental-graph)))
         :build-effects :none
         :capabilities (:capabilities module)
         :policy :stage0-safe}
        cache-entry
        {:artifact :gravity/cache-entry
         :cache-key (str "sha256:" (sha256-hex (pr-str cache-key)))
         :artifact-id input-id
         :producer {:stage :compiler-verify
                    :pass-version "stage0-c18"}
         :inputs [input-id]
         :preserved-facts #{:source-spans :diagnostics :proofs}
         :invalidated-by #{:source-change :diagnostic-schema-change
                           :proof-policy-change :target-change}
         :diagnostics :gravity/diagnostic-stream
         :trust :local-build
         :revalidation :required-before-release}
        plugin-manifest
        {:artifact :gravity/compiler-plugin
         :plugin 'gravity.plugins.stage0/verifier
         :package {:name 'gravity/compiler-verifier :version "0.1.0"}
         :api-version "1"
         :compiler-compatibility {:min "0.1.0" :max-exclusive "0.2.0"}
         :trust :sandboxed
         :profile :meta
         :build-effects #{}
         :capabilities #{:compiler/ir-transform}
         :capability-scopes {:compiler/ir-transform #{:read-mir
                                                       :emit-diagnostics}}
         :passes [:diagnostic-golden-check]
         :domains []
         :facets []
         :emits #{:diagnostic-stream :verification-report}
         :conformance [:compiler-verification-fixtures]
         :status :accepted}
        risk-records
        [{:artifact :gravity/pass-risk
          :pass :reader
          :risk :critical
          :reason #{:trusted-semantic-base}
          :affected-profiles #{:core :hosted :native}
          :minimum-evidence #{:golden-fixtures :fuzz}
          :release-gate :required}
         {:artifact :gravity/pass-risk
          :pass :bounds-check-elide
          :risk :high
          :reason #{:removes-runtime-checks :depends-on-proof}
          :affected-profiles #{:hosted :native :gpu}
          :minimum-evidence #{:translation-validation
                              :proof-dominance-check}
          :release-gate :required}
         {:artifact :gravity/pass-risk
          :pass :target-lowering
          :risk :high
          :reason #{:emits-backend-artifacts}
          :affected-profiles #{:hosted :native}
          :minimum-evidence #{:backend-conformance
                              :differential-fixtures}
          :release-gate :required}]
        artifact
        {:kind :gravity/stage0-compiler-verification-artifact
         :document-set ["C15" "C16" "C17" "C18"]
         :pass {:name :compiler-diagnostics-and-verification
                :input :optimization-lowering-manifest
                :output :compiler-verification-report
                :requires [:diagnostic-schema :incremental-graph
                           :plugin-manifest :risk-classification
                           :translation-validation :trust-report]
                :preserves [:source-spans :generated-origins :profile
                            :target :diagnostics :proofs]
                :emits [:diagnostic-schema :diagnostic-stream
                        :diagnostic-catalog :golden-diagnostic-fixtures
                        :incremental-dependency-graph :cache-key-schema
                        :cache-entry-manifest :invalidation-trace
                        :artifact-reuse-report :revalidation-report
                        :plugin-manifest :plugin-execution-trace
                        :compiler-verification-plan :pass-risk-classification
                        :pass-evidence-records :translation-validation-log
                        :compiler-trust-report :release-gate-report]
                :rejects compiler-verification-diagnostic-ids}
         :source-overrides overrides
         :optimization-lowering-artifact-kind (:kind optimization-artifact)
         :optimization-lowering-artifact-hash input-id
         :diagnostic-schema diagnostic-schema
         :diagnostic-stream diagnostic-stream
         :diagnostic-catalog
         {:artifact :gravity/diagnostic-catalog
          :rules compiler-verification-diagnostic-ids
          :status :complete}
         :related-span-map
         {:artifact :gravity/related-span-map
          :status :complete
          :entries (get-in diagnostic-stream [:diagnostics 0 :related])}
         :remediation-and-quick-fix-records
         [{:rule "C15-GOLDEN"
           :remediation :update-golden-fixture
           :quick-fix :regenerate-fixture
           :status :available}]
         :redaction-report
         {:artifact :gravity/diagnostic-redaction-report
          :status :passed
          :redacted-values []
          :public-safe? true}
         :rendering-records
         [{:renderer :cli
           :source :gravity/diagnostic-stream
           :status :complete}
          {:renderer :ide
           :source :gravity/diagnostic-stream
           :status :complete}
          {:renderer :ci
           :source :gravity/diagnostic-stream
           :status :complete}]
         :golden-diagnostic-fixtures
         [{:fixture :compiler-verification-golden
           :rules ["C15-GOLDEN"]
           :status :matched}]
         :incremental-dependency-graph incremental-graph
         :cache-key-schema
         {:artifact :gravity/cache-key-schema
          :required-fields [:stage :source :compiler :profile :target
                            :pass-contract :dependencies :build-effects
                            :capabilities :policy]
          :status :complete}
         :cache-entry-manifest cache-entry
         :invalidation-trace
         [{:invalidating-input :diagnostic-schema-change
           :affected-nodes [:diagnostics :target-artifact]
           :revalidation-stages [:compiler-verify]
           :status :recorded}]
         :artifact-reuse-report
         {:artifact :gravity/artifact-reuse-report
          :status :revalidated
          :reuse :allowed-after-validation}
         :revalidation-report
         {:artifact :gravity/revalidation-report
          :status :passed
          :checks [:cache-key :schema-version :producer-pass
                   :proof-freshness :profile-target :diagnostic-schema]}
         :stale-proof-rejection-report
         {:artifact :gravity/stale-proof-rejection-report
          :status :covered
          :diagnostic "C16-PROOF"}
         :plugin-manifest plugin-manifest
         :api-compatibility-report
         {:artifact :gravity/plugin-api-compatibility
          :plugin (:plugin plugin-manifest)
          :status :compatible}
         :sandbox-grant
         {:artifact :gravity/plugin-sandbox-grant
          :plugin (:plugin plugin-manifest)
          :status :sandboxed
          :capabilities (:capabilities plugin-manifest)}
         :plugin-pass-registration-records
         [{:plugin (:plugin plugin-manifest)
           :pass :diagnostic-golden-check
           :contract :accepted
           :status :registered}]
         :plugin-execution-trace
         {:artifact :gravity/plugin-execution
          :plugin (:plugin plugin-manifest)
          :pass :diagnostic-golden-check
          :input input-id
          :output :gravity/diagnostic-stream
          :grants :gravity/plugin-sandbox-grant
          :build-effects []
          :diagnostics []
          :verifier-result :passed}
         :plugin-conformance-results
         {:artifact :gravity/plugin-conformance-results
          :status :passed
          :fixtures [:compiler-verification-fixtures]}
         :compiler-verification-plan
         {:artifact :gravity/compiler-verification-plan
          :status :complete
          :evidence-policy :risk-based}
         :pass-risk-classification risk-records
         :pass-evidence-records
         (mapv (fn [risk]
                 {:pass (:pass risk)
                  :risk (:risk risk)
                  :evidence (:minimum-evidence risk)
                  :status :present})
               risk-records)
         :translation-validation-logs
         [{:artifact :gravity/translation-validation
           :pass :bounds-check-elide
           :input input-id
           :output input-id
           :changed-functions [:stage0-main]
           :properties #{:same-observable-result :same-effects
                         :same-safety-outcomes}
           :method :symbolic-plus-fixtures
           :proofs [:proof/c13-bounds-check-elision]
           :counterexamples []
           :result :accepted}]
         :proof-or-certificate-references
         [{:proof :proof/c13-bounds-check-elision
           :status :accepted}
          {:certificate :cert/stage0-diagnostic-golden
           :status :accepted}]
         :differential-and-property-fixture-results
         {:artifact :gravity/compiler-fixture-results
          :status :passed
          :families [:front-end :optimization :backend]}
         :compiler-trust-report
         {:artifact :gravity/compiler-trust-report
          :compiler "gravity-stage0-clojure"
          :passes (mapv #(select-keys % [:pass :risk :minimum-evidence])
                        risk-records)
          :profiles {:hosted {:required-evidence :high
                              :blocked-passes []}}
          :known-gaps []
          :status :complete}
         :release-gate-report
         {:artifact :gravity/release-gate-report
          :status :passed
          :checks [:verifiers :critical-failures :high-risk-evidence
                   :target-lowering-conformance :stale-proof-rejection
                   :diagnostic-goldens]}
         :counterexample-artifacts
         [{:artifact :gravity/counterexample
           :status :none-produced
           :regression-fixture-created? false}]
         :diagnostics []}
        capability-proof
        {:diagnostic-schema-complete?
         (= :complete (get-in artifact [:diagnostic-schema :status]))
         :diagnostic-stream-deterministic?
         (= [:rule :primary :artifact]
            (get-in artifact [:diagnostic-stream :ordering-key]))
         :redaction-public-safe?
         (true? (get-in artifact [:redaction-report :public-safe?]))
         :golden-fixtures-matched?
         (every? #(= :matched (:status %))
                 (:golden-diagnostic-fixtures artifact))
         :incremental-records-complete?
         (and (= :consistent
                 (get-in artifact [:incremental-dependency-graph :status]))
              (= :complete (get-in artifact [:cache-key-schema :status]))
              (= :gravity/cache-entry
                 (get-in artifact [:cache-entry-manifest :artifact]))
              (= :passed (get-in artifact [:revalidation-report :status])))
         :plugin-policy-enforced?
         (and (= :accepted (get-in artifact [:plugin-manifest :status]))
              (= :compatible
                 (get-in artifact [:api-compatibility-report :status]))
              (= :sandboxed (get-in artifact [:sandbox-grant :status]))
              (= :passed
                 (get-in artifact [:plugin-conformance-results :status])))
         :verification-evidence-present?
         (and (every? #(= :present (:status %))
                      (:pass-evidence-records artifact))
              (every? #(= :accepted (:result %))
                      (:translation-validation-logs artifact)))
         :trust-report-complete?
         (= :complete (get-in artifact [:compiler-trust-report :status]))
         :release-gate-passed?
         (= :passed (get-in artifact [:release-gate-report :status]))
         :status :complete}
        conformance {:documents ["C15" "C16" "C17" "C18"]
                     :task "P06-T06"
                     :required-diagnostic-ids
                     compiler-verification-diagnostic-ids
                     :diagnostic-status :complete
                     :incremental-status :complete
                     :plugin-status :complete
                     :verification-status :complete
                     :status :complete}]
    (assoc artifact
           :capability-based-proof capability-proof
           :compiler-verification-results conformance)))

(defn defn-form?
  [form]
  (and (seq? form) (= 'defn (first form))))

(defn def-main-form?
  [form]
  (and (seq? form)
       (= 'def (first form))
       (= 'main (second form))
       (seq? (nth form 2 nil))
       (= 'fn (first (nth form 2)))))

(defn def-function-form?
  [form]
  (and (seq? form)
       (= 'def (first form))
       (symbol? (second form))
       (seq? (nth form 2 nil))
       (= 'fn (first (nth form 2)))))

(def stage0-special-forms
  '#{println do if let quote host-reflect})

(def stage0-builtin-functions
  '#{+ - * / = < > <= >= str pr-str hash-map vector list conj assoc get
     first second rest count})

