(defn eval-do
  [module env forms]
  (reduce (fn [_ form] (eval-expr module env form)) nil forms))

(defn bind-let
  [module env bindings]
  (when-not (and (vector? bindings) (even? (count bindings)))
    (fail! "L2-LET-BINDING"
           "let requires an even binding vector"
           {:source-span {:source (:source-path module)}
            :bindings bindings
            :remediation "Use pairs of local names and expressions in let."}))
  (loop [env env
         pairs (partition 2 bindings)]
    (if-let [[name expr] (first pairs)]
      (do
        (when-not (symbol? name)
          (fail! "L2-LET-BINDING"
                 "let binding name must be a symbol"
                 {:source-span {:source (:source-path module)}
                  :binding name
                  :remediation "Bind symbols in stage0 let forms."}))
        (recur (assoc env name (eval-expr module env expr)) (rest pairs)))
      env)))

(defn function-definition-form
  [source-path form]
  (cond
    (defn-form? form)
    (let [[_ name params & body] form]
      {:name name :params params :body body :definition-form :defn})

    (def-function-form? form)
    (let [[_ params & body] (nth form 2)]
      {:name (second form) :params params :body body :definition-form :def-fn})

    :else nil))

(defn validate-function-definition!
  [source-path {:keys [name params body]}]
  (when-not (symbol? name)
    (fail! "L2-FUNCTION-PARAMS"
           "stage0 function name must be a symbol"
           {:source-span {:source source-path}
            :function name
            :remediation "Define functions with symbolic names."}))
  (when-not (and (vector? params) (every? symbol? params))
    (fail! "L2-FUNCTION-PARAMS"
           "stage0 function parameters must be a vector of symbols"
           {:source-span {:source source-path}
            :function name
            :params params
            :remediation "Use a fixed arity parameter vector such as [x y]."}))
  (when-not (seq body)
    (fail! "L2-FUNCTION-PARAMS"
           "stage0 function body cannot be empty"
           {:source-span {:source source-path}
            :function name
            :remediation "Add at least one body form."})))

(defn stage0-function-table
  [module]
  (let [source-path (:source-path module)
        definitions (keep #(function-definition-form source-path %)
                          (:forms module))
        duplicate (first (for [[name n] (frequencies (map :name definitions))
                               :when (> n 1)]
                           name))]
    (when duplicate
      (fail! "L2-DUPLICATE-FUNCTION"
             "stage0 executable has duplicate function definitions"
             {:source-span {:source source-path}
              :function duplicate
              :remediation "Keep one definition per stage0 function name."}))
    (into {}
          (map (fn [definition]
                 (validate-function-definition! source-path definition)
                 [(:name definition)
                  (assoc definition
                         :arity (count (:params definition))
                         :body-form-count (count (:body definition)))]))
          definitions)))

(defn fail-call-arity!
  [id module callee args expected]
  (fail! id
         (case id
           "L2-FUNCTION-ARITY" "stage0 function call has the wrong arity"
           "L2-BUILTIN-ARITY" "stage0 builtin call has the wrong arity"
           "stage0 call has the wrong arity")
         {:source-span {:source (:source-path module)}
          :function callee
          :expected-arity expected
          :actual-arity (count args)
          :remediation "Call the function with the arity supported by the stage0 hosted subset."}))

(defn assert-min-arity!
  [module callee args n]
  (when (< (count args) n)
    (fail-call-arity! "L2-BUILTIN-ARITY" module callee args
                      (str "at least " n))))

(defn assert-exact-arity!
  [module callee args n]
  (when-not (= n (count args))
    (fail-call-arity! "L2-BUILTIN-ARITY" module callee args n)))

(defn assert-between-arity!
  [module callee args min-n max-n]
  (when-not (<= min-n (count args) max-n)
    (fail-call-arity! "L2-BUILTIN-ARITY" module callee args
                      (str min-n " to " max-n))))

(defn assert-even-arity!
  [module callee args]
  (when (odd? (count args))
    (fail-call-arity! "L2-BUILTIN-ARITY" module callee args
                      "an even number of arguments")))

;; This printer is intentionally a Clojure-seed compatibility boundary.  It
;; prevents host reader/printer implementation details (notably BigInt's `N`
;; suffix and ambient print vars) from becoming Gravity output semantics, but
;; it does not claim that readable printing has moved into Gravity source.
(def p15-s23-seed-readable-printer-limits
  {:maximum-arguments 256
   :maximum-nodes 4096
   :maximum-depth 96
   :maximum-collection-width 512
   :maximum-integer-bits 4096
   :maximum-scalar-bytes 32768
   :maximum-output-bytes 262144})

(def p15-s23-seed-readable-printer-scalar-class-kinds
  {java.lang.Boolean :boolean
   java.lang.Byte :integer
   java.lang.Short :integer
   java.lang.Integer :integer
   java.lang.Long :integer
   java.math.BigInteger :integer
   clojure.lang.BigInt :integer
   clojure.lang.Ratio :ratio
   java.lang.Double :floating
   java.lang.String :string
   java.lang.Character :character
   clojure.lang.Keyword :keyword
   clojure.lang.Symbol :symbol
   java.util.Date :instant
   java.util.UUID :uuid})

(def p15-s23-seed-readable-printer-collection-class-kinds
  {clojure.lang.PersistentVector :vector
   clojure.lang.MapEntry :vector
   clojure.lang.PersistentList :list
   clojure.lang.PersistentList$EmptyList :list
   clojure.lang.PersistentArrayMap :map
   clojure.lang.PersistentHashMap :map
   clojure.lang.PersistentHashSet :set})

(def ^:dynamic ^:private *p15-s23-seed-readable-owned-failures* nil)

(defn p15-s23-seed-readable-printer-fail!
  [source-path reason data]
  (let [failure
        (diagnostic
         "L2-BUILTIN-ERROR"
         "bounded Clojure-seed readable printer rejected a value"
         (merge
          {:source-span {:source (or source-path "<unknown-source>")}
           :function 'pr-str
           :reason reason
           :printer-boundary :clojure-seed-compatibility
           :clojure-seed-boundary? true
           :self-hosted? false
           :result-committed? false
           :output-committed? false
           :remediation
           "Keep pr-str inputs inside the bounded Gravity value algebra until readable printing is implemented and authenticated in Gravity source."}
          data))]
    (when *p15-s23-seed-readable-owned-failures*
      (.put ^java.util.IdentityHashMap
            *p15-s23-seed-readable-owned-failures*
            failure Boolean/TRUE))
    (throw failure)))

(defn p15-s23-seed-readable-bounded-utf8-observation
  [^String text maximum-bytes]
  (loop [index 0
         bytes 0]
    (if (>= index (.length text))
      {:status :valid :bytes bytes}
      (let [unit (.charAt text index)
            high? (Character/isHighSurrogate unit)
            low? (Character/isLowSurrogate unit)]
        (cond
          (and high?
               (or (>= (inc index) (.length text))
                   (not (Character/isLowSurrogate
                         (.charAt text (inc index))))))
          {:status :invalid-unicode :bytes bytes}

          low?
          {:status :invalid-unicode :bytes bytes}

          :else
          (let [codepoint
                (if high?
                  (Character/toCodePoint unit (.charAt text (inc index)))
                  (int unit))
                width (cond
                        (<= codepoint 0x7f) 1
                        (<= codepoint 0x7ff) 2
                        (<= codepoint 0xffff) 3
                        :else 4)
                next-bytes (+ bytes width)]
            (if (> next-bytes maximum-bytes)
              {:status :byte-limit :bytes next-bytes}
              (recur (+ index (if high? 2 1)) next-bytes))))))))

(defn p15-s23-seed-readable-utf8-bytes
  [^String text]
  (alength (.getBytes text java.nio.charset.StandardCharsets/UTF_8)))

(defn p15-s23-seed-readable-name-safe?
  [^String text _symbol-name?]
  (not-any?
   (fn [unit]
     (or (Character/isWhitespace ^Character unit)
         (Character/isISOControl ^Character unit)
         (contains? #{\( \) \[ \] \{ \} \" \; \, \\ \' \` \~ \^ \@ \#}
                    unit)))
   text))

(defn p15-s23-seed-readable-named-scalar-text
  [kind value]
  (str (when (= :keyword kind) ":")
       (when-let [namespace-text (namespace value)]
         (str namespace-text "/"))
       (name value)))

(defn p15-s23-seed-readable-value-kind
  [source-path value]
  (let [value-class (when (some? value) (class value))
        scalar-kind
        (get p15-s23-seed-readable-printer-scalar-class-kinds value-class)
        collection-kind
        (get p15-s23-seed-readable-printer-collection-class-kinds
             value-class)]
    (cond
      (nil? value) :nil
      scalar-kind scalar-kind
      collection-kind collection-kind
      :else
      (p15-s23-seed-readable-printer-fail!
       source-path :unsupported-value-carrier
       {:observed-kind
        (cond
          (number? value) :unsupported-number
          (map? value) :unsupported-map
          (set? value) :unsupported-set
          (sequential? value) :unsupported-sequence
          (.isArray (class value)) :unsupported-array
          :else :unsupported-host-object)}))))

(defn p15-s23-seed-readable-bounded-text-bytes!
  [source-path scalar-kind text]
  (let [maximum-scalar-bytes
        (:maximum-scalar-bytes p15-s23-seed-readable-printer-limits)
        observation
        (p15-s23-seed-readable-bounded-utf8-observation
         text maximum-scalar-bytes)]
    (case (:status observation)
      :valid (:bytes observation)
      :invalid-unicode
      (p15-s23-seed-readable-printer-fail!
       source-path :invalid-unicode-scalar
       {:scalar-kind scalar-kind})
      :byte-limit
      (p15-s23-seed-readable-printer-fail!
       source-path :scalar-byte-limit
       {:scalar-kind scalar-kind
        :observed-scalar-bytes-at-least (:bytes observation)
        :maximum-scalar-bytes maximum-scalar-bytes}))))

(defn p15-s23-seed-readable-integer-bits
  [value]
  (.bitLength (.abs ^java.math.BigInteger (biginteger value))))

(defn p15-s23-seed-readable-integer-size!
  [source-path value component]
  (let [maximum-integer-bits
        (:maximum-integer-bits p15-s23-seed-readable-printer-limits)
        bits (p15-s23-seed-readable-integer-bits value)]
    (when (> bits maximum-integer-bits)
      (p15-s23-seed-readable-printer-fail!
       source-path :integer-magnitude-limit
       (cond-> {:observed-integer-bits bits
                :maximum-integer-bits maximum-integer-bits}
         component (assoc :integer-component component))))
    (+ 2 (quot (+ bits 2) 3))))

(defn p15-s23-seed-readable-ratio-components!
  [source-path value]
  (let [numerator (.numerator ^clojure.lang.Ratio value)
        denominator (.denominator ^clojure.lang.Ratio value)]
    (when-not (and (identical? java.math.BigInteger (class numerator))
                   (identical? java.math.BigInteger (class denominator)))
      (p15-s23-seed-readable-printer-fail!
       source-path :invalid-ratio-component-carrier {}))
    (let [numerator-size
          (p15-s23-seed-readable-integer-size!
           source-path numerator :numerator)
          denominator-size
          (p15-s23-seed-readable-integer-size!
           source-path denominator :denominator)]
    (when-not (and (not (zero? (.signum ^java.math.BigInteger numerator)))
                   (pos? (.compareTo ^java.math.BigInteger denominator
                                     java.math.BigInteger/ONE))
                   (= java.math.BigInteger/ONE
                      (.gcd (.abs ^java.math.BigInteger numerator)
                            ^java.math.BigInteger denominator)))
      (p15-s23-seed-readable-printer-fail!
       source-path :noncanonical-ratio {}))
      [numerator denominator numerator-size denominator-size])))

(defn p15-s23-seed-readable-floating-text
  [source-path value]
  (let [number (double value)]
    (when-not (Double/isFinite number)
      (p15-s23-seed-readable-printer-fail!
       source-path :non-finite-floating-point
       {:scalar-kind :floating}))
    (Double/toString number)))

(declare p15-s23-seed-readable-instant-text
         p15-s23-seed-readable-uuid-text)

(defn p15-s23-seed-readable-scalar-bytes!
  [source-path kind value]
  (case kind
      :nil 1
      :boolean 5
      :integer
      (p15-s23-seed-readable-integer-size! source-path value nil)
      :ratio
      (let [[_ _ numerator-size denominator-size]
            (p15-s23-seed-readable-ratio-components! source-path value)]
        (+ 1 numerator-size denominator-size))
      :floating
      (p15-s23-seed-readable-bounded-text-bytes!
       source-path kind (p15-s23-seed-readable-floating-text source-path value))
      :character
      (let [unit (char value)]
        (when (Character/isSurrogate unit)
          (p15-s23-seed-readable-printer-fail!
           source-path :invalid-unicode-scalar
           {:scalar-kind :character}))
        10)
      :string
      (p15-s23-seed-readable-bounded-text-bytes!
       source-path kind value)
      :instant
      (p15-s23-seed-readable-bounded-text-bytes!
       source-path kind
       (p15-s23-seed-readable-instant-text source-path value))
      :uuid
      (p15-s23-seed-readable-bounded-text-bytes!
       source-path kind (p15-s23-seed-readable-uuid-text value))
      :keyword
      (let [namespace-text (namespace value)
            name-text (name value)
            symbol-name? false
            namespace-bytes
            (if namespace-text
              (p15-s23-seed-readable-bounded-text-bytes!
               source-path kind namespace-text)
              0)
            name-bytes
            (p15-s23-seed-readable-bounded-text-bytes!
             source-path kind name-text)
            named-bytes (+ 1 (if namespace-text 1 0)
                           namespace-bytes name-bytes)
            maximum-scalar-bytes
            (:maximum-scalar-bytes p15-s23-seed-readable-printer-limits)
            named-size-check
            (when (> named-bytes maximum-scalar-bytes)
              (p15-s23-seed-readable-printer-fail!
               source-path :scalar-byte-limit
               {:scalar-kind kind
                :observed-scalar-bytes named-bytes
                :maximum-scalar-bytes maximum-scalar-bytes}))
            rendered
            (p15-s23-seed-readable-named-scalar-text kind value)]
        (when-not (and (seq rendered)
                       (p15-s23-seed-readable-name-safe?
                        name-text symbol-name?)
                       (or (nil? namespace-text)
                           (p15-s23-seed-readable-name-safe?
                            namespace-text false))
                       (= :keyword (stage1-reader-token-kind rendered))
                       (= value (keyword (subs rendered 1))))
          (p15-s23-seed-readable-printer-fail!
           source-path :unreadable-name
           {:scalar-kind kind}))
        named-bytes)
      :symbol
      (let [namespace-text (namespace value)
            name-text (name value)
            symbol-name? true
            namespace-bytes
            (if namespace-text
              (p15-s23-seed-readable-bounded-text-bytes!
               source-path kind namespace-text)
              0)
            name-bytes
            (p15-s23-seed-readable-bounded-text-bytes!
             source-path kind name-text)
            named-bytes (+ (if namespace-text 1 0)
                           namespace-bytes name-bytes)
            maximum-scalar-bytes
            (:maximum-scalar-bytes p15-s23-seed-readable-printer-limits)
            named-size-check
            (when (> named-bytes maximum-scalar-bytes)
              (p15-s23-seed-readable-printer-fail!
               source-path :scalar-byte-limit
               {:scalar-kind kind
                :observed-scalar-bytes named-bytes
                :maximum-scalar-bytes maximum-scalar-bytes}))
            rendered
            (p15-s23-seed-readable-named-scalar-text kind value)]
        (when-not (and (seq rendered)
                       (p15-s23-seed-readable-name-safe?
                        name-text symbol-name?)
                       (or (nil? namespace-text)
                           (p15-s23-seed-readable-name-safe?
                            namespace-text true))
                       (= :symbol (stage1-reader-token-kind rendered))
                       (= value (symbol rendered)))
          (p15-s23-seed-readable-printer-fail!
           source-path :unreadable-name
           {:scalar-kind kind}))
        named-bytes)
      0))

(defn p15-s23-seed-readable-snapshot-scalar!
  [source-path kind value]
  (case kind
    :instant (java.util.Date. (.getTime ^java.util.Date value))
    :integer
    (if (identical? clojure.lang.BigInt (class value))
      (let [big-part (.-bipart ^clojure.lang.BigInt value)]
        (when-not (or (nil? big-part)
                      (identical? java.math.BigInteger (class big-part)))
          (p15-s23-seed-readable-printer-fail!
           source-path :invalid-bigint-component-carrier {}))
        (if big-part
          (clojure.lang.BigInt/fromBigInteger big-part)
          (clojure.lang.BigInt/fromLong
           (.-lpart ^clojure.lang.BigInt value))))
      value)
    :ratio
    (let [[numerator denominator _ _]
          (p15-s23-seed-readable-ratio-components! source-path value)]
      (clojure.lang.Ratio. numerator denominator))
    value))

(defn p15-s23-seed-readable-preflight!
  [source-path args]
  (let [{:keys [maximum-arguments maximum-nodes maximum-depth
                maximum-collection-width maximum-scalar-bytes
                maximum-output-bytes]}
        p15-s23-seed-readable-printer-limits
        active (java.util.IdentityHashMap.)
        stats (volatile! {:node-count 0
                          :scalar-bytes 0
                          :maximum-depth 0})]
    (when-not (identical? clojure.lang.PersistentVector (class args))
      (p15-s23-seed-readable-printer-fail!
       source-path :unsupported-argument-carrier
       {:expected-argument-carrier :persistent-vector}))
    (when (> (count args) maximum-arguments)
      (p15-s23-seed-readable-printer-fail!
       source-path :argument-count-limit
       {:observed-arguments (count args)
        :maximum-arguments maximum-arguments}))
    (letfn [(fail-width! [observed]
              (p15-s23-seed-readable-printer-fail!
               source-path :collection-width-limit
               {:observed-width observed
                :maximum-collection-width maximum-collection-width}))
            (record-node! [depth scalar-bytes]
              (let [next-stats
                    (vswap! stats
                            (fn [{:keys [node-count] :as current}]
                              (-> current
                                  (assoc :node-count (inc node-count))
                                  (update :scalar-bytes + scalar-bytes)
                                  (update :maximum-depth max depth))))
                    node-count (:node-count next-stats)
                    total-scalar-bytes (:scalar-bytes next-stats)]
                (when (> node-count maximum-nodes)
                  (p15-s23-seed-readable-printer-fail!
                   source-path :node-count-limit
                   {:observed-nodes node-count
                    :maximum-nodes maximum-nodes}))
                (when (> depth maximum-depth)
                  (p15-s23-seed-readable-printer-fail!
                   source-path :depth-limit
                   {:observed-depth depth
                    :maximum-depth maximum-depth}))
                (when (> total-scalar-bytes maximum-scalar-bytes)
                  (p15-s23-seed-readable-printer-fail!
                   source-path :scalar-byte-limit
                   {:observed-scalar-bytes total-scalar-bytes
                    :maximum-scalar-bytes maximum-scalar-bytes}))
                (when (> (+ (* total-scalar-bytes 6) (* node-count 4))
                         maximum-output-bytes)
                  (p15-s23-seed-readable-printer-fail!
                   source-path :prospective-output-byte-limit
                   {:maximum-output-bytes maximum-output-bytes}))))
            (snapshot-value! [value depth]
              (let [kind (p15-s23-seed-readable-value-kind source-path value)
                    collection? (contains? #{:vector :list :map :set} kind)]
                (record-node! depth 0)
                (if-not collection?
                  (let [snapshot
                        (p15-s23-seed-readable-snapshot-scalar!
                         source-path kind value)
                        scalar-bytes
                        (p15-s23-seed-readable-scalar-bytes!
                         source-path kind snapshot)]
                    (vswap! stats update :scalar-bytes + scalar-bytes)
                    (let [{:keys [node-count scalar-bytes]} @stats]
                      (when (> scalar-bytes maximum-scalar-bytes)
                        (p15-s23-seed-readable-printer-fail!
                         source-path :scalar-byte-limit
                         {:observed-scalar-bytes scalar-bytes
                          :maximum-scalar-bytes maximum-scalar-bytes}))
                      (when (> (+ (* scalar-bytes 6) (* node-count 4))
                               maximum-output-bytes)
                        (p15-s23-seed-readable-printer-fail!
                         source-path :prospective-output-byte-limit
                         {:maximum-output-bytes maximum-output-bytes})))
                    snapshot)
                  (do
                    (when (.containsKey active value)
                      (p15-s23-seed-readable-printer-fail!
                       source-path :cyclic-value
                       {:observed-depth depth}))
                    (.put active value Boolean/TRUE)
                    (try
                      (case kind
                        :vector
                        (let [width (count value)]
                          (when (> width maximum-collection-width)
                            (fail-width! width))
                          (loop [index 0
                                 snapshot []]
                            (if (= index width)
                              snapshot
                              (recur
                               (inc index)
                               (conj snapshot
                                     (snapshot-value!
                                      (nth value index) (inc depth)))))))

                        :list
                        (loop [cursor (seq value)
                               width 0
                               snapshot []]
                          (if (nil? cursor)
                            (apply list snapshot)
                            (do
                              (when (>= width maximum-collection-width)
                                (fail-width! (inc width)))
                              (when-not
                               (or (identical? clojure.lang.PersistentList
                                               (class cursor))
                                   (identical?
                                    clojure.lang.PersistentList$EmptyList
                                    (class cursor)))
                                (p15-s23-seed-readable-printer-fail!
                                 source-path :unsupported-list-tail-carrier {}))
                              (recur
                               (next cursor)
                               (inc width)
                               (conj snapshot
                                     (snapshot-value!
                                      (first cursor) (inc depth)))))))

                        :set
                        (loop [cursor (seq value)
                               width 0
                               snapshot []]
                          (if (nil? cursor)
                            (let [result (into #{} snapshot)]
                              (when-not (= (count result) width)
                                (p15-s23-seed-readable-printer-fail!
                                 source-path :snapshot-collision {}))
                              result)
                            (do
                              (when (>= width maximum-collection-width)
                                (fail-width! (inc width)))
                              (recur
                               (next cursor)
                               (inc width)
                               (conj snapshot
                                     (snapshot-value!
                                      (first cursor) (inc depth)))))))

                        :map
                        (loop [cursor (seq value)
                               width 0
                               snapshot []]
                          (if (nil? cursor)
                            (let [result (into {} snapshot)]
                              (when-not (= (count result) width)
                                (p15-s23-seed-readable-printer-fail!
                                 source-path :snapshot-collision {}))
                              result)
                            (do
                              (when (>= width maximum-collection-width)
                                (fail-width! (inc width)))
                              (let [entry (first cursor)]
                                (when-not
                                 (identical? clojure.lang.MapEntry
                                             (class entry))
                                  (p15-s23-seed-readable-printer-fail!
                                   source-path :unsupported-map-entry-carrier
                                   {}))
                                (recur
                                 (next cursor)
                                 (inc width)
                                 (conj snapshot
                                       [(snapshot-value!
                                         (key entry) (inc depth))
                                        (snapshot-value!
                                         (val entry) (inc depth))])))))))
                      (finally
                        (.remove active value)))))))]
      (let [snapshot-args
            (loop [index 0 snapshot []]
              (if (= index (count args))
                snapshot
                (recur (inc index)
                       (conj snapshot
                             (snapshot-value! (nth args index) 0)))))]
        (assoc @stats
               :snapshot-args snapshot-args
               :printer-boundary :clojure-seed-compatibility)))))

(defn p15-s23-seed-readable-integer-text
  [value]
  (let [integer (biginteger value)
        negative? (neg? (.signum integer))
        magnitude (.abs integer)
        ten (java.math.BigInteger/valueOf 10)]
    (if (zero? (.signum magnitude))
      "0"
      (loop [remaining magnitude digits []]
        (if (zero? (.signum remaining))
          (str (when negative? "-") (apply str (reverse digits)))
          (let [digit (.intValue (.remainder remaining ten))]
            (recur (.divide remaining ten)
                   (conj digits (.charAt "0123456789" digit)))))))))

(defn p15-s23-seed-readable-append-hex4!
  [^StringBuilder builder code]
  (let [digits "0123456789abcdef"]
    (doseq [shift [12 8 4 0]]
      (.append builder
               (.charAt digits (bit-and 15 (bit-shift-right code shift))))))
  builder)

(defn p15-s23-seed-readable-append-fixed-decimal!
  [^StringBuilder builder value width]
  (let [text (Long/toString (long value))]
    (dotimes [_ (- width (.length text))]
      (.append builder \0))
    (.append builder text))
  builder)

(defn p15-s23-seed-readable-instant-text
  [source-path value]
  (let [calendar
        (doto (java.util.GregorianCalendar.
               (java.util.TimeZone/getTimeZone "GMT")
               java.util.Locale/ROOT)
          (.setGregorianChange (java.util.Date. -12219292800000))
          (.setLenient false)
          (.setTime ^java.util.Date value))
        era (.get calendar java.util.Calendar/ERA)
        calendar-year (.get calendar java.util.Calendar/YEAR)
        year (cond
               (and (= era java.util.GregorianCalendar/BC)
                    (= calendar-year 1))
               0

               (= era java.util.GregorianCalendar/AD)
               calendar-year

               :else nil)]
    (when-not (and (some? year) (<= 0 year 9999))
      (p15-s23-seed-readable-printer-fail!
       source-path :instant-range-limit
       {:minimum-year 0 :maximum-year 9999}))
    (let [builder (doto (StringBuilder.) (.append "#inst \""))]
      (p15-s23-seed-readable-append-fixed-decimal! builder year 4)
      (.append builder \-)
      (p15-s23-seed-readable-append-fixed-decimal!
       builder (inc (.get calendar java.util.Calendar/MONTH)) 2)
      (.append builder \-)
      (p15-s23-seed-readable-append-fixed-decimal!
       builder (.get calendar java.util.Calendar/DAY_OF_MONTH) 2)
      (.append builder \T)
      (p15-s23-seed-readable-append-fixed-decimal!
       builder (.get calendar java.util.Calendar/HOUR_OF_DAY) 2)
      (.append builder \:)
      (p15-s23-seed-readable-append-fixed-decimal!
       builder (.get calendar java.util.Calendar/MINUTE) 2)
      (.append builder \:)
      (p15-s23-seed-readable-append-fixed-decimal!
       builder (.get calendar java.util.Calendar/SECOND) 2)
      (.append builder \.)
      (p15-s23-seed-readable-append-fixed-decimal!
       builder (.get calendar java.util.Calendar/MILLISECOND) 3)
      (.append builder "-00:00\"")
      (.toString builder))))

(defn p15-s23-seed-readable-append-long-hex-range!
  [^StringBuilder builder value high-shift low-shift]
  (let [digits "0123456789abcdef"]
    (doseq [shift (range high-shift (dec low-shift) -4)]
      (.append builder
               (.charAt digits
                        (int (bit-and 15
                                      (bit-shift-right (long value)
                                                       shift)))))))
  builder)

(defn p15-s23-seed-readable-uuid-text
  [value]
  (let [most (.getMostSignificantBits ^java.util.UUID value)
        least (.getLeastSignificantBits ^java.util.UUID value)
        builder (doto (StringBuilder.) (.append "#uuid \""))]
    (p15-s23-seed-readable-append-long-hex-range! builder most 60 32)
    (.append builder \-)
    (p15-s23-seed-readable-append-long-hex-range! builder most 28 16)
    (.append builder \-)
    (p15-s23-seed-readable-append-long-hex-range! builder most 12 0)
    (.append builder \-)
    (p15-s23-seed-readable-append-long-hex-range! builder least 60 48)
    (.append builder \-)
    (p15-s23-seed-readable-append-long-hex-range! builder least 44 0)
    (.append builder \" )
    (.toString builder)))

(defn p15-s23-seed-readable-string-text
  [^String value]
  (let [builder (StringBuilder.)]
    (.append builder \" )
    (loop [index 0]
      (when (< index (.length value))
        (let [codepoint (.codePointAt value index)]
          (case codepoint
            8 (.append builder "\\b")
            9 (.append builder "\\t")
            10 (.append builder "\\n")
            12 (.append builder "\\f")
            13 (.append builder "\\r")
            34 (.append builder "\\\"")
            92 (.append builder "\\\\")
            (if (or (< codepoint 32) (= codepoint 127))
              (do
                (.append builder "\\u")
                (p15-s23-seed-readable-append-hex4! builder codepoint))
              (.appendCodePoint builder codepoint)))
          (recur (+ index (Character/charCount codepoint))))))
    (.append builder \" )
    (.toString builder)))

(defn p15-s23-seed-readable-character-text
  [value]
  (case (int (char value))
    8 "\\backspace"
    9 "\\tab"
    10 "\\newline"
    12 "\\formfeed"
    13 "\\return"
    32 "\\space"
    (let [unit (char value)]
      (if (or (Character/isWhitespace unit)
              (Character/isISOControl unit)
              (contains? #{\, \; \" \' \` \~ \^ \@ \\ \#} unit))
        (let [builder (doto (StringBuilder.) (.append "\\u"))]
          (p15-s23-seed-readable-append-hex4! builder (int unit))
          (.toString builder))
        (str "\\" unit)))))

(defn p15-s23-seed-readable-compare-utf8
  [^String left ^String right]
  (let [left-bytes (.getBytes left java.nio.charset.StandardCharsets/UTF_8)
        right-bytes (.getBytes right java.nio.charset.StandardCharsets/UTF_8)
        common (min (alength left-bytes) (alength right-bytes))]
    (loop [index 0]
      (if (= index common)
        (compare (alength left-bytes) (alength right-bytes))
        (let [left-byte (bit-and 0xff (aget left-bytes index))
              right-byte (bit-and 0xff (aget right-bytes index))]
          (if (= left-byte right-byte)
            (recur (inc index))
            (compare left-byte right-byte)))))))

(declare p15-s23-seed-readable-value-text)

(defn p15-s23-seed-readable-sorted-distinct!
  [source-path collision-reason rendered]
  (let [ordered (vec (sort p15-s23-seed-readable-compare-utf8 rendered))]
    (when (some true? (map = ordered (rest ordered)))
      (p15-s23-seed-readable-printer-fail!
       source-path collision-reason {}))
    ordered))

(defn p15-s23-seed-readable-value-text
  [source-path value]
  (let [kind (p15-s23-seed-readable-value-kind source-path value)]
    (case kind
      :nil "nil"
      :boolean (if value "true" "false")
      :integer (p15-s23-seed-readable-integer-text value)
      :ratio
      (let [[numerator denominator _ _]
            (p15-s23-seed-readable-ratio-components! source-path value)]
        (str (p15-s23-seed-readable-integer-text numerator)
             "/"
             (p15-s23-seed-readable-integer-text denominator)))
      :floating (p15-s23-seed-readable-floating-text source-path value)
      :string (p15-s23-seed-readable-string-text value)
      :character (p15-s23-seed-readable-character-text value)
      :instant (p15-s23-seed-readable-instant-text source-path value)
      :uuid (p15-s23-seed-readable-uuid-text value)
      :keyword (p15-s23-seed-readable-named-scalar-text kind value)
      :symbol (p15-s23-seed-readable-named-scalar-text kind value)
      :vector
      (str "[" (str/join " " (map #(p15-s23-seed-readable-value-text
                                      source-path %)
                                   value)) "]")
      :list
      (str "(" (str/join " " (map #(p15-s23-seed-readable-value-text
                                      source-path %)
                                   value)) ")")
      :set
      (let [rendered
            (mapv #(p15-s23-seed-readable-value-text source-path %) value)]
        (str "#{"
             (str/join
              " "
              (p15-s23-seed-readable-sorted-distinct!
               source-path :set-render-collision rendered))
             "}"))
      :map
      (let [rendered
            (reduce-kv
             (fn [entries key item]
               (conj entries
                     [(p15-s23-seed-readable-value-text source-path key)
                      (p15-s23-seed-readable-value-text source-path item)]))
             [] value)
            ordered
            (vec
             (sort
              (fn [[left-key left-value] [right-key right-value]]
                (let [key-order
                      (p15-s23-seed-readable-compare-utf8
                       left-key right-key)]
                  (if (zero? key-order)
                    (p15-s23-seed-readable-compare-utf8
                     left-value right-value)
                    key-order)))
              rendered))]
        (when (some true? (map #(= (first %1) (first %2))
                               ordered (rest ordered)))
          (p15-s23-seed-readable-printer-fail!
           source-path :map-key-render-collision {}))
        (str "{"
             (str/join ", " (map (fn [[key-text value-text]]
                                    (str key-text " " value-text))
                                  ordered))
             "}")))))

(defn p15-s23-seed-readable-pr-str
  [source-path args]
  (binding [*p15-s23-seed-readable-owned-failures*
            (java.util.IdentityHashMap.)]
    (try
      (let [preflight
            (p15-s23-seed-readable-preflight! source-path args)
            snapshot-args (:snapshot-args preflight)
            output
            (str/join " "
                      (map #(p15-s23-seed-readable-value-text source-path %)
                           snapshot-args))
            output-bytes (p15-s23-seed-readable-utf8-bytes output)
            maximum-output-bytes
            (:maximum-output-bytes p15-s23-seed-readable-printer-limits)]
        (when (> output-bytes maximum-output-bytes)
          (p15-s23-seed-readable-printer-fail!
           source-path :output-byte-limit
           {:observed-output-bytes output-bytes
            :maximum-output-bytes maximum-output-bytes}))
        output)
      (catch clojure.lang.ExceptionInfo ex
        (if (.remove ^java.util.IdentityHashMap
                     *p15-s23-seed-readable-owned-failures* ex)
          (throw ex)
          (p15-s23-seed-readable-printer-fail!
           source-path :contained-seed-printer-failure {})))
      (catch InterruptedException _
        (.interrupt (Thread/currentThread))
        (p15-s23-seed-readable-printer-fail!
         source-path :contained-seed-printer-failure
         {:interrupt-restored? true}))
      (catch Exception _
        (p15-s23-seed-readable-printer-fail!
         source-path :contained-seed-printer-failure {}))
      (catch java.lang.ThreadDeath fatal
        (throw fatal))
      (catch VirtualMachineError fatal
        (throw fatal))
      (catch LinkageError fatal
        (throw fatal))
      (catch Throwable _
        (p15-s23-seed-readable-printer-fail!
         source-path :contained-seed-printer-failure {})))))

(defn p15-s23-seed-readable-normalized-rest
  [value]
  (let [tail (rest value)
        tail-class (class tail)]
    (if (or (identical? clojure.lang.PersistentList tail-class)
            (identical? clojure.lang.PersistentList$EmptyList tail-class))
      tail
      (apply list tail))))

(defn invoke-stage0-builtin
  [module callee args]
  (try
    (case callee
      + (apply + args)
      - (do (assert-min-arity! module callee args 1)
            (apply - args))
      * (apply * args)
      / (do (assert-min-arity! module callee args 1)
            (apply / args))
      = (do (assert-min-arity! module callee args 1)
            (apply = args))
      < (do (assert-min-arity! module callee args 2)
            (apply < args))
      > (do (assert-min-arity! module callee args 2)
            (apply > args))
      <= (do (assert-min-arity! module callee args 2)
             (apply <= args))
      >= (do (assert-min-arity! module callee args 2)
             (apply >= args))
      str (apply str args)
      pr-str (p15-s23-seed-readable-pr-str (:source-path module) args)
      hash-map (do (assert-even-arity! module callee args)
                   (apply hash-map args))
      vector (vec args)
      list (apply list args)
      conj (do (assert-min-arity! module callee args 1)
               (apply conj args))
      assoc (do
              (assert-min-arity! module callee args 3)
              (when (even? (count args))
                (fail-call-arity! "L2-BUILTIN-ARITY" module callee args
                                  "a collection followed by key/value pairs"))
              (apply assoc args))
      get (do (assert-between-arity! module callee args 2 3)
              (apply get args))
      first (do (assert-exact-arity! module callee args 1)
                (first (first args)))
      second (do (assert-exact-arity! module callee args 1)
                 (second (first args)))
      rest (do (assert-exact-arity! module callee args 1)
               (p15-s23-seed-readable-normalized-rest (first args)))
      count (do (assert-exact-arity! module callee args 1)
                (count (first args))))
    (catch clojure.lang.ExceptionInfo ex
      (throw ex))
    (catch Exception ex
      (fail! "L2-BUILTIN-ERROR"
             "stage0 builtin call failed"
             {:source-span {:source (:source-path module)}
              :function callee
              :cause-message (.getMessage ex)
              :remediation "Keep builtin inputs inside the checked stage0 core subset."}))))

(defn invoke-stage0-function
  [module callee args]
  (let [definition (get (:function-table module) callee)
        params (:params definition)]
    (when-not (= (count params) (count args))
      (fail-call-arity! "L2-FUNCTION-ARITY" module callee args
                        (count params)))
    (eval-do module (zipmap params args) (:body definition))))

(defn eval-collection
  [module env form]
  (cond
    (vector? form) (mapv #(eval-expr module env %) form)
    (map? form) (into {} (map (fn [[k v]]
                                [(eval-expr module env k)
                                 (eval-expr module env v)]))
                      form)
    (set? form) (set (map #(eval-expr module env %) form))
    :else form))

(defn eval-expr
  [module env form]
  (cond
    (symbol? form)
    (if (contains? env form)
      (get env form)
      (fail! "L2-UNKNOWN-SYMBOL"
             "stage0 cannot resolve symbol"
             {:source-span {:source (:source-path module)}
              :symbol form
              :remediation "Define the symbol or stay within the stage0 subset."}))

    (seq? form)
    (case (first form)
      println (do
                (validate-module-effects! module)
                (println (clojure.string/join " " (map #(str (eval-expr module env %)) (rest form)))))
      do (eval-do module env (rest form))
      if (let [[_ test then else] form]
           (if (eval-expr module env test)
             (eval-expr module env then)
             (eval-expr module env else)))
      let (let [[_ bindings & body] form]
            (eval-do module (bind-let module env bindings) body))
      quote (second form)
      host-reflect (fail! "P4-HOST-REFLECTION"
                          "host reflection is not implemented in stage0"
                          {:source-span {:source (:source-path module)}
                           :remediation "Remove host reflection from the stage0 executable subset."})
      (let [callee (first form)
            args (mapv #(eval-expr module env %) (rest form))]
        (cond
          (contains? stage0-builtin-functions callee)
          (invoke-stage0-builtin module callee args)

          (contains? (:function-table module) callee)
          (invoke-stage0-function module callee args)

          :else
          (fail! "L2-UNKNOWN-CORE-FORM"
                 "stage0 cannot execute this form"
                 {:source-span {:source (:source-path module)}
                  :operator callee
                  :remediation "Use defn, println, do, if, let, quote, supported core builtins, or local function calls in the stage0 hosted subset."}))))

    (or (vector? form) (map? form) (set? form))
    (eval-collection module env form)

    :else form))

(defn run-main
  [module]
  (let [function-table (stage0-function-table module)
        module (assoc module :function-table function-table)
        main-function (get function-table 'main)]
    (when-not main-function
      (fail! "L3-UNKNOWN-ALIAS"
             "stage0 executable requires a main function"
             {:source-span {:source (:source-path module)}
              :remediation "Add (defn main [] ...)."}))
    (let [params (:params main-function)
          body (:body main-function)]
      (when-not (empty? params)
        (fail! "L2-MAIN-ARITY"
               "stage0 main must take no arguments"
               {:source-span {:source (:source-path module)}
                :params params
                :remediation "Use (defn main [] ...)."}))
      (with-out-str
        (eval-do module {} body)))))

(defn compile-stage0-collection
  [module locals form]
  (cond
    (vector? form)
    {:op :vector-literal
     :items (mapv #(compile-stage0-expr module locals %) form)}

    (map? form)
    {:op :map-literal
     :entries (mapv (fn [[k v]]
                      {:key (compile-stage0-expr module locals k)
                       :value (compile-stage0-expr module locals v)})
                    (sort-by (fn [[k v]] (pr-str [k v])) form))}

    (set? form)
    {:op :set-literal
     :items (mapv #(compile-stage0-expr module locals %)
                  (sort-by pr-str form))}

    :else
    {:op :literal :value form}))

(defn compile-stage0-let
  [module locals bindings body]
  (when-not (and (vector? bindings) (even? (count bindings)))
    (fail! "L2-LET-BINDING"
           "let requires an even binding vector"
           {:source-span {:source (:source-path module)}
            :bindings bindings
            :remediation "Use pairs of local names and expressions in let."}))
  (loop [scope locals
         compiled []
         pairs (partition 2 bindings)]
    (if-let [[name expr] (first pairs)]
      (do
        (when-not (symbol? name)
          (fail! "L2-LET-BINDING"
                 "let binding name must be a symbol"
                 {:source-span {:source (:source-path module)}
                  :binding name
                  :remediation "Bind symbols in stage0 let forms."}))
        (recur (conj scope name)
               (conj compiled {:name name
                               :expr (compile-stage0-expr module scope expr)})
               (rest pairs)))
      {:op :let
       :bindings compiled
       :body (mapv #(compile-stage0-expr module scope %) body)})))

(defn compile-stage0-expr
  [module locals form]
  (cond
    (symbol? form)
    (if (contains? locals form)
      {:op :local :name form}
      (fail! "L2-UNKNOWN-SYMBOL"
             "stage0 cannot resolve symbol"
             {:source-span {:source (:source-path module)}
              :symbol form
              :remediation "Define the symbol or stay within the stage0 subset."}))

    (seq? form)
    (case (first form)
      println {:op :println
               :effect :io/write
               :capability :io/stdout
               :args (mapv #(compile-stage0-expr module locals %) (rest form))}
      do {:op :do
          :body (mapv #(compile-stage0-expr module locals %) (rest form))}
      if (let [[_ test then else] form]
           {:op :if
            :test (compile-stage0-expr module locals test)
            :then (compile-stage0-expr module locals then)
            :else (compile-stage0-expr module locals else)})
      let (let [[_ bindings & body] form]
            (compile-stage0-let module locals bindings body))
      quote {:op :quote :value (second form)}
      host-reflect (fail! "P4-HOST-REFLECTION"
                          "host reflection is not implemented in stage0"
                          {:source-span {:source (:source-path module)}
                           :remediation "Remove host reflection from the stage0 executable subset."})
      (let [callee (first form)
            args (mapv #(compile-stage0-expr module locals %) (rest form))]
        (cond
          (contains? stage0-builtin-functions callee)
          {:op :builtin-call :function callee :args args}

          (contains? (:function-table module) callee)
          {:op :function-call :function callee :args args}

          :else
          (fail! "L2-UNKNOWN-CORE-FORM"
                 "stage0 cannot execute this form"
                 {:source-span {:source (:source-path module)}
                  :operator callee
                  :remediation "Use defn, println, do, if, let, quote, supported core builtins, or local function calls in the stage0 hosted subset."}))))

    (or (vector? form) (map? form) (set? form))
    (compile-stage0-collection module locals form)

    :else
    {:op :literal :value form}))

(defn compile-stage0-function
  [module {:keys [name params body] :as definition}]
  (assoc definition
         :binding {:name name
                   :kind :function
                   :namespace (:module module)
                   :profile (:profile module)
                   :target (:target module)
                   :visibility (if (seq (:exports module))
                                 (if (contains? (set (:exports module)) name)
                                   :public
                                   :private)
                                 :stage0-local)
                   :effects (:effects module)
                   :capabilities (:capabilities module)}
         :instructions (mapv #(compile-stage0-expr module (set params) %) body)))

(defn stage0-instruction-summary
  [instruction]
  (let [children
        (case (:op instruction)
          :println (:args instruction)
          :do (:body instruction)
          :if [(:test instruction) (:then instruction) (:else instruction)]
          :let (concat (map :expr (:bindings instruction)) (:body instruction))
          :loop (concat (map :expr (:bindings instruction))
                        (:body instruction))
          :recur (:args instruction)
          :builtin-call (:args instruction)
          :function-call (:args instruction)
          :vector-literal (:items instruction)
          :set-literal (:items instruction)
          :map-literal (mapcat (fn [{:keys [key value]}] [key value])
                                (:entries instruction))
          [])]
    ;; A parent and child may share an opcode (for example nested builtin
    ;; calls).  Add the parent fact instead of letting `merge` overwrite it;
    ;; this makes the stage0 comparison describe every concrete instruction.
    (merge-with +
                {(:op instruction) 1}
                (apply merge-with +
                       (map stage0-instruction-summary
                            (remove nil? children))))))

(defn stage0-compiled-core-plan
  [source-path source-text module]
  (let [function-table (stage0-function-table module)
        module (assoc module :function-table function-table)
        _ (validate-stage0-compiled-profile! module)
        _ (executable-profile! source-path module (:forms module))
        _ (validate-module-effects! module)
        _ (validate-stage0-executable-safety! module)
        _ (validate-stage0-compiled-performance! module)
        _ (validate-stage0-compiled-math! module)
        _ (validate-stage0-compiled-compiler! module)
        _ (validate-stage0-compiled-backend! module)
        _ (validate-stage0-compiled-runtime! module)
        _ (validate-stage0-compiled-domain! module)
        _ (validate-stage0-compiled-schema! module)
        _ (validate-stage0-compiled-ai! module)
        _ (validate-stage0-compiled-package! module)
        _ (validate-stage0-compiled-tooling! module)
        _ (validate-stage0-compiled-conformance! module)
        functions (into (sorted-map)
                        (map (fn [[name definition]]
                               [name (compile-stage0-function
                                      module
                                      definition)]))
                        function-table)
        main-function (get functions 'main)
        _ (when-not main-function
            (fail! "L3-UNKNOWN-ALIAS"
                   "stage0 executable requires a main function"
                   {:source-span {:source source-path}
                    :remediation "Add (defn main [] ...)."}))
        _ (when-not (empty? (:params main-function))
            (fail! "L2-MAIN-ARITY"
                   "stage0 main must take no arguments"
                   {:source-span {:source source-path}
                    :params (:params main-function)
                    :remediation "Use (defn main [] ...)."}))
        instruction-summary (apply merge-with +
                                   (mapcat (fn [[_ function]]
                                             (map stage0-instruction-summary
                                                  (:instructions function)))
                                           functions))
        plan-base {:kind :gravity/stage0-hosted-core-compiled-plan
                   :entrypoint 'main
                   :source {:path source-path
                            :sha256 (str "sha256:" (sha256-hex source-text))}
                   :compiler {:owner :clojure-bootstrap
                              :stage :stage0
                              :input :macro-expanded-core
                              :output :instruction-plan
                              :retirement-objective
                              :replace-with-gravity-self-hosted-compiler}
                   :module (select-keys module
                                        [:module :source-path :profile :target
                                         :effects :capabilities :providers
                                         :exports
                                         :safety])
                   :binding-table (mapv (fn [[name function]]
                                           (assoc (:binding function)
                                                  :arity (:arity function)))
                                         (sort-by key functions))
                   :functions functions
                   :instruction-summary instruction-summary
                   :effect-summary {:declared (:effects module)
                                    :inferred (if (pos? (get instruction-summary
                                                             :println
                                                             0))
                                                #{:io/write}
                                                #{})
                                    :capabilities (:capabilities module)}
                   :diagnostics []}]
    (assoc plan-base
           :plan-id (str "sha256:" (sha256-hex (pr-str plan-base))))))

(defn execute-stage0-instructions
  [plan env instructions]
  (reduce (fn [_ instruction]
            (execute-stage0-instruction plan env instruction))
          nil
          instructions))

(defn execute-stage0-instruction
  [plan env instruction]
  (case (:op instruction)
    :literal (:value instruction)
    :quote (:value instruction)
    :local (if (contains? env (:name instruction))
             (get env (:name instruction))
             (fail! "L2-UNKNOWN-SYMBOL"
                    "stage0 compiled plan cannot resolve local"
                    {:source-span {:source (get-in plan [:source :path])}
                     :symbol (:name instruction)
                     :remediation "Regenerate the compiled plan from a valid stage0 source module."}))
    :vector-literal (mapv #(execute-stage0-instruction plan env %)
                          (:items instruction))
    :set-literal (set (map #(execute-stage0-instruction plan env %)
                           (:items instruction)))
    :map-literal (into {}
                       (map (fn [{:keys [key value]}]
                              [(execute-stage0-instruction plan env key)
                               (execute-stage0-instruction plan env value)]))
                       (:entries instruction))
    :println (let [module (:module plan)
                   args (mapv #(execute-stage0-instruction plan env %)
                              (:args instruction))]
               (validate-module-effects! module)
               (println (clojure.string/join " " (map str args))))
    :do (execute-stage0-instructions plan env (:body instruction))
    :if (if (execute-stage0-instruction plan env (:test instruction))
          (execute-stage0-instruction plan env (:then instruction))
          (execute-stage0-instruction plan env (:else instruction)))
    :let (loop [env env
                bindings (:bindings instruction)]
           (if-let [{:keys [name expr]} (first bindings)]
             (recur (assoc env name
                           (execute-stage0-instruction plan env expr))
                    (rest bindings))
             (execute-stage0-instructions plan env (:body instruction))))
    :builtin-call (let [module (:module plan)
                        args (mapv #(execute-stage0-instruction plan env %)
                                   (:args instruction))]
                    (invoke-stage0-builtin module (:function instruction) args))
    :function-call (let [args (mapv #(execute-stage0-instruction plan env %)
                                    (:args instruction))]
                     (execute-stage0-compiled-function
                      plan
                      (:function instruction)
                      args))
    (fail! "L2-UNKNOWN-CORE-FORM"
           "stage0 compiled plan contains an unknown instruction"
           {:source-span {:source (get-in plan [:source :path])}
            :operator (:op instruction)
            :remediation "Regenerate the compiled plan with a supported stage0 compiler."})))

(defn execute-stage0-compiled-function
  [plan callee args]
  (let [definition (get-in plan [:functions callee])
        params (:params definition)]
    (when-not definition
      (fail! "L2-UNKNOWN-CORE-FORM"
             "stage0 compiled plan references an unknown function"
             {:source-span {:source (get-in plan [:source :path])}
              :function callee
              :remediation "Regenerate the compiled plan from source."}))
    (when-not (= (count params) (count args))
      (fail-call-arity! "L2-FUNCTION-ARITY"
                        (:module plan)
                        callee
                        args
                        (count params)))
    (execute-stage0-instructions plan (zipmap params args)
                                 (:instructions definition))))

(defn execute-stage0-compiled-plan
  [plan]
  (let [main-function (get-in plan [:functions (:entrypoint plan)])
        params (:params main-function)]
    (when-not main-function
      (fail! "L3-UNKNOWN-ALIAS"
             "stage0 compiled plan requires a main function"
             {:source-span {:source (get-in plan [:source :path])}
              :remediation "Regenerate the compiled plan from a module with main."}))
    (when-not (empty? params)
      (fail! "L2-MAIN-ARITY"
             "stage0 compiled main must take no arguments"
             {:source-span {:source (get-in plan [:source :path])}
              :params params
              :remediation "Use (defn main [] ...)."}))
    (with-out-str
      (execute-stage0-instructions plan {} (:instructions main-function)))))

(defn stage0-compiled-plan-safety-report
  [plan]
  (let [summary (:instruction-summary plan)
        source-path (get-in plan [:source :path])
        operation-records
        (vec
         (concat
          (when (pos? (get summary :function-call 0))
            [{:operation :stage0/function-call
              :outcome :runtime-checked
              :condition :fixed-arity
              :failure "L2-FUNCTION-ARITY"
              :source-span {:source source-path}
              :profile (get-in plan [:module :profile])}])
          (when (pos? (get summary :builtin-call 0))
            [{:operation :stage0/builtin-call
              :outcome :runtime-checked
              :condition :builtin-arity
              :failure "L2-BUILTIN-ARITY"
              :source-span {:source source-path}
              :profile (get-in plan [:module :profile])}])
          (when (pos? (get summary :println 0))
            [{:operation :stage0/io-write
              :outcome :proven-safe
              :condition :declared-effect-and-capability
              :effect :io/write
              :capability :io/stdout
              :source-span {:source source-path}
              :profile (get-in plan [:module :profile])}])
          [{:operation :stage0/control-flow
            :outcome :proven-safe
            :condition :compiled-instruction-plan
            :forms (select-keys summary [:do :if :let :quote])
            :source-span {:source source-path}
            :profile (get-in plan [:module :profile])}
           {:operation :stage0/literals-and-locals
            :outcome :proven-safe
            :condition :closed-compiled-plan
            :forms (select-keys summary
                                [:literal :local :vector-literal
                                 :map-literal :set-literal])
            :source-span {:source source-path}
            :profile (get-in plan [:module :profile])}]))
        report-base
        {:kind :gravity/stage0-hosted-core-compiled-safety-report
         :document "SAFE1"
         :governing-documents ["D8" "D9" "SAFE1" "SAFE6"]
         :compiled-plan-id (:plan-id plan)
         :module (:module plan)
         :safety-mode (get-in plan [:module :safety])
         :safety-outcomes stage0-safe1-outcomes
         :safety-classification-records operation-records
         :runtime-checks (filterv #(= :runtime-checked (:outcome %))
                                  operation-records)
         :unsafe-islands []
         :unsafe-policy {:mode (get-in plan [:module :safety])
                         :unsafe-islands-allowed? false}
         :diagnostics []}]
    (assoc report-base
           :report-id (str "sha256:" (sha256-hex (pr-str report-base))))))

(defn hosted-core-compiled-safety-proof-source-artifact
  [source-path source-text]
  (let [_ (validate-stage0-source-profile! source-path source-text)
        _ (validate-stage0-source-safety! source-path source-text)
        macro-artifact (macro-source-artifact source-path source-text)
        module (assoc (:module macro-artifact)
                      :forms (:expanded-forms macro-artifact))
        compiled-plan (stage0-compiled-core-plan source-path source-text module)
        run-output (execute-stage0-compiled-plan compiled-plan)
        safety-report (stage0-compiled-plan-safety-report compiled-plan)
        outcomes (map :outcome (:safety-classification-records safety-report))
        proof {:compiled-plan-safety-classified? true
               :exactly-one-outcome-per-operation?
               (and (seq outcomes)
                    (every? stage0-safe1-outcomes outcomes)
                    (= (count outcomes)
                       (count (:safety-classification-records
                               safety-report))))
               :runtime-checks-recorded?
               (set/subset? #{:stage0/function-call :stage0/builtin-call}
                            (set (map :operation
                                      (:runtime-checks safety-report))))
               :unsafe-islands-rejected? true
               :unsafe-audit-metadata-required? true
               :compiled-plan-executed? (= "core-app\ngravity:19:2\n(:ok 19)\n"
                                          run-output)
               :rejected-diagnostics-covered?
               (= #{"SAFE6-UNSAFE-FORBIDDEN" "SAFE6-MISSING-METADATA"}
                  (set (map :diagnostic
                            stage0-compiled-safety-rejected-fixtures)))
               :limitations {:clojure-instruction-runner? true
                             :self-hosted-compiler? false
                             :native-backend? false
                             :unsafe-island-execution? false
                             :next-required-capability
                             :lower-safety-report-into-runtime-and-mir-artifacts}
               :status :complete}
        artifact-base
        {:kind :gravity/stage0-hosted-core-compiled-safety-proof
         :phase "02"
         :task "P02-S1"
         :governing-documents ["D8" "D9" "SAFE1" "SAFE6"]
         :source {:path source-path
                  :sha256 (str "sha256:" (sha256-hex source-text))}
         :compiled-plan (select-keys compiled-plan
                                     [:kind :plan-id :entrypoint
                                      :instruction-summary :effect-summary])
         :safety-report (select-keys safety-report
                                     [:kind :report-id :document
                                      :safety-mode
                                      :safety-classification-records
                                      :runtime-checks :unsafe-islands
                                      :unsafe-policy :diagnostics])
         :accepted-run {:command (str "clojure -M:gravity run-compiled "
                                      source-path)
                        :stdout run-output}
         :rejected-fixtures stage0-compiled-safety-rejected-fixtures
         :trusted-boundary {:compiler :clojure/jvm
                            :runtime :clojure/jvm
                            :instruction-plan? true
                            :clojure-instruction-runner? true
                            :self-hosted-compiler? false}
         :capability-based-proof proof}]
    (assoc artifact-base
           :artifact-id (str "sha256:" (sha256-hex (pr-str artifact-base))))))

(defn hosted-core-compiled-safety-proof-file-artifact
  [path]
  (hosted-core-compiled-safety-proof-source-artifact path (slurp path)))

(defn stage0-compiled-plan-profile-report
  [plan]
  (let [module (:module plan)
        inferred-effects (get-in plan [:effect-summary :inferred] #{})
        required-capabilities (set/union
                               (get-in plan [:effect-summary :capabilities] #{})
                               (required-capabilities-for-effects
                                inferred-effects))
        effect-authority (profile-effective-effects module inferred-effects)
        capability-authority (profile-effective-capabilities
                              module
                              required-capabilities)
        effect-table (effect-permission-table module inferred-effects
                                              effect-authority)
        capability-table (capability-permission-table
                          module
                          required-capabilities
                          capability-authority)
        contract (profile-contract (:profile module))
        manifest {:module (:module module)
                  :source-path (:source-path module)
                  :profile (:profile module)
                  :target (:target module)
                  :source-effects (:source effect-authority)
                  :inferred-effects inferred-effects
                  :effective-effects (:effective effect-authority)
                  :source-capabilities (:source capability-authority)
                  :required-capabilities required-capabilities
                  :effective-capabilities (:effective capability-authority)
                  :memory-regime (:memory contract)
                  :runtime-assumptions (:runtime contract)
                  :unsafe-policy (:unsafe-policy contract)
                  :dependencies {:module (:module module)
                                 :dependencies []
                                 :acyclic true}
                  :provider-selections []
                  :safety (:safety module)
                  :policy-layers {:effects (select-keys
                                             effect-authority
                                             [:source :profile :package
                                              :provider :deployment])
                                  :capabilities (select-keys
                                                 capability-authority
                                                 [:source :profile :package
                                                  :provider :deployment])}}
        backend-report (backend-eligibility-report
                        module
                        (assoc manifest :profile-contract contract))
        report-base
        {:kind :gravity/stage0-hosted-core-compiled-profile-report
         :document-set ["P1" "P4" "P13"]
         :compiled-plan-id (:plan-id plan)
         :profile-contract (select-keys contract
                                        [:profile :allowed-effects
                                         :checked-effects :capabilities
                                         :memory :runtime :unsafe-policy])
         :profile-manifest manifest
         :effect-permission-table effect-table
         :capability-permission-table capability-table
         :cross-profile-dependency-graph (:dependencies manifest)
         :backend-eligibility-report backend-report
         :behavior-states {:effects (set (map :state effect-table))
                           :capabilities (set (map :state
                                                   capability-table))}
         :diagnostics []}]
    (assoc report-base
           :report-id (str "sha256:" (sha256-hex (pr-str report-base))))))

(defn hosted-core-compiled-profile-proof-source-artifact
  [source-path source-text]
  (let [_ (validate-stage0-source-profile! source-path source-text)
        _ (validate-stage0-source-safety! source-path source-text)
        macro-artifact (macro-source-artifact source-path source-text)
        module (assoc (:module macro-artifact)
                      :forms (:expanded-forms macro-artifact))
        compiled-plan (stage0-compiled-core-plan source-path source-text module)
        run-output (execute-stage0-compiled-plan compiled-plan)
        profile-report (stage0-compiled-plan-profile-report compiled-plan)
        manifest (:profile-manifest profile-report)
        proof {:compiled-profile-validated? true
               :active-profile-hosted? (= :hosted (:profile manifest))
               :target-jvm? (= :jvm (:target manifest))
               :effective-effects-covered?
               (contains? (:effective-effects manifest) :io/write)
               :effective-capabilities-covered?
               (contains? (:effective-capabilities manifest) :io/stdout)
               :backend-eligibility-recorded?
               (true? (get-in profile-report
                              [:backend-eligibility-report :eligible?]))
               :cross-profile-graph-recorded?
               (= [] (get-in profile-report
                             [:cross-profile-dependency-graph
                              :dependencies]))
               :compiled-plan-executed? (= "core-app\ngravity:19:2\n(:ok 19)\n"
                                          run-output)
               :rejected-diagnostics-covered?
               (= #{"P4-HOST-EFFECT" "P4-HOST-CAPABILITY" "P1-RUNTIME"}
                  (set (map :diagnostic
                            stage0-compiled-profile-rejected-fixtures)))
               :limitations {:clojure-instruction-runner? true
                             :self-hosted-compiler? false
                             :native-backend? false
                             :next-required-capability
                             :lower-profile-manifest-into-mir-runtime-and-package-artifacts}
               :status :complete}
        artifact-base
        {:kind :gravity/stage0-hosted-core-compiled-profile-proof
         :phase "03"
         :task "P03-S1"
         :governing-documents ["P1" "P4" "P13"]
         :source {:path source-path
                  :sha256 (str "sha256:" (sha256-hex source-text))}
         :compiled-plan (select-keys compiled-plan
                                     [:kind :plan-id :entrypoint
                                      :instruction-summary :effect-summary])
         :profile-report (select-keys profile-report
                                      [:kind :report-id :document-set
                                       :profile-manifest
                                       :effect-permission-table
                                       :capability-permission-table
                                       :cross-profile-dependency-graph
                                       :backend-eligibility-report
                                       :behavior-states :diagnostics])
         :accepted-run {:command (str "clojure -M:gravity run-compiled "
                                      source-path)
                        :stdout run-output}
         :rejected-fixtures stage0-compiled-profile-rejected-fixtures
         :trusted-boundary {:compiler :clojure/jvm
                            :runtime :clojure/jvm
                            :instruction-plan? true
                            :clojure-instruction-runner? true
                            :self-hosted-compiler? false}
         :capability-based-proof proof}]
    (assoc artifact-base
           :artifact-id (str "sha256:" (sha256-hex (pr-str artifact-base))))))

