               (boolean
                (and (true? (:diagnostics-match-cli lsp))
                     (= :passed (get-in debugger
                                        [:source-map-validation :status]))
                     (not (some #(and (true? (:redacted %))
                                      (true? (:accessed? %)))
                                (:variable-reports debugger)))))
