  ["P15S23F001" "P15S23F002" "P15S23F003" "P15S23F004"
   "P15S23F005" "P15S23F006" "P15S23F007" "P15S23F008"
   "P15S23F009"])

(defn p15-s23-stage2-source-front-end-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage2-source-front-end-diagnostic-messages
              id
              "P15-S23 stage2 source front-end proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage2-source-front-end
                 :diagnostic-family :p15-s23-stage2-source-front-end
                 :value value
                 :remediation "Keep the stage2 reader and macro front-end rules authored in Gravity source, execute accepted and rejected fixtures through the declared front-end boundary, and keep full self-hosting claims false."}
                data)))

(defn p15-s23-stage2-source-front-end-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage2-source-front-end
   :source-span {:source source-path}
   :message (get p15-s23-stage2-source-front-end-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_stage2_source_front_end})

(defonce p15-s23-source-artifact-cache
  (atom {}))

(defn p15-s23-source-artifact-cache-key
  [kind source-path]
  (let [file (java.io.File. source-path)]
    [kind (.getCanonicalPath file) (.lastModified file) (.length file)]))

(defn p15-s23-cached-source-artifact
  [kind source-path build-fn]
  (let [cache-key (p15-s23-source-artifact-cache-key kind source-path)]
    (if-let [artifact (get @p15-s23-source-artifact-cache cache-key)]
      artifact
      (let [artifact (build-fn)]
        (swap! p15-s23-source-artifact-cache assoc cache-key artifact)
        artifact))))

(defn p15-s23-front-end-state
  [source-path source-text]
  {:source-path source-path
   :source-text source-text
   :idx 0
   :line 1
   :column 1})

(defn p15-s23-front-end-current-char
  [state]
  (let [idx (:idx state)
        text (:source-text state)]
    (when (< idx (count text))
      (nth text idx))))

(defn p15-s23-front-end-advance
  [state]
  (let [ch (p15-s23-front-end-current-char state)
        previous-cr?
        (and (= \newline ch)
             (pos? (:idx state))
             (= \return (.charAt ^String (:source-text state)
                                 (dec (:idx state)))))]
    (cond
      (= \return ch)
      (-> state
          (update :idx inc)
          (assoc :line (inc (:line state)) :column 1))

      (and (= \newline ch) (not previous-cr?))
      (-> state
          (update :idx inc)
          (assoc :line (inc (:line state)) :column 1))

      previous-cr?
      (update state :idx inc)

      :else
      (-> state
          (update :idx inc)
          (update :column inc)))))

(defn p15-s23-front-end-location
  [state]
  {:line (:line state)
   :column (:column state)
   :char (:idx state)
   :byte (utf8-byte-count (subs (:source-text state) 0 (:idx state)))})

(defn p15-s23-front-end-span
  [source-path form-index start-state end-state]
  {:source source-path
   :form-index form-index
   :start (p15-s23-front-end-location start-state)
   :end (p15-s23-front-end-location end-state)
   :byte-start (:byte (p15-s23-front-end-location start-state))
   :byte-end (:byte (p15-s23-front-end-location end-state))})

(defn p15-s23-front-end-reader-error!
  [source-path state data]
  (p15-s23-stage2-source-front-end-fail!
   "P15S23F009" source-path data
   (merge {:reader-state (select-keys state [:idx :line :column])}
          data)))

(defn p15-s23-front-end-skip-comment
  [state]
  (loop [state state]
    (let [ch (p15-s23-front-end-current-char state)]
      (cond
        (nil? ch) state
        (= \return ch)
        (let [advanced (p15-s23-front-end-advance state)]
          (if (= \newline (p15-s23-front-end-current-char advanced))
            (p15-s23-front-end-advance advanced)
            advanced))
        (= \newline ch) (p15-s23-front-end-advance state)
        :else (recur (p15-s23-front-end-advance state))))))

(defn p15-s23-front-end-skip-ignored
  [state]
  (loop [state state]
    (let [ch (p15-s23-front-end-current-char state)]
      (cond
        (nil? ch) state
        (Character/isWhitespace ^Character ch)
        (recur (p15-s23-front-end-advance state))
        (= \, ch)
        (recur (p15-s23-front-end-advance state))
        (= \; ch)
        (recur (p15-s23-front-end-skip-comment state))
        :else state))))

(defn p15-s23-front-end-delimiter?
  [ch]
  (or (nil? ch)
      (Character/isWhitespace ^Character ch)
      (contains? #{\( \) \[ \] \{ \} \" \;} ch)
      (= \, ch)))

(declare p15-s23-front-end-read-form)

(defn p15-s23-front-end-read-string
  [source-path state]
  (let [start state]
    (loop [state (p15-s23-front-end-advance state)
           chars []]
      (let [ch (p15-s23-front-end-current-char state)]
        (cond
          (nil? ch)
          (p15-s23-front-end-reader-error!
           source-path state {:reason :unclosed-string})
          (= \" ch)
          [(apply str chars) (p15-s23-front-end-advance state)]
          (= \\ ch)
          (let [escape-state (p15-s23-front-end-advance state)
                escape (p15-s23-front-end-current-char escape-state)]
            (when (nil? escape)
              (p15-s23-front-end-reader-error!
               source-path escape-state {:reason :unclosed-string-escape}))
            (recur (p15-s23-front-end-advance escape-state)
                   (conj chars
                         (case escape
                           \n \newline
                           \t \tab
                           \r \return
                           \" \"
                           \\ \\
                           escape))))
          :else
          (recur (p15-s23-front-end-advance state)
                 (conj chars ch)))))))

(defn p15-s23-front-end-read-token
  [state]
  (loop [state state
         chars []]
    (let [ch (p15-s23-front-end-current-char state)]
      (if (p15-s23-front-end-delimiter? ch)
        [(apply str chars) state]
        (recur (p15-s23-front-end-advance state) (conj chars ch))))))

(defn p15-s23-front-end-parse-token
  [source-path state token]
  (cond
    (= "nil" token) nil
    (= "true" token) true
    (= "false" token) false
    (str/starts-with? token ":") (keyword (subs token 1))
    (re-matches #"-?[0-9]+" token) (Long/parseLong token)
    (seq token) (symbol token)
    :else
    (p15-s23-front-end-reader-error!
     source-path state {:reason :empty-token})))

(defn p15-s23-front-end-read-coll
  [source-path state form-index close-ch kind]
  (loop [state (p15-s23-front-end-skip-ignored
                (p15-s23-front-end-advance state))
         values []]
    (let [ch (p15-s23-front-end-current-char state)]
      (cond
        (nil? ch)
        (p15-s23-front-end-reader-error!
         source-path state {:reason :unclosed-form :expected close-ch})
        (= close-ch ch)
        (let [end-state (p15-s23-front-end-advance state)]
          [(case kind
             :list (apply list values)
             :vector (vec values)
             :map (do
                    (when (odd? (count values))
                      (p15-s23-front-end-reader-error!
                       source-path state {:reason :odd-map}))
                    (into {} (partition 2 values)))
             :set (set values))
           end-state])
        (contains? #{\) \] \}} ch)
        (p15-s23-front-end-reader-error!
         source-path state {:reason :unexpected-close :found ch})
        :else
        (let [[record next-state]
              (p15-s23-front-end-read-form source-path state form-index)]
          (recur (p15-s23-front-end-skip-ignored next-state)
                 (conj values (:form record))))))))

(defn p15-s23-front-end-read-form
  [source-path state form-index]
  (let [state (p15-s23-front-end-skip-ignored state)
        start-state state
        ch (p15-s23-front-end-current-char state)]
    (when (nil? ch)
      (p15-s23-front-end-reader-error!
       source-path state {:reason :unexpected-eof}))
    (let [[form end-state]
          (case ch
            \( (p15-s23-front-end-read-coll
                source-path state form-index \) :list)
            \[ (p15-s23-front-end-read-coll
                source-path state form-index \] :vector)
            \{ (p15-s23-front-end-read-coll
                source-path state form-index \} :map)
            \" (p15-s23-front-end-read-string source-path state)
            \# (let [dispatch-state (p15-s23-front-end-advance state)
                     dispatch (p15-s23-front-end-current-char dispatch-state)]
                 (if (= \{ dispatch)
                   (p15-s23-front-end-read-coll
                    source-path dispatch-state form-index \} :set)
                   (p15-s23-front-end-reader-error!
                    source-path state
                    {:reason :unsupported-dispatch
                     :dispatch dispatch})))
            (if (contains? #{\) \] \}} ch)
              (p15-s23-front-end-reader-error!
               source-path state {:reason :unexpected-close :found ch})
              (let [[token end-state] (p15-s23-front-end-read-token state)]
                [(p15-s23-front-end-parse-token source-path state token)
                 end-state])))]
      [{:form form
        :span (p15-s23-front-end-span source-path form-index
                                      start-state end-state)
        :metadata {}
        :reader-origin {:kind :stage2-source-front-end
                        :raw-form-kind (form-kind form)
                        :engine :gravity-stage2-reader-rules-v1}
        :generated-origin []}
       end-state])))

(defn p15-s23-stage2-front-end-read-source-form-records
  [front-end source-path source-text]
  (when-not (= :gravity-stage2-reader-rules-v1
               (get-in front-end [:reader-rules :engine]))
    (p15-s23-stage2-source-front-end-fail!
     "P15S23F002" source-path front-end
     {:missing-fields [:reader-rules :engine]}))
  (loop [state (p15-s23-front-end-skip-ignored
                (p15-s23-front-end-state source-path source-text))
         form-index 0
         records []]
    (if (nil? (p15-s23-front-end-current-char state))
      records
      (let [[record next-state]
            (p15-s23-front-end-read-form source-path state form-index)]
        (recur (p15-s23-front-end-skip-ignored next-state)
               (inc form-index)
               (conj records record))))))

(defn p15-s23-stage2-front-end-expand-form
  [front-end syntax]
  (let [form (:form syntax)]
    (if (and (seq? form) (= 'defn (first form)))
      (let [[_ name params & body] form]
        (when-not (and (symbol? name) (vector? params))
          (p15-s23-stage2-source-front-end-fail!
           "P15S23F003" (get-in syntax [:span :source]) form
           {:reason :invalid-defn-shape}))
        (let [expanded (list 'def name (cons 'fn (cons params body)))]
          (-> syntax
              (assoc :form expanded
                     :origin :generated
                     :phase :macro-expanded
                     :macro-namespace 'gravity.core
                     :generated-origin
                     [{:from (:span syntax)
                       :macro 'gravity.core/defn
                       :macro-version "stage2-front-end"
                       :input-hash (str "sha256:"
                                        (sha256-hex (pr-str form)))
                       :output-hash (str "sha256:"
                                         (sha256-hex
                                          (pr-str expanded)))}])
              (update :hygiene conj {:macro 'gravity.core/defn
                                     :policy :hygienic}))))
      (assoc syntax :phase :macro-expanded))))

(defn p15-s23-stage2-c2-c3-records
  [c2-artifact rich-syntax]
  (let [form-by-id (into {} (map (juxt :form-id identity)
                                  (:form-tree c2-artifact)))
        token-by-id (into {} (map (juxt :token-id identity)
                                   (:token-stream c2-artifact)))]
    (mapv
     (fn [syntax]
       (let [form-id (get-in syntax [:source :form-id])
             token-id (get-in syntax [:source :token-id])
             form-record (get form-by-id form-id)
             token-record (get token-by-id token-id)]
         {:form (get-in syntax [:form :value])
          :span (get-in syntax [:span :primary])
          :origin :source
          :metadata (or (:metadata syntax) {})
          :reader-origin
          {:kind :stage2-source-front-end
           :engine :gravity-stage2-c2-c3-ingress
           :c3-origin (:origin syntax)}
          :source-origin (vec (or (:origin syntax) []))
          :generated-origin []
          :form-id form-id
          :token-id token-id
          :source-id (get-in syntax [:source :source-id])
          :c2-form-record form-record
          :c2-token-record token-record
          :c3-syntax-object syntax}))
     rich-syntax)))

(defn p15-s23-stage2-c2-c3-front-end-products
  "Build the stage2 source-front-end view from the authoritative C2/C3
  reader products.  The old P15 parser remains available for its direct
  compatibility probes, but stage2 source ingress must not re-read source
  through that simplified parser."
  ([source-path source-text]
   (p15-s23-stage2-c2-c3-front-end-products
    source-path source-text
    (reader-project-context-for-source source-path)))
  ([source-path source-text project-context]
   (p15-s23-stage2-c2-c3-front-end-products
    source-path source-text project-context false))
  ([source-path source-text project-context retain-authenticated-artifacts?]
  (let [c3-artifact (compiler-c3-syntax-source-artifact
                     source-path source-text project-context)
        c2-artifact (:c2-reader-artifact c3-artifact)
        root-form-ids (:top-level-form-ids c2-artifact)
        rich-syntax (vec (take (count root-form-ids)
                               (:syntax-object-stream c3-artifact)))
        records (p15-s23-stage2-c2-c3-records c2-artifact rich-syntax)
        forms (mapv :form records)]
    (cond->
     {:artifact :gravity/p15-s23-stage2-c2-c3-front-end-products
      :source-path source-path
      :source-text source-text
      :source-unit-record (:source-unit-record c2-artifact)
      :source-unit-id (get-in c2-artifact [:source-unit-record :source-id])
      :token-stream (:token-stream c2-artifact)
      :form-tree (:form-tree c2-artifact)
      :top-level-form-ids root-form-ids
      :syntax-seed-stream (:syntax-seed-stream c2-artifact)
      :reader-source-map (:reader-source-map c2-artifact)
      :literal-decoding-records (:literal-decoding-records c2-artifact)
      :semantic-error-deferment-record
      (:semantic-error-deferment-record c2-artifact)
      :reader-extension-invocation-records
      (:reader-extension-invocation-records c2-artifact)
      :reader-diagnostics (:reader-diagnostics c2-artifact)
      :incremental-reader-hashes (:incremental-reader-hashes c2-artifact)
      :reader-product-integrity (:reader-product-integrity c2-artifact)
      :c2-reader-artifact (:c2-reader-artifact c3-artifact)
      :c3-artifact-id (:artifact-id c3-artifact)
      :c3-syntax-object-stream rich-syntax
      :c3-capability-proof (:capability-based-proof c3-artifact)
      :records records
      :forms forms
      :status :complete}
      retain-authenticated-artifacts?
      (assoc :authenticated-c3-source-artifact c3-artifact)))))

(declare c2-reader-message c2-reader-diagnostic-ids reader-canonical-hash
         c2-reader-governing-document c2-source-unit-record
         standard-reader-options compiler-c2-reader-source-artifact)

(def p15-s23-stage2-reader-compatibility-diagnostic-map
  {"STAGE1READER001"
   {:c2-id "C2-DELIMITER"
    :remapped-from "L1-DELIMITER"
    :reader-state-stages #{:recursive-form-building :read-source}
    :fact-key-sets #{#{:actual-delimiter}
                     #{:expected-delimiter :actual-delimiter}
                     #{:observed-close-codepoint :token-id :form-id}
                     #{:observed-close-codepoint :expected-close-codepoint
                       :token-id :form-id}}}
   "STAGE1READER002"
   {:c2-id "C2-DELIMITER"
    :remapped-from "L1-DELIMITER"
    :reader-state-stages #{:recursive-form-building :read-source}
    :fact-key-sets #{#{:expected-delimiter :open-token}
                     #{:open-form-id :token-id :form-id}}}
   "STAGE1READER003"
   {:c2-id "C2-STRING"
    :remapped-from "L1-STRING"
    :reader-state-stages #{:lexical-tokenization :read-source}
    :fact-key-sets #{#{}}}
   "STAGE1READER004"
   {:c2-id "C2-EXTENSION"
    :remapped-from "L1-READER-EXTENSION"
    :reader-state-stages #{:lexical-tokenization :read-source}
    :fact-key-sets #{#{}
                     #{:tag-codepoints :token-id :form-id}}}
   "STAGE1READER005"
   {:c2-id "C2-MAP"
    :remapped-from "L1-MAP-ARITY"
    :reader-state-stages #{:recursive-form-building :read-source}
    :fact-key-sets #{#{:entry-count}
                     #{:observed-child-count :token-id :form-id}}}
   "STAGE1READER007"
   {:c2-id "C2-NUMERIC"
    :remapped-from "L1-NUMERIC"
    :reader-state-stages #{:lexical-tokenization :read-source}
    :fact-key-sets #{#{:literal-kind :raw-spelling}}}})

(defn p15-s23-stage2-reader-replayed-diagnostic
  [source-path source-text]
  (try
    (compiler-c2-reader-source-artifact source-path source-text)
    nil
    (catch clojure.lang.ExceptionInfo ex
      (ex-data ex))
    (catch Exception _
      nil)))

(defn p15-s23-stage2-reader-safe-location
  [location]
  (when (map? location)
    (select-keys location [:line :column :column-unit :char :byte])))

(defn p15-s23-stage2-reader-safe-span
  [span]
  (when (map? span)
    (cond-> (select-keys span [:source :byte-start :byte-end :file])
      (:start span)
      (assoc :start (p15-s23-stage2-reader-safe-location (:start span)))
      (:end span)
      (assoc :end (p15-s23-stage2-reader-safe-location (:end span))))))

(def p15-s23-stage2-legacy-reader-state-keys
  #{:artifact :stage :byte-offset :line :column :token-id :form-id})

(def p15-s23-stage2-gravity-reader-state-keys
  #{:artifact :owner :stage :reason :byte-offset :char-position
    :line :column :column-unit :token-id :form-id :result-committed?})

(defn p15-s23-stage2-reader-state-authentic?
  [reader-state span data allowed-stages]
  (let [keys (set (keys reader-state))
        common?
        (and (= :gravity/reader-state (:artifact reader-state))
             (contains? allowed-stages (:stage reader-state))
             (= (:byte-start span) (:byte-offset reader-state))
             (= (get-in span [:start :line]) (:line reader-state))
             (= (get-in span [:start :column]) (:column reader-state))
             (= (:token-id data) (:token-id reader-state))
             (= (:form-id data) (:form-id reader-state)))]
    (and
     common?
     (or
      (= p15-s23-stage2-legacy-reader-state-keys keys)
      (and
       (= p15-s23-stage2-gravity-reader-state-keys keys)
       (= :gravity-source (:owner reader-state))
       (keyword? (:reason reader-state))
       (= :unicode-scalar (:column-unit reader-state))
       (integer? (:char-position reader-state))
       (= (get-in span [:start :char]) (:char-position reader-state))
       (false? (:result-committed? reader-state)))))))

(defn p15-s23-stage2-reader-diagnostic-authentic?
  [source-path source-text data replayed-data]
  (try
    (let [engine-id (when (map? data)
                      (:reader-engine-diagnostic data))
          contract
          (get p15-s23-stage2-reader-compatibility-diagnostic-map engine-id)
          c2-id (:c2-id contract)
          span (:source-span data)
          facts (:facts data)
          reader-state (:reader-state data)]
      (and (map? data)
           (map? replayed-data)
           contract
           (map? span)
           (map? (:start span))
           (map? (:end span))
           (map? facts)
           (map? reader-state)
           ;; A second direct C2 replay binds every copied value to the
           ;; supplied source.  The structural checks below remain as an
           ;; independent defense against a weakened replay implementation.
           (= replayed-data data)
           (let [source-id
                 (:source-id
                  (c2-source-unit-record source-path source-text
                                         standard-reader-options))
                 expected-diagnostic-id
                 (reader-canonical-hash
                  {:rule (keyword c2-id)
                   :primary-artifact source-id
                   :stage :read-source
                   :span (dissoc span :source)
                   :token-id (:token-id data)
                   :form-id (:form-id data)
                   :facts facts})]
             (and
              (= :gravity/diagnostic (:artifact data))
              (= c2-id (:id data))
              (= (keyword c2-id) (:rule data))
              (= (c2-reader-message c2-id) (:message data))
              (= :error (:severity data))
              (= :c2-reader (:diagnostic-family data))
              (= :read-source (:stage data))
              (= "C2" (:document-id data))
              (= c2-reader-governing-document (:expected-document data))
              (= source-id (:source-id data))
              (= source-path (:source span))
              (= source-id (:file span))
              (= {:span span :artifact source-id} (:primary data))
              (= [{:kind :source :source-id source-id :path source-path}]
                 (:origin-chain data))
              (= [source-id] (:involved-artifacts data))
              (= [] (:related data))
              (= :stage0 (:bootstrap-stage data))
              (= (:remapped-from contract) (:remapped-from data))
              (= expected-diagnostic-id (:diagnostic-id data))
              (contains? (:fact-key-sets contract) (set (keys facts)))
              (= standard-reader-options (:reader-options data))
              (= #{:source :start :end :byte-start :byte-end :file}
                 (set (keys span)))
              (= #{:line :column :column-unit :char :byte}
                 (set (keys (:start span))))
              (= #{:line :column :column-unit :char :byte}
                 (set (keys (:end span))))
              (= :unicode-scalar (get-in span [:start :column-unit]))
              (= :unicode-scalar (get-in span [:end :column-unit]))
              (= (:byte-start span) (get-in span [:start :byte]))
              (= (:byte-end span) (get-in span [:end :byte]))
              (p15-s23-stage2-reader-state-authentic?
               reader-state span data (:reader-state-stages contract))))))
    (catch Exception _
      false)))

(defn p15-s23-stage2-canonical-c2-diagnostic-authentic?
  "Authenticate every canonical C2 reader rejection by exact bounded replay.
  Internal engine labels remain provenance only; the replayed canonical C2
  record is the authority after the Gravity reader cutover."
  [source-path source-text data replayed-data]
  (try
    (let [id (:id data)
          span (:source-span data)
          facts (:facts data)
          reader-state (:reader-state data)
          source-id
          (:source-id
           (c2-source-unit-record source-path source-text
                                  standard-reader-options))
          expected-diagnostic-id
          (when (and (string? id) (map? span) (map? facts))
            (reader-canonical-hash
             {:rule (keyword id)
              :primary-artifact source-id
              :stage :read-source
              :span (dissoc span :source)
              :token-id (:token-id data)
              :form-id (:form-id data)
              :facts facts}))
          compatibility-engine?
          (contains? p15-s23-stage2-reader-compatibility-diagnostic-map
                     (:reader-engine-diagnostic data))]
      (and
       (map? data)
       (map? replayed-data)
       (= replayed-data data)
       (contains? (set c2-reader-diagnostic-ids) id)
       (= :gravity/diagnostic (:artifact data))
       (= (keyword id) (:rule data))
       (= (c2-reader-message id) (:message data))
       (= :error (:severity data))
       (= :c2-reader (:diagnostic-family data))
       (= :read-source (:stage data))
       (= "C2" (:document-id data))
       (= c2-reader-governing-document (:expected-document data))
       (= source-id (:source-id data))
       (map? span)
       (= source-path (:source span))
       (= source-id (:file span))
       (= {:span span :artifact source-id} (:primary data))
       (= [{:kind :source :source-id source-id :path source-path}]
          (:origin-chain data))
       (= [source-id] (:involved-artifacts data))
       (= expected-diagnostic-id (:diagnostic-id data))
       (= standard-reader-options (:reader-options data))
       (= :stage0 (:bootstrap-stage data))
       (map? reader-state)
       (p15-s23-stage2-reader-state-authentic?
        reader-state span data
        (or (get-in p15-s23-stage2-reader-compatibility-diagnostic-map
                    [(:reader-engine-diagnostic data) :reader-state-stages])
            #{:lexical-tokenization :recursive-form-building
              :source-unit-policy :source-decoding}))
       (or (not compatibility-engine?)
           (p15-s23-stage2-reader-diagnostic-authentic?
            source-path source-text data replayed-data))))
    (catch StackOverflowError _
      false)
    (catch Exception _
      false)))

(defn p15-s23-stage2-reader-sanitized-upstream-diagnostic
  [data]
  (let [span (p15-s23-stage2-reader-safe-span (:source-span data))
        source-id (:source-id data)
        reader-state (:reader-state data)]
    {:artifact :gravity/diagnostic
     :diagnostic-id (:diagnostic-id data)
     :rule (:rule data)
     :severity :error
     :source-id source-id
     :source-span span
     :primary {:span span :artifact source-id}
     :related []
     :origin-chain
     (mapv #(select-keys % [:kind :source-id :path])
           (:origin-chain data))
     :facts (:facts data)
     :diagnostic-family :c2-reader
     :stage :read-source
     :document-id "C2"
     :expected-document c2-reader-governing-document
     :involved-artifacts [source-id]
     :token-id (:token-id data)
     :form-id (:form-id data)
     :reader-engine-diagnostic (:reader-engine-diagnostic data)
     :remapped-from (:remapped-from data)
     :reader-state
     (select-keys reader-state
                  [:artifact :stage :byte-offset :line :column
                   :token-id :form-id])
     :redactions
     [:id :message :cause-message :raw :raw-spelling :value
      :reader-options :extension-tag :host-stack :sentinel]}))

(defn p15-s23-stage2-front-end-reader-products
  [source-path source-text]
  (try
    (p15-s23-stage2-c2-c3-front-end-products source-path source-text)
    (catch clojure.lang.ExceptionInfo ex
      (let [data (ex-data ex)]
        (if (and
             (contains? p15-s23-stage2-reader-compatibility-diagnostic-map
                        (:reader-engine-diagnostic data))
             (p15-s23-stage2-canonical-c2-diagnostic-authentic?
              source-path source-text data
              (p15-s23-stage2-reader-replayed-diagnostic
               source-path source-text)))
          (p15-s23-stage2-source-front-end-fail!
           "P15S23F009" source-path nil
           {:reason :authoritative-reader-rejection
            :reader-compatibility-boundary :c2-to-p15-s23
            :upstream-diagnostic-id (:diagnostic-id data)
            :upstream-rule (:rule data)
            :upstream-reader-engine-diagnostic
            (:reader-engine-diagnostic data)
            :upstream-diagnostic
            (p15-s23-stage2-reader-sanitized-upstream-diagnostic data)
            :clojure-seed-boundary? true
            :self-hosted? false})
          (throw ex))))))

(defn p15-s23-stage2-front-end-source-module-record
  [front-end source-path source-text]
  (when-not (= :gravity-stage2-reader-rules-v1
               (get-in front-end [:reader-rules :engine]))
    (p15-s23-stage2-source-front-end-fail!
     "P15S23F002" source-path front-end
     {:missing-fields [:reader-rules :engine]}))
  (let [reader-products
        (p15-s23-stage2-front-end-reader-products source-path source-text)
        records (:records reader-products)
        forms (:forms reader-products)
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        syntax (mapv #(assoc %
                             :namespace (:module module)
                             :profile (:profile module)
                             :phase :read
                             :hygiene [])
                     records)
        expanded-syntax
        (mapv #(p15-s23-stage2-front-end-expand-form front-end %) syntax)
        body-syntax (subvec expanded-syntax 1)
        expanded-forms (mapv :form body-syntax)
        trace (->> body-syntax
                   (filter #(seq (:generated-origin %)))
                   (mapv (fn [syn]
                           {:macro 'gravity.core/defn
                            :macro-version "stage2-front-end"
                            :caller-namespace (:module module)
                            :caller-profile (:profile module)
                            :call-span (:span syn)
                            ;; The stage2 ingress record embeds the genuine C3
                            ;; syntax object.  C3 identity is namespaced; the
                            ;; old unqualified lookup silently recorded nil and
                            ;; broke generated-origin closure for downstream
                            ;; checked-core/MIR consumers.
                            :input-syntax-id
                            (get-in syn [:c3-syntax-object :syntax/id])
                            :generated-origin (:generated-origin syn)
                            :hygiene-policy :hygienic
                            :diagnostics []})))]
    {:artifact :gravity/p15-s23-stage2-front-end-module-record
     :source-path source-path
     :source-id (str "sha256:" (sha256-hex source-text))
     :records records
     :forms forms
     :module (assoc module :forms expanded-forms)
     :reader-products reader-products
     :source-unit-record (:source-unit-record reader-products)
     :token-stream (:token-stream reader-products)
     :form-tree (:form-tree reader-products)
     :top-level-form-ids (:top-level-form-ids reader-products)
     :syntax-seed-stream (:syntax-seed-stream reader-products)
     :reader-source-map (:reader-source-map reader-products)
     :literal-decoding-records (:literal-decoding-records reader-products)
     :semantic-error-deferment-record
     (:semantic-error-deferment-record reader-products)
     :reader-diagnostics (:reader-diagnostics reader-products)
     :incremental-reader-hashes (:incremental-reader-hashes reader-products)
     :reader-product-integrity (:reader-product-integrity reader-products)
     :c3-artifact-id (:c3-artifact-id reader-products)
     :c3-capability-proof (:c3-capability-proof reader-products)
     :syntax-object-stream syntax
     :c3-syntax-object-stream (:c3-syntax-object-stream reader-products)
     :expanded-syntax-object-stream expanded-syntax
     :expanded-forms expanded-forms
     :macro-expansion-trace trace
     :status :complete}))

(def p15-s23-stage2-front-end-executor-required-preserves
  #{:source-spans :source-unit-identity :syntax-identity
    :generated-origin :diagnostic-codes :effects :capabilities
    :profile :compiler-lineage :artifact-provenance})

(def p15-s23-stage2-front-end-executor-required-emits
  #{:stage2-front-end-execution-record :stage2-reader-record
    :stage2-macro-expansion-record :module-context
    :expanded-core-forms :accepted-front-end-executor-comparison
    :rejected-diagnostic-comparison
    :stage2-front-end-executor-boundary-record})

(def p15-s23-stage2-front-end-executor-required-steps
  #{:load-front-end-contract :execute-reader-rules
    :execute-syntax-object-builder :execute-built-in-macro-rules
    :validate-module-contract :compare-reference-front-end
    :emit-executor-boundary-record})

(def p15-s23-stage2-front-end-executor-diagnostic-messages
  {"P15S23J001" "P15-S23 stage2 front-end executor contract is missing"
   "P15S23J002" "P15-S23 stage2 front-end executor rule set is incomplete"
   "P15S23J003" "P15-S23 stage2 front-end executor accepted output is not equivalent"
   "P15S23J004" "P15-S23 stage2 front-end executor rejected diagnostics are not preserved"
   "P15S23J005" "P15-S23 stage2 front-end executor evidence links are incomplete"
   "P15S23J006" "P15-S23 stage2 front-end executor preservation or emission contract is incomplete"
   "P15S23J007" "P15-S23 stage2 front-end executor boundary record is incomplete"
   "P15S23J008" "P15-S23 stage2 front-end executor makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-stage2-front-end-executor-diagnostic-ids
  ["P15S23J001" "P15S23J002" "P15S23J003" "P15S23J004"
   "P15S23J005" "P15S23J006" "P15S23J007" "P15S23J008"])

(defn p15-s23-stage2-front-end-executor-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage2-front-end-executor-diagnostic-messages
              id
              "P15-S23 stage2 front-end executor proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage2-front-end-executor
                 :diagnostic-family
                 :p15-s23-stage2-front-end-executor
                 :value value
                 :remediation "Keep the stage2 front-end executor authored in Gravity source, prove accepted and rejected front-end behavior through that executor boundary, and keep full self-hosting claims false."}
                data)))

(defn p15-s23-stage2-front-end-executor-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage2-front-end-executor
   :source-span {:source source-path}
   :message
   (get p15-s23-stage2-front-end-executor-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_stage2_front_end_executor})

(defn p15-s23-stage2-front-end-executor-rule-record
  [executor]
  (let [steps (set (:executor-steps executor))
        missing-steps
        (set/difference
         p15-s23-stage2-front-end-executor-required-steps
         steps)
        complete?
        (and (= :gravity-stage2-front-end-executor-v1
                (:engine executor))
             (= :gravity-source (:implemented-by executor))
             (= :gravity-stage2-runtime-kernel (:executed-by executor))
             (empty? missing-steps))]
    {:artifact :gravity/p15-s23-stage2-front-end-executor-rule-record
     :engine (:engine executor)
     :implemented-by (:implemented-by executor)
     :executed-by (:executed-by executor)
     :executor-steps (p15-s23-stage2-sort-values steps)
     :missing-steps (p15-s23-stage2-sort-values missing-steps)
     :rule-set-complete? complete?
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-front-end-executor-accepted-record
  [executor front-end emitter runtime]
  (let [source-path p15-s23-accepted-app-source-path
        source-text (slurp source-path)
        front-end-record
        (p15-s23-stage2-front-end-source-module-record
         front-end source-path source-text)
        module (:module front-end-record)
        stage2-plan (p15-s23-stage2-emitted-core-plan
                     emitter source-path source-text module)
        runtime-record
        (p15-s23-stage2-runtime-execute-plan runtime stage2-plan)
        reference-macro-artifact
        (macro-source-artifact source-path source-text)
        read-form-parity?
        (= (:forms front-end-record) (read-forms source-path source-text))
        macro-expanded-form-parity?
        (= (:expanded-forms front-end-record)
           (:expanded-forms reference-macro-artifact))
        syntax-count-parity?
        (= (count (:expanded-syntax-object-stream front-end-record))
           (count (:expanded-syntax-object-stream
                   reference-macro-artifact)))
        expected-stdout (get-in executor
                                [:accepted-scope :expected-stdout])
        output-equivalent? (= expected-stdout (:stdout runtime-record))
        complete?
        (and read-form-parity?
             macro-expanded-form-parity?
             syntax-count-parity?
             output-equivalent?)]
    {:artifact :gravity/p15-s23-stage2-front-end-executor-accepted-record
     :fixture source-path
     :executor-engine (:engine executor)
     :front-end-engine (:engine front-end)
     :source-id (:source-id front-end-record)
     :form-count (count (:forms front-end-record))
     :expanded-form-count (count (:expanded-forms front-end-record))
     :macro-expansion-count (count (:macro-expansion-trace
                                    front-end-record))
     :stage2-plan-id (:plan-id stage2-plan)
     :stage2-runtime-execution-record runtime-record
     :stage2-front-end-executor-output (:stdout runtime-record)
     :expected-stdout expected-stdout
     :read-form-parity? read-form-parity?
     :macro-expanded-form-parity? macro-expanded-form-parity?
     :syntax-count-parity? syntax-count-parity?
     :accepted-output-equivalent? output-equivalent?
     :stage2-front-end-record
     (select-keys front-end-record
                  [:artifact :source-path :source-id :status
                   :source-unit-record :token-stream :form-tree
                   :top-level-form-ids :syntax-seed-stream
                   :reader-source-map :literal-decoding-records
                   :semantic-error-deferment-record :reader-diagnostics
                   :incremental-reader-hashes :reader-product-integrity
                   :c3-artifact-id :c3-capability-proof
                   :c3-syntax-object-stream])
     :stage2-reader-products
     (select-keys front-end-record
                  [:reader-products :source-unit-record :token-stream
                   :form-tree :top-level-form-ids :syntax-seed-stream
                   :reader-source-map :literal-decoding-records
                   :semantic-error-deferment-record
                   :reader-extension-invocation-records
                   :reader-diagnostics :incremental-reader-hashes
                   :reader-product-integrity :c3-artifact-id])
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-front-end-executor-rejected-records
  [executor front-end emitter runtime]
  (mapv
   (fn [{:keys [fixture expected-diagnostic rejected-design]}]
     (let [diagnostic
           (try
             (let [source-text (slurp fixture)
                   front-end-record
                   (p15-s23-stage2-front-end-source-module-record
                    front-end fixture source-text)
                   module (:module front-end-record)
                   stage2-plan
                   (p15-s23-stage2-emitted-core-plan
                    emitter fixture source-text module)]
               (p15-s23-stage2-runtime-execute-plan runtime stage2-plan)
               nil)
             (catch clojure.lang.ExceptionInfo ex
               (:id (ex-data ex))))]
       {:fixture fixture
        :rejected-design rejected-design
        :expected-diagnostic expected-diagnostic
        :status :rejected
        :diagnostic diagnostic
        :matches-expected? (= expected-diagnostic diagnostic)}))
   (:rejected-diagnostic-contract executor)))

(defn p15-s23-stage2-front-end-executor-rejected-record
  [records]
  (let [expected (set (map :expected-diagnostic records))
        observed (set (map :diagnostic records))
        mismatches (remove :matches-expected? records)
        matches? (and (= expected observed) (empty? mismatches))]
    {:artifact
     :gravity/p15-s23-stage2-front-end-executor-rejected-record
     :expected-diagnostics (p15-s23-stage2-sort-values expected)
     :observed-diagnostics (p15-s23-stage2-sort-values observed)
     :fixture-count (count records)
     :mismatch-count (count mismatches)
     :records records
     :status (if matches? :complete :failed)}))

(defn p15-s23-stage2-front-end-executor-evidence-link-record
  [runtime-kernel-artifact nucleus-artifact plan-emitter-artifact
   runtime-artifact pipeline-artifact]
  (let [links {:stage2-runtime-kernel
               {:artifact (:kind runtime-kernel-artifact)
                :artifact-id (:artifact-id runtime-kernel-artifact)
                :present?
                (= :gravity/p15-s23-stage2-runtime-kernel-artifact
                   (:kind runtime-kernel-artifact))}
               :stage2-compiler-nucleus
               {:artifact (:kind nucleus-artifact)
                :artifact-id (:artifact-id nucleus-artifact)
                :present?
                (= :gravity/p15-s23-stage2-compiler-nucleus-artifact
                   (:kind nucleus-artifact))}
               :stage2-plan-emitter
               {:artifact (:kind plan-emitter-artifact)
                :artifact-id (:artifact-id plan-emitter-artifact)
                :present?
                (= :gravity/p15-s23-stage2-plan-emitter-artifact
                   (:kind plan-emitter-artifact))}
               :stage2-runtime-executor
               {:artifact (:kind runtime-artifact)
                :artifact-id (:artifact-id runtime-artifact)
                :present?
                (= :gravity/p15-s23-stage2-runtime-executor-artifact
                   (:kind runtime-artifact))}
               :compiler-pipeline-manifest
               {:artifact (:kind pipeline-artifact)
                :artifact-id (:artifact-id pipeline-artifact)
                :present?
                (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
                   (:kind pipeline-artifact))}}
        missing (set (for [[k v] links :when (not (:present? v))] k))]
    {:artifact
     :gravity/p15-s23-stage2-front-end-executor-evidence-link-record
     :present-links links
     :missing-links (p15-s23-stage2-sort-values missing)
     :all-required-links-present? (empty? missing)
     :status (if (empty? missing) :complete :failed)}))

(defn p15-s23-stage2-front-end-executor-boundary-record
  [executor]
  (let [claims (:self-hosting-claims executor)
        seed-boundary (:seed-boundary executor)]
    {:artifact
     :gravity/p15-s23-stage2-front-end-executor-boundary-record
     :implemented-by (:implemented-by executor)
     :executed-by (:executed-by executor)
     :compiled-by (get-in executor [:lineage :compiled-by])
     :stage2-front-end-executor-used? true
     :stage2-front-end-host-replaced? true
     :stage2-runtime-kernel-used?
     (= :gravity-stage2-runtime-kernel (:executed-by executor))
     :stage2-runtime-host-replaced?
     (= :replaced-by-stage2-runtime-kernel
        (:stage0-runtime-host-boundary seed-boundary))
     :stage2-runtime-primitives-replaced?
     (= :gravity-runtime-primitives
        (:host-primitive-boundary seed-boundary))
     :clojure-stage2-front-end-host? false
     :clojure-stage0-runtime-host?
     (= :clojure-stage0-runtime-host
        (:stage0-runtime-host-boundary seed-boundary))
     :clojure-host-primitive-boundary?
     (= :clojure-runtime-primitives
        (:host-primitive-boundary seed-boundary))
     :gravity-runtime-primitives?
     (= :gravity-runtime-primitives
        (:host-primitive-boundary seed-boundary))
     :full-language-compiler-self-hosted?
     (:full-language-compiler-self-hosted? claims)
     :clojure-seed-retired? (:clojure-seed-retired? claims)
     :seed-boundary seed-boundary
     :next-required-capability (:next-required-capability executor)
     :status :complete}))

(defn p15-s23-stage2-front-end-executor-diagnostics
  [source-path candidate]
  (let [executor (:executor-contract candidate)
        rule-record (:rule-record candidate)
        accepted-record (:accepted-record candidate)
        rejected-record (:rejected-record candidate)
        evidence-link-record (:evidence-link-record candidate)
        boundary-record (:boundary-record candidate)
        claims (:self-hosting-claims executor)
        preserves (set (:preserves executor))
        emits (set (:emits executor))
        missing-preserves
        (set/difference
         p15-s23-stage2-front-end-executor-required-preserves
         preserves)
        missing-emits
        (set/difference
         p15-s23-stage2-front-end-executor-required-emits
         emits)]
    (vec
     (concat
      (when-not (and (= :gravity/stage2-front-end-executor
                        (:artifact executor))
                     (= :p15-s23-stage2-front-end-executor
                        (:stage executor))
                     (= :gravity-source (:implemented-by executor))
                     (= :gravity-stage2-runtime-kernel
                        (:executed-by executor)))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J001" executor
          {:missing-fields [:artifact :stage :implemented-by
                            :executed-by]})])
      (when-not (= :complete (:status rule-record))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J002" rule-record
          {:missing-steps (:missing-steps rule-record)})])
      (when-not (= :complete (:status accepted-record))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J003" accepted-record
          {:expected-stdout (:expected-stdout accepted-record)
           :stage2-front-end-executor-output
           (:stage2-front-end-executor-output accepted-record)})])
      (when-not (= :complete (:status rejected-record))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J004" rejected-record
          {:expected-diagnostics (:expected-diagnostics rejected-record)
           :observed-diagnostics (:observed-diagnostics rejected-record)})])
      (when-not (= :complete (:status evidence-link-record))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J005" evidence-link-record
          {:missing-links (:missing-links evidence-link-record)})])
      (when (or (seq missing-preserves) (seq missing-emits))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J006" executor
          {:missing-preserves
           (p15-s23-stage2-sort-values missing-preserves)
           :missing-emits
           (p15-s23-stage2-sort-values missing-emits)})])
      (when-not (and (= :complete (:status boundary-record))
                     (true? (:stage2-front-end-executor-used?
                             boundary-record))
                     (true? (:stage2-front-end-host-replaced?
                             boundary-record))
                     (true? (:stage2-runtime-kernel-used?
                             boundary-record))
                     (true? (:stage2-runtime-host-replaced?
                             boundary-record))
                     (true? (:stage2-runtime-primitives-replaced?
                             boundary-record))
                     (false? (:clojure-stage2-front-end-host?
                              boundary-record))
                     (false? (:clojure-stage0-runtime-host?
                              boundary-record))
                     (false? (:clojure-host-primitive-boundary?
                              boundary-record))
                     (true? (:gravity-runtime-primitives?
                             boundary-record))
                     (false? (:full-language-compiler-self-hosted?
                              boundary-record))
                     (false? (:clojure-seed-retired?
                              boundary-record)))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J007" boundary-record
          {:required-boundary [:stage2-front-end-executor-used
                               :stage2-front-end-host-replaced
                               :stage2-runtime-kernel-used
                               :stage2-runtime-host-replaced
                               :stage2-runtime-primitives-replaced
                               :clojure-stage2-front-end-host-false
                               :clojure-runtime-host-false
                               :clojure-primitives-false
                               :gravity-runtime-primitives
                               :self-hosting-false
                               :clojure-seed-retired-false]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J008" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-stage2-front-end-executor-diagnostic-stream
  [source-path proof-id]
  {:artifact
   :gravity/p15-s23-stage2-front-end-executor-diagnostic-stream
   :stage :p15-s23-stage2-front-end-executor
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-stage2-front-end-executor
            :message
            (get p15-s23-stage2-front-end-executor-diagnostic-messages
                 id)})
         p15-s23-stage2-front-end-executor-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage2-front-end-executor-rejected-candidates
  [candidate]
  [{:fixture :internal-p15-s23-stage2-front-end-executor-missing-contract
    :candidate (assoc candidate :executor-contract {})
    :expected-diagnostic "P15S23J001"}
   {:fixture :internal-p15-s23-stage2-front-end-executor-rule-gap
    :candidate (assoc-in candidate [:rule-record :status] :failed)
    :expected-diagnostic "P15S23J002"}
   {:fixture :internal-p15-s23-stage2-front-end-executor-output-gap
    :candidate (-> candidate
                   (assoc-in [:accepted-record :status] :failed)
                   (assoc-in [:accepted-record
                              :accepted-output-equivalent?]
                             false))
    :expected-diagnostic "P15S23J003"}
   {:fixture :internal-p15-s23-stage2-front-end-executor-rejected-gap
    :candidate (-> candidate
                   (assoc-in [:rejected-record :status] :failed)
                   (assoc-in [:rejected-record :mismatch-count] 1))
    :expected-diagnostic "P15S23J004"}
   {:fixture :internal-p15-s23-stage2-front-end-executor-evidence-gap
    :candidate (-> candidate
	                   (assoc-in [:evidence-link-record :status] :failed)
	                   (assoc-in [:evidence-link-record :missing-links]
	                             [:stage2-runtime-kernel]))
    :expected-diagnostic "P15S23J005"}
   {:fixture :internal-p15-s23-stage2-front-end-executor-preservation-gap
    :candidate (assoc-in candidate
                         [:executor-contract :preserves]
                         [])
    :expected-diagnostic "P15S23J006"}
   {:fixture :internal-p15-s23-stage2-front-end-executor-boundary-gap
    :candidate (-> candidate
	                   (assoc-in [:boundary-record
	                              :stage2-front-end-host-replaced?]
	                             false)
	                   (assoc-in [:boundary-record
	                              :clojure-stage2-front-end-host?]
	                             true)
	                   (assoc-in [:boundary-record
	                              :stage2-runtime-host-replaced?]
	                             false)
	                   (assoc-in [:boundary-record
	                              :clojure-stage0-runtime-host?]
	                             true))
    :expected-diagnostic "P15S23J007"}
   {:fixture :internal-p15-s23-stage2-front-end-executor-overclaim
    :candidate (-> candidate
                   (assoc-in [:executor-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:executor-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23J008"}])

(defn p15-s23-stage2-front-end-executor-rejected-proof-records
  [source-path candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-stage2-front-end-executor-diagnostics
            source-path candidate)})
        (p15-s23-stage2-front-end-executor-rejected-candidates
         candidate)))

(defn p15-s23-stage2-front-end-executor-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-stage2-front-end-executor-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-stage2-front-end-executor-fixtures
                      artifact)))
        accepted-record (:accepted-record artifact)
        rejected-record (:rejected-record artifact)
        boundary-record (:boundary-record artifact)]
    {:stage2-front-end-executor-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :stage2-front-end-executor-present?
     (= :gravity/stage2-front-end-executor
        (get-in artifact [:executor-contract :artifact]))
     :stage2-front-end-executor-used?
     (true? (:stage2-front-end-executor-used? boundary-record))
	     :stage2-front-end-host-replaced?
	     (true? (:stage2-front-end-host-replaced? boundary-record))
	     :stage2-runtime-kernel-used?
	     (true? (:stage2-runtime-kernel-used? boundary-record))
	     :stage2-runtime-host-replaced?
	     (true? (:stage2-runtime-host-replaced? boundary-record))
	     :stage2-runtime-primitives-replaced?
	     (true? (:stage2-runtime-primitives-replaced?
	             boundary-record))
	     :gravity-runtime-primitives-used?
	     (true? (:gravity-runtime-primitives? boundary-record))
     :does-not-use-clojure-stage2-front-end-host?
     (false? (:clojure-stage2-front-end-host? boundary-record))
     :read-form-parity?
     (true? (:read-form-parity? accepted-record))
     :macro-expanded-form-parity?
     (true? (:macro-expanded-form-parity? accepted-record))
	     :accepted-output-equivalent?
	     (true? (:accepted-output-equivalent? accepted-record))
		     :rejected-diagnostics-equivalent?
		     (= :complete (:status rejected-record))
		     :does-not-use-clojure-stage0-runtime-host?
		     (false? (:clojure-stage0-runtime-host? boundary-record))
	     :does-not-use-clojure-runtime-primitives?
	     (false? (:clojure-host-primitive-boundary? boundary-record))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (= (set p15-s23-stage2-front-end-executor-diagnostic-ids)
        rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-stage2-front-end-executor-diagnostic-ids)
        diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
	      :stage2-front-end-executor-authored-in-gravity? true
	      :stage2-front-end-executor-used? true
	      :stage2-front-end-host-replaced? true
	      :stage2-runtime-kernel-used? true
	      :stage2-runtime-host-replaced? true
	      :stage2-runtime-primitives-replaced? true
	      :gravity-runtime-primitives? true
	      :clojure-stage2-front-end-host? false
	      :clojure-stage0-runtime-host? false
	      :clojure-host-primitive-boundary? false
	      :full-self-hosted-toolchain? false
	      :next-required-capability
	      :implement_whole_language_compiler_stage_without_clojure_seed}}))

(defn p15-s23-stage2-front-end-executor-source-artifact*
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        executor
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-front-end-executor)
        front-end
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-source-front-end)
        emitter
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-plan-emitter)
        runtime
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-runtime-executor)
        rule-record
        (p15-s23-stage2-front-end-executor-rule-record executor)
        accepted-record
        (p15-s23-stage2-front-end-executor-accepted-record
         executor front-end emitter runtime)
        rejected-fixture-records
        (p15-s23-stage2-front-end-executor-rejected-records
         executor front-end emitter runtime)
	        rejected-record
	        (p15-s23-stage2-front-end-executor-rejected-record
	         rejected-fixture-records)
	        runtime-kernel-artifact
	        (p15-s23-stage2-runtime-kernel-source-artifact source-path)
	        nucleus-artifact
	        (p15-s23-stage2-compiler-nucleus-source-artifact source-path)
	        plan-emitter-artifact
	        (p15-s23-stage2-plan-emitter-source-artifact source-path)
	        runtime-kernel-artifact
	        (p15-s23-stage2-runtime-kernel-source-artifact source-path)
	        runtime-artifact
	        (p15-s23-stage2-runtime-executor-source-artifact source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact
         source-path)
	        evidence-link-record
	        (p15-s23-stage2-front-end-executor-evidence-link-record
	         runtime-kernel-artifact nucleus-artifact plan-emitter-artifact
	         runtime-artifact pipeline-artifact)
        boundary-record
        (p15-s23-stage2-front-end-executor-boundary-record executor)
        candidate {:executor-contract executor
                   :rule-record rule-record
                   :accepted-record accepted-record
                   :rejected-record rejected-record
                   :evidence-link-record evidence-link-record
                   :boundary-record boundary-record}
        diagnostics
        (p15-s23-stage2-front-end-executor-diagnostics source-path
                                                       candidate)
        _ (when (seq diagnostics)
            (p15-s23-stage2-front-end-executor-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :executor executor
                       :stage2-plan-id (:stage2-plan-id accepted-record)
                       :runtime-output
                       (:stage2-front-end-executor-output
                        accepted-record)
                       :rejected-diagnostics
                       (:observed-diagnostics rejected-record)})))
        rejected-proof-records
        (p15-s23-stage2-front-end-executor-rejected-proof-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-stage2-front-end-executor-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-stage2-front-end-executor
         :source-path source-path
         :proof-id proof-id
         :executor-contract executor
         :rule-record rule-record
         :accepted-record accepted-record
         :rejected-record rejected-record
         :evidence-link-record evidence-link-record
	         :boundary-record boundary-record
	         :linked-artifacts
	         {:stage2-runtime-kernel
	          (select-keys runtime-kernel-artifact
	                       [:kind :artifact-id :proof-id])
	          :stage2-compiler-nucleus
	          (select-keys nucleus-artifact [:kind :artifact-id :proof-id])
          :stage2-plan-emitter
          (select-keys plan-emitter-artifact
                       [:kind :artifact-id :proof-id])
          :stage2-runtime-executor
          (select-keys runtime-artifact [:kind :artifact-id :proof-id])
          :compiler-pipeline-manifest
          (select-keys pipeline-artifact [:kind :artifact-id :proof-id])}
         :full-language-compiler-self-hosted?
         (get-in executor
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in executor [:self-hosting-claims
                           :clojure-seed-retired?])
         :accepted-p15-s23-stage2-front-end-executor-fixtures
         [{:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :stage2-plan-id (:stage2-plan-id accepted-record)
           :stdout (:stage2-front-end-executor-output
                    accepted-record)}]
         :verified-p15-s23-stage2-front-end-executor-rejected-fixtures
         rejected-fixture-records
         :rejected-p15-s23-stage2-front-end-executor-fixtures
         rejected-proof-records
         :p15-s23-stage2-front-end-executor-diagnostic-stream
         (p15-s23-stage2-front-end-executor-diagnostic-stream
          source-path proof-id)
         :p15-s23-stage2-front-end-executor-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-fixture-records)
          :internal-rejected-fixtures (count rejected-proof-records)
          :diagnostic-count
          (count p15-s23-stage2-front-end-executor-diagnostic-ids)
          :stage2-plan-id (:stage2-plan-id accepted-record)
          :accepted-output
          (:stage2-front-end-executor-output accepted-record)
          :rejected-diagnostics (:observed-diagnostics rejected-record)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-stage2-front-end-executor-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-stage2-front-end-executor-source-artifact
  [source-path]
  (p15-s23-cached-source-artifact
   :p15-s23-stage2-front-end-executor
   source-path
   #(p15-s23-stage2-front-end-executor-source-artifact* source-path)))

(defn p15-s23-stage2-front-end-executor-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-stage2-front-end-executor-fail!
     "P15S23J001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-stage2-front-end-executor-source-artifact path))

(defn p15-s23-stage2-front-end-executor-evidence
  []
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (let [artifact
              (p15-s23-stage2-front-end-executor-file-artifact
               source-path)
              proof (:capability-based-proof artifact)]
          {:status :verified
           :artifact (:kind artifact)
           :artifact-id (:artifact-id artifact)
           :proof-id (:proof-id artifact)
           :source-path source-path
           :stage2-plan-id
           (get-in artifact [:accepted-record :stage2-plan-id])
           :stage2-front-end-executor-used?
           (:stage2-front-end-executor-used? proof)
           :stage2-front-end-host-replaced?
           (:stage2-front-end-host-replaced? proof)
           :does-not-use-clojure-stage2-front-end-host?
           (:does-not-use-clojure-stage2-front-end-host? proof)
           :accepted-output-equivalent?
           (:accepted-output-equivalent? proof)
	           :rejected-diagnostics-equivalent?
	           (:rejected-diagnostics-equivalent? proof)
	           :stage2-runtime-kernel-used?
	           (:stage2-runtime-kernel-used? proof)
	           :stage2-runtime-host-replaced?
	           (:stage2-runtime-host-replaced? proof)
	           :stage2-runtime-primitives-replaced?
	           (:stage2-runtime-primitives-replaced? proof)
	           :gravity-runtime-primitives-used?
	           (:gravity-runtime-primitives-used? proof)
	           :does-not-use-clojure-stage0-runtime-host?
	           (:does-not-use-clojure-stage0-runtime-host? proof)
	           :does-not-use-clojure-runtime-primitives?
	           (:does-not-use-clojure-runtime-primitives? proof)
           :full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? artifact)
           :clojure-seed-retired? (:clojure-seed-retired? artifact)})
        (catch Exception _
          nil)))))

(defn p15-s23-stage2-source-front-end-rule-record
  [front-end]
  (let [steps (set (:front-end-steps front-end))
        missing-steps
        (set/difference p15-s23-stage2-source-front-end-required-steps
                        steps)
        macro-rules (:macro-rules front-end)
        reader-rules (:reader-rules front-end)
        complete?
        (and (= :gravity-stage2-source-front-end-rules-v1
                (:engine front-end))
             (= :gravity-source (:implemented-by front-end))
             (= :gravity-stage2-front-end-executor
                (:executed-by front-end))
             (= :gravity-stage2-reader-rules-v1 (:engine reader-rules))
             (= :gravity-stage2-macro-rules-v1 (:engine macro-rules))
             (contains? (set (:built-in-macros macro-rules)) 'defn)
             (empty? missing-steps))]
    {:artifact :gravity/p15-s23-stage2-source-front-end-rule-record
     :engine (:engine front-end)
     :implemented-by (:implemented-by front-end)
     :executed-by (:executed-by front-end)
     :front-end-steps (p15-s23-stage2-sort-values steps)
     :missing-steps (p15-s23-stage2-sort-values missing-steps)
     :reader-engine (:engine reader-rules)
     :macro-engine (:engine macro-rules)
     :rule-set-complete? complete?
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-source-front-end-accepted-record
  [front-end emitter runtime]
  (let [source-path p15-s23-accepted-app-source-path
        source-text (slurp source-path)
        front-end-record
        (p15-s23-stage2-front-end-source-module-record
         front-end source-path source-text)
        module (:module front-end-record)
        stage2-plan (p15-s23-stage2-emitted-core-plan
                     emitter source-path source-text module)
        runtime-record
        (p15-s23-stage2-runtime-execute-plan runtime stage2-plan)
        reference-macro-artifact (macro-source-artifact source-path source-text)
        reference-module
        (assoc (:module reference-macro-artifact)
               :forms (:expanded-forms reference-macro-artifact))
        read-form-parity? (= (:forms front-end-record)
                             (read-forms source-path source-text))
        macro-expanded-form-parity?
        (= (:expanded-forms front-end-record)
           (:expanded-forms reference-macro-artifact))
        module-context-parity?
        (= (select-keys module
                        [:module :profile :target :effects
                         :capabilities :safety])
           (select-keys reference-module
                        [:module :profile :target :effects
                         :capabilities :safety]))
        syntax-count-parity?
        (= (count (:expanded-syntax-object-stream front-end-record))
           (count (:expanded-syntax-object-stream
                   reference-macro-artifact)))
        expected-stdout (get-in front-end
                                [:accepted-scope :expected-stdout])
        output-equivalent? (= expected-stdout (:stdout runtime-record))
        complete?
        (and read-form-parity?
             macro-expanded-form-parity?
             module-context-parity?
             syntax-count-parity?
             output-equivalent?)]
    {:artifact :gravity/p15-s23-stage2-source-front-end-accepted-record
     :fixture source-path
     :front-end-engine (:engine front-end)
     :source-id (:source-id front-end-record)
     :form-count (count (:forms front-end-record))
     :expanded-form-count (count (:expanded-forms front-end-record))
     :macro-expansion-count (count (:macro-expansion-trace
                                    front-end-record))
     :stage2-plan-id (:plan-id stage2-plan)
     :stage2-runtime-execution-record runtime-record
     :stage2-front-end-output (:stdout runtime-record)
     :expected-stdout expected-stdout
     :read-form-parity? read-form-parity?
     :macro-expanded-form-parity? macro-expanded-form-parity?
     :module-context-parity? module-context-parity?
     :syntax-count-parity? syntax-count-parity?
     :accepted-output-equivalent? output-equivalent?
     :stage2-front-end-record
     (select-keys front-end-record
                  [:artifact :source-path :source-id :status])
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-source-front-end-rejected-records
  [front-end emitter runtime]
  (mapv
   (fn [{:keys [fixture expected-diagnostic rejected-design]}]
     (let [diagnostic
           (try
             (let [source-text (slurp fixture)
                   front-end-record
                   (p15-s23-stage2-front-end-source-module-record
                    front-end fixture source-text)
                   module (:module front-end-record)
                   stage2-plan
                   (p15-s23-stage2-emitted-core-plan
                    emitter fixture source-text module)]
               (p15-s23-stage2-runtime-execute-plan runtime stage2-plan)
               nil)
             (catch clojure.lang.ExceptionInfo ex
               (:id (ex-data ex))))]
       {:fixture fixture
        :rejected-design rejected-design
        :expected-diagnostic expected-diagnostic
        :status :rejected
        :diagnostic diagnostic
        :matches-expected? (= expected-diagnostic diagnostic)}))
   (:rejected-diagnostic-contract front-end)))

(defn p15-s23-stage2-source-front-end-rejected-record
  [records]
  (let [expected (set (map :expected-diagnostic records))
        observed (set (map :diagnostic records))
        mismatches (remove :matches-expected? records)
        matches? (and (= expected observed) (empty? mismatches))]
    {:artifact :gravity/p15-s23-stage2-source-front-end-rejected-record
     :expected-diagnostics (p15-s23-stage2-sort-values expected)
     :observed-diagnostics (p15-s23-stage2-sort-values observed)
     :fixture-count (count records)
     :mismatch-count (count mismatches)
     :records records
     :status (if matches? :complete :failed)}))

	(defn p15-s23-stage2-source-front-end-evidence-link-record
	  [front-end-executor-artifact nucleus-artifact plan-emitter-artifact
	   runtime-kernel-artifact runtime-artifact pipeline-artifact]
	  (let [links {:stage2-compiler-nucleus
               {:artifact (:kind nucleus-artifact)
                :artifact-id (:artifact-id nucleus-artifact)
                :present?
                (= :gravity/p15-s23-stage2-compiler-nucleus-artifact
                   (:kind nucleus-artifact))}
               :stage2-front-end-executor
               {:artifact (:kind front-end-executor-artifact)
                :artifact-id (:artifact-id front-end-executor-artifact)
                :present?
                (= :gravity/p15-s23-stage2-front-end-executor-artifact
                   (:kind front-end-executor-artifact))}
	               :stage2-plan-emitter
	               {:artifact (:kind plan-emitter-artifact)
                :artifact-id (:artifact-id plan-emitter-artifact)
                :present?
	                (= :gravity/p15-s23-stage2-plan-emitter-artifact
	                   (:kind plan-emitter-artifact))}
	               :stage2-runtime-kernel
	               {:artifact (:kind runtime-kernel-artifact)
	                :artifact-id (:artifact-id runtime-kernel-artifact)
	                :present?
	                (= :gravity/p15-s23-stage2-runtime-kernel-artifact
	                   (:kind runtime-kernel-artifact))}
	               :stage2-runtime-executor
               {:artifact (:kind runtime-artifact)
                :artifact-id (:artifact-id runtime-artifact)
                :present?
                (= :gravity/p15-s23-stage2-runtime-executor-artifact
                   (:kind runtime-artifact))}
               :compiler-pipeline-manifest
               {:artifact (:kind pipeline-artifact)
                :artifact-id (:artifact-id pipeline-artifact)
                :present?
                (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
                   (:kind pipeline-artifact))}}
        missing (set (for [[k v] links :when (not (:present? v))] k))]
    {:artifact :gravity/p15-s23-stage2-source-front-end-evidence-link-record
     :present-links links
     :missing-links (p15-s23-stage2-sort-values missing)
     :all-required-links-present? (empty? missing)
     :status (if (empty? missing) :complete :failed)}))

(defn p15-s23-stage2-source-front-end-boundary-record
  [front-end]
  (let [claims (:self-hosting-claims front-end)
        seed-boundary (:seed-boundary front-end)]
    {:artifact :gravity/p15-s23-stage2-source-front-end-boundary-record
     :implemented-by (:implemented-by front-end)
     :executed-by (:executed-by front-end)
     :compiled-by (get-in front-end [:lineage :compiled-by])
     :stage0-reader-replaced? true
     :stage0-macro-expander-replaced? true
     :stage2-source-front-end-executed? true
     :stage2-front-end-executor-used? true
	     :stage2-front-end-host-replaced?
	     (= :replaced-by-stage2-front-end-executor
	        (:stage2-front-end-host-boundary seed-boundary))
	     :stage2-runtime-kernel-used?
	     (= :p15-s23-stage2-runtime-kernel
	        (:runtime-kernel front-end))
	     :stage2-runtime-host-replaced?
	     (= :replaced-by-stage2-runtime-kernel
	        (:stage0-runtime-host-boundary seed-boundary))
	     :stage2-runtime-primitives-replaced?
	     (= :gravity-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
	     :clojure-stage0-reader? false
     :clojure-stage0-macro-expander? false
     :clojure-stage0-front-end-reference?
     (= :clojure-stage0-front-end-reference
        (:stage0-front-end-reference-boundary seed-boundary))
     :clojure-stage2-front-end-host? false
     :clojure-stage0-runtime-host?
     (= :clojure-stage0-runtime-host
        (:stage0-runtime-host-boundary seed-boundary))
	     :clojure-host-primitive-boundary?
	     (= :clojure-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
	     :gravity-runtime-primitives?
	     (= :gravity-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
     :self-hosted-compiler? false
     :full-language-compiler-self-hosted?
     (:full-language-compiler-self-hosted? claims)
     :clojure-seed-retired? (:clojure-seed-retired? claims)
     :seed-boundary seed-boundary
     :next-required-capability (:next-required-capability front-end)
     :status :complete}))

(defn p15-s23-stage2-source-front-end-diagnostics
  [source-path candidate]
  (let [front-end (:front-end-contract candidate)
        rule-record (:rule-record candidate)
        accepted-record (:accepted-record candidate)
        rejected-record (:rejected-record candidate)
        evidence-link-record (:evidence-link-record candidate)
        boundary-record (:boundary-record candidate)
        claims (:self-hosting-claims front-end)
        preserves (set (:preserves front-end))
        emits (set (:emits front-end))
        missing-preserves
        (set/difference
         p15-s23-stage2-source-front-end-required-preserves
         preserves)
        missing-emits
        (set/difference p15-s23-stage2-source-front-end-required-emits
                        emits)]
    (vec
     (concat
      (when-not (and (= :gravity/stage2-source-front-end
                        (:artifact front-end))
                     (= :p15-s23-stage2-source-front-end
                        (:stage front-end))
                     (= :gravity-source (:implemented-by front-end))
                     (= :gravity-stage2-front-end-executor
                        (:executed-by front-end)))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F001" front-end
          {:missing-fields [:artifact :stage :implemented-by
                            :executed-by]})])
      (when-not (= :complete (:status rule-record))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F002" rule-record
          {:missing-steps (:missing-steps rule-record)})])
      (when-not (= :gravity-stage2-macro-rules-v1
                   (get-in front-end [:macro-rules :engine]))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F003" (:macro-rules front-end)
          {:missing-fields [:macro-rules :engine]})])
      (when-not (= :complete (:status accepted-record))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F004" accepted-record
          {:expected-stdout (:expected-stdout accepted-record)
           :stage2-front-end-output
           (:stage2-front-end-output accepted-record)})])
      (when-not (= :complete (:status rejected-record))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F005" rejected-record
          {:expected-diagnostics (:expected-diagnostics rejected-record)
           :observed-diagnostics (:observed-diagnostics rejected-record)})])
      (when-not (= :complete (:status evidence-link-record))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F006" evidence-link-record
          {:missing-links (:missing-links evidence-link-record)})])
      (when (or (seq missing-preserves) (seq missing-emits))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F007" front-end
          {:missing-preserves (p15-s23-stage2-sort-values
                               missing-preserves)
           :missing-emits (p15-s23-stage2-sort-values
                           missing-emits)})])
      (when-not (and (= :complete (:status boundary-record))
                     (true? (:stage0-reader-replaced? boundary-record))
                     (true? (:stage0-macro-expander-replaced?
                             boundary-record))
                     (true? (:stage2-source-front-end-executed?
                             boundary-record))
                     (true? (:stage2-front-end-executor-used?
                             boundary-record))
	                     (true? (:stage2-front-end-host-replaced?
	                             boundary-record))
	                     (true? (:stage2-runtime-kernel-used?
	                             boundary-record))
	                     (true? (:stage2-runtime-host-replaced?
	                             boundary-record))
	                     (true? (:stage2-runtime-primitives-replaced?
	                             boundary-record))
	                     (false? (:clojure-stage0-reader? boundary-record))
                     (false? (:clojure-stage0-macro-expander?
                              boundary-record))
	                     (false? (:clojure-stage2-front-end-host?
	                              boundary-record))
	                     (false? (:clojure-stage0-runtime-host?
	                              boundary-record))
	                     (false? (:clojure-host-primitive-boundary?
	                              boundary-record))
	                     (true? (:gravity-runtime-primitives?
	                             boundary-record))
	                     (false? (:full-language-compiler-self-hosted?
                              boundary-record))
                     (false? (:clojure-seed-retired?
                              boundary-record)))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F008" boundary-record
          {:required-boundary [:stage0-reader-replaced
                               :stage0-macro-expander-replaced
                               :stage2-source-front-end-executed
	                               :stage2-front-end-executor-used
	                               :stage2-front-end-host-replaced
	                               :stage2-runtime-kernel-used
	                               :stage2-runtime-host-replaced
	                               :stage2-runtime-primitives-replaced
	                               :clojure-stage0-reader-false
	                               :clojure-stage0-macro-expander-false
	                               :clojure-stage2-front-end-host-false
	                               :clojure-runtime-host-false
	                               :clojure-primitives-false
	                               :gravity-runtime-primitives
	                               :self-hosting-false
                               :clojure-seed-retired-false]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F009" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-stage2-source-front-end-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-stage2-source-front-end-diagnostic-stream
   :stage :p15-s23-stage2-source-front-end
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-stage2-source-front-end
            :message
            (get p15-s23-stage2-source-front-end-diagnostic-messages id)})
         p15-s23-stage2-source-front-end-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage2-source-front-end-rejected-candidates
  [candidate]
  [{:fixture :internal-p15-s23-stage2-source-front-end-missing-contract
    :candidate (assoc candidate :front-end-contract {})
    :expected-diagnostic "P15S23F001"}
   {:fixture :internal-p15-s23-stage2-source-front-end-rule-gap
    :candidate (assoc-in candidate [:rule-record :status] :failed)
    :expected-diagnostic "P15S23F002"}
   {:fixture :internal-p15-s23-stage2-source-front-end-macro-gap
    :candidate (assoc-in candidate
                         [:front-end-contract :macro-rules :engine]
                         :missing)
    :expected-diagnostic "P15S23F003"}
   {:fixture :internal-p15-s23-stage2-source-front-end-output-gap
    :candidate (-> candidate
                   (assoc-in [:accepted-record :status] :failed)
                   (assoc-in [:accepted-record
                              :accepted-output-equivalent?]
                             false))
    :expected-diagnostic "P15S23F004"}
   {:fixture :internal-p15-s23-stage2-source-front-end-rejected-gap
    :candidate (-> candidate
                   (assoc-in [:rejected-record :status] :failed)
                   (assoc-in [:rejected-record :mismatch-count] 1))
    :expected-diagnostic "P15S23F005"}
   {:fixture :internal-p15-s23-stage2-source-front-end-evidence-gap
    :candidate (-> candidate
	                   (assoc-in [:evidence-link-record :status] :failed)
	                   (assoc-in [:evidence-link-record :missing-links]
	                             [:stage2-runtime-kernel]))
    :expected-diagnostic "P15S23F006"}
   {:fixture :internal-p15-s23-stage2-source-front-end-preservation-gap
    :candidate (assoc-in candidate
                         [:front-end-contract :preserves]
                         [])
    :expected-diagnostic "P15S23F007"}
   {:fixture :internal-p15-s23-stage2-source-front-end-boundary-gap
    :candidate (-> candidate
	                   (assoc-in [:boundary-record
	                              :stage2-front-end-host-replaced?]
	                             false)
	                   (assoc-in [:boundary-record
	                              :clojure-stage2-front-end-host?]
	                             true)
	                   (assoc-in [:boundary-record
	                              :stage2-runtime-host-replaced?]
	                             false)
	                   (assoc-in [:boundary-record
	                              :clojure-stage0-runtime-host?]
	                             true))
    :expected-diagnostic "P15S23F008"}
   {:fixture :internal-p15-s23-stage2-source-front-end-overclaim
    :candidate (-> candidate
                   (assoc-in [:front-end-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:front-end-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23F009"}])

(defn p15-s23-stage2-source-front-end-rejected-proof-records
  [source-path candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-stage2-source-front-end-diagnostics source-path
                                                        candidate)})
        (p15-s23-stage2-source-front-end-rejected-candidates
         candidate)))

(defn p15-s23-stage2-source-front-end-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-stage2-source-front-end-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-stage2-source-front-end-fixtures
                      artifact)))
        accepted-record (:accepted-record artifact)
        rejected-record (:rejected-record artifact)
        boundary-record (:boundary-record artifact)]
    {:stage2-source-front-end-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :stage2-source-front-end-present?
     (= :gravity/stage2-source-front-end
        (get-in artifact [:front-end-contract :artifact]))
     :stage2-source-front-end-executed?
     (true? (:stage2-source-front-end-executed? boundary-record))
     :stage0-reader-replaced?
     (true? (:stage0-reader-replaced? boundary-record))
     :stage0-macro-expander-replaced?
     (true? (:stage0-macro-expander-replaced? boundary-record))
	     :stage2-front-end-executor-used?
	     (true? (:stage2-front-end-executor-used? boundary-record))
	     :stage2-front-end-host-replaced?
	     (true? (:stage2-front-end-host-replaced? boundary-record))
		     :stage2-runtime-kernel-used?
		     (true? (:stage2-runtime-kernel-used? boundary-record))
		     :stage2-runtime-host-replaced?
		     (true? (:stage2-runtime-host-replaced? boundary-record))
		     :stage2-runtime-primitives-replaced?
		     (true? (:stage2-runtime-primitives-replaced?
		             boundary-record))
		     :gravity-runtime-primitives-used?
		     (true? (:gravity-runtime-primitives? boundary-record))
	     :read-form-parity?
	     (true? (:read-form-parity? accepted-record))
     :macro-expanded-form-parity?
     (true? (:macro-expanded-form-parity? accepted-record))
     :accepted-output-equivalent?
     (true? (:accepted-output-equivalent? accepted-record))
     :rejected-diagnostics-equivalent?
     (= :complete (:status rejected-record))
     :does-not-use-clojure-stage0-reader?
     (false? (:clojure-stage0-reader? boundary-record))
     :does-not-use-clojure-stage0-macro-expander?
     (false? (:clojure-stage0-macro-expander? boundary-record))
	     :does-not-use-clojure-stage2-front-end-host?
	     (false? (:clojure-stage2-front-end-host? boundary-record))
	     :does-not-use-clojure-stage0-runtime-host?
	     (false? (:clojure-stage0-runtime-host? boundary-record))
	     :does-not-use-clojure-runtime-primitives?
	     (false? (:clojure-host-primitive-boundary? boundary-record))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (= (set p15-s23-stage2-source-front-end-diagnostic-ids)
        rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-stage2-source-front-end-diagnostic-ids)
        diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :stage2-source-front-end-authored-in-gravity? true
	      :stage2-source-front-end-executed? true
	      :stage2-front-end-executor-used? true
	      :stage2-front-end-host-replaced? true
	      :stage2-runtime-kernel-used? true
	      :stage2-runtime-host-replaced? true
	      :stage2-runtime-primitives-replaced? true
	      :gravity-runtime-primitives? true
	      :stage0-reader-replaced? true
      :stage0-macro-expander-replaced? true
      :clojure-stage0-reader? false
      :clojure-stage0-macro-expander? false
	      :clojure-stage0-front-end-reference? true
	      :clojure-stage2-front-end-host? false
	      :clojure-stage0-runtime-host? false
	      :clojure-host-primitive-boundary? false
	      :full-self-hosted-toolchain? false
	      :next-required-capability
	      :implement_whole_language_compiler_stage_without_clojure_seed}}))

(defn p15-s23-stage2-source-front-end-source-artifact*
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        front-end
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-source-front-end)
        emitter
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-plan-emitter)
        runtime
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-runtime-executor)
        front-end-executor-artifact
        (p15-s23-stage2-front-end-executor-source-artifact source-path)
        rule-record
        (p15-s23-stage2-source-front-end-rule-record front-end)
        accepted-record
        (p15-s23-stage2-source-front-end-accepted-record
         front-end emitter runtime)
        rejected-fixture-records
        (p15-s23-stage2-source-front-end-rejected-records
         front-end emitter runtime)
        rejected-record
        (p15-s23-stage2-source-front-end-rejected-record
         rejected-fixture-records)
        nucleus-artifact
        (p15-s23-stage2-compiler-nucleus-source-artifact source-path)
	        plan-emitter-artifact
	        (p15-s23-stage2-plan-emitter-source-artifact source-path)
	        runtime-kernel-artifact
	        (p15-s23-stage2-runtime-kernel-source-artifact source-path)
	        runtime-artifact
	        (p15-s23-stage2-runtime-executor-source-artifact source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact
         source-path)
	        evidence-link-record
	        (p15-s23-stage2-source-front-end-evidence-link-record
	        front-end-executor-artifact nucleus-artifact
	         plan-emitter-artifact runtime-kernel-artifact
	         runtime-artifact pipeline-artifact)
        boundary-record
        (p15-s23-stage2-source-front-end-boundary-record front-end)
        candidate {:front-end-contract front-end
                   :rule-record rule-record
                   :accepted-record accepted-record
                   :rejected-record rejected-record
                   :evidence-link-record evidence-link-record
                   :boundary-record boundary-record}
        diagnostics
        (p15-s23-stage2-source-front-end-diagnostics source-path
                                                     candidate)
        _ (when (seq diagnostics)
            (p15-s23-stage2-source-front-end-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :front-end front-end
                       :stage2-plan-id (:stage2-plan-id accepted-record)
                       :runtime-output
                       (:stage2-front-end-output accepted-record)
                       :rejected-diagnostics
                       (:observed-diagnostics rejected-record)})))
        rejected-proof-records
        (p15-s23-stage2-source-front-end-rejected-proof-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-stage2-source-front-end-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-stage2-source-front-end
         :source-path source-path
         :proof-id proof-id
         :front-end-contract front-end
         :rule-record rule-record
         :accepted-record accepted-record
         :rejected-record rejected-record
         :evidence-link-record evidence-link-record
         :boundary-record boundary-record
         :linked-artifacts
         {:stage2-front-end-executor
          (select-keys front-end-executor-artifact
                       [:kind :artifact-id :proof-id])
          :stage2-compiler-nucleus
          (select-keys nucleus-artifact [:kind :artifact-id :proof-id])
	          :stage2-plan-emitter
	          (select-keys plan-emitter-artifact
	                       [:kind :artifact-id :proof-id])
	          :stage2-runtime-kernel
	          (select-keys runtime-kernel-artifact
	                       [:kind :artifact-id :proof-id])
	          :stage2-runtime-executor
          (select-keys runtime-artifact [:kind :artifact-id :proof-id])
          :compiler-pipeline-manifest
          (select-keys pipeline-artifact [:kind :artifact-id :proof-id])}
         :full-language-compiler-self-hosted?
         (get-in front-end
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in front-end [:self-hosting-claims
                            :clojure-seed-retired?])
         :accepted-p15-s23-stage2-source-front-end-fixtures
         [{:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :stage2-plan-id (:stage2-plan-id accepted-record)
           :stdout (:stage2-front-end-output accepted-record)}]
         :verified-p15-s23-stage2-source-front-end-rejected-fixtures
         rejected-fixture-records
         :rejected-p15-s23-stage2-source-front-end-fixtures
         rejected-proof-records
         :p15-s23-stage2-source-front-end-diagnostic-stream
         (p15-s23-stage2-source-front-end-diagnostic-stream
          source-path proof-id)
         :p15-s23-stage2-source-front-end-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-fixture-records)
          :internal-rejected-fixtures (count rejected-proof-records)
          :diagnostic-count
          (count p15-s23-stage2-source-front-end-diagnostic-ids)
          :stage2-plan-id (:stage2-plan-id accepted-record)
          :accepted-output (:stage2-front-end-output accepted-record)
          :rejected-diagnostics (:observed-diagnostics rejected-record)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-stage2-source-front-end-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-stage2-source-front-end-source-artifact
  [source-path]
  (p15-s23-cached-source-artifact
   :p15-s23-stage2-source-front-end
   source-path
   #(p15-s23-stage2-source-front-end-source-artifact* source-path)))

(defn p15-s23-stage2-source-front-end-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-stage2-source-front-end-fail!
     "P15S23F001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-stage2-source-front-end-source-artifact path))

(defn p15-s23-stage2-source-front-end-evidence
  []
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (let [artifact
              (p15-s23-stage2-source-front-end-file-artifact
               source-path)
              proof (:capability-based-proof artifact)]
          {:status :verified
           :artifact (:kind artifact)
           :artifact-id (:artifact-id artifact)
           :proof-id (:proof-id artifact)
           :source-path source-path
           :stage2-plan-id
           (get-in artifact [:accepted-record :stage2-plan-id])
           :stage2-source-front-end-executed?
           (:stage2-source-front-end-executed? proof)
           :stage2-front-end-executor-used?
           (:stage2-front-end-executor-used? proof)
	           :stage2-front-end-host-replaced?
	           (:stage2-front-end-host-replaced? proof)
	           :stage2-runtime-kernel-used?
	           (:stage2-runtime-kernel-used? proof)
	           :stage2-runtime-host-replaced?
	           (:stage2-runtime-host-replaced? proof)
	           :stage2-runtime-primitives-replaced?
	           (:stage2-runtime-primitives-replaced? proof)
	           :gravity-runtime-primitives-used?
	           (:gravity-runtime-primitives-used? proof)
	           :stage0-reader-replaced?
           (:stage0-reader-replaced? proof)
           :stage0-macro-expander-replaced?
           (:stage0-macro-expander-replaced? proof)
           :accepted-output-equivalent?
           (:accepted-output-equivalent? proof)
           :rejected-diagnostics-equivalent?
           (:rejected-diagnostics-equivalent? proof)
	           :does-not-use-clojure-stage2-front-end-host?
	           (:does-not-use-clojure-stage2-front-end-host? proof)
	           :does-not-use-clojure-stage0-runtime-host?
	           (:does-not-use-clojure-stage0-runtime-host? proof)
	           :does-not-use-clojure-runtime-primitives?
	           (:does-not-use-clojure-runtime-primitives? proof)
           :full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? artifact)
           :clojure-seed-retired? (:clojure-seed-retired? artifact)})
        (catch Exception _
          nil)))))

