(def p15-s23-stage2-compiler-driver-diagnostic-messages
  {"P15S23Y001" "P15-S23 stage2 compiler driver contract is missing"
   "P15S23Y002" "P15-S23 stage2 compiler driver step set is incomplete"
   "P15S23Y003" "P15-S23 stage2 compiler driver accepted execution is not equivalent"
   "P15S23Y004" "P15-S23 stage2 compiler driver rejected diagnostics are not preserved"
   "P15S23Y005" "P15-S23 stage2 compiler driver evidence links are incomplete"
   "P15S23Y006" "P15-S23 stage2 compiler driver preservation or emission contract is incomplete"
   "P15S23Y007" "P15-S23 stage2 compiler driver residual boundary record is incomplete"
   "P15S23Y008" "P15-S23 stage2 compiler driver makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-stage2-compiler-driver-diagnostic-ids
  ["P15S23Y001" "P15S23Y002" "P15S23Y003" "P15S23Y004"
   "P15S23Y005" "P15S23Y006" "P15S23Y007" "P15S23Y008"])

(defn p15-s23-stage2-compiler-driver-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage2-compiler-driver-diagnostic-messages
              id
              "P15-S23 stage2 compiler driver proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage2-compiler-driver
                 :diagnostic-family :p15-s23-stage2-compiler-driver
                 :value value
                 :remediation "Keep the stage2 compiler driver authored in Gravity source, execute accepted and rejected fixtures through the declared hosted driver boundary, record residual Clojure seed surfaces, and keep full self-hosting claims false."}
                data)))

(defn p15-s23-stage2-compiler-driver-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage2-compiler-driver
   :source-span {:source source-path}
   :message (get p15-s23-stage2-compiler-driver-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_stage2_compiler_driver})

(defn p15-s23-stage2-compiler-driver-rule-record
  [driver]
  (let [steps (set (:driver-steps driver))
        uses (set (get-in driver [:execution-contract :uses]))
        missing-steps
        (set/difference p15-s23-stage2-compiler-driver-required-steps
                        steps)
	        required-uses #{:stage2-front-end-executor
	                        :stage2-source-front-end
	                        :stage2-plan-emitter
	                        :stage2-runtime-kernel
	                        :stage2-runtime-executor}
        missing-uses (set/difference required-uses uses)
        complete?
        (and (= :gravity-stage2-compiler-driver-rules-v1
                (:engine driver))
             (= :gravity-source (:implemented-by driver))
             (= :clojure-stage0-driver-host (:executed-by driver))
             (empty? missing-steps)
             (empty? missing-uses))]
    {:artifact :gravity/p15-s23-stage2-compiler-driver-rule-record
     :engine (:engine driver)
     :implemented-by (:implemented-by driver)
     :executed-by (:executed-by driver)
     :driver-steps (p15-s23-stage2-sort-values steps)
     :uses (p15-s23-stage2-sort-values uses)
     :missing-steps (p15-s23-stage2-sort-values missing-steps)
     :missing-uses (p15-s23-stage2-sort-values missing-uses)
     :rule-set-complete? complete?
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-compiler-driver-run-source
  [driver front-end emitter runtime source-path source-text]
  (let [front-end-record
        (p15-s23-stage2-front-end-source-module-record
         front-end source-path source-text)
        module (:module front-end-record)
        stage2-plan (p15-s23-stage2-emitted-core-plan
                     emitter source-path source-text module)
        stage2-runtime-record
        (p15-s23-stage2-runtime-execute-plan runtime stage2-plan)
        stage0-plan (stage0-compiled-core-plan source-path source-text module)
        stage0-output (execute-stage0-compiled-plan stage0-plan)
        ;; The declared accepted-scope stdout is normative for the canonical
        ;; core-app fixture only.  The public stage2 driver may also be used
        ;; for another accepted source unit; in that case the stage0 result is
        ;; the comparison oracle while the contract still governs the driver
        ;; steps and boundaries.
        expected-stdout (if (= (str source-path)
                               (str p15-s23-accepted-app-source-path))
                          (get-in driver [:accepted-scope
                                          :expected-stdout])
                          stage0-output)
        normalized-stage2-bindings
        (mapv #(assoc % :visibility :local)
              (:binding-table stage2-plan))
        normalized-stage0-bindings
        (mapv #(assoc % :visibility :local)
              (:binding-table stage0-plan))
        binding-table-equivalent?
        (= normalized-stage2-bindings normalized-stage0-bindings)
        function-instructions-equivalent?
        (= (update-vals (:functions stage2-plan)
                        #(select-keys % [:params :body :arity
                                         :body-form-count :instructions]))
           (update-vals (:functions stage0-plan)
                        #(select-keys % [:params :body :arity
                                         :body-form-count :instructions])))
        instruction-summary-equivalent?
        (= (:instruction-summary stage2-plan)
           (:instruction-summary stage0-plan))
        effect-summary-equivalent?
        (= (:effect-summary stage2-plan)
           (:effect-summary stage0-plan))
        accepted-output-equivalent?
        (and (= (:stdout stage2-runtime-record) stage0-output)
             (= (:stdout stage2-runtime-record) expected-stdout))
        complete?
        (and binding-table-equivalent?
             function-instructions-equivalent?
             instruction-summary-equivalent?
             effect-summary-equivalent?
             accepted-output-equivalent?)]
    {:artifact :gravity/p15-s23-stage2-compiler-driver-run-record
     :fixture source-path
     :driver-engine (:engine driver)
     :driver-steps (:driver-steps driver)
     :source-id (str "sha256:" (sha256-hex source-text))
     :stage2-plan-id (:plan-id stage2-plan)
     ;; Keep the actual products available to downstream target lowerers.  The
     ;; driver remains the owner of plan emission and runtime execution; these
     ;; fields are intentionally not included in the identity hash.
     :stage2-plan stage2-plan
     :stage0-plan-id (:plan-id stage0-plan)
     :stage2-plan-kind (:kind stage2-plan)
     :stage0-plan-kind (:kind stage0-plan)
     :entrypoint (:entrypoint stage2-plan)
     :stage2-source-front-end-record
     (select-keys front-end-record
                  [:artifact :source-path :source-id :status])
     :stage2-runtime-execution-record stage2-runtime-record
     :stage2-driver-output (:stdout stage2-runtime-record)
     :stage0-reference-output stage0-output
     :expected-stdout expected-stdout
     :stage2-source-front-end-executed? true
     :stage2-plan-emitted? true
     :stage2-runtime-executed? true
     :binding-table-equivalent? binding-table-equivalent?
     :binding-table-visibility-normalized? true
     :function-instructions-equivalent?
     function-instructions-equivalent?
     :instruction-summary-equivalent?
     instruction-summary-equivalent?
     :effect-summary-equivalent? effect-summary-equivalent?
     :accepted-output-equivalent? accepted-output-equivalent?
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-compiler-driver-accepted-record
  [driver front-end emitter runtime]
  (p15-s23-stage2-compiler-driver-run-source
   driver
   front-end
   emitter
   runtime
   p15-s23-accepted-app-source-path
   (slurp p15-s23-accepted-app-source-path)))

(defn p15-s23-stage2-compiler-driver-rejected-records
  [driver front-end emitter runtime]
  (mapv
   (fn [{:keys [fixture expected-diagnostic rejected-design]}]
     (try
       (let [source-text (slurp fixture)
             run-record
             (p15-s23-stage2-compiler-driver-run-source
              driver front-end emitter runtime fixture source-text)]
         {:fixture fixture
          :rejected-design rejected-design
          :expected-diagnostic expected-diagnostic
          :status :accepted-unexpectedly
          :run-record run-record
          :matches-expected? false})
       (catch clojure.lang.ExceptionInfo ex
         (let [data (ex-data ex)
               diagnostic (:id data)]
           {:fixture fixture
            :rejected-design rejected-design
            :expected-diagnostic expected-diagnostic
            :status :rejected
            :diagnostic diagnostic
            :message (:message data)
            :diagnostic-data data
            :matches-expected? (= expected-diagnostic diagnostic)}))))
   (:rejected-diagnostic-contract driver)))

(defn p15-s23-stage2-compiler-driver-rejected-record
  [records]
  (let [expected (set (map :expected-diagnostic records))
        observed (set (map :diagnostic records))
        mismatches (remove :matches-expected? records)
        matches? (and (= expected observed) (empty? mismatches))]
    {:artifact :gravity/p15-s23-stage2-compiler-driver-rejected-record
     :expected-diagnostics (p15-s23-stage2-sort-values expected)
     :observed-diagnostics (p15-s23-stage2-sort-values observed)
     :fixture-count (count records)
     :mismatch-count (count mismatches)
     :records records
     :status (if matches? :complete :failed)}))

	(defn p15-s23-stage2-compiler-driver-evidence-link-record
	  [front-end-executor-artifact front-end-artifact
	   runtime-kernel-artifact runtime-artifact plan-emitter-artifact
	   nucleus-artifact pipeline-artifact accepted-artifact
	   rejected-artifact]
  (let [links {:stage2-source-front-end
               {:artifact (:kind front-end-artifact)
                :artifact-id (:artifact-id front-end-artifact)
                :present?
                (= :gravity/p15-s23-stage2-source-front-end-artifact
                   (:kind front-end-artifact))}
               :stage2-front-end-executor
               {:artifact (:kind front-end-executor-artifact)
                :artifact-id (:artifact-id front-end-executor-artifact)
                :present?
                (= :gravity/p15-s23-stage2-front-end-executor-artifact
                   (:kind front-end-executor-artifact))}
	               :stage2-runtime-executor
	               {:artifact (:kind runtime-artifact)
                :artifact-id (:artifact-id runtime-artifact)
                :present?
	                (= :gravity/p15-s23-stage2-runtime-executor-artifact
	                   (:kind runtime-artifact))}
	               :stage2-runtime-kernel
	               {:artifact (:kind runtime-kernel-artifact)
	                :artifact-id (:artifact-id runtime-kernel-artifact)
	                :present?
	                (= :gravity/p15-s23-stage2-runtime-kernel-artifact
	                   (:kind runtime-kernel-artifact))}
	               :stage2-plan-emitter
               {:artifact (:kind plan-emitter-artifact)
                :artifact-id (:artifact-id plan-emitter-artifact)
                :present?
                (= :gravity/p15-s23-stage2-plan-emitter-artifact
                   (:kind plan-emitter-artifact))}
               :stage2-compiler-nucleus
               {:artifact (:kind nucleus-artifact)
                :artifact-id (:artifact-id nucleus-artifact)
                :present?
                (= :gravity/p15-s23-stage2-compiler-nucleus-artifact
                   (:kind nucleus-artifact))}
               :compiler-pipeline-manifest
               {:artifact (:kind pipeline-artifact)
                :artifact-id (:artifact-id pipeline-artifact)
                :present?
                (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
                   (:kind pipeline-artifact))}
               :accepted-app-execution-proof
               {:artifact (:kind accepted-artifact)
                :artifact-id (:artifact-id accepted-artifact)
                :present?
                (= :gravity/p15-s23-accepted-app-execution-artifact
                   (:kind accepted-artifact))}
               :rejected-app-diagnostic-proof
               {:artifact (:kind rejected-artifact)
                :artifact-id (:artifact-id rejected-artifact)
                :present?
                (= :gravity/p15-s23-rejected-app-diagnostic-artifact
                   (:kind rejected-artifact))}}
        missing (set (for [[k v] links :when (not (:present? v))] k))]
    {:artifact :gravity/p15-s23-stage2-compiler-driver-evidence-link-record
     :present-links links
     :missing-links (p15-s23-stage2-sort-values missing)
     :all-required-links-present? (empty? missing)
     :status (if (empty? missing) :complete :failed)}))

(defn p15-s23-stage2-compiler-driver-boundary-record
  [driver]
  (let [claims (:self-hosting-claims driver)
        seed-boundary (:seed-boundary driver)]
    {:artifact :gravity/p15-s23-stage2-compiler-driver-boundary-record
     :implemented-by (:implemented-by driver)
     :executed-by (:executed-by driver)
     :compiled-by (get-in driver [:lineage :compiled-by])
     :stage0-compiler-driver-replaced? true
     :stage0-rule-runner-replaced? true
     :stage0-reader-replaced? true
     :stage0-macro-expander-replaced? true
     :stage2-compiler-driver-executed? true
     :stage2-front-end-executor-used? true
     :stage2-front-end-host-replaced?
     (= :replaced-by-stage2-front-end-executor
        (:stage2-front-end-host-boundary seed-boundary))
	     :stage2-source-front-end-used? true
	     :stage2-plan-emitter-used? true
	     :stage2-runtime-kernel-used?
	     (= :p15-s23-stage2-runtime-kernel
	        (:runtime-kernel driver))
	     :stage2-runtime-executor-used? true
	     :stage2-runtime-host-replaced?
	     (= :replaced-by-stage2-runtime-kernel
	        (:stage0-runtime-host-boundary seed-boundary))
	     :stage2-runtime-primitives-replaced?
	     (= :gravity-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
     :clojure-stage0-driver-host?
     (= :clojure-stage0-driver-host (:executed-by driver))
     :clojure-stage0-rule-runner? false
     :clojure-stage0-reader? false
     :clojure-stage0-macro-expander? false
     :clojure-stage2-front-end-host? false
     :clojure-stage0-runtime-host?
     (= :clojure-stage0-runtime-host
        (:stage0-runtime-host-boundary seed-boundary))
	     :clojure-host-primitive-boundary?
	     (= :clojure-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
	     :gravity-runtime-primitives?
	     (= :gravity-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
     :self-hosted-compiler? false
     :full-language-compiler-self-hosted?
     (:full-language-compiler-self-hosted? claims)
     :clojure-seed-retired? (:clojure-seed-retired? claims)
     :seed-boundary seed-boundary
     :next-required-capability (:next-required-capability driver)
     :status :complete}))

(defn p15-s23-stage2-compiler-driver-diagnostics
  [source-path candidate]
  (let [driver (:driver-contract candidate)
        rule-record (:rule-record candidate)
        accepted-record (:accepted-record candidate)
        rejected-record (:rejected-record candidate)
        evidence-link-record (:evidence-link-record candidate)
        boundary-record (:boundary-record candidate)
        claims (:self-hosting-claims driver)
        preserves (set (:preserves driver))
        emits (set (:emits driver))
        missing-preserves
        (set/difference
         p15-s23-stage2-compiler-driver-required-preserves
         preserves)
        missing-emits
        (set/difference p15-s23-stage2-compiler-driver-required-emits
                        emits)]
    (vec
     (concat
      (when-not (and (= :gravity/stage2-compiler-driver
                        (:artifact driver))
                     (= :p15-s23-stage2-compiler-driver
                        (:stage driver))
                     (= :gravity-source (:implemented-by driver))
                     (= :clojure-stage0-driver-host
                        (:executed-by driver)))
        [(p15-s23-stage2-compiler-driver-diagnostic-record
          source-path "P15S23Y001" driver
          {:missing-fields [:artifact :stage :implemented-by
                            :executed-by]})])
      (when-not (= :complete (:status rule-record))
        [(p15-s23-stage2-compiler-driver-diagnostic-record
          source-path "P15S23Y002" rule-record
          {:missing-steps (:missing-steps rule-record)
           :missing-uses (:missing-uses rule-record)})])
      (when-not (= :complete (:status accepted-record))
        [(p15-s23-stage2-compiler-driver-diagnostic-record
          source-path "P15S23Y003" accepted-record
          {:stage2-driver-output
           (:stage2-driver-output accepted-record)
           :stage0-reference-output
           (:stage0-reference-output accepted-record)
           :expected-stdout (:expected-stdout accepted-record)})])
      (when-not (= :complete (:status rejected-record))
        [(p15-s23-stage2-compiler-driver-diagnostic-record
          source-path "P15S23Y004" rejected-record
          {:expected-diagnostics (:expected-diagnostics rejected-record)
           :observed-diagnostics (:observed-diagnostics rejected-record)})])
      (when-not (= :complete (:status evidence-link-record))
        [(p15-s23-stage2-compiler-driver-diagnostic-record
          source-path "P15S23Y005" evidence-link-record
          {:missing-links (:missing-links evidence-link-record)})])
      (when (or (seq missing-preserves) (seq missing-emits))
        [(p15-s23-stage2-compiler-driver-diagnostic-record
          source-path "P15S23Y006" driver
          {:missing-preserves (p15-s23-stage2-sort-values
                               missing-preserves)
           :missing-emits (p15-s23-stage2-sort-values
                           missing-emits)})])
      (when-not (and (= :complete (:status boundary-record))
                     (true? (:stage0-compiler-driver-replaced?
                             boundary-record))
                     (true? (:stage0-rule-runner-replaced?
                             boundary-record))
                     (true? (:stage0-reader-replaced?
                             boundary-record))
                     (true? (:stage0-macro-expander-replaced?
                             boundary-record))
	                     (true? (:stage2-compiler-driver-executed?
	                             boundary-record))
	                     (true? (:stage2-front-end-executor-used?
	                             boundary-record))
	                     (true? (:stage2-front-end-host-replaced?
	                             boundary-record))
		                     (true? (:stage2-source-front-end-used?
		                             boundary-record))
	                     (true? (:stage2-runtime-kernel-used?
	                             boundary-record))
	                     (true? (:stage2-runtime-host-replaced?
	                             boundary-record))
	                     (true? (:stage2-runtime-primitives-replaced?
	                             boundary-record))
	                     (true? (:clojure-stage0-driver-host?
	                             boundary-record))
                     (false? (:clojure-stage0-rule-runner?
                              boundary-record))
                     (false? (:clojure-stage0-reader?
                              boundary-record))
                     (false? (:clojure-stage0-macro-expander?
                              boundary-record))
		                     (false? (:clojure-stage2-front-end-host?
		                              boundary-record))
	                     (false? (:clojure-stage0-runtime-host?
	                              boundary-record))
	                     (false? (:clojure-host-primitive-boundary?
	                              boundary-record))
	                     (true? (:gravity-runtime-primitives?
	                             boundary-record))
                     (false? (:full-language-compiler-self-hosted?
                              boundary-record))
                     (false? (:clojure-seed-retired?
                              boundary-record)))
        [(p15-s23-stage2-compiler-driver-diagnostic-record
          source-path "P15S23Y007" boundary-record
          {:required-boundary [:stage0-compiler-driver-replaced
                               :stage0-rule-runner-replaced
	                               :stage0-reader-replaced
	                               :stage0-macro-expander-replaced
	                               :stage2-compiler-driver-executed
	                               :stage2-front-end-executor-used
		                               :stage2-front-end-host-replaced
		                               :stage2-source-front-end-used
	                               :stage2-runtime-kernel-used
	                               :stage2-runtime-host-replaced
	                               :stage2-runtime-primitives-replaced
	                               :clojure-stage0-driver-host
                               :clojure-stage0-rule-runner-false
                               :clojure-stage0-reader-false
                               :clojure-stage0-macro-expander-false
		                               :clojure-stage2-front-end-host-false
	                               :clojure-runtime-host-false
	                               :clojure-primitives-false
	                               :gravity-runtime-primitives
	                               :self-hosting-false
                               :clojure-seed-retired-false]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-stage2-compiler-driver-diagnostic-record
          source-path "P15S23Y008" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-stage2-compiler-driver-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-stage2-compiler-driver-diagnostic-stream
   :stage :p15-s23-stage2-compiler-driver
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-stage2-compiler-driver
            :message
            (get p15-s23-stage2-compiler-driver-diagnostic-messages id)})
         p15-s23-stage2-compiler-driver-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage2-compiler-driver-rejected-candidates
  [candidate]
  [{:fixture :internal-p15-s23-stage2-compiler-driver-missing-contract
    :candidate (assoc candidate :driver-contract {})
    :expected-diagnostic "P15S23Y001"}
   {:fixture :internal-p15-s23-stage2-compiler-driver-step-gap
    :candidate (assoc-in candidate [:rule-record :status] :failed)
    :expected-diagnostic "P15S23Y002"}
   {:fixture :internal-p15-s23-stage2-compiler-driver-output-gap
    :candidate (-> candidate
                   (assoc-in [:accepted-record :status] :failed)
                   (assoc-in [:accepted-record
                              :accepted-output-equivalent?]
                             false))
    :expected-diagnostic "P15S23Y003"}
   {:fixture :internal-p15-s23-stage2-compiler-driver-rejected-gap
    :candidate (-> candidate
                   (assoc-in [:rejected-record :status] :failed)
                   (assoc-in [:rejected-record :mismatch-count] 1))
    :expected-diagnostic "P15S23Y004"}
   {:fixture :internal-p15-s23-stage2-compiler-driver-evidence-gap
    :candidate (-> candidate
	                   (assoc-in [:evidence-link-record :status] :failed)
	                   (assoc-in [:evidence-link-record :missing-links]
	                             [:stage2-runtime-kernel]))
    :expected-diagnostic "P15S23Y005"}
   {:fixture :internal-p15-s23-stage2-compiler-driver-preservation-gap
    :candidate (assoc-in candidate [:driver-contract :preserves] [])
    :expected-diagnostic "P15S23Y006"}
   {:fixture :internal-p15-s23-stage2-compiler-driver-boundary-gap
    :candidate (-> candidate
	                   (assoc-in [:boundary-record
	                              :stage2-front-end-host-replaced?]
	                             false)
	                   (assoc-in [:boundary-record
	                              :clojure-stage2-front-end-host?]
	                             true)
	                   (assoc-in [:boundary-record
	                              :stage2-runtime-host-replaced?]
	                             false)
	                   (assoc-in [:boundary-record
	                              :clojure-stage0-runtime-host?]
	                             true))
    :expected-diagnostic "P15S23Y007"}
   {:fixture :internal-p15-s23-stage2-compiler-driver-overclaim
    :candidate (-> candidate
                   (assoc-in [:driver-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:driver-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23Y008"}])

(defn p15-s23-stage2-compiler-driver-rejected-proof-records
  [source-path candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-stage2-compiler-driver-diagnostics source-path
                                                       candidate)})
        (p15-s23-stage2-compiler-driver-rejected-candidates
         candidate)))

(defn p15-s23-stage2-compiler-driver-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-stage2-compiler-driver-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-stage2-compiler-driver-fixtures
                      artifact)))
        accepted-record (:accepted-record artifact)
        rejected-record (:rejected-record artifact)
        boundary-record (:boundary-record artifact)]
    {:stage2-compiler-driver-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :stage2-compiler-driver-present?
     (= :gravity/stage2-compiler-driver
        (get-in artifact [:driver-contract :artifact]))
     :stage2-compiler-driver-executed?
     (true? (:stage2-compiler-driver-executed?
             boundary-record))
     :stage0-compiler-driver-replaced?
     (true? (:stage0-compiler-driver-replaced?
             boundary-record))
     :stage0-rule-runner-replaced?
     (true? (:stage0-rule-runner-replaced? boundary-record))
     :stage0-reader-replaced?
     (true? (:stage0-reader-replaced? boundary-record))
     :stage0-macro-expander-replaced?
     (true? (:stage0-macro-expander-replaced? boundary-record))
     :stage2-front-end-executor-used?
     (true? (:stage2-front-end-executor-used? boundary-record))
     :stage2-front-end-host-replaced?
     (true? (:stage2-front-end-host-replaced? boundary-record))
	     :stage2-source-front-end-used?
	     (true? (:stage2-source-front-end-used? boundary-record))
	     :stage2-runtime-kernel-used?
	     (true? (:stage2-runtime-kernel-used? boundary-record))
	     :stage2-runtime-host-replaced?
	     (true? (:stage2-runtime-host-replaced? boundary-record))
	     :stage2-runtime-primitives-replaced?
	     (true? (:stage2-runtime-primitives-replaced?
	             boundary-record))
	     :gravity-runtime-primitives-used?
	     (true? (:gravity-runtime-primitives? boundary-record))
	     :stage2-plan-emitted?
	     (true? (:stage2-plan-emitted? accepted-record))
     :stage2-runtime-executed?
     (true? (:stage2-runtime-executed? accepted-record))
     :accepted-output-equivalent?
     (true? (:accepted-output-equivalent? accepted-record))
     :function-instructions-equivalent?
     (true? (:function-instructions-equivalent? accepted-record))
     :rejected-diagnostics-equivalent?
     (= :complete (:status rejected-record))
     :residual-clojure-driver-host-recorded?
     (true? (:clojure-stage0-driver-host? boundary-record))
	     :does-not-use-clojure-stage2-front-end-host?
	     (false? (:clojure-stage2-front-end-host? boundary-record))
	     :does-not-use-clojure-stage0-runtime-host?
	     (false? (:clojure-stage0-runtime-host? boundary-record))
	     :does-not-use-clojure-runtime-primitives?
	     (false? (:clojure-host-primitive-boundary? boundary-record))
     :does-not-use-clojure-stage0-rule-runner?
     (false? (:clojure-stage0-rule-runner? boundary-record))
     :does-not-use-clojure-stage0-reader?
     (false? (:clojure-stage0-reader? boundary-record))
     :does-not-use-clojure-stage0-macro-expander?
     (false? (:clojure-stage0-macro-expander? boundary-record))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (= (set p15-s23-stage2-compiler-driver-diagnostic-ids)
        rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-stage2-compiler-driver-diagnostic-ids)
        diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :stage2-compiler-driver-authored-in-gravity? true
      :stage2-compiler-driver-executed? true
      :stage0-compiler-driver-replaced? true
      :stage0-rule-runner-replaced? true
      :stage0-reader-replaced? true
      :stage0-macro-expander-replaced? true
	      :stage2-front-end-executor-used? true
	      :stage2-front-end-host-replaced? true
	      :stage2-source-front-end-used? true
	      :stage2-runtime-kernel-used? true
	      :stage2-runtime-host-replaced? true
	      :stage2-runtime-primitives-replaced? true
	      :gravity-runtime-primitives? true
	      :clojure-stage0-driver-host? true
      :clojure-stage0-reader? false
	      :clojure-stage0-macro-expander? false
	      :clojure-stage2-front-end-host? false
	      :clojure-stage0-runtime-host? false
	      :clojure-host-primitive-boundary? false
	      :clojure-stage0-rule-runner? false
	      :full-self-hosted-toolchain? false
	      :next-required-capability
	      :implement_whole_language_compiler_stage_without_clojure_seed}}))

(defn p15-s23-stage2-compiler-driver-source-artifact*
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        driver
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-compiler-driver)
        front-end
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-source-front-end)
        emitter
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-plan-emitter)
        runtime
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-runtime-executor)
        rule-record
        (p15-s23-stage2-compiler-driver-rule-record driver)
        accepted-record
        (p15-s23-stage2-compiler-driver-accepted-record
         driver front-end emitter runtime)
        rejected-fixture-records
        (p15-s23-stage2-compiler-driver-rejected-records
         driver front-end emitter runtime)
        rejected-record
        (p15-s23-stage2-compiler-driver-rejected-record
         rejected-fixture-records)
        front-end-executor-artifact
        (p15-s23-stage2-front-end-executor-source-artifact source-path)
	        front-end-artifact
	        (p15-s23-stage2-source-front-end-source-artifact source-path)
	        runtime-kernel-artifact
	        (p15-s23-stage2-runtime-kernel-source-artifact source-path)
	        runtime-artifact
	        (p15-s23-stage2-runtime-executor-source-artifact source-path)
        plan-emitter-artifact
        (p15-s23-stage2-plan-emitter-source-artifact source-path)
        nucleus-artifact
        (p15-s23-stage2-compiler-nucleus-source-artifact source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact
         source-path)
        accepted-artifact
        (p15-s23-accepted-app-execution-source-artifact source-path)
        rejected-artifact
        (p15-s23-rejected-app-diagnostic-source-artifact source-path)
	        evidence-link-record
	        (p15-s23-stage2-compiler-driver-evidence-link-record
	         front-end-executor-artifact front-end-artifact
	         runtime-kernel-artifact runtime-artifact plan-emitter-artifact
	         nucleus-artifact pipeline-artifact accepted-artifact
	         rejected-artifact)
        boundary-record
        (p15-s23-stage2-compiler-driver-boundary-record driver)
        candidate {:driver-contract driver
                   :rule-record rule-record
                   :accepted-record accepted-record
                   :rejected-record rejected-record
                   :evidence-link-record evidence-link-record
                   :boundary-record boundary-record}
        diagnostics
        (p15-s23-stage2-compiler-driver-diagnostics source-path
                                                   candidate)
        _ (when (seq diagnostics)
            (p15-s23-stage2-compiler-driver-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :driver driver
                       :stage2-plan-id
                       (:stage2-plan-id accepted-record)
                       :runtime-output
                       (:stage2-driver-output accepted-record)
                       :rejected-diagnostics
                       (:observed-diagnostics rejected-record)})))
        rejected-proof-records
        (p15-s23-stage2-compiler-driver-rejected-proof-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-stage2-compiler-driver-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-stage2-compiler-driver
         :source-path source-path
         :proof-id proof-id
         :driver-contract driver
         :rule-record rule-record
         :accepted-record accepted-record
         :rejected-record rejected-record
         :evidence-link-record evidence-link-record
         :boundary-record boundary-record
         :linked-artifacts
         {:stage2-front-end-executor
          (select-keys front-end-executor-artifact
                       [:kind :artifact-id :proof-id])
	          :stage2-source-front-end
	          (select-keys front-end-artifact [:kind :artifact-id :proof-id])
	          :stage2-runtime-kernel
	          (select-keys runtime-kernel-artifact
	                       [:kind :artifact-id :proof-id])
	          :stage2-runtime-executor
          (select-keys runtime-artifact [:kind :artifact-id :proof-id])
          :stage2-plan-emitter
          (select-keys plan-emitter-artifact
                       [:kind :artifact-id :proof-id])
          :stage2-compiler-nucleus
          (select-keys nucleus-artifact [:kind :artifact-id :proof-id])
          :compiler-pipeline-manifest
          (select-keys pipeline-artifact [:kind :artifact-id :proof-id])
          :accepted-app-execution-proof
          (select-keys accepted-artifact [:kind :artifact-id :proof-id])
          :rejected-app-diagnostic-proof
          (select-keys rejected-artifact [:kind :artifact-id :proof-id])}
         :full-language-compiler-self-hosted?
         (get-in driver
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in driver [:self-hosting-claims
                         :clojure-seed-retired?])
         :accepted-p15-s23-stage2-compiler-driver-fixtures
         [{:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :stage2-plan-id (:stage2-plan-id accepted-record)
           :stdout (:stage2-driver-output accepted-record)}]
         :verified-p15-s23-stage2-compiler-driver-rejected-fixtures
         rejected-fixture-records
         :rejected-p15-s23-stage2-compiler-driver-fixtures
         rejected-proof-records
         :p15-s23-stage2-compiler-driver-diagnostic-stream
         (p15-s23-stage2-compiler-driver-diagnostic-stream
          source-path proof-id)
         :p15-s23-stage2-compiler-driver-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-fixture-records)
          :internal-rejected-fixtures (count rejected-proof-records)
          :diagnostic-count
          (count p15-s23-stage2-compiler-driver-diagnostic-ids)
          :stage2-plan-id (:stage2-plan-id accepted-record)
          :stage0-plan-id (:stage0-plan-id accepted-record)
          :accepted-output (:stage2-driver-output accepted-record)
          :rejected-diagnostics (:observed-diagnostics rejected-record)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-stage2-compiler-driver-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-stage2-compiler-driver-source-artifact
  [source-path]
  (p15-s23-cached-source-artifact
   :p15-s23-stage2-compiler-driver
   source-path
   #(p15-s23-stage2-compiler-driver-source-artifact* source-path)))

(defn p15-s23-stage2-compiler-driver-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-stage2-compiler-driver-fail!
     "P15S23Y001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-stage2-compiler-driver-source-artifact path))

(defn p15-s23-stage2-compiler-driver-evidence
  []
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (let [artifact
              (p15-s23-stage2-compiler-driver-file-artifact
               source-path)
              proof (:capability-based-proof artifact)]
          {:status :verified
           :artifact (:kind artifact)
           :artifact-id (:artifact-id artifact)
           :proof-id (:proof-id artifact)
           :source-path source-path
           :stage2-plan-id
           (get-in artifact [:accepted-record :stage2-plan-id])
           :stage2-compiler-driver-executed?
           (:stage2-compiler-driver-executed? proof)
           :stage0-compiler-driver-replaced?
           (:stage0-compiler-driver-replaced? proof)
           :stage0-rule-runner-replaced?
           (:stage0-rule-runner-replaced? proof)
           :stage0-reader-replaced?
           (:stage0-reader-replaced? proof)
           :stage0-macro-expander-replaced?
           (:stage0-macro-expander-replaced? proof)
           :stage2-front-end-executor-used?
           (:stage2-front-end-executor-used? proof)
           :stage2-front-end-host-replaced?
           (:stage2-front-end-host-replaced? proof)
	           :stage2-source-front-end-used?
	           (:stage2-source-front-end-used? proof)
	           :stage2-runtime-kernel-used?
	           (:stage2-runtime-kernel-used? proof)
	           :stage2-runtime-host-replaced?
	           (:stage2-runtime-host-replaced? proof)
	           :stage2-runtime-primitives-replaced?
	           (:stage2-runtime-primitives-replaced? proof)
	           :gravity-runtime-primitives-used?
	           (:gravity-runtime-primitives-used? proof)
	           :accepted-output-equivalent?
           (:accepted-output-equivalent? proof)
           :rejected-diagnostics-equivalent?
           (:rejected-diagnostics-equivalent? proof)
           :residual-clojure-driver-host-recorded?
           (:residual-clojure-driver-host-recorded? proof)
	           :does-not-use-clojure-stage2-front-end-host?
	           (:does-not-use-clojure-stage2-front-end-host? proof)
	           :does-not-use-clojure-stage0-runtime-host?
	           (:does-not-use-clojure-stage0-runtime-host? proof)
	           :does-not-use-clojure-runtime-primitives?
	           (:does-not-use-clojure-runtime-primitives? proof)
	           :does-not-use-clojure-stage0-reader?
           (:does-not-use-clojure-stage0-reader? proof)
           :does-not-use-clojure-stage0-macro-expander?
           (:does-not-use-clojure-stage0-macro-expander? proof)
           :full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? artifact)
           :clojure-seed-retired? (:clojure-seed-retired? artifact)})
	      (catch Exception _
	          nil)))))

