(def p15-s23-stage2-whole-language-compiler-diagnostic-messages
  {"P15S23Z001" "P15-S23 stage2 whole-language compiler contract is missing"
   "P15S23Z002" "P15-S23 stage2 whole-language compiler source subset is incomplete"
   "P15S23Z003" "P15-S23 stage2 whole-language compiler is not linked to an executed stage2 driver"
   "P15S23Z004" "P15-S23 stage2 whole-language compiler accepted output does not match the current stage"
   "P15S23Z005" "P15-S23 stage2 whole-language compiler rejected diagnostics are incomplete"
   "P15S23Z006" "P15-S23 stage2 whole-language compiler evidence links, preserves, or emitted records are incomplete"
   "P15S23Z007" "P15-S23 stage2 whole-language compiler trusted boundary record is incomplete"
   "P15S23Z008" "P15-S23 stage2 whole-language compiler makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-stage2-whole-language-compiler-diagnostic-ids
  ["P15S23Z001" "P15S23Z002" "P15S23Z003" "P15S23Z004"
   "P15S23Z005" "P15S23Z006" "P15S23Z007" "P15S23Z008"])

(defn p15-s23-stage2-whole-language-compiler-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage2-whole-language-compiler-diagnostic-messages
              id
              "P15-S23 stage2 whole-language compiler failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage2-whole-language-compiler
                 :diagnostic-family
                 :p15-s23-stage2-whole-language-compiler
                 :value value
                 :remediation "Keep the stage2 whole-language compiler stage authored in Gravity, linked to the stage2 driver, source front-end, runtime kernel, accepted and rejected fixtures, and residual Clojure verifier boundary. Do not claim full self-hosting or Clojure seed retirement until the final evidence bundle exists."}
                data)))

(defn p15-s23-stage2-whole-language-compiler-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage2-whole-language-compiler
   :source-span {:source source-path}
   :message
   (get p15-s23-stage2-whole-language-compiler-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_p15_s23_stage2_whole_language_compiler})

(defn p15-s23-stage2-whole-language-compiler-source-record
  [source-path proof-contract inventory-artifact]
  (let [modules (:source-inventory inventory-artifact)
        required-components
        (set (get-in proof-contract
                     [:claimed-language-subset
                      :compiler-source-components]))
        observed-components (set (map :component modules))
        missing-components
        (set/difference required-components observed-components)
        missing-files
        (->> modules
             (remove #(= :present (:status %)))
             (map :path)
             sort
             vec)]
    {:artifact :gravity/p15-s23-stage2-whole-language-compiler-source-record
     :source-path source-path
     :required-components (vec (sort required-components))
     :observed-components (vec (sort observed-components))
     :source-modules modules
     :missing-components (vec (sort missing-components))
     :missing-files missing-files
     :source-subset-covered?
     (and (empty? missing-components) (empty? missing-files))
     :status
     (if (and (= :gravity/p15-s23-compiler-source-inventory-artifact
                 (:kind inventory-artifact))
              (empty? missing-components)
              (empty? missing-files))
       :complete
       :failed)}))

(defn p15-s23-stage2-whole-language-compiler-stage-record
  [source-path proof-contract source-record]
  (let [stage-contract (:whole-language-stage proof-contract)
        preserves (set (:preserves proof-contract))
        emits (set (:emits proof-contract))
        required-emits
        (set (:emits stage-contract))
        missing-preserves
        (set/difference
         p15-s23-stage2-whole-language-compiler-required-preserves
         preserves)
        missing-emits
        (set/difference
         p15-s23-stage2-whole-language-compiler-required-emits
         emits)
        missing-stage-emits
        (set/difference required-emits emits)]
    {:artifact :gravity/p15-s23-stage2-whole-language-compiler-stage-record
     :source-path source-path
     :stage (:stage proof-contract)
     :whole-language-stage (:stage stage-contract)
     :input (:input proof-contract)
     :output (:output proof-contract)
     :stage2-compiler-driver (:stage2-compiler-driver proof-contract)
     :stage2-runtime-kernel (:stage2-runtime-kernel proof-contract)
     :source-subset-covered? (:source-subset-covered? source-record)
     :missing-preserves (vec (sort missing-preserves))
     :missing-emits (vec (sort (set/union missing-emits
                                          missing-stage-emits)))
     :status
     (if (and (= :gravity/stage2-whole-language-compiler
                 (:artifact proof-contract))
              (= :p15-s23-stage2-whole-language-compiler
                 (:stage proof-contract))
              (= :complete (:status source-record))
              (= :p15-s23-stage2-compiler-driver
                 (:stage2-compiler-driver proof-contract))
              (= :p15-s23-stage2-runtime-kernel
                 (:stage2-runtime-kernel proof-contract))
              (empty? missing-preserves)
              (empty? missing-emits)
              (empty? missing-stage-emits))
       :complete
       :failed)}))

(defn p15-s23-stage2-whole-language-compiler-evidence-link-record
  [whole-compiler-artifact pipeline-artifact driver-artifact source-front-end
   front-end-executor plan-emitter runtime-executor runtime-kernel
   accepted-artifact rejected-artifact stage-comparison-artifact
   conformance-artifact provenance-artifact tcb-artifact unsafe-artifact]
  (let [links
        [{:link :whole-language-compiler-artifact
          :artifact (:kind whole-compiler-artifact)
          :artifact-id (:artifact-id whole-compiler-artifact)}
         {:link :compiler-pipeline-manifest
          :artifact (:kind pipeline-artifact)
          :artifact-id (:artifact-id pipeline-artifact)}
         {:link :stage2-compiler-driver
          :artifact (:kind driver-artifact)
          :artifact-id (:artifact-id driver-artifact)}
         {:link :stage2-source-front-end
          :artifact (:kind source-front-end)
          :artifact-id (:artifact-id source-front-end)}
         {:link :stage2-front-end-executor
          :artifact (:kind front-end-executor)
          :artifact-id (:artifact-id front-end-executor)}
         {:link :stage2-plan-emitter
          :artifact (:kind plan-emitter)
          :artifact-id (:artifact-id plan-emitter)}
         {:link :stage2-runtime-executor
          :artifact (:kind runtime-executor)
          :artifact-id (:artifact-id runtime-executor)}
         {:link :stage2-runtime-kernel
          :artifact (:kind runtime-kernel)
          :artifact-id (:artifact-id runtime-kernel)}
         {:link :accepted-app-execution-proof
          :artifact (:kind accepted-artifact)
          :artifact-id (:artifact-id accepted-artifact)}
         {:link :rejected-app-diagnostic-proof
          :artifact (:kind rejected-artifact)
          :artifact-id (:artifact-id rejected-artifact)}
         {:link :stage-comparison-report
          :artifact (:kind stage-comparison-artifact)
          :artifact-id (:artifact-id stage-comparison-artifact)}
         {:link :self-hosting-conformance-report
          :artifact (:kind conformance-artifact)
          :artifact-id (:artifact-id conformance-artifact)}
         {:link :bootstrap-provenance-attestation
          :artifact (:kind provenance-artifact)
          :artifact-id (:artifact-id provenance-artifact)}
         {:link :trusted-computing-base-delta-record
          :artifact (:kind tcb-artifact)
          :artifact-id (:artifact-id tcb-artifact)}
         {:link :unsafe-audit-report
          :artifact (:kind unsafe-artifact)
          :artifact-id (:artifact-id unsafe-artifact)}]
        links-with-status
        (mapv (fn [link]
                (assoc link
                       :status
                       (if (re-find #"^sha256:"
                                    (str (:artifact-id link)))
                         :verified
                         :missing)))
              links)
        covered (set (map :link links-with-status))]
    {:artifact
     :gravity/p15-s23-stage2-whole-language-compiler-evidence-link-record
     :links links-with-status
     :required-links
     (vec (sort p15-s23-stage2-whole-language-compiler-required-links))
     :required-links-covered?
     (= p15-s23-stage2-whole-language-compiler-required-links covered)
     :all-artifacts-identified?
     (every? #(= :verified (:status %)) links-with-status)
     :status
     (if (and (= p15-s23-stage2-whole-language-compiler-required-links
                 covered)
              (every? #(= :verified (:status %)) links-with-status))
       :complete
       :failed)}))

(defn p15-s23-stage2-whole-language-compiler-accepted-record
  [source-record driver-artifact whole-compiler-artifact]
  (let [driver-accepted (:accepted-record driver-artifact)
        whole-accepted
        (:accepted-application-compile-record whole-compiler-artifact)
        stage2-output (:stage2-driver-output driver-accepted)
        current-output (:stdout whole-accepted)]
    {:artifact
     :gravity/p15-s23-stage2-whole-language-compiler-accepted-run-record
     :fixture p15-s23-accepted-app-source-path
     :compiler-source-modules-accepted?
     (= :complete (:status source-record))
     :stage2-compiler-driver-artifact-id (:artifact-id driver-artifact)
     :current-stage-compiler-artifact-id
     (get-in whole-compiler-artifact
             [:compiler-artifact-manifest :compiler-artifact-id])
     :stage2-plan-id (:stage2-plan-id driver-accepted)
     :reference-stage0-plan-id (:reference-stage0-plan-id driver-accepted)
     :stage2-plan-emitted?
     (true? (:stage2-plan-emitted? driver-accepted))
     :stage2-runtime-executed?
     (true? (:stage2-runtime-executed? driver-accepted))
     :stage2-output stage2-output
     :current-stage-output current-output
     :expected-output p15-s23-accepted-app-expected-stdout
     :stage2-output-equivalent-to-current-stage?
     (= stage2-output current-output p15-s23-accepted-app-expected-stdout)
     :binding-table-equivalent?
     (true? (:binding-table-equivalent? driver-accepted))
     :function-instructions-equivalent?
     (true? (:function-instructions-equivalent? driver-accepted))
     :instruction-summary-equivalent?
     (true? (:instruction-summary-equivalent? driver-accepted))
     :effect-summary-equivalent?
     (true? (:effect-summary-equivalent? driver-accepted))
     :status
     (if (and (= :complete (:status source-record))
              (= :complete (:status driver-accepted))
              (true? (:stage2-plan-emitted? driver-accepted))
              (true? (:stage2-runtime-executed? driver-accepted))
              (= stage2-output current-output
                 p15-s23-accepted-app-expected-stdout))
       :complete
       :failed)}))

(defn p15-s23-stage2-whole-language-compiler-rejected-record
  [driver-artifact whole-compiler-artifact]
  (let [driver-rejected (:rejected-record driver-artifact)
        whole-rejected
        (:rejected-application-diagnostic-record whole-compiler-artifact)
        observed (set (:observed-diagnostics driver-rejected))
        current (set (:diagnostics whole-rejected))
        expected #{"L2-FUNCTION-ARITY" "L2-BUILTIN-ARITY"}]
    {:artifact
     :gravity/p15-s23-stage2-whole-language-compiler-rejected-diagnostic-record
     :fixtures (:fixtures whole-rejected)
     :stage2-observed-diagnostics (vec (sort observed))
     :current-stage-diagnostics (vec (sort current))
     :expected-diagnostics (vec (sort expected))
     :all-fixtures-rejected?
     (and (= :complete (:status driver-rejected))
          (true? (:all-fixtures-rejected? whole-rejected)))
     :diagnostics-equivalent-to-current-stage?
     (= observed current expected)
     :diagnostic-codes-stable?
     (= observed expected)
     :status
     (if (and (= :complete (:status driver-rejected))
              (true? (:all-fixtures-rejected? whole-rejected))
              (= observed current expected))
       :complete
       :failed)}))

(defn p15-s23-stage2-whole-language-compiler-boundary-record
  [proof-contract driver-artifact whole-compiler-artifact tcb-artifact]
  (let [driver-boundary (:boundary-record driver-artifact)
        whole-boundary
        (:residual-trusted-boundary-record whole-compiler-artifact)
        tcb-boundaries
        (get-in tcb-artifact
                [:residual-trust-boundary-record :residual-boundaries])
        claims (:self-hosting-claims proof-contract)]
    {:artifact
     :gravity/p15-s23-stage2-whole-language-compiler-boundary-record
     :stage2-compiler-driver-executed?
     (true? (:stage2-compiler-driver-executed? driver-boundary))
     :stage0-compiler-driver-replaced?
     (true? (:stage0-compiler-driver-replaced? driver-boundary))
     :stage0-rule-runner-replaced?
     (true? (:stage0-rule-runner-replaced? driver-boundary))
     :stage0-reader-replaced?
     (true? (:stage0-reader-replaced? driver-boundary))
     :stage0-macro-expander-replaced?
     (true? (:stage0-macro-expander-replaced? driver-boundary))
     :stage2-source-front-end-used?
     (true? (:stage2-source-front-end-used? driver-boundary))
     :stage2-front-end-executor-used?
     (true? (:stage2-front-end-executor-used? driver-boundary))
     :stage2-runtime-kernel-used?
     (true? (:stage2-runtime-kernel-used? driver-boundary))
     :stage2-runtime-executor-used?
     (true? (:stage2-runtime-executor-used? driver-boundary))
     :clojure-stage0-driver-host?
     (true? (:clojure-stage0-driver-host? driver-boundary))
     :clojure-stage0-verifier? true
     :clojure-stage0-release-compiler? true
     :clojure-stage0-runtime-host?
     (true? (:clojure-stage0-runtime-host? driver-boundary))
     :clojure-host-primitive-boundary?
     (true? (:clojure-host-primitive-boundary? driver-boundary))
     :gravity-runtime-primitives?
     (true? (:gravity-runtime-primitives? driver-boundary))
     :current-stage-residual-boundary-recorded?
     (= :complete (:status whole-boundary))
     :residual-tcb-boundaries tcb-boundaries
     :full-language-compiler-self-hosted?
     (true? (:full-language-compiler-self-hosted? claims))
     :clojure-seed-retired?
     (true? (:clojure-seed-retired? claims))
     :status
     (if (and (true? (:stage2-compiler-driver-executed?
                     driver-boundary))
              (true? (:stage0-compiler-driver-replaced?
                      driver-boundary))
              (true? (:stage0-rule-runner-replaced?
                      driver-boundary))
              (true? (:stage0-reader-replaced? driver-boundary))
              (true? (:stage0-macro-expander-replaced?
                      driver-boundary))
              (true? (:stage2-source-front-end-used?
                      driver-boundary))
              (true? (:stage2-front-end-executor-used?
                      driver-boundary))
              (true? (:stage2-runtime-kernel-used?
                      driver-boundary))
              (true? (:stage2-runtime-executor-used?
                      driver-boundary))
              (true? (:clojure-stage0-driver-host?
                      driver-boundary))
              (false? (:clojure-stage0-runtime-host?
                       driver-boundary))
              (false? (:clojure-host-primitive-boundary?
                       driver-boundary))
              (true? (:gravity-runtime-primitives?
                      driver-boundary))
              (= :complete (:status whole-boundary))
              (contains? (set tcb-boundaries)
                         :clojure-stage0-bootstrap)
              (false? (:full-language-compiler-self-hosted?
                       claims))
              (false? (:clojure-seed-retired? claims)))
       :complete
       :failed)}))

(defn p15-s23-stage2-whole-language-compiler-lineage-record
  [source-path proof-contract inventory-artifact driver-artifact
   whole-compiler-artifact provenance-artifact]
  {:artifact
   :gravity/p15-s23-stage2-whole-language-compiler-lineage-record
   :source-path source-path
   :source-language :gravity
   :compiler-stage (:stage proof-contract)
   :compiled-by :gravity-stage2-compiler-driver
   :executed-by :gravity-stage2-runtime-kernel
   :verified-by :clojure-stage0-verifier
   :source-inventory-id (:inventory-id inventory-artifact)
   :stage2-compiler-driver-artifact-id (:artifact-id driver-artifact)
   :current-stage-compiler-artifact-id
   (get-in whole-compiler-artifact
           [:compiler-artifact-manifest :compiler-artifact-id])
   :bootstrap-provenance-record-id
   (get-in provenance-artifact
           [:bootstrap-provenance-record :provenance-record-id])
   :lineage-traversable-to-seed?
   (get-in provenance-artifact
           [:compiler-lineage-graph :lineage-traversable-to-seed?])
   :residual-verifier :clojure-stage0-verifier
   :residual-release-compiler :clojure-stage0-release-compiler
   :status
   (if (and (re-find #"^sha256:" (str (:inventory-id inventory-artifact)))
            (re-find #"^sha256:" (str (:artifact-id driver-artifact)))
            (re-find #"^sha256:"
                     (str (get-in whole-compiler-artifact
                                  [:compiler-artifact-manifest
                                   :compiler-artifact-id])))
            (true?
             (get-in provenance-artifact
                     [:compiler-lineage-graph
                      :lineage-traversable-to-seed?])))
     :complete
     :failed)})

(defn p15-s23-stage2-whole-language-compiler-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        source-record (:source-record candidate)
        stage-record (:stage-record candidate)
        accepted-record (:accepted-record candidate)
        rejected-record (:rejected-record candidate)
        evidence-link-record (:evidence-link-record candidate)
        boundary-record (:boundary-record candidate)
        lineage-record (:lineage-record candidate)
        claims (:self-hosting-claims proof-contract)]
    (vec
     (concat
      (when-not (= :gravity/stage2-whole-language-compiler
                   (:artifact proof-contract))
        [(p15-s23-stage2-whole-language-compiler-diagnostic-record
          source-path "P15S23Z001" proof-contract
          {:missing-fields [:artifact]})])
      (when-not (= :complete (:status source-record))
        [(p15-s23-stage2-whole-language-compiler-diagnostic-record
          source-path "P15S23Z002" source-record
          {:required-components
           (get-in proof-contract
                   [:claimed-language-subset
                    :compiler-source-components])})])
      (when-not (and (= :complete (:status stage-record))
                     (= :complete (:status lineage-record)))
        [(p15-s23-stage2-whole-language-compiler-diagnostic-record
          source-path "P15S23Z003"
          {:stage-record stage-record
           :lineage-record lineage-record}
          {:required [:stage2-driver
                      :stage2-runtime-kernel
                      :gravity-source-lineage]})])
      (when-not (and (= :complete (:status accepted-record))
                     (true?
                      (:stage2-output-equivalent-to-current-stage?
                       accepted-record))
                     (true? (:stage2-runtime-executed?
                             accepted-record)))
        [(p15-s23-stage2-whole-language-compiler-diagnostic-record
          source-path "P15S23Z004" accepted-record
          {:required [:accepted-output-equivalent
                      :stage2-runtime-executed]})])
      (when-not (and (= :complete (:status rejected-record))
                     (true?
                      (:diagnostics-equivalent-to-current-stage?
                       rejected-record))
                     (true? (:diagnostic-codes-stable?
                             rejected-record)))
        [(p15-s23-stage2-whole-language-compiler-diagnostic-record
          source-path "P15S23Z005" rejected-record
          {:required [:rejected-fixtures-fail-closed
                      :diagnostics-equivalent-to-current-stage]})])
      (when-not (and (= :complete (:status evidence-link-record))
                     (true?
                      (:required-links-covered? evidence-link-record))
                     (true? (:all-artifacts-identified?
                             evidence-link-record)))
        [(p15-s23-stage2-whole-language-compiler-diagnostic-record
          source-path "P15S23Z006" evidence-link-record
          {:required-links
           (vec (sort
                 p15-s23-stage2-whole-language-compiler-required-links))
           :required-emits
           (vec (sort
                 p15-s23-stage2-whole-language-compiler-required-emits))
           :required-preserves
           (vec (sort
                 p15-s23-stage2-whole-language-compiler-required-preserves))})])
      (when-not (and (= :complete (:status boundary-record))
                     (true? (:stage2-compiler-driver-executed?
                             boundary-record))
                     (true? (:clojure-stage0-verifier?
                             boundary-record))
                     (true? (:clojure-stage0-release-compiler?
                             boundary-record))
                     (false? (:clojure-stage0-runtime-host?
                              boundary-record))
                     (false? (:clojure-host-primitive-boundary?
                              boundary-record))
                     (true? (:gravity-runtime-primitives?
                             boundary-record)))
        [(p15-s23-stage2-whole-language-compiler-diagnostic-record
          source-path "P15S23Z007" boundary-record
          {:required [:stage2-driver-executed
                      :stage2-runtime-kernel
                      :clojure-stage0-verifier-recorded
                      :clojure-stage0-release-compiler-recorded]})])
      (when (or (true? (:full-language-compiler-self-hosted?
                       claims))
                (true? (:clojure-seed-retired? claims))
                (true? (:full-language-compiler-self-hosted?
                       boundary-record))
                (true? (:clojure-seed-retired?
                       boundary-record)))
        [(p15-s23-stage2-whole-language-compiler-diagnostic-record
          source-path "P15S23Z008"
          {:claims claims
           :boundary-record boundary-record}
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-stage2-whole-language-compiler-diagnostic-stream
  [source-path proof-id]
  {:artifact
   :gravity/p15-s23-stage2-whole-language-compiler-diagnostic-stream
   :stage :p15-s23-stage2-whole-language-compiler
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-stage2-whole-language-compiler
            :message
            (get p15-s23-stage2-whole-language-compiler-diagnostic-messages
                 id)})
         p15-s23-stage2-whole-language-compiler-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage2-whole-language-compiler-rejected-candidates
  [accepted-candidate]
  [{:fixture :internal-p15-s23-stage2-whole-language-compiler-missing-contract
    :candidate (assoc accepted-candidate :proof-contract {})
    :expected-diagnostic "P15S23Z001"}
   {:fixture :internal-p15-s23-stage2-whole-language-compiler-source-gap
    :candidate
    (assoc-in accepted-candidate [:source-record :status] :failed)
    :expected-diagnostic "P15S23Z002"}
   {:fixture :internal-p15-s23-stage2-whole-language-compiler-driver-gap
    :candidate
    (-> accepted-candidate
        (assoc-in [:stage-record :status] :failed)
        (assoc-in [:lineage-record :status] :failed))
    :expected-diagnostic "P15S23Z003"}
   {:fixture :internal-p15-s23-stage2-whole-language-compiler-output-gap
    :candidate
    (-> accepted-candidate
        (assoc-in [:accepted-record
                   :stage2-output-equivalent-to-current-stage?]
                  false)
        (assoc-in [:accepted-record :status] :failed))
    :expected-diagnostic "P15S23Z004"}
   {:fixture :internal-p15-s23-stage2-whole-language-compiler-rejected-gap
    :candidate
    (-> accepted-candidate
        (assoc-in [:rejected-record
                   :diagnostics-equivalent-to-current-stage?]
                  false)
        (assoc-in [:rejected-record :status] :failed))
    :expected-diagnostic "P15S23Z005"}
   {:fixture :internal-p15-s23-stage2-whole-language-compiler-evidence-gap
    :candidate
    (-> accepted-candidate
        (assoc-in [:evidence-link-record :required-links-covered?]
                  false)
        (assoc-in [:evidence-link-record :status] :failed))
    :expected-diagnostic "P15S23Z006"}
   {:fixture :internal-p15-s23-stage2-whole-language-compiler-boundary-gap
    :candidate
    (-> accepted-candidate
        (assoc-in [:boundary-record :clojure-stage0-verifier?]
                  false)
        (assoc-in [:boundary-record :status] :failed))
    :expected-diagnostic "P15S23Z007"}
   {:fixture :internal-p15-s23-stage2-whole-language-compiler-overclaim
    :candidate
    (-> accepted-candidate
        (assoc-in [:proof-contract :self-hosting-claims
                   :full-language-compiler-self-hosted?]
                  true)
        (assoc-in [:proof-contract :self-hosting-claims
                   :clojure-seed-retired?]
                  true)
        (assoc-in [:boundary-record
                   :full-language-compiler-self-hosted?]
                  true)
        (assoc-in [:boundary-record :clojure-seed-retired?]
                  true))
    :expected-diagnostic "P15S23Z008"}])

(defn p15-s23-stage2-whole-language-compiler-rejected-records
  [source-path accepted-candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-stage2-whole-language-compiler-proof-diagnostics
            source-path candidate)})
        (p15-s23-stage2-whole-language-compiler-rejected-candidates
         accepted-candidate)))

(defn p15-s23-stage2-whole-language-compiler-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-stage2-whole-language-compiler-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat
              #(map :diagnostic (:diagnostics %))
              (:rejected-p15-s23-stage2-whole-language-compiler-fixtures
               artifact)))]
    {:stage2-whole-language-compiler-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :stage2-whole-language-compiler-present?
     (= :gravity/stage2-whole-language-compiler
        (get-in artifact [:proof-contract :artifact]))
     :source-subset-covered?
     (= :complete (get-in artifact [:source-record :status]))
     :stage2-driver-linked?
     (= :complete (get-in artifact [:stage-record :status]))
     :stage2-compiler-driver-executed?
     (true? (get-in artifact
                    [:boundary-record
                     :stage2-compiler-driver-executed?]))
     :stage2-runtime-kernel-used?
     (true? (get-in artifact
                    [:boundary-record :stage2-runtime-kernel-used?]))
     :accepted-output-equivalent?
     (true? (get-in artifact
                    [:accepted-record
                     :stage2-output-equivalent-to-current-stage?]))
     :rejected-diagnostics-equivalent?
     (true? (get-in artifact
                    [:rejected-record
                     :diagnostics-equivalent-to-current-stage?]))
     :evidence-links-covered?
     (true? (get-in artifact
                    [:evidence-link-record
                     :required-links-covered?]))
     :boundary-recorded?
     (= :complete (get-in artifact [:boundary-record :status]))
     :residual-clojure-verifier-recorded?
     (true? (get-in artifact
                    [:boundary-record :clojure-stage0-verifier?]))
     :residual-clojure-release-compiler-recorded?
     (true? (get-in artifact
                    [:boundary-record
                     :clojure-stage0-release-compiler?]))
     :does-not-use-clojure-stage0-runtime-host?
     (false? (get-in artifact
                     [:boundary-record
                      :clojure-stage0-runtime-host?]))
     :does-not-use-clojure-runtime-primitives?
     (false? (get-in artifact
                     [:boundary-record
                      :clojure-host-primitive-boundary?]))
     :gravity-runtime-primitives-used?
     (true? (get-in artifact
                    [:boundary-record :gravity-runtime-primitives?]))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset?
      (set p15-s23-stage2-whole-language-compiler-diagnostic-ids)
      rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-stage2-whole-language-compiler-diagnostic-ids)
        diagnostics)
     :limitations
     {:stage2-whole-language-compiler-stage-present? true
      :accepted-app-through-stage2-whole-language-stage? true
      :rejected-app-through-stage2-whole-language-stage? true
      :stage2-compiler-driver-executed? true
      :stage2-runtime-kernel-used? true
      :clojure-stage0-runtime-host? false
      :clojure-host-primitive-boundary? false
      :gravity-runtime-primitives? true
      :clojure-stage0-verifier? true
      :clojure-stage0-release-compiler? true
      :full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :next-required-capability
      :prove_whole_language_stage_equivalence_and_run_self_hosted_app}}))

(defn p15-s23-stage2-whole-language-compiler-source-artifact*
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-stage2-whole-language-compiler)
        inventory-artifact
        (p15-s23-current-candidate-artifact-evidence
         :compiler-source-inventory)
        pipeline-artifact
        (p15-s23-current-candidate-artifact-evidence
         :compiler-pipeline-manifest)
        whole-compiler-artifact
        (p15-s23-current-candidate-artifact-evidence
         :whole-language-compiler-artifact)
        driver-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-compiler-driver)
        source-front-end-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-source-front-end)
        front-end-executor-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-front-end-executor)
        plan-emitter-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-plan-emitter)
        runtime-executor-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-runtime-executor)
        runtime-kernel-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-runtime-kernel)
        accepted-artifact
        (p15-s23-current-candidate-artifact-evidence
         :accepted-app-execution-proof)
        rejected-artifact
        (p15-s23-current-candidate-artifact-evidence
         :rejected-app-diagnostic-proof)
        stage-comparison-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage-comparison-report)
        conformance-artifact
        (p15-s23-current-candidate-artifact-evidence
         :conformance-report)
        provenance-artifact
        (p15-s23-current-candidate-artifact-evidence
         :provenance-attestation)
        tcb-artifact
        (p15-s23-current-candidate-artifact-evidence
         :tcb-delta-record)
        unsafe-artifact
        (p15-s23-current-candidate-artifact-evidence
         :unsafe-audit-report)
        source-record
        (p15-s23-stage2-whole-language-compiler-source-record
         source-path proof-contract inventory-artifact)
        stage-record
        (p15-s23-stage2-whole-language-compiler-stage-record
         source-path proof-contract source-record)
        evidence-link-record
        (p15-s23-stage2-whole-language-compiler-evidence-link-record
         whole-compiler-artifact pipeline-artifact driver-artifact
         source-front-end-artifact front-end-executor-artifact
         plan-emitter-artifact runtime-executor-artifact
         runtime-kernel-artifact accepted-artifact rejected-artifact
         stage-comparison-artifact conformance-artifact
         provenance-artifact tcb-artifact unsafe-artifact)
        accepted-record
        (p15-s23-stage2-whole-language-compiler-accepted-record
         source-record driver-artifact whole-compiler-artifact)
        rejected-record
        (p15-s23-stage2-whole-language-compiler-rejected-record
         driver-artifact whole-compiler-artifact)
        boundary-record
        (p15-s23-stage2-whole-language-compiler-boundary-record
         proof-contract driver-artifact whole-compiler-artifact
         tcb-artifact)
        lineage-record
        (p15-s23-stage2-whole-language-compiler-lineage-record
         source-path proof-contract inventory-artifact driver-artifact
         whole-compiler-artifact provenance-artifact)
        candidate {:proof-contract proof-contract
                   :source-record source-record
                   :stage-record stage-record
                   :accepted-record accepted-record
                   :rejected-record rejected-record
                   :evidence-link-record evidence-link-record
                   :boundary-record boundary-record
                   :lineage-record lineage-record}
        diagnostics
        (p15-s23-stage2-whole-language-compiler-proof-diagnostics
         source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-stage2-whole-language-compiler-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :proof-contract proof-contract
                       :source-record source-record
                       :stage-record stage-record
                       :accepted-record accepted-record
                       :rejected-record rejected-record
                       :evidence-link-record evidence-link-record
                       :boundary-record boundary-record
                       :lineage-record lineage-record})))
        rejected-records
        (p15-s23-stage2-whole-language-compiler-rejected-records
         source-path candidate)
        artifact-base
        {:kind
         :gravity/p15-s23-stage2-whole-language-compiler-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-stage2-whole-language-compiler
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :compiler-source-inventory-artifact
         (select-keys inventory-artifact
                      [:kind :artifact-id :inventory-id
                       :source-inventory :capability-based-proof])
         :compiler-pipeline-manifest-artifact
         (select-keys pipeline-artifact
                      [:kind :artifact-id :manifest-id
                       :compiler-pipeline-manifest
                       :capability-based-proof])
         :whole-language-compiler-artifact
         (select-keys whole-compiler-artifact
                      [:kind :artifact-id :proof-id
                       :compiler-artifact-manifest
                       :accepted-application-compile-record
                       :rejected-application-diagnostic-record
                       :residual-trusted-boundary-record
                       :capability-based-proof])
         :stage2-compiler-driver-artifact
         (select-keys driver-artifact
                      [:kind :artifact-id :proof-id :accepted-record
                       :rejected-record :boundary-record
                       :capability-based-proof])
         :stage2-source-front-end-artifact
         (select-keys source-front-end-artifact
                      [:kind :artifact-id :proof-id
                       :rule-record :accepted-record
                       :boundary-record :capability-based-proof])
         :stage2-front-end-executor-artifact
         (select-keys front-end-executor-artifact
                      [:kind :artifact-id :proof-id
                       :rule-record :accepted-record
                       :boundary-record :capability-based-proof])
         :stage2-plan-emitter-artifact
         (select-keys plan-emitter-artifact
                      [:kind :artifact-id :proof-id
                       :rule-record :accepted-record
                       :boundary-record :capability-based-proof])
         :stage2-runtime-executor-artifact
         (select-keys runtime-executor-artifact
                      [:kind :artifact-id :proof-id
                       :rule-record :accepted-record
                       :boundary-record :capability-based-proof])
         :stage2-runtime-kernel-artifact
         (select-keys runtime-kernel-artifact
                      [:kind :artifact-id :proof-id
                       :rule-record :accepted-record
                       :boundary-record :capability-based-proof])
         :accepted-app-execution-artifact
         (select-keys accepted-artifact
                      [:kind :artifact-id :proof-id
                       :accepted-output-comparison
                       :compiled-plan-execution-trace
                       :capability-based-proof])
         :rejected-app-diagnostic-artifact
         (select-keys rejected-artifact
                      [:kind :artifact-id :proof-id
                       :rejected-app-diagnostic-records
                       :capability-based-proof])
         :stage-comparison-report-artifact
         (select-keys stage-comparison-artifact
                      [:kind :artifact-id :proof-id
                       :capability-based-proof])
         :self-hosting-conformance-report-artifact
         (select-keys conformance-artifact
                      [:kind :artifact-id :proof-id
                       :capability-based-proof])
         :bootstrap-provenance-attestation-artifact
         (select-keys provenance-artifact
                      [:kind :artifact-id :proof-id
                       :bootstrap-provenance-record
                       :compiler-lineage-graph
                       :capability-based-proof])
         :tcb-delta-record-artifact
         (select-keys tcb-artifact
                      [:kind :artifact-id :proof-id
                       :residual-trust-boundary-record
                       :capability-based-proof])
         :unsafe-audit-report-artifact
         (select-keys unsafe-artifact
                      [:kind :artifact-id :proof-id
                       :unsafe-audit-report
                       :unsafe-island-index
                       :capability-based-proof])
         :source-record source-record
         :stage-record stage-record
         :accepted-record accepted-record
         :rejected-record rejected-record
         :evidence-link-record evidence-link-record
         :boundary-record boundary-record
         :lineage-record lineage-record
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-stage2-whole-language-compiler-fixtures
         [{:fixture source-path
           :status :accepted
           :source-components (:observed-components source-record)}
          {:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :stdout (:stage2-output accepted-record)
           :stage2-plan-id (:stage2-plan-id accepted-record)}]
         :rejected-p15-s23-stage2-whole-language-compiler-fixtures
         rejected-records
         :p15-s23-stage2-whole-language-compiler-diagnostic-stream
         (p15-s23-stage2-whole-language-compiler-diagnostic-stream
          source-path proof-id)
         :p15-s23-stage2-whole-language-compiler-results
         {:accepted-fixtures 2
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-stage2-whole-language-compiler-diagnostic-ids)
          :source-component-count
          (count (:observed-components source-record))
          :accepted-app-output (:stage2-output accepted-record)
          :rejected-diagnostics
          (:stage2-observed-diagnostics rejected-record)
          :stage2-compiler-driver-executed?
          (:stage2-compiler-driver-executed? boundary-record)
          :stage2-runtime-kernel-used?
          (:stage2-runtime-kernel-used? boundary-record)
          :clojure-stage0-verifier?
          (:clojure-stage0-verifier? boundary-record)
          :clojure-stage0-release-compiler?
          (:clojure-stage0-release-compiler? boundary-record)
          :full-language-compiler-self-hosted? false
          :clojure-seed-retired? false
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-stage2-whole-language-compiler-proof
               artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-stage2-whole-language-compiler-source-artifact
  [source-path]
  (p15-s23-cached-source-artifact
   :p15-s23-stage2-whole-language-compiler
   source-path
   #(p15-s23-stage2-whole-language-compiler-source-artifact*
     source-path)))

(defn p15-s23-stage2-whole-language-compiler-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-stage2-whole-language-compiler-fail!
     "P15S23Z001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-stage2-whole-language-compiler-source-artifact path))

(defn p15-s23-stage2-whole-language-compiler-evidence
  []
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (let [artifact
              (p15-s23-stage2-whole-language-compiler-file-artifact
               source-path)
              proof (:capability-based-proof artifact)]
          {:status :verified
           :artifact (:kind artifact)
           :artifact-id (:artifact-id artifact)
           :proof-id (:proof-id artifact)
           :source-path source-path
           :stage2-whole-language-compiler-present?
           (:stage2-whole-language-compiler-present? proof)
           :source-subset-covered? (:source-subset-covered? proof)
           :stage2-compiler-driver-executed?
           (:stage2-compiler-driver-executed? proof)
           :stage2-runtime-kernel-used?
           (:stage2-runtime-kernel-used? proof)
           :accepted-output-equivalent?
           (:accepted-output-equivalent? proof)
           :rejected-diagnostics-equivalent?
           (:rejected-diagnostics-equivalent? proof)
           :residual-clojure-verifier-recorded?
           (:residual-clojure-verifier-recorded? proof)
           :residual-clojure-release-compiler-recorded?
           (:residual-clojure-release-compiler-recorded? proof)
           :full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? artifact)
           :clojure-seed-retired?
           (:clojure-seed-retired? artifact)})
        (catch Exception _
          nil)))))

