(def p15-s23-stage3-seedless-compiler-candidate-diagnostic-messages
  {"P15S23AA001" "P15-S23 stage3 seedless compiler candidate contract is missing"
   "P15S23AA002" "P15-S23 stage3 seedless compiler source subset is incomplete"
   "P15S23AA003" "P15-S23 stage3 seedless compiler path is incomplete"
   "P15S23AA004" "P15-S23 stage3 seedless compiler accepted output does not match"
   "P15S23AA005" "P15-S23 stage3 seedless compiler rejected diagnostics are incomplete"
   "P15S23AA006" "P15-S23 stage3 seedless compiler still records a Clojure seed boundary"
   "P15S23AA007" "P15-S23 stage3 seedless compiler evidence links are incomplete"
   "P15S23AA008" "P15-S23 stage3 seedless compiler makes an unsupported final release claim"})

(def p15-s23-stage3-seedless-compiler-candidate-diagnostic-ids
  ["P15S23AA001" "P15S23AA002" "P15S23AA003" "P15S23AA004"
   "P15S23AA005" "P15S23AA006" "P15S23AA007" "P15S23AA008"])

(defn p15-s23-stage3-seedless-compiler-candidate-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage3-seedless-compiler-candidate-diagnostic-messages
              id
              "P15-S23 stage3 seedless compiler candidate failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage3-seedless-compiler-candidate
                 :diagnostic-family
                 :p15-s23-stage3-seedless-compiler-candidate
                 :value value
                 :remediation "Keep the candidate authored in Gravity, compile through the stage2 compiler driver and runtime kernel, replace Clojure verifier and release-compiler boundaries in the candidate record, and keep final self-hosting claims false until the full equivalence bundle is present."}
                data)))

(defn p15-s23-stage3-seedless-compiler-candidate-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage3-seedless-compiler-candidate
   :source-span {:source source-path}
   :message
   (get p15-s23-stage3-seedless-compiler-candidate-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_p15_s23_stage3_seedless_compiler_candidate})

(defn p15-s23-stage3-seedless-compiler-candidate-source-record
  [source-path proof-contract inventory-artifact]
  (let [modules (:source-inventory inventory-artifact)
        required-components
        (set (get-in proof-contract
                     [:claimed-language-subset
                      :compiler-source-components]))
        observed-components (set (map :component modules))
        missing-components
        (set/difference required-components observed-components)
        missing-files
        (->> modules
             (remove #(= :present (:status %)))
             (map :path)
             sort
             vec)]
    {:artifact
     :gravity/p15-s23-stage3-seedless-compiler-candidate-source-record
     :source-path source-path
     :required-components (vec (sort required-components))
     :observed-components (vec (sort observed-components))
     :source-modules modules
     :missing-components (vec (sort missing-components))
     :missing-files missing-files
     :source-subset-covered?
     (and (empty? missing-components) (empty? missing-files))
     :status
     (if (and (= :gravity/p15-s23-compiler-source-inventory-artifact
                 (:kind inventory-artifact))
              (empty? missing-components)
              (empty? missing-files))
       :complete
       :failed)}))

(defn p15-s23-stage3-seedless-compiler-candidate-record
  [source-path proof-contract source-record]
  (let [candidate-stage (:candidate-stage proof-contract)
        preserves (set (:preserves proof-contract))
        emits (set (:emits proof-contract))
        requires (set (:requires candidate-stage))
        missing-preserves
        (set/difference
         p15-s23-stage3-seedless-compiler-candidate-required-preserves
         preserves)
        missing-emits
        (set/difference
         p15-s23-stage3-seedless-compiler-candidate-required-emits
         emits)
        missing-requires
        (set/difference
         p15-s23-stage3-seedless-compiler-candidate-required-links
         requires)]
    {:artifact
     :gravity/p15-s23-stage3-seedless-compiler-candidate-record
     :source-path source-path
     :stage (:stage proof-contract)
     :candidate-stage (:stage candidate-stage)
     :implemented-by (:implemented-by proof-contract)
     :compiled-by (:compiled-by proof-contract)
     :verified-by (:verified-by proof-contract)
     :release-compiler (:release-compiler proof-contract)
     :executed-by (:executed-by proof-contract)
     :source-subset-covered? (:source-subset-covered? source-record)
     :missing-preserves (vec (sort missing-preserves))
     :missing-emits (vec (sort missing-emits))
     :missing-requires (vec (sort missing-requires))
     :compiler-path-seedless?
     (and (= :gravity-stage2-compiler-driver
             (:compiled-by proof-contract))
          (= :gravity-stage3-verifier (:verified-by proof-contract))
          (= :gravity-stage3-release-compiler
             (:release-compiler proof-contract))
          (= :gravity-stage2-runtime-kernel
             (:executed-by proof-contract)))
     :status
     (if (and (= :gravity/stage3-seedless-compiler-candidate
                 (:artifact proof-contract))
              (= :p15-s23-stage3-seedless-compiler-candidate
                 (:stage proof-contract))
              (= :complete (:status source-record))
              (= :compile-current-implementation-subset-without-clojure-seed
                 (:stage candidate-stage))
              (empty? missing-preserves)
              (empty? missing-emits)
              (empty? missing-requires)
              (= :gravity-stage2-compiler-driver
                 (:compiled-by proof-contract))
              (= :gravity-stage3-verifier (:verified-by proof-contract))
              (= :gravity-stage3-release-compiler
                 (:release-compiler proof-contract))
              (= :gravity-stage2-runtime-kernel
                 (:executed-by proof-contract)))
       :complete
       :failed)}))

(defn p15-s23-stage3-seedless-compiler-candidate-evidence-link-record
  [stage2-whole whole-compiler driver source-front-end front-end-executor
   plan-emitter runtime-executor runtime-kernel accepted rejected]
  (let [links
        [{:link :stage2-whole-language-compiler
          :artifact (:kind stage2-whole)
          :artifact-id (:artifact-id stage2-whole)}
         {:link :whole-language-compiler-artifact
          :artifact (:kind whole-compiler)
          :artifact-id (:artifact-id whole-compiler)}
         {:link :stage2-compiler-driver
          :artifact (:kind driver)
          :artifact-id (:artifact-id driver)}
         {:link :stage2-source-front-end
          :artifact (:kind source-front-end)
          :artifact-id (:artifact-id source-front-end)}
         {:link :stage2-front-end-executor
          :artifact (:kind front-end-executor)
          :artifact-id (:artifact-id front-end-executor)}
         {:link :stage2-plan-emitter
          :artifact (:kind plan-emitter)
          :artifact-id (:artifact-id plan-emitter)}
         {:link :stage2-runtime-executor
          :artifact (:kind runtime-executor)
          :artifact-id (:artifact-id runtime-executor)}
         {:link :stage2-runtime-kernel
          :artifact (:kind runtime-kernel)
          :artifact-id (:artifact-id runtime-kernel)}
         {:link :accepted-app-execution-proof
          :artifact (:kind accepted)
          :artifact-id (:artifact-id accepted)}
         {:link :rejected-app-diagnostic-proof
          :artifact (:kind rejected)
          :artifact-id (:artifact-id rejected)}]
        links-with-status
        (mapv (fn [link]
                (assoc link
                       :status
                       (if (re-find #"^sha256:"
                                    (str (:artifact-id link)))
                         :verified
                         :missing)))
              links)
        covered (set (map :link links-with-status))]
    {:artifact
     :gravity/p15-s23-stage3-seedless-compiler-candidate-evidence-link-record
     :links links-with-status
     :required-links
     (vec (sort p15-s23-stage3-seedless-compiler-candidate-required-links))
     :required-links-covered?
     (= p15-s23-stage3-seedless-compiler-candidate-required-links covered)
     :all-artifacts-identified?
     (every? #(= :verified (:status %)) links-with-status)
     :status
     (if (and (= p15-s23-stage3-seedless-compiler-candidate-required-links
                 covered)
              (every? #(= :verified (:status %)) links-with-status))
       :complete
       :failed)}))

(defn p15-s23-stage3-seedless-compiler-candidate-accepted-record
  [source-record candidate-record stage2-whole driver whole-compiler]
  (let [driver-accepted (:accepted-record driver)
        stage2-accepted (:accepted-record stage2-whole)
        whole-accepted
        (:accepted-application-compile-record whole-compiler)
        output (:stage2-driver-output driver-accepted)
        current-output (:stdout whole-accepted)]
    {:artifact
     :gravity/p15-s23-stage3-seedless-compiler-candidate-accepted-run-record
     :fixture p15-s23-accepted-app-source-path
     :compiler-source-modules-accepted?
     (= :complete (:status source-record))
     :candidate-compile-path-complete?
     (= :complete (:status candidate-record))
     :stage2-whole-language-compiler-artifact-id (:artifact-id stage2-whole)
     :stage2-compiler-driver-artifact-id (:artifact-id driver)
     :stage2-plan-id (:stage2-plan-id driver-accepted)
     :stage2-whole-language-stage-plan-id
     (:stage2-plan-id stage2-accepted)
     :seedless-candidate-output output
     :stage2-whole-language-output (:stage2-output stage2-accepted)
     :current-stage-output current-output
     :expected-output p15-s23-accepted-app-expected-stdout
     :accepted-output-equivalent?
     (= output
        (:stage2-output stage2-accepted)
        current-output
        p15-s23-accepted-app-expected-stdout)
     :stage2-plan-emitted?
     (true? (:stage2-plan-emitted? driver-accepted))
     :stage2-runtime-executed?
     (true? (:stage2-runtime-executed? driver-accepted))
     :binding-table-equivalent?
     (true? (:binding-table-equivalent? driver-accepted))
     :function-instructions-equivalent?
     (true? (:function-instructions-equivalent? driver-accepted))
     :instruction-summary-equivalent?
     (true? (:instruction-summary-equivalent? driver-accepted))
     :status
     (if (and (= :complete (:status source-record))
              (= :complete (:status candidate-record))
              (= :complete (:status driver-accepted))
              (true? (:stage2-plan-emitted? driver-accepted))
              (true? (:stage2-runtime-executed? driver-accepted))
              (= output
                 (:stage2-output stage2-accepted)
                 current-output
                 p15-s23-accepted-app-expected-stdout))
       :complete
       :failed)}))

(defn p15-s23-stage3-seedless-compiler-candidate-rejected-record
  [stage2-whole driver whole-compiler]
  (let [driver-rejected (:rejected-record driver)
        stage2-rejected (:rejected-record stage2-whole)
        whole-rejected
        (:rejected-application-diagnostic-record whole-compiler)
        observed (set (:observed-diagnostics driver-rejected))
        stage2-observed (set (:stage2-observed-diagnostics stage2-rejected))
        current (set (:diagnostics whole-rejected))
        expected #{"L2-FUNCTION-ARITY" "L2-BUILTIN-ARITY"}]
    {:artifact
     :gravity/p15-s23-stage3-seedless-compiler-candidate-rejected-diagnostic-record
     :fixtures (:fixtures whole-rejected)
     :seedless-candidate-diagnostics (vec (sort observed))
     :stage2-whole-language-diagnostics (vec (sort stage2-observed))
     :current-stage-diagnostics (vec (sort current))
     :expected-diagnostics (vec (sort expected))
     :all-fixtures-rejected?
     (and (= :complete (:status driver-rejected))
          (true? (:all-fixtures-rejected? whole-rejected)))
     :diagnostics-equivalent?
     (= observed stage2-observed current expected)
     :diagnostic-codes-stable? (= observed expected)
     :status
     (if (and (= :complete (:status driver-rejected))
              (true? (:all-fixtures-rejected? whole-rejected))
              (= observed stage2-observed current expected))
       :complete
       :failed)}))

(defn p15-s23-stage3-seedless-compiler-candidate-boundary-record
  [proof-contract driver stage2-whole]
  (let [seed-boundary (:seed-boundary proof-contract)
        claims (:self-hosting-claims proof-contract)
        driver-boundary (:boundary-record driver)
        stage2-boundary (:boundary-record stage2-whole)]
    {:artifact
     :gravity/p15-s23-stage3-seedless-compiler-candidate-boundary-record
     :compiler-path-uses-clojure-seed?
     (true? (:compiler-path-uses-clojure-seed? seed-boundary))
     :candidate-seedless?
     (true? (:candidate-seedless? seed-boundary))
     :verifier-boundary (:verifier-boundary seed-boundary)
     :release-compiler-boundary (:release-compiler-boundary seed-boundary)
     :clojure-stage0-verifier?
     (true? (:clojure-stage0-verifier? seed-boundary))
     :clojure-stage0-release-compiler?
     (true? (:clojure-stage0-release-compiler? seed-boundary))
     :stage2-compiler-driver-executed?
     (true? (:stage2-compiler-driver-executed? driver-boundary))
     :stage2-runtime-kernel-used?
     (true? (:stage2-runtime-kernel-used? driver-boundary))
     :stage2-whole-language-stage-present?
     (= :complete (:status stage2-boundary))
     :stage2-whole-language-recorded-clojure-verifier?
     (true? (:clojure-stage0-verifier? stage2-boundary))
     :stage2-whole-language-recorded-clojure-release-compiler?
     (true? (:clojure-stage0-release-compiler? stage2-boundary))
     :full-language-compiler-self-hosted?
     (true? (:full-language-compiler-self-hosted? claims))
     :clojure-seed-retired?
     (true? (:clojure-seed-retired? claims))
     :seedless-compiler-candidate?
     (true? (:seedless-compiler-candidate? claims))
     :status
     (if (and (false? (:compiler-path-uses-clojure-seed?
                      seed-boundary))
              (true? (:candidate-seedless? seed-boundary))
              (= :gravity-stage3-verifier
                 (:verifier-boundary seed-boundary))
              (= :gravity-stage3-release-compiler
                 (:release-compiler-boundary seed-boundary))
              (false? (:clojure-stage0-verifier? seed-boundary))
              (false? (:clojure-stage0-release-compiler?
                       seed-boundary))
              (true? (:stage2-compiler-driver-executed?
                      driver-boundary))
              (true? (:stage2-runtime-kernel-used? driver-boundary))
              (false? (:full-language-compiler-self-hosted? claims))
              (false? (:clojure-seed-retired? claims))
              (true? (:seedless-compiler-candidate? claims)))
       :complete
       :failed)}))

(defn p15-s23-stage3-seedless-compiler-candidate-lineage-record
  [source-path proof-contract stage2-whole provenance]
  (let [lineage (:lineage proof-contract)
        replaces (set (:replaces lineage))]
    {:artifact
     :gravity/p15-s23-stage3-seedless-compiler-candidate-lineage-record
     :source-path source-path
     :source-language (:source-language lineage)
     :compiled-by (:compiled-by lineage)
     :verified-by (:verified-by lineage)
     :release-compiled-by (:release-compiled-by lineage)
     :executed-by (:executed-by lineage)
     :replaces (vec (sort replaces))
     :stage2-whole-language-compiler-artifact-id (:artifact-id stage2-whole)
     :provenance-artifact-id (:artifact-id provenance)
     :lineage-traversable-to-seed?
     (true? (get-in provenance
                    [:compiler-lineage-graph
                     :lineage-traversable-to-seed?]))
     :status
     (if (and (= :gravity (:source-language lineage))
              (= :gravity-stage2-compiler-driver
                 (:compiled-by lineage))
              (= :gravity-stage3-verifier (:verified-by lineage))
              (= :gravity-stage3-release-compiler
                 (:release-compiled-by lineage))
              (= :gravity-stage2-runtime-kernel
                 (:executed-by lineage))
              (set/subset?
               #{:clojure-stage0-verifier
                 :clojure-stage0-release-compiler}
               replaces)
              (true? (get-in provenance
                             [:compiler-lineage-graph
                              :lineage-traversable-to-seed?])))
       :complete
       :failed)}))

(defn p15-s23-stage3-seedless-compiler-candidate-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        source-record (:source-record candidate)
        candidate-record (:candidate-record candidate)
        accepted-record (:accepted-record candidate)
        rejected-record (:rejected-record candidate)
        boundary-record (:boundary-record candidate)
        evidence-link-record (:evidence-link-record candidate)]
    (vec
     (keep
      identity
      [(when-not (= :gravity/stage3-seedless-compiler-candidate
                    (:artifact proof-contract))
         (p15-s23-stage3-seedless-compiler-candidate-diagnostic-record
          source-path "P15S23AA001" proof-contract
          {:required [:gravity/stage3-seedless-compiler-candidate]}))
       (when-not (= :complete (:status source-record))
         (p15-s23-stage3-seedless-compiler-candidate-diagnostic-record
          source-path "P15S23AA002" source-record
          {:missing-components (:missing-components source-record)
           :missing-files (:missing-files source-record)}))
       (when-not (= :complete (:status candidate-record))
         (p15-s23-stage3-seedless-compiler-candidate-diagnostic-record
          source-path "P15S23AA003" candidate-record
          {:missing-preserves (:missing-preserves candidate-record)
           :missing-emits (:missing-emits candidate-record)
           :missing-requires (:missing-requires candidate-record)}))
       (when-not (= :complete (:status accepted-record))
         (p15-s23-stage3-seedless-compiler-candidate-diagnostic-record
          source-path "P15S23AA004" accepted-record
          {:expected-output p15-s23-accepted-app-expected-stdout
           :observed-output (:seedless-candidate-output
                             accepted-record)}))
       (when-not (= :complete (:status rejected-record))
         (p15-s23-stage3-seedless-compiler-candidate-diagnostic-record
          source-path "P15S23AA005" rejected-record
          {:expected-diagnostics ["L2-BUILTIN-ARITY"
                                  "L2-FUNCTION-ARITY"]
           :observed-diagnostics
           (:seedless-candidate-diagnostics rejected-record)}))
       (when-not (= :complete (:status boundary-record))
         (p15-s23-stage3-seedless-compiler-candidate-diagnostic-record
          source-path "P15S23AA006" boundary-record
          {:required [:candidate-seedless
                      :clojure-stage0-verifier-false
                      :clojure-stage0-release-compiler-false]}))
       (when-not (= :complete (:status evidence-link-record))
         (p15-s23-stage3-seedless-compiler-candidate-diagnostic-record
          source-path "P15S23AA007" evidence-link-record
          {:required-links
           p15-s23-stage3-seedless-compiler-candidate-required-links}))
       (when (or (true? (get-in proof-contract
                                [:self-hosting-claims
                                 :full-language-compiler-self-hosted?]))
                 (true? (get-in proof-contract
                                [:self-hosting-claims
                                 :clojure-seed-retired?])))
         (p15-s23-stage3-seedless-compiler-candidate-diagnostic-record
          source-path "P15S23AA008"
          (:self-hosting-claims proof-contract)
          {:reason :candidate_is_not_final_release_bundle}))]))))

(defn p15-s23-stage3-seedless-compiler-candidate-diagnostic-stream
  [source-path proof-id]
  {:artifact
   :gravity/p15-s23-stage3-seedless-compiler-candidate-diagnostic-stream
   :stage :p15-s23-stage3-seedless-compiler-candidate
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic id
            :severity :error
            :message
            (get p15-s23-stage3-seedless-compiler-candidate-diagnostic-messages
                 id)
            :stable? true})
         p15-s23-stage3-seedless-compiler-candidate-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage3-seedless-compiler-candidate-rejected-records
  [source-path candidate]
  (let [base candidate
        candidates
        [{:fixture :internal-p15-s23-stage3-seedless-compiler-missing-contract
          :expected-diagnostic "P15S23AA001"
          :candidate (assoc base :proof-contract {})}
         {:fixture :internal-p15-s23-stage3-seedless-compiler-source-gap
          :expected-diagnostic "P15S23AA002"
          :candidate (assoc-in base [:source-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-seedless-compiler-path-gap
          :expected-diagnostic "P15S23AA003"
          :candidate (assoc-in base [:candidate-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-seedless-compiler-output-gap
          :expected-diagnostic "P15S23AA004"
          :candidate (assoc-in base [:accepted-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-seedless-compiler-rejected-gap
          :expected-diagnostic "P15S23AA005"
          :candidate (assoc-in base [:rejected-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-seedless-compiler-boundary-gap
          :expected-diagnostic "P15S23AA006"
          :candidate (assoc-in base [:boundary-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-seedless-compiler-evidence-gap
          :expected-diagnostic "P15S23AA007"
          :candidate (assoc-in base [:evidence-link-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-seedless-compiler-overclaim
          :expected-diagnostic "P15S23AA008"
          :candidate
          (-> base
              (assoc-in [:proof-contract :self-hosting-claims
                         :full-language-compiler-self-hosted?]
                        true)
              (assoc-in [:proof-contract :self-hosting-claims
                         :clojure-seed-retired?]
                        true))}]]
    (mapv (fn [{:keys [fixture expected-diagnostic candidate]}]
            {:fixture fixture
             :status :rejected
             :expected-diagnostic expected-diagnostic
             :diagnostics
             (p15-s23-stage3-seedless-compiler-candidate-proof-diagnostics
              source-path candidate)})
          candidates)))

(defn p15-s23-stage3-seedless-compiler-candidate-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-stage3-seedless-compiler-candidate-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat
              #(map :diagnostic (:diagnostics %))
              (:rejected-p15-s23-stage3-seedless-compiler-candidate-fixtures
               artifact)))]
    {:stage3-seedless-compiler-candidate-authored-in-gravity? true
     :status :candidate
     :task "P15-S23"
     :seedless-compiler-candidate-present?
     (= :gravity/stage3-seedless-compiler-candidate
        (get-in artifact [:proof-contract :artifact]))
     :source-subset-covered?
     (= :complete (get-in artifact [:source-record :status]))
     :compiler-path-complete?
     (= :complete (get-in artifact [:candidate-record :status]))
     :compiler-path-seedless?
     (true? (get-in artifact
                    [:candidate-record :compiler-path-seedless?]))
     :accepted-output-equivalent?
     (true? (get-in artifact
                    [:accepted-record :accepted-output-equivalent?]))
     :rejected-diagnostics-equivalent?
     (true? (get-in artifact
                    [:rejected-record :diagnostics-equivalent?]))
     :boundary-recorded?
     (= :complete (get-in artifact [:boundary-record :status]))
     :clojure-stage0-verifier-absent?
     (false? (get-in artifact
                     [:boundary-record :clojure-stage0-verifier?]))
     :clojure-stage0-release-compiler-absent?
     (false? (get-in artifact
                     [:boundary-record
                      :clojure-stage0-release-compiler?]))
     :evidence-links-covered?
     (true? (get-in artifact
                    [:evidence-link-record
                     :required-links-covered?]))
     :lineage-recorded?
     (= :complete (get-in artifact [:lineage-record :status]))
     :does-not-claim-final-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-final-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset?
      (set p15-s23-stage3-seedless-compiler-candidate-diagnostic-ids)
      rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-stage3-seedless-compiler-candidate-diagnostic-ids)
        diagnostics)
     :limitations
     {:seedless-compiler-candidate? true
      :compiler-path-uses-clojure-seed? false
      :clojure-stage0-verifier? false
      :clojure-stage0-release-compiler? false
      :full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :final-equivalence-bundle-complete? false
      :next-required-capability
      :prove_stage3_seedless_candidate_equivalence_bundle}}))

(defn p15-s23-stage3-seedless-compiler-candidate-source-artifact*
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-stage3-seedless-compiler-candidate)
        inventory-artifact
        (p15-s23-current-candidate-artifact-evidence
         :compiler-source-inventory)
        stage2-whole-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-whole-language-compiler)
        whole-compiler-artifact
        (p15-s23-current-candidate-artifact-evidence
         :whole-language-compiler-artifact)
        driver-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-compiler-driver)
        source-front-end-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-source-front-end)
        front-end-executor-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-front-end-executor)
        plan-emitter-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-plan-emitter)
        runtime-executor-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-runtime-executor)
        runtime-kernel-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-runtime-kernel)
        accepted-artifact
        (p15-s23-current-candidate-artifact-evidence
         :accepted-app-execution-proof)
        rejected-artifact
        (p15-s23-current-candidate-artifact-evidence
         :rejected-app-diagnostic-proof)
        provenance-artifact
        (p15-s23-current-candidate-artifact-evidence
         :provenance-attestation)
        source-record
        (p15-s23-stage3-seedless-compiler-candidate-source-record
         source-path proof-contract inventory-artifact)
        candidate-record
        (p15-s23-stage3-seedless-compiler-candidate-record
         source-path proof-contract source-record)
        evidence-link-record
        (p15-s23-stage3-seedless-compiler-candidate-evidence-link-record
         stage2-whole-artifact whole-compiler-artifact driver-artifact
         source-front-end-artifact front-end-executor-artifact
         plan-emitter-artifact runtime-executor-artifact
         runtime-kernel-artifact accepted-artifact rejected-artifact)
        accepted-record
        (p15-s23-stage3-seedless-compiler-candidate-accepted-record
         source-record candidate-record stage2-whole-artifact
         driver-artifact whole-compiler-artifact)
        rejected-record
        (p15-s23-stage3-seedless-compiler-candidate-rejected-record
         stage2-whole-artifact driver-artifact whole-compiler-artifact)
        boundary-record
        (p15-s23-stage3-seedless-compiler-candidate-boundary-record
         proof-contract driver-artifact stage2-whole-artifact)
        lineage-record
        (p15-s23-stage3-seedless-compiler-candidate-lineage-record
         source-path proof-contract stage2-whole-artifact
         provenance-artifact)
        candidate {:proof-contract proof-contract
                   :source-record source-record
                   :candidate-record candidate-record
                   :accepted-record accepted-record
                   :rejected-record rejected-record
                   :boundary-record boundary-record
                   :evidence-link-record evidence-link-record
                   :lineage-record lineage-record}
        diagnostics
        (p15-s23-stage3-seedless-compiler-candidate-proof-diagnostics
         source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-stage3-seedless-compiler-candidate-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :proof-contract proof-contract
                       :source-record source-record
                       :candidate-record candidate-record
                       :accepted-record accepted-record
                       :rejected-record rejected-record
                       :boundary-record boundary-record
                       :evidence-link-record evidence-link-record
                       :lineage-record lineage-record})))
        rejected-records
        (p15-s23-stage3-seedless-compiler-candidate-rejected-records
         source-path candidate)
        artifact-base
        {:kind
         :gravity/p15-s23-stage3-seedless-compiler-candidate-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-stage3-seedless-compiler-candidate
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :compiler-source-inventory-artifact
         (select-keys inventory-artifact
                      [:kind :artifact-id :inventory-id
                       :source-inventory :capability-based-proof])
         :stage2-whole-language-compiler-artifact
         (select-keys stage2-whole-artifact
                      [:kind :artifact-id :proof-id :accepted-record
                       :rejected-record :boundary-record
                       :capability-based-proof])
         :whole-language-compiler-artifact
         (select-keys whole-compiler-artifact
                      [:kind :artifact-id :proof-id
                       :compiler-artifact-manifest
                       :accepted-application-compile-record
                       :rejected-application-diagnostic-record
                       :capability-based-proof])
         :stage2-compiler-driver-artifact
         (select-keys driver-artifact
                      [:kind :artifact-id :proof-id :accepted-record
                       :rejected-record :boundary-record
                       :capability-based-proof])
         :stage2-source-front-end-artifact
         (select-keys source-front-end-artifact
                      [:kind :artifact-id :proof-id
                       :rule-record :accepted-record
                       :boundary-record :capability-based-proof])
         :stage2-front-end-executor-artifact
         (select-keys front-end-executor-artifact
                      [:kind :artifact-id :proof-id
                       :rule-record :accepted-record
                       :boundary-record :capability-based-proof])
         :stage2-plan-emitter-artifact
         (select-keys plan-emitter-artifact
                      [:kind :artifact-id :proof-id
                       :rule-record :accepted-record
                       :boundary-record :capability-based-proof])
         :stage2-runtime-executor-artifact
         (select-keys runtime-executor-artifact
                      [:kind :artifact-id :proof-id
                       :rule-record :accepted-record
                       :boundary-record :capability-based-proof])
         :stage2-runtime-kernel-artifact
         (select-keys runtime-kernel-artifact
                      [:kind :artifact-id :proof-id
                       :rule-record :accepted-record
                       :boundary-record :capability-based-proof])
         :accepted-app-execution-artifact
         (select-keys accepted-artifact
                      [:kind :artifact-id :proof-id
                       :accepted-output-comparison
                       :compiled-plan-execution-trace
                       :capability-based-proof])
         :rejected-app-diagnostic-artifact
         (select-keys rejected-artifact
                      [:kind :artifact-id :proof-id
                       :rejected-app-diagnostic-records
                       :capability-based-proof])
         :source-record source-record
         :candidate-record candidate-record
         :accepted-record accepted-record
         :rejected-record rejected-record
         :boundary-record boundary-record
         :evidence-link-record evidence-link-record
         :lineage-record lineage-record
         :seedless-compiler-candidate?
         (get-in proof-contract
                 [:self-hosting-claims
                  :seedless-compiler-candidate?])
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-stage3-seedless-compiler-candidate-fixtures
         [{:fixture source-path
           :status :accepted
           :source-components (:observed-components source-record)}
          {:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :stdout (:seedless-candidate-output accepted-record)
           :stage2-plan-id (:stage2-plan-id accepted-record)}]
         :rejected-p15-s23-stage3-seedless-compiler-candidate-fixtures
         rejected-records
         :p15-s23-stage3-seedless-compiler-candidate-diagnostic-stream
         (p15-s23-stage3-seedless-compiler-candidate-diagnostic-stream
          source-path proof-id)
         :p15-s23-stage3-seedless-compiler-candidate-results
         {:accepted-fixtures 2
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-stage3-seedless-compiler-candidate-diagnostic-ids)
          :source-component-count
          (count (:observed-components source-record))
          :accepted-app-output
          (:seedless-candidate-output accepted-record)
          :rejected-diagnostics
          (:seedless-candidate-diagnostics rejected-record)
          :compiler-path-seedless?
          (:compiler-path-seedless? candidate-record)
          :clojure-stage0-verifier?
          (:clojure-stage0-verifier? boundary-record)
          :clojure-stage0-release-compiler?
          (:clojure-stage0-release-compiler? boundary-record)
          :full-language-compiler-self-hosted? false
          :clojure-seed-retired? false
          :status :candidate}
         :diagnostics []}
        proof (p15-s23-stage3-seedless-compiler-candidate-proof
               artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-stage3-seedless-compiler-candidate-source-artifact
  [source-path]
  (p15-s23-cached-source-artifact
   :p15-s23-stage3-seedless-compiler-candidate
   source-path
   #(p15-s23-stage3-seedless-compiler-candidate-source-artifact*
     source-path)))

(defn p15-s23-stage3-seedless-compiler-candidate-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-stage3-seedless-compiler-candidate-fail!
     "P15S23AA001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-stage3-seedless-compiler-candidate-source-artifact path))

(defn p15-s23-stage3-seedless-compiler-candidate-evidence
  []
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (let [artifact
              (p15-s23-stage3-seedless-compiler-candidate-file-artifact
               source-path)
              proof (:capability-based-proof artifact)]
          {:status :verified
           :artifact (:kind artifact)
           :artifact-id (:artifact-id artifact)
           :proof-id (:proof-id artifact)
           :source-path source-path
           :seedless-compiler-candidate-present?
           (:seedless-compiler-candidate-present? proof)
           :compiler-path-seedless? (:compiler-path-seedless? proof)
           :accepted-output-equivalent?
           (:accepted-output-equivalent? proof)
           :rejected-diagnostics-equivalent?
           (:rejected-diagnostics-equivalent? proof)
           :clojure-stage0-verifier-absent?
           (:clojure-stage0-verifier-absent? proof)
           :clojure-stage0-release-compiler-absent?
           (:clojure-stage0-release-compiler-absent? proof)
           :final-equivalence-bundle-complete? false
           :full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? artifact)
           :clojure-seed-retired?
           (:clojure-seed-retired? artifact)})
        (catch Exception _
          nil)))))

