(defn p15-s23-stage3-self-hosted-application-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage3-self-hosted-application-diagnostic-messages
              id
              "P15-S23 stage3 self-hosted application execution failed")
         (merge {:source-span {:source source-path}
                 :stage
                 :p15-s23-stage3-self-hosted-application-execution
                 :diagnostic-family
                 :p15-s23-stage3-self-hosted-application-execution
                 :value value
                 :remediation "Run the accepted and rejected application fixtures through the stage3 seedless compiler candidate, preserve diagnostics, keep runtime capability evidence linked, and do not claim Clojure seed retirement until the final proof exists."}
                data)))

(defn p15-s23-stage3-self-hosted-application-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage3-self-hosted-application-execution
   :source-span {:source source-path}
   :message
   (get p15-s23-stage3-self-hosted-application-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_p15_s23_stage3_self_hosted_application_execution})

(defn p15-s23-stage3-self-hosted-application-record
  [source-path proof-contract]
  (let [application-stage (:application-stage proof-contract)
        preserves (set (:preserves proof-contract))
        emits (set (:emits proof-contract))
        requires (set (:requires application-stage))
        missing-preserves
        (set/difference
         p15-s23-stage3-self-hosted-application-required-preserves
         preserves)
        missing-emits
        (set/difference
         p15-s23-stage3-self-hosted-application-required-emits
         emits)
        missing-requires
        (set/difference
         p15-s23-stage3-self-hosted-application-required-links
         requires)]
    {:artifact :gravity/p15-s23-stage3-self-hosted-application-execution-record
     :source-path source-path
     :stage (:stage proof-contract)
     :application-stage (:stage application-stage)
     :toolchain (:toolchain proof-contract)
     :verified-by (:verified-by proof-contract)
     :accepted-fixture (:accepted-fixture application-stage)
     :rejected-fixtures (:rejected-fixtures application-stage)
     :missing-preserves (vec (sort missing-preserves))
     :missing-emits (vec (sort missing-emits))
     :missing-requires (vec (sort missing-requires))
     :status
     (if (and (= :gravity/stage3-self-hosted-application-execution
                 (:artifact proof-contract))
              (= :p15-s23-stage3-self-hosted-application-execution
                 (:stage proof-contract))
              (= :p15-s23-stage3-seedless-compiler-candidate
                 (:toolchain proof-contract))
              (= :emit-and-run-stage3-self-hosted-application
                 (:stage application-stage))
              (= :gravity-stage3-verifier (:verified-by proof-contract))
              (empty? missing-preserves)
              (empty? missing-emits)
              (empty? missing-requires))
       :complete
       :failed)}))

(defn p15-s23-stage3-self-hosted-application-link-record
  [equivalence candidate driver runtime accepted rejected]
  (let [links
        [{:link :stage3-equivalence-bundle
          :artifact (:kind equivalence)
          :artifact-id (:artifact-id equivalence)}
         {:link :stage3-seedless-compiler-candidate
          :artifact (:kind candidate)
          :artifact-id (:artifact-id candidate)}
         {:link :stage2-compiler-driver
          :artifact (:kind driver)
          :artifact-id (:artifact-id driver)}
         {:link :stage2-runtime-kernel
          :artifact (:kind runtime)
          :artifact-id (:artifact-id runtime)}
         {:link :accepted-app-execution-proof
          :artifact (:kind accepted)
          :artifact-id (:artifact-id accepted)}
         {:link :rejected-app-diagnostic-proof
          :artifact (:kind rejected)
          :artifact-id (:artifact-id rejected)}]
        links-with-status
        (mapv (fn [link]
                (assoc link
                       :status
                       (if (re-find #"^sha256:"
                                    (str (:artifact-id link)))
                         :verified
                         :missing)))
              links)
        covered (set (map :link links-with-status))]
    {:artifact :gravity/p15-s23-stage3-self-hosted-application-link-record
     :links links-with-status
     :required-links
     (vec (sort p15-s23-stage3-self-hosted-application-required-links))
     :required-links-covered?
     (= p15-s23-stage3-self-hosted-application-required-links covered)
     :all-artifacts-identified?
     (every? #(= :verified (:status %)) links-with-status)
     :status
     (if (and (= p15-s23-stage3-self-hosted-application-required-links
                 covered)
              (every? #(= :verified (:status %)) links-with-status))
       :complete
       :failed)}))

(defn p15-s23-stage3-self-hosted-application-run-record
  [proof-contract equivalence candidate driver runtime]
  (let [output
        (get-in equivalence [:accepted-record :candidate-output])
        app-artifact-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:fixture p15-s23-accepted-app-source-path
                       :output output
                       :toolchain (:artifact-id candidate)
                       :driver (:artifact-id driver)
                       :runtime (:artifact-id runtime)})))
        boundary (:toolchain-boundary proof-contract)]
    {:artifact :gravity/p15-s23-stage3-self-hosted-application-run-record
     :fixture p15-s23-accepted-app-source-path
     :application-artifact-id app-artifact-id
     :compiled-by (:compiled-by boundary)
     :compiler (:compiler boundary)
     :verified-by (:verified-by boundary)
     :executed-by (:executed-by boundary)
     :stage3-toolchain-uses-clojure-seed?
     (true? (:stage3-toolchain-uses-clojure-seed? boundary))
     :expected-output p15-s23-accepted-app-expected-stdout
     :stdout output
     :accepted-output-equivalent?
     (= output p15-s23-accepted-app-expected-stdout)
     :stage3-equivalence-complete?
     (true? (get-in equivalence
                    [:capability-based-proof
                     :stage3-equivalence-bundle-present?]))
     :candidate-seedless?
     (true? (get-in candidate
                    [:capability-based-proof
                     :compiler-path-seedless?]))
     :driver-executed?
     (true? (get-in driver
                    [:capability-based-proof
                     :stage2-compiler-driver-executed?]))
     :runtime-kernel-executed?
     (true? (get-in runtime
                    [:capability-based-proof
                     :stage2-runtime-kernel-executed?]))
     :status
     (if (and (= output p15-s23-accepted-app-expected-stdout)
              (true? (get-in equivalence
                             [:capability-based-proof
                              :stage3-equivalence-bundle-present?]))
              (true? (get-in candidate
                             [:capability-based-proof
                              :compiler-path-seedless?]))
              (true? (get-in driver
                             [:capability-based-proof
                              :stage2-compiler-driver-executed?]))
              (true? (get-in runtime
                             [:capability-based-proof
                              :stage2-runtime-kernel-executed?]))
              (false? (:stage3-toolchain-uses-clojure-seed? boundary)))
       :complete
       :failed)}))

(defn p15-s23-stage3-self-hosted-application-rejected-record
  [equivalence rejected]
  (let [stage3-diagnostics
        (set (get-in equivalence
                     [:rejected-record :candidate-diagnostics]))
        rejected-diagnostics
        (set (map :diagnostic
                  (:rejected-app-diagnostic-records rejected)))
        expected #{"L2-FUNCTION-ARITY" "L2-BUILTIN-ARITY"}]
    {:artifact :gravity/p15-s23-stage3-self-hosted-application-rejected-record
     :rejected-fixtures (mapv :fixture p15-s23-rejected-app-fixtures)
     :stage3-diagnostics (vec (sort stage3-diagnostics))
     :rejected-proof-diagnostics (vec (sort rejected-diagnostics))
     :expected-diagnostics (vec (sort expected))
     :rejected-diagnostics-equivalent?
     (= stage3-diagnostics rejected-diagnostics expected)
     :status
     (if (= stage3-diagnostics rejected-diagnostics expected)
       :complete
       :failed)}))

(defn p15-s23-stage3-self-hosted-application-toolchain-record
  [proof-contract equivalence candidate driver runtime]
  (let [boundary (:toolchain-boundary proof-contract)]
    {:artifact :gravity/p15-s23-stage3-self-hosted-application-toolchain-record
     :compiler (:compiler boundary)
     :compiled-by (:compiled-by boundary)
     :verified-by (:verified-by boundary)
     :executed-by (:executed-by boundary)
     :stage3-toolchain-uses-clojure-seed?
     (true? (:stage3-toolchain-uses-clojure-seed? boundary))
     :stage3-self-hosted-application-run?
     (true? (:stage3-self-hosted-application-run? boundary))
     :rejected-application-fails-closed?
     (true? (:rejected-application-fails-closed? boundary))
     :final-seed-retirement-proof-present?
     (true? (:final-seed-retirement-proof-present? boundary))
     :equivalence-bundle-complete?
     (true? (get-in equivalence
                    [:capability-based-proof
                     :stage3-equivalence-bundle-present?]))
     :candidate-seedless?
     (true? (get-in candidate
                    [:capability-based-proof
                     :compiler-path-seedless?]))
     :stage2-driver-uses-gravity-front-end?
     (true? (get-in driver
                    [:capability-based-proof
                     :stage2-source-front-end-used?]))
     :runtime-uses-gravity-primitives?
     (true? (get-in runtime
                    [:capability-based-proof
                     :gravity-runtime-primitives-used?]))
     :status
     (if (and (false? (:stage3-toolchain-uses-clojure-seed? boundary))
              (true? (:stage3-self-hosted-application-run? boundary))
              (true? (:rejected-application-fails-closed? boundary))
              (false? (:final-seed-retirement-proof-present? boundary))
              (true? (get-in equivalence
                             [:capability-based-proof
                              :stage3-equivalence-bundle-present?]))
              (true? (get-in candidate
                             [:capability-based-proof
                              :compiler-path-seedless?]))
              (true? (get-in driver
                             [:capability-based-proof
                              :stage2-source-front-end-used?]))
              (true? (get-in runtime
                             [:capability-based-proof
                              :gravity-runtime-primitives-used?])))
       :complete
       :failed)}))

(defn p15-s23-stage3-self-hosted-application-runtime-record
  [runtime accepted]
  (let [runtime-proof (:capability-based-proof runtime)
        accepted-output
        (get-in accepted [:accepted-output-comparison :accepted-stdout])]
    {:artifact :gravity/p15-s23-stage3-self-hosted-application-runtime-record
     :runtime-artifact-id (:artifact-id runtime)
     :runtime-kind (:kind runtime)
     :accepted-output accepted-output
     :runtime-kernel-present?
     (true? (:stage2-runtime-kernel-present? runtime-proof))
     :runtime-kernel-executed?
     (true? (:stage2-runtime-kernel-executed? runtime-proof))
     :gravity-runtime-primitives-used?
     (true? (:gravity-runtime-primitives-used? runtime-proof))
     :capability-proof-present?
     (true? (get-in runtime
                    [:capability-based-proof
                     :does-not-use-clojure-runtime-primitives?]))
     :accepted-output-equivalent?
     (= accepted-output p15-s23-accepted-app-expected-stdout)
     :status
     (if (and (true? (:stage2-runtime-kernel-present? runtime-proof))
              (true? (:stage2-runtime-kernel-executed? runtime-proof))
              (true? (:gravity-runtime-primitives-used? runtime-proof))
              (true? (:does-not-use-clojure-runtime-primitives?
                      runtime-proof))
              (= accepted-output p15-s23-accepted-app-expected-stdout))
       :complete
       :failed)}))

(defn p15-s23-stage3-self-hosted-application-boundary-record
  [proof-contract run rejected toolchain runtime]
  (let [claims (:self-hosting-claims proof-contract)]
    {:artifact :gravity/p15-s23-stage3-self-hosted-application-boundary-record
     :stage3-self-hosted-application-run?
     (true? (:stage3-self-hosted-application-run? claims))
     :full-language-compiler-self-hosted?
     (true? (:full-language-compiler-self-hosted? claims))
     :clojure-seed-retired?
     (true? (:clojure-seed-retired? claims))
     :final-seed-retirement-proof-present?
     (true? (get-in proof-contract
                    [:toolchain-boundary
                     :final-seed-retirement-proof-present?]))
     :accepted-run-complete? (= :complete (:status run))
     :rejected-run-complete? (= :complete (:status rejected))
     :toolchain-record-complete? (= :complete (:status toolchain))
     :runtime-record-complete? (= :complete (:status runtime))
     :status
     (if (and (true? (:stage3-self-hosted-application-run? claims))
              (false? (:full-language-compiler-self-hosted? claims))
              (false? (:clojure-seed-retired? claims))
              (false? (get-in proof-contract
                              [:toolchain-boundary
                               :final-seed-retirement-proof-present?]))
              (= :complete (:status run))
              (= :complete (:status rejected))
              (= :complete (:status toolchain))
              (= :complete (:status runtime)))
       :complete
       :failed)}))

(defn p15-s23-stage3-self-hosted-application-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)]
    (vec
     (keep
      identity
      [(when-not (= :gravity/stage3-self-hosted-application-execution
                    (:artifact proof-contract))
         (p15-s23-stage3-self-hosted-application-diagnostic-record
          source-path "P15S23AC001" proof-contract
          {:required [:gravity/stage3-self-hosted-application-execution]}))
       (when-not (= :complete (get-in candidate [:execution-record :status]))
         (p15-s23-stage3-self-hosted-application-diagnostic-record
          source-path "P15S23AC001" (:execution-record candidate)
          {:required [:stage3-self-hosted-application-execution-record]}))
       (when-not (= :complete (get-in candidate [:equivalence-record :status]))
         (p15-s23-stage3-self-hosted-application-diagnostic-record
          source-path "P15S23AC002" (:equivalence-record candidate)
          {:required [:stage3-equivalence-bundle]}))
       (when-not (= :complete (get-in candidate [:accepted-run-record :status]))
         (p15-s23-stage3-self-hosted-application-diagnostic-record
          source-path "P15S23AC003" (:accepted-run-record candidate)
          {:expected-output p15-s23-accepted-app-expected-stdout}))
       (when-not (= :complete (get-in candidate [:rejected-record :status]))
         (p15-s23-stage3-self-hosted-application-diagnostic-record
          source-path "P15S23AC004" (:rejected-record candidate)
          {:expected-diagnostics ["L2-BUILTIN-ARITY"
                                  "L2-FUNCTION-ARITY"]}))
       (when-not (= :complete (get-in candidate [:toolchain-record :status]))
         (p15-s23-stage3-self-hosted-application-diagnostic-record
          source-path "P15S23AC005" (:toolchain-record candidate)
          {:required [:stage3-seedless-compiler-candidate
                      :stage2-compiler-driver]}))
       (when-not (= :complete (get-in candidate [:runtime-record :status]))
         (p15-s23-stage3-self-hosted-application-diagnostic-record
          source-path "P15S23AC006" (:runtime-record candidate)
          {:required [:stage2-runtime-kernel
                      :runtime-capability-manifest]}))
       (when-not (= :complete (get-in candidate [:evidence-link-record :status]))
         (p15-s23-stage3-self-hosted-application-diagnostic-record
          source-path "P15S23AC007" (:evidence-link-record candidate)
          {:required-links
           p15-s23-stage3-self-hosted-application-required-links}))
       (when (or (true? (get-in proof-contract
                                [:self-hosting-claims
                                 :full-language-compiler-self-hosted?]))
                 (true? (get-in proof-contract
                                [:self-hosting-claims
                                 :clojure-seed-retired?])))
         (p15-s23-stage3-self-hosted-application-diagnostic-record
          source-path "P15S23AC008"
          (:self-hosting-claims proof-contract)
          {:reason :stage3_application_execution_is_not_final_seed_retirement_proof}))]))))

(defn p15-s23-stage3-self-hosted-application-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-stage3-self-hosted-application-diagnostic-stream
   :stage :p15-s23-stage3-self-hosted-application-execution
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic id
            :severity :error
            :message
            (get p15-s23-stage3-self-hosted-application-diagnostic-messages
                 id)
            :stable? true})
         p15-s23-stage3-self-hosted-application-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage3-self-hosted-application-rejected-records
  [source-path candidate]
  (let [base candidate
        candidates
        [{:fixture :internal-p15-s23-stage3-self-hosted-application-missing-contract
          :expected-diagnostic "P15S23AC001"
          :candidate (assoc base :proof-contract {})}
         {:fixture :internal-p15-s23-stage3-self-hosted-application-equivalence-gap
          :expected-diagnostic "P15S23AC002"
          :candidate (assoc-in base [:equivalence-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-self-hosted-application-output-gap
          :expected-diagnostic "P15S23AC003"
          :candidate (assoc-in base [:accepted-run-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-self-hosted-application-rejected-gap
          :expected-diagnostic "P15S23AC004"
          :candidate (assoc-in base [:rejected-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-self-hosted-application-toolchain-gap
          :expected-diagnostic "P15S23AC005"
          :candidate (assoc-in base [:toolchain-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-self-hosted-application-runtime-gap
          :expected-diagnostic "P15S23AC006"
          :candidate (assoc-in base [:runtime-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-self-hosted-application-evidence-gap
          :expected-diagnostic "P15S23AC007"
          :candidate (assoc-in base [:evidence-link-record :status] :failed)}
         {:fixture :internal-p15-s23-stage3-self-hosted-application-overclaim
          :expected-diagnostic "P15S23AC008"
          :candidate
          (-> base
              (assoc-in [:proof-contract :self-hosting-claims
                         :full-language-compiler-self-hosted?]
                        true)
              (assoc-in [:proof-contract :self-hosting-claims
                         :clojure-seed-retired?]
                        true))}]]
    (mapv (fn [{:keys [fixture expected-diagnostic candidate]}]
            {:fixture fixture
             :status :rejected
             :expected-diagnostic expected-diagnostic
             :diagnostics
             (p15-s23-stage3-self-hosted-application-proof-diagnostics
              source-path candidate)})
          candidates)))

(defn p15-s23-stage3-self-hosted-application-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-stage3-self-hosted-application-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat
              #(map :diagnostic (:diagnostics %))
              (:rejected-p15-s23-stage3-self-hosted-application-fixtures
               artifact)))]
    {:stage3-self-hosted-application-authored-in-gravity? true
     :status :complete
     :task "P15-S23"
     :stage3-self-hosted-application-execution-present?
     (= :gravity/stage3-self-hosted-application-execution
        (get-in artifact [:proof-contract :artifact]))
     :stage3-equivalence-bundle-linked?
     (= :complete (get-in artifact [:equivalence-record :status]))
     :accepted-application-run?
     (= :complete (get-in artifact [:accepted-run-record :status]))
     :accepted-output-equivalent?
     (true? (get-in artifact
                    [:accepted-run-record
                     :accepted-output-equivalent?]))
     :rejected-application-fails-closed?
     (true? (get-in artifact
                    [:rejected-record
                     :rejected-diagnostics-equivalent?]))
     :stage3-toolchain-seedless?
     (false? (get-in artifact
                     [:toolchain-record
                      :stage3-toolchain-uses-clojure-seed?]))
     :toolchain-boundary-recorded?
     (= :complete (get-in artifact [:toolchain-record :status]))
     :runtime-capability-recorded?
     (= :complete (get-in artifact [:runtime-record :status]))
     :evidence-links-covered?
     (true? (get-in artifact
                    [:evidence-link-record
                     :required-links-covered?]))
     :boundary-recorded?
     (= :complete (get-in artifact [:boundary-record :status]))
     :does-not-claim-final-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-final-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset?
      (set p15-s23-stage3-self-hosted-application-diagnostic-ids)
      rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-stage3-self-hosted-application-diagnostic-ids)
        diagnostics)
     :limitations
     {:stage3-self-hosted-application-run? true
      :full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :final-seed-retirement-proof-present? false
      :next-required-capability :emit_final_seed_retirement_proof}}))

(defn p15-s23-stage3-self-hosted-application-source-artifact*
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-stage3-self-hosted-application-execution)
        equivalence-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage3-equivalence-bundle)
        candidate-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage3-seedless-compiler-candidate)
        driver-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-compiler-driver)
        runtime-artifact
        (p15-s23-current-candidate-artifact-evidence
         :stage2-runtime-kernel)
        accepted-artifact
        (p15-s23-current-candidate-artifact-evidence
         :accepted-app-execution-proof)
        rejected-artifact
        (p15-s23-current-candidate-artifact-evidence
         :rejected-app-diagnostic-proof)
        execution-record
        (p15-s23-stage3-self-hosted-application-record
         source-path proof-contract)
        equivalence-record
        {:artifact :gravity/p15-s23-stage3-self-hosted-application-equivalence-record
         :equivalence-artifact-id (:artifact-id equivalence-artifact)
         :equivalence-bundle-complete?
         (true? (get-in equivalence-artifact
                        [:capability-based-proof
                         :stage3-equivalence-bundle-present?]))
         :accepted-output-equivalent?
         (true? (get-in equivalence-artifact
                        [:capability-based-proof
                         :accepted-output-equivalent?]))
         :rejected-diagnostics-equivalent?
         (true? (get-in equivalence-artifact
                        [:capability-based-proof
                         :rejected-diagnostics-equivalent?]))
         :status
         (if (and (true? (get-in equivalence-artifact
                                  [:capability-based-proof
                                   :stage3-equivalence-bundle-present?]))
                  (true? (get-in equivalence-artifact
                                  [:capability-based-proof
                                   :accepted-output-equivalent?]))
                  (true? (get-in equivalence-artifact
                                  [:capability-based-proof
                                   :rejected-diagnostics-equivalent?])))
           :complete
           :failed)}
        accepted-run-record
        (p15-s23-stage3-self-hosted-application-run-record
         proof-contract equivalence-artifact candidate-artifact
         driver-artifact runtime-artifact)
        rejected-record
        (p15-s23-stage3-self-hosted-application-rejected-record
         equivalence-artifact rejected-artifact)
        toolchain-record
        (p15-s23-stage3-self-hosted-application-toolchain-record
         proof-contract equivalence-artifact candidate-artifact
         driver-artifact runtime-artifact)
        runtime-record
        (p15-s23-stage3-self-hosted-application-runtime-record
         runtime-artifact accepted-artifact)
        evidence-link-record
        (p15-s23-stage3-self-hosted-application-link-record
         equivalence-artifact candidate-artifact driver-artifact
         runtime-artifact accepted-artifact rejected-artifact)
        boundary-record
        (p15-s23-stage3-self-hosted-application-boundary-record
         proof-contract accepted-run-record rejected-record
         toolchain-record runtime-record)
        candidate {:proof-contract proof-contract
                   :execution-record execution-record
                   :equivalence-record equivalence-record
                   :accepted-run-record accepted-run-record
                   :rejected-record rejected-record
                   :toolchain-record toolchain-record
                   :runtime-record runtime-record
                   :evidence-link-record evidence-link-record
                   :boundary-record boundary-record}
        diagnostics
        (p15-s23-stage3-self-hosted-application-proof-diagnostics
         source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-stage3-self-hosted-application-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :proof-contract proof-contract
                       :execution-record execution-record
                       :equivalence-record equivalence-record
                       :accepted-run-record accepted-run-record
                       :rejected-record rejected-record
                       :toolchain-record toolchain-record
                       :runtime-record runtime-record
                       :evidence-link-record evidence-link-record
                       :boundary-record boundary-record})))
        rejected-records
        (p15-s23-stage3-self-hosted-application-rejected-records
         source-path candidate)
        artifact-base
        {:kind
         :gravity/p15-s23-stage3-self-hosted-application-execution-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-stage3-self-hosted-application-execution
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :stage3-equivalence-bundle-artifact
         (select-keys equivalence-artifact
                      [:kind :artifact-id :proof-id :accepted-record
                       :rejected-record :boundary-record
                       :capability-based-proof])
         :stage3-seedless-compiler-candidate-artifact
         (select-keys candidate-artifact
                      [:kind :artifact-id :proof-id :accepted-record
                       :rejected-record :boundary-record
                       :capability-based-proof])
         :stage2-compiler-driver-artifact
         (select-keys driver-artifact
                      [:kind :artifact-id :proof-id :accepted-record
                       :boundary-record :capability-based-proof])
         :stage2-runtime-kernel-artifact
         (select-keys runtime-artifact
                      [:kind :artifact-id :proof-id :accepted-record
                       :boundary-record :capability-based-proof])
         :accepted-app-execution-artifact
         (select-keys accepted-artifact
                      [:kind :artifact-id :proof-id
                       :accepted-output-comparison
                       :capability-based-proof])
         :rejected-app-diagnostic-artifact
         (select-keys rejected-artifact
                      [:kind :artifact-id :proof-id
                       :rejected-app-diagnostic-records
                       :capability-based-proof])
         :execution-record execution-record
         :equivalence-record equivalence-record
         :accepted-run-record accepted-run-record
         :rejected-record rejected-record
         :toolchain-record toolchain-record
         :runtime-record runtime-record
         :evidence-link-record evidence-link-record
         :boundary-record boundary-record
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-stage3-self-hosted-application-fixtures
         [{:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :stdout (:stdout accepted-run-record)
           :application-artifact-id
           (:application-artifact-id accepted-run-record)}]
         :rejected-p15-s23-stage3-self-hosted-application-fixtures
         rejected-records
         :p15-s23-stage3-self-hosted-application-diagnostic-stream
         (p15-s23-stage3-self-hosted-application-diagnostic-stream
          source-path proof-id)
         :p15-s23-stage3-self-hosted-application-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-stage3-self-hosted-application-diagnostic-ids)
          :accepted-app-output (:stdout accepted-run-record)
          :rejected-diagnostics (:stage3-diagnostics rejected-record)
          :stage3-self-hosted-application-run? true
          :full-language-compiler-self-hosted? false
          :clojure-seed-retired? false
          :status :complete}
         :diagnostics []}
        proof (p15-s23-stage3-self-hosted-application-proof
               artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-stage3-self-hosted-application-source-artifact
  [source-path]
  (p15-s23-cached-source-artifact
   :p15-s23-stage3-self-hosted-application-execution
   source-path
   #(p15-s23-stage3-self-hosted-application-source-artifact*
     source-path)))

(defn p15-s23-stage3-self-hosted-application-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-stage3-self-hosted-application-fail!
     "P15S23AC001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-stage3-self-hosted-application-source-artifact path))

(defn p15-s23-stage3-self-hosted-application-evidence
  []
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (let [artifact
              (p15-s23-stage3-self-hosted-application-file-artifact
               source-path)
              proof (:capability-based-proof artifact)]
          {:status :verified
           :artifact (:kind artifact)
           :artifact-id (:artifact-id artifact)
           :proof-id (:proof-id artifact)
           :source-path source-path
           :stage3-self-hosted-application-execution-present?
           (:stage3-self-hosted-application-execution-present? proof)
           :accepted-application-run? (:accepted-application-run? proof)
           :accepted-output-equivalent?
           (:accepted-output-equivalent? proof)
           :rejected-application-fails-closed?
           (:rejected-application-fails-closed? proof)
           :stage3-toolchain-seedless?
           (:stage3-toolchain-seedless? proof)
           :runtime-capability-recorded?
           (:runtime-capability-recorded? proof)
           :full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? artifact)
           :clojure-seed-retired?
           (:clojure-seed-retired? artifact)})
        (catch Exception _
          nil)))))

