(defn p15-s23-final-seed-retirement-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-final-seed-retirement-diagnostic-messages
              id
              "P15-S23 final seed-retirement proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-final-seed-retirement-proof
                 :diagnostic-family :p15-s23-final-seed-retirement
                 :value value
                 :remediation "Only emit final self-hosting and seed-retirement claims when every required evidence link is present, the stage3 candidate and application path are seedless, release governance has no remaining seed blocker, TCB closure retires the Clojure seed boundary, and provenance closure records the seedless release boundary."}
                data)))

(defn p15-s23-final-seed-retirement-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-final-seed-retirement-proof
   :source-span {:source source-path}
   :message
   (get p15-s23-final-seed-retirement-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_p15_s23_final_seed_retirement_proof})

	(defn p15-s23-final-seed-retirement-base-evidence
	  []
	  {})

(defn p15-s23-final-seed-retirement-link-record
  [proof-contract evidence]
  (let [required (set (:required-evidence-links proof-contract))
        missing (set/difference required (set (keys evidence)))
        incomplete
        (set (for [[k v] evidence
                   :when (and (contains? required k)
                              (not (p15-s23-evidence-present? v)))]
               k))
        missing-links (set/union missing incomplete)
        links
        (mapv (fn [k]
                (let [v (get evidence k)]
                  {:link k
                   :artifact (:artifact v)
                   :artifact-id (:artifact-id v)
                   :proof-id (:proof-id v)
                   :status (:status v)
                   :present? (p15-s23-evidence-present? v)}))
              (sort required))]
    {:artifact :gravity/p15-s23-final-seed-retirement-link-record
     :required-links (vec (sort required))
     :links links
     :missing-links (vec (sort missing-links))
     :all-required-links-present? (empty? missing-links)
     :status (if (empty? missing-links) :complete :failed)}))

(defn p15-s23-final-seedless-boundary-record
  [proof-contract evidence]
  (let [boundary (:final-boundary proof-contract)
        seedless (:stage3-seedless-compiler-candidate evidence)
        equivalence (:stage3-equivalence-bundle evidence)
        app (:stage3-self-hosted-application-execution evidence)
        complete?
        (and (false? (:compiler-path-uses-clojure-seed? boundary))
             (false? (:runtime-path-uses-clojure-seed? boundary))
             (false? (:release-compiler-uses-clojure-seed? boundary))
             (false? (:verification-host-in-release-boundary? boundary))
             (true? (:compiler-path-seedless? seedless))
             (true? (:clojure-stage0-verifier-absent? seedless))
             (true? (:clojure-stage0-release-compiler-absent?
                     seedless))
             (true? (:stage3-toolchain-seedless? app))
             (true? (:stage3-equivalence-bundle-present?
                     equivalence)))]
    {:artifact :gravity/p15-s23-final-seedless-boundary-record
     :compiler-path-uses-clojure-seed?
     (:compiler-path-uses-clojure-seed? boundary)
     :runtime-path-uses-clojure-seed?
     (:runtime-path-uses-clojure-seed? boundary)
     :release-compiler-uses-clojure-seed?
     (:release-compiler-uses-clojure-seed? boundary)
     :verification-host (:verification-host boundary)
     :verification-host-in-release-boundary?
     (:verification-host-in-release-boundary? boundary)
     :stage3-compiler-path-seedless?
     (true? (:compiler-path-seedless? seedless))
     :stage3-verifier-absent-from-clojure?
     (true? (:clojure-stage0-verifier-absent? seedless))
     :stage3-release-compiler-absent-from-clojure?
     (true? (:clojure-stage0-release-compiler-absent? seedless))
     :stage3-toolchain-seedless?
     (true? (:stage3-toolchain-seedless? app))
     :stage3-equivalence-bundle-present?
     (true? (:stage3-equivalence-bundle-present? equivalence))
     :clojure-seed-boundary? (not complete?)
     :status (if complete? :complete :failed)}))

(defn p15-s23-final-stage3-execution-record
  [evidence]
  (let [equivalence (:stage3-equivalence-bundle evidence)
        app (:stage3-self-hosted-application-execution evidence)
        complete?
        (and (true? (:stage3-equivalence-bundle-present? equivalence))
             (true? (:accepted-output-equivalent? equivalence))
             (true? (:rejected-diagnostics-equivalent? equivalence))
             (true? (:rebuild-equivalence-complete? equivalence))
             (true? (:conformance-evidence-complete? equivalence))
             (true? (:stage3-self-hosted-application-execution-present?
                     app))
             (true? (:accepted-application-run? app))
             (true? (:rejected-application-fails-closed? app))
             (true? (:runtime-capability-recorded? app)))]
    {:artifact :gravity/p15-s23-final-stage3-execution-record
     :stage3-equivalence-bundle-present?
     (true? (:stage3-equivalence-bundle-present? equivalence))
     :accepted-output-equivalent?
     (true? (:accepted-output-equivalent? equivalence))
     :rejected-diagnostics-equivalent?
     (true? (:rejected-diagnostics-equivalent? equivalence))
     :rebuild-equivalence-complete?
     (true? (:rebuild-equivalence-complete? equivalence))
     :conformance-evidence-complete?
     (true? (:conformance-evidence-complete? equivalence))
     :stage3-self-hosted-application-execution-present?
     (true? (:stage3-self-hosted-application-execution-present? app))
     :accepted-application-run?
     (true? (:accepted-application-run? app))
     :rejected-application-fails-closed?
     (true? (:rejected-application-fails-closed? app))
     :runtime-capability-recorded?
     (true? (:runtime-capability-recorded? app))
     :status (if complete? :complete :failed)}))

(defn p15-s23-final-release-decision-record
  [proof-contract evidence boundary-record stage3-record]
  (let [governance (:governance-and-package-release-record evidence)
        previous-blockers (set (:release-blockers governance))
        seed-blocker-retired?
        (and (= #{:clojure-seed-retired} previous-blockers)
             (false? (:clojure-seed-boundary? boundary-record)))
        complete?
        (and (= :complete (:status boundary-record))
             (= :complete (:status stage3-record))
             (p15-s23-evidence-present? governance)
             seed-blocker-retired?
             (true? (get-in proof-contract
                            [:self-hosting-claims
                             :full-language-compiler-self-hosted?]))
             (true? (get-in proof-contract
                            [:self-hosting-claims
                             :clojure-seed-retired?])))
        remaining-blockers
        (if complete? [] (vec (sort previous-blockers)))]
    {:artifact :gravity/p15-s23-final-release-decision-record
     :previous-registry-decision (:registry-decision governance)
     :previous-release-blockers (vec (sort previous-blockers))
     :retired-release-blockers
     (if seed-blocker-retired? [:clojure-seed-retired] [])
     :remaining-release-blockers remaining-blockers
     :seed-blocker-retired? seed-blocker-retired?
     :release-eligible? complete?
     :registry-publication-eligible? complete?
     :governance-and-package-policy-satisfied? complete?
     :status (if complete? :complete :failed)}))

(defn p15-s23-final-tcb-retirement-record
  [evidence boundary-record release-decision]
  (let [tcb (:trusted-computing-base-delta-record evidence)
        complete?
        (and (p15-s23-evidence-present? tcb)
             (= :complete (:status boundary-record))
             (= :complete (:status release-decision)))]
    {:artifact :gravity/p15-s23-final-tcb-retirement-record
     :prior-tcb-delta-record-id (:tcb-delta-record-id tcb)
     :prior-clojure-seed-still-trusted?
     (:clojure-seed-still-trusted? tcb)
     :prior-residual-trusted-count
     (:current-residual-trusted-count tcb)
     :compiler-seed-residual-count (if complete? 0 1)
     :clojure-seed-still-trusted? (not complete?)
     :clojure-seed-retired-from-release-boundary? complete?
     :whole-language-tcb-reduced? complete?
     :status (if complete? :complete :failed)}))

(defn p15-s23-final-provenance-closure-record
  [proof-contract evidence boundary-record stage3-record release-decision]
  (let [provenance (:bootstrap-provenance-attestation evidence)
        seedless (:stage3-seedless-compiler-candidate evidence)
        equivalence (:stage3-equivalence-bundle evidence)
        app (:stage3-self-hosted-application-execution evidence)
        complete?
        (and (p15-s23-evidence-present? provenance)
             (= :complete (:status boundary-record))
             (= :complete (:status stage3-record))
             (= :complete (:status release-decision))
             (true? (:revocation-clear? provenance))
             (true? (:auditor-query-passed? provenance)))]
    {:artifact :gravity/p15-s23-final-provenance-closure-record
     :prior-provenance-record-id (:provenance-record-id provenance)
     :canonical-payload-id (:canonical-payload-id provenance)
     :stage3-seedless-candidate-artifact-id (:artifact-id seedless)
     :stage3-equivalence-bundle-artifact-id (:artifact-id equivalence)
     :stage3-application-artifact-id (:artifact-id app)
     :release-compiler :gravity-stage3-release-compiler
     :verification-host
     (get-in proof-contract [:final-boundary :verification-host])
     :verification-host-in-release-boundary?
     (get-in proof-contract
             [:final-boundary :verification-host-in-release-boundary?])
     :revocation-clear? (true? (:revocation-clear? provenance))
     :auditor-query-passed?
     (true? (:auditor-query-passed? provenance))
     :status (if complete? :complete :failed)}))

(defn p15-s23-final-gate-completion-record
  [proof-contract link-record boundary-record stage3-record release-decision
   tcb-retirement provenance-closure]
  (let [claims (:self-hosting-claims proof-contract)
        complete?
        (and (= :complete (:status link-record))
             (= :complete (:status boundary-record))
             (= :complete (:status stage3-record))
             (= :complete (:status release-decision))
             (= :complete (:status tcb-retirement))
             (= :complete (:status provenance-closure))
             (true? (:full-language-compiler-self-hosted? claims))
             (true? (:clojure-seed-retired? claims))
             (false? (:clojure-seed-boundary? claims)))]
    {:artifact :gravity/p15-s23-final-gate-completion-record
     :full-language-compiler-self-hosted?
     (true? (:full-language-compiler-self-hosted? claims))
     :clojure-seed-retired? (true? (:clojure-seed-retired? claims))
     :clojure-seed-boundary? (:clojure-seed-boundary? claims)
     :next-required-capability
     (:next-required-capability proof-contract)
     :status (if complete? :complete :failed)}))

(defn p15-s23-final-seed-retirement-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        link-record (:evidence-link-record candidate)
        boundary-record (:boundary-record candidate)
        stage3-record (:stage3-execution-record candidate)
        release-decision (:release-decision-record candidate)
        tcb-retirement (:tcb-retirement-record candidate)
        provenance-closure (:provenance-closure-record candidate)
        gate-completion (:gate-completion-record candidate)]
    (vec
     (concat
	      (when-not (and (= :gravity/final-seed-retirement-proof
	                        (:artifact proof-contract))
	                     (= :p15-s23-final-seed-retirement-proof
	                        (:stage proof-contract))
	                     (contains? #{:complete :incomplete}
	                                (:status proof-contract)))
        [(p15-s23-final-seed-retirement-diagnostic-record
          source-path "P15S23AD001" proof-contract
          {:missing-fields [:artifact :stage :status]})])
      (when-not (= :complete (:status link-record))
        [(p15-s23-final-seed-retirement-diagnostic-record
          source-path "P15S23AD002" link-record
          {:missing-links (:missing-links link-record)})])
      (when-not (= :complete (:status boundary-record))
        [(p15-s23-final-seed-retirement-diagnostic-record
          source-path "P15S23AD003" boundary-record
          {:required-boundary
           [:compiler-path-uses-clojure-seed-false
            :runtime-path-uses-clojure-seed-false
            :release-compiler-uses-clojure-seed-false
            :stage3-seedless-candidate
            :stage3-toolchain-seedless]})])
      (when-not (= :complete (:status stage3-record))
        [(p15-s23-final-seed-retirement-diagnostic-record
          source-path "P15S23AD004" stage3-record
          {:required-stage3 [:equivalence-bundle
                             :accepted-output-equivalence
                             :rejected-diagnostics
                             :rebuild-equivalence
                             :conformance-evidence
                             :self-hosted-application-run]})])
      (when-not (= :complete (:status release-decision))
        [(p15-s23-final-seed-retirement-diagnostic-record
          source-path "P15S23AD005" release-decision
          {:remaining-release-blockers
           (:remaining-release-blockers release-decision)})])
      (when-not (= :complete (:status tcb-retirement))
        [(p15-s23-final-seed-retirement-diagnostic-record
          source-path "P15S23AD006" tcb-retirement
          {:compiler-seed-residual-count
           (:compiler-seed-residual-count tcb-retirement)})])
      (when-not (= :complete (:status provenance-closure))
        [(p15-s23-final-seed-retirement-diagnostic-record
          source-path "P15S23AD007" provenance-closure
          {:verification-host-in-release-boundary?
           (:verification-host-in-release-boundary?
            provenance-closure)})])
      (when-not (= :complete (:status gate-completion))
        [(p15-s23-final-seed-retirement-diagnostic-record
          source-path "P15S23AD008"
          (select-keys proof-contract
                       [:self-hosting-claims :next-required-capability])
          {:gate-completion-status (:status gate-completion)})])))))

(defn p15-s23-final-seed-retirement-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-final-seed-retirement-diagnostic-stream
   :stage :p15-s23-final-seed-retirement-proof
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-final-seed-retirement-proof
            :message
            (get p15-s23-final-seed-retirement-diagnostic-messages
                 id)
            :stable? true})
         p15-s23-final-seed-retirement-diagnostic-ids)
   :status :complete})

(defn p15-s23-final-seed-retirement-rejected-records
  [source-path candidate]
  (let [base candidate
        records
        [{:fixture :internal-p15-s23-final-seed-retirement-missing-contract
          :expected-diagnostic "P15S23AD001"
          :candidate (assoc base :proof-contract {})}
         {:fixture :internal-p15-s23-final-seed-retirement-evidence-gap
          :expected-diagnostic "P15S23AD002"
          :candidate (assoc-in base
                               [:evidence-link-record :status]
                               :failed)}
         {:fixture :internal-p15-s23-final-seed-retirement-boundary-gap
          :expected-diagnostic "P15S23AD003"
          :candidate
          (-> base
              (assoc-in [:boundary-record :status] :failed)
              (assoc-in [:boundary-record
                         :compiler-path-uses-clojure-seed?]
                        true))}
         {:fixture :internal-p15-s23-final-seed-retirement-stage3-gap
          :expected-diagnostic "P15S23AD004"
          :candidate (assoc-in base
                               [:stage3-execution-record :status]
                               :failed)}
         {:fixture :internal-p15-s23-final-seed-retirement-release-gap
          :expected-diagnostic "P15S23AD005"
          :candidate (assoc-in base
                               [:release-decision-record :status]
                               :failed)}
         {:fixture :internal-p15-s23-final-seed-retirement-tcb-gap
          :expected-diagnostic "P15S23AD006"
          :candidate (assoc-in base
                               [:tcb-retirement-record :status]
                               :failed)}
         {:fixture :internal-p15-s23-final-seed-retirement-provenance-gap
          :expected-diagnostic "P15S23AD007"
          :candidate (assoc-in base
                               [:provenance-closure-record :status]
                               :failed)}
         {:fixture :internal-p15-s23-final-seed-retirement-unsupported-claim
          :expected-diagnostic "P15S23AD008"
          :candidate
          (-> base
              (assoc-in [:proof-contract :self-hosting-claims
                         :clojure-seed-boundary?]
                        true)
              (assoc-in [:gate-completion-record :status]
                        :failed))}]]
    (mapv
     (fn [{:keys [fixture expected-diagnostic candidate]}]
       {:fixture fixture
        :status :rejected
        :expected-diagnostic expected-diagnostic
        :diagnostics
        (p15-s23-final-seed-retirement-proof-diagnostics
         source-path candidate)})
     records)))

	(defn p15-s23-final-seed-retirement-proof
	  [artifact]
	  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-final-seed-retirement-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat
              #(map :diagnostic (:diagnostics %))
              (:rejected-p15-s23-final-seed-retirement-fixtures
               artifact)))
        boundary (:boundary-record artifact)
        stage3 (:stage3-execution-record artifact)
	        release (:release-decision-record artifact)
	        tcb (:tcb-retirement-record artifact)
	        provenance (:provenance-closure-record artifact)
	        gate (:gate-completion-record artifact)
	        complete? (= :complete (:status gate))]
	    {:final-seed-retirement-proof-authored-in-gravity? true
	     :status (if complete? :complete :incomplete)
	     :task "P15-S23"
	     :final-seed-retirement-proof-present?
	     complete?
     :evidence-links-covered?
     (= :complete (get-in artifact [:evidence-link-record :status]))
     :stage3-seedless-boundary-proven?
     (= :complete (:status boundary))
     :stage3-equivalence-and-application-proven?
     (= :complete (:status stage3))
     :release-governance-closed?
     (= :complete (:status release))
     :tcb-seed-boundary-retired?
     (= :complete (:status tcb))
     :provenance-closure-recorded?
     (= :complete (:status provenance))
     :full-language-compiler-self-hosted?
     (true? (:full-language-compiler-self-hosted? gate))
     :clojure-seed-retired?
     (true? (:clojure-seed-retired? gate))
     :clojure-seed-boundary?
     (:clojure-seed-boundary? gate)
     :verification-host
     (:verification-host provenance)
     :verification-host-in-release-boundary?
     (:verification-host-in-release-boundary? provenance)
     :rejected-candidates-covered?
     (= (set p15-s23-final-seed-retirement-diagnostic-ids)
        rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-final-seed-retirement-diagnostic-ids)
        diagnostics)
	     :limitations
	     {:full-language-compiler-self-hosted? complete?
	      :clojure-seed-retired? complete?
	      :clojure-seed-boundary? (not complete?)
	      :verification-host :clojure-bootstrap-verifier
	      :verification-host-in-release-boundary?
	      (:verification-host-in-release-boundary? provenance)
	      :next-required-capability
	      (or (get-in artifact [:proof-contract :next-required-capability])
	          :self_hosted_public_binary_final_verification)}}))

(defn p15-s23-final-seed-retirement-source-artifact*
  ([source-path]
   (p15-s23-final-seed-retirement-source-artifact*
    source-path
    (p15-s23-final-seed-retirement-base-evidence)))
  ([source-path evidence]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-final-seed-retirement-proof)
        link-record
        (p15-s23-final-seed-retirement-link-record
         proof-contract evidence)
        boundary-record
        (p15-s23-final-seedless-boundary-record
         proof-contract evidence)
        stage3-execution-record
        (p15-s23-final-stage3-execution-record evidence)
        release-decision
        (p15-s23-final-release-decision-record
         proof-contract evidence boundary-record stage3-execution-record)
        tcb-retirement
        (p15-s23-final-tcb-retirement-record
         evidence boundary-record release-decision)
        provenance-closure
        (p15-s23-final-provenance-closure-record
         proof-contract evidence boundary-record stage3-execution-record
         release-decision)
        gate-completion
        (p15-s23-final-gate-completion-record
         proof-contract link-record boundary-record stage3-execution-record
         release-decision tcb-retirement provenance-closure)
        candidate {:proof-contract proof-contract
                   :evidence-link-record link-record
                   :boundary-record boundary-record
                   :stage3-execution-record stage3-execution-record
                   :release-decision-record release-decision
                   :tcb-retirement-record tcb-retirement
                   :provenance-closure-record provenance-closure
                   :gate-completion-record gate-completion}
        diagnostics
        (p15-s23-final-seed-retirement-proof-diagnostics
         source-path candidate)
        complete? (empty? diagnostics)
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :proof-contract proof-contract
                       :evidence-link-record link-record
                       :boundary-record boundary-record
                       :stage3-execution-record stage3-execution-record
                       :release-decision-record release-decision
                       :tcb-retirement-record tcb-retirement
                       :provenance-closure-record provenance-closure
                       :gate-completion-record gate-completion})))
        rejected-records
        (p15-s23-final-seed-retirement-rejected-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-final-seed-retirement-proof-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-final-seed-retirement-proof
	         :status (if complete? :complete :incomplete)
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :linked-artifacts
         {:stage3-seedless-compiler-candidate
          (select-keys
           (:stage3-seedless-compiler-candidate evidence)
           [:artifact :artifact-id :proof-id])
          :stage3-equivalence-bundle
          (select-keys
           (:stage3-equivalence-bundle evidence)
           [:artifact :artifact-id :proof-id])
          :stage3-self-hosted-application-execution
          (select-keys
           (:stage3-self-hosted-application-execution evidence)
           [:artifact :artifact-id :proof-id])}
         :evidence-link-record link-record
         :boundary-record boundary-record
         :stage3-execution-record stage3-execution-record
         :release-decision-record release-decision
         :tcb-retirement-record tcb-retirement
         :provenance-closure-record provenance-closure
         :gate-completion-record gate-completion
	         :full-language-compiler-self-hosted?
	         (true? (:full-language-compiler-self-hosted? gate-completion))
	         :clojure-seed-retired?
	         (true? (:clojure-seed-retired? gate-completion))
	         :clojure-seed-boundary?
	         (:clojure-seed-boundary? gate-completion)
         :rejected-p15-s23-final-seed-retirement-fixtures
         rejected-records
         :p15-s23-final-seed-retirement-diagnostic-stream
         (p15-s23-final-seed-retirement-diagnostic-stream
          source-path proof-id)
         :p15-s23-final-seed-retirement-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-final-seed-retirement-diagnostic-ids)
	          :full-language-compiler-self-hosted?
	          (true? (:full-language-compiler-self-hosted? gate-completion))
	          :clojure-seed-retired?
	          (true? (:clojure-seed-retired? gate-completion))
	          :clojure-seed-boundary?
	          (:clojure-seed-boundary? gate-completion)
	          :status (if complete? :complete :incomplete)}
	         :diagnostics diagnostics}
        proof (p15-s23-final-seed-retirement-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof))))))

(defn p15-s23-final-seed-retirement-source-artifact
  [source-path]
  (p15-s23-cached-source-artifact
   :p15-s23-final-seed-retirement-proof
   source-path
   #(p15-s23-final-seed-retirement-source-artifact*
     source-path)))

(defn p15-s23-final-seed-retirement-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-final-seed-retirement-fail!
     "P15S23AD001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-final-seed-retirement-source-artifact path))

	(defn p15-s23-final-seed-retirement-evidence-summary
	  [artifact]
	  (let [proof (:capability-based-proof artifact)
	        complete? (= :complete (:status artifact))]
	    {:status (if complete? :verified :incomplete)
	     :artifact (:kind artifact)
     :artifact-id (:artifact-id artifact)
     :proof-id (:proof-id artifact)
     :source-path (:source-path artifact)
     :final-seed-retirement-proof-present?
     (:final-seed-retirement-proof-present? proof)
     :evidence-links-covered? (:evidence-links-covered? proof)
     :stage3-seedless-boundary-proven?
     (:stage3-seedless-boundary-proven? proof)
     :stage3-equivalence-and-application-proven?
     (:stage3-equivalence-and-application-proven? proof)
     :release-governance-closed? (:release-governance-closed? proof)
     :tcb-seed-boundary-retired?
     (:tcb-seed-boundary-retired? proof)
     :provenance-closure-recorded?
     (:provenance-closure-recorded? proof)
     :full-language-compiler-self-hosted?
     (:full-language-compiler-self-hosted? artifact)
     :clojure-seed-retired? (:clojure-seed-retired? artifact)
     :clojure-seed-boundary? (:clojure-seed-boundary? artifact)}))

(defn p15-s23-final-seed-retirement-evidence-from-evidence
  [evidence]
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (p15-s23-final-seed-retirement-evidence-summary
         (p15-s23-final-seed-retirement-source-artifact*
          source-path evidence))
        (catch Exception _
          nil)))))

(defn p15-s23-final-seed-retirement-evidence
  []
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (p15-s23-final-seed-retirement-evidence-summary
         (p15-s23-final-seed-retirement-file-artifact source-path))
        (catch Exception _
          nil)))))

;; ---------------------------------------------------------------------------
;; Hosted C target (bounded stage0 instruction-plan slice)
;;
;; This backend is deliberately small.  It consumes the verified stage0 plan
;; produced above and lowers only the closed, side-effecting hosted subset to
;; a deterministic C11 translation unit.  The subset is constant-output for
;; now: evaluation is performed by the verified stage0 plan, then the resulting
;; stdout is represented by a C fputs call.  This is a real executable target
;; boundary (with optional host cc invocation), while the artifact records the
;; seed boundary and does not claim final self-hosting.

(def c-backend-supported-targets #{:c :c-hosted :c11})
(def c-backend-supported-dialects #{:c11})
(def c-backend-supported-instructions
  #{:literal :quote :local :println :do :if :let :builtin-call
    :function-call :vector-literal :map-literal :set-literal})

;; The runtime-derived mode is intentionally narrower than the historical
;; stage0-output fallback below.  Each instruction in this set is emitted as
;; executable C statements; no precomputed stdout buffer is embedded in the
;; generated translation unit.  More ambitious instructions continue to use
;; the reviewed stage0 fallback until their runtime semantics have a closed
;; C lowering rule.  `str` is admitted only as a direct println value after
;; its operands have passed the typed byte-string check below.
(def c-backend-runtime-derived-instructions
  #{:literal :quote :local :println :do :if :let :builtin-call})

(declare p18-ensure-dir!)
(declare c-backend-fail!)

(defn c-backend-output-path-allowed?
  "Keep generated target artifacts inside the repository target tree or a
  caller-owned temporary directory.  Relative one-segment paths are retained
  for parity with the existing bootstrap command contract; absolute paths are
  accepted only below the host temporary directory used by tests/tools."
  [path]
  (when (string? path)
    (let [file (java.io.File. path)
          segments (vec (remove str/blank?
                               (str/split path #"/+")))
          canonical (try (.getCanonicalPath file)
                         (catch Exception _ nil))
          temp-root (try (.getCanonicalPath
                          (java.io.File. (System/getProperty "java.io.tmpdir")))
                         (catch Exception _ nil))]
      (and (not (str/blank? path))
           (not-any? #{".."} segments)
           (or (and (not (.isAbsolute file))
                    (or (str/starts-with? path "target/")
                        (= 1 (count segments))))
               (and (.isAbsolute file)
                    canonical temp-root
                    (or (= canonical temp-root)
                        (str/starts-with?
                         canonical
                         (str temp-root java.io.File/separator)))))))))

(defn c-backend-validate-output-paths!
  [source-path target paths]
  (doseq [[kind path] paths]
    (when (and path (not (c-backend-output-path-allowed? path)))
      (c-backend-fail! "C14-INPUT"
                       "C backend output path is outside the declared target roots"
                       source-path target nil
                       {:output-kind kind
                        :output-path path
                        :allowed-output-roots ["target/" "<current-directory>"
                                               (System/getProperty "java.io.tmpdir")]
                        :missing-fact :output-path-containment
                        :remediation "Use target/ or a caller-owned temporary directory for C backend outputs."}))))

(defn c-backend-canonical-value
  "Canonicalize artifact inputs without allowing host map/set iteration order
  to influence hashes or emitted manifests."
  [value]
  (cond
    (map? value)
    (into (sorted-map-by #(compare (pr-str %1) (pr-str %2)))
          (map (fn [[k v]] [(c-backend-canonical-value k)
                            (c-backend-canonical-value v)]))
          value)
    (set? value)
    (vec (sort-by pr-str (map c-backend-canonical-value value)))
    (vector? value)
    (mapv c-backend-canonical-value value)
    (seq? value)
    (mapv c-backend-canonical-value value)
    :else value))

(defn c-backend-instruction-children
  [instruction]
  (case (:op instruction)
    :println (:args instruction)
    :do (:body instruction)
    :if [(:test instruction) (:then instruction) (:else instruction)]
    :let (concat (map :expr (:bindings instruction)) (:body instruction))
    :builtin-call (:args instruction)
    :function-call (:args instruction)
    :vector-literal (:items instruction)
    :set-literal (:items instruction)
    :map-literal (mapcat (fn [{:keys [key value]}] [key value])
                          (:entries instruction))
    []))

(defn c-backend-fail!
  [id message source-path target subject extra]
  (fail! id message
         (merge {:severity :error
                 :stage :c-backend-lowering
                 :diagnostic-family (if (str/starts-with? id "C14")
                                      :c14-target-lowering
                                      :b2-c-backend)
                 :backend :c
                 :target target
                 :source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :primary {:span (or (:source-span subject)
                                     (source-span source-path 0))}
                 :related []
                 :facts {:instruction (when (map? subject) (:op subject))
                         :dialect :c11}
                 :remediation "Select the hosted C11 target and keep the source inside the verified stage0 instruction subset."}
                extra)))

(defn c-backend-validate-plan!
  "Validate the actual stage0 instruction plan iteratively before lowering."
  [source-path target plan]
  (when-not (contains? c-backend-supported-targets target)
    (c-backend-fail! "C14-TARGET"
                     "hosted C backend target is unsupported"
                     source-path target nil
                     {:supported-targets (vec (sort c-backend-supported-targets))
                      :missing-fact :supported-target
                      :remediation "Request :c, :c-hosted, or :c11 explicitly."}))
  (loop [pending (vec (mapcat (comp :instructions val) (:functions plan)))]
    (when-let [instruction (peek pending)]
      (let [pending (pop pending)]
        (when-not (map? instruction)
          (c-backend-fail! "B2-UNSUPPORTED"
                           "C backend received a malformed instruction"
                           source-path target instruction
                           {:missing-fact :instruction-record}))
        (when-not (contains? c-backend-supported-instructions (:op instruction))
          (c-backend-fail! "B2-UNSUPPORTED"
                           "C backend instruction is outside the hosted subset"
                           source-path target instruction
                           {:unsupported-op (:op instruction)
                            :missing-fact :c-lowering-rule}))
        (when (and (= :builtin-call (:op instruction))
                   (not (contains? stage0-builtin-functions
                                  (:function instruction))))
          (c-backend-fail! "B2-UNSUPPORTED"
                           "C backend builtin is outside the hosted subset"
                           source-path target instruction
                           {:unsupported-op (:function instruction)
                            :missing-fact :builtin-lowering-rule}))
        (recur (into pending (remove nil?
                                    (c-backend-instruction-children instruction)))))))
  :passed)

(defn c-backend-c-escape
  [text]
  (apply str
         (map (fn [ch]
                (cond
                  (= ch \\) "\\\\"
                  (= ch \") "\\\""
                  (= ch \newline) "\\n"
                  (= ch \return) "\\r"
                  (= ch \tab) "\\t"
                  (< (int ch) 32) (format "\\%03o" (int ch))
                  :else (str ch)))
              (str text))))

(defn c-backend-runtime-literal?
  "Return true when a scalar value has a stable hosted `str` spelling that
  can be represented by a runtime fwrite operation.  Collections are kept
  out of this first runtime-derived slice; their semantics remain on the
  verified stage0 fallback path."
  [value]
  (or (nil? value)
      (string? value)
      (number? value)
      (boolean? value)
      (char? value)
      (keyword? value)
      (symbol? value)))

(defn c-backend-runtime-binding-names
  [bindings]
  (mapv :name bindings))

(defn c-backend-runtime-local-kinds
  "Normalize the validator's lexical-local state to a name -> kind map.

  Older callers passed a set of names while the runtime-derived validator now
  needs the scalar kind to prove that `str` only consumes byte-string locals.
  Treating a legacy set as unknown scalar state preserves its presence checks
  without accidentally granting the stronger string capability."
  [locals]
  (if (map? locals)
    locals
    (into {} (map (fn [name] [name :scalar]) locals))))

(defn c-backend-runtime-local-present?
  [locals name]
  (contains? (c-backend-runtime-local-kinds locals) name))

(defn c-backend-runtime-string-expression-supported?
  "Return true only for a byte-string literal/quote or a local proven to be
  bound to one.  This intentionally excludes numeric/collection values,
  nested calls, and general control-flow expressions from the `str` operand
  surface."
  [instruction locals]
  (and (map? instruction)
       (let [op (:op instruction)
             locals (c-backend-runtime-local-kinds locals)]
         (cond
           (#{:literal :quote} op)
           (string? (:value instruction))
           (= :local op)
           (= :string (get locals (:name instruction)))
           :else false))))

(defn c-backend-runtime-next-local-kinds
  [locals bindings]
  (reduce (fn [scope {:keys [name expr]}]
            (assoc scope name
                   (if (and (map? expr)
                            (#{:literal :quote} (:op expr))
                            (string? (:value expr)))
                     :string
                     :scalar)))
          (c-backend-runtime-local-kinds locals)
          bindings))

(declare c-backend-runtime-test-expression-supported?)

(defn c-backend-runtime-scalar-expression-supported?
  "Recognize the value subset that can be represented by the runtime C
  emitter.  This predicate is deliberately closed over lexical locals: an
  unbound local, collection, builtin, function call, or statement in a value
  position is rejected before any target bytes are emitted."
  [instruction locals]
  (and (map? instruction)
       (let [op (:op instruction)]
         (cond
           (#{:literal :quote} op)
           (c-backend-runtime-literal? (:value instruction))
           (= :local op)
           (c-backend-runtime-local-present? locals (:name instruction))
           (= :builtin-call op)
           (and (= 'str (:function instruction))
                (contains? #{1 2} (count (:args instruction)))
                (every? #(c-backend-runtime-string-expression-supported?
                           % locals)
                        (:args instruction)))
           (= :if op)
           (and (c-backend-runtime-test-expression-supported?
                 (:test instruction) locals)
                (c-backend-runtime-scalar-expression-supported?
                 (:then instruction) locals)
                (c-backend-runtime-scalar-expression-supported?
                 (:else instruction) locals))
           (= :let op)
           (let [bindings (:bindings instruction)
                 next-locals (c-backend-runtime-next-local-kinds
                              locals bindings)]
             (and (= 1 (count (:body instruction)))
                  (every? (fn [{:keys [name expr]}]
                            (and (symbol? name)
                                 (or (= :literal (:op expr))
                                     (= :quote (:op expr)))
                                 (c-backend-runtime-literal?
                                  (:value expr))))
                          bindings)
                  (c-backend-runtime-scalar-expression-supported?
                   (first (:body instruction)) next-locals)))
           :else false))))

(defn c-backend-runtime-test-expression-supported?
  "Tests are intentionally simple scalar values.  Nested `if`/`let` tests
  would require a temporary tagged value ABI; rejecting them keeps this
  bounded slice explicit and fail-closed while still allowing locals and all
  scalar literal spellings as conditions."
  [instruction locals]
  (and (map? instruction)
       (let [op (:op instruction)]
         (cond
           (#{:literal :quote} op)
           (c-backend-runtime-literal? (:value instruction))
           (= :local op)
           (c-backend-runtime-local-present? locals (:name instruction))
           :else false))))

(defn c-backend-runtime-instruction-supported?
  ([instruction] (c-backend-runtime-instruction-supported? instruction #{}))
  ([instruction locals]
   (and (map? instruction)
        (contains? c-backend-runtime-derived-instructions (:op instruction))
        (let [op (:op instruction)]
          (cond
            (#{:literal :quote} op)
            (c-backend-runtime-literal? (:value instruction))
            (= :local op)
            (c-backend-runtime-local-present? locals (:name instruction))
            (= :println op)
            (every? #(c-backend-runtime-scalar-expression-supported?
                       % locals)
                    (:args instruction))
            (= :do op)
            (every? #(c-backend-runtime-instruction-supported? % locals)
                    (:body instruction))
            (= :if op)
            (and (c-backend-runtime-test-expression-supported?
                  (:test instruction) locals)
                 (c-backend-runtime-instruction-supported?
                  (:then instruction) locals)
                 (c-backend-runtime-instruction-supported?
                  (:else instruction) locals))
            (= :let op)
            (let [bindings (:bindings instruction)
                  next-locals (c-backend-runtime-next-local-kinds
                               locals bindings)]
              (and (every? (fn [{:keys [name expr]}]
                             (and (symbol? name)
                                  (or (= :literal (:op expr))
                                      (= :quote (:op expr)))
                                  (c-backend-runtime-literal?
                                   (:value expr))))
                           bindings)
                   (every? #(c-backend-runtime-instruction-supported?
                             % next-locals)
                           (:body instruction))))
            :else false)))))

(defn c-backend-runtime-plan-supported?
  [plan]
  (every? (fn [[_ function]]
            (every? #(c-backend-runtime-instruction-supported? % #{})
                    (:instructions function)))
          (:functions plan)))

(defn c-backend-runtime-reject!
  [source-path target subject message unsupported-op missing-fact]
  (c-backend-fail! "B2-UNSUPPORTED"
                   message
                   source-path target subject
                   {:unsupported-op unsupported-op
                    :lowering-mode :runtime-derived
                    :missing-fact missing-fact
                    :remediation "Use the verified stage0 fallback or restrict the source to scalar literals, locals, println, direct string concatenation, do, if, and let."}))

(defn c-backend-validate-runtime-plan!
  "Fail closed before lowering when the explicitly requested runtime-derived
  mode sees an instruction outside its closed scalar control-flow subset.

  Validation is iterative so malformed or adversarially deep plans cannot
  exhaust the host stack.  The lexical-local set travels with each pending
  frame and value-position failures retain the stable parent `println`
  diagnostic used by the earlier runtime-derived slice."
  [source-path target plan]
  (loop [pending (vec (mapcat (fn [[_ function]]
                                (map (fn [instruction]
                                       {:kind :statement
                                        :instruction instruction
                                        :locals {}})
                                     (:instructions function)))
                              (:functions plan)))]
    (when-let [{:keys [kind instruction locals parent]} (peek pending)]
      (let [pending (pop pending)
            op (when (map? instruction) (:op instruction))]
        (when-not (map? instruction)
          (c-backend-runtime-reject!
           source-path target instruction
           "runtime-derived C lowering received a malformed instruction"
           op :instruction-record))
        (when-not (contains? c-backend-runtime-derived-instructions op)
          (c-backend-runtime-reject!
           source-path target (or parent instruction)
           "runtime-derived C lowering does not implement this instruction"
           op :runtime-c-lowering-rule))
        (case kind
          :expression
          (cond
            (#{:literal :quote} op)
            (do
              (when-not (c-backend-runtime-literal? (:value instruction))
                (c-backend-runtime-reject!
                 source-path target (or parent instruction)
                 "runtime-derived C lowering only accepts scalar literals"
                 op (if parent :runtime-c-value-lowering
                        :scalar-literal-lowering)))
              (recur pending))
            (= :local op)
            (do
              (when-not (c-backend-runtime-local-present?
                         locals (:name instruction))
                (c-backend-runtime-reject!
                 source-path target (or parent instruction)
                 "runtime-derived C lowering cannot resolve this local"
                 :local (if parent :runtime-c-value-lowering
                            :runtime-local-binding)))
              (recur pending))
            (= :builtin-call op)
            (let [str? (= 'str (:function instruction))
                  supported-arity? (contains? #{1 2}
                                               (count (:args instruction)))
                  direct-println? (= :println (:op parent))
                  operands? (and (vector? (:args instruction))
                                 (every? #(c-backend-runtime-string-expression-supported?
                                            % locals)
                                         (:args instruction)))]
              (when-not (and str? direct-println? supported-arity? operands?)
                (c-backend-runtime-reject!
                 source-path target (or parent instruction)
                 (if (and str? direct-println? supported-arity?)
                   "runtime-derived str requires one or two string scalar literals, quotes, or proven string locals"
                   (if (and str? direct-println?)
                     "runtime-derived str supports one or two operands"
                     "runtime-derived str is only supported as a direct println value"))
                 (:function instruction)
                 (if (and str? direct-println? supported-arity?)
                   :runtime-str-operand-lowering
                   (if (and str? direct-println?)
                     :runtime-str-arity-lowering
                     :runtime-c-value-lowering))))
              (recur pending))
            (= :if op)
            (do
              (when-not (c-backend-runtime-test-expression-supported?
                         (:test instruction) locals)
                (c-backend-runtime-reject!
                 source-path target (or parent instruction)
                 "runtime-derived C lowering requires a scalar local or literal test"
                 :if :runtime-c-test-lowering))
              (recur (into pending
                           [{:kind :expression
                             :instruction (:else instruction)
                             :locals locals
                             :parent instruction}
                            {:kind :expression
                             :instruction (:then instruction)
                             :locals locals
                             :parent instruction}
                            {:kind :expression
                             :instruction (:test instruction)
                             :locals locals
                             :parent instruction}])))
            (= :let op)
            (let [bindings (:bindings instruction)]
              (when-not (and (vector? bindings)
                             (vector? (:body instruction)))
                (c-backend-runtime-reject!
                 source-path target (or parent instruction)
                 "runtime-derived let has a malformed binding or body shape"
                 :let :runtime-let-shape))
              (let [next-locals (c-backend-runtime-next-local-kinds
                                 locals bindings)]
                (when-not (= 1 (count (:body instruction)))
                  (c-backend-runtime-reject!
                   source-path target (or parent instruction)
                   "runtime-derived let value requires one scalar body expression"
                   :let :runtime-c-value-lowering))
                (doseq [{:keys [name expr]} bindings]
                  (when-not (and (symbol? name)
                                 (#{:literal :quote} (:op expr))
                                 (c-backend-runtime-literal?
                                  (:value expr)))
                    (c-backend-runtime-reject!
                     source-path target (or parent instruction)
                     "runtime-derived let bindings must be scalar literals"
                     :let :runtime-let-binding-lowering)))
                (recur (conj pending {:kind :expression
                                      :instruction (first (:body instruction))
                                      :locals next-locals
                                      :parent instruction}))))
            :else
            (c-backend-runtime-reject!
             source-path target (or parent instruction)
             "runtime-derived C lowering does not implement this value expression"
             (or (some-> parent :op) op)
             :runtime-c-value-lowering))

          :statement
          (case op
            :literal (recur pending)
            :quote (recur pending)
            :local
            (do
              (when-not (c-backend-runtime-local-present?
                         locals (:name instruction))
                (c-backend-runtime-reject!
                 source-path target instruction
                 "runtime-derived C lowering cannot resolve this local"
                 :local :runtime-local-binding))
              (recur pending))
            :println
            (do
              (when-not (vector? (:args instruction))
                (c-backend-runtime-reject!
                 source-path target instruction
                 "runtime-derived println has a malformed argument shape"
                 :println :runtime-c-value-lowering))
              (recur (into pending
                           (map (fn [arg]
                                  {:kind :expression
                                   :instruction arg
                                   :locals locals
                                   :parent instruction})
                                (:args instruction)))))
            :do
            (do
              (when-not (vector? (:body instruction))
                (c-backend-runtime-reject!
                 source-path target instruction
                 "runtime-derived do has a malformed body shape"
                 :do :runtime-c-lowering-rule))
              (recur (into pending
                           (map (fn [child]
                                  {:kind :statement
                                   :instruction child
                                   :locals locals})
                                (:body instruction)))))
            :if
            (do
              (when-not (c-backend-runtime-test-expression-supported?
                         (:test instruction) locals)
                (c-backend-runtime-reject!
                 source-path target instruction
                 "runtime-derived C lowering requires a scalar local or literal test"
                 :if :runtime-c-test-lowering))
              (recur (into pending
                           [{:kind :statement
                             :instruction (:else instruction)
                             :locals locals}
                            {:kind :statement
                             :instruction (:then instruction)
                             :locals locals}
                            {:kind :expression
                             :instruction (:test instruction)
                             :locals locals}])) )
            :let
            (let [bindings (:bindings instruction)]
              (when-not (and (vector? bindings)
                             (vector? (:body instruction)))
                (c-backend-runtime-reject!
                 source-path target instruction
                 "runtime-derived let has a malformed binding or body shape"
                 :let :runtime-let-shape))
              (let [next-locals (c-backend-runtime-next-local-kinds
                                 locals bindings)]
                (doseq [{:keys [name expr]} bindings]
                  (when-not (and (symbol? name)
                                 (#{:literal :quote} (:op expr))
                                 (c-backend-runtime-literal?
                                  (:value expr)))
                    (c-backend-runtime-reject!
                     source-path target instruction
                     "runtime-derived let bindings must be scalar literals"
                     :let :runtime-let-binding-lowering)))
                (recur (into pending
                             (map (fn [child]
                                    {:kind :statement
                                     :instruction child
                                     :locals next-locals})
                                  (:body instruction))))))
            ;; A statement value is legal only for the closed scalar forms.
            (c-backend-runtime-reject!
             source-path target instruction
             "runtime-derived C lowering does not implement this statement"
             op :runtime-c-lowering-rule))))))
  :passed)

(defn c-backend-resolve-p15-s23-compiler-source-path
  "Resolve the repository-owned P15-S23 source even when a direct caller is
  running from an unrelated working directory."
  []
  (let [relative p15-s23-compiler-source-path
        classpath-roots
        (keep (fn [entry]
                (let [file (java.io.File. entry)]
                  (when (.isDirectory file) file)))
              (str/split (System/getProperty "java.class.path" "")
                         (re-pattern (java.io.File/pathSeparator))))
        roots (distinct (cons (java.io.File.
                               (System/getProperty "user.dir"))
                              classpath-roots))]
    (or (some (fn [root]
                (loop [directory root]
                  (let [candidate (java.io.File. directory relative)]
                    (cond
                      (.isFile candidate) (.getPath candidate)
                      (.getParentFile directory)
                      (recur (.getParentFile directory))
                      :else nil))))
              roots)
        relative)))

(declare p15-s23-stage2-compiler-pinned-source!
         p15-s23-compiler-source-form-record-from-text)

(defn c-backend-stage2-plan-emitter-source-rule!
  "Load and validate the Gravity-authored P15-S23 stage2 plan-emitter rule.

  Runtime-derived C lowering is deliberately bound to this source rule rather
  than silently reusing the Clojure stage0 plan emitter.  The returned rule
  hash is path-neutral and is carried into manifests/provenance so the exact
  Gravity rule set used for lowering is auditable."
  [source-path target]
  (let [compiler-source (c-backend-resolve-p15-s23-compiler-source-path)]
    (when-not (.isFile (java.io.File. compiler-source))
      (p15-s23-stage2-plan-emitter-fail!
       "P15S23Q001"
       compiler-source
       nil
       {:missing-fields [:compiler-source]
        :requested-source source-path
        :target target
        :missing-fact :stage2-plan-emitter-source}))
    (let [pinned-source
          (p15-s23-stage2-compiler-pinned-source!
           compiler-source source-path target "P15S23Q001"
           p15-s23-stage2-plan-emitter-fail!)
          source-data
          (try
            (p15-s23-compiler-source-form-record-from-text
             compiler-source (:source-text pinned-source))
            (catch clojure.lang.ExceptionInfo ex
              (throw ex))
            (catch Exception ex
              (p15-s23-stage2-plan-emitter-fail!
               "P15S23Q001"
               compiler-source
               nil
               {:requested-source source-path
                :target target
                :missing-fact :stage2-plan-emitter-source
                :cause-message (.getMessage ex)})))
          emitter
          (try
            (p15-s23-compiler-def-value compiler-source
                                         (:forms source-data)
                                         'p15-s23-stage2-plan-emitter)
            (catch clojure.lang.ExceptionInfo ex
              (throw ex))
            (catch Exception ex
              (p15-s23-stage2-plan-emitter-fail!
               "P15S23Q001"
               compiler-source
               nil
               {:requested-source source-path
                :target target
                :missing-fact :stage2-plan-emitter-definition
                :cause-message (.getMessage ex)})))]
      (when-not (map? emitter)
        (p15-s23-stage2-plan-emitter-fail!
         "P15S23Q001"
         compiler-source
         emitter
         {:requested-source source-path
          :target target
          :missing-fields [:stage2-plan-emitter]
          :missing-fact :stage2-plan-emitter-definition}))
      (let [rule-record (p15-s23-stage2-plan-emitter-rule-record emitter)]
        (when-not (= :complete (:status rule-record))
          (p15-s23-stage2-plan-emitter-fail!
           "P15S23Q002"
           compiler-source
           rule-record
           {:requested-source source-path
            :target target
            :missing-fact :stage2-plan-emitter-rule-set}))
        {:emitter emitter
         :source-path compiler-source
         :rule-record rule-record
         :source-rule-hash
         (str "sha256:"
              (sha256-hex
               (pr-str (c-backend-canonical-value emitter))))}))))

