        action
        #(p15-s23-reference-runtime-action-record
          runtime-binding (merge {:plan-id plan-id :source-id source-id} %))
        allocation-decision
        (decision
         {:action-id :gravity.reference/action-managed-string-allocation
          :principal-id source-principal
          :effect :memory/allocate
          :capability :memory/allocator
          :provider-id allocation-provider
          :grant-id allocation-grant
          :scope :pinned-runtime-plan
          :mode :pinned-reference
          :live-external-authority? false
          :decision :grant
          :result :grant
          :reason :explicit-grant})
        stdout-decision
        (decision
         {:action-id :gravity.reference/action-transcript-capture
          :principal-id source-principal
          :effect :io/write
          :capability :io/stdout
          :provider-id capture-provider
          :grant-id stdout-grant
          :handler-principal-id handler-principal
          :scope :closed-plan-interpreter
          :mode :reference-test-interpreter
          :live-external-authority? false
          :decision :grant
          :result :grant
          :reason :closed-plan-reference-handler})
        fixture-decision
        (decision
         {:action-id :gravity.reference/action-transcript-capture
          :principal-id handler-principal
          :effect :io/write
          :capability :test/fixture
          :provider-id capture-provider
          :grant-id fixture-grant
          :source-principal-id source-principal
          :scope :closed-plan-interpreter
          :mode :reference-test-interpreter
          :live-external-authority? false
          :decision :grant
          :result :grant
          :reason :explicit-reference-harness-policy})
        allocation-action
        (action
         {:action-id :gravity.reference/action-managed-string-allocation
          :operation :managed-allocation
          :provider-id allocation-provider
          :effect :memory/allocate
          :capability :memory/allocator
          :grant-id allocation-grant
          :principal-id source-principal
          :scope :pinned-runtime-plan
          :mode :pinned-reference
          :live-external-authority? false
          :action-started? true
          :action-status :committed
          :result-committed? true
          :output-committed? false
          :diagnostic nil
          :remediation :none})
        capture-action
        (action
         {:action-id :gravity.reference/action-transcript-capture
          :operation :ordered-string-append
          :provider-id capture-provider
          :effect :io/write
          :handled-effect :io/write
          :source-capability :io/stdout
          :source-grant-id stdout-grant
          :capability :test/fixture
          :grant-id fixture-grant
          :principal-id handler-principal
          :source-principal-id source-principal
          :scope :closed-plan-interpreter
          :mode :reference-test-interpreter
          :live-external-authority? false
          :action-started? capture-invoked?
          :action-status (if capture-invoked? :committed :not-invoked)
          :result-committed? capture-invoked?
          :output-committed? capture-invoked?
          :diagnostic nil
          :remediation :none})
        provider-ids
        (cond-> #{allocation-provider}
          io-write-active? (conj capture-provider))
        grant-ids
        (cond-> #{allocation-grant}
          io-write-active? (conj stdout-grant fixture-grant))
        record
        {:artifact :gravity/p15-s23-reference-runtime-adapter-record
         :status :complete
         :mode :closed-plan-reference
         :runtime-artifact-hash
         p15-s23-stage2-runtime-artifact-expected-artifact-hash
         :runtime-contract-definition-hash
         p15-s23-reference-runtime-expected-contract-definition-hash
         :runtime-contract-derived-facts-hash
         p15-s23-reference-runtime-expected-derived-facts-hash
         :function p15-s23-stage2-runtime-artifact-closed-plan-function
         :function-hash
         (get p15-s23-reference-runtime-expected-function-hashes
              p15-s23-stage2-runtime-artifact-closed-plan-function)
         :plan-id plan-id
         :source-id source-id
         :source-principal source-principal
         :handler-principal handler-principal
         :provider-ids provider-ids
         :grant-ids grant-ids
         :authority
         (dissoc
          (p15-s23-reference-runtime-authority
           nil {:observed-operation-set
                (if io-write-active? #{:println} #{})})
          :failure-injection)
         :decision-records
         (cond-> [allocation-decision]
           io-write-active? (conj stdout-decision fixture-decision))
         :action-records
         (cond-> [allocation-action]
           io-write-active? (conj capture-action))
         :io-write-active? io-write-active?
         :reference-interpreter? true
         :deployment-runtime? false
         :clojure-seed-boundary? true
         :self-hosted? false}]
    (assoc record :record-hash
           (p15-s23-reference-runtime-hash record))))

(def p15-s23-reference-runtime-preserved-diagnostic-ids
  #{"P15S23X001" "P15S23X002" "P15S23X003"
    "L2-UNKNOWN-CORE-FORM" "L2-UNKNOWN-SYMBOL" "L2-BUILTIN-ARITY"
    "L2-BUILTIN-ERROR" "L2-FUNCTION-ARITY" "L2-MAIN-ARITY"})

(defn p15-s23-reference-runtime-structured-diagnostic?
  [exception allowed-source-paths]
  (let [data (ex-data exception)
        source (get-in data [:source-span :source])]
    (and (map? data)
         (contains? p15-s23-reference-runtime-preserved-diagnostic-ids
                    (:id data))
         (string? (:message data))
         (= :stage0 (:bootstrap-stage data))
         (keyword? (:stage data))
         (keyword? (:diagnostic-family data))
         (map? (:source-span data))
         (contains? allowed-source-paths source)
         (contains? data :remediation))))

(def p15-s23-checked-core-reference-result-keys
  #{:artifact :entrypoint :entrypoint-result :stdout :status
    :clojure-seed-boundary? :self-hosted?})

(defn p15-s23-checked-core-reference-result-valid?
  [result plan]
  (try
    (and
     (map? result)
     (contains?
      p15-s23-reference-runtime-supported-collection-class-names
      (some-> result class .getName))
     (<= (count result) 7)
     (do
       (p15-s23-reference-runtime-bounded-value!
        "checked-core-reference-result" :jvm
        :checked-core-reference-result result
        p15-s23-reference-runtime-max-contract-nodes
        p15-s23-reference-runtime-max-contract-depth)
       true)
     (= p15-s23-checked-core-reference-result-keys
        (set (keys result)))
     (= :gravity/p15-s23-runtime-closed-plan-execution-record
        (:artifact result))
     (= (:entrypoint plan) (:entrypoint result))
     (symbol? (:entrypoint result))
     (or (nil? (:entrypoint-result result))
         (string? (:entrypoint-result result))
         (boolean? (:entrypoint-result result))
         (integer? (:entrypoint-result result))
         (char? (:entrypoint-result result))
         (keyword? (:entrypoint-result result))
         (symbol? (:entrypoint-result result)))
     (string? (:stdout result))
     (= :complete (:status result))
     (true? (:clojure-seed-boundary? result))
     (false? (:self-hosted? result)))
    (catch StackOverflowError _ false)
    (catch Exception _ false)))

(defn p15-s23-reference-runtime-adapter-validated-invoke
  [runtime-rule function args authority target-plan plan-id source-id
   closed-plan-validation]
  (let [source-principal 'gravity.bootstrap.p15-s23.runtime
        handler-principal :gravity.bootstrap/reference-harness
        allocation-provider :gravity.reference/jvm-managed-allocator
        capture-provider :gravity.reference/transcript-capture
        allocation-grant :gravity.reference/grant-managed-allocation
        stdout-grant :gravity.reference/grant-reference-stdout
        fixture-grant :gravity.reference/grant-test-fixture
        writes-stdout?
        (contains? (:observed-operation-set closed-plan-validation) :println)
        required-provider-ids
        (cond-> #{allocation-provider}
          writes-stdout? (conj capture-provider))
        required-grant-ids
        (cond-> #{allocation-grant}
          writes-stdout? (conj stdout-grant fixture-grant))
        decision
        (fn [attributes]
          (p15-s23-reference-runtime-decision-record
           runtime-rule (merge {:plan-id plan-id :source-id source-id}
                               attributes)))
        action
        (fn [attributes]
          (p15-s23-reference-runtime-action-record
           runtime-rule (merge {:plan-id plan-id :source-id source-id}
                               attributes)))
        allocation-decision
        (fn [decision-value reason & [extra]]
          (decision
           (merge
            {:action-id :gravity.reference/action-managed-string-allocation
             :principal-id source-principal
             :effect :memory/allocate
             :capability :memory/allocator
             :provider-id allocation-provider
             :grant-id allocation-grant
             :scope :pinned-runtime-plan
             :mode :pinned-reference
             :live-external-authority? false
             :decision decision-value
             :result decision-value
             :reason reason}
            extra)))
        stdout-decision
        (fn [decision-value reason]
          (decision
           {:action-id :gravity.reference/action-transcript-capture
            :principal-id source-principal
            :effect :io/write
            :capability :io/stdout
            :provider-id capture-provider
            :grant-id stdout-grant
            :handler-principal-id handler-principal
            :scope :closed-plan-interpreter
            :mode :reference-test-interpreter
            :live-external-authority? false
            :decision decision-value
            :result decision-value
            :reason reason}))
        fixture-decision
        (fn [decision-value reason & [extra]]
          (decision
           (merge
            {:action-id :gravity.reference/action-transcript-capture
             :principal-id handler-principal
             :effect :io/write
             :capability :test/fixture
             :provider-id capture-provider
             :grant-id fixture-grant
             :source-principal-id source-principal
             :scope :closed-plan-interpreter
             :mode :reference-test-interpreter
             :live-external-authority? false
             :decision decision-value
             :result decision-value
             :reason reason}
            extra)))
        deployment-decision
        (fn []
          (decision
           {:action-id :gravity.reference/action-deployment-stdout
            :principal-id source-principal
            :effect :io/write
            :capability :io/stdout
            :provider-id :unresolved
            :grant-id :unresolved
            :scope :deployment-runtime
            :mode :deployment
            :live-external-authority? false
            :decision :deny
            :result :deny
            :reason :deployment-provider-unresolved}))
        allocation-action
        (fn [status started? result-committed?
             & [diagnostic remediation extra]]
          (action
           (merge
            {:action-id :gravity.reference/action-managed-string-allocation
             :operation :managed-allocation
             :provider-id allocation-provider
             :effect :memory/allocate
             :capability :memory/allocator
             :grant-id allocation-grant
             :principal-id source-principal
             :scope :pinned-runtime-plan
             :mode :pinned-reference
             :live-external-authority? false
             :action-started? started?
             :action-status status
             :result-committed? result-committed?
             :output-committed? false
             :diagnostic diagnostic
             :remediation (or remediation :none)}
            extra)))
        stdout-action
        (fn [status started? result-committed? output-committed?
             & [diagnostic remediation]]
          (action
           {:action-id :gravity.reference/action-transcript-capture
            :operation :authorize-reference-stdout
            :provider-id capture-provider
            :effect :io/write
            :capability :io/stdout
            :grant-id stdout-grant
            :principal-id source-principal
            :handler-principal-id handler-principal
            :scope :closed-plan-interpreter
            :mode :reference-test-interpreter
            :live-external-authority? false
            :action-started? started?
            :action-status status
            :result-committed? result-committed?
            :output-committed? output-committed?
            :diagnostic diagnostic
            :remediation (or remediation :none)}))
        capture-action
        (fn [status started? result-committed? output-committed?
             & [diagnostic remediation extra]]
          (action
           (merge
            {:action-id :gravity.reference/action-transcript-capture
             :operation :ordered-string-append
             :provider-id capture-provider
             :effect :io/write
             :handled-effect :io/write
             :source-capability :io/stdout
             :source-grant-id stdout-grant
             :capability :test/fixture
             :grant-id fixture-grant
             :principal-id handler-principal
             :source-principal-id source-principal
             :scope :closed-plan-interpreter
             :mode :reference-test-interpreter
             :live-external-authority? false
             :action-started? started?
             :action-status status
             :result-committed? result-committed?
             :output-committed? output-committed?
             :diagnostic diagnostic
             :remediation (or remediation :none)}
            extra)))
        deployment-action
        (fn []
          (action
           {:action-id :gravity.reference/action-deployment-stdout
            :operation :deployment-stdout
            :provider-id :unresolved
            :effect :io/write
            :capability :io/stdout
            :grant-id :unresolved
            :principal-id source-principal
            :scope :deployment-runtime
            :mode :deployment
            :live-external-authority? false
            :action-started? false
            :action-status :rejected-before-start
            :result-committed? false
            :output-committed? false
            :diagnostic "L15-PROVIDER-MISSING"
            :remediation :select_deployment_stdout_provider_and_grant}))
        preflight-decision
        (fn [diagnostic reason]
          (decision
           {:action-id :gravity.reference/action-managed-string-allocation
            :principal-id source-principal
            :effect :memory/allocate
            :capability :memory/allocator
            :provider-id allocation-provider
            :grant-id allocation-grant
            :scope :pinned-runtime-plan
            :mode :pinned-reference
            :live-external-authority? false
            :decision :deny
            :result :deny
            :diagnostic diagnostic
            :reason reason}))
        preflight-action
        (fn [diagnostic remediation]
          (action
           {:action-id :gravity.reference/action-managed-string-allocation
            :operation :managed-allocation-preflight
            :provider-id allocation-provider
            :effect :memory/allocate
            :capability :memory/allocator
            :grant-id allocation-grant
            :principal-id source-principal
            :scope :pinned-runtime-plan
            :mode :pinned-reference
            :live-external-authority? false
            :action-started? false
            :action-status :rejected-before-start
            :result-committed? false
            :output-committed? false
            :diagnostic diagnostic
            :remediation remediation}))
        noncapability-preflight-action
        (fn [diagnostic missing-fact remediation]
          (let [record
                {:artifact :gravity/runtime-preflight-failure-record
                 :diagnostic diagnostic
                 :source-span
                 {:source-id (or source-id
                                 (:runtime-artifact-source-content-hash
                                  runtime-rule))}
                 :generated-origin-chain
                 [:source-unit :p15-s23-reference-runtime-adapter]
                 :artifact-id (or plan-id
                                  (:runtime-artifact-hash runtime-rule))
                 :runtime-function function
                 :operation :runtime-contract-preflight
                 :missing-fact missing-fact
                 :action-started? false
                 :action-status :rejected-before-start
                 :result-committed? false
                 :output-committed? false
                 :redaction :none
                 :remediation remediation}]
            (assoc record :record-id
                   (p15-s23-reference-runtime-hash record))))
        noncapability-preflight-decision
        (fn [diagnostic missing-fact]
          (let [record
                {:artifact :gravity/runtime-preflight-decision-record
                 :diagnostic diagnostic
                 :runtime-artifact-hash
                 (:runtime-artifact-hash runtime-rule)
                 :plan-id plan-id
                 :source-id source-id
                 :runtime-function function
                 :missing-fact missing-fact
                 :result :reject
                 :redaction :none}]
            (assoc record :decision-id
                   (p15-s23-reference-runtime-hash record))))
        reject
        (fn [diagnostic missing-fact action-record decision-record & [extra]]
          (p15-s23-reference-runtime-adapter-fail!
           diagnostic runtime-rule action-record decision-record missing-fact
           (or extra {})))
        reject-host-exception
        (fn [exception]
          (let [redaction
                {:cause-class (.getName (class exception))
                 :cause-message-hash
                 (str "sha256:"
                      (sha256-hex (or (.getMessage exception) "")))}
                action-record
                (action
                 {:action-id :gravity.reference/action-generic-host-boundary
                  :operation :generic-host-boundary
                  :provider-id :unresolved
                  :effect :unresolved
                  :capability :unresolved
                  :grant-id :unresolved
                  :principal-id source-principal
                  :scope :generic-host-boundary
                  :mode :untranslated-host-exception
                  :live-external-authority? false
                  :action-started? true
                  :action-status :failed-before-commit
                  :result-committed? false
                  :output-committed? false
                  :diagnostic "R4-EXCEPTION"
                  :redaction redaction
                  :failure-cause redaction
                  :remediation
                  :translate_host_exception_at_runtime_adapter})
                decision-record
                (decision
                 {:action-id :gravity.reference/action-generic-host-boundary
                  :principal-id source-principal
                  :effect :unresolved
                  :capability :unresolved
                  :provider-id :unresolved
                  :grant-id :unresolved
                  :scope :generic-host-boundary
                  :mode :untranslated-host-exception
                  :live-external-authority? false
                  :decision :deny
                  :result :deny
                  :reason :untranslated-host-exception
                  :redaction redaction
                  :failure-cause redaction})]
            (p15-s23-reference-runtime-adapter-fail!
             "R4-EXCEPTION" runtime-rule action-record decision-record
             :untranslated-host-exception
             {:redaction redaction
              :failure-cause redaction
              :boundary :generic-host-runner})))
        reject-preflight
        (fn [diagnostic missing-fact remediation]
          (if (str/starts-with? diagnostic "P15S23")
            (reject diagnostic missing-fact
                    (noncapability-preflight-action
                     diagnostic missing-fact remediation)
                    (noncapability-preflight-decision
                     diagnostic missing-fact))
            (reject diagnostic missing-fact
                    (preflight-action diagnostic remediation)
                    (preflight-decision diagnostic missing-fact))))
        authority-shape?
        (fn []
          (and (map? authority)
               (= p15-s23-reference-runtime-authority-keys
                  (set (keys authority)))
               (contains? #{:closed-plan-reference :deployment}
                          (:mode authority))
               (symbol? (:source-principal authority))
               (keyword? (:handler-principal authority))
               (set? (:providers authority))
               (set? (:grants authority))
               (contains? #{nil :allocation :capture}
                          (:failure-injection authority))
               (boolean? (:deployment-stdout? authority))))]
    (when-not (authority-shape?)
      (reject-preflight "R11-GRANT" :runtime-authority-schema
                        :supply_exact_runtime_authority_schema))
    (when-not (= function p15-s23-stage2-runtime-artifact-closed-plan-function)
      (reject-preflight "P15S23X002" :runtime-contract-function-scope
                        :use_closed_plan_runtime_entrypoint))
    (when-not (and (= source-principal (:source-principal authority))
                   (= handler-principal (:handler-principal authority)))
      (reject-preflight "R11-GRANT" :runtime-principal-binding
                        :restore_source_and_handler_principals))
    (when (seq (set/difference (:providers authority)
                               required-provider-ids))
      (reject-preflight "R11-GRANT" :runtime-provider-authority-widening
                        :remove_ungranted_provider_authority))
    (when (seq (set/difference (:grants authority)
                               required-grant-ids))
      (reject-preflight "R11-GRANT" :runtime-grant-authority-widening
                        :remove_ungranted_capability_authority))
    (when-not (contains? (:providers authority) allocation-provider)
      (reject "R5-PROVIDER" :managed-allocation-provider
              (allocation-action :rejected-before-start false false
                                 "R5-PROVIDER"
                                 :restore_managed_allocator_provider)
              (allocation-decision :deny :provider-missing)))
    (when (and writes-stdout?
               (not (contains? (:providers authority) capture-provider)))
      (reject "L15-PROVIDER-MISSING" :transcript-capture-provider
              (stdout-action :rejected-before-start false false false
                             "L15-PROVIDER-MISSING"
                             :restore_reference_transcript_provider)
              (stdout-decision :deny :provider-missing)))
    (doseq [[grant action-record decision-record]
            (cond->
             [[allocation-grant
               (allocation-action :rejected-before-start false false
                                  "R11-GRANT"
                                  :restore_managed_allocation_grant)
               (allocation-decision :deny :grant-missing)]]
              writes-stdout?
               (into
               [[stdout-grant
                 (stdout-action :rejected-before-start false false false
                                "R11-GRANT"
                                :restore_reference_stdout_grant)
                 (stdout-decision :deny :grant-missing)]
                [fixture-grant
                 (capture-action :rejected-before-start false false false
                                 "R11-GRANT"
                                 :restore_test_fixture_grant)
                 (fixture-decision :deny :grant-missing)]]))]
      (when-not (contains? (:grants authority) grant)
        (reject "R11-GRANT" :runtime-capability-grant
                action-record decision-record)))
    (when (or (:deployment-stdout? authority)
              (= :deployment (:mode authority)))
      (reject "L15-PROVIDER-MISSING" :deployment-stdout-provider
              (deployment-action)
              (deployment-decision)))
    ;; These provider/handler probes deliberately throw and catch a normal
    ;; Exception.  JVM Error (including OOM) is never caught or normalized.
    (try
      (when (= :allocation (:failure-injection authority))
        (throw (ex-info "injected allocation provider failure"
                        {:failure-injection :allocation})))
      (catch Exception exception
        (let [redaction
              {:cause-class (.getName (class exception))
               :cause-message-hash
               (str "sha256:"
                    (sha256-hex (or (.getMessage exception) "")))}]
          (reject "R1-FAILURE" :injected-allocation-failure
                  (allocation-action
                   :failed-before-commit true false
                   "R1-FAILURE"
                   :repair_or_replace_allocation_provider
                   {:redaction redaction :failure-cause redaction})
                  (allocation-decision
                   :grant :explicit-grant
                   {:redaction redaction :failure-cause redaction})
                  {:redaction redaction
                   :failure-cause redaction}))))
    (when (and (= :capture (:failure-injection authority))
               (not writes-stdout?))
      (reject-preflight "P15S23X002"
                        :inactive-capture-failure-injection
                        :remove_inactive_capture_failure_injection))
    (try
      (when (= :capture (:failure-injection authority))
        (throw (ex-info "injected transcript handler failure"
                        {:failure-injection :capture})))
      (catch Exception exception
        (let [redaction
              {:cause-class (.getName (class exception))
               :cause-message-hash
               (str "sha256:"
                    (sha256-hex (or (.getMessage exception) "")))}]
          (reject "R1-FAILURE" :injected-capture-failure
                  (capture-action
                   :failed-before-commit true false false
                   "R1-FAILURE"
                   :repair_or_replace_transcript_handler
                   {:redaction redaction :failure-cause redaction})
                  (fixture-decision
                   :grant :explicit-reference-harness-policy
                   {:redaction redaction :failure-cause redaction})
                  {:redaction redaction
                   :failure-cause redaction}))))
    (let [result
          (try
            (let [candidate
                  (p15-s23-stage2-runtime-artifact-invoke
                   runtime-rule function args)]
              (when-not
               (p15-s23-checked-core-reference-result-valid?
                candidate target-plan)
                (throw
                 (ex-info "invalid checked-core reference result envelope"
                          {:missing-fact
                           :exact-checked-core-reference-result-envelope})))
              candidate)
            (catch clojure.lang.ExceptionInfo ex
              (if (p15-s23-reference-runtime-structured-diagnostic?
                   ex #{(:runtime-artifact-source-path runtime-rule)
                        (get-in target-plan [:source :path])})
                (throw ex)
                (reject-host-exception ex)))
            (catch Exception ex
              (reject-host-exception ex)))
          record
          (p15-s23-reference-runtime-success-adapter-record
           plan-id source-id writes-stdout? (boolean (seq (:stdout result))))]
      {:result result
       :adapter-record record})))

(defn p15-s23-reference-runtime-adapter-invoke
  [runtime-rule function args authority]
  (let [safe-function
        (when (symbol? function) function)
        reject-input!
        (fn [diagnostic plan-id source-id missing-fact remediation extra]
          (p15-s23-reference-runtime-adapter-noncapability-reject!
           diagnostic runtime-rule safe-function plan-id source-id missing-fact
           remediation extra))
        bound-input!
        (fn [definition-name value maximum-nodes maximum-depth]
          (try
            (p15-s23-reference-runtime-bounded-value!
             "p15-s23-reference-runtime-adapter" :jvm definition-name value
             maximum-nodes maximum-depth)
            (catch Exception exception
              (let [data (ex-data exception)
                    failure-cause
                    {:cause-class (.getName (class exception))
                     :cause-message-hash
                     (str "sha256:"
                          (sha256-hex (or (.getMessage exception) "")))}]
                (reject-input!
                 "P15S23X002" nil nil
                 (or (:missing-fact data) :runtime-adapter-input-bounds)
                 :supply_bounded_runtime_adapter_input
                 (merge
                  (select-keys
                   data
                   [:runtime-contract-definition :observed-nodes
                    :observed-depth :maximum-nodes :maximum-depth
                    :observed-total-scalar-bytes
                    :maximum-total-scalar-bytes])
                  {:redaction failure-cause
                   :failure-cause failure-cause
                   :cause-diagnostic (:id data)}))))))]
    ;; Reject hostile collection/scalar domains and cumulative byte budgets
    ;; before reading any candidate plan identity or hashing a failure record.
    (bound-input! :runtime-adapter-function function 1
                  p15-s23-reference-runtime-max-contract-depth)
    (when-not (= p15-s23-stage2-runtime-artifact-closed-plan-function
                 function)
      (reject-input!
       "P15S23X002" nil nil :runtime-contract-function-scope
       :use_closed_plan_runtime_entrypoint {}))
    (bound-input! :runtime-adapter-arguments args
                  p15-s23-reference-runtime-max-contract-nodes
                  p15-s23-reference-runtime-max-closed-plan-carrier-depth)
    (bound-input! :runtime-adapter-authority authority
                  p15-s23-reference-runtime-max-contract-nodes
                  p15-s23-reference-runtime-max-contract-depth)
    (when-not (and (= "clojure.lang.PersistentVector"
                      (some-> args class .getName))
                   (= 1 (count args))
                   (contains?
                    p15-s23-reference-runtime-supported-collection-class-names
                    (some-> (first args) class .getName))
                   (map? (first args)))
      (reject-input!
       "P15S23X002" nil nil :runtime-adapter-argument-schema
       :supply_one_bounded_closed_plan {}))
    (let [target-plan (first args)]
      (bound-input! :runtime-adapter-target-plan target-plan
                    p15-s23-reference-runtime-max-contract-nodes
                    p15-s23-reference-runtime-max-closed-plan-carrier-depth)
      (let [candidate-plan-id (:plan-id target-plan)
            source-record (:source target-plan)
            module-record (:module target-plan)
            candidate-source-id
            (when (map? source-record) (:sha256 source-record))
            digest?
            #(and (string? %)
                  (boolean (re-matches #"sha256:[0-9a-f]{64}" %)))
            plan-id (when (digest? candidate-plan-id) candidate-plan-id)
            source-id (when (digest? candidate-source-id)
                        candidate-source-id)]
        (when-not (and (map? source-record)
                       (map? module-record)
                       plan-id source-id
                       (string? (:path source-record))
                       (string? (:source-path module-record)))
          (reject-input!
           "P15S23X002" plan-id source-id
           :runtime-adapter-plan-envelope
           :restore_closed_plan_identity {}))
        (let [normalized-plan
              (-> target-plan
                  (dissoc :plan-id)
                  (update :source dissoc :path)
                  (update :module dissoc :source-path))
              derived-plan-id
              (c4-artifact-id (c-backend-canonical-value normalized-plan))]
        (when-not (and (= derived-plan-id plan-id)
                       source-id)
          (reject-input!
           "P15S23X002" plan-id source-id
           :runtime-adapter-plan-identity
           :restore_closed_plan_identity {}))
        (when-not (p15-s23-reference-runtime-rule-authentic? runtime-rule)
          (reject-input!
           "P15S23X002" plan-id source-id
           :runtime-contract-authenticity
           :restore_pinned_runtime_contract {}))
        (let [closed-plan-validation
              (try
                (p15-s23-closed-runtime-plan-validation!
                 (get-in target-plan [:source :path]) :jvm target-plan)
                (catch Exception exception
                  (let [data (ex-data exception)
                        diagnostic
                        (if (contains?
                             p15-s23-reference-runtime-preserved-diagnostic-ids
                             (:id data))
                          (:id data)
                          "P15S23X002")
                        failure-cause
                        {:cause-class (.getName (class exception))
                         :cause-message-hash
                         (str "sha256:"
                              (sha256-hex
                               (or (.getMessage exception) "")))}]
                    (reject-input!
                     diagnostic plan-id source-id
                     (or (:missing-fact data)
                         :runtime-adapter-plan-validation)
                     :restore_bounded_closed_plan
                     {:redaction failure-cause
                      :failure-cause failure-cause
                      :cause-diagnostic (:id data)}))))]
          (p15-s23-reference-runtime-adapter-validated-invoke
           runtime-rule function args authority target-plan plan-id source-id
           closed-plan-validation)))))))

(defn c-backend-stage2-compiler-driver-source-rule!
  "Load and validate the Gravity-authored P15-S23 stage2 compiler driver.

  The public runtime-derived route is allowed to use the stage2 emitter and
  runtime only through this declared driver contract.  Keep the driver hash
  independent of the checkout path while retaining the resolved source path
  as provenance."
  [source-path target]
  (let [compiler-source (c-backend-resolve-p15-s23-compiler-source-path)]
    (when-not (.isFile (java.io.File. compiler-source))
      (p15-s23-stage2-compiler-driver-fail!
       "P15S23Y001"
       compiler-source
       nil
       {:requested-source source-path
        :target target
        :missing-fields [:compiler-source]
        :missing-fact :stage2-compiler-driver-source}))
    (let [pinned-source
          (p15-s23-stage2-compiler-pinned-source!
           compiler-source source-path target "P15S23Y001"
           p15-s23-stage2-compiler-driver-fail!)
          source-data
          (try
            (p15-s23-compiler-source-form-record-from-text
             compiler-source (:source-text pinned-source))
            (catch clojure.lang.ExceptionInfo ex
              (throw ex))
            (catch Exception ex
              (p15-s23-stage2-compiler-driver-fail!
               "P15S23Y001"
               compiler-source
               nil
               {:requested-source source-path
                :target target
                :missing-fact :stage2-compiler-driver-source
                :cause-message (.getMessage ex)})))
          forms (:forms source-data)
          driver
          (try
            (p15-s23-compiler-def-value
             compiler-source forms 'p15-s23-stage2-compiler-driver)
            (catch clojure.lang.ExceptionInfo ex
              (throw ex))
            (catch Exception ex
              (p15-s23-stage2-compiler-driver-fail!
               "P15S23Y001"
               compiler-source
               nil
               {:requested-source source-path
                :target target
                :missing-fact :stage2-compiler-driver-definition
                :cause-message (.getMessage ex)})))
          front-end
          (try
            (p15-s23-compiler-def-value
             compiler-source forms 'p15-s23-stage2-source-front-end)
            (catch clojure.lang.ExceptionInfo ex
              (throw ex))
            (catch Exception ex
              (p15-s23-stage2-compiler-driver-fail!
               "P15S23Y002"
               compiler-source
               nil
               {:requested-source source-path
                :target target
                :missing-fact :stage2-source-front-end-definition
                :cause-message (.getMessage ex)})))]
      (when-not (map? driver)
        (p15-s23-stage2-compiler-driver-fail!
         "P15S23Y001"
         compiler-source
         driver
         {:requested-source source-path
          :target target
          :missing-fields [:p15-s23-stage2-compiler-driver]
          :missing-fact :stage2-compiler-driver-definition}))
      (when-not (map? front-end)
        (p15-s23-stage2-compiler-driver-fail!
         "P15S23Y002"
         compiler-source
         front-end
         {:requested-source source-path
          :target target
          :missing-fields [:p15-s23-stage2-source-front-end]
          :missing-fact :stage2-source-front-end-definition}))
      (let [rule-record (p15-s23-stage2-compiler-driver-rule-record driver)
            required-links
            {:nucleus :p15-s23-stage2-compiler-nucleus
             :plan-emitter :p15-s23-stage2-plan-emitter
             :runtime-executor :p15-s23-stage2-runtime-executor
             :runtime-kernel :p15-s23-stage2-runtime-kernel
             :front-end-executor :p15-s23-stage2-front-end-executor
             :source-front-end :p15-s23-stage2-source-front-end}
            observed-links (select-keys driver (keys required-links))
            missing-links
            (set (for [[field expected] required-links
                       :when (not= expected (get observed-links field))]
                   field))
            execution-contract (:execution-contract driver)
            execution-ok?
            (and (= :stage0-compiled-core-plan
                    (:compare-against execution-contract))
                 (true? (:accepted-output-must-match-expected?
                         execution-contract))
                 (= :gravity-source-bytes (:input driver))
                 (= :stage2-driver-run-record (:output driver))
                 (= :hosted-core-source-to-stage2-runtime-execution
                    (:module-responsibility driver)))]
        (when-not (and (= :complete (:status rule-record))
                       (empty? missing-links)
                       execution-ok?
                       (= :gravity/stage2-compiler-driver
                          (:artifact driver))
                       (= :p15-s23-stage2-compiler-driver
                          (:stage driver))
                       (= :p15-s23-compiler-stage
                          (:compiler-stage driver)))
          (p15-s23-stage2-compiler-driver-fail!
           "P15S23Y002"
           compiler-source
           {:driver driver
            :rule-record rule-record
            :missing-links (p15-s23-stage2-sort-values missing-links)
            :execution-contract execution-contract}
           {:requested-source source-path
            :target target
            :missing-fact :stage2-compiler-driver-rule-set
            :missing-links (p15-s23-stage2-sort-values missing-links)
            :execution-contract-valid? execution-ok?
            :rule-record rule-record}))
        (let [driver-rule-hash
              (str "sha256:"
                   (sha256-hex
                    (pr-str (c-backend-canonical-value driver))))
              source-content-hash
              (str "sha256:" (sha256-hex (:source-text source-data)))]
          {:driver driver
           :front-end front-end
           :rule-record rule-record
           :driver-engine (:engine driver)
           :driver-rule-hash driver-rule-hash
           :driver-source-path compiler-source
           :driver-source-content-hash source-content-hash
           :driver-rule-source
           {:kind :gravity-source
            :sha256 source-content-hash
            :driver-rule-hash driver-rule-hash
            :stage :p15-s23-stage2-compiler-driver}})))))

(defn stage2-runtime-derived-packet-fail!
  [id message source-path requested-target subject extra]
  (fail! id message
         (merge {:severity :error
                 :stage :stage2-runtime-derived-packet
                 :diagnostic-family :c14-target-lowering
                 :backend :target-neutral-stage2
                 :target requested-target
                 :source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :primary {:span (or (:source-span subject)
                                     (source-span source-path 0))}
                 :fallback-status :rejected}
                extra)))

(def stage2-runtime-derived-source-targets
  ;; :llvm and :wasm are admitted only to the internal pure checked-core/C11
  ;; construction path.  Effectful reference authority remains explicitly
  ;; JVM-only below.
  #{:jvm :c :c-hosted :c11 :js :js-ts :llvm :wasm})

(def p15-s23-closed-runtime-operations
  #{:literal :quote :local :builtin-call :println :do :if :let})

(def p15-s23-closed-runtime-max-depth 128)
(def p15-s23-closed-runtime-max-nodes 128)

(defn p15-s23-closed-runtime-inferred-type
  [instruction local-types depth]
  (if (or (> depth p15-s23-closed-runtime-max-depth)
          (not (map? instruction)))
    :unknown
    (case (:op instruction)
      :literal
      (let [value (:value instruction)]
        (cond
          (integer? value) :gravity/integer
          (boolean? value) :gravity/bool
          (string? value) :gravity/string
          (nil? value) :gravity/nil
          :else :unknown))

      :quote
      (let [value (:value instruction)]
        (cond
          (integer? value) :gravity/integer
          (boolean? value) :gravity/bool
          (string? value) :gravity/string
          (nil? value) :gravity/nil
          :else :unknown))

      :local
      (get local-types (:name instruction) :unknown)

      :builtin-call
      (let [function (:function instruction)
            arguments (:args instruction)]
        (cond
          (= 'str function) :gravity/string
          (and (contains? '#{= < <= > >=} function)
               (vector? arguments)
               (= 2 (count arguments))
               (every?
                #(= :gravity/integer
                    (p15-s23-closed-runtime-inferred-type
                     % local-types (inc depth)))
                arguments))
          :gravity/bool
          :else :unknown))

      :println :gravity/nil

      :do
      (let [body (:body instruction)]
        (if (and (vector? body) (seq body))
          (p15-s23-closed-runtime-inferred-type
           (peek body) local-types (inc depth))
          :gravity/nil))

      :if
      (let [then-type
            (p15-s23-closed-runtime-inferred-type
             (:then instruction) local-types (inc depth))
            else-type
            (p15-s23-closed-runtime-inferred-type
             (:else instruction) local-types (inc depth))]
        (if (= then-type else-type) then-type :unknown))

      :let
      (let [bindings (:bindings instruction)
            body (:body instruction)]
        (if (and (vector? bindings)
                 (vector? body)
                 (every? #(and (map? %)
                               (symbol? (:name %))
                               (map? (:expr %)))
                         bindings))
          (let [next-types
                (reduce
                 (fn [types binding]
                   (assoc
                    types (:name binding)
                    (p15-s23-closed-runtime-inferred-type
                     (:expr binding) types (inc depth))))
                 local-types bindings)]
            (if (seq body)
              (p15-s23-closed-runtime-inferred-type
               (peek body) next-types (inc depth))
              :gravity/nil))
          :unknown))

      :unknown)))

(defn p15-s23-closed-runtime-plan-validation!
  "Validate the exact public closed-plan subset before the Gravity executor is
  invoked.  The walk is iterative, bounded, and carries lexical bindings plus
  conservative scalar type facts, so a hostile plan cannot reach recursive
  Gravity evaluation or fail through the host stack."
  [source-path requested-target plan]
  (let [entrypoint (:entrypoint plan)
        definition (get-in plan [:functions entrypoint])]
    (when-not (and (symbol? entrypoint)
                   (map? definition)
                   (integer? (:arity definition))
                   (zero? (:arity definition))
                   (vector? (:params definition))
                   (empty? (:params definition))
                   (vector? (:instructions definition)))
      (p15-s23-stage2-runtime-executor-fail!
       "P15S23X002" source-path definition
       {:target requested-target
        :missing-fact :closed-plan-entrypoint-shape}))
    (loop [pending (vec (map (fn [instruction]
                             {:instruction instruction
                                :locals #{}
                                :local-types {}
                                :depth 1})
                             (:instructions definition)))
           visited 0
           observed-operation-set #{}]
      (if-let [{:keys [instruction locals local-types depth]}
               (peek pending)]
        (let [pending (pop pending)
              visited (inc visited)
              op (when (map? instruction) (:op instruction))
              observed-operation-set (conj observed-operation-set op)]
          (when (or (> depth p15-s23-closed-runtime-max-depth)
                    (> visited p15-s23-closed-runtime-max-nodes))
            (p15-s23-stage2-runtime-executor-fail!
             "P15S23X002" source-path instruction
             {:target requested-target
              :missing-fact :closed-plan-bounds
              :maximum-depth p15-s23-closed-runtime-max-depth
              :maximum-nodes p15-s23-closed-runtime-max-nodes
              :observed-depth depth
              :observed-nodes visited}))
          (when-not (and (map? instruction)
                         (contains? p15-s23-closed-runtime-operations op))
            (p15-s23-stage2-runtime-executor-fail!
             "P15S23X002" source-path instruction
             {:target requested-target
              :missing-fact :closed-plan-operation
              :unsupported-operation op}))
          (case op
            :literal
            (do
              (when-not (c-backend-runtime-literal? (:value instruction))
                (p15-s23-stage2-runtime-executor-fail!
                 "P15S23X002" source-path instruction
                 {:target requested-target
                  :missing-fact :closed-plan-literal}))
              (recur pending visited observed-operation-set))
            :quote
            (do
              (when-not (c-backend-runtime-literal? (:value instruction))
                (p15-s23-stage2-runtime-executor-fail!
                 "P15S23X002" source-path instruction
                 {:target requested-target
                  :missing-fact :closed-plan-literal}))
              (recur pending visited observed-operation-set))
            :local
            (do
              (when-not (and (symbol? (:name instruction))
                             (contains? locals (:name instruction)))
                (p15-s23-stage2-runtime-executor-fail!
                 "P15S23X002" source-path instruction
                 {:target requested-target
                  :missing-fact :closed-plan-local-binding
                  :local (:name instruction)}))
              (recur pending visited observed-operation-set))
            :builtin-call
            (let [args (:args instruction)
                  function (:function instruction)
                  observed-arity (when (vector? args) (count args))
                  comparison?
                  (contains? '#{= < <= > >=} function)
                  operand-types
                  (when (and comparison? (vector? args))
                    (mapv
                     #(p15-s23-closed-runtime-inferred-type
                       % local-types (inc depth))
                     args))]
              (when-not (and (vector? args)
                             (or (= 'str function) comparison?))
                (p15-s23-stage2-runtime-executor-fail!
                 "P15S23X002" source-path instruction
                 {:target requested-target
                  :missing-fact :closed-plan-builtin
                  :function function
                  :actual-arity observed-arity}))
              (when-not (if comparison?
                          (= 2 observed-arity)
                          (contains? #{1 2} observed-arity))
                (p15-s23-stage2-runtime-fail-call-arity!
                 "L2-BUILTIN-ARITY" plan function
                 (if (coll? args) args [])
                 (if comparison? 2 "1 or 2")))
              (when (and comparison?
                         (not= [:gravity/integer :gravity/integer]
                               operand-types))
                (p15-s23-stage2-runtime-executor-fail!
                 "P15S23X002" source-path instruction
                 {:target requested-target
                  :missing-fact
                  :closed-plan-binary-integer-comparison-operands
                  :function function
                  :operand-types operand-types}))
              (recur (into pending
                           (map (fn [child]
                                  {:instruction child
                                   :locals locals
                                   :local-types local-types
                                   :depth (inc depth)})
                                args))
                     visited
                     observed-operation-set))
            :println
            (let [args (:args instruction)
                  observed-arity (when (vector? args) (count args))]
              (when-not (and (vector? args)
                             (<= observed-arity
                                 p15-s23-closed-runtime-max-nodes)
                             (= :io/write (:effect instruction))
                             (= :io/stdout (:capability instruction)))
                (p15-s23-stage2-runtime-executor-fail!
                 "P15S23X002" source-path instruction
                 {:target requested-target
                  :missing-fact :closed-plan-println-contract
                  :actual-arity observed-arity}))
              (recur (into pending
                           (map (fn [child]
                                  {:instruction child
                                   :locals locals
                                   :local-types local-types
                                   :depth (inc depth)})
                                args))
                     visited
                     observed-operation-set))
            :do
            (do
              (when-not (vector? (:body instruction))
                (p15-s23-stage2-runtime-executor-fail!
                 "P15S23X002" source-path instruction
                 {:target requested-target
                  :missing-fact :closed-plan-do-shape}))
              (recur (into pending
                           (map (fn [child]
                                  {:instruction child
                                   :locals locals
                                   :local-types local-types
                                   :depth (inc depth)})
                                (:body instruction)))
                     visited
                     observed-operation-set))
            :if
            (do
              (when-not (and (map? (:test instruction))
                             (map? (:then instruction))
                             (map? (:else instruction)))
                (p15-s23-stage2-runtime-executor-fail!
                 "P15S23X002" source-path instruction
                 {:target requested-target
                  :missing-fact :closed-plan-if-shape}))
              (recur (into pending
                           (map (fn [child]
                                  {:instruction child
                                   :locals locals
                                   :local-types local-types
                                   :depth (inc depth)})
                                [(:test instruction)
                                 (:then instruction)
                                 (:else instruction)]))
                     visited
                     observed-operation-set))
            :let
            (let [bindings (:bindings instruction)
                  body (:body instruction)]
              (when-not (and (vector? bindings)
                             (vector? body)
                             (every? #(and (map? %)
                                           (symbol? (:name %))
                                           (map? (:expr %)))
                                     bindings))
                (p15-s23-stage2-runtime-executor-fail!
                 "P15S23X002" source-path instruction
                 {:target requested-target
                  :missing-fact :closed-plan-let-shape}))
              (let [binding-names (mapv :name bindings)
                    duplicate (first (for [name binding-names
                                           :when (> (count
                                                     (filter #{name}
                                                             binding-names))
                                                    1)]
                                       name))
                    next-locals (into locals binding-names)
                    next-local-types
                    (reduce
                     (fn [types binding]
                       (assoc
                        types (:name binding)
                        (p15-s23-closed-runtime-inferred-type
                         (:expr binding) types (inc depth))))
                     local-types bindings)]
                (when duplicate
                  (p15-s23-stage2-runtime-executor-fail!
                   "P15S23X002" source-path instruction
                   {:target requested-target
                    :missing-fact :closed-plan-let-binding
                    :duplicate-local duplicate}))
                ;; Binding expressions are evaluated left-to-right.  Carry the
                ;; preceding names into each validation frame, matching the
                ;; lexical environment used by the Gravity implementation.
                (let [binding-frames
                      (:frames
                       (reduce
                        (fn [{:keys [frames scope types]} binding]
                          {:frames
                           (conj frames
                                 {:instruction (:expr binding)
                                  :locals scope
                                  :local-types types
                                  :depth (inc depth)})
                           :scope (conj scope (:name binding))
                           :types
                           (assoc
                            types (:name binding)
                            (p15-s23-closed-runtime-inferred-type
                             (:expr binding) types (inc depth)))})
                        {:frames [] :scope locals :types local-types}
                        bindings))
                      body-frames
                      (map (fn [child]
                             {:instruction child
                              :locals next-locals
                              :local-types next-local-types
                              :depth (inc depth)})
                           body)]
                  (recur (into pending (concat binding-frames body-frames))
                         visited
                         observed-operation-set))))))
        {:artifact :gravity/p15-s23-runtime-closed-plan-validation-record
         :status :complete
         :entrypoint entrypoint
         :operation-set p15-s23-closed-runtime-operations
         :observed-operation-set observed-operation-set
         :node-count visited
         :maximum-depth p15-s23-closed-runtime-max-depth
         :maximum-nodes p15-s23-closed-runtime-max-nodes}))))

(defn stage2-runtime-derived-packet
  "Build the target-neutral, verified stage2 packet shared by executable
  backends.  The packet owns source/front-end/plan/runtime authenticity and
  differential execution; concrete backends only validate and emit their
  target instruction subset.

  `:jvm` remains the bootstrap seed target and may be explicitly overridden by
  a backend lowering request.  A non-seed source target is a real constraint
  and must equal the requested target.  The eligibility decision is carried as
  evidence rather than erased or relabelled."
  ([source-path source-text requested-target]
   (stage2-runtime-derived-packet source-path source-text requested-target {}))
  ([source-path source-text requested-target {:keys [validate-plan!]}]
   (when-not (contains? stage2-runtime-derived-source-targets
                        requested-target)
     (stage2-runtime-derived-packet-fail!
      "C14-UNSUPPORTED"
      "requested runtime-derived target is not supported"
      source-path requested-target nil
      {:requested-target requested-target
       :supported-targets
       (vec (sort stage2-runtime-derived-source-targets))
       :missing-fact :supported-runtime-derived-target}))
   (binding [*additional-bootstrap-targets*
             stage2-runtime-derived-source-targets]
    (let [stage2-rule
          (c-backend-stage2-plan-emitter-source-rule!
           source-path requested-target)
          stage2-runtime-rule
          (c-backend-stage2-runtime-source-rule!
           source-path requested-target)
          stage2-driver-rule
          (c-backend-stage2-compiler-driver-source-rule!
           source-path requested-target)
          plan
          (try
            (p15-s23-stage2-plan-emitter-compile-source
             (:emitter stage2-rule) source-path source-text)
            (catch clojure.lang.ExceptionInfo ex
              (throw ex))
            (catch StackOverflowError ex
              (p15-s23-stage2-runtime-executor-fail!
               "P15S23X002" source-path nil
               {:target requested-target
                :cause-message (.getMessage ex)
                :missing-fact :closed-plan-bounds
                :boundary :source-to-stage2-plan
                :maximum-depth p15-s23-closed-runtime-max-depth
                :maximum-nodes p15-s23-closed-runtime-max-nodes}))
            (catch Exception ex
              (stage2-runtime-derived-packet-fail!
               "C14-UNSUPPORTED"
               "stage2 plan emitter could not compile the source"
               source-path requested-target nil
               {:cause-message (.getMessage ex)
                :missing-fact :stage2-plan-emission})))
          ;; Give a concrete backend its historical input boundary before the
          ;; shared packet applies a generic integrity diagnostic or executes
          ;; the stage2 runtime.
          _ (when validate-plan! (validate-plan! plan))
          _ (when-not (and (= :gravity/stage2-hosted-core-compiled-plan
                               (:kind plan))
                           (= :p15-s23-stage2-plan-emitter
                              (get-in plan [:compiler :rule-source]))
                           (map? (:functions plan))
                           (symbol? (:entrypoint plan))
                           (contains? (:functions plan) (:entrypoint plan))
                           (vector? (get-in plan
                                            [:functions (:entrypoint plan)
                                             :instructions])))
              (stage2-runtime-derived-packet-fail!
               "C14-INPUT" "stage2 plan integrity validation failed"
               source-path requested-target plan
               {:observed-plan-kind (:kind plan)
                :observed-rule-source (get-in plan [:compiler :rule-source])
                :missing-fact :stage2-plan-integrity}))
          raw-source-declared-target (get-in plan [:module :target])
          source-declared-target
          (if (= :js raw-source-declared-target)
            :js-ts
            raw-source-declared-target)
          target-eligibility
          (cond
            (= source-declared-target requested-target)
            (cond-> {:status :accepted
                     :source-declared-target source-declared-target
                     :requested-target requested-target
                     :selection :source-and-request-agree}
              (not= raw-source-declared-target source-declared-target)
              (assoc :raw-source-declared-target
                     raw-source-declared-target
                     :source-target-alias-canonicalized? true))

            (= :jvm source-declared-target)
            {:status :accepted
             :source-declared-target :jvm
             :requested-target requested-target
             :selection :explicit-bootstrap-seed-target-override
             :bootstrap-seed-target? true}

            :else
            (stage2-runtime-derived-packet-fail!
             "C14-PROFILE"
             "source target constraint is incompatible with requested target"
             source-path requested-target plan
             {:source-declared-target source-declared-target
              :requested-target requested-target
              :missing-fact :target-constraint-compatibility}))
          closed-plan-validation
          (p15-s23-closed-runtime-plan-validation!
           source-path requested-target plan)
          compiler-artifact-record
          {:artifact :gravity/p15-s23-stage2-expression-lowering-binding
           :source-content-hash
           (get-in plan
                   [:compiler :expression-lowering-source-content-hash])
           :semantic-hash
           (get-in plan [:compiler :expression-lowering-semantic-hash])
           :artifact-hash
           (get-in plan [:compiler :expression-lowering-artifact-hash])
           :functions p15-s23-stage2-compiler-artifact-required-functions
           :invoked?
           (true? (get-in plan
                          [:compiler :expression-lowering-invoked?]))
           :generic-bridge-residual?
           (true? (get-in plan
                          [:compiler
                           :expression-lowering-generic-bridge-residual?]))
           :plan-assembly-function
           (get-in plan [:compiler :plan-assembly-function])
           :plan-assembly-source-content-hash
           (get-in plan [:compiler :plan-assembly-source-content-hash])
           :plan-assembly-semantic-hash
           (get-in plan [:compiler :plan-assembly-semantic-hash])
           :plan-assembly-artifact-hash
           (get-in plan [:compiler :plan-assembly-artifact-hash])
           :plan-assembly-invoked?
           (true? (get-in plan [:compiler :plan-assembly-invoked?]))
           :plan-assembly-generic-bridge-residual?
           (true? (get-in plan
                          [:compiler
                           :plan-assembly-generic-bridge-residual?]))
           :clojure-seed-boundary? true
           :self-hosted? false}
          _ (when-not
              (and
               (p15-s23-stage2-compiler-artifact-record-authentic?
                compiler-artifact-record)
               (p15-s23-stage2-compiler-artifact-record-matches-plan?
                compiler-artifact-record plan))
              (p15-s23-stage2-plan-emitter-fail!
               "P15S23Q002" source-path compiler-artifact-record
               {:target requested-target
                :missing-fact
                :stage2-expression-lowering-packet-binding}))
          stage2-driver-run
          (try
            (p15-s23-stage2-compiler-driver-run-source
             (:driver stage2-driver-rule)
             (:front-end stage2-driver-rule)
             (:emitter stage2-rule)
             (assoc (:runtime stage2-runtime-rule)
                    :runtime-artifact-plan
                    (:runtime-artifact-plan stage2-runtime-rule)
                    :runtime-artifact-source-path
                    (:runtime-artifact-source-path stage2-runtime-rule)
                    :runtime-artifact-hash
                    (:runtime-artifact-hash stage2-runtime-rule))
             source-path source-text)
            (catch clojure.lang.ExceptionInfo ex
              (throw ex))
            (catch StackOverflowError ex
              (p15-s23-stage2-runtime-executor-fail!
               "P15S23X002" source-path nil
               {:target requested-target
                :cause-message (.getMessage ex)
                :missing-fact :closed-plan-bounds
                :boundary :stage2-driver-execution
                :maximum-depth p15-s23-closed-runtime-max-depth
                :maximum-nodes p15-s23-closed-runtime-max-nodes}))
            (catch Exception ex
              (p15-s23-stage2-compiler-driver-fail!
               "P15S23Y003" source-path nil
               {:target requested-target
                :driver-engine (:driver-engine stage2-driver-rule)
                :driver-rule-hash (:driver-rule-hash stage2-driver-rule)
                :cause-message (.getMessage ex)
                :missing-fact :stage2-driver-execution})))
          _ (when-not (and (map? stage2-driver-run)
                           (= :complete (:status stage2-driver-run))
                           (true? (:accepted-output-equivalent?
                                   stage2-driver-run))
                           (map? (:stage2-plan stage2-driver-run))
                           (= :complete
                              (get-in stage2-driver-run
                                      [:stage2-runtime-execution-record
                                       :status]))
                           (true? (:stage2-runtime-executed?
                                   stage2-driver-run)))
              (p15-s23-stage2-compiler-driver-fail!
               "P15S23Y003" source-path stage2-driver-run
               {:requested-source source-path
                :target requested-target
                :driver-engine (:driver-engine stage2-driver-rule)
                :driver-rule-hash (:driver-rule-hash stage2-driver-rule)
                :missing-fact :stage2-driver-execution-equivalence}))
          driver-plan (:stage2-plan stage2-driver-run)
          plan-shape (select-keys plan
                                  [:kind :entrypoint :functions :binding-table
                                   :instruction-summary :effect-summary])
          driver-plan-shape
          (select-keys driver-plan
                       [:kind :entrypoint :functions :binding-table
                        :instruction-summary :effect-summary])
          _ (when-not (= (c-backend-canonical-value plan-shape)
                         (c-backend-canonical-value driver-plan-shape))
              (p15-s23-stage2-compiler-driver-fail!
               "P15S23Y003" source-path
               {:stage2-plan plan-shape :driver-plan driver-plan-shape}
               {:requested-source source-path
                :target requested-target
                :driver-engine (:driver-engine stage2-driver-rule)
                :driver-rule-hash (:driver-rule-hash stage2-driver-rule)
                :missing-fact :stage2-driver-plan-equivalence}))
          runtime-adapter-output
          (try
            (p15-s23-reference-runtime-adapter-invoke
             stage2-runtime-rule
             p15-s23-stage2-runtime-artifact-closed-plan-function
             [plan]
             (p15-s23-reference-runtime-authority
              plan closed-plan-validation))
            (catch clojure.lang.ExceptionInfo ex
              (throw ex))
            (catch StackOverflowError ex
              (p15-s23-stage2-runtime-executor-fail!
               "P15S23X002" source-path nil
               {:target requested-target
                :cause-message (.getMessage ex)
                :missing-fact :closed-plan-bounds
                :maximum-depth p15-s23-closed-runtime-max-depth
                :maximum-nodes p15-s23-closed-runtime-max-nodes}))
            (catch Exception ex
              (p15-s23-stage2-runtime-executor-fail!
               "P15S23X003" source-path nil
               {:target requested-target
                :cause-message (.getMessage ex)
                :missing-fact :gravity-closed-plan-execution})))
          closed-plan-execution (:result runtime-adapter-output)
          runtime-contract-adapter-record
          (:adapter-record runtime-adapter-output)
          _ (when-not
              (and
               (= :gravity/p15-s23-runtime-closed-plan-execution-record
                  (:artifact closed-plan-execution))
               (= (:entrypoint plan) (:entrypoint closed-plan-execution))
               (string? (:stdout closed-plan-execution))
               (= :complete (:status closed-plan-execution))
               (true? (:clojure-seed-boundary? closed-plan-execution))
               (false? (:self-hosted? closed-plan-execution)))
              (p15-s23-stage2-runtime-executor-fail!
               "P15S23X003" source-path closed-plan-execution
               {:target requested-target
                :missing-fact :gravity-closed-plan-execution-record}))
          closed-plan-execution-hash
          (str "sha256:"
               (sha256-hex
                (pr-str
                 (c-backend-canonical-value closed-plan-execution))))
          closed-plan-invocation
          {:artifact :gravity/p15-s23-runtime-closed-plan-invocation-record
           :function p15-s23-stage2-runtime-artifact-closed-plan-function
           :function-hash
           (:runtime-artifact-closed-plan-function-hash
            stage2-runtime-rule)
           :runtime-artifact-hash
           (:runtime-artifact-hash stage2-runtime-rule)
           :plan-id (:plan-id plan)
           :execution-hash closed-plan-execution-hash
           :stdout-hash
           (str "sha256:" (sha256-hex (:stdout closed-plan-execution)))
           :invocation-count 1
           :invocation-count-scope :authoritative-packet-construction
           :verification-replays-excluded? true
           :status :complete
           :clojure-seed-boundary? true
           :self-hosted? false}
          stage2-runtime-execution
          (:stage2-runtime-execution-record stage2-driver-run)
          reference-output
          (try
            (execute-stage0-compiled-plan plan)
            (catch clojure.lang.ExceptionInfo ex
              (throw ex))
            (catch StackOverflowError ex
              (p15-s23-stage2-runtime-executor-fail!
               "P15S23X002" source-path nil
               {:target requested-target
                :cause-message (.getMessage ex)
                :missing-fact :closed-plan-bounds
                :boundary :stage0-oracle-execution
                :maximum-depth p15-s23-closed-runtime-max-depth
                :maximum-nodes p15-s23-closed-runtime-max-nodes}))
            (catch Exception ex
              (stage2-runtime-derived-packet-fail!
               "C14-UNSUPPORTED"
               "stage2 plan lacks closed hosted runtime semantics"
               source-path requested-target nil
               {:cause-message (.getMessage ex)
                :missing-fact :closed-stage2-runtime-semantics})))
          _ (when-not (= (:stdout stage2-runtime-execution)
                         reference-output)
              (p15-s23-stage2-runtime-executor-fail!
               "P15S23X003" source-path stage2-runtime-execution
               {:requested-source source-path
                :target requested-target
                :runtime-engine (:runtime-engine stage2-runtime-rule)
                :runtime-rule-hash (:runtime-rule-hash stage2-runtime-rule)
                :stage2-runtime-output (:stdout stage2-runtime-execution)
                :stage0-reference-output reference-output
                :missing-fact :stage2-stage0-output-equivalence}))
          _ (when-not (and (= (:stdout closed-plan-execution)
                              (:stdout stage2-runtime-execution))
                           (= (:stdout closed-plan-execution)
                              reference-output))
              (p15-s23-stage2-runtime-executor-fail!
               "P15S23X003" source-path closed-plan-execution
               {:requested-source source-path
                :target requested-target
                :gravity-closed-plan-output (:stdout closed-plan-execution)
                :clojure-stage2-output (:stdout stage2-runtime-execution)
                :stage0-reference-output reference-output
                :missing-fact :closed-plan-three-way-output-equivalence}))]
      {:kind :gravity/target-neutral-stage2-runtime-packet
       :status :complete
       :requested-target requested-target
       :target-eligibility target-eligibility
       :plan plan
       :stage2-compiler-artifact-record compiler-artifact-record
       :provenance
       {:actual-paths
        {:stage2-compiler-source
         (:stage2-compiler-source-path stage2-runtime-rule)
         :stage2-expression-lowering-source
         (p15-s23-stage2-compiler-artifact-source-path)
         :stage2-runtime-artifact-source
         (:runtime-artifact-source-path stage2-runtime-rule)}}
       :stage2-plan-emitter-rule stage2-rule
       :stage2-runtime-rule stage2-runtime-rule
       :closed-plan-validation-record closed-plan-validation
       :closed-plan-execution-record closed-plan-execution
       :closed-plan-invocation-record closed-plan-invocation
       :runtime-contract-adapter-record runtime-contract-adapter-record
       :stage2-compiler-driver-rule stage2-driver-rule
       :stage2-compiler-driver-record stage2-driver-run
       :stage2-runtime-execution-record stage2-runtime-execution
       :reference-output reference-output}))))

(defn p15-s23-closed-runtime-packet-context
  [source-path source-text requested-target]
  {:source-path source-path
   :source-text source-text
   :source-content-hash (str "sha256:" (sha256-hex source-text))
   :requested-target requested-target})

(defn p15-s23-closed-runtime-packet-authentic?
  "Authenticate a packet against source bytes supplied by its trusted caller.

  Packet-local hashes only prove internal consistency, so the one-argument
  form fails closed.  The context form independently recompiles the trusted
  source with the pinned Gravity emitter and reloads the pinned Gravity runtime
  before it validates identities or performs the verification replay."
  ([packet]
   false)
  ([packet context]
   (try
     (let [_ (p15-s23-reference-runtime-bounded-value!
              (when (map? context) (:source-path context))
              (when (map? context) (:requested-target context))
              :closed-runtime-packet packet
              p15-s23-reference-runtime-max-packet-nodes
              p15-s23-reference-runtime-max-closed-plan-carrier-depth)
           _ (p15-s23-reference-runtime-bounded-value!
              (when (map? context) (:source-path context))
              (when (map? context) (:requested-target context))
              :closed-runtime-packet-context context
              p15-s23-reference-runtime-max-contract-nodes
              p15-s23-reference-runtime-max-contract-depth)
           context-valid?
           (and (map? context)
                (= #{:source-path :source-text :source-content-hash
                     :requested-target}
                   (set (keys context)))
                (string? (:source-path context))
                (string? (:source-text context))
                (= :valid
                   (:status
                    (p15-s23-reference-runtime-bounded-utf8-count
                     (:source-text context)
                     p15-s23-reference-runtime-max-context-source-bytes)))
                (keyword? (:requested-target context))
                (contains? stage2-runtime-derived-source-targets
                           (:requested-target context))
                (= (:source-content-hash context)
                   (str "sha256:" (sha256-hex (:source-text context)))))
           packet-envelope-valid?
           (and (map? packet)
                (= #{:kind :status :requested-target :target-eligibility
                     :plan :stage2-compiler-artifact-record :provenance
                     :stage2-plan-emitter-rule :stage2-runtime-rule
                     :closed-plan-validation-record
                     :closed-plan-execution-record
                     :closed-plan-invocation-record
                     :runtime-contract-adapter-record
                     :stage2-compiler-driver-rule
                     :stage2-compiler-driver-record
                     :stage2-runtime-execution-record :reference-output}
                   (set (keys packet)))
                (= :gravity/target-neutral-stage2-runtime-packet
                   (:kind packet))
                (= :complete (:status packet))
                (= (:requested-target context) (:requested-target packet)))
           candidate-runtime-rule-authentic?
           (and context-valid?
                packet-envelope-valid?
                (p15-s23-reference-runtime-rule-authentic?
                 (:stage2-runtime-rule packet)))
           packet-plan (:plan packet)
           derived-validation
           (when candidate-runtime-rule-authentic?
             (try
               (p15-s23-closed-runtime-plan-validation!
                (:source-path context)
                (:requested-target context)
                packet-plan)
               (catch Exception _ nil)))
           trusted-stage2-rule
           (when derived-validation
             (try
               (c-backend-stage2-plan-emitter-source-rule!
                (:source-path context) (:requested-target context))
               (catch Exception _ nil)))
           trusted-plan
           (when trusted-stage2-rule
             (try
               (binding [*additional-bootstrap-targets*
                         stage2-runtime-derived-source-targets]
                 (p15-s23-stage2-plan-emitter-compile-source
                  (:emitter trusted-stage2-rule)
                  (:source-path context)
                  (:source-text context)))
               (catch Exception _ nil)))
           trusted-plan-validation
           (when trusted-plan
             (try
               (p15-s23-closed-runtime-plan-validation!
                (:source-path context)
                (:requested-target context)
                trusted-plan)
               (catch Exception _ nil)))
           trusted-driver-rule
           (when trusted-plan-validation
             (try
               (c-backend-stage2-compiler-driver-source-rule!
                (:source-path context) (:requested-target context))
               (catch Exception _ nil)))
           trusted-runtime-rule
           (when trusted-driver-rule
             (try
               (c-backend-stage2-runtime-source-rule!
                (:source-path context) (:requested-target context))
               (catch Exception _ nil)))
           trusted-driver-record
           (when trusted-runtime-rule
             (try
               (binding [*additional-bootstrap-targets*
                         stage2-runtime-derived-source-targets]
                 (p15-s23-stage2-compiler-driver-run-source
                  (:driver trusted-driver-rule)
                  (:front-end trusted-driver-rule)
                  (:emitter trusted-stage2-rule)
                  (assoc (:runtime trusted-runtime-rule)
                         :runtime-artifact-plan
                         (:runtime-artifact-plan trusted-runtime-rule)
                         :runtime-artifact-source-path
                         (:runtime-artifact-source-path trusted-runtime-rule)
                         :runtime-artifact-hash
                         (:runtime-artifact-hash trusted-runtime-rule))
                  (:source-path context)
                  (:source-text context)))
               (catch Exception _ nil)))]
       (if-not (and derived-validation trusted-plan trusted-plan-validation
                    trusted-driver-rule
                    trusted-runtime-rule trusted-driver-record)
         false
         (let [validation (:closed-plan-validation-record packet)
               execution (:closed-plan-execution-record packet)
               invocation (:closed-plan-invocation-record packet)
               adapter-record (:runtime-contract-adapter-record packet)
               runtime-rule (:stage2-runtime-rule packet)
               emitter-rule (:stage2-plan-emitter-rule packet)
               driver-rule (:stage2-compiler-driver-rule packet)
               driver-record (:stage2-compiler-driver-record packet)
               driver-plan (:stage2-plan driver-record)
               normalize-plan
               (fn [plan]
                 (-> plan
                     (dissoc :plan-id)
                     (update :source dissoc :path)
                     (update :module dissoc :source-path)))
               packet-plan-base (normalize-plan packet-plan)
               trusted-plan-base (normalize-plan trusted-plan)
               driver-plan-base (normalize-plan driver-plan)
               normalize-comparison
               (fn [plan-base]
                 ;; The stage2 source front end materializes empty export and
                 ;; provider vectors while the direct emitter omits them.
                 ;; Normalize only those empty clauses for cross-path
                 ;; comparison, never for the canonical plan id.
                 (-> plan-base
                     (update-in [:module :exports] #(vec (or % [])))
                     (update-in [:module :providers] #(vec (or % [])))))
               normalize-emitter-rule #(dissoc % :source-path)
               normalize-driver-rule #(dissoc % :driver-source-path)
               normalize-runtime-rule
               #(-> %
                    (dissoc :stage2-compiler-source-path
                            :runtime-artifact-source-path
                            :runtime-source-path)
                    (update :runtime-artifact-authoritative-module
                            dissoc :source-path)
                    (update-in [:runtime-artifact-plan :source]
                               dissoc :path)
                    (update-in [:runtime-artifact-plan :module]
                               dissoc :source-path))
               raw-source-target (get-in trusted-plan [:module :target])
               source-target (if (= :js raw-source-target)
                               :js-ts
                               raw-source-target)
               expected-target-eligibility
               (cond
                 (= source-target (:requested-target context))
                 (cond-> {:status :accepted
                          :source-declared-target source-target
                          :requested-target (:requested-target context)
                          :selection :source-and-request-agree}
                   (not= raw-source-target source-target)
                   (assoc :raw-source-declared-target raw-source-target
                          :source-target-alias-canonicalized? true))

                 (= :jvm source-target)
                 {:status :accepted
                  :source-declared-target :jvm
                  :requested-target (:requested-target context)
                  :selection :explicit-bootstrap-seed-target-override
                  :bootstrap-seed-target? true}

                 :else nil)]
           ;; Establish source/runtime trust before canonical hashing.  This
           ;; both rejects coherent packet-local rewrites and prevents hostile
           ;; unbounded values from reaching canonical printers.
           (if-not
            (and (= #{:kind :status :requested-target :target-eligibility
                      :plan :stage2-compiler-artifact-record :provenance
                      :stage2-plan-emitter-rule :stage2-runtime-rule
                      :closed-plan-validation-record
                      :closed-plan-execution-record
                      :closed-plan-invocation-record
                      :runtime-contract-adapter-record
                      :stage2-compiler-driver-rule
                      :stage2-compiler-driver-record
                      :stage2-runtime-execution-record :reference-output}
                    (set (keys packet)))
                 (= :gravity/target-neutral-stage2-runtime-packet
                    (:kind packet))
                 (= :complete (:status packet))
                 (= expected-target-eligibility (:target-eligibility packet))
                 (= (normalize-emitter-rule emitter-rule)
                    (normalize-emitter-rule trusted-stage2-rule))
                 (= (normalize-driver-rule driver-rule)
                    (normalize-driver-rule trusted-driver-rule))
                 (= (normalize-runtime-rule runtime-rule)
                    (normalize-runtime-rule trusted-runtime-rule))
                 (= (:source-path emitter-rule)
                    (:source-path trusted-stage2-rule)
                    (:stage2-compiler-source-path runtime-rule)
                    (:stage2-compiler-source-path trusted-runtime-rule)
                    (:driver-source-path driver-rule)
                    (:driver-source-path trusted-driver-rule))
                 (= (:runtime-source-path runtime-rule)
                    (:runtime-artifact-source-path runtime-rule)
                    (:runtime-source-path trusted-runtime-rule)
                    (:runtime-artifact-source-path trusted-runtime-rule))
                 (= driver-record trusted-driver-record)
                 (= {:actual-paths
                     {:stage2-compiler-source
                      (:stage2-compiler-source-path trusted-runtime-rule)
                      :stage2-expression-lowering-source
                      (p15-s23-stage2-compiler-artifact-source-path)
                      :stage2-runtime-artifact-source
                      (:runtime-artifact-source-path trusted-runtime-rule)}}
                    (:provenance packet))
                 (= (normalize-comparison packet-plan-base)
                    (normalize-comparison trusted-plan-base)
                    (normalize-comparison driver-plan-base))
                 (p15-s23-stage2-compiler-artifact-record-authentic?
                  (:stage2-compiler-artifact-record packet))
                 (p15-s23-stage2-compiler-artifact-record-matches-plan?
                  (:stage2-compiler-artifact-record packet) trusted-plan))
             false
             (let [derived-plan-id
                   (c4-artifact-id
                    (c-backend-canonical-value packet-plan-base))
                   derived-driver-plan-id
                   (c4-artifact-id
                    (c-backend-canonical-value driver-plan-base))
                   runtime-artifact-plan
                   (:runtime-artifact-plan runtime-rule)
                   derived-runtime-artifact-hash
                   (p15-s23-reference-runtime-hash
                    (c-backend-stage2-runtime-artifact-hash-input
                     runtime-artifact-plan
                     (:runtime-artifact-authoritative-module runtime-rule)
                     (:runtime-contract-definitions runtime-rule)
                     (:runtime-artifact-function-hashes runtime-rule)
                     (get-in runtime-rule
                             [:runtime-contract-validation-record
                              :derived-contract-facts])))
                   derived-adapter-output
                   (try
                     (p15-s23-reference-runtime-adapter-invoke
                      trusted-runtime-rule
                      p15-s23-stage2-runtime-artifact-closed-plan-function
                      [trusted-plan]
                      (p15-s23-reference-runtime-authority
                       trusted-plan trusted-plan-validation))
                     (catch Exception _ nil))
                   derived-execution (:result derived-adapter-output)
                   derived-adapter-record (:adapter-record derived-adapter-output)
                   execution-hash
                   (str "sha256:"
                        (sha256-hex
                         (pr-str (c-backend-canonical-value execution))))
                   stdout-hash
                   (str "sha256:" (sha256-hex (:stdout execution)))]
               (and (= (:requested-target context) (:requested-target packet))
                    (= (:source-path context)
                       (get-in packet-plan [:source :path]))
                    (= (:source-content-hash context)
                       (get-in packet-plan [:source :sha256]))
                    (= (:source-content-hash context) (:source-id driver-record))
                    (= (:source-path context) (:fixture driver-record))
                    (= derived-driver-plan-id (:plan-id driver-plan))
                    (= derived-driver-plan-id
                       (:stage2-plan-id driver-record))
                    (= (:stage2-runtime-execution-record packet)
                       (:stage2-runtime-execution-record
                        trusted-driver-record))
                    (= (:reference-output packet)
                       (:stage0-reference-output trusted-driver-record))
                    (= :complete (:status validation))
                    (= #{:artifact :status :entrypoint :operation-set
                         :observed-operation-set
                         :node-count :maximum-depth :maximum-nodes}
                       (set (keys validation)))
                    (= #{:artifact :entrypoint :entrypoint-result :stdout
                         :status :clojure-seed-boundary? :self-hosted?}
                       (set (keys execution)))
                    (= #{:artifact :function :function-hash
                         :runtime-artifact-hash :plan-id :execution-hash
                         :stdout-hash :invocation-count
                         :invocation-count-scope
                         :verification-replays-excluded? :status
                         :clojure-seed-boundary? :self-hosted?}
                       (set (keys invocation)))
                    (= (c-backend-canonical-value derived-validation)
                       (c-backend-canonical-value validation))
                    (= (c-backend-canonical-value derived-execution)
                       (c-backend-canonical-value execution))
                    (= (c-backend-canonical-value derived-adapter-record)
                       (c-backend-canonical-value adapter-record))
                    (= :gravity/p15-s23-reference-runtime-adapter-record
                       (:artifact adapter-record))
                    (= :complete (:status adapter-record))
                    (= (:runtime-artifact-hash runtime-rule)
                       (:runtime-artifact-hash adapter-record))
                    (= (:entrypoint packet-plan) (:entrypoint validation))
                    (= (:entrypoint packet-plan) (:entrypoint execution))
                    (= derived-plan-id (:plan-id packet-plan))
                    (= :gravity/p15-s23-runtime-closed-plan-execution-record
                       (:artifact execution))
                    (= :complete (:status execution))
                    (= :gravity/p15-s23-runtime-closed-plan-invocation-record
                       (:artifact invocation))
                    (= :complete (:status invocation))
                    (= p15-s23-stage2-runtime-artifact-expected-source-content-hash
                       (:runtime-artifact-source-content-hash runtime-rule))
                    (= p15-s23-stage2-runtime-artifact-expected-artifact-hash
                       (:runtime-artifact-hash runtime-rule))
                    (= derived-runtime-artifact-hash
                       (:runtime-artifact-hash runtime-rule))
                    (= p15-s23-stage2-runtime-artifact-expected-closed-function-hashes
                       (:runtime-artifact-closed-function-hashes runtime-rule))
                    (= p15-s23-reference-runtime-expected-function-hashes
                       (:runtime-artifact-function-hashes runtime-rule))
                    (= p15-s23-reference-runtime-expected-contract-definition-hash
                       (:runtime-contract-definition-hash runtime-rule))
                    (= p15-s23-reference-runtime-source-provider-selections
                       (:runtime-artifact-providers runtime-rule))
                    (= :complete
                       (get-in runtime-rule
                               [:runtime-contract-validation-record :status]))
                    (= (p15-s23-reference-runtime-hash
                        (get-in runtime-rule
                                [:runtime-contract-validation-record
                                 :derived-contract-facts]))
                       (:runtime-contract-derived-facts-hash runtime-rule))
                    (= p15-s23-reference-runtime-expected-derived-facts-hash
                       (:runtime-contract-derived-facts-hash runtime-rule))
                    (= (get
                        p15-s23-stage2-runtime-artifact-expected-closed-function-hashes
                        p15-s23-stage2-runtime-artifact-closed-plan-function)
                       (:runtime-artifact-closed-plan-function-hash runtime-rule))
                    (= 1 (:invocation-count invocation))
                    (= :authoritative-packet-construction
                       (:invocation-count-scope invocation))
                    (true? (:verification-replays-excluded? invocation))
                    (= p15-s23-stage2-runtime-artifact-closed-plan-function
                       (:function invocation))
                    (= (:runtime-artifact-closed-plan-function-hash runtime-rule)
                       (:function-hash invocation))
                    (= (:runtime-artifact-hash runtime-rule)
                       (:runtime-artifact-hash invocation))
                    (= (:plan-id packet-plan) (:plan-id invocation))
                    (= execution-hash (:execution-hash invocation))
                    (= stdout-hash (:stdout-hash invocation))
                    (= (:stdout execution)
                       (get-in packet [:stage2-runtime-execution-record
                                       :stdout]))
                    (= (:stdout execution) (:reference-output packet))
                    (true? (:clojure-seed-boundary? execution))
                    (false? (:self-hosted? execution))
                    (true? (:clojure-seed-boundary? invocation))
                    (false? (:self-hosted? invocation))))))))
     (catch StackOverflowError _ false)
     (catch Exception _ false))))

;; ---------------------------------------------------------------------------
;; P15-S23 closed checked-core ingress (C6-C10 bounded migration slice)
;;
;; This is deliberately not MIR yet.  It authenticates the exact target-neutral
;; stage2 packet against trusted source bytes, rebuilds the authoritative C2/C3
;; products from those bytes, and emits a content-addressed checked-core/fact
;; sidecar for the entrypoint-only closed runtime language.  Raw C2/C3 ids and
;; actual paths are provenance, never semantic identity inputs.

(def p15-s23-closed-core-max-plan-nodes 128)
(def p15-s23-closed-core-max-plan-depth 128)
(def p15-s23-closed-core-max-derived-nodes 384)
(def p15-s23-closed-core-max-source-bytes (* 1024 1024))
(def p15-s23-closed-core-max-artifact-scalar-bytes (* 8 1024 1024))
(def p15-s23-closed-core-max-integer-bits 256)
(def p15-s23-closed-core-max-serialized-values
  (* p15-s23-closed-core-max-derived-nodes
     (inc p15-s23-closed-core-max-plan-depth)
     8))

(defn p15-s23-closed-core-bounded-utf8-count
  [^String value maximum-bytes]
  (let [length (.length value)]
    (if (> length maximum-bytes)
      {:status :over-limit :bytes (inc maximum-bytes)}
      (loop [idx 0
             bytes 0]
        (if (< idx length)
          (let [code (int (.charAt value idx))]
            (cond
              (<= 0xD800 code 0xDBFF)
              (if (and (< (inc idx) length)
                       (let [low (int (.charAt value (inc idx)))]
                         (<= 0xDC00 low 0xDFFF)))
                (let [next-bytes (+ bytes 4)]
                  (if (> next-bytes maximum-bytes)
                    {:status :over-limit :bytes next-bytes}
                    (recur (+ idx 2) next-bytes)))
                {:status :invalid-surrogate :index idx :bytes bytes})

              (<= 0xDC00 code 0xDFFF)
              {:status :invalid-surrogate :index idx :bytes bytes}

              :else
              (let [width (cond
                            (<= code 0x7F) 1
                            (<= code 0x7FF) 2
                            :else 3)
                    next-bytes (+ bytes width)]
                (if (> next-bytes maximum-bytes)
                  {:status :over-limit :bytes next-bytes}
                  (recur (inc idx) next-bytes)))))
          {:status :valid :bytes bytes})))))

(def p15-s23-closed-core-allowed-operations
  #{:literal :quote :local :do :if :let})

(def p15-s23-closed-core-recognized-plan-operations
  (conj p15-s23-closed-core-allowed-operations :builtin-call :println))

(def p15-s23-closed-core-recognized-core-operations
  (conj p15-s23-closed-core-allowed-operations :str :println))

(def p15-s23-closed-core-allowed-safety-outcomes
  #{:proven-safe :runtime-checked})

(def p15-s23-closed-core-known-effects
  #{:io/write :memory/allocate})

(def p15-s23-closed-core-known-capabilities
  #{:io/stdout :memory/allocator})

(declare p15-s23-closed-core-fail!)

(def p15-s23-closed-core-registered-effects
  ;; Registration and inference are separate.  The global L6 registry is the
  ;; recognition boundary, with the canon-confirmed legacy-only panic label
  ;; removed; this slice infers only the two labels above.
  (disj (set (keys effect-registry)) :panic/fail))

(def p15-s23-closed-core-registered-capabilities
  (set/union (set (keys provider-specs))
             (set (vals c8-effect-capability))
             p15-s23-closed-core-known-capabilities))

(defn p15-s23-closed-core-observed-plan-operations
  "Return the operations reachable in one concrete closed plan.

  This is deliberately distinct from the generic runtime validator's
  supported-operation inventory: an accepted pure artifact may use the
  runtime only as a seed-comparison oracle and must not imply that latent
  effectful executor branches conform to C8."
  [plan]
  (loop [pending
         (vec (mapcat :instructions (vals (:functions plan))))
         operations #{}
         visited 0]
    (if-let [instruction (peek pending)]
      (let [pending (pop pending)
            visited (inc visited)]
        (when-not (and (map? instruction)
                       (keyword? (:op instruction))
                       (<= visited p15-s23-closed-core-max-plan-nodes))
          (p15-s23-closed-core-fail!
           "C6-VERIFY" (or (get-in plan [:source :path]) "<closed-plan>")
           instruction
           {:missing-fact :bounded-concrete-plan-operation-inventory
            :observed-plan-nodes visited
            :maximum-plan-nodes p15-s23-closed-core-max-plan-nodes}))
        (recur (into pending (c-backend-instruction-children instruction))
               (conj operations (:op instruction))
               visited))
      operations)))

(defn p15-s23-closed-core-preflight-effect-requirements
  "Infer the recognized C8 residual requirements from a concrete plan
  without executing it or loading the runtime module."
  [plan]
  (loop [pending (vec (mapcat :instructions (vals (:functions plan))))
         effects #{}
         capabilities #{}
         visited 0]
    (if-let [instruction (peek pending)]
      (let [pending (pop pending)
            visited (inc visited)
            operation (:op instruction)
            str-call? (and (= :builtin-call operation)
                           (= 'str (:function instruction)))
            effects (cond-> effects
                      str-call? (conj :memory/allocate)
                      (= :println operation) (conj :io/write))
            capabilities (cond-> capabilities
                           str-call? (conj :memory/allocator)
                           (= :println operation) (conj :io/stdout))]
        (when-not (and (map? instruction)
                       (keyword? operation)
                       (<= visited p15-s23-closed-core-max-plan-nodes))
          (p15-s23-closed-core-fail!
           "C6-VERIFY" (or (get-in plan [:source :path]) "<closed-plan>")
           instruction
           {:missing-fact :bounded-preflight-effect-requirement-inventory
            :observed-plan-nodes visited
            :maximum-plan-nodes p15-s23-closed-core-max-plan-nodes}))
        (recur (into pending (c-backend-instruction-children instruction))
               effects capabilities visited))
      {:required-effects effects
       :required-capabilities capabilities})))

(defn p15-s23-closed-core-scope-contract
  ([]
  {:accepted-pure-operations
   (vec (sort p15-s23-closed-core-allowed-operations))
   :structural-node-kinds [:binding :function :truthiness]
   :recognized-but-rejected-pending-runtime-module [:println :str]
   :module {:profile :hosted
            :safety :safe
            :source-target :jvm
            :top-level-shape [:ns :single-zero-arity-main]
            :exports [#{} #{'main}]
            :requires :empty
            :imports :empty
            :providers :empty
            :metadata {}
            :doc nil}
   :literal-and-quote-types
   [:nil :string :bool :integer :char :keyword :symbol]
   :required-effects #{}
   :required-capabilities #{}
   :recognized-effectful-residual-labels
   p15-s23-closed-core-known-effects
   :recognized-but-uncredited-capabilities
   p15-s23-closed-core-known-capabilities
   :bounds {:maximum-plan-nodes p15-s23-closed-core-max-plan-nodes
            :maximum-plan-depth p15-s23-closed-core-max-plan-depth
            :maximum-derived-nodes p15-s23-closed-core-max-derived-nodes
            :maximum-source-bytes p15-s23-closed-core-max-source-bytes
            :maximum-artifact-scalar-bytes
            p15-s23-closed-core-max-artifact-scalar-bytes
            :maximum-integer-bits p15-s23-closed-core-max-integer-bits
            :maximum-serialized-values
            p15-s23-closed-core-max-serialized-values}
   :entrypoint-only? true
   :complete-for-pure-closed-slice? true
   :whole-language? false
   :mir-derived? false
   :c11-claimed? false
   :target-lowering-credit? false
   :release-credit? false
   :self-hosted? false})
  ([mode]
   (p15-s23-closed-core-scope-contract
    mode {:required-effects #{} :required-capabilities #{}}))
  ([mode {:keys [required-effects required-capabilities]}]
   (if (= :effectful-reference mode)
     (-> (p15-s23-closed-core-scope-contract)
         (dissoc :recognized-but-uncredited-capabilities)
         (assoc :recognized-but-rejected-pending-runtime-module []
                :required-effects required-effects
                :required-capabilities required-capabilities
                :accepted-reference-effects
                p15-s23-closed-core-known-effects
                :accepted-reference-capabilities
                p15-s23-closed-core-known-capabilities
                :complete-for-pure-closed-slice? false
                :accepted-reference-operations [:println :str]
                :reference-interpreter? true
                :single-authoritative-construction-invocation? true
                :verification-replay-is-separate-runtime-evaluation? true
                :complete-for-pinned-r1-r11-verification-replay-slice? true
                :r1-whole-conformance? false
                :r11-whole-conformance? false
                :deployment-runtime? false
                :live-external-io? false))
     (p15-s23-closed-core-scope-contract))))

(defn p15-s23-closed-core-executable-form-records
  "Return the single checked-core C2 executable preorder.

  Function bodies and each operation's evaluated children are visited
  left-to-right.  Quote itself is executable but its payload is data, so quote
  records are terminal."
  [form-tree top-level-form-ids]
  (let [limit (inc p15-s23-closed-core-max-plan-nodes)
        form-by-id (into {} (map (juxt :form-id identity)) form-tree)
        function-root (get form-by-id (second top-level-form-ids))
        body-form-ids
        (if (and (seq? (:value function-root))
                 (= 'defn (first (:value function-root))))
          (vec (take limit (drop 3 (:children function-root))))
          [])]
    (loop [pending (vec (reverse body-form-ids))
           ordered []
           seen #{}]
      (if-let [form-id (peek pending)]
        (let [pending (pop pending)
              record (get form-by-id form-id)]
          (if (or (nil? record) (contains? seen form-id))
            (recur pending ordered seen)
            (let [value (:value record)
                  operator (when (seq? value) (first value))
                  child-ids
                  (if (seq? value)
                    (case operator
                      quote []
                      (do if str println) (rest (:children record))
                      let
                      (let [binding-record
                            (get form-by-id (second (:children record)))]
                        (if (vector? (:value binding-record))
                          (concat
                           (take-nth 2 (rest (:children binding-record)))
                           (drop 2 (:children record)))
                          []))
                      [])
                    [])
                  next-ordered (conj ordered record)
                  remaining-capacity (- limit (count next-ordered))]
              (if (zero? remaining-capacity)
                next-ordered
                (recur
                 (into pending
                       (reverse (vec (take remaining-capacity child-ids))))
                 next-ordered
                 (conj seen form-id))))))
        ordered))))

(defn p15-s23-closed-core-source-surface-validation
  [forms executable-form-records]
  (let [namespace-form (first forms)
        function-form (second forms)
        top-level-valid?
        (and (= 2 (count forms))
             (seq? namespace-form)
             (= 'ns (first namespace-form))
             (seq? function-form)
             (= 'defn (first function-form))
             (= 'main (second function-form))
             (vector? (nth function-form 2 nil))
             (empty? (nth function-form 2 nil)))]
    (if-not top-level-valid?
      {:status :unsupported
       :missing-fact :exact-ns-and-single-zero-arity-main-source-shape}
      (loop [records executable-form-records
             visited 0]
        (if-let [record (first records)]
          (let [form (:value record)
                operator (when (seq? form) (first form))
                visited (inc visited)
                base {:operator operator
                      :observed-form form
                      :offending-form-id (:form-id record)}]
            (cond
              (> visited p15-s23-closed-core-max-plan-nodes)
              {:status :over-limit
               :missing-fact :bounded-pure-source-form-surface
               :observed-source-forms visited
               :offending-form-id (:form-id record)}

              (or (nil? form) (string? form) (boolean? form)
                  (number? form) (char? form) (keyword? form)
                  (symbol? form)
                  (and (map? form)
                       (= :gravity/deferred-ratio-literal
                          (:artifact form))))
              (recur (next records) visited)

              (seq? form)
              (cond
                (= 'quote operator)
                (if (= 2 (count form))
                  (recur (next records) visited)
                  (merge base
                         {:status :unsupported
                          :missing-fact :pure-quote-source-arity
                          :observed-arity (dec (count form))}))

                (= 'let operator)
                (let [bindings (second form)]
                  (if (and (vector? bindings)
                           (even? (count bindings))
                           (every? symbol? (take-nth 2 bindings))
                           (= (count (take-nth 2 bindings))
                              (count (set (take-nth 2 bindings)))))
                    (recur (next records) visited)
                    (merge base
                           {:status :unsupported
                            :missing-fact :pure-let-binding-source-shape})))

                (contains? #{'do 'if 'str 'println} operator)
                (recur (next records) visited)

                :else
                (merge base
                       {:status :unsupported
                        :missing-fact :pure-closed-source-operation}))

              :else
              (merge base
                     {:status :unsupported
                      :missing-fact :pure-closed-source-expression-kind
                      :observed-class (some-> form class .getName)})))
          {:status :passed :observed-source-forms visited})))))

