           (<= (.length ^String source-path) 4096)
           (try
             (= :valid
                (:status
                 (p15-s23-closed-core-bounded-utf8-count
                  source-path 4096)))
             (catch InterruptedException interrupted
               (.interrupt (Thread/currentThread))
               (throw interrupted))
             (catch Exception _ false)))
    source-path
    "<c11-mir>"))

