  (let [request (:request lowering)]
    {:artifact :gravity/b1-verified-backend-input-packet
     :schema-version 1 :status :accepted-for-bounded-llvm
     :input (:input request)
     :profile (:profile-contract request)
     :target (:target request)
     :source-target-selection (:source-target-selection request)
     :abi (:abi request) :runtime (:runtime request)
     :providers (:providers request)
     :effects (:effects request) :capabilities (:capabilities request)
     :safety (:safety request) :proofs (:proofs request)
     :proof-to-target-metadata (:proof-to-target-metadata request)
     :source-map (:source-map request)
     :dependencies (:dependency-provenance request)
     :contract-bindings (:contract-bindings request)
     :c14-eligibility (:eligibility lowering)
     :eligibility
     {:artifact :gravity/b1-backend-eligibility-report
      :backend :gravity.backend/llvm
      :input-artifact (get-in request [:input :artifact-id])
      :profile (:profile request) :target (:target request)
      :accepted? true :rejections [] :fallbacks []
      :missing-evidence [] :unsupported-operations [] :remediation []
      :checks [:profile-backend-compatibility :target-feature-support
               :runtime-availability-or-no-runtime-proof
               :abi-representability :layout-representability
               :provider-availability :effect-preservation
               :capability-preservation :safety-bundle-completeness
               :proof-validity-for-target-assumptions
               :source-debug-map-preservation]}
     :backend-manifest backend-manifest
     :unsupported-feature-report
     {:status :bounded-surface-only
      :policy (get-in request [:unsupported-feature-report :policy])
      :diagnostic "B1-UNSUPPORTED" :fallback-status :rejected}
     :diagnostics [] :semantic-authority :gravity-source
     :execution-tcb :clojure-stage0-rule-runner
     :clojure-seed-boundary? true :self-hosted? false}))

(defn- p15-s23-b1-build!
  [candidate source-path c11-artifact c13-record c14-record binding]
  (let [manifest (p15-s23-b1-backend-manifest c14-record)
        raw
        (p15-s23-c13-c14-b1-invoke!
         candidate source-path binding p15-s23-b1-builder-function
         [c14-record manifest] "B1-INPUT")
        expected (p15-s23-b1-expected-record c14-record manifest)]
    (p15-s23-c11-mir-require-strict-structure!
     source-path expected raw :independent-b1-packet-reconstruction)
    (when-not
     (and (= expected raw)
          (= (:artifact-id c14-record)
             (get-in raw [:backend-manifest :c14-artifact-id]))
          (= (get-in c14-record [:request :request-id])
             (get-in raw [:backend-manifest :c14-request-id]))
          (= (:artifact-id c13-record)
             (get-in raw [:input :artifact-id])))
      (p15-s23-b3-llvm-fail!
       "B1-METADATA" source-path raw
       {:missing-fact :exact-c14-bound-b1-reconstruction}))
    (p15-s23-c13-c14-b1-seal-stage
     :gravity/b1-verified-backend-input-packet raw
     (p15-s23-c13-c14-b1-source-rule
      :gravity.backend/b1-backend-interface binding
      p15-s23-b1-builder-function)
     {:source source-path
      :c11-source (get-in c11-artifact
                          [:provenance :actual-paths :c11-source])
      :c13-source (get-in c13-record
                          [:actual-path-provenance :c13-source])
      :c14-source (get-in c14-record
                          [:actual-path-provenance :c14-source])
      :b1-source (:source-path binding)})))

(declare p15-s23-b1-c-builder-function)

(defn p15-s23-b1-c-backend-manifest
  [c14-record]
  {:artifact :gravity/backend-manifest
   :backend :gravity.backend/c
   :version :bounded-authenticated-c17-v1
   :accepts [:gravity/mir]
   :emits [:c-source :c-header]
   :requires [:profile-manifest :target-manifest :c-dialect-selection
              :abi-policy :runtime-provider-selection :effect-summary
              :capability-proof-summary :safety-bundle :proof-table
              :source-map :dependency-graph]
   :supports-profiles [:hosted]
   :rejects [:unverified-ir :unsupported-op :missing-proof
             :implicit-ub :ambient-capability :profile-violation
             :dialect-mismatch]
   :dialect :c17
   :c14-request-id (get-in c14-record [:request :request-id])
   :c14-artifact-id (:artifact-id c14-record)})

(defn p15-s23-b1-c-expected-record
  [lowering backend-manifest]
  (let [request (:request lowering)]
    {:artifact :gravity/b1-verified-backend-input-packet
     :schema-version 1 :status :accepted-for-bounded-c
     :input (:input request)
     :bounded-lowering-payload (:bounded-lowering-payload lowering)
     :profile (:profile-contract request)
     :target (:target request)
     :source-target-selection (:source-target-selection request)
     :dialect :c17
     :abi (:abi request) :runtime (:runtime request)
     :providers (:providers request)
     :effects (:effects request) :capabilities (:capabilities request)
     :safety (:safety request) :proofs (:proofs request)
     :proof-to-target-metadata (:proof-to-target-metadata request)
     :source-map (:source-map request)
     :dependencies (:dependency-provenance request)
     :contract-bindings (:contract-bindings request)
     :c14-eligibility (:eligibility lowering)
     :eligibility
     {:artifact :gravity/b1-backend-eligibility-report
      :backend :gravity.backend/c
      :input-artifact (get-in request [:input :artifact-id])
      :profile (:profile request) :target (:target request)
      :accepted? true :rejections [] :fallbacks []
      :missing-evidence [] :unsupported-operations [] :remediation []
      :checks [:profile-backend-compatibility :target-feature-support
               :runtime-availability-or-no-runtime-proof
               :abi-representability :layout-representability
               :provider-availability :effect-preservation
               :capability-preservation :safety-bundle-completeness
               :proof-validity-for-target-assumptions
               :source-debug-map-preservation :c17-dialect-closure]}
     :backend-manifest backend-manifest
     :unsupported-feature-report
     {:status :bounded-surface-only
      :policy (get-in request [:unsupported-feature-report :policy])
      :diagnostic "B1-UNSUPPORTED" :fallback-status :rejected}
     :diagnostics [] :semantic-authority :gravity-source
     :execution-tcb :clojure-stage0-rule-runner
     :clojure-seed-boundary? true
     :whole-b1? false :whole-b2? false :self-hosted? false}))

(defn- p15-s23-b1-c-build!
  [candidate source-path c11-artifact c13-record c14-record binding]
  (let [manifest (p15-s23-b1-c-backend-manifest c14-record)
        raw
        (p15-s23-c13-c14-b1-invoke!
         candidate source-path binding p15-s23-b1-c-builder-function
         [c14-record manifest] "B1-INPUT")
        expected (p15-s23-b1-c-expected-record c14-record manifest)]
    (p15-s23-c11-mir-require-strict-structure!
     source-path expected raw :independent-b1-c-packet-reconstruction)
    (when-not
     (and (= expected raw)
          (= (:artifact-id c14-record)
             (get-in raw [:backend-manifest :c14-artifact-id]))
          (= (get-in c14-record [:request :request-id])
             (get-in raw [:backend-manifest :c14-request-id]))
          (= (:artifact-id c13-record)
             (get-in raw [:input :artifact-id])
             (get-in raw [:bounded-lowering-payload :c13-artifact-id]))
          (= (:artifact-id c11-artifact)
             (get-in raw [:input :c11-artifact-id])
             (get-in raw [:bounded-lowering-payload :c11-artifact-id]))
          (= (:optimized-mir c13-record)
             (get-in raw [:bounded-lowering-payload :mir])))
      (p15-s23-b3-llvm-fail!
       "B1-METADATA" source-path raw
       {:missing-fact :exact-c14-bound-b1-c-reconstruction}))
    (p15-s23-c13-c14-b1-seal-stage
     :gravity/b1-verified-backend-input-packet raw
     (p15-s23-c13-c14-b1-source-rule
      :gravity.backend/b1-backend-interface binding
      p15-s23-b1-c-builder-function)
     {:source source-path
      :c11-source (get-in c11-artifact
                          [:provenance :actual-paths :c11-source])
      :c13-source (get-in c13-record
                          [:actual-path-provenance :c13-source])
      :c14-source (get-in c14-record
                          [:actual-path-provenance :c14-source])
      :b1-source (:source-path binding)})))

(defn- p15-s23-c13-c14-b1-final-record
  [source-path c11-artifact checked-core c11-report bindings
   c13-record c14-record b1-record]
  (let [actual-path-provenance
        {:source source-path
         :c11-source (get-in c11-artifact
                             [:provenance :actual-paths :c11-source])
         :c13-source (get-in bindings [:c13 :source-path])
         :c14-source (get-in bindings [:c14 :source-path])
         :b1-source (get-in bindings [:b1 :source-path])}
        base
        {:kind :gravity/p15-s23-c13-c14-b1-authenticated-packet
         :schema-version 1 :status :accepted-for-bounded-llvm
         :c11
         {:artifact-id (:artifact-id c11-artifact)
          :mir-id (:mir-id c11-artifact)
          :module-id (get-in c11-artifact [:mir-module :module-id])
          :checked-core-artifact-id (:artifact-id checked-core)
          :verifier-record
          (p15-s23-b3-llvm-c11-verifier-record c11-report)}
         :c13 c13-record :c14 c14-record :b1 b1-record
         :optimized-mir (:optimized-mir c13-record)
         :actual-path-provenance actual-path-provenance
         :diagnostics []
         :semantic-authority :gravity-source
         :verification-tcb :clojure-stage0-independent-reconstruction
         :scope
         {:bounded-llvm? true :whole-c13? false :whole-c14? false
          :whole-b1? false :whole-b3? false :public? false
          :release? false :self-hosted? false}}
        semantic-id (p15-s23-c13-c14-b1-semantic-id base)
        artifact-id
        (p15-s23-c11-mir-digest
         {:kind (:kind base) :schema-version 1 :semantic-id semantic-id})]
    (assoc base :semantic-id semantic-id :artifact-id artifact-id
           :actual-path-binding-id
           (p15-s23-c13-c14-b1-actual-path-binding-id
            semantic-id actual-path-provenance))))

(defn- p15-s23-c13-c14-b1-build-internal!
  [candidate c11-artifact checked-core context]
  (let [source-path (p15-s23-c11-ingress-source-path context)
        sorted-policy (p15-s23-c11-carrier-sorted-policy checked-core)]
    (p15-s23-c13-c14-b1-require-trusted!
     source-path :c13-c14-b1-c11-ingress c11-artifact sorted-policy)
    (let [c11-report
          (p15-s23-stage2-c11-mir-verification-report
           c11-artifact checked-core context)]
      (when-not (= :passed (:status c11-report))
        (p15-s23-b3-llvm-fail!
         "B1-INPUT" source-path c11-artifact
         {:missing-fact :fresh-c11-before-c13-c14-b1}))
      (let [bindings
            (p15-s23-c13-c14-b1-source-bindings! candidate source-path)
            c13-record
            (p15-s23-c13-build!
             candidate source-path c11-artifact c11-report (:c13 bindings))
            c14-record
            (p15-s23-c14-build!
             candidate source-path c11-artifact checked-core c11-report
             c13-record (:c14 bindings))
            ;; C14 is the first owner of target-surface eligibility.  The
            ;; backend mirror runs only after the Gravity C14 record accepts
            ;; and before B1 or any backend/tool effect.
            _ (p15-s23-b3-llvm-preflight! c11-artifact)
            b1-record
            (p15-s23-b1-build!
             candidate source-path c11-artifact c13-record c14-record
             (:b1 bindings))]
        (p15-s23-c13-c14-b1-final-record
         source-path c11-artifact checked-core c11-report bindings
         c13-record c14-record b1-record)))))

(defn p15-s23-stage2-c13-c14-b1-packet-from-c11!
  [c11-artifact checked-core context]
  (let [source-path (p15-s23-c11-ingress-source-path context)]
    (try
      (p15-s23-c13-c14-b1-build-internal!
       p15-s23-c13-c14-b1-authority-token
       c11-artifact checked-core context)
      (catch InterruptedException interrupted
        (.interrupt (Thread/currentThread))
        (throw interrupted))
      (catch StackOverflowError _
        (p15-s23-b3-llvm-fail!
         "B1-INPUT" source-path {}
         {:missing-fact :bounded-hostile-c13-c14-b1-host-stack}))
      (catch AssertionError error
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-c13-c14-b1-assertion error))
      (catch LinkageError error
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-c13-c14-b1-linkage error))
      (catch clojure.lang.ExceptionInfo exception
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-c13-c14-b1-diagnostic exception))
      (catch Exception exception
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-c13-c14-b1-host-failure exception)))))

(def p15-s23-c13-c14-b1-final-packet-keys
  #{:kind :schema-version :status :c11 :c13 :c14 :b1 :optimized-mir
    :actual-path-provenance :diagnostics :semantic-authority
    :verification-tcb :scope :semantic-id :artifact-id
    :actual-path-binding-id})

(def p15-s23-c13-c14-b1-final-packet-scope
  {:bounded-llvm? true :whole-c13? false :whole-c14? false
   :whole-b1? false :whole-b3? false :public? false
   :release? false :self-hosted? false})

(defn- p15-s23-c13-c14-b1-verification-preflight!
  [source-path packet]
  ;; Exact carrier classes are established before the general bounded-value
  ;; walk so no custom comparator, lazy sequence, hashCode, or equals method
  ;; can execute at this untrusted public boundary.
  (p15-s23-c13-c14-b1-require-trusted!
   source-path :c13-c14-b1-final-packet packet :default-only)
  ;; The trusted-carrier walk bounds shape only.  Apply the shared C11 scalar,
  ;; magnitude, collection-width, and total-byte limits before any fresh C11
  ;; replay or Gravity source-plan reconstruction.
  (p15-s23-c11-mir-bounded-value!
   source-path :c13-c14-b1-final-packet packet
   p15-s23-c13-c14-b1-max-carrier-nodes
   p15-s23-c13-c14-b1-max-carrier-depth)
  (let [top-level-class (when (some? packet) (.getName (class packet)))]
    (when-not
     (and (map? packet)
          (contains? p15-s23-trusted-carrier-map-classes top-level-class)
          (= p15-s23-c13-c14-b1-final-packet-keys
             (set (keys packet)))
          (= :gravity/p15-s23-c13-c14-b1-authenticated-packet
             (:kind packet))
          (= 1 (:schema-version packet))
          (= :accepted-for-bounded-llvm (:status packet))
          (= :gravity-source (:semantic-authority packet))
          (= :clojure-stage0-independent-reconstruction
             (:verification-tcb packet))
          (= [] (:diagnostics packet))
          (= p15-s23-c13-c14-b1-final-packet-scope (:scope packet))
          (every? map?
                  ((juxt :c11 :c13 :c14 :b1 :optimized-mir
                         :actual-path-provenance)
                   packet))
          (every? string?
                  ((juxt :semantic-id :artifact-id :actual-path-binding-id)
                   packet)))
      (p15-s23-b3-llvm-fail!
       "B1-METADATA" source-path packet
       {:missing-fact :bounded-c13-c14-b1-final-envelope})))
  (let [semantic-id (p15-s23-c13-c14-b1-semantic-id packet)
        artifact-id
        (p15-s23-c11-mir-digest
         {:kind (:kind packet) :schema-version 1 :semantic-id semantic-id})
        actual-path-binding-id
        (p15-s23-c13-c14-b1-actual-path-binding-id
         semantic-id (:actual-path-provenance packet))]
    (when-not
     (= [semantic-id artifact-id actual-path-binding-id]
        ((juxt :semantic-id :artifact-id :actual-path-binding-id) packet))
      (p15-s23-b3-llvm-fail!
       "B1-METADATA" source-path packet
       {:missing-fact :recomputable-c13-c14-b1-final-identities})))
  :passed)

(defn p15-s23-stage2-c13-c14-b1-verification-report
  [packet checked-core context]
  (let [source-path (p15-s23-c11-ingress-source-path context)]
    (try
      (p15-s23-c13-c14-b1-verification-preflight! source-path packet)
      (let [fresh-c11 (p15-s23-stage2-c11-mir-artifact checked-core context)
            expected
            (p15-s23-c13-c14-b1-build-internal!
             p15-s23-c13-c14-b1-authority-token
             fresh-c11 checked-core context)]
        (p15-s23-c11-mir-require-strict-structure!
         source-path expected packet
         :contextual-fresh-c13-c14-b1-reconstruction)
        (when-not
         (and (= expected packet)
              (= (:semantic-id packet)
                 (p15-s23-c13-c14-b1-semantic-id packet))
              (= (:artifact-id packet)
                 (p15-s23-c11-mir-digest
                  {:kind (:kind packet) :schema-version 1
                   :semantic-id (:semantic-id packet)}))
              (= (:actual-path-binding-id packet)
                 (p15-s23-c13-c14-b1-actual-path-binding-id
                  (:semantic-id packet) (:actual-path-provenance packet))))
          (p15-s23-b3-llvm-fail!
           "B1-METADATA" source-path packet
           {:missing-fact :fresh-context-bound-c13-c14-b1-packet}))
        (p15-s23-c13-c14-b1-contextual-report-record packet))
      (catch InterruptedException interrupted
        (.interrupt (Thread/currentThread))
        (throw interrupted))
      (catch StackOverflowError _
        (p15-s23-b3-llvm-fail!
         "B1-INPUT" source-path {}
         {:missing-fact :bounded-hostile-c13-c14-b1-verifier-stack}))
      (catch AssertionError error
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-c13-c14-b1-verifier-assertion error))
      (catch LinkageError error
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-c13-c14-b1-verifier-linkage error))
      (catch clojure.lang.ExceptionInfo exception
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-c13-c14-b1-verifier-diagnostic exception))
      (catch Exception exception
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-c13-c14-b1-verifier-failure exception)))))

(defn p15-s23-stage2-c13-c14-b1-verify!
  [packet checked-core context]
  (let [report
        (p15-s23-stage2-c13-c14-b1-verification-report
         packet checked-core context)]
    (when-not (= :passed (:status report))
      (p15-s23-b3-llvm-fail!
       "B1-INPUT" (p15-s23-c11-ingress-source-path context) packet
       {:missing-fact :c13-c14-b1-verification-status}))
    :passed))

(defn p15-s23-stage2-c13-c14-b1-authentic?
  ([packet] false)
  ([packet checked-core context]
   (try
     (= :passed
        (p15-s23-stage2-c13-c14-b1-verify!
         packet checked-core context))
     (catch InterruptedException interrupted
       (.interrupt (Thread/currentThread)) (throw interrupted))
     (catch StackOverflowError _ false)
     (catch AssertionError _ false)
     (catch LinkageError _ false)
     (catch Exception _ false))))

(defn- p15-s23-sh02-final-preflight!
  [source-path artifact]
  ;; Establish exact built-in carrier classes before equality, hashing, or
  ;; contextual source replay. Request vectors receive their explicit 2,048
  ;; entry exception in the per-stage canonical carrier validation below.
  (p15-s23-sh02-require-bounded-carrier!
   source-path :sh02-final-artifact artifact)
  (p15-s23-c11-mir-bounded-value!
   source-path :sh02-final-artifact
   artifact
   (:maximum-carrier-nodes p15-s23-sh02-authenticated-envelope-bounds)
   (:maximum-carrier-depth p15-s23-sh02-authenticated-envelope-bounds))
  (let [envelopes (:envelopes artifact)
        source-rule (:source-rule artifact)
        actual-paths (:actual-path-provenance artifact)]
    (when-not
     (and (map? artifact)
          (= p15-s23-sh02-final-artifact-keys
             (set (keys artifact)))
          (= :gravity/sh02-reusable-authenticated-envelopes
             (:artifact artifact))
          (= 1 (:schema-version artifact))
          (= :accepted (:status artifact))
          (= :gravity-source (:semantic-authority artifact))
          (= [] (:diagnostics artifact))
          (= p15-s23-sh02-final-scope (:scope artifact))
          (map? (:host-tcb artifact))
          (map? source-rule)
          (= :gravity/pinned-authenticated-envelope-source-rule
             (:artifact source-rule))
          (= p15-s23-sh02-expected-source-content-hash
             (:source-content-hash source-rule))
          (= p15-s23-sh02-source-byte-count
             (:source-byte-count source-rule))
          (= p15-s23-sh02-expected-plan-semantic-hash
             (:plan-semantic-hash source-rule))
          (= p15-s23-sh02-expected-functions-semantic-hash
             (:functions-semantic-hash source-rule))
          (= p15-s23-sh02-builder-function
             (:builder-function source-rule))
          (= p15-s23-sh02-expected-builder-semantic-hash
             (:builder-semantic-hash source-rule))
          (= p15-s23-sh02-verifier-function
             (:verifier-function source-rule))
          (= p15-s23-sh02-expected-verifier-semantic-hash
             (:verifier-semantic-hash source-rule))
          (map? (:function-shapes source-rule))
          (= p15-s23-sh02-expected-function-count
             (count (:function-shapes source-rule)))
          (map? envelopes)
          (= #{:c13 :b1} (set (keys envelopes)))
          (map? actual-paths)
          (= #{:source :workspace-root :invocation-root
               :envelope-source :c13-source :b1-source}
             (set (keys actual-paths)))
          (every? #(and (string? %) (not (empty? %)))
                  (vals actual-paths))
          (every? p15-s23-sh02-sha256-id?
                  ((juxt :packet-id :packet-semantic-id
                         :semantic-id :artifact-id
                         :actual-path-binding-id)
                   artifact)))
      (p15-s23-sh02-fail!
       source-path artifact :exact-sh02-final-envelope
       {:observed-keys (when (map? artifact)
                         (set (keys artifact)))}))
    (doseq [stage [:c13 :b1]]
      (let [envelope (get envelopes stage)
            replay (:gravity-template-replay envelope)]
        (when-not
         (and (map? envelope)
              (= p15-s23-sh02-stage-envelope-keys
                 (set (keys envelope)))
              (= :gravity/sh02-stage-authenticated-envelope
                 (:artifact envelope))
              (= 1 (:schema-version envelope))
              (= :accepted (:status envelope))
              (= stage (:stage envelope))
              (map? (:sealed-artifact envelope))
              (vector? (:identity-checks envelope))
              (integer? (:request-count envelope))
              (pos? (:request-count envelope))
              (= (:request-count envelope)
                 (:request-count replay))
              (every? p15-s23-sh02-sha256-id?
                      ((juxt :semantic-envelope-id
                             :provenance-binding-id :request-graph-id)
                       envelope))
              (= [] (:diagnostics envelope))
              (= :gravity-source (:semantic-authority envelope))
              (map? (:host-tcb envelope))
              (false? (:self-hosted? envelope))
              (= source-rule (:source-rule envelope))
              (map? replay)
              (= p15-s23-sh02-template-replay-summary-keys
                 (set (keys replay)))
              (= :template-replay-passed (:status replay))
              (= :pending-host-resolution
                 (:identity-enforcement replay))
              (false? (:eligible-for-contextual-acceptance? replay))
              (= :gravity-source (:semantic-authority replay))
              (= p15-s23-sh02-verifier-checks (:checks replay))
              (= [] (:diagnostics replay)))
          (p15-s23-sh02-fail!
           source-path envelope :exact-sh02-stage-envelope-preflight
           {:stage stage}))
        ;; The public carrier stores only the resolved semantic envelope and
        ;; the leaf replay summary. The request graph is reconstructed from
        ;; current inputs before strict equality, never interpreted from the
        ;; candidate carrier.
        ))
    (let [semantic-id (p15-s23-sh02-final-semantic-id artifact)
          artifact-id (p15-s23-sh02-final-artifact-id semantic-id)
          path-binding-id
          (p15-s23-sh02-final-actual-path-binding-id
           semantic-id actual-paths)]
      (when-not
       (= [semantic-id artifact-id path-binding-id]
          ((juxt :semantic-id :artifact-id :actual-path-binding-id)
           artifact))
        (p15-s23-sh02-fail!
         source-path artifact :recomputable-sh02-final-identities {})))
    :passed))

(defn p15-s23-stage2-sh02-authenticated-envelope-artifact
  [packet checked-core context]
  (let [source-path (p15-s23-c11-ingress-source-path context)]
    (try
      (p15-s23-sh02-build-internal!
       p15-s23-c13-c14-b1-authority-token
       packet checked-core context)
      (catch InterruptedException interrupted
        (.interrupt (Thread/currentThread))
        (throw interrupted))
      (catch StackOverflowError _
        (p15-s23-sh02-fail!
         source-path {} :bounded-sh02-constructor-host-stack {}))
      (catch AssertionError error
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-sh02-constructor-assertion error))
      (catch LinkageError error
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-sh02-constructor-linkage error))
      (catch clojure.lang.ExceptionInfo exception
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-sh02-constructor-diagnostic exception))
      (catch Exception exception
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-sh02-constructor-host-failure exception)))))

(defn p15-s23-stage2-sh02-authenticated-envelope-verification-report
  [artifact checked-core context]
  (let [source-path (p15-s23-c11-ingress-source-path context)]
    (try
      (p15-s23-sh02-final-preflight! source-path artifact)
      (let [fresh-c11
            (p15-s23-stage2-c11-mir-artifact checked-core context)
            fresh-packet
            (p15-s23-c13-c14-b1-build-internal!
             p15-s23-c13-c14-b1-authority-token
             fresh-c11 checked-core context)
            expected
            (p15-s23-sh02-build-verified-packet-internal!
             p15-s23-c13-c14-b1-authority-token
             fresh-packet context)]
        (p15-s23-c11-mir-require-strict-structure!
         source-path expected artifact
         :fresh-contextual-sh02-envelope-reconstruction)
        (when-not (= expected artifact)
          (p15-s23-sh02-fail!
           source-path artifact :fresh-context-bound-sh02-envelope {}))
        (let [base
              {:artifact :gravity/sh02-contextual-verification-report
               :schema-version 1 :status :passed
               :artifact-id (:artifact-id artifact)
               :semantic-id (:semantic-id artifact)
               :packet-id (:packet-id artifact)
               :fresh-c11 :passed
               :fresh-c13 :passed
               :fresh-c14 :passed
               :fresh-b1 :passed
               :gravity-envelope-template-replay
               :template-replay-passed
               :host-digest-resolution :passed
               :identity-subject-equality :passed
               :fresh-envelope-reconstruction :passed
               :stages
               (into
                (sorted-map)
                (map
                 (fn [[stage envelope]]
                   [stage
                    {:semantic-envelope-id
                     (:semantic-envelope-id envelope)
                     :provenance-binding-id
                     (:provenance-binding-id envelope)
                     :identity-check-count
                     (count (:identity-checks envelope))
                     :request-count (:request-count envelope)}]))
                (:envelopes artifact))
               :external-tool-execution :not-performed
               :clojure-seed-boundary? true
               :self-hosted? false}]
          (assoc
           base :report-id
           (p15-s23-c6c10-canonical-digest
            source-path
            {:domain :gravity/sh02-contextual-verification-report-v1
             :report base}))))
      (catch InterruptedException interrupted
        (.interrupt (Thread/currentThread))
        (throw interrupted))
      (catch StackOverflowError _
        (p15-s23-sh02-fail!
         source-path {} :bounded-sh02-verifier-host-stack {}))
      (catch AssertionError error
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-sh02-verifier-assertion error))
      (catch LinkageError error
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-sh02-verifier-linkage error))
      (catch clojure.lang.ExceptionInfo exception
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-sh02-verifier-diagnostic exception))
      (catch Exception exception
        (p15-s23-b3-llvm-contain-exception!
         source-path :contained-sh02-verifier-host-failure exception)))))

(defn p15-s23-stage2-sh02-authenticated-envelope-verify!
  [artifact checked-core context]
  (let [report
        (p15-s23-stage2-sh02-authenticated-envelope-verification-report
         artifact checked-core context)]
    (when-not (= :passed (:status report))
      (p15-s23-sh02-fail!
       (p15-s23-c11-ingress-source-path context)
       artifact :sh02-contextual-verification-status {}))
    :passed))

(defn p15-s23-stage2-sh02-authenticated-envelope-authentic?
  ([artifact] false)
  ([artifact checked-core context]
   (try
     (= :passed
        (p15-s23-stage2-sh02-authenticated-envelope-verify!
         artifact checked-core context))
     (catch InterruptedException interrupted
       (.interrupt (Thread/currentThread))
       (throw interrupted))
     (catch StackOverflowError _ false)
     (catch AssertionError _ false)
     (catch LinkageError _ false)
     (catch Exception _ false))))

(defn p15-s23-stage2-sh02-descriptor-envelope
  "Build one reusable SH-02 envelope directly from a bounded stage descriptor.

  This is the narrow reuse seam for later bootstrap slices.  The caller may
  choose the stage label and artifact kind, but never supplies executable
  Gravity code, a compiled plan, a digest resolver, or construction authority.
  The pinned SH-02 source is reloaded and reauthenticated on every call."
  [stage artifact-kind descriptor source-path]
  (try
    (when-not (and (keyword? stage) (keyword? artifact-kind))
      (p15-s23-sh02-fail!
       source-path descriptor :sh02-descriptor-envelope-stage-contract
       {:stage stage :artifact-kind artifact-kind}))
    (let [binding
          (p15-s23-sh02-source-binding!
           p15-s23-c13-c14-b1-authority-token source-path)
          packet {stage {:artifact artifact-kind}}]
      (p15-s23-sh02-build-stage-envelope!
       p15-s23-c13-c14-b1-authority-token
       stage packet descriptor binding source-path))
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch StackOverflowError _
      (p15-s23-sh02-fail!
       source-path {} :bounded-sh02-descriptor-envelope-host-stack {}))
    (catch AssertionError error
      (p15-s23-b3-llvm-contain-exception!
       source-path :contained-sh02-descriptor-envelope-assertion error))
    (catch LinkageError error
      (p15-s23-b3-llvm-contain-exception!
       source-path :contained-sh02-descriptor-envelope-linkage error))
    (catch clojure.lang.ExceptionInfo exception
      (p15-s23-b3-llvm-contain-exception!
       source-path :contained-sh02-descriptor-envelope-diagnostic exception))
    (catch Exception exception
      (p15-s23-b3-llvm-contain-exception!
       source-path :contained-sh02-descriptor-envelope-host-failure exception))))

(defn p15-s23-stage2-sh02-descriptor-envelope-verify!
  "Reconstruct a descriptor envelope from current pinned source and inputs."
  [artifact stage artifact-kind descriptor source-path]
  (let [expected
        (p15-s23-stage2-sh02-descriptor-envelope
         stage artifact-kind descriptor source-path)]
    (p15-s23-c11-mir-require-strict-structure!
     source-path expected artifact
     :fresh-sh02-descriptor-envelope-reconstruction)
    (when-not (= expected artifact)
      (p15-s23-sh02-fail!
       source-path artifact :fresh-sh02-descriptor-envelope-equality
       {:stage stage :artifact-kind artifact-kind}))
    :passed))

(def p15-s23-c-backend-diagnostic-rules
  (into
   (set (remove #(str/starts-with? % "B3-")
                p15-s23-b3-llvm-diagnostic-rules))
   ["B2-DIALECT" "B2-UB" "B2-ABI" "B2-POINTER"
    "B2-NUMERIC" "B2-RUNTIME" "B2-FFI" "B2-MMIO"
    "B2-MANIFEST"
    "B13-SCHEMA" "B13-HASH" "B13-PROVENANCE"
    "B13-SOURCEMAP" "B13-EVIDENCE" "B13-TARGET"
    "B13-CONFORMANCE" "B13-REPRODUCIBILITY" "B13-RELEASE"
    "B13-GRAPH"
    "B14-COVERAGE" "B14-TARGET" "B14-POSITIVE" "B14-NEGATIVE"
    "B14-DIFFERENTIAL" "B14-METADATA" "B14-ARTIFACT"
    "B14-NONDETERMINISM" "B14-SKIP" "B14-EVIDENCE"]))

(defn p15-s23-c-backend-diagnostic-stage
  [id]
  (cond
    (str/starts-with? id "C13-") :c13-mir-optimization
    (str/starts-with? id "C14-") :c14-target-lowering
    (str/starts-with? id "B1-") :b1-backend-interface
    (str/starts-with? id "B2-") :b2-c-backend
    (str/starts-with? id "B13-") :b13-artifact-emission
    (str/starts-with? id "B14-") :b14-backend-conformance
    :else :b2-c-backend))

