(def ^:private p15-s23-b2-c17-pinned-source-failure-facts
  #{:exact-regular-pinned-gravity-bridge-source
    :stable-exact-pinned-gravity-bridge-source-size
    :pinned-gravity-bridge-source
    :pinned-gravity-bridge-source-identity
    :pinned-gravity-bridge-function-identity})

(defn- p15-s23-b2-c17-source-binding!
  [candidate source-path]
  (try
    (p15-s23-c13-c14-b1-source-binding!
     candidate source-path
     {:owner :gravity.backend/b2-c-backend
      :relative-path p15-s23-b2-c17-source-relative-path
      :source-byte-count p15-s23-b2-c17-source-byte-count
      :source-content-hash p15-s23-b2-c17-expected-source-content-hash
      :plan-semantic-hash p15-s23-b2-c17-expected-plan-semantic-hash
      :functions-semantic-hash
      p15-s23-b2-c17-expected-functions-semantic-hash
      :builder-semantic-hash
      p15-s23-b2-c17-expected-builder-semantic-hash
      :builder-function p15-s23-b2-c17-builder-function
      :required-functions p15-s23-b2-c17-required-functions
      :emitter-target :c})
    (catch clojure.lang.ExceptionInfo exception
      (let [data (ex-data exception)
            facts (if (map? (:facts data)) (:facts data) {})
            missing-fact
            (or (:missing-fact data) (:missing-fact facts))]
        (if (and (= "B1-INPUT" (or (:id data) (:rule data)))
                 (contains? p15-s23-b2-c17-pinned-source-failure-facts
                            missing-fact))
          (p15-s23-c-backend-fail!
           "B2-MANIFEST" source-path {}
           (merge
            (select-keys
             facts
             [:expected-source-content-hash
              :observed-source-content-hash
              :expected-source-bytes :observed-source-bytes])
            {:missing-fact :pinned-b2-gravity-source-identity
             :bounded-reason missing-fact}))
          (throw exception))))))

(defn p15-s23-b2-c17-forwarded-opcode?
  [opcode]
  (contains? #{:local :local-binding :sequence :lexical-scope
               :function-boundary}
             opcode))

(defn p15-s23-b2-c17-value-name
  [operation-index operation-id]
  (str "gravity_v" (get operation-index operation-id)))

(defn p15-s23-b2-c17-constant-expression
  [value]
  (cond
    (true? value) "INT64_C(1)"
    (false? value) "INT64_C(0)"
    (nil? value) "INT64_C(0)"
    (= Long/MIN_VALUE value) "INT64_MIN"
    (neg? value) (str "(-INT64_C(" (- value) "))")
    :else (str "INT64_C(" value ")")))

(defn p15-s23-b2-c17-operation-expression
  [operation operations operation-index]
  (let [opcode (:opcode operation)
        operands (:operands operation)
        name-for #(p15-s23-b2-c17-value-name operation-index %)]
    (cond
      (= :constant opcode)
      (p15-s23-b2-c17-constant-expression
       (get-in operation [:constant-payload :value]))

      (p15-s23-b2-c17-forwarded-opcode? opcode)
      (name-for (last operands))

      (= :truthiness opcode)
      (let [operand-id (first operands)
            operand (some #(when (= operand-id (:op-id %)) %) operations)
            value-name (name-for operand-id)]
        (case (:type operand)
          :gravity/nil "INT64_C(0)"
          :gravity/bool
          (str "(" value-name
               " == INT64_C(0) ? INT64_C(0) : INT64_C(1))")
          "INT64_C(1)"))

      (contains?
       #{:integer-eq :integer-lt :integer-lte :integer-gt :integer-gte}
       opcode)
      (str "(" (name-for (first operands))
           " "
           (case opcode
             :integer-eq "=="
             :integer-lt "<"
             :integer-lte "<="
             :integer-gt ">"
             :integer-gte ">=")
           " " (name-for (second operands))
           " ? INT64_C(1) : INT64_C(0))")

      (= :conditional-join opcode)
      (str "(" (name-for (first operands))
           " == INT64_C(0) ? " (name-for (last operands))
           " : " (name-for (second operands)) ")")

      :else "INT64_C(0)")))

(defn p15-s23-b2-c17-operation-record
  [operation operations operation-index]
  (let [name (p15-s23-b2-c17-value-name
              operation-index (:op-id operation))
        expression
        (p15-s23-b2-c17-operation-expression
         operation operations operation-index)]
    {:mir-operation-id (:op-id operation)
     :mir-block-id (:block-id operation)
     :source-operation (:source-operation operation)
     :mir-opcode (:opcode operation)
     :mir-type (:type operation)
     :c-type "int64_t"
     :c-value name
     :c-expression expression
     :c-statement
     (str "  int64_t " name " = " expression ";\n"
          "  (void)" name ";\n")
     :c-liveness-use (str "(void)" name ";")
     :safety-outcome :proven-safe}))

(defn p15-s23-b2-c17-return-id
  [function block-order]
  (first (get-in function [:blocks (last block-order)
                           :terminator :operands])))

(defn p15-s23-b2-c17-source-text
  [operation-records return-value-name]
  (str "#include <stdint.h>\n"
       "#include \"program.h\"\n\n"
       "int main(void) {\n"
       (apply str (map :c-statement operation-records))
       "  return (int)" return-value-name ";\n"
       "}\n"))

(defn p15-s23-b2-c17-abi-layout-record
  [b1-record]
  {:artifact :gravity/b2-abi-layout-manifest
   :status :pending-gate-b-toolchain-verification
   :compiler-family :apple-clang
   :compiler-version-constraint "21.0.0"
   :target-triple (get-in b1-record [:target :triple])
   :data-layout (get-in b1-record [:target :data-layout])
   :data-model :lp64
   :endianness :little
   :integer-carrier :int64-t
   :process-result :int
   :process-result-range [0 255]
   :alignment
   {:int {:size-bits 32 :alignment-bits 32}
    :int64-t {:size-bits 64 :alignment-bits 64}}
   :entrypoint-calling-convention :darwin-pcs-ccc
   :struct-field-order :not-applicable-bounded-scalar-slice
   :padding :not-applicable-bounded-scalar-slice
   :enum-and-tag-widths :not-applicable-bounded-scalar-slice
   :closure-representation :not-applicable-bounded-scalar-slice
   :slice-and-buffer-representation
   :not-applicable-bounded-scalar-slice
   :region-and-arena-handle-representation
   :not-applicable-bounded-scalar-slice
   :linear-resource-handle-representation
   :not-applicable-bounded-scalar-slice
   :ffi-calling-convention :not-applicable-no-ffi
   :abi (:abi b1-record)
   :implementation-defined-behavior-contract-pinned? true
   :toolchain-verification :not-performed-in-gate-a})

(defn p15-s23-b2-c17-runtime-helper-record
  [b1-record]
  {:artifact :gravity/b2-runtime-helper-manifest
   :profile :hosted
   :helpers []
   :gravity-runtime-providers
   (get-in b1-record [:runtime :gravity-runtime-providers])
   :platform-runtime-providers
   (get-in b1-record [:runtime :platform-runtime-providers])
   :provider-contract (:providers b1-record)
   :hidden-runtime-dependence? false
   :gate-b-platform-startup-required? true})

(defn- p15-s23-b2-c17-source-debug-entries
  [operations operation-records]
  (mapv
   (fn [index operation record]
     {:mir-operation-id (:op-id operation)
      :mir-block-id (:block-id operation)
      :source-origin-id (get-in operation [:facts :source-origin-id])
      :source-span (get-in operation [:source :span])
      :generated-origin-chain
      (get-in operation [:source :generated-origin])
      :c-value (:c-value record)
      :generated-declaration-line (+ 5 (* index 2))
      :generated-liveness-line (+ 6 (* index 2))})
   (range) operations operation-records))

(defn- p15-s23-b2-c17-source-debug-map-record
  [b1-record operations operation-records return-id return-value-name]
  {:artifact :gravity/b2-c-source-debug-map
   :status :source-map-preserved-debug-emission-pending-gate-b
   :source-map-id (get-in b1-record [:source-map :id])
   :generated-file "program.c"
   :entries
   (p15-s23-b2-c17-source-debug-entries
    operations operation-records)
   :final-return
   {:mir-operation-id return-id
    :c-value return-value-name
    :generated-return-line (+ 5 (* (count operation-records) 2))}
   :debug-info-emission :not-performed-in-gate-a})

(defn- p15-s23-b2-c17-operation-proof-bindings
  [operations operation-records]
  (mapv
   (fn [operation record]
     {:mir-operation-id (:op-id operation)
      :source-origin-id (get-in operation [:facts :source-origin-id])
      :safety-proof-id (get-in operation [:facts :safety-proof-id])
      :proof-certificate-ids
      (get-in operation [:facts :proof-certificate-ids])
      :c-value (:c-value record)})
   operations operation-records))

(defn- p15-s23-b2-c17-discard-cast-records
  [operations operation-records]
  (mapv
   (fn [operation record]
     {:kind :discarded-value
      :site (:c-liveness-use record)
      :from :int64-t :to :void
      :proof :initialized-scalar-liveness-use
      :safety-proof-id (get-in operation [:facts :safety-proof-id])})
   operations operation-records))

(defn p15-s23-b2-c17-proof-to-c-assumption-record
  [b1-record mir operations operation-records return-id
   return-value-name semantic-result]
  (let [certificates (get-in b1-record [:proofs :certificates])
        base-entries
        [{:assumption :signed-i64-carrier
          :evidence :authenticated-mir-scalar-type-and-constant-closure
          :c-site :all-generated-int64-t-initializers
          :outcome :proven-safe}
         {:assumption :explicit-discarded-value-conversions
          :evidence :initialized-generated-scalar-liveness
          :c-site :one-void-conversion-per-generated-local
          :outcome :proven-safe}
         {:assumption :final-exit-code-narrowing
          :evidence :independent-pure-mir-evaluation-in-0-to-255
          :c-site (str "return (int)" return-value-name ";")
          :outcome :proven-safe}]
        equality-entries
        (if (some #(= :integer-eq (:opcode %)) operations)
          (conj
           base-entries
           {:assumption :defined-signed-i64-equality
            :evidence
            :authenticated-two-integer-operands-and-boolean-result
            :c-site :generated-integer-eq-expressions
            :outcome :proven-safe})
          base-entries)
        entries
        (if (some #(contains?
                    #{:integer-lt :integer-lte :integer-gt :integer-gte}
                    (:opcode %))
                  operations)
          (conj
           equality-entries
           {:assumption :defined-signed-i64-ordering
            :evidence
            :authenticated-ordered-two-integer-operands-and-boolean-result
            :c-site :generated-integer-ordering-expressions
            :outcome :proven-safe})
          equality-entries)]
    {:artifact :gravity/b2-proof-to-c-assumption-map
     :proof-certificate-binding
     {:content-id (:content-id certificates)
      :entry-count (:entry-count certificates)}
     :operation-bindings
     (p15-s23-b2-c17-operation-proof-bindings
      operations operation-records)
     :entries entries
     :generated-c-casts
     (conj
      (p15-s23-b2-c17-discard-cast-records
       operations operation-records)
      {:kind :integer-narrowing
       :site (str "return (int)" return-value-name ";")
       :from :int64-t :to :int
       :proof :independent-pure-mir-evaluation-in-0-to-255
       :proof-binding
       {:kind :independent-bounded-mir-evaluation
        :mir-module-id (:module-id mir)
        :return-operation-id return-id
        :semantic-result semantic-result
        :permitted-result-range [0 255]
        :b1-artifact-id (:artifact-id b1-record)
        :proof-table-content-id (:content-id certificates)}})
     :all-casts-proof-authorized? true
     :implicit-undefined-behavior-permitted? false}))

(defn- p15-s23-b2-c17-assert-exact!
  [source-path expected actual missing-fact]
  (when-let [mismatch
             (p15-s23-c6c10-strict-first-mismatch
              source-path expected actual [])]
    (p15-s23-c-backend-fail!
     "B2-MANIFEST" source-path actual
     {:missing-fact missing-fact
      :bounded-reason
      (select-keys mismatch
                   [:path :expected-kind :actual-kind
                    :expected-count :actual-count
                    :missing-key-count :unexpected-key-count])})))

(defn- p15-s23-b2-c17-independent-raw
  [source-path c11-artifact c-packet]
  (let [b1-record (:b1 c-packet)
        payload (:bounded-lowering-payload b1-record)
        mir (:mir payload)
        preflight
        (p15-s23-c13-c14-b1-c-preflight! source-path c11-artifact)
        expected-mir (:mir preflight)
        operations (:operations preflight)
        block-order (:block-order preflight)
        operation-order (mapv :op-id operations)
        operation-index (zipmap operation-order (range))
        operation-records
        (mapv #(p15-s23-b2-c17-operation-record
                % operations operation-index)
              operations)
        function (:function preflight)
        return-id (p15-s23-b2-c17-return-id function block-order)
        return-value-name
        (p15-s23-b2-c17-value-name operation-index return-id)
        source-text
        (p15-s23-b2-c17-source-text
         operation-records return-value-name)
        semantic-result (:semantic-result preflight)
        source-debug-map
        (p15-s23-b2-c17-source-debug-map-record
         b1-record operations operation-records return-id
         return-value-name)]
    (p15-s23-b2-c17-assert-exact!
     source-path expected-mir mir :fresh-c11-to-sealed-b1-mir-parity)
    (when-not
     (and (= operation-order (:operation-order payload))
          (= (:artifact-id c11-artifact) (:c11-artifact-id payload))
          (= (:artifact-id c11-artifact)
             (get-in c-packet [:c11 :artifact-id]))
          (= (:mir-id c11-artifact)
             (get-in c-packet [:c11 :mir-id]))
          (= (:artifact-id b1-record)
             (get-in c-packet [:b1 :artifact-id]))
          (= (:semantic-id b1-record)
             (get-in c-packet [:b1 :semantic-id])))
      (p15-s23-c-backend-fail!
       "B2-MANIFEST" source-path b1-record
       {:missing-fact :fresh-context-bound-b1-to-b2-input-closure}))
    {:artifact :gravity/b2-bounded-hosted-c17
     :schema-version 1
     :status :constructed-unverified
     :policy p15-s23-b2-c17-policy-record
     :input-bindings
     {:b1-semantic-id (:semantic-id b1-record)
      :b1-artifact-id (:artifact-id b1-record)
      :b1-actual-path-binding-id (:actual-path-binding-id b1-record)
      :c11-artifact-id (:c11-artifact-id payload)
      :c13-artifact-id (:c13-artifact-id payload)
      :c13-semantic-id (:c13-semantic-id payload)
      :mir-module-id (:module-id mir)
      :b1-source-rule (:source-rule b1-record)}
     :backend-manifest (:backend-manifest b1-record)
     :c-build-manifest
     (p15-s23-b2-c17-build-manifest-record
      p15-s23-b2-c17-dialect-selection-record)
     :source-debug-map source-debug-map
     :dialect-selection p15-s23-b2-c17-dialect-selection-record
     :abi-layout-manifest
     (p15-s23-b2-c17-abi-layout-record b1-record)
     :runtime-helper-manifest
     (p15-s23-b2-c17-runtime-helper-record b1-record)
     :proof-to-c-assumption-map
     (p15-s23-b2-c17-proof-to-c-assumption-record
      b1-record mir operations operation-records return-id
      return-value-name semantic-result)
     :block-order block-order
     :operation-index operation-index
     :operation-records operation-records
     :header-file
     {:artifact :gravity/b2-c-header-file
      :path "program.h" :dialect :c17
      :content p15-s23-b2-c17-header-text
      :generated? true}
     :source-file
     {:artifact :gravity/b2-c-source-file
      :path "program.c" :dialect :c17 :content source-text
      :includes ["stdint.h" "program.h"]
      :generated? true}
     :semantic-result semantic-result
     :expected-exit-code semantic-result
     :verified-input-closure
     {:status :structurally-closed-after-root-contextual-gate
      :sealed-b1-record
      :fresh-contextual-strict-equality-required-before-invocation
      :raw-source-validator :not-a-standalone-seal-verifier
      :invocation-authority :clojure-seed-root-capability-gate
      :sealed-b1-semantic-id (:semantic-id b1-record)
      :sealed-b1-artifact-id (:artifact-id b1-record)
      :sealed-b1-actual-path-binding-id
      (:actual-path-binding-id b1-record)
      :actual-path-provenance (:actual-path-provenance b1-record)
      :mir-source :bounded-lowering-payload-only
      :source-core (:source-core mir)
      :mir-module-id (:module-id mir)
      :pass-execution-record-id
      (get-in mir [:pass-execution-record :record-id])
      :operation-count (count operations)
      :conditional-count
      (count (filter #(= :conditional-join (:opcode %)) operations))
      :full-dfg-definition-count
      (count (get-in mir [:data-flow-graph :definitions]))
      :full-dfg-value-count
      (count (get-in mir [:data-flow-graph :values]))
      :runtime-check-count (count (:runtime-check-table mir))
      :effect-count (count (:effect-table mir))
      :capability-count (count (:capability-table mir))}
     :diagnostics []
     :clojure-seed-boundary? true
     :whole-b2? false
     :public? false
     :release? false
     :self-hosted? false}))

(defn- p15-s23-b2-c17-final-record
  [source-path c11-artifact c-packet binding raw]
  (let [actual-path-provenance
        {:source source-path
         :c11-source (get-in c11-artifact
                             [:provenance :actual-paths :c11-source])
         :c13-source (get-in c-packet
                             [:actual-path-provenance :c13-source])
         :c14-source (get-in c-packet
                             [:actual-path-provenance :c14-source])
         :b1-source (get-in c-packet
                            [:actual-path-provenance :b1-source])
         :b2-source (:source-path binding)}]
    (p15-s23-c13-c14-b1-seal-stage
     :gravity/b2-bounded-hosted-c17
     raw
     (p15-s23-c13-c14-b1-source-rule
      :gravity.backend/b2-c-backend binding
      p15-s23-b2-c17-builder-function)
     actual-path-provenance)))

(defn- p15-s23-b2-c17-build-internal!
  [candidate c11-artifact checked-core context]
  (let [source-path (p15-s23-c11-ingress-source-path context)
        c-packet
        (p15-s23-c13-c14-b1-c-build-internal!
         candidate c11-artifact checked-core context)
        b1-record (:b1 c-packet)
        binding (p15-s23-b2-c17-source-binding! candidate source-path)
        expected
        (p15-s23-b2-c17-independent-raw
         source-path c11-artifact c-packet)
        raw
        (p15-s23-c13-c14-b1-invoke!
         candidate source-path binding p15-s23-b2-c17-builder-function
         [b1-record] "B1-INPUT")]
    (p15-s23-b2-c17-assert-exact!
     source-path expected raw :independent-b2-c17-reconstruction)
    (when-not (and (= p15-s23-b2-c17-raw-artifact-keys
                      (set (keys raw)))
                   (= expected raw)
                   (= (:artifact-id b1-record)
                      (get-in raw [:input-bindings :b1-artifact-id]))
                   (= (:semantic-id b1-record)
                      (get-in raw [:input-bindings :b1-semantic-id]))
                   (= (:actual-path-binding-id b1-record)
                      (get-in raw
                              [:input-bindings
                               :b1-actual-path-binding-id])))
      (p15-s23-c-backend-fail!
       "B2-MANIFEST" source-path raw
       {:missing-fact :exact-capability-gated-b1-bound-b2-output}))
    (p15-s23-b2-c17-final-record
     source-path c11-artifact c-packet binding raw)))

(defn- p15-s23-b2-c17-semantic-id
  [artifact]
  (p15-s23-c11-mir-digest
   {:kind :gravity/b2-bounded-hosted-c17
    :record (p15-s23-c13-c14-b1-stage-semantic-input artifact)}))

(defn- p15-s23-b2-c17-artifact-id
  [artifact]
  (p15-s23-c11-mir-digest
   {:kind :gravity/b2-bounded-hosted-c17
    :schema-version 1
    :semantic-id (:semantic-id artifact)}))

(defn- p15-s23-b2-c17-actual-path-binding-id
  [artifact]
  (p15-s23-c13-c14-b1-actual-path-binding-id
   (:semantic-id artifact) (:actual-path-provenance artifact)))

(defn- p15-s23-b2-c17-require-trusted-final!
  [source-path artifact]
  (let [validation
        (p15-s23-trusted-carrier-validation
         artifact :default-only
         p15-s23-c13-c14-b1-max-carrier-nodes
         p15-s23-c13-c14-b1-max-carrier-depth
         p15-s23-c13-c14-b1-max-carrier-nodes)]
    (when-not (= :passed (:status validation))
      (p15-s23-c-backend-fail!
       "B2-MANIFEST" source-path {}
       (merge
        {:missing-fact :trusted-bounded-b2-c17-final-carrier}
        (select-keys validation
                     [:reason :observed-nodes :observed-depth
                      :maximum-nodes :maximum-depth :maximum-width]))))
    (try
      (p15-s23-c11-mir-bounded-value!
       source-path :b2-c17-final-artifact artifact
       p15-s23-c13-c14-b1-max-carrier-nodes
       p15-s23-c13-c14-b1-max-carrier-depth)
      (catch clojure.lang.ExceptionInfo exception
        (p15-s23-c-backend-fail!
         "B2-MANIFEST" source-path {}
         {:missing-fact :bounded-b2-c17-final-carrier
          :bounded-reason
          (or (:missing-fact (ex-data exception))
              :contained-b2-final-carrier-diagnostic)})))
    :passed))

(defn- p15-s23-b2-c17-verification-preflight!
  [source-path artifact]
  (p15-s23-b2-c17-require-trusted-final! source-path artifact)
  (let [top-level-class (when (some? artifact)
                          (.getName (class artifact)))]
    (when-not
     (and (map? artifact)
          (contains? p15-s23-trusted-carrier-map-classes
                     top-level-class)
          (= p15-s23-b2-c17-final-artifact-keys
             (set (keys artifact)))
          (= :gravity/b2-bounded-hosted-c17 (:artifact artifact))
          (= 1 (:schema-version artifact))
          (= :constructed-unverified (:status artifact))
          (= p15-s23-b2-c17-policy-record (:policy artifact))
          (= p15-s23-b2-c17-dialect-selection-record
             (:dialect-selection artifact))
          (= [] (:diagnostics artifact))
          (true? (:clojure-seed-boundary? artifact))
          (false? (:whole-b2? artifact))
          (false? (:public? artifact))
          (false? (:release? artifact))
          (false? (:self-hosted? artifact))
          (map? (:source-rule artifact))
          (map? (:actual-path-provenance artifact))
          (= #{:source :c11-source :c13-source
               :c14-source :b1-source :b2-source}
             (set (keys (:actual-path-provenance artifact))))
          (every? string?
                  (vals (:actual-path-provenance artifact)))
          (every? string?
                  ((juxt :semantic-id :artifact-id
                         :actual-path-binding-id)
                   artifact)))
      (p15-s23-c-backend-fail!
       "B2-MANIFEST" source-path artifact
       {:missing-fact :exact-b2-c17-final-envelope})))
  (let [semantic-id (p15-s23-b2-c17-semantic-id artifact)
        expected
        [semantic-id
         (p15-s23-c11-mir-digest
          {:kind :gravity/b2-bounded-hosted-c17
           :schema-version 1 :semantic-id semantic-id})
         (p15-s23-c13-c14-b1-actual-path-binding-id
          semantic-id (:actual-path-provenance artifact))]]
    (when-not
     (= expected
        ((juxt :semantic-id :artifact-id :actual-path-binding-id)
         artifact))
      (p15-s23-c-backend-fail!
       "B13-HASH" source-path artifact
       {:missing-fact :recomputable-b2-c17-final-identities})))
  :passed)

(defn p15-s23-stage2-b2-c17-artifact-from-c11!
  [c11-artifact checked-core context]
  (let [source-path (p15-s23-c11-ingress-source-path context)]
    (try
      (p15-s23-b2-c17-build-internal!
       p15-s23-c13-c14-b1-authority-token
       c11-artifact checked-core context)
      (catch InterruptedException interrupted
        (.interrupt (Thread/currentThread))
        (throw interrupted))
      (catch StackOverflowError _
        (p15-s23-c-backend-fail!
         "B2-MANIFEST" source-path {}
         {:missing-fact :bounded-hostile-b2-c17-host-stack}))
      (catch clojure.lang.ExceptionInfo exception
        (p15-s23-c-backend-contain-exception!
         source-path :contained-b2-c17-diagnostic exception))
      (catch Exception exception
        (p15-s23-c-backend-contain-exception!
         source-path :contained-b2-c17-host-failure exception)))))

(defn p15-s23-stage2-b2-c17-source-artifact!
  [source-path source-text]
  (try
    (let [upstream-diagnostic-owner (Object.)
          [checked-core context]
          (binding [*p15-s23-c11-upstream-diagnostic-owner*
                    upstream-diagnostic-owner
                    *p15-s23-c11-mir-diagnostic-context*
                    {:requested-target :c}
                    *additional-bootstrap-targets*
                    stage2-runtime-derived-source-targets]
            (try
              (let [context
                    (p15-s23-stage2-gravity-checked-core-context
                     source-path source-text :c)]
                [(p15-s23-stage2-gravity-checked-core-source-artifact
                  context)
                 context])
              (catch InterruptedException interrupted
                (.interrupt (Thread/currentThread))
                (throw interrupted))
              (catch clojure.lang.ExceptionInfo exception
                (let [data
                      (p15-s23-backend-trusted-exception-data
                       exception 65536 128)]
                  (if (and
                       data
                       (p15-s23-c11-mir-owned-upstream-diagnostic? data))
                    (p15-s23-c11-mir-contain-checked-core-exception!
                     source-path :b2-source-checked-core-diagnostic
                     exception)
                    (throw exception))))))
          c11 (p15-s23-stage2-c11-mir-artifact checked-core context)]
      (p15-s23-stage2-b2-c17-artifact-from-c11!
       c11 checked-core context))
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch StackOverflowError _
      (p15-s23-c-backend-fail!
       "B2-MANIFEST" source-path {}
       {:missing-fact :bounded-hostile-b2-c17-source-host-stack}))
    (catch clojure.lang.ExceptionInfo exception
      (let [data
            (p15-s23-backend-trusted-exception-data
             exception 65536 128)
            replayed
            (when (map? data)
              (p15-s23-stage2-reader-replayed-diagnostic
               source-path source-text))]
        (if (and data
                 (p15-s23-stage2-canonical-c2-diagnostic-authentic?
                  source-path source-text data replayed))
          (throw exception)
          (p15-s23-c-backend-contain-exception!
           source-path :contained-b2-c17-source-diagnostic exception))))
    (catch Exception exception
      (p15-s23-c-backend-contain-exception!
       source-path :contained-b2-c17-source-host-failure exception))))

(defn- p15-s23-b2-c17-semantic-pure-closure-evidence
  [source-path fresh-c11 gate-a]
  (let [mir (:mir-module fresh-c11)
        function (get-in mir [:functions 'main])
        block-order (p15-s23-b3-llvm-block-order mir function)
        operations
        (p15-s23-b3-llvm-operation-sequence function block-order)
        union-fields
        (fn [table fields]
          (reduce
           set/union #{}
           (for [row (vals table) field fields]
             (let [value (get row field)]
               (cond
                 (set? value) value
                 (sequential? value) (set value)
                 (nil? value) #{}
                 :else #{value})))))
        semantic-effects
        (union-fields (:effect-table mir)
                      [:direct :latent :transitive :residual])
        semantic-capabilities
        (union-fields (:capability-table mir) [:required :granted])
        base
        {:artifact :gravity/b2-c17-semantic-pure-closure-evidence
         :schema-version 1 :status :passed
         :c11-artifact-id (:artifact-id fresh-c11)
         :c11-mir-id (:mir-id fresh-c11)
         :mir-module-id (:module-id mir)
         :operation-count (count operations)
         :effect-fact-row-count (count (:effect-table mir))
         :capability-fact-row-count (count (:capability-table mir))
         :runtime-check-count (count (:runtime-check-table mir))
         :capability-proof-count (count (:capability-proof-table mir))
         :semantic-effects semantic-effects
         :semantic-capabilities semantic-capabilities
         :semantic-effect-count (count semantic-effects)
         :semantic-capability-count (count semantic-capabilities)
         :main-latent-effects (set (:latent-effects function))
         :main-capabilities (set (:capabilities function))
         :all-operation-effects-empty?
         (every? empty? (map :effects operations))
         :all-operation-capabilities-empty?
         (every? empty? (map :capabilities operations))}]
    (when-not
     (and (= :passed (:verification-status mir))
          (= (:artifact-id fresh-c11)
             (get-in gate-a [:input-bindings :c11-artifact-id]))
          (= (:module-id mir)
             (get-in gate-a [:input-bindings :mir-module-id])
             (get-in gate-a [:verified-input-closure :mir-module-id]))
          (= (count operations)
             (get-in gate-a [:verified-input-closure :operation-count]))
          (= (count (:effect-table mir))
             (get-in gate-a [:verified-input-closure :effect-count]))
          (= (count (:capability-table mir))
             (get-in gate-a [:verified-input-closure :capability-count]))
          (= (count (:runtime-check-table mir))
             (get-in gate-a [:verified-input-closure :runtime-check-count]))
          (zero? (:runtime-check-count base))
          (zero? (:capability-proof-count base))
          (empty? (:main-latent-effects base))
          (empty? (:main-capabilities base))
          (true? (:all-operation-effects-empty? base))
          (true? (:all-operation-capabilities-empty? base))
          (empty? semantic-effects) (empty? semantic-capabilities))
      (p15-s23-c-backend-fail!
       "B14-METADATA" source-path gate-a
       {:missing-fact :authenticated-semantic-pure-c17-closure}))
    (assoc base :evidence-id
           (p15-s23-c11-mir-digest
            {:kind :gravity/b2-c17-semantic-pure-closure-evidence
             :schema-version 1 :record base}))))

(defn p15-s23-stage2-b2-c17-verification-report
  [artifact checked-core context]
  (let [source-path (p15-s23-c11-ingress-source-path context)]
    (try
      (p15-s23-b2-c17-verification-preflight! source-path artifact)
      (let [fresh-c11
            (p15-s23-stage2-c11-mir-artifact checked-core context)
            expected
            (p15-s23-b2-c17-build-internal!
             p15-s23-c13-c14-b1-authority-token
             fresh-c11 checked-core context)]
        (p15-s23-b2-c17-assert-exact!
         source-path expected artifact
         :contextual-fresh-c11-through-b2-c17-reconstruction)
        (when-not (= expected artifact)
          (p15-s23-c-backend-fail!
           "B2-MANIFEST" source-path artifact
           {:missing-fact :fresh-context-bound-b2-c17-artifact}))
        (let [semantic-pure-closure
              (p15-s23-b2-c17-semantic-pure-closure-evidence
               source-path fresh-c11 expected)
              base
              {:artifact :gravity/b2-c17-contextual-verification-report
               :schema-version 1
               :status :passed
               :artifact-id (:artifact-id artifact)
               :semantic-id (:semantic-id artifact)
               :fresh-c11 :passed
               :fresh-c13 :passed
               :fresh-c14 :passed
               :fresh-b1 :passed
               :gravity-b2-source-replay :passed
               :independent-c-reconstruction :passed
               :semantic-pure-closure semantic-pure-closure
               :external-tool-execution :not-performed-in-gate-a
               :public? false :release? false :self-hosted? false}]
          (assoc base :report-id
                 (p15-s23-c11-mir-digest
                  {:kind
                   :gravity/b2-c17-contextual-verification-report
                   :schema-version 1 :report base}))))
      (catch InterruptedException interrupted
        (.interrupt (Thread/currentThread))
        (throw interrupted))
      (catch StackOverflowError _
        (p15-s23-c-backend-fail!
         "B2-MANIFEST" source-path {}
         {:missing-fact :bounded-hostile-b2-c17-verifier-stack}))
      (catch clojure.lang.ExceptionInfo exception
        (p15-s23-c-backend-contain-exception!
         source-path :contained-b2-c17-verifier-diagnostic exception))
      (catch Exception exception
        (p15-s23-c-backend-contain-exception!
         source-path :contained-b2-c17-verifier-failure exception)))))

(defn p15-s23-stage2-b2-c17-verify!
  [artifact checked-core context]
  (let [report
        (p15-s23-stage2-b2-c17-verification-report
         artifact checked-core context)]
    (when-not (= :passed (:status report))
      (p15-s23-c-backend-fail!
       "B2-MANIFEST" (p15-s23-c11-ingress-source-path context)
       artifact {:missing-fact :b2-c17-verification-status}))
    :passed))

(defn p15-s23-stage2-b2-c17-authentic?
  ([artifact] false)
  ([artifact checked-core context]
   (try
     (= :passed
        (p15-s23-stage2-b2-c17-verify!
         artifact checked-core context))
     (catch InterruptedException interrupted
       (.interrupt (Thread/currentThread))
       (throw interrupted))
     (catch StackOverflowError _ false)
     (catch Exception _ false))))

(declare p15-s23-c13-c14-b1-wasm-build-internal!
         p15-s23-b4-wasm-fail!
         p15-s23-b4-wasm-contain-exception!)

(defn- p15-s23-c13-c14-b1-wasm-build-authorized!
  [c11-artifact checked-core context]
  (p15-s23-c13-c14-b1-wasm-build-internal!
   p15-s23-c13-c14-b1-authority-token
   c11-artifact checked-core context))

)

;; ---------------------------------------------------------------------------
;; Authenticated hosted-C17 toolchain Gate B (FL-P07-T02 bounded slice)
;; ---------------------------------------------------------------------------

;; Gate A above is intentionally pure with respect to the host toolchain.  The
;; lexical authority below is the only route from an authenticated Gate-A
;; carrier to filesystem or process effects.  None of the B3/LLVM authority or
;; command machinery is reused: its diagnostics, target contract, and six-file
;; publication inventory are deliberately backend-specific.

(declare p18-t04-experimental-verified-mir-c-route-record)

(def p15-s23-b2-c17-gate-b-final-artifact-keys
  #{:artifact :schema-version :status :policy :gate-a-artifact
    :gate-a-contextual-report :toolchain-evidence :b13-record :b14-record
    :c18-record :diagnostics :whole-b2? :public? :release? :self-hosted?
    :seed-boundary? :clojure-seed-boundary?
    :semantic-id :artifact-id :actual-path-provenance
    :actual-path-binding-id :publication-receipt})

(def p15-s23-b2-c17-gate-b-option-keys
  #{:output-directory})

(def p15-s23-b2-c17-gate-b-policy
  {:artifact :gravity/b2-hosted-c17-gate-b-policy
   :schema-version 1
   :owner :gravity.backend/b2-c
   :tier :experimental
   :exposure :internal
   :profile :hosted
   :target :c
   :dialect :c17
   :target-triple "arm64-apple-macosx14.0.0"
   :maximum-tool-output-bytes 65536
   :maximum-emitted-file-bytes (* 8 1024 1024)
   :tool-timeout-ms 30000
   :maximum-captured-descendants 64
   :private-workspace-mode "0700"
   :publication-mode-policy
   {:directory "0755" :executable "0755" :nonexecutable "0644"}
   :publication-file-set
   ["program.c" "program.h" "program.o" "program"
    "manifest.edn" "provenance.edn" "conformance.edn"]
   :whole-process-tree-reaping-proved? false
   :whole-b2? false
   :public? false
   :release? false
   :self-hosted? false})

(def ^:private p15-s23-b2-c17-gate-b-developer-directory
  "/Library/Developer/CommandLineTools")

(def p15-s23-b2-c17-gate-b-environment-policy
  {:inherited-environment? false
   :fixed-values {"PATH" "/usr/bin:/bin:/usr/sbin:/sbin"
                  "LC_ALL" "C"
                  "LANG" "C"
                  "DEVELOPER_DIR"
                  p15-s23-b2-c17-gate-b-developer-directory}
   :private-physical-values ["HOME" "TMPDIR"]
   :forbidden-prefixes ["DYLD_" "CCC_" "LLVM_"]
   :forbidden-names ["SDKROOT" "MACOSX_DEPLOYMENT_TARGET" "CPATH"
                     "LIBRARY_PATH"]})

(def ^:private p15-s23-b2-c17-gate-b-private-directory-permissions
  #{java.nio.file.attribute.PosixFilePermission/OWNER_READ
    java.nio.file.attribute.PosixFilePermission/OWNER_WRITE
    java.nio.file.attribute.PosixFilePermission/OWNER_EXECUTE})

(def ^:private p15-s23-b2-c17-gate-b-directory-permissions
  #{java.nio.file.attribute.PosixFilePermission/OWNER_READ
    java.nio.file.attribute.PosixFilePermission/OWNER_WRITE
    java.nio.file.attribute.PosixFilePermission/OWNER_EXECUTE
    java.nio.file.attribute.PosixFilePermission/GROUP_READ
    java.nio.file.attribute.PosixFilePermission/GROUP_EXECUTE
    java.nio.file.attribute.PosixFilePermission/OTHERS_READ
    java.nio.file.attribute.PosixFilePermission/OTHERS_EXECUTE})

(def ^:private p15-s23-b2-c17-gate-b-nonexecutable-permissions
  #{java.nio.file.attribute.PosixFilePermission/OWNER_READ
    java.nio.file.attribute.PosixFilePermission/OWNER_WRITE
    java.nio.file.attribute.PosixFilePermission/GROUP_READ
    java.nio.file.attribute.PosixFilePermission/OTHERS_READ})

(def ^:private p15-s23-b2-c17-gate-b-executable-permissions
  p15-s23-b2-c17-gate-b-directory-permissions)

(let [p15-s23-b2-c17-gate-b-authority-token (Object.)
      p15-s23-b2-c17-gate-b-tool-state
      (atom {:total 0 :steps {}})]

(defn- p15-s23-b2-c17-gate-b-interrupt-like?
  [error]
  (or (instance? InterruptedException error)
      (instance? java.nio.channels.ClosedByInterruptException error)
      (instance? java.io.InterruptedIOException error)))

(defn- p15-s23-b2-c17-gate-b-restore-interrupt!
  [error]
  (when (p15-s23-b2-c17-gate-b-interrupt-like? error)
    (.interrupt (Thread/currentThread)))
  error)

(defn- p15-s23-b2-c17-gate-b-rethrow-interrupt!
  [error]
  (when (p15-s23-b2-c17-gate-b-interrupt-like? error)
    (p15-s23-b2-c17-gate-b-restore-interrupt! error)
    (throw error))
  error)

(defn p15-s23-b2-c17-gate-b-tool-execution-snapshot
  []
  @p15-s23-b2-c17-gate-b-tool-state)

(defn- p15-s23-b2-c17-gate-b-require-authority!
  [candidate source-path operation]
  (when-not (identical? candidate
                         p15-s23-b2-c17-gate-b-authority-token)
    (p15-s23-c-backend-fail!
     "B2-MANIFEST" source-path {}
     {:missing-fact :opaque-authenticated-c17-gate-b-authority
      :bounded-reason operation})))

(defn- p15-s23-b2-c17-gate-b-provider-error?
  [error]
  (true? (:gravity.darwin-publication/error (ex-data error))))

(defn- p15-s23-b2-c17-gate-b-provider-mode
  [mode]
  (case mode
    0755 "0755"
    0644 "0644"
    :redacted))

(defn- p15-s23-b2-c17-gate-b-provider-fail!
  [source-path boundary error]
  (let [data (ex-data error)
        operation (:operation data)
        reason (:reason data)
        native-reasons
        #{:unsupported-host-runtime :native-access-disabled
          :missing-native-symbol :ffi-binding-unavailable}
        authority-reasons
        #{:invalid-output-location :parent-descriptor-open-failed
          :untrusted-parent-descriptor :destination-exists
          :destination-absence-check-failed :invalid-provider-context
          :invalid-provider-control-state :invalid-provider-lifecycle}
        schema-reasons
        #{:invalid-file-set :invalid-file-specification
          :created-file-metadata-mismatch :descriptor-chmod-failed
          :staging-contract-mismatch
          :directory-inventory-limit :directory-read-failed
          :fdopendir-failed :invalid-directory-entry-layout
          :unterminated-directory-entry :invalid-utf8-directory-entry
          :platform-thread-required :invalid-publication-receipt}
        hash-reasons
        #{:file-write-failed :zero-progress-file-write
          :file-readback-failed :short-file-readback
          :file-content-or-metadata-mismatch
          :published-bundle-content-or-identity-mismatch}
        provenance-reasons
        #{:descriptor-stat-failed :descriptor-path-failed
          :descriptor-sync-failed :descriptor-close-failed
          :access-control-list-inspection-failed
          :access-control-list-release-failed
          :nontrivial-extended-access-control-list
          :bounded-staging-name-exhausted
          :staging-directory-create-failed
          :staging-directory-open-failed
          :directory-reopen-failed :directory-stream-close-failed
          :cleanup-directory-open-failed
          :exclusive-file-create-failed :unique-file-open-failed
          :untrusted-staging-descriptor
          :descriptor-or-content-identity-changed
          :published-directory-open-failed
          :published-directory-provenance-mismatch}
        [diagnostic-id missing-fact]
        (cond
          (= :native-access-disabled reason)
          ["B2-MANIFEST"
           :jdk26-native-access-required-for-c17-publication]

          (= :unsupported-host-runtime reason)
          ["B2-MANIFEST"
           :pinned-jdk26-macos-aarch64-c17-host-runtime]

          (contains? #{:missing-native-symbol :ffi-binding-unavailable}
                     reason)
          ["B2-MANIFEST"
           :jdk26-darwin-c17-publication-ffi-binding]

          (= :destination-exists reason)
          ["B2-MANIFEST"
           :collision-free-regular-c17-output-directory]

          (contains? #{:destination-collision
                       :exclusive-rename-failed}
                     reason)
          ["B2-MANIFEST" :exclusive-no-clobber-c17-publication]

          (or (contains? native-reasons reason)
              (contains? authority-reasons reason))
          ["B2-MANIFEST" :descriptor-relative-c17-publication-authority]

          (contains? schema-reasons reason)
          ["B13-SCHEMA" :exact-descriptor-relative-c17-bundle]

          (contains? hash-reasons reason)
          ["B13-HASH" :descriptor-relative-c17-publication-content]

          (contains? provenance-reasons reason)
          ["B13-PROVENANCE"
           :descriptor-relative-c17-publication-provenance]

          (= :verify boundary)
          ["B13-PROVENANCE"
           :descriptor-relative-c17-publication-verification]

          :else
          ["B2-MANIFEST" :contained-darwin-publication-failure])
        facts
        (cond->
         {:missing-fact missing-fact
          :bounded-reason
          (if (keyword? reason) reason :invalid-provider-failure)
          :tool-step
          (if (keyword? operation) operation :darwin-publication)}
          (boolean? (:output-collision? data))
          (assoc :output-collision? (:output-collision? data))

          (boolean? (:native-access-enabled? data))
          (assoc :native-access-enabled? (:native-access-enabled? data))

          (integer? (:return-code data))
          (assoc (if (= :commit operation)
                   :rename-return-code
                   :provider-return-code)
                 (:return-code data))

          (integer? (:errno data))
          (assoc :captured-errno (:errno data))

          (integer? (:expected-file-count data))
          (assoc :expected-file-count (:expected-file-count data))

          (integer? (:observed-file-count data))
          (assoc :observed-file-count (:observed-file-count data))

          (integer? (:observed-byte-count data))
          (assoc :observed-byte-count (:observed-byte-count data))

          (and (integer? (:expected-byte-count data))
               (<= 0 (:expected-byte-count data) (* 8 1024 1024)))
          (assoc :expected-byte-count (:expected-byte-count data))

          (string? (:logical-path data))
          (assoc :logical-path (:logical-path data))

          (integer? (:observed-mode data))
          (assoc :observed-mode
                 (p15-s23-b2-c17-gate-b-provider-mode
                  (:observed-mode data)))

          (contains? data :expected-mode)
          (assoc :expected-mode
                 (p15-s23-b2-c17-gate-b-provider-mode
                  (:expected-mode data))))]
    (p15-s23-c-backend-fail!
     diagnostic-id source-path {} facts)))

(defn- p15-s23-b2-c17-gate-b-provider-call!
  [source-path boundary operation]
  (try
    (operation)
    (catch clojure.lang.ExceptionInfo error
      (if (p15-s23-b2-c17-gate-b-provider-error? error)
        (p15-s23-b2-c17-gate-b-provider-fail!
         source-path boundary error)
        (throw error)))))

(defn- p15-s23-b2-c17-gate-b-incomplete-cleanup!
  [source-path primary cleanup-error]
  (let [data
        (p15-s23-backend-trusted-exception-data primary 65536 128)
        primary-rule
        (if (and (map? data)
                 (contains? p15-s23-c-backend-diagnostic-rules
                            (:id data)))
          (:id data)
          :contained-host-failure)
        primary-diagnostic-id
        (when (and (map? data)
                   (string? (:diagnostic-id data))
                   (re-matches #"diag-[0-9a-f]{64}"
                               (:diagnostic-id data)))
          (:diagnostic-id data))
        facts
        (cond->
         {:missing-fact
          :complete-descriptor-relative-c17-publication-cleanup
          :cleanup-complete? false :residue-possible? true
          :primary-failure-rule primary-rule}
          primary-diagnostic-id
          (assoc :primary-diagnostic-id primary-diagnostic-id))
        diagnostic
        (try
          (p15-s23-c-backend-fail!
           "B13-PROVENANCE" source-path {} facts)
          (catch clojure.lang.ExceptionInfo diagnostic
            diagnostic))]
    (.addSuppressed ^Throwable diagnostic ^Throwable primary)
    (when cleanup-error
      (.addSuppressed ^Throwable diagnostic ^Throwable cleanup-error))
    (throw diagnostic)))

(defn- p15-s23-b2-c17-gate-b-canonical-abort-result?
  [cleanup]
  (and
   (map? cleanup)
   (contains? #{:aborted :already-aborted} (:status cleanup))
   (= (if (= :aborted (:status cleanup))
        #{:status :published? :cleanup-complete? :residue-possible?}
        #{:status :published? :cleanup-complete? :residue-possible?
          :native-calls})
      (set (keys cleanup)))
   (false? (:published? cleanup))
   (boolean? (:cleanup-complete? cleanup))
   (boolean? (:residue-possible? cleanup))
   (= (:cleanup-complete? cleanup)
      (not (:residue-possible? cleanup)))
   (or (= :aborted (:status cleanup))
       (and (integer? (:native-calls cleanup))
            (zero? (:native-calls cleanup))))))

(defn- p15-s23-b2-c17-gate-b-abort-after-failure!
  [publication-context source-path error]
  (let [incomplete? (atom false)
        cleanup-error (atom nil)]
    (try
      (let [cleanup
            (darwin-publication/abort-staged-bundle! publication-context)]
        (when-not
         (and (p15-s23-b2-c17-gate-b-canonical-abort-result? cleanup)
              (true? (:cleanup-complete? cleanup)))
          (reset! incomplete? true)))
      (catch Throwable cleanup
        (p15-s23-b2-c17-gate-b-restore-interrupt! error)
        (p15-s23-b2-c17-gate-b-restore-interrupt! cleanup)
        (cond
          (instance? Error error)
          (.addSuppressed ^Throwable error ^Throwable cleanup)

          (instance? Error cleanup)
          (do
            (.addSuppressed ^Throwable cleanup ^Throwable error)
            (throw cleanup))

          (p15-s23-b2-c17-gate-b-interrupt-like? error)
          (.addSuppressed ^Throwable error ^Throwable cleanup)

          (p15-s23-b2-c17-gate-b-interrupt-like? cleanup)
          (do
            (.addSuppressed ^Throwable cleanup ^Throwable error)
            (throw cleanup))

          :else
          (do
            (reset! incomplete? true)
            (reset! cleanup-error cleanup)))))
    (when @incomplete?
      (if (or (instance? Error error)
              (p15-s23-b2-c17-gate-b-interrupt-like? error))
        (.addSuppressed
         ^Throwable error
         (ex-info
          "C17 descriptor publication cleanup was incomplete"
          {:cleanup-complete? false :residue-possible? true}))
        (p15-s23-b2-c17-gate-b-incomplete-cleanup!
         source-path error @cleanup-error)))
    (p15-s23-b2-c17-gate-b-restore-interrupt! error)
    (throw error)))

(defn- p15-s23-b2-c17-gate-b-host-runtime-preflight!
  [candidate source-path]
  (p15-s23-b2-c17-gate-b-require-authority!
   candidate source-path :pinned-c17-host-runtime-preflight)
  (let [record
        {:artifact :gravity/b2-c17-gate-b-host-runtime
         :schema-version 1
         :java-vendor (System/getProperty "java.vendor")
         :java-vm-name (System/getProperty "java.vm.name")
         :java-version (System/getProperty "java.version")
         :java-feature (.feature (Runtime/version))
         :os-name (System/getProperty "os.name")
         :os-arch (System/getProperty "os.arch")}]
    (when-not
     (= {:artifact :gravity/b2-c17-gate-b-host-runtime
         :schema-version 1
         :java-vendor "Homebrew"
         :java-vm-name "OpenJDK 64-Bit Server VM"
         :java-version "26.0.1" :java-feature 26
         :os-name "Mac OS X" :os-arch "aarch64"}
        record)
      (p15-s23-c-backend-fail!
       "B2-MANIFEST" source-path {}
       {:missing-fact :pinned-jdk26-macos-aarch64-c17-host-runtime
        :bounded-reason :host-runtime-preflight}))
    record))

(defn- p15-s23-b2-c17-gate-b-sha256-bytes
  [bytes]
  (let [digest (java.security.MessageDigest/getInstance "SHA-256")]
    (.update digest ^bytes bytes)
    (str "sha256:"
         (apply str
                (map #(format "%02x" (bit-and % 0xff))
                     (.digest digest))))))

(defn- p15-s23-b2-c17-gate-b-read-bounded-stream
  [candidate stream source-path]
  (p15-s23-b2-c17-gate-b-require-authority!
   candidate source-path :read-bounded-c-tool-stream)
  (with-open [input stream
              output (java.io.ByteArrayOutputStream.)]
    (let [buffer (byte-array 4096)
          digest (java.security.MessageDigest/getInstance "SHA-256")]
      (loop [total 0]
        (let [read (.read input buffer)]
          (if (neg? read)
            (let [bytes (.toByteArray output)]
              {:bytes bytes
               :text (String. ^bytes bytes
                              java.nio.charset.StandardCharsets/UTF_8)
               :stream-read-complete? true
               :total-byte-count total
               :retained-byte-count total
               :truncated? false
               :hash
               (str "sha256:"
                    (apply str
                           (map #(format "%02x" (bit-and % 0xff))
                                (.digest digest))))})
            (let [next-total (+ total read)
                  remaining (- 65536 total)
                  keep-count (max 0 (min remaining read))]
              (when (pos? keep-count)
                (.update digest buffer 0 keep-count)
                (.write output buffer 0 keep-count))
              (if (> next-total 65536)
                (let [bytes (.toByteArray output)]
                  {:bytes bytes
                   :text (String. ^bytes bytes
                                  java.nio.charset.StandardCharsets/UTF_8)
                   :stream-read-complete? false
                   :limit-exceeded? true
                   :total-byte-count next-total
                   :retained-byte-count (+ total keep-count)
                   :truncated? true
                   :hash
                   (str "sha256:"
                        (apply str
                               (map #(format "%02x" (bit-and % 0xff))
                                    (.digest digest))))})
                (recur next-total)))))))))

(defn- p15-s23-b2-c17-gate-b-destroy-process-tree!
  [candidate process source-path]
  (p15-s23-b2-c17-gate-b-require-authority!
   candidate source-path :destroy-bounded-c-tool-process-set)
  (let [root (.toHandle process)
        descendants
        (with-open [stream (.descendants root)]
          (vec (iterator-seq
                (.iterator (.limit stream (long 65))))))
        overflow? (> (count descendants) 64)
        root-requested?
          (try (.destroyForcibly root) (catch Exception _ false))
        descendant-requests
        (mapv (fn [handle]
                (try (.destroyForcibly ^java.lang.ProcessHandle handle)
                     (catch Exception _ false)))
              descendants)
        deadline (+ (System/nanoTime) 2000000000)
        result
        (loop []
          (let [root-alive? (.isAlive root)
                alive-descendants
                (count (filter #(.isAlive ^java.lang.ProcessHandle %)
                               descendants))]
            (if (and (or root-alive? (pos? alive-descendants))
                     (< (System/nanoTime) deadline))
              (do (Thread/sleep 10) (recur))
              {:kill-requested? true
               :root-kill-requested? (boolean root-requested?)
               :descendant-count (count descendants)
               :descendant-kill-request-count
               (count (filter true? descendant-requests))
               :root-alive-after-kill? root-alive?
               :descendants-alive-after-kill alive-descendants
               :captured-process-set-reaped?
               (and (not root-alive?) (zero? alive-descendants))
               :whole-process-tree-reaping-proved? false})))]
    (when-not (:captured-process-set-reaped? result)
      (p15-s23-c-backend-fail!
       "B2-MANIFEST" source-path {}
       {:missing-fact :captured-c-tool-process-set-not-reaped
        :maximum-byte-count 64
        :observed-byte-count (:descendants-alive-after-kill result)}))
    (when overflow?
      (p15-s23-c-backend-fail!
       "B2-MANIFEST" source-path {}
       {:missing-fact :bounded-c-tool-descendant-count
        :maximum-byte-count 64
        :observed-byte-count (count descendants)}))
    result))

(defn- p15-s23-b2-c17-gate-b-run-process
  [candidate directory command timeout-ms source-path]
