        _ (.directory builder (.toFile directory))
        environment (.environment builder)
        _ (.clear environment)
        _ (.put environment "PATH" "/usr/bin:/bin:/usr/sbin:/sbin")
        _ (.put environment "LC_ALL" "C")
        _ (.put environment "LANG" "C")
