              (try
                (deref stream-future 3000 fallback)
                (catch java.util.concurrent.ExecutionException wrapped
                  (let [cause (.getCause wrapped)]
                    (cond
                      (instance? Error cause) (throw cause)
                      (p15-s23-b2-c17-gate-b-interrupt-like? cause)
