         (= p15-s23-closed-runtime-max-depth (:maximum-depth validation))
         (= p15-s23-closed-runtime-max-nodes (:maximum-nodes validation))
         (= :gravity/p15-s23-runtime-closed-plan-invocation-record
            (:artifact invocation))
         (= #{:artifact :function :function-hash :runtime-artifact-hash
              :plan-id :stdout-hash :invocation-count
              :invocation-count-scope :verification-replays-excluded?
              :status}
            (set (keys invocation)))
         (= 1 (:invocation-count invocation))
         (= :authoritative-packet-construction
            (:invocation-count-scope invocation))
         (true? (:verification-replays-excluded? invocation))
         (= :complete (:status invocation))
         (= (:executor-function record) (:function invocation))
         (= (:executor-function-hash record) (:function-hash invocation))
         (= (:runtime-artifact-hash record)
            (:runtime-artifact-hash invocation))
         (every? digest?
                 [(:plan-id invocation) (:stdout-hash invocation)])
         (= :gravity/p15-s23-runtime-closed-plan-execution-record
            (:artifact execution))
         (= #{:artifact :entrypoint :plan-id :stdout-hash :status}
            (set (keys execution)))
         (= :complete (:status execution))
         (= (:plan-id validation) (:plan-id invocation))
         (= (:plan-id execution) (:plan-id invocation))
         (= (:entrypoint validation) (:entrypoint execution))
         (= (:stdout-hash invocation) (:stdout-hash execution))
         (= {:artifact
             :gravity/p15-s23-runtime-closed-plan-verification-replay-record
             :function p15-s23-stage2-runtime-artifact-closed-plan-function
             :replay-count 1
             :count-scope :consumer-packet-authentication
             :included-in-authoritative-invocation-count? false
             :status :passed}
            verification-replay)
         (= (:plan-id context) (:plan-id invocation))
         (= (:entrypoint context) (:entrypoint execution))
         (= (:stdout-hash context) (:stdout-hash execution))
         (= {:kind :clojure-seed-runtime-primitive-classification
             :pure-primitives '#{= < <= > >= count first get second}
             :proven-allocation-primitives '#{assoc conj str}
             :proven-allocation-literals #{:vector-literal :map-literal}
             :allocation-unproven-primitives '#{rest}
             :proven-allocation-operation-counts
             {:str 11 :vector 10 :map 2 :conj 1 :assoc 1}
             :proven-allocation-count 25
             :allocation-unproven-operation-counts {:rest 4}
             :allocation-unproven-count 4
             :effects #{:memory/allocate}
             :capabilities #{:memory/allocator}}
            (:primitive-boundary record))
         (= {:closed-plan-reference
             {:scope :closed-plan-interpreter
              :direct-handler-function
              p15-s23-reference-runtime-handler-function
              :transitive-function-scope
              '#{p15-s23-runtime-evaluate-arguments
                 p15-s23-runtime-evaluate-bindings
                 p15-s23-runtime-evaluate-sequence
                 p15-s23-runtime-evaluate-closed-instruction
                 p15-s23-runtime-execute-closed-plan}
              :handled #{:io/write}
              :escaping #{:memory/allocate}
              :source-capabilities #{:memory/allocator :io/stdout}
              :handler-capabilities #{:test/fixture}
              :provider-id :gravity.reference/transcript-capture
              :handler-id :gravity.reference/transcript-string-handler
              :live-stdout? false}
             :legacy-println-helpers
             {:function-scope
              '#{p15-s23-runtime-println-value
                 p15-s23-runtime-println-two}
              :handled #{}
              :escaping #{:memory/allocate :io/write}
              :provider-selection :unresolved
              :grant :unresolved
              :status :unresolved}
             :deployment-stdout
             {:effect :io/write
              :capability :io/stdout
              :provider-selection :unresolved
              :grant :unresolved
              :closed-plan-interpreter-excluded? true
              :status :unresolved}
             :build-effects #{}}
            (:effect-projections record))
         (= {:reference-runtime? true
             :deployment-runtime? false
             :checked-core-str-println-admission? true
             :checked-core-binary-integer-comparison-admission? true
             :checked-core-binary-integer-comparison-operations
             '#{= < <= > >=}
             :checked-core-admission-scope
             :authenticated-hosted-jvm-reference-interpreter
             :typed-fourth-authority
             :gravity/p15-s23-checked-core-authority-binding-v1
             :typed-fourth-authority-consumed-by-this-packet? false
             :verification-replay-policy-id
             p15-s23-checked-core-verification-replay-policy-id
             :target-lowering-credit? false
             :release-credit? false
             :c11-credit? false}
            (:credit-boundary record))
         (= {:kind :actual-path-context
             :context-key :runtime-artifact-source-path
             :semantic-identity-input? false}
            (:provenance-binding record))
         (= {:clojure-stage2-executor? true
             :stage0-oracle? true
             :three-way-output-equivalent? true
             :closed-plan-variadic-println? true}
            (:migration-comparison record))
         (false? (:mir-derived? record))
         (true? (:clojure-seed-boundary? record))
         (false? (:self-hosted? record))))
   (catch StackOverflowError _ false)
   (catch Exception _ false))))

(defn c-backend-runtime-bytes
  [value]
  (let [text (str value)
        bytes (.getBytes (str text) java.nio.charset.StandardCharsets/UTF_8)]
    (vec (map #(bit-and (int %) 0xff) bytes))))

(defn c-backend-runtime-byte-array-source
  [name bytes]
  (let [values (if (seq bytes) bytes [0])]
    (str "  static const unsigned char " name "[] = {"
         (str/join "," values)
         "};\n"
         "  fwrite(" name ", 1, " (if (seq bytes) (str "sizeof(" name ")") "0")
         ", stdout);\n")))

(defn c-backend-runtime-value-declaration
  "Declare a stable byte array for one scalar value and return the descriptor
  used by local references.  The descriptor retains Clojure truthiness so a
  runtime `if` can branch without re-evaluating the source in the host."
  [instruction counter indent]
  (let [padding (apply str (repeat indent "  "))
        name (str "gravity_literal_" (swap! counter inc))
        value (:value instruction)
        bytes (c-backend-runtime-bytes value)
        values (if (seq bytes) bytes [0])]
    {:source (str padding
                  "static const unsigned char " name "[] = {"
                  (str/join "," values) "};\n")
     :descriptor {:name name
                  :length (count bytes)
                  ;; Reference the declaration in local conditions so
                  ;; -Wall/-Werror does not report an unused binding while
                  ;; preserving Clojure truthiness for scalar values.
                  :truth (str "(sizeof(" name ") >= 0 && "
                              (if (or (nil? value) (false? value)) "0" "1")
                              ")")}}))

(defn c-backend-runtime-write-source
  [descriptor indent]
  (let [padding (apply str (repeat indent "  "))
        name (:name descriptor)
        length (:length descriptor)]
    (str padding "fwrite(" name ", 1, "
         (if (nil? length) (str "sizeof(" name ")") length)
         ", stdout);\n")))

(defn c-backend-runtime-test-source
  [instruction env]
  (case (:op instruction)
    :literal (if (or (nil? (:value instruction))
                     (false? (:value instruction))) "0" "1")
    :quote (if (or (nil? (:value instruction))
                   (false? (:value instruction))) "0" "1")
    :local (get-in env [(:name instruction) :truth] "0")
    "0"))

(declare c-backend-runtime-value-source)
(declare c-backend-runtime-instruction-source)

(defn c-backend-runtime-value-source
  [instruction counter indent env]
  (let [padding (apply str (repeat indent "  "))
        op (:op instruction)]
    (cond
      (#{:literal :quote} op)
      (let [{:keys [source descriptor]}
            (c-backend-runtime-value-declaration instruction counter indent)]
        (str source (c-backend-runtime-write-source descriptor indent)))
      (= :local op)
      (c-backend-runtime-write-source (get env (:name instruction)) indent)
      (= :builtin-call op)
      (if (= 'str (:function instruction))
        ;; `str` is a byte-string concatenation at the runtime boundary.  Each
        ;; operand writes directly to stdout in sequence, so no separator is
        ;; introduced and embedded NUL/UTF-8 bytes remain lossless.
        (apply str
               (map #(c-backend-runtime-value-source % counter indent env)
                    (:args instruction)))
        "")
      (= :if op)
      (str padding "if (" (c-backend-runtime-test-source (:test instruction) env)
           ") {\n"
           (c-backend-runtime-value-source (:then instruction) counter
                                           (inc indent) env)
           padding "} else {\n"
           (c-backend-runtime-value-source (:else instruction) counter
                                           (inc indent) env)
           padding "}\n")
      (= :let op)
      (let [binding-state
            (reduce (fn [state {:keys [name expr]}]
                      (let [prior-source (:source state)
                            prior-env (:env state)
                            {:keys [source descriptor]}
                            (c-backend-runtime-value-declaration
                             expr counter indent)]
                        {:source (str prior-source
                                      ;; Bindings evaluate to scalar literals;
                                      ;; declaration is enough to make later
                                      ;; local references runtime writes.
                                      source)
                         :env (assoc prior-env name descriptor)}))
                    {:source "" :env env}
                    (:bindings instruction))]
        (str (:source binding-state)
             (c-backend-runtime-value-source
              (first (:body instruction)) counter indent (:env binding-state))))
      :else "")))

(defn c-backend-runtime-instruction-source
  ([instruction counter indent]
   (c-backend-runtime-instruction-source instruction counter indent {}))
  ([instruction counter indent env]
   (let [padding (apply str (repeat indent "  "))
         op (:op instruction)]
     (cond
       (#{:literal :quote :local} op) ""
       (= :println op)
       (str (apply str
                   (map-indexed
                    (fn [index arg]
                      (str (when (pos? index)
                             (c-backend-runtime-byte-array-source
                              (str "gravity_space_" (swap! counter inc))
                              [32]))
                           (c-backend-runtime-value-source
                            arg counter indent env)))
                    (:args instruction)))
            padding
            (c-backend-runtime-byte-array-source
             (str "gravity_newline_" (swap! counter inc)) [10]))
       (= :do op)
       (apply str
              (map #(c-backend-runtime-instruction-source % counter indent env)
                   (:body instruction)))
       (= :if op)
       (str padding "if (" (c-backend-runtime-test-source (:test instruction) env)
            ") {\n"
            (c-backend-runtime-instruction-source (:then instruction) counter
                                                   (inc indent) env)
            padding "} else {\n"
            (c-backend-runtime-instruction-source (:else instruction) counter
                                                   (inc indent) env)
            padding "}\n")
       (= :let op)
       (let [binding-state
             (reduce (fn [state {:keys [name expr]}]
                       (let [prior-source (:source state)
                             prior-env (:env state)
                             {:keys [source descriptor]}
                             (c-backend-runtime-value-declaration
                              expr counter indent)]
                         {:source (str prior-source source)
                          :env (assoc prior-env name descriptor)}))
                     {:source "" :env env}
                     (:bindings instruction))]
         (str (:source binding-state)
              (apply str
                     (map #(c-backend-runtime-instruction-source
                            % counter indent (:env binding-state))
                          (:body instruction)))))
       :else ""))))

(defn c-backend-runtime-source
  "Emit C that performs the instruction semantics at process runtime.  Each
  scalar literal is a byte array written by an individual fwrite call, so a
  source edit changes the generated runtime program without collapsing the
  whole result into a compile-time stdout string."
  [plan]
  (let [counter (atom 0)
        main (get-in plan [:functions (:entrypoint plan)])]
    (str "#include <stdio.h>\n\n"
         "int main(void) {\n"
         (apply str
                (map #(c-backend-runtime-instruction-source % counter 1 {})
                     (:instructions main)))
         "  return 0;\n"
         "}\n")))

(defn c-backend-source
  [stdout]
  (str "#include <stdio.h>\n\n"
       "int main(void) {\n"
       "  static const unsigned char gravity_output[] = \""
       (c-backend-c-escape stdout) "\";\n"
       "  fwrite(gravity_output, 1, sizeof(gravity_output) - 1, stdout);\n"
       "  return 0;\n"
       "}\n"))

(defn c-backend-run-cc!
  ([c-source-path executable-path source-path target]
   (c-backend-run-cc! c-source-path executable-path source-path target false))
  ([c-source-path executable-path source-path target execute?]
  (let [stdout-file (java.io.File/createTempFile "gravity-c-cc-stdout-" ".txt")
        stderr-file (java.io.File/createTempFile "gravity-c-cc-stderr-" ".txt")
        pb (ProcessBuilder.
            ^java.util.List
            ["/usr/bin/cc" "-std=c11" "-Wall" "-Werror"
             (str c-source-path) "-o" (str executable-path)])]
    (try
      (.redirectOutput pb stdout-file)
      (.redirectError pb stderr-file)
      (let [process (.start pb)]
        (.waitFor process 60000 java.util.concurrent.TimeUnit/MILLISECONDS)
        (let [result {:exit (.exitValue process)
                      :out (if (.exists stdout-file) (slurp stdout-file) "")
                      :err (if (.exists stderr-file) (slurp stderr-file) "")}]
          (when-not (zero? (:exit result))
            (c-backend-fail! "B2-DIALECT"
                             "host C compiler rejected generated C11 source"
                             source-path target nil
                             {:compiler "/usr/bin/cc"
                              :compile-result result
                              :missing-fact :c11-compiler-acceptance}))
          ;; The compiler process itself normally writes no stdout.  Runtime-
          ;; derived lowering opts into executing the emitted program here so
          ;; callers can compare its result with the stage2 runtime record.
          (if-not execute?
            result
            (let [run-stdout-file
                (java.io.File/createTempFile
                 "gravity-c-runtime-stdout-" ".txt")
                run-stderr-file
                (java.io.File/createTempFile
                 "gravity-c-runtime-stderr-" ".txt")
                run-pb (ProcessBuilder. [(str executable-path)])]
            (try
              (.redirectOutput run-pb run-stdout-file)
              (.redirectError run-pb run-stderr-file)
              (let [run-process (.start run-pb)]
                (.waitFor run-process 60000
                          java.util.concurrent.TimeUnit/MILLISECONDS)
                (let [run-result {:exit (.exitValue run-process)
                                  :out (if (.exists run-stdout-file)
                                         (slurp run-stdout-file)
                                         "")
                                  :err (if (.exists run-stderr-file)
                                         (slurp run-stderr-file)
                                         "")}]
                  (when-not (zero? (:exit run-result))
                    (c-backend-fail!
                     "B2-DIALECT"
                     "generated C executable failed at runtime"
                     source-path target nil
                     {:compiler "/usr/bin/cc"
                      :runtime-result run-result
                      :missing-fact :c-runtime-execution}))
                  (assoc result
                         :compile-out (:out result)
                         :compile-err (:err result)
                         :runtime-out (:out run-result)
                         :runtime-err (:err run-result)
                         :runtime-exit (:exit run-result))))
              (finally
                (.delete run-stdout-file)
                (.delete run-stderr-file)))))))
      (catch clojure.lang.ExceptionInfo ex
        (throw ex))
      (catch Exception ex
        (c-backend-fail! "B2-DIALECT"
                         "host C compiler is unavailable"
                         source-path target nil
                         {:compiler "/usr/bin/cc"
                          :cause-message (.getMessage ex)
                          :missing-fact :c11-compiler}))
      (finally
        (.delete stdout-file)
        (.delete stderr-file))))))

(defn c-backend-source-artifact
  "Lower a source unit through the genuine stage0 plan into a C artifact.

  `:compile?` is intentionally opt-in.  Without it this function performs no
  host compiler invocation and only returns deterministic lowering artifacts.
  `:emit-dir` writes the C source and three EDN sidecars when requested."
  ([source-path source-text]
   (c-backend-source-artifact source-path source-text {}))
  ([source-path source-text {:keys [target dialect emit-dir compile?
                                    lowering-mode runtime-derived?
                                    executable-path c-source-path
                                    manifest-path source-map-path
                                    provenance-path]
                             :or {target :c-hosted
                                  dialect :c11
                                  compile? false
                                  lowering-mode :verified-stage0-output}}]
   (let [target (cond
                  (keyword? target) target
                  (string? target) (keyword (str/lower-case target))
                  :else target)
         dialect (cond
                   (keyword? dialect) dialect
                   (string? dialect) (keyword (str/lower-case dialect))
                   :else dialect)]
     (when-not (contains? c-backend-supported-dialects dialect)
       (c-backend-fail! "C14-TARGET"
                        "C backend dialect is unsupported"
                        source-path target nil
                        {:dialect dialect
                         :supported-dialects (vec (sort c-backend-supported-dialects))
                         :missing-fact :c-dialect}))
     (let [runtime-derived? (or (= :runtime-derived lowering-mode)
                                (= true runtime-derived?))
           shared-packet
           (when runtime-derived?
             (stage2-runtime-derived-packet
              source-path source-text target
              {:validate-plan!
               (fn [candidate-plan]
                 (when-not
                  (and (= :gravity/stage2-hosted-core-compiled-plan
                          (:kind candidate-plan))
                       (= :p15-s23-stage2-plan-emitter
                          (get-in candidate-plan
                                  [:compiler :rule-source]))
                       (map? (:functions candidate-plan))
                       (symbol? (:entrypoint candidate-plan))
                       (contains? (:functions candidate-plan)
                                  (:entrypoint candidate-plan))
                       (vector?
                        (get-in candidate-plan
                                [:functions (:entrypoint candidate-plan)
                                 :instructions])))
                   (c-backend-fail!
                    "B2-UNSUPPORTED"
                    "Gravity stage2 plan emitter returned a mismatched plan"
                    source-path target candidate-plan
                    {:compiler-stage :p15-s23-stage2-plan-emitter
                     :observed-plan-kind (:kind candidate-plan)
                     :observed-rule-source
                     (get-in candidate-plan [:compiler :rule-source])
                     :p15-diagnostic "P15S23Q003"
                     :missing-fact :stage2-plan-integrity}))
                 (c-backend-validate-plan!
                  source-path target candidate-plan)
                 (c-backend-validate-runtime-plan!
                  source-path target candidate-plan))}))
           macro-artifact
           (when-not runtime-derived?
             (macro-source-artifact source-path source-text))
           module
           (when-not runtime-derived?
             (assoc (:module macro-artifact)
                    :forms (:expanded-forms macro-artifact)))
           stage2-rule
           (:stage2-plan-emitter-rule shared-packet)
           stage2-compiler-artifact-record
           (:stage2-compiler-artifact-record shared-packet)
           _ (when runtime-derived?
               (when-not
                (p15-s23-stage2-compiler-artifact-record-authentic?
                 stage2-compiler-artifact-record)
                 (c-backend-fail!
                  "C14-INPUT"
                  "C backend received inconsistent stage2 compiler artifact metadata"
                  source-path target stage2-compiler-artifact-record
                  {:missing-fact
                   :authenticated-stage2-compiler-artifact-record})))
           stage2-compiler-artifact-source-path
           (get-in shared-packet
                   [:provenance :actual-paths
                    :stage2-expression-lowering-source])
           stage2-runtime-rule (:stage2-runtime-rule shared-packet)
           stage2-driver-rule (:stage2-compiler-driver-rule shared-packet)
           _ (when (and runtime-derived?
                        (not
                         (p15-s23-closed-runtime-packet-authentic?
                          shared-packet
                          (p15-s23-closed-runtime-packet-context
                           source-path source-text target))))
               (c-backend-fail!
                "C14-INPUT"
                "C backend received an unauthenticated closed runtime execution"
                source-path target shared-packet
                {:missing-fact :authenticated-closed-runtime-execution}))
           plan (if runtime-derived?
                  (:plan shared-packet)
                  (stage0-compiled-core-plan source-path source-text module))
           _ (when (and runtime-derived?
                        (not
                         (p15-s23-stage2-compiler-artifact-record-matches-plan?
                          stage2-compiler-artifact-record plan)))
               (c-backend-fail!
                "C14-INPUT"
                "C backend received a stage2 compiler record that does not match its plan"
                source-path target stage2-compiler-artifact-record
                {:missing-fact
                 :authenticated-stage2-compiler-artifact-record}))
           _ (when-not runtime-derived?
               (c-backend-validate-plan! source-path target plan))
           stage2-driver-run
           (:stage2-compiler-driver-record shared-packet)
           stage2-runtime-execution
           (:stage2-runtime-execution-record shared-packet)
           closed-plan-validation
           (:closed-plan-validation-record shared-packet)
           closed-plan-execution
           (:closed-plan-execution-record shared-packet)
           closed-plan-invocation
           (:closed-plan-invocation-record shared-packet)
           closed-plan-target-record
           (when runtime-derived?
             (p15-s23-closed-runtime-target-record shared-packet))
           _ (when (and runtime-derived?
                        (not
                         (p15-s23-closed-runtime-target-record-authentic?
                          closed-plan-target-record
                          (p15-s23-closed-runtime-target-context
                           shared-packet))))
               (c-backend-fail!
                "C14-INPUT"
                "C backend received an unauthenticated closed runtime target record"
                source-path target closed-plan-target-record
                {:missing-fact :authenticated-closed-runtime-target-record}))
           clojure-stage0-output
           (if runtime-derived?
             (:reference-output shared-packet)
             (try
               (execute-stage0-compiled-plan plan)
               (catch clojure.lang.ExceptionInfo ex
                 (throw ex))
               (catch Exception ex
                 (c-backend-fail!
                  "B2-UNSUPPORTED"
                  "stage0 plan could not be represented by the C backend"
                  source-path target nil
                  {:cause-message (.getMessage ex)
                   :missing-fact :closed-c-runtime-semantics}))))
           stdout (if runtime-derived?
                    (:stdout stage2-runtime-execution)
                    clojure-stage0-output)
           c-source (if runtime-derived?
                      (c-backend-runtime-source plan)
                      (c-backend-source stdout))
           source-hash (str "sha256:" (sha256-hex source-text))
           plan-input (select-keys plan [:kind :entrypoint :functions
                                         :instruction-summary :effect-summary])
           plan-hash (c4-artifact-id (c-backend-canonical-value plan-input))
           stage2-runtime-execution-record
           (when runtime-derived?
             ;; The executor record's native plan id retains source-path
             ;; provenance.  Artifacts use the already path-neutral plan hash
             ;; for deterministic cross-root identity.
             (assoc stage2-runtime-execution :plan-id plan-hash))
           c-source-hash (str "sha256:" (sha256-hex c-source))
           output-hash (str "sha256:" (sha256-hex stdout))
           source-map {:kind :gravity/c-backend-source-map
                       :schema-version "gravity.c.source-map/v1"
                       :entries [{:generated-line 4
                                  :generated-column 3
                                  :source-path source-path
                                  :source-span (source-span source-path 0)
                                  :origin-chain [{:kind :source-unit
                                                  :path source-path}]}]}
           source-map-hash
           (str "sha256:" (sha256-hex
                            (pr-str
                             (c-backend-canonical-value
                              (update source-map :entries
                                      (fn [entries]
                                        (mapv (fn [entry]
                                                (-> entry
                                                    (dissoc :source-path)
                                                    (update :source-span
                                                            #(when %
                                                               (dissoc % :source)))
                                                    (update :origin-chain
                                                            (fn [chain]
                                                              (mapv #(dissoc % :path)
                                                                    chain)))))
                                              entries)))))))
           manifest-input
           (cond-> {:kind :gravity/c-backend-manifest
                    :schema-version "gravity.c.backend-manifest/v1"
                    :backend :c
                    :dialect dialect
                    :target target
                    :input-plan-kind (:kind plan)
                    :input-plan-hash plan-hash
                    :source-content-hash source-hash
                    :c-source-hash c-source-hash
                    :stdout-hash output-hash
                    :instruction-summary (:instruction-summary plan)
                    :effect-summary (:effect-summary plan)
                    :lowering-strategy (if runtime-derived?
                                         :runtime-derived-instruction-lowering
                                         :verified-stage0-output-lowering)
                    :runtime :hosted-libc-stdout
                    :compile-time-evaluated? (not runtime-derived?)
                    :runtime-derived? runtime-derived?
                    :target-eligibility
                    (when runtime-derived?
                      (:target-eligibility shared-packet))
                    :oracle (when runtime-derived?
                              {:kind :gravity-stage2-runtime-execution
                               :compiler-driver-engine
                               (:driver-engine stage2-driver-rule)
                               :compiler-driver-rule-hash
                               (:driver-rule-hash stage2-driver-rule)
                               :runtime-engine
                               (:runtime-engine stage2-runtime-rule)
                               :runtime-kernel-engine
                               (:runtime-kernel-engine stage2-runtime-rule)
                               :runtime-rule-hash
                               (:runtime-rule-hash stage2-runtime-rule)
                               :runtime-kernel-rule-hash
                               (:runtime-kernel-rule-hash stage2-runtime-rule)
                               :runtime-artifact-hash
                               (:runtime-artifact-hash stage2-runtime-rule)
                               :runtime-artifact-function
                               (:runtime-artifact-function stage2-runtime-rule)
                               :runtime-artifact-concat-function
                               (:runtime-artifact-concat-function
                                stage2-runtime-rule)
                               :runtime-artifact-println-function
                               (:runtime-artifact-println-function
                                stage2-runtime-rule)
                               :runtime-artifact-println-two-function
                               (:runtime-artifact-println-two-function
                                stage2-runtime-rule)
                               :runtime-artifact-println-over-two-boundary
