                          (when runtime-derived?
                            (:runtime-artifact-source-path stage2-runtime-rule))
                          :runtime-artifact-source
                          (when runtime-derived?
                            {:kind :gravity-source
                             :sha256
                             (:runtime-artifact-source-content-hash
                              stage2-runtime-rule)
                             :artifact-hash
                             (:runtime-artifact-hash stage2-runtime-rule)
                             :function
                             (:runtime-artifact-function stage2-runtime-rule)
                             :concat-function
                             (:runtime-artifact-concat-function
                              stage2-runtime-rule)
                             :println-function
                             (:runtime-artifact-println-function
                              stage2-runtime-rule)
                             :println-two-function
                             (:runtime-artifact-println-two-function
                              stage2-runtime-rule)
                             :println-over-two-boundary
                             (:runtime-artifact-println-over-two-boundary
                              stage2-runtime-rule)
                             :generic-bridge-residual?
                             (:runtime-artifact-generic-bridge-residual?
                              stage2-runtime-rule)})
                          :runtime-artifact-host-runner
                          (when runtime-derived?
                            :gravity-stage2-runtime-artifact-host-runner)
                          :compiler-stage
                          (when runtime-derived?
                            :p15-s23-stage2-compiler-driver)
                          :expression-lowering-artifact
                          (when runtime-derived?
                            (dissoc stage2-compiler-artifact-record
                                    :source-path))
                          :compiler-engine
                          (when runtime-derived?
                            (:driver-engine stage2-driver-rule))
                          :compiler-driver-rule-hash
                          (when runtime-derived?
                            (:driver-rule-hash stage2-driver-rule))
                          :compiler-driver-rule-source
                          (when runtime-derived?
                            (:driver-rule-source stage2-driver-rule))
                          :stage2-compiler-driver-used?
                          (when runtime-derived? true)
                          :stage2-compiler-driver-record
                          (when runtime-derived? stage2-driver-run)
                          :runtime-rule-source-path
                          (when runtime-derived?
                            (:runtime-source-path stage2-runtime-rule))
                          :runtime-rule-source
                          (when runtime-derived?
                            (:runtime-rule-source stage2-runtime-rule))
                          :stage2-runtime-execution-record
                          (when runtime-derived?
                            stage2-runtime-execution-record)
                          :clojure-instruction-runner-comparison
                          {:boundary (if runtime-derived?
                                       :comparison-only
                                       :not-used)
                           :authoritative-runtime? false
                           :stdout clojure-stage0-output}
                          :c-source c-source
                          :c-source-hash c-source-hash
                          :manifest (assoc manifest-input
                                            :manifest-hash manifest-hash)
                          :manifest-hash manifest-hash
                          :source-map (assoc source-map
                                              :source-map-hash source-map-hash)
                          :source-map-hash source-map-hash
                          :provenance
                          (cond-> (assoc provenance
                                         :provenance-hash provenance-hash)
                            runtime-derived?
                            (assoc :actual-paths
                                   {:stage2-expression-lowering-source
                                    stage2-compiler-artifact-source-path
                                    :stage2-runtime-artifact-source
                                    (:runtime-artifact-source-path
                                     stage2-runtime-rule)}))
                          :provenance-hash provenance-hash
                          :safety {:mode (get-in plan [:module :safety])
                                   :unsafe-islands []
                                   :status :preserved}
                          :capabilities (get-in plan [:module :capabilities])
                          :seed-boundary {:clojure-seed-boundary? true
                                          :self-hosted? false
                                          :final-release? false}
                          :diagnostics []}
           artifact (assoc artifact-base
                           :artifact-id (c4-artifact-id
                                         (c-backend-canonical-value
                                          identity-input)))
           emit-dir (when emit-dir (str emit-dir))
           c-source-path (or c-source-path
                             (when emit-dir (str emit-dir "/program.c")))
           executable-path (or executable-path
                               (when emit-dir (str emit-dir "/program")))
           manifest-path (or manifest-path
                            (when emit-dir (str emit-dir "/manifest.edn")))
           source-map-path (or source-map-path
                              (when emit-dir (str emit-dir "/source-map.edn")))
           provenance-path (or provenance-path
                              (when emit-dir (str emit-dir "/provenance.edn")))]
       (c-backend-validate-output-paths!
        source-path target
        [[:emit-dir emit-dir]
         [:c-source c-source-path]
         [:executable executable-path]
         [:manifest manifest-path]
         [:source-map source-map-path]
         [:provenance provenance-path]])
       (when emit-dir (p18-ensure-dir! emit-dir))
       (when c-source-path (spit c-source-path c-source))
       (when manifest-path (spit manifest-path (pr-str (:manifest artifact))))
       (when source-map-path (spit source-map-path (pr-str (:source-map artifact))))
       (when provenance-path (spit provenance-path (pr-str (:provenance artifact))))
       (let [compile-result
             (when compile?
               (when-not (and c-source-path executable-path)
                 (c-backend-fail! "C14-INPUT"
                                  "C backend compilation requires explicit output paths"
                                  source-path target nil
                                  {:missing-fields [:c-source-path :executable-path]}))
               (c-backend-run-cc! c-source-path executable-path source-path
                                   target runtime-derived?))]
         (when (and runtime-derived?
                    compile?
                    (not= (:runtime-out compile-result)
                          (:stdout stage2-runtime-execution)))
           (p15-s23-stage2-runtime-executor-fail!
            "P15S23X003"
            source-path
            compile-result
            {:requested-source source-path
             :target target
             :runtime-engine (:runtime-engine stage2-runtime-rule)
             :runtime-rule-hash (:runtime-rule-hash stage2-runtime-rule)
             :stage2-runtime-output (:stdout stage2-runtime-execution)
             :c-executable-output (:runtime-out compile-result)
             :p15-diagnostic "P15S23X003"
             :missing-fact :c-runtime-execution-equivalence}))
         (cond-> (assoc artifact
                        :emitted-files (cond-> {}
                                         c-source-path (assoc :c-source c-source-path)
                                         manifest-path (assoc :manifest manifest-path)
                                         source-map-path (assoc :source-map source-map-path)
                                         provenance-path (assoc :provenance provenance-path))
                        :compile-requested? (boolean compile?)
                        :executable-path executable-path)
           compile? (assoc :compiled-executable? true)
           (and compile? runtime-derived?)
           (assoc :compiled-execution-output
                  (:runtime-out compile-result))))))))

(defn c-backend-file-artifact
  ([path] (c-backend-file-artifact path {}))
  ([path options]
   (c-backend-source-artifact path (read-gravity-source-text path) options)))

;; ---------------------------------------------------------------------------
;; Hosted JavaScript / TypeScript target (Node 20, ES2022 ESM)
;;
;; This target deliberately shares the authoritative stage2 compiler-driver,
;; plan-emitter, and Gravity-authored runtime packet used by runtime-derived C.
;; The C artifact is used only as a validated packet carrier: the JavaScript
;; emitter consumes its genuine stage2 instruction plan and emits executable
;; ESM statements.  Target bytes never contain checkout or output paths.

(def js-ts-backend-target :js-ts)
(def js-ts-backend-target-aliases #{:js :js-ts})
(def js-ts-backend-runtime :node20)
(def js-ts-backend-ecmascript :es2022)
(def js-ts-backend-module-format :esm)

(defn js-ts-backend-canonical-target
  [target]
  (let [target (cond
                 (keyword? target) target
                 (string? target) (keyword (str/lower-case target))
                 :else target)]
    (if (contains? js-ts-backend-target-aliases target)
      js-ts-backend-target
      target)))

(defn js-ts-backend-fail!
  [id message source-path subject extra]
  (fail! id message
         (merge {:severity :error
                 :stage :js-ts-backend-lowering
                 :diagnostic-family
                 (cond
                   (str/starts-with? id "B6") :b6-js-ts-backend
                   (str/starts-with? id "B14") :b14-backend-conformance
                   :else :c14-target-lowering)
                 :backend :gravity.backend/js-ts
                 :target js-ts-backend-target
                 :source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :primary {:span (or (:source-span subject)
                                     (source-span source-path 0))}
                 :facts {:instruction (when (map? subject) (:op subject))
                         :runtime js-ts-backend-runtime
                         :ecmascript js-ts-backend-ecmascript
                         :module-format js-ts-backend-module-format}
                 :remediation
                 "Use --target js or --target js-ts with the closed Node 20 ES2022 ESM hosted subset."}
                extra)))

(defn js-ts-backend-validate-plan!
  "Apply the JS/TS-specific closed-surface rules after the shared stage2/C
  packet has validated instruction shape.  Variadic println remains bounded by
  the shared closed-plan node limit and lowers to ordered byte writes."
  [source-path plan]
  ;; Source-path and plan remain explicit arguments so future target-specific
  ;; representation checks can fail at this boundary without changing callers.
  (when-not (and (string? source-path) (map? plan))
    (js-ts-backend-fail!
     "C14-INPUT" "JS/TS backend requires a source-bound stage2 plan"
     source-path plan {:missing-fact :source-bound-stage2-plan}))
  :passed)

(defn js-ts-backend-bytes-source
  [name bytes indent]
  (let [padding (apply str (repeat indent "  "))]
    (str padding "const " name " = new Uint8Array(["
         (str/join "," bytes) "]);\n")))

(defn js-ts-backend-value-declaration
  [instruction counter indent]
  (let [name (str "gravityValue" (swap! counter inc))
        value (:value instruction)
        bytes (c-backend-runtime-bytes value)]
    {:source (js-ts-backend-bytes-source name bytes indent)
     :descriptor {:name name
                  :truth (not (or (nil? value) (false? value)))}}))

(defn js-ts-backend-write-source
  [descriptor indent]
  (let [padding (apply str (repeat indent "  "))]
    (str padding "stdout.write(" (:name descriptor) ");\n")))

(defn js-ts-backend-test-source
  [instruction env]
  (case (:op instruction)
    :literal (if (or (nil? (:value instruction))
                     (false? (:value instruction))) "false" "true")
    :quote (if (or (nil? (:value instruction))
                   (false? (:value instruction))) "false" "true")
    :local (if (get-in env [(:name instruction) :truth]) "true" "false")
    "false"))

(declare js-ts-backend-value-source)
(declare js-ts-backend-instruction-source)

(defn js-ts-backend-value-source
  [instruction counter indent env]
  (let [padding (apply str (repeat indent "  "))
        op (:op instruction)]
    (cond
      (#{:literal :quote} op)
      (let [{:keys [source descriptor]}
            (js-ts-backend-value-declaration instruction counter indent)]
        (str source (js-ts-backend-write-source descriptor indent)))

      (= :local op)
      (js-ts-backend-write-source (get env (:name instruction)) indent)

      (= :builtin-call op)
      (apply str
             (map #(js-ts-backend-value-source % counter indent env)
                  (:args instruction)))

      (= :if op)
      (str padding "if ("
           (js-ts-backend-test-source (:test instruction) env)
           ") {\n"
           (js-ts-backend-value-source (:then instruction) counter
                                       (inc indent) env)
           padding "} else {\n"
           (js-ts-backend-value-source (:else instruction) counter
                                       (inc indent) env)
           padding "}\n")

      (= :let op)
      (let [binding-state
            (reduce (fn [state {:keys [name expr]}]
                      (let [{:keys [source descriptor]}
                            (js-ts-backend-value-declaration expr counter indent)]
                        {:source (str (:source state) source)
                         :env (assoc (:env state) name descriptor)}))
                    {:source "" :env env}
                    (:bindings instruction))]
        (str (:source binding-state)
             (js-ts-backend-value-source
              (first (:body instruction)) counter indent
              (:env binding-state))))

      :else "")))

(defn js-ts-backend-instruction-source
  ([instruction counter indent]
   (js-ts-backend-instruction-source instruction counter indent {}))
  ([instruction counter indent env]
   (let [padding (apply str (repeat indent "  "))
         op (:op instruction)]
     (cond
       (#{:literal :quote :local} op) ""

       (= :println op)
       (str (apply str
                   (map-indexed
                    (fn [index argument]
                      (str (when (pos? index)
                             (let [name (str "gravitySpace"
                                             (swap! counter inc))]
                               (str (js-ts-backend-bytes-source
                                     name [32] indent)
                                    padding "stdout.write(" name ");\n")))
                           (js-ts-backend-value-source
                            argument counter indent env)))
                    (:args instruction)))
            (let [name (str "gravityNewline" (swap! counter inc))]
              (str (js-ts-backend-bytes-source name [10] indent)
                   padding "stdout.write(" name ");\n")))

       (= :do op)
       (apply str
              (map #(js-ts-backend-instruction-source % counter indent env)
                   (:body instruction)))

       (= :if op)
       (str padding "if ("
            (js-ts-backend-test-source (:test instruction) env)
            ") {\n"
            (js-ts-backend-instruction-source (:then instruction) counter
                                              (inc indent) env)
            padding "} else {\n"
            (js-ts-backend-instruction-source (:else instruction) counter
                                              (inc indent) env)
            padding "}\n")

       (= :let op)
       (let [binding-state
             (reduce (fn [state {:keys [name expr]}]
                       (let [{:keys [source descriptor]}
                             (js-ts-backend-value-declaration
                              expr counter indent)]
                         {:source (str (:source state) source)
                          :env (assoc (:env state) name descriptor)}))
                     {:source "" :env env}
                     (:bindings instruction))]
         (str (:source binding-state)
              (apply str
                     (map #(js-ts-backend-instruction-source
                            % counter indent (:env binding-state))
                          (:body instruction)))))

       :else ""))))

(defn js-ts-backend-source
  [plan]
  (let [counter (atom 0)
        main (get-in plan [:functions (:entrypoint plan)])
        writes-stdout? (pos? (get-in plan [:instruction-summary :println] 0))]
    (str "#!/usr/bin/env node\n"
         (when writes-stdout?
           "import { stdout } from \"node:process\";\n")
         "\n"
         (apply str
                (map #(js-ts-backend-instruction-source % counter 0 {})
                     (:instructions main)))
         "//# sourceMappingURL=program.mjs.map\n")))

(def js-ts-backend-declaration-source
  "// Generated Gravity hosted entrypoint; no exported API in this slice.\nexport {};\n")

(defn js-ts-backend-json-string
  [value]
  (str "\""
       (apply str
              (map (fn [ch]
                     (case ch
                       \" "\\\""
                       \\ "\\\\"
                       \backspace "\\b"
                       \formfeed "\\f"
                       \newline "\\n"
                       \return "\\r"
                       \tab "\\t"
                       (if (< (int ch) 32)
                         (format "\\u%04x" (int ch))
                         (str ch))))
                   (str value)))
       "\""))

(defn js-ts-backend-source-map-source
  "Emit a deterministic v3 source map.  Generated lines are conservatively
  anchored at the beginning of the source unit, while the Gravity extension
  records the path-neutral content identity and explicit stage2 origin chain.
  The source text itself is embedded so consumers can recover exact line and
  Unicode content without consulting a checkout path."
  [javascript source-text]
  (let [generated-lines (max 1 (count (str/split javascript #"\n" -1)))
        mappings (str/join ";" (repeat generated-lines "AAAA"))
        source-hash (str "sha256:" (sha256-hex source-text))
        entries
        (str/join
         ","
         (map (fn [line]
                (str "{\"generatedLine\":" line
                     ",\"generatedColumn\":0,\"sourceLine\":1"
                     ",\"sourceColumn\":0,\"originChain\":["
                     "\"source-unit\",\"stage2-plan-emitter\","
                     "\"stage2-compiler-driver\",\"js-ts-lowering\"]}"))
              (range 1 (inc generated-lines))))]
    (str "{\"version\":3,\"file\":\"program.mjs\","
         "\"sources\":[\"gravity-source\"],\"sourcesContent\":["
         (js-ts-backend-json-string source-text)
         "],\"names\":[],\"mappings\":"
         (js-ts-backend-json-string mappings)
         ",\"x_gravity\":{\"sourceContentHash\":"
         (js-ts-backend-json-string source-hash)
         ",\"sourceKind\":\"co-canonical-gravity-source\","
         "\"coverage\":\"source-unit-only\","
         "\"perFormOriginPreserved\":false,"
         "\"generatedOrigins\":[" entries "]}}\n")))

(defn js-ts-backend-package-source
  [writes-stdout?]
  (str "{\"name\":\"gravity-js-ts-artifact\",\"private\":true,"
       "\"type\":\"module\",\"sideEffects\":"
       (if writes-stdout? "true" "false")
       ",\"engines\":{\"node\":\">=20 <21\"}}\n"))

(defn js-ts-backend-validate-manifest!
  ([source-path manifest]
   (js-ts-backend-fail!
    "B6-MANIFEST"
    "JS/TS manifest validation requires trusted runtime context"
    source-path manifest
    {:missing-fact :closed-runtime-validation-context}))
  ([source-path manifest closed-runtime-context]
  (let [required-top-level
        [:artifact :schema-version :backend :profile :target :module :emits
         :content-hashes :input :effects :capabilities :safety :host-globals
         :numeric-representation :nullish-policy :exception-policy
         :typescript-compiler :conformance :closed-plan-runtime
         :manifest-hash
         :clojure-seed-boundary?
         :self-hosted? :release-grade? :diagnostics]
        missing (vec (remove #(contains? manifest %) required-top-level))
        runtime-version (get-in manifest [:target :runtime-version])
        valid-target?
        (and (string? runtime-version)
             (boolean (re-matches #"v20(?:\.[0-9]+){1,2}" runtime-version))
             (= {:runtime js-ts-backend-runtime
                 :runtime-version runtime-version
                 :ecmascript js-ts-backend-ecmascript
                 :module-format js-ts-backend-module-format}
                (:target manifest)))
        valid-hashes?
        (and (= #{:javascript :typescript-declarations :source-map
                  :package-metadata}
                (set (keys (:content-hashes manifest))))
             (every? #(and (string? %)
                           (boolean
                            (re-matches #"sha256:[0-9a-f]{64}" %)))
                     (vals (:content-hashes manifest))))
        manifest-hash-valid?
        (and (string? (:manifest-hash manifest))
             (= (:manifest-hash manifest)
                (str "sha256:"
                     (sha256-hex
                      (pr-str
                       (c-backend-canonical-value
                        (update (dissoc manifest :manifest-hash)
                                :closed-plan-runtime
                                p15-s23-closed-runtime-target-semantic-record)))))))
        writes-stdout? (true? (get-in manifest [:module :side-effects]))
        stdout-authorized?
        (contains? (set (:capabilities manifest)) :io/stdout)
        host-global-valid?
        (= (if writes-stdout?
             [{:module "node:process"
               :symbol :stdout
               :effect :io/write
               :capability :io/stdout
               :representation :uint8array-bytes}]
             [])
           (:host-globals manifest))
        input (:input manifest)
        closed-plan-runtime (:closed-plan-runtime manifest)
        eligibility (:target-eligibility input)
        source-declared-target (:source-declared-target input)
        valid-input?
        (and (= #{:source-content-hash :source-declared-target
                  :requested-backend-target :target-eligibility
                  :stage2-plan-hash :compiler-driver-rule-hash
                  :runtime-rule-hash :runtime-artifact-hash
                  :expression-lowering-artifact-hash
                  :expression-lowering-source-content-hash
                  :expression-lowering-semantic-hash
                  :expression-lowering-invoked?
                  :expression-lowering-generic-bridge-residual?
                  :plan-assembly-function :plan-assembly-artifact-hash
                  :plan-assembly-source-content-hash
                  :plan-assembly-semantic-hash :plan-assembly-invoked?
                  :plan-assembly-generic-bridge-residual?}
                (set (keys input)))
             (every? #(boolean
                       (re-matches #"sha256:[0-9a-f]{64}" (str %)))
                     [(:source-content-hash input)
                      (:stage2-plan-hash input)
                      (:expression-lowering-artifact-hash input)
                      (:expression-lowering-source-content-hash input)
                      (:expression-lowering-semantic-hash input)
                      (:plan-assembly-artifact-hash input)
                      (:plan-assembly-source-content-hash input)
                      (:plan-assembly-semantic-hash input)
                      (:compiler-driver-rule-hash input)
                      (:runtime-rule-hash input)
                      (:runtime-artifact-hash input)])
             (true? (:expression-lowering-invoked? input))
             (true? (:expression-lowering-generic-bridge-residual? input))
             (= p15-s23-stage2-compiler-artifact-plan-assembly-function
                (:plan-assembly-function input))
             (= (:expression-lowering-artifact-hash input)
                (:plan-assembly-artifact-hash input))
             (= (:expression-lowering-source-content-hash input)
                (:plan-assembly-source-content-hash input))
             (= (:expression-lowering-semantic-hash input)
                (:plan-assembly-semantic-hash input))
             (true? (:plan-assembly-invoked? input))
             (true? (:plan-assembly-generic-bridge-residual? input))
             (= js-ts-backend-target (:requested-backend-target input))
             (= :accepted (:status eligibility))
             (= source-declared-target
                (:source-declared-target eligibility))
             (= js-ts-backend-target (:requested-target eligibility))
             (or (and (= js-ts-backend-target source-declared-target)
                      (= :source-and-request-agree (:selection eligibility)))
                 (and (= :jvm source-declared-target)
                      (= :explicit-bootstrap-seed-target-override
                         (:selection eligibility))
                      (true? (:bootstrap-seed-target? eligibility)))))]
    (when-not (and (empty? missing)
                   (= :gravity/js-ts-backend-manifest (:artifact manifest))
                   (= 1 (:schema-version manifest))
                   (= :gravity.backend/js-ts (:backend manifest))
                   (= :hosted (:profile manifest))
                   valid-target?
                   (= {:side-effects writes-stdout?
                       :package-boundary :standalone}
                      (:module manifest))
                   (= #{:javascript :typescript-declarations :source-map
                        :package-metadata :manifest :provenance}
                      (set (:emits manifest)))
                   (= 6 (count (:emits manifest)))
                   valid-input?
                   (= #{:declared :inferred :capabilities}
                      (set (keys (:effects manifest))))
                   (set/subset? (get-in manifest [:effects :declared] #{})
                                #{:io/write})
                   (set/subset? (get-in manifest [:effects :inferred] #{})
                                #{:io/write})
                   (set/subset? (get-in manifest [:effects :inferred] #{})
                                (get-in manifest [:effects :declared] #{}))
                   (= writes-stdout?
                      (contains? (get-in manifest [:effects :inferred] #{})
                                 :io/write))
                   (set/subset? (set (:capabilities manifest))
                                #{:io/stdout})
                   (= (set (:capabilities manifest))
                      (set (get-in manifest [:effects :capabilities])))
                   (or (not writes-stdout?)
                       (and (contains? (get-in manifest
                                               [:effects :declared] #{})
                                       :io/write)
                            (contains? (get-in manifest
                                               [:effects :inferred] #{})
                                       :io/write)))
                   (or (not writes-stdout?) stdout-authorized?)
                   host-global-valid?
                   valid-hashes?
                   manifest-hash-valid?
                   (= {:mode :hosted-scalar-spelling
                       :bytes :utf8
                       :lossy-number-lowering? false}
                      (:numeric-representation manifest))
                   (= :no-host-nullish-inputs (:nullish-policy manifest))
                   (= :no-host-exception-boundary-in-slice
                      (:exception-policy manifest))
                   (= {:available? false :required? false
                       :reason :tsc-not-installed}
                      (:typescript-compiler manifest))
                   (= {:node-check :passed
                       :stage2-differential :passed
                       :stdout-byte-exact? true
                       :source-map :partial
                       :source-map-coverage :source-unit-only
                       :per-form-origin-preserved? false
                       :b6-conforming? false}
                      (:conformance manifest))
                   (p15-s23-closed-runtime-target-record-authentic?
                    closed-plan-runtime closed-runtime-context)
                   (= :complete
                      (get-in closed-plan-runtime [:validation :status]))
                   (= 1
                      (get-in closed-plan-runtime
                              [:invocation :invocation-count]))
                   (= :complete
                      (get-in closed-plan-runtime [:execution :status]))
                   (boolean
                    (re-matches #"sha256:[0-9a-f]{64}"
                                (str (:record-hash closed-plan-runtime))))
                   (true? (:clojure-seed-boundary? closed-plan-runtime))
                   (false? (:self-hosted? closed-plan-runtime))
                   (= {:mode :safe :unsafe-islands [] :status :preserved}
                      (:safety manifest))
                   (true? (:clojure-seed-boundary? manifest))
                   (false? (:self-hosted? manifest))
                   (false? (:release-grade? manifest))
                   (= [] (:diagnostics manifest)))
      (js-ts-backend-fail!
       "B6-MANIFEST" "JS/TS artifact manifest is incomplete or contradictory"
       source-path manifest
       {:missing-fields missing
        :target-valid? valid-target?
        :input-valid? valid-input?
        :content-hashes-valid? valid-hashes?
        :manifest-hash-valid? manifest-hash-valid?
        :missing-fact :complete-js-ts-manifest})))
  :passed))

(defn js-ts-backend-run-node-process!
  [arguments source-path diagnostic-id message]
  (let [stdout-file (java.io.File/createTempFile "gravity-js-node-out-" ".bin")
        stderr-file (java.io.File/createTempFile "gravity-js-node-err-" ".txt")
        pb (ProcessBuilder. ^java.util.List (into ["node"] arguments))]
    (try
      (.redirectOutput pb stdout-file)
      (.redirectError pb stderr-file)
      (let [process (.start pb)
            finished? (.waitFor process 60000
                                java.util.concurrent.TimeUnit/MILLISECONDS)]
        (when-not finished?
          (.destroyForcibly process)
          (js-ts-backend-fail!
           diagnostic-id message source-path nil
           {:node-command (into ["node"] arguments)
            :missing-fact :node-process-completion}))
        (let [result {:exit (.exitValue process)
                      :stdout-bytes
                      (vec (map #(bit-and (int %) 0xff)
                                (java.nio.file.Files/readAllBytes
                                 (.toPath stdout-file))))
                      :stderr (if (.exists stderr-file)
                                (slurp stderr-file) "")}]
          (when-not (zero? (:exit result))
            (js-ts-backend-fail!
             diagnostic-id message source-path nil
             {:node-command (into ["node"] arguments)
              :node-result result
              :missing-fact :node20-esm-acceptance}))
          result))
      (catch clojure.lang.ExceptionInfo ex
        (throw ex))
      (catch Exception ex
        (js-ts-backend-fail!
         "B6-TARGET" "Node 20 runtime is unavailable"
         source-path nil
         {:runtime js-ts-backend-runtime
          :cause-message (.getMessage ex)
          :missing-fact :node20-runtime}))
      (finally
        (.delete stdout-file)
        (.delete stderr-file)))))

(defn js-ts-backend-node-version!
  [source-path]
  (let [result (js-ts-backend-run-node-process!
                ["--version"] source-path "B6-TARGET"
                "Node runtime version check failed")
        version (str/trim
                 (String. (byte-array (map byte (:stdout-bytes result)))
                          java.nio.charset.StandardCharsets/UTF_8))]
    (when-not (re-matches #"v20(?:\..*)?" version)
      (js-ts-backend-fail!
       "B6-TARGET" "JS/TS backend requires Node 20"
       source-path nil
       {:observed-node-version version
        :required-node-version "20.x"
        :missing-fact :node20-runtime}))
    version))

(defn js-ts-backend-output-paths
  [output-path]
  ;; `-o` names an artifact directory for the multi-file JS/TS target.  Fixed
  ;; logical filenames keep sourceMappingURL and every emitted byte independent
  ;; of the checkout and caller-selected output path.
  {:javascript (str output-path "/program.mjs")
   :typescript-declarations (str output-path "/program.d.ts")
   :source-map (str output-path "/program.mjs.map")
   :package-metadata (str output-path "/package.json")
   :manifest (str output-path "/manifest.edn")
   :provenance (str output-path "/provenance.edn")})

(defn js-ts-backend-delete-tree!
  [path]
  (when (and path (.exists (.toFile path)))
    (doseq [file (reverse (file-seq (.toFile path)))]
      (.delete file))))

(defn js-ts-backend-stage-files!
  [output-path paths contents source-path]
  (when-not (c-backend-output-path-allowed? output-path)
    (js-ts-backend-fail!
     "C14-INPUT" "JS/TS artifact directory is outside declared roots"
     source-path nil
     {:output-path output-path
      :missing-fact :output-path-containment}))
  (let [output-directory (java.io.File. output-path)
        expected-parent (.getCanonicalPath output-directory)]
    (when (.exists output-directory)
      (js-ts-backend-fail!
       "C14-INPUT" "JS/TS backend requires a fresh artifact directory"
       source-path nil
       {:output-path output-path
        :missing-fact :fresh-output-path}))
    (doseq [[kind path] paths]
      (when-not (= expected-parent
                   (.getCanonicalPath (.getParentFile (java.io.File. path))))
        (js-ts-backend-fail!
         "C14-INPUT" "JS/TS sidecar escaped its artifact directory"
         source-path nil
         {:output-kind kind :output-path path
          :missing-fact :artifact-directory-containment})))
    (let [parent-file (or (.getParentFile output-directory)
                          (java.io.File. "."))]
      (when (and (.exists parent-file) (not (.isDirectory parent-file)))
        (js-ts-backend-fail!
         "C14-INPUT" "JS/TS artifact parent is not a directory"
         source-path nil
         {:output-path output-path
          :output-parent (.getPath parent-file)
          :missing-fact :output-parent-directory}))
      (when (and (not (.exists parent-file))
                 (not (.mkdirs parent-file)))
        (js-ts-backend-fail!
         "C14-INPUT" "JS/TS artifact parent directory is unavailable"
         source-path nil
         {:output-path output-path
          :output-parent (.getPath parent-file)
          :missing-fact :output-parent-directory}))
      (let [stage-directory
            (try
              (java.nio.file.Files/createTempDirectory
               (.toPath parent-file)
               ".gravity-js-ts-stage-"
               (make-array java.nio.file.attribute.FileAttribute 0))
              (catch Exception ex
                (js-ts-backend-fail!
                 "C14-INPUT"
                 "JS/TS staging directory could not be created"
                 source-path nil
                 {:output-path output-path
                  :output-parent (.getPath parent-file)
                  :cause-message (.getMessage ex)
                  :missing-fact :output-staging-directory})))]
        (try
        (doseq [[kind value] contents]
          (let [target-name (.getName (java.io.File. (get paths kind)))
                staged-path (.resolve stage-directory target-name)]
            (java.nio.file.Files/write
             staged-path
             (.getBytes (str value)
                        java.nio.charset.StandardCharsets/UTF_8)
             (into-array java.nio.file.OpenOption
                          [java.nio.file.StandardOpenOption/CREATE_NEW
                           java.nio.file.StandardOpenOption/WRITE]))))
        (let [staged-javascript
              (.toFile
               (.resolve stage-directory
                         (.getName (java.io.File. (:javascript paths)))))]
          (when-not (.setExecutable staged-javascript true false)
            (js-ts-backend-fail!
             "B6-MANIFEST"
             "staged JS/TS entrypoint could not be made executable"
             source-path nil
             {:missing-fact :executable-module-permission})))
        (try
          (java.nio.file.Files/move
           stage-directory
           (.toPath output-directory)
           (into-array java.nio.file.CopyOption
                       [java.nio.file.StandardCopyOption/ATOMIC_MOVE]))
          (catch Exception ex
            (js-ts-backend-fail!
             "B6-MANIFEST"
             "JS/TS artifact directory could not be atomically committed"
             source-path nil
             {:cause-message (.getMessage ex)
              :missing-fact :atomic-artifact-directory-commit})))
          (finally
            (js-ts-backend-delete-tree! stage-directory)))))))

(defn js-ts-backend-source-artifact
  "Emit and execute the bounded Node 20 ES2022 ESM target from the genuine
  stage2 compiler-driver packet.  All validation and differential execution
  completes in a temporary directory before caller-visible files are moved
  into place."
  ([source-path source-text]
   (js-ts-backend-source-artifact source-path source-text {}))
  ([source-path source-text {:keys [target output-path emit?]
                             :or {target js-ts-backend-target
                                  emit? false}}]
   (let [target (js-ts-backend-canonical-target target)]
     (when-not (= js-ts-backend-target target)
       (js-ts-backend-fail!
        "B6-TARGET" "JS/TS backend target is unsupported"
        source-path nil
        {:requested-target target
         :supported-targets (vec (sort js-ts-backend-target-aliases))
         :missing-fact :supported-target}))
     (when (and emit? (str/blank? (str output-path)))
       (js-ts-backend-fail!
        "C14-INPUT" "JS/TS target compilation requires an output path"
        source-path nil {:missing-fields [:output-path]}))
     (let [node-version (js-ts-backend-node-version! source-path)
           packet (stage2-runtime-derived-packet
                   source-path source-text target
                   {:validate-plan!
                    (fn [candidate-plan]
                      (js-ts-backend-validate-plan!
                       source-path candidate-plan))})
           compiler-artifact-record
           (:stage2-compiler-artifact-record packet)
           _ (when-not
              (p15-s23-stage2-compiler-artifact-record-authentic?
               compiler-artifact-record)
               (js-ts-backend-fail!
                "C14-INPUT"
                "JS/TS backend received inconsistent stage2 compiler artifact metadata"
                source-path compiler-artifact-record
                {:missing-fact
                 :authenticated-stage2-compiler-artifact-record}))
           _ (when-not
              (p15-s23-closed-runtime-packet-authentic?
               packet
               (p15-s23-closed-runtime-packet-context
                source-path source-text target))
               (js-ts-backend-fail!
                "C14-INPUT"
                "JS/TS backend received an unauthenticated closed runtime execution"
                source-path packet
                {:missing-fact :authenticated-closed-runtime-execution}))
           compiler-artifact-source-path
           (get-in packet
                   [:provenance :actual-paths
                    :stage2-expression-lowering-source])
           driver-record (:stage2-compiler-driver-record packet)
           runtime-record (:stage2-runtime-execution-record packet)
           runtime-rule (:stage2-runtime-rule packet)
           driver-rule (:stage2-compiler-driver-rule packet)
           closed-plan-runtime
           (p15-s23-closed-runtime-target-record packet)
           closed-runtime-context
           (p15-s23-closed-runtime-target-context packet)
           _ (when-not
              (p15-s23-closed-runtime-target-record-authentic?
               closed-plan-runtime
               closed-runtime-context)
               (js-ts-backend-fail!
                "C14-INPUT"
                "JS/TS backend received an unauthenticated closed runtime target record"
                source-path closed-plan-runtime
                {:missing-fact :authenticated-closed-runtime-target-record}))
           plan (:plan packet)
           _ (when-not
              (p15-s23-stage2-compiler-artifact-record-matches-plan?
               compiler-artifact-record plan)
               (js-ts-backend-fail!
                "C14-INPUT"
                "JS/TS backend received a stage2 compiler record that does not match its plan"
                source-path compiler-artifact-record
                {:missing-fact
                 :authenticated-stage2-compiler-artifact-record}))
           _ (when-not (= :safe (get-in plan [:module :safety]))
               (js-ts-backend-fail!
                "C14-PROFILE"
                "bounded JS/TS target does not lower unsafe modules"
                source-path plan
                {:observed-safety-mode (get-in plan [:module :safety])
                 :supported-safety-modes [:safe]
                 :missing-fact :safe-js-ts-module}))
           _ (when-not (c-backend-runtime-plan-supported? plan)
               (js-ts-backend-fail!
                "C14-UNSUPPORTED"
                "JS/TS backend cannot lower this stage2 instruction plan"
                source-path plan
                {:missing-fact :js-ts-lowering-rule
                 :fallback-status :rejected}))
           _ (js-ts-backend-validate-plan! source-path plan)
           plan-hash
           (c4-artifact-id
            (c-backend-canonical-value
             (select-keys plan [:kind :entrypoint :functions
                                :instruction-summary :effect-summary])))
           javascript (js-ts-backend-source plan)
           writes-stdout?
           (pos? (get-in plan [:instruction-summary :println] 0))
           source-map (js-ts-backend-source-map-source
                       javascript source-text)
           package-metadata (js-ts-backend-package-source writes-stdout?)
           js-hash (str "sha256:" (sha256-hex javascript))
           declaration-hash
           (str "sha256:" (sha256-hex js-ts-backend-declaration-source))
           source-map-hash
           (str "sha256:" (sha256-hex source-map))
           package-hash
           (str "sha256:" (sha256-hex package-metadata))
           source-hash (str "sha256:" (sha256-hex source-text))
           expected-output (:stdout runtime-record)
           expected-bytes (c-backend-runtime-bytes expected-output)
           temp-directory
           (java.nio.file.Files/createTempDirectory
            "gravity-js-ts-validate-"
            (make-array java.nio.file.attribute.FileAttribute 0))
           temp-module (.resolve temp-directory "program.mjs")
           _ (java.nio.file.Files/write
              temp-module
              (.getBytes javascript java.nio.charset.StandardCharsets/UTF_8)
              (into-array java.nio.file.OpenOption
                          [java.nio.file.StandardOpenOption/CREATE_NEW
                           java.nio.file.StandardOpenOption/WRITE]))
           _ (js-ts-backend-run-node-process!
              ["--check" (.toString temp-module)] source-path "B6-TARGET"
              "Node rejected generated ES2022 ESM")
           execution (js-ts-backend-run-node-process!
                      [(.toString temp-module)] source-path
                      "B14-DIFFERENTIAL"
                      "generated JS/TS execution failed")
           _ (java.nio.file.Files/deleteIfExists temp-module)
           _ (java.nio.file.Files/deleteIfExists temp-directory)
           _ (when-not (= expected-bytes (:stdout-bytes execution))
               (js-ts-backend-fail!
                "B14-DIFFERENTIAL"
                "JS/TS execution differs from the authoritative stage2 runtime"
                source-path nil
                {:expected-stdout-hash
                 (str "sha256:" (sha256-hex expected-output))
                 :actual-stdout-hash
                 (str "sha256:"
                      (sha256-bytes-hex
                       (byte-array (map byte (:stdout-bytes execution)))))
                 :missing-fact :stage2-js-execution-equivalence}))
           manifest-input
           {:artifact :gravity/js-ts-backend-manifest
            :schema-version 1
            :backend :gravity.backend/js-ts
            :profile :hosted
            :target {:runtime js-ts-backend-runtime
                     :runtime-version node-version
                     :ecmascript js-ts-backend-ecmascript
                     :module-format js-ts-backend-module-format}
            :module {:side-effects writes-stdout?
                     :package-boundary :standalone}
            :emits [:javascript :typescript-declarations :source-map
                    :package-metadata :manifest :provenance]
            :content-hashes
            {:javascript js-hash
             :typescript-declarations declaration-hash
             :source-map source-map-hash
             :package-metadata package-hash}
            :input {:source-content-hash source-hash
                    :source-declared-target
                    (get-in packet [:target-eligibility
                                    :source-declared-target])
                    :requested-backend-target target
                    :target-eligibility (:target-eligibility packet)
                    :stage2-plan-hash plan-hash
                    :expression-lowering-artifact-hash
                    (:artifact-hash compiler-artifact-record)
                    :expression-lowering-source-content-hash
                    (:source-content-hash compiler-artifact-record)
                    :expression-lowering-semantic-hash
                    (:semantic-hash compiler-artifact-record)
                    :expression-lowering-invoked?
                    (:invoked? compiler-artifact-record)
                    :expression-lowering-generic-bridge-residual?
                    (:generic-bridge-residual? compiler-artifact-record)
                    :plan-assembly-function
                    (:plan-assembly-function compiler-artifact-record)
                    :plan-assembly-artifact-hash
                    (:plan-assembly-artifact-hash compiler-artifact-record)
                    :plan-assembly-source-content-hash
                    (:plan-assembly-source-content-hash
                     compiler-artifact-record)
                    :plan-assembly-semantic-hash
                    (:plan-assembly-semantic-hash compiler-artifact-record)
                    :plan-assembly-invoked?
                    (:plan-assembly-invoked? compiler-artifact-record)
                    :plan-assembly-generic-bridge-residual?
                    (:plan-assembly-generic-bridge-residual?
                     compiler-artifact-record)
                    :compiler-driver-rule-hash
                    (:driver-rule-hash driver-rule)
                    :runtime-rule-hash (:runtime-rule-hash runtime-rule)
                    :runtime-artifact-hash
                    (:runtime-artifact-hash runtime-rule)}
            :effects (:effect-summary plan)
            :capabilities (get-in plan [:module :capabilities])
            :safety {:mode (get-in plan [:module :safety])
                     :unsafe-islands [] :status :preserved}
            :host-globals
            (if writes-stdout?
              [{:module "node:process"
                :symbol :stdout
                :effect :io/write
                :capability :io/stdout
                :representation :uint8array-bytes}]
              [])
            :numeric-representation {:mode :hosted-scalar-spelling
                                     :bytes :utf8
                                     :lossy-number-lowering? false}
            :nullish-policy :no-host-nullish-inputs
            :exception-policy :no-host-exception-boundary-in-slice
            :typescript-compiler {:available? false
                                  :required? false
                                  :reason :tsc-not-installed}
            :conformance {:node-check :passed
                          :stage2-differential :passed
                          :stdout-byte-exact? true
                          :source-map :partial
                          :source-map-coverage :source-unit-only
                          :per-form-origin-preserved? false
                          :b6-conforming? false}
            :closed-plan-runtime closed-plan-runtime
            :release-grade? false
            :clojure-seed-boundary? true
            :self-hosted? false
            :diagnostics []}
           manifest-hash
           (str "sha256:"
                (sha256-hex
                 (pr-str
                  (c-backend-canonical-value
                   (update manifest-input :closed-plan-runtime
                           p15-s23-closed-runtime-target-semantic-record)))))
           manifest (assoc manifest-input :manifest-hash manifest-hash)
           _ (js-ts-backend-validate-manifest!
              source-path manifest closed-runtime-context)
           provenance-input
           {:artifact :gravity/js-ts-provenance
            :schema-version 1
            :source-content-hash source-hash
            :stage2-plan-hash plan-hash
            :stage2-expression-lowering-artifact
            (dissoc compiler-artifact-record :source-path)
            :target-eligibility (:target-eligibility packet)
            :stage2-compiler-driver-rule-hash
            (:driver-rule-hash driver-rule)
            :stage2-runtime-rule-hash (:runtime-rule-hash runtime-rule)
            :stage2-runtime-artifact-hash
            (:runtime-artifact-hash runtime-rule)
            :closed-plan-runtime closed-plan-runtime
            :backend :gravity.backend/js-ts
            :backend-version 1
            :target js-ts-backend-target
            :manifest-hash manifest-hash
            :pass-history [:c2-reader :stage2-source-front-end
                           :stage2-plan-emitter :stage2-compiler-driver
                           :stage2-runtime-executor :js-ts-lowering]
            :seed-boundary {:clojure-seed-boundary? true
                            :self-hosted? false}}
           provenance-hash
           (str "sha256:"
                (sha256-hex
                 (pr-str
                  (c-backend-canonical-value
                   (update provenance-input :closed-plan-runtime
                           p15-s23-closed-runtime-target-semantic-record)))))
           paths (when output-path
                   (js-ts-backend-output-paths (str output-path)))
           provenance
           (assoc provenance-input
                  :provenance-hash provenance-hash
                  :actual-paths
                  {:source source-path
                   :outputs paths
                   :stage2-expression-lowering-source
                   compiler-artifact-source-path
                   :stage2-runtime-artifact-source
                   (:runtime-artifact-source-path runtime-rule)})
           identity-input
           {:kind :gravity/js-ts-backend-artifact
            :source-content-hash source-hash
            :stage2-plan-hash plan-hash
            :expression-lowering-artifact-hash
            (:artifact-hash compiler-artifact-record)
            :javascript-hash js-hash
            :declaration-hash declaration-hash
            :source-map-hash source-map-hash
            :package-hash package-hash
            :manifest-hash manifest-hash
            :provenance-hash provenance-hash
            :closed-plan-target-record-hash
            (:record-hash closed-plan-runtime)}
           artifact
           {:kind :gravity/js-ts-backend-artifact
            :task "HOSTED-JS-TS-TARGET"
            :status :complete-for-slice
            :artifact-id
            (c4-artifact-id
             (c-backend-canonical-value identity-input))
            :source {:kind :co-canonical-gravity-source
                     :sha256 source-hash}
            :target (:target manifest)
            :input-plan-id (:plan-id plan)
            :input-plan-hash plan-hash
            :target-eligibility (:target-eligibility packet)
            :stage2-expression-lowering-artifact
            (dissoc compiler-artifact-record :source-path)
            :instruction-summary (:instruction-summary plan)
            :effect-summary (:effect-summary plan)
            :capabilities (get-in plan [:module :capabilities])
            :javascript-source javascript
            :typescript-declarations js-ts-backend-declaration-source
            :source-map source-map
            :package-metadata package-metadata
            :manifest manifest
            :manifest-hash manifest-hash
            :provenance provenance
            :provenance-hash provenance-hash
            :stage2-compiler-driver-record driver-record
            :stage2-runtime-execution-record
            runtime-record
            :closed-plan-runtime-target-record closed-plan-runtime
            :closed-runtime-validation-context closed-runtime-context
            :compiled-execution-output-bytes (:stdout-bytes execution)
            :compiled-execution-output expected-output
            :seed-boundary {:clojure-seed-boundary? true
                            :self-hosted? false
                            :final-release? false}
            :diagnostics []}]
       (when emit?
         (js-ts-backend-stage-files!
          (str output-path) paths
          {:javascript javascript
           :typescript-declarations js-ts-backend-declaration-source
           :source-map source-map
           :package-metadata package-metadata
           :manifest (pr-str manifest)
           :provenance (pr-str provenance)}
          source-path))
       artifact))))

(defn js-ts-backend-file-artifact
  ([path] (js-ts-backend-file-artifact path {}))
  ([path options]
   (js-ts-backend-source-artifact
    path (read-gravity-source-text path) options)))

;; ---------------------------------------------------------------------------
;; Hosted JVM target (Java 21 class files and modular executable JAR)
;;
;; This is an opt-in target over the same authenticated stage2 packet as the
;; runtime-derived C and Node targets.  The generated Java executes the closed
;; scalar/control-flow plan; it does not embed stage2 stdout.  javac remains an
;; external target tool and the compiler remains inside the Clojure seed
;; boundary, so this slice deliberately does not claim full B5 conformance.

(def jvm-backend-target :jvm)
(def jvm-backend-target-release 21)
(def jvm-backend-required-classfile-major 65)
(def jvm-backend-module-name "gravity.stage")
(def jvm-backend-main-class "gravity.stage2.Program")
(def ^:dynamic *jvm-backend-javac-command* "javac")
(def ^:dynamic *jvm-backend-java-command* "java")

(defn jvm-backend-fail!
  [id message source-path subject extra]
  (fail! id message
         (merge {:severity :error
                 :stage :jvm-backend-lowering
                 :diagnostic-family
                 (cond
                   (str/starts-with? id "B5") :b5-jvm-backend
                   (str/starts-with? id "B13") :b13-artifact-emission
                   (str/starts-with? id "B14") :b14-backend-conformance
                   :else :c14-target-lowering)
                 :backend :gravity.backend/jvm
                 :target jvm-backend-target
                 :source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :primary {:span (or (:source-span subject)
                                     (source-span source-path 0))}
                 :fallback-status :rejected
                 :remediation
                 "Use --target jvm --lowering runtime-derived with the closed Java 21 hosted subset."}
                extra)))

(defn jvm-backend-validate-plan!
  [source-path plan]
  (try
    ;; Reuse the shared iterative scalar/control-flow validator, but remap its
    ;; historical C diagnostic at this concrete backend boundary.
    (c-backend-validate-runtime-plan! source-path jvm-backend-target plan)
    (catch clojure.lang.ExceptionInfo ex
      (if (= "B2-UNSUPPORTED" (:id (ex-data ex)))
        (jvm-backend-fail!
         "C14-UNSUPPORTED"
         "JVM backend cannot lower this stage2 instruction plan"
         source-path plan
         {:unsupported-op (:unsupported-op (ex-data ex))
          :missing-fact :jvm-stage2-lowering-rule})
        (throw ex))))
  :passed)

(defn jvm-backend-validate-packet!
  [source-path packet trusted-emitter-rule trusted-driver-rule
   trusted-runtime-rule trusted-plan packet-context]
  (let [emitter-hash (get-in packet
                             [:stage2-plan-emitter-rule :source-rule-hash])
        trusted-emitter-hash (:source-rule-hash trusted-emitter-rule)
        driver-hash (get-in packet
                            [:stage2-compiler-driver-rule :driver-rule-hash])
        trusted-driver-hash (:driver-rule-hash trusted-driver-rule)
        runtime-hash (get-in packet
                             [:stage2-runtime-rule :runtime-rule-hash])
        trusted-runtime-hash (:runtime-rule-hash trusted-runtime-rule)
        runtime-artifact-hash
        (get-in packet [:stage2-runtime-rule :runtime-artifact-hash])
        trusted-runtime-artifact-hash
        (:runtime-artifact-hash trusted-runtime-rule)
        compiler-record (:stage2-compiler-artifact-record packet)
        packet-plan (:plan packet)
        driver-plan (:stage2-plan (:stage2-compiler-driver-record packet))
        plan-shape-keys
        [:kind :entrypoint :functions :binding-table
         :instruction-summary :effect-summary]
        plan-compiler (get-in packet [:plan :compiler])
        runtime-record (:stage2-runtime-execution-record packet)
        driver-record (:stage2-compiler-driver-record packet)]
    (when-not
     (and (= :gravity/target-neutral-stage2-runtime-packet (:kind packet))
          (= :complete (:status packet))
          (= :jvm (:requested-target packet))
          (= {:status :accepted
              :source-declared-target :jvm
              :requested-target :jvm
              :selection :source-and-request-agree}
             (:target-eligibility packet))
          (map? packet-plan)
          (= (c-backend-canonical-value
              (select-keys trusted-plan plan-shape-keys))
             (c-backend-canonical-value
              (select-keys packet-plan plan-shape-keys)))
          (= (c-backend-canonical-value
              (select-keys trusted-plan plan-shape-keys))
             (c-backend-canonical-value
              (select-keys driver-plan plan-shape-keys)))
          (= (:plan-id trusted-plan) (:plan-id packet-plan))
          (= (:plan-id driver-plan) (:plan-id runtime-record))
          (= :complete (:status runtime-record))
          (= :complete (:status driver-record))
          (true? (:accepted-output-equivalent? driver-record))
          (= (:reference-output packet) (:stdout runtime-record))
          (string? emitter-hash)
          (boolean (re-matches #"sha256:[0-9a-f]{64}" emitter-hash))
          (= trusted-emitter-hash emitter-hash)
          (= trusted-driver-hash driver-hash)
          (= trusted-runtime-hash runtime-hash)
          (= trusted-runtime-artifact-hash runtime-artifact-hash)
          (p15-s23-closed-runtime-packet-authentic? packet packet-context)
          (p15-s23-stage2-compiler-artifact-record-authentic?
           compiler-record)
          (p15-s23-stage2-compiler-artifact-record-matches-plan?
           compiler-record packet-plan)
          (= (:artifact-hash compiler-record)
             (:expression-lowering-artifact-hash plan-compiler))
          (= (:source-content-hash compiler-record)
             (:expression-lowering-source-content-hash plan-compiler))
          (= (:semantic-hash compiler-record)
             (:expression-lowering-semantic-hash plan-compiler))
          (= (select-keys
              compiler-record
              [:plan-assembly-function :plan-assembly-artifact-hash
               :plan-assembly-source-content-hash
               :plan-assembly-semantic-hash :plan-assembly-invoked?
               :plan-assembly-generic-bridge-residual?])
             (select-keys
              plan-compiler
              [:plan-assembly-function :plan-assembly-artifact-hash
               :plan-assembly-source-content-hash
               :plan-assembly-semantic-hash :plan-assembly-invoked?
               :plan-assembly-generic-bridge-residual?])))
      (jvm-backend-fail!
       "C14-INPUT" "JVM backend received an unauthenticated stage2 packet"
       source-path (:plan packet)
       {:observed-packet-kind (:kind packet)
        :observed-packet-status (:status packet)
        :observed-plan-id (:plan-id packet-plan)
        :expected-plan-id (:plan-id trusted-plan)
        :observed-emitter-source-rule-hash emitter-hash
        :expected-emitter-source-rule-hash trusted-emitter-hash
        :observed-driver-rule-hash driver-hash
        :expected-driver-rule-hash trusted-driver-hash
        :observed-runtime-rule-hash runtime-hash
        :expected-runtime-rule-hash trusted-runtime-hash
        :observed-runtime-artifact-hash runtime-artifact-hash
        :expected-runtime-artifact-hash trusted-runtime-artifact-hash
        :missing-fact :authenticated-target-neutral-stage2-packet})))
  :passed)

(defn jvm-backend-byte-array-source
  [name bytes indent]
  (let [padding (apply str (repeat indent "  "))]
    (str padding "byte[] " name " = new byte[]{"
         (str/join "," (map #(str "(byte)" %) bytes)) "};\n")))

(defn jvm-backend-value-declaration
  [instruction counter indent]
  (let [name (str "gravityValue" (swap! counter inc))
        value (:value instruction)]
    {:source (jvm-backend-byte-array-source
              name (c-backend-runtime-bytes value) indent)
     :descriptor {:name name
                  :truth (not (or (nil? value) (false? value)))}}))

(defn jvm-backend-write-source
  [descriptor indent]
  (let [padding (apply str (repeat indent "  "))
        name (:name descriptor)]
    (str padding "System.out.write(" name ", 0, " name ".length);\n")))

(defn jvm-backend-test-source
  [instruction env]
  (case (:op instruction)
    :literal (if (or (nil? (:value instruction))
                     (false? (:value instruction))) "false" "true")
    :quote (if (or (nil? (:value instruction))
                   (false? (:value instruction))) "false" "true")
    :local (if (get-in env [(:name instruction) :truth]) "true" "false")
    "false"))

(declare jvm-backend-value-source)
(declare jvm-backend-instruction-source)

(defn jvm-backend-value-source
  [instruction counter indent env]
  (let [padding (apply str (repeat indent "  "))
        op (:op instruction)]
    (cond
      (#{:literal :quote} op)
      (let [{:keys [source descriptor]}
            (jvm-backend-value-declaration instruction counter indent)]
        (str source (jvm-backend-write-source descriptor indent)))

      (= :local op)
      (jvm-backend-write-source (get env (:name instruction)) indent)

      (= :builtin-call op)
      (apply str
             (map #(jvm-backend-value-source % counter indent env)
                  (:args instruction)))

      (= :if op)
      (str padding "if ("
           (jvm-backend-test-source (:test instruction) env)
           ") {\n"
           (jvm-backend-value-source (:then instruction) counter
                                     (inc indent) env)
           padding "} else {\n"
           (jvm-backend-value-source (:else instruction) counter
                                     (inc indent) env)
           padding "}\n")

      (= :let op)
      (let [binding-state
            (reduce (fn [state {:keys [name expr]}]
                      (let [{:keys [source descriptor]}
                            (jvm-backend-value-declaration
                             expr counter indent)]
                        {:source (str (:source state) source)
                         :env (assoc (:env state) name descriptor)}))
                    {:source "" :env env}
                    (:bindings instruction))]
        (str (:source binding-state)
             (jvm-backend-value-source
              (first (:body instruction)) counter indent
              (:env binding-state))))

      :else "")))

(defn jvm-backend-instruction-source
  ([instruction counter indent]
   (jvm-backend-instruction-source instruction counter indent {}))
  ([instruction counter indent env]
   (let [padding (apply str (repeat indent "  "))
         op (:op instruction)]
     (cond
       (#{:literal :quote :local} op) ""

       (= :println op)
       (str (apply str
                   (map-indexed
                    (fn [index argument]
                      (str (when (pos? index)
                             (let [name (str "gravitySpace"
                                             (swap! counter inc))]
                               (str (jvm-backend-byte-array-source
                                     name [32] indent)
                                    (jvm-backend-write-source
                                     {:name name} indent))))
                           (jvm-backend-value-source
                            argument counter indent env)))
                    (:args instruction)))
            (let [name (str "gravityNewline" (swap! counter inc))]
              (str (jvm-backend-byte-array-source name [10] indent)
                   (jvm-backend-write-source {:name name} indent))))

       (= :do op)
       (apply str
              (map #(jvm-backend-instruction-source % counter indent env)
                   (:body instruction)))

       (= :if op)
       (str padding "if ("
            (jvm-backend-test-source (:test instruction) env)
            ") {\n"
            (jvm-backend-instruction-source (:then instruction) counter
                                            (inc indent) env)
            padding "} else {\n"
            (jvm-backend-instruction-source (:else instruction) counter
                                            (inc indent) env)
            padding "}\n")

       (= :let op)
       (let [binding-state
             (reduce (fn [state {:keys [name expr]}]
                       (let [{:keys [source descriptor]}
                             (jvm-backend-value-declaration
                              expr counter indent)]
                         {:source (str (:source state) source)
                          :env (assoc (:env state) name descriptor)}))
                     {:source "" :env env}
                     (:bindings instruction))]
         (str (:source binding-state)
              (apply str
                     (map #(jvm-backend-instruction-source
                            % counter indent (:env binding-state))
                          (:body instruction)))))

       :else ""))))

(defn jvm-backend-java-source
  [plan]
  (let [counter (atom 0)
        main (get-in plan [:functions (:entrypoint plan)])]
    (str "package gravity.stage2;\n\n"
         "public final class Program {\n"
         "  private Program() {}\n\n"
         "  public static void main(String[] args) {\n"
         (apply str
                (map #(jvm-backend-instruction-source % counter 2 {})
                     (:instructions main)))
         "  }\n"
         "}\n")))

(def jvm-backend-module-source
  (str "module " jvm-backend-module-name " {\n"
       "  exports gravity.stage2;\n"
       "}\n"))

(defn jvm-backend-source-map
  [source-text java-source]
  {:artifact :gravity/jvm-source-map
   :schema-version 1
   :source {:kind :co-canonical-gravity-source
            :content-hash (str "sha256:" (sha256-hex source-text))
            :content source-text}
   :generated {:file "sources/gravity/stage2/Program.java"
               :line-count (count (str/split-lines java-source))}
   :origin-chain [:source-unit :c2-reader :stage2-source-front-end
                  :stage2-plan-emitter :stage2-compiler-driver
                  :jvm-lowering]
   :coverage :source-unit-only
   :per-form-origin-preserved? false
   :status :partial})

(defn jvm-backend-output-paths
  [output-path]
  {:java-source (str output-path "/sources/gravity/stage2/Program.java")
   :module-source (str output-path "/sources/module-info.java")
   :class-file (str output-path "/classes/gravity/stage2/Program.class")
   :module-class (str output-path "/classes/module-info.class")
   :jar (str output-path "/program.jar")
   :source-map (str output-path "/source-map.edn")
   :manifest (str output-path "/manifest.edn")
   :provenance (str output-path "/provenance.edn")})

(defn jvm-backend-run-process!
  [command source-path diagnostic-id message]
  (let [stdout-file (java.io.File/createTempFile "gravity-jvm-out-" ".bin")
        stderr-file (java.io.File/createTempFile "gravity-jvm-err-" ".txt")]
    (try
      (let [pb (ProcessBuilder. ^java.util.List (vec command))]
        (.redirectOutput pb stdout-file)
        (.redirectError pb stderr-file)
        (let [process (.start pb)
              finished? (.waitFor process 60000
                                  java.util.concurrent.TimeUnit/MILLISECONDS)]
          (when-not finished?
            (.destroyForcibly process)
            (jvm-backend-fail!
             diagnostic-id message source-path nil
             {:command (vec command)
              :missing-fact :jvm-target-process-completion}))
          (let [result
                {:exit (.exitValue process)
                 :stdout-bytes
                 (vec (map #(bit-and (int %) 0xff)
                           (java.nio.file.Files/readAllBytes
                            (.toPath stdout-file))))
                 :stderr (if (.exists stderr-file) (slurp stderr-file) "")}]
            (when-not (zero? (:exit result))
              (jvm-backend-fail!
               diagnostic-id message source-path nil
               {:command (vec command)
                :process-result result
                :missing-fact :jvm-target-tool-acceptance}))
            result)))
      (catch clojure.lang.ExceptionInfo ex
        (throw ex))
      (catch Exception ex
        (jvm-backend-fail!
         "B5-TARGET" "JVM target tool is unavailable"
         source-path nil
         {:command (vec command)
          :cause-message (.getMessage ex)
          :missing-fact :java21-target-toolchain}))
      (finally
        (.delete stdout-file)
        (.delete stderr-file)))))

(defn jvm-backend-tool-version!
  [command source-path]
  (let [result (jvm-backend-run-process!
                [command "-version"] source-path "B5-TARGET"
                "JVM target tool version check failed")
        stdout (String. (byte-array (map byte (:stdout-bytes result)))
                        java.nio.charset.StandardCharsets/UTF_8)
        output (str/trim (str stdout "\n" (:stderr result)))
        major (some-> (re-find #"(?:version )?\"?([0-9]+)" output)
                      second Long/parseLong)]
    (when-not (and major (>= major jvm-backend-target-release))
      (jvm-backend-fail!
       "B5-TARGET" "JVM target tool cannot produce or run Java 21 artifacts"
       source-path nil
       {:command command
        :observed-version output
        :required-major jvm-backend-target-release
        :missing-fact :java21-target-toolchain}))
    {:command command :version output :major major}))

(defn jvm-backend-write-file!
  [path content]
  (java.nio.file.Files/createDirectories (.getParent path)
                                          (make-array
                                           java.nio.file.attribute.FileAttribute
                                           0))
  (java.nio.file.Files/write
   path (.getBytes (str content) java.nio.charset.StandardCharsets/UTF_8)
   (into-array java.nio.file.OpenOption
               [java.nio.file.StandardOpenOption/CREATE_NEW
                java.nio.file.StandardOpenOption/WRITE])))

(defn jvm-backend-stored-jar-entry!
  [jar-output entry-name bytes]
  (let [crc (java.util.zip.CRC32.)
        entry (java.util.jar.JarEntry. entry-name)]
    (.update crc bytes)
    (.setTime entry 0)
    (.setMethod entry java.util.zip.ZipEntry/STORED)
    (.setSize entry (alength bytes))
    (.setCompressedSize entry (alength bytes))
    (.setCrc entry (.getValue crc))
    (.putNextEntry jar-output entry)
    (.write jar-output bytes 0 (alength bytes))
    (.closeEntry jar-output)))

(defn jvm-backend-write-deterministic-jar!
  [jar-path class-directory]
  (let [manifest-bytes
        (.getBytes
         (str "Manifest-Version: 1.0\r\n"
              "Main-Class: " jvm-backend-main-class "\r\n\r\n")
         java.nio.charset.StandardCharsets/UTF_8)
        entries
        [["META-INF/MANIFEST.MF" manifest-bytes]
         ["gravity/stage2/Program.class"
          (java.nio.file.Files/readAllBytes
           (.resolve class-directory "gravity/stage2/Program.class"))]
         ["module-info.class"
          (java.nio.file.Files/readAllBytes
           (.resolve class-directory "module-info.class"))]]]
    (with-open [output
                (java.util.jar.JarOutputStream.
                 (java.nio.file.Files/newOutputStream
                  jar-path
                  (into-array java.nio.file.OpenOption
                              [java.nio.file.StandardOpenOption/CREATE_NEW
                               java.nio.file.StandardOpenOption/WRITE])))]
      (doseq [[entry-name bytes] entries]
        (jvm-backend-stored-jar-entry! output entry-name bytes)))))

(defn jvm-backend-classfile-major
  [path]
  (let [bytes (java.nio.file.Files/readAllBytes path)]
    (when (and (>= (alength bytes) 8)
               (= [202 254 186 190]
                  (mapv #(bit-and (int (aget bytes %)) 0xff) (range 4))))
      (+ (bit-shift-left (bit-and (int (aget bytes 6)) 0xff) 8)
         (bit-and (int (aget bytes 7)) 0xff)))))

(defn jvm-backend-jar-record
  [jar-path]
  (with-open [jar (java.util.jar.JarFile. (.toFile jar-path))]
    (let [module-entry (.getJarEntry jar "module-info.class")
          module-name
          (when module-entry
            (with-open [input (.getInputStream jar module-entry)]
              (.name (java.lang.module.ModuleDescriptor/read input))))]
      {:entries (->> (enumeration-seq (.entries jar))
                     (map #(.getName ^java.util.jar.JarEntry %))
                     sort vec)
       :main-class (some-> jar .getManifest .getMainAttributes
                           (.getValue
                            java.util.jar.Attributes$Name/MAIN_CLASS))
       :module-name module-name})))

(defn jvm-backend-validate-content-hashes!
  [source-path manifest paths]
  (doseq [[kind expected] (:content-hashes manifest)]
    (let [path (get paths kind)
          actual
          (when (and path (.isFile (java.io.File. path)))
            (str "sha256:"
                 (sha256-bytes-hex
                  (java.nio.file.Files/readAllBytes
                   (.toPath (java.io.File. path))))))]
      (when-not (= expected actual)
        (jvm-backend-fail!
         "B13-HASH" "JVM emitted artifact content hash is stale or mismatched"
         source-path nil
         {:artifact-kind kind :artifact-path path
          :expected-content-hash expected :actual-content-hash actual
          :missing-fact :content-hash-integrity}))))
  :passed)

(defn jvm-backend-validate-manifest!
  ([source-path manifest]
   (jvm-backend-fail!
    "B5-MANIFEST"
    "JVM manifest validation requires trusted artifact context"
    source-path manifest
    {:missing-fact :jvm-manifest-validation-context}))
  ([source-path manifest expected-context]
   (let [required
        [:artifact :schema-version :backend :profile :target :module :emits
         :content-hashes :input :effects :capabilities :safety
         :managed-runtime :host-boundaries :toolchain :conformance
         :closed-plan-runtime
         :clojure-seed-boundary? :self-hosted? :release-grade? :diagnostics]
        missing (vec (remove #(contains? manifest %) required))
        hashes (:content-hashes manifest)
        input (:input manifest)
        closed-plan-runtime (:closed-plan-runtime manifest)
        inferred-effects (get-in manifest [:effects :inferred] #{})
        println-count (get-in input [:instruction-summary :println] 0)
        writes-stdout? (and (set? inferred-effects)
                            (contains? inferred-effects :io/write))
        eligibility (:target-eligibility input)
        digest? #(and (string? %)
                      (boolean
                       (re-matches #"sha256:[0-9a-f]{64}" %)))
        required-input-keys
        #{:source-content-hash :source-declared-target
          :requested-backend-target :target-eligibility
          :stage2-plan-hash :instruction-summary
          :expression-lowering-artifact-hash
          :expression-lowering-source-content-hash
          :expression-lowering-semantic-hash
          :expression-lowering-invoked?
          :expression-lowering-generic-bridge-residual?
          :plan-assembly-function :plan-assembly-artifact-hash
          :plan-assembly-source-content-hash :plan-assembly-semantic-hash
          :plan-assembly-invoked?
          :plan-assembly-generic-bridge-residual?
          :plan-emitter-source-rule-hash
          :compiler-driver-rule-hash :runtime-rule-hash
          :runtime-artifact-hash}
        input-valid?
        (and (= required-input-keys (set (keys input)))
             (every? digest?
                     [(:source-content-hash input)
                      (:stage2-plan-hash input)
                      (:expression-lowering-artifact-hash input)
                      (:expression-lowering-source-content-hash input)
                      (:expression-lowering-semantic-hash input)
                      (:plan-assembly-artifact-hash input)
                      (:plan-assembly-source-content-hash input)
                      (:plan-assembly-semantic-hash input)
                      (:plan-emitter-source-rule-hash input)
                      (:compiler-driver-rule-hash input)
                      (:runtime-rule-hash input)
                      (:runtime-artifact-hash input)])
             (= p15-s23-stage2-compiler-artifact-expected-semantic-hash
                (:expression-lowering-semantic-hash input))
             (true? (:expression-lowering-invoked? input))
             (true? (:expression-lowering-generic-bridge-residual? input))
             (= p15-s23-stage2-compiler-artifact-plan-assembly-function
                (:plan-assembly-function input))
             (= (:expression-lowering-artifact-hash input)
                (:plan-assembly-artifact-hash input))
             (= (:expression-lowering-source-content-hash input)
                (:plan-assembly-source-content-hash input))
             (= (:expression-lowering-semantic-hash input)
                (:plan-assembly-semantic-hash input))
             (true? (:plan-assembly-invoked? input))
             (true? (:plan-assembly-generic-bridge-residual? input))
             (= :jvm (:requested-backend-target input))
             (= :jvm (:source-declared-target input))
             (= {:status :accepted
                 :source-declared-target :jvm
                 :requested-target :jvm
                 :selection :source-and-request-agree}
                eligibility)
             (map? (:instruction-summary input))
             (integer? println-count)
             (not (neg? println-count))
             (= writes-stdout?
                (pos? println-count)))
        managed-runtime
        {:family :managed :host :jvm-21
         :delegated #{:startup :gc :classloading}
         :generated #{:entrypoint :byte-array-values}
         :linked #{}
         :forbidden #{:reflection :dynamic-loading :native-access
                      :threads :monitors}}
         manifest-hash-valid?
         (and (contains? manifest :manifest-hash)
              (= (:manifest-hash manifest)
                 (str "sha256:"
                      (sha256-hex
                       (pr-str
                        (c-backend-canonical-value
                         (update (dissoc manifest :manifest-hash)
                                 :closed-plan-runtime
                                 p15-s23-closed-runtime-target-semantic-record)))))))
         expected-context-valid?
         (and (map? expected-context)
              (= #{:input :effects :capabilities :content-hashes
                   :closed-runtime-context}
                 (set (keys expected-context)))
              (= (:input expected-context) input)
              (= (:effects expected-context) (:effects manifest))
              (= (:capabilities expected-context)
                 (:capabilities manifest))
              (= (:content-hashes expected-context)
                 (:content-hashes manifest)))]
    (when-not
     (and (empty? missing)
          (= :gravity/jvm-backend-manifest (:artifact manifest))
          (= 1 (:schema-version manifest))
          (= :gravity.backend/jvm (:backend manifest))
          (= :hosted (:profile manifest))
          (= {:classfile 65 :runtime :jvm-21 :module-system :named
              :packaging :modular-executable-jar}
             (:target manifest))
          (= {:name jvm-backend-module-name
              :main-class jvm-backend-main-class
              :side-effects writes-stdout?}
             (:module manifest))
          (= #{:java-sources :class-files :modular-executable-jar
               :source-map :manifest :provenance}
             (set (:emits manifest)))
          (= #{:java-source :module-source :class-file :module-class
               :jar :source-map}
             (set (keys hashes)))
          (every? #(boolean
                    (re-matches #"sha256:[0-9a-f]{64}" (str %)))
                  (vals hashes))
          input-valid?
          (= #{:declared :inferred :capabilities}
             (set (keys (:effects manifest))))
          (set? inferred-effects)
          (set? (get-in manifest [:effects :declared]))
          (set? (get-in manifest [:effects :capabilities]))
          (set? (:capabilities manifest))
          (set/subset? (get-in manifest [:effects :declared]) #{:io/write})
          (set/subset? inferred-effects #{:io/write})
          (set/subset? inferred-effects
                       (get-in manifest [:effects :declared] #{}))
          (set/subset? (get-in manifest [:effects :capabilities])
                       #{:io/stdout})
          (set/subset? (:capabilities manifest) #{:io/stdout})
          (= (set (:capabilities manifest))
             (set (get-in manifest [:effects :capabilities])))
          (or (not writes-stdout?)
              (and (contains? (get-in manifest [:effects :declared] #{})
                              :io/write)
                   (contains? (get-in manifest [:effects :inferred] #{})
                              :io/write)
                   (contains? (set (:capabilities manifest)) :io/stdout)))
          (= (if writes-stdout?
               [{:class "java.lang.System" :member "out"
                 :operation :write-byte-array
                 :effect :io/write :capability :io/stdout
                 :representation :byte-array}]
               [])
             (:host-boundaries manifest))
          (= managed-runtime (:managed-runtime manifest))
          manifest-hash-valid?
          expected-context-valid?
          (= {:mode :safe :unsafe-islands [] :status :preserved}
             (:safety manifest))
          (= {:target-release 21 :encoding :utf8
              :debug [:source :lines] :annotation-processing :disabled}
             (:toolchain manifest))
          (= {:classfile-major :passed :jar-entries :passed
              :main-class :passed :stage2-differential :passed
              :stdout-byte-exact? true :source-map :partial
              :source-map-coverage :source-unit-only
              :per-form-origin-preserved? false :b5-conforming? false
              :verified-mir-input? false}
             (:conformance manifest))
          (p15-s23-closed-runtime-target-record-authentic?
           closed-plan-runtime
           (:closed-runtime-context expected-context))
          (= :complete (get-in closed-plan-runtime [:validation :status]))
          (= 1 (get-in closed-plan-runtime [:invocation :invocation-count]))
          (= :complete (get-in closed-plan-runtime [:execution :status]))
          (digest? (:record-hash closed-plan-runtime))
          (true? (:clojure-seed-boundary? closed-plan-runtime))
          (false? (:self-hosted? closed-plan-runtime))
          (true? (:clojure-seed-boundary? manifest))
          (false? (:self-hosted? manifest))
          (false? (:release-grade? manifest))
          (= [] (:diagnostics manifest)))
      (jvm-backend-fail!
       "B5-MANIFEST" "JVM artifact manifest is incomplete or contradictory"
       source-path manifest
        {:missing-fields missing
        :input-valid? input-valid?
        :manifest-hash-valid? manifest-hash-valid?
        :expected-context-valid? expected-context-valid?
        :missing-fact :complete-jvm-manifest})))
   :passed))

(defn jvm-backend-preflight-output!
  [output-path source-path]
  (when-not (c-backend-output-path-allowed? output-path)
    (jvm-backend-fail!
     "C14-INPUT" "JVM artifact directory is outside declared roots"
     source-path nil
     {:output-path output-path :missing-fact :output-path-containment}))
  (let [output (java.io.File. output-path)
        parent (or (.getParentFile output) (java.io.File. "."))]
    (when (.exists output)
      (jvm-backend-fail!
       "C14-INPUT" "JVM backend requires a fresh artifact directory"
       source-path nil
       {:output-path output-path :missing-fact :fresh-output-path}))
    (when (and (.exists parent) (not (.isDirectory parent)))
      (jvm-backend-fail!
       "C14-INPUT" "JVM artifact parent is not a directory"
       source-path nil
       {:output-path output-path :output-parent (.getPath parent)
        :missing-fact :output-parent-directory}))
    (when (and (not (.exists parent)) (not (.mkdirs parent)))
      (jvm-backend-fail!
       "C14-INPUT" "JVM artifact parent directory is unavailable"
       source-path nil
       {:output-path output-path :output-parent (.getPath parent)
        :missing-fact :output-parent-directory}))
    {:output output :parent parent}))

(defn jvm-backend-source-artifact
  ([source-path source-text]
   (jvm-backend-source-artifact source-path source-text {}))
  ([source-path source-text {:keys [output-path emit?]
                             :or {emit? false}}]
   (when (and emit? (str/blank? (str output-path)))
     (jvm-backend-fail!
      "C14-INPUT" "JVM target compilation requires an output directory"
      source-path nil {:missing-fields [:output-path]}))
   (let [{:keys [output parent]}
         (when emit? (jvm-backend-preflight-output! (str output-path)
                                                    source-path))
         javac-version (jvm-backend-tool-version!
                        *jvm-backend-javac-command* source-path)
         java-version (jvm-backend-tool-version!
                       *jvm-backend-java-command* source-path)
         packet (stage2-runtime-derived-packet
                 source-path source-text jvm-backend-target
                 {:validate-plan!
                  (fn [candidate-plan]
                    (jvm-backend-validate-plan!
                     source-path candidate-plan))})
         trusted-emitter-rule
         (c-backend-stage2-plan-emitter-source-rule!
          source-path jvm-backend-target)
         trusted-driver-rule
         (c-backend-stage2-compiler-driver-source-rule!
          source-path jvm-backend-target)
         trusted-runtime-rule
         (c-backend-stage2-runtime-source-rule!
          source-path jvm-backend-target)
         trusted-plan
         (p15-s23-stage2-plan-emitter-compile-source
          (:emitter trusted-emitter-rule) source-path source-text)
         _ (jvm-backend-validate-packet!
            source-path packet trusted-emitter-rule trusted-driver-rule
            trusted-runtime-rule trusted-plan
            (p15-s23-closed-runtime-packet-context
             source-path source-text jvm-backend-target))
         plan (:plan packet)
         _ (when-not (= :hosted (get-in plan [:module :profile]))
             (jvm-backend-fail!
              "C14-PROFILE" "JVM target requires the hosted profile"
              source-path plan
              {:observed-profile (get-in plan [:module :profile])
               :missing-fact :hosted-jvm-profile}))
         _ (when-not (= :safe (get-in plan [:module :safety]))
             (jvm-backend-fail!
              "C14-PROFILE" "bounded JVM target does not lower unsafe modules"
              source-path plan
              {:observed-safety-mode (get-in plan [:module :safety])
               :missing-fact :safe-jvm-module}))
         _ (jvm-backend-validate-plan! source-path plan)
         writes-stdout? (pos? (get-in plan [:instruction-summary :println] 0))
         _ (when (and writes-stdout?
                      (not (and
                            (contains? (get-in plan
                                               [:effect-summary :declared] #{})
                                       :io/write)
                            (contains? (get-in plan
                                               [:effect-summary :inferred] #{})
                                       :io/write)
                            (contains? (set (get-in plan
                                                    [:module :capabilities]))
                                       :io/stdout))))
             (jvm-backend-fail!
              "B5-INTEROP" "JVM stdout lowering lacks effect or capability authority"
              source-path plan
              {:missing-fact :stdout-effect-capability-adapter}))
         java-source (jvm-backend-java-source plan)
         module-source jvm-backend-module-source
         source-map (jvm-backend-source-map source-text java-source)
         plan-hash (c4-artifact-id
                    (c-backend-canonical-value
                     (select-keys plan [:kind :entrypoint :functions
                                        :instruction-summary :effect-summary])))
         source-hash (str "sha256:" (sha256-hex source-text))
         compiler-record (:stage2-compiler-artifact-record packet)
         closed-plan-runtime
         (p15-s23-closed-runtime-target-record packet)
         _ (when-not
            (p15-s23-closed-runtime-target-record-authentic?
             closed-plan-runtime
             (p15-s23-closed-runtime-target-context packet))
             (jvm-backend-fail!
              "C14-INPUT"
              "JVM backend received an unauthenticated closed runtime target record"
              source-path closed-plan-runtime
              {:missing-fact :authenticated-closed-runtime-target-record}))
         stage-directory
         (if emit?
           (try
             (java.nio.file.Files/createTempDirectory
              (.toPath parent) ".gravity-jvm-stage-"
              (make-array java.nio.file.attribute.FileAttribute 0))
             (catch Exception ex
               (jvm-backend-fail!
                "C14-INPUT" "JVM staging directory could not be created"
                source-path nil
                {:cause-message (.getMessage ex)
                 :missing-fact :output-staging-directory})))
           (java.nio.file.Files/createTempDirectory
            "gravity-jvm-validate-"
            (make-array java.nio.file.attribute.FileAttribute 0)))
         staged-paths (jvm-backend-output-paths (.toString stage-directory))]
     (try
       (jvm-backend-write-file!
        (.toPath (java.io.File. (:java-source staged-paths))) java-source)
       (jvm-backend-write-file!
        (.toPath (java.io.File. (:module-source staged-paths))) module-source)
       (java.nio.file.Files/createDirectories
        (.toPath (java.io.File. (str stage-directory "/classes")))
        (make-array java.nio.file.attribute.FileAttribute 0))
       (jvm-backend-run-process!
        [*jvm-backend-javac-command* "--release" "21"
         "-encoding" "UTF-8" "-g:source,lines" "-proc:none"
         "-implicit:none" "-Werror" "-d"
         (str stage-directory "/classes")
         (:module-source staged-paths) (:java-source staged-paths)]
        source-path "B5-TARGET" "javac rejected generated Java 21 source")
       (let [class-path (.toPath (java.io.File. (:class-file staged-paths)))
             module-class-path
             (.toPath (java.io.File. (:module-class staged-paths)))
             class-major (jvm-backend-classfile-major class-path)]
         (when-not (and (= jvm-backend-required-classfile-major class-major)
                        (= jvm-backend-required-classfile-major
                           (jvm-backend-classfile-major module-class-path)))
           (jvm-backend-fail!
            "B5-MANIFEST" "generated JVM classfile version is invalid"
            source-path nil
            {:observed-classfile-major class-major
             :required-classfile-major jvm-backend-required-classfile-major
             :missing-fact :classfile-major-65}))
         (jvm-backend-write-deterministic-jar!
          (.toPath (java.io.File. (:jar staged-paths)))
          (.toPath (java.io.File. (str stage-directory "/classes"))))
         (let [jar-record
               (jvm-backend-jar-record
                (.toPath (java.io.File. (:jar staged-paths))))
               expected-entries
               ["META-INF/MANIFEST.MF" "gravity/stage2/Program.class"
                "module-info.class"]]
           (when-not (and (= expected-entries (:entries jar-record))
                          (= jvm-backend-main-class (:main-class jar-record))
                          (= jvm-backend-module-name
                             (:module-name jar-record)))
             (jvm-backend-fail!
              "B5-MANIFEST" "generated JVM JAR structure is invalid"
              source-path nil
              {:observed-jar jar-record
               :expected-entries expected-entries
               :missing-fact :modular-executable-jar}))
           (let [execution
                 (jvm-backend-run-process!
                  [*jvm-backend-java-command* "-jar" (:jar staged-paths)]
                  source-path "B14-DIFFERENTIAL"
                  "generated JVM artifact execution failed")
                 expected-output
                 (get-in packet [:stage2-runtime-execution-record :stdout])
                 expected-bytes (c-backend-runtime-bytes expected-output)]
             (when-not (= expected-bytes (:stdout-bytes execution))
               (jvm-backend-fail!
                "B14-DIFFERENTIAL"
                "JVM execution differs from the authoritative stage2 runtime"
                source-path nil
                {:expected-stdout-hash
                 (str "sha256:" (sha256-hex expected-output))
                 :actual-stdout-hash
                 (str "sha256:"
                      (sha256-bytes-hex
                       (byte-array (map byte (:stdout-bytes execution)))))
                 :missing-fact :stage2-jvm-execution-equivalence}))
             (let [source-map-text
                   (pr-str (c-backend-canonical-value source-map))
                   _ (jvm-backend-write-file!
                      (.toPath (java.io.File. (:source-map staged-paths)))
                      source-map-text)
                   content-hashes
                   (into {}
                         (map (fn [[kind path]]
                                [kind
                                 (str "sha256:"
                                      (sha256-bytes-hex
                                       (java.nio.file.Files/readAllBytes
                                        (.toPath (java.io.File. path)))))]))
                         (select-keys staged-paths
                                      [:java-source :module-source :class-file
                                       :module-class :jar :source-map]))
                   expected-input
                   {:source-content-hash source-hash
                    :source-declared-target
                    (get-in packet [:target-eligibility
                                    :source-declared-target])
                    :requested-backend-target :jvm
                    :target-eligibility (:target-eligibility packet)
                    :stage2-plan-hash plan-hash
                    :instruction-summary (:instruction-summary plan)
                    :expression-lowering-artifact-hash
                    (:artifact-hash compiler-record)
                    :expression-lowering-source-content-hash
                    (:source-content-hash compiler-record)
                    :expression-lowering-semantic-hash
                    (:semantic-hash compiler-record)
                    :expression-lowering-invoked? (:invoked? compiler-record)
                    :expression-lowering-generic-bridge-residual?
                    (:generic-bridge-residual? compiler-record)
                    :plan-assembly-function
                    (:plan-assembly-function compiler-record)
                    :plan-assembly-artifact-hash
                    (:plan-assembly-artifact-hash compiler-record)
                    :plan-assembly-source-content-hash
                    (:plan-assembly-source-content-hash compiler-record)
                    :plan-assembly-semantic-hash
                    (:plan-assembly-semantic-hash compiler-record)
                    :plan-assembly-invoked?
                    (:plan-assembly-invoked? compiler-record)
                    :plan-assembly-generic-bridge-residual?
                    (:plan-assembly-generic-bridge-residual?
                     compiler-record)
                    :plan-emitter-source-rule-hash
                    (get-in packet
                            [:stage2-plan-emitter-rule :source-rule-hash])
                    :compiler-driver-rule-hash
                    (get-in packet
                            [:stage2-compiler-driver-rule :driver-rule-hash])
                    :runtime-rule-hash
                    (get-in packet [:stage2-runtime-rule :runtime-rule-hash])
                    :runtime-artifact-hash
                    (get-in packet
                            [:stage2-runtime-rule :runtime-artifact-hash])}
                   expected-effects (:effect-summary plan)
                   expected-capabilities (get-in plan [:module :capabilities])
                   manifest-input
                   {:artifact :gravity/jvm-backend-manifest
                    :schema-version 1
                    :backend :gravity.backend/jvm
                    :profile :hosted
                    :target {:classfile 65 :runtime :jvm-21
                             :module-system :named
                             :packaging :modular-executable-jar}
                    :module {:name jvm-backend-module-name
                             :main-class jvm-backend-main-class
                             :side-effects writes-stdout?}
                    :emits [:java-sources :class-files
                            :modular-executable-jar :source-map
                            :manifest :provenance]
                    :content-hashes content-hashes
                    :input expected-input
                    :effects expected-effects
                    :capabilities expected-capabilities
                    :safety {:mode :safe :unsafe-islands []
                             :status :preserved}
                    :managed-runtime
                    {:family :managed :host :jvm-21
                     :delegated #{:startup :gc :classloading}
                     :generated #{:entrypoint :byte-array-values}
                     :linked #{}
                     :forbidden #{:reflection :dynamic-loading :native-access
                                  :threads :monitors}}
                    :host-boundaries
                    (if writes-stdout?
                      [{:class "java.lang.System" :member "out"
                        :operation :write-byte-array
                        :effect :io/write :capability :io/stdout
                        :representation :byte-array}]
                      [])
                    :toolchain {:target-release 21 :encoding :utf8
                                :debug [:source :lines]
                                :annotation-processing :disabled}
                    :conformance
                    {:classfile-major :passed :jar-entries :passed
                     :main-class :passed :stage2-differential :passed
                     :stdout-byte-exact? true :source-map :partial
                     :source-map-coverage :source-unit-only
                     :per-form-origin-preserved? false
                     :b5-conforming? false :verified-mir-input? false}
                    :closed-plan-runtime closed-plan-runtime
                    :clojure-seed-boundary? true
                    :self-hosted? false :release-grade? false
                    :diagnostics []}
                   manifest-hash
                   (str "sha256:"
                        (sha256-hex
                         (pr-str
                          (c-backend-canonical-value
                           (update manifest-input :closed-plan-runtime
                                   p15-s23-closed-runtime-target-semantic-record)))))
                   manifest (assoc manifest-input
                                   :manifest-hash manifest-hash)
                   validation-context
                   {:input expected-input
                    :effects expected-effects
                    :capabilities expected-capabilities
                    :content-hashes content-hashes
                    :closed-runtime-context
                    (p15-s23-closed-runtime-target-context packet)}
                   _ (jvm-backend-validate-manifest!
                      source-path manifest validation-context)
                   _ (jvm-backend-validate-content-hashes!
                      source-path manifest staged-paths)
                   provenance-input
                   {:artifact :gravity/jvm-provenance
                    :schema-version 1 :backend :gravity.backend/jvm
                    :source-content-hash source-hash
                   :stage2-plan-hash plan-hash
                    :stage2-expression-lowering-artifact
                    (dissoc compiler-record :source-path)
                    :target-eligibility (:target-eligibility packet)
                    :stage2-plan-emitter-source-rule-hash
                    (get-in packet
                            [:stage2-plan-emitter-rule :source-rule-hash])
                    :compiler-driver-rule-hash
                    (get-in packet
                            [:stage2-compiler-driver-rule :driver-rule-hash])
                    :runtime-rule-hash
                    (get-in packet [:stage2-runtime-rule :runtime-rule-hash])
                    :closed-plan-runtime closed-plan-runtime
                    :manifest-hash manifest-hash
                    :pass-history [:c2-reader :stage2-source-front-end
                                   :stage2-plan-emitter
                                   :stage2-compiler-driver
                                   :stage2-runtime-executor :jvm-lowering
                                   :javac-21 :deterministic-jar]
                    :seed-boundary {:clojure-seed-boundary? true
                                    :self-hosted? false}}
                   provenance-hash
                   (str "sha256:"
                        (sha256-hex
                         (pr-str
                          (c-backend-canonical-value
                           (update provenance-input :closed-plan-runtime
                                   p15-s23-closed-runtime-target-semantic-record)))))
                   final-paths (when emit?
                                 (jvm-backend-output-paths (str output-path)))
                   provenance
                   (assoc provenance-input
                          :provenance-hash provenance-hash
                          :actual-paths
                          {:source source-path :outputs final-paths
                           :stage2-expression-lowering-source
                           (get-in packet
                                   [:provenance :actual-paths
                                    :stage2-expression-lowering-source])
                           :stage2-runtime-artifact-source
                           (get-in packet
                                   [:provenance :actual-paths
                                    :stage2-runtime-artifact-source])
                           :validation-toolchain
                           {:javac javac-version :java java-version}})
                   _ (jvm-backend-write-file!
                      (.toPath (java.io.File. (:manifest staged-paths)))
                      (pr-str manifest))
                   _ (jvm-backend-write-file!
                      (.toPath (java.io.File. (:provenance staged-paths)))
                      (pr-str provenance))
                   identity
                   {:kind :gravity/jvm-backend-artifact
                    :source-content-hash source-hash
                    :stage2-plan-hash plan-hash
                    :expression-lowering-artifact-hash
                    (:artifact-hash compiler-record)
                    :plan-emitter-source-rule-hash
                    (get-in packet
                            [:stage2-plan-emitter-rule :source-rule-hash])
                    :content-hashes content-hashes
                    :manifest-hash manifest-hash
                    :provenance-hash provenance-hash
                    :closed-plan-target-record-hash
                    (:record-hash closed-plan-runtime)}
                   artifact
                   {:kind :gravity/jvm-backend-artifact
                    :task "HOSTED-JVM-TARGET"
                    :status :complete-for-slice
                    :artifact-id
                    (c4-artifact-id
                     (c-backend-canonical-value identity))
                    :source {:kind :co-canonical-gravity-source
                             :sha256 source-hash}
                    :target (:target manifest)
                    :input-plan-id (:plan-id plan)
                    :input-plan-hash plan-hash
                    :target-eligibility (:target-eligibility packet)
                    :stage2-expression-lowering-artifact compiler-record
                    :plan-emitter-source-rule-hash
                    (get-in packet
                            [:stage2-plan-emitter-rule :source-rule-hash])
                    :instruction-summary (:instruction-summary plan)
                    :effect-summary (:effect-summary plan)
                    :capabilities (get-in plan [:module :capabilities])
                    :java-source java-source
                    :module-source module-source
                    :source-map source-map
                    :manifest manifest :manifest-hash manifest-hash
                    :manifest-validation-context validation-context
                    :provenance provenance :provenance-hash provenance-hash
                    :classfile-major class-major
                    :jar-record jar-record
                    :stage2-compiler-driver-record
                    (:stage2-compiler-driver-record packet)
                    :stage2-runtime-execution-record
                    (:stage2-runtime-execution-record packet)
                    :closed-plan-runtime-target-record closed-plan-runtime
                    :compiled-execution-output expected-output
                    :compiled-execution-output-bytes (:stdout-bytes execution)
                    :seed-boundary {:clojure-seed-boundary? true
                                    :self-hosted? false
                                    :final-release? false}
                    :emitted-files final-paths
                    :diagnostics []}]
               (when emit?
                 (try
                   (java.nio.file.Files/move
                    stage-directory (.toPath output)
                    (into-array java.nio.file.CopyOption
                                [java.nio.file.StandardCopyOption/ATOMIC_MOVE]))
                   (catch Exception ex
                     (jvm-backend-fail!
                      "B5-MANIFEST"
                      "JVM artifact directory could not be atomically committed"
                      source-path nil
                      {:cause-message (.getMessage ex)
                       :missing-fact :atomic-artifact-directory-commit}))))
               artifact))))
       (catch clojure.lang.ExceptionInfo ex
         (throw ex))
       (catch Exception ex
         (jvm-backend-fail!
          "B5-MANIFEST" "JVM artifact construction failed closed"
          source-path nil
          {:cause-message (.getMessage ex)
           :missing-fact :transactional-jvm-artifact}))
       (finally
         (when (.exists (.toFile stage-directory))
           (js-ts-backend-delete-tree! stage-directory)))))))

(defn jvm-backend-file-artifact
  ([path] (jvm-backend-file-artifact path {}))
  ([path options]
   (jvm-backend-source-artifact
    path (read-gravity-source-text path) options)))

(defn compile-source-from-records
  [source-path source-text records]
  (let [macro-artifact (macro-source-artifact-from-records
                        source-path source-text records)
        module (assoc (:module macro-artifact) :forms (:expanded-forms macro-artifact))
        _ (executable-profile! source-path module (:forms module))
        _ (validate-module-effects! module)]
    {:kind :gravity/stage0-hosted-artifact
     :compiler {:owner :clojure-bootstrap
                :stage :stage0
                :retirement-objective :replace-with-gravity-self-hosted-compiler}
     :module (select-keys module [:module :source-path :profile :target :effects :capabilities])
     :syntax-object-stream (:expanded-syntax-object-stream macro-artifact)
     :macro-expansion-trace (:macro-expansion-trace macro-artifact)
     :hosted-execution {:entrypoint 'main
                        :runtime :clojure/jvm
                        :effects (:effects module)
                        :capabilities (:capabilities module)}}))

(defn compile-source
  [source-path source-text]
  (compile-source-from-records
   source-path source-text
   (read-source-form-records source-path source-text)))

(defn source-path-policy-fail!
  ([source-path]
   (let [source-file (java.io.File. source-path)
         bytes (when (.isFile source-file)
                 (java.nio.file.Files/readAllBytes (.toPath source-file)))]
     (source-path-policy-fail! source-path bytes)))
  ([source-path bytes]
   (let [bytes-hash (when bytes
                      (str "sha256:" (sha256-bytes-hex bytes)))
         span {:source source-path :byte-start 0 :byte-end 0}]
     (fail! "L1-SOURCE-EXTENSION"
            "Gravity source path does not use a co-canonical source extension"
            (cond->
             {:severity :error
              :stage :read-source
              :source-span span
              :primary (cond-> {:span span}
                         bytes-hash (assoc :artifact bytes-hash))
              :related []
              :origin-chain
              [(cond-> {:kind :source-path :path source-path}
                 bytes-hash (assoc :source-id bytes-hash))]
              :profile nil
              :target nil
              :facts
              (cond->
               {:actual-extension (gravity-source-extension source-path)
                :allowed-extensions
                (vec (sort co-canonical-source-extensions))}
                bytes-hash (assoc :bytes-hash bytes-hash
                                  :byte-count (alength bytes)))
              :reader-state {:stage :source-unit-policy}
              :remediation
              "Rename the source to .qst or .gravity; both are canonical and first-class."}
              bytes-hash (assoc :source-id bytes-hash))))))

(defn decode-gravity-source-bytes
  "Decode one already-captured source snapshot without reopening its path."
  [path bytes]
  (let [decoder (doto (.newDecoder java.nio.charset.StandardCharsets/UTF_8)
                  (.onMalformedInput java.nio.charset.CodingErrorAction/REPORT)
                  (.onUnmappableCharacter
                   java.nio.charset.CodingErrorAction/REPORT))
        input (java.nio.ByteBuffer/wrap bytes)
        output (java.nio.CharBuffer/allocate (max 1 (alength bytes)))
        result (.decode decoder input output true)]
    (when (.isError result)
      (let [start (.position input)
            end (+ start (max 1 (.length result)))
            bytes-hash (str "sha256:" (sha256-bytes-hex bytes))]
        (fail! "L1-SOURCE-ENCODING"
               "source bytes cannot be decoded as UTF-8"
               {:severity :error
                :stage :read-source
                :source-id bytes-hash
                :source-span {:source path
                              :byte-start start
                              :byte-end end}
                :primary {:span {:source path
                                 :byte-start start
                                 :byte-end end}
                          :artifact bytes-hash}
                :related []
                :origin-chain [{:kind :source-bytes :path path}]
                :profile nil
                :target nil
                :facts {:declared-encoding :utf-8
                        :bytes-hash bytes-hash
                        :malformed-input-length (.length result)}
                :reader-state {:stage :source-decoding
                               :encoding :utf-8}
                :remediation "Save the source as valid UTF-8 without replacement decoding."})))
    (let [flush-result (.flush decoder output)]
      (when (.isError flush-result)
        (.throwException flush-result)))
    (.flip output)
    (.toString output)))

(defn read-gravity-source-text
  [path]
  (when-not (qst-or-gravity-source? path)
    (source-path-policy-fail! path))
  (decode-gravity-source-bytes
   path
   (java.nio.file.Files/readAllBytes
    (.toPath (java.io.File. path)))))

(defn compile-file
  [path]
  (compile-source path (read-gravity-source-text path)))

