(def c2-reader-override-diagnostics
  {:encoding "C2-ENCODING"
   :abbrev "C2-ABBREV"
   :hash "C2-HASH"})

(defn c2-reader-source-overrides
  [module]
  (get-in module [:metadata :compiler :c2-reader] {}))

(defn c2-reader-message
  [id]
  (case id
    "C2-ENCODING" "source decoding failed or used an undeclared encoding"
    "C2-DELIMITER" "reader delimiter structure is malformed"
    "C2-STRING" "string or character literal is malformed"
    "C2-NUMERIC" "numeric candidate fails every enabled numeric literal grammar"
    "C2-IDENTIFIER" "symbol or keyword has an invalid surface spelling"
    "C2-NS-SHAPE" "namespace clause has invalid reader-level syntax shape"
    "C2-MAP" "map literal has odd arity"
    "C2-SET" "literal set contains duplicate entries decidable at read time"
    "C2-METADATA" "metadata is unattached or has invalid reader shape"
    "C2-ABBREV" "reader abbreviation placement is invalid"
    "C2-EXTENSION" "source extension is noncanonical or reader extension is unknown, disallowed, or effect-violating"
    "C2-HASH" "reader artifact identity is unstable or incomplete"
    "reader document coverage failed"))

(defn c2-reader-fail!
  [id source-path subject extra]
  (let [raw-span (or (:source-span subject)
                     (:source-span extra)
                     (source-span source-path 0))
        source-id (or (:source-id subject)
                      (:source-id extra)
                      (get-in subject [:primary :artifact])
                      (get-in extra [:primary :artifact]))
        span (cond-> raw-span
               (and source-id (not (:file raw-span)))
               (assoc :file source-id))
        raw (or (:raw subject) (:raw-spelling subject)
                (:raw extra) (:raw-spelling extra))
        token-id (or (:token-id subject) (:token-id extra))
        form-id (or (:form-id subject) (:form-id extra))
        facts (merge (or (:facts subject) {})
                     (or (:facts extra) {}))
        remediation
        "Regenerate reader artifacts with deterministic decoding, spans, raw literal facts, extension policy, and stable incremental hashes."
        defaults
        {:artifact :gravity/diagnostic
         :diagnostic-id
         (reader-canonical-hash
          {:rule (keyword id)
           :primary-artifact source-id
           :stage :read-source
           :span (dissoc span :source)
           :token-id token-id
           :form-id form-id
           :facts facts})
         :rule (keyword id)
         :severity :error
         :source-id source-id
         :source-span span
         :primary {:span span :artifact source-id}
         :related []
         :origin-chain [{:kind :source
                         :source-id source-id
                         :path source-path}]
         :profile nil
         :target nil
         :facts facts
         :diagnostic-family :c2-reader
         :stage :read-source
         :document-id "C2"
         :expected-document c2-reader-governing-document
         :involved-artifacts (cond-> [] source-id (conj source-id))
         :token-id token-id
         :form-id form-id
         :raw-spelling raw
         :reader-options (or (:reader-options subject)
                             (:reader-options extra))
         :extension-tag (or (:extension-tag subject)
                            (:extension-tag extra))
         :reader-state {:artifact :gravity/reader-state
                        :stage :read-source
                        :byte-offset (:byte-start span)
                        :line (get-in span [:start :line])
                        :column (get-in span [:start :column])
                        :token-id token-id
                        :form-id form-id}
         :redactions []
         :lifecycle :active
         :remediation remediation
         :remediation-records [{:kind :fix-reader-source}]}
        payload (-> (merge defaults extra)
                    (assoc :artifact (:artifact defaults)
                           :diagnostic-id (:diagnostic-id defaults)
                           :rule (:rule defaults)
                           :severity (:severity defaults)
                           :source-id source-id
                           :source-span span
                           :primary (:primary defaults)
                           :facts facts
                           :diagnostic-family :c2-reader
                           :stage :read-source
                           :document-id "C2"
                           :expected-document c2-reader-governing-document
                           :token-id (:token-id defaults)
                           :form-id (:form-id defaults)
                           :raw-spelling raw
                           :reader-options (:reader-options defaults)
                           :extension-tag (:extension-tag defaults)
                           :remediation remediation
                           :remediation-records
                           [{:kind :fix-reader-source}]))]
    (fail! id (c2-reader-message id) payload)))

(defn c2-reader-remap-exception!
  [source-path ex]
  (let [data (ex-data ex)
        old-id (:id data)
        cause (str (or (:cause-message data) (:message data)))
        reader-engine-diagnostic
        (when (and (string? old-id) (str/starts-with? old-id "STAGE1"))
          old-id)
        owner-id (case old-id
                   ("STAGE1READER001" "STAGE1READER002") "L1-DELIMITER"
                   "STAGE1READER003" "L1-STRING"
                   "STAGE1READER004" "L1-READER-EXTENSION"
                   "STAGE1READER005" "L1-MAP-ARITY"
                   "STAGE1READER007" "L1-NUMERIC"
                   old-id)
        id (cond
             (= "L1-SOURCE-ENCODING" owner-id) "C2-ENCODING"
             (= "L1-SOURCE-EXTENSION" owner-id) "C2-EXTENSION"
             (= "L1-DELIMITER" owner-id) "C2-DELIMITER"
             (= "L1-STRING" owner-id) "C2-STRING"
             (= "L1-NUMERIC" owner-id) "C2-NUMERIC"
             (= "L1-IDENTIFIER" owner-id) "C2-IDENTIFIER"
             (= "L1-NS-SHAPE" owner-id) "C2-NS-SHAPE"
             (= "L1-MAP-ARITY" owner-id) "C2-MAP"
             (= "L1-METADATA" owner-id) "C2-METADATA"
             (= "L1-READER-EXTENSION" owner-id) "C2-EXTENSION"
             (str/includes? cause "Duplicate key") "C2-SET"
             :else owner-id)
        span (:source-span data)
        reader-state
        (or (:reader-state data)
            {:artifact :gravity/reader-state
             :stage (if (contains? #{"STAGE1READER003"
                                     "STAGE1READER004"
                                     "STAGE1READER007"}
                                   old-id)
                      :lexical-tokenization
                      :recursive-form-building)
             :byte-offset (:byte-start span)
             :line (get-in span [:start :line])
             :column (get-in span [:start :column])
             :token-id (:token-id data)
             :form-id (:form-id data)})]
    (if (contains? (set c2-reader-diagnostic-ids) id)
      (let [preserved-fields
            (dissoc data :id :message :diagnostic-family :reader-options)]
        (c2-reader-fail!
         id source-path data
         (cond-> (assoc preserved-fields
                        :cause-message (or (:cause-message data)
                                           (:message data))
                        :reader-options standard-reader-options
                        :reader-state reader-state)
           (and owner-id (not= owner-id id))
           (assoc :remapped-from owner-id)

           reader-engine-diagnostic
           (assoc :reader-engine-diagnostic reader-engine-diagnostic))))
      (throw ex))))

(defn c2-reader-validate-overrides!
  [source-path overrides source-unit token-stream]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get c2-reader-override-diagnostics fail-kind)]
      (let [failure-token (or (some #(when (= fail-kind (:decoded %)) %)
                                    token-stream)
                              (first token-stream))]
        (c2-reader-fail! id source-path
                         {:source-id (:source-id source-unit)
                          :source-span (:span failure-token)
                          :token-id (:token-id failure-token)
                          :raw (:raw failure-token)
                          :reader-options (:reader-options source-unit)
                          :extension-tag (:extension-tag overrides)}
                         {:missing-fields [fail-kind]})))))

(defn reader-canonical-value
  [value]
  (cond
    (map? value)
    (let [decorated
          (mapv
           (fn [[key item]]
             (let [entry [(reader-canonical-value key)
                          (reader-canonical-value item)]]
               [(pr-str entry) entry]))
           value)]
      [:map
       (->> decorated
            (sort-by first)
            (mapv second))])

    (set? value)
    [:set (->> value
               (map reader-canonical-value)
               (sort-by pr-str)
               vec)]

    (vector? value)
    [:vector (mapv reader-canonical-value value)]

    (seq? value)
    [:list (mapv reader-canonical-value value)]

    :else value))

(defn reader-canonical-hash
  [value]
  (str "sha256:"
       (sha256-hex
        (binding [*print-length* nil
                  *print-level* nil
                  *print-meta* true]
          (pr-str (reader-canonical-value value))))))

(def standard-reader-policy
  {:policy :gravity/standard-reader
   :version 1
   :registered-tags ['inst 'uuid]
   :ambient-authority :denied})

(def standard-reader-options
  {:retain-comments true
   :enabled-features #{:standard-reader}
   :extension-policy (reader-canonical-hash standard-reader-policy)})

(defn reader-project-root-path
  [source-path]
  (let [source-file (.getCanonicalFile (java.io.File. source-path))
        start (if (.isDirectory source-file)
                source-file
                (.getParentFile source-file))]
    (or (loop [candidate start]
          (when candidate
            (if (.isFile (java.io.File. candidate "deps.edn"))
              candidate
              (recur (.getParentFile candidate)))))
        start
        (.getParentFile source-file))))

(defn reader-project-root-id
  [project-root-path]
  (let [manifest (java.io.File. project-root-path "deps.edn")]
    (if (.isFile manifest)
      (reader-canonical-hash
       {:project-manifest "deps.edn"
        :bytes-hash
        (str "sha256:"
             (sha256-bytes-hex
              (java.nio.file.Files/readAllBytes (.toPath manifest))))})
      (reader-canonical-hash {:project-root-kind :standalone-source-root}))))

(defn reader-normalize-relative-path
  [path]
  (let [slash-path (str/replace (str path) "\\" "/")]
    (->> (str/split slash-path #"/")
         (reduce (fn [segments segment]
                   (cond
                     (or (str/blank? segment) (= "." segment))
                     segments

                     (= ".." segment)
                     (if (and (seq segments) (not= ".." (peek segments)))
                       (pop segments)
                       (conj segments segment))

                     :else
                     (conj segments segment)))
                 [])
         (str/join "/"))))

(defn reader-platform-neutral-absolute-path?
  [path]
  (let [slash-path (str/replace (str path) "\\" "/")]
    (or (str/starts-with? slash-path "/")
        (boolean (re-find #"(?i)^[a-z]:" slash-path)))))

(defn reader-valid-project-relative-path?
  [path]
  (let [normalized-path (reader-normalize-relative-path path)]
    (and (not (reader-platform-neutral-absolute-path? path))
         (not (str/blank? normalized-path))
         (not= ".." (first (str/split normalized-path #"/"))))))

(defn reader-project-context-for-source
  [source-path]
  (let [source-file (.getCanonicalFile (java.io.File. source-path))
        project-root (.getCanonicalFile
                      (reader-project-root-path source-path))
        relative-path (.relativize (.toPath project-root)
                                   (.toPath source-file))]
    {:project-root-id (reader-project-root-id project-root)
     :project-root-path (.getPath project-root)
     :project-relative-path (reader-normalize-relative-path relative-path)}))

(defn reader-explicit-project-context
  [project-context]
  (let [project-root-id (:project-root-id project-context)
        project-relative-path (:project-relative-path project-context)
        normalized-path (when (string? project-relative-path)
                          (reader-normalize-relative-path
                           project-relative-path))]
    (when-not (and (string? project-root-id)
                   (re-matches #"sha256:[0-9a-f]{64}" project-root-id)
                   (string? normalized-path)
                   (reader-valid-project-relative-path?
                    project-relative-path))
      (throw
       (ex-info
        "reader project context requires a project-root id and relative path"
        {:id "C2-HASH"
         :project-context project-context
         :normalized-project-relative-path normalized-path
         :missing-fields
         (vec (remove #(get project-context %)
                      [:project-root-id :project-relative-path]))})))
    (assoc project-context
           :project-relative-path
           normalized-path)))

(defn reader-valid-options?
  [reader-options]
  (and (map? reader-options)
       (boolean? (:retain-comments reader-options))
       (set? (:enabled-features reader-options))
       (string? (:extension-policy reader-options))
       (boolean
        (re-matches #"sha256:[0-9a-f]{64}"
                    (:extension-policy reader-options)))))

(defn reader-validate-options!
  [reader-options]
  (when-not (reader-valid-options? reader-options)
    (throw
     (ex-info
      "reader options must be deterministic and content-addressed"
      {:id "C2-HASH"
       :reader-options reader-options
       :required-fields
       {:retain-comments :boolean
        :enabled-features :set
        :extension-policy :sha256-lowercase-hex}})))
  reader-options)

(defn reader-project-root-record
  [project-context]
  (let [context (reader-explicit-project-context project-context)]
    {:path (:project-root-path context)
     :project-root-id (:project-root-id context)}))

(defn reader-source-identity-inputs
  [source-text reader-options project-context]
  (let [context (reader-explicit-project-context project-context)
        options (reader-validate-options! reader-options)]
    {:project-root-id (:project-root-id context)
     :project-relative-path (:project-relative-path context)
     :encoding :utf-8
     :bytes-hash (str "sha256:" (sha256-hex source-text))
     :reader-options options
     :enabled-features (:enabled-features options)
     :extension-policy (:extension-policy options)}))

(defn c2-source-unit-record
  ([source-path source-text reader-options]
   (c2-source-unit-record source-path source-text reader-options
                          (reader-project-context-for-source source-path)))
  ([source-path source-text reader-options project-context]
   (let [context (reader-explicit-project-context project-context)
         identity-inputs (reader-source-identity-inputs source-text
                                                        reader-options
                                                        context)
         project-root (reader-project-root-record context)]
     (merge
      {:artifact :gravity/source-unit
       :source-id (reader-canonical-hash identity-inputs)
       :path source-path
       :extension (gravity-source-extension source-path)
       :source-kind (gravity-source-kind source-path)
       :project-relative-path (:project-relative-path context)
       :project-root (:project-root-id context)
       :project-root-record project-root
       :identity-inputs identity-inputs}
      (select-keys identity-inputs
                   [:encoding :bytes-hash :reader-options
                    :enabled-features :extension-policy])))))

(defn c2-token-record
  [token source-unit]
  (let [source-id (:source-id source-unit)]
    (-> token
        (assoc :token-id (keyword (str "tok-" (:index token)))
               :source-id source-id
               :source-path (:path source-unit)
               :span (assoc (:span token) :file source-id)
               :trivia-before []
               :reader-origin :source)
        (dissoc :index))))

(defn c2-form-record
  [record source-unit]
  (let [source-id (:source-id source-unit)]
    (-> record
        (assoc :source-id source-id
               :source-path (:path source-unit)
               :span (assoc (:span record) :file source-id)
               :origin (merge {:kind :source
                               :source-id source-id
                               :source-path (:path source-unit)}
                              (when (map? (:origin record))
                                (:origin record)))))))

(defn c2-literal-records
  [form-tree]
  (let [literal-kinds #{:nil :boolean :integer :ratio :decimal :string
                        :character :symbol :keyword :tagged-literal}
        candidates (filter #(contains? literal-kinds (:kind %)) form-tree)]
    (mapv
     (fn [idx {:keys [kind raw value span tag form-id]}]
       {:literal-id (keyword (str "lit-" idx))
        :form-id form-id
        :kind kind
        :raw raw
        :decoded value
        :span span
        :facts
        (case kind
          :integer
          {:radix (cond
                    (re-find #"^[+-]?0[xX]" raw) 16
                    (re-find #"^[+-]?0[bB]" raw) 2
                    :else 10)
           :sign (cond
                   (str/starts-with? raw "-") :negative
                   (str/starts-with? raw "+") :explicit-positive
                   :else :unsigned)
           :exact? true}
          :ratio
          (let [[numerator denominator] (str/split raw #"/" 2)]
            {:numerator-spelling numerator
             :denominator-spelling denominator
             :exact? true})
          :decimal
          {:exponent-spelling (second (re-find #"([eE][+-]?[0-9]+)" raw))
           :exact? false}
          :string
          {:escapes (mapv (fn [[match offset]]
                            {:raw match :character-offset offset})
                          (map vector
                               (re-seq #"\\(?:[btnfr\"\\]|u[0-9A-Fa-f]{4})"
                                       raw)
                               (keep-indexed (fn [offset ch]
                                               (when (= \\ ch) offset))
                                             raw)))}
          :character {:escape raw}
          :symbol {:namespace (namespace value)}
          :keyword {:namespace (namespace value)}
          :tagged-literal {:tag tag}
          {})})
     (range)
     candidates)))

(defn c2-trivia-records
  [token-stream]
  (mapv (fn [token]
          {:trivia-id (:token-id token)
           :kind (:kind token)
           :raw (:raw token)
           :span (:span token)
           :source-id (:source-id token)
           :source-path (:source-path token)})
        (filter :trivia? token-stream)))

(defn c2-semantic-form-hash-input
  [form-tree]
  (mapv #(select-keys % [:form-id :kind :collection-kind :children
                         :parent-form-id :abbrev :tag :value :metadata])
        form-tree))

(defn c2-path-neutral-span
  [span]
  (if (map? span) (dissoc span :source) span))

(defn c2-token-hash-input
  [token-stream]
  (mapv #(-> %
             (dissoc :source-path)
             (update :span c2-path-neutral-span))
        token-stream))

(defn c2-form-hash-input
  [form-tree]
  (mapv (fn [form]
          (-> form
              (dissoc :source-path)
              (update :span c2-path-neutral-span)
              (update :surface-span c2-path-neutral-span)
              (update :origin #(when % (dissoc % :source-path)))
              (update :generated-origin
                      (fn [origins]
                        (mapv #(update % :from c2-path-neutral-span)
                              (or origins []))))))
        form-tree))

(defn c2-syntax-seed-hash-input
  [syntax-seeds]
  (mapv (fn [seed]
          (cond-> (update seed :span c2-path-neutral-span)
            (contains? seed :generated-origin)
            (update :generated-origin
                    (fn [origins]
                      (mapv #(cond-> %
                               (contains? % :from)
                               (update :from c2-path-neutral-span))
                            origins)))))
        syntax-seeds))

(defn c2-extension-hash-input
  [extension-invocations]
  (let [semantic-span
        (fn [span]
          (if (map? span)
            (dissoc span :source :file)
            span))]
    (mapv
     (fn [invocation]
       (cond-> (dissoc invocation :source-path)
         (contains? invocation :span)
         (update :span semantic-span)

         (contains? invocation :invocations)
         (update :invocations
                 (fn [records]
                   (mapv #(cond-> %
                            (contains? % :span)
                            (update :span semantic-span))
                         records)))))
     extension-invocations)))

(defn c2-diagnostic-hash-input
  [diagnostics]
  (mapv
   (fn [diagnostic]
     (cond-> diagnostic
       (contains? diagnostic :source-span)
       (update :source-span c2-path-neutral-span)

       (get-in diagnostic [:primary :span])
       (update-in [:primary :span] c2-path-neutral-span)

       (contains? diagnostic :related)
       (update :related
               (fn [related]
                 (mapv #(cond-> %
                          (contains? % :span)
                          (update :span c2-path-neutral-span))
                       related)))

       (contains? diagnostic :origin-chain)
       (update :origin-chain
               (fn [origins]
                 (mapv #(cond-> (dissoc % :path)
                          (contains? % :span)
                          (update :span c2-path-neutral-span))
                       origins)))))
   diagnostics))

(defn c2-incremental-hashes
  [source-unit token-stream form-tree syntax-seeds extension-invocations
  diagnostics]
  (let [graph-metrics (c2-form-graph-metrics form-tree)
        max-depth (:max-form-depth graph-metrics)
        _ (when-not (:acyclic? graph-metrics)
            (c2-reader-fail!
             "C2-HASH" (:path source-unit)
             {:stage :read-source
              :source-id (:source-id source-unit)
              :source-span (or (:span (first form-tree))
                               (source-span (:path source-unit) 0))
              :reader-options (:reader-options source-unit)}
             {:missing-fields [:acyclic-reader-form-graph]
              :facts {:failure-kind :reader-form-cycle}}))
        _ (when (> max-depth max-reader-form-graph-depth)
            (c2-reader-fail!
             "C2-HASH" (:path source-unit)
             {:stage :read-source
              :source-id (:source-id source-unit)
              :source-span (or (:span (first form-tree))
                               (source-span (:path source-unit) 0))
              :reader-options (:reader-options source-unit)}
             {:missing-fields [:bounded-reader-form-depth]
              :facts {:observed-form-depth max-depth
                      :maximum-form-depth max-reader-form-graph-depth
                      :failure-kind :reader-resource-depth-limit}}))
        retain-trivia? (true? (get-in source-unit
                                      [:reader-options :retain-comments]))
        form-hash-input (if retain-trivia?
                          (c2-form-hash-input form-tree)
                          (c2-semantic-form-hash-input form-tree))
        token-hash-input (c2-token-hash-input token-stream)
        syntax-hash-input (c2-syntax-seed-hash-input syntax-seeds)
        extension-hash-input (c2-extension-hash-input extension-invocations)
        diagnostic-hash-input (c2-diagnostic-hash-input diagnostics)]
    {:artifact :gravity/reader-incremental-hashes
     :source-unit (:source-id source-unit)
     :token-stream (reader-canonical-hash token-hash-input)
     :form-tree (reader-canonical-hash form-hash-input)
     :syntax-seed-stream (reader-canonical-hash syntax-hash-input)
     :extension-invocation-set (reader-canonical-hash extension-hash-input)
     :reader-diagnostics (reader-canonical-hash diagnostic-hash-input)
     :retained-trivia-affects-form-tree? retain-trivia?
     :status :stable}))

(defn c2-reader-product-integrity-record
  [source-unit top-level-form-ids incremental-hashes literal-records
   deferred-literal-records]
  (let [literal-input
        (mapv #(update % :span c2-path-neutral-span) literal-records)
        deferred-input
        (mapv #(update % :span c2-path-neutral-span)
              deferred-literal-records)
        input
        {:source-id (:source-id source-unit)
         :source-identity-inputs (:identity-inputs source-unit)
         :source-bytes-hash (:bytes-hash source-unit)
         :reader-options (:reader-options source-unit)
         :top-level-form-ids (vec top-level-form-ids)
         :incremental-reader-hashes incremental-hashes
         :literal-records-hash (reader-canonical-hash literal-input)
         :deferred-literal-records-hash
         (reader-canonical-hash deferred-input)}
        integrity-hash (reader-canonical-hash input)]
    {:artifact :gravity/c2-reader-product-integrity
     :algorithm :sha256
     :input input
     :integrity-hash integrity-hash
     :status :verified}))

(defn c2-reader-artifact-id
  [artifact]
  (reader-canonical-hash
   {:kind (:kind artifact)
    :task (:task artifact)
    :document-set (:document-set artifact)
    :source-id (get-in artifact [:source-unit-record :source-id])
    :reader-product-integrity (:reader-product-integrity artifact)
    :incremental-reader-hashes (:incremental-reader-hashes artifact)
    :representation-boundary (:representation-boundary artifact)
    :source-overrides (:source-overrides artifact)
    :capability-based-proof (:capability-based-proof artifact)}))

(defn c2-prevalidate-token-depth!
  [source-path source-unit token-stream]
  (loop [tokens token-stream
         depth 0]
    (when-let [token (first tokens)]
      (let [next-depth
            (cond
              (contains? #{:list-open :vector-open :map-open :set-open}
                         (:kind token))
              (inc depth)

              (= :close (:kind token))
              (max 0 (dec depth))

              :else depth)]
        (when (> next-depth max-reader-form-depth)
          (c2-reader-fail!
           "C2-HASH" source-path
           {:stage :read-source
            :source-id (:source-id source-unit)
            :source-span (:span token)
            :token-id (keyword (str "tok-" (:index token)))
            :raw (:raw token)
            :reader-options (:reader-options source-unit)}
           {:missing-fields [:bounded-reader-token-depth]
            :facts {:observed-form-depth next-depth
                    :maximum-form-depth max-reader-form-depth
                    :failure-kind :reader-resource-depth-limit}}))
        (recur (next tokens) next-depth))))
  :complete)

;; SH-03 executes only this exact Gravity-authored reader closure.  The pinned
;; values are filled after the leaf source and its independent review freeze.
;; Keeping these separate from the builder makes the source/plan tripwire
;; explicit and prevents a rebuild from silently authorizing changed code.
(def sh03-reader-expected-source-byte-count 257161)
(def sh03-reader-uncredited-source-model-entrypoints
  ['stage1-read-source-formal-release-governance-seed-retirement
   'stage1-read-source-release-attestation-seed-retirement
   'stage1-read-source-diverse-bootstrap-verification
   'stage1-read-source-verified-boot-chain
   'stage1-read-source-runtime-image
   'stage1-read-source-runtime-entrypoint
   'stage1-read-source-compiler-driver
   'stage1-read-source-core-bootstrap
   'stage1-read-source-self-hosted-runtime])
(def sh03-reader-expected-source-content-hash
  "sha256:bd262c746ad88d9213e4b3160943fecde948c5ceee12a65dfe67ffb29d4e5b77")
(def sh03-reader-expected-plan-semantic-hash
  "sha256:25689f7c0bf9c1872aab4f3e41ac930efdf8c350231b14b2573e23a6d76fc475")
(def sh03-reader-expected-functions-semantic-hash
  "sha256:2e7bd1504df9cac0451d391f4f20cd5fac524e4f289289d136ac43f279f759cb")
(def sh03-reader-expected-function-count 231)
(def sh03-reader-expected-function-names-hash
  "sha256:27c0e98eec6e92acdf9d4c5a9db966374136f1c8084f7e9f13bea1610d6bf868")
(def sh03-reader-expected-function-shapes-hash
  "sha256:af3f655c92eb88945c6a46cdc8f0dcc157c92a8e7f9cd80cc2595129bd088e07")
(def sh03-reader-expected-entrypoint-semantic-hash
  "sha256:9ea6a927c2f25fa80b123af18d3a6824bd9e2863e8c55fbc9f02839d882eb0cc")
(def sh03-reader-expected-verifier-semantic-hash
  "sha256:625bbeccf94f75fedbd6232e4a54b1a44435f06bf07352b8d19b1a35196038a7")
(def sh03-reader-expected-builtin-functions-hash
  "sha256:03394c173b55bcb279070adc77d0494ee334c42505d814593f46109000dc1400")

(declare sh03-reader-canonical-maximum-scalar-bytes
         sh03-reader-canonical-maximum-total-scalar-bytes)

(def sh03-reader-source-relative-path
  "bootstrap/gravity/src/gravity/bootstrap/reader.gravity")
(def sh03-reader-entrypoint 'sh03-read-source-unit)
(def sh03-reader-verifier 'sh03-verify-reader-result)
(def sh03-reader-function-prefix "sh03-")
(def sh03-reader-plan-maximum-nodes 524288)
(def sh03-reader-plan-maximum-depth 512)
(def sh03-reader-plan-maximum-width 131072)
(def sh03-reader-result-maximum-nodes 167772160)
(def sh03-reader-result-maximum-depth 2048)
(def sh03-reader-result-maximum-width 1048576)
(def sh03-reader-input-maximum-identity-utf8-bytes 4096)
(def sh03-reader-input-maximum-identity-code-units 1024)

(def sh03-reader-plan-keys
  #{:kind :compiler-artifact-plan? :entrypoint :source :compiler :module
    :functions :instruction-summary :effect-summary :sh03-reader :plan-id})

(def sh03-reader-function-keys
  #{:name :params :arity :body-form-count :binding :instructions})

(def sh03-reader-binding-keys
  #{:name :kind :namespace :profile :target :visibility :effects
    :capabilities})

(def sh03-reader-instruction-keysets
  {:literal #{:op :value}
   :quote #{:op :value}
   :local #{:op :name}
   :vector-literal #{:op :items}
   :set-literal #{:op :items}
   :map-literal #{:op :entries}
   :do #{:op :body}
   :if #{:op :test :then :else}
   :let #{:op :bindings :body}
   :loop #{:op :bindings :binding-count :body}
   :recur #{:op :args}
   :builtin-call #{:op :function :args}
   :function-call #{:op :function :args}})

(def sh03-reader-allowed-opcodes
  (set (keys sh03-reader-instruction-keysets)))

(def sh03-reader-allowed-builtins
  (set/union stage0-builtin-functions
             p15-s23-stage2-compiler-artifact-builtins))

(defn sh03-reader-boundary-fail!
  [source-path missing-fact subject facts]
  (c2-reader-fail!
   "C2-HASH" source-path
   {:stage :read-source
    :source-span (source-span source-path 0)
    :reader-options standard-reader-options}
   {:missing-fields [missing-fact]
    :facts (merge {:sh03-boundary :gravity-reader-plan}
                  facts)
    :observed subject}))

(defn sh03-reader-resolve-source-path
  []
  (let [anchor (java.io.File.
                (p15-s23-stage2-compiler-artifact-source-path))
        start (if (.isDirectory anchor) anchor (.getParentFile anchor))]
    (or
     (loop [directory start]
       (when directory
         (let [candidate (java.io.File. directory
                                        sh03-reader-source-relative-path)]
           (if (.isFile candidate)
             (.getPath candidate)
             (recur (.getParentFile directory))))))
     sh03-reader-source-relative-path)))

(defn sh03-reader-read-pinned-source-bytes!
  [request-source]
  (let [source-path (sh03-reader-resolve-source-path)
        path (.toPath (java.io.File. source-path))
        nofollow (into-array java.nio.file.LinkOption
                             [java.nio.file.LinkOption/NOFOLLOW_LINKS])
        attributes
        (try
          (java.nio.file.Files/readAttributes
           path java.nio.file.attribute.BasicFileAttributes nofollow)
          (catch Exception error
            (sh03-reader-boundary-fail!
             request-source :pinned-sh03-reader-source-readable
             source-path {:cause-message (.getMessage error)})))]
    (when-not (and attributes
                   (.isRegularFile attributes)
                   (= (long sh03-reader-expected-source-byte-count)
                      (.size attributes)))
      (sh03-reader-boundary-fail!
       request-source :exact-regular-pinned-sh03-reader-source
       source-path
       {:expected-source-byte-count sh03-reader-expected-source-byte-count
        :observed-source-byte-count (when attributes (.size attributes))
        :regular-file? (boolean (and attributes
                                     (.isRegularFile attributes)))}))
    (let [limit (inc sh03-reader-expected-source-byte-count)
          buffer (byte-array limit)
          observed
          (try
            (with-open [input
                        (java.nio.file.Files/newInputStream
                         path
                         (into-array java.nio.file.OpenOption
                                     [java.nio.file.LinkOption/NOFOLLOW_LINKS]))]
              (loop [offset 0]
                (if (= offset limit)
                  offset
                  (let [n (.read input buffer offset (- limit offset))]
                    (if (= -1 n) offset (recur (+ offset n)))))))
            (catch Exception error
              (sh03-reader-boundary-fail!
               request-source :stable-pinned-sh03-reader-source-read
               source-path {:cause-message (.getMessage error)})))
          bytes (java.util.Arrays/copyOf
                 buffer sh03-reader-expected-source-byte-count)
          content-hash (str "sha256:" (sha256-bytes-hex bytes))]
      (when-not (and (= sh03-reader-expected-source-byte-count observed)
                     (= sh03-reader-expected-source-content-hash content-hash))
        (sh03-reader-boundary-fail!
         request-source :pinned-sh03-reader-source-identity
         source-path
         {:expected-source-byte-count sh03-reader-expected-source-byte-count
          :observed-source-byte-count observed
          :expected-source-content-hash
          sh03-reader-expected-source-content-hash
          :observed-source-content-hash content-hash}))
      {:source-path source-path
       :bytes bytes
       :source-byte-count observed
       :source-content-hash content-hash})))

(defn sh03-reader-strict-source-text!
  [request-source source-path bytes]
  (try
    (str
     (.decode
      (doto (.newDecoder java.nio.charset.StandardCharsets/UTF_8)
        (.onMalformedInput java.nio.charset.CodingErrorAction/REPORT)
        (.onUnmappableCharacter java.nio.charset.CodingErrorAction/REPORT))
      (java.nio.ByteBuffer/wrap bytes)))
    (catch java.nio.charset.CharacterCodingException error
      (sh03-reader-boundary-fail!
       request-source :valid-utf8-pinned-sh03-reader-source
       source-path {:cause-message (.getMessage error)}))))

(defn sh03-reader-plan-instruction-summary
  [source-path functions]
  (loop [pending
         (reduce
          (fn [tasks [_ function]]
            (into tasks (map #(vector % 1) (:instructions function))))
          [] functions)
         summary {}
         builtins #{}
         observed-nodes 0
         observed-depth 0]
    (when (> observed-nodes sh03-reader-plan-maximum-nodes)
      (sh03-reader-boundary-fail!
       source-path :bounded-sh03-reader-plan-instructions
       observed-nodes {:maximum-nodes sh03-reader-plan-maximum-nodes}))
    (if (empty? pending)
      {:instruction-summary summary
       :builtin-functions builtins
       :observed-nodes observed-nodes
       :observed-depth observed-depth}
      (let [[instruction depth] (peek pending)
            pending (pop pending)
            op (:op instruction)
            children
            (case op
              (:literal :quote :local) []
              (:vector-literal :set-literal) (:items instruction)
              :map-literal
              (mapcat (juxt :key :value) (:entries instruction))
              :do (:body instruction)
              :if [(:test instruction) (:then instruction) (:else instruction)]
              (:let :loop)
              (concat (map :expr (:bindings instruction))
                      (:body instruction))
              :recur (:args instruction)
              (:builtin-call :function-call) (:args instruction)
              [])]
        (recur
         (into pending (map #(vector % (inc depth)) children))
         (update summary op (fnil inc 0))
         (cond-> builtins (= :builtin-call op)
           (conj (:function instruction)))
         (inc observed-nodes)
         (max observed-depth depth))))))

(defn sh03-reader-build-plan!
  [request-source {:keys [source-path bytes source-byte-count
                          source-content-hash]}]
  (let [source-text
        (sh03-reader-strict-source-text!
         request-source source-path bytes)
        macro-artifact (macro-source-artifact source-path source-text)
        module-base (assoc (:module macro-artifact)
                           :forms (:expanded-forms macro-artifact))
        all-functions (stage0-function-table module-base)
        selected-functions
        (into
         (sorted-map)
         (filter (fn [[function-name _]]
                   (str/starts-with? (name function-name)
                                     sh03-reader-function-prefix)))
         all-functions)
        module (assoc module-base :function-table selected-functions)
        emitter-binding
        (c-backend-stage2-plan-emitter-source-rule! source-path :jvm)
        emitter
        (p15-s23-stage2-compiler-artifact-augmented-emitter
         (:emitter emitter-binding))
        functions
        (into
         (sorted-map)
         (map
          (fn [[name definition]]
            [name
             (select-keys
              (p15-s23-stage2-seed-compile-function
               emitter module definition)
              sh03-reader-function-keys)]))
         selected-functions)
        audit (sh03-reader-plan-instruction-summary source-path functions)
        plan-base
        {:kind :gravity/stage2-compiler-artifact-plan
         :compiler-artifact-plan? true
         :entrypoint sh03-reader-entrypoint
         :source {:sha256 source-content-hash
                  :byte-count source-byte-count}
         :compiler
         {:owner :gravity-source
          :stage :p15-s23-stage2-expression-lowering
          :compiled-by :clojure-stage0-seed
          :executed-by :clojure-stage2-generic-rule-runner
          :emitter-source-content-hash
          p15-s23-stage2-compiler-artifact-expected-source-content-hash
          :emitter-semantic-hash
          p15-s23-stage2-compiler-artifact-expected-semantic-hash
          :emitter-source-rule-hash (:source-rule-hash emitter-binding)
          :generic-bridge-residual? true
          :self-hosted? false}
         :module (select-keys module
                              [:module :profile :target :effects
                               :capabilities :exports :safety])
         :functions functions
         :instruction-summary (:instruction-summary audit)
         :effect-summary {:declared (:effects module)
                          :inferred #{}
                          :capabilities (:capabilities module)}
         :sh03-reader
         {:slice :SH-03
          :source-language :gravity
          :entrypoint sh03-reader-entrypoint
          :verifier sh03-reader-verifier
          :target-source-reread? false
          :clojure-seed-boundary? true
          :self-hosted? false}}
        plan (assoc plan-base :plan-id (reader-canonical-hash plan-base))]
    {:plan plan
     :source-path source-path
     :source-byte-count source-byte-count
     :source-content-hash source-content-hash
     :builtin-functions (:builtin-functions audit)}))

(defn sh03-reader-plan-identities
  [plan]
  (let [functions (:functions plan)
        function-names (vec (sort-by str (keys functions)))
        function-shapes
        (into (sorted-map)
              (map (fn [[name function]]
                     [name (select-keys function [:arity :params])]))
              functions)
        audit
        (sh03-reader-plan-instruction-summary
         "<sh03-reader-plan>" functions)]
    {:plan-semantic-hash
     (reader-canonical-hash (dissoc plan :plan-id))
     :functions-semantic-hash (reader-canonical-hash functions)
     :function-count (count functions)
     :function-names-hash (reader-canonical-hash function-names)
     :function-shapes-hash (reader-canonical-hash function-shapes)
     :entrypoint-semantic-hash
     (reader-canonical-hash (get functions sh03-reader-entrypoint))
     :verifier-semantic-hash
     (reader-canonical-hash (get functions sh03-reader-verifier))
     :builtin-functions-hash
     (reader-canonical-hash
      (vec (sort-by str (:builtin-functions audit))))
     :instruction-summary (:instruction-summary audit)
     :observed-instruction-nodes (:observed-nodes audit)
     :observed-instruction-depth (:observed-depth audit)}))

(defn sh03-reader-plan-task
  [instruction locals target tail? depth]
  {:instruction instruction :locals locals :target target
   :tail? tail? :depth depth})

(defn sh03-reader-plan-sequence-tasks
  [instructions locals target tail? depth]
  (let [instructions (vec instructions)
        last-index (dec (count instructions))]
    (mapv (fn [index instruction]
            (sh03-reader-plan-task
             instruction locals target
             (and tail? (= index last-index)) (inc depth)))
          (range) instructions)))

(defn sh03-reader-plan-static-audit!
  [source-path plan]
  (let [functions (:functions plan)
        function-arities
        (into {} (map (fn [[name function]] [name (:arity function)]))
              functions)
        initial-tasks
        (reduce
         (fn [tasks [_ function]]
           (let [params (:params function)
                 target {:kind :function :arity (:arity function)}]
             (into tasks
                   (sh03-reader-plan-sequence-tasks
                    (:instructions function) (set params) target true 0))))
         [] functions)]
    (loop [pending initial-tasks
           observed 0
           summary {}
           builtins #{}
           maximum-depth 0]
      (when (> observed sh03-reader-plan-maximum-nodes)
        (sh03-reader-boundary-fail!
         source-path :bounded-static-sh03-reader-plan
         observed {:maximum-nodes sh03-reader-plan-maximum-nodes}))
      (if (empty? pending)
        {:instruction-summary summary
         :builtin-functions builtins
         :observed-nodes observed
         :observed-depth maximum-depth}
        (let [{:keys [instruction locals target tail? depth]} (peek pending)
              pending (pop pending)
              op (:op instruction)
              expected-keys (get sh03-reader-instruction-keysets op)]
          (when-not (and (map? instruction)
                         (contains? sh03-reader-allowed-opcodes op)
                         (= expected-keys (set (keys instruction)))
                         (<= depth sh03-reader-plan-maximum-depth))
            (sh03-reader-boundary-fail!
             source-path :exact-bounded-sh03-reader-instruction
             instruction {:opcode op :depth depth}))
          (let [tasks
                (case op
                  (:literal :quote) []

                  :local
                  (do
                    (when-not (contains? locals (:name instruction))
                      (sh03-reader-boundary-fail!
                       source-path :lexically-bound-sh03-reader-local
                       instruction {:local (:name instruction)}))
                    [])

                  (:vector-literal :set-literal)
                  (mapv #(sh03-reader-plan-task
                          % locals target false (inc depth))
                        (:items instruction))

                  :map-literal
                  (reduce
                   (fn [result entry]
                     (when-not (and (map? entry)
                                    (= #{:key :value} (set (keys entry))))
                       (sh03-reader-boundary-fail!
                        source-path :exact-sh03-reader-map-entry
                        entry {:opcode op}))
                     (conj result
                           (sh03-reader-plan-task
                            (:key entry) locals target false (inc depth))
                           (sh03-reader-plan-task
                            (:value entry) locals target false (inc depth))))
                   [] (:entries instruction))

                  :do
                  (sh03-reader-plan-sequence-tasks
                   (:body instruction) locals target tail? depth)

                  :if
                  [(sh03-reader-plan-task
                    (:test instruction) locals target false (inc depth))
                   (sh03-reader-plan-task
                    (:then instruction) locals target tail? (inc depth))
                   (sh03-reader-plan-task
                    (:else instruction) locals target tail? (inc depth))]

                  (:let :loop)
                  (let [bindings (:bindings instruction)
                        body (:body instruction)]
                    (when-not (and (vector? bindings)
                                   (vector? body)
                                   (seq body)
                                   (every? #(and (map? %)
                                                 (= #{:name :expr}
                                                    (set (keys %)))
                                                 (symbol? (:name %)))
                                           bindings)
                                   (= (count bindings)
                                      (count (distinct (map :name bindings))))
                                   (if (= :loop op)
                                     (= (:binding-count instruction)
                                        (count bindings))
                                     true))
                      (sh03-reader-boundary-fail!
                       source-path :exact-sh03-reader-local-bindings
                       instruction {:opcode op}))
                    (let [[binding-tasks body-locals]
                          (reduce
                           (fn [[result scope] binding]
                             [(conj result
                                    (sh03-reader-plan-task
                                     (:expr binding) scope target false
                                     (inc depth)))
                              (conj scope (:name binding))])
                           [[] locals] bindings)
                          body-target
                          (if (= :loop op)
                            {:kind :loop :arity (count bindings)}
                            target)
                          body-tail? (if (= :loop op) true tail?)]
                      (into binding-tasks
                            (sh03-reader-plan-sequence-tasks
                             body body-locals body-target body-tail? depth))))

                  :recur
                  (do
                    (when-not (and target tail?
                                   (= (:arity target)
                                      (count (:args instruction))))
                      (sh03-reader-boundary-fail!
                       source-path :valid-tail-sh03-reader-recur
                       instruction
                       {:target target :tail-position? tail?
                        :actual-arity (count (:args instruction))}))
                    (mapv #(sh03-reader-plan-task
                            % locals target false (inc depth))
                          (:args instruction)))

                  :builtin-call
                  (do
                    (when-not (contains? sh03-reader-allowed-builtins
                                         (:function instruction))
                      (sh03-reader-boundary-fail!
                       source-path :approved-pure-sh03-reader-builtin
                       instruction {:function (:function instruction)}))
                    (mapv #(sh03-reader-plan-task
                            % locals target false (inc depth))
                          (:args instruction)))

                  :function-call
                  (let [callee (:function instruction)
                        arity (get function-arities callee ::missing)]
                    (when-not (and (not= ::missing arity)
                                   (= arity (count (:args instruction))))
                      (sh03-reader-boundary-fail!
                       source-path :exact-sh03-reader-function-call
                       instruction
                       {:function callee :expected-arity
                        (when-not (= ::missing arity) arity)
                        :actual-arity (count (:args instruction))}))
                    (mapv #(sh03-reader-plan-task
                            % locals target false (inc depth))
                          (:args instruction))))]
            (recur (into pending (reverse tasks))
                   (inc observed)
                   (update summary op (fnil inc 0))
                   (cond-> builtins (= :builtin-call op)
                     (conj (:function instruction)))
                   (max maximum-depth depth))))))))

(defn sh03-reader-plan-validate!
  [source-path plan]
  (let [carrier
        (p15-s23-trusted-carrier-validation
         plan :default-only sh03-reader-plan-maximum-nodes
         sh03-reader-plan-maximum-depth sh03-reader-plan-maximum-width)]
    (when-not (= :passed (:status carrier))
      (sh03-reader-boundary-fail!
       source-path :trusted-bounded-sh03-reader-plan
       plan (select-keys carrier [:reason :observed-nodes :observed-depth
                                  :maximum-nodes :maximum-depth
                                  :maximum-width])))
    (let [functions (:functions plan)]
      (when-not
       (and (map? plan)
            (= sh03-reader-plan-keys (set (keys plan)))
            (= :gravity/stage2-compiler-artifact-plan (:kind plan))
            (true? (:compiler-artifact-plan? plan))
            (= sh03-reader-entrypoint (:entrypoint plan))
            (= 'gravity.bootstrap.reader (get-in plan [:module :module]))
            (= :meta (get-in plan [:module :profile]))
            (= :jvm (get-in plan [:module :target]))
            (= #{} (get-in plan [:module :effects]))
            (= #{} (get-in plan [:module :capabilities]))
            (= :safe (get-in plan [:module :safety]))
            (= :gravity-source (get-in plan [:compiler :owner]))
            (= :p15-s23-stage2-expression-lowering
               (get-in plan [:compiler :stage]))
            (= :clojure-stage0-seed
               (get-in plan [:compiler :compiled-by]))
            (= :clojure-stage2-generic-rule-runner
               (get-in plan [:compiler :executed-by]))
            (true? (get-in plan [:compiler :generic-bridge-residual?]))
            (false? (get-in plan [:compiler :self-hosted?]))
            (map? functions)
            (= sh03-reader-expected-function-count (count functions))
            (contains? functions sh03-reader-entrypoint)
            (contains? functions sh03-reader-verifier)
            (every?
             (fn [[function-name function]]
               (and (str/starts-with? (name function-name)
                                      sh03-reader-function-prefix)
                    (= sh03-reader-function-keys
                       (set (keys function)))
                    (= function-name (:name function))
                    (vector? (:params function))
                    (= (:arity function) (count (:params function)))
                    (= (count (:params function))
                       (count (distinct (:params function))))
                    (every? symbol? (:params function))
                    (pos-int? (:body-form-count function))
                    (vector? (:instructions function))
                    (seq (:instructions function))
                    (= sh03-reader-binding-keys
                       (set (keys (:binding function))))
                    (= function-name (get-in function [:binding :name]))
                    (= :function (get-in function [:binding :kind]))
                    (= 'gravity.bootstrap.reader
                       (get-in function [:binding :namespace]))
                    (= :meta (get-in function [:binding :profile]))
                    (= :jvm (get-in function [:binding :target]))
                    (= #{} (get-in function [:binding :effects]))
                    (= #{} (get-in function [:binding :capabilities]))))
             functions))
        (sh03-reader-boundary-fail!
         source-path :exact-sh03-reader-plan-envelope
         plan {:observed-keys (when (map? plan) (set (keys plan)))}))
      (let [static-audit (sh03-reader-plan-static-audit! source-path plan)
            identities (sh03-reader-plan-identities plan)
            expected-plan-id
            (reader-canonical-hash (dissoc plan :plan-id))]
        (when-not
         (and (= expected-plan-id (:plan-id plan))
              (= sh03-reader-expected-plan-semantic-hash
                 (:plan-semantic-hash identities))
              (= sh03-reader-expected-functions-semantic-hash
                 (:functions-semantic-hash identities))
              (= sh03-reader-expected-function-count
                 (:function-count identities))
              (= sh03-reader-expected-function-names-hash
                 (:function-names-hash identities))
              (= sh03-reader-expected-function-shapes-hash
                 (:function-shapes-hash identities))
              (= sh03-reader-expected-entrypoint-semantic-hash
                 (:entrypoint-semantic-hash identities))
              (= sh03-reader-expected-verifier-semantic-hash
                 (:verifier-semantic-hash identities))
              (= sh03-reader-expected-builtin-functions-hash
                 (:builtin-functions-hash identities))
              (= (:instruction-summary plan)
                 (:instruction-summary static-audit)
                 (:instruction-summary identities))
              (= (:builtin-functions static-audit)
                 (:builtin-functions
                  (sh03-reader-plan-instruction-summary
                   source-path functions))))
          (sh03-reader-boundary-fail!
           source-path :pinned-recomputable-sh03-reader-plan-identities
           identities {:observed-plan-id (:plan-id plan)}))
        identities))))

(defn sh03-reader-build-pinned-binding!
  [request-source]
  (let [source (sh03-reader-read-pinned-source-bytes! request-source)
        built (sh03-reader-build-plan! request-source source)
        identities
        (sh03-reader-plan-validate! (:source-path source) (:plan built))]
    (merge
     (dissoc built :builtin-functions)
     identities
     {:artifact :gravity/sh03-pinned-reader-plan-binding
      :status :complete
      :semantic-authority :gravity-source
      :compiled-by :clojure-stage0-seed
      :executed-by :clojure-stage2-generic-rule-runner
      :generic-bridge-residual? true
      :self-hosted? false})))

(def ^:private sh03-reader-cached-binding
  (delay (sh03-reader-build-pinned-binding! "<sh03-reader-bootstrap>")))

(defn sh03-reader-current-binding!
  [request-source]
  (let [current-source
        (sh03-reader-read-pinned-source-bytes! request-source)
        binding @sh03-reader-cached-binding
        identities
        (sh03-reader-plan-validate! request-source (:plan binding))]
    (when-not
     (and (= (:source-byte-count current-source)
             (:source-byte-count binding))
          (= (:source-content-hash current-source)
             (:source-content-hash binding))
          (= (select-keys identities
                          [:plan-semantic-hash
                           :functions-semantic-hash
                           :function-count
                           :function-names-hash
                           :function-shapes-hash
                           :entrypoint-semantic-hash
                           :verifier-semantic-hash
                           :builtin-functions-hash])
             (select-keys binding
                          [:plan-semantic-hash
                           :functions-semantic-hash
                           :function-count
                           :function-names-hash
                           :function-shapes-hash
                           :entrypoint-semantic-hash
                           :verifier-semantic-hash
                           :builtin-functions-hash])))
      (sh03-reader-boundary-fail!
       request-source :fresh-sh03-reader-source-and-plan-binding
       binding {:current-source-content-hash
                (:source-content-hash current-source)}))
    binding))

(def sh03-reader-result-keys
  #{:artifact :schema-version :status :source-unit :actual-path-provenance
    :token-stream :form-tree :top-level-form-ids :top-level-parsed-records
    :parsed-semantic-values :semantic-value-table :literal-decoding-records
    :semantic-error-deferment-record
    :reader-extension-invocation-records :reader-source-map
    :incremental-reader-hashes :semantic-reader-template :digest-requests
    :diagnostics :bounds :execution-boundary})

(def sh03-reader-verification-report-keys
  #{:artifact :schema-version :status :verified? :reader-result-status
    :semantic-reader-template :digest-requests :diagnostics :bounds
    :execution-boundary})

(def sh03-reader-digest-request-keys
  #{:algorithm :depends-on :encoding :key :ordinal :preimage})

(def sh03-reader-source-digest-request-keys
  (conj sh03-reader-digest-request-keys :observed-id))

(def sh03-reader-accepted-digest-request-names
  [:source-content :source-unit :token-stream :form-tree
   :extension-invocation-set :reader-result])

(def sh03-reader-rejected-digest-request-names
  [:source-content :source-unit])

(def sh03-reader-source-slice-keys
  #{:artifact :schema-version :encoding :source-content-id
    :byte-start :byte-end :scalar-start :scalar-end})

(def sh03-reader-semantic-value-entry-keys
  #{:artifact :schema-version :value-id :form-id :token-id :kind
    :descriptor :semantic-key})

(def sh03-reader-semantic-value-reference-keys
  #{:artifact :schema-version :value-id :field})

(def sh03-reader-form-value-reference-keys
  #{:artifact :schema-version :form-id})

(defn sh03-reader-byte-vector
  [bytes]
  (mapv #(bit-and (int %) 0xff) bytes))

(defn sh03-reader-byte-array
  [values]
  (byte-array (map #(unchecked-byte (int %)) values)))

(defn sh03-reader-tag-codepoints
  [tag]
  (let [value (name tag)]
    (vec (.toArray (.codePoints value)))))

(defn sh03-reader-input-source-unit
  [source-path source-bytes project-context]
  (let [context (reader-explicit-project-context project-context)
        extension (gravity-source-extension source-path)
        identity-fields
        {:project-root-id (:project-root-id context)
         :logical-source-id (:project-relative-path context)
         :actual-path source-path}]
    (doseq [[field value] identity-fields]
      (let [utf8-byte-count
            (when (string? value)
              (alength (.getBytes ^String value
                                 java.nio.charset.StandardCharsets/UTF_8)))]
        (when-not (and (string? value)
                       (<= (.length ^String value)
                           sh03-reader-input-maximum-identity-code-units)
                       (<= utf8-byte-count
                           sh03-reader-input-maximum-identity-utf8-bytes))
          (sh03-reader-boundary-fail!
           "<sh03-source-identity>" :bounded-sh03-reader-source-identity
           {:field field}
           {:maximum-code-units
            sh03-reader-input-maximum-identity-code-units
            :maximum-utf8-bytes
            sh03-reader-input-maximum-identity-utf8-bytes
            :observed-code-units
            (when (string? value) (.length ^String value))
            :observed-utf8-bytes utf8-byte-count}))))
    {:artifact :gravity/sh03-source-unit
     :schema-version 1
     :project-root-id (:project-root-id context)
     :logical-source-id (:project-relative-path context)
     :source-content-hash
     (str "sha256:" (sha256-bytes-hex source-bytes))
     :source-byte-count (alength source-bytes)
     :encoding :utf-8
     :actual-path-provenance
     {:path source-path
      :extension extension
      :source-kind (case extension ".gravity" :gravity ".qst" :qst nil)}}))

(defn sh03-reader-input-policy
  [reader-options]
  (reader-validate-options! reader-options)
  {:artifact :gravity/sh03-reader-policy
   :schema-version 1
   :retain-trivia (true? (:retain-comments reader-options))
   :enabled-reader-tags
   (mapv sh03-reader-tag-codepoints (:registered-tags standard-reader-policy))})

(defn sh03-reader-require-result-carrier!
  [source-path carrier value]
  (let [validation
        (p15-s23-trusted-carrier-validation
         value :default-only sh03-reader-result-maximum-nodes
         sh03-reader-result-maximum-depth sh03-reader-result-maximum-width)]
    (when-not (= :passed (:status validation))
      (sh03-reader-boundary-fail!
       source-path :trusted-bounded-sh03-reader-result
       {} (merge {:carrier carrier}
                 (select-keys validation
                              [:reason :observed-nodes :observed-depth
                               :maximum-nodes :maximum-depth
                               :maximum-width]))))
    validation))

(defn sh03-reader-result-preflight!
  [source-path source-unit reader-policy result]
  (sh03-reader-require-result-carrier!
   source-path :gravity-reader-result result)
  (let [bounds (:bounds result)
        carrier-responsibility
        (get-in result
                [:execution-boundary :clojure-boundary-responsibility])
        input-responsibility
        (get-in result [:execution-boundary :gravity-input-responsibility])
        accepted? (= :accepted (:status result))]
    (when-not
     (and (map? result)
          (= sh03-reader-result-keys (set (keys result)))
          (= :gravity/sh03-reader-result (:artifact result))
          (= 1 (:schema-version result))
          (contains? #{:accepted :rejected} (:status result))
          (= (:actual-path-provenance source-unit)
             (:actual-path-provenance result))
          (= reader-policy
             (get-in result [:source-unit :reader-options]))
          (= (:source-content-hash source-unit)
             (get-in result [:source-unit :bytes-hash]))
          (= (:source-byte-count source-unit)
             (get-in result [:source-unit :source-byte-count]))
          (vector? (:token-stream result))
          (vector? (:form-tree result))
          (vector? (:top-level-form-ids result))
          (vector? (:top-level-parsed-records result))
          (vector? (:parsed-semantic-values result))
          (vector? (:semantic-value-table result))
          (vector? (:literal-decoding-records result))
          (vector? (:reader-extension-invocation-records result))
          (vector? (:digest-requests result))
          (vector? (:diagnostics result))
          (map? bounds)
          (= sh03-reader-result-maximum-nodes
             (:maximum-result-carrier-nodes bounds))
          (= sh03-reader-result-maximum-depth
             (:maximum-result-carrier-depth bounds))
          (= sh03-reader-result-maximum-width
             (:maximum-result-carrier-width bounds))
          (= sh03-reader-canonical-maximum-scalar-bytes
             (:maximum-canonical-scalar-bytes bounds))
          (= sh03-reader-canonical-maximum-total-scalar-bytes
             (:maximum-canonical-total-scalar-bytes bounds))
          (= sh03-reader-input-maximum-identity-utf8-bytes
             (:maximum-source-identity-utf8-bytes bounds))
          (map? carrier-responsibility)
          (= sh03-reader-result-maximum-nodes
             (:maximum-nodes carrier-responsibility))
          (= sh03-reader-result-maximum-depth
             (:maximum-depth carrier-responsibility))
          (= sh03-reader-result-maximum-width
             (:maximum-width carrier-responsibility))
          (= sh03-reader-canonical-maximum-scalar-bytes
             (:maximum-canonical-scalar-bytes carrier-responsibility))
          (= sh03-reader-canonical-maximum-total-scalar-bytes
             (:maximum-canonical-total-scalar-bytes
              carrier-responsibility))
          (map? input-responsibility)
          (= sh03-reader-input-maximum-identity-utf8-bytes
             (:maximum-source-identity-utf8-bytes
              input-responsibility))
          (= sh03-reader-input-maximum-identity-code-units
             (:maximum-logical-source-id-code-units
              input-responsibility))
          (= sh03-reader-input-maximum-identity-code-units
             (:maximum-actual-path-code-units input-responsibility))
          (= (:maximum-source-bytes bounds)
             (:maximum-source-bytes input-responsibility))
          (= :bounded-summary
             (:invalid-input-carrier-policy input-responsibility))
          (integer? (:maximum-tokens bounds))
          (integer? (:maximum-forms bounds))
          (pos-int? (:maximum-semantic-work-units bounds))
          (pos-int? (:maximum-numeric-semantic-scalars bounds))
          (pos-int? (:maximum-numeric-semantic-work-units bounds))
          (map? (:result-carrier-node-budget bounds))
          (<= (get-in bounds
                      [:result-carrier-node-budget :derived-maximum-nodes])
              (:maximum-result-carrier-nodes bounds))
          (<= (count (:token-stream result)) (:maximum-tokens bounds))
          (<= (count (:form-tree result)) (:maximum-forms bounds))
          (<= (count (:digest-requests result)) 6)
          (if accepted?
            (and (empty? (:diagnostics result))
                 (= 6 (count (:digest-requests result)))
                 (= (count (:enabled-reader-tags reader-policy))
                    (count (:reader-extension-invocation-records result)))
                 (= (count (:top-level-form-ids result))
                    (count (:top-level-parsed-records result))
                    (count (:parsed-semantic-values result))))
            (and (= 1 (count (:diagnostics result)))
                 (= 2 (count (:digest-requests result)))
                 (empty? (:token-stream result))
                 (empty? (:form-tree result))
                 (empty? (:top-level-form-ids result))
                 (empty? (:semantic-value-table result))
                 (empty? (:reader-extension-invocation-records result)))))
      (sh03-reader-boundary-fail!
       source-path :exact-sh03-reader-result-envelope
       result {:observed-keys (when (map? result) (set (keys result)))}))
    result))

(defn sh03-reader-verifier-preflight!
  [source-path raw-result report]
  (sh03-reader-require-result-carrier!
   source-path :gravity-reader-verification-report report)
  (when-not
   (and (map? report)
        (= sh03-reader-verification-report-keys (set (keys report)))
        (= :gravity/sh03-reader-verification-report (:artifact report))
        (= 1 (:schema-version report))
        (= :accepted (:status report))
        (true? (:verified? report))
        (= (:status raw-result) (:reader-result-status report))
        (= (:semantic-reader-template raw-result)
           (:semantic-reader-template report))
        (= (mapv #(select-keys
                   % [:key :ordinal :algorithm :encoding :depends-on])
                 (:digest-requests raw-result))
           (:digest-requests report))
        (= [] (:diagnostics report))
        (= (:bounds raw-result) (:bounds report))
        (= (:execution-boundary raw-result)
           (:execution-boundary report)))
    (sh03-reader-boundary-fail!
     source-path :fresh-gravity-sh03-reader-result-replay
     report {:reader-result-status (:status raw-result)}))
  report)

(defn sh03-reader-execute-plan!
  [source-path plan function arguments]
  (try
    (p15-s23-stage2-runtime-execute-function
     {:engine :gravity-sh03-pinned-reader-host-runner
      :compiler-artifact-plan? true}
     plan function arguments)
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch StackOverflowError error
      (sh03-reader-boundary-fail!
       source-path :bounded-sh03-reader-host-stack
       function {:contained-host-error (.getName (class error))}))
    (catch AssertionError error
      (sh03-reader-boundary-fail!
       source-path :contained-sh03-reader-assertion
       function {:contained-host-error (.getName (class error))}))
    (catch LinkageError error
      (sh03-reader-boundary-fail!
       source-path :contained-sh03-reader-linkage
       function {:contained-host-error (.getName (class error))}))
    (catch clojure.lang.ExceptionInfo error
      (sh03-reader-boundary-fail!
       source-path :contained-sh03-reader-runtime-diagnostic
       function {:contained-diagnostic (:id (ex-data error))
                 :cause-message (.getMessage error)}))
    (catch Exception error
      (sh03-reader-boundary-fail!
       source-path :contained-sh03-reader-host-failure
       function {:contained-host-error (.getName (class error))
                 :cause-message (.getMessage error)}))))

(def sh03-reader-canonical-maximum-nodes 167772160)
(def sh03-reader-canonical-maximum-depth 2048)
(def sh03-reader-canonical-maximum-width 1048576)
(def sh03-reader-canonical-maximum-scalar-bytes 1048576)
(def sh03-reader-canonical-maximum-total-scalar-bytes 67108864)

(defn sh03-reader-canonical-identity
  [source-path value]
  (binding [p15-s23-c6c10-max-carrier-nodes
            sh03-reader-canonical-maximum-nodes
            p15-s23-c6c10-max-carrier-depth
            sh03-reader-canonical-maximum-depth
            p15-s23-c6c10-max-container-width
            sh03-reader-canonical-maximum-width
            p15-s23-c6c10-max-scalar-bytes
            sh03-reader-canonical-maximum-scalar-bytes
            p15-s23-c6c10-max-total-scalar-bytes
            sh03-reader-canonical-maximum-total-scalar-bytes]
    (p15-s23-c6c10-canonical-identity source-path value)))

(defn sh03-reader-canonical-digest
  [source-path value]
  (binding [p15-s23-c6c10-max-carrier-nodes
            sh03-reader-canonical-maximum-nodes
            p15-s23-c6c10-max-carrier-depth
            sh03-reader-canonical-maximum-depth
            p15-s23-c6c10-max-container-width
            sh03-reader-canonical-maximum-width
            p15-s23-c6c10-max-scalar-bytes
            sh03-reader-canonical-maximum-scalar-bytes
            p15-s23-c6c10-max-total-scalar-bytes
            sh03-reader-canonical-maximum-total-scalar-bytes]
    (p15-s23-c6c10-canonical-digest source-path value)))

(defn sh03-reader-resolve-digest-requests!
  [source-path raw-result source-bytes]
  (let [requests (:digest-requests raw-result)
        request-count (count requests)
        expected-names
        (if (= :accepted (:status raw-result))
          sh03-reader-accepted-digest-request-names
          sh03-reader-rejected-digest-request-names)]
    (when-not (= expected-names (mapv :key requests))
      (sh03-reader-boundary-fail!
       source-path :exact-sh03-reader-digest-request-set
       (mapv :key requests) {:expected expected-names}))
    (loop [ordinal 0
           digests []
           resolved-identities []
           resolved-requests []]
      (if (= ordinal request-count)
        (let [resolve-complete
              (fn [value]
                (p15-s23-c6c10-resolve-digest-references!
                 source-path value request-count nil digests))
              resolved-result (resolve-complete raw-result)
              resolved-result
              (assoc resolved-result
                     :digest-requests resolved-requests
                     :incremental-reader-hashes
                     (assoc (:incremental-reader-hashes resolved-result)
                            :status (if (= :accepted (:status raw-result))
                                      :stable :rejected)))]
          {:result resolved-result
           :resolved-digests digests
           :resolved-requests resolved-requests
           :reader-result-id (last digests)})
        (let [request (get requests ordinal)
              expected-keys (if (zero? ordinal)
                              sh03-reader-source-digest-request-keys
                              sh03-reader-digest-request-keys)]
          (when-not
           (and (map? request)
                (= expected-keys (set (keys request)))
                (= ordinal (:ordinal request))
                (= (get expected-names ordinal) (:key request))
                (= :sha256 (:algorithm request))
                (vector? (:depends-on request)))
            (sh03-reader-boundary-fail!
             source-path :exact-sh03-reader-digest-request-schema
             (dissoc request :preimage) {:ordinal ordinal}))
          (let [references
                (p15-s23-c6c10-collect-digest-ref-ordinals!
                 source-path (:preimage request) request-count ordinal)
                dependencies (:depends-on request)]
            (when-not
             (and (= dependencies (vec (sort (distinct dependencies))))
                  (= (set dependencies) (set references))
                  (every? #(and (integer? %) (<= 0 %) (< % ordinal))
                          dependencies))
              (sh03-reader-boundary-fail!
               source-path :prior-only-sh03-reader-digest-dependencies
               request {:ordinal ordinal :references references}))
            (let [resolved-preimage
                  (p15-s23-c6c10-resolve-digest-references!
                   source-path (:preimage request) request-count ordinal digests)
                  raw-request? (zero? ordinal)
                  _
                  (when-not (= (if raw-request?
                                 :raw-byte-vector-v1
                                 :gravity-canonical-edn-v1)
                               (:encoding request))
                    (sh03-reader-boundary-fail!
                     source-path :declared-sh03-reader-digest-encoding
                     request {:ordinal ordinal}))
                  _
                  (when (and raw-request?
                             (not= (sh03-reader-byte-vector source-bytes)
                                   resolved-preimage))
                    (sh03-reader-boundary-fail!
                     source-path :source-bound-sh03-reader-digest-request
                     request {:ordinal ordinal}))
                  resolved-identity
                  (if raw-request?
                    [:raw-byte-vector-v1 resolved-preimage]
                    (sh03-reader-canonical-identity
                     source-path resolved-preimage))
                  digest
                  (if raw-request?
                    (str "sha256:"
                         (sha256-bytes-hex
                          (sh03-reader-byte-array resolved-preimage)))
                    (sh03-reader-canonical-digest
                     source-path resolved-preimage))]
              (when (or (some #{resolved-identity} resolved-identities)
                        (some #{digest} digests)
                        (and raw-request? (not= digest (:observed-id request))))
                (sh03-reader-boundary-fail!
                 source-path :unique-bound-sh03-reader-digest
                 request {:ordinal ordinal :digest digest}))
              (recur
               (inc ordinal)
               (conj digests digest)
               (conj resolved-identities resolved-identity)
               (conj resolved-requests
                     (assoc request
                            :preimage resolved-preimage
                            :digest digest))))))))))

(defn sh03-reader-resolve-diagnostic-id
  [source-path diagnostic]
  (let [request (:diagnostic-id-request diagnostic)]
    (when-not (map? request)
      (sh03-reader-boundary-fail!
       source-path :sh03-reader-diagnostic-id-request
       diagnostic {}))
    (-> diagnostic
        (dissoc :diagnostic-id-request)
        (assoc :diagnostic-id
               (sh03-reader-canonical-digest source-path request)))))

(defn sh03-reader-resolved-result!
  [source-path source-bytes project-context reader-options]
  (when-not (qst-or-gravity-source? source-path)
    (try
      (source-path-policy-fail! source-path source-bytes)
      (catch clojure.lang.ExceptionInfo ex
        (c2-reader-remap-exception! source-path ex))))
  (when (> (alength source-bytes) 1048576)
    (sh03-reader-boundary-fail!
     source-path :bounded-sh03-reader-source-bytes
     (alength source-bytes) {:maximum-source-bytes 1048576}))
  (let [binding (sh03-reader-current-binding! source-path)
        plan (:plan binding)
        source-unit
        (sh03-reader-input-source-unit
         source-path source-bytes project-context)
        reader-policy (sh03-reader-input-policy reader-options)
        source-byte-vector (sh03-reader-byte-vector source-bytes)
        arguments [source-unit source-byte-vector reader-policy]
        raw-result
        (sh03-reader-execute-plan!
         source-path plan sh03-reader-entrypoint arguments)
        _ (sh03-reader-result-preflight!
           source-path source-unit reader-policy raw-result)
        verifier-result
        (sh03-reader-execute-plan!
         source-path plan sh03-reader-verifier
         [source-unit source-byte-vector reader-policy raw-result])
        _ (sh03-reader-verifier-preflight!
           source-path raw-result verifier-result)
        resolved
        (sh03-reader-resolve-digest-requests!
         source-path raw-result source-bytes)
        result
        (update (:result resolved) :diagnostics
                #(mapv (partial sh03-reader-resolve-diagnostic-id source-path)
                       %))]
    (assoc resolved
           :result result
           :raw-result raw-result
           :verification-report verifier-result
           :plan-binding (dissoc binding :plan))))

(defn sh03-reader-decode-raw-bytes!
  [source-path raw bytes]
  (try
    (str
     (.decode
      (doto (.newDecoder java.nio.charset.StandardCharsets/UTF_8)
        (.onMalformedInput java.nio.charset.CodingErrorAction/REPORT)
        (.onUnmappableCharacter java.nio.charset.CodingErrorAction/REPORT))
      (java.nio.ByteBuffer/wrap bytes)))
    (catch java.nio.charset.CharacterCodingException error
      (sh03-reader-boundary-fail!
       source-path :valid-sh03-reader-raw-utf8 raw
       {:cause-message (.getMessage error)}))))

(defn sh03-reader-source-scalar-boundaries!
  [source-path source-text source-bytes]
  (loop [utf16-index 0
         byte-index 0
         scalar-index 0
         boundaries {0 0}]
    (if (= utf16-index (.length source-text))
      (do
        (when-not (= byte-index (alength source-bytes))
          (sh03-reader-boundary-fail!
           source-path :complete-sh03-reader-source-scalar-index
           {:observed-byte-count byte-index}
           {:expected-byte-count (alength source-bytes)}))
        boundaries)
      (let [codepoint (.codePointAt source-text utf16-index)
            utf16-width (Character/charCount codepoint)
            utf8-width (cond
                         (<= codepoint 0x7f) 1
                         (<= codepoint 0x7ff) 2
                         (<= codepoint 0xffff) 3
                         :else 4)
            next-byte (+ byte-index utf8-width)]
        (recur (+ utf16-index utf16-width)
               next-byte
               (inc scalar-index)
               (assoc boundaries next-byte (inc scalar-index)))))))

(defn sh03-reader-source-slice-text!
  [source-path source-bytes source-content-id scalar-boundaries raw]
  (let [byte-count (alength source-bytes)
        start (:byte-start raw)
        end (:byte-end raw)
        scalar-start (:scalar-start raw)
        scalar-end (:scalar-end raw)]
    (when-not
     (and (map? raw)
          (= sh03-reader-source-slice-keys (set (keys raw)))
          (= :gravity/source-slice (:artifact raw))
          (= 1 (:schema-version raw))
          (= :utf-8 (:encoding raw))
          (= source-content-id (:source-content-id raw))
          (integer? start) (integer? end)
          (<= 0 start end byte-count)
          (integer? scalar-start) (integer? scalar-end)
          (<= 0 scalar-start scalar-end)
          (= scalar-start (get scalar-boundaries start ::missing))
          (= scalar-end (get scalar-boundaries end ::missing)))
      (sh03-reader-boundary-fail!
       source-path :source-bound-sh03-reader-slice raw
       {:source-byte-count byte-count
        :expected-source-content-id source-content-id}))
    (let [bytes (java.util.Arrays/copyOfRange source-bytes start end)
          text (sh03-reader-decode-raw-bytes! source-path raw bytes)
          observed-scalars (.codePointCount text 0 (.length text))]
      (when-not (= observed-scalars (- scalar-end scalar-start))
        (sh03-reader-boundary-fail!
         source-path :unicode-scalar-bound-sh03-reader-slice raw
         {:observed-scalar-count observed-scalars}))
      text)))

(defn sh03-reader-raw-text!
  ([source-path raw]
   (when-not (and (map? raw)
                  (= :utf-8 (:encoding raw))
                  (vector? (:bytes raw))
                  (every? #(and (integer? %) (<= 0 % 255)) (:bytes raw)))
     (sh03-reader-boundary-fail!
      source-path :sh03-reader-inline-raw-utf8 raw {}))
   (sh03-reader-decode-raw-bytes!
    source-path raw (sh03-reader-byte-array (:bytes raw))))
  ([source-path source-bytes source-content-id raw]
   (if (= :gravity/source-slice (:artifact raw))
     (sh03-reader-source-slice-text!
      source-path source-bytes source-content-id
      (sh03-reader-source-scalar-boundaries!
       source-path
       (sh03-reader-decode-raw-bytes! source-path raw source-bytes)
       source-bytes)
      raw)
     (sh03-reader-raw-text! source-path raw))))

(defn sh03-reader-accepted-raw-text!
  [source-path source-bytes source-content-id scalar-boundaries raw span]
  (when-not
   (and (= :gravity/source-slice (:artifact raw))
        (= (:byte-start raw) (:byte-start span))
        (= (:byte-end raw) (:byte-end span)))
    (sh03-reader-boundary-fail!
     source-path :span-bound-sh03-reader-source-slice raw
     {:owner-span span}))
  (sh03-reader-source-slice-text!
   source-path source-bytes source-content-id scalar-boundaries raw))

(defn sh03-reader-codepoints-text!
  [source-path codepoints]
  (when-not (and (vector? codepoints)
                 (every? #(and (integer? %)
                               (<= 0 % 0x10ffff)
                               (not (<= 0xd800 % 0xdfff)))
                         codepoints))
    (sh03-reader-boundary-fail!
     source-path :valid-sh03-reader-unicode-scalars codepoints {}))
  (let [builder (StringBuilder.)]
    (doseq [codepoint codepoints]
      (.appendCodePoint builder codepoint))
    (.toString builder)))

(defn sh03-reader-semantic-value-index!
  [source-path entries]
  (when-not (vector? entries)
    (sh03-reader-boundary-fail!
     source-path :sh03-reader-semantic-value-table entries {}))
  (let [valid-entry?
        (fn [entry]
          (and (map? entry)
               (= sh03-reader-semantic-value-entry-keys
                  (set (keys entry)))
               (= :gravity/semantic-value (:artifact entry))
               (= 1 (:schema-version entry))
               (string? (:value-id entry))
               (string? (:form-id entry))
               (string? (:token-id entry))
               (keyword? (:kind entry))))
        value-ids (mapv :value-id entries)
        form-ids (mapv :form-id entries)
        token-ids (mapv :token-id entries)]
    (when-not
     (and (every? valid-entry? entries)
          (= (count value-ids) (count (distinct value-ids)))
          (= (count form-ids) (count (distinct form-ids)))
          (= (count token-ids) (count (distinct token-ids))))
      (sh03-reader-boundary-fail!
       source-path :exact-unique-sh03-reader-semantic-values entries {}))
    {:by-value-id (into {} (map (juxt :value-id identity) entries))
     :by-form-id (into {} (map (juxt :form-id identity) entries))
     :by-token-id (into {} (map (juxt :token-id identity) entries))}))

(defn sh03-reader-semantic-reference-value!
  [source-path semantic-index reference expected-field]
  (when-not
   (and (map? reference)
        (= sh03-reader-semantic-value-reference-keys
           (set (keys reference)))
        (= :gravity/semantic-value-reference (:artifact reference))
        (= 1 (:schema-version reference))
        (= expected-field (:field reference)))
    (sh03-reader-boundary-fail!
     source-path :exact-sh03-reader-semantic-value-reference reference
     {:expected-field expected-field}))
  (let [entry (get-in semantic-index [:by-value-id (:value-id reference)])]
    (when-not entry
      (sh03-reader-boundary-fail!
       source-path :resolving-sh03-reader-semantic-value-reference reference {}))
    (get entry expected-field)))

(defn sh03-reader-form-value-reference!
  [source-path reference expected-form-id]
  (when-not
   (and (map? reference)
        (= sh03-reader-form-value-reference-keys (set (keys reference)))
        (= :gravity/form-value-reference (:artifact reference))
        (= 1 (:schema-version reference))
        (= expected-form-id (:form-id reference)))
    (sh03-reader-boundary-fail!
     source-path :exact-sh03-reader-form-value-reference reference
     {:expected-form-id expected-form-id}))
  reference)

(def sh03-reader-atomic-kinds
  #{:nil :boolean :integer :ratio :decimal :string :character :symbol :keyword})

(defn sh03-reader-semantic-value-closure!
  [source-path source-bytes source-content-id scalar-boundaries
   tokens forms semantic-index]
  (let [tokens-by-id (into {} (map (juxt :token-id identity) tokens))
        forms-by-id (into {} (map (juxt :form-id identity) forms))
        atomic-forms (filterv #(contains? sh03-reader-atomic-kinds (:kind %))
                              forms)
        entries (vals (:by-value-id semantic-index))]
    (when-not (= (count atomic-forms) (count entries))
      (sh03-reader-boundary-fail!
       source-path :complete-sh03-reader-semantic-value-closure entries
       {:expected-atomic-form-count (count atomic-forms)}))
    (doseq [entry entries]
      (let [form (forms-by-id (:form-id entry))
            token (tokens-by-id (:token-id entry))
            _ (sh03-reader-semantic-reference-value!
               source-path semantic-index (:value form) :descriptor)
            _ (sh03-reader-semantic-reference-value!
               source-path semantic-index (:semantic-key form) :semantic-key)
            _ (sh03-reader-semantic-reference-value!
               source-path semantic-index (:descriptor token) :descriptor)]
        (when (and (map? (:descriptor entry))
                   (contains? (:descriptor entry) :raw))
          (sh03-reader-accepted-raw-text!
           source-path source-bytes source-content-id scalar-boundaries
           (get-in entry [:descriptor :raw]) (:span form)))
        (when-not
         (and form token
              (= (:kind entry) (:kind form) (:kind token))
              (= (:token-id entry) (:open-token form))
              (= (:value-id entry) (get-in form [:value :value-id]))
              (= :descriptor (get-in form [:value :field]))
              (= (:value-id entry) (get-in form [:semantic-key :value-id]))
              (= :semantic-key (get-in form [:semantic-key :field]))
              (= (:value-id entry) (get-in token [:descriptor :value-id]))
              (= :descriptor (get-in token [:descriptor :field])))
          (sh03-reader-boundary-fail!
           source-path :owned-sh03-reader-semantic-value-reference
           entry {:form form :token token}))))
    :complete))

(defn sh03-reader-path-span
  [source-path source-id span]
  (when-not (map? span)
    (sh03-reader-boundary-fail!
     source-path :sh03-reader-span span {}))
  (assoc span :source source-path :file source-id))

(defn sh03-reader-host-bigint!
  [source-path value]
  (cond
    (integer? value)
    value

    (and (map? value)
         (= :gravity/arbitrary-precision-integer (:artifact value))
         (contains? #{:negative :positive} (:sign value))
         (contains? #{2 10 16} (:radix value))
         (vector? (:digit-codepoints value)))
    (let [digits (sh03-reader-codepoints-text!
                  source-path (:digit-codepoints value))
          magnitude (java.math.BigInteger. digits (int (:radix value)))
          signed (if (= :negative (:sign value))
                   (.negate magnitude)
                   magnitude)]
      (clojure.lang.BigInt/fromBigInteger signed))

    :else
    (sh03-reader-boundary-fail!
     source-path :sh03-reader-integer-descriptor value {})))

(defn sh03-reader-host-decimal-value!
  [source-path raw descriptor]
  (try
    (bigdec raw)
    (catch NumberFormatException _
      {:artifact :gravity/decimal-literal
       :kind :decimal
       :raw raw
       :integer-spelling
       (sh03-reader-codepoints-text!
        source-path (:integer-spelling descriptor))
       :fraction-spelling
       (sh03-reader-codepoints-text!
        source-path (:fraction-spelling descriptor))
       :exponent-spelling
       (sh03-reader-codepoints-text!
        source-path (:exponent-spelling descriptor))
       :semantic-key (:semantic-key descriptor)
       :semantic-validation :deferred
       :reason :host-independent-decimal-range})))

(defn sh03-reader-normalization-deferred?
  [descriptor]
  (and (= :deferred (:semantic-validation descriptor))
       (= :reader-semantic-work-boundary
          (:normalization-reason descriptor))))

(defn sh03-reader-host-deferred-numeric-value
  [kind raw descriptor]
  {:artifact :gravity/deferred-numeric-literal
   :kind kind
   :raw raw
   :descriptor (assoc descriptor :raw raw)
   :semantic-validation :deferred
   :reason :reader-semantic-work-boundary
   :normalization-reason :reader-semantic-work-boundary
   :numeric-semantic-work (:numeric-semantic-work descriptor)})

(defn sh03-reader-host-character-value!
  [source-path descriptor]
  (let [codepoint (:codepoint descriptor)]
    (when-not (and (integer? codepoint)
                   (<= 0 codepoint 0x10ffff)
                   (not (<= 0xd800 codepoint 0xdfff)))
      (sh03-reader-boundary-fail!
       source-path :sh03-reader-character-value descriptor {}))
    (if (<= codepoint 0xffff)
      (char codepoint)
      {:artifact :gravity/unicode-scalar-character
       :schema-version 1
       :codepoint codepoint
       :text (String. (Character/toChars (int codepoint)))})))

(defn sh03-reader-host-atomic-value!
  [source-path source-bytes source-content-id scalar-boundaries form descriptor]
  (let [kind (:kind form)
        raw (sh03-reader-accepted-raw-text!
             source-path source-bytes source-content-id scalar-boundaries
             (:raw form) (:span form))]
    (if (and (contains? #{:integer :ratio :decimal} kind)
             (sh03-reader-normalization-deferred? descriptor))
      (sh03-reader-host-deferred-numeric-value kind raw descriptor)
      (case kind
      :nil nil
      :boolean (:value descriptor)
      :integer (sh03-reader-host-bigint! source-path (:value descriptor))
      :ratio
      (let [numerator (sh03-reader-host-bigint!
                       source-path (:numerator descriptor))
            denominator (sh03-reader-host-bigint!
                         source-path (:denominator descriptor))]
        (if (zero? denominator)
          {:artifact :gravity/deferred-ratio-literal
           :kind :ratio
           :raw raw
           :numerator-spelling
           (sh03-reader-codepoints-text!
            source-path (:numerator-spelling descriptor))
           :denominator-spelling
           (sh03-reader-codepoints-text!
            source-path (:denominator-spelling descriptor))
           :numerator numerator
           :denominator denominator
           :semantic-validation :deferred
           :reason :zero-denominator}
          (/ numerator denominator)))
      :decimal (sh03-reader-host-decimal-value!
                source-path raw descriptor)
      :string (sh03-reader-codepoints-text!
               source-path (:decoded-codepoints descriptor))
      :character (sh03-reader-host-character-value! source-path descriptor)
      :symbol (symbol (sh03-reader-codepoints-text!
                       source-path (:name-codepoints descriptor)))
      :keyword (keyword (sh03-reader-codepoints-text!
                         source-path (:name-codepoints descriptor)))
      (sh03-reader-boundary-fail!
       source-path :sh03-reader-atomic-kind form {:kind kind})))))

(defn sh03-reader-metadata-map!
  [source-path metadata-value metadata-form]
  (cond
    (map? metadata-value) metadata-value
    (keyword? metadata-value) {metadata-value true}
    (or (symbol? metadata-value) (string? metadata-value))
    {:tag metadata-value}
    :else
    (sh03-reader-boundary-fail!
     source-path :sh03-reader-metadata-value metadata-form
     {:metadata-value metadata-value})))

(defn sh03-reader-host-values!
  [source-path source-bytes source-content-id scalar-boundaries
   form-tree semantic-index]
  (let [forms-by-id (into {} (map (juxt :form-id identity) form-tree))]
    (loop [remaining (reverse form-tree)
           values {}]
      (if (empty? remaining)
        values
        (let [form (first remaining)
              kind (:kind form)
              child-values (mapv values (:children form))
              _ (when (some nil? (map #(get forms-by-id %) (:children form)))
                  (sh03-reader-boundary-fail!
                   source-path :sh03-reader-form-child-link form {}))
              value
              (case kind
                (:nil :boolean :integer :ratio :decimal :string
                 :character :symbol :keyword)
                (let [reference (:value form)
                      descriptor
                      (sh03-reader-semantic-reference-value!
                       source-path semantic-index reference :descriptor)
                      entry (get-in semantic-index
                                    [:by-value-id (:value-id reference)])]
                  (when-not
                   (and (= (:form-id form) (:form-id entry))
                        (= (:open-token form) (:token-id entry))
                        (= kind (:kind entry)))
                    (sh03-reader-boundary-fail!
                     source-path :form-bound-sh03-reader-semantic-value
                     entry {:form-id (:form-id form)}))
                  (sh03-reader-host-atomic-value!
                   source-path source-bytes source-content-id
                   scalar-boundaries form descriptor))

                :list (apply list child-values)
                :vector (vec child-values)
                :map (apply hash-map child-values)
                :set (set child-values)

                :abbreviation
                (let [operator ({:quote 'quote
                                 :syntax-quote 'syntax-quote
                                 :unquote 'unquote
                                 :splice-unquote 'splice-unquote
                                 :deref 'deref}
                                (:abbrev form))]
                  (when-not (and operator (= 1 (count child-values)))
                    (sh03-reader-boundary-fail!
                     source-path :sh03-reader-abbreviation-value form {}))
                  (list operator (first child-values)))

                :metadata-wrapper
                (let [[metadata-value target] child-values
                      metadata (sh03-reader-metadata-map!
                                source-path metadata-value form)]
                  (when-not (and (= 2 (count child-values))
                                 (instance? clojure.lang.IObj target))
                    (sh03-reader-boundary-fail!
                     source-path :sh03-reader-metadata-target form {}))
                  (with-meta target (merge (meta target) metadata)))

                :tagged-literal
                (let [tag (sh03-reader-codepoints-text!
                           source-path (:tag-codepoints form))
                      payload (first child-values)]
                  (when-not (= 1 (count child-values))
                    (sh03-reader-boundary-fail!
                     source-path :sh03-reader-tag-payload form {}))
                  (case tag
                    "inst" (instant/read-instant-date payload)
                    "uuid" (java.util.UUID/fromString payload)
                    (sh03-reader-boundary-fail!
                     source-path :sh03-reader-registered-tag form
                     {:tag tag})))

                (sh03-reader-boundary-fail!
                 source-path :sh03-reader-form-kind form {:kind kind}))]
          (recur (rest remaining) (assoc values (:form-id form) value)))))))

(defn sh03-reader-legacy-trivia-hash
  [token-ids tokens-by-id]
  (reader-canonical-hash
   (mapv (fn [token-id]
           (let [token (tokens-by-id token-id)]
             {:kind (:kind token)
              :raw (:raw token)
              :span (dissoc (:span token) :source :file)}))
         token-ids)))

(defn sh03-reader-contiguous-trivia
  [tokens position direction token-id-map]
  (loop [cursor (+ position direction)
         result []]
    (if (and (<= 0 cursor) (< cursor (count tokens))
             (true? (:trivia? (nth tokens cursor))))
      (recur (+ cursor direction)
             (conj result (token-id-map (:token-id (nth tokens cursor)))))
      (if (neg? direction) (vec (reverse result)) (vec result)))))

(defn sh03-reader-legacy-id
  [value]
  (if (string? value)
    (if-let [[_ family ordinal] (re-matches #"(token|form)/([0-9]+)" value)]
      (keyword (str (if (= family "token") "tok-" "form-") ordinal))
      value)
    value))

(defn sh03-reader-related-records
  [source-path source-id related]
  (mapv
   (fn [record]
     (cond-> record
       (:span record)
       (update :span #(sh03-reader-path-span source-path source-id %))

       (:artifact record)
       (update :artifact sh03-reader-legacy-id)))
   (or related [])))

(defn sh03-reader-raise-rejection!
  [source-path source-bytes reader-options project-context result]
  (when (= :rejected (:status result))
    (let [diagnostic (first (:diagnostics result))
          owner-id (str (:id diagnostic))
          id (case owner-id
               "L1-NS-SHAPE" "C2-NS-SHAPE"
               owner-id)
          reader-engine-diagnostic
          (:reader-engine-diagnostic diagnostic)
          reader-stage
          (if (contains? #{"STAGE1READER003"
                           "STAGE1READER004"
                           "STAGE1READER007"}
                         reader-engine-diagnostic)
            :lexical-tokenization
            :recursive-form-building)
          diagnostic-facts
          (let [facts (:facts diagnostic)
                failure-kind (or (:failure-kind facts)
                                 (:reason diagnostic)
                                 (get-in diagnostic [:reader-state :reason]))]
            (if (and (= id "C2-HASH")
                     (contains? #{:delimiter-depth-limit
                                  :reader-frame-depth-limit}
                                failure-kind))
              (assoc facts
                     :failure-kind :reader-resource-depth-limit
                     :gravity-failure-kind failure-kind)
              facts))
          _
          (case id
            "C2-EXTENSION"
            (when-not (qst-or-gravity-source? source-path)
              (try
                (source-path-policy-fail! source-path source-bytes)
                (catch clojure.lang.ExceptionInfo ex
                  (c2-reader-remap-exception! source-path ex))))

            "C2-ENCODING"
            (try
              (decode-gravity-source-bytes source-path source-bytes)
              (catch clojure.lang.ExceptionInfo ex
                (c2-reader-remap-exception! source-path ex)))

            nil)
          source-id
          (try
            (:source-id
             (c2-source-unit-record
              source-path
              (sh03-reader-strict-source-text!
               source-path source-path source-bytes)
              reader-options project-context))
            (catch clojure.lang.ExceptionInfo _
              (get-in result [:source-unit :source-id])))
          source-content-id (get-in result [:source-unit :bytes-hash])
          raw (when-let [raw-spelling (:raw-spelling diagnostic)]
                (try
                  (if (= :gravity/source-slice (:artifact raw-spelling))
                    (let [source-text
                          (sh03-reader-strict-source-text!
                           source-path source-path source-bytes)
                          scalar-boundaries
                          (sh03-reader-source-scalar-boundaries!
                           source-path source-text source-bytes)]
                      (sh03-reader-accepted-raw-text!
                       source-path source-bytes source-content-id
                       scalar-boundaries raw-spelling
                       (get-in diagnostic [:primary :span])))
                    (sh03-reader-raw-text! source-path raw-spelling))
                  (catch clojure.lang.ExceptionInfo _ nil)))]
      (let [span (sh03-reader-path-span
                  source-path source-id
                  (get-in diagnostic [:primary :span]))
            token-id (sh03-reader-legacy-id
                      (get-in diagnostic [:reader-state :token-id]))
            form-id (sh03-reader-legacy-id
                     (get-in diagnostic [:reader-state :form-id]))
            related (sh03-reader-related-records
                     source-path source-id (:related diagnostic))]
        (if (str/starts-with? id "L1-")
          (throw
           (ex-info
            (or (:message diagnostic) id)
            (-> diagnostic
                (assoc :id id
                       :rule id
                       :source-id source-id
                       :source-span span
                       :primary {:span span :artifact source-id}
                       :related related
                       :token-id token-id
                       :form-id form-id
                       :raw-spelling raw
                       :reader-options reader-options)
                (update :reader-state
                        merge {:token-id token-id :form-id form-id}))))
          (c2-reader-fail!
           id source-path
           {:source-id source-id
            :source-span span
            :token-id token-id
            :form-id form-id
            :raw raw
            :reader-options reader-options
            :facts (:facts diagnostic)}
           {:related related
            :reader-engine-diagnostic
            reader-engine-diagnostic
            :remapped-from
            (or (when (not= owner-id id) owner-id)
                (:remapped-from diagnostic))
            :reader-state
            (merge (:reader-state diagnostic)
                   {:artifact :gravity/reader-state
                    :stage reader-stage
                    :token-id token-id
                    :form-id form-id})
            :cause-message
            (or (:message diagnostic) (c2-reader-message id))
            :facts diagnostic-facts}))))))

(defn sh03-reader-sh02-descriptor
  [source-path project-context resolved summary]
  (let [binding (:plan-binding resolved)
        projection-name :reader-product-identities
        fact-name :reader-product-binding
        identity-name :reader-result
        identity-domain :gravity/sh03-reader-result-identity-v2
        evidence-id
        (p15-s23-c6c10-canonical-digest
         source-path
         {:domain :gravity/sh03-reader-envelope-evidence-v2
          :summary summary
          :plan-semantic-hash (:plan-semantic-hash binding)})
        identity-preimage {:summary summary}
        observed-id
        (p15-s23-c6c10-canonical-digest
         source-path
         {:domain identity-domain :semantic-input identity-preimage})
        fact-entries
        [{:syntax-result-id (:syntax-result-id summary)
          :syntax-stream-id (:syntax-stream-id summary)
          :serialization-id (:serialization-set-id summary)
          :graph-id (:graph-id summary)}]
        fact-value {:family fact-name :entries fact-entries}
        artifact-id
        (p15-s23-c6c10-canonical-digest
         source-path {:reader-result (:reader-result-id summary)})]
    {:artifact :gravity/private-authenticated-envelope-descriptor
     :schema-version 1
     :stage :c2-reader
     :artifact-kind :gravity/sh03-reader-products
     :source-revision
     {:owner :sh03-reader
      :source-language :gravity
      :logical-source-path sh03-reader-source-relative-path
      :source-content-hash (:source-content-hash binding)
      :source-byte-count (:source-byte-count binding)
      :plan-semantic-hash (:plan-semantic-hash binding)
      :functions-semantic-hash (:functions-semantic-hash binding)
      :builder-function sh03-reader-entrypoint
      :builder-semantic-hash (:entrypoint-semantic-hash binding)
      :function-shapes
      {sh03-reader-entrypoint {:arity 3}
       sh03-reader-verifier {:arity 4}}}
     :projection-contract
     {:contract-kind :gravity/sh03-reader-product-envelope-contract
      :contract-version 1
      :profile :meta
      :target :jvm
      :required-semantic-projections [projection-name]
      :required-fact-families [fact-name]
      :required-identity-subjects [identity-name]}
     :semantic-projections
     [{:name projection-name
       :role :complete-reader-product-identity-projection
       :entry-count (count summary)
       :value summary}]
     :fact-transitions
     [{:name fact-name
       :disposition :preserved
       :input fact-value
       :output fact-value
       :input-count (count fact-value)
       :output-count (count fact-value)
       :evidence-ids [evidence-id]}]
     :effect-capability-relation
     {:effect-facts {:declared #{} :observed #{}}
      :capability-facts {:required #{} :granted #{}}
      :capability-proof-facts {:proof-ids [evidence-id]}
      :effect-order []
      :provider-selections []
      :grant-scopes []}
     :proof-composite
     {:proof-records [{:proof-id evidence-id :status :checked}]
      :proof-certificate-table {evidence-id {:status :checked}}
      :proof-summary {:required 1 :checked 1}
      :proof-usage [{:proof-id evidence-id :used-by :reader-products}]}
     :preservation
     {:requires [fact-name]
      :preserves [fact-name]
      :invalidates []
      :regenerates []
      :residual-checks [:identity-subject-equality
                        :digest-graph-reachability]}
     :identity-subjects
     [{:name identity-name
       :domain identity-domain
       :preimage identity-preimage
       :observed-id observed-id}]
     :lineage
     [{:stage :sh03-reader
       :artifact-kind :gravity/sh03-reader-result
       :semantic-id (:reader-result-id summary)
       :artifact-id artifact-id
       :verification-id evidence-id
       :relation :produced-from-gravity-reader}]
     :reference-closure
     {:root-id "sh03-reader-result"
      :node-ids ["sh03-reader-result"]
      :edges []
      :fact-reference-ids [evidence-id]
      :origin-reference-ids []
      :proof-reference-ids [evidence-id]
      :runtime-check-reference-ids []
      :observed-node-count 1
      :observed-edge-count 0
      :observed-maximum-depth 0}
     :actual-path-provenance
     {:source-path source-path
      :workspace-root (or (:project-root-path project-context)
                          (System/getProperty "user.dir"))
      :invocation-root (System/getProperty "user.dir")}
     :bounds p15-s23-sh02-authenticated-envelope-bounds}))

(defn sh03-reader-adapt-evidence!
  [source-path source-id source-bytes source-content-id scalar-boundaries result
   form-id-map token-id-map token-stream form-tree]
  (let [forms-by-id (into {} (map (juxt :form-id identity) form-tree))
        literal-records (c2-literal-records form-tree)
        literal-by-form (into {} (map (juxt :form-id identity)
                                     literal-records))
        gravity-literal-projection
        (mapv
         (fn [record]
           (let [form-id (form-id-map (:form-id record))
                 _ (sh03-reader-form-value-reference!
                    source-path (:decoded record) (:form-id record))
                 literal (literal-by-form form-id)]
             (when-not
              (and literal
                   (= (:kind record) (:kind literal))
                   (= (sh03-reader-accepted-raw-text!
                       source-path source-bytes source-content-id
                       scalar-boundaries (:raw record) (:span record))
                      (:raw literal))
                   (= (dissoc (:span record) :source :file)
                      (dissoc (:span literal) :source :file)))
               (sh03-reader-boundary-fail!
                source-path :sh03-reader-literal-projection record
                {:adapted-form-id form-id}))
             literal))
         (:literal-decoding-records result))
        _ (when-not (= literal-records gravity-literal-projection)
            (sh03-reader-boundary-fail!
             source-path :complete-sh03-reader-literal-projection
             gravity-literal-projection
             {:expected-literal-count (count literal-records)}))
        deferred-records (c2-deferred-semantic-literals form-tree)
        deferred-by-form (into {} (map (juxt :form-id identity)
                                      deferred-records))
        gravity-deferred
        (get-in result [:semantic-error-deferment-record
                        :deferred-literal-records])
        gravity-deferred-projection
        (mapv
         (fn [record]
           (let [form-id (form-id-map (:form-id record))
                 _ (sh03-reader-form-value-reference!
                    source-path (:descriptor record) (:form-id record))
                 deferred (deferred-by-form form-id)]
             (when-not
              (and deferred
                   (= (:kind record) (:kind deferred))
                   (= (sh03-reader-accepted-raw-text!
                       source-path source-bytes source-content-id
                       scalar-boundaries (:raw record) (:span deferred))
                      (:raw deferred))
                   (= :deferred (:semantic-validation record)))
               (sh03-reader-boundary-fail!
                source-path :sh03-reader-deferred-literal-projection record
                {:adapted-form-id form-id}))
             deferred))
         gravity-deferred)
        _ (when-not (= deferred-records gravity-deferred-projection)
            (sh03-reader-boundary-fail!
             source-path :complete-sh03-reader-deferment-projection
             gravity-deferred-projection
             {:expected-deferred-count (count deferred-records)}))
        extension-records (c2-reader-extension-invocations form-tree)
        gravity-extension-projection
        (mapv
         (fn [record]
           (let [tag (symbol (sh03-reader-codepoints-text!
                              source-path (:tag-codepoints record)))
                 handler
                 (symbol (sh03-reader-codepoints-text!
                          source-path
                          (get-in record [:handler :name-codepoints])))]
             {:artifact :gravity/reader-extension-invocation
              :tag tag
              :handler handler
              :build-effects (:build-effects record)
              :capabilities (:capabilities record)
              :profiles (:profiles record)
              :invocations
              (mapv
               (fn [invocation]
                 {:form-id (form-id-map (:form-id invocation))
                  :span (sh03-reader-path-span
                         source-path source-id (:span invocation))
                  :raw (sh03-reader-accepted-raw-text!
                        source-path source-bytes source-content-id
                        scalar-boundaries (:raw invocation)
                        (:span invocation))})
               (:invocations record))
              :status (:status record)}))
         (:reader-extension-invocation-records result))
        _ (when-not (= extension-records gravity-extension-projection)
            (sh03-reader-boundary-fail!
             source-path :complete-sh03-reader-extension-projection
             gravity-extension-projection
             {:expected-extension-records extension-records}))
        source-map (:reader-source-map result)
        projected-token-spans
        (mapv (fn [record]
                {:token-id (token-id-map (:token-id record))
                 :span (sh03-reader-path-span source-path source-id
                                               (:span record))})
              (:token-spans source-map))
        expected-token-spans
        (mapv #(select-keys % [:token-id :span]) token-stream)
        projected-form-spans
        (mapv (fn [record]
                {:form-id (form-id-map (:form-id record))
                 :span (sh03-reader-path-span source-path source-id
                                               (:span record))
                 :parent-form-id
                 (form-id-map (:parent-form-id record))})
              (:form-spans source-map))
        expected-form-spans
        (mapv #(select-keys % [:form-id :span :parent-form-id]) form-tree)]
    (when-not (and (= expected-token-spans projected-token-spans)
                   (= expected-form-spans projected-form-spans))
      (sh03-reader-boundary-fail!
       source-path :complete-sh03-reader-source-map-projection source-map
       {:expected-token-span-count (count expected-token-spans)
        :expected-form-span-count (count expected-form-spans)}))
    {:literal-decoding-records literal-records
     :deferred-literal-records deferred-records
     :reader-extension-invocation-records extension-records
     :reader-source-map
     {:artifact :gravity/reader-source-map
      :token-spans projected-token-spans
      :form-spans projected-form-spans}}))

(defn- sh03-reader-adapter-summary
  [result source-unit token-stream form-tree extension-records
   token-id-map form-id-map]
  {:slice :SH-03
   :status :accepted
   :adapter-contract :gravity/sh03-to-c2-reader-products-v2
   :source-unit-id (get-in result [:incremental-reader-hashes :source-unit])
   :token-stream-id (get-in result [:incremental-reader-hashes :token-stream])
   :form-tree-id (get-in result [:incremental-reader-hashes :form-tree])
   :extension-invocation-set-id
   (get-in result [:incremental-reader-hashes :extension-invocation-set])
   :reader-result-id
   (get-in result [:incremental-reader-hashes :reader-result])
   :semantic-value-table-id
   (reader-canonical-hash (:semantic-value-table result))
   :adapted-source-unit-id (:source-id source-unit)
   :adapted-token-stream-id
   (reader-canonical-hash (c2-token-hash-input token-stream))
   :adapted-form-tree-id
   (reader-canonical-hash (c2-form-hash-input form-tree))
   :adapted-extension-invocation-set-id
   (reader-canonical-hash (c2-extension-hash-input extension-records))
   :token-id-projection-id (reader-canonical-hash token-id-map)
   :form-id-projection-id (reader-canonical-hash form-id-map)})

(defn sh03-reader-adapt-products!
  [source-path source-text source-bytes reader-options project-context
   resolved]
  (let [result (:result resolved)]
    (sh03-reader-raise-rejection!
     source-path source-bytes reader-options project-context result)
    (when-not (= :accepted (:status result))
      (sh03-reader-boundary-fail!
       source-path :accepted-sh03-reader-result result {}))
    (let [source-unit (c2-source-unit-record
                       source-path source-text reader-options project-context)
          source-id (:source-id source-unit)
          source-content-id (get-in result [:source-unit :bytes-hash])
          _ (when-not (= source-content-id (:bytes-hash source-unit))
              (sh03-reader-boundary-fail!
               source-path :snapshot-bound-sh03-reader-source-unit
               (:source-unit result)
               {:expected-source-content-id (:bytes-hash source-unit)}))
          scalar-boundaries
          (sh03-reader-source-scalar-boundaries!
           source-path source-text source-bytes)
          raw-tokens (:token-stream result)
          raw-forms (:form-tree result)
          semantic-index
          (sh03-reader-semantic-value-index!
           source-path (:semantic-value-table result))
          _ (sh03-reader-semantic-value-closure!
             source-path source-bytes source-content-id scalar-boundaries
             raw-tokens raw-forms semantic-index)
          token-id-map
          (into {} (map-indexed
                    (fn [index token]
                      [(:token-id token) (keyword (str "tok-" index))])
                    raw-tokens))
          form-id-map
          (into {} (map-indexed
                    (fn [index form]
                      [(:form-id form) (keyword (str "form-" index))])
                    raw-forms))
          _ (doseq [[form-id record reference]
                    (map vector (:top-level-form-ids result)
                         (:top-level-parsed-records result)
                         (:parsed-semantic-values result))]
              (when-not (= form-id (:form-id record))
                (sh03-reader-boundary-fail!
                 source-path :form-bound-sh03-reader-top-level-record
                 record {:expected-form-id form-id}))
              (sh03-reader-form-value-reference!
               source-path (:value record) form-id)
              (sh03-reader-form-value-reference!
               source-path reference form-id))
          host-values
          (try
            (sh03-reader-host-values!
             source-path source-bytes source-content-id scalar-boundaries
             raw-forms semantic-index)
            (catch InterruptedException interrupted
              (.interrupt (Thread/currentThread))
              (throw interrupted))
            (catch clojure.lang.ExceptionInfo error
              (throw error))
            (catch StackOverflowError error
              (sh03-reader-boundary-fail!
               source-path :bounded-sh03-reader-adapter-host-stack {}
               {:contained-host-error (.getName (class error))}))
            (catch Throwable error
              (sh03-reader-boundary-fail!
               source-path :contained-sh03-reader-adapter-value-failure {}
               {:contained-host-error (.getName (class error))
                :cause-message (.getMessage error)})))
          token-stream
          (mapv
           (fn [token]
             (let [kind (:kind token)
                   raw (sh03-reader-accepted-raw-text!
                        source-path source-bytes source-content-id
                        scalar-boundaries (:raw token) (:span token))
                   descriptor
                   (if (= :gravity/semantic-value-reference
                          (:artifact (:descriptor token)))
                     (sh03-reader-semantic-reference-value!
                      source-path semantic-index (:descriptor token)
                      :descriptor)
                     (:descriptor token))
                   decoded
                   (cond
                     (contains? #{:whitespace :comment} kind) nil
                     (contains? #{:list-open :vector-open :map-open :close}
                                kind) raw
                     (= :set-open kind) :set
                     (= :abbreviation kind) (:abbreviation token)
                     (= :reader-tag kind)
                     (symbol (sh03-reader-codepoints-text!
                              source-path (:tag-codepoints token)))
                     :else
                     (sh03-reader-host-atomic-value!
                      source-path source-bytes source-content-id
                      scalar-boundaries token descriptor))]
               (cond->
                {:token-id (token-id-map (:token-id token))
                 :source-id source-id
                 :source-path source-path
                 :kind (if (= :reader-tag kind) :tag kind)
                 :raw raw
                 :lexeme (if (contains? #{:string :character} kind)
                           decoded raw)
                 :decoded decoded
                 :span (sh03-reader-path-span source-path source-id
                                               (:span token))
                 :trivia-before []
                 :reader-origin :source}
                 (true? (:trivia? token)) (assoc :trivia? true)
                 (= :abbreviation kind) (assoc :abbrev (:abbreviation token))
                 (= :reader-tag kind) (assoc :tag decoded)
                 (contains? #{:list-open :vector-open :map-open :set-open}
                            kind)
                 (assoc :close-token ({:list-open ")" :vector-open "]"
                                       :map-open "}" :set-open "}"} kind))
                 (= :set-open kind) (assoc :dispatch "#"))))
           raw-tokens)
          tokens-by-id (into {} (map (juxt :token-id identity) token-stream))
          raw-token-position
          (into {} (map-indexed (fn [index token]
                                  [(:token-id token) index]) raw-tokens))
          form-tree
          (mapv
           (fn [form]
             (let [value (host-values (:form-id form))
                   kind (:kind form)
                   open-position (raw-token-position (:open-token form))
                   close-position (raw-token-position (:close-token form))
                   leading (if (integer? open-position)
                             (sh03-reader-contiguous-trivia
                              raw-tokens open-position -1 token-id-map)
                             [])
                   trailing (if (and (:collection-kind form)
                                     (integer? close-position))
                              (sh03-reader-contiguous-trivia
                               raw-tokens close-position -1 token-id-map)
                              [])
                   child-ids (mapv form-id-map (:children form))
                   target-child-id
                   (when (contains? #{:abbreviation :metadata-wrapper} kind)
                     (if (= :metadata-wrapper kind)
                       (second child-ids)
                       (first child-ids)))
                   prefix-span
                   (when (contains? #{:abbreviation :metadata-wrapper} kind)
                     (:span (tokens-by-id (token-id-map (:open-token form)))))
                   metadata
                   (if (= :metadata-wrapper kind)
                     (or (meta value) {})
                     (or (meta value) {}))]
               (cond->
                {:form-id (form-id-map (:form-id form))
                 :source-id source-id
                 :source-path source-path
                 :kind kind
                 :parent-form-id (form-id-map (:parent-form-id form))
                 :children child-ids
                 :open-token (token-id-map (:open-token form))
                 :close-token (token-id-map (:close-token form))
                 :span (sh03-reader-path-span source-path source-id
                                               (:span form))
                 :metadata metadata
                 :origin {:kind :source
                          :reader :gravity-sh03-reader
                          :projection :clojure-c2-compatibility-adapter
                          :source-id source-id
                          :source-path source-path}
                 :leading-trivia-token-ids leading
                 :leading-trivia-hash
                 (sh03-reader-legacy-trivia-hash leading tokens-by-id)
                 :raw (sh03-reader-accepted-raw-text!
                       source-path source-bytes source-content-id
                       scalar-boundaries (:raw form) (:span form))
                 :value value}
                 (empty? (:children form))
                 (assoc :token-id (token-id-map (:open-token form)))
                 (:collection-kind form)
                 (assoc :collection-kind (:collection-kind form)
                        :trailing-trivia-token-ids trailing
                        :trailing-trivia-hash
                        (sh03-reader-legacy-trivia-hash trailing tokens-by-id))
                 (= :tagged-literal kind)
                 (assoc :tag (symbol (sh03-reader-codepoints-text!
                                      source-path (:tag-codepoints form))))
                 (contains? #{:abbreviation :metadata-wrapper} kind)
                 (assoc :abbrev (:abbrev form)
                        :surface-span prefix-span
                        :expanded-form value
                        :generated-origin
                        [{:kind :generated
                          :producer :reader-abbreviation
                          :reason (:abbrev form)
                          :from prefix-span
                          :child-form-id target-child-id}]))))
           raw-forms)
          forms-by-id (into {} (map (juxt :form-id identity) form-tree))
          root-form-ids (mapv form-id-map (:top-level-form-ids result))
          parsed-records
          (mapv (fn [root-index form-id]
                  (let [form (forms-by-id form-id)]
                    {:form (:value form)
                     :kind (:kind form)
                     :form-id form-id
                     :span (assoc (:span form) :form-index root-index)
                     :parent-form-id nil}))
                (range) root-form-ids)
          adapted-evidence
          (sh03-reader-adapt-evidence!
           source-path source-id source-bytes source-content-id
           scalar-boundaries result form-id-map token-id-map
           token-stream form-tree)
          descriptor
          (sh03-reader-adapter-summary
           result source-unit token-stream form-tree
           (:reader-extension-invocation-records adapted-evidence)
           token-id-map form-id-map)
          envelope-descriptor
          (sh03-reader-sh02-descriptor
           source-path project-context resolved descriptor)
          envelope
          (p15-s23-stage2-sh02-descriptor-envelope
           :c2-reader :gravity/sh03-reader-products envelope-descriptor
           source-path)
          _ (p15-s23-stage2-sh02-descriptor-envelope-verify!
             envelope :c2-reader :gravity/sh03-reader-products
             envelope-descriptor source-path)]
      {:source-unit source-unit
       :token-stream token-stream
       :form-tree form-tree
       :root-form-ids root-form-ids
       :parsed-records parsed-records
       :parsed-values (mapv :form parsed-records)
       :literal-decoding-records
       (:literal-decoding-records adapted-evidence)
       :deferred-literal-records
       (:deferred-literal-records adapted-evidence)
       :reader-extension-invocation-records
       (:reader-extension-invocation-records adapted-evidence)
       :gravity-reader-source-map (:reader-source-map adapted-evidence)
       :sh03-reader-raw-result (:raw-result resolved)
       :sh03-reader-result result
       :sh03-reader-verification-report (:verification-report resolved)
       :sh03-reader-plan-binding (:plan-binding resolved)
       :sh03-reader-adapter-contract
       :gravity/sh03-to-c2-reader-products-v2
       :sh03-reader-adapter-descriptor descriptor
       :sh03-semantic-value-table-id
       (:semantic-value-table-id descriptor)
       :sh02-reader-envelope-descriptor envelope-descriptor
       :sh02-reader-envelope envelope})))

(defn c2-reader-products-clojure-oracle
  ([source-path source-text reader-options]
   (c2-reader-products-clojure-oracle
    source-path source-text reader-options
    (reader-project-context-for-source source-path)))
  ([source-path source-text reader-options project-context]
   (let [source-unit (c2-source-unit-record source-path source-text
                                            reader-options project-context)
         table (stage1-reader-table)]
     (try
       (let [stage1-stream (stage1-reader-token-stream source-path source-text
                                                       table reader-options)
             _ (c2-prevalidate-token-depth!
                source-path source-unit (:tokens stage1-stream))
             token-stream (mapv #(c2-token-record % source-unit)
                                (:tokens stage1-stream))
             parser-stream (assoc stage1-stream :tokens token-stream)
             parsed (stage1-reader-products-from-token-stream
                     source-path source-text table parser-stream)
             form-tree (mapv #(c2-form-record % source-unit)
                             (:form-tree parsed))]
         {:source-unit source-unit
          :token-stream token-stream
          :form-tree form-tree
          :root-form-ids (:root-form-ids parsed)
          :parsed-records (:records parsed)
          :parsed-values (:parsed-values parsed)})
       (catch StackOverflowError error
         (c2-reader-fail!
          "C2-HASH" source-path
          {:stage :read-source
           :source-id (:source-id source-unit)
           :source-span (source-span source-path 0)
           :reader-options reader-options}
          {:missing-fields [:stack-safe-reader-form-construction]
           :facts {:maximum-form-depth max-reader-form-depth
                   :failure-kind :reader-resource-depth-limit
                   :contained-host-error (.getName (class error))}}))
       (catch clojure.lang.ExceptionInfo ex
         (throw
          (ex-info (.getMessage ex)
                   (merge {:source-id (:source-id source-unit)
                           :reader-options reader-options}
                          (ex-data ex))
                   ex)))))))

(defn c2-reader-products
  ([source-path source-text reader-options]
   (c2-reader-products source-path source-text reader-options
                       (reader-project-context-for-source source-path)))
  ([source-path source-text reader-options project-context]
   (let [source-bytes (.getBytes source-text
                                 java.nio.charset.StandardCharsets/UTF_8)
         resolved (sh03-reader-resolved-result!
                   source-path source-bytes project-context reader-options)]
     (sh03-reader-adapt-products!
      source-path source-text source-bytes reader-options project-context
      resolved))))

(defn c2-syntax-seed-stream
  [source-path products module-context]
  (let [forms-by-id (into {} (map (juxt :form-id identity)
                                  (:form-tree products)))
        seed-records
        (mapv
         (fn [idx record]
           (let [node (forms-by-id (:form-id record))
                 generated-origins
                 (mapv (fn [origin]
                         {:from (:from origin)
                          :reader-abbreviation (:reason origin)
                          :expanded-form (:value node)})
                       (:generated-origin node))]
             {:form (:form record)
              :form-id (:form-id node)
              :span (assoc (:span node) :form-index idx)
              :metadata (or (:metadata node) {})
              :reader-origin {:kind :source
                              :raw-form-kind (:kind node)
                              :raw-excerpt (:raw node)
                              :abbreviation (:abbrev node)}
              :generated-origin generated-origins}))
         (range)
         (:parsed-records products))]
    (syntax-object-stream source-path seed-records module-context)))

(defn c2-deferred-semantic-literals
  [form-tree]
  (mapv #(select-keys % [:form-id :kind :raw :value :span])
        (filter (fn [form]
                  (and (contains? #{:integer :ratio :decimal} (:kind form))
                       (= :deferred
                          (get-in form [:value :semantic-validation]))
                       (contains?
                        #{:gravity/deferred-ratio-literal
                          :gravity/decimal-literal
                          :gravity/deferred-numeric-literal}
                        (get-in form [:value :artifact]))))
                form-tree)))

(defn c2-top-level-products
  [artifact]
  (let [forms-by-id (into {} (map (juxt :form-id identity)
                                  (:form-tree artifact)))
        tokens-by-id (into {} (map (juxt :token-id identity)
                                   (:token-stream artifact)))]
    (mapv (fn [form-id]
            (let [form-record (forms-by-id form-id)]
              {:form-record form-record
               :token-record (tokens-by-id (:open-token form-record))}))
          (:top-level-form-ids artifact))))

(defn l1-source-unit-artifacts
  [source-path source-text reader-options project-context]
  {:source-unit-record
   (c2-source-unit-record source-path source-text reader-options
                          project-context)
   :reader-options reader-options})

(defn c2-utf8-slice
  [source-bytes byte-start byte-end]
  (String. (java.util.Arrays/copyOfRange source-bytes byte-start byte-end)
           java.nio.charset.StandardCharsets/UTF_8))

(defn c2-span-encloses?
  [parent child]
  (and (map? parent)
       (map? child)
       (integer? (:byte-start parent))
       (integer? (:byte-end parent))
       (integer? (:byte-start child))
       (integer? (:byte-end child))
       (<= (:byte-start parent) (:byte-start child))
       (>= (:byte-end parent) (:byte-end child))))

(defn c2-spans-source-ordered?
  [spans]
  (every? (fn [[left right]]
            (and (map? left)
                 (map? right)
                 (integer? (:byte-end left))
                 (integer? (:byte-start right))
                 (<= (:byte-end left) (:byte-start right))))
          (partition 2 1 spans)))

(defn c2-form-graph-metrics
  [form-tree]
  (let [forms-by-id (into {} (map (juxt :form-id identity) form-tree))
        form-ids (mapv :form-id form-tree)
        indegrees
        (reduce (fn [counts form]
                  (reduce (fn [result child-id]
                            (if (contains? forms-by-id child-id)
                              (update result child-id (fnil inc 0))
                              result))
                          counts
                          (:children form)))
                (zipmap form-ids (repeat 0))
                form-tree)
        initial-ids (filterv #(zero? (get indegrees % 0)) form-ids)
        initial-queue (reduce conj clojure.lang.PersistentQueue/EMPTY
                              initial-ids)]
    (loop [pending initial-queue
           remaining indegrees
           depths (zipmap initial-ids (repeat 1))
           processed 0
           max-depth 0]
      (if (empty? pending)
        {:acyclic? (= processed (count form-ids))
         :processed-form-count processed
         :max-form-depth max-depth}
        (let [form-id (peek pending)
              parent-depth (get depths form-id 1)
              children (filterv #(contains? forms-by-id %)
                                (:children (forms-by-id form-id)))
              [next-queue next-remaining next-depths]
              (reduce
               (fn [[queue counts known-depths] child-id]
                 (let [next-count (dec (get counts child-id 0))
                       child-depth (max (get known-depths child-id 1)
                                        (inc parent-depth))]
                   [(cond-> queue (zero? next-count) (conj child-id))
                    (assoc counts child-id next-count)
                    (assoc known-depths child-id child-depth)]))
               [(pop pending) remaining depths]
               children)]
          (recur next-queue next-remaining next-depths (inc processed)
                 (max max-depth parent-depth)))))))

(defn c2-lexical-product-validation
  [source-text token-stream form-tree root-form-ids]
  (let [source-bytes (.getBytes source-text
                                java.nio.charset.StandardCharsets/UTF_8)
        source-byte-count (alength source-bytes)
        token-ids (mapv :token-id token-stream)
        form-ids (mapv :form-id form-tree)
        token-ids-unique? (= token-ids (vec (distinct token-ids)))
        form-ids-unique? (= form-ids (vec (distinct form-ids)))
        root-form-ids-unique?
        (= (vec root-form-ids) (vec (distinct root-form-ids)))
        tokens-by-id (into {} (map (juxt :token-id identity) token-stream))
        forms-by-id (into {} (map (juxt :form-id identity) form-tree))
        form-id-set (set form-ids)
        root-id-set (set root-form-ids)
        child-ids (mapcat :children form-tree)
        child-frequency (frequencies child-ids)
        parentless-id-set
        (set (keep #(when (nil? (:parent-form-id %)) (:form-id %)) form-tree))
        root-form-ids-resolve?
        (every? #(contains? forms-by-id %) root-form-ids)
        token-links-resolve-exactly-once?
        (and token-ids-unique?
             (every? (fn [form]
                       (and (contains? tokens-by-id (:open-token form))
                            (contains? tokens-by-id (:close-token form))))
                     form-tree))
        child-links-resolve-exactly-once?
        (and form-ids-unique?
             (every? #(contains? forms-by-id %) child-ids))
        parent-links-resolve-exactly-once?
        (and form-ids-unique?
             (every? #(or (nil? (:parent-form-id %))
                          (contains? forms-by-id (:parent-form-id %)))
                     form-tree))
        form-links-resolve?
        (and token-links-resolve-exactly-once?
             child-links-resolve-exactly-once?
             parent-links-resolve-exactly-once?)
        children-unique?
        (every? #(= (count (:children %))
                    (count (distinct (:children %))))
                form-tree)
        roots-parentless?
        (and root-form-ids-resolve?
             (every? #(nil? (:parent-form-id (forms-by-id %)))
                     root-form-ids))
        declared-roots-match-parentless?
        (= root-id-set parentless-id-set)
        non-root-single-parent?
        (every?
         (fn [form]
           (let [form-id (:form-id form)
                 parent-id (:parent-form-id form)]
             (if (contains? root-id-set form-id)
               (and (nil? parent-id)
                    (zero? (get child-frequency form-id 0)))
               (let [parent (forms-by-id parent-id)]
                 (and parent
                      (= 1 (get child-frequency form-id 0))
                      (= 1 (count (filter #{form-id} (:children parent)))))))))
         form-tree)
        parent-child-bidirectional?
        (and non-root-single-parent?
             (every? (fn [parent]
                       (every? #(= (:form-id parent)
                                   (:parent-form-id (forms-by-id %)))
                               (:children parent)))
                     form-tree))
        no-orphans?
        (every? #(if (contains? root-id-set %)
                   (zero? (get child-frequency % 0))
                   (= 1 (get child-frequency % 0)))
                form-ids)
        reachable-form-ids
        (loop [pending (vec root-form-ids)
               seen #{}]
          (if-let [form-id (first pending)]
            (let [remaining (subvec pending 1)
                  form (forms-by-id form-id)]
              (if (or (contains? seen form-id) (nil? form))
                (recur remaining seen)
                (recur (into remaining (:children form))
                       (conj seen form-id))))
            seen))
        all-forms-reachable? (= form-id-set reachable-form-ids)
        graph-metrics (c2-form-graph-metrics form-tree)
        acyclic? (:acyclic? graph-metrics)
        children-source-ordered?
        (every? (fn [form]
                  (let [children (mapv forms-by-id (:children form))]
                    (and (every? some? children)
                         (c2-spans-source-ordered? (mapv :span children)))))
                form-tree)
        root-forms-source-ordered?
        (let [roots (mapv forms-by-id root-form-ids)]
          (and (every? some? roots)
               (c2-spans-source-ordered? (mapv :span roots))))
        parent-spans-enclose?
        (and form-links-resolve?
             (every?
              (fn [form]
                (and (c2-span-encloses? (:span form)
                                        (:span (tokens-by-id
                                                (:open-token form))))
                     (c2-span-encloses? (:span form)
                                        (:span (tokens-by-id
                                                (:close-token form))))
                     (every? #(c2-span-encloses?
                               (:span form) (:span (forms-by-id %)))
                             (:children form))))
              form-tree))
        collection-delimiters-resolve?
        (and token-links-resolve-exactly-once?
             (every?
              (fn [form]
                (if-let [collection-kind (:collection-kind form)]
                  (let [open (tokens-by-id (:open-token form))
                        close (tokens-by-id (:close-token form))
                        expected-open ({:list ["(" :list-open]
                                        :vector ["[" :vector-open]
                                        :map ["{" :map-open]
                                        :set ["#{" :set-open]}
                                       collection-kind)
                        expected-close ({:list ")" :vector "]" :map "}"
                                         :set "}"} collection-kind)]
                    (and expected-open
                         (= (first expected-open) (:raw open))
                         (= (second expected-open) (:kind open))
                         (= expected-close (:raw close))
                         (= :close (:kind close))))
                  true))
              form-tree))
        maps-even-logical-children?
        (every? #(if (= :map (:collection-kind %))
                   (even? (count (:children %)))
                   true)
                form-tree)
        max-depth (:max-form-depth graph-metrics)
        valid-byte-range?
        (fn [span]
          (and (map? span)
               (integer? (:byte-start span))
               (integer? (:byte-end span))
               (<= 0 (:byte-start span) (:byte-end span) source-byte-count)))
        root-raw
        (set (keep (fn [form-id]
                     (let [form (forms-by-id form-id)]
                       (when (and form
                                  (or (:collection-kind form)
                                      (seq (:children form))))
                         (:raw form))))
                   root-form-ids))
        token-raw-slices-exact?
        (every? (fn [token]
                  (let [span (:span token)]
                    (and (string? (:raw token))
                         (pos? (count (:raw token)))
                         (valid-byte-range? span)
                         (= (:raw token)
                            (c2-utf8-slice source-bytes
                                          (:byte-start span)
                                          (:byte-end span))))))
                token-stream)
        form-raw-slices-exact?
        (every? (fn [form]
                  (let [span (:span form)]
                    (and (string? (:raw form))
                         (pos? (count (:raw form)))
                         (valid-byte-range? span)
                         (= (:raw form)
                            (c2-utf8-slice source-bytes
                                          (:byte-start span)
                                          (:byte-end span))))))
                form-tree)
        graph-valid?
        (every? true?
                [token-ids-unique? form-ids-unique? root-form-ids-unique?
                 root-form-ids-resolve? token-links-resolve-exactly-once?
                 child-links-resolve-exactly-once?
                 parent-links-resolve-exactly-once? children-unique?
                 roots-parentless? declared-roots-match-parentless?
                 non-root-single-parent? parent-child-bidirectional?
                 no-orphans? all-forms-reachable? acyclic?
                 children-source-ordered? root-forms-source-ordered?
                 parent-spans-enclose? collection-delimiters-resolve?
                 maps-even-logical-children? form-raw-slices-exact?])]
    {:artifact :gravity/c2-lexical-product-validation
     :ordered-token-ids-unique? token-ids-unique?
     :form-ids-unique? form-ids-unique?
     :root-form-ids-unique? root-form-ids-unique?
     :token-count-exceeds-top-level-form-count?
     (> (count token-stream) (count root-form-ids))
     :token-raw-slices-exact? token-raw-slices-exact?
     :form-raw-slices-exact? form-raw-slices-exact?
     :token-provenance-complete?
     (every? #(and (:source-id %) (:source-path %)
                   (= (:source-id %) (get-in % [:span :file]))
                   (get-in % [:span :start :line])
                   (get-in % [:span :start :column])
                   (get-in % [:span :end :line])
                   (get-in % [:span :end :column]))
             token-stream)
     :no-token-contains-top-level-form?
     (not-any? (fn [token]
                 (some #(str/includes? (:raw token) %) root-raw))
               token-stream)
     :root-form-ids-resolve? root-form-ids-resolve?
     :token-links-resolve-exactly-once? token-links-resolve-exactly-once?
     :child-links-resolve-exactly-once? child-links-resolve-exactly-once?
     :parent-links-resolve-exactly-once? parent-links-resolve-exactly-once?
     :form-links-resolve? form-links-resolve?
     :children-unique? children-unique?
     :roots-parentless? roots-parentless?
     :declared-roots-match-parentless? declared-roots-match-parentless?
     :non-root-single-parent? non-root-single-parent?
     :parent-child-bidirectional? parent-child-bidirectional?
     :no-orphans? no-orphans?
     :all-forms-reachable? all-forms-reachable?
     :acyclic? acyclic?
     :children-source-ordered? children-source-ordered?
     :root-forms-source-ordered? root-forms-source-ordered?
     :parent-spans-enclose-children? parent-spans-enclose?
     :collection-delimiters-resolve? collection-delimiters-resolve?
     :maps-even-logical-children? maps-even-logical-children?
     :recursive-children-present? (boolean (some #(seq (:children %)) form-tree))
     :nested-depth-at-least-three? (>= max-depth 3)
     :max-form-depth max-depth
     :graph-valid? graph-valid?
     :status (if graph-valid? :passed :failed)}))
(defn c2-reader-capability-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic (:rejected-design-coverage artifact)))
        hashes (:incremental-reader-hashes artifact)
        lexical (:lexical-product-validation artifact)
        abbreviation-forms (filter #(contains? #{:abbreviation
                                                  :metadata-wrapper}
                                                (:kind %))
                                   (:form-tree artifact))]
    {:source-unit-hash-stable?
     (boolean
      (re-find #"^sha256:" (get-in artifact [:source-unit-record
                                             :source-id])))
     :token-and-form-spans-present?
     (and (every? #(and (:token-id %) (get-in % [:span :byte-start])
                        (get-in % [:span :byte-end]))
                  (:token-stream artifact))
          (every? #(and (:form-id %) (get-in % [:span :byte-start])
                        (get-in % [:span :byte-end]))
                  (:form-tree artifact)))
     :abbreviation-origins-present?
     (every? #(seq (:generated-origin %)) abbreviation-forms)
     :literal-facts-present?
     (let [records (:literal-decoding-records artifact)
           expected-records (c2-literal-records (:form-tree artifact))]
       (and (= (count expected-records) (count records))
            (every? #(and (:literal-id %)
                          (:form-id %)
                          (:kind %)
                          (string? (:raw %))
                          (:span %)
                          (contains? % :decoded)
                          (map? (:facts %)))
                    records)))
     :trivia-retained?
     (and (true? (get-in artifact [:source-unit-record :reader-options
                                   :retain-comments]))
          (= (mapv :token-id (filter :trivia? (:token-stream artifact)))
             (mapv :trivia-id (:trivia-retention-records artifact))))
     :extension-policy-recorded?
     (= :registered (get-in artifact [:reader-extension-policy :status]))
     :incremental-hashes-stable?
     (and (= :stable (:status hashes))
          (every? #(re-find #"^sha256:" (str (get hashes %)))
                  [:source-unit :token-stream :form-tree
                   :syntax-seed-stream :extension-invocation-set
                   :reader-diagnostics]))
     :diagnostics-covered?
     (= (set c2-reader-diagnostic-ids) diagnostics)
     :semantic-errors-deferred?
     (true? (get-in artifact [:semantic-error-deferment-record :deferred?]))
     :lexical-token-stream?
     (every? true?
             (map lexical
                  [:ordered-token-ids-unique?
                   :token-raw-slices-exact?
                   :token-provenance-complete?
                   :no-token-contains-top-level-form?]))
     :nested-form-tree?
     (every? true?
             (map lexical
                  [:form-ids-unique?
                   :graph-valid?
                   :root-form-ids-resolve?
                   :form-raw-slices-exact?
                   :form-links-resolve?
                   :parent-spans-enclose-children?
                   :collection-delimiters-resolve?]))
     :representation-status :genuine-lexical-token-and-recursive-form-tree
     :status :partial}))

(defn c2-reader-validate!
  [source-path artifact]
  (let [proof (c2-reader-capability-proof artifact)]
    (doseq [[field id] [[:source-unit-hash-stable? "C2-HASH"]
                        [:token-and-form-spans-present? "C2-HASH"]
                        [:abbreviation-origins-present? "C2-ABBREV"]
                        [:literal-facts-present? "C2-STRING"]
                        [:trivia-retained? "C2-HASH"]
                        [:extension-policy-recorded? "C2-EXTENSION"]
                        [:incremental-hashes-stable? "C2-HASH"]
                        [:diagnostics-covered? "C2-HASH"]
                        [:lexical-token-stream? "C2-HASH"]
                        [:nested-form-tree? "C2-HASH"]]]
      (when-not (get proof field)
        (c2-reader-fail! id source-path
                         {:stage :read-source
                          :source-id (get-in artifact
                                             [:source-unit-record :source-id])
                          :source-span (or (get-in artifact
                                                   [:token-stream 0 :span])
                                           (source-span source-path 0))
                          :reader-options (get-in artifact
                                                  [:source-unit-record
                                                   :reader-options])}
                         {:missing-fields [field]}))))
  :complete)

(defn c2-reader-overrides-from-forms
  [forms]
  (let [ns-form (first forms)
        metadata-clause (when (and (seq? ns-form) (= 'ns (first ns-form)))
                          (first (filter #(and (seq? %)
                                               (= :metadata (first %)))
                                         (drop 2 ns-form))))
        metadata (second metadata-clause)]
    (get-in metadata [:compiler :c2-reader] {})))

(defn c2-reader-extension-invocations
  [form-tree]
  (mapv
   (fn [tag]
     (let [forms (filterv #(= tag (:tag %)) form-tree)]
       {:artifact :gravity/reader-extension-invocation
        :tag tag
        :handler ({'inst 'gravity.reader.standard/read-inst
                   'uuid 'gravity.reader.standard/read-uuid}
                  tag)
        :build-effects #{}
        :capabilities #{}
        :profiles #{:kernel :core :hosted :meta}
        :invocations (mapv #(select-keys % [:form-id :span :raw]) forms)
        :status (if (seq forms) :invoked :registered-not-invoked)}))
   (:registered-tags standard-reader-policy)))

(def ^:private sh03-reader-internal-product-authority (Object.))

(defn- sh03-reader-precomputed-products-payload-valid?
  [source-path source-text project-context products]
  (let [result (:sh03-reader-result products)
        raw-tokens (:token-stream result)
        raw-forms (:form-tree result)
        token-stream (:token-stream products)
        form-tree (:form-tree products)
        token-id-map
        (when (= (count raw-tokens) (count token-stream))
          (into {} (map vector (map :token-id raw-tokens)
                               (map :token-id token-stream))))
        form-id-map
        (when (= (count raw-forms) (count form-tree))
          (into {} (map vector (map :form-id raw-forms)
                               (map :form-id form-tree))))
        root-form-ids (mapv form-id-map (:top-level-form-ids result))
        forms-by-id (into {} (map (juxt :form-id identity) form-tree))
        parsed-records
        (mapv (fn [root-index form-id]
                (let [form (forms-by-id form-id)]
                  {:form (:value form)
                   :kind (:kind form)
                   :form-id form-id
                   :span (assoc (:span form) :form-index root-index)
                   :parent-form-id nil}))
              (range) root-form-ids)
        literal-records (c2-literal-records form-tree)
        deferred-records (c2-deferred-semantic-literals form-tree)
        extension-records (c2-reader-extension-invocations form-tree)
        source-map
        {:artifact :gravity/reader-source-map
         :token-spans (mapv #(select-keys % [:token-id :span]) token-stream)
         :form-spans
         (mapv #(select-keys % [:form-id :span :parent-form-id]) form-tree)}
        source-unit
        (c2-source-unit-record source-path source-text standard-reader-options
                               project-context)
        summary
        (when (and token-id-map form-id-map)
          (sh03-reader-adapter-summary
           result source-unit token-stream form-tree extension-records
           token-id-map form-id-map))
        descriptor (:sh02-reader-envelope-descriptor products)
        descriptor-summary
        (:value
         (some #(when (= :reader-product-identities (:name %)) %)
               (:semantic-projections descriptor)))]
    (and token-id-map
         form-id-map
         (= source-unit (:source-unit products))
         (= root-form-ids (:root-form-ids products))
         (= parsed-records (:parsed-records products))
         (= (mapv :form parsed-records) (:parsed-values products))
         (= literal-records (:literal-decoding-records products))
         (= deferred-records (:deferred-literal-records products))
         (= extension-records
            (:reader-extension-invocation-records products))
         (= source-map (:gravity-reader-source-map products))
         (= (:semantic-value-table-id summary)
            (:sh03-semantic-value-table-id products))
         (= summary (:sh03-reader-adapter-descriptor products))
         (= summary descriptor-summary))))

(defn- sh03-reader-precomputed-products-verify!
  [candidate source-path source-text project-context products]
  (when-not (identical? candidate sh03-reader-internal-product-authority)
    (c2-reader-fail!
     "C2-HASH" source-path
     {:stage :read-source
      :source-span (source-span source-path 0)
      :reader-options standard-reader-options}
     {:missing-fields [:internal-sh03-precomputed-product-authority]}))
  (let [expected-binding
        (dissoc (sh03-reader-current-binding! source-path) :plan)
        source-bytes
        (.getBytes source-text java.nio.charset.StandardCharsets/UTF_8)
        input-source-unit
        (sh03-reader-input-source-unit source-path source-bytes project-context)
        input-reader-policy
        (sh03-reader-input-policy standard-reader-options)
        raw-result (:sh03-reader-raw-result products)
        result (:sh03-reader-result products)
        report (:sh03-reader-verification-report products)
        descriptor (:sh02-reader-envelope-descriptor products)
        envelope (:sh02-reader-envelope products)
        _ (sh03-reader-result-preflight!
           source-path input-source-unit input-reader-policy raw-result)
        replayed (sh03-reader-resolve-digest-requests!
                  source-path raw-result source-bytes)
        replayed-result
        (update (:result replayed) :diagnostics
                #(mapv (partial sh03-reader-resolve-diagnostic-id source-path)
                       %))]
    (when-not
     (and (= :gravity/sh03-to-c2-reader-products-v2
             (:sh03-reader-adapter-contract products))
          (= expected-binding (:sh03-reader-plan-binding products))
          (= :gravity/sh03-reader-result (:artifact raw-result))
          (= :accepted (:status raw-result))
          (= :gravity/sh03-reader-result (:artifact result))
          (= :accepted (:status result))
          (= replayed-result result)
          (= :gravity/sh03-reader-verification-report (:artifact report))
          (= :accepted (:status report))
          (true? (:verified? report))
          (= p15-s23-sh02-stage-envelope-keys (set (keys envelope)))
          (= :accepted (:status envelope))
          (= :c2-reader (:stage envelope))
          (= :gravity/sh03-reader-products
             (get-in envelope [:sealed-artifact :artifact-kind]))
          (map? descriptor)
          (try
            (sh03-reader-precomputed-products-payload-valid?
             source-path source-text project-context products)
            (catch InterruptedException interrupted
              (.interrupt (Thread/currentThread))
              (throw interrupted))
            (catch Throwable _ false)))
      (c2-reader-fail!
       "C2-HASH" source-path
       {:stage :read-source
        :source-span (source-span source-path 0)
        :reader-options standard-reader-options}
       {:missing-fields [:authenticated-sh03-precomputed-products]}))
    (sh03-reader-verifier-preflight! source-path raw-result report)
    (p15-s23-stage2-sh02-descriptor-envelope-verify!
     envelope :c2-reader :gravity/sh03-reader-products descriptor source-path)
    products))

(defn compiler-c2-reader-source-artifact
  ([source-path source-text]
   (compiler-c2-reader-source-artifact
    source-path source-text (reader-project-context-for-source source-path)))
  ([source-path source-text project-context]
   (compiler-c2-reader-source-artifact
    source-path source-text project-context nil))
  ([source-path source-text project-context precomputed-products]
   (if precomputed-products
     (c2-reader-fail!
      "C2-HASH" source-path
      {:stage :read-source
       :source-span (source-span source-path 0)
       :reader-options standard-reader-options}
      {:missing-fields [:internal-sh03-precomputed-product-authority]})
     (compiler-c2-reader-source-artifact
      source-path source-text project-context nil
      sh03-reader-internal-product-authority)))
  ([source-path source-text project-context precomputed-products candidate]
   (try
    (let [reader-options standard-reader-options
          products
          (if precomputed-products
            (sh03-reader-precomputed-products-verify!
             candidate source-path source-text project-context
             precomputed-products)
            (c2-reader-products source-path source-text
                                reader-options project-context))
          source-unit (:source-unit products)
          token-stream (:token-stream products)
          form-tree (:form-tree products)
          top-level-form-ids (:root-form-ids products)
          records (:parsed-records products)
          forms (:parsed-values products)
          _ (validate-ns-syntax! source-path forms)
          module-context (reader-module-context forms)
          overrides (c2-reader-overrides-from-forms forms)
          _ (c2-reader-validate-overrides! source-path overrides source-unit
                                           token-stream)
          syntax-seeds (c2-syntax-seed-stream source-path products
                                              module-context)
          deferred-literals (or (:deferred-literal-records products)
                                (c2-deferred-semantic-literals form-tree))
          literal-records (or (:literal-decoding-records products)
                              (c2-literal-records form-tree))
          extension-invocations
          (or (:reader-extension-invocation-records products)
              (c2-reader-extension-invocations form-tree))
          diagnostics []
          lexical-validation (c2-lexical-product-validation
                              source-text token-stream form-tree
                              top-level-form-ids)
          lexical-token-stream?
          (every? true?
                  (map lexical-validation
                       [:ordered-token-ids-unique?
                        :token-raw-slices-exact?
                        :token-provenance-complete?
                        :no-token-contains-top-level-form?]))
          nested-form-tree?
          (every? true?
                  (map lexical-validation
                       [:form-ids-unique?
                        :graph-valid?
                        :root-form-ids-resolve?
                        :form-raw-slices-exact?
                        :form-links-resolve?
                        :parent-spans-enclose-children?
                        :collection-delimiters-resolve?]))
          incremental-hashes (c2-incremental-hashes
                              source-unit token-stream form-tree syntax-seeds
                              extension-invocations diagnostics)
          integrity-record (c2-reader-product-integrity-record
                            source-unit top-level-form-ids incremental-hashes
                            literal-records deferred-literals)
          artifact-base
          {:kind :gravity/stage0-c2-reader-document-artifact
           :task "P06-D081"
           :document-set ["C2"]
           :governing-document c2-reader-governing-document
           :pass {:name :c2-reader-document-coverage
                  :input :source-bytes
                  :output :reader-document-proof
                  :requires [:source-unit :reader-policy]
                  :preserves [:source-spans :raw-literal-facts
                              :reader-origin :trivia :diagnostics]
                  :emits [:source-unit-record :token-stream :form-tree
                          :syntax-seed-stream :reader-source-map
                          :literal-decoding-records
                          :reader-extension-invocation-records
                          :reader-diagnostics :incremental-reader-hash]
                  :rejects c2-reader-diagnostic-ids}
           :source-overrides overrides
           :module (assoc (dissoc module-context :namespace-clause-syntax)
                          :source-path source-path)
           :source-unit-record source-unit
           :gravity-reader-boundary
           {:slice :SH-03
            :owner :gravity-source
            :plan-binding (:sh03-reader-plan-binding products)
            :resolved-reader-result
            (select-keys (:sh03-reader-result products)
                         [:artifact :schema-version :status
                          :actual-path-provenance
                          :incremental-reader-hashes
                          :semantic-reader-template
                          :bounds :execution-boundary])
            :adapter-contract (:sh03-reader-adapter-contract products)
            :uncredited-source-models
            {:status :not-executed
             :entrypoints sh03-reader-uncredited-source-model-entrypoints
             :self-hosting-credit? false
             :seed-retirement-credit? false
             :release-credit? false}
            :semantic-value-table-id
            (:sh03-semantic-value-table-id products)
            :authenticated-envelope-descriptor
            (:sh02-reader-envelope-descriptor products)
            :authenticated-envelope (:sh02-reader-envelope products)
            :target-source-reread? false
            :clojure-adapter-residual? true
            :self-hosted? false}
           :representation-boundary
           {:token-stream :ordered-utf8-lexical-token-stream
            :form-tree :recursive-delimiter-linked-form-tree
            :lexical-token-stream? lexical-token-stream?
            :nested-form-tree? nested-form-tree?
            :remaining-reader-boundaries
            [:full-language-literal-surface
             :full-language-reader-abbreviation-surface
             :full-language-reader-extension-registry
             :host-and-seed-retirement]
            :sh03-bootstrap-subset-status :complete
            :status (if (and lexical-token-stream? nested-form-tree?)
                      :complete-for-slice
                      :failed)}
           :token-stream token-stream
           :form-tree form-tree
           :top-level-form-ids top-level-form-ids
           :parsed-semantic-values (:parsed-values products)
           :lexical-product-validation lexical-validation
           :syntax-seed-stream syntax-seeds
           :reader-source-map (mapv #(select-keys % [:syntax-id :form-id :span])
                                    syntax-seeds)
           :gravity-reader-source-map (:gravity-reader-source-map products)
           :literal-decoding-records literal-records
           :trivia-retention-records (c2-trivia-records token-stream)
           :reader-extension-policy
           {:artifact :gravity/reader-extension-policy
            :extensions
            [{:tag 'inst
              :handler 'gravity.reader.standard/read-inst
              :build-effects #{}
              :capabilities #{}
              :profiles #{:kernel :core :hosted :meta}
              :output :syntax-seed}
             {:tag 'uuid
              :handler 'gravity.reader.standard/read-uuid
              :build-effects #{}
              :capabilities #{}
              :profiles #{:kernel :core :hosted :meta}
              :output :syntax-seed}]
            :status :registered}
           :reader-extension-invocation-records extension-invocations
           :semantic-error-deferment-record
           {:artifact :gravity/semantic-error-deferment
            :forms-retained [:unknown-symbol :profile-illegal-form
                             :zero-denominator-ratio
                             :host-independent-decimal-range]
            :deferred-literal-records deferred-literals
            :semantic-analysis-in-reader? false
            :module-parser-invoked? false
            :deferred? true
            :owner-phases [:namespace-analysis :type-check :profile-validate
                           :numeric-mode-validation]}
           :reader-diagnostics diagnostics
           :incremental-reader-hashes incremental-hashes
           :reader-product-integrity integrity-record
           :rejected-design-coverage c2-reader-rejected-designs
           :diagnostics []}
          _ (c2-reader-validate! source-path artifact-base)
          capability-proof (c2-reader-capability-proof artifact-base)
          conformance {:documents ["C2"]
                       :task "P06-D081"
                       :required-diagnostic-ids c2-reader-diagnostic-ids
                       :source-unit-status :complete
                       :token-stream-status :complete-for-slice
                       :form-tree-status :complete-for-slice
                       :span-status :exact-utf8-byte-and-line-column
                       :abbreviation-status :complete-bootstrap-subset
                       :literal-status :complete-bootstrap-subset
                       :trivia-status :reader-option-sensitive
                       :extension-status :complete-bootstrap-subset
                       :incremental-hash-status :complete-for-slice
                       :diagnostic-status :complete-bootstrap-subset
                       :semantic-deferment-status :complete-for-slice
                       :status :partial}
          artifact (assoc artifact-base
                          :capability-based-proof capability-proof
                          :c2-reader-results conformance)]
      (assoc artifact :artifact-id (c2-reader-artifact-id artifact)))
     (catch clojure.lang.ExceptionInfo ex
       (c2-reader-remap-exception! source-path ex)))))

(def sh03-reader-maximum-source-bytes 1048576)

(defn sh03-reader-read-target-source-bytes!
  [path]
  (let [nio-path (.toPath (java.io.File. path))
        nofollow (into-array java.nio.file.LinkOption
                             [java.nio.file.LinkOption/NOFOLLOW_LINKS])
        attributes
        (try
          (java.nio.file.Files/readAttributes
           nio-path java.nio.file.attribute.BasicFileAttributes nofollow)
          (catch Exception error
            (c2-reader-fail!
             "C2-ENCODING" path
             {:stage :read-source
              :source-span (source-span path 0)
              :reader-options standard-reader-options}
             {:facts {:failure-kind :source-file-attributes
                      :contained-host-error (.getName (class error))}
              :cause-message (.getMessage error)})))]
    (when-not (and attributes
                   (.isRegularFile attributes)
                   (<= (.size attributes)
                       sh03-reader-maximum-source-bytes))
      (c2-reader-fail!
       "C2-HASH" path
       {:stage :read-source
        :source-span (source-span path 0)
        :reader-options standard-reader-options}
       {:missing-fields [:bounded-regular-source-file]
        :facts {:regular-file? (boolean (and attributes
                                             (.isRegularFile attributes)))
                :observed-source-byte-count
                (when attributes (.size attributes))
                :maximum-source-bytes sh03-reader-maximum-source-bytes}}))
    (let [limit (inc sh03-reader-maximum-source-bytes)
          buffer (byte-array limit)
          observed
          (try
            (with-open [input
                        (java.nio.file.Files/newInputStream
                         nio-path
                         (into-array java.nio.file.OpenOption
                                     [java.nio.file.LinkOption/NOFOLLOW_LINKS]))]
              (loop [offset 0]
                (if (= offset limit)
                  offset
                  (let [count (.read input buffer offset (- limit offset))]
                    (if (= -1 count)
                      offset
                      (recur (+ offset count)))))))
            (catch Exception error
              (c2-reader-fail!
               "C2-ENCODING" path
               {:stage :read-source
                :source-span (source-span path 0)
                :reader-options standard-reader-options}
               {:facts {:failure-kind :bounded-source-byte-read
                        :contained-host-error (.getName (class error))}
                :cause-message (.getMessage error)})))]
      (when (> observed sh03-reader-maximum-source-bytes)
        (c2-reader-fail!
         "C2-HASH" path
         {:stage :read-source
          :source-span (source-span path 0)
          :reader-options standard-reader-options}
         {:missing-fields [:bounded-source-byte-snapshot]
          :facts {:observed-source-byte-count observed
                  :maximum-source-bytes sh03-reader-maximum-source-bytes}}))
      (java.util.Arrays/copyOf buffer observed))))

(defn compiler-c2-reader-file-artifact
  [path]
  (let [source-bytes (sh03-reader-read-target-source-bytes! path)
        project-context (reader-project-context-for-source path)
        resolved (sh03-reader-resolved-result!
                  path source-bytes project-context standard-reader-options)
        result (:result resolved)
        _ (sh03-reader-raise-rejection!
           path source-bytes standard-reader-options project-context result)
        source-text (sh03-reader-strict-source-text!
                     path path source-bytes)
        products (sh03-reader-adapt-products!
                  path source-text source-bytes standard-reader-options
                  project-context resolved)]
    (compiler-c2-reader-source-artifact
     path source-text project-context products
     sh03-reader-internal-product-authority)))

(def c3-syntax-diagnostic-ids
  ["C3-SHAPE"
   "C3-ID"
   "C3-SPAN"
   "C3-ORIGIN"
   "C3-HYGIENE"
   "C3-CAPTURE"
   "C3-METADATA"
   "C3-FACT-STALE"
   "C3-SERIALIZE"])

(def c3-syntax-governing-document
  "docs/phase-06-compiler-architecture/082-c3-syntax-object-model.md")

(def c3-syntax-rejected-designs
  [{:diagnostic "C3-SHAPE"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c3-shape.gravity"
    :rejected-design :raw-list-macro-api}
   {:diagnostic "C3-ID"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c3-id.gravity"
    :rejected-design :unstable-syntax-identity}
   {:diagnostic "C3-SPAN"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c3-span.gravity"
    :rejected-design :syntax-without-resolvable-span}
   {:diagnostic "C3-ORIGIN"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c3-origin.gravity"
    :rejected-design :syntax-without-source-or-generated-origin}
   {:diagnostic "C3-HYGIENE"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c3-hygiene.gravity"
    :rejected-design :hidden-hygiene-state}
   {:diagnostic "C3-CAPTURE"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c3-capture.gravity"
    :rejected-design :undeclared-or-accidental-capture}
   {:diagnostic "C3-METADATA"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c3-metadata.gravity"
    :rejected-design :metadata-loss-or-invalid-shape}
   {:diagnostic "C3-FACT-STALE"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c3-fact-stale.gravity"
    :rejected-design :stale-semantic-fact-use}
   {:diagnostic "C3-SERIALIZE"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c3-serialize.gravity"
    :rejected-design :non-round-tripping-syntax-artifact}])

(def c3-syntax-override-diagnostics
  {:shape "C3-SHAPE"
   :id "C3-ID"
   :span "C3-SPAN"
   :origin "C3-ORIGIN"
   :hygiene "C3-HYGIENE"
   :capture "C3-CAPTURE"
   :metadata "C3-METADATA"
   :fact-stale "C3-FACT-STALE"
   :serialize "C3-SERIALIZE"})

(defn c3-syntax-source-overrides
  [module]
  (get-in module [:metadata :compiler :c3-syntax] {}))

(defn c3-syntax-overrides-from-forms
  [forms]
  (let [ns-form (first forms)
        metadata-clause
        (when (and (seq? ns-form) (= 'ns (first ns-form)))
          (first (filter #(and (seq? %)
                               (= :metadata (first %)))
                         (drop 2 ns-form))))]
    (get-in (second metadata-clause) [:compiler :c3-syntax] {})))

(defn c3-syntax-message
  [id]
  (case id
    "C3-SHAPE" "syntax object fields are malformed or incomplete"
    "C3-ID" "syntax object identity is unstable or inconsistent"
    "C3-SPAN" "syntax object span is not resolvable"
    "C3-ORIGIN" "syntax object origin chain is missing or broken"
    "C3-HYGIENE" "syntax object hygiene context is malformed or hidden"
    "C3-CAPTURE" "syntax object captures a binding without explicit capture"
    "C3-METADATA" "syntax object metadata is invalid or lost"
    "C3-FACT-STALE" "syntax object facts are stale after transformation"
    "C3-SERIALIZE" "syntax object artifact does not round-trip"
    "syntax object model failed"))

(defn c3-syntax-fail!
  [id source-path subject extra]
  (fail! id
         (c3-syntax-message id)
         (merge {:source-span (or (:source-span subject)
                                  (:span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :c3-syntax-object
                 :stage :syntax-object-model
                 :document-id "C3"
                 :expected-document c3-syntax-governing-document
                 :syntax-id (or (:syntax-id subject)
                                (:syntax/id subject))
                 :form-kind (:form-kind subject)
                 :phase (:phase subject)
                 :producer (:producer subject)
                 :origin-chain (:origin subject)
                 :hygiene-summary (:hygiene subject)
                 :remediation "Rebuild syntax objects with stable ids, spans, origin chains, exposed hygiene, versioned facts, and round-tripping serialization."}
                extra)))

(defn c3-syntax-validate-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get c3-syntax-override-diagnostics fail-kind)]
      (c3-syntax-fail! id source-path
                       {:source-span (source-span source-path 0)
                        :producer :fixture-override
                        :form-kind fail-kind
                        :hygiene {:marks [] :captures []}}
                       {:missing-fields [fail-kind]}))))

(defn c3-origin-chain
  [seed source-unit]
  (let [source-entry {:kind :source
                      :producer {:kind :reader
                                 :name 'gravity.stage0/reader
                                 :version "stage0"}
                      :source-id (get source-unit :source-id)
                      :span (:span seed)
                      :input-syntax-ids []
                      :reason :source-read
                      :build-effects []}
        generated (mapv (fn [origin]
                          {:kind :generated
                           :producer {:kind :reader
                                      :name 'gravity.stage0/reader-abbreviation
                                      :version "stage0"}
                           :inputs [(:syntax-id seed)]
                           :generated-span (str "generated:reader:"
                                                (name (or (:reader-abbreviation origin)
                                                          :abbreviation))
                                                ":"
                                                (get-in seed [:span :form-index]))
                           :source-span (:from origin)
                           :reason (:reader-abbreviation origin)
                           :build-effects []})
                        (:generated-origin seed))]
    (vec (cons source-entry generated))))

(defn c3-c2-reader-integrity-report
  [c2-artifact]
  (try
    (let [source-unit (:source-unit-record c2-artifact)
          token-stream (:token-stream c2-artifact)
          form-tree (:form-tree c2-artifact)
          top-level-form-ids (:top-level-form-ids c2-artifact)
          syntax-seeds (:syntax-seed-stream c2-artifact)
          extension-invocations
          (or (:reader-extension-invocation-records c2-artifact) [])
          diagnostics (or (:reader-diagnostics c2-artifact) [])
          raw-source-available? (every? #(string? (:raw %)) token-stream)
          source-text (when raw-source-available?
                        (apply str (map :raw token-stream)))
          lexical (when source-text
                    (c2-lexical-product-validation
                     source-text token-stream form-tree top-level-form-ids))
          graph-valid? (true? (:graph-valid? lexical))
          depth-valid? (and (integer? (:max-form-depth lexical))
                            (<= (:max-form-depth lexical)
                                max-reader-form-graph-depth))
          recomputed-hashes
          (when (and graph-valid? depth-valid?)
            (c2-incremental-hashes source-unit token-stream form-tree
                                   syntax-seeds extension-invocations
                                   diagnostics))
          literal-records (c2-literal-records form-tree)
          deferred-records (c2-deferred-semantic-literals form-tree)
          forms-by-id (into {} (map (juxt :form-id identity) form-tree))
          canonical-form-ids
          (loop [pending (vec (reverse top-level-form-ids))
                 ordered []
                 seen #{}]
            (if-let [form-id (peek pending)]
              (let [remaining (pop pending)
                    form (forms-by-id form-id)]
                (if (or (contains? seen form-id) (nil? form))
                  (recur remaining ordered seen)
                  (recur (into remaining (reverse (:children form)))
                         (conj ordered form-id)
                         (conj seen form-id))))
              ordered))
          deferred-descriptors-valid?
          (every?
           (fn [form]
             (let [ratio-form
                   (cond
                     (= :ratio (:kind form)) form
                     (= :metadata-wrapper (:kind form))
                     (let [ratios (filterv #(= :ratio (:kind %))
                                           (keep forms-by-id
                                                 (:children form)))]
                       (when (= 1 (count ratios)) (first ratios)))
                     :else nil)]
               (if (and ratio-form
                        (= :gravity/deferred-ratio-literal
                           (get-in ratio-form [:value :artifact])))
                 (let [expected
                       (c3-deferred-ratio-descriptor-from-raw
                        (:raw ratio-form))]
                   (and expected
                        (= expected (:value ratio-form))
                        (if (= :metadata-wrapper (:kind form))
                          (= expected (:value form) (:expanded-form form))
                          true)))
                 true)))
           form-tree)
          expected-integrity
          (when recomputed-hashes
            (c2-reader-product-integrity-record
             source-unit top-level-form-ids recomputed-hashes literal-records
             deferred-records))
          source-id (:source-id source-unit)
          source-path (:path source-unit)
          expected-source-map
          (mapv #(select-keys % [:syntax-id :form-id :span]) syntax-seeds)
          expected-parsed-values
          (mapv #(get-in forms-by-id [% :value]) top-level-form-ids)
          parsed-semantic-values-valid?
          (and (= expected-parsed-values
                  (:parsed-semantic-values c2-artifact))
               (= expected-parsed-values (mapv :form syntax-seeds))
               (= (count top-level-form-ids)
                  (count (:parsed-semantic-values c2-artifact))
                  (count syntax-seeds)))
          stable-token-ids?
          (= (mapv :token-id token-stream)
             (mapv #(keyword (str "tok-" %)) (range (count token-stream))))
          stable-form-ids?
          (and (= (mapv :form-id form-tree) canonical-form-ids)
               (= canonical-form-ids
                  (mapv #(keyword (str "form-" %))
                        (range (count form-tree)))))
          stable-seed-ids?
          (and (= (mapv :syntax-id syntax-seeds)
                  (mapv #(str "stage0-syntax-" %)
                        (range (count syntax-seeds))))
               (= (mapv :form-id syntax-seeds)
                  (vec top-level-form-ids))
               (= (mapv #(get-in % [:span :form-index]) syntax-seeds)
                  (vec (range (count syntax-seeds)))))
          stable-literal-ids?
          (= (mapv :literal-id (:literal-decoding-records c2-artifact))
             (mapv #(keyword (str "lit-" %))
                   (range (count (:literal-decoding-records c2-artifact)))))
          source-id-valid?
          (= source-id (reader-canonical-hash (:identity-inputs source-unit)))
          source-bytes-valid?
          (and source-text
               (= (:bytes-hash source-unit)
                  (str "sha256:" (sha256-hex source-text))))
          product-provenance-valid?
          (and
           (every? #(and (= source-id (:source-id %))
                         (= source-id (get-in % [:span :file]))
                         (= source-path (:source-path %))
                         (= source-path (get-in % [:span :source])))
                   token-stream)
           (every? #(and (= source-id (:source-id %))
                         (= source-id (get-in % [:span :file]))
                         (= source-path (:source-path %))
                         (= source-path (get-in % [:span :source]))
                         (= source-id (get-in % [:origin :source-id]))
                         (= source-path (get-in % [:origin :source-path])))
                   form-tree)
           (every? #(and (:form-id %)
                         (= source-id (get-in % [:span :file]))
                         (= source-path (get-in % [:span :source])))
                   syntax-seeds))
          checks
          {:artifact-kind-valid?
           (= :gravity/stage0-c2-reader-document-artifact
              (:kind c2-artifact))
           :artifact-id-valid?
           (= (:artifact-id c2-artifact)
              (c2-reader-artifact-id (dissoc c2-artifact :artifact-id)))
           :stable-token-ids? stable-token-ids?
           :stable-form-ids? stable-form-ids?
           :stable-seed-ids? stable-seed-ids?
           :stable-literal-ids? stable-literal-ids?
           :source-id-valid? source-id-valid?
           :source-bytes-valid? (boolean source-bytes-valid?)
           :lexical-graph-valid? graph-valid?
           :reader-depth-valid? depth-valid?
           :product-provenance-valid? product-provenance-valid?
           :reader-source-map-valid?
           (= expected-source-map (:reader-source-map c2-artifact))
           :parsed-semantic-values-valid?
           parsed-semantic-values-valid?
           :incremental-hashes-valid?
           (= recomputed-hashes (:incremental-reader-hashes c2-artifact))
           :literal-records-valid?
           (= literal-records (:literal-decoding-records c2-artifact))
           :deferment-records-valid?
           (= deferred-records
              (get-in c2-artifact
                      [:semantic-error-deferment-record
                       :deferred-literal-records]))
           :deferment-policy-valid?
           (and (true? (get-in c2-artifact
                               [:semantic-error-deferment-record :deferred?]))
                (false? (get-in c2-artifact
                                [:semantic-error-deferment-record
                                 :semantic-analysis-in-reader?])))
           :deferred-descriptors-valid? deferred-descriptors-valid?
           :integrity-record-valid?
           (= expected-integrity (:reader-product-integrity c2-artifact))}]
      (assoc checks
             :authentic? (every? true? (vals checks))
             :failures (vec (keep (fn [[field passed?]]
                                    (when-not passed? field))
                                  checks))))
    (catch StackOverflowError _
      {:authentic? false
       :failures [:reader-depth-stack-overflow-contained?]})
    (catch Exception ex
      {:authentic? false
       :failures [:reader-product-validation-exception]
       :cause-class (.getName (class ex))})))

(defn c3-validate-c2-reader-artifact!
  [source-path c2-artifact]
  (let [base-report (c3-c2-reader-integrity-report c2-artifact)
        source-path-binding-valid?
        (= source-path (get-in c2-artifact [:source-unit-record :path]))
        report (-> base-report
                   (assoc :source-path-binding-valid?
                          source-path-binding-valid?)
                   (update :failures
                           #(cond-> (vec %)
                              (not source-path-binding-valid?)
                              (conj :source-path-binding-valid?)))
                   (assoc :authentic?
                          (and (:authentic? base-report)
                               source-path-binding-valid?)))]
    (when-not (:authentic? report)
      (c3-syntax-fail!
       "C3-FACT-STALE" source-path
       {:source-span (or (get-in c2-artifact [:form-tree 0 :span])
                         (source-span source-path 0))
        :producer :c2-reader-artifact
        :form-kind (get-in c2-artifact [:form-tree 0 :kind])}
       {:missing-fields (:failures report)
        :facts {:reader-product-integrity report}}))
    report))

(defn c3-deferred-ratio-descriptor-from-raw
  [raw]
  (when-let [[_ numerator-spelling denominator-spelling]
             (and (string? raw)
                  (re-matches #"([+-]?[0-9]+)/([+-]?[0-9]+)" raw))]
    (try
      (let [numerator (bigint numerator-spelling)
            denominator (bigint denominator-spelling)]
        (when (zero? denominator)
          {:artifact :gravity/deferred-ratio-literal
           :kind :ratio
           :raw raw
           :numerator-spelling numerator-spelling
           :denominator-spelling denominator-spelling
           :numerator numerator
           :denominator denominator
           :semantic-validation :deferred
           :reason :zero-denominator}))
      (catch NumberFormatException _ nil))))

(defn c3-ratio-descriptor-from-raw
  [raw]
  (when-let [[_ numerator-spelling denominator-spelling]
             (and (string? raw)
                  (re-matches #"([+-]?[0-9]+)/([+-]?[0-9]+)" raw))]
    (try
      (let [numerator (bigint numerator-spelling)
            denominator (bigint denominator-spelling)]
        (if (zero? denominator)
          {:artifact :gravity/deferred-ratio-literal
           :kind :ratio
           :raw raw
           :numerator-spelling numerator-spelling
           :denominator-spelling denominator-spelling
           :numerator numerator
           :denominator denominator
           :semantic-validation :deferred
           :reason :zero-denominator}
          {:artifact :gravity/ratio-literal
           :kind :ratio
           :raw raw
           :numerator-spelling numerator-spelling
           :denominator-spelling denominator-spelling
           :numerator numerator
           :denominator denominator
           :semantic-validation :accepted}))
      (catch NumberFormatException _ nil))))

(defn c3-lossless-literal-descriptor
  [seed form-record c2-artifact integrity-report]
  (let [integrity-report (or integrity-report
                             (c3-c2-reader-integrity-report c2-artifact))
        forms-by-id (into {} (map (juxt :form-id identity)
                                  (:form-tree c2-artifact)))
        tokens-by-id (into {} (map (juxt :token-id identity)
                                   (:token-stream c2-artifact)))
        root-form-id (:form-id form-record)
        ratio-form
        (case (:kind form-record)
          :ratio form-record
          :metadata-wrapper
          (let [ratio-children
                (filterv #(= :ratio (:kind %))
                         (keep forms-by-id (:children form-record)))]
            (when (= 1 (count ratio-children)) (first ratio-children)))
          nil)
        ratio-token (when ratio-form
                      (tokens-by-id (:open-token ratio-form)))
        descriptor (when ratio-token
                     (c3-ratio-descriptor-from-raw (:raw ratio-token)))
        literal-records
        (filterv #(= (:form-id ratio-form) (:form-id %))
                 (:literal-decoding-records c2-artifact))
        deferred-records
        (filterv #(= (:form-id ratio-form) (:form-id %))
                 (get-in c2-artifact
                         [:semantic-error-deferment-record
                          :deferred-literal-records]))
        wrapper? (= :metadata-wrapper (:kind form-record))
        expected-seed-span (when form-record
                             (assoc (:span form-record)
                                    :form-index
                                    (get-in seed [:span :form-index])))]
    (when
     (and (:authentic? integrity-report)
          descriptor ratio-form ratio-token
          (= root-form-id (:form-id seed))
          (if (= :deferred (:semantic-validation descriptor))
            (and (= descriptor (:form seed))
                 (= descriptor (:value ratio-form) (:decoded ratio-token)))
            (= (:form seed) (:value ratio-form) (:decoded ratio-token)))
          (= :ratio (:kind ratio-form) (:kind ratio-token))
          (= (:open-token ratio-form) (:close-token ratio-form)
             (:token-id ratio-token))
          (= (:raw ratio-form) (:raw ratio-token) (:lexeme ratio-token)
             (:raw descriptor))
          (= (:span ratio-form) (:span ratio-token))
          (= 1 (count literal-records))
          (= (if (= :deferred (:semantic-validation descriptor))
               descriptor
               (:form seed))
             (:decoded (first literal-records)))
          (= (:raw descriptor) (:raw (first literal-records)))
          (= (:span ratio-form) (:span (first literal-records)))
          (= {:numerator-spelling (:numerator-spelling descriptor)
              :denominator-spelling (:denominator-spelling descriptor)
              :exact? true}
             (:facts (first literal-records)))
          (if (= :deferred (:semantic-validation descriptor))
            (and (= 1 (count deferred-records))
                 (= descriptor (:value (first deferred-records)))
                 (= (:raw descriptor) (:raw (first deferred-records)))
                 (= (:span ratio-form) (:span (first deferred-records))))
            (and (empty? deferred-records)
                 (= (:form seed) (:decoded (first literal-records))
                    (:value ratio-form) (:decoded ratio-token))))
          (= expected-seed-span (:span seed))
          (= (:raw form-record) (get-in seed [:reader-origin :raw-excerpt]))
          (= (:kind form-record)
             (get-in seed [:reader-origin :raw-form-kind]))
          (if wrapper?
            (and (= :metadata (:abbrev form-record)
                    (get-in seed [:reader-origin :abbreviation]))
                 (= (if (= :deferred (:semantic-validation descriptor))
                      descriptor
                      (:form seed))
                    (:value form-record)
                    (:expanded-form form-record)
                    (get-in seed [:generated-origin 0 :expanded-form]))
                 (= :metadata
                    (get-in seed [:generated-origin 0
                                  :reader-abbreviation]))
                 (= (:surface-span form-record)
                    (get-in seed [:generated-origin 0 :from]))
                 (= (:form-id ratio-form)
                    (get-in form-record
                            [:generated-origin 0 :child-form-id])))
            (and (= (if (= :deferred (:semantic-validation descriptor))
                      descriptor
                      (:form seed))
                    (:value form-record))
                 (nil? (:abbrev form-record))
                 (empty? (:generated-origin seed)))))
     descriptor)))

(defn c3-tagged-literal-descriptor
  [seed form-record c2-artifact integrity-report]
  (when (= :tagged-literal (:kind form-record))
    (let [integrity-report
          (or integrity-report (c3-c2-reader-integrity-report c2-artifact))
          forms-by-id
          (into {} (map (juxt :form-id identity) (:form-tree c2-artifact)))
          payload-record (get forms-by-id (first (:children form-record)))
          literal-record
          (first
           (filter #(= (:form-id form-record) (:form-id %))
                   (:literal-decoding-records c2-artifact)))
          tag (:tag form-record)]
      (when (and (:authentic? integrity-report)
                 (= (:form-id seed) (:form-id form-record))
                 (= 1 (count (:children form-record)))
                 (= :string (:kind payload-record))
                 (= tag (get-in literal-record [:facts :tag]))
                 (= (:raw form-record) (:raw literal-record))
                 (= (:span form-record) (:span literal-record)))
        {:artifact :gravity/tagged-literal-descriptor
         :kind :tagged-literal
         :tag tag
         :raw (:raw form-record)
         :payload (:value payload-record)
         :semantic-validation :accepted}))))

(defn c3-source-form-kind
  [seed form-record c2-artifact integrity-report]
  (if (or (c3-lossless-literal-descriptor seed form-record c2-artifact
                                          integrity-report)
          (c3-tagged-literal-descriptor seed form-record c2-artifact
                                        integrity-report))
    (:kind form-record)
    (form-kind (:form seed))))

(defn c3-source-facts
  [seed form-record c2-artifact integrity-report]
  (if-let [descriptor
           (or (c3-lossless-literal-descriptor
                seed form-record c2-artifact integrity-report)
               (c3-tagged-literal-descriptor
                seed form-record c2-artifact integrity-report))]
    {:reader-literal-kind (:kind descriptor)
     :reader-literal-descriptor descriptor
     :reader-product-integrity-hash
     (get-in c2-artifact [:reader-product-integrity :integrity-hash])
     :reader-source-id (get-in c2-artifact [:source-unit-record :source-id])
     :reader-form-id (:form-id form-record)
     :reader-seed-id (:syntax-id seed)
     :reader-container-kind
     (when (= :metadata-wrapper (:kind form-record)) :metadata-wrapper)
     :reader-literal-facts
     (select-keys descriptor
                  [:raw :numerator-spelling :denominator-spelling
                   :numerator :denominator :tag :payload
                   :semantic-validation :reason])}
    {}))

(defn c3-path-neutral-origin
  [origin]
  (cond-> origin
    (contains? origin :span) (update :span c2-path-neutral-span)
    (contains? origin :source-span) (update :source-span c2-path-neutral-span)
    (contains? origin :from) (update :from c2-path-neutral-span)))

(defn c3-identity-input
  [seed origin namespace-context hygiene-context source-form-kind]
  {:form-kind source-form-kind
   :form (pr-str (:form seed))
   :span (c2-path-neutral-span (:span seed))
   :origin (mapv c3-path-neutral-origin origin)
   :namespace namespace-context
   :phase (:phase seed)
   :profile (:profile seed)
   :metadata (:metadata seed)
   :hygiene hygiene-context
   :version 1})

(defn c3-stable-syntax-id
  [identity-input]
  (str "sha256:" (sha256-hex (pr-str identity-input))))

(defn c3-syntax-object
  [seed form-record token-record source-unit c2-artifact integrity-report]
  (let [namespace-context {:current (:namespace seed)
                           :aliases {}
                           :imports []}
        hygiene-context {:marks []
                         :lexical-scopes []
                         :renames {}
                         :captures []
                         :introduced-identifiers []
                         :macro-definition-namespace nil
                         :macro-call-site-namespace (:namespace seed)}
        origin (c3-origin-chain seed source-unit)
        source-form-kind (c3-source-form-kind seed form-record c2-artifact
                                              integrity-report)
        identity-input (c3-identity-input seed origin namespace-context
                                          hygiene-context source-form-kind)
        syntax-id (c3-stable-syntax-id identity-input)]
    {:artifact :gravity/syntax-object
     :syntax/id syntax-id
     :identity {:algorithm :sha256
                :semantic-fields [:form-kind :form :span :origin
                                  :namespace :phase :profile :metadata
                                  :hygiene :version]
                :input-hash (str "sha256:" (sha256-hex (pr-str identity-input)))}
     :form {:kind source-form-kind
            :value (:form seed)
            :raw (get-in seed [:reader-origin :raw-excerpt])}
     :span {:primary (:span seed)
            :all [(:span seed)]}
     :source {:source-id (:source-id source-unit)
              :form-id (:form-id form-record)
              :token-range [(:open-token form-record)
                            (:close-token form-record)]
              :token-id (:token-id token-record)}
     :namespace namespace-context
     :phase (:phase seed)
     :profile (:profile seed)
     :metadata (:metadata seed)
     :hygiene hygiene-context
     :origin origin
     :facts (c3-source-facts seed form-record c2-artifact integrity-report)
     :version 1
     :prior-syntax-ids []
     :immutable? true}))

(defn c3-generated-syntax-object
  [base-object]
  (let [origin [{:kind :generated
                 :producer {:kind :macro
                            :name 'compiler.c3/with-capture-demo
                            :version "stage0"}
                 :inputs [(:syntax/id base-object)]
                 :generated-span "generated:compiler.c3/with-capture-demo:1"
                 :reason :generated-syntax-conformance
                 :build-effects []}]
        hygiene-context {:marks [:c3/generated-mark]
                         :lexical-scopes [:caller-scope :introduced-scope]
                         :renames {'tmp__auto__ 'tmp__c3__1}
                         :captures [{:identifier 'captured-binding
                                     :macro-api 'gravity.syntax/capture
                                     :call-site-namespace (get-in base-object
                                                                  [:namespace :current])
                                     :intentional? true
                                     :authority-bearing? false}]
                         :introduced-identifiers ['tmp__c3__1]
                         :macro-definition-namespace 'compiler.c3
                         :macro-call-site-namespace (get-in base-object
                                                            [:namespace :current])}
        namespace-context (:namespace base-object)
        identity-input {:form-kind :generated-form
                        :form "(do tmp__c3__1)"
                        :span "generated:compiler.c3/with-capture-demo:1"
                        :origin origin
                        :namespace namespace-context
                        :phase :macro-expanded
                        :profile (:profile base-object)
                        :metadata {:generated true}
                        :hygiene hygiene-context
                        :version 1}
        syntax-id (c3-stable-syntax-id identity-input)]
    {:artifact :gravity/syntax-object
     :syntax/id syntax-id
     :identity {:algorithm :sha256
                :semantic-fields [:form-kind :form :span :origin
                                  :namespace :phase :profile :metadata
                                  :hygiene :version]
                :input-hash (str "sha256:" (sha256-hex (pr-str identity-input)))}
     :form {:kind :generated-form
            :value '(do tmp__c3__1)
            :raw "(do tmp__c3__1)"}
     :span {:primary "generated:compiler.c3/with-capture-demo:1"
            :all ["generated:compiler.c3/with-capture-demo:1"
                  (get-in base-object [:span :primary])]}
     :source {:source-id (get-in base-object [:source :source-id])
              :form-id :generated-form-0
              :token-range []
              :token-id nil}
     :namespace namespace-context
     :phase :macro-expanded
     :profile (:profile base-object)
     :metadata {:generated true
                :source-metadata (:metadata base-object)}
     :hygiene hygiene-context
     :origin origin
     :facts {}
     :version 1
     :prior-syntax-ids [(:syntax/id base-object)]
     :immutable? true}))

(def c3-required-form-kinds
  [:list :vector :map :set :symbol :keyword :string :character :integer
   :ratio :decimal :boolean :nil :tagged-literal :metadata-wrapper
   :abbreviation-expansion :generated-form])

(defn c3-syntax-schema
  []
  {:artifact :gravity/syntax-object-schema
   :required-fields [:artifact :syntax/id :form :span :source :namespace
                     :phase :profile :metadata :hygiene :origin :facts
                     :reader-binding :reader-source-revision :ownership
                     :version :prior-syntax-ids :immutable?]
   :form-kinds c3-required-form-kinds
   :identity :content-derived
   :mutation :immutable
   :fact-policy :versioned-and-invalidated})

(defn c3-hygiene-context-map
  [syntax-stream]
  {:artifact :gravity/hygiene-context-map
   :contexts
   (mapv (fn [syntax]
           {:syntax-id (:syntax/id syntax)
            :marks (get-in syntax [:hygiene :marks])
            :lexical-scopes (get-in syntax [:hygiene :lexical-scopes])
            :renames (get-in syntax [:hygiene :renames])
            :captures (get-in syntax [:hygiene :captures])
            :introduced-identifiers (get-in syntax
                                             [:hygiene :introduced-identifiers])
            :macro-definition-namespace
            (get-in syntax [:hygiene :macro-definition-namespace])
            :macro-call-site-namespace
            (get-in syntax [:hygiene :macro-call-site-namespace])})
         syntax-stream)
   :status :complete})

(defn c3-origin-chain-graph
  [syntax-stream]
  {:artifact :gravity/syntax-origin-chain-graph
   :nodes (mapv (fn [syntax]
                  {:syntax-id (:syntax/id syntax)
                   :origin (:origin syntax)
                   :prior-syntax-ids (:prior-syntax-ids syntax)})
                syntax-stream)
   :status :complete})

(defn c3-metadata-ledger
  [syntax-stream]
  (let [source-metadata (vec (keep (fn [syntax]
                                     (when (and (not= :generated-form
                                                      (get-in syntax
                                                              [:form :kind]))
                                                (seq (:metadata syntax)))
                                       {:syntax-id (:syntax/id syntax)
                                        :action :preserved
                                        :metadata (:metadata syntax)}))
                                   syntax-stream))
        generated (first (filter #(= :generated-form (get-in % [:form :kind]))
                                 syntax-stream))]
    {:artifact :gravity/syntax-metadata-ledger
     :source-metadata source-metadata
     :explicit-changes
     (if generated
       [{:syntax-id (:syntax/id generated)
         :action :explicit-change
         :producer 'compiler.c3/with-capture-demo
         :metadata (:metadata generated)}]
       [])
     :status :complete}))

(defn c3-fact-ledger
  [syntax-stream]
  (let [target (first syntax-stream)
        generated (first (filter #(= :generated-form (get-in % [:form :kind]))
                                 syntax-stream))]
    {:artifact :gravity/syntax-fact-ledger
     :attached [{:syntax-id (:syntax/id target)
                 :fact :declared-profile
                 :value (:profile target)
                 :producer :syntax-object-model
                 :version 1
                 :invalidation-conditions [:macro-expansion
                                           :metadata-change
                                           :namespace-change]}]
     :invalidated [{:syntax-id (:syntax/id target)
                    :successor-syntax-id (:syntax/id generated)
                    :fact :declared-profile
                    :stale-version 1
                    :new-version 2
                    :reason :syntax-transformation
                    :replacement-fact :declared-profile}]
     :status :complete}))

(defn c3-generated-syntax-report
  [syntax-stream]
  {:artifact :gravity/generated-syntax-report
   :generated
   (mapv (fn [syntax]
           {:syntax-id (:syntax/id syntax)
            :producer (get-in syntax [:origin 0 :producer])
            :input-syntax-ids (or (get-in syntax
                                          [:origin 0 :input-syntax-ids])
                                  (get-in syntax [:origin 0 :inputs]))
            :expansion-step 1
            :generated-span (or (get-in syntax [:origin 0 :span])
                                (get-in syntax
                                        [:origin 0 :generated-span]))
            :caller-profile (:profile syntax)
            :hygiene (:hygiene syntax)})
         (filter #(= :generated-form (get-in % [:form :kind])) syntax-stream))
   :status :complete})

(defn c3-syntax-serialization-fixture
  [syntax-stream]
  (let [payload {:artifact :gravity/syntax-serialization-fixture
                 :syntax-ids (mapv :syntax/id syntax-stream)
                 :forms (mapv #(get-in % [:form :kind]) syntax-stream)
                 :origins (mapv #(mapv :kind (:origin %)) syntax-stream)
                 :identity-input-hashes
                 (mapv #(get-in % [:identity :input-hash]) syntax-stream)
                 :source-links (mapv :source syntax-stream)
                 :reader-facts (mapv :facts syntax-stream)
                 :versions (mapv :version syntax-stream)}
        serialized (pr-str payload)
        semantic-payload
        (-> payload
            (update :source-links
                    #(mapv (fn [source]
                             (dissoc source :actual-path :path))
                           (or % []))))
        round-trip (read-string serialized)]
    {:artifact :gravity/syntax-serialization-fixture
     :format :edn
     :payload payload
     :canonical serialized
     :hash (reader-canonical-hash
            {:domain :gravity/c3-syntax-serialization-fixture-v2
             :semantic-payload semantic-payload})
     :roundtrip? (= payload round-trip)}))

(defn c3-resolvable-span?
  [span]
  (let [primary (:primary span)]
    (or (and (map? primary)
             (:source primary)
             (contains? primary :byte-start)
             (contains? primary :byte-end))
        (and (string? primary)
             (str/starts-with? primary "generated:"))
        (and (map? primary)
             (= :generated (:kind primary))
             (string? (:producer-id primary))
             (re-find #"^sha256:[0-9a-f]{64}$" (:producer-id primary))
             (integer? (:ordinal primary))
             (not (neg? (:ordinal primary)))))))

(declare sh04-syntax-current-binding!
         sh04-syntax-execute!
         sh04-syntax-rich-object
         sh04-syntax-semantic-source-id
         sh04-syntax-reader-binding
         sh04-syntax-current-sh03-product-binding
         sh04-syntax-descriptor-sh03-product-binding
         sh04-syntax-sh02-descriptor
         sh04-syntax-strip-host-metadata
         sh04-syntax-registered-literal-projection-authentic?
         sh04-syntax-adapter-contract)

(defn c3-syntax-stream-reader-products-authentic?
  ([syntax-stream c2-artifact]
   (c3-syntax-stream-reader-products-authentic?
    syntax-stream c2-artifact nil))
  ([syntax-stream c2-artifact gravity-boundary]
   (try
     (if (:registered-literal-projection c2-artifact)
       (if gravity-boundary
         (let [result (:resolved-syntax-result gravity-boundary)
               result-stream (:syntax-object-stream result)
               source-path
               (get-in c2-artifact [:source-unit-record :path])
               serialization-id
               (p15-s23-c6c10-canonical-digest
                source-path
                (get-in gravity-boundary
                        [:gravity-syntax-serialization
                         :payload-id-request]))
               expected-rich-stream
               (mapv sh04-syntax-rich-object result-stream
                     (repeat serialization-id))]
           (and
            (sh04-syntax-registered-literal-projection-authentic?
             c2-artifact gravity-boundary)
            (= :accepted (:status result))
            (= syntax-stream expected-rich-stream)
            (= :passed
               (get-in gravity-boundary
                       [:resolved-stream-verification :status]))
            (= :accepted
               (get-in gravity-boundary
                       [:gravity-syntax-serialization :status]))
            (= :accepted
               (get-in gravity-boundary
                       [:gravity-syntax-deserialization :status]))))
         false)
       (let [integrity-report (c3-c2-reader-integrity-report c2-artifact)]
        (if gravity-boundary
         (let [result (:resolved-syntax-result gravity-boundary)
               result-stream (:syntax-object-stream result)
               source-path (get-in c2-artifact
                                   [:source-unit-record :path])
               semantic-source-id
               (sh04-syntax-semantic-source-id
                source-path (:source-unit-record c2-artifact))
               expected-reader-authentication
               (sh04-syntax-reader-binding
                source-path c2-artifact semantic-source-id)
               sh03-authentication
               (or (:sh03-reader-authentication c2-artifact)
                   (let [reader-boundary
                         (:gravity-reader-boundary c2-artifact)]
                     {:reader-result-id
                      (get-in reader-boundary
                              [:resolved-reader-result
                               :incremental-reader-hashes
                               :reader-result])
                      :semantic-envelope-id
                      (get-in reader-boundary
                              [:authenticated-envelope
                               :semantic-envelope-id])
                      :provenance-binding-id
                      (get-in reader-boundary
                              [:authenticated-envelope
                               :provenance-binding-id])}))
               reader-authentication-provenance
               (:reader-authentication-provenance gravity-boundary)
               actual-sh03-envelope
               (:actual-sh03-authenticated-envelope
                reader-authentication-provenance)
               actual-sh03-envelope-descriptor
               (:actual-sh03-envelope-descriptor
                reader-authentication-provenance)
               expected-sh03-product-binding
               (sh04-syntax-current-sh03-product-binding c2-artifact)
               actual-sh03-product-binding
               (sh04-syntax-descriptor-sh03-product-binding
                actual-sh03-envelope-descriptor)
               actual-sh03-envelope-verification
               (p15-s23-stage2-sh02-descriptor-envelope-verify!
                actual-sh03-envelope :c2-reader
                :gravity/sh03-reader-products
                actual-sh03-envelope-descriptor source-path)
               binding (sh04-syntax-current-binding! source-path)
               requests (:stream-digest-requests gravity-boundary)
               digests (:stream-resolved-digests gravity-boundary)
               fresh-stream-verification
               (sh04-syntax-execute!
                source-path binding 'c3-syntax-stream-verify-resolved
                [result requests digests])
               fresh-serialization
               (sh04-syntax-execute!
                source-path binding 'c3-syntax-serialize-template
                [result requests digests])
               fresh-deserialization
               (sh04-syntax-execute!
                source-path binding 'c3-syntax-deserialize-template
                [(:carrier fresh-serialization)])
               serialization-id
               (p15-s23-c6c10-canonical-digest
                source-path
                (get-in gravity-boundary
                        [:gravity-syntax-serialization
                         :payload-id-request]))
               expected-rich-stream
               (mapv sh04-syntax-rich-object result-stream
                     (repeat serialization-id))
               source-syntax
               (filterv #(not= :generated-form (get-in % [:form :kind]))
                        syntax-stream)
               generated-syntax
               (filterv #(= :generated-form (get-in % [:form :kind]))
                        syntax-stream)
               expected-form-ids
               (mapv :form-id (:syntax-seed-stream c2-artifact))
               observed-form-ids
               (mapv #(get-in % [:source :form-id]) source-syntax)
               envelope (:authenticated-envelope gravity-boundary)
               envelope-descriptor
               (:authenticated-envelope-descriptor gravity-boundary)
               expected-summary
               {:slice :SH-04 :status :accepted
                :adapter-contract sh04-syntax-adapter-contract
                :semantic-source-id semantic-source-id
                :reader-binding-id
                (reader-canonical-hash
                 (:reader-binding expected-reader-authentication))
                :reader-source-revision-id
                (get-in expected-reader-authentication
                        [:reader-source-revision :revision-id])
                :syntax-stream-id (:artifact-id result)
                :serialization-set-id serialization-id
                :graph-id
                (reader-canonical-hash
                 (:graph-verification-report result))
                :syntax-result-id (:artifact-id result)}
               expected-envelope-descriptor
               (sh04-syntax-sh02-descriptor source-path binding
                                            expected-summary)
               expected-envelope
               (p15-s23-stage2-sh02-descriptor-envelope
                :c3-syntax :gravity/sh04-syntax-products
                expected-envelope-descriptor source-path)
               envelope-verification
               (p15-s23-stage2-sh02-descriptor-envelope-verify!
                envelope :c3-syntax :gravity/sh04-syntax-products
                envelope-descriptor source-path)]
           (and (:authentic? integrity-report)
                (= :SH-04 (:slice gravity-boundary))
                (= :gravity-source (:owner gravity-boundary))
                (= :accepted (:status result))
                (= syntax-stream expected-rich-stream)
                (= (:reader-binding expected-reader-authentication)
                   (:reader-semantic-binding gravity-boundary))
                (= (:reader-source-revision
                    expected-reader-authentication)
                   (:reader-source-revision gravity-boundary))
                (= (:reader-result-id sh03-authentication)
                   (:actual-sh03-reader-result-id
                    reader-authentication-provenance))
                (= (:semantic-envelope-id sh03-authentication)
                   (:actual-sh03-semantic-envelope-id
                    reader-authentication-provenance))
                (= (:provenance-binding-id sh03-authentication)
                   (:actual-sh03-provenance-binding-id
                    reader-authentication-provenance))
                (= :passed actual-sh03-envelope-verification)
                (= expected-sh03-product-binding
                   actual-sh03-product-binding)
                (= expected-sh03-product-binding
                   (:actual-sh03-semantic-product-binding
                    reader-authentication-provenance))
                (= (:semantic-envelope-id actual-sh03-envelope)
                   (:actual-sh03-semantic-envelope-id
                    reader-authentication-provenance))
                (= (:provenance-binding-id actual-sh03-envelope)
                   (:actual-sh03-provenance-binding-id
                    reader-authentication-provenance))
                (= expected-form-ids observed-form-ids)
                (= 1 (count generated-syntax))
                (= (:reader-semantic-binding gravity-boundary)
                   (:reader-binding result))
                (= (:reader-source-revision gravity-boundary)
                   (:reader-source-revision result))
                (= :passed (:status fresh-stream-verification))
                (= fresh-stream-verification
                   (:resolved-stream-verification gravity-boundary))
                (= :accepted (:status fresh-serialization))
                (= fresh-serialization
                   (:gravity-syntax-serialization gravity-boundary))
                (= :accepted (:status fresh-deserialization))
                (= fresh-deserialization
                   (:gravity-syntax-deserialization gravity-boundary))
                (= (:semantic-payload fresh-serialization)
                   (:semantic-payload fresh-deserialization))
                (= expected-envelope-descriptor envelope-descriptor)
                (= expected-envelope envelope)
                (= :passed
                   (get-in result [:graph-verification-report :status]))
                (= :accepted (:status envelope))
                (= :c3-syntax (:stage envelope))
                (= :passed envelope-verification)))
         (let [source-unit (:source-unit-record c2-artifact)
               top-level-products (c2-top-level-products c2-artifact)
               expected-base
               (mapv (fn [seed {:keys [form-record token-record]}]
                       (c3-syntax-object seed form-record token-record
                                         source-unit c2-artifact
                                         integrity-report))
                     (:syntax-seed-stream c2-artifact)
                     top-level-products)
               expected-generated
               (c3-generated-syntax-object
                (or (some #(when (seq (:origin %)) %) expected-base)
                    (first expected-base)))
               expected-stream (conj expected-base expected-generated)]
           (and (:authentic? integrity-report)
                (= expected-stream syntax-stream))))))
     (catch StackOverflowError _ false)
     (catch Exception _ false))))

(defn c3-syntax-verification-report
  ([syntax-stream serialization]
   (c3-syntax-verification-report syntax-stream serialization nil))
  ([syntax-stream serialization c2-artifact]
   (c3-syntax-verification-report
    syntax-stream serialization c2-artifact nil))
  ([syntax-stream serialization c2-artifact gravity-boundary]
   (let [required-fields (set (:required-fields (c3-syntax-schema)))
         checks
         {:required-fields-present?
          (every? #(set/subset? required-fields (set (keys %)))
                  syntax-stream)
          :source-spans-resolve?
          (every? #(c3-resolvable-span? (:span %)) syntax-stream)
          :generated-origins-valid?
          (every? #(and (get-in % [:origin 0 :producer])
                        (seq (or (get-in %
                                         [:origin 0 :input-syntax-ids])
                                 (get-in % [:origin 0 :inputs])))
                        (or (get-in % [:origin 0 :span])
                            (get-in %
                                    [:origin 0 :generated-span])))
                  (filter #(= :generated-form (get-in % [:form :kind]))
                          syntax-stream))
          :hygiene-visible? (every? #(map? (:hygiene %)) syntax-stream)
          :metadata-valid? (every? #(map? (:metadata %)) syntax-stream)
          :namespace-context-valid?
          (every? #(map? (:namespace %)) syntax-stream)
          :phase-transitions-allowed?
          (every? #{:read :macro-expanded} (map :phase syntax-stream))
          :serialization-round-trips? (true? (:roundtrip? serialization))
          :serialization-current?
          (= serialization (c3-syntax-serialization-fixture syntax-stream))
          :reader-products-authentic?
          (if c2-artifact
            (c3-syntax-stream-reader-products-authentic?
             syntax-stream c2-artifact gravity-boundary)
            true)}]
     (assoc checks
            :artifact :gravity/syntax-verification-report
            :status (if (every? true? (vals checks)) :passed :failed)))))

(defn c3-syntax-capability-proof
  [artifact]
  (let [syntax-stream (:syntax-object-stream artifact)
        source-syntax (remove #(= :generated-form (get-in % [:form :kind]))
                              syntax-stream)
        diagnostics (set (map :diagnostic (:rejected-design-coverage artifact)))
        metadata-ledger (:metadata-ledger artifact)
        expected-metadata-syntax-ids
        (set (map :syntax/id (filter #(seq (:metadata %)) source-syntax)))
        recorded-metadata-syntax-ids
        (set (map :syntax-id (:source-metadata metadata-ledger)))
        fact-ledger (:fact-ledger artifact)
        serialization (:syntax-serialization-fixture artifact)
        fresh-serialization (c3-syntax-serialization-fixture syntax-stream)
        generated-report (:generated-syntax-report artifact)
        verifier (:syntax-verification-report artifact)
        gravity-result
        (get-in artifact
                [:gravity-syntax-boundary :resolved-syntax-result])
        gravity-ownership (:gravity-syntax-ownership-product artifact)
        fresh-verifier
        (c3-syntax-verification-report syntax-stream fresh-serialization
                                       (:c2-reader-artifact artifact)
                                       (:gravity-syntax-boundary artifact))
        checks
        {:construction-from-reader-seeds?
     (boolean (and (seq syntax-stream)
                   (= (inc (count (:syntax-seed-stream (:c2-reader-artifact
                                                        artifact))))
                      (count syntax-stream))))
     :stable-syntax-ids?
     (boolean (and (every? #(re-find #"^sha256:" (:syntax/id %))
                           syntax-stream)
                   (= (count syntax-stream)
                      (count (set (map :syntax/id syntax-stream))))))
     :source-and-generated-origins?
     (boolean (and (every? #(some (comp #{:source} :kind) (:origin %))
                           (remove #(= :generated-form (get-in % [:form :kind]))
                                   syntax-stream))
                   (seq (:generated generated-report))))
     :hygiene-propagated?
     (boolean (and (= :complete (get-in artifact [:hygiene-context-map
                                                 :status]))
                   (some #(seq (get-in % [:hygiene :marks]))
                         syntax-stream)))
     :intentional-capture-recorded?
     (boolean (some #(seq (get-in % [:hygiene :captures])) syntax-stream))
     :capture-rejection-covered?
     (contains? diagnostics "C3-CAPTURE")
     :metadata-preservation-and-change?
     (boolean (and (= expected-metadata-syntax-ids
                      recorded-metadata-syntax-ids)
                   (seq (:explicit-changes metadata-ledger))))
     :fact-invalidation-recorded?
     (boolean (and (seq (:attached fact-ledger))
                   (seq (:invalidated fact-ledger))))
     :serialization-round-trips?
     (and (true? (:roundtrip? serialization))
          (= serialization fresh-serialization))
     :reader-products-authentic?
     (true? (:reader-products-authentic? fresh-verifier))
     :syntax-verifier-current? (= verifier fresh-verifier)
     :syntax-verifier-passed? (= :passed (:status fresh-verifier))
     :gravity-authoritative-products-current?
     (boolean
      (and (= (:gravity-hygiene-context-map artifact)
              (:hygiene-context-map gravity-result))
           (= (:gravity-metadata-ledger artifact)
              (:metadata-ledger gravity-result))
           (= (:gravity-fact-invalidation-ledger artifact)
              (:fact-invalidation-ledger gravity-result))
           (= (:gravity-origin-chain-graph artifact)
              (:origin-chain-graph gravity-result))
           (= gravity-ownership (:ownership-product gravity-result))
           (= :gravity-source (:owner gravity-ownership))
           (= 'gravity.bootstrap.syntax (:module gravity-ownership))
           (= (mapv :ownership (:syntax-object-stream gravity-result))
              (:syntax-ownership gravity-ownership))))
     :diagnostics-covered?
     (= (set c3-syntax-diagnostic-ids) diagnostics)}]
    (assoc checks :status (if (every? true? (vals checks))
                            :complete
                            :failed))))

(defn c3-syntax-validate!
  [source-path artifact]
  (let [proof (c3-syntax-capability-proof artifact)]
    (doseq [[field id] [[:construction-from-reader-seeds? "C3-SHAPE"]
                        [:stable-syntax-ids? "C3-ID"]
                        [:source-and-generated-origins? "C3-ORIGIN"]
                        [:hygiene-propagated? "C3-HYGIENE"]
                        [:intentional-capture-recorded? "C3-CAPTURE"]
                        [:metadata-preservation-and-change? "C3-METADATA"]
                        [:fact-invalidation-recorded? "C3-FACT-STALE"]
                        [:serialization-round-trips? "C3-SERIALIZE"]
                        [:reader-products-authentic? "C3-FACT-STALE"]
                        [:syntax-verifier-current? "C3-FACT-STALE"]
                        [:syntax-verifier-passed? "C3-SHAPE"]
                        [:gravity-authoritative-products-current?
                         "C3-FACT-STALE"]
                        [:diagnostics-covered? "C3-SHAPE"]]]
      (when-not (get proof field)
        (c3-syntax-fail! id source-path {:stage :syntax-object-model}
                         {:missing-fields [field]}))))
  :complete)

(defn sh04-syntax-registered-literal-fail!
  [source-path form-record missing-fields facts]
  (c3-syntax-fail!
   "C3-FACT-STALE" source-path
   {:source-span (or (:span form-record) (source-span source-path 0))
    :producer :gravity.bootstrap.reader
    :form-kind :tagged-literal}
   {:missing-fields missing-fields
    :facts facts}))

(defn sh04-syntax-registered-literal-registry
  [source-path c2-artifact]
  (let [forms (:form-tree c2-artifact)
        forms-by-id (into {} (map (juxt :form-id identity)) forms)
        tagged-forms
        (filterv #(and (= :tagged-literal (:kind %))
                       (contains? #{'inst 'uuid} (:tag %)))
                 forms)
        literals-by-form
        (group-by :form-id (:literal-decoding-records c2-artifact))
        invocations-by-form
        (group-by
         :form-id
         (for [extension (:reader-extension-invocation-records c2-artifact)
               invocation (:invocations extension)]
           (assoc invocation :tag (:tag extension))))
        entries
        (mapv
         (fn [form-record]
           (let [tag (:tag form-record)
                 payload-record
                 (get forms-by-id (first (:children form-record)))
                 literal-records
                 (get literals-by-form (:form-id form-record) [])
                 invocation-records
                 (get invocations-by-form (:form-id form-record) [])
                 literal-record (first literal-records)
                 invocation-record (first invocation-records)
                 decoded (:value form-record)
                 payload (:value payload-record)
                 canonical-text
                 (case tag
                   inst
                   (when (= java.util.Date (class decoded))
                     (let [expected
                           (try
                             (.toEpochMilli
                              (.toInstant
                               (java.time.OffsetDateTime/parse payload)))
                             (catch Exception _ nil))
                           observed (.getTime ^java.util.Date decoded)]
                       (when (= expected observed)
                         (Long/toString observed))))
                   uuid
                   (when (= java.util.UUID (class decoded))
                     (let [expected
                           (try
                             (java.util.UUID/fromString payload)
                             (catch Exception _ nil))
                           observed (.toString ^java.util.UUID decoded)]
                       (when (= expected decoded)
                         observed)))
                   nil)
                 descriptor
                 (case tag
                   inst
                   {:artifact :gravity/registered-literal-value
                    :kind :tagged-literal
                    :tag 'inst
                    :canonical-value
                    {:kind :instant
                     :epoch-milliseconds canonical-text}
                    :semantic-validation :accepted}
                   uuid
                   {:artifact :gravity/registered-literal-value
                    :kind :tagged-literal
                    :tag 'uuid
                    :canonical-value
                    {:kind :uuid :canonical-text canonical-text}
                    :semantic-validation :accepted})]
             (when-not
              (and (= 1 (count (:children form-record)))
                   (= :string (:kind payload-record))
                   (string? payload)
                   (= 1 (count literal-records))
                   (= 1 (count invocation-records))
                   (= tag (get-in literal-record [:facts :tag])
                      (:tag invocation-record))
                   (= decoded (:decoded literal-record))
                   (= (:raw form-record) (:raw literal-record)
                      (:raw invocation-record))
                   (= (:span form-record) (:span literal-record)
                      (:span invocation-record))
                   (string? canonical-text))
               (sh04-syntax-registered-literal-fail!
                source-path form-record
                [:authenticated-registered-literal-occurrence]
                {:tag tag :form-id (:form-id form-record)}))
             {:lookup-key [tag canonical-text]
              :descriptor descriptor
              :binding
              {:form-id (:form-id form-record)
               :literal-id (:literal-id literal-record)
               :tag tag
               :raw (:raw form-record)
               :payload payload
               :descriptor descriptor}}))
         tagged-forms)
        expected-form-ids (set (map :form-id tagged-forms))
        invoked-form-ids
        (set
         (for [[form-id records] invocations-by-form
               :when (some #(contains? #{'inst 'uuid} (:tag %)) records)]
           form-id))]
    (when-not (= expected-form-ids invoked-form-ids)
      (sh04-syntax-registered-literal-fail!
       source-path nil [:registered-literal-invocation-bijection]
       {:expected-form-ids expected-form-ids
        :invoked-form-ids invoked-form-ids}))
    {:lookup
     (reduce
      (fn [lookup {:keys [lookup-key descriptor]}]
        (if-let [current (get lookup lookup-key)]
          (if (= current descriptor)
            lookup
            (sh04-syntax-registered-literal-fail!
             source-path nil [:unambiguous-registered-literal-descriptor]
             {:lookup-key lookup-key}))
          (assoc lookup lookup-key descriptor)))
      {} entries)
     :bindings (mapv :binding entries)}))

(defn sh04-syntax-project-registered-literal-values
  [source-path registry value]
  (letfn [(project [item]
            (cond
              (= java.util.Date (class item))
              (or (get-in registry
                          [:lookup
                           ['inst
                            (Long/toString
                             (.getTime ^java.util.Date item))]])
                  (sh04-syntax-registered-literal-fail!
                   source-path nil
                   [:registered-instant-bound-to-reader-occurrence] {}))

              (= java.util.UUID (class item))
              (or (get-in registry
                          [:lookup ['uuid (.toString ^java.util.UUID item)]])
                  (sh04-syntax-registered-literal-fail!
                   source-path nil
                   [:registered-uuid-bound-to-reader-occurrence] {}))

              (map? item)
              (into (empty item)
                    (map (fn [[key child]]
                           [(project key) (project child)]))
                    item)

              (vector? item) (mapv project item)
              (set? item) (into #{} (map project) item)
              (seq? item) (apply list (map project item))
              :else item))]
    (project value)))

(defn sh04-syntax-registered-literal-projection-authentic?
  [c2-view gravity-boundary]
  (try
    (let [projection (:registered-literal-projection c2-view)
          bindings (:bindings projection)
          source-path (get-in c2-view [:source-unit-record :path])
          expected-projection-id
          (p15-s23-c6c10-canonical-digest
           source-path
           {:domain :gravity/sh04-registered-literal-projection-v1
            :bindings bindings})
          forms-by-id
          (into {} (map (juxt :form-id identity)) (:form-tree c2-view))
          literals-by-form
          (group-by :form-id (:literal-decoding-records c2-view))
          invocations-by-form
          (group-by
           :form-id
           (for [extension
                 (:reader-extension-invocation-records c2-view)
                 invocation (:invocations extension)]
             (assoc invocation :tag (:tag extension))))
          tagged-form-ids
          (set
           (map :form-id
                (filter #(and (= :tagged-literal (:kind %))
                              (contains? #{'inst 'uuid} (:tag %)))
                        (:form-tree c2-view))))
          binding-form-ids (set (map :form-id bindings))
          provenance
          (:reader-authentication-provenance gravity-boundary)
          carrier-validation
          (p15-s23-trusted-carrier-validation
           (sh04-syntax-strip-host-metadata c2-view)
           :default-only 1048576 256 4096)]
      (and
       (= #{:artifact :schema-version :projection-id :bindings
            :upstream-artifact-id :upstream-integrity-hash
            :upstream-product-binding :reader-binding
            :reader-source-revision}
          (set (keys projection)))
       (= :gravity/sh04-registered-literal-projection
          (:artifact projection))
       (= 1 (:schema-version projection))
       (= expected-projection-id (:projection-id projection))
       (= :passed (:status carrier-validation))
       (= tagged-form-ids binding-form-ids)
       (= (count bindings) (count binding-form-ids))
       (every?
        (fn [{:keys [form-id literal-id tag raw payload descriptor]}]
          (let [form-record (get forms-by-id form-id)
                payload-record
                (get forms-by-id (first (:children form-record)))
                literal-records (get literals-by-form form-id [])
                invocation-records (get invocations-by-form form-id [])
                literal-record (first literal-records)
                invocation-record (first invocation-records)]
            (and (= :tagged-literal (:kind form-record))
                 (= tag (:tag form-record)
                    (get-in literal-record [:facts :tag])
                    (:tag invocation-record))
                 (= 1 (count (:children form-record)))
                 (= :string (:kind payload-record))
                 (= payload (:value payload-record))
                 (= 1 (count literal-records))
                 (= literal-id (:literal-id literal-record))
                 (= 1 (count invocation-records))
                 (= raw (:raw form-record) (:raw literal-record)
                    (:raw invocation-record))
                 (= descriptor (:value form-record)
                    (:decoded literal-record)))))
        bindings)
       (= (:upstream-artifact-id projection)
          (:actual-c2-artifact-id provenance))
       (= (:upstream-integrity-hash projection)
          (:actual-reader-product-integrity-hash provenance))
       (= (:upstream-product-binding projection)
          (:actual-sh03-semantic-product-binding provenance))
       (= (:reader-binding projection)
          (:reader-semantic-binding gravity-boundary))
       (= (:reader-source-revision projection)
          (:reader-source-revision gravity-boundary))))
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch Throwable _ false)))

(defn c3-reader-artifact-view
  [c2-artifact]
  (let [boundary (:gravity-reader-boundary c2-artifact)
        source-path (get-in c2-artifact [:source-unit-record :path])
        registry
        (sh04-syntax-registered-literal-registry source-path c2-artifact)
        semantic-source-id
        (sh04-syntax-semantic-source-id
         source-path (:source-unit-record c2-artifact))
        reader-authentication
        (sh04-syntax-reader-binding
         source-path c2-artifact semantic-source-id)
        projection-bindings (:bindings registry)
        projection-id
        (p15-s23-c6c10-canonical-digest
         source-path
         {:domain :gravity/sh04-registered-literal-projection-v1
          :bindings projection-bindings})
        projection
        {:artifact :gravity/sh04-registered-literal-projection
         :schema-version 1
         :projection-id projection-id
         :bindings projection-bindings
         :upstream-artifact-id (:artifact-id c2-artifact)
         :upstream-integrity-hash
         (get-in c2-artifact
                 [:reader-product-integrity :integrity-hash])
         :upstream-product-binding
         (sh04-syntax-current-sh03-product-binding c2-artifact)
         :reader-binding (:reader-binding reader-authentication)
         :reader-source-revision
         (:reader-source-revision reader-authentication)}
        base
        (assoc
         (select-keys
          c2-artifact
          [:kind :artifact-id :task :document-set :source-overrides
           :representation-boundary :capability-based-proof
           :source-unit-record :token-stream :form-tree
           :top-level-form-ids :parsed-semantic-values
           :syntax-seed-stream :reader-source-map
           :literal-decoding-records :semantic-error-deferment-record
           :reader-extension-invocation-records :reader-diagnostics
           :incremental-reader-hashes :reader-product-integrity])
         :sh03-reader-authentication
         {:reader-result-id
          (get-in boundary
                  [:resolved-reader-result :incremental-reader-hashes
                   :reader-result])
          :semantic-envelope-id
          (get-in boundary
                  [:authenticated-envelope :semantic-envelope-id])
          :provenance-binding-id
          (get-in boundary
                  [:authenticated-envelope :provenance-binding-id])})]
    (if (seq projection-bindings)
      (sh04-syntax-project-registered-literal-values
       source-path registry
       (assoc base :registered-literal-projection projection))
      base)))

(defn c3-path-neutral-reader-artifact-view
  [c2-view]
  (-> c2-view
      (update :sh03-reader-authentication
              #(dissoc % :provenance-binding-id))
      (update :source-unit-record
              #(-> %
                   (dissoc :path)
                   (update :project-root-record dissoc :path)))
      (update :token-stream c2-token-hash-input)
      (update :form-tree c2-form-hash-input)
      (update :syntax-seed-stream c2-syntax-seed-hash-input)
      (update :reader-extension-invocation-records c2-extension-hash-input)
      (update :reader-source-map
              (fn [records]
                (mapv #(update % :span c2-path-neutral-span) records)))
      (update :literal-decoding-records
              (fn [records]
                (mapv #(update % :span c2-path-neutral-span) records)))
      (update-in [:semantic-error-deferment-record
                  :deferred-literal-records]
                 (fn [records]
                   (mapv #(update % :span c2-path-neutral-span) records)))))

(defn c3-path-neutral-syntax-object
  [syntax]
  (-> syntax
      (update :span
              (fn [span]
                (-> span
                    (update :primary c2-path-neutral-span)
                    (update :all
                            #(mapv c2-path-neutral-span (or % []))))))
      (update :origin #(mapv c3-path-neutral-origin (or % [])))))

(defn c3-gravity-syntax-boundary-identity-view
  [boundary]
  (let [binding (:plan-binding boundary)
        result (:resolved-syntax-result boundary)
        envelope (:authenticated-envelope boundary)]
    {:slice (:slice boundary)
     :owner (:owner boundary)
     :adapter-contract (:adapter-contract boundary)
     :plan-binding
     (select-keys
      binding
      [:artifact :status :semantic-authority :source-byte-count
       :source-content-hash :plan-semantic-hash
       :functions-semantic-hash :function-count
       :function-names-hash :function-shapes-hash
       :public-function-hashes :public-function-shapes])
     :reader-semantic-binding (:reader-semantic-binding boundary)
     :reader-source-revision (:reader-source-revision boundary)
     :resolved-syntax-result
     (select-keys
      result
      [:artifact :kind :schema-version :status :artifact-id
       :semantic-source-id
       :reader-binding :root-syntax-ids :graph-verification-report
       :syntax-serialization :authority :trusted-boundary])
     :semantic-envelope-id (:semantic-envelope-id envelope)
     :resolved-stream-verification
     (select-keys (:resolved-stream-verification boundary)
                  [:artifact :schema-version :status :checks])
     :stream-digest-requests (:stream-digest-requests boundary)
     :stream-resolved-digests (:stream-resolved-digests boundary)
     :gravity-syntax-serialization
     (select-keys (:gravity-syntax-serialization boundary)
                  [:artifact :schema-version :status :encoding
                   :payload-id-request])
     :gravity-syntax-deserialization
     (select-keys (:gravity-syntax-deserialization boundary)
                  [:artifact :schema-version :status :encoding])
     :uncredited-compatibility-facade
     (:uncredited-compatibility-facade boundary)
     :target-source-reread? (:target-source-reread? boundary)
     :clojure-adapter-residual? (:clojure-adapter-residual? boundary)
     :self-hosted? (:self-hosted? boundary)}))

(defn c3-artifact-identity-input
  [artifact]
  (let [boundary (:gravity-syntax-boundary artifact)]
    (cond->
     (-> artifact
         (dissoc :artifact-id)
         (update :c2-reader-artifact c3-path-neutral-reader-artifact-view)
         (update :syntax-object-stream
                 #(mapv c3-path-neutral-syntax-object (or % [])))
         (update-in [:origin-chain-graph :nodes]
                    (fn [nodes]
                      (mapv #(update % :origin
                                     (fn [origins]
                                       (mapv c3-path-neutral-origin
                                             (or origins []))))
                            (or nodes []))))
         (update-in [:gravity-origin-chain-graph :nodes]
                    (fn [nodes]
                      (mapv #(update % :origin
                                     (fn [origins]
                                       (mapv c3-path-neutral-origin
                                             (or origins []))))
                            (or nodes [])))))
      boundary
      (assoc :c2-reader-artifact (:reader-semantic-binding boundary)
             :gravity-syntax-boundary
             (c3-gravity-syntax-boundary-identity-view boundary)))))

(defn c3-artifact-id
  [artifact]
  (reader-canonical-hash (c3-artifact-identity-input artifact)))

(defn- sh03-c3-precomputed-c2-verify!
  [candidate source-path c2-artifact]
  (let [boundary (:gravity-reader-boundary c2-artifact)
        envelope (:authenticated-envelope boundary)
        envelope-descriptor
        (:authenticated-envelope-descriptor boundary)
        expected-binding
        (dissoc (sh03-reader-current-binding! source-path) :plan)]
    (when-not
     (and (identical? candidate sh03-reader-internal-product-authority)
          (= :gravity/stage0-c2-reader-document-artifact
             (:kind c2-artifact))
          (= :SH-03 (:slice boundary))
          (= :gravity-source (:owner boundary))
          (= :gravity/sh03-to-c2-reader-products-v2
             (:adapter-contract boundary))
          (= expected-binding (:plan-binding boundary))
          (= p15-s23-sh02-stage-envelope-keys (set (keys envelope)))
          (= :accepted (:status envelope))
          (= :c2-reader (:stage envelope))
          (= :gravity/sh03-reader-products
             (get-in envelope [:sealed-artifact :artifact-kind]))
          (map? envelope-descriptor)
          (= :passed
             (p15-s23-stage2-sh02-descriptor-envelope-verify!
              envelope :c2-reader :gravity/sh03-reader-products
              envelope-descriptor source-path)))
      (c2-reader-fail!
       "C2-HASH" source-path
       {:stage :read-source
        :source-span (source-span source-path 0)
        :reader-options standard-reader-options}
       {:missing-fields [:authenticated-sh03-c3-precomputed-c2]}))
    c2-artifact))

;; SH-04 executes the pinned Gravity syntax leaf and adapts only its verified
;; products into the compatibility-rich C3 artifact below.  Clojure remains the
;; declared plan runner, digest resolver, envelope binder, and provenance host.
