   {:arity 12
    :params ['base-syntax-id 'form 'generated-span 'producer
             'generation-reason 'namespace-context 'profile 'metadata
             'hygiene 'facts 'reader-binding
             'reader-source-revision]}
   'c3-syntax-verify-template
