(def sh04-syntax-adapter-contract
  :gravity/sh04-to-c3-syntax-products-v1)
(def sh04-syntax-sealed-artifact-kind
  :gravity/sh04-syntax-products)
(def sh04-syntax-envelope-stage :c3-syntax)

(defn sh04-syntax-boundary-fail!
  [rule source-path missing-field observed facts]
  (c3-syntax-fail!
   rule source-path
   {:source-span (source-span source-path 0)
    :producer :gravity.bootstrap.syntax
    :form-kind :syntax-object}
   {:missing-fields [missing-field]
    :facts (merge {:sh04-boundary :gravity-syntax-plan} facts)
    :observed observed}))

(defn sh04-syntax-resolve-source-path
  []
  (let [anchor (java.io.File.
                (p15-s23-stage2-compiler-artifact-source-path))
        start (if (.isDirectory anchor) anchor (.getParentFile anchor))]
    (or
     (loop [directory start]
       (when directory
         (let [candidate
               (java.io.File. directory sh04-syntax-source-relative-path)]
           (if (.isFile candidate)
             (.getPath candidate)
             (recur (.getParentFile directory))))))
     sh04-syntax-source-relative-path)))

(defn sh04-syntax-read-pinned-source!
  [request-source]
  (let [source-path (sh04-syntax-resolve-source-path)
        nio-path (.toPath (java.io.File. source-path))
        nofollow (into-array java.nio.file.LinkOption
                             [java.nio.file.LinkOption/NOFOLLOW_LINKS])
        attributes
        (try
          (java.nio.file.Files/readAttributes
           nio-path java.nio.file.attribute.BasicFileAttributes nofollow)
          (catch Exception error
            (sh04-syntax-boundary-fail!
             "C3-ID" request-source :pinned-syntax-source-readable
             source-path {:cause-message (.getMessage error)})))
        _ (when-not (and attributes
                         (.isRegularFile attributes)
                         (= (long sh04-syntax-expected-source-byte-count)
                            (.size attributes)))
            (sh04-syntax-boundary-fail!
             "C3-ID" request-source :exact-pinned-syntax-source
             source-path
             {:expected-byte-count sh04-syntax-expected-source-byte-count
              :observed-byte-count (when attributes (.size attributes))}))
        bytes
        (try
          (java.nio.file.Files/readAllBytes nio-path)
          (catch Exception error
            (sh04-syntax-boundary-fail!
             "C3-ID" request-source :pinned-syntax-source-bytes
             source-path {:cause-message (.getMessage error)})))
        content-hash (str "sha256:" (sha256-bytes-hex bytes))]
    (when-not (and (= sh04-syntax-expected-source-byte-count
                      (alength bytes))
                   (= sh04-syntax-expected-source-content-hash content-hash))
      (sh04-syntax-boundary-fail!
       "C3-ID" request-source :pinned-syntax-source-identity
       source-path {:observed-content-hash content-hash
                    :observed-byte-count (alength bytes)}))
    {:source-path source-path
     :source-text (String. bytes java.nio.charset.StandardCharsets/UTF_8)
     :source-byte-count (alength bytes)
     :source-content-hash content-hash}))

(defn sh04-syntax-plan-identities
  [plan]
  (let [functions (:functions plan)
        shapes
        (into (sorted-map)
              (map (fn [[name function]]
                     [name (select-keys function [:arity :params])]))
              functions)]
    {:plan-semantic-hash
     (p15-s23-c11-mir-digest
      (p15-s23-stage2-compiler-artifact-semantic-input plan))
     :functions-semantic-hash (p15-s23-c11-mir-digest functions)
     :function-count (count functions)
     :function-names-hash
     (p15-s23-c11-mir-digest (vec (keys functions)))
     :function-shapes-hash (p15-s23-c11-mir-digest shapes)
     :public-function-hashes
     (into (sorted-map)
           (map (fn [name]
                  [name (p15-s23-c11-mir-digest (get functions name))]))
           (keys sh04-syntax-public-function-hashes))
     :public-function-shapes
     (select-keys shapes (keys sh04-syntax-public-function-shapes))}))

(defn sh04-syntax-build-binding!
  [request-source]
  (let [source (sh04-syntax-read-pinned-source! request-source)
        emitter
        (:emitter
         (c-backend-stage2-plan-emitter-source-rule!
          (:source-path source) :jvm))
        plan
        (p15-s23-stage2-compiler-artifact-plan
         emitter (:source-path source) (:source-text source))
        identities (sh04-syntax-plan-identities plan)]
    (when-not
     (and (= :gravity/stage2-compiler-artifact-plan (:kind plan))
          (true? (:compiler-artifact-plan? plan))
          (= 'gravity.bootstrap.syntax (get-in plan [:module :module]))
          (= :meta (get-in plan [:module :profile]))
          (= :jvm (get-in plan [:module :target]))
          (= #{} (get-in plan [:module :effects]))
          (= #{} (get-in plan [:module :capabilities]))
          (= :safe (get-in plan [:module :safety]))
          (= sh04-syntax-expected-plan-semantic-hash
             (:plan-semantic-hash identities))
          (= sh04-syntax-expected-functions-semantic-hash
             (:functions-semantic-hash identities))
          (= sh04-syntax-expected-function-count
             (:function-count identities))
          (= sh04-syntax-expected-function-names-hash
             (:function-names-hash identities))
          (= sh04-syntax-expected-function-shapes-hash
             (:function-shapes-hash identities))
          (= sh04-syntax-public-function-hashes
             (:public-function-hashes identities))
          (= sh04-syntax-public-function-shapes
             (:public-function-shapes identities)))
      (sh04-syntax-boundary-fail!
       "C3-ID" request-source :pinned-syntax-plan-and-functions
       identities {}))
    (merge source identities
           {:artifact :gravity/sh04-pinned-syntax-plan-binding
            :status :complete
            :semantic-authority :gravity-source
            :compiled-by :clojure-stage0-seed
            :executed-by :clojure-stage2-generic-rule-runner
            :generic-bridge-residual? true
            :self-hosted? false
            :plan plan})))

(def ^:private sh04-syntax-cached-binding
  (delay (sh04-syntax-build-binding! "<sh04-syntax-bootstrap>")))

(defn sh04-syntax-current-binding!
  [request-source]
  (let [fresh (sh04-syntax-read-pinned-source! request-source)
        binding @sh04-syntax-cached-binding
        identities (sh04-syntax-plan-identities (:plan binding))]
    (when-not
     (and (= (:source-byte-count fresh) (:source-byte-count binding))
          (= (:source-content-hash fresh) (:source-content-hash binding))
          (= (select-keys binding
                          [:plan-semantic-hash :functions-semantic-hash
                           :function-count :function-names-hash
                           :function-shapes-hash :public-function-hashes
                           :public-function-shapes])
             identities))
      (sh04-syntax-boundary-fail!
       "C3-ID" request-source :fresh-syntax-source-and-plan-binding
       binding {}))
    binding))

(declare sh04-syntax-strip-host-metadata)

(defn sh04-syntax-execute!
  [source-path binding function arguments]
  (try
    (let [clean-arguments
          (sh04-syntax-strip-host-metadata arguments)]
      (sh04-syntax-strip-host-metadata
       (p15-s23-stage2-runtime-execute-function
        {:engine :gravity-sh04-pinned-syntax-runner
         :compiler-artifact-plan? true}
        (:plan binding) function clean-arguments)))
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch StackOverflowError error
      (sh04-syntax-boundary-fail!
       "C3-SHAPE" source-path :bounded-syntax-host-stack function
       {:contained-host-error (.getName (class error))}))
    (catch AssertionError error
      (sh04-syntax-boundary-fail!
       "C3-SHAPE" source-path :contained-syntax-assertion function
       {:contained-host-error (.getName (class error))}))
    (catch LinkageError error
      (sh04-syntax-boundary-fail!
       "C3-SHAPE" source-path :contained-syntax-linkage function
       {:contained-host-error (.getName (class error))}))
    (catch clojure.lang.ExceptionInfo error
      (sh04-syntax-boundary-fail!
       "C3-SHAPE" source-path :contained-syntax-runtime-diagnostic
       function {:contained-diagnostic (:id (ex-data error))}))
    (catch Exception error
      (sh04-syntax-boundary-fail!
       "C3-SHAPE" source-path :contained-syntax-host-failure function
       {:contained-host-error (.getName (class error))
        :cause-message (.getMessage error)}))))

(defn sh04-syntax-require-carrier!
  [source-path carrier value]
  (let [validation
        (p15-s23-trusted-carrier-validation
         value :default-only 1048576 256 4096)]
    (when-not (= :passed (:status validation))
      (sh04-syntax-boundary-fail!
       "C3-SHAPE" source-path :bounded-syntax-result-carrier
       carrier (select-keys validation [:reason :observed-nodes
                                        :observed-depth :maximum-nodes
                                        :maximum-depth :maximum-width])))
    value))

(defn sh04-syntax-raise-result!
  [source-path result]
  (sh04-syntax-require-carrier! source-path :gravity-syntax-result result)
  (when-not (= :accepted (:status result))
    (let [diagnostic (first (:diagnostics result))
          rule (or (:rule diagnostic) "C3-SHAPE")]
      (c3-syntax-fail!
       rule source-path
       {:source-span (or (get-in diagnostic [:primary :span])
                         (source-span source-path 0))
        :syntax-id (get-in diagnostic [:primary :syntax-id])
        :producer :gravity.bootstrap.syntax
        :form-kind (get-in diagnostic [:facts :form-kind])}
       {:missing-fields (or (get-in diagnostic [:facts :missing-fields])
                            [:accepted-gravity-syntax-result])
        :facts {:gravity-diagnostic diagnostic}})))
  result)

(defn sh04-syntax-resolve-object-template!
  [source-path syntax-template resolved-digests]
  ;; Digest references are control data only in schema-declared identity
  ;; slots.  Semantic forms may legitimately contain an ordinary map such as
  ;; {:digest-ref 0}; recursively walking the artifact would reinterpret that
  ;; source data and change the program being compiled.
  (when-not (and (= 2 (count resolved-digests))
                 (= {:digest-ref 1} (:syntax-id syntax-template)))
    (sh04-syntax-boundary-fail!
     "C3-ID" source-path :declared-syntax-id-reference
     (:syntax-id syntax-template)
     {:resolved-digest-count (count resolved-digests)}))
  (assoc syntax-template :syntax-id (second resolved-digests)))

(defn sh04-syntax-resolve-stream-template!
  [source-path stream-template resolved-digests]
  (when-not (and (= 1 (count resolved-digests))
                 (= {:digest-ref 0} (:artifact-id stream-template)))
    (sh04-syntax-boundary-fail!
     "C3-ID" source-path :declared-stream-artifact-id-reference
     (:artifact-id stream-template)
     {:resolved-digest-count (count resolved-digests)}))
  (assoc stream-template :artifact-id (first resolved-digests)))

(defn sh04-syntax-resolve-request-preimage!
  [source-path request resolved-digests]
  (let [ordinal (:ordinal request)
        dependencies (:depends-on request)
        preimage (:preimage request)]
    (case ordinal
      0
      (do
        (when-not (and (= [] dependencies) (empty? resolved-digests))
          (sh04-syntax-boundary-fail!
           "C3-ID" source-path :exact-syntax-request-zero-dependencies
           dependencies {:resolved-digest-count (count resolved-digests)}))
        preimage)

      1
      (do
        (when-not (and (= [0] dependencies)
                       (= 1 (count resolved-digests))
                       (= {:digest-ref 0}
                          (get-in preimage
                                  [:reader-binding
                                   :semantic-binding-id])))
          (sh04-syntax-boundary-fail!
           "C3-ID" source-path :declared-reader-binding-reference
           (get-in preimage [:reader-binding :semantic-binding-id])
           {:dependencies dependencies
            :resolved-digest-count (count resolved-digests)}))
        (assoc-in preimage [:reader-binding :semantic-binding-id]
                  (first resolved-digests)))

      (sh04-syntax-boundary-fail!
       "C3-ID" source-path :known-syntax-request-ordinal
       ordinal {:dependencies dependencies}))))

(defn sh04-syntax-resolve-stream-request-preimage!
  [source-path request resolved-digests]
  (when-not (and (= 0 (:ordinal request))
                 (= [] (:depends-on request))
                 (empty? resolved-digests))
    (sh04-syntax-boundary-fail!
     "C3-ID" source-path :exact-syntax-stream-request-dependencies
     request {:resolved-digest-count (count resolved-digests)}))
  (:preimage request))

(defn sh04-syntax-resolve-template!
  [source-path binding raw reader-binding reader-source-revision]
  (sh04-syntax-raise-result! source-path raw)
  (let [requests (:digest-requests raw)
        request-count (count requests)
        _ (when-not (and (= :gravity/sh04-syntax-template-result
                            (:artifact raw))
                         (= 1 (:schema-version raw))
                         (= 2 request-count)
                         (= false
                            (get-in raw
                                    [:containment
                                     :downstream-artifacts-forbidden])))
            (sh04-syntax-boundary-fail!
             "C3-SHAPE" source-path :exact-syntax-template-result raw {}))
        verification
        (sh04-syntax-execute!
         source-path binding 'c3-syntax-verify-template
         [(:syntax-template raw) requests])
        _ (when-not (and (= :gravity/sh04-syntax-verification-report
                            (:artifact verification))
                         (= :passed (:status verification))
                         (= false
                            (get-in verification
                                    [:containment
                                     :downstream-artifacts-forbidden])))
            (sh04-syntax-boundary-fail!
             "C3-ID" source-path :fresh-gravity-syntax-template-replay
             verification {}))
        digests
        (reduce
         (fn [resolved request]
           (let [ordinal (:ordinal request)
                 resolved-preimage
                 (sh04-syntax-resolve-request-preimage!
                  source-path request resolved)]
             (when-not (= ordinal (count resolved))
               (sh04-syntax-boundary-fail!
                "C3-ID" source-path :ordered-syntax-digest-requests
                request {:resolved-count (count resolved)}))
             (conj resolved
                   (p15-s23-c6c10-canonical-digest
                    source-path resolved-preimage))))
         [] requests)
        syntax
        (sh04-syntax-resolve-object-template!
         source-path (:syntax-template raw) digests)
        resolved-verification
        (sh04-syntax-execute!
         source-path binding 'c3-syntax-verify-resolved
         [syntax requests digests reader-binding reader-source-revision])
        _ (when-not (and (= :gravity/sh04-resolved-syntax-verification-report
                            (:artifact resolved-verification))
                         (= :passed (:status resolved-verification))
                         (= (:semantic-binding-id reader-binding)
                            (first digests))
                         (= (:syntax-id syntax) (second digests))
                         (= false
                            (get-in resolved-verification
                                    [:containment
                                     :downstream-artifacts-forbidden])))
            (sh04-syntax-boundary-fail!
             "C3-ID" source-path :fresh-resolved-syntax-verification
             resolved-verification {}))]
    {:raw-result raw
     :verification-report verification
     :resolved-verification-report resolved-verification
     :resolved-digests digests
     :syntax syntax
     :serialization-id (:syntax-id syntax)}))

(defn sh04-syntax-logical-stem
  [source-path source-unit]
  (-> (or (:project-relative-path source-unit)
          (.getName (java.io.File. source-path)))
      reader-normalize-relative-path
      (str/replace #"\.(gravity|qst)$" "")))

(defn sh04-syntax-semantic-source-id
  [source-path source-unit]
  (reader-canonical-hash
   {:domain :gravity/sh04-co-canonical-source-v1
    :logical-source-stem (sh04-syntax-logical-stem source-path source-unit)
    :encoding (:encoding source-unit)
    :bytes-hash (:bytes-hash source-unit)
    :reader-options (:reader-options source-unit)}))

(defn sh04-syntax-semantic-span
  [span semantic-source-id]
  {:source (:source span)
   :file semantic-source-id
   :byte-start (:byte-start span)
   :byte-end (:byte-end span)
   :scalar-start (or (:scalar-start span) (get-in span [:start :char]))
   :scalar-end (or (:scalar-end span) (get-in span [:end :char]))
   :line-start (or (:line-start span) (get-in span [:start :line]))
   :column-start (or (:column-start span) (get-in span [:start :column]))
   :line-end (or (:line-end span) (get-in span [:end :line]))
   :column-end (or (:column-end span) (get-in span [:end :column]))})

(def sh04-syntax-sh03-product-binding-keys
  [:adapter-contract :adapted-source-unit-id :adapted-token-stream-id
   :adapted-form-tree-id :adapted-extension-invocation-set-id])

(defn sh04-syntax-current-sh03-product-binding
  [c2-artifact]
  {:adapter-contract
   (or (get-in c2-artifact [:gravity-reader-boundary :adapter-contract])
       :gravity/sh03-to-c2-reader-products-v2)
   :adapted-source-unit-id
   (get-in c2-artifact [:source-unit-record :source-id])
   :adapted-token-stream-id
   (reader-canonical-hash (c2-token-hash-input (:token-stream c2-artifact)))
   :adapted-form-tree-id
   (reader-canonical-hash (c2-form-hash-input (:form-tree c2-artifact)))
   :adapted-extension-invocation-set-id
   (reader-canonical-hash
    (c2-extension-hash-input
     (:reader-extension-invocation-records c2-artifact)))})

(defn sh04-syntax-descriptor-sh03-product-binding
  [descriptor]
  (let [summary
        (:value
         (some #(when (= :reader-product-identities (:name %)) %)
               (:semantic-projections descriptor)))]
    (when (map? summary)
      (select-keys summary sh04-syntax-sh03-product-binding-keys))))

(defn sh04-syntax-reader-binding
  [source-path c2-artifact semantic-source-id]
  (let [source-unit (:source-unit-record c2-artifact)
        token-stream (:token-stream c2-artifact)
        form-tree (:form-tree c2-artifact)
        seeds (:syntax-seed-stream c2-artifact)
        span-input
        (fn [span]
          (select-keys span [:byte-start :byte-end :scalar-start :scalar-end
                             :line-start :column-start :line-end :column-end]))
        semantic-core
        {:semantic-source-id semantic-source-id
         :source-bytes-hash (:bytes-hash source-unit)
         :reader-options (:reader-options source-unit)
         :token-stream-id
         (reader-canonical-hash
          (mapv (fn [token]
                  {:token-id (:token-id token) :kind (:kind token)
                   :raw (:raw token) :span (span-input (:span token))})
                token-stream))
         :form-tree-id
         (reader-canonical-hash
          (mapv (fn [form]
                  {:form-id (:form-id form) :kind (:kind form)
                   :children (:children form)
                   :parent-form-id (:parent-form-id form)
                   :raw (:raw form) :span (span-input (:span form))})
                form-tree))
         :syntax-seed-stream-id
         (reader-canonical-hash
          (mapv (fn [seed]
                  {:form-id (:form-id seed) :form (:form seed)
                   :span (span-input (:span seed))
                   :metadata (:metadata seed) :phase (:phase seed)
                   :profile (:profile seed)})
                seeds))
         :literal-records-id
         (reader-canonical-hash
          (mapv #(update % :span span-input)
                (:literal-decoding-records c2-artifact)))
         :deferment-records-id
         (reader-canonical-hash
          (mapv #(update % :span span-input)
                (get-in c2-artifact
                        [:semantic-error-deferment-record
                         :deferred-literal-records])))
         :extension-records-id
         (reader-canonical-hash
          (c2-extension-hash-input
           (:reader-extension-invocation-records c2-artifact)))}
        reader-result-id
        (reader-canonical-hash
         {:domain :gravity/sh04-semantic-sh03-reader-result-v1
          :semantic-reader-products semantic-core})
        c2-artifact-id
        (reader-canonical-hash
         {:domain :gravity/sh04-semantic-c2-adapter-v1
          :adapter-contract
          (or (get-in c2-artifact
                      [:gravity-reader-boundary :adapter-contract])
              :gravity/sh03-to-c2-reader-products-v2)
          :semantic-reader-products semantic-core})
        envelope-id
        (reader-canonical-hash
         {:domain :gravity/sh04-semantic-sh03-envelope-v1
          :source-content-hash sh03-reader-expected-source-content-hash
          :plan-semantic-hash sh03-reader-expected-plan-semantic-hash
          :reader-result-id reader-result-id
          :c2-artifact-id c2-artifact-id})
        binding-base
        (merge {:artifact :gravity/sh04-reader-semantic-binding
                :schema-version 1}
               semantic-core
               {:reader-result-id reader-result-id
                :c2-artifact-id c2-artifact-id
                :authenticated-envelope-id envelope-id})
        binding-preimage
        (assoc binding-base
               :domain :gravity/sh04-reader-semantic-binding-v1)
        semantic-binding-id
        (p15-s23-c6c10-canonical-digest source-path binding-preimage)
        revision-base
        {:artifact :gravity/sh03-reader-source-revision
         :schema-version 1
         :owner :sh03-reader
         :source-language :gravity
         :logical-source-path sh03-reader-source-relative-path
         :source-content-hash sh03-reader-expected-source-content-hash
         :source-byte-count sh03-reader-expected-source-byte-count
         :plan-semantic-hash sh03-reader-expected-plan-semantic-hash
         :functions-semantic-hash
         sh03-reader-expected-functions-semantic-hash
         :entry-function sh03-reader-entrypoint
         :entry-semantic-hash sh03-reader-expected-entrypoint-semantic-hash
         :verifier-function sh03-reader-verifier
         :verifier-semantic-hash sh03-reader-expected-verifier-semantic-hash
         :reader-result-id reader-result-id
         :c2-artifact-id c2-artifact-id
         :authenticated-envelope-id envelope-id
         :semantic-binding-id semantic-binding-id}
        revision
        (assoc revision-base :revision-id
               (p15-s23-c6c10-canonical-digest
                source-path
                {:domain :gravity/sh03-reader-source-revision-v1
                 :revision revision-base}))
        binding (assoc binding-base
                       :semantic-binding-id semantic-binding-id
                       :source-revision-id (:revision-id revision))]
    {:reader-binding binding
     :reader-source-revision revision}))

(defn sh04-syntax-empty-hygiene
  [namespace]
  {:marks [] :lexical-scopes [] :renames {}
   :introduced-identifiers [] :captures []
   :macro-definition-namespace nil
   :macro-call-site-namespace namespace})

(defn sh04-syntax-strip-host-metadata
  [value]
  (let [clean
        (cond
          (map? value)
          (into (empty value)
                (map (fn [[key item]]
                       [(sh04-syntax-strip-host-metadata key)
                        (sh04-syntax-strip-host-metadata item)]))
                value)

          (vector? value)
          (mapv sh04-syntax-strip-host-metadata value)

          (set? value)
          (into #{} (map sh04-syntax-strip-host-metadata) value)

          (seq? value)
          (apply list (map sh04-syntax-strip-host-metadata value))

          :else value)]
    (if (instance? clojure.lang.IObj clean)
      (with-meta clean nil)
      clean)))

(defn sh04-syntax-descendant-form-ids
  [forms-by-id root-form-id]
  (loop [pending [root-form-id]
         visited #{}]
    (if-let [form-id (peek pending)]
      (if (contains? visited form-id)
        (recur (pop pending) visited)
        (let [record (get forms-by-id form-id)]
          (recur (into (pop pending) (:children record))
                 (conj visited form-id))))
      visited)))

(defn sh04-syntax-source-descriptor
  [seed form-record c2-artifact integrity-report semantic-source-id
   reader-binding reader-source-revision registered-literals]
  (let [span (sh04-syntax-semantic-span (:span seed) semantic-source-id)
        source-namespace (or (:namespace seed) 'gravity.user)
        namespace-context {:current source-namespace :aliases {} :imports []}
        forms-by-id
        (into {} (map (juxt :form-id identity)) (:form-tree c2-artifact))
        descendant-form-ids
        (sh04-syntax-descendant-form-ids
         forms-by-id (:form-id form-record))
        registered-literal-bindings
        (filterv #(contains? descendant-form-ids (:form-id %))
                 (:bindings registered-literals))
        literal-descriptor
        (or (c3-lossless-literal-descriptor seed form-record c2-artifact
                                            integrity-report)
            (c3-tagged-literal-descriptor seed form-record c2-artifact
                                          integrity-report))
        kind (if literal-descriptor
               (:kind form-record)
               (form-kind (:form seed)))
        host-facts (c3-source-facts seed form-record c2-artifact
                                    integrity-report)
        host-facts
        (cond-> host-facts
          (seq registered-literal-bindings)
          (assoc :registered-literal-bindings
                 registered-literal-bindings))
        facts
        (cond-> (dissoc host-facts :reader-product-integrity-hash
                        :reader-source-id)
          (seq host-facts)
          (assoc :semantic-source-id semantic-source-id
                 :reader-result-id (:reader-result-id reader-binding)
                 :c2-artifact-id (:c2-artifact-id reader-binding)
                 :authenticated-envelope-id
                 (:authenticated-envelope-id reader-binding)))]
    (sh04-syntax-strip-host-metadata
     (sh04-syntax-project-registered-literal-values
      (get-in c2-artifact [:source-unit-record :path])
      registered-literals
      {:form {:kind kind :value (or literal-descriptor (:form seed))
              :raw (or (get-in seed [:reader-origin :raw-excerpt]) "")}
       :span span
       :source {:source-id semantic-source-id
                :form-id (:form-id form-record)
                :token-range [(:open-token form-record)
                              (:close-token form-record)]}
       :namespace namespace-context
       :phase (:phase seed)
       :profile (or (:profile seed) :meta)
       :metadata (or (:metadata seed) {})
       :hygiene (sh04-syntax-empty-hygiene source-namespace)
       :origin
       [{:kind :source
         :span span
         :producer {:kind :reader :name 'gravity.bootstrap.reader
                    :identity (:reader-result-id reader-binding)
                    :source-id semantic-source-id
                    :generated-form-id nil}
         :producer-version "SH-03"
         :input-syntax-ids []
         :generation-reason :source-read
         :build-effects []}]
       :facts
       [{:producer-stage :reader
         :fact-kind :authenticated-reader-products
         :value facts
         :version 1
         :invalidated-by [:macro-expansion :metadata-change
                          :namespace-change]}]
       :reader-binding reader-binding
       :reader-source-revision reader-source-revision
       :version 1}))))

(defn sh04-syntax-rich-object
  [syntax serialization-id]
  (-> syntax
      (assoc :syntax/id (:syntax-id syntax)
             :identity {:algorithm :sha256
                        :authority :gravity.bootstrap.syntax
                        :domain :gravity/sh04-syntax-object-v1
                        :input-hash (:syntax-id syntax)
                        :serialization-id serialization-id}
             :authority {:slice :SH-04
                         :owner :gravity-source
                         :module 'gravity.bootstrap.syntax
                         :clojure-adapter-residual? true})
      (dissoc :syntax-id :schema-version)))

(defn sh04-syntax-generated-products!
  [source-path binding base semantic-source-id reader-binding
   reader-source-revision]
  (let [producer-id
        (reader-canonical-hash
         {:domain :gravity/sh04-generated-producer-v1
          :semantic-source-id semantic-source-id
          :input-syntax-id (:syntax-id base)})
        producer {:kind :macro
                  :name 'gravity.bootstrap.syntax/generated-conformance
                  :identity producer-id
                  :version "SH-04"
                  :source-id semantic-source-id
                  :generated-form-id :generated-form-0}
        generated-span {:kind :generated :producer-id producer-id :ordinal 0}
        namespace-context (:namespace base)
        hygiene
        {:marks [:sh04/generated-mark]
         :lexical-scopes [:caller-scope :introduced-scope]
         :renames {'tmp__auto__ 'tmp__sh04__1}
         :introduced-identifiers ['tmp__sh04__1]
         :captures [{:identifier 'captured-binding
                     :macro-api 'gravity.syntax/capture
                     :call-site-namespace (:current namespace-context)
                     :intentional? true
                     :authority-bearing? false
                     :policy-result :not-required}]
         :macro-definition-namespace 'gravity.bootstrap.syntax
         :macro-call-site-namespace (:current namespace-context)}
        raw
        (sh04-syntax-execute!
         source-path binding 'c3-generated-syntax-template
         [(:syntax-id base)
          {:kind :generated-form :value '(do tmp__sh04__1)
           :raw "(do tmp__sh04__1)"}
          generated-span producer :generated-syntax-conformance
          namespace-context (:profile base)
          {:generated true :source-metadata (:metadata base)}
          hygiene
          [{:producer-stage :macro-expansion
            :fact-kind :generated-origin-checked
            :value true :version 1
            :invalidated-by [:name-resolution]}]
          reader-binding reader-source-revision])]
    (sh04-syntax-resolve-template!
     source-path binding raw reader-binding reader-source-revision)))

(defn sh04-syntax-sh02-descriptor
  [source-path binding summary]
  (let [projection-name :syntax-product-identities
        fact-name :syntax-product-binding
        identity-name :syntax-result
        identity-domain :gravity/sh04-syntax-result-identity-v1
        evidence-id
        (p15-s23-c6c10-canonical-digest
         source-path {:domain :gravity/sh04-syntax-envelope-evidence-v1
                      :summary summary
                      :plan-semantic-hash (:plan-semantic-hash binding)})
        identity-preimage {:summary summary}
        observed-id
        (p15-s23-c6c10-canonical-digest
         source-path {:domain identity-domain
                      :semantic-input identity-preimage})
        fact-entries
        [{:syntax-result-id (:syntax-result-id summary)
          :syntax-stream-id (:syntax-stream-id summary)
          :serialization-id (:serialization-set-id summary)
          :graph-id (:graph-id summary)}]
        fact-value {:family fact-name :entries fact-entries}
        artifact-id
        (p15-s23-c6c10-canonical-digest
         source-path {:syntax-result (:syntax-result-id summary)})]
    {:artifact :gravity/private-authenticated-envelope-descriptor
     :schema-version 1
     :stage :c3-syntax
     :artifact-kind sh04-syntax-sealed-artifact-kind
     :source-revision
     {:owner :sh04-syntax
      :source-language :gravity
      :logical-source-path sh04-syntax-source-relative-path
      :source-content-hash (:source-content-hash binding)
      :source-byte-count (:source-byte-count binding)
      :plan-semantic-hash (:plan-semantic-hash binding)
      :functions-semantic-hash (:functions-semantic-hash binding)
      :builder-function 'c3-syntax-stream-build-template
      :builder-semantic-hash
      (get sh04-syntax-public-function-hashes
           'c3-syntax-stream-build-template)
      :function-shapes sh04-syntax-public-function-shapes}
     :projection-contract
     {:contract-kind :gravity/sh04-syntax-product-envelope-contract
      :contract-version 1 :profile :meta :target :jvm
      :required-semantic-projections [projection-name]
      :required-fact-families [fact-name]
      :required-identity-subjects [identity-name]}
     :semantic-projections
     [{:name projection-name :role :complete-syntax-product-identities
       :entry-count (count summary) :value summary}]
     :fact-transitions
     [{:name fact-name :disposition :preserved
       :input fact-value :output fact-value
       :input-count (count fact-value)
       :output-count (count fact-value)
       :evidence-ids [evidence-id]}]
     :effect-capability-relation
     {:effect-facts {:declared #{} :observed #{}}
      :capability-facts {:required #{} :granted #{}}
      :capability-proof-facts {:proof-ids [evidence-id]}
      :effect-order [] :provider-selections [] :grant-scopes []}
     :proof-composite
     {:proof-records [{:proof-id evidence-id :status :checked}]
      :proof-certificate-table {evidence-id {:status :checked}}
      :proof-summary {:required 1 :checked 1}
      :proof-usage [{:proof-id evidence-id :used-by :syntax-products}]}
     :preservation
     {:requires [fact-name] :preserves [fact-name]
      :invalidates [] :regenerates []
      :residual-checks [:identity-subject-equality
                        :digest-graph-reachability]}
     :identity-subjects
     [{:name identity-name :domain identity-domain
       :preimage identity-preimage :observed-id observed-id}]
     :lineage
     [{:stage :sh04-syntax
       :artifact-kind :gravity/sh04-syntax-object-artifact
       :semantic-id (:syntax-result-id summary)
       :artifact-id artifact-id :verification-id evidence-id
       :relation :produced-from-gravity-syntax}]
     :reference-closure
     {:root-id "sh04-syntax-result" :node-ids ["sh04-syntax-result"]
      :edges [] :fact-reference-ids [evidence-id]
      :origin-reference-ids [] :proof-reference-ids [evidence-id]
      :runtime-check-reference-ids [] :observed-node-count 1
      :observed-edge-count 0 :observed-maximum-depth 0}
     :actual-path-provenance
     {:source-path source-path
      :workspace-root (System/getProperty "user.dir")
      :invocation-root (System/getProperty "user.dir")}
     :bounds p15-s23-sh02-authenticated-envelope-bounds}))

(defn sh04-syntax-resolved-result!
  [source-path c2-artifact]
  (let [integrity-report
        (c3-validate-c2-reader-artifact! source-path c2-artifact)
        binding (sh04-syntax-current-binding! source-path)
        source-unit (:source-unit-record c2-artifact)
        semantic-source-id
        (sh04-syntax-semantic-source-id source-path source-unit)
        reader-authentication
        (sh04-syntax-reader-binding
         source-path c2-artifact semantic-source-id)
        reader-binding (:reader-binding reader-authentication)
        reader-source-revision
        (:reader-source-revision reader-authentication)
        registered-literals
        (sh04-syntax-registered-literal-registry
         source-path c2-artifact)
        top-level-products (c2-top-level-products c2-artifact)
        seeds (:syntax-seed-stream c2-artifact)
        base-products
        (mapv
         (fn [seed {:keys [form-record]}]
           (let [descriptor
                 (sh04-syntax-source-descriptor
                 seed form-record c2-artifact integrity-report
                  semantic-source-id reader-binding reader-source-revision
                  registered-literals)
                 raw
                 (sh04-syntax-execute!
                  source-path binding 'c3-syntax-build-template [descriptor])]
             (sh04-syntax-resolve-template!
              source-path binding raw reader-binding
              reader-source-revision)))
         seeds top-level-products)
        _ (when (empty? base-products)
            (sh04-syntax-boundary-fail!
             "C3-SHAPE" source-path :nonempty-syntax-object-stream
             base-products {}))
        generated-product
        (sh04-syntax-generated-products!
         source-path binding (:syntax (first base-products))
         semantic-source-id reader-binding reader-source-revision)
        all-products (conj base-products generated-product)
        resolved-products
        (mapv (fn [product]
                {:syntax-object (:syntax product)
                 :digest-requests
                 (get-in product [:raw-result :digest-requests])
                 :resolved-digests (:resolved-digests product)})
              all-products)
        root-syntax-ids (mapv #(get-in % [:syntax :syntax-id])
                              base-products)
        stream-template-result
        (sh04-syntax-execute!
         source-path binding 'c3-syntax-stream-build-template
         [resolved-products reader-binding reader-source-revision
          root-syntax-ids])
        _ (sh04-syntax-require-carrier!
           source-path :gravity-syntax-stream-template
           stream-template-result)
        _ (when-not (and (= :gravity/sh04-syntax-stream-template-result
                            (:artifact stream-template-result))
                         (= :accepted (:status stream-template-result))
                         (= 1 (count (:digest-requests
                                     stream-template-result)))
                         (= false
                            (get-in stream-template-result
                                    [:containment
                                     :downstream-artifacts-forbidden])))
            (sh04-syntax-boundary-fail!
             "C3-ID" source-path :gravity-syntax-stream-template
             stream-template-result {}))
        stream-requests (:digest-requests stream-template-result)
        stream-digests
        (reduce
         (fn [resolved request]
           (let [ordinal (:ordinal request)
                 resolved-preimage
                 (sh04-syntax-resolve-stream-request-preimage!
                  source-path request resolved)]
             (when-not (= ordinal (count resolved))
               (sh04-syntax-boundary-fail!
                "C3-ID" source-path :ordered-syntax-stream-digest-requests
                request {:resolved-count (count resolved)}))
             (conj resolved
                   (p15-s23-c6c10-canonical-digest
                    source-path resolved-preimage))))
         [] stream-requests)
        resolved-stream
        (sh04-syntax-resolve-stream-template!
         source-path (:stream-template stream-template-result)
         stream-digests)
        _ (sh04-syntax-require-carrier!
           source-path :resolved-gravity-syntax-stream resolved-stream)
        stream-verification
        (sh04-syntax-execute!
         source-path binding 'c3-syntax-stream-verify-resolved
         [resolved-stream stream-requests stream-digests])
        _ (sh04-syntax-require-carrier!
           source-path :gravity-syntax-stream-verification
           stream-verification)
        _ (when-not (and
                     (= :gravity/sh04-resolved-syntax-stream-verification-report
                        (:artifact stream-verification))
                     (= :passed (:status stream-verification))
                     (= false
                        (get-in stream-verification
                                [:containment
                                 :downstream-artifacts-forbidden])))
            (sh04-syntax-boundary-fail!
             "C3-ID" source-path :fresh-resolved-syntax-stream-verification
             stream-verification {}))
        serialization
        (sh04-syntax-execute!
         source-path binding 'c3-syntax-serialize-template
         [resolved-stream stream-requests stream-digests])
        _ (sh04-syntax-require-carrier!
           source-path :gravity-syntax-stream-serialization serialization)
        _ (when-not (= :accepted (:status serialization))
            (sh04-syntax-boundary-fail!
             "C3-SERIALIZE" source-path :gravity-syntax-stream-serialization
             serialization {}))
        deserialization
        (sh04-syntax-execute!
         source-path binding 'c3-syntax-deserialize-template
         [(:carrier serialization)])
        _ (sh04-syntax-require-carrier!
           source-path :gravity-syntax-stream-deserialization deserialization)
        _ (when-not (and (= :accepted (:status deserialization))
                         (= (:semantic-payload serialization)
                            (:semantic-payload deserialization)))
            (sh04-syntax-boundary-fail!
             "C3-SERIALIZE" source-path :gravity-syntax-stream-round-trip
             deserialization {}))
        serialization-id
        (p15-s23-c6c10-canonical-digest
         source-path (:payload-id-request serialization))
        resolved-syntax (:syntax-object-stream resolved-stream)
        rich-syntax
        (mapv sh04-syntax-rich-object resolved-syntax
              (repeat serialization-id))
        graph-report (:graph-verification-report resolved-stream)
        syntax-result-id (:artifact-id resolved-stream)
        summary
        {:slice :SH-04 :status :accepted
         :adapter-contract sh04-syntax-adapter-contract
         :semantic-source-id semantic-source-id
         :reader-binding-id (reader-canonical-hash reader-binding)
         :reader-source-revision-id (:revision-id reader-source-revision)
         :syntax-stream-id syntax-result-id
         :serialization-set-id serialization-id
         :graph-id (reader-canonical-hash graph-report)
         :syntax-result-id syntax-result-id}
        descriptor (sh04-syntax-sh02-descriptor source-path binding summary)
        envelope
        (p15-s23-stage2-sh02-descriptor-envelope
         sh04-syntax-envelope-stage sh04-syntax-sealed-artifact-kind
         descriptor source-path)
        _ (p15-s23-stage2-sh02-descriptor-envelope-verify!
           envelope sh04-syntax-envelope-stage
           sh04-syntax-sealed-artifact-kind descriptor source-path)
        reader-authentication-provenance
        {:actual-c2-artifact-id (:artifact-id c2-artifact)
         :actual-reader-product-integrity-hash
         (get-in c2-artifact
                 [:reader-product-integrity :integrity-hash])
         :actual-reader-source-id (:source-id source-unit)
         :actual-sh03-semantic-product-binding
         (sh04-syntax-descriptor-sh03-product-binding
          (get-in c2-artifact
                  [:gravity-reader-boundary
                   :authenticated-envelope-descriptor]))
         :actual-sh03-reader-result-id
         (get-in c2-artifact
                 [:gravity-reader-boundary :resolved-reader-result
                  :incremental-reader-hashes :reader-result])
         :actual-sh03-semantic-envelope-id
         (get-in c2-artifact
                 [:gravity-reader-boundary :authenticated-envelope
                  :semantic-envelope-id])
         :actual-sh03-provenance-binding-id
         (get-in c2-artifact
                 [:gravity-reader-boundary :authenticated-envelope
                  :provenance-binding-id])
         :actual-sh03-authenticated-envelope
         (get-in c2-artifact
                 [:gravity-reader-boundary :authenticated-envelope])
         :actual-sh03-envelope-descriptor
         (get-in c2-artifact
                 [:gravity-reader-boundary
                  :authenticated-envelope-descriptor])
         :semantic-source-id semantic-source-id}]
    {:resolved-result resolved-stream
     :summary summary
     :descriptor descriptor
     :envelope envelope
     :plan-binding (dissoc binding :plan :source-text)
     :rich-syntax rich-syntax
     :raw-template-results (mapv :raw-result all-products)
     :stream-template-result stream-template-result
     :stream-digest-requests stream-requests
     :stream-resolved-digests stream-digests
     :stream-verification stream-verification
     :serialization serialization
     :deserialization deserialization
     :serialization-id serialization-id
     :reader-binding reader-binding
     :reader-source-revision reader-source-revision
     :reader-authentication-provenance
     reader-authentication-provenance}))

(defn compiler-c3-syntax-source-artifact
  ([source-path source-text]
   (compiler-c3-syntax-source-artifact
    source-path source-text (reader-project-context-for-source source-path)))
  ([source-path source-text project-context]
   (compiler-c3-syntax-source-artifact
    source-path source-text project-context nil))
  ([source-path source-text project-context precomputed-c2-artifact]
   (if precomputed-c2-artifact
     (c2-reader-fail!
      "C2-HASH" source-path
      {:stage :read-source
       :source-span (source-span source-path 0)
       :reader-options standard-reader-options}
      {:missing-fields [:internal-sh03-precomputed-product-authority]})
     (compiler-c3-syntax-source-artifact
      source-path source-text project-context nil
      sh03-reader-internal-product-authority)))
  ([source-path source-text project-context precomputed-c2-artifact candidate]
  (let [c2-artifact
        (if precomputed-c2-artifact
          (sh03-c3-precomputed-c2-verify!
           candidate source-path precomputed-c2-artifact)
          (compiler-c2-reader-source-artifact
           source-path source-text project-context))
        integrity-report
        (c3-validate-c2-reader-artifact! source-path c2-artifact)
        forms (:parsed-semantic-values c2-artifact)
        overrides (c3-syntax-overrides-from-forms forms)
        _ (c3-syntax-validate-overrides! source-path overrides)
        sh04-products (sh04-syntax-resolved-result! source-path c2-artifact)
        syntax-stream (:rich-syntax sh04-products)
        sh04-result (:resolved-result sh04-products)
        gravity-boundary
        {:slice :SH-04
         :owner :gravity-source
         :plan-binding (:plan-binding sh04-products)
         :reader-semantic-binding (:reader-binding sh04-products)
         :reader-source-revision
         (:reader-source-revision sh04-products)
         :reader-authentication-provenance
         (:reader-authentication-provenance sh04-products)
         :resolved-syntax-result sh04-result
         :resolved-stream-verification
         (:stream-verification sh04-products)
         :stream-digest-requests
         (:stream-digest-requests sh04-products)
         :stream-resolved-digests
         (:stream-resolved-digests sh04-products)
         :gravity-syntax-serialization (:serialization sh04-products)
         :gravity-syntax-deserialization (:deserialization sh04-products)
         :adapter-contract sh04-syntax-adapter-contract
         :authenticated-envelope (:envelope sh04-products)
         :authenticated-envelope-descriptor (:descriptor sh04-products)
         :uncredited-compatibility-facade
         {:module 'gravity.compiler.c3-syntax-object-model
          :source-path sh04-syntax-facade-relative-path
          :status :compatibility-only
          :authentication-credit? false
          :authoritative-result? false
          :self-hosting-credit? false
          :seed-retirement-credit? false
          :release-credit? false}
         :target-source-reread? false
         :clojure-adapter-residual? true
         :self-hosted? false}
        serialization (c3-syntax-serialization-fixture syntax-stream)
        artifact-base {:kind :gravity/stage0-c3-syntax-object-artifact
                       :task "P06-D082"
                       :document-set ["C3"]
                       :governing-document c3-syntax-governing-document
                       :pass {:name :c3-syntax-object-model
                              :input :c2-reader-document-artifact
                              :output :syntax-object-model-proof
                              :requires [:source-unit-record
                                         :syntax-seed-stream
                                         :reader-source-map]
                              :preserves [:source-spans :generated-origin
                                          :namespace-context :profile
                                          :metadata :hygiene]
                              :emits [:syntax-object-schema
                                      :syntax-object-stream
                                      :hygiene-context-map
                                      :origin-chain-graph
                                      :metadata-ledger
                                      :generated-syntax-report
                                      :syntax-verification-report
                                      :syntax-serialization-fixture]
                              :rejects c3-syntax-diagnostic-ids}
                       :source-overrides overrides
                       :gravity-syntax-boundary gravity-boundary
                       :c2-reader-artifact
                       (c3-reader-artifact-view c2-artifact)
                       :syntax-object-schema (c3-syntax-schema)
                       :syntax-object-stream syntax-stream
                       :gravity-hygiene-context-map
                       (:hygiene-context-map sh04-result)
                       :gravity-metadata-ledger
                       (:metadata-ledger sh04-result)
                       :gravity-fact-invalidation-ledger
                       (:fact-invalidation-ledger sh04-result)
                       :gravity-origin-chain-graph
                       (:origin-chain-graph sh04-result)
                       :gravity-syntax-ownership-product
                       (:ownership-product sh04-result)
                       :hygiene-context-map (c3-hygiene-context-map
                                             syntax-stream)
                       :origin-chain-graph (c3-origin-chain-graph
                                            syntax-stream)
                       :metadata-ledger (c3-metadata-ledger syntax-stream)
                       :generated-syntax-report (c3-generated-syntax-report
                                                 syntax-stream)
                       :fact-ledger (c3-fact-ledger syntax-stream)
                       :syntax-serialization-fixture serialization
                       :syntax-verification-report
                       (c3-syntax-verification-report syntax-stream
                                                      serialization
                                                      c2-artifact
                                                      gravity-boundary)
                       :rejected-design-coverage c3-syntax-rejected-designs
                       :diagnostics []}
        _ (c3-syntax-validate! source-path artifact-base)
        capability-proof (c3-syntax-capability-proof artifact-base)
        conformance {:documents ["C3"]
                     :task "P06-D082"
                     :required-diagnostic-ids c3-syntax-diagnostic-ids
                     :schema-status :complete
                     :stream-status :complete
                     :origin-status :complete
                     :hygiene-status :complete
                     :capture-status :complete
                     :metadata-status :complete
                     :fact-invalidation-status :complete
                     :serialization-status :complete
                     :diagnostic-status :complete
                     :status :complete}
        artifact (assoc artifact-base
                        :capability-based-proof capability-proof
                        :c3-syntax-results conformance)]
    (assoc artifact :artifact-id (c3-artifact-id artifact)))))

(defn compiler-c3-syntax-file-artifact
  [path]
  (let [c2-artifact (compiler-c2-reader-file-artifact path)
        source-text (c2-reader-artifact-source-text path c2-artifact)]
    (compiler-c3-syntax-source-artifact
     path source-text (reader-project-context-for-source path) c2-artifact
     sh03-reader-internal-product-authority)))

;; SH-05 executes the pinned Gravity macro leaf over authenticated SH-04
;; syntax.  Clojure remains the declared plan runner, digest resolver,
;; envelope binder, compatibility packager, and central route host.
(def sh05-macro-source-relative-path
  "bootstrap/gravity/src/gravity/macro.gravity")
(def sh05-macro-facade-relative-path
  "bootstrap/gravity/src/gravity/compiler/c4_macro_expansion_engine.gravity")
(def sh05-macro-expected-source-byte-count 56488)
(def sh05-macro-expected-source-content-hash
  "sha256:19fe589efb27228b8788347439381b61c907a7b6a562a2a3ac3f7256ae77e549")
(def sh05-macro-expected-plan-semantic-hash
  "sha256:fa8d1c27377204ab134d47ab217b39638acd6eb5a1580276d899850f3fd3d1da")
(def sh05-macro-expected-functions-semantic-hash
  "sha256:50d131f8146232fc09929e5fbcfab4f9db011f720b785d05fe40029bd01ce407")
(def sh05-macro-expected-function-count 46)
(def sh05-macro-expected-function-names-hash
  "sha256:42e599bb9b50599135695c0eb6bf39c4ceb0c79884ad6fcd7b08537871b15dbe")
(def sh05-macro-expected-function-shapes-hash
  "sha256:4a49b16738264948c46c15674b9a96fbc32cb473054bebe3893b5a871d156c1a")
(def sh05-macro-public-function-hashes
  {'sh05-expand-macro-template
   "sha256:7bdb4f2ffebbb9519065e005210f5f2fca2efe90017996d82db9fdd807030b04"
   'sh05-verify-macro-template
   "sha256:599304043c490982bb4c58b919cac16d3e18172f348d4359d62a0e3d9630d241"
   'sh05-verify-macro-resolved
   "sha256:0d3f61ce19a0093d674f5411189dcfd3aebf4ae20a7151c227dbdff15a79b432"})
(def sh05-macro-public-function-shapes
  {'sh05-expand-macro-template {:arity 1 :params ['request]}
   'sh05-verify-macro-template
   {:arity 2 :params ['expansion-template 'digest-requests]}
   'sh05-verify-macro-resolved
   {:arity 3
    :params ['resolved-expansion 'digest-requests 'resolved-digests]}})
(def sh05-macro-adapter-contract
  :gravity/sh05-to-c4-macro-products-v1)
(def sh05-macro-version
  (get sh05-macro-public-function-hashes 'sh05-expand-macro-template))
(def sh05-macro-envelope-stage :c4-macro)
(def sh05-macro-sealed-artifact-kind :gravity/sh05-macro-products)

(defn sh05-macro-boundary-fail!
  [rule source-path missing-field observed facts]
  (c4-macro-fail!
   rule source-path
   {:source-span (source-span source-path 0)
    :macro 'gravity.core/defn
    :macro-version sh05-macro-version
    :profile :meta
    :target :jvm
    :build-effects []
    :capabilities []
    :hygiene {:marks [] :lexical-scopes []}}
   {:severity :error
    :missing-fields [missing-field]
    :facts (merge {:sh05-boundary :gravity-macro-plan} facts)
    :observed observed}))

(defn sh05-macro-resolve-source-path
  []
  (let [anchor (java.io.File.
                (p15-s23-stage2-compiler-artifact-source-path))
        start (if (.isDirectory anchor) anchor (.getParentFile anchor))]
    (or
     (loop [directory start]
       (when directory
         (let [candidate
               (java.io.File. directory sh05-macro-source-relative-path)]
           (if (.isFile candidate)
             (.getPath candidate)
             (recur (.getParentFile directory))))))
     sh05-macro-source-relative-path)))

(defn sh05-macro-read-pinned-source!
  [request-source]
  (let [source-path (sh05-macro-resolve-source-path)
        nio-path (.toPath (java.io.File. source-path))
        nofollow (into-array java.nio.file.LinkOption
                             [java.nio.file.LinkOption/NOFOLLOW_LINKS])
        attributes
        (try
          (java.nio.file.Files/readAttributes
           nio-path java.nio.file.attribute.BasicFileAttributes nofollow)
          (catch Exception error
            (sh05-macro-boundary-fail!
             "C4-TRACE" request-source :pinned-macro-source-readable
             source-path {:cause-message (.getMessage error)})))
        _ (when-not (and attributes (.isRegularFile attributes)
                         (= (long sh05-macro-expected-source-byte-count)
                            (.size attributes)))
            (sh05-macro-boundary-fail!
             "C4-TRACE" request-source :exact-pinned-macro-source
             source-path
             {:expected-byte-count sh05-macro-expected-source-byte-count
              :observed-byte-count (when attributes (.size attributes))}))
        bytes
        (try
          (java.nio.file.Files/readAllBytes nio-path)
          (catch Exception error
            (sh05-macro-boundary-fail!
             "C4-TRACE" request-source :pinned-macro-source-bytes
             source-path {:cause-message (.getMessage error)})))
        content-hash (str "sha256:" (sha256-bytes-hex bytes))]
    (when-not (and (= sh05-macro-expected-source-byte-count
                      (alength bytes))
                   (= sh05-macro-expected-source-content-hash content-hash))
      (sh05-macro-boundary-fail!
       "C4-TRACE" request-source :pinned-macro-source-identity
       source-path {:observed-content-hash content-hash
                    :observed-byte-count (alength bytes)}))
    {:source-path source-path
     :source-text (String. bytes java.nio.charset.StandardCharsets/UTF_8)
     :source-byte-count (alength bytes)
     :source-content-hash content-hash}))

(defn- sh05-macro-compute-plan-identities
  [plan]
  (let [functions (:functions plan)
        shapes
        (into (sorted-map)
              (map (fn [[name function]]
                     [name (select-keys function [:arity :params])]))
              functions)]
    {:plan-semantic-hash
     (p15-s23-c11-mir-digest
      (p15-s23-stage2-compiler-artifact-semantic-input plan))
     :functions-semantic-hash (p15-s23-c11-mir-digest functions)
     :function-count (count functions)
     :function-names-hash
     (p15-s23-c11-mir-digest (vec (keys functions)))
     :function-shapes-hash (p15-s23-c11-mir-digest shapes)
     :public-function-hashes
     (into (sorted-map)
           (map (fn [name]
                  [name (p15-s23-c11-mir-digest (get functions name))]))
           (keys sh05-macro-public-function-hashes))
     :public-function-shapes
     (select-keys shapes (keys sh05-macro-public-function-shapes))}))

(def ^:private sh05-macro-pinned-plan-identities
  (atom nil))

(defn sh05-macro-plan-identities
  [plan]
  (let [[pinned-plan pinned-identities] @sh05-macro-pinned-plan-identities]
    (if (and pinned-plan (identical? pinned-plan plan))
      pinned-identities
      (sh05-macro-compute-plan-identities plan))))

(defn sh05-macro-build-binding!
  [request-source]
  (let [source (sh05-macro-read-pinned-source! request-source)
        emitter
        (:emitter
         (c-backend-stage2-plan-emitter-source-rule!
          (:source-path source) :jvm))
        plan
        (p15-s23-stage2-compiler-artifact-plan
         emitter (:source-path source) (:source-text source))
        identities (sh05-macro-compute-plan-identities plan)]
    (when-not
     (and (= :gravity/stage2-compiler-artifact-plan (:kind plan))
          (true? (:compiler-artifact-plan? plan))
          (= 'gravity.macro (get-in plan [:module :module]))
          (= :meta (get-in plan [:module :profile]))
          (= :jvm (get-in plan [:module :target]))
          (= #{} (get-in plan [:module :effects]))
          (= #{} (get-in plan [:module :capabilities]))
          (= :safe (get-in plan [:module :safety]))
          (= sh05-macro-expected-plan-semantic-hash
             (:plan-semantic-hash identities))
          (= sh05-macro-expected-functions-semantic-hash
             (:functions-semantic-hash identities))
          (= sh05-macro-expected-function-count (:function-count identities))
          (= sh05-macro-expected-function-names-hash
             (:function-names-hash identities))
          (= sh05-macro-expected-function-shapes-hash
             (:function-shapes-hash identities))
          (= sh05-macro-public-function-hashes
             (:public-function-hashes identities))
          (= sh05-macro-public-function-shapes
             (:public-function-shapes identities)))
      (sh05-macro-boundary-fail!
       "C4-TRACE" request-source :pinned-macro-plan-and-functions
       identities {}))
    (reset! sh05-macro-pinned-plan-identities [plan identities])
    (merge source identities
           {:artifact :gravity/sh05-pinned-macro-plan-binding
            :status :complete
            :semantic-authority :gravity-source
            :compiled-by :clojure-stage0-seed
            :executed-by :clojure-stage2-generic-rule-runner
            :generic-bridge-residual? true
            :self-hosted? false
            :plan plan})))

(def ^:private sh05-macro-cached-binding
  (delay (sh05-macro-build-binding! "<sh05-macro-bootstrap>")))

(defn sh05-macro-current-binding!
  [request-source]
  (let [fresh (sh05-macro-read-pinned-source! request-source)
        binding @sh05-macro-cached-binding
        identities (sh05-macro-plan-identities (:plan binding))]
    (when-not
     (and (= (:source-byte-count fresh) (:source-byte-count binding))
          (= (:source-content-hash fresh) (:source-content-hash binding))
          (= (select-keys
              binding
              [:plan-semantic-hash :functions-semantic-hash
               :function-count :function-names-hash
               :function-shapes-hash :public-function-hashes
               :public-function-shapes])
             identities))
      (sh05-macro-boundary-fail!
       "C4-TRACE" request-source :fresh-macro-source-and-plan-binding
       binding {}))
    binding))

(defn sh05-macro-execute!
  [source-path binding function arguments]
  (try
    (sh04-syntax-strip-host-metadata
     (p15-s23-stage2-runtime-execute-function
      {:engine :gravity-sh05-pinned-macro-runner
       :compiler-artifact-plan? true}
      (:plan binding) function
      (sh04-syntax-strip-host-metadata arguments)))
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch StackOverflowError error
      (sh05-macro-boundary-fail!
       "C4-DEPTH" source-path :bounded-macro-host-stack function
       {:contained-host-error (.getName (class error))}))
    (catch AssertionError error
      (sh05-macro-boundary-fail!
       "C4-RETURN" source-path :contained-macro-assertion function
       {:contained-host-error (.getName (class error))}))
    (catch LinkageError error
      (sh05-macro-boundary-fail!
       "C4-RETURN" source-path :contained-macro-linkage function
       {:contained-host-error (.getName (class error))}))
    (catch clojure.lang.ExceptionInfo error
      (sh05-macro-boundary-fail!
       "C4-RETURN" source-path :contained-macro-runtime-diagnostic
       function {:contained-diagnostic (:id (ex-data error))}))
    (catch Exception error
      (sh05-macro-boundary-fail!
       "C4-RETURN" source-path :contained-macro-host-failure function
       {:contained-host-error (.getName (class error))
        :cause-message (.getMessage error)}))))

(defn sh05-resolve-request-preimage!
  [source-path request resolved-digests]
  (let [ordinal (:ordinal request)
        purpose (:purpose request)
        preimage (:preimage request)]
    (case purpose
      :sh05-expanded-syntax-id
      (do
        (when-not (and (= 0 ordinal) (empty? resolved-digests))
          (sh05-macro-boundary-fail!
           "C4-TRACE" source-path :exact-expanded-syntax-request
           request {:resolved-digest-count (count resolved-digests)}))
        preimage)

      :sh05-expansion-provenance-binding-id
      (do
        (when-not (and (= 1 ordinal)
                       (= 1 (count resolved-digests))
                       (= {:digest-ref 0}
                          (:semantic-artifact-id preimage)))
          (sh05-macro-boundary-fail!
           "C4-TRACE" source-path :declared-provenance-artifact-reference
           (:semantic-artifact-id preimage)
           {:resolved-digest-count (count resolved-digests)}))
        (assoc preimage :semantic-artifact-id (first resolved-digests)))

      :sh05-macro-diagnostic-id
      (do
        (when-not (and (= 0 ordinal) (empty? resolved-digests))
          (sh05-macro-boundary-fail!
           "C4-TRACE" source-path :exact-macro-diagnostic-request
           request {:resolved-digest-count (count resolved-digests)}))
        preimage)

      (sh05-macro-boundary-fail!
       "C4-TRACE" source-path :known-macro-digest-request-purpose
       purpose {:ordinal ordinal}))))

(defn sh05-macro-resolve-digests!
  [source-path digest-requests]
  (reduce
   (fn [resolved request]
     (let [ordinal (:ordinal request)
           preimage
           (sh05-resolve-request-preimage!
            source-path request resolved)]
       (when-not (= ordinal (count resolved))
         (sh05-macro-boundary-fail!
          "C4-TRACE" source-path :ordered-macro-digest-requests
          request {:resolved-count (count resolved)}))
       (conj resolved
             (p15-s23-c6c10-canonical-digest source-path preimage))))
   [] digest-requests))

(defn sh05-deep-merge
  [left right]
  (merge-with (fn [left-value right-value]
                (if (and (map? left-value) (map? right-value))
                  (sh05-deep-merge left-value right-value)
                  right-value))
              left right))

(defn sh05-defn-form?
  [form]
  (and (seq? form) (= 'defn (first form))))

(defn sh05-defmacro-form?
  [form]
  (and (seq? form) (= 'defmacro (first form))))

(defn sh05-semantic-component-id
  [call-site-syntax-id role value]
  (reader-canonical-hash
   {:domain :gravity/sh05-input-syntax-component-v1
    :call-site-syntax-id call-site-syntax-id
    :role role
    :semantic-value (sh04-syntax-strip-host-metadata value)}))

(defn sh05-default-macro-request
  [source-path c3-artifact module syntax form]
  (let [[_ name parameters & body] form
        call-site-syntax-id (:syntax/id syntax)
        reader-binding
        (get-in c3-artifact
                [:gravity-syntax-boundary :reader-semantic-binding])
        reader-source-revision
        (get-in c3-artifact
                [:gravity-syntax-boundary :reader-source-revision])
        macro-environment-id
        (reader-canonical-hash
         {:domain :gravity/sh05-bootstrap-macro-environment-v1
          :macros [{:name 'defn :version sh05-macro-version
                    :phase :macro-expansion
                    :build-effects [] :capabilities []}]})
        base-policy
        {:macro-return-kind :syntax
         :expansion-depth 0
         :output-node-count (+ 4 (count body))
         :requested-build-effects []
         :declared-build-effects []
         :granted-build-effects []
         :requested-capabilities []
         :granted-capabilities []
         :hidden-captures []
         :capture-policy :explicit-only
         :generated-unsafe? false
         :unsafe-declared? false
         :allowed-profiles [(:profile module)]
         :generated-profile (:profile module)}
        build-policy-id
        (reader-canonical-hash
         {:domain :gravity/sh05-build-policy-v1 :policy base-policy})
        trace-replay-id
        (reader-canonical-hash
         {:domain :gravity/sh05-trace-replay-v1
          :call-site-syntax-id call-site-syntax-id
          :macro-environment-id macro-environment-id
          :build-policy-id build-policy-id})
        semantic-span
        (let [span
              (select-keys (:span syntax)
                           [:file :byte-start :byte-end
                            :scalar-start :scalar-end :line-start
                            :column-start :line-end :column-end])]
          ;; SH-04 retains the physical source in :source for diagnostics.
          ;; Macro semantic identity uses only its co-canonical source id.
          (assoc span :source (:file span)))]
    {:artifact :gravity/sh05-authenticated-c3-macro-request
     :schema-version 1
     :call
     {:macro-name 'defn
      :macro-version sh05-macro-version
      :call-site-syntax-id call-site-syntax-id
      :definition-syntax-id
      (reader-canonical-hash
       {:domain :gravity/sh05-defn-macro-definition-v1
        :macro-version sh05-macro-version})
      :name-syntax-id
      (sh05-semantic-component-id call-site-syntax-id :name name)
      :parameter-vector-syntax-id
      (sh05-semantic-component-id call-site-syntax-id
                                  :parameters parameters)
      :body-syntax-ids
      (mapv #(sh05-semantic-component-id call-site-syntax-id
                                         [:body %1] %2)
            (range) body)
      :semantic-call-span semantic-span
      :metadata (or (:metadata syntax) {})
      :hygiene (select-keys (:hygiene syntax)
                            [:marks :lexical-scopes])
      :origin-chain (vec (:origin syntax))
      :call-site-span (:span syntax)
      :definition-span
      {:source sh05-macro-source-relative-path
       :byte-start 0 :byte-end sh05-macro-expected-source-byte-count}}
     :context
     {:phase :macro-expansion
      :profile (:profile module)
      :target (:target module)
      :macro-environment-id macro-environment-id
      :build-policy-id build-policy-id
      :trace-replay-id trace-replay-id}
     :policy (assoc base-policy
                    :recorded-trace-replay-id trace-replay-id)
     :provenance {:actual-source-path source-path}
     :reader-binding reader-binding
     :reader-source-revision reader-source-revision
     :reader-semantic-binding-id (:semantic-binding-id reader-binding)
     :source-revision-id (:revision-id reader-source-revision)}))

(defn sh05-macro-raise-rejection!
  [source-path raw resolved-digests]
  (let [diagnostic
        (let [template (first (:diagnostics raw))]
          (when-not (and (= 1 (count resolved-digests))
                         (= {:digest-ref 0}
                            (:diagnostic-id-request template)))
            (sh05-macro-boundary-fail!
             "C4-TRACE" source-path :declared-diagnostic-id-reference
             (:diagnostic-id-request template)
             {:resolved-digest-count (count resolved-digests)}))
          (assoc template :diagnostic-id-request
                 (first resolved-digests)))
        rule (:rule diagnostic)]
    (c4-macro-fail!
     rule source-path
     {:source-span (source-span source-path 0)
      :macro (:macro-name diagnostic)
      :macro-version (:macro-version diagnostic)
      :profile (:profile diagnostic)
      :target (:target diagnostic)
      :build-effects (:build-effects diagnostic)
      :capabilities (:capabilities diagnostic)
      :hygiene (:hygiene-context diagnostic)}
     {:severity (:severity diagnostic)
      :diagnostic-family :c4-macro-expansion
      :stage :macro-expansion
      :facts (:facts diagnostic)
      :remediation (:remediation diagnostic)
      :gravity-diagnostic diagnostic
      :diagnostic-id (get diagnostic :diagnostic-id-request)})))

(defn sh05-contain-coordinator-operation!
  [source-path responsibility operation]
  (try
    (operation)
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch StackOverflowError error
      (sh05-macro-boundary-fail!
       "C4-DEPTH" source-path responsibility nil
       {:contained-host-error (.getName (class error))}))
    (catch clojure.lang.ExceptionInfo error
      (if (contains? (set c4-macro-diagnostic-ids)
                     (:id (ex-data error)))
        (throw error)
        (sh05-macro-boundary-fail!
         "C4-TRACE" source-path responsibility nil
         {:contained-diagnostic (:id (ex-data error))})))
    (catch Throwable error
      (sh05-macro-boundary-fail!
       "C4-RETURN" source-path responsibility nil
       {:contained-host-error (.getName (class error))
        :cause-message (.getMessage error)}))))

(defn sh05-resolve-expansion-template!
  [source-path expansion-template resolved-digests]
  ;; Only these schema-declared positions carry coordinator digest controls.
  ;; Macro input and generated semantic forms remain opaque data, including
  ;; ordinary maps whose shape happens to resemble a digest reference.
  (let [output-reference {:digest-ref 0}
        provenance-reference {:digest-ref 1}
        output-reference-slots
        [[:artifact-id]
         [:output-syntax-id]
         [:macro-expansion-trace 0 :output-syntax-ids 0]
         [:metadata-ledger 0 :output-syntax-id]
         [:generated-origin-source-map 0 :output-syntax-id]]]
    (when-not
     (and (= 2 (count resolved-digests))
          (every? #(= output-reference (get-in expansion-template %))
                  output-reference-slots)
          (= provenance-reference
             (:provenance-binding-id expansion-template)))
      (sh05-macro-boundary-fail!
       "C4-TRACE" source-path :declared-macro-output-reference-slots
       {:output-references
        (mapv #(get-in expansion-template %) output-reference-slots)
        :provenance-reference
        (:provenance-binding-id expansion-template)}
       {:resolved-digest-count (count resolved-digests)}))
    (-> (reduce (fn [template slot]
                  (assoc-in template slot (first resolved-digests)))
                expansion-template output-reference-slots)
        (assoc :provenance-binding-id (second resolved-digests)))))

(defn sh05-run-macro-request!
  [source-path binding request]
  (let [raw
        (sh05-macro-execute!
         source-path binding 'sh05-expand-macro-template [request])
        digest-requests (:digest-requests raw)
        resolved-digests
        (sh05-contain-coordinator-operation!
         source-path :bounded-ordered-macro-digest-resolution
         #(sh05-macro-resolve-digests! source-path digest-requests))]
    (if (= :rejected (:status raw))
      (sh05-contain-coordinator-operation!
       source-path :structured-macro-rejection-packaging
       #(sh05-macro-raise-rejection! source-path raw resolved-digests))
      (let [template-verification
            (sh05-macro-execute!
             source-path binding 'sh05-verify-macro-template
             [(:expansion-template raw) digest-requests])
            resolved-expansion
            (sh05-contain-coordinator-operation!
             source-path :bounded-macro-reference-resolution
             #(sh05-resolve-expansion-template!
               source-path (:expansion-template raw) resolved-digests))
            resolved-verification
            (sh05-macro-execute!
             source-path binding 'sh05-verify-macro-resolved
             [resolved-expansion digest-requests resolved-digests])]
        (when-not (and (= :passed (:status template-verification))
                       (= :passed (:status resolved-verification)))
          (sh05-macro-boundary-fail!
           "C4-TRACE" source-path :fresh-gravity-macro-verification
           {:template template-verification
            :resolved resolved-verification} {}))
        {:raw-template-result
         (select-keys raw
                      [:artifact :schema-version :status
                       :expansion-template])
         :digest-requests digest-requests
         :resolved-digests resolved-digests
         :resolved-expansion resolved-expansion
         :template-verification
         (select-keys template-verification
                      [:artifact :schema-version :status :rule])
         :resolved-verification
         (select-keys resolved-verification
                      [:artifact :schema-version :status :rule])}))))

(defn sh05-source-syntax-stream
  [c3-artifact]
  (filterv #(not= :generated-form (get-in % [:form :kind]))
           (:syntax-object-stream c3-artifact)))

(defn sh05-expanded-form
  [form]
  (if (sh05-defn-form? form)
    (let [[_ name parameters & body] form]
      (list 'def name (apply list 'fn parameters body)))
    form))

(defn sh05-package-trace
  [run profile target]
  (let [expansion (:resolved-expansion run)
        trace (first (:macro-expansion-trace expansion))
        origin (get-in expansion [:generated-origin-source-map 0 :origin])]
    {:artifact :gravity/macro-expansion-step
     :step (:step trace)
     :macro 'defn
     :macro-version (:macro-version trace)
     :definition-span (:definition-span trace)
     :call-site-span (:call-site-span trace)
     :input-syntax-id (first (:input-syntax-ids trace))
     :output-syntax-id (first (:output-syntax-ids trace))
     :hygiene (:hygiene trace)
     :build-effects (:build-effects trace)
     :capabilities (:capabilities trace)
     :generated-origin [origin]
     :profile profile
     :target target
     :trace-replay-id (:trace-replay-id trace)
     :diagnostics []}))

(defn sh05-expanded-syntax-object
  [syntax form run]
  (if run
    (let [expansion (:resolved-expansion run)
          output-id (:output-syntax-id expansion)
          origin (get-in expansion [:generated-origin-source-map 0 :origin])]
      (-> syntax
          (assoc :artifact :gravity/expanded-syntax-object
                 :form (sh05-expanded-form form)
                 :syntax/id output-id
                 :expanded-syntax-id output-id
                 :phase :macro-expanded)
          (update :origin #(conj (vec %) origin))))
    (assoc syntax
           :artifact :gravity/expanded-syntax-object
           :form form
           :expanded-syntax-id (:syntax/id syntax)
           :phase :macro-expanded)))

(defn sh05-expanded-graph
  [expanded-stream trace]
  (let [nodes
        (mapv (fn [syntax]
                {:id (:expanded-syntax-id syntax)
                 :kind :expanded-syntax
                 :form (:form syntax)})
              expanded-stream)
        node-ids (set (map :id nodes))
        edges
        (mapv (fn [step]
                {:from (:input-syntax-id step)
                 :to (:output-syntax-id step)})
              trace)]
    {:artifact :gravity/sh05-expanded-syntax-graph
     :nodes nodes
     :edges edges
     :node-ids node-ids
     :status :complete}))

(defn sh05-expanded-graph-valid?
  [graph]
  (let [node-ids (set (map :id (:nodes graph)))]
    (and (= node-ids (:node-ids graph))
         (every? (fn [edge]
                   (and (contains? node-ids (:to edge))
                        (or (contains? node-ids (:from edge))
                            (string? (:from edge)))))
                 (:edges graph)))))

(defn sh05-macro-sh02-descriptor
  [source-path binding summary]
  (let [projection-name :macro-product-identities
        fact-name :macro-product-binding
        identity-name :macro-result
        identity-domain :gravity/sh05-macro-result-identity-v2
        evidence-id
        (p15-s23-c6c10-canonical-digest
         source-path {:domain :gravity/sh05-macro-envelope-evidence-v2
                      :summary summary
                      :plan-semantic-hash (:plan-semantic-hash binding)})
        identity-preimage {:summary summary}
        observed-id
        (p15-s23-c6c10-canonical-digest
         source-path {:domain identity-domain
                      :semantic-input identity-preimage})
        fact-value {:family fact-name :entries [summary]}
        artifact-id
        (p15-s23-c6c10-canonical-digest
         source-path {:macro-result (:artifact-id summary)})]
    {:artifact :gravity/private-authenticated-envelope-descriptor
     :schema-version 1
     :stage sh05-macro-envelope-stage
     :artifact-kind sh05-macro-sealed-artifact-kind
     :source-revision
     {:owner :sh05-macro
      :source-language :gravity
      :logical-source-path sh05-macro-source-relative-path
      :source-content-hash (:source-content-hash binding)
      :source-byte-count (:source-byte-count binding)
      :plan-semantic-hash (:plan-semantic-hash binding)
      :functions-semantic-hash (:functions-semantic-hash binding)
      :builder-function 'sh05-expand-macro-template
      :builder-semantic-hash
      (get sh05-macro-public-function-hashes
           'sh05-expand-macro-template)
      :function-shapes sh05-macro-public-function-shapes}
     :projection-contract
     {:contract-kind :gravity/sh05-macro-product-envelope-contract
      :contract-version 1 :profile :meta :target :jvm
      :required-semantic-projections [projection-name]
      :required-fact-families [fact-name]
      :required-identity-subjects [identity-name]}
     :semantic-projections
     [{:name projection-name :role :complete-macro-product-identities
       :entry-count (count summary) :value summary}]
     :fact-transitions
     [{:name fact-name :disposition :preserved
       :input fact-value :output fact-value
       :input-count (count fact-value)
       :output-count (count fact-value)
       :evidence-ids [evidence-id]}]
     :effect-capability-relation
     {:effect-facts {:declared #{} :observed #{}}
      :capability-facts {:required #{} :granted #{}}
      :capability-proof-facts {:proof-ids [evidence-id]}
      :effect-order [] :provider-selections [] :grant-scopes []}
     :proof-composite
     {:proof-records [{:proof-id evidence-id :status :checked}]
      :proof-certificate-table {evidence-id {:status :checked}}
      :proof-summary {:required 1 :checked 1}
      :proof-usage [{:proof-id evidence-id :used-by :macro-products}]}
     :preservation
     {:requires [fact-name] :preserves [fact-name]
      :invalidates [] :regenerates []
      :residual-checks [:identity-subject-equality
                        :digest-graph-reachability]}
     :identity-subjects
     [{:name identity-name :domain identity-domain
       :preimage identity-preimage :observed-id observed-id}]
     :lineage
     [{:stage :sh05-macro
       :artifact-kind :gravity/sh05-macro-expansion-artifact
       :semantic-id (:artifact-id summary)
       :artifact-id artifact-id :verification-id evidence-id
       :relation :produced-from-gravity-macro}]
     :reference-closure
     {:root-id "sh05-macro-result" :node-ids ["sh05-macro-result"]
      :edges [] :fact-reference-ids [evidence-id]
      :origin-reference-ids [] :proof-reference-ids [evidence-id]
      :runtime-check-reference-ids [] :observed-node-count 1
      :observed-edge-count 0 :observed-maximum-depth 0}
     :actual-path-provenance
     {:source-path source-path
      :workspace-root (System/getProperty "user.dir")
      :invocation-root (System/getProperty "user.dir")}
     :bounds p15-s23-sh02-authenticated-envelope-bounds}))

(def sh05-macro-artifact-keys
  #{:kind :status :slice :task :document-set :governing-document
    :artifact-id :expanded-syntax-stream-id :macro-expansion-trace-id
    :expanded-defn-count :expanded-syntax-stream :expanded-forms
    :macro-expansion-trace :macro-environment
    :generated-origin-source-map :expanded-syntax-graph
    :sh04-syntax-artifact :gravity-macro-boundary :provenance
    :pass :capability-based-proof :execution-boundary :diagnostics})

(defn sh05-path-neutral-semantic-value
  [value]
  (cond
    (map? value)
    (let [clean
          (into {}
                (keep (fn [[key item]]
                        (when-not (contains? #{:actual-source-path
                                               :workspace-root
                                               :invocation-root}
                                             key)
                          [key (sh05-path-neutral-semantic-value item)])))
                value)]
      (if (and (contains? clean :byte-start)
               (or (contains? clean :source) (contains? clean :file)))
        (let [semantic-source (or (:file clean) (:source clean))]
          (cond-> clean
            (contains? clean :source) (assoc :source semantic-source)
            (contains? clean :file) (assoc :file semantic-source)))
        clean))

    (vector? value) (mapv sh05-path-neutral-semantic-value value)
    (set? value) (into #{} (map sh05-path-neutral-semantic-value) value)
    (seq? value) (apply list (map sh05-path-neutral-semantic-value value))
    :else value))

(def sh05-identity-chunk-width 16)

(defn sh05-ordered-identity-chunks
  [values projector]
  (->> values
       (map-indexed vector)
       (partition-all sh05-identity-chunk-width)
       (map-indexed
        (fn [chunk-index entries]
          {:chunk-index chunk-index
           :start-ordinal (first (first entries))
           :item-count (count entries)
           :items
           (mapv (fn [[ordinal value]]
                   (projector ordinal value))
                 entries)}))
       vec))

(defn sh05-macro-run-semantic-summary
  [run]
  (let [raw (:raw-template-result run)
        resolved (:resolved-expansion run)
        trace (first (:macro-expansion-trace resolved))]
    {:raw-result {:artifact (:artifact raw)
                  :schema-version (:schema-version raw)
                  :status (:status raw)}
     :digest-contract
     (mapv #(select-keys % [:ordinal :purpose]) (:digest-requests run))
     :semantic-resolved-digest (first (:resolved-digests run))
     :resolved-expansion
     (select-keys
      resolved
      [:artifact :schema-version :artifact-id :status :macro
       :macro-version :input-syntax-id :output-syntax-id
       :semantic-binding :profile :target :phase :bounds])
     :trace-replay-id (:trace-replay-id trace)
     :template-verification
     (:template-verification run)
     :resolved-verification
     (:resolved-verification run)}))

(defn sh05-macro-artifact-semantic-payload
  [artifact]
  (let [boundary (:gravity-macro-boundary artifact)]
    (sh05-path-neutral-semantic-value
     {:domain :gravity/sh05-macro-source-artifact-v2
      :kind (:kind artifact)
      :status (:status artifact)
      :slice (:slice artifact)
      :task (:task artifact)
      :document-set (:document-set artifact)
      :governing-document (:governing-document artifact)
      :sh04-syntax-artifact (:sh04-syntax-artifact artifact)
      :expanded-syntax-stream-id (:expanded-syntax-stream-id artifact)
      :macro-expansion-trace-id (:macro-expansion-trace-id artifact)
      :expanded-defn-count (:expanded-defn-count artifact)
      :macro-environment (:macro-environment artifact)
      :pass (:pass artifact)
      :execution-boundary (:execution-boundary artifact)
      :diagnostics (:diagnostics artifact)
      :boundary-contract
      (select-keys boundary
                   [:slice :owner :adapter-contract
                    :target-source-reread? :clojure-adapter-residual?
                    :self-hosted?])
      :plan-binding
      (select-keys
       (:plan-binding boundary)
       [:artifact :status :semantic-authority :compiled-by :executed-by
        :generic-bridge-residual? :self-hosted? :source-language
        :source-byte-count :source-content-hash :plan-semantic-hash
        :functions-semantic-hash :function-count :function-names-hash
        :function-shapes-hash :public-function-hashes
        :public-function-shapes])
      :expansion-run-count (count (:expansion-runs boundary))
      :expansion-run-chunks
      (sh05-ordered-identity-chunks
       (:expansion-runs boundary)
       (fn [ordinal run]
         {:ordinal ordinal
          :summary (sh05-macro-run-semantic-summary run)}))})))

(defn sh05-macro-artifact-identity-input
  [artifact]
  (sh05-macro-artifact-semantic-payload artifact))

(defn sh05-macro-artifact-id
  [artifact]
  (p15-s23-c6c10-canonical-digest
   "<sh05-macro-artifact>"
   (sh05-macro-artifact-identity-input artifact)))

(defn sh05-expanded-syntax-stream-identity-input
  [expanded-stream]
  {:domain :gravity/sh05-expanded-syntax-stream-v2
   :item-count (count expanded-stream)
   :item-chunks
   (sh05-ordered-identity-chunks
    expanded-stream
    (fn [ordinal syntax]
      {:ordinal ordinal
       :expanded-syntax-id (:expanded-syntax-id syntax)}))})

(defn sh05-expanded-syntax-stream-id
  [source-path expanded-stream]
  (p15-s23-c6c10-canonical-digest
   source-path
   (sh05-expanded-syntax-stream-identity-input expanded-stream)))

(defn sh05-macro-trace-identity-input
  [trace]
  {:domain :gravity/sh05-macro-expansion-trace-v2
   :item-count (count trace)
   :item-chunks
   (sh05-ordered-identity-chunks
    trace
    (fn [ordinal step]
      {:ordinal ordinal
       :input-syntax-id (:input-syntax-id step)
       :output-syntax-id (:output-syntax-id step)
       :macro (:macro step)
       :macro-version (:macro-version step)
       :trace-replay-id (:trace-replay-id step)}))})

(defn sh05-macro-trace-id
  [source-path trace]
  (p15-s23-c6c10-canonical-digest
   source-path (sh05-macro-trace-identity-input trace)))

(defn sh05-macro-envelope-summary
  [artifact]
  {:slice :SH-05
   :status (:status artifact)
   :artifact-id (:artifact-id artifact)
   :semantic-payload-id (:artifact-id artifact)
   :expanded-syntax-stream-id (:expanded-syntax-stream-id artifact)
   :macro-expansion-trace-id (:macro-expansion-trace-id artifact)
   :expanded-defn-count (:expanded-defn-count artifact)
   :sh04-artifact-id (get-in artifact [:sh04-syntax-artifact :artifact-id])
   :ordered-run-count
   (count (get-in artifact [:gravity-macro-boundary :expansion-runs]))
   :ordered-run-identity-chunks
   (sh05-ordered-identity-chunks
    (get-in artifact [:gravity-macro-boundary :expansion-runs])
    (fn [ordinal run]
      {:ordinal ordinal
       :artifact-id (get-in run [:resolved-expansion :artifact-id])
       :input-syntax-id
       (get-in run [:resolved-expansion :input-syntax-id])
       :output-syntax-id
       (get-in run [:resolved-expansion :output-syntax-id])
       :macro-version
       (get-in run [:resolved-expansion :macro-version])
       :trace-replay-id
       (get-in run [:resolved-expansion
                    :macro-expansion-trace 0 :trace-replay-id])}))})

(defn sh05-macro-gravity-verifier-report
  [source-path boundary]
  (let [binding (sh05-macro-current-binding! source-path)
        reports
        (mapv
         (fn [run]
           (let [raw (:raw-template-result run)
                 resolved (:resolved-expansion run)
                 requests (:digest-requests run)
                 digests (:resolved-digests run)]
             {:template
              (sh05-macro-execute!
               source-path binding 'sh05-verify-macro-template
               [(:expansion-template raw) requests])
              :resolved
              (sh05-macro-execute!
               source-path binding 'sh05-verify-macro-resolved
               [resolved requests digests])}))
         (:expansion-runs boundary))
        template-passed?
        (every? #(= :passed (get-in % [:template :status])) reports)
        resolved-passed?
        (every? #(= :passed (get-in % [:resolved :status])) reports)]
    {:template {:status (if template-passed? :passed :failed)
                :verified-run-count (count reports)}
     :resolved {:status (if resolved-passed? :passed :failed)
                :verified-run-count (count reports)}
     :runs reports}))

;; SH-07 authoritative proof transactions remove repeated verification work
;; inside one module without changing the public verifier contracts.  Receipts
;; are private, thread-confined, phase-confined, identity-bound, and retained
;; only for passed immutable reports.  Construction receipts are destroyed
;; before the independent audit begins.
(def ^:dynamic ^:private *sh07-proof-transaction-context* nil)
(def ^:dynamic ^:private *sh07-proof-transaction-cleanup-observer* nil)

(defn- sh07-proof-transaction-thread-id
  []
  (.getId (Thread/currentThread)))

(defn- sh07-proof-transaction-artifact-root
  [stage artifact]
  (case stage
    :sh05
    {:artifact-id (:artifact-id artifact)
     :stream-id (:expanded-syntax-stream-id artifact)
     :trace-id (:macro-expansion-trace-id artifact)}

    :sh06
    {:artifact-id (:artifact-id artifact)
     :semantic-projection-id (:semantic-projection-id artifact)
     :alias-table-id (:alias-table-id artifact)}

    :sh07
    {:artifact-id (:artifact-id artifact)
     :semantic-projection-id
     (get-in artifact
             [:gravity-core-boundary :canonical-core-artifact
              :semantic-projection-id])}

    {:artifact-id (:artifact-id artifact)}))

(defn- sh07-proof-transaction-immutable-carrier?
  [value]
  (let [pending (java.util.ArrayDeque.)
        push! (fn [entry]
                (when-not (nil? entry) (.push pending entry)))]
    (push! value)
    (loop [visited 0]
      (cond
        (> visited 67108864) false
        (.isEmpty pending) true
        :else
        (let [current (.pop pending)
              metadata (when (instance? clojure.lang.IObj current)
                         (meta current))]
          (push! metadata)
          (cond
            (or (nil? current)
                (boolean? current)
                (instance? java.lang.Byte current)
                (instance? java.lang.Short current)
                (instance? java.lang.Integer current)
                (instance? java.lang.Long current)
                (instance? java.lang.Float current)
                (instance? java.lang.Double current)
                (instance? java.math.BigInteger current)
                (instance? java.math.BigDecimal current)
                (instance? clojure.lang.BigInt current)
                (instance? clojure.lang.Ratio current)
                (string? current)
                (keyword? current)
                (symbol? current)
                (char? current))
            (recur (inc visited))

            (instance? clojure.lang.LazySeq current)
            false

            (map? current)
            (do
              (doseq [[key entry-value] current]
                (push! key)
                (push! entry-value))
              (recur (inc visited)))

            (or (vector? current) (set? current) (list? current)
                (instance? clojure.lang.IMapEntry current))
            (do
              (doseq [entry current] (push! entry))
              (recur (inc visited)))

            :else false))))))

(defn- sh07-proof-transaction-context!
  []
  (when-let [context *sh07-proof-transaction-context*]
    (let [state @context]
      (when-not (and (:open? state)
                     (= (:owner-thread-id state)
                        (sh07-proof-transaction-thread-id)))
        (throw
         (ex-info "SH-07 proof transaction is closed or thread-confined"
                  {:id "C6-VERIFY"
                   :stage :sh07-proof-transaction
                   :reason (if (:open? state)
                             :cross-thread-access
                             :closed-transaction)})))
      context)))

(defn- sh07-proof-transaction-report
  [stage mode verifier-epoch artifact verify]
  (if-let [context (sh07-proof-transaction-context!)]
    (let [state @context
          phase (:phase state)
          root (sh07-proof-transaction-artifact-root stage artifact)
          catalog-key [stage mode]
          expected-catalog (get-in state [:check-catalogs catalog-key])
          receipt
          (some
           (fn [candidate]
             (when (and (= phase (:phase candidate))
                        (= stage (:stage candidate))
                        (= mode (:mode candidate))
                        (identical?
                         (:verifier-root verifier-epoch)
                         (get-in candidate [:verifier-epoch :verifier-root]))
                        (= (dissoc verifier-epoch :verifier-root)
                           (dissoc (:verifier-epoch candidate)
                                   :verifier-root))
                        (= expected-catalog
                           {:check-catalog (:check-catalog candidate)
                            :check-catalog-hash
                            (:check-catalog-hash candidate)})
                        (identical? artifact (:artifact candidate))
                        (= root (:artifact-root candidate)))
               candidate))
           (:receipts state))]
      (if receipt
        (do
          (swap! context update-in [:reuses stage] (fnil inc 0))
          (:report receipt))
        (let [report (verify)
              check-catalog (set (keys (:checks report)))
              check-catalog-hash
              (reader-canonical-hash
               {:domain (:check-catalog-domain verifier-epoch)
                :schema-version (:report-schema-version verifier-epoch)
                :checks (vec (sort check-catalog))})
              observed-catalog
              {:check-catalog check-catalog
               :check-catalog-hash check-catalog-hash}]
          (swap! context update-in [:executions stage] (fnil inc 0))
          (when (and expected-catalog
                     (not= expected-catalog observed-catalog))
            (throw
             (ex-info "SH-07 proof transaction verifier catalog changed"
                      {:id "C6-VERIFY"
                       :stage :sh07-proof-transaction
                       :reason :check-catalog-changed
                       :verifier-stage stage
                       :verifier-mode mode})))
          (swap! context update :check-catalogs
                 #(if (contains? % catalog-key)
                    %
                    (assoc % catalog-key observed-catalog)))
          (when-not (= :passed (:status report))
            (swap! context update :failed-report-executions (fnil inc 0)))
          (when (and (= :passed (:status report))
                     (sh07-proof-transaction-immutable-carrier? artifact)
                     (sh07-proof-transaction-immutable-carrier? report))
            (swap!
             context
             (fn [current]
               (when (>= (count (:receipts current))
                         (:maximum-receipts current))
                 (throw
                  (ex-info "SH-07 proof transaction receipt bound exceeded"
                           {:id "C6-VERIFY"
                            :stage :sh07-proof-transaction
                            :reason :maximum-receipts
                            :maximum (:maximum-receipts current)})))
               (update current :receipts conj
                       {:phase phase
                        :stage stage
                        :mode mode
                        :verifier-epoch verifier-epoch
                        :artifact artifact
                        :artifact-root root
                        :check-catalog check-catalog
                        :check-catalog-hash check-catalog-hash
                        :report report}))))
          report)))
    (verify)))

(defn sh05-macro-artifact-verification*
  [artifact allow-missing-proof?]
  (let [source-path (get-in artifact [:provenance :source-path])
        boundary (:gravity-macro-boundary artifact)
        c3-artifact (:authenticated-sh04-artifact boundary)
        c3-boundary (:gravity-syntax-boundary c3-artifact)
        gravity-verifiers
        (try
          (sh05-macro-gravity-verifier-report source-path boundary)
          (catch InterruptedException interrupted
            (.interrupt (Thread/currentThread))
            (throw interrupted))
          (catch Throwable _
            {:template {:status :failed}
             :resolved {:status :failed}}))
        output-envelope-ok?
        (try
          (= :passed
             (p15-s23-stage2-sh02-descriptor-envelope-verify!
              (:authenticated-envelope boundary)
              sh05-macro-envelope-stage sh05-macro-sealed-artifact-kind
              (:authenticated-envelope-descriptor boundary) source-path))
          (catch InterruptedException interrupted
            (.interrupt (Thread/currentThread))
            (throw interrupted))
          (catch Throwable _ false))
        binding (sh05-macro-current-binding! source-path)
        embedded-descriptor (:authenticated-envelope-descriptor boundary)
        expected-descriptor
        (try
          (sh05-macro-sh02-descriptor
           source-path binding (sh05-macro-envelope-summary artifact))
          (catch InterruptedException interrupted
            (.interrupt (Thread/currentThread))
            (throw interrupted))
          (catch Throwable _ nil))
        descriptor-current? (= expected-descriptor embedded-descriptor)
        sh03-current?
        (try
          (true?
           (c3-syntax-stream-reader-products-authentic?
            (:syntax-object-stream c3-artifact)
            (:c2-reader-artifact c3-artifact) c3-boundary))
          (catch InterruptedException interrupted
            (.interrupt (Thread/currentThread))
            (throw interrupted))
          (catch Throwable _ false))
        sh04-current?
        (try
          (and (= (:artifact-id c3-artifact) (c3-artifact-id c3-artifact))
               (= :complete (:status (c3-syntax-capability-proof c3-artifact))))
          (catch InterruptedException interrupted
            (.interrupt (Thread/currentThread))
            (throw interrupted))
          (catch Throwable _ false))
        template-passed?
        (= :passed (get-in gravity-verifiers [:template :status]))
        resolved-passed?
        (= :passed (get-in gravity-verifiers [:resolved :status]))
        runs (:expansion-runs boundary)
        input-forms
        (get-in c3-artifact [:c2-reader-artifact :parsed-semantic-values])
        input-syntax (sh05-source-syntax-stream c3-artifact)
        input-module (parse-module source-path input-forms)
        expected-expanded-stream
        (loop [forms input-forms
               syntaxes input-syntax
               remaining-runs runs
               result []]
          (if-let [form (first forms)]
            (let [syntax (first syntaxes)
                  run (when (sh05-defn-form? form) (first remaining-runs))]
              (recur (rest forms)
                     (rest syntaxes)
                     (if run (rest remaining-runs) remaining-runs)
                     (conj result
                           (sh05-expanded-syntax-object syntax form run))))
            (when (and (empty? syntaxes) (empty? remaining-runs))
              result)))
        expected-trace
        (mapv #(sh05-package-trace % (:profile input-module)
                                   (:target input-module))
              runs)
        first-run (first runs)
        first-run-shortcuts-current?
        (if first-run
          (= (select-keys
              boundary
              [:raw-template-result :resolved-expansion
               :digest-requests :resolved-digests])
             (select-keys
              first-run
              [:raw-template-result :resolved-expansion
               :digest-requests :resolved-digests]))
          (every? nil?
                  ((juxt :raw-template-result :resolved-expansion
                         :digest-requests :resolved-digests)
                   boundary)))
        run-count-current?
        (= (:expanded-defn-count artifact) (count runs))
        run-storage-exact?
        (every?
         (fn [run]
           (and
            (= #{:raw-template-result :digest-requests
                 :resolved-digests :resolved-expansion
                 :template-verification :resolved-verification}
               (set (keys run)))
            (= #{:artifact :schema-version :status :expansion-template}
               (set (keys (:raw-template-result run))))
            (= #{:artifact :schema-version :status :rule}
               (set (keys (:template-verification run))))
            (= #{:artifact :schema-version :status :rule}
               (set (keys (:resolved-verification run))))))
         runs)
        plan-binding-current?
        (= (select-keys
            (:plan-binding boundary)
            [:source-byte-count :source-content-hash :plan-semantic-hash
             :functions-semantic-hash :function-count :function-names-hash
             :function-shapes-hash :public-function-hashes
             :public-function-shapes])
           (select-keys
            binding
            [:source-byte-count :source-content-hash :plan-semantic-hash
             :functions-semantic-hash :function-count :function-names-hash
             :function-shapes-hash :public-function-hashes
             :public-function-shapes]))
        pinned-version?
        (every? #(= sh05-macro-version
                    (get-in % [:resolved-expansion :macro-version])) runs)
        grants-current?
        (every?
         (fn [run]
           (let [log (get-in run [:resolved-expansion :build-effect-log])]
             (and (set/subset? (set (:requested log))
                               (set (:declared log)))
                  (set/subset? (set (:declared log))
                               (set (:granted log))))))
         runs)
        trace-current?
        (and template-passed? resolved-passed?
             (= expected-trace (:macro-expansion-trace artifact))
             (= (:macro-expansion-trace-id artifact)
                (sh05-macro-trace-id
                 source-path (:macro-expansion-trace artifact))))
        output-current?
        (and template-passed? resolved-passed?
             (= expected-expanded-stream
                (:expanded-syntax-stream artifact))
             (= (:expanded-defn-count artifact) (count runs))
             (= (:expanded-forms artifact)
                (mapv :form
                      (subvec (:expanded-syntax-stream artifact) 1)))
             (= (:expanded-syntax-stream-id artifact)
                (sh05-expanded-syntax-stream-id
                 source-path (:expanded-syntax-stream artifact))))
        generated-origins-current?
        (= (:generated-origin-source-map artifact)
           (mapv #(select-keys % [:output-syntax-id :generated-origin])
                 (:macro-expansion-trace artifact)))
        input-lineage-current?
        (= (get-in artifact [:sh04-syntax-artifact :artifact-id])
           (:artifact-id c3-artifact))
        c3-syntax-by-id
        (into {} (map (juxt :syntax/id identity)
                      (:syntax-object-stream c3-artifact)))
        expected-reader-binding (:reader-semantic-binding c3-boundary)
        expected-reader-revision (:reader-source-revision c3-boundary)
        expected-definition-span
        {:source sh05-macro-source-relative-path
         :byte-start 0 :byte-end sh05-macro-expected-source-byte-count}
        run-provenance-current?
        (every?
         (fn [run]
           (let [raw-expansion
                 (get-in run [:raw-template-result :expansion-template])
                 resolved (:resolved-expansion run)
                 input-id (:input-syntax-id resolved)
                 input-syntax (get c3-syntax-by-id input-id)
                 raw-provenance (:provenance raw-expansion)
                 resolved-provenance (:provenance resolved)
                 digest-provenance
                 (get-in run [:digest-requests 1 :preimage :provenance])]
             (and input-syntax
                  (= source-path
                     (:actual-source-path raw-provenance)
                     (:actual-source-path resolved-provenance)
                     (:actual-source-path digest-provenance))
                  (= (:span input-syntax)
                     (:call-site-span raw-provenance)
                     (:call-site-span resolved-provenance)
                     (:call-site-span digest-provenance))
                  (= (:origin input-syntax)
                     (:input-origin-chain raw-provenance)
                     (:input-origin-chain resolved-provenance)
                     (:input-origin-chain digest-provenance))
                  (= expected-definition-span
                     (:definition-span raw-provenance)
                     (:definition-span resolved-provenance)
                     (:definition-span digest-provenance))
                  (= expected-reader-binding
                     (:reader-binding raw-expansion)
                     (:reader-binding resolved)
                     (:reader-binding raw-provenance)
                     (:reader-binding resolved-provenance)
                     (:reader-binding digest-provenance))
                  (= expected-reader-revision
                     (:reader-source-revision raw-expansion)
                     (:reader-source-revision resolved)
                     (:reader-source-revision raw-provenance)
                     (:reader-source-revision resolved-provenance)
                     (:reader-source-revision digest-provenance)))))
         runs)
        provenance-current?
        (and (= source-path (get-in artifact [:provenance :source-path]))
             (= (get-in c3-artifact
                        [:c2-reader-artifact :source-unit-record :source-id])
                (get-in artifact [:provenance :source-id])))
        graph-valid? (sh05-expanded-graph-valid?
                      (:expanded-syntax-graph artifact))
        graph-current?
        (= (:expanded-syntax-graph artifact)
           (sh05-expanded-graph (:expanded-syntax-stream artifact)
                                (:macro-expansion-trace artifact)))
        exact-shape?
        (and (= sh05-macro-artifact-keys (set (keys artifact)))
             template-passed? resolved-passed?)
        artifact-id-current?
        (= (:artifact-id artifact) (sh05-macro-artifact-id artifact))
        base-checks
        {:fresh-sh02-envelope-verified? output-envelope-ok?
         :sh02-envelope-descriptor-current? descriptor-current?
         :sh03-reader-lineage-current? sh03-current?
         :sh04-syntax-lineage-current? sh04-current?
         :macro-run-count-current? run-count-current?
         :macro-run-storage-exact? run-storage-exact?
         :first-run-compatibility-view-current? first-run-shortcuts-current?
         :macro-plan-binding-current? plan-binding-current?
         :macro-output-current? output-current?
         :generated-origins-current? generated-origins-current?
         :trace-replay-current? trace-current?
         :build-grants-current? grants-current?
         :macro-version-current? pinned-version?
         :input-lineage-current? input-lineage-current?
         :macro-run-provenance-current? run-provenance-current?
         :actual-path-provenance-current? provenance-current?
         :expanded-graph-valid? graph-valid?
         :expanded-graph-current? graph-current?
         :exact-artifact-shape? exact-shape?
         :artifact-id-current? artifact-id-current?}
        base-failed-checks
        (vec
         (keep (fn [[check-name passed?]]
                 (when-not passed?
                   (keyword
                    (str/replace (clojure.core/name check-name) #"\?$" ""))))
               base-checks))
        expected-embedded-proof
        (assoc base-checks
               :embedded-capability-proof-current? true
               :artifact :gravity/sh05-macro-capability-proof
               :status (if (empty? base-failed-checks) :complete :failed)
               :failed-checks base-failed-checks)
        embedded-proof-current?
        (or (and allow-missing-proof?
                 (nil? (:capability-based-proof artifact)))
            (= expected-embedded-proof (:capability-based-proof artifact)))
        checks
        (assoc base-checks
               :embedded-capability-proof-current?
               embedded-proof-current?)
        failed-checks
        (vec
         (keep (fn [[check-name passed?]]
                 (when-not passed?
                   (keyword
                    (str/replace (clojure.core/name check-name) #"\?$" ""))))
               checks))]
    {:artifact :gravity/sh05-macro-artifact-verification
     :status (if (empty? failed-checks) :passed :failed)
     :checks checks
     :failed-checks failed-checks
     :gravity-verifiers gravity-verifiers}))

(defn sh05-macro-artifact-verification
  [artifact]
  (sh07-proof-transaction-report
   :sh05 :final
   {:verifier-root
    (var-get #'sh05-macro-artifact-verification*)
    :report-schema-version 1
    :check-catalog-domain :gravity/sh05-final-verification-checks
    :source-content-hash sh05-macro-expected-source-content-hash
    :plan-semantic-hash sh05-macro-expected-plan-semantic-hash
    :functions-semantic-hash
    sh05-macro-expected-functions-semantic-hash}
   artifact
   #(sh05-macro-artifact-verification* artifact false)))

(defn sh05-macro-capability-based-proof-for-construction
  [artifact]
  (let [report
        (sh07-proof-transaction-report
         :sh05 :construction
         {:verifier-root
          (var-get #'sh05-macro-artifact-verification*)
          :report-schema-version 1
          :check-catalog-domain :gravity/sh05-construction-verification-checks
          :source-content-hash sh05-macro-expected-source-content-hash
          :plan-semantic-hash sh05-macro-expected-plan-semantic-hash
          :functions-semantic-hash
          sh05-macro-expected-functions-semantic-hash}
         artifact
         #(sh05-macro-artifact-verification* artifact true))
        checks (:checks report)]
    (assoc checks
           :artifact :gravity/sh05-macro-capability-proof
           :status (if (= :passed (:status report)) :complete :failed)
           :failed-checks (:failed-checks report))))

(defn sh05-macro-capability-based-proof
  [artifact]
  (let [report (sh05-macro-artifact-verification artifact)
        checks (:checks report)]
    (assoc checks
           :artifact :gravity/sh05-macro-capability-proof
           :status (if (= :passed (:status report)) :complete :failed)
           :failed-checks (:failed-checks report))))

(defn sh05-macro-source-artifact
  [source-path source-text]
  (let [c3-artifact
        (compiler-c3-syntax-source-artifact source-path source-text)
        _ (c3-syntax-validate! source-path c3-artifact)
        c2-artifact (:c2-reader-artifact c3-artifact)
        forms (:parsed-semantic-values c2-artifact)
        module (parse-module source-path forms)
        binding (sh05-macro-current-binding! source-path)
        source-syntax (sh05-source-syntax-stream c3-artifact)
        _ (when-not (= (count forms) (count source-syntax))
            (sh05-macro-boundary-fail!
             "C4-RETURN" source-path :complete-sh04-source-syntax-lockstep
             {:forms (count forms) :syntaxes (count source-syntax)} {}))
        compiler-metadata (get-in module [:metadata :compiler])
        request-overrides
        (if (and (map? compiler-metadata)
                 (contains? compiler-metadata :sh05-request))
          (:sh05-request compiler-metadata)
          {})
        _ (when-not (map? request-overrides)
            (sh05-macro-boundary-fail!
             "C4-RETURN" source-path :map-shaped-macro-request-overrides
             request-overrides
             {:observed-type (some-> request-overrides class .getName)}))
        pairs
        (mapv
         (fn [form syntax]
           (if (sh05-defn-form? form)
             (let [request
                   (sh05-deep-merge
                    (sh05-default-macro-request
                     source-path c3-artifact module syntax form)
                    request-overrides)]
               {:form form :syntax syntax
                :run (sh05-run-macro-request!
                      source-path binding request)})
             {:form form :syntax syntax :run nil}))
         forms source-syntax)
        runs (mapv :run (filter :run pairs))
        expanded-stream
        (mapv (fn [{:keys [syntax form run]}]
                (sh05-expanded-syntax-object syntax form run))
              pairs)
        ;; C4's compatibility projection is the expanded namespace body.  The
        ;; authenticated syntax stream retains the namespace declaration for
        ;; C5, while :expanded-forms matches the established stage0 boundary.
        expanded-forms (mapv :form (subvec expanded-stream 1))
        trace
        (mapv #(sh05-package-trace % (:profile module) (:target module))
              runs)
        stream-id
        (sh05-expanded-syntax-stream-id source-path expanded-stream)
        trace-id
        (sh05-macro-trace-id source-path trace)
        graph (sh05-expanded-graph expanded-stream trace)
        sh04-view
        {:artifact :gravity/sh04-syntax-object-artifact
         :artifact-id (:artifact-id c3-artifact)
         :status :accepted
         :syntax-stream-id
         (get-in c3-artifact
                 [:gravity-syntax-boundary :resolved-syntax-result
                  :artifact-id])}
        plan-binding (dissoc binding :plan :source-text)
        boundary-base
        {:slice :SH-05
         :owner :gravity-source
         :adapter-contract sh05-macro-adapter-contract
         :plan-binding plan-binding
         :authenticated-sh04-artifact c3-artifact
         :expansion-runs runs
         :raw-template-result (:raw-template-result (first runs))
         :resolved-expansion (:resolved-expansion (first runs))
         :digest-requests (:digest-requests (first runs))
         :resolved-digests (:resolved-digests (first runs))
         :target-source-reread? false
         :clojure-adapter-residual? true
         :self-hosted? false}
        artifact-base
        {:kind :gravity/sh05-macro-expansion-artifact
         :status :accepted
         :slice :SH-05
         :task "SH-05"
         :document-set ["L4" "C4"]
         :governing-document c4-macro-governing-document
         :artifact-id nil
         :expanded-syntax-stream-id stream-id
         :macro-expansion-trace-id trace-id
         :expanded-defn-count (count runs)
         :expanded-syntax-stream expanded-stream
         :expanded-forms expanded-forms
         :macro-expansion-trace trace
         :macro-environment
         {:artifact :gravity/sh05-macro-environment
          :macros [{:name 'defn :version sh05-macro-version
                    :phase :macro-expansion}]
          :status :complete}
         :generated-origin-source-map
         (mapv #(select-keys % [:output-syntax-id :generated-origin]) trace)
         :expanded-syntax-graph graph
         :sh04-syntax-artifact sh04-view
         :gravity-macro-boundary boundary-base
         :provenance {:source-path source-path
                      :source-id (get-in c2-artifact
                                         [:source-unit-record :source-id])}
         :pass {:name :sh05-gravity-macro-expansion
                :input :authenticated-sh04-syntax
                :output :authenticated-sh05-expanded-syntax
                :preserves [:syntax-identity :metadata :hygiene
                            :origins :reader-lineage]
                :rejects c4-macro-diagnostic-ids}
         :capability-based-proof nil
         :execution-boundary
         {:macro-authority :gravity
          :gravity-module 'gravity.macro
          :plan-runner :clojure-stage0
          :digest-resolver :clojure-stage0
          :envelope-binder :clojure-stage0
          :c4-stage0-adapter :compatibility-only
          :self-hosted? false}
         :diagnostics []}
        artifact-id (sh05-macro-artifact-id artifact-base)
        summary
        (sh05-macro-envelope-summary
         (assoc artifact-base :artifact-id artifact-id))
        descriptor
        (sh05-macro-sh02-descriptor source-path binding summary)
        envelope
        (p15-s23-stage2-sh02-descriptor-envelope
         sh05-macro-envelope-stage sh05-macro-sealed-artifact-kind
         descriptor source-path)
        _ (p15-s23-stage2-sh02-descriptor-envelope-verify!
           envelope sh05-macro-envelope-stage
           sh05-macro-sealed-artifact-kind descriptor source-path)
        artifact-with-envelope
        (-> artifact-base
            (assoc :artifact-id artifact-id)
            (assoc-in [:gravity-macro-boundary
                       :authenticated-envelope-descriptor] descriptor)
            (assoc-in [:gravity-macro-boundary
                       :authenticated-envelope] envelope))
        proof
        (sh05-macro-capability-based-proof-for-construction
         artifact-with-envelope)
        artifact (assoc artifact-with-envelope :capability-based-proof proof)
        final-report (sh05-macro-artifact-verification artifact)]
    (when-not (= :passed (:status final-report))
      (sh05-macro-boundary-fail!
       "C4-TRACE" source-path :final-authenticated-macro-artifact
       (:failed-checks final-report) {}))
    artifact))

(defn sh05-macro-file-artifact
  [source-path]
  (let [c2-artifact (compiler-c2-reader-file-artifact source-path)
        source-text (c2-reader-artifact-source-text source-path c2-artifact)]
    (sh05-macro-source-artifact source-path source-text)))

;; Preserve the broader stage0 user-macro oracle outside SH-05 credit.  The
;; public C4 compatibility entrypoint uses Gravity for the compiler-required
;; defn subset and falls back only for source that actually defines user macros.
(def compiler-c4-stage0-legacy-source-artifact
  compiler-c4-macro-source-artifact)

(defn sh05-c4-compatibility-identity-input
  [artifact]
  {:domain :gravity/sh05-c4-compatibility-artifact-v1
   :kind (:kind artifact)
   :task (:task artifact)
   :document-set (:document-set artifact)
   :governing-document (:governing-document artifact)
   :sh05-artifact-id
   (get-in artifact [:sh05-macro-expansion-artifact :artifact-id])
   :macro-expansion-input (:macro-expansion-input artifact)
   :macro-environment (:macro-environment artifact)
   :expanded-syntax-stream-id
   (get-in artifact
           [:sh05-macro-expansion-artifact :expanded-syntax-stream-id])
   :macro-expansion-trace-id
   (get-in artifact
           [:sh05-macro-expansion-artifact :macro-expansion-trace-id])
   :hygiene-capture-records (:hygiene-capture-records artifact)
   :build-effect-log (:build-effect-log artifact)
   :macro-safety-declarations (:macro-safety-declarations artifact)
   :capability-based-proof (:capability-based-proof artifact)
   :execution-boundary (:execution-boundary artifact)
   :diagnostics (:diagnostics artifact)})

(defn sh05-c4-compatibility-artifact-id
  [artifact]
  (reader-canonical-hash (sh05-c4-compatibility-identity-input artifact)))

(defn sh05-c4-compatibility-artifact
  [source-path sh05]
  (let [artifact-base
        {:kind :gravity/stage0-c4-macro-expansion-artifact
         :task "P06-D083"
         :document-set ["C4"]
         :governing-document c4-macro-governing-document
         :sh05-macro-expansion-artifact sh05
         :c3-syntax-object-artifact (:sh04-syntax-artifact sh05)
         :macro-expansion-input
         {:artifact :gravity/macro-expansion-input
          :syntax-root (get-in sh05
                               [:sh04-syntax-artifact :syntax-stream-id])
          :profile :meta :target :jvm :hermetic true}
         :macro-environment (:macro-environment sh05)
         :expanded-syntax-stream (:expanded-syntax-stream sh05)
         :macro-expansion-trace (:macro-expansion-trace sh05)
         :generated-origin-source-map (:generated-origin-source-map sh05)
         :hygiene-capture-records []
         :build-effect-log {:artifact :gravity/macro-build-effect-log
                            :records [] :status :complete}
         :macro-safety-declarations
         {:artifact :gravity/macro-safety-declaration-records
          :records [] :status :complete}
         :capability-based-proof (:capability-based-proof sh05)
         :execution-boundary
         {:macro-authority :gravity
          :c4-stage0-adapter :compatibility-only
          :target-source-reread? false
          :self-hosting-credit? false}
         :diagnostics []}
        artifact-id (sh05-c4-compatibility-artifact-id artifact-base)]
    (assoc artifact-base :artifact-id artifact-id)))

(defn sh05-authoritative-compiler-source-path?
  [source-path]
  (let [anchor (io/file (sh05-macro-resolve-source-path))
        repository-root
        (loop [directory (.getParentFile anchor)]
          (cond
            (nil? directory) nil
            (.isFile (io/file directory "deps.edn")) directory
            :else (recur (.getParentFile directory))))
        root
        (.toPath
         (.getCanonicalFile
          (io/file (or repository-root (io/file "."))
                   "bootstrap/gravity/src")))
        candidate (.toPath (.getCanonicalFile (io/file source-path)))]
    (.startsWith candidate root)))

(defn sh05-form-contains-legacy-macro-position?
  [form]
  (cond
    (seq? form)
    (or (contains? '#{when -> defmacro} (first form))
        (some sh05-form-contains-legacy-macro-position? form))

    (map? form)
    (some sh05-form-contains-legacy-macro-position?
          (mapcat identity form))

    (coll? form)
    (some sh05-form-contains-legacy-macro-position? form)

    :else false))

(defn sh05-bounded-authoritative-source?
  [source-path module forms]
  (and (sh05-authoritative-compiler-source-path? source-path)
       (empty? (:requires module))
       (empty? (:imports module))
       (every?
        (fn [form]
          (and (seq? form)
               (contains? '#{ns def defn} (first form))))
        forms)
       (not-any? sh05-form-contains-legacy-macro-position? forms)))

(defn compiler-c4-macro-source-artifact
  [source-path source-text]
  (let [c2 (compiler-c2-reader-source-artifact source-path source-text)
        forms (:parsed-semantic-values c2)
        module (parse-module source-path forms)]
    (if (sh05-bounded-authoritative-source? source-path module forms)
      (sh05-c4-compatibility-artifact
       source-path (sh05-macro-source-artifact source-path source-text))
      (compiler-c4-stage0-legacy-source-artifact source-path source-text))))

;; SH-06 normalizes the verified SH-05 syntax product into the exact bounded
;; request accepted by gravity.resolution.  This remains coordinator-owned
;; transport code: resolution policy and result construction live in Gravity.
(def sh06-resolution-special-symbols
  '#{quote if do let loop recur fn def defn defconst var set! try catch
     finally throw match new syntax-quote unquote splice-unquote unsafe})

(def sh06-resolution-core-symbols
  '#{= not not= identical? < > <= >= + - * / mod quot rem inc dec min max
     zero? pos? neg? compare
     get get-in assoc assoc-in update update-in dissoc select-keys merge
     merge-with conj disj into empty count first second last rest next nth
     peek pop take drop take-while drop-while subvec vec vector list hash-map
     set sorted-map sorted-set keys vals contains? find
     nil? some? true? false? boolean? symbol? keyword? string? char? number?
     integer? ratio? map? vector? set? seq? coll? sequential? empty? seq
     map mapv map-indexed filter filterv remove keep keep-indexed reduce
     reduce-kv some every? not-any? concat mapcat partition partition-all
     range repeat repeatedly iterate zipmap frequencies group-by sort sort-by
     sort-by-pr-str distinct reverse identity constantly comp complement
     partial juxt apply
     name namespace symbol keyword str subs pr-str println format hash
     bit-and bit-or bit-xor bit-not bit-shift-left bit-shift-right
     numerator denominator meta with-meta vary-meta atom deref reset! swap!
     volatile! vreset! vswap! ex-info ex-data
     read-string slurp spit load-file resolve ns-resolve
     agent send send-off await promise deliver future future-call
     realized? delay force time rand rand-int
     transient persistent! conj! assoc! dissoc! pop!
     bigint bigdec double float long int short byte boolean
     even? odd? abs gcd lcm
     starts-with? ends-with? includes? split join replace trim lower-case
     upper-case blank?
     uuid random-uuid inst? uuid? tagged-literal
     type class instance? satisfies? extends?})

(def sh06-resolution-type-symbols
  '#{I8 I16 I32 I64 U8 U16 U32 U64 F32 F64 Bool String Symbol Keyword
     Dynamic Unit Never Any Object Class Throwable Exception RuntimeException
     Map Vector Set List Seq Fn Ratio BigInt BigDecimal})

(def sh06-resolution-all-core-symbols
  (set/union sh06-resolution-special-symbols
             sh06-resolution-core-symbols
             sh06-resolution-type-symbols))

(defn sh06-resolution-semantic-span
  [span ordinal]
  (merge
   {:ordinal ordinal}
   (select-keys (or span {})
                [:byte-start :byte-end :line-start :column-start
                 :line-end :column-end :scalar-start :scalar-end])))

(defn sh06-resolution-source-revision-id
  [sh05-artifact]
  (or (get-in sh05-artifact
              [:gravity-macro-boundary :authenticated-sh04-artifact
               :gravity-syntax-boundary :reader-source-revision :revision-id])
      (get-in sh05-artifact
              [:gravity-macro-boundary :authenticated-sh04-artifact
               :c2-reader-artifact :source-unit-record :source-id])
      (reader-canonical-hash
       {:domain :gravity/sh06-upstream-source-revision-v1
        :syntax-stream-id (:expanded-syntax-stream-id sh05-artifact)
        :macro-trace-id (:macro-expansion-trace-id sh05-artifact)})))

(defn sh06-resolution-envelope-id
  [sh05-artifact]
  (or (get-in sh05-artifact
              [:gravity-macro-boundary :authenticated-envelope
               :semantic-envelope-id])
      (reader-canonical-hash
       {:domain :gravity/sh06-upstream-envelope-reference-v1
        :artifact-id (:artifact-id sh05-artifact)
        :syntax-stream-id (:expanded-syntax-stream-id sh05-artifact)
        :macro-trace-id (:macro-expansion-trace-id sh05-artifact)})))

(defn sh06-resolution-package
  [namespace]
  {:name (symbol (str namespace)) :version "workspace"})

(defn sh06-resolution-definition-kind
  [form]
  (let [operator (when (seq? form) (first form))
        value (when (and (seq? form) (> (count form) 2)) (nth form 2))]
    (case operator
      defconst :compile-time-constant
      defn :function
      defmacro :macro
      defschema :schema
      defprotocol :protocol
      def (if (and (seq? value) (= 'fn (first value))) :function :var)
      nil)))

(defn sh06-resolution-definition-records
  [module sh05-artifact]
  (let [exports (set (:exports module))
        module-namespace (:module module)
        artifact-id (:artifact-id sh05-artifact)]
    (->> (:expanded-syntax-stream sh05-artifact)
         (map-indexed
          (fn [ordinal syntax]
            (let [form (:form syntax)
                  kind (sh06-resolution-definition-kind form)
                  declared-name (when kind (second form))]
              (when (and kind (symbol? declared-name))
                (let [simple-name (clojure.core/symbol (name declared-name))
                      declared-namespace
                      (some-> (namespace declared-name) clojure.core/symbol)
                      binding-namespace
                      (or declared-namespace module-namespace)]
                 {:name simple-name
                 :kind kind
                 :namespace binding-namespace
                 :package (sh06-resolution-package binding-namespace)
                 :binding-class :namespace
                 :visibility (if (or (contains? exports declared-name)
                                     (contains? exports simple-name))
                               :public
                               :private)
                 :profile-set [(:profile module)]
                 :target-set [(:target module)]
                 :type-ref (case kind
                             :function :gravity.type/function
                             :macro :gravity.syntax/macro
                             :schema :gravity.type/schema
                             :protocol :gravity.type/protocol
                             :gravity.type/value)
                 :effects (vec (sort (:effects module)))
                 :capabilities (vec (sort (:capabilities module)))
                 :safety (:safety module)
                 :semantic-span
                 (sh06-resolution-semantic-span (:span syntax) ordinal)
                 :source-span (:span syntax)
                 :definition-syntax-id (:syntax/id syntax)
                 :definition-artifact-id artifact-id})))))
         (remove nil?)
         vec)))

(defn sh06-resolution-core-record
  [symbol kind ordinal]
  {:name symbol
   :kind kind
   :namespace 'gravity.core
   :package {:name 'gravity/core :version "bootstrap-contract-v1"}
   :binding-class :core
   :visibility :public
   :profile-set (vec (sort known-source-profiles))
   :target-set [:all]
   :type-ref (case kind
               :special-form :gravity.syntax/special-form
               :type :gravity.type/type
               :gravity.type/core-var)
   :effects (if (= symbol 'println) [:io/write] [])
   :capabilities (if (= symbol 'println) [:io/stdout] [])
   :safety :safe
   :semantic-span {:catalog :gravity/core :ordinal ordinal}
   :source-span {:source "gravity.core" :form-index ordinal}
   :definition-syntax-id
   (reader-canonical-hash
    {:domain :gravity/sh06-core-binding-syntax-v1
     :name symbol :kind kind})
   :definition-artifact-id
   (reader-canonical-hash
    {:domain :gravity/sh06-core-catalog-v1
     :catalog-version 1})})

(defn sh06-resolution-core-records
  []
  (mapv
   (fn [ordinal symbol]
     (sh06-resolution-core-record
      symbol
      (cond
        (contains? sh06-resolution-special-symbols symbol) :special-form
        (contains? sh06-resolution-type-symbols symbol) :type
        :else :var)
      ordinal))
   (range)
   (sort sh06-resolution-all-core-symbols)))

(defn sh06-resolution-request-overrides
  [module]
  (let [candidate (get-in module [:metadata :compiler :sh06-request])]
    (if (map? candidate) candidate {})))

(defn sh06-resolution-candidate-for
  [overrides namespace name]
  (first
   (filter
    #(and (= namespace (:namespace %)) (= name (:name %)))
    (:candidate-bindings overrides))))

(defn sh06-resolution-dependency-record
  [source-path module dependency overrides ordinal]
  (let [namespace (:module dependency)
        alias (:alias dependency)
        referred (vec (:refer dependency))
        candidate
        (or (first (filter #(= namespace (:namespace %))
                           (:candidate-bindings overrides)))
            {})
        declared-target (or (:target candidate)
                            (first (:target-set candidate)))
        targets (if declared-target
                  [declared-target]
                  [(:target module)])
        foreign? (= :import (:kind dependency))
        semantic-span {:dependency-ordinal ordinal
                       :namespace namespace
                       :alias alias}]
    {:namespace namespace
     :alias alias
     :kind (if foreign? :foreign :namespace)
     :profile (or (:profile dependency) (:profile module))
     :targets targets
     :visibility (or (:visibility candidate)
                     (:visibility dependency) :public)
     :refer referred
     :effects (vec (sort (:effects dependency)))
     :capabilities (vec (sort (or (:capabilities candidate)
                                  (:capabilities dependency))))
     :safety (if foreign? :boundary-checked :safe)
     :boundary (or (:boundary dependency)
                   (when (= :core (:profile dependency)) :pure-core-api))
     :semantic-span semantic-span
     :source-span (source-span source-path 0)
     :dependency-artifact-id
     (reader-canonical-hash
      {:domain :gravity/sh06-dependency-artifact-v1
       :namespace namespace :profile (:profile dependency)
       :targets targets :boundary (:boundary dependency)})
     :foreign-record-complete?
     (if foreign?
       (and (symbol? namespace) (symbol? alias)
            (some? (:boundary dependency)))
       true)}))

(defn sh06-resolution-import-records
  [source-path module overrides]
  (mapv
   (fn [ordinal dependency]
     (sh06-resolution-dependency-record
      source-path module dependency overrides ordinal))
   (range)
   (concat (:requires module) (:imports module))))

(defn sh06-resolution-import-binding-records
  [module imports overrides]
  (vec
   (mapcat
    (fn [ordinal dependency]
      (let [explicit
            (filter #(= (:namespace dependency) (:namespace %))
                    (:candidate-bindings overrides))
            names (distinct
                   (concat (:refer dependency)
                           (map :name explicit)))
            candidates-by-name (group-by :name explicit)]
        (map-indexed
         (fn [name-ordinal name]
           (let [candidate (first (get candidates-by-name name))]
             {:name name
              :kind (if (= :foreign (:kind dependency)) :foreign :var)
              :namespace (:namespace dependency)
              :package (sh06-resolution-package (:namespace dependency))
              :binding-class :import
              :visibility (or (:visibility candidate)
                              (:visibility dependency) :public)
              :profile-set [(:profile dependency)]
              :target-set (or (some-> candidate :target-set vec)
                              (:targets dependency))
              :type-ref (if (= :foreign (:kind dependency))
                          :gravity.interop/foreign-value
                          :gravity.type/imported-var)
              :effects (:effects dependency)
              :capabilities (or (some-> candidate :capabilities vec)
                                (:capabilities dependency))
              :safety (:safety dependency)
              :semantic-span {:dependency-ordinal ordinal
                              :binding-ordinal name-ordinal
                              :namespace (:namespace dependency)
                              :name name}
              :source-span (:source-span dependency)
              :definition-syntax-id
              (reader-canonical-hash
               {:domain :gravity/sh06-import-binding-syntax-v1
                :dependency-id (:dependency-artifact-id dependency)
                :name name})
              :definition-artifact-id
              (:dependency-artifact-id dependency)}))
         names)))
    (range)
    imports)))

(defn sh06-resolution-explicit-candidate-records
  [module sh05-artifact overrides]
  (let [existing-import-names
        (set (mapcat :refer (concat (:requires module) (:imports module))))]
    (->> (:candidate-bindings overrides)
         (remove #(contains? existing-import-names (:name %)))
         (map-indexed
          (fn [ordinal candidate]
            {:name (:name candidate)
             :kind (or (:kind candidate) :var)
             :namespace (or (:namespace candidate) (:module module))
             :package (sh06-resolution-package
                       (or (:namespace candidate) (:module module)))
             :binding-class :namespace
             :visibility (or (:visibility candidate) :public)
             :profile-set [(or (:profile candidate) (:profile module))]
             :target-set (vec (or (:target-set candidate)
                                  [(:target module)]))
             :type-ref :gravity.type/value
             :effects (vec (or (:effects candidate) []))
             :capabilities (vec (or (:capabilities candidate) []))
             :safety :safe
             :semantic-span {:explicit-candidate ordinal
                             :name (:name candidate)
                             :namespace (:namespace candidate)}
             :source-span (source-span (:source-path module) 0)
             :definition-syntax-id
             (reader-canonical-hash
              {:domain :gravity/sh06-explicit-candidate-v1
               :ordinal ordinal :candidate candidate})
             :definition-artifact-id
             (reader-canonical-hash
              {:domain :gravity/sh06-explicit-candidate-artifact-v1
               :owner-artifact-id (:artifact-id sh05-artifact)
               :ordinal ordinal
               :candidate candidate})}))
         vec)))

(defn sh06-match-pattern-binding-paths
  [pattern path]
  (cond
    (and (symbol? pattern)
         (not= '_ pattern)
         (not= '& pattern))
    [{:name pattern :path path}]

    (vector? pattern)
    (vec
     (mapcat
      (fn [index item]
        (sh06-match-pattern-binding-paths
         item (conj path index)))
      (range)
      pattern))

    :else
    []))

(defn sh06-fixed-vector-pattern?
  [pattern]
  (cond
    (vector? pattern)
    (every? sh06-fixed-vector-pattern? pattern)

    (symbol? pattern)
    (not= '& pattern)

    :else
    (or (nil? pattern)
        (true? pattern)
        (false? pattern)
        (number? pattern)
        (char? pattern)
        (string? pattern)
        (keyword? pattern))))

(defn sh06-unique-match-binding-paths
  [pattern path]
  (let [binding-paths
        (sh06-match-pattern-binding-paths pattern path)
        names (mapv :name binding-paths)]
    (when (= (count names) (count (set names)))
      binding-paths)))

(defn sh06-resolution-analysis-inputs
  [module sh05-artifact overrides]
  (let [scopes (atom [])
        references (atom [])
        next-scope (atom 0)
        next-reference (atom 0)
        shadow-forbidden (set (get-in overrides [:shadow-policy :forbidden]))
        add-reference!
        (fn [symbol scope-chain syntax position span]
          (when (symbol? symbol)
            (let [ordinal (swap! next-reference inc)
                  namespace-part (namespace symbol)
                  simple-name (clojure.core/symbol (name symbol))]
              (swap!
               references conj
               {:syntax-id
                (reader-canonical-hash
                 {:domain :gravity/sh06-reference-syntax-v1
                  :owner-syntax-id (:syntax/id syntax)
                  :ordinal ordinal :symbol symbol :position position})
                :symbol symbol
                :qualifier (when namespace-part
                             (clojure.core/symbol namespace-part))
                :name simple-name
                :position position
                :scope-chain (vec scope-chain)
                :semantic-span
                (sh06-resolution-semantic-span span ordinal)
                :source-span span}))))
        add-scope!
        (fn [owner-syntax-id parent-scope-id local-names span]
          (let [ordinal (swap! next-scope inc)
                scope-id
                (reader-canonical-hash
                 {:domain :gravity/sh06-lexical-scope-v1
                  :owner-syntax-id owner-syntax-id
                  :ordinal ordinal
                  :parent-scope-id parent-scope-id})
                bindings
                (mapv
                 (fn [binding-ordinal name]
                   {:name name
                    :kind :local
                    :semantic-span
                    {:scope-ordinal ordinal
                     :binding-ordinal binding-ordinal}
                    :source-span span
                    :binding-syntax-id
                    (reader-canonical-hash
                     {:domain :gravity/sh06-local-binding-v1
                      :scope-id scope-id :ordinal binding-ordinal
                      :name name})
                    :allow-shadow?
                    (not (contains? shadow-forbidden name))})
                 (range)
                 local-names)]
            (swap! scopes conj
                   {:scope-id scope-id
                    :parent-scope-id parent-scope-id
                    :owner-syntax-id owner-syntax-id
                    :bindings bindings})
            scope-id))]
    (letfn [(parameter-names [parameters]
              (loop [remaining
                     (seq (if (sequential? parameters) parameters []))
                     names []]
                (if (empty? remaining)
                  names
                  (let [item (first remaining)]
                    (cond
                      (= item ':-) (recur (nnext remaining) names)
                      (= item '&) (recur (next remaining) names)
                      (symbol? item) (recur (next remaining)
                                            (conj names item))
                      :else (recur (next remaining) names))))))
            (walk-form [value scope-chain syntax position]
              (cond
                (symbol? value)
                (add-reference! value scope-chain syntax position
                                (:span syntax))

                (seq? value)
                (let [operator (first value)]
                  (cond
                    (= operator 'quote)
                    (add-reference! 'quote scope-chain syntax :operator
                                    (:span syntax))

                    (contains? '#{syntax-quote} operator)
                    (add-reference! operator scope-chain syntax :operator
                                    (:span syntax))

                    (contains? '#{def defconst} operator)
                    (do
                      (add-reference! operator scope-chain syntax :operator
                                      (:span syntax))
                      (doseq [item (drop 2 value)]
                        (walk-form item scope-chain syntax :expression)))

                    (= operator 'defn)
                    (let [parameters (nth value 2 [])
                          names (parameter-names parameters)
                          scope-id (add-scope! (:syntax/id syntax)
                                               (first scope-chain)
                                               names (:span syntax))]
                      (add-reference! 'defn scope-chain syntax :operator
                                      (:span syntax))
                      (doseq [item (drop 3 value)]
                        (walk-form item (cons scope-id scope-chain)
                                   syntax :expression)))

                    (= operator 'fn)
                    (let [named? (symbol? (second value))
                          parameters (if named? (nth value 2 [])
                                         (second value))
                          body (if named? (drop 3 value) (drop 2 value))
                          names (cond-> (parameter-names parameters)
                                  named? (conj (second value)))
                          scope-id (add-scope! (:syntax/id syntax)
                                               (first scope-chain)
                                               names (:span syntax))]
                      (add-reference! 'fn scope-chain syntax :operator
                                      (:span syntax))
                      (doseq [item body]
                        (walk-form item (cons scope-id scope-chain)
                                   syntax :expression)))

                    (= operator 'match)
                    (do
                      (add-reference! 'match scope-chain syntax :operator
                                      (:span syntax))
                      (when-let [scrutinee (second value)]
                        (walk-form scrutinee scope-chain syntax :expression))
                      (doseq [[pattern branch]
                              (partition 2 (drop 2 value))]
                        (cond
                          (and (symbol? pattern) (not= '_ pattern))
                          (let [scope-id
                                (add-scope!
                                 (:syntax/id syntax)
                                 (first scope-chain)
                                 [pattern] (:span syntax))]
                            (walk-form branch
                                       (cons scope-id scope-chain)
                                       syntax :expression))

                          (and (vector? pattern)
                               (sh06-fixed-vector-pattern? pattern))
                          (when-let
                              [binding-paths
                               (sh06-unique-match-binding-paths
                                pattern [])]
                            (if (empty? binding-paths)
                              (walk-form branch scope-chain syntax
                                         :expression)
                              (let [scope-id
                                    (add-scope!
                                     (:syntax/id syntax)
                                     (first scope-chain)
                                     (mapv :name binding-paths)
                                     (:span syntax))]
                                (walk-form branch
                                           (cons scope-id scope-chain)
                                           syntax :expression))))

                          (or (= '_ pattern)
                              (nil? pattern)
                              (true? pattern)
                              (false? pattern)
                              (number? pattern)
                              (char? pattern)
                              (string? pattern)
                              (keyword? pattern))
                          (walk-form branch scope-chain syntax :expression)

                          :else nil)))

                    (= operator 'try)
                    (do
                      (add-reference! 'try scope-chain syntax :operator
                                      (:span syntax))
                      (doseq [item (rest value)]
                        (cond
                          (and (seq? item) (= 'catch (first item)))
                          (do
                            (add-reference!
                             'catch scope-chain syntax :operator
                             (:span syntax))
                            (when-let [error-type (second item)]
                              (walk-form error-type scope-chain syntax :type))
                            (let [binding-name (nth item 2 nil)]
                              (when (symbol? binding-name)
                                (let [scope-id
                                      (add-scope!
                                       (:syntax/id syntax)
                                       (first scope-chain)
                                       [binding-name] (:span syntax))
                                      nested (cons scope-id scope-chain)]
                                  (doseq [handler-form (drop 3 item)]
                                    (walk-form handler-form nested syntax
                                               :expression))))))

                          (and (seq? item) (= 'finally (first item)))
                          (do
                            (add-reference!
                             'finally scope-chain syntax :operator
                             (:span syntax))
                            (doseq [cleanup-form (rest item)]
                              (walk-form cleanup-form scope-chain syntax
                                         :expression)))

                          :else
                          (walk-form item scope-chain syntax :expression))))

                    (contains? '#{let loop} operator)
                    (let [binding-vector (second value)
                          pairs
                          (if (vector? binding-vector)
                            (partition 2 binding-vector)
                            [])
                          _ (add-reference! operator scope-chain syntax
                                            :operator (:span syntax))
                          nested
                          (loop [remaining pairs
                                 active-scope-chain scope-chain]
                            (if (empty? remaining)
                              active-scope-chain
                              (let [[binding-name initializer]
                                    (first remaining)
                                    _ (walk-form initializer
                                                 active-scope-chain syntax
                                                 :expression)
                                    next-scope-chain
                                    (if (symbol? binding-name)
                                      (let [scope-id
                                            (add-scope!
                                             (:syntax/id syntax)
                                             (first active-scope-chain)
                                             [binding-name] (:span syntax))]
                                        (cons scope-id active-scope-chain))
                                      active-scope-chain)]
                                (recur (next remaining)
                                       next-scope-chain))))]
                      (doseq [item (drop 2 value)]
                        (walk-form item nested syntax :expression)))

                    :else
                    (doseq [[index item] (map-indexed vector value)]
                      (walk-form item scope-chain syntax
                                 (if (zero? index)
                                   :operator
                                   position)))))

                (map? value)
                (doseq [[key item] value]
                  (walk-form key scope-chain syntax :expression)
                  (walk-form item scope-chain syntax :expression))

                (coll? value)
                (doseq [item value]
                  (walk-form item scope-chain syntax position))

                :else nil))]
      (doseq [syntax (:expanded-syntax-stream sh05-artifact)]
        (let [form (:form syntax)]
          (when-not (and (seq? form) (= 'ns (first form)))
            (walk-form form [] syntax :expression))))
      {:lexical-scopes @scopes :references @references})))

(defn sh06-resolution-dependency-edges
  [source-path module imports overrides]
  (let [base
        (mapv
         (fn [ordinal dependency]
           {:from (:module module)
            :to (:namespace dependency)
            :kind (:kind dependency)
            :boundary (:boundary dependency)
            :semantic-span {:dependency-edge ordinal}
            :source-span (:source-span dependency)})
         (range) imports)
        explicit (get-in overrides [:module-graph :edges])]
    (vec
     (distinct
      (concat
       base
       (map-indexed
        (fn [ordinal edge]
          (let [[from to] (when (vector? edge) edge)]
            {:from (or (:from edge) from)
             :to (or (:to edge) to)
             :kind (or (:kind edge) :namespace)
             :boundary (:boundary edge)
             :semantic-span {:explicit-edge ordinal}
             :source-span (source-span source-path 0)}))
        explicit))))))

(defn sh06-resolution-request
  [source-path sh05-artifact]
  (let [verification (sh05-macro-artifact-verification sh05-artifact)
        _ (when-not (= :passed (:status verification))
            (c5-resolution-fail!
             "C5-UNRESOLVED" source-path
             {:stage :name-resolution}
             {:missing-fields [:verified-sh05-macro-artifact]}))
        forms (mapv :form (:expanded-syntax-stream sh05-artifact))
        module (parse-module source-path forms)
        overrides (sh06-resolution-request-overrides module)
        imports (sh06-resolution-import-records
                 source-path module overrides)
        explicit-definitions
        (sh06-resolution-explicit-candidate-records
         module sh05-artifact overrides)
        analysis-inputs
        (sh06-resolution-analysis-inputs
         module sh05-artifact overrides)
        source-revision-id
        (sh06-resolution-source-revision-id sh05-artifact)]
    {:artifact :gravity/sh06-authenticated-c4-resolution-request
     :schema-version 1
     :module
     {:namespace (:module module)
      :package (sh06-resolution-package (:module module))
      :profile (:profile module)
      :target (:target module)
      :safety (:safety module)
      :effects (vec (sort (:effects module)))
      :capabilities (vec (sort (:capabilities module)))
      :exports (vec (:exports module))
      :source-revision-id source-revision-id
      :c4-artifact-id (:artifact-id sh05-artifact)}
     :definitions
     (vec (concat
           (sh06-resolution-definition-records module sh05-artifact)
           explicit-definitions))
     :imports imports
     :import-bindings
     (sh06-resolution-import-binding-records module imports overrides)
     :lexical-scopes (:lexical-scopes analysis-inputs)
     :references (:references analysis-inputs)
     :core-bindings (sh06-resolution-core-records)
     :dependency-edges
     (sh06-resolution-dependency-edges source-path module imports overrides)
     :macro-expansion-binding
     {:artifact :gravity/sh05-macro-expansion-binding
      :schema-version 1
      :c4-artifact-id (:artifact-id sh05-artifact)
      :source-revision-id source-revision-id
      :macro-result-id (:expanded-syntax-stream-id sh05-artifact)
      :authenticated-envelope-id
      (sh06-resolution-envelope-id sh05-artifact)}
     :provenance {:actual-source-path source-path}}))

(def sh06-resolution-source-relative-path
  "bootstrap/gravity/src/gravity/resolution.gravity")
(def sh06-resolution-facade-relative-path
  "bootstrap/gravity/src/gravity/compiler/c5_name_resolution_namespace_analyzer.gravity")
(def sh06-resolution-adapter-contract
  :gravity/sh06-to-c5-resolution-products-v1)
(def sh06-resolution-envelope-stage :c5-resolution)
(def sh06-resolution-sealed-artifact-kind
  :gravity/sh06-resolution-products)

;; Final source/plan pins are filled only after the leaf's semantic matrix is
;; stable.  A nil pin is rejected, so an in-progress leaf cannot accidentally
;; receive integration credit.
(def sh06-resolution-expected-source-byte-count 77209)
(def sh06-resolution-expected-source-content-hash
  "sha256:001ef59741f17b98b37ee5bdb21e698cb1e6e56ce76c5f5fdd5f1fc9a4caeb56")
(def sh06-resolution-expected-plan-semantic-hash
  "sha256:ba8c292ffe3c703bbc220af0a7121496c134793d1e80a012f6fb0a0d9dc6b6fa")
(def sh06-resolution-expected-functions-semantic-hash
  "sha256:a1445872cda26a9aa0fb8959165eada593619de7a03f527a8ea8a8c216237b91")
(def sh06-resolution-expected-function-count 94)
(def sh06-resolution-expected-function-names-hash
  "sha256:1a12e29aea416d4df7c2904d366975ce240f5ecaee0b2b9c5aa95b1aa83d1ba4")
(def sh06-resolution-expected-function-shapes-hash
  "sha256:62aec401ab663019a10b63c1b91487f70b9756503d59e43879283afae8c02f57")
(def sh06-resolution-public-function-hashes
  {'sh06-build-resolution-template
   "sha256:154d52c95bc0488e5ec302ce9219b57d72995f5f54f137816ca980d97bf71f38"
   'sh06-verify-resolution-template
   "sha256:de579ce14c12644979fe636d5f7b32d02c505753b85463b8a1994eb9de7a03ec"
   'sh06-verify-resolution-resolved
   "sha256:80e3c1e5313ffb38805eba60110dc80edccb50218eaabd5edba98b2025e99342"})
(def sh06-resolution-public-function-shapes
  {'sh06-build-resolution-template {:arity 1 :params ['request]}
   'sh06-verify-resolution-template
   {:arity 2 :params ['analysis 'digest-requests]}
   'sh06-verify-resolution-resolved
   {:arity 3
    :params ['analysis 'digest-requests 'resolved-digests]}})

(defn sh06-resolution-boundary-fail!
  [rule source-path missing-field observed facts]
  (c5-resolution-fail!
   rule source-path
   {:source-span (source-span source-path 0)
    :symbol (:symbol facts)
    :syntax-id (:syntax-id facts)
    :namespace (:namespace facts)
    :profile (:profile facts)
    :target (:target facts)
    :candidate-bindings (:candidate-bindings facts)
    :dependency-edge (:dependency-edge facts)}
   {:severity :error
    :profile (:profile facts)
    :missing-fields [missing-field]
    :facts (merge {:sh06-boundary :gravity-resolution-plan} facts)
    :observed observed}))

(defn sh06-resolution-resolve-source-path
  []
  (let [anchor (java.io.File.
                (p15-s23-stage2-compiler-artifact-source-path))
        start (if (.isDirectory anchor) anchor (.getParentFile anchor))]
    (or
     (loop [directory start]
       (when directory
         (let [candidate
               (java.io.File. directory sh06-resolution-source-relative-path)]
           (if (.isFile candidate)
             (.getPath candidate)
             (recur (.getParentFile directory))))))
     sh06-resolution-source-relative-path)))

(defn sh06-resolution-read-pinned-source!
  [request-source]
  (let [source-path (sh06-resolution-resolve-source-path)
        nio-path (.toPath (java.io.File. source-path))
        nofollow (into-array java.nio.file.LinkOption
                             [java.nio.file.LinkOption/NOFOLLOW_LINKS])
        attributes
        (try
          (java.nio.file.Files/readAttributes
           nio-path java.nio.file.attribute.BasicFileAttributes nofollow)
          (catch Exception error
            (sh06-resolution-boundary-fail!
             "C5-UNRESOLVED" request-source :pinned-resolution-source-readable
             source-path {:cause-message (.getMessage error)})))
        bytes
        (try
          (java.nio.file.Files/readAllBytes nio-path)
          (catch Exception error
            (sh06-resolution-boundary-fail!
             "C5-UNRESOLVED" request-source :pinned-resolution-source-bytes
             source-path {:cause-message (.getMessage error)})))
        content-hash (str "sha256:" (sha256-bytes-hex bytes))]
    (when-not
     (and (number? sh06-resolution-expected-source-byte-count)
          (string? sh06-resolution-expected-source-content-hash)
          attributes (.isRegularFile attributes)
          (= (long sh06-resolution-expected-source-byte-count)
             (.size attributes))
          (= sh06-resolution-expected-source-byte-count (alength bytes))
          (= sh06-resolution-expected-source-content-hash content-hash))
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" request-source :exact-pinned-resolution-source
       {:source-path source-path
        :source-byte-count (alength bytes)
        :source-content-hash content-hash}
       {:expected-byte-count sh06-resolution-expected-source-byte-count
        :expected-content-hash
        sh06-resolution-expected-source-content-hash}))
    {:source-path source-path
     :source-text (String. bytes java.nio.charset.StandardCharsets/UTF_8)
     :source-byte-count (alength bytes)
     :source-content-hash content-hash}))

(defn sh06-resolution-plan-identities
  [plan]
  (let [functions (:functions plan)
        shapes
        (into (sorted-map)
              (map (fn [[name function]]
                     [name (select-keys function [:arity :params])]))
              functions)]
    {:plan-semantic-hash
     (p15-s23-c11-mir-digest
      (p15-s23-stage2-compiler-artifact-semantic-input plan))
     :functions-semantic-hash (p15-s23-c11-mir-digest functions)
     :function-count (count functions)
     :function-names-hash
     (p15-s23-c11-mir-digest (vec (keys functions)))
     :function-shapes-hash (p15-s23-c11-mir-digest shapes)
     :public-function-hashes
     (into (sorted-map)
           (map (fn [name]
                  [name (p15-s23-c11-mir-digest (get functions name))]))
           (keys sh06-resolution-public-function-shapes))
     :public-function-shapes
     (select-keys shapes (keys sh06-resolution-public-function-shapes))}))

(defn sh06-resolution-build-binding!
  [request-source]
  (let [source (sh06-resolution-read-pinned-source! request-source)
        emitter
        (:emitter
         (c-backend-stage2-plan-emitter-source-rule!
          (:source-path source) :jvm))
        plan
        (p15-s23-stage2-compiler-artifact-plan
         emitter (:source-path source) (:source-text source))
        identities (sh06-resolution-plan-identities plan)]
    (when-not
     (and (= :gravity/stage2-compiler-artifact-plan (:kind plan))
          (true? (:compiler-artifact-plan? plan))
          (= 'gravity.resolution (get-in plan [:module :module]))
          (= :meta (get-in plan [:module :profile]))
          (= :jvm (get-in plan [:module :target]))
          (= #{} (get-in plan [:module :effects]))
          (= #{} (get-in plan [:module :capabilities]))
          (= :safe (get-in plan [:module :safety]))
          (= sh06-resolution-expected-plan-semantic-hash
             (:plan-semantic-hash identities))
          (= sh06-resolution-expected-functions-semantic-hash
             (:functions-semantic-hash identities))
          (= sh06-resolution-expected-function-count
             (:function-count identities))
          (= sh06-resolution-expected-function-names-hash
             (:function-names-hash identities))
          (= sh06-resolution-expected-function-shapes-hash
             (:function-shapes-hash identities))
          (= sh06-resolution-public-function-hashes
             (:public-function-hashes identities))
          (= sh06-resolution-public-function-shapes
             (:public-function-shapes identities)))
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" request-source :pinned-resolution-plan-and-functions
       identities {}))
    (merge source identities
           {:artifact :gravity/sh06-pinned-resolution-plan-binding
            :status :complete
            :semantic-authority :gravity-source
            :compiled-by :clojure-stage0-seed
            :executed-by :clojure-stage2-generic-rule-runner
            :generic-bridge-residual? true
            :self-hosted? false
            :plan plan})))

(def ^:private sh06-resolution-cached-binding
  (delay (sh06-resolution-build-binding!
          "<sh06-resolution-bootstrap>")))

(defn sh06-resolution-current-binding!
  [request-source]
  (let [fresh (sh06-resolution-read-pinned-source! request-source)
        binding @sh06-resolution-cached-binding
        identities (sh06-resolution-plan-identities (:plan binding))]
    (when-not
     (and (= (:source-byte-count fresh) (:source-byte-count binding))
          (= (:source-content-hash fresh) (:source-content-hash binding))
          (= (select-keys
              binding
              [:plan-semantic-hash :functions-semantic-hash
               :function-count :function-names-hash
               :function-shapes-hash :public-function-hashes
               :public-function-shapes])
             identities))
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" request-source
       :fresh-resolution-source-and-plan-binding binding {}))
    binding))

(defn sh06-resolution-execute!
  [source-path binding function arguments]
  (try
    (sh04-syntax-strip-host-metadata
     (p15-s23-stage2-runtime-execute-function
      {:engine :gravity-sh06-pinned-resolution-runner
       :compiler-artifact-plan? true}
      (:plan binding) function
      (sh04-syntax-strip-host-metadata arguments)))
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch StackOverflowError error
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path :bounded-resolution-host-stack function
       {:contained-host-error (.getName (class error))}))
    (catch AssertionError error
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path :contained-resolution-assertion function
       {:contained-host-error (.getName (class error))}))
    (catch LinkageError error
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path :contained-resolution-linkage function
       {:contained-host-error (.getName (class error))}))
    (catch clojure.lang.ExceptionInfo error
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path
       :contained-resolution-runtime-diagnostic function
       {:contained-diagnostic (:id (ex-data error))}))
    (catch Exception error
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path :contained-resolution-host-failure
       function {:contained-host-error (.getName (class error))
                 :cause-message (.getMessage error)}))))

(def sh06-resolution-transport-bounds
  ;; Per-component request, replay, result, and upstream carrier limits.  These
  ;; remain strict even though the aggregate artifact serializes several
  ;; independently bounded products and projections together.
  {:maximum-carrier-nodes 33554432
   :maximum-carrier-depth 64
   :maximum-container-width 131072})

(def sh06-resolution-artifact-bounds
  ;; The checked-core self-input exceeds the earlier reader-sized envelope.
  ;; Keep a finite power-of-two aggregate ceiling while retaining independent
  ;; component, depth, and width checks.
  {:maximum-carrier-nodes 67108864
   :maximum-carrier-depth 64
   :maximum-container-width 131072
   ;; The serialized ceiling is checked before EDN parsing.
   :maximum-serialized-bytes 1073741824})

(def sh06-resolution-diagnostic-measurement-bounds
  ;; Failure-only measurement ceiling.  This never authorizes transport or
  ;; artifact acceptance; it exists to replace blind resource-bound changes
  ;; with an exact finite observation when the normal aggregate gate rejects.
  {:maximum-carrier-nodes 134217728
   :maximum-carrier-depth 64
   :maximum-container-width 131072})

(defmacro with-sh06-resolution-transport-bounds
  [& body]
  `(binding [p15-s23-c6c10-max-carrier-nodes
             (:maximum-carrier-nodes sh06-resolution-transport-bounds)
             p15-s23-c6c10-max-carrier-depth
             (:maximum-carrier-depth sh06-resolution-transport-bounds)
             p15-s23-c6c10-max-container-width
             (:maximum-container-width sh06-resolution-transport-bounds)
             p15-s23-c6c10-max-digest-requests 8192]
     ~@body))

(defn sh06-resolution-require-carrier!
  [source-path carrier value]
  (let [validation
        (p15-s23-trusted-carrier-validation
         value :default-only
         (:maximum-carrier-nodes sh06-resolution-transport-bounds)
         (:maximum-carrier-depth sh06-resolution-transport-bounds)
         (:maximum-container-width sh06-resolution-transport-bounds))]
    (when-not (= :passed (:status validation))
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path :bounded-sh06-resolution-carrier
       (select-keys
        validation
        [:reason :class :observed-nodes :observed-depth
         :maximum-nodes :maximum-depth :maximum-width])
       {:carrier carrier
        :transport-bounds sh06-resolution-transport-bounds}))
    validation))

(defn sh06-resolution-digest-reference
  [value]
  (when (and (map? value)
             (= #{:digest-ref} (set (keys value)))
             (integer? (:digest-ref value))
             (not (neg? (:digest-ref value))))
    (:digest-ref value)))

(defn sh06-resolution-resolve-declared-id!
  [source-path value resolved-digests slot]
  (let [ordinal (sh06-resolution-digest-reference value)
        resolved (when (some? ordinal) (get resolved-digests ordinal))]
    (when-not (and (some? ordinal)
                   (p15-s23-sh02-sha256-id? resolved))
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path slot value
       {:resolved-digest resolved :digest-ordinal ordinal}))
    resolved))

(defn sh06-resolution-resolve-record-binding-id!
  [source-path record resolved-digests slot]
  (assoc record :binding-id
         (sh06-resolution-resolve-declared-id!
          source-path (:binding-id record) resolved-digests slot)))

(defn sh06-resolution-resolve-analysis!
  ([source-path raw-analysis resolved-digests]
   (sh06-resolution-resolve-analysis!
    source-path raw-analysis resolved-digests false))
  ([source-path raw-analysis resolved-digests allow-pending-artifact-id?]
   (let [bindings
        (mapv
         #(sh06-resolution-resolve-record-binding-id!
           source-path % resolved-digests :binding-table-binding-id)
         (:binding-table raw-analysis))
        resolutions
        (mapv
         #(sh06-resolution-resolve-record-binding-id!
           source-path % resolved-digests :resolution-table-binding-id)
         (:resolution-table raw-analysis))
        binding-identities
        (mapv
         #(sh06-resolution-resolve-declared-id!
           source-path % resolved-digests
           :identity-preimage-binding-identity)
         (get-in raw-analysis [:identity-preimage :binding-identities]))
        invalidation-binding-ids
        (mapv
         #(sh06-resolution-resolve-declared-id!
           source-path % resolved-digests
           :incremental-invalidation-binding-id)
         (get-in raw-analysis
                 [:incremental-invalidation-inputs :binding-ids]))
        identity-preimage
        (-> (:identity-preimage raw-analysis)
            (assoc :binding-identities binding-identities)
            (assoc :resolutions
                   (mapv #(dissoc % :source-span) resolutions)))
        artifact-ordinal
        (sh06-resolution-digest-reference (:artifact-id raw-analysis))
        artifact-id
        (if (and allow-pending-artifact-id?
                 (= artifact-ordinal (count resolved-digests)))
          (:artifact-id raw-analysis)
          (sh06-resolution-resolve-declared-id!
           source-path (:artifact-id raw-analysis) resolved-digests
           :namespace-analysis-artifact-id))]
    (-> raw-analysis
        (assoc :artifact-id artifact-id)
        (assoc :binding-table bindings)
        (assoc :resolution-table resolutions)
        (assoc :identity-preimage identity-preimage)
        (assoc-in [:incremental-invalidation-inputs :binding-ids]
                  invalidation-binding-ids)))))

(defn sh06-resolution-resolve-digest-requests!
  [source-path raw-analysis digest-requests]
  (when-not (and (vector? digest-requests)
                 (<= (count digest-requests) 8192)
                 (seq digest-requests))
    (sh06-resolution-boundary-fail!
     "C5-UNRESOLVED" source-path :bounded-resolution-digest-requests
     digest-requests {:maximum-digest-requests 8192}))
  (let [binding-count (count (:binding-table raw-analysis))]
    (when-not (= (inc binding-count) (count digest-requests))
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path :complete-resolution-digest-requests
       digest-requests {:binding-count binding-count}))
    (loop [remaining digest-requests resolved []]
      (if (empty? remaining)
        resolved
        (let [request (first remaining)
              ordinal (:ordinal request)
              purpose (:purpose request)
              preimage
              (if (= purpose :sh06-namespace-analysis-id)
                (:identity-preimage
                 (sh06-resolution-resolve-analysis!
                  source-path raw-analysis resolved true))
                (:preimage request))]
          (when-not (= ordinal (count resolved))
            (sh06-resolution-boundary-fail!
             "C5-UNRESOLVED" source-path
             :ordered-resolution-digest-requests request
             {:resolved-count (count resolved)}))
          (recur
           (rest remaining)
           (conj resolved
                 (reader-canonical-hash
                  {:domain :gravity/sh06-declared-digest-v1
                   :purpose purpose :preimage preimage}))))))))

(defn sh06-resolution-raise-rejection!
  [source-path template]
  (let [diagnostic (first (:diagnostics template))
        requests (:digest-requests template)
        request (first requests)
        diagnostic-id
        (reader-canonical-hash
         {:domain :gravity/sh06-declared-digest-v1
          :purpose (:purpose request)
          :preimage (:preimage request)})
        rule (:rule diagnostic)]
    (when-not (and (= :rejected (:status template))
                   (= 1 (count (:diagnostics template)))
                   (= 1 (count requests))
                   (contains? (set c5-resolution-diagnostic-ids) rule)
                   (= 0 (:ordinal request))
                   (= :sh06-resolution-diagnostic-id (:purpose request))
                   (= {:digest-ref 0}
                      (:diagnostic-id-request diagnostic))
                   (p15-s23-sh02-sha256-id? diagnostic-id))
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path
       :exact-gravity-resolution-rejection template {}))
    (c5-resolution-fail!
     rule source-path
     (assoc diagnostic
            :source-span
            (assoc (or (:source-span diagnostic)
                       (source-span source-path 0))
                   :source source-path))
     {:severity :error
      :profile (:profile diagnostic)
      :diagnostic-id diagnostic-id
      :facts (:facts diagnostic)
      :remediation (:remediation diagnostic)})))

(defn sh06-resolution-run-request!
  [source-path binding request]
  (sh06-resolution-require-carrier!
   source-path :authenticated-sh06-resolution-request request)
  (let [template
        (sh06-resolution-execute!
         source-path binding 'sh06-build-resolution-template [request])]
    (sh06-resolution-require-carrier!
     source-path :gravity-resolution-template template)
    (case (:status template)
      :rejected (sh06-resolution-raise-rejection! source-path template)
      :accepted
      (let [raw-analysis (:namespace-analysis-template template)
            digest-requests (:digest-requests template)
            template-verification
            (sh06-resolution-execute!
             source-path binding 'sh06-verify-resolution-template
             [raw-analysis digest-requests])
            _ (when-not (= :passed (:status template-verification))
                (sh06-resolution-boundary-fail!
                 "C5-UNRESOLVED" source-path
                 :fresh-gravity-resolution-template-verification
                 template-verification {}))
            resolved-digests
            (sh06-resolution-resolve-digest-requests!
             source-path raw-analysis digest-requests)
            resolved-analysis
            (sh06-resolution-resolve-analysis!
             source-path raw-analysis resolved-digests)
            resolved-verification
            (sh06-resolution-execute!
             source-path binding 'sh06-verify-resolution-resolved
             [resolved-analysis digest-requests resolved-digests])]
        (sh06-resolution-require-carrier!
         source-path :resolved-gravity-resolution-analysis
         resolved-analysis)
        (when-not (= :passed (:status resolved-verification))
          (sh06-resolution-boundary-fail!
           "C5-UNRESOLVED" source-path
           :fresh-gravity-resolution-resolved-verification
           resolved-verification {}))
        {:raw-template-result template
         :raw-analysis raw-analysis
         :resolved-analysis resolved-analysis
         :digest-requests digest-requests
         :resolved-digests resolved-digests
         :template-verification template-verification
         :resolved-verification resolved-verification})
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path :gravity-resolution-result-status
       template {}))))

(defn sh06-resolution-order-compatibility
  [order]
  (case order
    :local-lexical-binding :local
    :current-namespace-binding :namespace
    :alias-qualified-required-binding :alias-qualified
    :fully-qualified-namespace-binding :fully-qualified
    :profile-allowed-core-binding :core-auto-import
    :explicit-foreign-import-binding :foreign
    order))

(defn sh06-resolution-product-projections
  [analysis]
  (let [compatibility-resolutions
        (mapv #(assoc % :resolution-kind
                      (sh06-resolution-order-compatibility
                       (:resolution-order %)))
              (:resolution-table analysis))]
    {:namespace-analysis
     (assoc analysis :artifact :gravity/namespace-analysis)
     :binding-table
     {:artifact :gravity/c5-binding-table
      :status :complete
      :bindings (:binding-table analysis)
      :resolution-table compatibility-resolutions}
     :alias-table
     {:artifact :gravity/c5-alias-table
      :status :complete :aliases (:alias-table analysis)}
     :import-export-table
     {:artifact :gravity/c5-import-export-table
      :status :complete
      :imports (:dependency-records analysis)
      :exports (:exports analysis)}
     :lexical-scope-graph
     {:artifact :gravity/c5-lexical-scope-graph
      :status :complete :scopes (:lexical-scope-graph analysis)}
     :dependency-graph
     (assoc (:dependency-graph analysis)
            :artifact :gravity/c5-module-dependency-graph
            :status :complete)
     :cross-profile-edge-report
     {:artifact :gravity/c5-cross-profile-edge-report
      :status :complete
      :records (:cross-profile-edge-report analysis)}
     :incremental-invalidation-keys
     {:artifact :gravity/c5-incremental-invalidation-keys
      :status :stable
      :inputs (:incremental-invalidation-inputs analysis)
      :invalidation-id
      (reader-canonical-hash
       {:domain :gravity/sh06-invalidation-identity-v1
        :inputs (:incremental-invalidation-inputs analysis)})}
     :resolution-table compatibility-resolutions}))

(defn sh06-resolution-identity-chunks
  [values]
  (mapv
   (fn [chunk-index chunk]
     {:chunk-index chunk-index
      :entry-count (count chunk)
      :chunk-id
      (reader-canonical-hash
       {:domain :gravity/sh06-resolution-identity-chunk-v1
        :chunk-index chunk-index :entries (vec chunk)})})
   (range)
   (partition-all 16 values)))

(defn sh06-resolution-artifact-identity-input
  [artifact]
  {:domain :gravity/sh06-resolution-artifact-v1
   :kind (:kind artifact)
   :slice (:slice artifact)
   :task (:task artifact)
   :adapter-contract
   (get-in artifact [:gravity-resolution-boundary :adapter-contract])
   :analysis-artifact-id
   (get-in artifact [:gravity-resolution-boundary :resolved-analysis
                     :artifact-id])
   :source-revision-id
   (get-in artifact [:gravity-resolution-boundary
                     :authenticated-resolution-request :module
                     :source-revision-id])
   :upstream-artifact-id
   (get-in artifact [:sh05-macro-artifact :artifact-id])
   :upstream-syntax-stream-id
   (get-in artifact [:sh05-macro-artifact :expanded-syntax-stream-id])
   :upstream-trace-id
   (get-in artifact [:sh05-macro-artifact :macro-expansion-trace-id])
   :binding-id-chunks
   (sh06-resolution-identity-chunks
    (mapv :binding-id (get-in artifact [:binding-table :bindings])))
   :resolution-chunks
   (sh06-resolution-identity-chunks
    (mapv #(dissoc % :source-span) (:resolution-table artifact)))
   :dependency-graph-id
   (reader-canonical-hash
    {:domain :gravity/sh06-dependency-graph-v1
     :nodes (get-in artifact [:dependency-graph :nodes])
     :edges (mapv #(dissoc % :source-span)
                  (get-in artifact [:dependency-graph :edges]))})
   :invalidation-id
   (get-in artifact [:incremental-invalidation-keys :invalidation-id])})

(defn sh06-resolution-artifact-id
  [artifact]
  (reader-canonical-hash
   (sh06-resolution-artifact-identity-input artifact)))

(defn sh06-resolution-envelope-summary
  [artifact]
  {:slice :SH-06
   :artifact-id (:artifact-id artifact)
   :analysis-artifact-id
   (get-in artifact [:gravity-resolution-boundary :resolved-analysis
                     :artifact-id])
   :upstream-artifact-id (get-in artifact [:sh05-macro-artifact :artifact-id])
   :source-revision-id
   (get-in artifact [:gravity-resolution-boundary
                     :authenticated-resolution-request :module
                     :source-revision-id])
   :binding-count (count (get-in artifact [:binding-table :bindings]))
   :reference-count (count (:resolution-table artifact))
   :dependency-edge-count (count (get-in artifact [:dependency-graph :edges]))
   :binding-id-chunks
   (sh06-resolution-identity-chunks
    (mapv :binding-id (get-in artifact [:binding-table :bindings])))
   :resolution-chunks
   (sh06-resolution-identity-chunks
    (mapv #(dissoc % :source-span) (:resolution-table artifact)))})

(defn sh06-resolution-sh02-descriptor
  [source-path binding summary]
  (let [projection-name :resolution-product-identities
        fact-name :resolution-product-binding
        identity-name :resolution-result
        identity-domain :gravity/sh06-resolution-result-identity-v1
        evidence-id
        (p15-s23-c6c10-canonical-digest
         source-path
         {:domain :gravity/sh06-resolution-envelope-evidence-v1
          :summary summary
          :plan-semantic-hash (:plan-semantic-hash binding)})
        identity-preimage {:summary summary}
        observed-id
        (p15-s23-c6c10-canonical-digest
         source-path {:domain identity-domain
                      :semantic-input identity-preimage})
        fact-value {:family fact-name :entries [summary]}
        sealed-artifact-id
        (p15-s23-c6c10-canonical-digest
         source-path {:resolution-result (:artifact-id summary)})]
    {:artifact :gravity/private-authenticated-envelope-descriptor
     :schema-version 1
     :stage sh06-resolution-envelope-stage
     :artifact-kind sh06-resolution-sealed-artifact-kind
     :source-revision
     {:owner :sh06-resolution
      :source-language :gravity
      :logical-source-path sh06-resolution-source-relative-path
      :source-content-hash (:source-content-hash binding)
      :source-byte-count (:source-byte-count binding)
      :plan-semantic-hash (:plan-semantic-hash binding)
      :functions-semantic-hash (:functions-semantic-hash binding)
      :builder-function 'sh06-build-resolution-template
      :builder-semantic-hash
      (get sh06-resolution-public-function-hashes
           'sh06-build-resolution-template)
      :function-shapes sh06-resolution-public-function-shapes}
     :projection-contract
     {:contract-kind :gravity/sh06-resolution-product-envelope-contract
      :contract-version 1 :profile :meta :target :jvm
      :required-semantic-projections [projection-name]
      :required-fact-families [fact-name]
      :required-identity-subjects [identity-name]}
     :semantic-projections
     [{:name projection-name :role :complete-resolution-product-identities
       :entry-count (count summary) :value summary}]
     :fact-transitions
     [{:name fact-name :disposition :preserved
       :input fact-value :output fact-value
       :input-count (count fact-value)
       :output-count (count fact-value)
       :evidence-ids [evidence-id]}]
     :effect-capability-relation
     {:effect-facts {:declared #{} :observed #{}}
      :capability-facts {:required #{} :granted #{}}
      :capability-proof-facts {:proof-ids [evidence-id]}
      :effect-order [] :provider-selections [] :grant-scopes []}
     :proof-composite
     {:proof-records [{:proof-id evidence-id :status :checked}]
      :proof-certificate-table {evidence-id {:status :checked}}
      :proof-summary {:required 1 :checked 1}
      :proof-usage [{:proof-id evidence-id :used-by :resolution-products}]}
     :preservation
     {:requires [fact-name] :preserves [fact-name]
      :invalidates [] :regenerates []
      :residual-checks [:identity-subject-equality
                        :digest-graph-reachability]}
     :identity-subjects
     [{:name identity-name :domain identity-domain
       :preimage identity-preimage :observed-id observed-id}]
     :lineage
     [{:stage :sh06-resolution
       :artifact-kind :gravity/sh06-resolution-artifact
       :semantic-id (:artifact-id summary)
       :artifact-id sealed-artifact-id
       :verification-id evidence-id
       :relation :produced-from-gravity-resolution}]
     :reference-closure
     {:root-id "sh06-resolution-result"
      :node-ids ["sh06-resolution-result"]
      :edges [] :fact-reference-ids [evidence-id]
      :origin-reference-ids [] :proof-reference-ids [evidence-id]
      :runtime-check-reference-ids [] :observed-node-count 1
      :observed-edge-count 0 :observed-maximum-depth 0}
     :actual-path-provenance
     {:source-path source-path
      :workspace-root (System/getProperty "user.dir")
      :invocation-root (System/getProperty "user.dir")}
     :bounds p15-s23-sh02-authenticated-envelope-bounds}))

(def sh06-resolution-artifact-keys
  #{:kind :status :slice :task :document-set :governing-document
    :artifact-id :sh05-macro-artifact :gravity-resolution-boundary
    :provenance :pass :execution-boundary :capability-based-proof
    :diagnostics :namespace-analysis :binding-table :alias-table
    :import-export-table :lexical-scope-graph :dependency-graph
    :cross-profile-edge-report :incremental-invalidation-keys
    :resolution-table})

(def sh06-resolution-boundary-keys
  #{:slice :owner :adapter-contract :plan-binding
    :authenticated-resolution-request :raw-template-result :raw-analysis
    :resolved-analysis :digest-requests :resolved-digests
    :template-verification :resolved-verification
    :authenticated-envelope-descriptor :authenticated-envelope
    :target-source-reread? :clojure-adapter-residual? :self-hosted?})

(def sh06-resolution-component-paths
  [[:document-set [:document-set]]
   [:provenance [:provenance]]
   [:pass [:pass]]
   [:execution-boundary [:execution-boundary]]
   [:capability-based-proof [:capability-based-proof]]
   [:diagnostics [:diagnostics]]
   [:sh05-macro-artifact [:sh05-macro-artifact]]
   [:plan-binding [:gravity-resolution-boundary :plan-binding]]
   [:authenticated-resolution-request
    [:gravity-resolution-boundary :authenticated-resolution-request]]
   [:raw-template-result
    [:gravity-resolution-boundary :raw-template-result]]
   [:raw-analysis [:gravity-resolution-boundary :raw-analysis]]
   [:resolved-analysis [:gravity-resolution-boundary :resolved-analysis]]
   [:digest-requests [:gravity-resolution-boundary :digest-requests]]
   [:resolved-digests [:gravity-resolution-boundary :resolved-digests]]
   [:template-verification
    [:gravity-resolution-boundary :template-verification]]
   [:resolved-verification
    [:gravity-resolution-boundary :resolved-verification]]
   [:authenticated-envelope-descriptor
    [:gravity-resolution-boundary :authenticated-envelope-descriptor]]
   [:authenticated-envelope
    [:gravity-resolution-boundary :authenticated-envelope]]
   [:namespace-analysis [:namespace-analysis]]
   [:binding-table [:binding-table]]
   [:alias-table [:alias-table]]
   [:import-export-table [:import-export-table]]
   [:lexical-scope-graph [:lexical-scope-graph]]
   [:dependency-graph [:dependency-graph]]
   [:cross-profile-edge-report [:cross-profile-edge-report]]
   [:incremental-invalidation-keys [:incremental-invalidation-keys]]
   [:resolution-table [:resolution-table]]])

(defn sh06-resolution-carrier-validation
  [value bounds]
  (p15-s23-trusted-carrier-validation
   value :default-only
   (:maximum-carrier-nodes bounds)
   (:maximum-carrier-depth bounds)
   (:maximum-container-width bounds)))

(defn sh06-resolution-component-validations
  [artifact]
  (into
   (sorted-map)
   (map
    (fn [[component path]]
      [component
       (sh06-resolution-carrier-validation
        (get-in artifact path) sh06-resolution-transport-bounds)]))
   sh06-resolution-component-paths))

(defn- sh06-resolution-candidate-measurements
  [artifact]
  (let [aggregate
        (sh06-resolution-carrier-validation
         artifact sh06-resolution-diagnostic-measurement-bounds)
        trusted-aggregate? (= :passed (:status aggregate))
        boundary (when (and trusted-aggregate? (map? artifact))
                   (:gravity-resolution-boundary artifact))
        exact-shape?
        (and (map? artifact)
             (= sh06-resolution-artifact-keys (set (keys artifact)))
             (map? boundary)
             (= sh06-resolution-boundary-keys (set (keys boundary))))]
    {:aggregate aggregate
     :components
     (when exact-shape?
       (sh06-resolution-component-validations artifact))
     :trusted-exact-shape? (boolean exact-shape?)
     :measurement-only? true
     :authorizes-bound-change? false}))

(def sh06-resolution-pass-contract
  {:name :sh06-gravity-name-resolution
   :input :authenticated-sh05-expanded-syntax
   :output :authenticated-sh06-namespace-analysis
   :preserves [:source-spans :syntax-ids :macro-lineage
               :profile :target :effects :capabilities]
   :rejects c5-resolution-diagnostic-ids})

(def sh06-resolution-execution-boundary-contract
  {:resolution-authority :gravity
   :gravity-module 'gravity.resolution
   :plan-runner :clojure-stage0
   :digest-resolver :clojure-stage0
   :envelope-binder :clojure-stage0
   :compatibility-adapter :clojure-stage0
   :component-transport-bounds sh06-resolution-transport-bounds
   :aggregate-artifact-bounds sh06-resolution-artifact-bounds
   :self-hosted? false})

(defn- sh06-resolution-artifact-verification-bounded*
  [artifact construction?]
  (with-sh06-resolution-transport-bounds
   (let [source-path (or (get-in artifact [:provenance :source-path])
                        "<sh06-resolution-artifact>")
        boundary (:gravity-resolution-boundary artifact)
        analysis (:resolved-analysis boundary)
        sh05-artifact (:sh05-macro-artifact artifact)
        sh05-report
        (try
          (sh05-macro-artifact-verification sh05-artifact)
          (catch Throwable _ {:status :failed}))
        binding
        (try
          (sh06-resolution-current-binding! source-path)
          (catch Throwable _ nil))
        expected-plan-binding
        (when binding (dissoc binding :plan :source-text))
        replay
        (when (and binding (= :passed (:status sh05-report)))
          (try
            (let [request (sh06-resolution-request source-path sh05-artifact)
                  run (sh06-resolution-run-request!
                       source-path binding request)]
              {:status :passed :request request :run run})
            (catch InterruptedException interrupted
              (.interrupt (Thread/currentThread))
              (throw interrupted))
            (catch Throwable error
              {:status :failed
               :contained-host-error (.getName (class error))
               :contained-diagnostic
               (when (instance? clojure.lang.ExceptionInfo error)
                 (:id (ex-data error)))})))
        expected-request (:request replay)
        expected-run (:run replay)
        gravity-report
        (or (:resolved-verification expected-run) {:status :failed})
        projections (when (map? analysis)
                      (sh06-resolution-product-projections analysis))
        summary (sh06-resolution-envelope-summary artifact)
        expected-descriptor
        (when binding
          (sh06-resolution-sh02-descriptor source-path binding summary))
        envelope-ok?
        (and expected-descriptor
             (= expected-descriptor
                (:authenticated-envelope-descriptor boundary))
             (try
               (p15-s23-stage2-sh02-descriptor-envelope-verify!
                (:authenticated-envelope boundary)
                sh06-resolution-envelope-stage
                sh06-resolution-sealed-artifact-kind
                expected-descriptor source-path)
               true
               (catch Throwable _ false)))
        base-checks
        {:bounded-artifact-carrier? true
         :bounded-semantic-components? true
         :exact-kind? (= :gravity/sh06-resolution-artifact (:kind artifact))
         :accepted-status? (= :accepted (:status artifact))
         :document-set-current?
         (= ["L3" "C5"] (:document-set artifact))
         :governing-document-current?
         (= c5-resolution-governing-document
            (:governing-document artifact))
         :fresh-upstream-sh05-verification?
         (= :passed (:status sh05-report))
         :plan-binding-current?
         (and expected-plan-binding
              (= expected-plan-binding (:plan-binding boundary)))
         :fresh-gravity-request-replay?
         (= :passed (:status replay))
         :authenticated-resolution-request-current?
         (and expected-request
              (= expected-request
                 (:authenticated-resolution-request boundary)))
         :raw-template-result-current?
         (and expected-run
              (= (:raw-template-result expected-run)
                 (:raw-template-result boundary)))
         :raw-analysis-current?
         (and expected-run
              (= (:raw-analysis expected-run) (:raw-analysis boundary)))
         :resolved-analysis-current?
         (and expected-run
              (= (:resolved-analysis expected-run)
                 (:resolved-analysis boundary)))
         :digest-requests-current?
         (and expected-run
              (= (:digest-requests expected-run)
                 (:digest-requests boundary)))
         :resolved-digests-current?
         (and expected-run
              (= (:resolved-digests expected-run)
                 (:resolved-digests boundary)))
         :template-verification-current?
         (and expected-run
              (= (:template-verification expected-run)
                 (:template-verification boundary)))
         :resolved-verification-current?
         (and expected-run
              (= (:resolved-verification expected-run)
                 (:resolved-verification boundary)))
         :upstream-request-binding?
         (and (= (:artifact-id sh05-artifact)
                 (get-in boundary
                         [:authenticated-resolution-request :module
                          :c4-artifact-id]))
              (= (:expanded-syntax-stream-id sh05-artifact)
                 (get-in boundary
                         [:authenticated-resolution-request
                          :macro-expansion-binding :macro-result-id])))
         :fresh-gravity-verification?
         (= :passed (:status gravity-report))
         :namespace-analysis-current?
         (= (:namespace-analysis projections) (:namespace-analysis artifact))
         :binding-table-current?
         (= (:binding-table projections) (:binding-table artifact))
         :alias-table-current?
         (= (:alias-table projections) (:alias-table artifact))
         :import-export-current?
         (= (:import-export-table projections) (:import-export-table artifact))
         :lexical-scope-current?
         (= (:lexical-scope-graph projections)
            (:lexical-scope-graph artifact))
         :dependency-graph-current?
         (= (:dependency-graph projections) (:dependency-graph artifact))
         :cross-profile-current?
         (= (:cross-profile-edge-report projections)
            (:cross-profile-edge-report artifact))
         :invalidation-current?
         (= (:incremental-invalidation-keys projections)
            (:incremental-invalidation-keys artifact))
         :resolution-table-current?
         (= (:resolution-table projections) (:resolution-table artifact))
         :artifact-identity-current?
         (= (:artifact-id artifact) (sh06-resolution-artifact-id artifact))
         :fresh-sh02-envelope-verified? envelope-ok?
         :exact-artifact-shape?
         (= sh06-resolution-artifact-keys (set (keys artifact)))
         :exact-boundary-shape?
         (= sh06-resolution-boundary-keys (set (keys boundary)))
         :fixed-boundary-contract?
         (= {:slice :SH-06
             :owner :gravity-source
             :adapter-contract sh06-resolution-adapter-contract
             :target-source-reread? false
             :clojure-adapter-residual? true
             :self-hosted? false}
            (select-keys
             boundary
             [:slice :owner :adapter-contract
              :target-source-reread? :clojure-adapter-residual?
              :self-hosted?]))
         :pass-contract-current?
         (= sh06-resolution-pass-contract (:pass artifact))
         :execution-boundary-current?
         (= sh06-resolution-execution-boundary-contract
            (:execution-boundary artifact))
         :component-transport-bounds-current?
         (= sh06-resolution-transport-bounds
            (get-in artifact
                    [:execution-boundary :component-transport-bounds]))
         :aggregate-artifact-bounds-current?
         (= sh06-resolution-artifact-bounds
            (get-in artifact
                    [:execution-boundary :aggregate-artifact-bounds]))
         :provenance-current?
         (let [source-revision-id
               (get-in boundary
                       [:authenticated-resolution-request :module
                        :source-revision-id])]
           (and (= {:source-path source-path
                    :source-revision-id source-revision-id}
                   (:provenance artifact))
                (= source-path
                   (get-in boundary
                           [:authenticated-resolution-request
                            :provenance :actual-source-path]))))
         :accepted-diagnostics-empty?
         (empty? (:diagnostics artifact))}
        base-failed
        (->> base-checks (keep (fn [[key passed?]]
                                (when-not passed? key))) vec)
        expected-embedded-proof
        (assoc base-checks
               :embedded-capability-proof-current? true
               :artifact :gravity/sh06-resolution-capability-proof
               :status (if (empty? base-failed) :complete :failed)
               :failed-checks base-failed)
        embedded-proof-current?
        (or (and construction?
                 (nil? (:capability-based-proof artifact)))
            (= expected-embedded-proof
               (:capability-based-proof artifact)))
        checks
        (assoc base-checks
               :embedded-capability-proof-current?
               embedded-proof-current?)
        failed (->> checks (keep (fn [[key passed?]]
                                   (when-not passed? key))) vec)]
    {:artifact :gravity/sh06-resolution-artifact-verification
     :status (if (empty? failed) :passed :failed)
     :checks checks
     :failed-checks failed
     :source-path source-path
     :gravity-verification gravity-report
     :upstream-verification sh05-report})))

(defn- sh06-resolution-artifact-verification*
  [artifact construction?]
  (with-sh06-resolution-transport-bounds
   (let [aggregate-validation
         (sh06-resolution-carrier-validation
          artifact sh06-resolution-artifact-bounds)
         carrier-ok? (= :passed (:status aggregate-validation))
         boundary (when (and carrier-ok? (map? artifact))
                    (:gravity-resolution-boundary artifact))
         shape-checks
         {:bounded-artifact-carrier? carrier-ok?
          :top-level-artifact-map? (and carrier-ok? (map? artifact))
          :exact-artifact-shape?
          (and carrier-ok? (map? artifact)
               (= sh06-resolution-artifact-keys (set (keys artifact))))
          :resolution-boundary-map? (map? boundary)
          :exact-boundary-shape?
          (and (map? boundary)
               (= sh06-resolution-boundary-keys (set (keys boundary))))}
         shape-failed
         (->> shape-checks
              (keep (fn [[key passed?]] (when-not passed? key)))
              vec)
         component-validations
         (when (empty? shape-failed)
           (sh06-resolution-component-validations artifact))
         components-ok?
         (and component-validations
              (every? #(= :passed (:status %))
                      (vals component-validations)))
         preflight-checks
         (assoc shape-checks
                :bounded-semantic-components? (boolean components-ok?))
         preflight-failed
         (->> preflight-checks
              (keep (fn [[key passed?]] (when-not passed? key)))
              vec)
         preflight-observations
         (when (and construction?
                    (seq preflight-failed)
                    (= :maximum-carrier-nodes
                       (:reason aggregate-validation)))
           (merge
            {:normal-aggregate-bounds sh06-resolution-artifact-bounds
             :diagnostic-measurement-bounds
             sh06-resolution-diagnostic-measurement-bounds}
            (sh06-resolution-candidate-measurements artifact)))]
     (if (empty? preflight-failed)
       (sh06-resolution-artifact-verification-bounded* artifact construction?)
       {:artifact :gravity/sh06-resolution-artifact-verification
        :status :failed
        :checks preflight-checks
        :failed-checks preflight-failed
        :source-path "<sh06-resolution-artifact>"
        :carrier-validation aggregate-validation
        :preflight-observations preflight-observations
        :component-validations component-validations
        :gravity-verification nil
        :upstream-verification nil}))))

(defn sh06-resolution-contained-verification-failure
  [error]
  {:artifact :gravity/sh06-resolution-artifact-verification
   :status :failed
   :checks {:contained-host-resource-failure? false}
   :failed-checks [:contained-host-resource-failure?]
   :source-path "<sh06-resolution-artifact>"
   :contained-host-error (.getName (class error))
   :gravity-verification nil
   :upstream-verification nil})

(defn- sh06-resolution-artifact-verification-contained
  [artifact construction?]
  (try
    (sh06-resolution-artifact-verification* artifact construction?)
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch StackOverflowError error
      (sh06-resolution-contained-verification-failure error))
    (catch OutOfMemoryError error
      (sh06-resolution-contained-verification-failure error))
    (catch AssertionError error
      (sh06-resolution-contained-verification-failure error))
    (catch LinkageError error
      (sh06-resolution-contained-verification-failure error))
    (catch Exception error
      (sh06-resolution-contained-verification-failure error))))

(defn sh06-resolution-artifact-verification
  [artifact]
  (sh07-proof-transaction-report
   :sh06 :final
   {:verifier-root
    (var-get #'sh06-resolution-artifact-verification-contained)
    :report-schema-version 1
    :check-catalog-domain :gravity/sh06-final-verification-checks
    :source-content-hash sh06-resolution-expected-source-content-hash
    :plan-semantic-hash sh06-resolution-expected-plan-semantic-hash
    :functions-semantic-hash
    sh06-resolution-expected-functions-semantic-hash}
   artifact
   #(sh06-resolution-artifact-verification-contained artifact false)))

(defn- sh06-resolution-capability-based-proof-for-construction
  [artifact]
  (let [report
        (sh06-resolution-artifact-verification-contained artifact true)]
    (cond->
     (assoc (:checks report)
            :artifact :gravity/sh06-resolution-capability-proof
            :status (if (= :passed (:status report)) :complete :failed)
            :failed-checks (:failed-checks report))
      (and (= :failed (:status report))
           (:preflight-observations report))
      (assoc :preflight-observations
             (:preflight-observations report))
      (and (= :failed (:status report))
           (:carrier-validation report))
      (assoc :carrier-validation
             (:carrier-validation report)))))

(defn sh06-resolution-capability-based-proof
  [artifact]
  (let [report (sh06-resolution-artifact-verification artifact)]
    (assoc (:checks report)
           :artifact :gravity/sh06-resolution-capability-proof
           :status (if (= :passed (:status report)) :complete :failed)
           :failed-checks (:failed-checks report))))

(defn- sh06-resolution-source-artifact-candidate
  "Construct the authentic internal aggregate before its mandatory proof gate.

  This private value is available to bounded diagnostics and tests only.  It is
  not an accepted artifact and must never cross the public SH-06 boundary
  without sh06-resolution-capability-based-proof-for-construction."
  [source-path source-text]
  (with-sh06-resolution-transport-bounds
   (let [sh05-artifact (sh05-macro-source-artifact source-path source-text)
        upstream-report (sh05-macro-artifact-verification sh05-artifact)
        _ (when-not (= :passed (:status upstream-report))
            (sh06-resolution-boundary-fail!
             "C5-UNRESOLVED" source-path
             :fresh-authenticated-sh05-input upstream-report {}))
        request (sh06-resolution-request source-path sh05-artifact)
        binding (sh06-resolution-current-binding! source-path)
        run (sh06-resolution-run-request! source-path binding request)
        analysis (:resolved-analysis run)
        projections (sh06-resolution-product-projections analysis)
        plan-binding (dissoc binding :plan :source-text)
        boundary-base
        {:slice :SH-06
         :owner :gravity-source
         :adapter-contract sh06-resolution-adapter-contract
         :plan-binding plan-binding
         :authenticated-resolution-request request
         :raw-template-result (:raw-template-result run)
         :raw-analysis (:raw-analysis run)
         :resolved-analysis analysis
         :digest-requests (:digest-requests run)
         :resolved-digests (:resolved-digests run)
         :template-verification (:template-verification run)
         :resolved-verification (:resolved-verification run)
         :target-source-reread? false
         :clojure-adapter-residual? true
         :self-hosted? false}
        artifact-base
        (merge
         {:kind :gravity/sh06-resolution-artifact
          :status :accepted
          :slice :SH-06
          :task "SH-06"
          :document-set ["L3" "C5"]
          :governing-document c5-resolution-governing-document
          :artifact-id nil
          :sh05-macro-artifact sh05-artifact
          :gravity-resolution-boundary boundary-base
          :provenance
          {:source-path source-path
           :source-revision-id (get-in request
                                       [:module :source-revision-id])}
          :pass
          {:name :sh06-gravity-name-resolution
           :input :authenticated-sh05-expanded-syntax
           :output :authenticated-sh06-namespace-analysis
           :preserves [:source-spans :syntax-ids :macro-lineage
                       :profile :target :effects :capabilities]
           :rejects c5-resolution-diagnostic-ids}
          :execution-boundary
          {:resolution-authority :gravity
           :gravity-module 'gravity.resolution
           :plan-runner :clojure-stage0
           :digest-resolver :clojure-stage0
           :envelope-binder :clojure-stage0
           :compatibility-adapter :clojure-stage0
           :component-transport-bounds sh06-resolution-transport-bounds
           :aggregate-artifact-bounds sh06-resolution-artifact-bounds
           :self-hosted? false}
          :capability-based-proof nil
          :diagnostics []}
         projections)
        artifact-id (sh06-resolution-artifact-id artifact-base)
        artifact-with-id (assoc artifact-base :artifact-id artifact-id)
        summary (sh06-resolution-envelope-summary artifact-with-id)
        descriptor
        (sh06-resolution-sh02-descriptor source-path binding summary)
        envelope
        (p15-s23-stage2-sh02-descriptor-envelope
         sh06-resolution-envelope-stage
         sh06-resolution-sealed-artifact-kind descriptor source-path)
        _ (p15-s23-stage2-sh02-descriptor-envelope-verify!
           envelope sh06-resolution-envelope-stage
           sh06-resolution-sealed-artifact-kind descriptor source-path)
        artifact-with-envelope
        (-> artifact-with-id
            (assoc-in [:gravity-resolution-boundary
                       :authenticated-envelope-descriptor] descriptor)
            (assoc-in [:gravity-resolution-boundary
                       :authenticated-envelope] envelope))]
    artifact-with-envelope)))

(defn- sh06-resolution-finalize-candidate
  [source-path artifact-with-envelope]
  (let [proof
        (sh06-resolution-capability-based-proof-for-construction
         artifact-with-envelope)
        artifact
        (assoc artifact-with-envelope :capability-based-proof proof)]
    ;; The construction report above already replayed the exact authenticated
    ;; request and every stored run product.  The only post-construction change
    ;; is installing that report as the embedded proof, so a second identical
    ;; Gravity replay here would add cost without checking a new semantic fact.
    (when-not (and (= :complete (:status proof))
                   (empty? (:failed-checks proof))
                   (= proof (:capability-based-proof artifact)))
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED" source-path
       :final-authenticated-resolution-artifact
       (cond-> {:failed-checks (:failed-checks proof)}
         (:preflight-observations proof)
         (assoc :preflight-observations
                (:preflight-observations proof))
         (:carrier-validation proof)
         (assoc :carrier-validation
                (:carrier-validation proof)))
       {}))
    artifact))

(defn sh06-resolution-source-artifact
  [source-path source-text]
  (with-sh06-resolution-transport-bounds
   (sh06-resolution-finalize-candidate
    source-path
    (sh06-resolution-source-artifact-candidate source-path source-text))))

(defn sh06-resolution-file-artifact
  [source-path]
  (let [c2-artifact (compiler-c2-reader-file-artifact source-path)
        source-text (c2-reader-artifact-source-text source-path c2-artifact)]
    (sh06-resolution-source-artifact source-path source-text)))

(defn sh06-resolution-utf8-byte-count-up-to
  [^String text maximum]
  (let [length (.length text)]
    (loop [index 0 byte-count 0]
      (if (or (>= index length) (> byte-count maximum))
        byte-count
        (let [code (int (.charAt text index))]
          (cond
            (<= code 0x7f)
            (recur (inc index) (inc byte-count))

            (<= code 0x7ff)
            (recur (inc index) (+ byte-count 2))

            (and (<= 0xd800 code 0xdbff)
                 (< (inc index) length)
                 (let [low (int (.charAt text (inc index)))]
                   (<= 0xdc00 low 0xdfff)))
            (recur (+ index 2) (+ byte-count 4))

            :else
            (recur (inc index) (+ byte-count 3))))))))

(defn sh06-resolution-bounded-pr-str
  [source-path artifact]
  (let [maximum (:maximum-serialized-bytes
                 sh06-resolution-artifact-bounds)
        builder (StringBuilder.)
        byte-count (volatile! 0)
        pending-high? (volatile! false)
        char-array-class (Class/forName "[C")]
    (letfn [(add-bytes! [amount]
              (let [observed (vswap! byte-count + amount)]
                (when (> observed maximum)
                  (sh06-resolution-boundary-fail!
                   "C5-UNRESOLVED" source-path
                   :maximum-resolution-serialization-bytes
                   {:observed-serialized-bytes observed
                    :maximum-serialized-bytes maximum}
                   {:aggregate-artifact-bounds
                    sh06-resolution-artifact-bounds}))))
            (consume-code! [code]
              (if @pending-high?
                (if (<= 0xdc00 code 0xdfff)
                  (do (vreset! pending-high? false)
                      (add-bytes! 4))
                  (do (vreset! pending-high? false)
                      (add-bytes! 3)
                      (consume-code! code)))
                (cond
                  (<= code 0x7f) (add-bytes! 1)
                  (<= code 0x7ff) (add-bytes! 2)
                  (<= 0xd800 code 0xdbff) (vreset! pending-high? true)
                  :else (add-bytes! 3))))
            (append-range! [value offset length]
              (dotimes [ordinal length]
                (let [index (+ offset ordinal)
                      code
                      (if (string? value)
                        (int (.charAt ^String value index))
                        (int (aget ^chars value index)))]
                  (consume-code! code)))
              (if (string? value)
                (.append builder ^String value offset (+ offset length))
                (.append builder ^chars value offset length)))]
      (let [writer
            (proxy [java.io.Writer] []
              (write
                ([value]
                 (cond
                   (integer? value)
                   (let [character (char value)]
                     (consume-code! (int character))
                     (.append builder character))

                   (string? value)
                   (append-range! value 0 (.length ^String value))

                   (instance? char-array-class value)
                   (append-range! value 0 (alength ^chars value))

                   :else
                   (throw
                    (IllegalArgumentException.
                     (str "unsupported writer value " (class value))))))
                ([value offset length]
                 (append-range! value offset length)))
              (flush [])
              (close []))]
        (binding [*out* writer]
          (pr artifact)
          (.flush writer))
        (when @pending-high?
          (vreset! pending-high? false)
          (add-bytes! 3))
        (str builder)))))

(defn sh06-resolution-serialize
  [artifact]
  (let [report (sh06-resolution-artifact-verification artifact)]
    (when-not (= :passed (:status report))
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED"
       (or (get-in artifact [:provenance :source-path])
           "<sh06-resolution-serialize>")
       :verified-resolution-artifact-before-serialization
       (:failed-checks report) {}))
    (let [source-path
          (or (get-in artifact [:provenance :source-path])
              "<sh06-resolution-serialize>")]
      (try
        (sh06-resolution-bounded-pr-str source-path artifact)
        (catch InterruptedException interrupted
          (.interrupt (Thread/currentThread))
          (throw interrupted))
        (catch StackOverflowError error
          (sh06-resolution-boundary-fail!
           "C5-UNRESOLVED" source-path
           :contained-resolution-serialization-resource
           {:contained-host-error (.getName (class error))}
           {:aggregate-artifact-bounds sh06-resolution-artifact-bounds}))
        (catch OutOfMemoryError error
          (sh06-resolution-boundary-fail!
           "C5-UNRESOLVED" source-path
           :contained-resolution-serialization-resource
           {:contained-host-error (.getName (class error))}
           {:aggregate-artifact-bounds
            sh06-resolution-artifact-bounds}))))))

(defn sh06-resolution-deserialize
  [serialized]
  (let [maximum (:maximum-serialized-bytes
                 sh06-resolution-artifact-bounds)
        serialized-byte-count
        (cond
          (string? serialized)
          (sh06-resolution-utf8-byte-count-up-to serialized maximum)

          (= (class serialized) (Class/forName "[B"))
          (alength ^bytes serialized)

          :else nil)
        _
        (when-not (and (some? serialized-byte-count)
                       (<= serialized-byte-count maximum))
          (sh06-resolution-boundary-fail!
           "C5-UNRESOLVED" "<sh06-resolution-deserialize>"
           :bounded-resolution-serialization-bytes
           {:serialized-class
            (when (some? serialized) (.getName (class serialized)))
            :observed-serialized-bytes serialized-byte-count
            :maximum-serialized-bytes maximum}
           {:aggregate-artifact-bounds sh06-resolution-artifact-bounds}))
        artifact
        (try
          (let [serialized-text
                (if (string? serialized)
                  serialized
                  (String. ^bytes serialized
                           java.nio.charset.StandardCharsets/UTF_8))]
            (edn/read-string
             {:readers *data-readers* :default tagged-literal}
             serialized-text))
          (catch InterruptedException interrupted
            (.interrupt (Thread/currentThread))
            (throw interrupted))
          (catch Throwable error
            (sh06-resolution-boundary-fail!
             "C5-UNRESOLVED" "<sh06-resolution-deserialize>"
             :canonical-resolution-serialization
             {:serialized-class
              (when (some? serialized) (.getName (class serialized)))}
             {:contained-host-error (.getName (class error))})))
        report (sh06-resolution-artifact-verification artifact)]
    (when-not (= :passed (:status report))
      (sh06-resolution-boundary-fail!
       "C5-UNRESOLVED"
       (or (get-in artifact [:provenance :source-path])
           "<sh06-resolution-deserialize>")
       :verified-resolution-artifact-after-deserialization
       (:failed-checks report) {}))
    artifact))

(def compiler-c5-stage0-legacy-source-artifact
  compiler-c5-resolution-source-artifact)

(defn sh06-resolution-slice-source?
  [source-path source-text]
  (try
    (let [c2 (compiler-c2-reader-source-artifact source-path source-text)
          forms (:parsed-semantic-values c2)
          module (parse-module source-path forms)]
      (= :SH-06 (get-in module [:metadata :slice])))
    (catch clojure.lang.ExceptionInfo _ false)))

(defn compiler-c5-resolution-source-artifact
  [source-path source-text]
  (if (sh06-resolution-slice-source? source-path source-text)
    (sh06-resolution-source-artifact source-path source-text)
    (compiler-c5-stage0-legacy-source-artifact source-path source-text)))

;; SH-07-A/B1/B2/B3/B4/B5/B6/B7/B8/B9/B10/B11/B12/B13/B15 is the checked-core projection
;; owned by Gravity source.
;; The coordinator authenticates the verified SH-06 carrier, projects the
;; bounded literal/function/control-flow subset, resolves declared digest
;; requests, and keeps physical paths out of semantic identity.
(def sh07-core-source-relative-path
  "bootstrap/gravity/src/gravity/checked_core.gravity")

(def sh07-core-adapter-contract
  :gravity/sh07-to-c6-core-products-v15)

(def sh07-core-governing-document
  "docs/phase-06-compiler-architecture/085-c6-ast-and-core-lowering-design.md")

(def sh07-core-public-function-shapes
  {'sh07-build-core-template {:arity 1 :params '[request]}
   'sh07-verify-core-template
   {:arity 3 :params '[request template digest-requests]}
   'sh07-verify-core-resolved
   {:arity 4
    :params '[request resolved-core digest-requests resolved-digests]}})

(def sh07-core-expected-source-byte-count 407721)
(def sh07-core-expected-source-content-hash
  "sha256:c020a0344d42569577e8baa6e28a2ce210f3eb76f774ff25490ddb18390d93e0")
(def sh07-core-expected-plan-semantic-hash
  "sha256:c4f79830786a206261f0526b2a225fe0772a6443e2b001c0da8118bf13bb9dd1")
(def sh07-core-expected-functions-semantic-hash
  "sha256:49a446f8af1db428caf2f4722fae0f80a4a64cc9a5a99d9e2cda3eebe1950db7")
(def sh07-core-expected-function-count 274)
(def sh07-core-expected-function-names-hash
  "sha256:a7f23daf98ea3e8be0bf4ab562741bb538c1220401d6a450d986b98611933835")
(def sh07-core-expected-function-shapes-hash
  "sha256:210056984bad174006b1a74de2ba9cbb6cb71743b0f81e6ddece19e3101a7b96")
(def sh07-core-public-function-hashes
  {'sh07-build-core-template
   "sha256:3c986f70123a51afb4e788199f559b1d571afd825c2ba72c0a53675eb5c34948"
   'sh07-verify-core-template
   "sha256:f54b579ad1647cf020605bca95ed296bbe5744401c8b56c8806edc8180edf23b"
   'sh07-verify-core-resolved
   "sha256:729d28b08a3cb19dc1d22b70deb807c5b470c7a0bdcc48e83da8eb4a24c5ad6e"})

(defn sh07-core-source-path
  []
  (let [anchor (java.io.File.
                (p15-s23-stage2-compiler-artifact-source-path))
        start (if (.isDirectory anchor) anchor (.getParentFile anchor))]
    (or
     (loop [directory start]
       (when directory
         (let [candidate
               (java.io.File. directory sh07-core-source-relative-path)]
           (if (.isFile candidate)
             (.getPath candidate)
             (recur (.getParentFile directory))))))
     sh07-core-source-relative-path)))

(defn sh07-core-plan-identities
  [plan]
  (let [functions (:functions plan)
        shapes
        (into (sorted-map)
              (map (fn [[name function]]
                     [name (select-keys function [:arity :params])]))
              functions)]
    {:plan-semantic-hash
     (p15-s23-c11-mir-digest
      (p15-s23-stage2-compiler-artifact-semantic-input plan))
     :functions-semantic-hash (p15-s23-c11-mir-digest functions)
     :function-count (count functions)
     :function-names-hash
     (p15-s23-c11-mir-digest (vec (keys functions)))
     :function-shapes-hash (p15-s23-c11-mir-digest shapes)
     :public-function-hashes
     (into (sorted-map)
           (map (fn [name]
                  [name (p15-s23-c11-mir-digest (get functions name))]))
           (keys sh07-core-public-function-shapes))
     :public-function-shapes
     (select-keys shapes (keys sh07-core-public-function-shapes))}))

(defn sh07-core-build-binding!
  []
  (let [source-path (sh07-core-source-path)
        bytes (java.nio.file.Files/readAllBytes
               (.toPath (java.io.File. source-path)))
        source-text
        (String. bytes java.nio.charset.StandardCharsets/UTF_8)
        source-hash (str "sha256:" (sha256-bytes-hex bytes))
        emitter
        (:emitter
         (c-backend-stage2-plan-emitter-source-rule! source-path :jvm))
        plan
        (p15-s23-stage2-compiler-artifact-plan
         emitter source-path source-text)
        identities (sh07-core-plan-identities plan)]
    (when-not
     (and (= sh07-core-expected-source-byte-count (alength bytes))
          (= sh07-core-expected-source-content-hash source-hash)
          (= sh07-core-expected-plan-semantic-hash
             (:plan-semantic-hash identities))
          (= sh07-core-expected-functions-semantic-hash
             (:functions-semantic-hash identities))
          (= sh07-core-expected-function-count
             (:function-count identities))
          (= sh07-core-expected-function-names-hash
             (:function-names-hash identities))
          (= sh07-core-expected-function-shapes-hash
             (:function-shapes-hash identities))
          (= sh07-core-public-function-hashes
             (:public-function-hashes identities))
          (= sh07-core-public-function-shapes
             (:public-function-shapes identities))
          (= 'gravity.checked-core (get-in plan [:module :module]))
          (= :meta (get-in plan [:module :profile]))
          (= :jvm (get-in plan [:module :target]))
          (= #{} (get-in plan [:module :effects]))
          (= #{} (get-in plan [:module :capabilities]))
          (= :safe (get-in plan [:module :safety])))
      (throw
       (ex-info "Pinned SH-07 checked-core source or plan changed"
                {:id "C6-VERIFY"
                 :stage :core-lowering
                 :missing-fields [:pinned-sh07-core-plan]
                 :observed
                 (merge {:source-byte-count (alength bytes)
                         :source-content-hash source-hash}
                        identities)})))
    (merge
     {:artifact :gravity/sh07-pinned-core-plan-binding
      :source-path source-path
      :source-byte-count (alength bytes)
      :source-content-hash source-hash
      :plan plan
      :semantic-authority :gravity-source
      :compiled-by :clojure-stage0-seed
      :executed-by :clojure-stage2-generic-rule-runner
      :generic-bridge-residual? true
      :self-hosted? false}
     identities)))

(def ^:private sh07-core-cached-binding
  (delay (sh07-core-build-binding!)))

(defn sh07-core-execute!
  [source-path function arguments]
  (try
    (sh04-syntax-strip-host-metadata
     (p15-s23-stage2-runtime-execute-function
      {:engine :gravity-sh07-pinned-core-runner
       :compiler-artifact-plan? true}
      (:plan @sh07-core-cached-binding)
      function
      (sh04-syntax-strip-host-metadata arguments)))
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch StackOverflowError error
      (throw (ex-info "SH-07 core boundary rejected host stack exhaustion"
                      {:id "C6-VERIFY" :stage :core-lowering
                       :source-path source-path
                       :contained-host-error (.getName (class error))})))
    (catch OutOfMemoryError error
      (throw (ex-info "SH-07 core boundary rejected host memory exhaustion"
                      {:id "C6-VERIFY" :stage :core-lowering
                       :source-path source-path
                       :contained-host-error (.getName (class error))})))
    (catch AssertionError error
      (throw (ex-info "SH-07 core boundary contained an assertion"
                      {:id "C6-VERIFY" :stage :core-lowering
                       :source-path source-path
                       :contained-host-error (.getName (class error))})))
    (catch LinkageError error
      (throw (ex-info "SH-07 core boundary contained a linkage failure"
                      {:id "C6-VERIFY" :stage :core-lowering
                       :source-path source-path
                       :contained-host-error (.getName (class error))})))
    (catch clojure.lang.ExceptionInfo error
      (throw error))
    (catch Exception error
      (throw (ex-info "SH-07 core boundary contained a host failure"
                      {:id "C6-VERIFY" :stage :core-lowering
                       :source-path source-path
                       :contained-host-error (.getName (class error))}
                      error)))))

(defn sh07-core-source-path-from-resolution
  [resolution-artifact]
  (or (get-in resolution-artifact [:provenance :source-path])
      (get-in resolution-artifact
              [:gravity-resolution-boundary
               :authenticated-resolution-request
               :provenance :actual-source-path])
      "<sh07-core-input>"))

(defn sh07-core-semantic-span
  [span]
  (select-keys
   (or (:primary span) span {})
   [:byte-start :byte-end :line-start :column-start
    :line-end :column-end :scalar-start :scalar-end]))

(defn sh07-core-value-kind
  [value]
  (cond
    (nil? value) :nil
    (boolean? value) :boolean
    (integer? value) :integer
    (or (instance? java.math.BigDecimal value)
        (instance? Double value)
        (instance? Float value)) :decimal
    (ratio? value) :ratio
    (char? value) :character
    (string? value) :string
    (keyword? value) :keyword
    (symbol? value) :symbol
    (vector? value) :vector
    (map? value) :map
    (set? value) :set
    (seq? value) :list
    :else :unsupported))

(defn sh07-core-children
  [value]
  (cond
    (map? value) (vec (mapcat identity value))
    (set? value) (vec (sort-by pr-str value))
    (or (vector? value) (seq? value)) (vec value)
    :else []))

(defn sh07-core-decimal-descriptor
  [source-path value evidence projection-form-id]
  (let [decimal ^java.math.BigDecimal value
        scale (long (.scale decimal))
        unscaled (.unscaledValue decimal)]
    (when-not
     (and evidence
          (= :decimal (:kind evidence))
          (= value (:decoded evidence))
          (<= (.bitLength ^java.math.BigInteger unscaled)
              p15-s23-c6c10-max-integer-bits)
          (<= (Math/abs scale) 65536))
      (throw
       (ex-info "Decimal literal is not exactly bound to bounded C2 evidence"
                {:id "C6-ORIGIN" :stage :core-lowering
                 :source-path source-path
                 :reason :exact-bounded-decimal-c2-evidence})))
    {:kind :gravity/arbitrary-decimal-literal
     :unscaled-value (.toString unscaled)
     :scale scale
     :literal-id
     (reader-canonical-hash
      {:domain :gravity/sh07-c2-decimal-literal-evidence-v1
       :literal-id (:literal-id evidence)
       :form-id (:form-id evidence)})
     :form-id
     (reader-canonical-hash
      {:domain :gravity/sh07-c2-decimal-form-evidence-v1
       :form-id (:form-id evidence)
       :literal-id (:literal-id evidence)})
     :token-id
     (reader-canonical-hash
      {:domain :gravity/sh07-c2-decimal-token-evidence-v1
       :token-id (:token-id evidence)
       :literal-id (:literal-id evidence)
       :form-id (:form-id evidence)})
     :projection-form-id projection-form-id}))

(defn sh07-core-decimal-evidence
  [resolution-artifact]
  (let [records
        (get-in
         resolution-artifact
         [:sh05-macro-artifact :gravity-macro-boundary
          :authenticated-sh04-artifact :c2-reader-artifact
          :literal-decoding-records])]
    {:records
     (reduce
      (fn [result record]
        (if (instance? java.math.BigDecimal (:decoded record))
          (update result
                  (p15-s23-c6c10-literal-scalar-descriptor
                   (:decoded record))
                  (fnil conj []) record)
          result))
      {}
      records)
     :next (atom {})
     :cache (atom {})}))

(defn sh07-core-projected-form-id
  [source-revision-id root-syntax-id path kind]
  (reader-canonical-hash
   {:domain :gravity/sh07-form-occurrence-v1
    :source-revision-id source-revision-id
    :root-syntax-id root-syntax-id
    :path path
    :kind kind}))

(defn sh07-core-projected-syntax-id
  [source-revision-id root-syntax-id path kind trace]
  (cond
    (empty? path)
    root-syntax-id

    (and trace (= path [2]))
    (:introduced-fn-syntax-id trace)

    :else
    (reader-canonical-hash
     {:domain :gravity/sh07-form-syntax-v1
      :source-revision-id source-revision-id
      :root-syntax-id root-syntax-id
      :path path
      :kind kind})))

(defn sh07-core-neutral-value
  [source-path source-revision-id root-syntax-id path
   decimal-evidence value]
  (cond
    (instance? java.math.BigDecimal value)
    (let [descriptor (p15-s23-c6c10-literal-scalar-descriptor value)
          cache-key [root-syntax-id path]
          cached (get @(:cache decimal-evidence) cache-key)]
      (or
       cached
       (let [ordinal (get @(:next decimal-evidence) descriptor 0)
             evidence (get-in decimal-evidence
                              [:records descriptor ordinal])
             projection-form-id
             (sh07-core-projected-form-id
              source-revision-id root-syntax-id path :decimal)
             result
             (sh07-core-decimal-descriptor
              source-path value evidence projection-form-id)]
         (swap! (:next decimal-evidence) assoc descriptor (inc ordinal))
         (swap! (:cache decimal-evidence) assoc cache-key result)
         result)))
    (map? value)
    (into {}
          (map-indexed
           (fn [index [key child]]
             [(sh07-core-neutral-value
               source-path source-revision-id root-syntax-id
               (conj path (* 2 index))
               decimal-evidence key)
              (sh07-core-neutral-value
               source-path source-revision-id root-syntax-id
               (conj path (inc (* 2 index)))
               decimal-evidence child)]))
          value)
    (vector? value)
    (mapv
     (fn [index child]
       (sh07-core-neutral-value
        source-path source-revision-id root-syntax-id
        (conj path index) decimal-evidence child))
     (range) value)
    (set? value)
    (into #{}
          (map-indexed
           (fn [index child]
             (sh07-core-neutral-value
              source-path source-revision-id root-syntax-id
              (conj path index) decimal-evidence child)))
          (sort-by pr-str value))
    (seq? value)
    (apply list
           (map-indexed
            (fn [index child]
              (sh07-core-neutral-value
               source-path source-revision-id root-syntax-id
               (conj path index) decimal-evidence child))
            value))
    :else value))

(defn sh07-core-macro-trace
  [lineage sh05-step]
  (let [input-id (:input-syntax-id sh05-step)
        output-id (:output-syntax-id sh05-step)
        fn-id
        (reader-canonical-hash
         {:domain :gravity/sh07-introduced-fn-syntax-v1
          :input-syntax-id input-id
          :output-def-syntax-id output-id})
        def-origin-id
        (reader-canonical-hash
         {:domain :gravity/sh07-def-generated-origin-v1
          :input-syntax-id input-id :output-syntax-id output-id})
        fn-origin-id
        (reader-canonical-hash
         {:domain :gravity/sh07-fn-generated-origin-v1
          :input-syntax-id input-id :fn-syntax-id fn-id})]
    {:macro 'defn
     :input-syntax-id input-id
     :output-def-syntax-id output-id
     :introduced-fn-syntax-id fn-id
     :def-generated-origin-id def-origin-id
     :fn-generated-origin-id fn-origin-id
     :source-revision-id (:source-revision-id lineage)
     :sh05-artifact-id (:sh05-artifact-id lineage)
     :macro-expansion-trace-id (:macro-expansion-trace-id lineage)}))

(defn sh07-core-root-syntax-id
  [source-revision-id ordinal form]
  (reader-canonical-hash
   {:domain :gravity/sh07-root-syntax-v1
    :source-revision-id source-revision-id
    :ordinal ordinal
    :form
    (sh05-path-neutral-semantic-value form)}))

(defn sh07-core-decimal-evidence-complete!
  [source-path decimal-evidence]
  (doseq [[descriptor records] (:records decimal-evidence)]
    (let [consumed (get @(:next decimal-evidence) descriptor 0)]
      (when-not (= consumed (count records))
        (throw
         (ex-info "SH-07 decimal occurrence evidence is not bijective"
                  {:id "C6-ORIGIN" :stage :core-lowering
                   :source-path source-path
                   :reason :decimal-c2-occurrence-bijection
                   :descriptor descriptor
                   :expected-occurrences (count records)
                   :observed-occurrences consumed})))))
  :passed)

(defn sh07-core-semantic-macro-trace
  [trace]
  (mapv
   (fn [ordinal step]
     {:artifact :gravity/sh07-preserved-macro-expansion-step
      :ordinal ordinal
      :macro (:macro step)
      :profile (:profile step)
      :target (:target step)
      :step (:step step)
      :capabilities
      (sh05-path-neutral-semantic-value (:capabilities step))
      :build-effects
      (sh05-path-neutral-semantic-value (:build-effects step))
      :diagnostics
      (sh05-path-neutral-semantic-value (:diagnostics step))})
   (range)
   trace))

(defn sh07-core-build-form-tree
  [source-path source-revision-id decimal-evidence syntax trace]
  (let [root-id (:sh07/root-syntax-id syntax)
        source-span (sh07-core-semantic-span (:span syntax))
        trace? (and trace (= root-id (:output-def-syntax-id trace)))
        records (atom [])]
    (letfn [(walk [value path parent-form-id]
              (let [kind (sh07-core-value-kind value)
                    syntax-id
                    (sh07-core-projected-syntax-id
                     source-revision-id root-id path kind
                     (when trace? trace))
                    form-id
                    (sh07-core-projected-form-id
                     source-revision-id root-id path kind)
                    children (sh07-core-children value)
                    child-records
                    (mapv
                     (fn [index child]
                       (walk child (conj path index) form-id))
                     (range) children)
                    generated-origin
                    (cond
                      (and trace? (empty? path))
                      [{:origin-id (:def-generated-origin-id trace)
                        :kind :macro-expansion
                        :from-syntax-id (:input-syntax-id trace)
                        :role :introduced-def}]
                      (and trace? (= path [2]))
                      [{:origin-id (:fn-generated-origin-id trace)
                        :kind :macro-expansion
                        :from-syntax-id (:input-syntax-id trace)
                        :role :introduced-fn}]
                      :else [])
                    record
                    {:form-id form-id
                     :syntax-id syntax-id
                     :kind kind
                     :value
                     (sh07-core-neutral-value
                      source-path source-revision-id root-id path
                      decimal-evidence value)
                     :parent-form-id parent-form-id
                     :child-form-ids (mapv :form-id child-records)
                     :source-span source-span
                     :origin-chain []
                     :generated-origin generated-origin
                     :metadata
                     (sh05-path-neutral-semantic-value
                      (or (meta value) {}))
                     :scope-id nil}]
                (swap! records conj record)
                record))]
      (let [root (walk (:form syntax) [] nil)]
        {:root root :records @records}))))

(defn sh07-core-parameter-binding-paths
  [parameters parameter-path]
  (loop [remaining (seq (if (sequential? parameters) parameters []))
         index 0
         result []]
    (if (empty? remaining)
      result
      (let [item (first remaining)]
        (cond
          (= item ':-)
          (recur (nnext remaining) (+ index 2) result)

          (= item '&)
          (recur (next remaining) (inc index) result)

          (symbol? item)
          (recur
           (next remaining)
           (inc index)
           (conj result
                 {:name item
                  :path (conj parameter-path index)}))

          :else
          (recur (next remaining) (inc index) result))))))

(defn sh07-core-resolution-projection!
  [source-path source-revision-id executable-syntax trees traces
   authenticated-sh06-request resolved-analysis]
  (let [upstream-scopes (vec (:lexical-scopes authenticated-sh06-request))
        upstream-references (vec (:references authenticated-sh06-request))
        resolved-references (vec (:resolution-table resolved-analysis))
        resolved-by-reference
        (into {} (map (juxt :syntax-id identity)) resolved-references)
        resolved-binding-by-id
        (into {} (map (juxt :binding-id identity))
              (:binding-table resolved-analysis))
        namespace-root-scope-id
        (reader-canonical-hash
         {:domain :gravity/sh07-projected-namespace-root-scope-v1
          :source-revision-id source-revision-id
          :namespace
          (get-in resolved-analysis [:module-contract :namespace])})
        scope-index (atom 0)
        reference-index (atom 0)
        projected-scope-by-upstream (atom {})
        scope-by-syntax-id (atom {})
        declaration-syntax-by-upstream-id (atom {})
        occurrences (atom [])
        trace-by-root (into {} (map (juxt :output-def-syntax-id identity))
                            traces)
        root-by-upstream-id
        (into {}
              (map (fn [[syntax tree]]
                     [(:syntax/id syntax) (:root tree)]))
              (map vector executable-syntax trees))
        projected-syntax-id
        (fn [syntax path value]
          (sh07-core-projected-syntax-id
           source-revision-id
           (:sh07/root-syntax-id syntax)
           path
           (sh07-core-value-kind value)
           (get trace-by-root (:sh07/root-syntax-id syntax))))
        remember-scope!
        (fn [syntax path value scope-chain]
          (swap! scope-by-syntax-id
                 assoc
                 (projected-syntax-id syntax path value)
                 (or (get @projected-scope-by-upstream
                          (first scope-chain))
                     namespace-root-scope-id)))
        consume-scope!
        (fn [syntax parent-scope-id bindings]
          (let [index @scope-index
                scope (get upstream-scopes index)
                projected-scope-id
                (reader-canonical-hash
                 {:domain :gravity/sh07-projected-lexical-scope-v1
                  :source-revision-id source-revision-id
                  :ordinal index
                  :parent-scope-id
                  (or (get @projected-scope-by-upstream parent-scope-id)
                      namespace-root-scope-id)
                  :binding-names (mapv :name bindings)})]
            (when-not
             (and scope
                  (= (:syntax/id syntax) (:owner-syntax-id scope))
                  (= parent-scope-id (:parent-scope-id scope))
                  (= (mapv :name bindings)
                     (mapv #(get-in % [:name]) (:bindings scope))))
              (throw
               (ex-info "SH-07 lexical scope projection is not bijective"
                        {:id "C6-VERIFY" :stage :core-lowering
                         :source-path source-path
                         :reason :sh06-lexical-scope-projection-mismatch
                         :scope-index index})))
            (swap! scope-index inc)
            (swap! projected-scope-by-upstream
                   assoc (:scope-id scope) projected-scope-id)
            (assoc scope :sh07/projected-scope-id projected-scope-id)))
        add-reference!
        (fn [syntax path symbol position scope-chain]
          (let [index @reference-index
                upstream (get upstream-references index)
                resolved (get resolved-by-reference (:syntax-id upstream))
                resolved-binding
                (get resolved-binding-by-id (:binding-id resolved))
                expected-upstream-id
                (reader-canonical-hash
                 {:domain :gravity/sh06-reference-syntax-v1
                  :owner-syntax-id (:syntax/id syntax)
                  :ordinal (inc index)
                  :symbol symbol
                  :position position})
                projected-id (projected-syntax-id syntax path symbol)]
            (when-not
             (and upstream resolved
                  (= expected-upstream-id (:syntax-id upstream))
                  (= symbol (:symbol upstream) (:symbol resolved))
                  (= position (:position upstream) (:position resolved))
                  (= (:syntax-id upstream) (:syntax-id resolved))
                  (= (vec scope-chain) (:scope-chain upstream))
                  (= (:semantic-span upstream) (:semantic-span resolved))
                  resolved-binding
                  (or (not= :lexical (:binding-class resolved-binding))
                      (some #{(:scope-id resolved-binding)}
                            scope-chain)))
              (throw
               (ex-info "SH-07 reference projection is not bijective"
                        {:id "C6-VERIFY" :stage :core-lowering
                         :source-path source-path
                         :reason :sh06-reference-projection-mismatch
                         :reference-index index
                         :symbol symbol :position position})))
            (swap! reference-index inc)
            (swap! occurrences conj
                   {:reference-syntax-id projected-id
                    :symbol symbol
                    :position position
                    :binding-id (:binding-id resolved)
                    :resolution-order (:resolution-order resolved)
                    :source-span
                    (sh07-core-semantic-span (:source-span resolved))})))]
    (letfn [(walk [syntax value path scope-chain position]
              (remember-scope! syntax path value scope-chain)
              (cond
                (symbol? value)
                (add-reference! syntax path value position scope-chain)

                (seq? value)
                (let [items (vec value)
                      operator (first items)]
                  (cond
                    (= operator 'quote)
                    (add-reference! syntax (conj path 0) 'quote
                                    :operator scope-chain)

                    (= operator 'syntax-quote)
                    (add-reference! syntax (conj path 0) operator
                                    :operator scope-chain)

                    (contains? '#{def defconst} operator)
                    (do
                      (add-reference! syntax (conj path 0) operator
                                      :operator scope-chain)
                      (doseq [index (range 2 (count items))]
                        (walk syntax (get items index) (conj path index)
                              scope-chain :expression)))

                    (= operator 'defn)
                    (throw
                     (ex-info "Unexpanded defn reached SH-07 projection"
                              {:id "C6-VERIFY" :stage :core-lowering
                               :source-path source-path
                               :reason :unexpanded-defn}))

                    (= operator 'fn)
                    (let [named? (symbol? (second items))
                          parameter-index (if named? 2 1)
                          parameters (get items parameter-index [])
                          binding-paths
                          (cond-> (sh07-core-parameter-binding-paths
                                   parameters
                                   (conj path parameter-index))
                            named?
                            (conj {:name (second items)
                                   :path (conj path 1)}))
                          scope
                          (consume-scope!
                           syntax (first scope-chain) binding-paths)
                          nested (cons (:scope-id scope) scope-chain)]
                      (swap! scope-by-syntax-id
                             assoc
                             (projected-syntax-id syntax path value)
                             (:sh07/projected-scope-id scope))
                      (add-reference! syntax (conj path 0) 'fn
                                      :operator scope-chain)
                      (remember-scope!
                       syntax (conj path parameter-index)
                       parameters nested)
                      (doseq [[binding projected]
                              (map vector (:bindings scope) binding-paths)]
                        (let [syntax-id
                              (projected-syntax-id
                               syntax (:path projected) (:name projected))]
                          (swap! scope-by-syntax-id assoc syntax-id
                                 (:sh07/projected-scope-id scope))
                          (swap! declaration-syntax-by-upstream-id
                                 assoc (:binding-syntax-id binding)
                                 syntax-id)))
                      (doseq [index
                              (range (if named? 3 2) (count items))]
                        (walk syntax (get items index) (conj path index)
                              nested :expression)))

                    (= operator 'match)
                    (do
                      (add-reference! syntax (conj path 0) 'match
                                      :operator scope-chain)
                      (when (< 1 (count items))
                        (walk syntax (get items 1) (conj path 1)
                              scope-chain :expression))
                      (loop [pattern-index 2]
                        (when (< (+ pattern-index 1) (count items))
                          (let [pattern (get items pattern-index)
                                branch-index (+ pattern-index 1)
                                branch (get items branch-index)
                                pattern-path (conj path pattern-index)]
                            (cond
                              (and (symbol? pattern) (not= '_ pattern))
                              (let [scope
                                    (consume-scope!
                                     syntax
                                     (first scope-chain)
                                     [{:name pattern
                                       :path pattern-path}])
                                    syntax-id
                                    (projected-syntax-id
                                     syntax pattern-path pattern)
                                    nested
                                    (cons (:scope-id scope) scope-chain)]
                                (swap! scope-by-syntax-id assoc syntax-id
                                       (:sh07/projected-scope-id scope))
                                (swap!
                                 declaration-syntax-by-upstream-id
                                 assoc
                                 (get-in scope
                                         [:bindings 0
                                          :binding-syntax-id])
                                 syntax-id)
                                (walk syntax branch
                                      (conj path branch-index)
                                      nested :expression))

                              (and (vector? pattern)
                                   (sh06-fixed-vector-pattern? pattern))
                              (when-let
                                  [binding-paths
                                   (sh06-unique-match-binding-paths
                                    pattern pattern-path)]
                                (if (empty? binding-paths)
                                  (walk syntax branch
                                        (conj path branch-index)
                                        scope-chain :expression)
                                  (let [scope
                                        (consume-scope!
                                         syntax
                                         (first scope-chain)
                                         binding-paths)
                                        nested
                                        (cons (:scope-id scope)
                                              scope-chain)]
                                    (doseq
                                        [[binding projected]
                                         (map vector
                                              (:bindings scope)
                                              binding-paths)]
                                      (let [syntax-id
                                            (projected-syntax-id
                                             syntax
                                             (:path projected)
                                             (:name projected))]
                                        (swap!
                                         scope-by-syntax-id assoc syntax-id
                                         (:sh07/projected-scope-id scope))
                                        (swap!
                                         declaration-syntax-by-upstream-id
                                         assoc
                                         (:binding-syntax-id binding)
                                         syntax-id)))
                                    (walk syntax branch
                                          (conj path branch-index)
                                          nested :expression))))

                              (or (= '_ pattern)
                                  (nil? pattern)
                                  (true? pattern)
                                  (false? pattern)
                                  (number? pattern)
                                  (char? pattern)
                                  (string? pattern)
                                  (keyword? pattern))
                              (walk syntax branch
                                    (conj path branch-index)
                                    scope-chain :expression)

                              :else nil)
                            (recur (+ pattern-index 2))))))

                    (= operator 'try)
                    (do
                      (add-reference! syntax (conj path 0) 'try
                                      :operator scope-chain)
                      (doseq [index (range 1 (count items))]
                        (let [item (get items index)
                              item-path (conj path index)
                              clause-items
                              (when (seq? item) (vec item))
                              clause-operator (first clause-items)]
                          (cond
                            (= clause-operator 'catch)
                            (do
                              (add-reference!
                               syntax (conj item-path 0) 'catch
                               :operator scope-chain)
                              (when (< 1 (count clause-items))
                                (walk syntax (get clause-items 1)
                                      (conj item-path 1)
                                      scope-chain :type))
                              (let [binding-name (get clause-items 2)]
                                (when (symbol? binding-name)
                                  (let [binding-path (conj item-path 2)
                                        scope
                                        (consume-scope!
                                         syntax
                                         (first scope-chain)
                                         [{:name binding-name
                                           :path binding-path}])
                                        syntax-id
                                        (projected-syntax-id
                                         syntax binding-path binding-name)
                                        nested
                                        (cons (:scope-id scope)
                                              scope-chain)]
                                    (swap!
                                     scope-by-syntax-id assoc syntax-id
                                     (:sh07/projected-scope-id scope))
                                    (swap!
                                     declaration-syntax-by-upstream-id
                                     assoc
                                     (get-in
                                      scope
                                      [:bindings 0 :binding-syntax-id])
                                     syntax-id)
                                    (doseq [handler-index
                                            (range 3
                                                   (count clause-items))]
                                      (walk
                                       syntax
                                       (get clause-items handler-index)
                                       (conj item-path handler-index)
                                       nested :expression))))))

                            (= clause-operator 'finally)
                            (do
                              (add-reference!
                               syntax (conj item-path 0) 'finally
                               :operator scope-chain)
                              (doseq [cleanup-index
                                      (range 1 (count clause-items))]
                                (walk
                                 syntax
                                 (get clause-items cleanup-index)
                                 (conj item-path cleanup-index)
                                 scope-chain :expression)))

                            :else
                            (walk syntax item item-path
                                  scope-chain :expression)))))

                    (contains? '#{let loop} operator)
                    (let [binding-vector (second items)
                          pairs
                          (if (vector? binding-vector)
                            (partition 2 binding-vector)
                            [])
                          _ (add-reference! syntax (conj path 0) operator
                                            :operator scope-chain)
                          nested
                          (loop [remaining (seq pairs)
                                 binding-index 0
                                 active scope-chain]
                            (if (empty? remaining)
                              active
                              (let [[binding-name initializer]
                                    (first remaining)
                                    initializer-index
                                    (+ 2 (* binding-index 2))
                                    binding-path
                                    (conj path 1 (* binding-index 2))
                                    _ (walk syntax initializer
                                            (conj path 1
                                                  (inc (* binding-index 2)))
                                            active :expression)
                                    next-active
                                    (if (symbol? binding-name)
                                      (let [scope
                                            (consume-scope!
                                             syntax (first active)
                                             [{:name binding-name
                                               :path binding-path}])
                                            syntax-id
                                            (projected-syntax-id
                                             syntax binding-path binding-name)]
                                        (swap! scope-by-syntax-id assoc
                                               syntax-id
                                               (:sh07/projected-scope-id scope))
                                        (swap!
                                         declaration-syntax-by-upstream-id
                                         assoc
                                         (get-in scope
                                                 [:bindings 0
                                                  :binding-syntax-id])
                                         syntax-id)
                                        (cons (:scope-id scope) active))
                                      active)]
                                (recur (next remaining)
                                       (inc binding-index)
                                       next-active))))]
                      (doseq [index (range 2 (count items))]
                        (walk syntax (get items index) (conj path index)
                              nested :expression)))

                    :else
                    (doseq [index (range (count items))]
                      (let [item (get items index)]
                        (walk syntax item (conj path index) scope-chain
                              (if (zero? index)
                                :operator
                                position))))))

                (map? value)
                (doseq [[index [key child]] (map-indexed vector value)]
                  (walk syntax key (conj path (* 2 index))
                        scope-chain :expression)
                  (walk syntax child (conj path (inc (* 2 index)))
                        scope-chain :expression))

                (set? value)
                (let [ordered (vec (sort-by pr-str value))
                      path-by-value
                      (into {} (map-indexed (fn [index item] [item index]))
                            ordered)]
                  (doseq [item value]
                    (walk syntax item (conj path (get path-by-value item))
                          scope-chain position)))

                (coll? value)
                (doseq [index (range (count value))]
                  (walk syntax (nth value index) (conj path index)
                        scope-chain position))

                :else nil))]
      (doseq [syntax executable-syntax]
        (walk syntax (:form syntax) [] [] :expression)))
    (when-not
     (and (= @scope-index (count upstream-scopes))
          (= (count @projected-scope-by-upstream)
             (count upstream-scopes))
          (= @reference-index (count upstream-references))
          (= (count upstream-references) (count resolved-references)))
      (throw
       (ex-info "SH-07 resolution projection did not consume SH-06 inputs"
                {:id "C6-VERIFY" :stage :core-lowering
                 :source-path source-path
                 :reason :sh06-resolution-projection-incomplete
                 :scopes [@scope-index (count upstream-scopes)]
                 :references [@reference-index
                              (count upstream-references)
                              (count resolved-references)]})))
    (let [all-records (vec (mapcat :records trees))
          form-by-syntax (into {} (map (juxt :syntax-id identity))
                               all-records)
          namespace-definition-syntax
          (into {}
                (keep
                 (fn [[upstream-id root]]
                   (let [name-form
                         (get
                          (into {} (map (juxt :form-id identity))
                                all-records)
                          (second (:child-form-ids root)))]
                     (when name-form
                       [upstream-id (:syntax-id name-form)]))))
                root-by-upstream-id)
          binding-projections
          (mapv
           (fn [binding]
             (let [definition-syntax-id
                   (or
                    (get @declaration-syntax-by-upstream-id
                         (:definition-syntax-id binding))
                    (get namespace-definition-syntax
                         (:definition-syntax-id binding))
                    (:definition-syntax-id binding))
                   semantic-binding
                   {:name (:name binding)
                    :kind (:kind binding)
                    :binding-class (:binding-class binding)
                    :namespace (:namespace binding)
                    :package (:package binding)
                    :upstream-binding-id (:binding-id binding)
                    :scope-id (when (= :lexical (:binding-class binding))
                                (get @projected-scope-by-upstream
                                     (:scope-id binding)))
                    :definition-syntax-id definition-syntax-id
                    :definition-artifact-id
                    (:definition-artifact-id binding)
                    :visibility (:visibility binding)
                    :profile-set (:profile-set binding)
                    :target-set (:target-set binding)
                    :type-ref (:type-ref binding)
                    :effects (:effects binding)
                    :capabilities (:capabilities binding)
                    :safety (:safety binding)
                    :semantic-span (:semantic-span binding)}
                   projected-binding-id
                   (reader-canonical-hash
                    {:domain :gravity/sh07-projected-sh06-binding-v1
                     :source-revision-id source-revision-id
                     :binding
                     (dissoc semantic-binding
                             :upstream-binding-id
                             :definition-artifact-id)})]
               {:upstream-binding-id (:binding-id binding)
                :projected-binding
                (assoc semantic-binding :binding-id projected-binding-id)}))
           (:binding-table resolved-analysis))
          projected-binding-id-by-upstream
          (into {}
                (map (juxt :upstream-binding-id
                           (comp :binding-id :projected-binding)))
                binding-projections)
          bindings (mapv :projected-binding binding-projections)
          forms
          (mapv
           (fn [form]
             (assoc form :scope-id
                    (get @scope-by-syntax-id (:syntax-id form))))
           all-records)
          resolutions
          (mapv
           (fn [resolution]
             (let [projected-binding-id
                   (get projected-binding-id-by-upstream
                        (:binding-id resolution))
                   projected-resolution
                   (assoc resolution
                          :upstream-binding-id (:binding-id resolution)
                          :binding-id projected-binding-id)]
               (when-not
                (and
                 projected-binding-id
                 (get form-by-syntax
                      (:reference-syntax-id projected-resolution))
                 (some #(= projected-binding-id (:binding-id %))
                       bindings))
                 (throw
                  (ex-info "SH-07 projected resolution is dangling"
                           {:id "C6-VERIFY" :stage :core-lowering
                            :source-path source-path
                            :reason :sh06-projected-resolution-dangling
                            :resolution resolution})))
               projected-resolution))
           @occurrences)]
      (when-not
       (and (= (count binding-projections)
               (count projected-binding-id-by-upstream))
            (= (count bindings) (count (set (map :binding-id bindings)))))
        (throw
         (ex-info "SH-07 binding projection is not bijective"
                  {:id "C6-VERIFY" :stage :core-lowering
                   :source-path source-path
                   :reason :sh06-binding-projection-not-bijective
                   :binding-count (count bindings)
                   :upstream-count
                   (count projected-binding-id-by-upstream)})))
      {:forms forms
       :binding-table bindings
       :alias-table (vec (:alias-table resolved-analysis))
       :resolution-table resolutions})))

(defn sh07-core-lineage
  [resolution-artifact]
  (let [boundary (:gravity-resolution-boundary resolution-artifact)
        analysis (:resolved-analysis boundary)
        sh05 (:sh05-macro-artifact resolution-artifact)
        neutral sh05-path-neutral-semantic-value
        source-unit
        (get-in sh05
                [:gravity-macro-boundary
                 :authenticated-sh04-artifact
                 :c2-reader-artifact :source-unit-record])
        source-revision-id (:bytes-hash source-unit)
        expanded-forms (mapv :form (:expanded-syntax-stream sh05))
        semantic-trace
        (sh07-core-semantic-macro-trace
         (:macro-expansion-trace sh05))
        semantic-module
        (select-keys (:module-contract analysis)
                     [:namespace :profile :target :safety
                      :effects :capabilities :exports])
        binding-semantics
        (mapv #(select-keys
                %
                [:name :kind :namespace :package
                 :binding-class :visibility
                 :profile-set :target-set :type-ref :effects
                 :capabilities :safety :semantic-span])
              (:binding-table analysis))
        resolution-semantics
        (mapv #(select-keys
                %
                [:reference-syntax-id :symbol :position
                 :resolution-order :semantic-span :resolution-kind])
              (:resolution-table analysis))
        alias-semantics (vec (:alias-table analysis))]
    (let [semantic-projection-id
          (reader-canonical-hash
           {:domain :gravity/sh07-semantic-sh06-artifact-v1
            :source-revision-id source-revision-id
            :module semantic-module
            :expanded-forms (neutral expanded-forms)
            :bindings binding-semantics
            :aliases alias-semantics
            :resolutions resolution-semantics})]
      {:authenticated-sh06-artifact-id (:artifact-id resolution-artifact)
       :sh06-semantic-projection-id semantic-projection-id
       ;; Retained as a compatibility alias while consumers migrate to the
       ;; unambiguous semantic-projection name above.
       :sh06-artifact-id semantic-projection-id
     :sh06-analysis-artifact-id
     (reader-canonical-hash
      {:domain :gravity/sh07-semantic-sh06-analysis-v1
       :source-revision-id source-revision-id
       :module semantic-module
       :bindings binding-semantics
       :aliases alias-semantics
       :resolutions resolution-semantics})
     :source-revision-id
     source-revision-id
     :sh05-artifact-id
     (reader-canonical-hash
      {:domain :gravity/sh07-semantic-sh05-artifact-v1
       :source-revision-id source-revision-id
       :expanded-forms (neutral expanded-forms)
       :macro-trace semantic-trace})
     :expanded-syntax-stream-id
     (reader-canonical-hash
      {:domain :gravity/sh07-semantic-expanded-stream-v1
       :source-revision-id source-revision-id
       :expanded-forms (neutral expanded-forms)})
     :macro-expansion-trace-id
     (reader-canonical-hash
      {:domain :gravity/sh07-semantic-macro-trace-v1
       :source-revision-id source-revision-id
       :trace semantic-trace})
     :binding-table-id
     (reader-canonical-hash
      {:domain :gravity/sh07-sh06-binding-table-v1
       :bindings binding-semantics})
     :resolution-table-id
     (reader-canonical-hash
      {:domain :gravity/sh07-sh06-resolution-table-v1
       :resolutions resolution-semantics})
     :alias-table-id
     (reader-canonical-hash
      {:domain :gravity/sh07-sh06-alias-table-v1
       :aliases alias-semantics})
     :lexical-scope-graph-id
     (reader-canonical-hash
      {:domain :gravity/sh07-sh06-lexical-scope-graph-v1
       :source-revision-id source-revision-id
       :graph
       (neutral
        (select-keys (:lexical-scope-graph analysis)
                     [:scope-count :edge-count :status]))})
     :authenticated-envelope-id
     (reader-canonical-hash
      {:domain :gravity/sh07-semantic-upstream-envelope-v1
       :source-revision-id source-revision-id
       :sh05-artifact-id
       (reader-canonical-hash
        {:domain :gravity/sh07-semantic-sh05-artifact-v1
         :source-revision-id source-revision-id
         :expanded-forms (neutral expanded-forms)
         :macro-trace semantic-trace})})})))

(defn sh07-core-projection-binding-input
  [request]
  {:domain :gravity/sh07-authenticated-sh06-core-projection-v15
   :request
   (-> request
       (dissoc :projection-binding :provenance)
       sh05-path-neutral-semantic-value)})

(defn sh07-b13-alias-name
  [resolution]
  (when (= :alias-qualified-required-binding
           (:resolution-order resolution))
    (some-> (:symbol resolution)
            namespace
            symbol)))

(defn sh07-b13-fragment-record
  [lineage module ordinal tree bindings resolutions aliases]
  (let [forms (:records tree)
        form-ids (mapv :form-id forms)
        syntax-ids (set (map :syntax-id forms))
        local-bindings
        (filterv #(contains? syntax-ids (:definition-syntax-id %))
                 bindings)
        local-binding-ids (mapv :binding-id local-bindings)
        local-binding-id-set (set local-binding-ids)
        fragment-resolutions
        (filterv #(contains? syntax-ids (:reference-syntax-id %))
                 resolutions)
        external-binding-ids
        (->> fragment-resolutions
             (map :binding-id)
             (remove local-binding-id-set)
             distinct
             vec)
        alias-names
        (->> fragment-resolutions
             (keep sh07-b13-alias-name)
             distinct
             vec)
        available-aliases (set (map :alias aliases))
        root-form-id (get-in tree [:root :form-id])
        root-node-id root-form-id
        content
        {:ordinal ordinal
         :root-form-ids [root-form-id]
         :form-ids form-ids
         :local-binding-ids local-binding-ids
         :external-binding-ids external-binding-ids
         :resolution-reference-syntax-ids
         (mapv :reference-syntax-id fragment-resolutions)
         :alias-names alias-names
         :root-node-ids [root-node-id]}
        content-id root-form-id
        fragment-id root-form-id]
    (when-not (every? available-aliases alias-names)
      (throw
       (ex-info "SH-07-B13 fragment referenced an undeclared alias"
                {:id "C6-VERIFY"
                 :stage :core-lowering
                 :reason :fragment-undeclared-alias
                 :ordinal ordinal
                 :alias-names alias-names})))
    (assoc content
           :fragment-id fragment-id
           :content-id content-id)))

(defn sh07-b13-fragment-manifest
  [lineage module trees bindings resolutions aliases]
  (mapv
   #(sh07-b13-fragment-record
     lineage module %1 %2 bindings resolutions aliases)
   (range)
   trees))

(defn sh07-b13-binding-order
  [module trees bindings]
  (let [fragment-by-syntax
        (into {}
              (mapcat
               (fn [ordinal tree]
                 (map
                  (fn [form] [(:syntax-id form) ordinal])
                  (:records tree)))
               (range)
               trees))
        indexed (map-indexed vector bindings)
        local?
        #(contains? fragment-by-syntax (:definition-syntax-id %))]
    (->> indexed
         (sort-by
          (fn [[index binding]]
            [(if (local? binding)
               (get fragment-by-syntax
                    (:definition-syntax-id binding)
                    Integer/MAX_VALUE)
               Integer/MAX_VALUE)
             index]))
         (mapv second))))

(defn sh07-b13-fragment-coverage
  [module forms bindings resolutions fragment-manifest]
  (let [local-binding-ids
        (vec (mapcat :local-binding-ids fragment-manifest))]
    {:root-form-count
     (count (mapcat :root-form-ids fragment-manifest))
     :form-count (count forms)
     :local-binding-count (count local-binding-ids)
     :resolution-count (count resolutions)
     :fragment-count (count fragment-manifest)
     :covered-root-form-ids
     (vec (mapcat :root-form-ids fragment-manifest))
     :covered-form-ids
     (vec (mapcat :form-ids fragment-manifest))
     :covered-local-binding-ids
     local-binding-ids
     :covered-resolution-reference-syntax-ids
     (vec
      (mapcat
       :resolution-reference-syntax-ids fragment-manifest))}))

(defn sh07-b13-module-assembly-manifest
  [lineage fragment-manifest]
  (let [content
        {:ordered-fragment-ids (mapv :fragment-id fragment-manifest)
         :root-form-ids (vec (mapcat :root-form-ids fragment-manifest))
         :source-revision-id (:source-revision-id lineage)
         :sh06-semantic-projection-id
         (:sh06-semantic-projection-id lineage)
         :alias-table-id (:alias-table-id lineage)}
        content-id (:source-revision-id lineage)]
    (assoc content
           :content-id content-id
           :module-id
           (:sh06-semantic-projection-id lineage))))

(defn sh07-core-authenticated-request
  [resolution-artifact]
  (let [source-path
        (sh07-core-source-path-from-resolution resolution-artifact)
        upstream-verification
        (sh06-resolution-artifact-verification resolution-artifact)]
    (when-not
     (and (= :gravity/sh06-resolution-artifact
             (:kind resolution-artifact))
          (= :passed (:status upstream-verification))
          (= :complete
             (get-in resolution-artifact
                     [:capability-based-proof :status])))
      (throw
       (ex-info "SH-07 requires a fresh verified SH-06 artifact"
                {:id "C6-VERIFY" :stage :core-lowering
                 :source-path source-path
                 :missing-fields [:fresh-authenticated-sh06-resolution]})))
    (let [lineage (sh07-core-lineage resolution-artifact)
          sh05 (:sh05-macro-artifact resolution-artifact)
          module-contract
          (get-in resolution-artifact
                  [:gravity-resolution-boundary
                   :resolved-analysis :module-contract])
          module
          {:namespace (:namespace module-contract)
           :profile (:profile module-contract)
           :target (:target module-contract)
           :safety (:safety module-contract)
           :effects (vec (:effects module-contract))
           :capabilities (vec (:capabilities module-contract))
           :exports (vec (:exports module-contract))
           :source-revision-id (:source-revision-id lineage)}
          decimal-evidence (sh07-core-decimal-evidence resolution-artifact)
          executable-syntax
          (->> (:expanded-syntax-stream sh05)
               (remove #(and (seq? (:form %))
                             (= 'ns (first (:form %)))))
               (map-indexed
                (fn [ordinal syntax]
                  (assoc syntax :sh07/root-syntax-id
                         (sh07-core-root-syntax-id
                          (:source-revision-id lineage)
                          ordinal (:form syntax)))))
               vec)
          root-id-by-upstream-id
          (into {}
                (map (fn [syntax]
                       [(:syntax/id syntax)
                        (:sh07/root-syntax-id syntax)]))
                executable-syntax)
          raw-traces
          (filterv #(= 'defn (:macro %))
                   (:macro-expansion-trace sh05))
          traces
          (mapv
           (fn [ordinal step]
             (sh07-core-macro-trace
              lineage
              (assoc step
                     :input-syntax-id
                     (reader-canonical-hash
                      {:domain :gravity/sh07-macro-input-syntax-v1
                       :source-revision-id
                       (:source-revision-id lineage)
                       :ordinal ordinal
                       :macro (:macro step)})
                     :output-syntax-id
                     (get root-id-by-upstream-id
                          (:output-syntax-id step)))))
           (range)
           raw-traces)
          trace-by-output
          (into {} (map (juxt :output-def-syntax-id identity)) traces)
          trees
          (mapv
           #(sh07-core-build-form-tree
             source-path (:source-revision-id lineage) decimal-evidence %
             (get trace-by-output (:sh07/root-syntax-id %)))
           executable-syntax)
          _ (sh07-core-decimal-evidence-complete!
             source-path decimal-evidence)
          authenticated-sh06-request
          (get-in resolution-artifact
                  [:gravity-resolution-boundary
                   :authenticated-resolution-request])
          resolved-analysis
          (get-in resolution-artifact
                  [:gravity-resolution-boundary :resolved-analysis])
          projection
          (sh07-core-resolution-projection!
           source-path (:source-revision-id lineage)
           executable-syntax trees traces
           authenticated-sh06-request resolved-analysis)
          forms (:forms projection)
          roots (mapv (comp :form-id :root) trees)
          bindings
          (sh07-b13-binding-order
           module trees (:binding-table projection))
          aliases (:alias-table projection)
          resolutions (:resolution-table projection)
          fragment-manifest
          (sh07-b13-fragment-manifest
           lineage module trees bindings resolutions aliases)
          fragment-coverage
          (sh07-b13-fragment-coverage
           module forms bindings resolutions fragment-manifest)
          module-assembly-manifest
          (sh07-b13-module-assembly-manifest
           lineage fragment-manifest)
          expectation
          {:source-revision-id (:source-revision-id lineage)
           :sh05-artifact-id (:sh05-artifact-id lineage)
           :macro-expansion-trace-id (:macro-expansion-trace-id lineage)
           :expanded-defn-count (count traces)
           :expected-input-syntax-ids (mapv :input-syntax-id traces)
           :expected-output-def-syntax-ids
           (mapv :output-def-syntax-id traces)
           :expected-introduced-fn-syntax-ids
           (mapv :introduced-fn-syntax-id traces)}
          request
          {:artifact :gravity/sh07-authenticated-sh06-core-request
           :schema-version 15
           :lineage lineage
           :module module
           :forms forms
           :top-level-form-ids roots
           :binding-table bindings
           :alias-table aliases
           :resolution-table resolutions
           :fragment-manifest fragment-manifest
           :fragment-coverage fragment-coverage
           :module-assembly-manifest module-assembly-manifest
           :macro-expansion-trace
           (sh07-core-semantic-macro-trace
            (:macro-expansion-trace sh05))
           :macro-origin-traces traces
           :macro-origin-expectation expectation
           :projection-binding nil
           :provenance {:actual-source-path source-path}
           :scope :sh07-b15-keyword-map-lookup}
          binding
          (reader-canonical-hash
           (sh07-core-projection-binding-input request))]
      (assoc request :projection-binding binding))))

(defn sh07-core-digest-reference-ordinal
  [value]
  (when (and (map? value)
             (= #{:artifact :schema-version :ordinal :authority}
                (set (keys value)))
             (= :gravity/sh07-internal-digest-reference
                (:artifact value))
             (= 1 (:schema-version value))
             (= :sh07-digest-resolver (:authority value))
             (integer? (:ordinal value))
             (not (neg? (:ordinal value))))
    (:ordinal value)))

(defn sh07-core-resolve-reference!
  [source-path value resolved-digests]
  (let [ordinal (sh07-core-digest-reference-ordinal value)
        resolved (when (some? ordinal)
                   (get resolved-digests ordinal))]
    (when-not (and (some? ordinal)
                   (p15-s23-sh02-sha256-id? resolved))
      (throw
       (ex-info "SH-07 digest reference is unresolved"
                {:id "C6-VERIFY" :stage :core-lowering
                 :source-path source-path
                 :digest-reference value
                 :resolved-count (count resolved-digests)})))
    resolved))

(defn sh07-core-resolve-reference-vector!
  [source-path values resolved-digests]
  (mapv #(sh07-core-resolve-reference!
          source-path % resolved-digests)
        values))

(defn sh07-core-semantic-projection-id
  [value]
  (or (get-in value [:lineage :sh06-semantic-projection-id])
      (get value :sh06-semantic-projection-id)
      (get-in value [:attributes :sh06-semantic-projection-id])))

(defn sh07-core-semantic-binding
  [semantic-projection-id binding]
  (cond-> binding
    (:upstream-binding-id binding)
    (assoc :upstream-binding-id (:binding-id binding))

    (and semantic-projection-id
         (:definition-artifact-id binding))
    (assoc :definition-artifact-id semantic-projection-id)))

(defn sh07-core-semantic-resolution
  [resolution]
  (cond-> resolution
    (:upstream-binding-id resolution)
    (assoc :upstream-binding-id (:binding-id resolution))))

(defn sh07-core-semantic-var-reference
  [semantic-projection-id reference]
  (let [semantic-projection-id
        (or semantic-projection-id
            (sh07-core-semantic-projection-id reference))]
    (cond-> reference
      (:upstream-binding-id reference)
      (assoc :upstream-binding-id (:binding-id reference))

      (and semantic-projection-id
           (:definition-artifact-id reference))
      (assoc :definition-artifact-id semantic-projection-id)

      (and semantic-projection-id
           (:authenticated-sh06-artifact-id reference))
      (assoc :authenticated-sh06-artifact-id semantic-projection-id))))

(defn sh07-core-semantic-mutation
  [semantic-projection-id mutation]
  (let [semantic-projection-id
        (or semantic-projection-id
            (sh07-core-semantic-projection-id mutation))]
    (cond-> mutation
      (:target-upstream-binding-id mutation)
      (assoc :target-upstream-binding-id
             (:target-binding-id mutation))

      (and semantic-projection-id
           (:target-definition-artifact-id mutation))
      (assoc :target-definition-artifact-id
             semantic-projection-id)

      (and semantic-projection-id
           (:authenticated-sh06-artifact-id mutation))
      (assoc :authenticated-sh06-artifact-id
             semantic-projection-id))))

(defn sh07-core-semantic-error-transfer
  [semantic-projection-id transfer]
  (let [semantic-projection-id
        (or semantic-projection-id
            (sh07-core-semantic-projection-id transfer))]
    (cond-> transfer
      (and semantic-projection-id
           (:authenticated-sh06-artifact-id transfer))
      (assoc :authenticated-sh06-artifact-id
             semantic-projection-id))))

(defn sh07-core-semantic-error-handler
  [semantic-projection-id handler]
  (let [semantic-projection-id
        (or semantic-projection-id
            (sh07-core-semantic-projection-id handler))]
    (cond-> handler
      (and semantic-projection-id
           (:authenticated-sh06-artifact-id handler))
      (assoc :authenticated-sh06-artifact-id
             semantic-projection-id))))

(defn sh07-core-semantic-node
  [semantic-projection-id node]
  (case (:core-form node)
    :var
    (update node :attributes
            #(sh07-core-semantic-var-reference
              semantic-projection-id %))
    :set!
    (update node :attributes
            #(sh07-core-semantic-mutation
              semantic-projection-id %))
    :throw
    (update node :attributes
            #(sh07-core-semantic-error-transfer
              semantic-projection-id %))
    :try
    (update node :attributes
            #(sh07-core-semantic-error-handler
              semantic-projection-id %))
    node))

(defn sh07-core-semantic-identity-preimage
  [preimage]
  (let [semantic-projection-id
        (sh07-core-semantic-projection-id preimage)]
    (cond-> preimage
      (and semantic-projection-id
           (contains? preimage :projection-binding))
      (assoc :projection-binding semantic-projection-id)

      (and semantic-projection-id
           (contains? preimage :lineage))
      (assoc-in
       [:lineage :authenticated-sh06-artifact-id]
       semantic-projection-id)

      (:binding-table preimage)
      (update :binding-table
              #(mapv
                (partial sh07-core-semantic-binding
                         semantic-projection-id)
                %))

      (:resolution-table preimage)
      (update :resolution-table
              #(mapv sh07-core-semantic-resolution %))

      (:var-references preimage)
      (update :var-references
              #(mapv
                (partial sh07-core-semantic-var-reference
                         semantic-projection-id)
                %))

      (:mutations preimage)
      (update :mutations
              #(mapv
                (partial sh07-core-semantic-mutation
                         semantic-projection-id)
                %))

      (:error-transfers preimage)
      (update :error-transfers
              #(mapv
                (partial sh07-core-semantic-error-transfer
                         semantic-projection-id)
                %))

      (:error-handlers preimage)
      (update :error-handlers
              #(mapv
                (partial sh07-core-semantic-error-handler
                         semantic-projection-id)
                %))

      (:nodes preimage)
      (update :nodes
              #(mapv
                (partial sh07-core-semantic-node
                         semantic-projection-id)
                %))

      (= :var (:core-form preimage))
      (update :attributes
              #(sh07-core-semantic-var-reference
                semantic-projection-id %))

      (= :set! (:core-form preimage))
      (update :attributes
              #(sh07-core-semantic-mutation
                semantic-projection-id %))

      (= :throw (:core-form preimage))
      (update :attributes
              #(sh07-core-semantic-error-transfer
                semantic-projection-id %))

      (= :try (:core-form preimage))
      (update :attributes
              #(sh07-core-semantic-error-handler
                semantic-projection-id %)))))

(defn sh07-core-resolve-digest-preimage!
  [source-path purpose preimage resolved-digests]
  (case purpose
    :sh07-core-node-id
    (-> preimage
        (assoc :children
               (sh07-core-resolve-reference-vector!
                source-path (:children preimage) resolved-digests))
        (assoc :evaluated-children
               (sh07-core-resolve-reference-vector!
                source-path (:evaluated-children preimage)
                resolved-digests))
        sh07-core-semantic-identity-preimage)

    :sh07-core-artifact-id
    (let [result
          (sh07-core-execute!
           source-path 'sh07-resolve-identity-preimage
           [preimage resolved-digests])]
      (when-not (= :accepted (:status result))
        (throw
         (ex-info "SH-07 identity digest preimage did not resolve"
                  {:id "C6-VERIFY" :stage :core-lowering
                   :source-path source-path
                   :reason (:reason result)})))
      (sh07-core-semantic-identity-preimage (:value result)))

    :sh07-core-provenance-binding-id
    (let [result
          (sh07-core-execute!
           source-path 'sh07-resolve-provenance-preimage
           [preimage resolved-digests])]
      (when-not (= :accepted (:status result))
        (throw
         (ex-info "SH-07 provenance digest preimage did not resolve"
                  {:id "C6-VERIFY" :stage :core-lowering
                   :source-path source-path
                   :reason (:reason result)})))
      (:value result))

    preimage))

(defn sh07-core-digest-requests
  [source-path digest-requests]
  (loop [remaining digest-requests
         ordinal 0
         resolved []]
    (if (empty? remaining)
      resolved
      (let [request (first remaining)]
        (when-not
         (and (= ordinal (:ordinal request))
              (= #{:ordinal :purpose :preimage} (set (keys request)))
              (<= 0 ordinal 65539))
          (throw
           (ex-info "Malformed SH-07 digest request sequence"
                    {:id "C6-VERIFY" :stage :core-lowering
                     :digest-request request :ordinal ordinal})))
        (let [purpose (:purpose request)
              preimage
              (sh07-core-resolve-digest-preimage!
               source-path purpose (:preimage request) resolved)
              digest
              (reader-canonical-hash
               {:domain :gravity/sh07-declared-digest-v1
                :purpose purpose
                :preimage preimage})]
          (recur (rest remaining)
                 (inc ordinal)
                 (conj resolved digest)))))))

(defn sh07-core-resolve-result
  [source-path template digest-requests resolved-digests]
  (let [resolution
        (sh07-core-execute!
         source-path 'sh07-resolve-core-template
         [template resolved-digests])]
    (when-not (= :accepted (:status resolution))
      (throw
       (ex-info "SH-07 controlled digest-slot resolution failed"
                {:id "C6-VERIFY" :stage :core-lowering
                 :source-path source-path
                 :reason (:reason resolution)
                 :resolution resolution})))
    (:value resolution)))

(defn sh07-core-public-decimal-presentation
  [core]
  (update
   core :nodes
   (fn [nodes]
     (mapv
      (fn [node]
        (let [descriptor (get-in node [:attributes :value])]
          (if (and (= :decimal
                      (get-in node [:attributes :literal-kind]))
                   (map? descriptor)
                   (= :gravity/arbitrary-decimal-literal
                      (:kind descriptor)))
            (assoc-in
             node [:attributes :value]
             (java.math.BigDecimal.
              (java.math.BigInteger. (:unscaled-value descriptor))
              (int (:scale descriptor))))
            node)))
      nodes))))

(defn sh07-core-canonical-artifact
  [resolved-template]
  (-> resolved-template
      (assoc :artifact :gravity/sh07-canonical-core-artifact
             :artifact-id (:artifact-id-request resolved-template)
             :provenance-binding-id
             (:provenance-binding-id-request resolved-template)
             :identity-preimage
             (sh07-core-semantic-identity-preimage
              (:identity-preimage resolved-template)))
      (dissoc :artifact-id-request :provenance-binding-id-request)
      sh07-core-public-decimal-presentation))

(defn sh07-core-raise-diagnostic!
  [source-path template]
  (let [diagnostic (first (:diagnostics template))
        request (first (:digest-requests template))
        diagnostic-id
        (reader-canonical-hash
         {:domain :gravity/sh07-declared-digest-v1
          :purpose (:purpose request)
          :preimage (:preimage request)})
        resolved
        (assoc diagnostic :diagnostic-id-request diagnostic-id)]
    (throw (ex-info "Gravity checked-core lowering rejected the source"
                    resolved))))

(defn sh07-core-nested-depth
  [value]
  (loop [frontier [[value 0]]
         maximum 0
         visited 0]
    (if (empty? frontier)
      maximum
      (let [[item depth] (peek frontier)
            frontier (pop frontier)]
        (cond
          (or (> depth 256) (> visited 8388608))
          257

          (or (map? item) (vector? item) (set? item) (list? item))
          (let [next-depth (inc depth)
                children
                (if (map? item)
                  (mapcat (fn [[key value]] [key value]) item)
                  item)
                bounded-children (vec (take 65537 children))]
            (if (> (count bounded-children) 65536)
              257
              (recur
               (into frontier
                     (map #(vector % next-depth) bounded-children))
               (max maximum next-depth)
               (inc visited))))

          (coll? item)
          257

          :else
          (recur frontier maximum (inc visited)))))))

(defn sh07-core-request-diagnostic!
  [request rule-specific]
  (let [source-path (get-in request [:provenance :actual-source-path])
        lineage (:lineage request)
        module (:module request)
        reason (or (:reason rule-specific)
                   :bounded-authenticated-core-request)
        remediation
        (case reason
          :fragment-root-form-bound
          "Split the top-level definition into supported bounded helper definitions."

          "Replay the Gravity template and bind every digest ordinal exactly once.")
        diagnostic
        {:artifact :gravity/sh07-core-diagnostic
         :rule "C6-VERIFY"
         :severity :error
         :stage :core-lowering
         :syntax-id nil
         :form-id nil
         :core-node-id nil
         :source-span {:source source-path}
         :generated-origin-chain []
         :namespace (:namespace module)
         :profile (:profile module)
         :target (:target module)
         :lowering-rule :sh07-b15-keyword-map-lookup
         :facts {:reason reason
                 :rule-specific rule-specific
                 :source-revision-id (:source-revision-id lineage)
                 :sh06-artifact-id (:sh06-artifact-id lineage)
                 :authenticated-sh06-artifact-id
                 (:authenticated-sh06-artifact-id lineage)
                 :sh06-semantic-projection-id
                 (:sh06-semantic-projection-id lineage)
                 :fail-closed true}
         :remediation remediation
         :diagnostic-id-request
         (reader-canonical-hash
          {:domain :gravity/sh07-request-bound-diagnostic-v11
           :source-revision-id (:source-revision-id lineage)
           :rule-specific rule-specific})}]
    (throw (ex-info "SH-07 authenticated request exceeded a bound"
                    diagnostic))))

(defn sh07-core-request-preflight!
  [request]
  (let [forms-value (:forms request)
        bindings-value (:binding-table request)
        aliases-value (:alias-table request)
        resolutions-value (:resolution-table request)
        fragments-value (:fragment-manifest request)
        trace-value (:macro-expansion-trace request)
        origin-traces-value (:macro-origin-traces request)
        value-shape
        (fn [value]
          (cond
            (nil? value) :nil
            (map? value) :map
            (vector? value) :vector
            (set? value) :set
            (sequential? value) :sequential
            (coll? value) :collection
            :else :scalar))
        request-depth
        (when (map? request)
          (sh07-core-nested-depth request))]
    (cond
      (not (map? request))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-map-required
        :observed-shape (value-shape request)})

      (not (map? (:lineage request)))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-lineage-map-required
        :observed-shape (value-shape (:lineage request))})

      (not (map? (:module request)))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-module-map-required
        :observed-shape (value-shape (:module request))})

      (not (map? (:provenance request)))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-provenance-map-required
        :observed-shape (value-shape (:provenance request))})

      (not (vector? forms-value))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-forms-vector-required
        :observed-shape (value-shape forms-value)})

      (not (vector? bindings-value))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-binding-table-vector-required
        :observed-shape (value-shape bindings-value)})

      (not (vector? aliases-value))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-alias-table-vector-required
        :observed-shape (value-shape aliases-value)})

      (not (vector? resolutions-value))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-resolution-table-vector-required
        :observed-shape (value-shape resolutions-value)})

      (not (vector? fragments-value))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-fragment-manifest-vector-required
        :observed-shape (value-shape fragments-value)})

      (not (vector? trace-value))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-macro-trace-vector-required
        :observed-shape (value-shape trace-value)})

      (> request-depth 256)
      (sh07-core-request-diagnostic!
       request
       {:bound :maximum-carrier-depth
        :maximum 256
        :observed request-depth})

      (not=
       (:projection-binding request)
       (reader-canonical-hash
        (sh07-core-projection-binding-input request)))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-projection-binding-mismatch})

      (not=
       (get-in request [:lineage :alias-table-id])
       (reader-canonical-hash
        {:domain :gravity/sh07-sh06-alias-table-v1
         :aliases aliases-value}))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-alias-table-lineage-mismatch})

      :else
      (let [forms (count forms-value)
            bindings (count bindings-value)
            aliases (count aliases-value)
            resolutions (count resolutions-value)
            fragments (count fragments-value)
            trace-count (count trace-value)
            origin-trace-count
            (if (vector? origin-traces-value)
              (count origin-traces-value)
              0)]
        (cond
      (not= 15 (:schema-version request))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-schema-version
        :expected 15
        :observed (:schema-version request)})

      (not= :sh07-b15-keyword-map-lookup (:scope request))
      (sh07-core-request-diagnostic!
       request
       {:reason :request-scope
        :expected :sh07-b15-keyword-map-lookup
        :observed (:scope request)})

      (> forms 65536)
      (sh07-core-request-diagnostic!
       request
       {:bound :maximum-module-forms
        :maximum 65536
        :observed forms
        :projected-core-node-count forms
         :projected-digest-request-count (+ forms 2)})

      (> fragments 1024)
      (sh07-core-request-diagnostic!
       request
       {:bound :maximum-top-level-fragments
        :maximum 1024
        :observed fragments})

      (some #(> (count (:form-ids %)) 1024) fragments-value)
      (let [fragment
            (first
             (filter #(> (count (:form-ids %)) 1024)
                     fragments-value))]
        (sh07-core-request-diagnostic!
         request
         {:reason :fragment-root-form-bound
          :bound :maximum-fragment-forms
          :maximum 1024
          :ordinal (:ordinal fragment)
          :observed (count (:form-ids fragment))}))

      (> bindings 2197)
      (sh07-core-request-diagnostic!
       request
       {:bound :maximum-module-bindings
        :maximum 2197
        :observed bindings})

      (> aliases 256)
      (sh07-core-request-diagnostic!
       request
       {:bound :maximum-alias-records
        :maximum 256
        :observed aliases})

      (> resolutions 65536)
      (sh07-core-request-diagnostic!
       request
       {:bound :maximum-resolutions
        :maximum 65536
        :observed resolutions})

      (> trace-count 1024)
      (sh07-core-request-diagnostic!
       request
       {:bound :maximum-forms
        :maximum 1024
        :observed trace-count})

      (> origin-trace-count 2048)
      (sh07-core-request-diagnostic!
       request
       {:bound :maximum-carrier-origin-traces
        :maximum 2048
        :observed origin-trace-count})

          :else :passed)))))

(defn- sh07-core-template-carrier-census
  [value]
  (let [maximum-nodes (* 32 1024 1024)
        maximum-scalar-bytes (* 8 268435456)
        frontier (java.util.ArrayDeque.)]
    (.addLast frontier [value 0])
    (loop [nodes 0
           aggregate-nodes 0
           component-nodes 0
           scalar-bytes 0
           maximum-depth 0
           maximum-width 0]
      (if (.isEmpty frontier)
        {:status :complete
         :nodes nodes
         :aggregate-nodes aggregate-nodes
         :component-nodes component-nodes
         :scalar-bytes scalar-bytes
         :maximum-depth maximum-depth
         :maximum-width maximum-width}
        (let [[current depth] (.removeLast frontier)
              next-nodes (inc nodes)
              aggregate?
              (or (map? current) (vector? current)
                  (set? current) (seq? current))]
          (cond
            (> next-nodes maximum-nodes)
            {:status :truncated
             :reason :measurement-node-bound
             :observed-at-least next-nodes
             :maximum maximum-nodes}

            aggregate?
            (let [components
                  (if (map? current)
                    (mapcat (fn [[key item]] [key item]) current)
                    current)
                  width (if (map? current)
                          (* 2 (count current))
                          (count current))]
              (doseq [component components]
                (.addLast frontier [component (inc depth)]))
              (recur
               next-nodes
               (inc aggregate-nodes)
               (+ component-nodes width)
               scalar-bytes
               (max maximum-depth depth)
               (max maximum-width width)))

            :else
            (let [next-scalar-bytes
                  (+ scalar-bytes (* 4 (count (str current))))]
              (if (> next-scalar-bytes maximum-scalar-bytes)
                {:status :truncated
                 :reason :measurement-scalar-byte-bound
                 :observed-at-least next-scalar-bytes
                 :maximum maximum-scalar-bytes}
                (recur
                 next-nodes
                 aggregate-nodes
                 component-nodes
                 next-scalar-bytes
                 (max maximum-depth depth)
                 maximum-width)))))))))

(defn sh07-core-run-structural-request-for-test
  "Test-only structural runner. It does not authenticate SH-06 membership;
  callers testing the executable boundary must use
  sh07-core-run-request-for-test with the verified SH-06 artifact."
  [authenticated-request]
  (let [_ (sh07-core-request-preflight! authenticated-request)
        source-path
        (get-in authenticated-request [:provenance :actual-source-path])
        result
        (sh07-core-execute!
         source-path 'sh07-build-core-template [authenticated-request])]
    (case (:status result)
      :rejected (sh07-core-raise-diagnostic! source-path result)
      :accepted
      (let [template (:core-template result)
            digest-requests (:digest-requests result)
            template-verification
            (sh07-core-execute!
             source-path 'sh07-verify-core-template
             [authenticated-request template digest-requests])
            _ (when-not (= :passed (:status template-verification))
                (throw
                 (ex-info "Gravity SH-07 template replay failed"
                          {:id "C6-VERIFY" :stage :core-lowering
                           :source-path source-path
                           :template-verification
                           template-verification
                           :template-carrier-census
                           (sh07-core-template-carrier-census
                            template)
                           :digest-request-carrier-census
                           (sh07-core-template-carrier-census
                            digest-requests)})))
            resolved-digests
            (sh07-core-digest-requests source-path digest-requests)
            resolved-template
            (sh07-core-resolve-result
             source-path template digest-requests resolved-digests)
            resolved-verification
            (sh07-core-execute!
             source-path 'sh07-verify-core-resolved
             [authenticated-request resolved-template
              digest-requests resolved-digests])
            _ (when-not (= :passed (:status resolved-verification))
                (throw
                 (ex-info "Gravity SH-07 resolved replay failed"
                          {:id "C6-VERIFY" :stage :core-lowering
                           :source-path source-path
                           :resolved-verification
                           resolved-verification})))]
        {:raw-template-result result
         :canonical-core-artifact
         (sh07-core-canonical-artifact resolved-template)
         :digest-requests digest-requests
         :resolved-digests resolved-digests
         :template-verification template-verification
         :resolved-verification resolved-verification})
      (throw
       (ex-info "Gravity SH-07 returned an invalid result status"
                {:id "C6-VERIFY" :stage :core-lowering
                 :source-path source-path
                 :status (:status result)})))))

(defn sh07-core-run-request-for-test
  [resolution-artifact authenticated-request]
  (let [upstream-verification
        (sh06-resolution-artifact-verification resolution-artifact)
        expected-request
        (when (= :passed (:status upstream-verification))
          (sh07-core-authenticated-request resolution-artifact))]
    (when-not (= :passed (:status upstream-verification))
      (sh07-core-request-diagnostic!
       authenticated-request
       {:reason :authenticated-sh06-artifact-required
        :failed-checks (:failed-checks upstream-verification)}))
    (when-not (= expected-request authenticated-request)
      (sh07-core-request-diagnostic!
       authenticated-request
       {:reason :authenticated-sh06-request-membership-mismatch}))
    (sh07-core-run-structural-request-for-test authenticated-request)))

(defn sh07-core-projection-diagnostic!
  [resolution-artifact reason]
  (let [source-path
        (sh07-core-source-path-from-resolution resolution-artifact)
        diagnostic
        {:artifact :gravity/sh07-core-diagnostic
         :rule "C6-VERIFY"
         :severity :error
         :stage :core-lowering
         :syntax-id nil
         :form-id nil
         :core-node-id nil
         :source-span {:source source-path}
         :generated-origin-chain []
         :namespace
         (get-in resolution-artifact [:namespace-analysis :namespace])
         :profile
         (get-in resolution-artifact [:namespace-analysis :profile])
         :target
         (get-in resolution-artifact [:namespace-analysis :target])
         :lowering-rule :sh07-b15-keyword-map-lookup
         :facts {:reason reason
                 :rule-specific {:reason reason}
                 :source-revision-id
                 (get-in resolution-artifact
                         [:gravity-resolution-boundary
                          :authenticated-resolution-request
                          :module :source-revision-id])
                 :sh06-artifact-id (:artifact-id resolution-artifact)
                 :authenticated-sh06-artifact-id
                 (:artifact-id resolution-artifact)
                 :fail-closed true}
         :remediation
         "Replay the Gravity template and bind every digest ordinal exactly once."
         :diagnostic-id-request
         (reader-canonical-hash
          {:domain :gravity/sh07-projection-diagnostic-v11
           :reason reason
           :sh06-artifact-id (:artifact-id resolution-artifact)})}]
    (throw (ex-info "SH-07 projection authentication failed" diagnostic))))

(declare sh07-core-exact-comparison-value)

(defn sh07-core-error-transfers-coherent?
  [core]
  (let [nodes (:nodes core)
        transfers (:error-transfers core)
        throw-nodes
        (when (vector? nodes)
          (filterv #(and (map? %) (= :throw (:core-form %))) nodes))
        throw-node-by-id
        (when (vector? throw-nodes)
          (into {} (map (juxt :node-id identity)) throw-nodes))
        shared-attribute-keys
        [:construction-order :runtime-reachability
         :transfer-policy :result-policy :required-effect
         :authenticated-sh06-artifact-id
         :sh06-semantic-projection-id
         :type-legality :effect-registry-legality
         :effect-profile-capability-legality
         :profile-error-lowering-legality
         :ownership-legality :safety-classification]]
    (and
     (vector? nodes)
     (vector? transfers)
     (= (count throw-nodes) (count transfers))
     (= (count throw-nodes) (count throw-node-by-id))
     (every?
      true?
      (map-indexed
       (fn [ordinal transfer]
         (let [node (get throw-node-by-id (:core-node-id transfer))
               value-node-id (:value-core-node-id transfer)]
           (and
            (map? transfer)
            (map? node)
            (= ordinal (:ordinal transfer))
            (= [value-node-id] (:evaluated-children transfer))
            (= [value-node-id] (:children node))
            (= [] (:resolved-binding-ids node))
            (= :value-then-transfer
               (get-in node [:evaluation :kind]))
            (= [{:index 0 :core-node-id value-node-id}]
               (get-in node [:evaluation :order]))
            (= 0 (get-in node [:attributes :value-child-index]))
            (= :value-then-transfer
               (get-in node [:attributes :evaluation-order]))
            (= [:evaluate-value :transfer-error]
               (:ordered-steps transfer))
            (= (select-keys transfer shared-attribute-keys)
               (select-keys (:attributes node)
                            shared-attribute-keys)))))
       transfers)))))

(defn sh07-core-descendant-node-ids
  [node-by-id root-node-id]
  (loop [frontier [root-node-id]
         visited #{}]
    (if (empty? frontier)
      visited
      (let [node-id (peek frontier)
            frontier (pop frontier)
            node (get node-by-id node-id)]
        (cond
          (contains? visited node-id)
          (recur frontier visited)

          (not (map? node))
          nil

          :else
          (recur (into frontier (:children node))
                 (conj visited node-id)))))))

(def ^:private sh07-b9-handler-descriptor-keys
  [:clause-ordinal :handler-child-index
   :catch-clause-form-id :catch-clause-syntax-id
   :error-type-form-id :error-type-syntax-id
   :error-type-binding-id
   :catch-binding-form-id :catch-binding-syntax-id
   :catch-binding-id :catch-binding-scope-id])

(defn sh07-b9-handler-group-coherent?
  [node-by-id transfers references try-node handlers]
  (let [handlers (vec (sort-by :clause-ordinal handlers))
        attributes (:attributes try-node)
        protected-node-id (first (:children try-node))
        handler-node-ids (mapv :handler-core-node-id handlers)
        expected-children (into [protected-node-id] handler-node-ids)
        expected-bindings
        (vec
         (mapcat
          (juxt :error-type-binding-id :catch-binding-id)
          handlers))
        expected-indexes
        (mapv inc (range (count handlers)))
        expected-descriptors
        (mapv #(select-keys % sh07-b9-handler-descriptor-keys)
              handlers)
        protected-tree
        (sh07-core-descendant-node-ids node-by-id protected-node-id)
        owner (:evaluation-owner-function-syntax-id (first handlers))
        expected-candidates
        (when protected-tree
          (->> transfers
               (filter
                #(and (= owner
                         (:evaluation-owner-function-syntax-id %))
                      (contains? protected-tree (:core-node-id %))))
               (mapv #(select-keys % [:ordinal :core-node-id]))))
        shared-attribute-keys
        [:runtime-reachability :selection-policy :result-policy
         :authenticated-sh06-artifact-id
         :sh06-semantic-projection-id
         :type-coverage-legality :result-type-join-legality
         :effect-registry-legality
         :effect-profile-capability-legality
         :profile-error-lowering-legality
         :ownership-legality :safety-classification]]
    (and
     (seq handlers)
     (= (range (count handlers))
        (map :clause-ordinal handlers))
     (every? #(= (count handlers) (:clause-count %)) handlers)
     (= expected-indexes (mapv :handler-child-index handlers))
     (= expected-children (:children try-node))
     (= expected-bindings (:resolved-binding-ids try-node))
     (= (count handler-node-ids) (count (distinct handler-node-ids)))
     (= (count handlers)
        (count (distinct (map :catch-binding-id handlers))))
     (= (count handlers)
        (count (distinct (map :catch-binding-scope-id handlers))))
     (= :protected-then-ordered-typed-handler-candidates
        (get-in try-node [:evaluation :kind]))
     (= [{:index 0 :core-node-id protected-node-id}]
        (get-in try-node [:evaluation :order]))
     (= 0 (:protected-child-index attributes))
     (= (count handlers) (:handler-count attributes))
     (= expected-indexes (:handler-child-indexes attributes))
     (= expected-descriptors (:handler-clauses attributes))
     (= :protected-then-ordered-typed-handler-candidates
        (:evaluation-order attributes))
     (every?
      (fn [handler]
        (let [handler-tree
              (sh07-core-descendant-node-ids
               node-by-id (:handler-core-node-id handler))
              expected-use-syntax-ids
              (when handler-tree
                (->> references
                     (filter
                      #(and (= (:catch-binding-id handler)
                               (:binding-id %))
                            (contains? handler-tree
                                       (:core-node-id %))))
                     (mapv :syntax-id)))]
          (and
           (= (:node-id try-node) (:core-node-id handler))
           (= protected-node-id (:protected-core-node-id handler))
           (= expected-candidates
              (:candidate-error-transfers handler))
           (= expected-use-syntax-ids
              (:catch-binding-use-syntax-ids handler))
           (= (select-keys attributes shared-attribute-keys)
              (select-keys handler shared-attribute-keys)))))
      handlers))))

(defn sh07-core-error-handlers-coherent?
  [core]
  (let [nodes (:nodes core)
        handlers (:error-handlers core)
        transfers (:error-transfers core)
        references (:reference-uses core)
        try-nodes
        (when (vector? nodes)
          (filterv #(and (map? %) (= :try (:core-form %))) nodes))
        node-by-id
        (when (vector? nodes)
          (into {} (map (juxt :node-id identity)) nodes))
        try-by-id
        (when (vector? try-nodes)
          (into {} (map (juxt :node-id identity)) try-nodes))
        handlers-by-try
        (when (vector? handlers)
          (group-by :core-node-id handlers))]
    (and
     (vector? nodes)
     (vector? handlers)
     (vector? transfers)
     (vector? references)
     (= (count nodes) (count node-by-id))
     (= (count try-nodes) (count try-by-id))
     (= (mapv :ordinal handlers) (vec (range (count handlers))))
     (= (set (keys try-by-id)) (set (keys handlers-by-try)))
     (every?
      (fn [[try-id try-node]]
        (sh07-b9-handler-group-coherent?
         node-by-id transfers references try-node
         (get handlers-by-try try-id)))
      try-by-id))))

(def ^:private sh07-b11-match-clause-keys
  [:clause-ordinal :branch-child-index
   :pattern-kind :pattern-form-id :pattern-syntax-id :pattern-value
   :branch-form-id :branch-syntax-id
   :pattern-binding-id :pattern-binding-scope-id
   :pattern-binding-ids])

(def ^:private sh07-b11-match-pattern-record-keys
  #{:ordinal :clause-ordinal :local-ordinal
    :parent-local-ordinal :root-local-ordinal
    :parent-ordinal :root-ordinal :core-node-id
    :depth :path :pattern-kind
    :pattern-form-id :pattern-syntax-id
    :pattern-value :vector-width
    :pattern-binding-id :pattern-binding-scope-id
    :pattern-binding-use-syntax-ids
    :authenticated-sh06-artifact-id
    :sh06-semantic-projection-id})

(defn sh07-b11-match-pattern-record-coherent?
  [node-by-id references branch-by-clause record record-by-ordinal]
  (let [parent (when-some [ordinal (:parent-ordinal record)]
                 (get record-by-ordinal ordinal))
        root (get record-by-ordinal (:root-ordinal record))
        branch-record (get branch-by-clause (:clause-ordinal record))
        branch-tree
        (when branch-record
          (sh07-core-descendant-node-ids
           node-by-id (:branch-core-node-id branch-record)))
        expected-uses
        (if (:pattern-binding-id record)
          (->> references
               (filter
                #(and (= (:pattern-binding-id record) (:binding-id %))
                      (contains? branch-tree (:core-node-id %))))
               (mapv :syntax-id))
          [])]
    (and
     (= sh07-b11-match-pattern-record-keys
        (set (keys record)))
     (integer? (:ordinal record))
     (not (neg? (:ordinal record)))
     (integer? (:clause-ordinal record))
     (not (neg? (:clause-ordinal record)))
     (integer? (:local-ordinal record))
     (not (neg? (:local-ordinal record)))
     (= 0 (:root-local-ordinal record))
     (integer? (:root-ordinal record))
     (<= 0 (:root-ordinal record) (:ordinal record))
     (= (:local-ordinal record)
        (- (:ordinal record) (:root-ordinal record)))
     (integer? (:depth record))
     (<= 0 (:depth record) 64)
     (vector? (:path record))
     (= (:depth record) (count (:path record)))
     (every? #(and (integer? %) (not (neg? %))) (:path record))
     (contains? #{:literal :wildcard :binding :vector}
                (:pattern-kind record))
     (p15-s23-sh02-sha256-id? (:pattern-form-id record))
     (p15-s23-sh02-sha256-id? (:pattern-syntax-id record))
     (p15-s23-sh02-sha256-id? (:core-node-id record))
     (p15-s23-sh02-sha256-id?
      (:authenticated-sh06-artifact-id record))
     (p15-s23-sh02-sha256-id?
      (:sh06-semantic-projection-id record))
     (= expected-uses (:pattern-binding-use-syntax-ids record))
     (case (:pattern-kind record)
       :vector
       (and (nil? (:pattern-value record))
            (integer? (:vector-width record))
            (<= 0 (:vector-width record) 256)
            (nil? (:pattern-binding-id record))
            (nil? (:pattern-binding-scope-id record)))

       :binding
       (and (symbol? (:pattern-value record))
            (not= '_ (:pattern-value record))
            (p15-s23-sh02-sha256-id?
             (:pattern-binding-id record))
            (p15-s23-sh02-sha256-id?
             (:pattern-binding-scope-id record))
            (nil? (:vector-width record)))

       :wildcard
       (and (= '_ (:pattern-value record))
            (nil? (:vector-width record))
            (nil? (:pattern-binding-id record))
            (nil? (:pattern-binding-scope-id record)))

       :literal
       (and (nil? (:vector-width record))
            (nil? (:pattern-binding-id record))
            (nil? (:pattern-binding-scope-id record))))
     (if (nil? parent)
       (and (= (:ordinal record) (:root-ordinal record))
            (= 0 (:local-ordinal record))
            (nil? (:parent-local-ordinal record))
            (= 0 (:depth record))
            (empty? (:path record)))
       (and (= :vector (:pattern-kind parent))
            (= (:core-node-id record) (:core-node-id parent))
            (= (:clause-ordinal record) (:clause-ordinal parent))
            (= (:root-ordinal record) (:root-ordinal parent))
            (= (:parent-local-ordinal record)
               (:local-ordinal parent))
            (= (:depth record) (inc (:depth parent)))
            (= (:path parent) (pop (:path record)))
            (< (peek (:path record)) (:vector-width parent))))
     (= (:core-node-id record) (:core-node-id root))
     (= (:clause-ordinal record) (:clause-ordinal root)))))

(defn sh07-b11-match-pattern-graph-complete?
  [pattern-records]
  (let [roots (filterv #(nil? (:parent-ordinal %)) pattern-records)
        root-groups (group-by (juxt :core-node-id :clause-ordinal) roots)]
    (and
     (every? #(= 1 (count %)) (vals root-groups))
     (every?
      (fn [record]
        (if (= :vector (:pattern-kind record))
          (let [children
                (filterv
                 #(= (:ordinal record) (:parent-ordinal %))
                 pattern-records)
                child-indexes (mapv #(peek (:path %)) children)]
            (and
             (= (:vector-width record) (count children))
             (= (count children) (count (set child-indexes)))
             (every?
              #(and (integer? %)
                    (<= 0 %)
                    (< % (:vector-width record)))
              child-indexes)))
          true))
      pattern-records))))

(defn sh07-b11-match-group-coherent?
  [node-by-id references match-node records skeleton pattern-records]
  (let [records (vec (sort-by :clause-ordinal records))
        pattern-records (vec (sort-by :ordinal pattern-records))
        pattern-record-by-ordinal
        (into {} (map (juxt :ordinal identity)) pattern-records)
        branch-by-clause
        (into {} (map (juxt :clause-ordinal identity)) records)
        attributes (:attributes match-node)
        scrutinee-node-id (first (:children match-node))
        branch-node-ids (vec (rest (:children match-node)))
        expected-indexes (mapv inc (range (count records)))
        expected-bindings
        (vec (keep :pattern-binding-id pattern-records))
        expected-clauses
        (mapv #(select-keys % sh07-b11-match-clause-keys) records)]
    (and
     (seq records)
     (= (range (count records)) (map :clause-ordinal records))
     (every? #(= (count records) (:clause-count %)) records)
     (= expected-indexes (mapv :branch-child-index records))
     (= branch-node-ids (mapv :branch-core-node-id records))
     (= #{scrutinee-node-id}
        (set (map :scrutinee-core-node-id records)))
     (= expected-bindings (:resolved-binding-ids match-node))
     (= 0 (:scrutinee-child-index attributes))
     (= (count records) (:branch-count attributes))
     (= expected-indexes (:branch-child-indexes attributes))
     (= expected-clauses (:branch-clauses attributes))
     (= (set (range (count records)))
        (set (map :clause-ordinal pattern-records)))
     (sh07-b11-match-pattern-graph-complete? pattern-records)
     (every?
      #(sh07-b11-match-pattern-record-coherent?
        node-by-id references branch-by-clause %
        pattern-record-by-ordinal)
      pattern-records)
     (= :scrutinee-then-source-ordered-pattern-candidates
        (:evaluation-order attributes))
     (= :not-asserted-by-sh07-b11
        (:runtime-reachability attributes))
     (= :source-ordered-pattern-candidates
        (:selection-policy attributes))
     (= :pending-sh08
        (:result-type-join attributes)
        (:exhaustiveness attributes))
     (= :scrutinee-then-source-ordered-pattern-candidates
        (get-in match-node [:evaluation :kind]))
     (= [{:index 0 :core-node-id scrutinee-node-id}]
        (get-in match-node [:evaluation :order]))
     (every?
      (fn [record]
        (let [branch-tree
              (sh07-core-descendant-node-ids
               node-by-id (:branch-core-node-id record))
              expected-pattern-binding-ids
              (->> pattern-records
                   (filter
                    #(= (:clause-ordinal record)
                        (:clause-ordinal %)))
                   (keep :pattern-binding-id)
                   vec)
              expected-uses
              (if (:pattern-binding-id record)
                (->> references
                     (filter
                      #(and (= (:pattern-binding-id record)
                               (:binding-id %))
                            (contains? branch-tree
                                       (:core-node-id %))))
                     (mapv :syntax-id))
                [])]
          (and
           (= (:node-id match-node) (:core-node-id record))
           (= expected-pattern-binding-ids
              (:pattern-binding-ids record))
           (= expected-uses
              (:pattern-binding-use-syntax-ids record))
           (= :evaluate-scrutinee-once
              (:scrutinee-evaluation record))
           (= :conditionally-evaluate-selected-branch
              (:branch-evaluation record))
           (= {:kind :match-branch
               :match-syntax-id
               (get-in record
                       [:conditional-region :match-syntax-id])
               :clause-ordinal (:clause-ordinal record)}
              (:conditional-region record))
           (= (:authenticated-sh06-artifact-id attributes)
              (:authenticated-sh06-artifact-id record))
           (= (:sh06-semantic-projection-id attributes)
              (:sh06-semantic-projection-id record)))))
      records)
     (= (:node-id match-node) (:core-node-id skeleton))
     (= scrutinee-node-id (:scrutinee-core-node-id skeleton))
     (= branch-node-ids (:branch-core-node-ids skeleton))
     (= :source-ordered-pattern-candidates
        (:selection-policy skeleton))
     (= :not-asserted-by-sh07-b11
        (:runtime-reachability skeleton))
     (= :pending-sh08
        (:result-type-join skeleton)
        (:exhaustiveness skeleton))
     (= (:authenticated-sh06-artifact-id attributes)
        (:authenticated-sh06-artifact-id skeleton))
     (= (:sh06-semantic-projection-id attributes)
        (:sh06-semantic-projection-id skeleton)))))

(defn sh07-core-match-products-coherent?
  [core]
  (let [nodes (:nodes core)
        records (:match-branch-records core)
        skeletons (:match-decision-skeletons core)
        pattern-records (:match-pattern-records core)
        references (:reference-uses core)
        node-by-id
        (when (vector? nodes)
          (into {} (map (juxt :node-id identity)) nodes))
        match-nodes
        (when (vector? nodes)
          (filterv #(and (map? %) (= :match (:core-form %))) nodes))
        match-by-id
        (when (vector? match-nodes)
          (into {} (map (juxt :node-id identity)) match-nodes))
        records-by-match
        (when (vector? records) (group-by :core-node-id records))
        patterns-by-match
        (when (vector? pattern-records)
          (group-by :core-node-id pattern-records))
        skeleton-by-match
        (when (vector? skeletons)
          (into {} (map (juxt :core-node-id identity)) skeletons))]
    (and
     (vector? nodes)
     (vector? records)
     (vector? skeletons)
     (vector? pattern-records)
     (vector? references)
     (= (count nodes) (count node-by-id))
     (= (mapv :ordinal records) (vec (range (count records))))
     (= (mapv :ordinal pattern-records)
        (vec (range (count pattern-records))))
     (= (count match-nodes) (count match-by-id))
     (= (count skeletons) (count skeleton-by-match))
     (= (set (keys match-by-id)) (set (keys records-by-match)))
     (= (set (keys match-by-id)) (set (keys skeleton-by-match)))
     (= (set (keys match-by-id)) (set (keys patterns-by-match)))
     (every?
      (fn [[match-id match-node]]
        (sh07-b11-match-group-coherent?
         node-by-id references match-node
         (get records-by-match match-id)
         (get skeleton-by-match match-id)
         (get patterns-by-match match-id)))
      match-by-id))))

(defn sh07-core-verification-checks
  [artifact expected upstream-verification]
  (let [core
        (get-in artifact
                [:gravity-core-boundary :canonical-core-artifact])
        expected-core
        (get-in expected
                [:gravity-core-boundary :canonical-core-artifact])
        source-path (get-in artifact [:provenance :source-path])]
    {:wrapper-schema-current?
     (= (set (keys expected)) (set (keys artifact)))
     :wrapper-kind-current?
     (= :gravity/sh07-core-artifact (:kind artifact))
     :upstream-verification-passed?
     (= :passed (:status upstream-verification))
     :semantic-artifact-id-current?
     (= (:artifact-id artifact)
        (:artifact-id core)
        (reader-canonical-hash
         {:domain :gravity/sh07-declared-digest-v1
          :purpose :sh07-core-artifact-id
          :preimage (:identity-preimage core)}))
     :authenticated-request-replays?
     (= (get-in expected
                [:gravity-core-boundary :authenticated-core-request])
        (get-in artifact
                [:gravity-core-boundary :authenticated-core-request]))
     :gravity-template-replays?
     (= (get-in expected
                [:gravity-core-boundary :raw-template-result])
        (get-in artifact
                [:gravity-core-boundary :raw-template-result]))
     :digest-sequence-replays?
     (= (get-in expected
                [:gravity-core-boundary :digest-requests])
        (get-in artifact
                [:gravity-core-boundary :digest-requests]))
     :resolved-digests-replay?
     (= (get-in expected
                [:gravity-core-boundary :resolved-digests])
        (get-in artifact
                [:gravity-core-boundary :resolved-digests]))
     :canonical-core-replays?
     (= (sh07-core-exact-comparison-value expected-core)
        (sh07-core-exact-comparison-value core))
     :fragment-manifest-replay?
     (= (sh07-core-exact-comparison-value
         (:fragment-manifest expected-core))
        (sh07-core-exact-comparison-value
         (:fragment-manifest core)))
     :fragment-coverage-replay?
     (= (sh07-core-exact-comparison-value
         (:fragment-coverage expected-core))
        (sh07-core-exact-comparison-value
         (:fragment-coverage core)))
     :module-assembly-manifest-replay?
     (= (sh07-core-exact-comparison-value
         (:module-assembly-manifest expected-core))
        (sh07-core-exact-comparison-value
         (:module-assembly-manifest core)))
     :module-replay?
     (and
      (= (sh07-core-exact-comparison-value
          (:identity-preimage expected-core))
         (sh07-core-exact-comparison-value
          (:identity-preimage core)))
      (= (sh07-core-exact-comparison-value
          (:module-assembly-manifest expected-core))
         (sh07-core-exact-comparison-value
          (:module-assembly-manifest core)))
      (= (sh07-core-exact-comparison-value
          (get-in core
                  [:identity-preimage
                   :module-assembly-manifest]))
         (sh07-core-exact-comparison-value
          (:module-assembly-manifest core))))
     :declared-alias-table-replay?
     (= (sh07-core-exact-comparison-value
         (:declared-alias-table expected-core))
        (sh07-core-exact-comparison-value
         (:declared-alias-table core)))
     :control-flow-replays?
     (= (sh07-core-exact-comparison-value
         (:control-flow expected-core))
        (sh07-core-exact-comparison-value
         (:control-flow core)))
     :reference-uses-replay?
     (= (sh07-core-exact-comparison-value
         (:reference-uses expected-core))
        (sh07-core-exact-comparison-value
         (:reference-uses core)))
     :var-references-replay?
     (= (sh07-core-exact-comparison-value
         (:var-references expected-core))
        (sh07-core-exact-comparison-value
         (:var-references core)))
     :calls-replay?
     (= (sh07-core-exact-comparison-value
         (:calls expected-core))
        (sh07-core-exact-comparison-value
         (:calls core)))
     :keyword-lookups-replay?
     (= (sh07-core-exact-comparison-value
         (:keyword-lookups expected-core))
        (sh07-core-exact-comparison-value
         (:keyword-lookups core)))
     :lexical-bindings-replay?
     (= (sh07-core-exact-comparison-value
         (:lexical-bindings expected-core))
        (sh07-core-exact-comparison-value
         (:lexical-bindings core)))
     :loop-bindings-replay?
     (= (sh07-core-exact-comparison-value
         (:loop-bindings expected-core))
        (sh07-core-exact-comparison-value
         (:loop-bindings core)))
     :recur-targets-replay?
     (= (sh07-core-exact-comparison-value
         (:recur-targets expected-core))
        (sh07-core-exact-comparison-value
         (:recur-targets core)))
     :recur-transfers-replay?
     (= (sh07-core-exact-comparison-value
         (:recur-transfers expected-core))
        (sh07-core-exact-comparison-value
         (:recur-transfers core)))
     :mutations-replay?
     (= (sh07-core-exact-comparison-value
         (:mutations expected-core))
        (sh07-core-exact-comparison-value
         (:mutations core)))
     :error-transfers-replay?
     (and
      (= (sh07-core-exact-comparison-value
          (:error-transfers expected-core))
         (sh07-core-exact-comparison-value
          (:error-transfers core)))
      (sh07-core-error-transfers-coherent? core))
     :error-handlers-replay?
     (and
      (= (sh07-core-exact-comparison-value
          (:error-handlers expected-core))
         (sh07-core-exact-comparison-value
          (:error-handlers core)))
      (sh07-core-error-handlers-coherent? core))
     :match-branch-records-replay?
     (and
      (= (sh07-core-exact-comparison-value
          (:match-branch-records expected-core))
         (sh07-core-exact-comparison-value
          (:match-branch-records core)))
      (sh07-core-match-products-coherent? core))
     :match-decision-skeletons-replay?
     (and
      (= (sh07-core-exact-comparison-value
          (:match-decision-skeletons expected-core))
         (sh07-core-exact-comparison-value
          (:match-decision-skeletons core)))
      (sh07-core-match-products-coherent? core))
     :match-pattern-records-replay?
     (and
      (= (sh07-core-exact-comparison-value
          (:match-pattern-records expected-core))
         (sh07-core-exact-comparison-value
          (:match-pattern-records core)))
      (sh07-core-match-products-coherent? core))
     :template-verification-passed?
     (= :passed
        (get-in artifact
                [:gravity-core-boundary
                 :template-verification :status]))
     :resolved-verification-passed?
     (= :passed
        (get-in artifact
                [:gravity-core-boundary
                 :resolved-verification :status]))
     :authoritative-products-replay?
     (= (sh07-core-exact-comparison-value
         (dissoc expected :capability-based-proof))
        (sh07-core-exact-comparison-value
         (dissoc artifact :capability-based-proof)))
     :stored-capability-proof-current?
     (= (:capability-based-proof expected)
        (:capability-based-proof artifact))
     :provenance-retained?
     (= source-path
        (get-in core [:provenance :actual-source-path]))}))

(defn sh07-core-proof-from-checks
  [checks]
  (let [failed
        (vec (for [[check passed?] checks
                   :when (not (true? passed?))]
               check))]
    (assoc checks
           :artifact :gravity/sh07-core-capability-proof
           :status (if (empty? failed) :complete :failed)
           :failed-checks failed)))

(defn sh07-core-exact-comparison-value
  [value]
  (cond
    (instance? java.math.BigDecimal value)
    [:gravity/exact-big-decimal
     (.toString (.unscaledValue ^java.math.BigDecimal value))
     (.scale ^java.math.BigDecimal value)]
    (map? value)
    (into {}
          (map (fn [[key child]]
                 [(sh07-core-exact-comparison-value key)
                  (sh07-core-exact-comparison-value child)]))
          value)
    (vector? value)
    (mapv sh07-core-exact-comparison-value value)
    (set? value)
    (into #{} (map sh07-core-exact-comparison-value) value)
    (list? value)
    (apply list (map sh07-core-exact-comparison-value value))
    :else value))

(defn sh07-core-from-authenticated-request
  [resolution-artifact authenticated-request]
  (let [run (sh07-core-run-request-for-test
             resolution-artifact authenticated-request)
          core (:canonical-core-artifact run)
          source-path
          (sh07-core-source-path-from-resolution resolution-artifact)
          boundary
          {:slice :SH-07
           :owner :gravity-source
           :adapter-contract sh07-core-adapter-contract
           :plan-binding
           (dissoc @sh07-core-cached-binding :plan :source-path)
           :authenticated-sh06-resolution-artifact resolution-artifact
           :authenticated-core-request authenticated-request
           :raw-template-result (:raw-template-result run)
           :canonical-core-artifact core
           :digest-requests (:digest-requests run)
           :resolved-digests (:resolved-digests run)
           :template-verification (:template-verification run)
           :resolved-verification (:resolved-verification run)
           :authenticated-envelope-descriptor
           {:artifact :gravity/sh07-authenticated-envelope-descriptor
            :semantic-artifact-id (:artifact-id core)
            :source-revision-id
            (get-in authenticated-request
                    [:lineage :source-revision-id])
            :authenticated-sh06-artifact-id
            (get-in authenticated-request
                    [:lineage :authenticated-sh06-artifact-id])
            :sh06-semantic-projection-id
            (get-in authenticated-request
                    [:lineage :sh06-semantic-projection-id])}
           :authenticated-envelope
           {:artifact :gravity/sh07-authenticated-envelope
            :semantic-artifact-id (:artifact-id core)
            :authenticated-sh06-artifact-id
            (get-in authenticated-request
                    [:lineage :authenticated-sh06-artifact-id])
            :actual-source-path source-path}
           :target-source-reread? false
           :clojure-adapter-residual? true
           :self-hosted? false}
          artifact-base
          {:kind :gravity/sh07-core-artifact
           :status :accepted
           :slice :SH-07
           :task "SH-07-B15"
           :document-set ["L2" "L3" "L6" "L7" "L9" "C5" "C6"]
           :governing-document sh07-core-governing-document
           :artifact-id (:artifact-id core)
           :sh06-resolution-artifact resolution-artifact
           :gravity-core-boundary boundary
           :provenance {:source-path source-path}
           :pass
           {:name :c6-gravity-core-lowering-b15
            :input :authenticated-sh06-resolution
            :output :canonical-core
            :owner :gravity.checked-core}
           :execution-boundary
           {:gravity-owned
            [:core-template-construction :template-verification
             :control-flow-construction :control-flow-verification
             :reference-construction :reference-verification
             :var-reference-construction
             :var-reference-verification
             :call-construction :call-verification
             :keyword-map-lookup-construction
             :keyword-map-lookup-verification
             :lexical-binding-construction
             :lexical-binding-verification
             :loop-binding-construction
             :loop-binding-verification
             :recur-target-construction
             :recur-target-verification
             :recur-transfer-construction
             :recur-transfer-verification
             :mutation-construction
             :mutation-verification
             :error-transfer-construction
             :error-transfer-verification
             :error-handler-construction
             :error-handler-verification
             :match-branch-construction
             :match-branch-verification
             :match-decision-skeleton-construction
             :match-decision-skeleton-verification
             :match-pattern-record-construction
             :match-pattern-record-verification
             :fragment-partition-validation
             :fragment-ordered-lowering
             :module-assembly-validation
             :resolved-verification]
            :clojure-seed-owned
            [:plan-execution :sh06-projection-authentication
             :digest-resolution :envelope-binding
             :compatibility-routing
             :fragment-envelope-construction
             :final-artifact-binding]
            :downstream-fact-statuses
            {:C7 :pending :C8 :pending :C9 :pending :C10 :pending}
            :pending-lowering-families
            [:cross-file-module-linking
             :incremental-fragment-cache
             :parallel-fragment-lowering
             :whole-program-execution
             :alias-qualified-type-references
             :alias-qualified-var-references
             :alias-qualified-set-mutations
             :qualified-var-references
             :var-profile-legality-sh09
             :keyword-default-value-lookup
             :general-callable-keywords
             :destructuring-bindings
             :variadic-function-recur
             :recur-type-compatibility
             :general-recursion
             :try-finally
             :try-protected-sequencing
             :try-handler-sequencing
             :map-list-set-record-constructor-patterns
             :variable-width-vector-patterns
             :duplicate-pattern-binding-policy
             :guard-patterns
             :match-exhaustiveness
             :match-result-type-join]
            :sh07-complete? false
            :self-hosted? false}
           :capability-based-proof nil
           :diagnostics []}
          upstream-verification
          (sh06-resolution-artifact-verification resolution-artifact)
          proof
          (sh07-core-proof-from-checks
           (sh07-core-verification-checks
            artifact-base artifact-base upstream-verification))]
    (assoc artifact-base :capability-based-proof proof)))

(defn sh07-core-from-resolution-artifact
  [resolution-artifact]
  (sh07-core-from-authenticated-request
   resolution-artifact
   (sh07-core-authenticated-request resolution-artifact)))

(defn sh07-core-source-artifact
  [source-path source-text]
  (sh07-core-from-resolution-artifact
   (sh06-resolution-source-artifact source-path source-text)))

(defn sh07-core-file-artifact
  [source-path]
  (let [source-text
        (try
          (slurp source-path)
          (catch Exception _
            (throw
             (ex-info
              "SH-07 could not read the requested source"
              {:artifact :gravity/sh07-core-diagnostic
               :rule "C6-VERIFY"
               :severity :error
               :stage :core-lowering
               :syntax-id nil
               :form-id nil
               :core-node-id nil
               :source-span {:source source-path}
               :generated-origin-chain []
               :lowering-rule :sh07-b15-keyword-map-lookup
               :facts {:reason :source-read-failed
                       :fail-closed true}
               :remediation
               "Provide a readable source file through the declared artifact source boundary."
               :diagnostic-id-request
               (reader-canonical-hash
                {:domain :gravity/sh07-source-read-diagnostic-v1
                 :source-path source-path
                 :reason :source-read-failed})}))))]
    (sh07-core-source-artifact source-path source-text)))

(defn sh07-public-core-file-artifact
  "Builds the authenticated SH-07 core artifact through the strict public
  source boundary. The Clojure bootstrap still owns byte loading, UTF-8
  decoding, plan execution, digest resolution, and final artifact assembly."
  [source-path]
  (sh07-core-source-artifact
   source-path
   (try
     (read-gravity-source-text source-path)
     (catch clojure.lang.ExceptionInfo ex
       (throw ex))
     (catch Exception _
       (throw
        (ex-info
         "SH-07 could not read the requested public source"
         {:artifact :gravity/sh07-core-diagnostic
          :rule "C6-VERIFY"
          :severity :error
          :stage :core-lowering
          :syntax-id nil
          :form-id nil
          :core-node-id nil
          :source-span {:source source-path}
          :generated-origin-chain []
          :lowering-rule :sh07-b46-public-routing
          :facts {:reason :source-read-failed
                  :fail-closed true}
          :remediation
          "Provide a readable .gravity or .qst source file through the declared public source boundary."}))))))

(defn sh07-core-artifact-identity-input
  [artifact]
  (get-in artifact
          [:gravity-core-boundary :canonical-core-artifact
           :identity-preimage]))

(defn- sh07-core-artifact-verification*
  [artifact]
  (let [source-path (or (get-in artifact [:provenance :source-path])
                        "<sh07-core-verification>")
        upstream (:sh06-resolution-artifact artifact)
        upstream-verification
        (try
          (sh06-resolution-artifact-verification upstream)
          (catch InterruptedException interrupted
            (.interrupt (Thread/currentThread))
            (throw interrupted))
          (catch Throwable _
            {:artifact :gravity/sh06-resolution-artifact-verification
             :status :failed :failed-checks [:contained-failure]}))
        checks
        (try
          (let [expected
                (sh07-core-from-resolution-artifact upstream)]
            (sh07-core-verification-checks
             artifact expected upstream-verification))
          (catch InterruptedException interrupted
            (.interrupt (Thread/currentThread))
            (throw interrupted))
          (catch Throwable _
            {:contained-verification? false}))
        failed (vec (for [[check passed?] checks
                          :when (not (true? passed?))]
                      check))
        boundary (:gravity-core-boundary artifact)]
    {:artifact :gravity/sh07-core-artifact-verification
     :status (if (empty? failed) :passed :failed)
     :checks checks
     :failed-checks failed
     :source-path source-path
     :template-verification (:template-verification boundary)
     :resolved-verification (:resolved-verification boundary)
     :upstream-verification upstream-verification}))

(defn sh07-core-artifact-verification
  [artifact]
  (sh07-proof-transaction-report
   :sh07 :final
   {:verifier-root
    (var-get #'sh07-core-artifact-verification*)
    :report-schema-version 1
    :check-catalog-domain :gravity/sh07-final-verification-checks
    :source-content-hash sh07-core-expected-source-content-hash
    :plan-semantic-hash sh07-core-expected-plan-semantic-hash
    :functions-semantic-hash
    sh07-core-expected-functions-semantic-hash}
   artifact
   #(sh07-core-artifact-verification* artifact)))

(defn sh07-core-capability-based-proof
  [artifact]
  (let [report (sh07-core-artifact-verification artifact)]
    (assoc (:checks report)
           :artifact :gravity/sh07-core-capability-proof
           :status (if (= :passed (:status report))
                     :complete :failed)
           :failed-checks (:failed-checks report))))

(defn- sh07-core-proof-from-verification-report
  [report]
  (assoc (:checks report)
         :artifact :gravity/sh07-core-capability-proof
         :status (if (= :passed (:status report)) :complete :failed)
         :failed-checks (:failed-checks report)))

(defn- sh07-proof-transaction-source-snapshot
  [source-path]
  (let [bytes (java.nio.file.Files/readAllBytes
               (.toPath (java.io.File. source-path)))]
    {:source-path source-path
     :source-byte-count (alength bytes)
     :source-content-hash
     (str "sha256:" (sha256-bytes-hex bytes))}))

(defn- sh07-proof-transaction-core-snapshot
  []
  (let [sh05-binding @sh05-macro-cached-binding
        sh05-source
        (sh05-macro-read-pinned-source! "<sh07-proof-transaction>")
        sh06-binding @sh06-resolution-cached-binding
        sh06-source
        (sh06-resolution-read-pinned-source! "<sh07-proof-transaction>")
        binding
        (select-keys
         @sh07-core-cached-binding
         [:source-byte-count :source-content-hash :plan-semantic-hash
          :functions-semantic-hash :function-count :function-names-hash
          :function-shapes-hash :public-function-hashes
          :public-function-shapes])
        source-path (sh07-core-source-path)
        bytes (java.nio.file.Files/readAllBytes
               (.toPath (java.io.File. source-path)))
        observed
        {:source-byte-count (alength bytes)
         :source-content-hash
         (str "sha256:" (sha256-bytes-hex bytes))}]
    (when-not (= observed
                 (select-keys binding
                              [:source-byte-count :source-content-hash]))
      (throw
       (ex-info "SH-07 checked-core source differs from the active binding"
                {:id "C6-VERIFY"
                 :stage :sh07-proof-transaction
                 :reason :checked-core-source-binding-changed})))
    (when-not (= (select-keys sh05-binding
                             [:source-byte-count :source-content-hash])
                 (select-keys sh05-source
                              [:source-byte-count :source-content-hash]))
      (throw
       (ex-info "SH-05 macro source differs from the active binding"
                {:id "C6-VERIFY"
                 :stage :sh07-proof-transaction
                 :reason :sh05-source-binding-changed})))
    (when-not (= (select-keys sh06-binding
                             [:source-byte-count :source-content-hash])
                 (select-keys sh06-source
                              [:source-byte-count :source-content-hash]))
      (throw
       (ex-info "SH-06 resolution source differs from the active binding"
                {:id "C6-VERIFY"
                 :stage :sh07-proof-transaction
                 :reason :sh06-source-binding-changed})))
    (assoc binding
           :observed-source-path source-path
           :sh05-macro-revision
           (assoc
            (select-keys
             sh05-binding
             [:source-byte-count :source-content-hash :plan-semantic-hash
              :functions-semantic-hash :function-count
              :function-names-hash :function-shapes-hash
              :public-function-hashes :public-function-shapes])
            :observed-source-path (:source-path sh05-source))
           :sh06-resolution-revision
           (assoc
            (select-keys
             sh06-binding
             [:source-byte-count :source-content-hash :plan-semantic-hash
              :functions-semantic-hash :function-count
              :function-names-hash :function-shapes-hash
              :public-function-hashes :public-function-shapes])
            :observed-source-path (:source-path sh06-source)))))

(defn- sh07-proof-transaction-phase-summary
  [state]
  {:phase (:phase state)
   :epoch (:epoch state)
   :verification-executions (:executions state)
   :verification-reuses (:reuses state)
   :receipt-count (count (:receipts state))})

(defn- sh07-proof-transaction-transition!
  [context expected-source expected-core]
  (let [source-after
        (sh07-proof-transaction-source-snapshot
         (:source-path expected-source))
        core-after (sh07-proof-transaction-core-snapshot)]
    (when-not (= expected-source source-after)
      (throw
       (ex-info "SH-07 source changed between proof phases"
                {:id "C6-VERIFY"
                 :stage :sh07-proof-transaction
                 :reason :source-snapshot-changed})))
    (when-not (= expected-core core-after)
      (throw
       (ex-info "SH-07 checked-core revision changed between proof phases"
                {:id "C6-VERIFY"
                 :stage :sh07-proof-transaction
                 :reason :checked-core-revision-changed})))
    (swap!
     context
     (fn [state]
       (-> state
           (update :completed-phases conj
                   (sh07-proof-transaction-phase-summary state))
           (assoc :phase :independent-audit
                  :epoch (inc (:epoch state))
                  :receipts []
                  :executions {}
                  :reuses {}
                  :construction-receipts-cleared? true))))))

(defn- sh07-proof-transaction-final-snapshot-check!
  [context expected-source expected-core]
  (let [source-after
        (sh07-proof-transaction-source-snapshot
         (:source-path expected-source))
        core-after (sh07-proof-transaction-core-snapshot)]
    (when-not (= expected-source source-after)
      (throw
       (ex-info "SH-07 source changed during independent audit"
                {:id "C6-VERIFY"
                 :stage :sh07-proof-transaction
                 :reason :source-snapshot-changed-during-audit})))
    (when-not (= expected-core core-after)
      (throw
       (ex-info "SH-07 checked-core revision changed during independent audit"
                {:id "C6-VERIFY"
                 :stage :sh07-proof-transaction
                 :reason :checked-core-revision-changed-during-audit})))
    (swap! context assoc :final-snapshot-rechecked? true)))

(defn- sh07-proof-transaction-close!
  [context status]
  (let [closed
        (swap!
         context
         (fn [state]
           (-> state
               (update :completed-phases conj
                       (sh07-proof-transaction-phase-summary state))
               (assoc :open? false
                      :receipts []
                      :cleanup-complete? true))))]
    {:artifact :gravity/sh07-proof-transaction-receipt
     :schema-version 1
     :status status
     :thread-confined? true
     :owner-thread-id (:owner-thread-id closed)
     :phase-order (mapv :phase (:completed-phases closed))
     :phases (:completed-phases closed)
     :source-snapshot (:source-snapshot closed)
     :checked-core-revision (:checked-core-revision closed)
     :check-catalog-bindings
     (into (sorted-map)
           (map (fn [[key catalog]]
                  [key (:check-catalog-hash catalog)]))
           (:check-catalogs closed))
     :maximum-receipts (:maximum-receipts closed)
     :artifact-id (:audited-artifact-id closed)
     :verification-report-id (:verification-report-id closed)
     :construction-receipts-cleared?
     (:construction-receipts-cleared? closed)
     :final-snapshot-rechecked? (:final-snapshot-rechecked? closed)
     :cross-epoch-reuse-count (:cross-epoch-reuse-count closed)
     :cross-epoch-reuse? (pos? (:cross-epoch-reuse-count closed))
     :failed-report-executions (:failed-report-executions closed)
     :failed-report-reuse-count (:failed-report-reuse-count closed)
     :failed-report-reuse? (pos? (:failed-report-reuse-count closed))
     :cleanup-complete? (:cleanup-complete? closed)
     :retained-receipt-count (count (:receipts closed))}))

(defn sh07-core-file-proof-transaction
  "Build and independently audit one SH-07 module in a private proof epoch.

  The returned receipt contains counters and identity snapshots only.  Cached
  artifacts and reports are cleared before the function returns."
  [source-path]
  (when *sh07-proof-transaction-context*
    (throw
     (ex-info "Nested SH-07 proof transactions are not allowed"
              {:id "C6-VERIFY"
               :stage :sh07-proof-transaction
               :reason :nested-transaction})))
  (let [source-snapshot
        (sh07-proof-transaction-source-snapshot source-path)
        core-snapshot (sh07-proof-transaction-core-snapshot)
        context
        (atom
         {:open? true
          :owner-thread-id (sh07-proof-transaction-thread-id)
          :phase :construction
          :epoch 0
          :maximum-receipts 64
          :source-snapshot source-snapshot
          :checked-core-revision core-snapshot
          :receipts []
          :check-catalogs {}
          :executions {}
          :reuses {}
          :completed-phases []
          :cross-epoch-reuse-count 0
          :failed-report-executions 0
          :failed-report-reuse-count 0
          :construction-receipts-cleared? false
          :final-snapshot-rechecked? false
          :cleanup-complete? false})]
    (try
      (binding [*sh07-proof-transaction-context* context]
        (try
          (let [artifact (sh07-core-file-artifact source-path)
                _ (sh07-proof-transaction-transition!
                   context source-snapshot core-snapshot)
                verification (sh07-core-artifact-verification artifact)
                capability-proof
                (sh07-core-proof-from-verification-report verification)
                _
                (sh07-proof-transaction-final-snapshot-check!
                 context source-snapshot core-snapshot)
                _
                (swap! context assoc
                       :audited-artifact-id (:artifact-id artifact)
                       :verification-report-id
                       (reader-canonical-hash verification))
                transaction-status
                (if (and (= :passed (:status verification))
                         (= :complete (:status capability-proof)))
                  :passed :failed)
                receipt
                (sh07-proof-transaction-close!
                 context transaction-status)]
            {:artifact artifact
             :verification verification
             :capability-proof capability-proof
             :proof-transaction receipt})
          (finally
            (when (:open? @context)
              (let [receipt-count-before-cleanup (count (:receipts @context))
                    closed
                    (swap! context assoc
                           :open? false
                           :receipts []
                           :cleanup-complete? true)
                    cleanup
                    {:open? (:open? closed)
                     :cleanup-complete? (:cleanup-complete? closed)
                     :receipt-count-before-cleanup
                     receipt-count-before-cleanup
                     :retained-receipt-count (count (:receipts closed))
                     :owner-thread-id (:owner-thread-id closed)}]
                (when *sh07-proof-transaction-cleanup-observer*
                  (try
                    (*sh07-proof-transaction-cleanup-observer* cleanup)
                    (catch Throwable _ nil))))))))
      (catch InterruptedException interrupted
        (.interrupt (Thread/currentThread))
        (throw interrupted)))))

(defn macro-file-artifact
  [path]
  (macro-source-artifact path (slurp path)))

(defn run-file
  [path]
  (let [source (slurp path)
        macro-artifact (macro-source-artifact path source)
        module (assoc (:module macro-artifact) :forms (:expanded-forms macro-artifact))
        _ (executable-profile! path module (:forms module))]
    (run-main module)))

(defn p18-diagnostic-id
  [f]
  (try
    (f)
    nil
    (catch clojure.lang.ExceptionInfo ex
      (:id (ex-data ex)))))

(defn p18-executable?
  [path]
  (let [file (java.io.File. path)]
    (and (.isFile file) (.canExecute file))))

(defn p18-t01-thin-cli-wrapper-artifact
  []
  (let [hello "examples/hello.gravity"
        rejected "bootstrap/clojure/fixtures/rejected/core-app-builtin-arity.gravity"
        hello-artifact (compile-file hello)
        hello-output (run-file hello)
        rejected-diagnostic (p18-diagnostic-id #(run-compiled-file rejected))
        artifact-base
        {:kind :gravity/p18-t01-thin-cli-wrapper-proof
         :task "P18-T01"
         :status :complete
         :phase :binary-distribution-and-seedless-release
         :command-boundary
         {:public-command "bin/gravity"
          :bootstrap-command "bin/gravity-bootstrap"
          :delegates-to ["clojure" "-M:gravity"]
          :bootstrap-hosted? true
          :seedless-release? false
          :public-release-boundary? false
          :replacement-objective
          :replace-with-self-hosted-release-artifact}
         :command-metadata
         {:version-reports {:bootstrap-hosted? true
                            :seedless-release? false
                            :delegates-to "clojure -M:gravity"}
          :help-lists ["check" "run" "compile" "test" "artifact-command"]
          :delegated-commands-report-bootstrap-hosted? true}
         :accepted-command-proofs
         [{:command ["bin/gravity" "check" hello]
           :delegated-command ["clojure" "-M:gravity" "check" hello]
           :module (get-in hello-artifact [:module :module])
           :bootstrap-hosted? true
           :expected-stdout-prefix "gravity stage0 check passed:"}
          {:command ["bin/gravity" "run" hello]
           :delegated-command ["clojure" "-M:gravity" "run" hello]
           :stdout hello-output
           :bootstrap-hosted? true}
          {:command ["bin/gravity" "compile" hello]
           :delegated-command ["clojure" "-M:gravity" "compile" hello]
           :artifact-kind (:kind hello-artifact)
           :bootstrap-hosted? true}]
         :rejected-command-proofs
         [{:command ["bin/gravity" "run-compiled" rejected]
           :delegated-command ["clojure" "-M:gravity" "run-compiled" rejected]
           :diagnostic rejected-diagnostic
           :stable-diagnostic-preserved? (= "L2-BUILTIN-ARITY"
                                            rejected-diagnostic)
           :bootstrap-hosted? true}]
         :unsupported-release-claim
         {:command ["bin/gravity" "--assert-seedless-release"]
          :diagnostic "P18T01001"
          :bootstrap-hosted? true
          :seedless-release? false}
         :capability-based-proof
         {:thin-wrapper-present? (p18-executable? "bin/gravity")
          :bootstrap-command-present? (p18-executable? "bin/gravity-bootstrap")
          :check-delegates-to-stage0? (= 'hello.main
                                         (get-in hello-artifact
                                                 [:module :module]))
          :run-delegates-to-stage0? (= "Hello Gravity\n" hello-output)
          :compile-delegates-to-stage0? (= :gravity/stage0-hosted-artifact
                                           (:kind hello-artifact))
          :diagnostic-preserved? (= "L2-BUILTIN-ARITY" rejected-diagnostic)
          :seedless-overclaim-rejected? true
          :final-seedless-release? false}}]
    (assoc artifact-base :artifact-id (c4-artifact-id artifact-base))))

