(defn p18-cli-help-text
  []
  (cli/p18-cli-help-text (p18-packaged-jvm-cli?)))

(defn p18-seedless-overclaim!
  []
  (if (p18-packaged-jvm-cli?)
    (fail! "P18T02001"
           "packaged JVM CLI is bootstrap-hosted and cannot be claimed as the seedless release artifact"
           {:source-span {:source "bin/gravity"}
            :phase "P18-T02"
            :bootstrap-hosted? true
            :packaged-jvm-cli? true
            :seedless-release? false
            :remediation "Complete P18-T03 through P18-T05 before claiming the public gravity command is seedless."})
    (fail! "P18T01001"
           "thin CLI wrapper is bootstrap-hosted and cannot be claimed as the seedless release artifact"
           {:source-span {:source "bin/gravity"}
            :phase "P18-T01"
            :bootstrap-hosted? true
            :seedless-release? false
            :remediation "Complete P18-T03 and P18-T05 before claiming the public gravity command is seedless."})))

(defn p18-ensure-dir!
  [path]
  (.mkdirs (java.io.File. path)))

(defn p18-file-bytes
  [path]
  (java.nio.file.Files/readAllBytes
   (.toPath (java.io.File. path))))

(defn p18-bytes-sha256
  [bytes]
  (let [digest (.digest (java.security.MessageDigest/getInstance "SHA-256")
                        bytes)]
    (apply str (map #(format "%02x" (bit-and % 0xff)) digest))))

(defn p18-file-sha256
  [path]
  (if (.isFile (java.io.File. path))
    (str "sha256:" (p18-bytes-sha256 (p18-file-bytes path)))
    "sha256:missing"))

(defn p18-t02-source-material
  []
  (mapv (fn [{:keys [path]}]
          {:path path
           :hash (if (string? path)
                   (p18-file-sha256 path)
                   "sha256:missing")})
        p18-t02-source-inventory))

(defn p18-t02-source-hashes
  []
  (into (sorted-map)
        (map (fn [{:keys [role path]}]
               [role (if (string? path)
                       (p18-file-sha256 path)
                       "sha256:missing")]))
        p18-t02-source-inventory))

(defn p18-t02-packaged-source-entries
  []
  (into
   []
   (keep
    (fn [{:keys [path jar-entry]}]
      (let [suffix (str "/" jar-entry)]
        (when (and (string? path) (string? jar-entry)
                   (str/ends-with? path suffix))
          {:path path
           :source-root (subs path 0 (- (count path) (count suffix)))
           :jar-entry jar-entry}))))
   (filterv :jar-entry p18-t02-source-inventory)))

(defn p18-t02-compiled-jar-entries
  []
  (mapv :compiled-jar-entry
        (filterv :compiled-jar-entry p18-t02-source-inventory)))

(defn p18-t02-expected-jar-file-entries
  []
  (->> (concat [p18-t02-manifest-entry]
               (p18-t02-compiled-jar-entries)
               (map :jar-entry (p18-t02-packaged-source-entries)))
       sort
       vec))

(defn p18-t02-source-inventory-report
  []
  (let [inventory p18-t02-source-inventory
        roles (mapv :role inventory)
        paths (mapv :path inventory)
        packaged-inventory (filterv :jar-entry inventory)
        compiled-inventory (filterv :compiled-jar-entry inventory)
        packaged-sources (p18-t02-packaged-source-entries)
        jar-entries (mapv :jar-entry packaged-inventory)
        compiled-jar-entries (mapv :compiled-jar-entry compiled-inventory)
        material (p18-t02-source-material)
        valid?
        (and (= #{:launcher :bootstrap :diagnostics :cli
                  :darwin-publication :deps}
                (set roles))
             (= (count roles) (count (set roles)))
             (= (count paths) (count (set paths)))
             (= #{:bootstrap :diagnostics :cli :darwin-publication}
                (set (map :role packaged-inventory)))
             (= [:launcher] (mapv :role compiled-inventory))
             (= (count packaged-inventory) (count packaged-sources))
             (= (count jar-entries) (count (set jar-entries)))
             (= [p18-t02-launcher-class-entry] compiled-jar-entries)
             (= (count compiled-jar-entries)
                (count (set compiled-jar-entries)))
             (every? (fn [path]
                       (and (string? path)
                            (not (str/blank? path))
                            (not (.isAbsolute (java.io.File. path)))
                            (.isFile (java.io.File. path))))
                     paths)
             (every? #(re-matches #"sha256:[0-9a-f]{64}" (:hash %))
                     material))]
    {:valid? (boolean valid?)
     :roles roles
     :paths paths
     :packaged-source-entries (mapv :jar-entry packaged-sources)
     :source-material material}))

(defn p18-t02-validate-source-inventory!
  []
  (let [report (p18-t02-source-inventory-report)]
    (when-not (:valid? report)
      (fail! "P18T02006"
             "packaged JVM CLI source inventory is invalid"
             {:source-span {:source "P18-T02 source inventory"}
              :missing-fact :complete-packaged-source-inventory
              :observed-source-count (count (:paths report))
              :observed-packaged-source-count
              (count (:packaged-source-entries report))
              :remediation
              "Restore the exact declared launcher, bootstrap, diagnostics, CLI presentation, Darwin publication provider, and deps inputs before building the package."}))
    report))

(defn p18-t02-jar-source-inventory-report
  [jar-entries]
  (let [expected (mapv :jar-entry (p18-t02-packaged-source-entries))
        observed (filterv #(and (string? %)
                                (str/ends-with? % ".clj"))
                          jar-entries)
        entry-frequencies (frequencies jar-entries)
        valid?
        (and (every? string? jar-entries)
             (= expected observed)
             (every? #(= 1 (get entry-frequencies % 0)) expected))]
    {:valid? (boolean valid?)
     :expected expected
     :observed observed
     :entry-frequencies entry-frequencies}))

(defn p18-t02-jar-inventory-report
  [jar-file-entries]
  (let [expected (p18-t02-expected-jar-file-entries)
        string-entries? (every? string? jar-file-entries)
        observed (if string-entries?
                   (vec (sort jar-file-entries))
                   (vec jar-file-entries))
        entry-frequencies (frequencies jar-file-entries)
        valid?
        (and string-entries?
             (= expected observed)
             (every? #(= 1 (get entry-frequencies % 0)) expected))]
    {:valid? (boolean valid?)
     :expected expected
     :observed observed
     :missing (vec (remove (set observed) expected))
     :unexpected (vec (remove (set expected) observed))
     :entry-frequencies entry-frequencies}))

(defn p18-t02-jar-command
  []
  (vec
   (concat
    ["jar" "--create"
     (str "--file=" p18-t02-jar-path)
     (str "--manifest=" p18-t02-manifest-path)
     "--date=2026-01-01T00:00:00Z"]
    (mapcat (fn [jar-entry]
              ["-C" p18-t02-classes-dir jar-entry])
            (p18-t02-compiled-jar-entries))
    (mapcat (fn [{:keys [source-root jar-entry]}]
              ["-C" source-root jar-entry])
            (p18-t02-packaged-source-entries)))))

(defn p18-t02-classpath-entries
  []
  (vec (remove str/blank?
               (str/split (System/getProperty "java.class.path")
                          (re-pattern java.io.File/pathSeparator)))))

(defn p18-t02-runtime-classpath-entries
  []
  (vec
   (remove
    (fn [entry]
      (or (= entry "bootstrap/clojure/src")
          (= entry "./bootstrap/clojure/src")
          (= entry p18-t02-jar-path)
          (str/ends-with? entry "/bootstrap/clojure/src")
          (str/ends-with? entry "/gravity-jvm-cli.jar")))
    (p18-t02-classpath-entries))))

(defn p18-t02-runtime-classpath
  []
  (str/join java.io.File/pathSeparator
            (p18-t02-runtime-classpath-entries)))

(defn p18-shell-run
  ([args]
   (p18-shell-run nil args))
  ([env args]
   (let [process-builder (ProcessBuilder.
                          ^java.util.List
                          (into ["/bin/bash" "-c" "\"$@\"" "gravity-p18-shell"]
                                (mapv str args)))
         process-env (.environment process-builder)
         stdout-file (java.io.File/createTempFile "gravity-p18-stdout-" ".txt")
         stderr-file (java.io.File/createTempFile "gravity-p18-stderr-" ".txt")
         timeout-ms 60000
         wait-for-exit
         (fn [process timeout-ms]
           (.waitFor process timeout-ms
                     java.util.concurrent.TimeUnit/MILLISECONDS))
         read-output
         (fn [file]
           (if (.exists file)
             (slurp file)
             ""))]
     (when env
       (doseq [[k v] env]
         (.put process-env (str k) (str v))))
     (try
       (.redirectOutput process-builder stdout-file)
       (.redirectError process-builder stderr-file)
       (let [process (.start process-builder)]
         (if (wait-for-exit process timeout-ms)
           {:exit (.exitValue process)
            :out (read-output stdout-file)
            :err (read-output stderr-file)}
           (do
             (.destroyForcibly process)
             (wait-for-exit process 5000)
             {:exit 124
              :out (read-output stdout-file)
              :err (str (read-output stderr-file)
                        "\nprocess timed out after "
                        timeout-ms
                        "ms: "
                        (str/join " " args))})))
       (finally
         (.delete stdout-file)
         (.delete stderr-file))))))

(defn p18-t02-shell!
  [stage args]
  (let [result (p18-shell-run args)]
    (when-not (zero? (:exit result))
      (fail! "P18T02006"
             "packaged JVM CLI build command failed"
             {:source-span {:source stage}
              :stage stage
              :command args
              :stdout (:out result)
              :stderr (:err result)
              :remediation "Install a JDK with javac and jar, then rebuild the P18-T02 package."}))
    result))

(defn p18-t02-write-manifest!
  []
  (spit p18-t02-manifest-path
        (str "Manifest-Version: 1.0\n"
             "Main-Class: gravity.cli.Main\n"
             "Implementation-Title: Gravity Packaged JVM CLI\n"
             "Implementation-Version: P18-T02\n"
             "Gravity-Bootstrap-Hosted: true\n"
             "Gravity-Seedless-Release: false\n\n")))

(declare p18-t02-jar-entries p18-t02-jar-file-entries)

(defn p18-t02-build-packaged-jvm-cli!
  []
  (p18-t02-validate-source-inventory!)
  (p18-ensure-dir! p18-t02-build-root)
  (p18-ensure-dir! p18-t02-classes-dir)
  (p18-t02-write-manifest!)
  (p18-t02-shell!
   "p18-t02-javac"
   ["javac" "-cp" (str/join java.io.File/pathSeparator
                            (p18-t02-classpath-entries))
    "-d" p18-t02-classes-dir
    p18-t02-launcher-source])
  (p18-t02-shell!
   "p18-t02-jar"
   (p18-t02-jar-command))
  (let [source-report
        (p18-t02-jar-source-inventory-report (p18-t02-jar-entries))
        jar-report
        (p18-t02-jar-inventory-report (p18-t02-jar-file-entries))]
    (when-not (and (:valid? source-report) (:valid? jar-report))
      (fail! "P18T02006"
             "packaged JVM CLI JAR inventory is invalid"
             {:source-span {:source p18-t02-jar-path}
              :missing-fact :exact-whole-jar-file-inventory
              :expected-file-entries (:expected jar-report)
              :observed-file-entries (:observed jar-report)
              :missing-file-entries (:missing jar-report)
              :unexpected-file-entries (:unexpected jar-report)
              :packaged-source-inventory-valid?
              (:valid? source-report)
              :remediation
              "Rebuild the package from the exact declared launcher and Clojure source inventory without omissions or ambient files."})))
  p18-t02-jar-path)

(defn p18-t02-jar-entry-records
  []
  (with-open [jar-file (java.util.jar.JarFile. p18-t02-jar-path)]
    (->> (enumeration-seq (.entries jar-file))
         (map (fn [entry]
                {:name (.getName entry)
                 :directory? (.isDirectory entry)}))
         (sort-by :name)
         vec)))

(defn p18-t02-jar-entries
  []
  (mapv :name (p18-t02-jar-entry-records)))

(defn p18-t02-jar-file-entries
  []
  (into []
        (comp (remove :directory?)
              (map :name))
        (p18-t02-jar-entry-records)))

(defn p18-t02-dependency-record
  []
  (let [entries (p18-t02-runtime-classpath-entries)
        dependencies
        (mapv (fn [path]
                {:path path
                 :content-hash (p18-file-sha256 path)
                 :runtime-dependency? true})
              entries)
        base {:artifact :gravity/p18-t02-dependency-record
              :schema-version "gravity.dependency-record/v1"
              :dependency-source :clojure-runtime-classpath
              :bootstrap-hosted? true
              :seedless-release? false
              :dependencies dependencies}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t02-package-manifest
  [jar-hash]
  (let [base {:artifact :gravity/p18-t02-package-manifest
              :schema-version "gravity.package-manifest/v1"
              :package-id "gravity/jvm-cli"
              :package-version "0.0.0-p18-t02"
              :entrypoint "gravity.cli.Main"
              :source-roots ["bootstrap/clojure/src" "bootstrap/clojure/java"]
              :profile :hosted
              :target :jvm-hosted
              :runtime :clojure/jvm
              :artifact-kind :executable
              :artifact-path p18-t02-jar-path
              :content-hash jar-hash
              :bootstrap-hosted? true
              :packaged-jvm-cli? true
              :seedless-release? false
              :public-release-boundary? false
              :replacement-objective :replace-with-self-hosted-release-artifact}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t02-artifact-manifest
  [package-manifest jar-hash]
  (let [base {:artifact :gravity/p18-t02-artifact-manifest
              :schema-version "gravity.artifact-manifest/v1"
              :kind :executable
              :path p18-t02-jar-path
              :content-hash jar-hash
              :package-id (:package-id package-manifest)
              :package-version (:package-version package-manifest)
              :profile (:profile package-manifest)
              :target (:target package-manifest)
              :compiler-identity :clojure-stage0-bootstrap
              :runtime-boundary :clojure-jvm-runtime-dependency
              :evidence-links [:package-manifest :dependency-record
                               :provenance-record :sbom :signing-record]
              :bootstrap-hosted? true
              :seedless-release? false}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t02-reproducible-build-record
  [package-manifest jar-hash]
  (let [base {:artifact :gravity/p18-t02-reproducible-build-record
              :schema-version "gravity.reproducible-build/v1"
              :package-id (:package-id package-manifest)
              :recipe {:javac ["javac" "-cp" "<runtime-classpath>" "-d"
                               p18-t02-classes-dir p18-t02-launcher-source]
                       :jar (p18-t02-jar-command)}
              :timestamp-policy :fixed-jar-entry-time
              :network-policy :disabled-after-local-runtime-dependencies
              :source-inventory p18-t02-source-inventory
              :source-hashes (p18-t02-source-hashes)
              :expected-output-hash jar-hash
              :reproducible-claim :packaged-jvm-bootstrap-milestone
              :final-release-reproducible? false}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t02-provenance-record
  [package-manifest dependency-record reproducible-record jar-hash]
  (let [base {:artifact :gravity/p18-t02-provenance-record
              :schema-version "gravity.provenance/v1"
              :artifact-path p18-t02-jar-path
              :artifact-content-hash jar-hash
              :package-id (:package-id package-manifest)
              :project-manifest-hash (p18-file-sha256 "deps.edn")
              :compiler-identity :clojure-stage0-bootstrap
              :builder-identity {:kind :local-jdk
                                 :java-version (System/getProperty "java.version")
                                 :java-runtime (System/getProperty "java.runtime.name")}
              :source-material (p18-t02-source-material)
              :dependency-record-id (:artifact-id dependency-record)
              :reproducible-build-record-id (:artifact-id reproducible-record)
              :generated-source-ledger []
              :binary-blob-ledger []
              :revocation-status :not-applicable-local-bootstrap-package
              :bootstrap-hosted? true
              :seedless-release? false}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t02-sbom-record
  [package-manifest dependency-record provenance-record]
  (let [base {:artifact :gravity/p18-t02-sbom
              :schema-version "gravity.sbom/v1"
              :package-id (:package-id package-manifest)
              :package-version (:package-version package-manifest)
              :artifact-path p18-t02-jar-path
              :dependencies (:dependencies dependency-record)
              :source-references (p18-t02-source-material)
              :capability-summary {:declared #{:io/stdout}
                                   :denied #{:network/ambient :shell/ambient}}
              :unsafe-summary {:unsafe-islands 0}
              :generated-source-summary []
              :binary-blob-summary []
              :provenance-record-id (:artifact-id provenance-record)
              :bootstrap-hosted? true
              :seedless-release? false}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t02-signing-record
  [artifact-manifest provenance-record sbom-record]
  (let [payload {:artifact-manifest-id (:artifact-id artifact-manifest)
                 :content-hash (:content-hash artifact-manifest)
                 :provenance-record-id (:artifact-id provenance-record)
                 :sbom-id (:artifact-id sbom-record)
                 :signing-policy-id :p18-t02-development-hash-bound-record}
        base {:artifact :gravity/p18-t02-development-signing-record
              :schema-version "gravity.signing-record/v1"
              :payload payload
              :payload-hash (c4-artifact-id payload)
              :signature-mode :development-content-hash-record
              :cryptographic-release-signature? false
              :verification-track :bootstrap-packaged-cli
              :final-release-acceptable? false
              :replacement-objective :p18-t06-release-signing-record}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t02-run-packaged
  [& args]
  (p18-shell-run
   (concat ["java" "-cp"
            (str p18-t02-jar-path
                 java.io.File/pathSeparator
                 (p18-t02-runtime-classpath))
            "gravity.cli.Main"]
           args)))

(defn p18-t02-run-clojure
  [& args]
  (p18-shell-run (concat ["clojure" "-M:gravity"] args)))

(defn p18-t02-run-bin-gravity
  [& args]
  (p18-shell-run {"GRAVITY_PACKAGED_CLI_ONLY" "1"}
                 (concat ["bin/gravity"] args)))

(defn p18-t02-command-proof
  [command path]
  (let [args (cond-> [command] path (conj path))
        packaged (apply p18-t02-run-packaged args)
        clojure-result (apply p18-t02-run-clojure args)]
    {:command (vec (concat ["bin/gravity"] args))
     :packaged-command (vec (concat ["java" "-cp"
                                     "target/phase-18/jvm-cli/gravity-jvm-cli.jar:<runtime-classpath>"
                                     "gravity.cli.Main"]
                                    args))
     :clojure-command (vec (concat ["clojure" "-M:gravity"] args))
     :exit-match? (= (:exit packaged) (:exit clojure-result))
     :stdout-match? (= (:out packaged) (:out clojure-result))
     :stderr-match? (= (:err packaged) (:err clojure-result))
     :exit (:exit packaged)
     :stdout (:out packaged)
     :stderr (:err packaged)}))

(def p18-t02-diagnostic-messages
  {"P18T02001" "packaged JVM CLI is not the seedless release artifact"
   "P18T02002" "packaged JVM CLI manifest is missing package metadata"
   "P18T02003" "packaged JVM CLI command parity proof failed"
   "P18T02004" "packaged JVM CLI target claim is unsupported"
   "P18T02005" "packaged JVM CLI provenance is missing"
   "P18T02006" "packaged JVM CLI build failed"})

(defn p18-t02-diagnostic-record
  [id fixture value data]
  {:artifact :gravity/diagnostic
   :diagnostic id
   :severity :error
   :stage :p18-t02-packaged-jvm-cli
   :fixture fixture
   :message (get p18-t02-diagnostic-messages id)
   :observed value
   :facts data})

(defn p18-t02-candidate-diagnostics
  [fixture candidate]
  (let [manifest (:package-manifest candidate)
        missing-fields
        (vec (remove #(contains? manifest %)
                     [:package-id :package-version :entrypoint :target
                      :artifact-path :content-hash]))
        parity (:command-parity candidate)]
    (vec
     (concat
      (when (seq missing-fields)
        [(p18-t02-diagnostic-record
          "P18T02002" fixture manifest {:missing-fields missing-fields})])
      (when-not (every? true?
                        (mapcat (fn [proof]
                                  [(:exit-match? proof)
                                   (:stdout-match? proof)
                                   (:stderr-match? proof)])
                                parity))
        [(p18-t02-diagnostic-record
          "P18T02003" fixture parity {:required [:exit :stdout :stderr]})])
      (when-not (= :jvm-hosted (:target manifest))
        [(p18-t02-diagnostic-record
          "P18T02004" fixture (:target manifest)
          {:supported-target :jvm-hosted})])
      (when-not (:provenance-record candidate)
        [(p18-t02-diagnostic-record
          "P18T02005" fixture nil
          {:required-record :provenance-record})])))))

(defn p18-t02-rejected-fixture-records
  [candidate]
  (let [fixtures
        [{:fixture :p18-t02-missing-package-metadata
          :expected-diagnostic "P18T02002"
          :candidate (update candidate :package-manifest dissoc
                             :package-id :package-version)}
         {:fixture :p18-t02-command-parity-mismatch
          :expected-diagnostic "P18T02003"
          :candidate (assoc-in candidate
                               [:command-parity 0 :stdout-match?]
                               false)}
         {:fixture :p18-t02-invalid-target-claim
          :expected-diagnostic "P18T02004"
          :candidate (assoc-in candidate
                               [:package-manifest :target]
                               :native-seedless)}
         {:fixture :p18-t02-missing-package-provenance
          :expected-diagnostic "P18T02005"
          :candidate (assoc candidate :provenance-record nil)}]]
    (mapv
     (fn [{:keys [fixture expected-diagnostic candidate]}]
       (let [diagnostics (p18-t02-candidate-diagnostics fixture candidate)
             observed (set (map :diagnostic diagnostics))]
         {:fixture fixture
          :status :rejected
          :expected-diagnostic expected-diagnostic
          :diagnostics diagnostics
          :matches-expected? (contains? observed expected-diagnostic)}))
     fixtures)))

(defn p18-t02-packaged-jvm-cli-artifact!
  []
  (p18-t02-build-packaged-jvm-cli!)
  (let [jar-entries (p18-t02-jar-entries)
        jar-file-entries (p18-t02-jar-file-entries)
        jar-source-report
        (p18-t02-jar-source-inventory-report jar-entries)
        jar-inventory-report
        (p18-t02-jar-inventory-report jar-file-entries)
        jar-entry-frequencies (:entry-frequencies jar-source-report)
        expected-source-entries (:expected jar-source-report)
        jar-hash (p18-file-sha256 p18-t02-jar-path)
        dependency-record (p18-t02-dependency-record)
        package-manifest (p18-t02-package-manifest jar-hash)
        artifact-manifest (p18-t02-artifact-manifest package-manifest jar-hash)
        reproducible-record
        (p18-t02-reproducible-build-record package-manifest jar-hash)
        provenance-record
        (p18-t02-provenance-record package-manifest dependency-record
                                   reproducible-record jar-hash)
        sbom-record (p18-t02-sbom-record package-manifest dependency-record
                                         provenance-record)
        signing-record (p18-t02-signing-record artifact-manifest
                                               provenance-record sbom-record)
        command-parity
        [(p18-t02-command-proof "check" "examples/hello.gravity")
         (p18-t02-command-proof "run" "examples/hello.gravity")
         (p18-t02-command-proof "compile" "examples/hello.gravity")
         (p18-t02-command-proof "check" "examples/core-app.gravity")
         (p18-t02-command-proof "run" "examples/core-app.gravity")
         (p18-t02-command-proof "compile" "examples/core-app.gravity")
         (p18-t02-command-proof "p18-t01-thin-cli-wrapper" nil)]
        rejected-command
        (p18-t02-command-proof
         "run-compiled"
         "bootstrap/clojure/fixtures/rejected/core-app-builtin-arity.gravity")
        bin-version (p18-t02-run-bin-gravity "--version")
        seedless-claim (p18-t02-run-bin-gravity "--assert-seedless-release")
        candidate {:package-manifest package-manifest
                   :artifact-manifest artifact-manifest
                   :dependency-record dependency-record
                   :provenance-record provenance-record
                   :sbom-record sbom-record
                   :signing-record signing-record
                   :command-parity command-parity}
        rejected-fixtures (p18-t02-rejected-fixture-records candidate)
        proof {:packaged-jar-built? (.isFile (java.io.File. p18-t02-jar-path))
               :jar-contains-launcher?
               (boolean
                (some #{"gravity/cli/Main.class"} jar-entries))
               :jar-contains-bootstrap-source?
               (= 1 (get jar-entry-frequencies "gravity/bootstrap.clj" 0))
               :jar-contains-cli-source?
               (= 1 (get jar-entry-frequencies "gravity/cli.clj" 0))
               :jar-contains-diagnostics-source?
               (= 1 (get jar-entry-frequencies "gravity/diagnostics.clj" 0))
               :jar-contains-darwin-publication-source?
               (= 1 (get jar-entry-frequencies
                         "gravity/darwin_publication.clj" 0))
               :jar-contains-packaged-sources-exactly-once?
               (:valid? jar-source-report)
               :jar-file-inventory-exact?
               (:valid? jar-inventory-report)
               :bin-gravity-launches-packaged-jar?
               (and (zero? (:exit bin-version))
                    (str/includes? (:out bin-version)
                                   ":packaged-jvm-cli? true"))
               :command-parity? (every? true?
                                        (mapcat (fn [proof]
                                                  [(:exit-match? proof)
                                                   (:stdout-match? proof)
                                                   (:stderr-match? proof)])
                                                command-parity))
               :accepted-hello-through-packaged-cli?
               (and (zero? (:exit (first command-parity)))
                    (zero? (:exit (second command-parity))))
               :accepted-core-app-through-packaged-cli?
               (and (zero? (:exit (nth command-parity 3)))
                    (zero? (:exit (nth command-parity 4))))
               :rejected-diagnostic-preserved?
               (and (= 1 (:exit rejected-command))
                    (str/includes? (:stderr rejected-command)
                                   "L2-BUILTIN-ARITY"))
               :package-records-present?
               (every? some?
                       [package-manifest dependency-record artifact-manifest
                        provenance-record sbom-record signing-record])
               :seedless-overclaim-rejected?
               (and (= 1 (:exit seedless-claim))
                    (str/includes? (:err seedless-claim) "P18T02001"))
               :bootstrap-hosted? true
               :seedless-release? false}
        artifact-base
        {:kind :gravity/p18-t02-packaged-jvm-cli-proof
         :task "P18-T02"
         :status :complete
         :phase :binary-distribution-and-seedless-release
         :jar-path p18-t02-jar-path
         :jar-content-hash jar-hash
         :jar-entries jar-entries
         :jar-file-entries jar-file-entries
         :packaged-source-inventory p18-t02-source-inventory
         :packaged-source-entries expected-source-entries
         :command-boundary
         {:public-command "bin/gravity"
          :packaged-command ["java" "-cp"
                             "target/phase-18/jvm-cli/gravity-jvm-cli.jar:<runtime-classpath>"
                             "gravity.cli.Main"]
          :bootstrap-recovery-command "bin/gravity-bootstrap"
          :bootstrap-hosted? true
          :packaged-jvm-cli? true
          :seedless-release? false
          :public-release-boundary? false
          :runtime-dependency-boundary :clojure-jvm-runtime-dependency}
         :package-manifest package-manifest
         :dependency-record dependency-record
         :artifact-manifest artifact-manifest
         :reproducible-build-record reproducible-record
         :provenance-record provenance-record
         :sbom-record sbom-record
         :signing-record signing-record
         :accepted-command-proofs command-parity
         :rejected-command-proof rejected-command
         :bin-version-output (:out bin-version)
         :unsupported-release-claim
         {:command ["bin/gravity" "--assert-seedless-release"]
          :diagnostic "P18T02001"
          :bootstrap-hosted? true
          :packaged-jvm-cli? true
          :seedless-release? false}
         :rejected-fixtures rejected-fixtures
         :capability-based-proof proof}
        artifact (assoc artifact-base :artifact-id
                        (c4-artifact-id artifact-base))]
    artifact))

(defn p18-t02-write-edn!
  [path value]
  (p18-ensure-dir! (.getParent (java.io.File. path)))
  (spit path (str (pr-str value) "\n")))

