           :opened-source-read-failed
           {:captured-errno
            (p18-t04-verified-mir-c-source-native-errno binding state)})

          (zero? read-count)
          (do
            (when-not (= offset initial-byte-count)
              (p18-t04-verified-mir-c-source-snapshot-fail!
               source-path :stable-bounded-source-snapshot
               :opened-source-size-changed-during-snapshot
               {:initial-byte-count initial-byte-count
                :observed-byte-count offset}))
            (.toArray (.asSlice buffer (long 0) (long offset))
                      java.lang.foreign.ValueLayout/JAVA_BYTE))

          (> (+ offset read-count) initial-byte-count)
          (p18-t04-verified-mir-c-source-snapshot-fail!
           source-path :stable-bounded-source-snapshot
           :opened-source-size-grew-during-snapshot
           {:maximum-byte-count
            p18-t04-verified-mir-c-maximum-source-bytes
            :initial-byte-count initial-byte-count
            :observed-byte-count (+ offset read-count)})

          :else
          (recur (+ offset (int read-count))))))))

(defn- p18-t04-verified-mir-c-source-native-close
  [binding state file-descriptor]
  (p18-t04-verified-mir-c-source-native-int-call
   binding :close state [file-descriptor]))

(defn- p18-t04-verified-mir-c-with-source-descriptor!
  [binding arena state source-path actual-path f]
  (let [file-descriptor
        (p18-t04-verified-mir-c-source-native-open!
         binding arena state source-path actual-path)
        close-attempted? (atom false)]
    (try
      (let [result (f file-descriptor)
            _ (reset! close-attempted? true)
            close-code
            (p18-t04-verified-mir-c-source-native-close
             binding state file-descriptor)]
        (when-not (zero? close-code)
          (p18-t04-verified-mir-c-source-snapshot-fail!
           source-path :descriptor-bound-source-snapshot
           :opened-source-close-failed
           {:captured-errno
            (p18-t04-verified-mir-c-source-native-errno binding state)}))
        result)
      (finally
        (when-not @close-attempted?
          (try
            (p18-t04-verified-mir-c-source-native-close
             binding state file-descriptor)
            (catch Throwable _ nil)))))))

(defn p18-t04-verified-mir-c-source-input!
  [source-path]
  (let [character-count (when (string? source-path) (count source-path))
        utf8-byte-count
        (when (and (string? source-path)
                   (<= 1 character-count 4096))
          (alength (.getBytes ^String source-path
                             java.nio.charset.StandardCharsets/UTF_8)))]
    (when-not
     (and (string? source-path)
          (<= 1 character-count 4096)
          (<= 1 (or utf8-byte-count 0) 4096)
          (not (str/blank? source-path))
          (not (str/includes? source-path "\u0000"))
          (not-any? #(Character/isISOControl ^char %) source-path))
      (p18-t04-verified-mir-c-source-snapshot-fail!
       (if (string? source-path) source-path
           "<verified-mir-c-source>")
       :bounded-public-gravity-source-path
       :invalid-source-path-spelling {})))
  (try
    (let [requested-path
          (java.nio.file.Paths/get source-path (make-array String 0))
          _
          (when (java.nio.file.Files/isSymbolicLink requested-path)
            (p18-t04-verified-mir-c-source-snapshot-fail!
             source-path :bounded-readable-regular-gravity-source
             :source-final-component-is-symbolic-link
             {:maximum-byte-count
              p18-t04-verified-mir-c-maximum-source-bytes}))
          requested-actual-path-before
          (.toString
           (.toRealPath requested-path
                        (make-array java.nio.file.LinkOption 0)))
          binding
          (p18-t04-verified-mir-c-source-native-binding! source-path)
          snapshot
          (with-open [arena (java.lang.foreign.Arena/ofConfined)]
            (let [state (.allocate arena (:state-layout binding))
                  path-stat-before
                  (p18-t04-verified-mir-c-source-native-path-stat!
                   binding arena state source-path requested-actual-path-before)]
              (p18-t04-verified-mir-c-with-source-descriptor!
               binding arena state source-path requested-actual-path-before
               (fn [file-descriptor]
                 (let [descriptor-stat-before
                       (p18-t04-verified-mir-c-source-native-fstat!
                        binding arena state source-path file-descriptor)
                       descriptor-path-before
                       (p18-t04-verified-mir-c-source-native-fd-path!
                        binding arena state source-path file-descriptor)
                       descriptor-path-stat-before
                       (p18-t04-verified-mir-c-source-native-path-stat!
                        binding arena state source-path
                        descriptor-path-before)
                       initial-byte-count (:byte-count descriptor-stat-before)
                       regular?
                       (= p18-t04-darwin-s-ifreg
                          (bit-and (:mode descriptor-stat-before)
                                   p18-t04-darwin-s-ifmt))
                       _
                       (when-not
                        (and regular?
                             (= path-stat-before descriptor-stat-before
                                descriptor-path-stat-before)
                             (<= 0 initial-byte-count
                                 p18-t04-verified-mir-c-maximum-source-bytes))
                         (p18-t04-verified-mir-c-source-snapshot-fail!
                          source-path
                          :bounded-readable-regular-gravity-source
                          :path-and-opened-descriptor-identity-mismatch
                          {:maximum-byte-count
                           p18-t04-verified-mir-c-maximum-source-bytes
                           :observed-byte-count initial-byte-count}))
                       bytes
                       (p18-t04-verified-mir-c-source-native-read-bytes!
                        binding arena state source-path file-descriptor
                        initial-byte-count)
                       descriptor-stat-after
                       (p18-t04-verified-mir-c-source-native-fstat!
                        binding arena state source-path file-descriptor)
                       descriptor-path-after
                       (p18-t04-verified-mir-c-source-native-fd-path!
                        binding arena state source-path file-descriptor)
                       descriptor-path-stat-after
                       (p18-t04-verified-mir-c-source-native-path-stat!
                        binding arena state source-path descriptor-path-after)
                       requested-path-stat-after
                       (p18-t04-verified-mir-c-source-native-path-stat!
                        binding arena state source-path
                        requested-actual-path-before)
                       requested-actual-path-after
                       (.toString
                        (.toRealPath
                         requested-path
                         (make-array java.nio.file.LinkOption 0)))]
                   (when-not
                    (and (= path-stat-before descriptor-stat-before
                            descriptor-path-stat-before
                            descriptor-stat-after
                            descriptor-path-stat-after
                            requested-path-stat-after)
                         (= requested-actual-path-before
                            requested-actual-path-after)
                         (not (java.nio.file.Files/isSymbolicLink
                               requested-path))
                         (= descriptor-path-before descriptor-path-after)
                         (= (alength bytes)
                            (:byte-count descriptor-stat-after)))
                     (p18-t04-verified-mir-c-source-snapshot-fail!
                      source-path :stable-bounded-source-snapshot
                      :source-path-or-descriptor-mutated-during-snapshot
                      {:observed-byte-count (alength bytes)
                       :after-byte-count
                       (:byte-count descriptor-stat-after)}))
                   {:actual-path descriptor-path-after
                    :identity descriptor-stat-after
                    :bytes bytes})))))
          bytes (:bytes snapshot)
          actual-path (:actual-path snapshot)
          _
          (when-not (qst-or-gravity-source? source-path)
            (source-path-policy-fail! source-path bytes))
          source-text (decode-gravity-source-bytes actual-path bytes)
          content-hash (str "sha256:" (sha256-bytes-hex bytes))]
      {:source-path actual-path
       :source-text source-text
       :source-snapshot-evidence
       {:kind :gravity/p18-t04-bounded-source-snapshot
        :schema-version 1
        :policy-id
        (p15-s23-c11-mir-digest
         (:source-snapshot-policy
          p18-t04-experimental-verified-mir-c-route-policy))
        :actual-path actual-path
        :file-key-hash
        (p15-s23-c11-mir-digest
         {:kind :gravity/p18-t04-source-file-key
          :schema-version 1
          :device (get-in snapshot [:identity :device])
          :inode (get-in snapshot [:identity :inode])})
        :byte-count (alength bytes)
        :content-hash content-hash
        :capture-provider :jdk26-ffm-darwin-libsystem
        :native-functions
        ["fstatat" "open" "fstat" "fcntl" "read" "close"]
        :identity-observation-phase-count
        (count
         (get-in p18-t04-experimental-verified-mir-c-route-policy
                 [:source-snapshot-policy :identity-observation-phases]))
        :source-byte-path-reopen-count 0
        :opened-handle-file-key-observation
        :native-fstat-device-and-inode
        :opened-handle-size-parity? true
        :path-and-descriptor-identity-parity? true
        :native-access-enabled?
        (.isNativeAccessEnabled (.getModule clojure.lang.RT))
        :status :captured}})
    (catch java.nio.file.NoSuchFileException _
      (p18-t04-verified-mir-c-source-snapshot-fail!
       source-path :bounded-readable-regular-gravity-source
       :missing-nonregular-unreadable-or-oversize-source
       {:maximum-byte-count
        p18-t04-verified-mir-c-maximum-source-bytes}))
    (catch java.nio.file.AccessDeniedException _
      (p18-t04-verified-mir-c-source-snapshot-fail!
       source-path :bounded-readable-regular-gravity-source
       :missing-nonregular-unreadable-or-oversize-source
       {:maximum-byte-count
        p18-t04-verified-mir-c-maximum-source-bytes}))
    (catch java.nio.file.InvalidPathException _
      (p18-t04-verified-mir-c-source-snapshot-fail!
       source-path :readable-gravity-source :invalid-source-path {}))
    (catch java.nio.channels.ClosedByInterruptException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch java.io.InterruptedIOException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch UnsupportedOperationException _
      (p18-t04-verified-mir-c-source-snapshot-fail!
       source-path :descriptor-bound-source-snapshot
       :source-provider-lacks-descriptor-bound-capture {}))
    (catch SecurityException _
      (p18-t04-verified-mir-c-source-snapshot-fail!
       source-path :readable-gravity-source :source-security-denial {}))
    (catch java.io.IOException _
      (p18-t04-verified-mir-c-source-snapshot-fail!
       source-path :readable-gravity-source :source-io-failure {}))
    (catch clojure.lang.ExceptionInfo exception
      (throw exception))
    (catch Exception _
      (p18-t04-verified-mir-c-source-snapshot-fail!
       source-path :descriptor-bound-source-snapshot
       :contained-source-snapshot-host-failure {}))))

(defn- p18-t04-verified-mir-c-authenticated-source-snapshot!
  [source-path source-text evidence]
  (let [source-bytes
        (when (string? source-text)
          (.getBytes ^String source-text
                     java.nio.charset.StandardCharsets/UTF_8))
        snapshot-policy
        (:source-snapshot-policy
         p18-t04-experimental-verified-mir-c-route-policy)
        expected-policy-id (p15-s23-c11-mir-digest snapshot-policy)
        expected-content-hash
        (when source-bytes
          (str "sha256:" (sha256-bytes-hex source-bytes)))
        expected-phase-count
        (count (:identity-observation-phases snapshot-policy))]
    (when-not
     (and (string? source-path)
          source-bytes
          (map? evidence)
          (= p18-t04-verified-mir-c-source-snapshot-evidence-keys
             (set (keys evidence)))
          (= :gravity/p18-t04-bounded-source-snapshot (:kind evidence))
          (= 1 (:schema-version evidence))
          (= expected-policy-id (:policy-id evidence))
          (= source-path (:actual-path evidence))
          (string? (:file-key-hash evidence))
          (re-matches #"sha256:[0-9a-f]{64}" (:file-key-hash evidence))
          (= (alength ^bytes source-bytes) (:byte-count evidence))
          (<= 0 (:byte-count evidence)
              p18-t04-verified-mir-c-maximum-source-bytes)
          (= expected-content-hash (:content-hash evidence))
          (= (:capture-provider snapshot-policy)
             (:capture-provider evidence))
          (= (:native-functions snapshot-policy)
             (:native-functions evidence))
          (= expected-phase-count
             (:identity-observation-phase-count evidence))
          (= 0 (:source-byte-path-reopen-count evidence))
          (= :native-fstat-device-and-inode
             (:opened-handle-file-key-observation evidence))
          (true? (:opened-handle-size-parity? evidence))
          (true? (:path-and-descriptor-identity-parity? evidence))
          (= (.isNativeAccessEnabled (.getModule clojure.lang.RT))
             (:native-access-enabled? evidence))
          (= :captured (:status evidence)))
      (p18-t04-fail!
       "P18T04001"
       {:source (if (string? source-path)
                  source-path
                  "<verified-mir-c-source>")
        :missing-fields
        [:authenticated-descriptor-bound-source-snapshot-evidence]}))
    {:source-snapshot-evidence evidence
     :source-snapshot-evidence-id
     (p15-s23-c11-mir-digest
      {:kind :gravity/p18-t04-authenticated-source-snapshot-evidence
       :schema-version 1
       :evidence evidence})}))

(defn- p18-t04-experimental-verified-mir-c-gate-b-handoff!
  [source-path source-text source-snapshot-evidence output-directory gate-b]
  (let [{:keys [source-snapshot-evidence source-snapshot-evidence-id]}
        (p18-t04-verified-mir-c-authenticated-source-snapshot!
         source-path source-text source-snapshot-evidence)
        _ (p15-s23-b2-c17-gate-b-integrity-preflight! source-path gate-b)
        receipt (:publication-receipt gate-b)
        provenance (:actual-path-provenance gate-b)
        expected-semantic-id
        (p15-s23-b2-c17-gate-b-artifact-id gate-b)
        expected-artifact-id
        (p15-s23-c11-mir-digest
         {:kind :gravity/b2-hosted-c17-gate-b-artifact
          :schema-version 1 :semantic-id expected-semantic-id})
        expected-path-binding-id
        (p15-s23-b2-c17-gate-b-path-binding-id
         expected-semantic-id provenance receipt)]
    (when-not
     (and (= p15-s23-b2-c17-gate-b-final-artifact-keys
             (set (keys gate-b)))
          (= :gravity/b2-hosted-c17-gate-b (:artifact gate-b))
          (= 1 (:schema-version gate-b))
          (= :validated-bounded-internal-c17-candidate (:status gate-b))
          (= p15-s23-b2-c17-gate-b-policy (:policy gate-b))
          (= source-path (:source provenance))
          (= output-directory (:actual-output-directory provenance))
          (= output-directory (:actual-output-directory receipt))
          (p15-s23-b2-c17-gate-b-canonical-published-receipt?
           receipt output-directory)
          (= [expected-semantic-id expected-artifact-id
              expected-path-binding-id]
             ((juxt :semantic-id :artifact-id :actual-path-binding-id)
              gate-b))
          (= [] (:diagnostics gate-b))
          (true? (get-in gate-b
                         [:toolchain-evidence :publication-intent?]))
          (false? (:whole-b2? gate-b))
          (false? (:public? gate-b))
          (false? (:release? gate-b))
          (false? (:self-hosted? gate-b))
          (true? (:seed-boundary? gate-b))
          (true? (:clojure-seed-boundary? gate-b))
          (not (contains? gate-b :publication-payload))
          (not (contains? (:toolchain-evidence gate-b)
                          :publication-payload)))
      (p18-t04-fail!
       "P18T04001"
       {:source source-path
        :missing-fields [:exact-published-c17-gate-b-handoff]}))
    {:gate-b gate-b
     :source-snapshot-evidence source-snapshot-evidence
     :source-snapshot-evidence-id source-snapshot-evidence-id
     :publication-receipt-id
     (p15-s23-c11-mir-digest
      {:kind :gravity/b2-c17-gate-b-publication-receipt
       :schema-version 1 :receipt receipt})}))

(defn- p18-t04-experimental-verified-mir-c-gate-b-summary
  [gate-b publication-receipt-id]
  {:artifact (:artifact gate-b)
   :schema-version (:schema-version gate-b)
   :status (:status gate-b)
   :semantic-id (:semantic-id gate-b)
   :artifact-id (:artifact-id gate-b)
   :actual-path-binding-id (:actual-path-binding-id gate-b)
   :policy (:policy gate-b)
   :publication-receipt (:publication-receipt gate-b)
   :publication-receipt-id publication-receipt-id
   :whole-b2? (:whole-b2? gate-b)
   :public? (:public? gate-b)
   :release? (:release? gate-b)
   :self-hosted? (:self-hosted? gate-b)
   :seed-boundary? (:seed-boundary? gate-b)
   :clojure-seed-boundary? (:clojure-seed-boundary? gate-b)})

(defn- p18-t04-experimental-verified-mir-c-route-record
  [source-path source-text source-snapshot-evidence output-directory gate-b]
  (let [{:keys [gate-b publication-receipt-id
                source-snapshot-evidence source-snapshot-evidence-id]}
        (p18-t04-experimental-verified-mir-c-gate-b-handoff!
         source-path source-text source-snapshot-evidence
         output-directory gate-b)
        summary
        (p18-t04-experimental-verified-mir-c-gate-b-summary
         gate-b publication-receipt-id)
        semantic-id
        (p15-s23-c11-mir-digest
         {:kind :gravity/p18-t04-experimental-verified-mir-c-route
          :schema-version 1
          :route-policy p18-t04-experimental-verified-mir-c-route-policy
          :gate-b
          (select-keys summary [:semantic-id :artifact-id])})
        artifact-id
        (p15-s23-c11-mir-digest
         {:kind :gravity/p18-t04-experimental-verified-mir-c-route-artifact
          :schema-version 1 :semantic-id semantic-id})
        actual-path-provenance
        {:source source-path
         :source-snapshot-evidence-id source-snapshot-evidence-id
         :output-directory output-directory}
        actual-path-binding-id
        (p15-s23-c11-mir-digest
         {:kind :gravity/p18-t04-experimental-verified-mir-c-route-path-binding
          :schema-version 1 :semantic-id semantic-id
          :actual-path-provenance actual-path-provenance
          :gate-b-actual-path-binding-id (:actual-path-binding-id summary)
          :gate-b-publication-receipt-id publication-receipt-id})
        result
        {:kind :gravity/p18-t04-experimental-verified-mir-c-route
         :schema-version 1 :task "P18-T04"
         :status
         :implemented-internal-candidate-public-exposure-disabled
         :route-policy p18-t04-experimental-verified-mir-c-route-policy
         :source
         {:kind (gravity-source-kind source-path)
          :extension (gravity-source-extension source-path)
          :content-hash (str "sha256:" (sha256-hex source-text))}
         :source-snapshot-evidence source-snapshot-evidence
         :source-snapshot-evidence-id source-snapshot-evidence-id
         :source-target :jvm :requested-target :c :profile :hosted
         :lowering-mode :verified-mir
         :command-boundary
         {:grammar (:command-grammar
                    p18-t04-experimental-verified-mir-c-route-policy)
          :output-kind :bundle-directory
          :experimental? true
          :governance-status :pending-feature-specific-review
          :activation :internal-proof-only
          :replacement :established-bootstrap-compile-routes}
         :gate-b-summary summary
         :semantic-id semantic-id :artifact-id artifact-id
         :actual-path-provenance actual-path-provenance
         :actual-path-binding-id actual-path-binding-id
         :diagnostics []
         :governance-status :pending-feature-specific-review
         :governance-conforming? false
         :security-review-complete? false
         :unsafe-review-complete? false
         :target-support-record-complete? false
         :t1-cli-conformance? false
         :p18-t04-proof-credited? false
         :experimental-use-notice
         (:experimental-use-notice
          p18-t04-experimental-verified-mir-c-route-policy)
         :public-command-route? false
         :public-target-support-claim? false
         :whole-b2? false :public? false :release? false :self-hosted? false
         :seed-boundary? true :clojure-seed-boundary? true}]
    (when-not
     (= p18-t04-experimental-verified-mir-c-route-artifact-keys
        (set (keys result)))
      (p18-t04-fail!
       "P18T04001"
       {:source source-path
        :missing-fields [:exact-experimental-verified-mir-c-route-envelope]}))
    result))

(defn- p18-t04-compile-internal-experimental-verified-mir-c-target-file!
  [request]
  (try
    (let [request (p18-t04-verified-mir-c-request! request)
          output-directory
          (p18-t04-verified-mir-c-output-directory!
           (:source-path request) (:output-path request))
          {:keys [source-path source-text source-snapshot-evidence]}
          (p18-t04-verified-mir-c-source-input! (:source-path request))]
      ;; The private Gate-B path executes the projector while the complete
      ;; bundle is still staged, then makes the exclusive rename its final
      ;; success-path effect and returns this precomputed route record.
      (p15-s23-stage2-b2-c17-gate-b-p18-t04-route-source-artifact!
       source-path source-text source-snapshot-evidence output-directory))
    (catch InterruptedException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch java.nio.channels.ClosedByInterruptException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch java.io.InterruptedIOException interrupted
      (.interrupt (Thread/currentThread))
      (throw interrupted))
    (catch clojure.lang.ExceptionInfo exception
      (throw exception))
    (catch Exception _
      (p15-s23-c-backend-fail!
       "C14-INPUT" (or (:source-path request) "<verified-mir-c-route>") {}
       {:missing-fact :contained-internal-verified-mir-c-route-host-failure
        :source-target :jvm :requested-target :c
        :bounded-reason :internal-route-host-failure}))))

(defn p18-t04-compile-experimental-verified-mir-c-target-file!
  "Governed public wrapper for the internal verified-MIR C candidate."
  [request]
  (let [request (p18-t04-verified-mir-c-public-authority! request)]
    (p18-t04-compile-internal-experimental-verified-mir-c-target-file!
     request)))

(defn p18-shell-single-quote
  [text]
  (str "'" (str/replace (str text) "'" "'\"'\"'") "'"))

(defn p18-t04-release-candidate
  []
  (or (p18-t03-read-edn-artifact p18-t03-release-artifact-path)
      (:release-artifact-candidate
       (p18-t03-write-self-hosted-release-artifacts!))))

(defn p18-t04-executable-script
  [record stdout]
  (str "#!/usr/bin/env bash\n"
       "set -euo pipefail\n"
       "# Gravity P18-T04 executable command artifact\n"
       "# source: " (get-in record [:source :path]) "\n"
       "# source-sha256: " (get-in record [:source :sha256]) "\n"
       "# compiled-plan-id: " (:compiled-plan-id record) "\n"
       "# release-artifact-id: " (:release-artifact-id record) "\n"
       "# final-seedless-release: false\n"
       "printf '%s' " (p18-shell-single-quote stdout) "\n"))

(defn p18-t04-compile-executable-file!
  [source-path output-path]
  (when-not (p18-t04-output-path-allowed? output-path)
    (p18-t04-fail! "P18T04002"
                   {:source source-path
                    :output-path output-path
                    :allowed-output-roots ["target/" "<current-directory>"]}))
  (let [source-text (slurp source-path)
        _ (validate-stage0-source-profile! source-path source-text)
        _ (validate-stage0-source-safety! source-path source-text)
        macro-artifact (macro-source-artifact source-path source-text)
        module (assoc (:module macro-artifact)
                      :forms (:expanded-forms macro-artifact))
        compiled-plan (stage0-compiled-core-plan source-path source-text
                                                 module)
        stdout (execute-stage0-compiled-plan compiled-plan)
        release-candidate (p18-t04-release-candidate)
        output-file (java.io.File. output-path)
        sidecar-path (str output-path ".gravity-artifact.edn")
        _ (when-let [parent (.getParentFile output-file)]
            (.mkdirs parent))
        base {:kind :gravity/p18-t04-executable-artifact
              :schema-version "gravity.executable-command-artifact/v1"
              :task "P18-T04"
              :status :complete
              :source {:path source-path
                       :sha256 (p18-file-sha256 source-path)}
              :module (select-keys module
                                   [:module :profile :target :effects
                                    :capabilities :exports :safety])
              :compiled-plan-id (:plan-id compiled-plan)
              :compiled-plan-kind (:kind compiled-plan)
              :compiled-plan-summary
              (select-keys compiled-plan
                           [:entrypoint :instruction-summary
                            :effect-summary])
              :release-artifact-id (:artifact-id release-candidate)
              :release-artifact-path (:release-artifact-path
                                      release-candidate)
              :compiler-path-id (:compiler-path-id release-candidate)
              :runtime-path-id (:runtime-path-id release-candidate)
              :release-compiler-id (:release-compiler-id release-candidate)
              :command-boundary
              {:compile-command ["bin/gravity" "compile" source-path "-o"
                                 output-path]
               :run-command [output-path]
               :public-command "bin/gravity"
               :bootstrap-recovery-command "bin/gravity-bootstrap"
               :public-executable-command-contract? true
               :final-seedless-release? false}
              :executable-path output-path
              :sidecar-path sidecar-path
              :expected-stdout stdout
              :execution-strategy :stage0-compiled-main-stdout-executable
              :runtime-boundary :posix-shell-executable-artifact
              :bootstrap-hosted-compile-command? true
              :self-hosted-release-artifact-linked? true
              :seedless-release? false
              :final-release-boundary? false
              :diagnostics []}
        script (p18-t04-executable-script base stdout)
        _ (spit output-path script)
        _ (.setExecutable output-file true false)
        executable-hash (p18-file-sha256 output-path)
        artifact-base (assoc base
                             :executable-content-hash executable-hash)
        artifact (assoc artifact-base
                        :artifact-id (c4-artifact-id artifact-base))]
    (p18-t02-write-edn! sidecar-path artifact)
    artifact))

(defn p18-t04-compile-c-target-file!
  "Compile the current source unit through the real C backend boundary.

  Unlike the legacy JVM command, this path writes C11 source, invokes the host
  C compiler, and returns the backend manifest/source-map/provenance artifact.
  The Clojure bootstrap and hosted-libc runtime remain explicit in the record;
  this is not a seedless-release claim."
  ([source-path output-path target]
   (p18-t04-compile-c-target-file! source-path output-path target nil))
  ([source-path output-path target lowering-mode]
   (let [source-text (read-gravity-source-text source-path)]
    ;; Reject unsupported target selection before reader/macro/lowering work;
    ;; this keeps the public boundary's C14 diagnostic deterministic.
    (when-not (contains? c-backend-supported-targets target)
      (c-backend-fail! "C14-TARGET"
                       "C backend target is unsupported"
                       source-path target nil
                       {:supported-targets
                        (vec (sort c-backend-supported-targets))
                        :missing-fact :supported-target
                        :remediation "Request :c, :c-hosted, or :c11 explicitly."}))
    (when (and lowering-mode
               (not= :runtime-derived lowering-mode))
      (c-backend-fail! "C14-TARGET"
                       "requested C lowering mode is unsupported"
                       source-path target nil
                       {:lowering-mode lowering-mode
                        :supported-lowering-modes [:runtime-derived]
                        :missing-fact :runtime-c-lowering-mode
                        :remediation "Request --lowering runtime-derived for the opt-in runtime-derived C subset, or omit --lowering for the verified stage0 fallback."}))
    (when-not output-path
      (c-backend-fail! "C14-INPUT"
                       "C target compilation requires an explicit executable output"
                       source-path target nil
                       {:missing-fields [:output-path]
                        :remediation "Use --target c -o <executable> for a public C compile."}))
    (let [output-file (java.io.File. output-path)
          parent (.getParentFile output-file)]
      (when (and parent
                 (not (or (.isDirectory parent)
                          (.mkdirs parent))))
        (c-backend-fail! "C14-INPUT"
                         "C target output directory is unavailable"
                         source-path target nil
                         {:output-path output-path
                          :missing-fact :output-directory
                          :remediation "Use a writable target output directory."})))
    (let [c-source-path (str output-path ".c")
          manifest-path (str output-path ".manifest.edn")
          source-map-path (str output-path ".source-map.edn")
          provenance-path (str output-path ".provenance.edn")
          artifact (c-backend-source-artifact
                    source-path source-text
                    (cond-> {:target target
                             :dialect :c11
                             :compile? true
                             :executable-path output-path
                             :c-source-path c-source-path
                             :manifest-path manifest-path
                             :source-map-path source-map-path
                             :provenance-path provenance-path}
                      lowering-mode
                      (assoc :lowering-mode lowering-mode)))]
      (assoc artifact
             :command-boundary
             {:compile-command (cond-> ["gravity" "compile" source-path
                                        "--target" (name target)]
                                 lowering-mode
                                 (into ["--lowering" (name lowering-mode)])
                                 true
                                 (into ["-o" output-path]))
              :run-command [output-path]
              :public-command "gravity"
              :bootstrap-hosted? true
              :clojure-seed-boundary? true
              :self-hosted? false
              :seedless-release? false}
             :target-requested? true
             :target-selection :explicit
             :public-current-source? true
             :lowering-mode lowering-mode
             :lowering-requested? (some? lowering-mode))))))

(defn p18-t04-compile-js-ts-target-file!
  "Compile a current source unit to the bounded Node 20 ES2022 ESM target.

  Both public aliases are canonicalized before this boundary.  The emitted
  JavaScript, declarations, source map, package metadata, manifest, and
  provenance are validated and differentially executed before becoming
  caller-visible."
  [source-path output-path target lowering-mode]
  (let [target (js-ts-backend-canonical-target target)]
    (when-not (= js-ts-backend-target target)
      (js-ts-backend-fail!
       "B6-TARGET" "public JS/TS target is unsupported"
       source-path nil
       {:requested-target target
        :supported-targets (vec (sort js-ts-backend-target-aliases))
        :missing-fact :supported-target}))
    (when (and lowering-mode (not= :runtime-derived lowering-mode))
      (js-ts-backend-fail!
       "B6-TARGET" "requested JS/TS lowering mode is unsupported"
       source-path nil
       {:lowering-mode lowering-mode
        :supported-lowering-modes [:runtime-derived]
        :missing-fact :js-ts-lowering-mode}))
    (when-not output-path
      (js-ts-backend-fail!
       "C14-INPUT" "JS/TS target compilation requires an explicit output"
       source-path nil
       {:missing-fields [:output-path]
        :remediation "Use --target js -o <module-base>."}))
    (let [artifact
          (js-ts-backend-file-artifact
           source-path
           {:target target :output-path output-path :emit? true})]
      (assoc artifact
             :command-boundary
             {:compile-command
              (cond-> ["gravity" "compile" source-path
                       "--target" (name target)]
                lowering-mode
                (into ["--lowering" (name lowering-mode)])
                true
                (into ["-o" output-path]))
              :run-command ["node"
                            (get-in artifact
                                    [:provenance :actual-paths :outputs
                                     :javascript])]
              :public-command "gravity"
              :bootstrap-hosted? true
              :clojure-seed-boundary? true
              :self-hosted? false
              :seedless-release? false}
             :target-requested? true
             :target-selection :explicit
             :public-current-source? true
             :lowering-mode :runtime-derived
             :lowering-requested? (some? lowering-mode)
             :compiled-executable? true))))

(defn p18-t04-compile-jvm-target-file!
  "Compile a current source unit to the bounded Java 21 modular JAR target.

  This entrypoint is intentionally reachable only for the explicit
  runtime-derived lowering mode.  The historical JVM compile behavior remains
  the default seed/release compatibility route."
  [source-path output-path target lowering-mode]
  (when-not (= jvm-backend-target target)
    (jvm-backend-fail!
     "B5-TARGET" "public JVM target is unsupported"
     source-path nil
     {:requested-target target :supported-targets [:jvm]
      :missing-fact :supported-target}))
  (when-not (= :runtime-derived lowering-mode)
    (jvm-backend-fail!
     "B5-TARGET" "new JVM backend requires the runtime-derived lowering mode"
     source-path nil
     {:lowering-mode lowering-mode
      :supported-lowering-modes [:runtime-derived]
      :missing-fact :jvm-lowering-mode}))
  (when-not output-path
    (jvm-backend-fail!
     "C14-INPUT" "JVM target compilation requires an explicit output"
     source-path nil
     {:missing-fields [:output-path]
      :remediation
      "Use --target jvm --lowering runtime-derived -o <artifact-directory>."}))
  (let [artifact
        (jvm-backend-file-artifact
         source-path {:output-path output-path :emit? true})]
    (assoc artifact
           :command-boundary
           {:compile-command
            ["gravity" "compile" source-path "--target" "jvm"
             "--lowering" "runtime-derived" "-o" output-path]
            :run-command
            ["java" "-jar"
             (get-in artifact [:provenance :actual-paths :outputs :jar])]
            :public-command "gravity"
            :bootstrap-hosted? true
            :clojure-seed-boundary? true
            :self-hosted? false
            :seedless-release? false}
           :target-requested? true
           :target-selection :explicit
           :public-current-source? true
           :lowering-mode :runtime-derived
           :lowering-requested? true
           :compiled-executable? true)))

(defn p18-t04-shell
  [& args]
  (if (= "bin/gravity" (first args))
    (p18-shell-run {"GRAVITY_PACKAGED_CLI_ONLY" "1"} args)
    (p18-shell-run args)))

(defn p18-t04-read-edn-stdout
  [result]
  (when (zero? (:exit result))
    (edn/read-string (:out result))))

