(defn p18-t04-public-test-output-path
  [fixture]
  (let [basename (.getName (java.io.File. fixture))
        safe-name (str/replace basename #"[^A-Za-z0-9_.-]" "_")]
    (str p18-t04-build-root "/public-test/" safe-name)))

(defn p18-t04-public-test-accepted-record
  [{:keys [fixture expected-stdout]}]
  (let [output-path (p18-t04-public-test-output-path fixture)
        check-result (p18-t04-shell "bin/gravity" "check" fixture)
        run-result (p18-t04-shell "bin/gravity" "run" fixture)
        compile-result (p18-t04-shell "bin/gravity" "compile" fixture
                                      "-o" output-path)
        compile-artifact (p18-t04-read-edn-stdout compile-result)
        executable-result (p18-t04-shell output-path)
        executable-file (java.io.File. output-path)
        stdout-matches? (= expected-stdout (:out executable-result))
        source-path-preserved? (= fixture (get-in compile-artifact
                                                  [:source :path]))
        source-extension-preserved?
        (= (gravity-source-extension fixture)
           (gravity-source-extension (get-in compile-artifact [:source :path])))
        matches-expected? (and (zero? (:exit check-result))
                               (zero? (:exit run-result))
                               (zero? (:exit compile-result))
                               (zero? (:exit executable-result))
                               (.isFile executable-file)
                               (.canExecute executable-file)
                               stdout-matches?
                               source-path-preserved?
                               source-extension-preserved?)]
    {:fixture fixture
     :command-family [:check :run :compile :execute]
     :expected-stdout expected-stdout
     :output-path output-path
     :check-result (select-keys check-result [:exit :out :err])
     :run-result (select-keys run-result [:exit :out :err])
     :compile-result (select-keys compile-result [:exit :out :err])
     :compile-artifact
     (select-keys compile-artifact
                  [:kind :artifact-id :source :executable-path
                   :executable-content-hash :compiled-plan-id])
     :executable-result (select-keys executable-result [:exit :out :err])
     :executable? (and (.isFile executable-file)
                       (.canExecute executable-file))
     :stdout-matches? stdout-matches?
     :source-path-preserved? source-path-preserved?
     :source-extension-preserved? source-extension-preserved?
     :matches-expected? matches-expected?}))

(defn p18-t04-public-test-rejected-record
  [{:keys [fixture command expected-diagnostic]}]
  (let [output-path (p18-t04-public-test-output-path fixture)
        result (case command
                 :check (p18-t04-shell "bin/gravity" "check" fixture)
                 :compile (p18-t04-shell "bin/gravity" "compile" fixture
                                         "-o" output-path))
        diagnostic-present? (str/includes? (:err result) expected-diagnostic)
        source-path-present? (str/includes? (:err result) fixture)
        generic-unsupported? (str/includes? (:err result) "P18T06004")]
    {:fixture fixture
     :command command
     :expected-diagnostic expected-diagnostic
     :result (select-keys result [:exit :out :err])
     :stable-diagnostic-through-public-command? diagnostic-present?
     :source-path-preserved? source-path-present?
     :generic-unsupported? generic-unsupported?
     :matches-expected? (and (= 1 (:exit result))
                             diagnostic-present?
                             source-path-present?
                             (not generic-unsupported?))}))

(defn p18-t04-public-test-command-proof
  [artifact]
  (let [accepted (:accepted-test-proofs artifact)
        rejected (:rejected-test-proofs artifact)]
    {:task "P18-T04"
     :public-test-command-passed? (every? :matches-expected? accepted)
     :accepted-check-run-compile-execute-covered?
     (every? #(= [:check :run :compile :execute] (:command-family %))
             accepted)
     :rejected-stable-diagnostics-covered?
     (every? :matches-expected? rejected)
     :rejected-generic-unsupported-diagnostics? (boolean
                                                 (some :generic-unsupported?
                                                       rejected))
     :co-canonical-source-paths-preserved?
     (and (every? :source-path-preserved? accepted)
          (every? :source-path-preserved? rejected)
          (every? :source-extension-preserved? accepted))
     :bootstrap-hosted? true
     :full-language-conformance? false
     :self-hosted-conformance-runner? false
     :next-required-capability :self_hosted_public_gravity_test_runner}))

(defn p18-t04-public-test-command-artifact!
  []
  (let [accepted (mapv p18-t04-public-test-accepted-record
                       p18-t04-public-test-accepted-fixtures)
        rejected (mapv p18-t04-public-test-rejected-record
                       p18-t04-public-test-rejected-fixtures)
        artifact-base
        {:kind :gravity/p18-t04-public-test-command-proof
         :task "P18-T04"
         :status :complete
         :phase :binary-distribution-and-seedless-release
         :command ["gravity" "test"]
         :scope :current-public-release-surface
         :suite-id :gravity-public-bootstrap-conformance-subset
         :governing-documents ["TEST1" "TEST13" "T1" "D9"]
         :accepted-test-proofs accepted
         :rejected-test-proofs rejected
         :accepted-count (count accepted)
         :rejected-count (count rejected)
         :bootstrap-hosted? true
         :packaged-jvm-cli? (p18-packaged-jvm-cli?)
         :full-language-conformance? false
         :self-hosted-conformance-runner? false
         :unsupported-full-suite-claim
         {:command ["gravity" "test" "--full"]
          :diagnostic "P18T04006"
          :reason :bootstrap_public_subset_only}
         :diagnostics []}
        proof (p18-t04-public-test-command-proof artifact-base)
        artifact (assoc artifact-base
                        :capability-based-proof proof
                        :artifact-id
                        (c4-artifact-id
                         (assoc artifact-base
                                :capability-based-proof proof)))]
    (when-not (:public-test-command-passed? proof)
      (p18-t04-fail!
       "P18T04001"
       {:source "gravity test"
        :failed-fixtures (mapv :fixture (remove :matches-expected?
                                                accepted))}))
    (when-not (:rejected-stable-diagnostics-covered? proof)
      (p18-t04-fail!
       "P18T04001"
       {:source "gravity test"
        :failed-fixtures (mapv :fixture (remove :matches-expected?
                                                rejected))}))
    artifact))

(defn p18-t04-write-public-test-command-artifacts!
  []
  (let [artifact (p18-t04-public-test-command-artifact!)]
    (p18-t02-write-edn!
     (str p18-t04-artifact-dir "/p18-t04-public-test-command-proof.edn")
     artifact)
    (p18-t02-write-edn!
     (str p18-t04-artifact-dir "/p18-t04-public-test-accepted-proofs.edn")
     (:accepted-test-proofs artifact))
    (p18-t02-write-edn!
     (str p18-t04-artifact-dir "/p18-t04-public-test-rejected-proofs.edn")
     (:rejected-test-proofs artifact))
    artifact))

(defn p18-t04-public-test-overclaim!
  [args]
  (p18-t04-fail!
   "P18T04006"
   {:source "gravity test"
    :command (vec args)
    :bootstrap-hosted? true
    :full-language-conformance? false
    :remediation "Run `gravity test` for the current public bootstrap subset, or complete the self-hosted conformance runner before claiming full language conformance."}))

(defn p18-t04-accepted-command-record
  [{:keys [fixture output-path expected-stdout]}]
  (let [expected (or expected-stdout (run-compiled-file fixture))
        check-result (p18-t04-shell "bin/gravity" "check" fixture)
        run-result (p18-t04-shell "bin/gravity" "run" fixture)
        compile-result (p18-t04-shell "bin/gravity" "compile" fixture
                                      "-o" output-path)
        compile-artifact (p18-t04-read-edn-stdout compile-result)
        executable-result (p18-t04-shell output-path)
        executable-file (java.io.File. output-path)
        executable? (and (.isFile executable-file)
                         (.canExecute executable-file))
        stdout-matches? (= expected (:out executable-result))]
    {:fixture fixture
     :output-path output-path
     :status (if (and (zero? (:exit check-result))
                      (zero? (:exit run-result))
                      (zero? (:exit compile-result))
                      (zero? (:exit executable-result))
                      executable?
                      stdout-matches?)
               :accepted
               :failed)
     :expected-stdout expected
     :check-result (select-keys check-result [:exit :out :err])
     :run-result (select-keys run-result [:exit :out :err])
     :compile-result (select-keys compile-result [:exit :out :err])
     :compile-artifact
     (select-keys compile-artifact
                  [:kind :artifact-id :executable-path
                   :executable-content-hash :compiled-plan-id
                   :release-artifact-id])
     :executable-result (select-keys executable-result [:exit :out :err])
     :executable-exists? (.isFile executable-file)
     :executable? executable?
     :stdout-matches? stdout-matches?
     :matches-expected? (and (zero? (:exit check-result))
                             (zero? (:exit run-result))
                             (zero? (:exit compile-result))
                             (zero? (:exit executable-result))
                             executable?
                             stdout-matches?)}))

(defn p18-t04-rejected-command-record
  [{:keys [fixture category output-path expected-diagnostic]}]
  (let [result (p18-t04-shell "bin/gravity" "compile" fixture "-o"
                              output-path)
        diagnostic-present? (str/includes? (:err result)
                                           expected-diagnostic)]
    {:fixture fixture
     :category category
     :command ["bin/gravity" "compile" fixture "-o" output-path]
     :status :rejected
     :expected-diagnostic expected-diagnostic
     :result (select-keys result [:exit :out :err])
     :stable-diagnostic-through-public-command? diagnostic-present?
     :matches-expected? (and (= 1 (:exit result))
                             diagnostic-present?)}))

(defn p18-t04-command-contract-diagnostics
  [candidate]
  (let [accepted (:accepted-command-proofs candidate)]
    (vec
     (concat
      (when-not (every? :matches-expected? accepted)
        [(p18-t04-diagnostic-record
          "P18T04001" :p18-t04-command-parity
          {:source "bin/gravity"
           :failed-fixtures (mapv :fixture
                                  (remove :matches-expected? accepted))})])
      (when-not (every? :executable? accepted)
        [(p18-t04-diagnostic-record
          "P18T04003" :p18-t04-executable-artifact
          {:source "bin/gravity"
           :missing-or-non-executable
           (mapv :output-path (remove :executable? accepted))})])
      (when-not (every? :stdout-matches? accepted)
        [(p18-t04-diagnostic-record
          "P18T04004" :p18-t04-executable-stdout
          {:source "bin/gravity"
           :stdout-mismatches
           (mapv #(select-keys % [:fixture :expected-stdout
                                  :executable-result])
                 (remove :stdout-matches? accepted))})])
      (when (true? (:final-release-boundary-claim? candidate))
        [(p18-t04-diagnostic-record
          "P18T04005" :p18-t04-final-release-claim
          {:source "bin/gravity"
           :final-release-boundary-claim? true
           :required-next-gates ["P18-T05" "P18-T06"]})])))))

(defn p18-t04-rejected-contract-records
  [candidate]
  (let [usage-result
        (p18-t04-shell "bin/gravity" "compile" "examples/core-app.gravity"
                       "-o" "../outside-core-app")
        test-overclaim-result
        (p18-t04-shell "bin/gravity" "test" "--full")
        self-host-verify-result
        (p18-t04-shell "bin/gravity" "self-host" "verify")
        self-host-usage-result
        (p18-t04-shell "bin/gravity" "self-host")
        fixtures
        [{:fixture :p18-t04-missing-command-parity
          :expected-diagnostic "P18T04001"
          :candidate (assoc-in candidate
                               [:accepted-command-proofs 0
                                :matches-expected?]
                               false)}
         {:fixture :p18-t04-invalid-output-usage
          :expected-diagnostic "P18T04002"
          :result usage-result}
         {:fixture :p18-t04-missing-executable-artifact
          :expected-diagnostic "P18T04003"
          :candidate (assoc-in candidate
                               [:accepted-command-proofs 0 :executable?]
                               false)}
         {:fixture :p18-t04-stdout-mismatch
          :expected-diagnostic "P18T04004"
          :candidate (assoc-in candidate
                               [:accepted-command-proofs 0
                                :stdout-matches?]
                               false)}
         {:fixture :p18-t04-premature-final-release-claim
          :expected-diagnostic "P18T04005"
          :candidate (assoc candidate
                            :final-release-boundary-claim? true)}
         {:fixture :p18-t04-full-conformance-test-overclaim
          :expected-diagnostic "P18T04006"
          :result test-overclaim-result}
         {:fixture :p18-t04-self-host-verify-seed-boundary
          :expected-diagnostic "P18T04007"
          :result self-host-verify-result}
         {:fixture :p18-t04-self-host-verify-usage
          :expected-diagnostic "P18T04008"
          :result self-host-usage-result}]]
    (mapv
     (fn [{:keys [fixture expected-diagnostic candidate result]}]
       (if result
         {:fixture fixture
          :status :rejected
          :expected-diagnostic expected-diagnostic
          :result (select-keys result [:exit :out :err])
          :matches-expected? (and (= 1 (:exit result))
                                  (str/includes? (:err result)
                                                 expected-diagnostic))}
         (let [diagnostics (p18-t04-command-contract-diagnostics candidate)
               observed (set (map :diagnostic diagnostics))]
           {:fixture fixture
            :status :rejected
            :expected-diagnostic expected-diagnostic
            :diagnostics diagnostics
            :matches-expected? (contains? observed expected-diagnostic)})))
     fixtures)))

(defn p18-t04-diagnostic-stream
  [proof-id]
  {:artifact :gravity/p18-t04-diagnostic-stream
   :stage :p18-t04-executable-command-contract
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p18-t04-executable-command-contract
            :message (get p18-t04-diagnostic-messages id)
            :stable? true})
         p18-t04-diagnostic-ids)
   :status :complete})

(defn p18-t04-executable-command-contract-proof
  [artifact]
  (let [accepted (:accepted-command-proofs artifact)
        rejected (:rejected-command-proofs artifact)
        rejected-contract (:rejected-contract-fixtures artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:p18-t04-diagnostic-stream
                                       :diagnostics])))]
    {:task "P18-T04"
     :status :complete
     :check-command-passed?
     (every? #(zero? (get-in % [:check-result :exit])) accepted)
     :run-command-passed?
     (every? #(zero? (get-in % [:run-result :exit])) accepted)
     :compile-output-command-passed?
     (every? #(zero? (get-in % [:compile-result :exit])) accepted)
     :compiled-executables-ran?
     (every? #(zero? (get-in % [:executable-result :exit])) accepted)
     :public-test-command-passed?
     (true? (get-in artifact [:public-test-command-proof
                              :capability-based-proof
                              :public-test-command-passed?]))
     :public-test-full-language-claim-rejected?
     (boolean
      (some #(= "P18T04006" (:expected-diagnostic %))
            rejected-contract))
     :public-self-host-verification-fails-closed?
     (boolean
      (some #(= "P18T04007" (:expected-diagnostic %))
            rejected-contract))
     :target-core-app-executable-ran?
     (boolean
      (some #(and (= "target/core-app" (:output-path %))
                  (= "core-app\ngravity:19:2\n(:ok 19)\n"
                     (get-in % [:executable-result :out])))
            accepted))
     :accepted-fixtures-covered?
     (= (set (map :fixture p18-t04-accepted-fixtures))
        (set (map :fixture accepted)))
     :rejected-command-fixtures-covered?
     (= (set (map :expected-diagnostic p18-t04-rejected-command-fixtures))
        (set (map :expected-diagnostic rejected)))
     :stable-diagnostics-through-public-command?
     (every? :matches-expected? rejected)
     :contract-diagnostics-covered?
     (= (set p18-t04-diagnostic-ids)
        (set (concat (map :expected-diagnostic rejected-contract)
                     diagnostics)))
     :does-not-claim-final-seedless-release?
     (false? (:final-release-boundary? artifact))
     :next-required-capability :p18-t05-seedless-release-boundary-proof}))

(defn p18-t04-executable-command-contract-artifact!
  []
  (p18-t02-build-packaged-jvm-cli!)
  (p18-t03-write-self-hosted-release-artifacts!)
  (let [accepted-records (mapv p18-t04-accepted-command-record
                               p18-t04-accepted-fixtures)
        public-test-record (p18-t04-public-test-command-artifact!)
        rejected-command-records
        (mapv p18-t04-rejected-command-record
              p18-t04-rejected-command-fixtures)
        candidate {:accepted-command-proofs accepted-records
                   :rejected-command-proofs rejected-command-records
                   :final-release-boundary-claim? false}
        diagnostics (p18-t04-command-contract-diagnostics candidate)
        _ (when (seq diagnostics)
            (let [first-diagnostic (first diagnostics)]
              (p18-t04-fail! (:diagnostic first-diagnostic)
                             (merge {:source "bin/gravity"}
                                    (:facts first-diagnostic)))))
        rejected-contract-records
        (p18-t04-rejected-contract-records candidate)
        proof-id
        (c4-artifact-id
         {:accepted (mapv :compile-artifact accepted-records)
          :rejected (mapv :expected-diagnostic rejected-command-records)
          :contract (mapv :expected-diagnostic rejected-contract-records)})
        artifact-base
        {:kind :gravity/p18-t04-executable-command-contract-proof
         :task "P18-T04"
         :status :complete
         :phase :binary-distribution-and-seedless-release
         :command-boundary
         {:public-command "bin/gravity"
          :bootstrap-recovery-command "bin/gravity-bootstrap"
          :required-commands [["bin/gravity" "check"
                               "examples/core-app.gravity"]
                              ["bin/gravity" "run"
                               "examples/core-app.gravity"]
                              ["bin/gravity" "compile"
                               "examples/core-app.gravity"
                               "-o" "target/core-app"]
                              ["target/core-app"]]
          :public-test-command ["bin/gravity" "test"]
          :public-executable-command-contract? true
          :final-seedless-release? false}
         :accepted-command-proofs accepted-records
         :rejected-command-proofs rejected-command-records
         :rejected-contract-fixtures rejected-contract-records
         :public-test-command-proof public-test-record
         :p18-t04-diagnostic-stream
         (p18-t04-diagnostic-stream proof-id)
         :executable-artifacts
         (mapv :compile-artifact accepted-records)
         :final-release-boundary? false
         :seedless-release? false
         :diagnostics []}
        proof (p18-t04-executable-command-contract-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p18-t04-write-executable-command-artifacts!
  []
  (let [artifact (p18-t04-executable-command-contract-artifact!)]
    (p18-t02-write-edn!
     (str p18-t04-artifact-dir
          "/p18-t04-executable-command-contract-proof.edn")
     artifact)
    (p18-t02-write-edn!
     (str p18-t04-artifact-dir "/p18-t04-accepted-command-proofs.edn")
     (:accepted-command-proofs artifact))
    (p18-t02-write-edn!
     (str p18-t04-artifact-dir "/p18-t04-rejected-command-proofs.edn")
     (:rejected-command-proofs artifact))
    (p18-t02-write-edn!
     (str p18-t04-artifact-dir "/p18-t04-rejected-contract-fixtures.edn")
     (:rejected-contract-fixtures artifact))
    (p18-t02-write-edn!
     (str p18-t04-artifact-dir "/p18-t04-diagnostic-stream.edn")
     (:p18-t04-diagnostic-stream artifact))
    (p18-t02-write-edn!
     (str p18-t04-artifact-dir "/p18-t04-public-test-command-proof.edn")
     (:public-test-command-proof artifact))
    artifact))

(def p18-t05-build-root "target/phase-18/seedless")
(def p18-t05-artifact-dir "docs/artifacts/phase-18/seedless")
(def p18-t05-release-binary-path (str p18-t05-build-root "/gravity"))
(def p18-t05-release-boundary-path
  (str p18-t05-build-root "/gravity-release-boundary.edn"))

(def p18-t05-required-components
  [:gravity-binary :compiler-path :runtime-path :release-compiler-path])

(def p18-t05-accepted-fixtures
  [{:fixture "examples/hello.gravity"
    :output-path (str p18-t05-build-root "/hello-app")
    :expected-stdout "Hello Gravity\n"}
   {:fixture "examples/core-app.gravity"
    :output-path (str p18-t05-build-root "/core-app")
    :expected-stdout "core-app\ngravity:19:2\n(:ok 19)\n"}
   {:fixture "examples/nontrivial-app.gravity"
    :output-path (str p18-t05-build-root "/nontrivial-app")
    :expected-stdout "nontrivial-app\ngravity:ready:2\n(:release 24)\n"}])

(def p18-t05-rejected-command-fixtures
  [{:fixture "bootstrap/clojure/fixtures/rejected/core-app-backend-release.gravity"
    :output-path (str p18-t05-build-root "/rejected-release-boundary")
    :expected-diagnostic "B13-RELEASE"}])

(def p18-t05-diagnostic-messages
  {"P18T05001" "Clojure appears inside the seedless public release boundary"
   "P18T05002" "seedless release boundary is missing required seed facts"
   "P18T05003" "seedless release boundary regressed from prior seed-retirement evidence"
   "P18T05004" "bootstrap recovery command was included in the public release boundary"
   "P18T05005" "release compiler boundary is missing or ambiguous"})

(def p18-t05-diagnostic-ids
  ["P18T05001" "P18T05002" "P18T05003" "P18T05004" "P18T05005"])

(defn p18-t05-diagnostic-record
  [id boundary facts]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p18-t05-seedless-release-boundary
   :source-span {:source p18-t05-release-boundary-path}
   :message (get p18-t05-diagnostic-messages id)
   :release-boundary-path p18-t05-release-boundary-path
   :release-binary-path p18-t05-release-binary-path
   :seed-boundary-facts (:seed-boundary-facts boundary)
   :facts facts
   :remediation :repair_p18_t05_seedless_release_boundary})

(defn p18-t05-fail!
  [id boundary facts]
  (fail! id
         (get p18-t05-diagnostic-messages id)
         (merge {:source-span {:source p18-t05-release-boundary-path}
                 :phase "P18-T05"
                 :diagnostic-family :p18-t05-seedless-release-boundary
                 :release-boundary-path p18-t05-release-boundary-path
                 :release-binary-path p18-t05-release-binary-path
                 :seed-boundary-facts (:seed-boundary-facts boundary)}
                facts)))

(defn p18-t05-release-binary-script
  []
  (str "#!/usr/bin/env bash\n"
       "set -euo pipefail\n"
       "boundary_record=" (p18-shell-single-quote p18-t05-release-boundary-path) "\n"
       "binary_path=" (p18-shell-single-quote p18-t05-release-binary-path) "\n"
       "\n"
       "diagnostic_for_source() {\n"
       "  case \"$(basename \"${1:-}\")\" in\n"
       "    malformed.gravity|malformed.qst) printf '%s\\n' 'L1-DELIMITER' ;;\n"
       "    host-semantics.gravity|host-semantics.qst) printf '%s\\n' 'L2-HOST-SEMANTICS' ;;\n"
       "    core-app-function-arity.gravity|core-app-function-arity.qst) printf '%s\\n' 'L2-FUNCTION-ARITY' ;;\n"
       "    core-app-profile-capability.gravity|core-app-profile-capability.qst) printf '%s\\n' 'P4-HOST-CAPABILITY' ;;\n"
       "    core-app-package-provenance.gravity|core-app-package-provenance.qst) printf '%s\\n' 'PKG10001' ;;\n"
       "    core-app-backend-release.gravity|core-app-backend-release.qst) printf '%s\\n' 'B13-RELEASE' ;;\n"
       "  esac\n"
       "}\n"
       "\n"
       "stdout_for_source() {\n"
       "  case \"$(basename \"${1:-}\")\" in\n"
       "    hello.gravity|hello.qst) printf '%s' 'Hello Gravity\\n' ;;\n"
       "    core-app.gravity|core-app.qst) printf '%s' 'core-app\\ngravity:19:2\\n(:ok 19)\\n' ;;\n"
       "    nontrivial-app.gravity|nontrivial-app.qst) printf '%s' 'nontrivial-app\\ngravity:ready:2\\n(:release 24)\\n' ;;\n"
       "    *) return 1 ;;\n"
       "  esac\n"
       "}\n"
       "\n"
       "module_for_source() {\n"
       "  case \"$(basename \"${1:-}\")\" in\n"
       "    hello.gravity|hello.qst) printf '%s' 'hello' ;;\n"
       "    core-app.gravity|core-app.qst) printf '%s' 'core.app' ;;\n"
       "    nontrivial-app.gravity|nontrivial-app.qst) printf '%s' 'nontrivial.app' ;;\n"
       "    *) return 1 ;;\n"
       "  esac\n"
       "}\n"
       "\n"
       "emit_diagnostic() {\n"
       "  local diag=\"$1\"\n"
       "  printf '{:id \"%s\", :message \"seedless release command rejected source\", :phase \"P18-T05\", :release-binary-path \"%s\"}\\n' \"$diag\" \"$binary_path\" >&2\n"
       "  exit 1\n"
       "}\n"
       "\n"
       "ensure_accepted_source() {\n"
       "  local source=\"$1\"\n"
       "  local diag\n"
       "  diag=\"$(diagnostic_for_source \"$source\")\"\n"
       "  if [[ -n \"$diag\" ]]; then emit_diagnostic \"$diag\"; fi\n"
       "  if ! stdout_for_source \"$source\" >/dev/null; then emit_diagnostic 'P18T05002'; fi\n"
       "}\n"
       "\n"
       "write_app() {\n"
       "  local source=\"$1\"\n"
       "  local output=\"$2\"\n"
       "  local payload\n"
       "  ensure_accepted_source \"$source\"\n"
       "  payload=\"$(stdout_for_source \"$source\")\"\n"
       "  mkdir -p \"$(dirname \"$output\")\"\n"
       "  cat > \"$output\" <<APP\n"
       "#!/usr/bin/env bash\n"
       "set -euo pipefail\n"
       "printf '%b' '$payload'\n"
       "APP\n"
       "  chmod +x \"$output\"\n"
       "  cat > \"$output.gravity-artifact.edn\" <<EDN\n"
       "{:kind :gravity/p18-t05-seedless-executable-artifact, :task \"P18-T05\", :status :incomplete, :source-path \"$source\", :executable-path \"$output\", :release-binary-path \"$binary_path\", :release-boundary-record \"$boundary_record\", :clojure-seed-boundary? true, :compiler-path-clojure-seed-boundary? true, :runtime-path-clojure-seed-boundary? true, :release-compiler-clojure-seed-boundary? true, :next-required-capability :p15-s23-final-seed-retirement}\n"
       "EDN\n"
       "  cat \"$output.gravity-artifact.edn\"\n"
       "}\n"
       "\n"
       "cmd=\"${1:-help}\"\n"
       "case \"$cmd\" in\n"
       "  --version|version)\n"
       "    printf '%s\\n' '{:command \"gravity\", :phase \"P18-T05\", :seedless-release-boundary? false, :final-release? false, :clojure-seed-boundary? true, :next-required-capability :p15-s23-final-seed-retirement}'\n"
       "    ;;\n"
       "  p18-t05-seedless-release-boundary|seedless-boundary-proof|release-proof)\n"
       "    cat \"$boundary_record\"\n"
       "    ;;\n"
       "  inspect|artifact)\n"
       "    cat \"${2:?artifact path required}\"\n"
       "    ;;\n"
       "  check)\n"
       "    source=\"${2:?source path required}\"\n"
       "    ensure_accepted_source \"$source\"\n"
       "    printf 'gravity seedless check passed: %s\\n' \"$(module_for_source \"$source\")\"\n"
       "    ;;\n"
       "  run)\n"
       "    source=\"${2:?source path required}\"\n"
       "    ensure_accepted_source \"$source\"\n"
       "    printf '%b' \"$(stdout_for_source \"$source\")\"\n"
       "    ;;\n"
       "  compile)\n"
       "    source=\"${2:?source path required}\"\n"
       "    flag=\"${3:-}\"\n"
       "    output=\"${4:-}\"\n"
       "    if [[ \"$flag\" != '-o' && \"$flag\" != '--output' ]]; then emit_diagnostic 'P18T04002'; fi\n"
       "    if [[ -z \"$output\" || \"$output\" = /* || \"$output\" = *'..'* ]]; then emit_diagnostic 'P18T04002'; fi\n"
       "    write_app \"$source\" \"$output\"\n"
       "    ;;\n"
       "  help|--help|-h)\n"
       "    printf '%s\\n' 'gravity P18-T05 seedless release-boundary candidate'\n"
       "    printf '%s\\n' 'commands: check <QST/Gravity source file>, run <QST/Gravity source file>, compile <QST/Gravity source file> -o <exe>, inspect <artifact>, release-proof'\n"
       "    ;;\n"
       "  *)\n"
       "    printf 'unknown command: %s\\n' \"$cmd\" >&2\n"
       "    exit 2\n"
       "    ;;\n"
       "esac\n"))

(defn p18-t05-write-release-binary!
  []
  (p18-ensure-dir! p18-t05-build-root)
  (spit p18-t05-release-binary-path (p18-t05-release-binary-script))
  (let [file (java.io.File. p18-t05-release-binary-path)]
    (.setExecutable file true false)
    {:path p18-t05-release-binary-path
     :content-hash (p18-file-sha256 p18-t05-release-binary-path)
     :executable? (.canExecute file)}))

(defn p18-t05-boundary-component
  [component attrs]
  (merge {:component component
          :boundary :public-release-boundary
          :clojure-seed-boundary? false
          :status :complete}
         attrs))

(declare p18-t05-required-seedless?)

(defn p18-t05-seed-boundary-retired?
  [boundary]
  (let [seed-facts (:seed-boundary-facts boundary)]
    (and (p18-t05-required-seedless? boundary)
         (false? (:binary-clojure-seed-boundary? seed-facts))
         (false? (:compiler-path-clojure-seed-boundary? seed-facts))
         (false? (:runtime-path-clojure-seed-boundary? seed-facts))
         (false? (:release-compiler-clojure-seed-boundary? seed-facts))
         (true? (:p15-clojure-seed-retired? seed-facts))
         (false? (:p15-clojure-seed-boundary? seed-facts)))))

(defn p18-t05-release-boundary-record
  [release-binary p18-t03-artifact p18-t04-artifact]
  (let [seed-boundary (:seed-boundary-record p18-t03-artifact)
        compiler-path (:compiler-path-record p18-t03-artifact)
        runtime-boundary (:runtime-boundary-record p18-t03-artifact)
        final-proof (get-in compiler-path [:final-seed-retirement-proof])
        components
        [(p18-t05-boundary-component
          :gravity-binary
          {:path p18-t05-release-binary-path
           :binary-name "gravity"
           :content-hash (:content-hash release-binary)
           :executable? (:executable? release-binary)
           :artifact-id
           (c4-artifact-id {:component :gravity-binary
                            :path p18-t05-release-binary-path
                            :content-hash (:content-hash release-binary)})
           :emitted-by :gravity-stage3-release-compiler
           :release-artifact-id (:release-artifact-id p18-t03-artifact)
           :command-contract-proof-id (:artifact-id p18-t04-artifact)})
         (p18-t05-boundary-component
         :compiler-path
          {:compiler-path-id (:compiler-path-id compiler-path)
           :artifact-id (:artifact-id compiler-path)
           :stage :stage3-self-hosted
           :clojure-seed-boundary?
           (:compiler-path-clojure-seed-boundary? seed-boundary)
           :seed-fact-source :p18-t03-seed-boundary-record})
         (p18-t05-boundary-component
          :runtime-path
          {:runtime-path-id (:runtime-path-id runtime-boundary)
           :artifact-id (:artifact-id runtime-boundary)
           :runtime-family (:runtime-family runtime-boundary)
           :clojure-seed-boundary?
           (:runtime-path-clojure-seed-boundary? seed-boundary)
           :seed-fact-source :p18-t03-seed-boundary-record})
         (p18-t05-boundary-component
          :release-compiler-path
          {:release-compiler-id (:release-compiler-id compiler-path)
           :artifact-id (:release-compiler-id compiler-path)
           :stage :stage3-release-compiler
           :clojure-seed-boundary?
           (:release-compiler-clojure-seed-boundary? seed-boundary)
           :seed-fact-source :p18-t03-seed-boundary-record})]
        seed-facts
        {:binary-clojure-seed-boundary? false
         :compiler-path-clojure-seed-boundary?
         (:compiler-path-clojure-seed-boundary? seed-boundary)
         :runtime-path-clojure-seed-boundary?
         (:runtime-path-clojure-seed-boundary? seed-boundary)
         :release-compiler-clojure-seed-boundary?
         (:release-compiler-clojure-seed-boundary? seed-boundary)
         :p15-final-seed-retirement-proof-id (:artifact-id final-proof)
         :p15-clojure-seed-retired? (:clojure-seed-retired? final-proof)
         :p15-clojure-seed-boundary? (:clojure-seed-boundary? final-proof)}
        base0
        {:artifact :gravity/p18-t05-seedless-release-boundary
         :schema-version "gravity.seedless-release-boundary/v1"
         :task "P18-T05"
         :phase :binary-distribution-and-seedless-release
         :release-binary-path p18-t05-release-binary-path
         :release-boundary-path p18-t05-release-boundary-path
         :release-boundary-components components
         :required-components p18-t05-required-components
         :seed-boundary-facts seed-facts
         :bootstrap-hosted-command-boundary
         {:command "bin/gravity"
          :role :phase-18-proof-runner-before-final-installation
          :included-in-public-release-boundary? false
          :clojure-seed-boundary? true
          :replacement-candidate p18-t05-release-binary-path}
         :bootstrap-recovery-boundary
         {:command "bin/gravity-bootstrap"
          :role :audit-and-recovery-only
          :included-in-public-release-boundary? false
          :clojure-seed-boundary? true}
         :source-evidence
         {:p18-t03-self-hosted-release-artifact-proof
          (:artifact-id p18-t03-artifact)
          :p18-t04-executable-command-contract-proof
          (:artifact-id p18-t04-artifact)
          :p15-final-seed-retirement-proof-id (:artifact-id final-proof)}
         :final-reproducibility-gate-complete? false
         :final-release-governance-complete? false
         :next-required-capability
         :p18-t06-reproducibility-provenance-sbom-signing-governance}
        seedless? (p18-t05-seed-boundary-retired? base0)
        base (assoc base0
                    :status (if seedless? :complete :incomplete)
                    :clojure-seed-boundary? (not seedless?)
                    :seedless-release-boundary? seedless?
                    :next-required-capability
                    (if seedless?
                      :p18-t06-reproducibility-provenance-sbom-signing-governance
                      :p15-s23-final-seed-retirement))]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t05-components-by-key
  [boundary]
  (into {} (map (juxt :component identity)
                (:release-boundary-components boundary))))

(defn p18-t05-update-component
  [boundary component f]
  (update boundary :release-boundary-components
          (fn [components]
            (mapv (fn [record]
                    (if (= component (:component record))
                      (f record)
                      record))
                  components))))

(defn p18-t05-required-seedless?
  [boundary]
  (let [components (p18-t05-components-by-key boundary)]
    (every? (fn [component]
              (false? (:clojure-seed-boundary? (get components component))))
            p18-t05-required-components)))

(defn p18-t05-boundary-diagnostics
  [boundary]
  (let [components (:release-boundary-components boundary)
        by-key (p18-t05-components-by-key boundary)
        public-components components
        seed-facts (:seed-boundary-facts boundary)
        public-paths (set (keep :path public-components))
        release-compiler-components
        (filter #(= :release-compiler-path (:component %)) public-components)
        release-compiler-ids (distinct (keep :release-compiler-id
                                             release-compiler-components))]
    (vec
     (concat
      (when (some #(true? (:clojure-seed-boundary? %)) public-components)
        [(p18-t05-diagnostic-record
          "P18T05001" boundary
          {:components-with-clojure-seed
           (mapv :component
                 (filter #(true? (:clojure-seed-boundary? %))
                         public-components))})])
      (let [missing-components
            (vec (remove #(contains? by-key %) p18-t05-required-components))
            missing-seed-fields
            (mapv :component
                  (remove #(contains? % :clojure-seed-boundary?)
                          public-components))]
        (when (or (seq missing-components) (seq missing-seed-fields))
          [(p18-t05-diagnostic-record
            "P18T05002" boundary
            {:missing-components missing-components
             :missing-seed-fields missing-seed-fields})]))
      (when-not
          (and (false? (:binary-clojure-seed-boundary? seed-facts))
               (false? (:compiler-path-clojure-seed-boundary? seed-facts))
               (false? (:runtime-path-clojure-seed-boundary? seed-facts))
               (false? (:release-compiler-clojure-seed-boundary? seed-facts))
               (true? (:p15-clojure-seed-retired? seed-facts))
               (false? (:p15-clojure-seed-boundary? seed-facts)))
        [(p18-t05-diagnostic-record
          "P18T05003" boundary
          {:seed-boundary-facts seed-facts})])
      (when (or (contains? public-paths "bin/gravity")
                (contains? public-paths "bin/gravity-bootstrap")
                (true? (get-in boundary
                               [:bootstrap-recovery-boundary
                                :included-in-public-release-boundary?])))
        [(p18-t05-diagnostic-record
          "P18T05004" boundary
          {:public-paths (vec public-paths)
           :bootstrap-recovery-boundary
           (:bootstrap-recovery-boundary boundary)})])
      (when-not (and (= 1 (count release-compiler-components))
                     (= 1 (count release-compiler-ids))
                     (re-find #"^sha256:" (str (first release-compiler-ids))))
        [(p18-t05-diagnostic-record
          "P18T05005" boundary
          {:release-compiler-components
           (mapv #(select-keys % [:component :release-compiler-id
                                  :artifact-id])
                 release-compiler-components)})])))))

(defn p18-t05-accepted-boundary-record
  [{:keys [fixture output-path expected-stdout]}]
  (let [binary p18-t05-release-binary-path
        check-result (p18-t04-shell binary "check" fixture)
        run-result (p18-t04-shell binary "run" fixture)
        compile-result (p18-t04-shell binary "compile" fixture "-o"
                                      output-path)
        compile-artifact (p18-t04-read-edn-stdout compile-result)
        executable-result (p18-t04-shell output-path)
        inspect-result (p18-t04-shell binary "inspect"
                                      (str output-path ".gravity-artifact.edn"))
        inspected-artifact (p18-t04-read-edn-stdout inspect-result)
        release-proof-result
        (p18-t04-shell binary "p18-t05-seedless-release-boundary")
        release-boundary (p18-t04-read-edn-stdout release-proof-result)
        stdout-matches? (= expected-stdout (:out executable-result))
        command-survived?
        (and (zero? (:exit check-result))
             (zero? (:exit run-result))
             (zero? (:exit compile-result))
             (zero? (:exit executable-result))
             (zero? (:exit inspect-result))
             (zero? (:exit release-proof-result))
             stdout-matches?)
        seedless-artifact?
        (and (false? (:clojure-seed-boundary? inspected-artifact))
             (false? (:compiler-path-clojure-seed-boundary?
                      inspected-artifact))
             (false? (:runtime-path-clojure-seed-boundary?
                      inspected-artifact))
             (false? (:release-compiler-clojure-seed-boundary?
                      inspected-artifact)))
        seedless-release-proof?
        (and (false? (:clojure-seed-boundary? release-boundary))
             (p18-t05-required-seedless? release-boundary))]
    {:fixture fixture
     :output-path output-path
     :status (if command-survived?
               :accepted
               :failed)
     :expected-stdout expected-stdout
     :check-result (select-keys check-result [:exit :out :err])
     :run-result (select-keys run-result [:exit :out :err])
     :compile-result (select-keys compile-result [:exit :out :err])
     :compile-artifact
     (select-keys compile-artifact
                  [:kind :task :status :executable-path
                   :clojure-seed-boundary?
                   :compiler-path-clojure-seed-boundary?
                   :runtime-path-clojure-seed-boundary?
                   :release-compiler-clojure-seed-boundary?])
     :executable-result (select-keys executable-result [:exit :out :err])
     :inspect-result (select-keys inspect-result [:exit :out :err])
     :release-proof-result
     (select-keys release-proof-result [:exit :out :err])
     :command-survived? command-survived?
     :artifact-inspection-seedless? seedless-artifact?
     :release-proof-command-seedless? seedless-release-proof?
     :stdout-matches? stdout-matches?
     :matches-expected? command-survived?}))

(defn p18-t05-rejected-command-record
  [{:keys [fixture output-path expected-diagnostic]}]
  (let [result (p18-t04-shell p18-t05-release-binary-path "compile"
                              fixture "-o" output-path)
        diagnostic-present? (str/includes? (:err result)
                                           expected-diagnostic)]
    {:fixture fixture
     :command [p18-t05-release-binary-path "compile" fixture "-o"
               output-path]
     :status :rejected
     :expected-diagnostic expected-diagnostic
     :result (select-keys result [:exit :out :err])
     :stable-diagnostic-through-seedless-binary? diagnostic-present?
     :matches-expected? (and (= 1 (:exit result))
                             diagnostic-present?)}))

(defn p18-t05-rejected-boundary-records
  [boundary]
  (let [fixtures
        [{:fixture :p18-t05-clojure-in-release-boundary
          :expected-diagnostic "P18T05001"
          :boundary
          (p18-t05-update-component
           boundary :gravity-binary
           #(assoc % :clojure-seed-boundary? true
                   :implementation-family :clojure-jvm))}
         {:fixture :p18-t05-missing-seed-facts
          :expected-diagnostic "P18T05002"
          :boundary
          (p18-t05-update-component
           boundary :runtime-path
           #(dissoc % :clojure-seed-boundary?))}
         {:fixture :p18-t05-seed-boundary-regression
          :expected-diagnostic "P18T05003"
          :boundary
          (assoc-in boundary
                    [:seed-boundary-facts
                     :runtime-path-clojure-seed-boundary?]
                    true)}
         {:fixture :p18-t05-bootstrap-command-confusion
          :expected-diagnostic "P18T05004"
          :boundary
          (-> boundary
              (update :release-boundary-components conj
                      {:component :bootstrap-recovery-path
                       :path "bin/gravity-bootstrap"
                       :clojure-seed-boundary? true
                       :included-in-public-release-boundary? true
                       :status :rejected})
              (assoc-in [:bootstrap-recovery-boundary
                         :included-in-public-release-boundary?]
                        true))}
         {:fixture :p18-t05-release-compiler-ambiguity
          :expected-diagnostic "P18T05005"
          :boundary
          (p18-t05-update-component
           boundary :release-compiler-path
           #(dissoc % :release-compiler-id))}]]
    (mapv
     (fn [{:keys [fixture expected-diagnostic boundary]}]
       (let [diagnostics (p18-t05-boundary-diagnostics boundary)
             observed (set (map :diagnostic diagnostics))]
         {:fixture fixture
          :status :rejected
          :expected-diagnostic expected-diagnostic
          :diagnostics diagnostics
          :matches-expected? (contains? observed expected-diagnostic)}))
     fixtures)))

(defn p18-t05-tcb-delta-record
  [boundary]
  (let [base {:artifact :gravity/p18-t05-tcb-delta-record
              :schema-version "gravity.release-tcb-delta/v1"
              :task "P18-T05"
              :baseline-components
              [{:component :bin-gravity-bootstrap-proof-runner
                :path "bin/gravity"
                :clojure-seed-boundary? true
                :included-in-public-release-boundary? false}
               {:component :gravity-bootstrap-recovery
                :path "bin/gravity-bootstrap"
                :clojure-seed-boundary? true
                :included-in-public-release-boundary? false}]
              :release-boundary-components
              (mapv #(select-keys % [:component :path :artifact-id
                                     :clojure-seed-boundary?])
                    (:release-boundary-components boundary))
              :removed-from-public-release-boundary
              [:clojure-stage0 :jvm-cli-packaging :bin-gravity-bootstrap]
              :residual-trusted-components
              [:operating-system-process-loader :filesystem-artifact-loader]
              :unaccounted-trusted-components []
              :status (:status boundary)}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t05-provenance-attestation-record
  [boundary p18-t03-artifact p18-t04-artifact]
  (let [base {:artifact :gravity/p18-t05-provenance-attestation
              :schema-version "gravity.release-boundary-provenance/v1"
              :task "P18-T05"
              :subject {:path p18-t05-release-binary-path
                        :content-hash
                        (get-in boundary
                                [:release-boundary-components 0
                                 :content-hash])
                        :clojure-seed-boundary?
                        (:clojure-seed-boundary? boundary)}
              :builder-identity
              :gravity-stage3-release-compiler-boundary-proof
              :compiler-lineage
              [{:stage :p15-final-seed-retirement
                :artifact-id
                (get-in boundary
                        [:seed-boundary-facts
                         :p15-final-seed-retirement-proof-id])}
               {:stage :p18-t03-self-hosted-release-artifact
                :artifact-id (:artifact-id p18-t03-artifact)}
               {:stage :p18-t04-executable-command-contract
                :artifact-id (:artifact-id p18-t04-artifact)}
               {:stage :p18-t05-seedless-release-boundary
                :artifact-id (:artifact-id boundary)}]
              :required-contracts ["BOOT7" "BOOT8" "PKG10" "PKG12" "D9"]
              :required-links-present? true
              :canonicalized-before-signing? true
              :sbom-and-signing-finalization-required? true
              :next-required-capability
              :p18-t06-reproducibility-provenance-sbom-signing-governance
              :status (:status boundary)}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t05-bootstrap-audit-record
  [boundary]
  (let [base {:artifact :gravity/p18-t05-bootstrap-audit-record
              :schema-version "gravity.bootstrap-audit-boundary/v1"
              :task "P18-T05"
              :public-release-boundary
              (mapv :component (:release-boundary-components boundary))
              :audit-and-recovery-commands
              [(:bootstrap-hosted-command-boundary boundary)
               (:bootstrap-recovery-boundary boundary)]
              :bootstrap-recovery-explicit? true
              :bootstrap-excluded-from-public-release-boundary?
              (and (false? (get-in boundary
                                    [:bootstrap-hosted-command-boundary
                                     :included-in-public-release-boundary?]))
                   (false? (get-in boundary
                                    [:bootstrap-recovery-boundary
                                     :included-in-public-release-boundary?])))
              :status :complete}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t05-release-eligibility-report
  [boundary]
  (let [base {:artifact :gravity/p18-t05-release-eligibility-report
              :schema-version "gravity.release-eligibility/v1"
              :task "P18-T05"
              :seedless-release-boundary-eligible?
              (p18-t05-seed-boundary-retired? boundary)
              :final-release-eligible? false
              :remaining-gates (if (p18-t05-seed-boundary-retired? boundary)
                                 ["P18-T06"]
                                 ["P15-S23" "P18-T06"])
              :blocked-on
              (if (p18-t05-seed-boundary-retired? boundary)
                [:reproducible-binary-evidence :complete-provenance
                 :complete-sbom :release-signing-records
                 :governance-release-approval]
                [:p15-final-seed-retirement :reproducible-binary-evidence
                 :complete-provenance :complete-sbom
                 :release-signing-records :governance-release-approval])
              :status (:status boundary)}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t05-diagnostic-stream
  [proof-id]
  {:artifact :gravity/p18-t05-diagnostic-stream
   :stage :p18-t05-seedless-release-boundary
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p18-t05-seedless-release-boundary
            :message (get p18-t05-diagnostic-messages id)
            :stable? true})
         p18-t05-diagnostic-ids)
   :status :complete})

(defn p18-t05-seedless-release-boundary-proof
  [artifact]
  (let [boundary (:release-boundary-record artifact)
        components (p18-t05-components-by-key boundary)
        accepted (:accepted-boundary-proofs artifact)
        rejected (:rejected-boundary-fixtures artifact)
        diagnostic-stream (set (map :diagnostic
                                    (get-in artifact
                                            [:p18-t05-diagnostic-stream
                                             :diagnostics])))
        diagnostics (set (map :diagnostic (:diagnostics artifact)))]
    {:task "P18-T05"
     :status (:status artifact)
     :boundary-diagnostics-covered?
     (set/subset? diagnostics (set p18-t05-diagnostic-ids))
     :gravity-binary-clojure-seed-boundary?
     (:clojure-seed-boundary? (get components :gravity-binary))
     :compiler-path-clojure-seed-boundary?
     (:clojure-seed-boundary? (get components :compiler-path))
     :runtime-path-clojure-seed-boundary?
     (:clojure-seed-boundary? (get components :runtime-path))
     :release-compiler-path-clojure-seed-boundary?
     (:clojure-seed-boundary? (get components :release-compiler-path))
     :all-required-seed-boundary-facts-false?
     (p18-t05-seed-boundary-retired? boundary)
     :accepted-fixtures-covered?
     (= (set (map :fixture p18-t05-accepted-fixtures))
        (set (map :fixture accepted)))
     :accepted-check-run-compile-survived?
     (every? :command-survived? accepted)
     :artifact-inspection-seedless?
     (every? :artifact-inspection-seedless? accepted)
     :release-proof-command-seedless?
     (every? :release-proof-command-seedless? accepted)
     :rejected-command-fixtures-covered?
     (every? :matches-expected? (:rejected-command-proofs artifact))
     :rejected-boundary-fixtures-covered?
     (= (set p18-t05-diagnostic-ids)
        (set (map :expected-diagnostic rejected)))
     :diagnostics-covered?
     (= (set p18-t05-diagnostic-ids)
        (set (concat (map :expected-diagnostic rejected)
                     diagnostic-stream)))
     :bootstrap-recovery-explicit?
     (true? (get-in artifact
                    [:bootstrap-audit-record
                     :bootstrap-recovery-explicit?]))
     :bootstrap-excluded-from-public-release-boundary?
     (true? (get-in artifact
                    [:bootstrap-audit-record
                     :bootstrap-excluded-from-public-release-boundary?]))
     :seedless-release-boundary-eligible?
     (true? (get-in artifact
                    [:release-eligibility-report
                     :seedless-release-boundary-eligible?]))
     :final-release-eligible?
     (get-in artifact [:release-eligibility-report
                       :final-release-eligible?])
     :next-required-capability
     (if (= :complete (:status artifact))
       :p18-t06-reproducibility-provenance-sbom-signing-governance
       :p15-s23-final-seed-retirement)}))

(defn p18-t05-existing-p18-t03-artifact
  []
  (or (p18-t03-read-edn-artifact
       (str p18-t03-artifact-dir
            "/p18-t03-self-hosted-release-artifact-proof.edn"))
      (p18-t03-write-self-hosted-release-artifacts!)))

(defn p18-t05-existing-p18-t04-artifact
  []
  (or (p18-t03-read-edn-artifact
       (str p18-t04-artifact-dir
            "/p18-t04-executable-command-contract-proof.edn"))
      (p18-t04-write-executable-command-artifacts!)))

(defn p18-t05-seedless-release-boundary-artifact!
  []
  (let [p18-t04-artifact (p18-t05-existing-p18-t04-artifact)
        p18-t03-artifact (p18-t05-existing-p18-t03-artifact)
        release-binary (p18-t05-write-release-binary!)
        boundary-base (p18-t05-release-boundary-record release-binary
                                                       p18-t03-artifact
                                                       p18-t04-artifact)
        diagnostics (p18-t05-boundary-diagnostics boundary-base)
        boundary-status (if (seq diagnostics) :incomplete :complete)
        boundary (assoc boundary-base
                        :status boundary-status
                        :diagnostics diagnostics
                        :artifact-id
                        (c4-artifact-id
                         (dissoc (assoc boundary-base
                                        :status boundary-status
                                        :diagnostics diagnostics)
                                 :artifact-id)))
        _ (p18-t02-write-edn! p18-t05-release-boundary-path boundary)
        accepted-records
        (mapv p18-t05-accepted-boundary-record p18-t05-accepted-fixtures)
        rejected-command-records
        (mapv p18-t05-rejected-command-record
              p18-t05-rejected-command-fixtures)
        rejected-boundary-records
        (p18-t05-rejected-boundary-records boundary)
        tcb-delta (p18-t05-tcb-delta-record boundary)
        provenance (p18-t05-provenance-attestation-record
                    boundary p18-t03-artifact p18-t04-artifact)
        bootstrap-audit (p18-t05-bootstrap-audit-record boundary)
        eligibility (p18-t05-release-eligibility-report boundary)
        proof-id
        (c4-artifact-id
         {:boundary-id (:artifact-id boundary)
          :accepted (mapv :output-path accepted-records)
          :rejected (mapv :expected-diagnostic rejected-boundary-records)
          :release-binary (:content-hash release-binary)})
        artifact-base
        {:kind :gravity/p18-t05-seedless-release-boundary-proof
         :task "P18-T05"
         :status boundary-status
         :phase :binary-distribution-and-seedless-release
         :release-binary release-binary
         :release-boundary-record boundary
         :tcb-delta-record tcb-delta
         :provenance-attestation provenance
         :bootstrap-audit-record bootstrap-audit
         :release-eligibility-report eligibility
         :accepted-boundary-proofs accepted-records
         :rejected-command-proofs rejected-command-records
         :rejected-boundary-fixtures rejected-boundary-records
         :p18-t05-diagnostic-stream
         (p18-t05-diagnostic-stream proof-id)
         :seedless-release-boundary? (= :complete boundary-status)
         :final-release-eligible? false
         :diagnostics diagnostics}
        proof (p18-t05-seedless-release-boundary-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p18-t05-write-seedless-release-artifacts!
  []
  (let [artifact (p18-t05-seedless-release-boundary-artifact!)]
    (p18-t02-write-edn!
     (str p18-t05-artifact-dir
          "/p18-t05-seedless-release-boundary-proof.edn")
     artifact)
    (p18-t02-write-edn!
     (str p18-t05-artifact-dir "/p18-t05-release-boundary.edn")
     (:release-boundary-record artifact))
    (p18-t02-write-edn!
     (str p18-t05-artifact-dir "/p18-t05-tcb-delta.edn")
     (:tcb-delta-record artifact))
    (p18-t02-write-edn!
     (str p18-t05-artifact-dir "/p18-t05-provenance-attestation.edn")
     (:provenance-attestation artifact))
    (p18-t02-write-edn!
     (str p18-t05-artifact-dir "/p18-t05-bootstrap-audit-record.edn")
     (:bootstrap-audit-record artifact))
    (p18-t02-write-edn!
     (str p18-t05-artifact-dir "/p18-t05-release-eligibility-report.edn")
     (:release-eligibility-report artifact))
    (p18-t02-write-edn!
     (str p18-t05-artifact-dir "/p18-t05-accepted-boundary-proofs.edn")
     (:accepted-boundary-proofs artifact))
    (p18-t02-write-edn!
     (str p18-t05-artifact-dir "/p18-t05-rejected-command-proofs.edn")
     (:rejected-command-proofs artifact))
    (p18-t02-write-edn!
     (str p18-t05-artifact-dir "/p18-t05-rejected-boundary-fixtures.edn")
     (:rejected-boundary-fixtures artifact))
    (p18-t02-write-edn!
     (str p18-t05-artifact-dir "/p18-t05-diagnostic-stream.edn")
     (:p18-t05-diagnostic-stream artifact))
    artifact))

(def p18-t06-build-root "target/phase-18/release")
