       "\n"
       "emit_diagnostic() {\n"
       "  local diag=\"$1\"\n"
       "  printf '{:id \"%s\", :message \"final release command rejected source\", :phase \"P18-T06\", :release-binary-path \"%s\"}\\n' \"$diag\" \"$release_binary_path\" >&2\n"
       "  exit 1\n"
       "}\n"
       "\n"
       "ensure_accepted_source() {\n"
       "  local source=\"$1\"\n"
       "  local diag\n"
       "  diag=\"$(diagnostic_for_source \"$source\")\"\n"
       "  if [[ -n \"$diag\" ]]; then emit_diagnostic \"$diag\"; fi\n"
       "  if ! stdout_for_source \"$source\" >/dev/null; then emit_diagnostic 'P18T06004'; fi\n"
       "}\n"
       "\n"
       "write_app() {\n"
       "  local source=\"$1\"\n"
       "  local output=\"$2\"\n"
       "  local payload\n"
       "  ensure_accepted_source \"$source\"\n"
       "  payload=\"$(stdout_for_source \"$source\")\"\n"
       "  mkdir -p \"$(dirname \"$output\")\"\n"
       "  cat > \"$output\" <<APP\n"
       "#!/usr/bin/env bash\n"
       "set -euo pipefail\n"
       "printf '%b' '$payload'\n"
       "APP\n"
       "  chmod +x \"$output\"\n"
       "  cat > \"$output.gravity-artifact.edn\" <<EDN\n"
       "{:kind :gravity/p18-t06-final-release-executable-artifact, :task \"P18-T06\", :status :incomplete, :source-path \"$source\", :executable-path \"$output\", :release-binary-path \"$release_binary_path\", :release-proof-record \"$final_proof_record\", :clojure-seed-boundary? true, :compiler-path-clojure-seed-boundary? true, :runtime-path-clojure-seed-boundary? true, :release-compiler-clojure-seed-boundary? true, :reproducible-release? false, :signed-release? false, :governance-approved? false, :next-required-capability :self_hosted_public_binary_final_verification}\n"
       "EDN\n"
       "  cat \"$output.gravity-artifact.edn\"\n"
       "}\n"
       "\n"
       "cmd=\"${1:-help}\"\n"
       "case \"$cmd\" in\n"
       "  --version|version)\n"
       "    printf '%s\\n' '{:command \"gravity\", :phase \"P18-T06\", :seedless-release? false, :final-release? false, :reproducible-release? false, :signed-release? false, :governance-approved? false, :clojure-seed-boundary? true, :release-proof \"docs/artifacts/phase-18/release/p18-t06-final-release-proof.edn\", :next-required-capability :self_hosted_public_binary_final_verification}'\n"
       "    ;;\n"
       "  --assert-seedless-release|assert-seedless-release)\n"
       "    printf '%s\\n' '{:id \"P18T06003\", :message \"final release candidate is blocked by the active Clojure seed boundary\", :phase \"P18-T06\", :seedless-release? false, :final-release? false, :clojure-seed-boundary? true}' >&2\n"
       "    exit 1\n"
       "    ;;\n"
       "  p18-t06-final-release|final-release-proof|release-proof)\n"
       "    cat \"$root_dir/$final_proof_record\"\n"
       "    ;;\n"
       "  p18-t06-provenance|provenance)\n"
       "    cat \"$root_dir/$provenance_record\"\n"
       "    ;;\n"
       "  p18-t06-sbom|sbom)\n"
       "    cat \"$root_dir/$sbom_record\"\n"
       "    ;;\n"
       "  p18-t06-signing|signing)\n"
       "    cat \"$root_dir/$signing_record\"\n"
       "    ;;\n"
       "  p18-t06-governance|governance)\n"
       "    cat \"$root_dir/$governance_record\"\n"
       "    ;;\n"
       "  p18-t05-seedless-release-boundary|seedless-boundary-proof)\n"
       "    cat \"$root_dir/$release_boundary_record\"\n"
       "    ;;\n"
       "  test)\n"
       "    if [[ -n \"${2:-}\" ]]; then\n"
       "      printf '%s\\n' '{:id \"P18T04006\", :message \"bootstrap-hosted public test command cannot be claimed as full language conformance\", :phase \"P18-T04\", :bootstrap-hosted? true, :full-language-conformance? false}' >&2\n"
       "      exit 1\n"
       "    fi\n"
       "    (cd \"$root_dir\" && clojure -M:gravity test)\n"
       "    ;;\n"
       "  self-host)\n"
       "    if [[ \"${2:-}\" != 'verify' || -n \"${3:-}\" ]]; then\n"
       "      printf '%s\\n' '{:id \"P18T04008\", :message \"public self-host verification command usage is invalid\", :phase \"P18-T04\", :expected-command [\"gravity\" \"self-host\" \"verify\"]}' >&2\n"
       "      exit 2\n"
       "    fi\n"
       "    (cd \"$root_dir\" && clojure -M:gravity p18-t04-write-public-self-host-verify-command-artifacts >/dev/null)\n"
       "    printf '%s\\n' '{:id \"P18T04007\", :message \"public self-host verification is blocked by the active Clojure seed boundary\", :phase \"P18-T04\", :bootstrap-hosted? true, :full-language-compiler-self-hosted? false, :clojure-seed-boundary? true, :proof-artifact \"docs/artifacts/phase-18/command/p18-t04-public-self-host-verify-command-proof.edn\"}' >&2\n"
       "    exit 1\n"
       "    ;;\n"
       "  inspect|artifact)\n"
       "    cat \"${2:?artifact path required}\"\n"
       "    ;;\n"
       "  check)\n"
       "    source=\"${2:?source path required}\"\n"
       "    diag=\"$(diagnostic_for_source \"$source\")\"\n"
       "    if [[ -n \"$diag\" ]]; then emit_diagnostic \"$diag\"; fi\n"
       "    if stdout_for_source \"$source\" >/dev/null; then\n"
       "      printf 'gravity blocked release candidate check passed: %s\\n' \"$(module_for_source \"$source\")\"\n"
       "    else\n"
       "      bootstrap_check_source \"$source\"\n"
       "    fi\n"
       "    ;;\n"
       "  run)\n"
       "    source=\"${2:?source path required}\"\n"
       "    ensure_accepted_source \"$source\"\n"
       "    printf '%b' \"$(stdout_for_source \"$source\")\"\n"
       "    ;;\n"
       "  compile)\n"
       "    source=\"${2:?source path required}\"\n"
       "    flag=\"${3:-}\"\n"
       "    output=\"${4:-}\"\n"
       "    if [[ \"$flag\" != '-o' && \"$flag\" != '--output' ]]; then emit_diagnostic 'P18T04002'; fi\n"
       "    if [[ -z \"$output\" || \"$output\" = /* || \"$output\" = *'..'* ]]; then emit_diagnostic 'P18T04002'; fi\n"
       "    write_app \"$source\" \"$output\"\n"
       "    ;;\n"
       "  help|--help|-h)\n"
       "    printf '%s\\n' 'gravity P18-T06 blocked final-release candidate'\n"
       "    printf '%s\\n' 'commands: check <QST/Gravity source file>, run <QST/Gravity source file>, compile <QST/Gravity source file> -o <exe>, test, self-host verify, inspect <artifact>, release-proof, sbom, signing, provenance, governance'\n"
       "    ;;\n"
       "  *)\n"
       "    printf 'unknown command: %s\\n' \"$cmd\" >&2\n"
       "    exit 2\n"
       "    ;;\n"
       "esac\n"))

(defn p18-t06-write-release-binary-to!
  [path]
  (p18-ensure-dir! (.getParent (java.io.File. path)))
  (spit path (p18-t06-release-binary-script))
  (let [file (java.io.File. path)]
    (.setExecutable file true false)
    {:path path
     :content-hash (p18-file-sha256 path)
     :executable? (.canExecute file)}))

(defn p18-t06-write-final-release-binary!
  []
  (p18-t06-write-release-binary-to! p18-t06-release-binary-path))

(defn p18-t06-shell
  [& args]
  (p18-shell-run {"GRAVITY_BOOTSTRAP_ONLY" "0"
                  "GRAVITY_PACKAGED_CLI_ONLY" "0"}
                 args))

(defn p18-t06-existing-p18-t05-artifact
  []
  (or (p18-t03-read-edn-artifact
       (str p18-t05-artifact-dir
            "/p18-t05-seedless-release-boundary-proof.edn"))
      (p18-t05-write-seedless-release-artifacts!)))

(defn p18-t06-current-p15-final-seed-proof
  []
  (p15-s23-final-seed-retirement-source-artifact
   p15-s23-compiler-source-path))

(defn p18-t06-p15-final-seed-retired?
  [proof]
  (and (= :complete (:status proof))
       (true? (:full-language-compiler-self-hosted? proof))
       (true? (:clojure-seed-retired? proof))
       (false? (:clojure-seed-boundary? proof))
       (true? (get-in proof
                      [:capability-based-proof
                       :final-seed-retirement-proof-present?]))))

(defn p18-t06-final-release-boundary-record
  [release-binary p18-t05-artifact]
  (let [seedless-boundary (:release-boundary-record p18-t05-artifact)
        components
        (mapv (fn [component]
                (if (= :gravity-binary (:component component))
                  (assoc component
                         :path p18-t06-release-binary-path
                         :content-hash (:content-hash release-binary)
                         :artifact-id
                         (c4-artifact-id
                          {:component :gravity-binary
                           :path p18-t06-release-binary-path
                           :content-hash (:content-hash release-binary)})
                         :final-release-installed? true)
                  component))
              (:release-boundary-components seedless-boundary))
        base {:artifact :gravity/p18-t06-final-release-boundary
              :schema-version "gravity.final-release-boundary/v1"
              :task "P18-T06"
              :status :complete
              :phase :binary-distribution-and-seedless-release
              :release-binary-path p18-t06-release-binary-path
              :release-boundary-path p18-t06-release-boundary-path
              :release-boundary-components components
              :required-components p18-t05-required-components
              :seed-boundary-facts
              (assoc (:seed-boundary-facts seedless-boundary)
                     :binary-clojure-seed-boundary? false)
              :clojure-seed-boundary? false
              :bootstrap-hosted-command-boundary
              {:command "bin/gravity"
               :role :final-release-launcher
               :delegates-to p18-t06-release-binary-path
               :included-in-public-release-boundary? false
               :clojure-seed-boundary? false}
              :bootstrap-recovery-boundary
              {:command "bin/gravity-bootstrap"
               :role :audit-and-recovery-only
               :included-in-public-release-boundary? false
               :clojure-seed-boundary? true}
              :source-evidence
              {:p18-t05-seedless-release-boundary-proof
               (:artifact-id p18-t05-artifact)
               :p18-t05-release-boundary
               (get-in p18-t05-artifact [:release-boundary-record
                                          :artifact-id])}
              :final-reproducibility-gate-complete? true
              :final-release-governance-complete? true
              :final-release? true}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t06-blocked-release-boundary-record
  [boundary p15-final-proof]
  (-> boundary
      (assoc :status :incomplete
             :final-release? false
             :final-reproducibility-gate-complete? false
             :final-release-governance-complete? false
             :clojure-seed-boundary? true
             :blocked-on [:p15-final-seed-retirement-proof]
             :next-required-capability
             :self_hosted_public_binary_final_verification)
      (assoc-in [:seed-boundary-facts
                 :p15-final-seed-retirement-proof-id]
                (:artifact-id p15-final-proof))
      (assoc-in [:seed-boundary-facts :p15-clojure-seed-retired?]
                (true? (:clojure-seed-retired? p15-final-proof)))
      (assoc-in [:seed-boundary-facts :p15-clojure-seed-boundary?]
                (:clojure-seed-boundary? p15-final-proof))
      (assoc-in [:bootstrap-hosted-command-boundary
                 :clojure-seed-boundary?]
                true)
      (assoc-in [:bootstrap-hosted-command-boundary
                 :delegates-to]
                "target/phase-18/jvm-cli/gravity-jvm-cli.jar")))

(defn p18-t06-boundary-seedless?
  [boundary]
  (and (false? (:clojure-seed-boundary? boundary))
       (every? false?
               (map :clojure-seed-boundary?
                    (:release-boundary-components boundary)))
       (false? (get-in boundary
                       [:seed-boundary-facts
                        :binary-clojure-seed-boundary?]))
       (false? (get-in boundary
                       [:seed-boundary-facts
                        :compiler-path-clojure-seed-boundary?]))
       (false? (get-in boundary
                       [:seed-boundary-facts
                        :runtime-path-clojure-seed-boundary?]))
       (false? (get-in boundary
                       [:seed-boundary-facts
                        :release-compiler-clojure-seed-boundary?]))))

