(defn p18-t06-final-release-artifact!
  []
  (let [p18-t05-artifact (p18-t06-existing-p18-t05-artifact)
        p15-final-proof (p18-t06-current-p15-final-seed-proof)
        p15-seed-retired?
        (p18-t06-p15-final-seed-retired? p15-final-proof)
        release-binary (p18-t06-write-final-release-binary!)
        boundary-base (p18-t06-final-release-boundary-record
                       release-binary p18-t05-artifact)
        boundary (if p15-seed-retired?
                   boundary-base
                   (p18-t06-blocked-release-boundary-record
                    boundary-base p15-final-proof))
        recipe (p18-t06-reproducible-build-recipe
                release-binary boundary p18-t05-artifact)
        rebuild (p18-t06-rebuild-verification-record release-binary recipe)
        provenance (p18-t06-provenance-record
                    release-binary boundary recipe rebuild)
        sbom (p18-t06-sbom-record release-binary boundary provenance)
        signing (p18-t06-signing-record
                 release-binary boundary recipe rebuild provenance sbom)
        target-policy (p18-t06-target-support-policy)
        compatibility (p18-t06-compatibility-record target-policy)
        security-review (p18-t06-security-review-record
                         boundary provenance sbom)
        release-notes (p18-t06-release-notes release-binary)
        governance (p18-t06-governance-approval-record
                    release-notes target-policy compatibility
                    security-review signing)
        accepted-records
        (if p15-seed-retired?
          (mapv p18-t06-accepted-command-record p18-t06-accepted-fixtures)
          [])
        rejected-command-records
        (if p15-seed-retired?
          (mapv p18-t06-rejected-command-record
                p18-t06-rejected-command-fixtures)
          [])
        candidate-base
        {:kind :gravity/p18-t06-final-release-proof
         :task "P18-T06"
         :status (if p15-seed-retired? :complete :incomplete)
         :phase :binary-distribution-and-seedless-release
         :target :portable-posix-shell
         :release-binary release-binary
         :p15-final-seed-retirement-proof
         (select-keys p15-final-proof
                      [:kind :artifact :artifact-id :proof-id :status
                       :full-language-compiler-self-hosted?
                       :clojure-seed-retired?
                       :clojure-seed-boundary?
                       :next-required-capability])
         :release-boundary-record boundary
         :reproducible-build-recipe recipe
         :rebuild-verification-record rebuild
         :provenance-record provenance
         :sbom-record sbom
         :signing-record signing
         :target-support-policy target-policy
         :compatibility-record compatibility
         :security-review-record security-review
         :release-notes release-notes
         :governance-approval-record governance
         :accepted-command-proofs accepted-records
         :rejected-command-proofs rejected-command-records
         :final-release? p15-seed-retired?
         :seedless-release? p15-seed-retired?
         :clojure-seed-boundary? (not p15-seed-retired?)
         :next-required-capability
         (if p15-seed-retired?
           :none
           :self_hosted_public_binary_final_verification)}
        diagnostics (p18-t06-final-release-diagnostics
                     :p18-t06-final-release candidate-base)
        rejected-release-candidates
        (p18-t06-rejected-release-candidates candidate-base)
        proof-id
        (c4-artifact-id
         {:release-binary (:content-hash release-binary)
          :boundary-id (:artifact-id boundary)
          :rebuild-id (:artifact-id rebuild)
          :provenance-id (:artifact-id provenance)
          :sbom-id (:artifact-id sbom)
          :signing-id (:artifact-id signing)
          :governance-id (:artifact-id governance)})
        artifact-base
        (assoc candidate-base
               :rejected-release-candidates rejected-release-candidates
               :p18-t06-diagnostic-stream
               (p18-t06-diagnostic-stream proof-id)
               :diagnostics diagnostics)
        proof (p18-t06-capability-proof artifact-base)
        artifact (assoc artifact-base
                        :capability-based-proof proof
                        :artifact-id
                        (c4-artifact-id
                         (assoc artifact-base
                                :capability-based-proof proof)))]
    artifact))

(defn p18-t06-write-final-release-artifacts!
  []
  (let [artifact (p18-t06-final-release-artifact!)]
    (p18-t02-write-edn! p18-t06-final-proof-path artifact)
    (p18-t02-write-edn! p18-t06-release-boundary-path
                        (:release-boundary-record artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-reproducible-build-recipe.edn")
     (:reproducible-build-recipe artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-rebuild-verification.edn")
     (:rebuild-verification-record artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-provenance.edn")
     (:provenance-record artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-sbom.edn")
     (:sbom-record artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-signing-record.edn")
     (:signing-record artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-release-notes.edn")
     (:release-notes artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-target-support-policy.edn")
     (:target-support-policy artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-compatibility-record.edn")
     (:compatibility-record artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-security-review.edn")
     (:security-review-record artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-governance-approval.edn")
     (:governance-approval-record artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-accepted-command-proofs.edn")
     (:accepted-command-proofs artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-rejected-command-proofs.edn")
     (:rejected-command-proofs artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-rejected-release-candidates.edn")
     (:rejected-release-candidates artifact))
    (p18-t02-write-edn!
     (str p18-t06-artifact-dir "/p18-t06-diagnostic-stream.edn")
     (:p18-t06-diagnostic-stream artifact))
    (p18-ensure-dir! (.getParent (java.io.File. p18-t06-report-path)))
    (spit p18-t06-report-path (p18-t06-report-markdown artifact))
    artifact))

(def p18-t04-public-self-host-verify-proof-path
  (str p18-t04-artifact-dir
       "/p18-t04-public-self-host-verify-command-proof.edn"))

(def p18-t04-public-self-host-verify-diagnostics-path
  (str p18-t04-artifact-dir
       "/p18-t04-public-self-host-verify-diagnostics.edn"))

(defn p18-t04-self-host-verify-compiler-source
  []
  {:path p15-s23-compiler-source-path
   :extension (gravity-source-extension p15-s23-compiler-source-path)
   :source-kind (gravity-source-kind p15-s23-compiler-source-path)
   :exists? (.isFile (java.io.File. p15-s23-compiler-source-path))
   :co-canonical-source-extensions (vec (sort co-canonical-source-extensions))
   :deprecation-warning? false
   :legacy-alias? false})

(defn p18-t04-self-host-verify-complete?
  [p15-final-proof p18-final-proof]
  (and (= :complete (:status p15-final-proof))
       (true? (:full-language-compiler-self-hosted? p15-final-proof))
       (true? (:clojure-seed-retired? p15-final-proof))
       (false? (:clojure-seed-boundary? p15-final-proof))
       (= :complete (:status p18-final-proof))
       (true? (:final-release? p18-final-proof))
       (true? (:seedless-release? p18-final-proof))
       (false? (:clojure-seed-boundary? p18-final-proof))
       (false? (get-in p18-final-proof
                       [:capability-based-proof
                        :clojure-seed-boundary?]))))

(defn p18-t04-public-self-host-verify-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic (:diagnostics artifact)))
        p15 (:p15-final-seed-retirement-proof artifact)
        p18 (:p18-final-release-proof artifact)
        complete? (= :complete (:status artifact))]
    {:task "P18-T04"
     :status (:status artifact)
     :public-self-host-verify-command-present? true
     :final-self-host-verification? complete?
     :p15-final-seed-retirement-proof-linked?
     (boolean (:artifact-id p15))
     :p18-final-release-proof-linked?
     (boolean (:artifact-id p18))
     :full-language-compiler-self-hosted?
     (true? (:full-language-compiler-self-hosted? p15))
     :clojure-seed-retired?
     (true? (:clojure-seed-retired? p15))
     :clojure-seed-boundary?
     (or (true? (:clojure-seed-boundary? p15))
         (true? (:clojure-seed-boundary? p18)))
     :fails-closed-while-seed-boundary-active?
     (if complete? false (contains? diagnostics "P18T04007"))
     :source-path-preserved?
     (= p15-s23-compiler-source-path
        (get-in artifact [:compiler-source :path]))
     :source-extension-preserved?
     (= (gravity-source-extension p15-s23-compiler-source-path)
        (get-in artifact [:compiler-source :extension]))
     :no-extension-deprecation-warning?
     (false? (get-in artifact [:compiler-source :deprecation-warning?]))
     :bootstrap-hosted? true
     :full-language-conformance? false
     :self-hosted-conformance-runner? false
     :next-required-capability
     (if complete? :none :self_hosted_public_binary_final_verification)}))

(defn p18-t04-public-self-host-verify-command-artifact!
  []
  (let [p15-final-proof (p18-t06-current-p15-final-seed-proof)
        p18-final-proof (p18-t06-write-final-release-artifacts!)
        complete? (p18-t04-self-host-verify-complete?
                   p15-final-proof p18-final-proof)
        compiler-source (p18-t04-self-host-verify-compiler-source)
        diagnostics
        (if complete?
          []
          [(p18-t04-diagnostic-record
            "P18T04007"
            "gravity self-host verify"
            {:source "gravity self-host verify"
             :p15-final-seed-retirement-proof
             (select-keys p15-final-proof
                          [:kind :artifact-id :proof-id :status
                           :full-language-compiler-self-hosted?
                           :clojure-seed-retired?
                           :clojure-seed-boundary?])
             :p18-final-release-proof
             (select-keys p18-final-proof
                          [:kind :artifact-id :status :final-release?
                           :seedless-release? :clojure-seed-boundary?])
             :compiler-source compiler-source
             :proof-artifact-path
             p18-t04-public-self-host-verify-proof-path
             :remediation
             "Complete P15-S23 final seed retirement and P18-T06 final release before `gravity self-host verify` can succeed."})])
        artifact-base
        {:kind :gravity/p18-t04-public-self-host-verify-command-proof
         :task "P18-T04"
         :status (if complete? :complete :incomplete)
         :phase :binary-distribution-and-seedless-release
         :command ["gravity" "self-host" "verify"]
         :scope :current-public-release-surface
         :governing-documents ["TEST13" "BOOT7" "BOOT8" "T1" "D9"]
         :compiler-source compiler-source
         :p15-final-seed-retirement-proof
         (select-keys p15-final-proof
                      [:kind :artifact :artifact-id :proof-id :status
                       :source-path :full-language-compiler-self-hosted?
                       :clojure-seed-retired? :clojure-seed-boundary?
                       :next-required-capability])
         :p18-final-release-proof
         (select-keys p18-final-proof
                      [:kind :artifact-id :status :target :final-release?
                       :seedless-release? :clojure-seed-boundary?
                       :next-required-capability])
         :p18-final-release-proof-path p18-t06-final-proof-path
         :p18-release-binary-path p18-t06-release-binary-path
         :bootstrap-hosted? true
         :final-self-host-verification? complete?
         :full-language-conformance? false
         :self-hosted-conformance-runner? false
         :diagnostics diagnostics}
        proof (p18-t04-public-self-host-verify-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p18-t04-write-public-self-host-verify-command-artifacts!
  []
  (let [artifact (p18-t04-public-self-host-verify-command-artifact!)]
    (p18-t02-write-edn! p18-t04-public-self-host-verify-proof-path
                        artifact)
    (p18-t02-write-edn! p18-t04-public-self-host-verify-diagnostics-path
                        (:diagnostics artifact))
    artifact))

(defn p18-t04-public-self-host-verify-usage!
  [args]
  (p18-t04-fail!
   "P18T04008"
   {:source "gravity self-host"
    :command (vec args)
    :expected-command ["gravity" "self-host" "verify"]
    :remediation "Use `gravity self-host verify` exactly."}))

(defn p18-t04-public-self-host-verify-command!
  [args]
  (if-not (and (= "self-host" (first args))
               (= "verify" (second args))
               (= 2 (count args)))
    (p18-t04-public-self-host-verify-usage! args)
    (let [artifact (p18-t04-write-public-self-host-verify-command-artifacts!)]
      (if (= :complete (:status artifact))
        (prn artifact)
        (p18-t04-fail!
         "P18T04007"
         {:source "gravity self-host verify"
          :command (vec args)
          :proof-artifact-path p18-t04-public-self-host-verify-proof-path
          :proof-artifact-id (:artifact-id artifact)
          :p15-final-seed-retirement-proof
          (:p15-final-seed-retirement-proof artifact)
          :p18-final-release-proof (:p18-final-release-proof artifact)
          :compiler-source (:compiler-source artifact)
          :bootstrap-hosted? true
          :full-language-compiler-self-hosted? false
          :clojure-seed-boundary? true
          :remediation
          "Complete P15-S23 final seed retirement and P18-T06 final release before claiming public self-host verification."})))))

(def p18-t00-artifact-dir "docs/artifacts/phase-18/source-extensions")
(def p18-t00-report-path
  "docs/artifacts/phase-18/reports/p18-t00-co-canonical-source-extensions-report.md")

