    :output-prefix "target/phase-18/source-extensions/rejected-backend-release"}])

(defn p18-t00-shell
  [& args]
  (p18-shell-run args))

(defn p18-t00-output-has-warning?
  [result]
  (boolean
   (re-find #"(?i)\b(deprecat|compatibility warning|alias-only|warning)\b"
            (str (:out result) "\n" (:err result)))))

(defn p18-t00-semantic-summary
  [path]
  (let [source-text (slurp path)
        compile-artifact (compile-source path source-text)
        reader-artifact (read-source-artifact path source-text)
        source-unit (c2-source-unit-record
                     path source-text standard-reader-options)
        source-map (get-in reader-artifact
                           [:syntax-object-stream 0 :span :source])]
    {:source-path path
     :source-extension (gravity-source-extension path)
     :source-kind (gravity-source-kind path)
     :recognized-source? (qst-or-gravity-source? path)
     :source-unit-path (:path source-unit)
     :source-unit-kind (:source-kind source-unit)
     :reader-source-path (get-in reader-artifact [:source :path])
     :reader-source-map-path source-map
     :module (dissoc (:module compile-artifact) :source-path)
     :syntax-count (count (:syntax-object-stream compile-artifact))
     :compiled-kind (:kind compile-artifact)}))

(defn p18-t00-compile-artifact-source-path
  [artifact]
  (or (:source-path artifact)
      (get-in artifact [:source :path])))

(defn p18-t00-accepted-extension-record
  [{:keys [gravity qst expected-stdout bootstrap-module release-module
           bootstrap-output-prefix release-output-prefix]}]
  (let [bootstrap-gravity-output (str bootstrap-output-prefix "-gravity")
        bootstrap-qst-output (str bootstrap-output-prefix "-qst")
        release-gravity-output (str release-output-prefix "-gravity")
        release-qst-output (str release-output-prefix "-qst")
        gravity-summary (p18-t00-semantic-summary gravity)
        qst-summary (p18-t00-semantic-summary qst)
        gravity-check (p18-t00-shell "clojure" "-M:gravity" "check" gravity)
        qst-check (p18-t00-shell "clojure" "-M:gravity" "check" qst)
        gravity-run (p18-t00-shell "clojure" "-M:gravity" "run" gravity)
        qst-run (p18-t00-shell "clojure" "-M:gravity" "run" qst)
        gravity-run-compiled (p18-t00-shell "clojure" "-M:gravity"
                                            "run-compiled" gravity)
        qst-run-compiled (p18-t00-shell "clojure" "-M:gravity"
                                        "run-compiled" qst)
        gravity-compile (p18-t00-shell "clojure" "-M:gravity" "compile"
                                       gravity "-o" bootstrap-gravity-output)
        qst-compile (p18-t00-shell "clojure" "-M:gravity" "compile"
                                   qst "-o" bootstrap-qst-output)
        gravity-compile-artifact (p18-t04-read-edn-stdout gravity-compile)
        qst-compile-artifact (p18-t04-read-edn-stdout qst-compile)
        gravity-exec (p18-t00-shell bootstrap-gravity-output)
        qst-exec (p18-t00-shell bootstrap-qst-output)
        release-gravity-check (p18-t06-shell "bin/gravity" "check" gravity)
        release-qst-check (p18-t06-shell "bin/gravity" "check" qst)
        release-gravity-run (p18-t06-shell "bin/gravity" "run" gravity)
        release-qst-run (p18-t06-shell "bin/gravity" "run" qst)
        release-gravity-compile (p18-t06-shell "bin/gravity" "compile"
                                               gravity "-o"
                                               release-gravity-output)
        release-qst-compile (p18-t06-shell "bin/gravity" "compile"
                                           qst "-o" release-qst-output)
        release-gravity-artifact (p18-t04-read-edn-stdout
                                  release-gravity-compile)
        release-qst-artifact (p18-t04-read-edn-stdout release-qst-compile)
        release-gravity-source-path
        (p18-t00-compile-artifact-source-path release-gravity-artifact)
        release-qst-source-path
        (p18-t00-compile-artifact-source-path release-qst-artifact)
        release-gravity-exec (p18-t06-shell release-gravity-output)
        release-qst-exec (p18-t06-shell release-qst-output)
        results [gravity-check qst-check gravity-run qst-run
                 gravity-run-compiled qst-run-compiled gravity-compile
                 qst-compile gravity-exec qst-exec release-gravity-check
                 release-qst-check release-gravity-run release-qst-run
                 release-gravity-compile release-qst-compile
                 release-gravity-exec release-qst-exec]
        semantic-equivalent?
        (= (dissoc gravity-summary :source-path :source-extension
                   :source-kind :source-unit-path :source-unit-kind
                   :reader-source-path :reader-source-map-path)
           (dissoc qst-summary :source-path :source-extension
                   :source-kind :source-unit-path :source-unit-kind
                   :reader-source-path :reader-source-map-path))
        provenance-preserved?
        (and (= gravity (get-in gravity-compile-artifact [:source :path]))
             (= qst (get-in qst-compile-artifact [:source :path]))
             (= gravity release-gravity-source-path)
             (= qst release-qst-source-path)
             (= gravity (:source-unit-path gravity-summary))
             (= qst (:source-unit-path qst-summary))
             (= gravity (:reader-source-map-path gravity-summary))
             (= qst (:reader-source-map-path qst-summary)))]
    {:gravity-source gravity
     :qst-source qst
     :expected-stdout expected-stdout
     :bootstrap-module bootstrap-module
     :release-module release-module
     :gravity-summary gravity-summary
     :qst-summary qst-summary
     :bootstrap-check-parity?
     (and (zero? (:exit gravity-check))
          (zero? (:exit qst-check))
          (= (:out gravity-check)
             (str "gravity stage0 check passed: " bootstrap-module "\n"))
          (= (:out qst-check) (:out gravity-check)))
     :bootstrap-run-parity?
     (and (= expected-stdout (:out gravity-run) (:out qst-run))
          (zero? (:exit gravity-run))
          (zero? (:exit qst-run)))
     :bootstrap-compile-parity?
     (and (zero? (:exit gravity-compile))
          (zero? (:exit qst-compile))
          (= expected-stdout (:out gravity-exec) (:out qst-exec)))
     :bootstrap-run-compiled-parity?
     (and (= expected-stdout
             (:out gravity-run-compiled)
             (:out qst-run-compiled))
          (zero? (:exit gravity-run-compiled))
          (zero? (:exit qst-run-compiled)))
     :release-check-parity?
     (and (zero? (:exit release-gravity-check))
          (zero? (:exit release-qst-check))
          (str/includes? (:out release-gravity-check)
                         " check passed: ")
          (= (:out release-qst-check) (:out release-gravity-check)))
     :release-run-parity?
     (and (= expected-stdout (:out release-gravity-run)
             (:out release-qst-run))
          (zero? (:exit release-gravity-run))
          (zero? (:exit release-qst-run)))
     :release-compile-parity?
     (and (zero? (:exit release-gravity-compile))
          (zero? (:exit release-qst-compile))
          (= expected-stdout
             (:out release-gravity-exec)
             (:out release-qst-exec)))
     :semantic-equivalent? semantic-equivalent?
     :provenance-preserves-actual-extension? provenance-preserved?
     :no-deprecation-or-compatibility-warning?
     (not-any? p18-t00-output-has-warning? results)
     :bootstrap-compile-provenance
     {:gravity (get-in gravity-compile-artifact [:source :path])
      :qst (get-in qst-compile-artifact [:source :path])}
     :release-compile-provenance
     {:gravity release-gravity-source-path
      :qst release-qst-source-path}
     :matches-expected?
     (and semantic-equivalent?
          provenance-preserved?
          (not-any? p18-t00-output-has-warning? results)
          (every? zero? (map :exit results)))}))

(defn p18-t00-rejected-extension-record
  [{:keys [gravity qst expected-diagnostic output-prefix]}]
  (let [bootstrap-gravity (p18-t00-shell "clojure" "-M:gravity"
                                         "run-compiled" gravity)
        bootstrap-qst (p18-t00-shell "clojure" "-M:gravity"
                                     "run-compiled" qst)
        release-gravity (p18-t06-shell "bin/gravity" "compile" gravity
                                       "-o" (str output-prefix "-gravity"))
        release-qst (p18-t06-shell "bin/gravity" "compile" qst
                                   "-o" (str output-prefix "-qst"))
        results [bootstrap-gravity bootstrap-qst release-gravity release-qst]]
    {:gravity-source gravity
     :qst-source qst
     :expected-diagnostic expected-diagnostic
     :bootstrap-diagnostic-parity?
     (and (= 1 (:exit bootstrap-gravity) (:exit bootstrap-qst))
          (str/includes? (:err bootstrap-gravity) expected-diagnostic)
          (str/includes? (:err bootstrap-qst) expected-diagnostic))
     :release-diagnostic-parity?
     (and (= 1 (:exit release-gravity) (:exit release-qst))
          (str/includes? (:err release-gravity) expected-diagnostic)
          (str/includes? (:err release-qst) expected-diagnostic))
     :no-deprecation-or-compatibility-warning?
     (not-any? p18-t00-output-has-warning? results)
     :matches-expected?
     (and (= 1 (:exit bootstrap-gravity) (:exit bootstrap-qst)
             (:exit release-gravity) (:exit release-qst))
          (every? #(str/includes? (:err %) expected-diagnostic) results)
          (not-any? p18-t00-output-has-warning? results))}))

(defn p18-t00-capability-proof
  [artifact]
  (let [accepted (:accepted-extension-parity artifact)
        rejected (:rejected-extension-parity artifact)
        accepted-provenance (map :provenance-preserves-actual-extension?
                                 accepted)]
    {:task "P18-T00"
     :status :complete
     :co-canonical-source-extensions?
     (= #{".qst" ".gravity"} co-canonical-source-extensions)
     :qst-represents-qst-theory?
     (= :qst-theory-source
        (gravity-source-kind "examples/core-app.qst"))
     :gravity-represents-branded-source?
     (= :gravity-branded-source
        (gravity-source-kind "examples/core-app.gravity"))
     :accepted-fixtures-covered?
     (= (set (map (juxt :gravity :qst)
                  p18-t00-accepted-extension-fixtures))
        (set (map (juxt :gravity-source :qst-source) accepted)))
     :bootstrap-check-parity?
     (every? :bootstrap-check-parity? accepted)
     :bootstrap-run-parity?
     (every? :bootstrap-run-parity? accepted)
     :bootstrap-compile-parity?
     (every? :bootstrap-compile-parity? accepted)
     :bootstrap-run-compiled-parity?
     (every? :bootstrap-run-compiled-parity? accepted)
     :release-check-parity?
     (every? :release-check-parity? accepted)
     :release-run-parity?
     (every? :release-run-parity? accepted)
     :release-compile-parity?
     (every? :release-compile-parity? accepted)
     :accepted-semantic-parity?
     (every? :semantic-equivalent? accepted)
     :rejected-diagnostic-parity?
     (every? :matches-expected? rejected)
     :provenance-preserves-actual-extension?
     (every? true? accepted-provenance)
     :no-deprecation-or-compatibility-warnings?
     (and (every? :no-deprecation-or-compatibility-warning? accepted)
          (every? :no-deprecation-or-compatibility-warning? rejected))
     :final-release-command-supports-both?
     (and (every? :release-check-parity? accepted)
          (every? :release-run-parity? accepted)
          (every? :release-compile-parity? accepted))
     :phase-18-prerequisite-satisfied? true}))

(defn p18-t00-report-markdown
  [artifact]
  (let [proof (:capability-based-proof artifact)]
    (str "# P18-T00 Co-canonical Source Extensions Report\n\n"
         "Date: 2026-07-02\n\n"
         "## Scope\n\n"
         "P18-T00 proves that `.qst` and `.gravity` are co-canonical "
         "Gravity source file extensions. `.qst` represents QST theory "
         "source, `.gravity` represents Gravity-branded source, and both "
         "extensions are first-class canonical source forms.\n\n"
         "## Proof Summary\n\n"
         "- Bootstrap check parity: `" (:bootstrap-check-parity? proof) "`\n"
         "- Bootstrap run parity: `" (:bootstrap-run-parity? proof) "`\n"
         "- Bootstrap compile parity: `" (:bootstrap-compile-parity? proof) "`\n"
         "- Bootstrap run-compiled parity: `"
         (:bootstrap-run-compiled-parity? proof) "`\n"
         "- Final release check parity: `" (:release-check-parity? proof)
         "`\n"
         "- Final release run parity: `" (:release-run-parity? proof) "`\n"
         "- Final release compile parity: `" (:release-compile-parity? proof)
         "`\n"
         "- Rejected diagnostic parity: `"
         (:rejected-diagnostic-parity? proof) "`\n"
         "- Provenance preserves actual extension: `"
         (:provenance-preserves-actual-extension? proof) "`\n\n"
         "## Artifacts\n\n"
         "- `" p18-t00-artifact-dir
         "/p18-t00-co-canonical-source-extensions-proof.edn`\n"
         "- `" p18-t00-artifact-dir
         "/p18-t00-accepted-extension-parity.edn`\n"
         "- `" p18-t00-artifact-dir
         "/p18-t00-rejected-extension-parity.edn`\n\n")))

(defn p18-t00-co-canonical-source-extensions-artifact!
  []
  (p18-t06-write-final-release-artifacts!)
  (let [accepted (mapv p18-t00-accepted-extension-record
                       p18-t00-accepted-extension-fixtures)
        rejected (mapv p18-t00-rejected-extension-record
                       p18-t00-rejected-extension-fixtures)
        artifact-base
        {:kind :gravity/p18-t00-co-canonical-source-extensions-proof
         :task "P18-T00"
         :status :complete
         :phase :binary-distribution-and-seedless-release
         :source-extension-contract
         {:co-canonical-extensions [".qst" ".gravity"]
          :qst-source-kind :qst-theory-source
          :gravity-source-kind :gravity-branded-source
          :both-valid-indefinitely? true
          :deprecation-warnings? false
          :compatibility-warnings? false}
         :accepted-extension-parity accepted
         :rejected-extension-parity rejected
         :governing-documents ["C2" "C15" "PKG3" "PKG10" "PKG12"
                               "T1" "BOOT7" "BOOT8" "D9"]
         :diagnostics []}
        proof (p18-t00-capability-proof artifact-base)
        artifact (assoc artifact-base
                        :capability-based-proof proof
                        :artifact-id
                        (c4-artifact-id
                         (assoc artifact-base
                                :capability-based-proof proof)))]
    artifact))

(defn p18-t00-write-co-canonical-source-extension-artifacts!
  []
  (let [artifact (p18-t00-co-canonical-source-extensions-artifact!)]
    (p18-ensure-dir! p18-t00-artifact-dir)
    (p18-ensure-dir! (.getParent (java.io.File. p18-t00-report-path)))
    (p18-t02-write-edn!
     (str p18-t00-artifact-dir
          "/p18-t00-co-canonical-source-extensions-proof.edn")
     artifact)
    (p18-t02-write-edn!
     (str p18-t00-artifact-dir
          "/p18-t00-accepted-extension-parity.edn")
     (:accepted-extension-parity artifact))
    (p18-t02-write-edn!
     (str p18-t00-artifact-dir
          "/p18-t00-rejected-extension-parity.edn")
     (:rejected-extension-parity artifact))
    (spit p18-t00-report-path (p18-t00-report-markdown artifact))
    artifact))

(defn print-diagnostic!
  [ex]
  (binding [*out* *err*]
    (let [data (ex-data ex)
          authentic-c-diagnostic
          (p15-s23-c-backend-sanitized-complete-diagnostic data)
          projection
          (select-keys data [:id :rule :message :severity :bootstrap-stage
                                     :source-span
                                     :profile :active-profile :target
                                     :reader-state :analyzer-stage :alias :symbol
                                     :syntax-id :candidate-bindings
                                     :dependency-edge :namespace
                                     :module :macro :operator :function
                                     :expected-arity :actual-arity :effect
                                     :bootstrap-hosted? :packaged-jvm-cli?
                                     :seedless-release?
                                     :declared-effects :granted-build-effects
                                     :required-effect :required-capability
                                     :requested-capability
                                     :selected-or-missing-provider
                                     :declared-capabilities :grant-id :scope :phase
                                     :expected-type :actual-type :resource
                                     :resource-type :depth :limit :generated-form
                                     :safety-outcome :safety-mode :missing-fact
                                     :safe-rule :dependency :dependency-safety
                                     :underlying-diagnostic :underlying-message
                                     :diagnostic-family :legal-alternative
                                     :release-artifact-id :release-compiler-id
                                     :compiler-path-id :runtime-path-id
                                     :artifact-producer
                                     :release-boundary-path
                                     :release-binary-path
                                     :proof-artifact-path
                                     :proof-artifact-id
                                     :p15-final-seed-retirement-proof
                                     :p18-final-release-proof
                                     :compiler-source
                                     :full-language-compiler-self-hosted?
                                     :clojure-seed-boundary?
                                     :expected-command
                                     :seed-boundary-facts
                                     :output-path :executable-path
                                     :expected-stdout :actual-stdout
                                     :command-contract
                                     :profile-clauses :profiles-clauses
                                     :profile-contract :policy-layers
                                     :dependency-profile :supported
                                     :host-runtime :host-symbol
                                     :target-profile :target-feature
                                     :caller-safety :erased-check
                                     :operation :memory-regime :memory-family
                                     :provider-id :region-id :arena-id
                                     :generation :resource-id :owner-id
                                     :borrow-id :lifetime-id
	                                     :package-id :package-version
	                                     :dependency-path :denied-authority
	                                     :denied-policy-layer :policy-layer
	                                     :manifest-entry :lockfile-entry
	                                     :macro-symbol :macro-definition-span
	                                     :call-site-span :generated-form-span
	                                     :expansion-phase :build-effects
	                                     :model-id :tool-id :prompt-role
	                                     :taint-source :human-review-policy
	                                     :replay-policy :agent-artifact-id
	                                     :consumer-namespace :consumer-profile
	                                     :producer-namespace :producer-profile
	                                     :edge-kind :boundary
	                                     :missing-evidence :required-evidence
	                                     :suggested-boundary
	                                     :unsupported-runtime-providers
	                                     :denied-effects :denied-capabilities
	                                     :generated-origin-chain
	                                     :missing-profiles :missing-documents
	                                     :missing-diagnostic-ids
	                                     :unexpected-diagnostic-ids
	                                     :expected-profile
	                                     :expected-document
	                                     :claim-id :missing-fields
	                                     :target-request :target-features
	                                     :target-fingerprint
	                                     :lost-safety-facts
	                                     :expanded-effects
	                                     :expanded-capabilities
	                                     :source-numeric-mode
	                                     :optimized-numeric-mode
	                                     :generated-variant
	                                     :abstraction :equivalent-form
	                                     :expected-erased-costs
	                                     :erased-costs :residual-costs
	                                     :residual-cost :ir-artifacts
	                                     :profile-illegal-behavior
	                                     :source-function
	                                     :specialization-key
	                                     :guard :guard-stage
	                                     :build-effects
	                                     :ungranted-build-effects
	                                     :grants :cache-key-inputs
	                                     :invalidation-inputs
	                                     :missing-key-inputs
	                                     :missing-cache-inputs
	                                     :variant-selection
	                                     :layout-type :layout-transform
	                                     :alignment :erased-checks
                                     :benchmark-id :metric :baseline
                                     :environment-fingerprint
                                     :sample-summary :threshold
                                     :gate-state :samples
                                     :required-samples
                                     :regression-percent
                                     :classification
                                     :baseline-update
                                     :environment-drift
                                     :profile-data-id :policy
                                     :source-hash :mir-hash
                                     :workload :stale-field
                                     :privacy :pass-id
                                     :decision-id
                                     :changed-operations
                                     :expected-workload
                                     :actual-workload
                                     :candidate-space-id
                                     :candidate-id :variant-id
                                     :objective
                                     :missing-certificate
