                "self-host" (p18-t04-public-self-host-verify-command! args)
                "compile" (let [request
                                 (p18-t04-parse-compile-request args)
                                 {:keys [target output-path target-requested?
                                         lowering-mode]} request]
                             (if (= :verified-mir lowering-mode)
                               (prn
                                (p18-t04-compile-experimental-verified-mir-c-target-file!
                                 request))
                               (if target-requested?
                               (cond
                                 (= :jvm target)
                                 (if lowering-mode
                                   (prn (p18-t04-compile-jvm-target-file!
                                         path output-path target
                                         lowering-mode))
                                   (if output-path
                                     (prn (p18-t04-compile-executable-file!
                                           path output-path))
                                     (prn (compile-file path))))

                                 (= js-ts-backend-target target)
                                 (prn (p18-t04-compile-js-ts-target-file!
                                       path output-path target
                                       lowering-mode))

                                 (contains? c-backend-supported-targets target)
                                 (prn (p18-t04-compile-c-target-file!
                                       path output-path target
                                       lowering-mode))

                                 :else
                                 (fail!
                                  "C14-TARGET"
                                  "requested compile target is unsupported"
                                  {:severity :error
                                   :stage :target-selection
                                   :diagnostic-family :c14-target-lowering
                                   :source-span (source-span path 0)
                                   :primary {:span (source-span path 0)}
                                   :target target
                                   :backend nil
                                   :supported-targets
                                   [:jvm :c :c-hosted :c11 :js :js-ts]
                                   :missing-fact :supported-target
                                   :remediation
                                   "Select jvm, c, js, or js-ts; other documented targets remain unimplemented."}))
                                 (if output-path
                                   (prn (p18-t04-compile-executable-file!
                                         path output-path))
                                   (prn (compile-file path))))))
	        "check" (let [artifact (check-file-artifact path)]
	                  (println "gravity stage0 check passed:" (check-artifact-module-name artifact)))
        "run" (print (run-file path))
        "run-compiled" (print (run-compiled-file path))
        (do
	          (binding [*out* *err*]
	                        (println "usage: clojure -M:gravity <read|module|macro|core|sh07-core|typed|safety|memory-safety|unsafe-audit|boundary-safety|capability-supply-chain|safety-conformance|profile-manifest|profile-set|profile-validation|profile-distributed-ai|profile-compatibility|profile-compliance|performance|zero-cost|specialization|layout|performance-governance|realtime-governance|numeric-modes|efir|eml|approximation|math-proof|math-conformance|compiler-passes|checked-core|mir|domain-ir|optimize-lower|compiler-verify|compiler-c1-architecture|compiler-c2-reader|compiler-c3-syntax|compiler-c4-macro|compiler-c5-resolution|compiler-c6-lowering|compiler-c7-type-check|compiler-c8-effect-check|compiler-c9-ownership-check|compiler-c10-safety-analysis|compiler-c11-mir-spec|compiler-c12-domain-ir|compiler-c13-optimization|compiler-c14-lowering|compiler-c15-diagnostics|compiler-c16-incremental|compiler-c17-plugin|compiler-c18-verification|backend-interface|native-lowering|hosted-lowering|specialized-lowering|artifact-emission|backend-test-matrix|backend-b1-document|backend-b2-c-document|backend-b3-llvm-document|backend-b4-wasm-document|backend-b5-jvm-document|backend-b6-js-ts-document|backend-b7-mlir-document|backend-b8-gpu-document|backend-b9-hdl-document|backend-b10-workflow-document|backend-b11-query-document|backend-b12-mobile-document|backend-b13-artifact-document|backend-b14-conformance-document|runtime-selection|runtime-minimal-native|runtime-managed|runtime-concurrency|runtime-ai-ffi|runtime-observability|runtime-r1-document|runtime-r2-document|runtime-r3-document|runtime-r4-document|runtime-r5-document|runtime-r6-document|runtime-r7-document|runtime-r8-document|runtime-r9-document|runtime-r10-document|runtime-r11-document|runtime-r12-document|domain-coverage|schema-interop|ai-agentic|package-artifacts|tooling-experience|conformance-system|bootstrap-self-hosting|stage1-bootstrap-source|stage1-reader-execute|stage1-reader-algorithm|stage1-reader-pipeline|stage1